    /// Note: Caller must free the returned links array and all strings
within.
    pub fn get_document_links(self: *Editor) !?[]LspClient.DocumentLink {
        // Request document links from LSP server
        const links = try self.lsp.requestDocumentLinks(self.file_uri);
        
        // Return links array (caller must free)
        return links;
    }
    
    /// Resolve document link (get target URI for link without target).
    /// Why: Resolve document link target if it was not provided in
get_document_links.
    /// Contract: link must be valid (must have range at minimum).
    /// Returns: Resolved document link with target URI, or null if not
available.
    /// Note: Caller must free the returned link and all strings within.
    pub fn resolve_document_link(
        self: *Editor,
        link: LspClient.DocumentLink,
    ) !?LspClient.DocumentLink {
        // Request document link resolve from LSP server
        const resolved = try self.lsp.resolveDocumentLink(link);
        
        // Return resolved link (caller must free)
        return resolved;
    }
    
    /// Get linked editing ranges for current file (for synchronized
editing).
    /// Why: Get ranges that should be edited together (e.g., HTML tag
names, JSX tags).
    /// Contract: File must be open and LSP server must be running.
    /// Returns: Linked editing range with ranges to edit together, or
null if not available.
    /// Note: Caller must free the returned linked editing range and all
strings within.
    pub fn get_linked_editing_ranges(self: *Editor)
!?LspClient.LinkedEditingRange {
        // Request linked editing ranges from LSP server
        const linked_range = try self.lsp.requestLinkedEditingRange(
            self.file_uri,
            self.cursor_line,
            self.cursor_char,
        );
        
        // Return linked editing range (caller must free)
        return linked_range;
    }
    
    /// Get color information for current file (for color picker).
    /// Why: Get color information from LSP server for color picker and
color editing.
    /// Contract: File must be open and LSP server must be running.
    /// Returns: Array of color information with ranges, or null if not
available.
    /// Note: Caller must free the returned array.
    pub fn get_document_colors(self: *Editor) !?[]struct { range:
LspClient.Range, color: LspClient.Color } {
        // Request document colors from LSP server
        const colors = try self.lsp.requestDocumentColor(self.file_uri);
        
        // Return colors array (caller must free)
        return colors;
    }
    
    /// Get color presentation options (different ways to display/edit a
color).
    /// Why: Get different color formats (e.g., "rgb(255, 0, 0)",
"#ff0000", "red").
    /// Contract: File must be open, color and range must be valid, and
LSP server must be running.
    /// Returns: Array of color presentations, or null if not available.
    /// Note: Caller must free the returned presentations array and all
strings within.
    pub fn get_color_presentations(
        self: *Editor,
        color: LspClient.Color,
        start_line: u32,
        start_char: u32,
        end_line: u32,
        end_char: u32,
    ) !?[]LspClient.ColorPresentation {
        // Assert: Range must be valid
        std.debug.assert(start_line <= end_line);
        if (start_line == end_line) {
            std.debug.assert(start_char <= end_char);
        }
        
        // Request color presentations from LSP server
        const range = LspClient.Range{
            .start = LspClient.Position{ .line = start_line, .character
= start_char },
            .end = LspClient.Position{ .line = end_line, .character =
end_char },
        };
        const presentations = try
self.lsp.requestColorPresentation(self.file_uri, color, range);
        
        // Return presentations array (caller must free)
        return presentations;
    }
    
    /// Get folding ranges for current file (for code folding).
    /// Why: Get folding ranges from LSP server for code folding (e.g.,
functions, blocks, regions).
    /// Contract: File must be open and LSP server must be running.
    /// Returns: Array of folding ranges, or null if not available.
    /// Note: Caller must free the returned ranges array.
    pub fn get_folding_ranges(self: *Editor) !?[]LspClient.FoldingRange {
        // Request folding ranges from LSP server
        const ranges = try self.lsp.requestFoldingRanges(self.file_uri);
        
        // Return ranges array (caller must free)
        return ranges;
    }
    
    /// Get document highlights for symbol at cursor position.
    /// Why: Highlight all occurrences of a symbol at the cursor
position (e.g., variable, function).
    /// Contract: File must be open and LSP server must be running.
    /// Returns: Array of document highlights, or null if not available.
    /// Note: Caller must free the returned highlights array.
    pub fn get_document_highlights(self: *Editor)
!?[]LspClient.DocumentHighlight {
        // Request document highlights from LSP server
        const highlights = try self.lsp.requestDocumentHighlights(
            self.file_uri,
            self.cursor_line,
            self.cursor_char,
        );
        
        // Return highlights array (caller must free)
        return highlights;
    }
    
    /// Get selection ranges for expanding text selection at cursor
position.
    /// Why: Get selection ranges for expanding text selection (e.g.,
word -> statement -> block).
    /// Contract: File must be open and LSP server must be running.
    /// Returns: Array of selection ranges (one per position), or null
if not available.
    /// Note: Caller must free the returned ranges array and all nested
parent ranges.
    pub fn get_selection_ranges(self: *Editor)
!?[]LspClient.SelectionRange {
        // Build positions array (single position at cursor)
        const positions = [_]LspClient.Position{
            LspClient.Position{ .line = self.cursor_line, .character =
self.cursor_char },
        };
        
        // Request selection ranges from LSP server
        const ranges = try
self.lsp.requestSelectionRanges(self.file_uri, &positions);
        
        // Return ranges array (caller must free)
        return ranges;
    }
    
    /// Get code lenses for current file (for actionable code
information).
    /// Why: Get code lenses for actionable code information (e.g.,
references count, test coverage).
    /// Contract: File must be open and LSP server must be running.
    /// Returns: Array of code lenses, or null if not available.
    /// Note: Caller must free the returned lenses array and all strings
within.
    pub fn get_code_lenses(self: *Editor) !?[]LspClient.CodeLens {
        // Request code lenses from LSP server
        const lenses = try self.lsp.requestCodeLens(self.file_uri);
        
        // Return lenses array (caller must free)
        return lenses;
    }
    
    /// Resolve code lens (get full command details).
    /// Why: Resolve a code lens to get its full command details (lazy
loading).
    /// Contract: code_lens must be valid.
    /// Returns: Resolved code lens with command, or null if not
available.
    /// Note: Caller must free the returned code lens and all strings
within.
    pub fn resolve_code_lens(self: *Editor, code_lens:
LspClient.CodeLens) !?LspClient.CodeLens {
        // Resolve code lens from LSP server
        const resolved = try self.lsp.resolveCodeLens(code_lens);
        
        // Return resolved code lens (caller must free)
        return resolved;
    }
    
    /// Get workspace folders (for multi-root workspaces).
    /// Why: Get workspace folders from LSP server for multi-root
workspaces.
    /// Contract: LSP server must be running.
    /// Returns: Array of workspace folders, or null if not available.
    /// Note: Caller must free the returned folders array and all
strings within.
    pub fn get_workspace_folders(self: *Editor)
!?[]LspClient.WorkspaceFolder {
        // Request workspace folders from LSP server
        const folders = try self.lsp.requestWorkspaceFolders();
        
        // Return folders array (caller must free)
        return folders;
    }
    
    /// Notify workspace folders changed (add or remove workspace
folders).
    /// Why: Notify LSP server when workspace folders are added or
removed.
    /// Contract: added and removed arrays must be valid.
    pub fn notify_workspace_folders_changed(
        self: *Editor,
        added: []const LspClient.WorkspaceFolder,
        removed: []const LspClient.WorkspaceFolder,
    ) !void {
        // Notify LSP server of workspace folder changes
        try self.lsp.notifyDidChangeWorkspaceFolders(added, removed);
    }
    
    /// Execute workspace command (run a command from code actions or
code lenses).
    /// Why: Execute workspace commands from code actions, code lenses,
or other LSP features.
    /// Contract: command and arguments must be valid.
    /// Returns: Command result (JSON value), or null if not available.
    /// Note: Caller must free the returned result if it contains
allocated strings.
    pub fn execute_command(
        self: *Editor,
        command: []const u8,
        arguments: ?[]const std.json.Value,
    ) !?std.json.Value {
        // Execute command from LSP server
        const result = try self.lsp.executeCommand(command, arguments);
        
        // Return result (caller must free if it contains allocated
strings)
        return result;
    }
    
    /// Apply workspace edit from LSP server (apply edits from server).
    /// Why: Apply workspace edits from the LSP server (e.g., from code
actions).
    /// Contract: edit must be valid.
    /// Returns: Whether the edit was applied (true) or rejected (false).
    pub fn apply_workspace_edit_from_server(self: *Editor, edit:
LspClient.WorkspaceEdit) !bool {
        // Apply edit from LSP server
        const applied = try self.lsp.applyEdit(edit);
        
        // If applied, also apply locally
        if (applied) {
            try self.apply_workspace_edit(edit);
        }
        
        return applied;
    }
    
