    /// Render editor view: buffer content + LSP diagnostics overlay.
    /// Includes readonly spans and ghost text for visual distinction.
    pub fn render(self: *Editor) !GrainAurora.RenderResult {
        const text = self.buffer.textSlice();
        const readonly_spans = self.buffer.getReadonlySpans();
        
        // Convert GrainBuffer segments to Aurora spans
        // Note: readonly_spans are owned by GrainBuffer, we just
reference them
        // For RenderResult, we'll use the spans directly from
GrainBuffer
        
        // Build rendered text with ghost text appended (if pending
completion exists)
        var rendered_text = text;
        var ghost_spans: []const GrainAurora.Span = &.{};
        
        if (self.pending_completion) |completion| {
            // Assert: Completion must be bounded
            std.debug.assert(completion.len <= 10 * 1024); // Max 10KB
ghost text
            
            // Calculate cursor position in text (simplified: line * 80
+ char)
            const cursor_pos = self.cursor_line * 80 + self.cursor_char;
            
            // Assert: Cursor position must be within bounds
            std.debug.assert(cursor_pos <= text.len);
            
            // Free old ghost text buffer if it exists
            if (self.ghost_text_buffer) |old_buffer| {
                self.allocator.free(old_buffer);
            }
            
            // Append ghost text to rendered text (for display)
            var text_with_ghost = try std.ArrayList(u8).initCapacity(
                self.allocator,
                text.len + completion.len,
            );
            defer text_with_ghost.deinit();
            
            // Add text before cursor
            try text_with_ghost.appendSlice(text[0..cursor_pos]);
            // Add ghost text
            try text_with_ghost.appendSlice(completion);
            // Add text after cursor
            try text_with_ghost.appendSlice(text[cursor_pos..]);
            
            // Store in editor for lifetime management
            self.ghost_text_buffer = try text_with_ghost.toOwnedSlice();
            rendered_text = self.ghost_text_buffer.?;
            
            // Create ghost text span (starts at cursor, extends for
completion length)
            const ghost_start = cursor_pos;
            const ghost_end = cursor_pos + @as(u32,
@intCast(completion.len));
            
            // Allocate ghost span
            const ghost_span = try
self.allocator.alloc(GrainAurora.Span, 1);
            ghost_span[0] = GrainAurora.Span{
                .start = ghost_start,
                .end = ghost_end,
            };
            ghost_spans = ghost_span;
        } else {
            // Clear ghost text buffer if no completion
            if (self.ghost_text_buffer) |old_buffer| {
                self.allocator.free(old_buffer);
                self.ghost_text_buffer = null;
            }
        }
        
        // Get LSP diagnostics and convert to diagnostic spans
        // Grain/Tiger style: fixed-size array, no dynamic allocation
        const diagnostics = self.get_diagnostics();
        var diagnostic_spans:
[GrainAurora.MAX_DIAGNOSTIC_SPANS]GrainAurora.DiagnosticSpan = undefined;
        var diagnostic_spans_len: u32 = 0;
        
        // Assert: Diagnostics must be bounded
        std.debug.assert(diagnostics.len <=
LspClient.MAX_DIAGNOSTICS_PER_DOCUMENT);
        std.debug.assert(diagnostics.len <=
GrainAurora.MAX_DIAGNOSTIC_SPANS);
        
        for (diagnostics) |diag| {
            // Bounded: Check if we've reached max spans
            if (diagnostic_spans_len >=
GrainAurora.MAX_DIAGNOSTIC_SPANS) break;
            
            // Convert diagnostic range to byte positions
            const start_byte = try self.position_to_byte(text,
diag.range.start);
            const end_byte = try self.position_to_byte(text,
diag.range.end);
            
            // Assert: Byte positions must be valid
            std.debug.assert(start_byte <= end_byte);
            std.debug.assert(end_byte <= text.len);
            
            // Copy diagnostic message to fixed-size buffer (truncate if
needed)
            var message_buf: [GrainAurora.MAX_DIAGNOSTIC_MESSAGE_LEN]u8
= undefined;
            const message_len = @min(diag.message.len,
GrainAurora.MAX_DIAGNOSTIC_MESSAGE_LEN);
            @memcpy(message_buf[0..message_len],
diag.message[0..message_len]);
            
            // Get severity (default to Error if not specified)
            const severity: u32 = diag.severity orelse 1; // 1=Error
            
            diagnostic_spans[diagnostic_spans_len] =
GrainAurora.DiagnosticSpan{
                .start = start_byte,
                .end = end_byte,
                .severity = severity,
                .message = message_buf,
                .message_len = message_len,
            };
            diagnostic_spans_len += 1;
        }
        
        // Get LSP inlay hints and convert to inlay hint spans
        // Calculate line count from text (for requesting hints for
entire document)
        var line_count: u32 = 0;
        var last_char: u32 = 0;
        for (text) |c| {
            if (c == '\n') {
                line_count += 1;
                last_char = 0;
            } else {
                last_char += 1;
            }
        }
        const last_line = line_count;
        
        // Grain/Tiger style: fixed-size array, no dynamic allocation
        var inlay_hint_spans:
[GrainAurora.MAX_INLAY_HINT_SPANS]GrainAurora.InlayHintSpan = undefined;
        var inlay_hint_spans_len: u32 = 0;
        
        // Request inlay hints for entire document (non-fatal if it
fails)
        if (self.get_inlay_hints(0, 0, last_line, last_char)) |hints| {
            defer {
                // Free hints array (but not the strings inside, we copy
them)
                self.allocator.free(hints);
            }
            
            // Assert: Hints must be bounded
            std.debug.assert(hints.len <=
GrainAurora.MAX_INLAY_HINT_SPANS);
            
            for (hints) |hint| {
                // Bounded: Check if we've reached max spans
                if (inlay_hint_spans_len >=
GrainAurora.MAX_INLAY_HINT_SPANS) break;
                
                // Convert hint position to byte position
                const position_byte = try self.position_to_byte(text,
hint.position);
                
                // Assert: Position must be valid
                std.debug.assert(position_byte <= text.len);
                
                // Copy hint label to fixed-size buffer (truncate if
needed)
                var label_buf: [GrainAurora.MAX_INLAY_HINT_LABEL_LEN]u8
= undefined;
                const label_len = @min(hint.label.len,
GrainAurora.MAX_INLAY_HINT_LABEL_LEN);
                @memcpy(label_buf[0..label_len],
hint.label[0..label_len]);
                
                // Copy tooltip to fixed-size buffer if present
(truncate if needed)
                var tooltip_buf:
[GrainAurora.MAX_INLAY_HINT_TOOLTIP_LEN]u8 = undefined;
                var tooltip_len: u32 = 0;
                if (hint.tooltip) |tooltip| {
                    tooltip_len = @min(tooltip.len,
GrainAurora.MAX_INLAY_HINT_TOOLTIP_LEN);
                    @memcpy(tooltip_buf[0..tooltip_len],
tooltip[0..tooltip_len]);
                }
                
                // Get hint kind (default to Parameter if not specified)
                const kind: u32 = hint.kind orelse 2; // 2=Parameter
                
                // Get padding flags (default to false)
                const padding_left: bool = hint.padding_left orelse
false;
                const padding_right: bool = hint.padding_right orelse
false;
                
                inlay_hint_spans[inlay_hint_spans_len] =
GrainAurora.InlayHintSpan{
                    .position = position_byte,
                    .label = label_buf,
                    .label_len = label_len,
                    .kind = kind,
                    .tooltip = tooltip_buf,
                    .tooltip_len = tooltip_len,
                    .padding_left = padding_left,
                    .padding_right = padding_right,
                };
                inlay_hint_spans_len += 1;
            }
        } else |err| {
            // If get_inlay_hints returns an error, just skip inlay hints
            // (this is non-fatal, editor can still render without hints)
            _ = err;
        }
        
        // Get LSP code lenses and convert to code lens spans
        // Grain/Tiger style: fixed-size array, no dynamic allocation
        var code_lens_spans:
[GrainAurora.MAX_CODE_LENS_SPANS]GrainAurora.CodeLensSpan = undefined;
        var code_lens_spans_len: u32 = 0;
        
        // Request code lenses (non-fatal if it fails)
        if (self.get_code_lenses()) |lenses| {
            defer {
                // Free lenses array (but not the strings inside, we
copy them)
                self.allocator.free(lenses);
            }
            
            // Assert: Lenses must be bounded
            std.debug.assert(lenses.len <=
GrainAurora.MAX_CODE_LENS_SPANS);
            
            for (lenses) |lens| {
                // Bounded: Check if we've reached max spans
                if (code_lens_spans_len >=
GrainAurora.MAX_CODE_LENS_SPANS) break;
                
                // Convert lens range to byte positions
                const range_start_byte = try self.position_to_byte(text,
lens.range.start);
                const range_end_byte = try self.position_to_byte(text,
lens.range.end);
                
                // Assert: Range positions must be valid
                std.debug.assert(range_start_byte <= range_end_byte);
                std.debug.assert(range_end_byte <= text.len);
                
                // Code lens position is at the start of the range
(displayed above line)
                const position_byte = range_start_byte;
                
                // Get command from lens (may need to resolve first)
                if (lens.command) |cmd| {
                    // Copy command identifier to fixed-size buffer
(truncate if needed)
                    var command_buf:
[GrainAurora.MAX_CODE_LENS_COMMAND_LEN]u8 = undefined;
                    const command_len = @min(cmd.command.len,
GrainAurora.MAX_CODE_LENS_COMMAND_LEN);
                    @memcpy(command_buf[0..command_len],
cmd.command[0..command_len]);
                    
                    // Copy title to fixed-size buffer (truncate if
needed)
                    var title_buf:
[GrainAurora.MAX_CODE_LENS_TITLE_LEN]u8 = undefined;
                    const title_len = @min(cmd.title.len,
GrainAurora.MAX_CODE_LENS_TITLE_LEN);
                    @memcpy(title_buf[0..title_len],
cmd.title[0..title_len]);
                    
                    code_lens_spans[code_lens_spans_len] =
GrainAurora.CodeLensSpan{
                        .position = position_byte,
                        .title = title_buf,
                        .title_len = title_len,
                        .command = command_buf,
                        .command_len = command_len,
                        .range_start = range_start_byte,
                        .range_end = range_end_byte,
                    };
                    code_lens_spans_len += 1;
                } else {
                    // If no command, skip this lens (unresolved lenses
need resolution first)
                    // In full implementation, would resolve lens here
or queue for resolution
                    continue;
                }
            }
        } else |err| {
            // If get_code_lenses returns an error, just skip code lenses
            // (this is non-fatal, editor can still render without
lenses)
            _ = err;
        }
        
        // Get LSP document highlights and convert to highlight spans
        // Grain/Tiger style: fixed-size array, no dynamic allocation
        // Request highlights at cursor position (non-fatal if it fails)
        var document_highlight_spans:
[GrainAurora.MAX_DOCUMENT_HIGHLIGHT_SPANS]GrainAurora.DocumentHighlightSp
an = undefined;
        var document_highlight_spans_len: u32 = 0;
        
        if (self.get_document_highlights()) |highlights| {
            defer {
                // Free highlights array (but not the ranges inside, we
convert them)
                self.allocator.free(highlights);
            }
            
            // Assert: Highlights must be bounded
            std.debug.assert(highlights.len <=
GrainAurora.MAX_DOCUMENT_HIGHLIGHT_SPANS);
            
            for (highlights) |highlight| {
                // Bounded: Check if we've reached max spans
                if (document_highlight_spans_len >=
GrainAurora.MAX_DOCUMENT_HIGHLIGHT_SPANS) break;
                
                // Convert highlight range to byte positions
                const start_byte = try self.position_to_byte(text,
highlight.range.start);
                const end_byte = try self.position_to_byte(text,
highlight.range.end);
                
                // Assert: Range positions must be valid
                std.debug.assert(start_byte <= end_byte);
                std.debug.assert(end_byte <= text.len);
                
                // Get highlight kind (default to Text if not specified)
                const kind: u32 = highlight.kind orelse 1; // 1=Text
                
                document_highlight_spans[document_highlight_spans_len] =
GrainAurora.DocumentHighlightSpan{
                    .start = start_byte,
                    .end = end_byte,
                    .kind = kind,
                };
                document_highlight_spans_len += 1;
            }
        } else |err| {
            // If get_document_highlights returns an error, just skip
highlights
            // (this is non-fatal, editor can still render without
highlights)
            _ = err;
        }
        
        // Get LSP semantic tokens and convert to semantic token spans
        // Grain/Tiger style: fixed-size array, no dynamic allocation
        // Request semantic tokens for entire document (non-fatal if it
fails)
        var semantic_token_spans:
[GrainAurora.MAX_SEMANTIC_TOKEN_SPANS]GrainAurora.SemanticTokenSpan =
undefined;
        var semantic_token_spans_len: u32 = 0;
        
        if (self.get_semantic_tokens()) |tokens| {
            defer {
                // Free tokens array (but not the token data inside, we
convert them)
                self.allocator.free(tokens);
            }
            
            // Assert: Tokens must be bounded
            std.debug.assert(tokens.len <=
GrainAurora.MAX_SEMANTIC_TOKEN_SPANS);
            
            // Track current position for delta decoding
            var current_line: u32 = 0;
            var current_char: u32 = 0;
            
            for (tokens) |token| {
                // Bounded: Check if we've reached max spans
                if (semantic_token_spans_len >=
GrainAurora.MAX_SEMANTIC_TOKEN_SPANS) break;
                
                // Decode delta-encoded position
                current_line += token.delta_line;
                if (token.delta_line == 0) {
                    // Same line: add character delta
                    current_char += token.delta_start;
                } else {
                    // New line: character delta is absolute
                    current_char = token.delta_start;
                }
                
                // Convert line/character to byte position
                const start_pos = LspClient.Position{
                    .line = current_line,
                    .character = current_char,
                };
                const start_byte = try self.position_to_byte(text,
start_pos);
                
                // Calculate end position (start + length)
                const end_char = current_char + token.length;
                const end_pos = LspClient.Position{
                    .line = current_line,
                    .character = end_char,
                };
                const end_byte = try self.position_to_byte(text,
end_pos);
                
                // Assert: Range positions must be valid
                std.debug.assert(start_byte <= end_byte);
                std.debug.assert(end_byte <= text.len);
                
                semantic_token_spans[semantic_token_spans_len] =
GrainAurora.SemanticTokenSpan{
                    .start = start_byte,
                    .end = end_byte,
                    .token_type = token.token_type,
                    .modifiers = token.token_modifiers,
                };
                semantic_token_spans_len += 1;
            }
        } else |err| {
            // If get_semantic_tokens returns an error, just skip
semantic tokens
            // (this is non-fatal, editor can still render without
syntax highlighting)
            _ = err;
        }
        
        // Get LSP folding ranges and convert to folding range spans
        // Grain/Tiger style: fixed-size array, no dynamic allocation
        // Request folding ranges (non-fatal if it fails)
        var folding_range_spans:
[GrainAurora.MAX_FOLDING_RANGE_SPANS]GrainAurora.FoldingRangeSpan =
undefined;
        var folding_range_spans_len: u32 = 0;
        
        if (self.get_folding_ranges()) |ranges| {
            defer {
                // Free ranges array (but not the range data inside, we
convert them)
                self.allocator.free(ranges);
            }
            
            // Assert: Ranges must be bounded
            std.debug.assert(ranges.len <=
GrainAurora.MAX_FOLDING_RANGE_SPANS);
            
            for (ranges) |range| {
                // Bounded: Check if we've reached max spans
                if (folding_range_spans_len >=
GrainAurora.MAX_FOLDING_RANGE_SPANS) break;
                
                // Get start character (default to 0 if not specified)
                const start_char: u32 = range.start_character orelse 0;
                // Get end character (default to end of line if not
specified)
                // For now, use 0 as placeholder (would need line length
calculation)
                const end_char: u32 = range.end_character orelse 0;
                
                // Convert start position to byte position
                const start_pos = LspClient.Position{
                    .line = range.start_line,
                    .character = start_char,
                };
                const start_byte = try self.position_to_byte(text,
start_pos);
                
                // Convert end position to byte position
                const end_pos = LspClient.Position{
                    .line = range.end_line,
                    .character = end_char,
                };
                const end_byte = try self.position_to_byte(text,
end_pos);
                
                // Assert: Range positions must be valid
                std.debug.assert(start_byte <= end_byte);
                std.debug.assert(end_byte <= text.len);
                
                // Get folding range kind (default to Comment if not
specified)
                const kind: u32 = range.kind orelse 1; // 1=Comment
                
                folding_range_spans[folding_range_spans_len] =
GrainAurora.FoldingRangeSpan{
                    .start = start_byte,
                    .end = end_byte,
                    .kind = kind,
                };
                folding_range_spans_len += 1;
            }
        } else |err| {
            // If get_folding_ranges returns an error, just skip folding
ranges
            // (this is non-fatal, editor can still render without
folding)
            _ = err;
        }
        
        // Get LSP selection ranges and convert to selection range spans
        // Grain/Tiger style: fixed-size array, no dynamic allocation
        // Request selection ranges at cursor position (non-fatal if it
fails)
        var selection_range_spans:
[GrainAurora.MAX_SELECTION_RANGE_SPANS]GrainAurora.SelectionRangeSpan =
undefined;
        var selection_range_spans_len: u32 = 0;
        
        if (self.get_selection_ranges()) |ranges| {
            defer {
                // Free ranges array (but not the nested parent ranges,
we flatten them)
                self.allocator.free(ranges);
            }
            
            // Assert: Ranges must be bounded
            std.debug.assert(ranges.len <= 100); // MAX_SELECTION_RANGES
            
            // Flatten selection range hierarchy (parent-child chain)
into spans
            for (ranges) |range| {
                var current_range: ?*LspClient.SelectionRange = &range;
                var level: u32 = 0;
                
                // Traverse parent chain (innermost to outermost)
                while (current_range) |sel_range| {
                    // Bounded: Check if we've reached max spans
                    if (selection_range_spans_len >=
GrainAurora.MAX_SELECTION_RANGE_SPANS) break;
                    
                    // Convert range to byte positions
                    const start_byte = try self.position_to_byte(text,
sel_range.range.start);
                    const end_byte = try self.position_to_byte(text,
sel_range.range.end);
                    
                    // Assert: Range positions must be valid
                    std.debug.assert(start_byte <= end_byte);
                    std.debug.assert(end_byte <= text.len);
                    
                    selection_range_spans[selection_range_spans_len] =
GrainAurora.SelectionRangeSpan{
                        .start = start_byte,
                        .end = end_byte,
                        .level = level,
                    };
                    selection_range_spans_len += 1;
                    
                    // Move to parent (if exists)
                    current_range = sel_range.parent;
                    level += 1;
                    
                    // Assert: Level must be bounded (prevent infinite
loops)
                    std.debug.assert(level <= 100); //
MAX_SELECTION_LEVEL
                }
            }
        } else |err| {
            // If get_selection_ranges returns an error, just skip
selection ranges
            // (this is non-fatal, editor can still render without
selection ranges)
            _ = err;
        }
        
        // Get LSP document links and convert to document link spans
        // Grain/Tiger style: fixed-size array, no dynamic allocation
        // Request document links (non-fatal if it fails)
        var document_link_spans:
[GrainAurora.MAX_DOCUMENT_LINK_SPANS]GrainAurora.DocumentLinkSpan =
undefined;
        var document_link_spans_len: u32 = 0;
        
        if (self.get_document_links()) |links| {
            defer {
                // Free links array (but not the strings inside, we copy
them)
                self.allocator.free(links);
            }
            
            // Assert: Links must be bounded
            std.debug.assert(links.len <=
GrainAurora.MAX_DOCUMENT_LINK_SPANS);
            
            for (links) |link| {
                // Bounded: Check if we've reached max spans
                if (document_link_spans_len >=
GrainAurora.MAX_DOCUMENT_LINK_SPANS) break;
                
                // Convert link range to byte positions
                const start_byte = try self.position_to_byte(text,
link.range.start);
                const end_byte = try self.position_to_byte(text,
link.range.end);
                
                // Assert: Range positions must be valid
                std.debug.assert(start_byte <= end_byte);
                std.debug.assert(end_byte <= text.len);
                
                // Copy target URI to fixed-size buffer if present
(truncate if needed)
                var target_buf:
[GrainAurora.MAX_DOCUMENT_LINK_TARGET_LEN]u8 = undefined;
                var target_len: u32 = 0;
                if (link.target) |target| {
                    target_len = @min(target.len,
GrainAurora.MAX_DOCUMENT_LINK_TARGET_LEN);
                    @memcpy(target_buf[0..target_len],
target[0..target_len]);
                }
                
                // Copy tooltip to fixed-size buffer if present
(truncate if needed)
                var tooltip_buf:
[GrainAurora.MAX_DOCUMENT_LINK_TOOLTIP_LEN]u8 = undefined;
                var tooltip_len: u32 = 0;
                if (link.tooltip) |tooltip| {
                    tooltip_len = @min(tooltip.len,
GrainAurora.MAX_DOCUMENT_LINK_TOOLTIP_LEN);
                    @memcpy(tooltip_buf[0..tooltip_len],
tooltip[0..tooltip_len]);
                }
                
                document_link_spans[document_link_spans_len] =
GrainAurora.DocumentLinkSpan{
                    .start = start_byte,
                    .end = end_byte,
                    .target = target_buf,
                    .target_len = target_len,
                    .tooltip = tooltip_buf,
                    .tooltip_len = tooltip_len,
                };
                document_link_spans_len += 1;
            }
        } else |err| {
            // If get_document_links returns an error, just skip
document links
            // (this is non-fatal, editor can still render without links)
            _ = err;
        }
        
        // Convert readonly spans to Aurora spans (for compatibility)
        var readonly_aurora_spans: [1000]GrainAurora.Span = undefined;
        var readonly_aurora_spans_len: u32 = 0;
        for (readonly_spans) |segment| {
            if (readonly_aurora_spans_len >= 1000) break; // Bounded
            readonly_aurora_spans[readonly_aurora_spans_len] =
GrainAurora.Span{
                .start = @as(u32, @intCast(segment.start)),
                .end = @as(u32, @intCast(segment.end)),
            };
            readonly_aurora_spans_len += 1;
        }
        
        // Create RenderResult with fixed-size arrays (Grain/Tiger
style: no dynamic allocation)
        // Note: We store the arrays directly in RenderResult, not slices
        const result = GrainAurora.RenderResult{
            .root = .{ .text = rendered_text },
            .readonly_spans =
readonly_aurora_spans[0..readonly_aurora_spans_len],
            .ghost_spans = ghost_spans,
            .diagnostic_spans = diagnostic_spans,
            .diagnostic_spans_len = diagnostic_spans_len,
            .inlay_hint_spans = inlay_hint_spans,
            .inlay_hint_spans_len = inlay_hint_spans_len,
            .code_lens_spans = code_lens_spans,
            .code_lens_spans_len = code_lens_spans_len,
            .document_highlight_spans = document_highlight_spans,
            .document_highlight_spans_len = document_highlight_spans_len,
            .semantic_token_spans = semantic_token_spans,
            .semantic_token_spans_len = semantic_token_spans_len,
            .folding_range_spans = folding_range_spans,
            .folding_range_spans_len = folding_range_spans_len,
            .selection_range_spans = selection_range_spans,
            .selection_range_spans_len = selection_range_spans_len,
            .document_link_spans = document_link_spans,
            .document_link_spans_len = document_link_spans_len,
        };
        
        return result;
    }
    
    /// Request tool call from AI provider (if enabled).
    /// Executes commands like `zig build`, `jj status`, etc.
    pub fn request_tool_call(
        self: *Editor,
        tool_name: []const u8,
        arguments: []const []const u8,
        context: []const AiProvider.Message,
    ) !AiProvider.ToolCallResult {
        // Assert: Tool name and arguments must be valid
        std.debug.assert(tool_name.len > 0);
        std.debug.assert(tool_name.len <= 256); // Bounded:
MAX_TOOL_NAME_LEN
        std.debug.assert(arguments.len <= 32); // Bounded: MAX_TOOL_ARGS
        
        if (self.ai_provider) |*provider| {
            const request = AiProvider.ToolCallRequest{
                .tool_name = tool_name,
                .arguments = arguments,
                .context = context,
            };
            
            return try provider.request_tool_call(request);
        } else {
            // No AI provider enabled, return error
            return AiProvider.ToolCallResult{
                .success = false,
                .output = "",
                .error_output = "AI provider not enabled",
                .exit_code = -1,
            };
        }
    }
    
    /// Refactor: Rename symbol at current cursor position.
    pub fn refactor_rename(
        self: *Editor,
        symbol_name: []const u8,
        new_name: []const u8,
    ) !AiTransforms.TransformResult {
        // Assert: Symbol names must be valid
        std.debug.assert(symbol_name.len > 0);
        std.debug.assert(symbol_name.len <=
AiTransforms.MAX_SYMBOL_NAME_LENGTH);
        std.debug.assert(new_name.len > 0);
        std.debug.assert(new_name.len <=
AiTransforms.MAX_SYMBOL_NAME_LENGTH);
        
        if (self.ai_transforms) |*transforms| {
            return try transforms.refactor_rename(
                self.file_uri,
                symbol_name,
                new_name,
                self.cursor_line,
                self.cursor_char,
            );
        } else {
            return AiTransforms.TransformResult{
                .transform_type = .refactor_rename,
                .file_edits = &.{},
                .file_edits_len = 0,
                .success = false,
                .error_message = "AI provider not enabled",
            };
        }
    }
    
    /// Refactor: Move function/struct to different location.
    pub fn refactor_move(
        self: *Editor,
        symbol_name: []const u8,
        target_file_uri: []const u8,
        target_line: u32,
    ) !AiTransforms.TransformResult {
        // Assert: Parameters must be valid
        std.debug.assert(symbol_name.len > 0);
        std.debug.assert(symbol_name.len <=
AiTransforms.MAX_SYMBOL_NAME_LENGTH);
        std.debug.assert(target_file_uri.len > 0);
        std.debug.assert(target_file_uri.len <=
AiTransforms.MAX_FILE_URI_LENGTH);
        
        if (self.ai_transforms) |*transforms| {
            return try transforms.refactor_move(
                self.file_uri,
                symbol_name,
                target_file_uri,
                target_line,
                self.cursor_line,
                self.cursor_char,
            );
        } else {
            return AiTransforms.TransformResult{
                .transform_type = .refactor_move,
                .file_edits = &.{},
                .file_edits_len = 0,
                .success = false,
                .error_message = "AI provider not enabled",
            };
        }
    }
    
    /// Extract function: Extract selected code into new function.
    pub fn extract_function(
        self: *Editor,
        function_name: []const u8,
        start_line: u32,
        start_char: u32,
        end_line: u32,
        end_char: u32,
    ) !AiTransforms.TransformResult {
        // Assert: Parameters must be valid
        std.debug.assert(function_name.len > 0);
        std.debug.assert(function_name.len <=
AiTransforms.MAX_SYMBOL_NAME_LENGTH);
        std.debug.assert(start_line <= end_line);
        
        if (self.ai_transforms) |*transforms| {
            // Get selected text from buffer
            const text = self.buffer.textSlice();
            const start_pos = start_line * 80 + start_char;
            const end_pos = end_line * 80 + end_char;
            
            // Assert: Positions must be within bounds
            std.debug.assert(start_pos <= text.len);
            std.debug.assert(end_pos <= text.len);
            std.debug.assert(start_pos <= end_pos);
            
            const selected_text = text[start_pos..end_pos];
            
            return try transforms.extract_function(
                self.file_uri,
                function_name,
                start_line,
                start_char,
                end_line,
                end_char,
                selected_text,
            );
        } else {
            return AiTransforms.TransformResult{
                .transform_type = .extract_function,
                .file_edits = &.{},
                .file_edits_len = 0,
                .success = false,
                .error_message = "AI provider not enabled",
            };
        }
    }
    
    /// Inline function: Inline function call at current cursor position.
    pub fn inline_function(
        self: *Editor,
        function_name: []const u8,
    ) !AiTransforms.TransformResult {
        // Assert: Function name must be valid
        std.debug.assert(function_name.len > 0);
        std.debug.assert(function_name.len <=
AiTransforms.MAX_SYMBOL_NAME_LENGTH);
        
        if (self.ai_transforms) |*transforms| {
            return try transforms.inline_function(
                self.file_uri,
                function_name,
                self.cursor_line,
                self.cursor_char,
            );
        } else {
            return AiTransforms.TransformResult{
                .transform_type = .inline_function,
                .file_edits = &.{},
                .file_edits_len = 0,
                .success = false,
                .error_message = "AI provider not enabled",
            };
        }
    }
    
    /// Apply transformation edits to current buffer.
    pub fn apply_transformation_edits(
        self: *Editor,
        result: AiTransforms.TransformResult,
    ) !void {
        // Assert: Result must be valid
        std.debug.assert(result.file_edits_len <=
AiTransforms.MAX_FILES_PER_TRANSFORM);
        
        if (!result.success) {
            return;
        }
        
        // Get current file content
        const file_content = self.buffer.textSlice();
        
        // Filter edits for current file
        var current_file_edits =
std.ArrayList(AiTransforms.FileEdit).init(self.allocator);
        defer current_file_edits.deinit();
        
        for (result.file_edits[0..result.file_edits_len]) |edit| {
            if (std.mem.eql(u8, edit.file_uri, self.file_uri)) {
                try current_file_edits.append(edit);
            }
        }
        
        if (current_file_edits.items.len > 0) {
            // Apply edits using AiTransforms
            if (self.ai_transforms) |*transforms| {
                const modified_content =
transforms.apply_edits(file_content, current_file_edits.items) catch
|err| {
                    // If edit application fails, return error
                    return err;
                };
                defer self.allocator.free(modified_content);
                
                // Replace buffer content
                self.buffer.deinit();
                self.buffer = GrainBuffer.fromSlice(self.allocator,
modified_content) catch |err| {
                    // If buffer creation fails, free content and return
error
                    self.allocator.free(modified_content);
                    return err;
                };
                
                // Update Aurora
                self.aurora.deinit();
                self.aurora = GrainAurora.init(self.allocator,
modified_content) catch |err| {
                    // If Aurora init fails, free buffer and content,
then return error
                    self.buffer.deinit();
                    self.allocator.free(modified_content);
                    return err;
                };
            }
        }
    }
    
    /// Save editor buffer to file.
    /// Why: Persist editor content to disk.
    /// Contract: file_uri must be a valid file path.
    pub fn save_file(self: *Editor) !void {
        // Assert: File URI must be valid
        std.debug.assert(self.file_uri.len > 0);
        std.debug.assert(self.file_uri.len <= 4096); // Bounded URI
length
        
        // Request will save wait until (get text edits before save)
        // Reason: 1 = Manual (user explicitly saved)
        const will_save_edits = try
self.lsp.requestWillSaveWaitUntil(self.file_uri, 1);
        defer if (will_save_edits) |edits| {
            // Free edits if they were returned
            for (edits) |*edit| {
                self.allocator.free(edit.new_text);
            }
            self.allocator.free(edits);
        };
        
        // Apply will save edits if any
        if (will_save_edits) |edits| {
            if (edits.len > 0) {
                try self.apply_text_edits(edits);
            }
        }
        
        // Request will save (check if save should proceed)
        const should_save = try self.lsp.requestWillSave(self.file_uri,
1);
        if (!should_save) {
            // Save was cancelled by LSP server
            // Note: In full implementation, this would return a custom
error
            // For now, we'll proceed with save anyway (willSave is
advisory)
        }
        
        // Extract file path from URI (remove "file://" prefix if
present)
        const file_path = if (std.mem.startsWith(u8, self.file_uri,
"file://"))
            self.file_uri[7..]
        else
            self.file_uri;
        
        // Assert: File path must be valid
        std.debug.assert(file_path.len > 0);
        std.debug.assert(file_path.len <= 4096); // Bounded path length
        
        // Get buffer content (may have been modified by will save edits)
        const content = self.buffer.textSlice();
        
        // Assert: Content size must be bounded
        std.debug.assert(content.len <= 100 * 1024 * 1024); // Max 100MB
        
        // Open file for writing (create or truncate)
        const cwd = std.fs.cwd();
        const file = try cwd.createFile(file_path, .{});
        defer file.close();
        
        // Write content to file
        try file.writeAll(content);
        
        // Notify LSP server that file was saved (include text for
server processing)
        try self.lsp.didSave(self.file_uri, content);
        
        // Assert: File written successfully
        std.debug.assert(file_path.len > 0);
    }
    
    /// Load file into editor buffer.
    /// Why: Load file content from disk into editor.
    /// Contract: file_uri must be a valid file path.
    pub fn load_file(self: *Editor, file_uri: []const u8) !void {
        // Assert: File URI must be valid
        std.debug.assert(file_uri.len > 0);
        std.debug.assert(file_uri.len <= 4096); // Bounded URI length
        
        // Extract file path from URI (remove "file://" prefix if
present)
        const file_path = if (std.mem.startsWith(u8, file_uri,
"file://"))
            file_uri[7..]
        else
            file_uri;
        
        // Assert: File path must be valid
        std.debug.assert(file_path.len > 0);
        std.debug.assert(file_path.len <= 4096); // Bounded path length
        
        // Open file for reading
        const cwd = std.fs.cwd();
        const file = try cwd.openFile(file_path, .{});
        defer file.close();
        
        // Read file content (bounded to 100MB)
        const max_file_size: u32 = 100 * 1024 * 1024;
        const content = try file.readToEndAlloc(self.allocator,
max_file_size);
        defer self.allocator.free(content);
        
        // Assert: Content size must be bounded
        std.debug.assert(content.len <= max_file_size);
        
        // Replace buffer content
        self.buffer.deinit();
        self.buffer = GrainBuffer.fromSlice(self.allocator, content)
catch |err| {
            // If buffer creation fails, free content and return error
            self.allocator.free(content);
            return err;
        };
        
        // Update Aurora rendering
        self.aurora.deinit();
        self.aurora = GrainAurora.init(self.allocator, content) catch
|err| {
            // If Aurora init fails, free buffer and content, then
return error
            self.buffer.deinit();
            self.allocator.free(content);
            return err;
        };
        
        // Update file URI
        if (!std.mem.eql(u8, self.file_uri, file_uri)) {
            self.allocator.free(self.file_uri);
            self.file_uri = self.allocator.dupe(u8, file_uri) catch
|err| {
                // If URI duplication fails, clean up and return error
                self.buffer.deinit();
                self.aurora.deinit();
                self.allocator.free(content);
                return err;
            };
        }
        
        // Parse for folds and syntax tree (errors are non-fatal,
continue if they fail)
        self.folding.parse(content) catch {};
        _ = self.tree_sitter.parseZig(content) catch {};
        
        // Reset cursor position
        self.cursor_line = 0;
        self.cursor_char = 0;
        
        // Assert: File loaded successfully
        std.debug.assert(self.buffer.textSlice().len == content.len);
    }
};

