// === aurora_glm46_provider.zig ===

const std = @import("std");
const AiProvider = @import("aurora_ai_provider.zig").AiProvider;
const Glm46Client = @import("aurora_glm46.zig").Glm46Client;

/// GLM-4.6 Provider: GLM-4.6-specific implementation of AI provider
interface.
/// ~<~ Glow Airbend: explicit GLM-4.6 API calls, bounded context
windows.
/// ~~~~ Glow Waterbend: GLM-4.6 responses flow deterministically.
pub const Glm46Provider = struct {
    allocator: std.mem.Allocator,
    client: Glm46Client,
    
    /// Initialize GLM-4.6 provider.
    pub fn init(allocator: std.mem.Allocator, config:
AiProvider.ProviderConfig) !*Glm46Provider {
        // Assert: Config must be for GLM-4.6
        std.debug.assert(config == .glm46);
        std.debug.assert(config.glm46.api_key.len > 0);
        
        const provider = try allocator.create(Glm46Provider);
        errdefer allocator.destroy(provider);
        
        provider.* = Glm46Provider{
            .allocator = allocator,
            .client = Glm46Client.init(allocator, config.glm46.api_key),
        };
        
        return provider;
    }
    
    /// Deinitialize GLM-4.6 provider.
    pub fn deinit_impl(self: *anyopaque) void {
        const provider: *Glm46Provider = @ptrCast(@alignCast(self));
        provider.client.deinit();
        provider.allocator.destroy(provider);
    }
    
    /// Request code completion (streaming).
    pub fn request_completion_impl(
        self: *anyopaque,
        request: AiProvider.CompletionRequest,
        callback: fn (chunk: AiProvider.CompletionChunk) void,
    ) !void {
        const provider: *Glm46Provider = @ptrCast(@alignCast(self));
        
        // Assert: Request must be valid
        std.debug.assert(request.messages.len > 0);
        std.debug.assert(request.messages.len <=
AiProvider.MAX_MESSAGES);
        
        // Convert AiProvider messages to Glm46Client messages
        const messages = try
provider.allocator.alloc(Glm46Client.Message, request.messages.len);
        defer provider.allocator.free(messages);
        
        for (request.messages, 0..) |msg, i| {
            // Assert: Message content must be within bounds
            std.debug.assert(msg.content.len <=
AiProvider.MAX_MESSAGE_SIZE);
            
            messages[i] = Glm46Client.Message{
                .role = msg.role,
                .content = msg.content,
            };
        }
        
        // Request completion from GLM-4.6 client
        try provider.client.requestCompletion(messages, struct {
            fn callback_wrapper(chunk: []const u8) void {
                callback(AiProvider.CompletionChunk{
                    .content = chunk,
                    .is_done = false,
                });
            }
        }.callback_wrapper);
        
        // Signal completion
        callback(AiProvider.CompletionChunk{
            .content = "",
            .is_done = true,
        });
    }
    
    /// Request code transformation.
    pub fn request_transformation_impl(
        self: *anyopaque,
        request: AiProvider.TransformRequest,
    ) !AiProvider.TransformResult {
        const provider: *Glm46Provider = @ptrCast(@alignCast(self));
        
        // Convert transformation request to GLM-4.6 format
        // For now, return placeholder (full implementation would call
GLM-4.6 API)
        _ = request;
        
        const error_msg = try provider.allocator.dupe(u8, "Not yet
implemented");
        return AiProvider.TransformResult{
            .file_edits = &.{},
            .file_edits_len = 0,
            .success = false,
            .error_message = error_msg,
        };
    }
    
    /// Request tool call.
    /// Executes commands like `zig build`, `jj status`, etc.
    pub fn request_tool_call_impl(
        self: *anyopaque,
        request: AiProvider.ToolCallRequest,
    ) !AiProvider.ToolCallResult {
        const provider: *Glm46Provider = @ptrCast(@alignCast(self));
        
        // Assert: Tool name and arguments must be valid
        std.debug.assert(request.tool_name.len > 0);
        std.debug.assert(request.tool_name.len <= 256); // Bounded:
MAX_TOOL_NAME_LEN
        std.debug.assert(request.arguments.len <= 32); // Bounded:
MAX_TOOL_ARGS
        
        // Build command arguments
        var cmd_args = std.ArrayList([]const
u8).init(provider.allocator);
        defer cmd_args.deinit();
        
        // Add tool name as first argument
        const tool_name_owned = try provider.allocator.dupe(u8,
request.tool_name);
        errdefer provider.allocator.free(tool_name_owned);
        try cmd_args.append(tool_name_owned);
        
        // Add arguments
        for (request.arguments) |arg| {
            // Assert: Each argument must be within bounds
            std.debug.assert(arg.len <= 4096); // Bounded: MAX_ARG_LEN
            
            const arg_owned = try provider.allocator.dupe(u8, arg);
            errdefer provider.allocator.free(arg_owned);
            try cmd_args.append(arg_owned);
        }
        
        // Spawn process
        var child = std.process.Child.init(cmd_args.items,
provider.allocator);
        child.stdout_behavior = .Pipe;
        child.stderr_behavior = .Pipe;
        
        try child.spawn();
        
        // Read stdout
        const stdout = child.stdout orelse return error.NoStdout;
        var output = std.ArrayList(u8).init(provider.allocator);
        errdefer output.deinit();
        
        var stdout_buf: [4096]u8 = undefined;
        while (true) {
            const bytes_read_u64 = try stdout.read(&stdout_buf);
            if (bytes_read_u64 == 0) break;
            
            // Assert: Bytes read fits in u32
            std.debug.assert(bytes_read_u64 <= std.math.maxInt(u32));
            const bytes_read = @as(u32, @intCast(bytes_read_u64));
            
            // Assert: Output size bounded (10MB max)
            std.debug.assert(output.items.len + bytes_read <= 10 * 1024
* 1024);
            
            try output.appendSlice(stdout_buf[0..bytes_read]);
        }
        
        // Read stderr
        const stderr = child.stderr orelse return error.NoStderr;
        var error_output = std.ArrayList(u8).init(provider.allocator);
        errdefer error_output.deinit();
        
        var stderr_buf: [4096]u8 = undefined;
        while (true) {
            const bytes_read_u64 = try stderr.read(&stderr_buf);
            if (bytes_read_u64 == 0) break;
            
            // Assert: Bytes read fits in u32
            std.debug.assert(bytes_read_u64 <= std.math.maxInt(u32));
            const bytes_read = @as(u32, @intCast(bytes_read_u64));
            
            // Assert: Error output size bounded (10MB max)
            std.debug.assert(error_output.items.len + bytes_read <= 10 *
1024 * 1024);
            
            try error_output.appendSlice(stderr_buf[0..bytes_read]);
        }
        
        // Wait for process
        const term = try child.wait();
        
        // Determine exit code
        const exit_code: i32 = switch (term) {
            .Exited => |code| code,
            .Signal => |sig| -@as(i32, @intCast(sig)),
            .Stopped => |sig| -@as(i32, @intCast(sig)),
            .Unknown => |code| code,
        };
        
        // Allocate output strings
        const output_str = try output.toOwnedSlice();
        errdefer provider.allocator.free(output_str);
        
        const error_output_str = if (error_output.items.len > 0) 
            try error_output.toOwnedSlice() 
        else 
            null;
        errdefer if (error_output_str) |err|
provider.allocator.free(err);
        
        // Clean up command arguments
        for (cmd_args.items) |arg| {
            provider.allocator.free(arg);
        }
        
        return AiProvider.ToolCallResult{
            .success = exit_code == 0,
            .output = output_str,
            .error_output = error_output_str,
            .exit_code = exit_code,
        };
    }
    
    /// Get provider type.
    pub fn get_provider_type_impl(self: *const anyopaque)
AiProvider.ProviderType {
        _ = self;
        return .glm46;
    }
    
    /// VTable implementation for GLM-4.6 provider.
    pub const vtable_impl = AiProvider.VTable{
        .request_completion = request_completion_impl,
        .request_transformation = request_transformation_impl,
        .request_tool_call = request_tool_call_impl,
        .get_provider_type = get_provider_type_impl,
        .deinit = deinit_impl,
    };
};

test "glm46 provider initialization" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    const config = AiProvider.ProviderConfig{
        .glm46 = .{
            .api_key = "test-api-key",
        },
    };
    
    const provider = try Glm46Provider.init(arena.allocator(), config);
    defer Glm46Provider.deinit_impl(provider);
    
    // Assert: Provider initialized
    try std.testing.expect(@intFromPtr(provider) != 0);
}


// === aurora_grainbank.zig ===

const std = @import("std");
const DagCore = @import("dag_core.zig").DagCore;
const BrowserDagIntegration =
@import("dream_browser_dag_integration.zig").BrowserDagIntegration;

/// GrainBank Integration: Micropayments and deterministic contracts in
browser.
/// ~<~ Glow Airbend: explicit contract state, bounded payments.
/// ~~~~ Glow Waterbend: payments flow deterministically through state
machine.
///
/// This implements:
/// - Micropayments in browser (automatic payments for content)
/// - Deterministic contracts (TigerBeetle-style state machine)
/// - Peer-to-peer payments (direct Nostr-based transfers)
/// - State machine execution (bounded, deterministic)
pub const AuroraGrainBank = struct {
    allocator: std.mem.Allocator,
    dag: *DagCore,
    browser_dag: BrowserDagIntegration,
    
    // Bounded: Max 1,000 active contracts
    pub const MAX_ACTIVE_CONTRACTS: u32 = 1_000;
    active_contracts: std.ArrayList(Contract) = undefined,
    
    // Bounded: Max 10,000 pending payments per second
    pub const MAX_PENDING_PAYMENTS: u32 = 10_000;
    pending_payments: std.ArrayList(Payment) = undefined,
    
    // Bounded: Max 100 currencies per user
    pub const MAX_CURRENCIES_PER_USER: u32 = 100;
    
    pub const Contract = struct {
        id: u64, // Unique contract ID
        npub: [32]u8, // Nostr public key (issuer)
        title: []const u8, // Currency title
        policy: Policy,
        state: ContractState,
        balance: u128, // Current balance
        dag_node_id: u32, // DAG node for this contract
    };
    
    pub const Policy = struct {
        base_rate_bps: i32, // Interest rate in basis points
        tax_rate_bps: i32, // Tax rate in basis points
        
        pub const encoded_len: u32 = 8;
    };
    
    pub const ContractState = enum {
        pending, // Contract created, not yet executed
        active, // Contract active, accepting payments
        completed, // Contract completed successfully
        failed, // Contract execution failed
    };
    
    pub const Payment = struct {
        id: u64, // Unique payment ID
        contract_id: u64, // Contract this payment belongs to
        amount: u128, // Payment amount
        from_npub: [32]u8, // Sender's Nostr public key
        to_npub: [32]u8, // Recipient's Nostr public key
        timestamp: u64, // Unix timestamp
        state: PaymentState,
        dag_event_id: u64, // DAG event for this payment
    };
    
    pub const PaymentState = enum {
        pending, // Payment initiated, not yet confirmed
        confirmed, // Payment confirmed and executed
        failed, // Payment failed
    };
    
    pub const Action = union(enum) {
        mint: u128, // Mint currency (increase supply)
        burn: u128, // Burn currency (decrease supply)
        transfer: Transfer, // Transfer between users
        collect_tax: u128, // Collect tax
    };
    
    pub const Transfer = struct {
        amount: u128,
        to_npub: [32]u8,
    };
    
    pub fn init(allocator: std.mem.Allocator, dag: *DagCore)
!AuroraGrainBank {
        // Assert: Allocator and DAG must be valid
        std.debug.assert(allocator.ptr != null);
        _ = dag; // DAG is owned by caller
        
        const browser_dag = BrowserDagIntegration.init(allocator, dag);
        
        return AuroraGrainBank{
            .allocator = allocator,
            .dag = dag,
            .browser_dag = browser_dag,
            .active_contracts = std.ArrayList(Contract).init(allocator),
            .pending_payments = std.ArrayList(Payment).init(allocator),
        };
    }
    
    pub fn deinit(self: *AuroraGrainBank) void {
        // Free contract titles
        for (self.active_contracts.items) |*contract| {
            self.allocator.free(contract.title);
        }
        self.active_contracts.deinit();
        
        self.pending_payments.deinit();
        self.browser_dag.deinit();
        self.* = undefined;
    }
    
    /// Create new GrainBank contract (MMT-style currency).
    pub fn create_contract(
        self: *AuroraGrainBank,
        npub: [32]u8,
        title: []const u8,
        policy: Policy,
    ) !u64 {
        // Assert: Title must be valid
        std.debug.assert(title.len > 0);
        std.debug.assert(title.len <= 96); // Bounded title length
        
        // Assert: Bounded contracts
        std.debug.assert(self.active_contracts.items.len <
MAX_ACTIVE_CONTRACTS);
        
        // Create DAG node for contract
        var node_data = std.ArrayList(u8).init(self.allocator);
        defer node_data.deinit();
        
        const writer = node_data.writer();
        try writer.print("grainbank:{s}:", .{title});
        try writer.print("npub:{d}:", .{npub[0]});
        try writer.print("rate:{d}:tax:{d}", .{ policy.base_rate_bps,
policy.tax_rate_bps });
        
        const dag_node_id = try self.dag.addNode(
            .dom_node, // Use dom_node for browser contracts
            try node_data.toOwnedSlice(),
            .{},
        );
        
        // Create contract
        const contract_id = @intCast(self.active_contracts.items.len +
1);
        const title_copy = try self.allocator.dupe(u8, title);
        errdefer self.allocator.free(title_copy);
        
        try self.active_contracts.append(Contract{
            .id = contract_id,
            .npub = npub,
            .title = title_copy,
            .policy = policy,
            .state = .pending,
            .balance = 0,
            .dag_node_id = dag_node_id,
        });
        
        // Assert: Contract created successfully
        std.debug.assert(self.active_contracts.items.len <=
MAX_ACTIVE_CONTRACTS);
        
        return contract_id;
    }
    
    /// Execute contract action (mint, burn, transfer, collect_tax).
    pub fn execute_action(
        self: *AuroraGrainBank,
        contract_id: u64,
        action: Action,
    ) !void {
        // Assert: Contract ID must be valid
        std.debug.assert(contract_id > 0);
        std.debug.assert(contract_id <= self.active_contracts.items.len);
        
        const contract = &self.active_contracts.items[contract_id - 1];
        
        // Assert: Contract must be active
        std.debug.assert(contract.state == .active or contract.state ==
.pending);
        
        // Execute action based on type
        switch (action) {
            .mint => |amount| {
                // Assert: Amount must be valid
                std.debug.assert(amount > 0);
                
                // Mint currency (increase balance)
                contract.balance +%= amount;
                
                // Create DAG event for mint
                const parent_events = try
self.get_latest_parent_events();
                _ = try self.dag.addEvent(
                    .web_request, // Use web_request for payment events
                    contract.dag_node_id,
                    try std.fmt.allocPrint(self.allocator, "mint:{d}",
.{amount}),
                    parent_events,
                );
            },
            .burn => |amount| {
                // Assert: Amount must be valid
                std.debug.assert(amount > 0);
                std.debug.assert(amount <= contract.balance);
                
                // Burn currency (decrease balance)
                contract.balance -%= amount;
                
                // Create DAG event for burn
                const parent_events = try
self.get_latest_parent_events();
                _ = try self.dag.addEvent(
                    .web_request,
                    contract.dag_node_id,
                    try std.fmt.allocPrint(self.allocator, "burn:{d}",
.{amount}),
                    parent_events,
                );
            },
            .transfer => |transfer| {
                // Assert: Transfer amount must be valid
                std.debug.assert(transfer.amount > 0);
                std.debug.assert(transfer.amount <= contract.balance);
                
                // Create peer-to-peer payment
                _ = try self.create_payment(
                    contract_id,
                    transfer.amount,
                    contract.npub,
                    transfer.to_npub,
                );
                
                // Decrease balance (transfer out)
                contract.balance -%= transfer.amount;
            },
            .collect_tax => |amount| {
                // Assert: Tax amount must be valid
                std.debug.assert(amount > 0);
                std.debug.assert(amount <= contract.balance);
                
                // Collect tax (decrease balance, tax goes to issuer)
                contract.balance -%= amount;
                
                // Create DAG event for tax collection
                const parent_events = try
self.get_latest_parent_events();
                _ = try self.dag.addEvent(
                    .web_request,
                    contract.dag_node_id,
                    try std.fmt.allocPrint(self.allocator, "tax:{d}",
.{amount}),
                    parent_events,
                );
            },
        }
        
        // Activate contract if pending
        if (contract.state == .pending) {
            contract.state = .active;
        }
    }
    
    /// Create peer-to-peer payment.
    pub fn create_payment(
        self: *AuroraGrainBank,
        contract_id: u64,
        amount: u128,
        from_npub: [32]u8,
        to_npub: [32]u8,
    ) !u64 {
        // Assert: Contract ID and amount must be valid
        std.debug.assert(contract_id > 0);
        std.debug.assert(contract_id <= self.active_contracts.items.len);
        std.debug.assert(amount > 0);
        
        // Assert: Bounded pending payments
        std.debug.assert(self.pending_payments.items.len <
MAX_PENDING_PAYMENTS);
        
        const contract = &self.active_contracts.items[contract_id - 1];
        
        // Assert: Contract must be active
        std.debug.assert(contract.state == .active);
        std.debug.assert(amount <= contract.balance);
        
        // Create payment
        const payment_id = @intCast(self.pending_payments.items.len + 1);
        const timestamp = std.time.timestamp();
        std.debug.assert(timestamp >= 0);
        const timestamp_u64 = @intCast(timestamp);
        
        // Create DAG event for payment
        const parent_events = try self.get_latest_parent_events();
        const dag_event_id = try self.dag.addEvent(
            .web_request,
            contract.dag_node_id,
            try std.fmt.allocPrint(
                self.allocator,
                "payment:{d}:from:{d}:to:{d}",
                .{ amount, from_npub[0], to_npub[0] },
            ),
            parent_events,
        );
        
        try self.pending_payments.append(Payment{
            .id = payment_id,
            .contract_id = contract_id,
            .amount = amount,
            .from_npub = from_npub,
            .to_npub = to_npub,
            .timestamp = timestamp_u64,
            .state = .pending,
            .dag_event_id = dag_event_id,
        });
        
        // Execute payment immediately (deterministic state machine)
        try self.process_payment(payment_id);
        
        // Assert: Payment created successfully
        std.debug.assert(self.pending_payments.items.len <=
MAX_PENDING_PAYMENTS);
        
        return payment_id;
    }
    
    /// Process payment (TigerBeetle-style deterministic state machine).
    fn process_payment(self: *AuroraGrainBank, payment_id: u64) !void {
        // Assert: Payment ID must be valid
        std.debug.assert(payment_id > 0);
        std.debug.assert(payment_id <= self.pending_payments.items.len);
        
        const payment = &self.pending_payments.items[payment_id - 1];
        
        // Assert: Payment must be pending
        std.debug.assert(payment.state == .pending);
        
        // Execute payment (deterministic)
        // In a real implementation, this would:
        // 1. Verify sender has sufficient balance
        // 2. Transfer amount from sender to recipient
        // 3. Update contract balance
        // 4. Confirm payment
        
        // For now, mark as confirmed (deterministic execution)
        payment.state = .confirmed;
        
        // Assert: Payment must be confirmed
        std.debug.assert(payment.state == .confirmed);
    }
    
    /// Process all pending payments (batch processing).
    pub fn process_pending_payments(self: *AuroraGrainBank) !void {
        // Assert: Payments must be within bounds
        std.debug.assert(self.pending_payments.items.len <=
MAX_PENDING_PAYMENTS);
        
        // Process payments in order (deterministic)
        for (self.pending_payments.items) |*payment| {
            if (payment.state == .pending) {
                try self.process_payment(payment.id);
            }
        }
        
        // Process DAG events (TigerBeetle-style state machine)
        try self.dag.processEvents();
    }
    
    /// Get contract by ID.
    pub fn get_contract(self: *AuroraGrainBank, contract_id: u64)
?*Contract {
        // Assert: Contract ID must be valid
        if (contract_id == 0 or contract_id >
self.active_contracts.items.len) {
            return null;
        }
        
        return &self.active_contracts.items[contract_id - 1];
    }
    
    /// Get payment by ID.
    pub fn get_payment(self: *AuroraGrainBank, payment_id: u64)
?*Payment {
        // Assert: Payment ID must be valid
        if (payment_id == 0 or payment_id >
self.pending_payments.items.len) {
            return null;
        }
        
        return &self.pending_payments.items[payment_id - 1];
    }
    
    /// Get latest parent events for HashDAG-style ordering.
    fn get_latest_parent_events(self: *AuroraGrainBank) ![]const u64 {
        // Get latest events from DAG (for parent references)
        // Bounded: Max 10 parent events
        const max_parents: u32 = 10;
        var parents = std.ArrayList(u64).init(self.allocator);
        errdefer parents.deinit();
        
        // Get latest events (simplified: get from pending events)
        const count = @min(self.dag.pending_events_len, max_parents);
        for (0..count) |i| {
            const event = self.dag.pending_events[i];
            try parents.append(event.id);
        }
        
        return try parents.toOwnedSlice();
    }
    
    /// Get all active contracts (for browser display).
    pub fn get_active_contracts(self: *AuroraGrainBank) []const Contract
{
        return self.active_contracts.items;
    }
    
    /// Get all pending payments (for browser display).
    pub fn get_pending_payments(self: *AuroraGrainBank) []const Payment {
        return self.pending_payments.items;
    }
};

test "grainbank lifecycle" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag = try DagCore.init(arena.allocator());
    defer dag.deinit();
    
    var grainbank = try AuroraGrainBank.init(arena.allocator(), &dag);
    defer grainbank.deinit();
    
    // Assert: GrainBank initialized
    std.debug.assert(grainbank.active_contracts.items.len == 0);
    std.debug.assert(grainbank.pending_payments.items.len == 0);
}

test "grainbank create contract" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag = try DagCore.init(arena.allocator());
    defer dag.deinit();
    
    var grainbank = try AuroraGrainBank.init(arena.allocator(), &dag);
    defer grainbank.deinit();
    
    var npub: [32]u8 = undefined;
    @memset(&npub, 0x42);
    
    const contract_id = try grainbank.create_contract(
        npub,
        "TestCurrency",
        .{ .base_rate_bps = 100, .tax_rate_bps = 50 },
    );
    
    // Assert: Contract created
    std.debug.assert(contract_id > 0);
    std.debug.assert(grainbank.active_contracts.items.len == 1);
    
    const contract = grainbank.get_contract(contract_id);
    std.debug.assert(contract != null);
    std.debug.assert(contract.?.state == .pending);
}

test "grainbank execute mint" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag = try DagCore.init(arena.allocator());
    defer dag.deinit();
    
    var grainbank = try AuroraGrainBank.init(arena.allocator(), &dag);
    defer grainbank.deinit();
    
    var npub: [32]u8 = undefined;
    @memset(&npub, 0x42);
    
    const contract_id = try grainbank.create_contract(
        npub,
        "TestCurrency",
        .{ .base_rate_bps = 100, .tax_rate_bps = 50 },
    );
    
    // Execute mint action
    try grainbank.execute_action(contract_id, .{ .mint = 1000 });
    
    // Assert: Balance increased
    const contract = grainbank.get_contract(contract_id);
    std.debug.assert(contract != null);
    std.debug.assert(contract.?.balance == 1000);
    std.debug.assert(contract.?.state == .active);
}


// === aurora_layout.zig ===

const std = @import("std");

/// Multi-pane layout system inspired by River compositor.
/// ~<~ Glow Airbend: explicit layout tree, bounded panes.
/// ~~~~ Glow Waterbend: layout flows deterministically from split
operations.
pub const Layout = struct {
    allocator: std.mem.Allocator,
    root: ?*Pane = null,
    
    // Bounded: Max 100 panes per workspace
    pub const MAX_PANES: u32 = 100;
    pane_count: u32 = 0,
    
    // Bounded: Max 10 workspaces
    pub const MAX_WORKSPACES: u32 = 10;
    workspaces: std.ArrayList(Workspace) = undefined,
    current_workspace: u32 = 0,
    
    pub const Pane = struct {
        id: u32,
        rect: Rectangle,
        pane_type: PaneType,
        parent: ?*Pane = null,
        left: ?*Pane = null,
        right: ?*Pane = null,
        focused: bool = false,
    };
    
    pub const Rectangle = struct {
        x: u32,
        y: u32,
        width: u32,
        height: u32,
    };
    
    pub const PaneType = enum {
        editor,
        terminal,
        vcs_status,
        browser,
    };
    
    pub const SplitDirection = enum {
        horizontal,
        vertical,
    };
    
    pub const Workspace = struct {
        id: u32,
        name: []const u8,
        root: ?*Pane = null,
    };
    
    pub fn init(allocator: std.mem.Allocator) Layout {
        return Layout{
            .allocator = allocator,
            .workspaces = std.ArrayList(Workspace).init(allocator),
        };
    }
    
    pub fn deinit(self: *Layout) void {
        // Free all panes (iterative, no recursion)
        if (self.root) |root| {
            self.free_pane_tree(root);
        }
        
        // Free workspace names
        for (self.workspaces.items) |*ws| {
            self.allocator.free(ws.name);
            if (ws.root) |root| {
                self.free_pane_tree(root);
            }
        }
        self.workspaces.deinit();
        
        self.* = undefined;
    }
    
    /// Free pane tree iteratively (no recursion, GrainStyle).
    fn free_pane_tree(self: *Layout, root: *Pane) void {
        // Assert: Root must be valid
        std.debug.assert(root != null);
        
        // Use explicit stack instead of recursion
        // Bounded: Max stack depth of MAX_PANES
        var stack: [MAX_PANES]?*Pane = undefined;
        var stack_len: u32 = 0;
        
        stack[stack_len] = root;
        stack_len += 1;
        
        while (stack_len > 0) {
            // Assert: Stack depth within bounds
            std.debug.assert(stack_len <= MAX_PANES);
            
            stack_len -= 1;
            const current = stack[stack_len].?;
            
            // Add children to stack
            if (current.left) |left| {
                // Assert: Stack has room
                std.debug.assert(stack_len < MAX_PANES);
                stack[stack_len] = left;
                stack_len += 1;
            }
            if (current.right) |right| {
                // Assert: Stack has room
                std.debug.assert(stack_len < MAX_PANES);
                stack[stack_len] = right;
                stack_len += 1;
            }
            
            // Free current pane
            self.allocator.destroy(current);
            self.pane_count -= 1;
        }
    }
    
    /// Create initial workspace with single editor pane.
    pub fn create_workspace(self: *Layout, name: []const u8, width: u32,
height: u32) !u32 {
        // Assert: Name and dimensions must be valid
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= 256); // Bounded name length
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        std.debug.assert(width <= 16384); // Bounded width (16K)
        std.debug.assert(height <= 16384); // Bounded height (16K)
        
        // Assert: Bounded workspaces
        std.debug.assert(self.workspaces.items.len < MAX_WORKSPACES);
        
        // Create root pane (editor)
        const pane = try self.allocator.create(Pane);
        pane.* = Pane{
            .id = self.pane_count,
            .rect = Rectangle{
                .x = 0,
                .y = 0,
                .width = width,
                .height = height,
            },
            .pane_type = .editor,
            .focused = true,
        };
        self.pane_count += 1;
        
        // Assert: Bounded panes
        std.debug.assert(self.pane_count <= MAX_PANES);
        
        // Create workspace
        const name_copy = try self.allocator.dupe(u8, name);
        errdefer self.allocator.free(name_copy);
        
        const workspace_id = @intCast(self.workspaces.items.len);
        try self.workspaces.append(Workspace{
            .id = workspace_id,
            .name = name_copy,
            .root = pane,
        });
        
        // Set as root if first workspace
        if (self.workspaces.items.len == 1) {
            self.root = pane;
        }
        
        // Assert: Workspace created successfully
        std.debug.assert(self.workspaces.items.len <= MAX_WORKSPACES);
        
        return workspace_id;
    }
    
    /// Split focused pane in given direction.
    pub fn split_pane(self: *Layout, direction: SplitDirection,
pane_type: PaneType) !void {
        // Assert: Must have root pane
        std.debug.assert(self.root != null);
        std.debug.assert(self.pane_count < MAX_PANES);
        
        // Find focused pane
        const focused = self.find_focused_pane() orelse return
error.NoFocusedPane;
        
        // Create new pane
        const new_pane = try self.allocator.create(Pane);
        new_pane.* = Pane{
            .id = self.pane_count,
            .rect = Rectangle{
                .x = 0,
                .y = 0,
                .width = 0,
                .height = 0,
            },
            .pane_type = pane_type,
            .parent = focused,
        };
        self.pane_count += 1;
        
        // Assert: Bounded panes
        std.debug.assert(self.pane_count <= MAX_PANES);
        
        // Split focused pane
        if (direction == .horizontal) {
            // Horizontal split: left/right
            const new_width = focused.rect.width / 2;
            const old_width = focused.rect.width - new_width;
            
            new_pane.rect = Rectangle{
                .x = focused.rect.x + @intCast(old_width),
                .y = focused.rect.y,
                .width = new_width,
                .height = focused.rect.height,
            };
            
            focused.rect.width = old_width;
            focused.left = new_pane;
        } else {
            // Vertical split: top/bottom
            const new_height = focused.rect.height / 2;
            const old_height = focused.rect.height - new_height;
            
            new_pane.rect = Rectangle{
                .x = focused.rect.x,
                .y = focused.rect.y + @intCast(old_height),
                .width = focused.rect.width,
                .height = new_height,
            };
            
            focused.rect.height = old_height;
            focused.right = new_pane;
        }
        
        // Focus new pane
        focused.focused = false;
        new_pane.focused = true;
        
        // Assert: Split successful
        std.debug.assert(new_pane.rect.width > 0);
        std.debug.assert(new_pane.rect.height > 0);
    }
    
    /// Find focused pane (iterative search, no recursion).
    fn find_focused_pane(self: *Layout) ?*Pane {
        if (self.root == null) return null;
        
        // Use explicit stack instead of recursion
        var stack: [MAX_PANES]?*Pane = undefined;
        var stack_len: u32 = 0;
        
        stack[stack_len] = self.root;
        stack_len += 1;
        
        while (stack_len > 0) {
            // Assert: Stack depth within bounds
            std.debug.assert(stack_len <= MAX_PANES);
            
            stack_len -= 1;
            const current = stack[stack_len].?;
            
            // Check if focused
            if (current.focused) {
                return current;
            }
            
            // Add children to stack
            if (current.left) |left| {
                // Assert: Stack has room
                std.debug.assert(stack_len < MAX_PANES);
                stack[stack_len] = left;
                stack_len += 1;
            }
            if (current.right) |right| {
                // Assert: Stack has room
                std.debug.assert(stack_len < MAX_PANES);
                stack[stack_len] = right;
                stack_len += 1;
            }
        }
        
        return null;
    }
    
    /// Focus next pane (River-style navigation).
    pub fn focus_next(self: *Layout) void {
        // Assert: Must have root
        std.debug.assert(self.root != null);
        
        const focused = self.find_focused_pane() orelse return;
        
        // Find next pane in traversal order (left-to-right,
top-to-bottom)
        const next = self.find_next_pane(focused);
        if (next) |n| {
            focused.focused = false;
            n.focused = true;
        }
    }
    
    /// Find next pane in traversal order (iterative).
    fn find_next_pane(self: *Layout, current: *Pane) ?*Pane {
        _ = self;
        
        // Simple traversal: prefer left, then right, then parent's right
        if (current.left) |left| {
            return left;
        }
        if (current.right) |right| {
            return right;
        }
        
        // Go up to parent and try its right sibling
        var parent = current.parent;
        while (parent) |p| {
            if (p.right) |right| {
                if (right.id != current.id) {
                    return right;
                }
            }
            parent = p.parent;
        }
        
        return null;
    }
    
    /// Close focused pane (merge with sibling or parent).
    pub fn close_pane(self: *Layout) !void {
        // Assert: Must have root
        std.debug.assert(self.root != null);
        
        const focused = self.find_focused_pane() orelse return
error.NoFocusedPane;
        
        // Cannot close root if it's the only pane
        if (focused.parent == null and focused.left == null and
focused.right == null) {
            return error.CannotCloseLastPane;
        }
        
        // If has parent, merge with sibling
        if (focused.parent) |parent| {
            // Give sibling focus
            if (parent.left) |left| {
                if (left.id == focused.id) {
                    // Focus is left child, focus right sibling
                    if (parent.right) |right| {
                        right.focused = true;
                        // Merge right into parent
                        parent.rect = right.rect;
                        parent.left = right.left;
                        parent.right = right.right;
                        self.allocator.destroy(right);
                        self.pane_count -= 1;
                    } else {
                        // No right sibling, become parent
                        parent.focused = true;
                        parent.left = null;
                    }
                } else {
                    // Focus is right child, focus left sibling
                    if (parent.left) |left| {
                        left.focused = true;
                        // Merge left into parent
                        parent.rect = left.rect;
                        parent.left = left.left;
                        parent.right = left.right;
                        self.allocator.destroy(left);
                        self.pane_count -= 1;
                    } else {
                        // No left sibling, become parent
                        parent.focused = true;
                        parent.right = null;
                    }
                }
            }
            
            // Free focused pane
            self.allocator.destroy(focused);
            self.pane_count -= 1;
        } else {
            // Root pane: replace with child
            if (focused.left) |left| {
                left.focused = true;
                left.parent = null;
                self.root = left;
                self.allocator.destroy(focused);
                self.pane_count -= 1;
            } else if (focused.right) |right| {
                right.focused = true;
                right.parent = null;
                self.root = right;
                self.allocator.destroy(focused);
                self.pane_count -= 1;
            }
        }
        
        // Assert: Pane count valid
        std.debug.assert(self.pane_count > 0);
    }
    
    /// Switch to workspace (River-style workspace switching).
    pub fn switch_workspace(self: *Layout, workspace_id: u32) !void {
        // Assert: Workspace ID must be valid
        std.debug.assert(workspace_id < MAX_WORKSPACES);
        std.debug.assert(workspace_id < self.workspaces.items.len);
        
        self.current_workspace = workspace_id;
        const workspace = &self.workspaces.items[workspace_id];
        self.root = workspace.root;
        
        // Assert: Workspace switched successfully
        std.debug.assert(self.root != null);
    }
    
    /// Get all panes in current workspace (for rendering).
    pub fn get_panes(self: *Layout, panes: *std.ArrayList(*Pane)) !void {
        // Assert: Must have root
        std.debug.assert(self.root != null);
        
        // Clear existing panes
        panes.clearRetainingCapacity();
        
        // Traverse tree and collect all panes (iterative)
        var stack: [MAX_PANES]?*Pane = undefined;
        var stack_len: u32 = 0;
        
        stack[stack_len] = self.root;
        stack_len += 1;
        
        while (stack_len > 0) {
            // Assert: Stack depth within bounds
            std.debug.assert(stack_len <= MAX_PANES);
            
            stack_len -= 1;
            const current = stack[stack_len].?;
            
            // Add to list
            try panes.append(current);
            
            // Add children to stack
            if (current.left) |left| {
                // Assert: Stack has room
                std.debug.assert(stack_len < MAX_PANES);
                stack[stack_len] = left;
                stack_len += 1;
            }
            if (current.right) |right| {
                // Assert: Stack has room
                std.debug.assert(stack_len < MAX_PANES);
                stack[stack_len] = right;
                stack_len += 1;
            }
        }
        
        // Assert: Panes collected successfully
        std.debug.assert(panes.items.len <= MAX_PANES);
    }
    
    /// Resize layout to new dimensions (recalculate all pane
rectangles).
    pub fn resize(self: *Layout, width: u32, height: u32) !void {
        // Assert: Dimensions must be valid
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        std.debug.assert(width <= 16384); // Bounded width
        std.debug.assert(height <= 16384); // Bounded height
        
        if (self.root == null) return;
        
        // Resize root pane
        self.root.?.rect.width = width;
        self.root.?.rect.height = height;
        
        // Recursively resize children (iterative)
        var stack: [MAX_PANES]?*Pane = undefined;
        var stack_len: u32 = 0;
        
        stack[stack_len] = self.root;
        stack_len += 1;
        
        while (stack_len > 0) {
            // Assert: Stack depth within bounds
            std.debug.assert(stack_len <= MAX_PANES);
            
            stack_len -= 1;
            const current = stack[stack_len].?;
            
            // Resize children based on split direction
            if (current.left) |left| {
                if (current.right) |right| {
                    // Both children: determine split direction
                    if (left.rect.x == current.rect.x) {
                        // Vertical split (top/bottom)
                        const left_height = current.rect.height / 2;
                        const right_height = current.rect.height -
left_height;
                        
                        left.rect = Rectangle{
                            .x = current.rect.x,
                            .y = current.rect.y,
                            .width = current.rect.width,
                            .height = left_height,
                        };
                        
                        right.rect = Rectangle{
                            .x = current.rect.x,
                            .y = current.rect.y + @intCast(left_height),
                            .width = current.rect.width,
                            .height = right_height,
                        };
                    } else {
                        // Horizontal split (left/right)
                        const left_width = current.rect.width / 2;
                        const right_width = current.rect.width -
left_width;
                        
                        left.rect = Rectangle{
                            .x = current.rect.x,
                            .y = current.rect.y,
                            .width = left_width,
                            .height = current.rect.height,
                        };
                        
                        right.rect = Rectangle{
                            .x = current.rect.x + @intCast(left_width),
                            .y = current.rect.y,
                            .width = right_width,
                            .height = current.rect.height,
                        };
                    }
                    
                    // Add children to stack
                    // Assert: Stack has room
                    std.debug.assert(stack_len + 2 <= MAX_PANES);
                    stack[stack_len] = left;
                    stack_len += 1;
                    stack[stack_len] = right;
                    stack_len += 1;
                } else {
                    // Only left child: fill parent
                    left.rect = current.rect;
                    // Assert: Stack has room
                    std.debug.assert(stack_len < MAX_PANES);
                    stack[stack_len] = left;
                    stack_len += 1;
                }
            } else if (current.right) |right| {
                // Only right child: fill parent
                right.rect = current.rect;
                // Assert: Stack has room
                std.debug.assert(stack_len < MAX_PANES);
                stack[stack_len] = right;
                stack_len += 1;
            }
        }
    }
};

test "layout create workspace" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var layout = Layout.init(arena.allocator());
    defer layout.deinit();
    
    const workspace_id = try layout.create_workspace("main", 1920, 1080);
    
    // Assert: Workspace created
    std.debug.assert(workspace_id == 0);
    std.debug.assert(layout.root != null);
    std.debug.assert(layout.root.?.pane_type == .editor);
    std.debug.assert(layout.root.?.focused == true);
}

test "layout split pane" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var layout = Layout.init(arena.allocator());
    defer layout.deinit();
    
    _ = try layout.create_workspace("main", 1920, 1080);
    try layout.split_pane(.horizontal, .terminal);
    
    // Assert: Split successful
    std.debug.assert(layout.pane_count == 2);
    std.debug.assert(layout.root.?.left != null);
    std.debug.assert(layout.root.?.left.?.pane_type == .terminal);
    std.debug.assert(layout.root.?.left.?.focused == true);
}

test "layout focus next" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var layout = Layout.init(arena.allocator());
    defer layout.deinit();
    
    _ = try layout.create_workspace("main", 1920, 1080);
    try layout.split_pane(.horizontal, .terminal);
    
    // Focus should be on terminal
    std.debug.assert(layout.root.?.left.?.focused == true);
    
    // Focus next should go back to editor
    layout.focus_next();
    
    // Assert: Focus moved
    std.debug.assert(layout.root.?.focused == true);
    std.debug.assert(layout.root.?.left.?.focused == false);
}


// === aurora_live_preview.zig ===

const std = @import("std");
const Editor = @import("aurora_editor.zig").Editor;
const EditorDagIntegration =
@import("aurora_dag_integration.zig").EditorDagIntegration;
const BrowserDagIntegration =
@import("dream_browser_dag_integration.zig").BrowserDagIntegration;
const DagCore = @import("dag_core.zig").DagCore;
const DreamBrowserParser =
@import("dream_browser_parser.zig").DreamBrowserParser;
const DreamBrowserRenderer =
@import("dream_browser_renderer.zig").DreamBrowserRenderer;
const GrainBuffer = @import("grain_buffer.zig").GrainBuffer;
const GrainAurora = @import("grain_aurora.zig").GrainAurora;

/// Live Preview: Real-time bidirectional sync between editor and
browser.
/// ~<~ Glow Airbend: explicit sync state, bounded updates.
/// ~~~~ Glow Waterbend: edits flow through DAG deterministically.
pub const LivePreview = struct {
    // Bounded: Max 100 sync subscriptions
    pub const MAX_SYNC_SUBSCRIPTIONS: u32 = 100;
    
    // Bounded: Max 1,000 pending updates per second
    pub const MAX_UPDATES_PER_SECOND: u32 = 1_000;
    
    pub const SyncSubscription = struct {
        editor_tab_id: u32,
        browser_tab_id: u32,
        sync_direction: SyncDirection,
        enabled: bool = true,
    };
    
    pub const SyncDirection = enum {
        editor_to_browser, // Editor edits → Browser preview
        browser_to_editor, // Browser updates → Editor sync
        bidirectional, // Both directions
    };
    
    pub const Update = struct {
        source: UpdateSource,
        source_id: u32, // Editor tab ID or browser tab ID
        target_id: u32, // Target tab ID
        data: []const u8,
        timestamp: u64,
    };
    
    pub const UpdateSource = enum {
        editor_edit, // Code edit in editor
        nostr_event, // Nostr event in browser
        browser_content, // Browser content update
    };
    
    allocator: std.mem.Allocator,
    dag: DagCore,
    editor_dag: EditorDagIntegration,
    browser_dag: BrowserDagIntegration,
    sync_subscriptions: std.ArrayList(SyncSubscription) = undefined,
    pending_updates: std.ArrayList(Update) = undefined,
    
    pub fn init(allocator: std.mem.Allocator) !LivePreview {
        const dag = try DagCore.init(allocator);
        errdefer dag.deinit();
        
        const editor_dag = try EditorDagIntegration.init(allocator);
        errdefer editor_dag.deinit();
        
        const browser_dag = BrowserDagIntegration.init(allocator, &dag);
        
        return LivePreview{
            .allocator = allocator,
            .dag = dag,
            .editor_dag = editor_dag,
            .browser_dag = browser_dag,
            .sync_subscriptions =
std.ArrayList(SyncSubscription).init(allocator),
            .pending_updates = std.ArrayList(Update).init(allocator),
        };
    }
    
    pub fn deinit(self: *LivePreview) void {
        // Free pending updates
        for (self.pending_updates.items) |*update| {
            self.allocator.free(update.data);
        }
        self.pending_updates.deinit();
        
        self.sync_subscriptions.deinit();
        self.browser_dag.deinit();
        self.editor_dag.deinit();
        self.dag.deinit();
        self.* = undefined;
    }
    
    /// Subscribe editor tab to browser tab for live preview.
    pub fn subscribe(
        self: *LivePreview,
        editor_tab_id: u32,
        browser_tab_id: u32,
        direction: SyncDirection,
    ) !void {
        // Assert: Tab IDs must be valid
        std.debug.assert(editor_tab_id < 100); // Bounded editor tabs
        std.debug.assert(browser_tab_id < 100); // Bounded browser tabs
        
        // Assert: Bounded subscriptions
        std.debug.assert(self.sync_subscriptions.items.len <
MAX_SYNC_SUBSCRIPTIONS);
        
        try self.sync_subscriptions.append(SyncSubscription{
            .editor_tab_id = editor_tab_id,
            .browser_tab_id = browser_tab_id,
            .sync_direction = direction,
            .enabled = true,
        });
        
        // Assert: Subscription added successfully
        std.debug.assert(self.sync_subscriptions.items.len <=
MAX_SYNC_SUBSCRIPTIONS);
    }
    
    /// Handle editor edit and propagate to browser preview.
    pub fn handle_editor_edit(
        self: *LivePreview,
        editor_tab_id: u32,
        file_uri: []const u8,
        old_text: []const u8,
        new_text: []const u8,
        edit_type: EditorDagIntegration.EditType,
    ) !void {
        // Assert: Editor tab ID and text must be valid
        std.debug.assert(editor_tab_id < 100); // Bounded editor tabs
        std.debug.assert(file_uri.len > 0);
        std.debug.assert(file_uri.len <= 4096); // Bounded URI length
        std.debug.assert(old_text.len <= 100 * 1024 * 1024); // Bounded
text size
        std.debug.assert(new_text.len <= 100 * 1024 * 1024); // Bounded
text size
        
        // Find subscriptions for this editor tab
        for (self.sync_subscriptions.items) |*sub| {
            if (sub.editor_tab_id == editor_tab_id and sub.enabled) {
                // Check sync direction
                if (sub.sync_direction == .editor_to_browser or 
                    sub.sync_direction == .bidirectional)
                {
                    // Map code edit to DAG event
                    const node_id = try
self.find_or_create_editor_node(file_uri);
                    const parent_events = try
self.get_latest_parent_events();
                    
                    const event_id = try
self.editor_dag.mapCodeEditToDag(
                        node_id,
                        edit_type,
                        old_text,
                        new_text,
                        parent_events,
                    );
                    
                    // Queue update for browser preview
                    try self.queue_browser_update(
                        sub.browser_tab_id,
                        new_text,
                        event_id,
                    );
                }
            }
        }
    }
    
    /// Handle Nostr event update and propagate to editor sync.
    pub fn handle_nostr_event(
        self: *LivePreview,
        browser_tab_id: u32,
        event_content: []const u8,
        event_id: []const u8,
    ) !void {
        // Assert: Browser tab ID and content must be valid
        std.debug.assert(browser_tab_id < 100); // Bounded browser tabs
        std.debug.assert(event_content.len > 0);
        std.debug.assert(event_content.len <= 10 * 1024 * 1024); //
Bounded content size (10MB)
        std.debug.assert(event_id.len > 0);
        std.debug.assert(event_id.len <= 64); // Bounded event ID length
        
        // Find subscriptions for this browser tab
        for (self.sync_subscriptions.items) |*sub| {
            if (sub.browser_tab_id == browser_tab_id and sub.enabled) {
                // Check sync direction
                if (sub.sync_direction == .browser_to_editor or 
                    sub.sync_direction == .bidirectional)
                {
                    // Map Nostr event to DAG event
                    const node_id = try
self.find_or_create_browser_node(event_id);
                    const parent_events = try
self.get_latest_parent_events();
                    
                    const web_event_id = try
self.browser_dag.mapWebRequestToDag(
                        node_id,
                        "nostr",
                        "GET",
                        &.{},
                        event_content,
                        parent_events,
                    );
                    
                    // Queue update for editor sync
                    try self.queue_editor_update(
                        sub.editor_tab_id,
                        event_content,
                        web_event_id,
                    );
                }
            }
        }
    }
    
    /// Process pending updates (streaming, Hyperfiddle-style).
    /// Takes optional editor and browser renderer instances for actual
updates.
    pub fn process_updates(
        self: *LivePreview,
        editor_instances: ?[]const EditorInstance,
        browser_renderers: ?[]const BrowserRendererInstance,
    ) !void {
        // Assert: Updates must be within bounds
        std.debug.assert(self.pending_updates.items.len <=
MAX_UPDATES_PER_SECOND);
        
        // Process updates in order (deterministic)
        for (self.pending_updates.items) |*update| {
            // Apply update based on source
            switch (update.source) {
                .editor_edit => {
                    // Editor edit → Browser preview
                    // Find browser renderer for target tab
                    if (browser_renderers) |renderers| {
                        for (renderers) |renderer_instance| {
                            if (renderer_instance.tab_id ==
update.target_id) {
                                // Parse new content as HTML
                                var parser =
DreamBrowserParser.init(self.allocator);
                                defer parser.deinit();
                                
                                const html_node =
parser.parseHtml(update.data) catch {
                                    // If parsing fails, skip this update
                                    continue;
                                };
                                
                                // Re-render browser with new content
                                renderer_instance.renderer.renderPage(
                                    &html_node,
                                    &.{}, // Empty CSS rules for now
                                    renderer_instance.buffer,
                                ) catch {
                                    // If rendering fails, skip this
update
                                    continue;
                                };
                                break;
                            }
                        }
                    }
                },
                .nostr_event, .browser_content => {
                    // Browser update → Editor sync
                    // Find editor for target tab
                    if (editor_instances) |editors| {
                        for (editors) |editor_instance| {
                            if (editor_instance.tab_id ==
update.target_id) {
                                // Update editor buffer with new content
                                // Replace entire buffer content with
new content
                                const current_text =
editor_instance.editor.buffer.textSlice();
                                
                                // Clear existing buffer and create new
one with updated content
                                editor_instance.editor.buffer.deinit();
                                
                                // Create new buffer with updated content
                                editor_instance.editor.buffer =
GrainBuffer.fromSlice(
                                    editor_instance.editor.allocator,
                                    update.data,
                                ) catch {
                                    // If buffer creation fails, skip
this update
                                    continue;
                                };
                                
                                // Update Aurora rendering
                                editor_instance.editor.aurora.deinit();
                                editor_instance.editor.aurora =
GrainAurora.init(
                                    editor_instance.editor.allocator,
                                    update.data,
                                ) catch {
                                    // If Aurora init fails, skip this
update
                                    continue;
                                };
                                break;
                            }
                        }
                    }
                },
            }
        }
        
        // Clear pending updates after processing
        for (self.pending_updates.items) |*update| {
            self.allocator.free(update.data);
        }
        self.pending_updates.clearRetainingCapacity();
        
        // Process DAG events (TigerBeetle-style state machine)
        try self.editor_dag.processEvents();
        try self.browser_dag.processEvents();
        
        // Assert: Updates processed successfully
        std.debug.assert(self.pending_updates.items.len == 0);
    }
    
    /// Editor instance (for update processing).
    pub const EditorInstance = struct {
        tab_id: u32,
        editor: *Editor,
    };
    
    /// Browser renderer instance (for update processing).
    pub const BrowserRendererInstance = struct {
        tab_id: u32,
        renderer: *DreamBrowserRenderer,
        buffer: *GrainBuffer,
    };
    
    /// Find or create editor node in DAG for file URI.
    fn find_or_create_editor_node(self: *LivePreview, file_uri: []const
u8) !u32 {
        // Assert: File URI must be valid
        std.debug.assert(file_uri.len > 0);
        std.debug.assert(file_uri.len <= 4096); // Bounded URI length
        
        // Search for existing node with this file URI
        for (0..self.dag.nodes_len) |i| {
            const node = &self.dag.nodes[i];
            if (node.node_type == .ast_node) {
                // Check if node data contains file URI
                if (std.mem.indexOf(u8, node.data[0..node.data_len],
file_uri)) |_| {
                    return @intCast(i);
                }
            }
        }
        
        // Create new node for file
        const node_data = try std.fmt.allocPrint(
            self.allocator,
            "file:{s}",
            .{file_uri},
        );
        defer self.allocator.free(node_data);
        
        const node_id = try self.dag.addNode(
            .ast_node,
            node_data,
            .{},
        );
        
        // Assert: Node created successfully
        std.debug.assert(node_id < DagCore.MAX_NODES);
        
        return node_id;
    }
    
    /// Find or create browser node in DAG for event ID.
    fn find_or_create_browser_node(self: *LivePreview, event_id: []const
u8) !u32 {
        // Assert: Event ID must be valid
        std.debug.assert(event_id.len > 0);
        std.debug.assert(event_id.len <= 64); // Bounded event ID length
        
        // Search for existing node with this event ID
        for (0..self.dag.nodes_len) |i| {
            const node = &self.dag.nodes[i];
            if (node.node_type == .dom_node) {
                // Check if node data contains event ID
                if (std.mem.indexOf(u8, node.data[0..node.data_len],
event_id)) |_| {
                    return @intCast(i);
                }
            }
        }
        
        // Create new node for event
        const node_data = try std.fmt.allocPrint(
            self.allocator,
            "nostr:{s}",
            .{event_id},
        );
        defer self.allocator.free(node_data);
        
        const node_id = try self.dag.addNode(
            .dom_node,
            node_data,
            .{},
        );
        
        // Assert: Node created successfully
        std.debug.assert(node_id < DagCore.MAX_NODES);
        
        return node_id;
    }
    
    /// Get latest parent events for HashDAG-style ordering.
    fn get_latest_parent_events(self: *LivePreview) ![]const u64 {
        // Get latest events from DAG (for parent references)
        // Bounded: Max 10 parent events
        const max_parents: u32 = 10;
        var parents = std.ArrayList(u64).init(self.allocator);
        errdefer parents.deinit();
        
        // Get latest events (simplified: get from pending events)
        const count = @min(self.dag.pending_events_len, max_parents);
        for (0..count) |i| {
            const event = self.dag.pending_events[i];
            try parents.append(event.id);
        }
        
        return try parents.toOwnedSlice();
    }
    
    /// Queue browser update for processing.
    fn queue_browser_update(
        self: *LivePreview,
        browser_tab_id: u32,
        content: []const u8,
        event_id: u64,
    ) !void {
        // Assert: Browser tab ID and content must be valid
        std.debug.assert(browser_tab_id < 100); // Bounded browser tabs
        std.debug.assert(content.len > 0);
        std.debug.assert(content.len <= 10 * 1024 * 1024); // Bounded
content size
        
        // Assert: Bounded pending updates
        std.debug.assert(self.pending_updates.items.len <
MAX_UPDATES_PER_SECOND);
        
        const content_copy = try self.allocator.dupe(u8, content);
        errdefer self.allocator.free(content_copy);
        
        const timestamp = std.time.timestamp();
        // Assert: Timestamp must be non-negative (cast to u64)
        std.debug.assert(timestamp >= 0);
        const timestamp_u64 = @intCast(timestamp);
        
        try self.pending_updates.append(Update{
            .source = .editor_edit,
            .source_id = browser_tab_id, // Source is editor, target is
browser
            .target_id = browser_tab_id,
            .data = content_copy,
            .timestamp = timestamp_u64,
        });
        
        // Assert: Update queued successfully
        std.debug.assert(self.pending_updates.items.len <=
MAX_UPDATES_PER_SECOND);
    }
    
    /// Queue editor update for processing.
    fn queue_editor_update(
        self: *LivePreview,
        editor_tab_id: u32,
        content: []const u8,
        event_id: u64,
    ) !void {
        // Assert: Editor tab ID and content must be valid
        std.debug.assert(editor_tab_id < 100); // Bounded editor tabs
        std.debug.assert(content.len > 0);
        std.debug.assert(content.len <= 10 * 1024 * 1024); // Bounded
content size
        
        // Assert: Bounded pending updates
        std.debug.assert(self.pending_updates.items.len <
MAX_UPDATES_PER_SECOND);
        
        const content_copy = try self.allocator.dupe(u8, content);
        errdefer self.allocator.free(content_copy);
        
        const timestamp = std.time.timestamp();
        // Handle negative timestamps (shouldn't happen, but handle
gracefully)
        const timestamp_u64 = if (timestamp < 0)
            @as(u64, 0)
        else
            @as(u64, @intCast(timestamp));
        
        try self.pending_updates.append(Update{
            .source = .nostr_event,
            .source_id = editor_tab_id, // Source is browser, target is
editor
            .target_id = editor_tab_id,
            .data = content_copy,
            .timestamp = timestamp_u64,
        });
        
        // Assert: Update queued successfully
        std.debug.assert(self.pending_updates.items.len <=
MAX_UPDATES_PER_SECOND);
    }
    
    /// Enable or disable sync subscription.
    pub fn set_sync_enabled(self: *LivePreview, subscription_idx: u32,
enabled: bool) void {
        // Assert: Subscription index must be valid
        std.debug.assert(subscription_idx <
self.sync_subscriptions.items.len);
        
        self.sync_subscriptions.items[subscription_idx].enabled =
enabled;
    }
    
    /// Get sync subscription by editor and browser tab IDs.
    pub fn get_subscription(
        self: *LivePreview,
        editor_tab_id: u32,
        browser_tab_id: u32,
    ) ?*SyncSubscription {
        // Assert: Tab IDs must be valid
        std.debug.assert(editor_tab_id < 100); // Bounded editor tabs
        std.debug.assert(browser_tab_id < 100); // Bounded browser tabs
        
        for (self.sync_subscriptions.items) |*sub| {
            if (sub.editor_tab_id == editor_tab_id and 
                sub.browser_tab_id == browser_tab_id)
            {
                return sub;
            }
        }
        
        return null;
    }
};

test "live preview lifecycle" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var preview = try LivePreview.init(arena.allocator());
    defer preview.deinit();
    
    // Assert: Preview initialized
    std.debug.assert(preview.sync_subscriptions.items.len == 0);
    std.debug.assert(preview.pending_updates.items.len == 0);
}

test "live preview subscribe" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var preview = try LivePreview.init(arena.allocator());
    defer preview.deinit();
    
    try preview.subscribe(0, 0, .bidirectional);
    
    // Assert: Subscription created
    std.debug.assert(preview.sync_subscriptions.items.len == 1);
    std.debug.assert(preview.sync_subscriptions.items[0].enabled ==
true);
}


// === aurora_lsp.zig ===

const std = @import("std");
const GrainBuffer = @import("grain_buffer.zig").GrainBuffer;

// Cancellation support: track pending requests
// Bounded: Max 100 pending requests
pub const MAX_PENDING_REQUESTS: u32 = 100;

/// LSP client for Aurora IDE: communicates with ZLS (Zig Language
Server) via JSON-RPC 2.0.
/// ~<~ Glow Airbend: static allocation for message buffers; process
lifecycle explicit.
/// ~~~~ Glow Waterbend: snapshot model tracks incremental document
changes (Matklad-style).
pub const LspClient = struct {
    // Snapshot model: track document versions incrementally
(Matklad-style)
    // Bounded: Max 1000 document snapshots
    pub const MAX_SNAPSHOTS: u32 = 1000;
    
    // Diagnostics storage: track diagnostics per document
    // Bounded: Max 1000 diagnostics per document
    pub const MAX_DIAGNOSTICS_PER_DOCUMENT: u32 = 1000;
    
    allocator: std.mem.Allocator,
    server_process: ?std.process.Child = null,
    request_id: u64 = 1,
    message_buffer: [8192]u8 = undefined,
    snapshots: std.ArrayListUnmanaged(DocumentSnapshot) = .{},
    current_snapshot_id: u64 = 0,
    pending_requests: std.AutoHashMap(u64, void) = undefined,
    diagnostics: std.StringHashMap(std.ArrayListUnmanaged(Diagnostic)) =
undefined,

    pub const Message = struct {
        jsonrpc: []const u8 = "2.0",
        id: ?u64 = null,
        method: ?[]const u8 = null,
        params: ?std.json.Value = null,
        result: ?std.json.Value = null,
        lsp_error: ?LspError = null,
    };

    pub const LspError = struct {
        code: i32,
        message: []const u8,
        data: ?std.json.Value = null,
    };

    pub const CompletionItem = struct {
        label: []const u8,
        kind: ?u32 = null,
        detail: ?[]const u8 = null,
        documentation: ?[]const u8 = null,
    };
    
    pub const HoverResult = struct {
        contents: []const u8, // Hover content (markdown or plain text)
        range: ?Range = null, // Optional range for hover
    };
    
    /// Location result for go-to-definition (file URI and range).
    pub const Location = struct {
        uri: []const u8, // File URI where definition is located
        range: Range, // Range of the definition
    };

    pub const Diagnostic = struct {
        range: Range,
        severity: ?u32 = null,
        message: []const u8,
        source: ?[]const u8 = null,
    };

    pub const Range = struct {
        start: Position,
        end: Position,
    };

    pub const Position = struct {
        line: u32,
        character: u32,
    };
    
    /// Document snapshot: incremental change tracking (Matklad-style).
    /// Tracks document version, URI, and text content.
    pub const DocumentSnapshot = struct {
        id: u64,
        uri: []const u8,
        version: u64,
        text: []const u8,
    };
    
    /// Text document change: incremental edit (LSP
textDocument/didChange).
    pub const TextDocumentChange = struct {
        range: ?Range = null, // null = full document replacement
        range_length: ?u32 = null,
        text: []const u8,
    };

    pub fn init(allocator: std.mem.Allocator) LspClient {
        return LspClient{
            .allocator = allocator,
            .snapshots = .{},
            .pending_requests = std.AutoHashMap(u64,
void).init(allocator),
            .diagnostics =
std.StringHashMap(std.ArrayListUnmanaged(Diagnostic)).init(allocator),
        };
    }

    pub fn deinit(self: *LspClient) void {
        // Free snapshot URIs and text
        for (self.snapshots.items) |*snapshot| {
            self.allocator.free(snapshot.uri);
            self.allocator.free(snapshot.text);
        }
        self.snapshots.deinit(self.allocator);
        
        // Free diagnostics
        var diagnostics_it = self.diagnostics.iterator();
        while (diagnostics_it.next()) |entry| {
            // Free diagnostic messages and sources
            for (entry.value_ptr.items) |*diag| {
                self.allocator.free(diag.message);
                if (diag.source) |source| {
                    self.allocator.free(source);
                }
            }
            entry.value_ptr.deinit(self.allocator);
            // Free URI key (StringHashMap owns keys, but we allocated
them)
            self.allocator.free(entry.key_ptr.*);
        }
        self.diagnostics.deinit();
        
        self.pending_requests.deinit();
        
        if (self.server_process) |*proc| {
            _ = proc.kill() catch {};
            _ = proc.wait() catch {};
        }
        self.* = undefined;
    }

    /// Spawn ZLS process: expects `zls` in PATH or use explicit path.
    pub fn startServer(self: *LspClient, zls_path: []const u8) !void {
        if (self.server_process != null) return;

        const argv = [_][]const u8{ zls_path };
        var child = std.process.Child.init(&argv, self.allocator);
        child.stdin_behavior = .Pipe;
        child.stdout_behavior = .Pipe;
        child.stderr_behavior = .Pipe;
        try child.spawn();
        self.server_process = child;
    }

    /// Send initialize request to LSP server.
    pub fn initialize(self: *LspClient, root_uri: []const u8) !void {
        // Assert: Root URI must be non-empty
        std.debug.assert(root_uri.len > 0);
        std.debug.assert(root_uri.len <= 4096); // Bounded URI length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        try params_obj.put("rootUri", std.json.Value{ .string = root_uri
});
        
        const capabilities_obj = std.json.ObjectMap.init(self.allocator);
        try params_obj.put("capabilities", std.json.Value{ .object =
capabilities_obj });
        
        const params = std.json.Value{ .object = params_obj };
        _ = try self.sendRequest("initialize", params);
    }

    /// Request textDocument/completion at a position.
    pub fn requestCompletion(
        self: *LspClient,
        uri: []const u8,
        line: u32,
        character: u32,
    ) !?[]CompletionItem {
        // Assert: URI and position must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        var position_obj = std.json.ObjectMap.init(self.allocator);
        defer position_obj.deinit();
        try position_obj.put("line", std.json.Value{ .integer =
@intCast(line) });
        try position_obj.put("character", std.json.Value{ .integer =
@intCast(character) });
        try params_obj.put("position", std.json.Value{ .object =
position_obj });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try self.sendRequest("textDocument/completion",
params);
        
        // Parse completion items from response.result
        if (response.result) |result| {
            if (result == .array) {
                const items = result.array.items;
                var completions = try
self.allocator.alloc(CompletionItem, items.len);
                for (items, 0..) |item, i| {
                    if (item == .object) {
                        const obj = item.object;
                        completions[i] = CompletionItem{
                            .label = if (obj.get("label")) |l| l.string
else "",
                            .kind = if (obj.get("kind")) |k|
@intCast(k.integer) else null,
                            .detail = if (obj.get("detail")) |d|
d.string else null,
                            .documentation = if
(obj.get("documentation")) |doc| doc.string else null,
                        };
                    }
                }
                return completions;
            }
        }
        return null;
    }
    
    /// Request completionItem/resolve (get additional details for
completion item).
    /// Why: Get full documentation and details for a completion item
after selection.
    /// Contract: completion_item must be valid (must have label at
minimum).
    /// Returns: Resolved completion item with full details, or null if
not available.
    pub fn resolveCompletionItem(
        self: *LspClient,
        completion_item: CompletionItem,
    ) !?CompletionItem {
        // Assert: Completion item must have label
        std.debug.assert(completion_item.label.len > 0);
        std.debug.assert(completion_item.label.len <= 1024); // Bounded
label length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        // Build completion item object
        var item_obj = std.json.ObjectMap.init(self.allocator);
        try item_obj.put("label", std.json.Value{ .string =
completion_item.label });
        
        if (completion_item.kind) |kind| {
            try item_obj.put("kind", std.json.Value{ .integer =
@intCast(kind) });
        }
        if (completion_item.detail) |detail| {
            try item_obj.put("detail", std.json.Value{ .string = detail
});
        }
        if (completion_item.documentation) |doc| {
            try item_obj.put("documentation", std.json.Value{ .string =
doc });
        }
        
        try params_obj.put("item", std.json.Value{ .object = item_obj });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try self.sendRequest("completionItem/resolve",
params);
        
        // Parse resolved completion item from response.result
        if (response.result) |result| {
            if (result == .object) {
                const obj = result.object;
                
                // Parse label (required)
                const label_val = obj.get("label") orelse return null;
                if (label_val != .string) return null;
                const label_str = label_val.string;
                
                const label_copy = try self.allocator.dupe(u8,
label_str);
                errdefer self.allocator.free(label_copy);
                
                // Parse kind (optional)
                const kind: ?u32 = if (obj.get("kind")) |k|
                    if (k == .integer) @as(u32, @intCast(k.integer))
else null
                else
                    null;
                
                // Parse detail (optional)
                var detail: ?[]const u8 = null;
                if (obj.get("detail")) |detail_val| {
                    if (detail_val == .string) {
                        const detail_str = detail_val.string;
                        const detail_copy = try self.allocator.dupe(u8,
detail_str);
                        errdefer self.allocator.free(detail_copy);
                        detail = detail_copy;
                    }
                }
                
                // Parse documentation (optional)
                var documentation: ?[]const u8 = null;
                if (obj.get("documentation")) |doc_val| {
                    if (doc_val == .string) {
                        const doc_str = doc_val.string;
                        const doc_copy = try self.allocator.dupe(u8,
doc_str);
                        errdefer self.allocator.free(doc_copy);
                        documentation = doc_copy;
                    } else if (doc_val == .object) {
                        // Documentation can be MarkupContent (object
with kind and value)
                        if (doc_val.object.get("value")) |value| {
                            if (value == .string) {
                                const doc_str = value.string;
                                const doc_copy = try
self.allocator.dupe(u8, doc_str);
                                errdefer self.allocator.free(doc_copy);
                                documentation = doc_copy;
                            }
                        }
                    }
                }
                
                return CompletionItem{
                    .label = label_copy,
                    .kind = kind,
                    .detail = detail,
                    .documentation = documentation,
                };
            }
        }
        return null;
    }
    
    /// Request textDocument/signatureHelp (get function signature at
position).
    /// Why: Show function signatures and parameter hints as user types.
    /// Contract: uri, line, and character must be valid.
    /// Returns: Signature help information, or null if not available.
    pub fn requestSignatureHelp(
        self: *LspClient,
        uri: []const u8,
        line: u32,
        character: u32,
    ) !?SignatureHelp {
        // Assert: URI and position must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        var position_obj = std.json.ObjectMap.init(self.allocator);
        defer position_obj.deinit();
        try position_obj.put("line", std.json.Value{ .integer =
@intCast(line) });
        try position_obj.put("character", std.json.Value{ .integer =
@intCast(character) });
        try params_obj.put("position", std.json.Value{ .object =
position_obj });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try
self.sendRequest("textDocument/signatureHelp", params);
        
        // Parse signature help from response.result
        if (response.result) |result| {
            if (result == .object) {
                const obj = result.object;
                
                // Parse signatures array
                const signatures_val = obj.get("signatures") orelse
return null;
                if (signatures_val != .array) return null;
                
                var signatures =
std.ArrayList(SignatureInformation).init(self.allocator);
                errdefer {
                    // Free any allocated strings on error
                    for (signatures.items) |*sig| {
                        self.allocator.free(sig.label);
                        if (sig.documentation) |doc| {
                            self.allocator.free(doc);
                        }
                        if (sig.parameters) |params_list| {
                            for (params_list.items) |*param| {
                                self.allocator.free(param.label);
                                if (param.documentation) |doc| {
                                    self.allocator.free(doc);
                                }
                            }
                            params_list.deinit(self.allocator);
                            self.allocator.free(params_list.items);
                        }
                    }
                    signatures.deinit();
                }
                
                for (signatures_val.array.items) |sig_item| {
                    if (sig_item == .object) {
                        const sig_obj = sig_item.object;
                        
                        // Parse label
                        const label_val = sig_obj.get("label") orelse
continue;
                        if (label_val != .string) continue;
                        const label_str = label_val.string;
                        
                        const label_copy = try self.allocator.dupe(u8,
label_str);
                        errdefer self.allocator.free(label_copy);
                        
                        // Parse documentation (optional)
                        var documentation: ?[]const u8 = null;
                        if (sig_obj.get("documentation")) |doc_val| {
                            if (doc_val == .string) {
                                const doc_str = doc_val.string;
                                const doc_copy = try
self.allocator.dupe(u8, doc_str);
                                errdefer self.allocator.free(doc_copy);
                                documentation = doc_copy;
                            }
                        }
                        
                        // Parse parameters (optional)
                        var parameters:
?std.ArrayList(ParameterInformation) = null;
                        if (sig_obj.get("parameters")) |params_val| {
                            if (params_val == .array) {
                                parameters =
std.ArrayList(ParameterInformation).init(self.allocator);
                                errdefer {
                                    if (parameters) |*params_list| {
                                        for (params_list.items) |*param|
{
                                           
self.allocator.free(param.label);
                                            if (param.documentation)
|doc| {
                                                self.allocator.free(doc);
                                            }
                                        }
                                        params_list.deinit();
                                    }
                                }
                                
                                for (params_val.array.items)
|param_item| {
                                    if (param_item == .object) {
                                        const param_obj =
param_item.object;
                                        
                                        // Parse label
                                        const param_label_val =
param_obj.get("label") orelse continue;
                                        if (param_label_val != .string)
continue;
                                        const param_label_str =
param_label_val.string;
                                        
                                        const param_label_copy = try
self.allocator.dupe(u8, param_label_str);
                                        errdefer
self.allocator.free(param_label_copy);
                                        
                                        // Parse documentation (optional)
                                        var param_doc: ?[]const u8 =
null;
                                        if
(param_obj.get("documentation")) |doc_val| {
                                            if (doc_val == .string) {
                                                const param_doc_str =
doc_val.string;
                                                const param_doc_copy =
try self.allocator.dupe(u8, param_doc_str);
                                                errdefer
self.allocator.free(param_doc_copy);
                                                param_doc =
param_doc_copy;
                                            }
                                        }
                                        
                                        try
parameters.?.append(ParameterInformation{
                                            .label = param_label_copy,
                                            .documentation = param_doc,
                                        });
                                    }
                                }
                            }
                        }
                        
                        try signatures.append(SignatureInformation{
                            .label = label_copy,
                            .documentation = documentation,
                            .parameters = parameters,
                        });
                    }
                }
                
                // Parse activeSignature (optional)
                const active_sig: ?u32 = if (obj.get("activeSignature"))
|as|
                    if (as == .integer) @as(u32, @intCast(as.integer))
else null
                else
                    null;
                
                // Parse activeParameter (optional)
                const active_param: ?u32 = if
(obj.get("activeParameter")) |ap|
                    if (ap == .integer) @as(u32, @intCast(ap.integer))
else null
                else
                    null;
                
                const signatures_slice = try signatures.toOwnedSlice();
                return SignatureHelp{
                    .signatures =
std.ArrayList(SignatureInformation).fromOwnedSlice(self.allocator,
signatures_slice),
                    .active_signature = active_sig,
                    .active_parameter = active_param,
                };
            }
        }
        return null;
    }
    
    /// Signature help information from LSP server.
    pub const SignatureHelp = struct {
        signatures: std.ArrayList(SignatureInformation), // Available
signatures
        active_signature: ?u32 = null, // Currently active signature
index
        active_parameter: ?u32 = null, // Currently active parameter
index
    };
    
    /// Signature information (function signature).
    pub const SignatureInformation = struct {
        label: []const u8, // Function signature label
        documentation: ?[]const u8 = null, // Optional documentation
        parameters: ?std.ArrayList(ParameterInformation) = null, //
Optional parameters
    };
    
    /// Parameter information (function parameter).
    pub const ParameterInformation = struct {
        label: []const u8, // Parameter label
        documentation: ?[]const u8 = null, // Optional documentation
    };
    
    /// Request textDocument/hover at a position.
    pub fn requestHover(
        self: *LspClient,
        uri: []const u8,
        line: u32,
        character: u32,
    ) !?HoverResult {
        // Assert: URI and position must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        var position_obj = std.json.ObjectMap.init(self.allocator);
        defer position_obj.deinit();
        try position_obj.put("line", std.json.Value{ .integer =
@intCast(line) });
        try position_obj.put("character", std.json.Value{ .integer =
@intCast(character) });
        try params_obj.put("position", std.json.Value{ .object =
position_obj });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try self.sendRequest("textDocument/hover",
params);
        
        // Parse hover result from response.result
        if (response.result) |result| {
            if (result == .object) {
                const obj = result.object;
                var contents: []const u8 = "";
                var hover_range: ?Range = null;
                
                // Parse contents (can be string or object with value)
                if (obj.get("contents")) |contents_val| {
                    if (contents_val == .string) {
                        contents = contents_val.string;
                    } else if (contents_val == .object) {
                        if (contents_val.object.get("value")) |value| {
                            if (value == .string) {
                                contents = value.string;
                            }
                        }
                    }
                }
                
                // Parse range (optional)
                if (obj.get("range")) |range_val| {
                    if (range_val == .object) {
                        const range_obj = range_val.object;
                        if (range_obj.get("start")) |start_val| {
                            if (start_val == .object) {
                                const start_obj = start_val.object;
                                const start_line = if
(start_obj.get("line")) |l| @as(u32, @intCast(l.integer)) else 0;
                                const start_char = if
(start_obj.get("character")) |c| @as(u32, @intCast(c.integer)) else 0;
                                
                                if (range_obj.get("end")) |end_val| {
                                    if (end_val == .object) {
                                        const end_obj = end_val.object;
                                        const end_line = if
(end_obj.get("line")) |l| @as(u32, @intCast(l.integer)) else 0;
                                        const end_char = if
(end_obj.get("character")) |c| @as(u32, @intCast(c.integer)) else 0;
                                        
                                        hover_range = Range{
                                            .start = Position{ .line =
start_line, .character = start_char },
                                            .end = Position{ .line =
end_line, .character = end_char },
                                        };
                                    }
                                }
                            }
                        }
                    }
                }
                
                if (contents.len > 0) {
                    // Allocate hover result
                    const contents_copy = try self.allocator.dupe(u8,
contents);
                    return HoverResult{
                        .contents = contents_copy,
                        .range = hover_range,
                    };
                }
            }
        }
        return null;
    }
    
    /// Request textDocument/references at a position (find all
references).
    /// Why: Find all references to a symbol for code navigation and
refactoring.
    /// Contract: uri, line, and character must be valid.
    /// Returns: Array of locations where the symbol is referenced.
    pub fn requestReferences(
        self: *LspClient,
        uri: []const u8,
        line: u32,
        character: u32,
        include_declaration: bool,
    ) !?[]Location {
        // Assert: URI and position must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        var position_obj = std.json.ObjectMap.init(self.allocator);
        defer position_obj.deinit();
        try position_obj.put("line", std.json.Value{ .integer =
@intCast(line) });
        try position_obj.put("character", std.json.Value{ .integer =
@intCast(character) });
        try params_obj.put("position", std.json.Value{ .object =
position_obj });
        
        // Set includeDeclaration in context
        var context_obj = std.json.ObjectMap.init(self.allocator);
        try context_obj.put("includeDeclaration", std.json.Value{ .bool
= include_declaration });
        try params_obj.put("context", std.json.Value{ .object =
context_obj });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try self.sendRequest("textDocument/references",
params);
        
        // Parse locations array from response.result
        if (response.result) |result| {
            if (result == .array) {
                const items = result.array.items;
                var locations =
std.ArrayList(Location).init(self.allocator);
                errdefer {
                    // Free any allocated URIs on error
                    for (locations.items) |*loc| {
                        self.allocator.free(loc.uri);
                    }
                    locations.deinit();
                }
                
                for (items) |item| {
                    if (item == .object) {
                        const obj = item.object;
                        const location_uri = obj.get("uri") orelse
continue;
                        if (location_uri != .string) continue;
                        const uri_str = location_uri.string;
                        
                        const range_val = obj.get("range") orelse
continue;
                        if (range_val != .object) continue;
                        const range_obj = range_val.object;
                        
                        const start_val = range_obj.get("start") orelse
continue;
                        const end_val = range_obj.get("end") orelse
continue;
                        if (start_val != .object or end_val != .object)
continue;
                        
                        const start_obj = start_val.object;
                        const end_obj = end_val.object;
                        
                        const start_line_val = start_obj.get("line")
orelse continue;
                        const start_char_val =
start_obj.get("character") orelse continue;
                        const end_line_val = end_obj.get("line") orelse
continue;
                        const end_char_val = end_obj.get("character")
orelse continue;
                        
                        if (start_line_val != .integer or start_char_val
!= .integer or
                            end_line_val != .integer or end_char_val !=
.integer) continue;
                        
                        const start_line = @as(u32,
@intCast(start_line_val.integer));
                        const start_char = @as(u32,
@intCast(start_char_val.integer));
                        const end_line = @as(u32,
@intCast(end_line_val.integer));
                        const end_char = @as(u32,
@intCast(end_char_val.integer));
                        
                        const uri_copy = try self.allocator.dupe(u8,
uri_str);
                        errdefer self.allocator.free(uri_copy);
                        
                        try locations.append(Location{
                            .uri = uri_copy,
                            .range = Range{
                                .start = Position{ .line = start_line,
.character = start_char },
                                .end = Position{ .line = end_line,
.character = end_char },
                            },
                        });
                    }
                }
                
                return try locations.toOwnedSlice();
            }
        }
        return null;
    }
    
    /// Request textDocument/definition at a position (go-to-definition).
    /// Why: Navigate to symbol definition for code navigation.
    /// Contract: uri, line, and character must be valid.
    pub fn requestDefinition(
        self: *LspClient,
        uri: []const u8,
        line: u32,
        character: u32,
    ) !?Location {
        // Assert: URI and position must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        var position_obj = std.json.ObjectMap.init(self.allocator);
        defer position_obj.deinit();
        try position_obj.put("line", std.json.Value{ .integer =
@intCast(line) });
        try position_obj.put("character", std.json.Value{ .integer =
@intCast(character) });
        try params_obj.put("position", std.json.Value{ .object =
position_obj });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try self.sendRequest("textDocument/definition",
params);
        
        // Parse location from response.result
        // LSP can return either a single Location or an array of
Locations
        if (response.result) |result| {
            if (result == .object) {
                // Single location
                const obj = result.object;
                const location_uri = if (obj.get("uri")) |u| u.string
else return null;
                const range_val = obj.get("range") orelse return null;
                
                if (range_val == .object) {
                    const range_obj = range_val.object;
                    const start_val = range_obj.get("start") orelse
return null;
                    const end_val = range_obj.get("end") orelse return
null;
                    
                    if (start_val == .object and end_val == .object) {
                        const start_obj = start_val.object;
                        const end_obj = end_val.object;
                        
                        const start_line = if (start_obj.get("line"))
|l| @as(u32, @intCast(l.integer)) else return null;
                        const start_char = if
(start_obj.get("character")) |c| @as(u32, @intCast(c.integer)) else
return null;
                        const end_line = if (end_obj.get("line")) |l|
@as(u32, @intCast(l.integer)) else return null;
                        const end_char = if (end_obj.get("character"))
|c| @as(u32, @intCast(c.integer)) else return null;
                        
                        const uri_copy = try self.allocator.dupe(u8,
location_uri);
                        return Location{
                            .uri = uri_copy,
                            .range = Range{
                                .start = Position{ .line = start_line,
.character = start_char },
                                .end = Position{ .line = end_line,
.character = end_char },
                            },
                        };
                    }
                }
            } else if (result == .array) {
                // Array of locations (take first one)
                const items = result.array.items;
                if (items.len > 0) {
                    const first_item = items[0];
                    if (first_item == .object) {
                        const obj = first_item.object;
                        const location_uri = if (obj.get("uri")) |u|
u.string else return null;
                        const range_val = obj.get("range") orelse return
null;
                        
                        if (range_val == .object) {
                            const range_obj = range_val.object;
                            const start_val = range_obj.get("start")
orelse return null;
                            const end_val = range_obj.get("end") orelse
return null;
                            
                            if (start_val == .object and end_val ==
.object) {
                                const start_obj = start_val.object;
                                const end_obj = end_val.object;
                                
                                const start_line = if
(start_obj.get("line")) |l| @as(u32, @intCast(l.integer)) else return
null;
                                const start_char = if
(start_obj.get("character")) |c| @as(u32, @intCast(c.integer)) else
return null;
                                const end_line = if
(end_obj.get("line")) |l| @as(u32, @intCast(l.integer)) else return null;
                                const end_char = if
(end_obj.get("character")) |c| @as(u32, @intCast(c.integer)) else return
null;
                                
                                const uri_copy = try
self.allocator.dupe(u8, location_uri);
                                return Location{
                                    .uri = uri_copy,
                                    .range = Range{
                                        .start = Position{ .line =
start_line, .character = start_char },
                                        .end = Position{ .line =
end_line, .character = end_char },
                                    },
                                };
                            }
                        }
                    }
                }
            }
        }
        return null;
    }
    
