    /// Request textDocument/codeAction (get code actions for
diagnostics/selection).
    /// Why: Get quick fixes, refactorings, and other code actions from
LSP server.
    /// Contract: uri and range must be valid.
    /// Returns: Array of code actions, or null if no actions available.
    pub fn requestCodeActions(
        self: *LspClient,
        uri: []const u8,
        range: Range,
        context: ?CodeActionContext,
    ) !?[]CodeAction {
        // Assert: URI and range must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        // Add range
        var range_param_obj = std.json.ObjectMap.init(self.allocator);
        var start_obj = std.json.ObjectMap.init(self.allocator);
        try start_obj.put("line", std.json.Value{ .integer =
@intCast(range.start.line) });
        try start_obj.put("character", std.json.Value{ .integer =
@intCast(range.start.character) });
        try range_param_obj.put("start", std.json.Value{ .object =
start_obj });
        
        var end_obj = std.json.ObjectMap.init(self.allocator);
        try end_obj.put("line", std.json.Value{ .integer =
@intCast(range.end.line) });
        try end_obj.put("character", std.json.Value{ .integer =
@intCast(range.end.character) });
        try range_param_obj.put("end", std.json.Value{ .object = end_obj
});
        try params_obj.put("range", std.json.Value{ .object =
range_param_obj });
        
        // Add context if provided
        if (context) |ctx| {
            var context_obj = std.json.ObjectMap.init(self.allocator);
            if (ctx.diagnostics.len > 0) {
                var diags_array =
std.ArrayList(std.json.Value).init(self.allocator);
                defer diags_array.deinit(self.allocator);
                
                for (ctx.diagnostics) |diag| {
                    var diag_obj =
std.json.ObjectMap.init(self.allocator);
                    
                    // Add range
                    var diag_range_obj =
std.json.ObjectMap.init(self.allocator);
                    var diag_start_obj =
std.json.ObjectMap.init(self.allocator);
                    try diag_start_obj.put("line", std.json.Value{
.integer = @intCast(diag.range.start.line) });
                    try diag_start_obj.put("character", std.json.Value{
.integer = @intCast(diag.range.start.character) });
                    try diag_range_obj.put("start", std.json.Value{
.object = diag_start_obj });
                    
                    var diag_end_obj =
std.json.ObjectMap.init(self.allocator);
                    try diag_end_obj.put("line", std.json.Value{
.integer = @intCast(diag.range.end.line) });
                    try diag_end_obj.put("character", std.json.Value{
.integer = @intCast(diag.range.end.character) });
                    try diag_range_obj.put("end", std.json.Value{
.object = diag_end_obj });
                    try diag_obj.put("range", std.json.Value{ .object =
diag_range_obj });
                    
                    // Add severity if present
                    if (diag.severity) |sev| {
                        try diag_obj.put("severity", std.json.Value{
.integer = @intCast(sev) });
                    }
                    
                    // Add message
                    try diag_obj.put("message", std.json.Value{ .string
= diag.message });
                    
                    // Add source if present
                    if (diag.source) |src| {
                        try diag_obj.put("source", std.json.Value{
.string = src });
                    }
                    
                    try diags_array.append(self.allocator,
std.json.Value{ .object = diag_obj });
                }
                
                const diags_slice = try
diags_array.toOwnedSlice(self.allocator);
                try context_obj.put("diagnostics", std.json.Value{
.array = .{ .items = diags_slice, .capacity = diags_slice.len,
.allocator = self.allocator } });
            }
            
            // Add onlyRequested if present
            if (ctx.only_requested) |only| {
                try context_obj.put("only", std.json.Value{ .bool = only
});
            }
            
            try params_obj.put("context", std.json.Value{ .object =
context_obj });
        }
        
        const params = std.json.Value{ .object = params_obj };
        const response = try self.sendRequest("textDocument/codeAction",
params);
        
        // Parse code actions array from response.result
        if (response.result) |result| {
            if (result == .array) {
                const items = result.array.items;
                var actions =
std.ArrayList(CodeAction).init(self.allocator);
                errdefer {
                    // Free any allocated strings on error
                    for (actions.items) |*action| {
                        self.allocator.free(action.title);
                        if (action.command) |cmd| {
                            self.allocator.free(cmd.command);
                            if (cmd.arguments) |args| {
                                self.allocator.free(args);
                            }
                        }
                        if (action.edit) |edit| {
                            for (edit.changes.items) |*change| {
                                for (change.edits.items) |*text_edit| {
                                   
self.allocator.free(text_edit.new_text);
                                }
                                change.edits.deinit(self.allocator);
                                self.allocator.free(change.uri);
                            }
                            edit.changes.deinit(self.allocator);
                        }
                    }
                    actions.deinit();
                }
                
                for (items) |item| {
                    if (item == .object) {
                        const obj = item.object;
                        
                        // Parse title
                        const title_val = obj.get("title") orelse
continue;
                        if (title_val != .string) continue;
                        const title_str = title_val.string;
                        
                        const title_copy = try self.allocator.dupe(u8,
title_str);
                        errdefer self.allocator.free(title_copy);
                        
                        // Parse command (optional)
                        var command: ?CodeActionCommand = null;
                        if (obj.get("command")) |cmd_val| {
                            if (cmd_val == .object) {
                                const cmd_obj = cmd_val.object;
                                const cmd_title = cmd_obj.get("command")
orelse continue;
                                if (cmd_title != .string) continue;
                                
                                const cmd_str = try
self.allocator.dupe(u8, cmd_title.string);
                                errdefer self.allocator.free(cmd_str);
                                
                                // Parse arguments (optional)
                                var arguments: ?[]const u8 = null;
                                if (cmd_obj.get("arguments")) |args_val|
{
                                    // Arguments can be any JSON value,
store as string for now
                                    const args_str = try
self.serialize_json_value(args_val);
                                    errdefer
self.allocator.free(args_str);
                                    arguments = args_str;
                                }
                                
                                command = CodeActionCommand{
                                    .command = cmd_str,
                                    .arguments = arguments,
                                };
                            }
                        }
                        
                        // Parse edit (optional)
                        var edit: ?WorkspaceEdit = null;
                        if (obj.get("edit")) |edit_val| {
                            if (edit_val == .object) {
                                const edit_obj = edit_val.object;
                                
                                // Parse changes (map of URI to
TextEdit[])
                                var changes =
std.ArrayList(TextDocumentEdit).init(self.allocator);
                                errdefer {
                                    for (changes.items) |*change| {
                                        for (change.edits.items)
|*text_edit| {
                                           
self.allocator.free(text_edit.new_text);
                                        }
                                       
change.edits.deinit(self.allocator);
                                        self.allocator.free(change.uri);
                                    }
                                    changes.deinit();
                                }
                                
                                if (edit_obj.get("changes"))
|changes_val| {
                                    if (changes_val == .object) {
                                        var changes_it =
changes_val.object.iterator();
                                        while (changes_it.next())
|entry| {
                                            const uri_str =
entry.key_ptr.*;
                                            const edits_val =
entry.value_ptr.*;
                                            
                                            if (edits_val == .array) {
                                                var edits =
std.ArrayList(TextEdit).init(self.allocator);
                                                errdefer {
                                                    for (edits.items)
|*text_edit| {
                                                       
self.allocator.free(text_edit.new_text);
                                                    }
                                                    edits.deinit();
                                                }
                                                
                                                for
(edits_val.array.items) |edit_item| {
                                                    if (edit_item ==
.object) {
                                                        const
edit_item_obj = edit_item.object;
                                                        
                                                        // Parse range
                                                        const range_val
= edit_item_obj.get("range") orelse continue;
                                                        if (range_val !=
.object) continue;
                                                        const
edit_range_obj = range_val.object;
                                                        
                                                        const start_val
= edit_range_obj.get("start") orelse continue;
                                                        const end_val =
edit_range_obj.get("end") orelse continue;
                                                        if (start_val !=
.object or end_val != .object) continue;
                                                        
                                                        const
edit_start_obj = start_val.object;
                                                        const
edit_end_obj = end_val.object;
                                                        
                                                        const
start_line_val = edit_start_obj.get("line") orelse continue;
                                                        const
start_char_val = edit_start_obj.get("character") orelse continue;
                                                        const
end_line_val = edit_end_obj.get("line") orelse continue;
                                                        const
end_char_val = edit_end_obj.get("character") orelse continue;
                                                        
                                                        if
(start_line_val != .integer or start_char_val != .integer or
                                                            end_line_val
!= .integer or end_char_val != .integer) continue;
                                                        
                                                        const start_line
= @as(u32, @intCast(start_line_val.integer));
                                                        const start_char
= @as(u32, @intCast(start_char_val.integer));
                                                        const end_line =
@as(u32, @intCast(end_line_val.integer));
                                                        const end_char =
@as(u32, @intCast(end_char_val.integer));
                                                        
                                                        // Parse newText
                                                        const
new_text_val = edit_item_obj.get("newText") orelse continue;
                                                        if (new_text_val
!= .string) continue;
                                                        const
new_text_str = new_text_val.string;
                                                        
                                                        const
new_text_copy = try self.allocator.dupe(u8, new_text_str);
                                                        errdefer
self.allocator.free(new_text_copy);
                                                        
                                                        try
edits.append(TextEdit{
                                                            .range =
Range{
                                                                .start =
Position{ .line = start_line, .character = start_char },
                                                                .end =
Position{ .line = end_line, .character = end_char },
                                                            },
                                                            .new_text =
new_text_copy,
                                                        });
                                                    }
                                                }
                                                
                                                const uri_copy = try
self.allocator.dupe(u8, uri_str);
                                                errdefer
self.allocator.free(uri_copy);
                                                
                                                try
changes.append(TextDocumentEdit{
                                                    .uri = uri_copy,
                                                    .edits = edits,
                                                });
                                            }
                                        }
                                    }
                                }
                                
                                const changes_slice = try
changes.toOwnedSlice(self.allocator);
                                edit = WorkspaceEdit{
                                    .changes =
std.ArrayList(TextDocumentEdit).fromOwnedSlice(self.allocator,
changes_slice),
                                };
                            }
                        }
                        
                        try actions.append(CodeAction{
                            .title = title_copy,
                            .command = command,
                            .edit = edit,
                        });
                    }
                }
                
                return try actions.toOwnedSlice();
            }
        }
        return null;
    }
    
    /// Code action from LSP server.
    pub const CodeAction = struct {
        title: []const u8, // Title of the action
        command: ?CodeActionCommand = null, // Optional command to
execute
        edit: ?WorkspaceEdit = null, // Optional workspace edit
    };
    
    /// Code action command.
    pub const CodeActionCommand = struct {
        command: []const u8, // Command identifier
        arguments: ?[]const u8 = null, // Optional arguments (JSON
string)
    };
    
    /// Workspace edit (multiple file edits).
    pub const WorkspaceEdit = struct {
        changes: std.ArrayList(TextDocumentEdit), // Changes per document
    };
    
    /// Text document edit (edits for a single document).
    pub const TextDocumentEdit = struct {
        uri: []const u8, // Document URI
        edits: std.ArrayList(TextEdit), // Text edits for this document
    };
    
    /// Code action context (diagnostics, etc.).
    pub const CodeActionContext = struct {
        diagnostics: []const Diagnostic, // Diagnostics in the range
        only_requested: ?bool = null, // Only return requested action
kinds
    };
    
    /// Text edit for document formatting.
    pub const TextEdit = struct {
        range: Range, // Range to replace
        new_text: []const u8, // New text to insert
    };
    
    /// Request textDocument/prepareRename (check if rename is valid at
position).
    /// Why: Validate that rename is possible at the given position
before attempting rename.
    /// Contract: uri, line, and character must be valid.
    /// Returns: Range where rename is valid, or null if rename not
available.
    /// Note: Caller must free the returned range if it contains
allocated strings.
    pub fn requestPrepareRename(
        self: *LspClient,
        uri: []const u8,
        line: u32,
        character: u32,
    ) !?Range {
        // Assert: URI and position must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        var position_obj = std.json.ObjectMap.init(self.allocator);
        defer position_obj.deinit();
        try position_obj.put("line", std.json.Value{ .integer =
@intCast(line) });
        try position_obj.put("character", std.json.Value{ .integer =
@intCast(character) });
        try params_obj.put("position", std.json.Value{ .object =
position_obj });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try
self.sendRequest("textDocument/prepareRename", params);
        
        // Parse range from response.result
        if (response.result) |result| {
            if (result == .object) {
                const obj = result.object;
                
                const start_val = obj.get("start") orelse return null;
                const end_val = obj.get("end") orelse return null;
                if (start_val != .object or end_val != .object) return
null;
                
                const start_obj = start_val.object;
                const end_obj = end_val.object;
                
                const start_line_val = start_obj.get("line") orelse
return null;
                const start_char_val = start_obj.get("character") orelse
return null;
                const end_line_val = end_obj.get("line") orelse return
null;
                const end_char_val = end_obj.get("character") orelse
return null;
                
                if (start_line_val != .integer or start_char_val !=
.integer or
                    end_line_val != .integer or end_char_val !=
.integer) return null;
                
                const start_line = @as(u32,
@intCast(start_line_val.integer));
                const start_char = @as(u32,
@intCast(start_char_val.integer));
                const end_line = @as(u32,
@intCast(end_line_val.integer));
                const end_char = @as(u32,
@intCast(end_char_val.integer));
                
                return Range{
                    .start = Position{ .line = start_line, .character =
start_char },
                    .end = Position{ .line = end_line, .character =
end_char },
                };
            }
        }
        return null;
    }
    
    /// Request textDocument/rename (rename symbol at position).
    /// Why: Rename a symbol across all references for refactoring.
    /// Contract: uri, position, and new_name must be valid.
    /// Returns: Workspace edit with changes to all files, or null if
rename not available.
    pub fn requestRename(
        self: *LspClient,
        uri: []const u8,
        line: u32,
        character: u32,
        new_name: []const u8,
    ) !?WorkspaceEdit {
        // Assert: URI, position, and new name must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        std.debug.assert(new_name.len > 0);
        std.debug.assert(new_name.len <= 1024); // Bounded name length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        // Add position
        var position_obj = std.json.ObjectMap.init(self.allocator);
        defer position_obj.deinit();
        try position_obj.put("line", std.json.Value{ .integer =
@intCast(line) });
        try position_obj.put("character", std.json.Value{ .integer =
@intCast(character) });
        try params_obj.put("position", std.json.Value{ .object =
position_obj });
        
        // Add new name
        try params_obj.put("newName", std.json.Value{ .string = new_name
});
        
        const params = std.json.Value{ .object = params_obj };
        const response = try self.sendRequest("textDocument/rename",
params);
        
        // Parse workspace edit from response.result
        if (response.result) |result| {
            if (result == .object) {
                const obj = result.object;
                
                // Parse changes (map of URI to TextEdit[])
                var changes =
std.ArrayList(TextDocumentEdit).init(self.allocator);
                errdefer {
                    for (changes.items) |*change| {
                        for (change.edits.items) |*text_edit| {
                            self.allocator.free(text_edit.new_text);
                        }
                        change.edits.deinit(self.allocator);
                        self.allocator.free(change.uri);
                    }
                    changes.deinit();
                }
                
                if (obj.get("changes")) |changes_val| {
                    if (changes_val == .object) {
                        var changes_it = changes_val.object.iterator();
                        while (changes_it.next()) |entry| {
                            const uri_str = entry.key_ptr.*;
                            const edits_val = entry.value_ptr.*;
                            
                            if (edits_val == .array) {
                                var edits =
std.ArrayList(TextEdit).init(self.allocator);
                                errdefer {
                                    for (edits.items) |*text_edit| {
                                       
self.allocator.free(text_edit.new_text);
                                    }
                                    edits.deinit();
                                }
                                
                                for (edits_val.array.items) |edit_item| {
                                    if (edit_item == .object) {
                                        const edit_item_obj =
edit_item.object;
                                        
                                        // Parse range
                                        const range_val =
edit_item_obj.get("range") orelse continue;
                                        if (range_val != .object)
continue;
                                        const edit_range_obj =
range_val.object;
                                        
                                        const start_val =
edit_range_obj.get("start") orelse continue;
                                        const end_val =
edit_range_obj.get("end") orelse continue;
                                        if (start_val != .object or
end_val != .object) continue;
                                        
                                        const edit_start_obj =
start_val.object;
                                        const edit_end_obj =
end_val.object;
                                        
                                        const start_line_val =
edit_start_obj.get("line") orelse continue;
                                        const start_char_val =
edit_start_obj.get("character") orelse continue;
                                        const end_line_val =
edit_end_obj.get("line") orelse continue;
                                        const end_char_val =
edit_end_obj.get("character") orelse continue;
                                        
                                        if (start_line_val != .integer
or start_char_val != .integer or
                                            end_line_val != .integer or
end_char_val != .integer) continue;
                                        
                                        const start_line = @as(u32,
@intCast(start_line_val.integer));
                                        const start_char = @as(u32,
@intCast(start_char_val.integer));
                                        const end_line = @as(u32,
@intCast(end_line_val.integer));
                                        const end_char = @as(u32,
@intCast(end_char_val.integer));
                                        
                                        // Parse newText
                                        const new_text_val =
edit_item_obj.get("newText") orelse continue;
                                        if (new_text_val != .string)
continue;
                                        const new_text_str =
new_text_val.string;
                                        
                                        const new_text_copy = try
self.allocator.dupe(u8, new_text_str);
                                        errdefer
self.allocator.free(new_text_copy);
                                        
                                        try edits.append(TextEdit{
                                            .range = Range{
                                                .start = Position{ .line
= start_line, .character = start_char },
                                                .end = Position{ .line =
end_line, .character = end_char },
                                            },
                                            .new_text = new_text_copy,
                                        });
                                    }
                                }
                                
                                const uri_copy = try
self.allocator.dupe(u8, uri_str);
                                errdefer self.allocator.free(uri_copy);
                                
                                try changes.append(TextDocumentEdit{
                                    .uri = uri_copy,
                                    .edits = edits,
                                });
                            }
                        }
                    }
                }
                
                const changes_slice = try
changes.toOwnedSlice(self.allocator);
                return WorkspaceEdit{
                    .changes =
std.ArrayList(TextDocumentEdit).fromOwnedSlice(self.allocator,
changes_slice),
                };
            }
        }
        return null;
    }
    
    /// Request workspace/symbol (search for symbols in workspace).
    /// Why: Search for symbols across the entire workspace for
navigation.
    /// Contract: query must be valid.
    /// Returns: Array of symbol information, or null if no symbols
found.
    pub fn requestWorkspaceSymbols(
        self: *LspClient,
        query: []const u8,
    ) !?[]SymbolInformation {
        // Assert: Query must be valid
        std.debug.assert(query.len <= 1024); // Bounded query length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        try params_obj.put("query", std.json.Value{ .string = query });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try self.sendRequest("workspace/symbol",
params);
        
        // Parse symbol information array from response.result
        if (response.result) |result| {
            if (result == .array) {
                const items = result.array.items;
                var symbols =
std.ArrayList(SymbolInformation).init(self.allocator);
                errdefer {
                    // Free any allocated strings on error
                    for (symbols.items) |*symbol| {
                        self.allocator.free(symbol.name);
                        self.allocator.free(symbol.uri);
                        if (symbol.container_name) |container| {
                            self.allocator.free(container);
                        }
                    }
                    symbols.deinit();
                }
                
                for (items) |item| {
                    if (item == .object) {
                        const obj = item.object;
                        
                        // Parse name
                        const name_val = obj.get("name") orelse continue;
                        if (name_val != .string) continue;
                        const name_str = name_val.string;
                        
                        const name_copy = try self.allocator.dupe(u8,
name_str);
                        errdefer self.allocator.free(name_copy);
                        
                        // Parse kind (optional)
                        const kind: ?u32 = if (obj.get("kind")) |k|
                            if (k == .integer) @as(u32,
@intCast(k.integer)) else null
                        else
                            null;
                        
                        // Parse location
                        const location_val = obj.get("location") orelse
continue;
                        if (location_val != .object) continue;
                        const location_obj = location_val.object;
                        
                        const location_uri = location_obj.get("uri")
orelse continue;
                        if (location_uri != .string) continue;
                        const uri_str = location_uri.string;
                        
                        const uri_copy = try self.allocator.dupe(u8,
uri_str);
                        errdefer self.allocator.free(uri_copy);
                        
                        // Parse range
                        const range_val = location_obj.get("range")
orelse continue;
                        if (range_val != .object) continue;
                        const range_obj = range_val.object;
                        
                        const start_val = range_obj.get("start") orelse
continue;
                        const end_val = range_obj.get("end") orelse
continue;
                        if (start_val != .object or end_val != .object)
continue;
                        
                        const start_obj = start_val.object;
                        const end_obj = end_val.object;
                        
                        const start_line_val = start_obj.get("line")
orelse continue;
                        const start_char_val =
start_obj.get("character") orelse continue;
                        const end_line_val = end_obj.get("line") orelse
continue;
                        const end_char_val = end_obj.get("character")
orelse continue;
                        
                        if (start_line_val != .integer or start_char_val
!= .integer or
                            end_line_val != .integer or end_char_val !=
.integer) continue;
                        
                        const start_line = @as(u32,
@intCast(start_line_val.integer));
                        const start_char = @as(u32,
@intCast(start_char_val.integer));
                        const end_line = @as(u32,
@intCast(end_line_val.integer));
                        const end_char = @as(u32,
@intCast(end_char_val.integer));
                        
                        // Parse containerName (optional)
                        var container_name: ?[]const u8 = null;
                        if (obj.get("containerName")) |container_val| {
                            if (container_val == .string) {
                                const container_str =
container_val.string;
                                const container_copy = try
self.allocator.dupe(u8, container_str);
                                errdefer
self.allocator.free(container_copy);
                                container_name = container_copy;
                            }
                        }
                        
                        try symbols.append(SymbolInformation{
                            .name = name_copy,
                            .kind = kind,
                            .uri = uri_copy,
                            .range = Range{
                                .start = Position{ .line = start_line,
.character = start_char },
                                .end = Position{ .line = end_line,
.character = end_char },
                            },
                            .container_name = container_name,
                        });
                    }
                }
                
                return try symbols.toOwnedSlice();
            }
        }
        return null;
    }
    
    /// Symbol information from workspace symbol search.
    pub const SymbolInformation = struct {
        name: []const u8, // Symbol name
        kind: ?u32 = null, // Symbol kind (function, class, etc.)
        uri: []const u8, // File URI where symbol is located
        range: Range, // Range of the symbol
        container_name: ?[]const u8 = null, // Optional container name
(e.g., class name)
    };
    
    /// Request textDocument/documentSymbol (get symbols in document).
    /// Why: Get outline of document (functions, classes, etc.) for
navigation.
    /// Contract: uri must be valid.
    /// Returns: Array of document symbols, or null if no symbols found.
    pub fn requestDocumentSymbols(
        self: *LspClient,
        uri: []const u8,
    ) !?[]DocumentSymbol {
        // Assert: URI must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try
self.sendRequest("textDocument/documentSymbol", params);
        
        // Parse document symbols array from response.result
        if (response.result) |result| {
            if (result == .array) {
                const items = result.array.items;
                var symbols =
std.ArrayList(DocumentSymbol).init(self.allocator);
                errdefer {
                    // Free any allocated strings on error
                    for (symbols.items) |*symbol| {
                        self.allocator.free(symbol.name);
                        if (symbol.detail) |detail| {
                            self.allocator.free(detail);
                        }
                        if (symbol.children) |children| {
                            for (children.items) |*child| {
                                self.allocator.free(child.name);
                                if (child.detail) |d| {
                                    self.allocator.free(d);
                                }
                            }
                            children.deinit(self.allocator);
                            self.allocator.free(children.items);
                        }
                    }
                    symbols.deinit();
                }
                
                for (items) |item| {
                    if (item == .object) {
                        const obj = item.object;
                        
                        // Parse name
                        const name_val = obj.get("name") orelse continue;
                        if (name_val != .string) continue;
                        const name_str = name_val.string;
                        
                        const name_copy = try self.allocator.dupe(u8,
name_str);
                        errdefer self.allocator.free(name_copy);
                        
                        // Parse kind (optional)
                        const kind: ?u32 = if (obj.get("kind")) |k|
                            if (k == .integer) @as(u32,
@intCast(k.integer)) else null
                        else
                            null;
                        
                        // Parse range
                        const range_val = obj.get("range") orelse
continue;
                        if (range_val != .object) continue;
                        const range_obj = range_val.object;
                        
                        const start_val = range_obj.get("start") orelse
continue;
                        const end_val = range_obj.get("end") orelse
continue;
                        if (start_val != .object or end_val != .object)
continue;
                        
                        const start_obj = start_val.object;
                        const end_obj = end_val.object;
                        
                        const start_line_val = start_obj.get("line")
orelse continue;
                        const start_char_val =
start_obj.get("character") orelse continue;
                        const end_line_val = end_obj.get("line") orelse
continue;
                        const end_char_val = end_obj.get("character")
orelse continue;
                        
                        if (start_line_val != .integer or start_char_val
!= .integer or
                            end_line_val != .integer or end_char_val !=
.integer) continue;
                        
                        const start_line = @as(u32,
@intCast(start_line_val.integer));
                        const start_char = @as(u32,
@intCast(start_char_val.integer));
                        const end_line = @as(u32,
@intCast(end_line_val.integer));
                        const end_char = @as(u32,
@intCast(end_char_val.integer));
                        
                        // Parse selectionRange (optional, defaults to
range)
                        var selection_range = Range{
                            .start = Position{ .line = start_line,
.character = start_char },
                            .end = Position{ .line = end_line,
.character = end_char },
                        };
                        if (obj.get("selectionRange")) |sel_range_val| {
                            if (sel_range_val == .object) {
                                const sel_range_obj =
sel_range_val.object;
                                const sel_start_val =
sel_range_obj.get("start");
                                const sel_end_val =
sel_range_obj.get("end");
                                if (sel_start_val != null and
sel_end_val != null) {
                                    if (sel_start_val.? == .object and
sel_end_val.? == .object) {
                                        const sel_start_obj =
sel_start_val.?.object;
                                        const sel_end_obj =
sel_end_val.?.object;
                                        
                                        const sel_start_line_val =
sel_start_obj.get("line");
                                        const sel_start_char_val =
sel_start_obj.get("character");
                                        const sel_end_line_val =
sel_end_obj.get("line");
                                        const sel_end_char_val =
sel_end_obj.get("character");
                                        
                                        if (sel_start_line_val != null
and sel_start_char_val != null and
                                            sel_end_line_val != null and
sel_end_char_val != null) {
                                            if (sel_start_line_val.? ==
.integer and sel_start_char_val.? == .integer and
                                                sel_end_line_val.? ==
.integer and sel_end_char_val.? == .integer) {
                                                selection_range = Range{
                                                    .start = Position{
                                                        .line = @as(u32,
@intCast(sel_start_line_val.?.integer)),
                                                        .character =
@as(u32, @intCast(sel_start_char_val.?.integer)),
                                                    },
                                                    .end = Position{
                                                        .line = @as(u32,
@intCast(sel_end_line_val.?.integer)),
                                                        .character =
@as(u32, @intCast(sel_end_char_val.?.integer)),
                                                    },
                                                };
                                            }
                                        }
                                    }
                                }
                            }
                        }
                        
                        // Parse detail (optional)
                        var detail: ?[]const u8 = null;
                        if (obj.get("detail")) |detail_val| {
                            if (detail_val == .string) {
                                const detail_str = detail_val.string;
                                const detail_copy = try
self.allocator.dupe(u8, detail_str);
                                errdefer
self.allocator.free(detail_copy);
                                detail = detail_copy;
                            }
                        }
                        
                        // Parse children (optional, recursive)
                        var children: ?std.ArrayList(DocumentSymbol) =
null;
                        if (obj.get("children")) |children_val| {
                            if (children_val == .array) {
                                children =
std.ArrayList(DocumentSymbol).init(self.allocator);
                                errdefer {
                                    if (children) |*ch| {
                                        for (ch.items) |*child| {
                                           
self.allocator.free(child.name);
                                            if (child.detail) |d| {
                                                self.allocator.free(d);
                                            }
                                        }
                                        ch.deinit();
                                    }
                                }
                                
                                // Note: For simplicity, we only parse
one level of children
                                // Full recursive parsing would require
more complex error handling
                                for (children_val.array.items)
|child_item| {
                                    if (child_item == .object) {
                                        const child_obj =
child_item.object;
                                        
                                        const child_name_val =
child_obj.get("name") orelse continue;
                                        if (child_name_val != .string)
continue;
                                        const child_name_str =
child_name_val.string;
                                        
                                        const child_name_copy = try
self.allocator.dupe(u8, child_name_str);
                                        errdefer
self.allocator.free(child_name_copy);
                                        
                                        const child_kind: ?u32 = if
(child_obj.get("kind")) |k|
                                            if (k == .integer) @as(u32,
@intCast(k.integer)) else null
                                        else
                                            null;
                                        
                                        const child_range_val =
child_obj.get("range") orelse continue;
                                        if (child_range_val != .object)
continue;
                                        const child_range_obj =
child_range_val.object;
                                        
                                        const child_start_val =
child_range_obj.get("start") orelse continue;
                                        const child_end_val =
child_range_obj.get("end") orelse continue;
                                        if (child_start_val != .object
or child_end_val != .object) continue;
                                        
                                        const child_start_obj =
child_start_val.object;
                                        const child_end_obj =
child_end_val.object;
                                        
                                        const child_start_line_val =
child_start_obj.get("line") orelse continue;
                                        const child_start_char_val =
child_start_obj.get("character") orelse continue;
                                        const child_end_line_val =
child_end_obj.get("line") orelse continue;
                                        const child_end_char_val =
child_end_obj.get("character") orelse continue;
                                        
                                        if (child_start_line_val !=
.integer or child_start_char_val != .integer or
                                            child_end_line_val !=
.integer or child_end_char_val != .integer) continue;
                                        
                                        const child_start_line =
@as(u32, @intCast(child_start_line_val.integer));
                                        const child_start_char =
@as(u32, @intCast(child_start_char_val.integer));
                                        const child_end_line = @as(u32,
@intCast(child_end_line_val.integer));
                                        const child_end_char = @as(u32,
@intCast(child_end_char_val.integer));
                                        
                                        var child_detail: ?[]const u8 =
null;
                                        if (child_obj.get("detail"))
|d_val| {
                                            if (d_val == .string) {
                                                const child_detail_str =
d_val.string;
                                                const child_detail_copy
= try self.allocator.dupe(u8, child_detail_str);
                                                errdefer
self.allocator.free(child_detail_copy);
                                                child_detail =
child_detail_copy;
                                            }
                                        }
                                        
                                        try
children.?.append(DocumentSymbol{
                                            .name = child_name_copy,
                                            .kind = child_kind,
                                            .range = Range{
                                                .start = Position{ .line
= child_start_line, .character = child_start_char },
                                                .end = Position{ .line =
child_end_line, .character = child_end_char },
                                            },
                                            .selection_range = Range{
                                                .start = Position{ .line
= child_start_line, .character = child_start_char },
                                                .end = Position{ .line =
child_end_line, .character = child_end_char },
                                            },
                                            .detail = child_detail,
                                            .children = null, // Only
one level for now
                                        });
                                    }
                                }
                            }
                        }
                        
                        try symbols.append(DocumentSymbol{
                            .name = name_copy,
                            .kind = kind,
                            .range = Range{
                                .start = Position{ .line = start_line,
.character = start_char },
                                .end = Position{ .line = end_line,
.character = end_char },
                            },
                            .selection_range = selection_range,
                            .detail = detail,
                            .children = children,
                        });
                    }
                }
                
                return try symbols.toOwnedSlice();
            }
        }
        return null;
    }
    
    /// Document symbol (for outline view).
    pub const DocumentSymbol = struct {
        name: []const u8, // Symbol name
        kind: ?u32 = null, // Symbol kind (function, class, etc.)
        range: Range, // Full range of symbol
        selection_range: Range, // Range that should be selected when
navigating
        detail: ?[]const u8 = null, // Optional detail (e.g., function
signature)
        children: ?std.ArrayList(DocumentSymbol) = null, // Optional
child symbols
    };
    
    /// Request textDocument/onTypeFormatting (format on character
trigger).
    /// Why: Format code automatically when typing specific characters
(e.g., ';', '}').
    /// Contract: uri, position, and ch must be valid.
    /// Returns: Array of text edits to apply, or null if formatting not
available.
    pub fn requestOnTypeFormatting(
        self: *LspClient,
        uri: []const u8,
        line: u32,
        character: u32,
        ch: u8,
        options: ?FormattingOptions,
    ) !?[]TextEdit {
        // Assert: URI, position, and character must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        std.debug.assert(ch > 0);
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        // Add position
        var position_obj = std.json.ObjectMap.init(self.allocator);
        defer position_obj.deinit();
        try position_obj.put("line", std.json.Value{ .integer =
@intCast(line) });
        try position_obj.put("character", std.json.Value{ .integer =
@intCast(character) });
        try params_obj.put("position", std.json.Value{ .object =
position_obj });
        
        // Add character that triggered formatting
        var ch_str: [1]u8 = undefined;
        ch_str[0] = ch;
        try params_obj.put("ch", std.json.Value{ .string = &ch_str });
        
        // Add formatting options if provided
        if (options) |opts| {
            var options_obj = std.json.ObjectMap.init(self.allocator);
            try options_obj.put("tabSize", std.json.Value{ .integer =
@intCast(opts.tab_size) });
            try options_obj.put("insertSpaces", std.json.Value{ .bool =
opts.insert_spaces });
            try params_obj.put("options", std.json.Value{ .object =
options_obj });
        }
        
        const params = std.json.Value{ .object = params_obj };
        const response = try
self.sendRequest("textDocument/onTypeFormatting", params);
        
        // Parse text edits array from response.result (same as document
formatting)
        if (response.result) |result| {
            if (result == .array) {
                const items = result.array.items;
                var edits = std.ArrayList(TextEdit).init(self.allocator);
                errdefer {
                    // Free any allocated text on error
                    for (edits.items) |*edit| {
                        self.allocator.free(edit.new_text);
                    }
                    edits.deinit();
                }
                
                for (items) |item| {
                    if (item == .object) {
                        const obj = item.object;
                        
                        // Parse range
                        const range_val = obj.get("range") orelse
continue;
                        if (range_val != .object) continue;
                        const edit_range_obj = range_val.object;
                        
                        const start_val = edit_range_obj.get("start")
orelse continue;
                        const end_val = edit_range_obj.get("end") orelse
continue;
                        if (start_val != .object or end_val != .object)
continue;
                        
                        const edit_start_obj = start_val.object;
                        const edit_end_obj = end_val.object;
                        
                        const start_line_val =
edit_start_obj.get("line") orelse continue;
                        const start_char_val =
edit_start_obj.get("character") orelse continue;
                        const end_line_val = edit_end_obj.get("line")
orelse continue;
                        const end_char_val =
edit_end_obj.get("character") orelse continue;
                        
                        if (start_line_val != .integer or start_char_val
!= .integer or
                            end_line_val != .integer or end_char_val !=
.integer) continue;
                        
                        const start_line = @as(u32,
@intCast(start_line_val.integer));
                        const start_char = @as(u32,
@intCast(start_char_val.integer));
                        const end_line = @as(u32,
@intCast(end_line_val.integer));
                        const end_char = @as(u32,
@intCast(end_char_val.integer));
                        
                        // Parse newText
                        const new_text_val = obj.get("newText") orelse
continue;
                        if (new_text_val != .string) continue;
                        const new_text_str = new_text_val.string;
                        
                        const new_text_copy = try
self.allocator.dupe(u8, new_text_str);
                        errdefer self.allocator.free(new_text_copy);
                        
                        try edits.append(TextEdit{
                            .range = Range{
                                .start = Position{ .line = start_line,
.character = start_char },
                                .end = Position{ .line = end_line,
.character = end_char },
                            },
                            .new_text = new_text_copy,
                        });
                    }
                }
                
                return try edits.toOwnedSlice();
            }
        }
        return null;
    }
    
    /// Formatting options for document formatting.
    pub const FormattingOptions = struct {
        tab_size: u32, // Number of spaces per tab
        insert_spaces: bool, // Use spaces instead of tabs
    };
    
    /// Send textDocument/didOpen notification (document opened).
    pub fn didOpen(self: *LspClient, uri: []const u8, text: []const u8)
!void {
        // Assert: URI and text must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        std.debug.assert(text.len <= 100 * 1024 * 1024); // Bounded text
size (100MB)
        
        // Assert: Bounded snapshots
        std.debug.assert(self.snapshots.items.len < MAX_SNAPSHOTS);
        
        // Create snapshot
        const snapshot = DocumentSnapshot{
            .id = self.current_snapshot_id,
            .uri = try self.allocator.dupe(u8, uri),
            .version = 0,
            .text = try self.allocator.dupe(u8, text),
        };
        self.current_snapshot_id += 1;
        
        try self.snapshots.append(self.allocator, snapshot);
        
        // Assert: Snapshot added successfully
        std.debug.assert(self.snapshots.items.len <= MAX_SNAPSHOTS);
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try text_doc_obj.put("languageId", std.json.Value{ .string =
"zig" });
        try text_doc_obj.put("version", std.json.Value{ .integer = 0 });
        try text_doc_obj.put("text", std.json.Value{ .string = text });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        const params = std.json.Value{ .object = params_obj };
        try self.sendNotification("textDocument/didOpen", params);
    }
    
    /// Send textDocument/didChange notification (incremental update,
Matklad snapshot model).
    pub fn didChange(self: *LspClient, uri: []const u8, changes: []const
TextDocumentChange) !void {
        // Find existing snapshot
        var snapshot_idx: ?u32 = null;
        for (self.snapshots.items, 0..) |*snapshot, i| {
            if (std.mem.eql(u8, snapshot.uri, uri)) {
                // Assert: Index fits in u32
                std.debug.assert(i <= std.math.maxInt(u32));
                snapshot_idx = @intCast(i);
                break;
            }
        }
        
        // Assert: Snapshot must exist
        std.debug.assert(snapshot_idx != null);
        const snapshot = &self.snapshots.items[snapshot_idx.?];
        
        // Apply incremental changes (Matklad snapshot model)
        var new_text = try self.allocator.dupe(u8, snapshot.text);
        errdefer self.allocator.free(new_text);
        
        for (changes) |change| {
            if (change.range) |range| {
                // Incremental edit: replace range with new text
                const start_byte = try
self.positionToByte(snapshot.text, range.start);
                const end_byte = try self.positionToByte(snapshot.text,
range.end);
                
                // Replace range in text
                var updated = try self.allocator.alloc(u8, new_text.len
- (end_byte - start_byte) + change.text.len);
                @memcpy(updated[0..start_byte], new_text[0..start_byte]);
                @memcpy(updated[start_byte..start_byte +
change.text.len], change.text);
                @memcpy(updated[start_byte + change.text.len..],
new_text[end_byte..]);
                
                self.allocator.free(new_text);
                new_text = updated;
            } else {
                // Full document replacement
                self.allocator.free(new_text);
                new_text = try self.allocator.dupe(u8, change.text);
            }
        }
        
        // Update snapshot
        self.allocator.free(snapshot.text);
        snapshot.text = new_text;
        snapshot.version += 1;
        
        // Build LSP params
        var change_objects = std.ArrayList(std.json.Value){ .items =
&.{}, .capacity = 0 };
        defer change_objects.deinit(self.allocator);
        
        for (changes) |change| {
            var change_obj = std.json.ObjectMap.init(self.allocator);
            if (change.range) |range| {
                var range_obj = std.json.ObjectMap.init(self.allocator);
                
                var start_obj = std.json.ObjectMap.init(self.allocator);
                try start_obj.put("line", std.json.Value{ .integer =
@intCast(range.start.line) });
                try start_obj.put("character", std.json.Value{ .integer
= @intCast(range.start.character) });
                try range_obj.put("start", std.json.Value{ .object =
start_obj });
                
                var end_obj = std.json.ObjectMap.init(self.allocator);
                try end_obj.put("line", std.json.Value{ .integer =
@intCast(range.end.line) });
                try end_obj.put("character", std.json.Value{ .integer =
@intCast(range.end.character) });
                try range_obj.put("end", std.json.Value{ .object =
end_obj });
                
                try change_obj.put("range", std.json.Value{ .object =
range_obj });
                
                if (change.range_length) |len| {
                    try change_obj.put("rangeLength", std.json.Value{
.integer = @intCast(len) });
                }
            }
            try change_obj.put("text", std.json.Value{ .string =
change.text });
            try change_objects.append(self.allocator, std.json.Value{
.object = change_obj });
        }
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try text_doc_obj.put("version", std.json.Value{ .integer =
@intCast(snapshot.version) });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        const changes_slice = try
change_objects.toOwnedSlice(self.allocator);
        try params_obj.put("contentChanges", std.json.Value{ .array = .{
.items = changes_slice, .capacity = changes_slice.len, .allocator =
self.allocator } });
        
        const params = std.json.Value{ .object = params_obj };
        try self.sendNotification("textDocument/didChange", params);
    }
    
    /// Request textDocument/willSave (check if save should proceed).
    /// Why: Allow LSP server to request save confirmation or prepare
for save.
    /// Contract: uri must be valid, reason must be valid (1=Manual,
2=AfterDelay, 3=FocusOut).
    /// Returns: True if save should proceed, false if save should be
cancelled.
    pub fn requestWillSave(self: *LspClient, uri: []const u8, reason:
u32) !bool {
        // Assert: URI must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        // Assert: Reason must be valid (1=Manual, 2=AfterDelay,
3=FocusOut)
        std.debug.assert(reason >= 1);
        std.debug.assert(reason <= 3);
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        try params_obj.put("reason", std.json.Value{ .integer =
@intCast(reason) });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try self.sendRequest("textDocument/willSave",
params);
        
        // WillSave is a notification, but some servers may respond
        // For now, assume save should proceed unless server explicitly
rejects
        _ = response;
        return true;
    }
    
    /// Request textDocument/willSaveWaitUntil (get text edits before
save).
    /// Why: Allow LSP server to provide text edits that should be
applied before save.
    /// Contract: uri must be valid, reason must be valid (1=Manual,
2=AfterDelay, 3=FocusOut).
    /// Returns: Array of text edits to apply before save, or null if no
edits needed.
    /// Note: Caller must free the returned edits array and new_text
strings.
    pub fn requestWillSaveWaitUntil(
        self: *LspClient,
        uri: []const u8,
        reason: u32,
    ) !?[]TextEdit {
        // Assert: URI must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        // Assert: Reason must be valid (1=Manual, 2=AfterDelay,
3=FocusOut)
        std.debug.assert(reason >= 1);
        std.debug.assert(reason <= 3);
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        try params_obj.put("reason", std.json.Value{ .integer =
@intCast(reason) });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try
self.sendRequest("textDocument/willSaveWaitUntil", params);
        
        // Parse text edits array from response.result (same as document
formatting)
        if (response.result) |result| {
            if (result == .array) {
                const items = result.array.items;
                var edits = std.ArrayList(TextEdit).init(self.allocator);
                errdefer {
                    // Free any allocated text on error
                    for (edits.items) |*edit| {
                        self.allocator.free(edit.new_text);
                    }
                    edits.deinit();
                }
                
                for (items) |item| {
                    if (item == .object) {
                        const obj = item.object;
                        
                        // Parse range
                        const range_val = obj.get("range") orelse
continue;
                        if (range_val != .object) continue;
                        const inner_range_obj = range_val.object;
                        
                        const start_val = inner_range_obj.get("start")
orelse continue;
                        const end_val = inner_range_obj.get("end")
orelse continue;
                        if (start_val != .object or end_val != .object)
continue;
                        
                        const inner_start_obj = start_val.object;
                        const inner_end_obj = end_val.object;
                        
                        const start_line_val =
inner_start_obj.get("line") orelse continue;
                        const start_char_val =
inner_start_obj.get("character") orelse continue;
                        const end_line_val = inner_end_obj.get("line")
orelse continue;
                        const end_char_val =
inner_end_obj.get("character") orelse continue;
                        
                        if (start_line_val != .integer or start_char_val
!= .integer or
                            end_line_val != .integer or end_char_val !=
.integer) continue;
                        
                        const start_line = @as(u32,
@intCast(start_line_val.integer));
                        const start_char = @as(u32,
@intCast(start_char_val.integer));
                        const end_line = @as(u32,
@intCast(end_line_val.integer));
                        const end_char = @as(u32,
@intCast(end_char_val.integer));
                        
                        // Parse newText
                        const new_text_val = obj.get("newText") orelse
continue;
                        if (new_text_val != .string) continue;
                        const new_text_str = new_text_val.string;
                        
                        const new_text_copy = try
self.allocator.dupe(u8, new_text_str);
                        errdefer self.allocator.free(new_text_copy);
                        
                        try edits.append(TextEdit{
                            .range = Range{
                                .start = Position{ .line = start_line,
.character = start_char },
                                .end = Position{ .line = end_line,
.character = end_char },
                            },
                            .new_text = new_text_copy,
                        });
                    }
                }
                
                return try edits.toOwnedSlice();
            }
        }
        return null;
    }
    
    /// Send textDocument/didSave notification (document saved).
    /// Why: Notify LSP server that document was saved.
    /// Contract: uri must be valid, text is optional (includeText
parameter).
    pub fn didSave(self: *LspClient, uri: []const u8, text: ?[]const u8)
!void {
        // Assert: URI must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        if (text) |t| {
            std.debug.assert(t.len <= 100 * 1024 * 1024); // Bounded
text size (100MB)
        }
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        // Include text if provided
        if (text) |t| {
            try params_obj.put("text", std.json.Value{ .string = t });
        }
        
        const params = std.json.Value{ .object = params_obj };
        try self.sendNotification("textDocument/didSave", params);
    }
    
    /// Send textDocument/didClose notification (document closed).
    /// Why: Notify LSP server that document was closed.
    /// Contract: uri must be valid.
    pub fn didClose(self: *LspClient, uri: []const u8) !void {
        // Assert: URI must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        const params = std.json.Value{ .object = params_obj };
        try self.sendNotification("textDocument/didClose", params);
        
        // Remove snapshot for closed document
        var snapshot_idx: ?u32 = null;
        for (self.snapshots.items, 0..) |*snapshot, i| {
            if (std.mem.eql(u8, snapshot.uri, uri)) {
                // Assert: Index fits in u32
                std.debug.assert(i <= std.math.maxInt(u32));
                snapshot_idx = @intCast(i);
                break;
            }
        }
        
        if (snapshot_idx) |idx| {
            const snapshot = &self.snapshots.items[idx];
            self.allocator.free(snapshot.uri);
            self.allocator.free(snapshot.text);
            _ = self.snapshots.swapRemove(idx);
        }
        
        // Remove diagnostics for closed document
        if (self.diagnostics.get(uri)) |diags| {
            for (diags.items) |*diag| {
                self.allocator.free(diag.message);
                if (diag.source) |source| {
                    self.allocator.free(source);
                }
            }
            diags.deinit(self.allocator);
            _ = self.diagnostics.remove(uri);
        }
    }
    
    /// Semantic token types (for textDocument/semanticTokens).
    pub const SemanticTokenType = enum(u32) {
        namespace = 0,
        type = 1,
        class = 2,
        enum_type = 3, // Renamed from 'enum' (reserved keyword)
        interface = 4,
        struct_type = 5, // Renamed from 'struct' (reserved keyword)
        type_parameter = 6,
        parameter = 7,
        variable = 8,
        property = 9,
        enum_member = 10,
        event = 11,
        function = 12,
        method = 13,
        macro = 14,
        keyword = 15,
        modifier = 16,
        comment = 17,
        string = 18,
        number = 19,
        regexp = 20,
        operator = 21,
    };
    
    /// Semantic token modifiers (bit flags).
    pub const SemanticTokenModifiers = struct {
        pub const declaration: u32 = 1;
        pub const definition: u32 = 2;
        pub const readonly: u32 = 4;
        pub const static: u32 = 8;
        pub const deprecated: u32 = 16;
        pub const async: u32 = 32;
        pub const modification: u32 = 64;
        pub const documentation: u32 = 128;
        pub const default_library: u32 = 256;
    };
    
    /// Semantic token (for syntax highlighting).
    pub const SemanticToken = struct {
        delta_line: u32, // Line delta from previous token
        delta_start: u32, // Character delta from previous token start
        length: u32, // Token length
        token_type: u32, // Token type (SemanticTokenType)
        token_modifiers: u32, // Token modifiers (bit flags)
    };
    
    /// Request textDocument/semanticTokens/full (get all semantic
tokens).
    /// Why: Get semantic tokens for syntax highlighting based on
language server analysis.
    /// Contract: uri must be valid.
    /// Returns: Array of semantic tokens, or null if not available.
    /// Note: Caller must free the returned tokens array.
    pub fn requestSemanticTokensFull(self: *LspClient, uri: []const u8)
!?[]SemanticToken {
        // Assert: URI must be valid
        std.debug.assert(uri.len > 0);
        std.debug.assert(uri.len <= 4096); // Bounded URI length
        
        var params_obj = std.json.ObjectMap.init(self.allocator);
        defer params_obj.deinit();
        
        var text_doc_obj = std.json.ObjectMap.init(self.allocator);
        defer text_doc_obj.deinit();
        try text_doc_obj.put("uri", std.json.Value{ .string = uri });
        try params_obj.put("textDocument", std.json.Value{ .object =
text_doc_obj });
        
        const params = std.json.Value{ .object = params_obj };
        const response = try
self.sendRequest("textDocument/semanticTokens/full", params);
        
        // Parse semantic tokens from response.result
        if (response.result) |result| {
            if (result == .object) {
                const obj = result.object;
                
                // Parse data array (encoded semantic tokens)
                const data_val = obj.get("data") orelse return null;
                if (data_val != .array) return null;
                
                const data_items = data_val.array.items;
                if (data_items.len % 5 != 0) return null; // Must be
multiple of 5
                
                var tokens = try
std.ArrayList(SemanticToken).initCapacity(
                    self.allocator,
                    data_items.len / 5,
                );
                errdefer tokens.deinit();
                
                var i: u32 = 0;
                while (i < data_items.len) {
                    if (i + 4 >= data_items.len) break;
                    
                    // Parse 5 integers: deltaLine, deltaStart, length,
tokenType, tokenModifiers
                    if (data_items[i] != .integer or
                        data_items[i + 1] != .integer or
                        data_items[i + 2] != .integer or
                        data_items[i + 3] != .integer or
                        data_items[i + 4] != .integer) {
                        i += 5;
                        continue;
                    }
                    
                    const delta_line = @as(u32,
@intCast(data_items[i].integer));
                    const delta_start = @as(u32, @intCast(data_items[i +
1].integer));
                    const length = @as(u32, @intCast(data_items[i +
2].integer));
                    const token_type = @as(u32, @intCast(data_items[i +
3].integer));
                    const token_modifiers = @as(u32,
@intCast(data_items[i + 4].integer));
                    
                    try tokens.append(SemanticToken{
                        .delta_line = delta_line,
                        .delta_start = delta_start,
                        .length = length,
                        .token_type = token_type,
                        .token_modifiers = token_modifiers,
                    });
                    
                    i += 5;
                }
                
                return try tokens.toOwnedSlice();
            }
        }
        return null;
    }
    
