                            if (k == .string) blk: {
                                // Parse kind string (e.g., "comment",
"imports", "region")
                                const kind_str = k.string;
                                if (std.mem.eql(u8, kind_str,
"comment")) {
                                    break :blk
@intFromEnum(FoldingRangeKind.comment);
                                } else if (std.mem.eql(u8, kind_str,
"imports")) {
                                    break :blk
@intFromEnum(FoldingRangeKind.imports);
                                } else if (std.mem.eql(u8, kind_str,
"region")) {
