                                }
                            } else if (k == .integer) @as(u32,
@intCast(k.integer)) else null
                        else
                            null;
                        
                        try ranges.append(FoldingRange{
                            .start_line = start_line,
                            .end_line = end_line,
                            .start_character = start_char,
                            .end_character = end_char,
                            .kind = kind,
