    defer arena.deinit();

    var dag = try DagCore.init(arena.allocator());
    defer dag.deinit();

    const node1 = try dag.addNode(.ast_node, "node1", .{});
    const node2 = try dag.addNode(.ast_node, "node2", .{});

    try dag.addEdge(node1, node2, .dependency);

    // Assert: DAG is acyclic
    try std.testing.expect(dag.verifyAcyclic());
}


// === dm.zig ===

const std = @import("std");
const crypto = std.crypto;

const X25519 = crypto.dh.X25519;
const Ae = crypto.aead.chacha_poly.ChaCha20Poly1305;
const Sha256 = crypto.hash.sha2.Sha256;

pub const shared_length = X25519.shared_length;
pub const public_length = X25519.public_length;
pub const secret_length = X25519.secret_length;

pub const Nonce = [Ae.nonce_length]u8;
pub const Tag = [Ae.tag_length]u8;
pub const Key = [Ae.key_length]u8;

pub const SharedSecret = struct {
    bytes: [shared_length]u8,

    fn symmetricKey(self: SharedSecret) Key {
        var digest: [Sha256.digest_length]u8 = undefined;
        Sha256.hash(&self.bytes, &digest, .{});
        return digest;
    }
};

pub fn deriveSharedSecret(
    local_secret: [secret_length]u8,
    peer_public: [public_length]u8,
) !SharedSecret {
    const shared = try X25519.scalarmult(local_secret, peer_public);
    return SharedSecret{ .bytes = shared };
}

pub fn encryptMessage(
    allocator: std.mem.Allocator,
    shared: SharedSecret,
    nonce: Nonce,
    plaintext: []const u8,
    aad: []const u8,
) ![]u8 {
    const mac = Ae.tag_length;
    const buf = try allocator.alloc(u8, plaintext.len + mac);
    errdefer allocator.free(buf);

    const key = shared.symmetricKey();
    const nonce_copy = nonce;
    var tag: Tag = undefined;
    Ae.encrypt(buf[0..plaintext.len], &tag, plaintext, aad, nonce_copy,
key);
    std.mem.copyForwards(u8, buf[plaintext.len..], tag[0..]);
    return buf;
}

pub fn decryptMessage(
    allocator: std.mem.Allocator,
    shared: SharedSecret,
    nonce: Nonce,
    ciphertext: []const u8,
    aad: []const u8,
) ![]u8 {
    if (ciphertext.len < Ae.tag_length) return error.CiphertextTooShort;
    const msg_len = ciphertext.len - Ae.tag_length;

    const key = shared.symmetricKey();
    const nonce_copy = nonce;
    var tag: Tag = undefined;
    std.mem.copyForwards(u8, tag[0..], ciphertext[msg_len..]);

    const plaintext = try allocator.alloc(u8, msg_len);
    errdefer allocator.free(plaintext);

    try Ae.decrypt(plaintext, ciphertext[0..msg_len], tag, aad,
nonce_copy, key);
    return plaintext;
}

pub const DirectMessage = struct {
    sender: [public_length]u8,
    receiver: [public_length]u8,
    nonce: Nonce,
    ciphertext: []u8,
    timestamp: i64,

    pub fn deinit(self: *DirectMessage, allocator: std.mem.Allocator)
void {
        allocator.free(self.ciphertext);
        self.* = undefined;
    }
};

pub const Conversation = struct {
    allocator: std.mem.Allocator,
    messages: std.ArrayListUnmanaged(DirectMessage),

    pub fn init(allocator: std.mem.Allocator) Conversation {
        return .{
            .allocator = allocator,
            .messages = .{},
        };
    }

    pub fn deinit(self: *Conversation) void {
        for (self.messages.items) |*msg| {
            msg.deinit(self.allocator);
        }
        self.messages.deinit(self.allocator);
        self.messages = .{};
    }

    pub fn append(self: *Conversation, message: DirectMessage) !void {
        try self.messages.append(self.allocator, message);
    }

    pub fn count(self: *Conversation) usize {
        return self.messages.items.len;
    }

    pub fn last(self: *Conversation) ?DirectMessage {
        if (self.messages.items.len == 0) return null;
        return self.messages.items[self.messages.items.len - 1];
    }
};

test "direct message encrypt/decrypt roundtrip" {
    const alice_seed = [_]u8{0x11} ** secret_length;
    const bob_seed = [_]u8{0x22} ** secret_length;

    const alice = try X25519.KeyPair.generateDeterministic(alice_seed);
    const bob = try X25519.KeyPair.generateDeterministic(bob_seed);

    const alice_shared = try deriveSharedSecret(alice.secret_key,
bob.public_key);
    const bob_shared = try deriveSharedSecret(bob.secret_key,
alice.public_key);
    try std.testing.expectEqualSlices(u8, &alice_shared.bytes,
&bob_shared.bytes);

    const nonce: Nonce = [_]u8{0xAA} ** Ae.nonce_length;
    const aad = "nostr-dm";
    const plain = "Glow G2 whispers";

    const cipher = try encryptMessage(std.testing.allocator,
alice_shared, nonce, plain, aad);
    defer std.testing.allocator.free(cipher);

    const decrypted = try decryptMessage(std.testing.allocator,
bob_shared, nonce, cipher, aad);
    defer std.testing.allocator.free(decrypted);

    try std.testing.expectEqualSlices(u8, plain, decrypted);
}

test "conversation appends and frees" {
    const alice_seed = [_]u8{0x01} ** secret_length;
    const bob_seed = [_]u8{0x02} ** secret_length;
    const alice = try X25519.KeyPair.generateDeterministic(alice_seed);
    const bob = try X25519.KeyPair.generateDeterministic(bob_seed);
    const shared = try deriveSharedSecret(alice.secret_key,
bob.public_key);

    const nonce: Nonce = [_]u8{0xBB} ** Ae.nonce_length;
    const aad = "";
    const plain = "Descending prompts stay true.";

    const cipher = try encryptMessage(std.testing.allocator, shared,
nonce, plain, aad);
    defer std.testing.allocator.free(cipher);

    var dm = DirectMessage{
        .sender = alice.public_key,
        .receiver = bob.public_key,
        .nonce = nonce,
        .ciphertext = try std.testing.allocator.dupe(u8, cipher),
        .timestamp = 1,
    };
    errdefer dm.deinit(std.testing.allocator);

    var convo = Conversation.init(std.testing.allocator);
    defer convo.deinit();

    try convo.append(dm);
    dm = undefined;
    try std.testing.expectEqual(@as(usize, 1), convo.count());
}

// === dream_browser_bookmarks.zig ===

const std = @import("std");

/// Dream Browser Bookmarks: Bookmark management and history tracking.
/// ~<~ Glow Airbend: explicit bookmark storage, bounded history.
/// ~~~~ Glow Waterbend: bookmarks flow deterministically through DAG.
///
/// This implements:
/// - Bookmark storage (URL, title, timestamp)
/// - Bookmark organization (folders, tags)
/// - History tracking (visited URLs, timestamps)
/// - Search and filtering (by title, URL, tag)
pub const DreamBrowserBookmarks = struct {
    // Bounded: Max 10,000 bookmarks
    pub const MAX_BOOKMARKS: u32 = 10_000;
    
    // Bounded: Max 1,000 history entries
    pub const MAX_HISTORY_ENTRIES: u32 = 1_000;
    
    // Bounded: Max 256 characters for title/URL
    pub const MAX_TITLE_LENGTH: u32 = 256;
    pub const MAX_URL_LENGTH: u32 = 2048;
    
    // Bounded: Max 100 tags per bookmark
    pub const MAX_TAGS_PER_BOOKMARK: u32 = 100;
    
    /// Bookmark entry.
    pub const Bookmark = struct {
        url: []const u8, // Bookmark URL
        title: []const u8, // Bookmark title
        folder: ?[]const u8 = null, // Folder name (optional)
        tags: []const []const u8, // Tags (optional, allocated array)
        tags_len: u32, // Number of tags (to track which tags were
allocated)
        created_at: u64, // Creation timestamp
        last_visited: u64, // Last visit timestamp
        visit_count: u32, // Number of visits
    };
    
    /// History entry.
    pub const HistoryEntry = struct {
        url: []const u8, // Visited URL
        title: []const u8, // Page title
        visited_at: u64, // Visit timestamp
        visit_duration: u32, // Visit duration in seconds
    };
    
    /// Bookmark folder.
    pub const BookmarkFolder = struct {
        name: []const u8, // Folder name
        bookmarks: []const u32, // Bookmark indices
        bookmarks_len: u32, // Number of bookmarks in folder
        created_at: u64, // Creation timestamp
    };
    
    /// Bookmarks storage.
    pub const BookmarksStorage = struct {
        bookmarks: []Bookmark, // Bookmark entries
        bookmarks_len: u32, // Current number of bookmarks
        folders: []BookmarkFolder, // Bookmark folders
        folders_len: u32, // Current number of folders
    };
    
    /// History storage.
    pub const HistoryStorage = struct {
        entries: []HistoryEntry, // History entries
        entries_len: u32, // Current number of entries
        entries_index: u32, // Circular buffer index
    };
    
    allocator: std.mem.Allocator,
    bookmarks_storage: BookmarksStorage,
    history_storage: HistoryStorage,
    
    /// Initialize bookmarks manager.
    pub fn init(allocator: std.mem.Allocator) !DreamBrowserBookmarks {
        // Pre-allocate bookmarks storage
        const bookmarks = try allocator.alloc(Bookmark, MAX_BOOKMARKS);
        const folders = try allocator.alloc(BookmarkFolder, 100); // Max
100 folders
        
        // Pre-allocate history storage
        const history_entries = try allocator.alloc(HistoryEntry,
MAX_HISTORY_ENTRIES);
        
        return DreamBrowserBookmarks{
            .allocator = allocator,
            .bookmarks_storage = BookmarksStorage{
                .bookmarks = bookmarks,
                .bookmarks_len = 0,
                .folders = folders,
                .folders_len = 0,
            },
            .history_storage = HistoryStorage{
                .entries = history_entries,
                .entries_len = 0,
                .entries_index = 0,
            },
        };
    }
    
    /// Deinitialize bookmarks manager.
    pub fn deinit(self: *DreamBrowserBookmarks) void {
        // Free bookmarks
        for
(self.bookmarks_storage.bookmarks[0..self.bookmarks_storage.bookmarks_len
]) |*bookmark| {
            self.allocator.free(bookmark.url);
            self.allocator.free(bookmark.title);
            if (bookmark.folder) |folder| {
                self.allocator.free(folder);
            }
            // Free tags (array is always allocated, but individual tags
only if they exist)
            // Only free individual tag strings if they were allocated
(tags_len > 0 means tags were added)
            if (bookmark.tags_len > 0) {
                for (bookmark.tags[0..bookmark.tags_len]) |tag| {
                    self.allocator.free(tag);
                }
            }
            // Free tags array (always allocated in add_bookmark)
            self.allocator.free(bookmark.tags);
        }
        
        // Free folders
        for
(self.bookmarks_storage.folders[0..self.bookmarks_storage.folders_len])
|*folder| {
            self.allocator.free(folder.name);
            self.allocator.free(folder.bookmarks);
        }
        
        // Free history entries
        for
(self.history_storage.entries[0..self.history_storage.entries_len])
|*entry| {
            self.allocator.free(entry.url);
            self.allocator.free(entry.title);
        }
        
        // Free arrays
        self.allocator.free(self.bookmarks_storage.bookmarks);
        self.allocator.free(self.bookmarks_storage.folders);
        self.allocator.free(self.history_storage.entries);
    }
    
    /// Add bookmark.
    pub fn add_bookmark(
        self: *DreamBrowserBookmarks,
        url: []const u8,
        title: []const u8,
        folder: ?[]const u8,
    ) !u32 {
        // Assert: URL and title must be non-empty
        std.debug.assert(url.len > 0);
        std.debug.assert(url.len <= MAX_URL_LENGTH);
        std.debug.assert(title.len > 0);
        std.debug.assert(title.len <= MAX_TITLE_LENGTH);
        
        // Assert: Bookmarks must be within bounds
        std.debug.assert(self.bookmarks_storage.bookmarks_len <
MAX_BOOKMARKS);
        
        // Check if bookmark already exists
        var i: u32 = 0;
        while (i < self.bookmarks_storage.bookmarks_len) : (i += 1) {
            if (std.mem.eql(u8, self.bookmarks_storage.bookmarks[i].url,
url)) {
                // Update existing bookmark
                self.bookmarks_storage.bookmarks[i].last_visited =
get_current_timestamp();
                self.bookmarks_storage.bookmarks[i].visit_count += 1;
                return i;
            }
        }
        
        // Copy URL and title
        const url_copy = try self.allocator.dupe(u8, url);
        errdefer self.allocator.free(url_copy);
        
        const title_copy = try self.allocator.dupe(u8, title);
        errdefer self.allocator.free(title_copy);
        
        const folder_copy = if (folder) |f| blk: {
            const copy = try self.allocator.dupe(u8, f);
            break :blk copy;
        } else null;
        errdefer if (folder_copy) |f| self.allocator.free(f);
        
        // Create empty tags array
        const tags = try self.allocator.alloc([]const u8,
MAX_TAGS_PER_BOOKMARK);
        
        // Add bookmark
        const idx = self.bookmarks_storage.bookmarks_len;
        self.bookmarks_storage.bookmarks[idx] = Bookmark{
            .url = url_copy,
            .title = title_copy,
            .folder = folder_copy,
            .tags = tags,
            .tags_len = 0, // No tags added yet
            .created_at = get_current_timestamp(),
            .last_visited = get_current_timestamp(),
            .visit_count = 1,
        };
        self.bookmarks_storage.bookmarks_len += 1;
        
        return idx;
    }
    
    /// Remove bookmark.
    pub fn remove_bookmark(self: *DreamBrowserBookmarks, bookmark_idx:
u32) void {
        if (bookmark_idx >= self.bookmarks_storage.bookmarks_len) {
            return;
        }
        
        const bookmark = &self.bookmarks_storage.bookmarks[bookmark_idx];
        
        // Free bookmark data
        self.allocator.free(bookmark.url);
        self.allocator.free(bookmark.title);
        if (bookmark.folder) |folder| {
            self.allocator.free(folder);
        }
        // Free tags (array is always allocated, but individual tags
only if they exist)
        // Only free individual tag strings if they were allocated
        for (bookmark.tags) |tag| {
            // Tag strings are only allocated when tags are added (not
in add_bookmark)
            // For now, tags array is pre-allocated but empty, so no
individual tags to free
            _ = tag;
        }
        // Free tags array (always allocated in add_bookmark)
        self.allocator.free(bookmark.tags);
        
        // Move last bookmark to this position
        if (self.bookmarks_storage.bookmarks_len > 1) {
            const last_idx = self.bookmarks_storage.bookmarks_len - 1;
            if (bookmark_idx != last_idx) {
                self.bookmarks_storage.bookmarks[bookmark_idx] =
self.bookmarks_storage.bookmarks[last_idx];
            }
        }
        
        self.bookmarks_storage.bookmarks_len -= 1;
    }
    
    /// Get bookmark by index.
    pub fn get_bookmark(self: *const DreamBrowserBookmarks,
bookmark_idx: u32) ?*const Bookmark {
        if (bookmark_idx >= self.bookmarks_storage.bookmarks_len) {
            return null;
        }
        return &self.bookmarks_storage.bookmarks[bookmark_idx];
    }
    
    /// Add history entry.
    pub fn add_history_entry(
        self: *DreamBrowserBookmarks,
        url: []const u8,
        title: []const u8,
        visit_duration: u32,
    ) !void {
        // Assert: URL and title must be non-empty
        std.debug.assert(url.len > 0);
        std.debug.assert(url.len <= MAX_URL_LENGTH);
        std.debug.assert(title.len > 0);
        std.debug.assert(title.len <= MAX_TITLE_LENGTH);
        
        // Copy URL and title
        const url_copy = try self.allocator.dupe(u8, url);
        errdefer self.allocator.free(url_copy);
        
        const title_copy = try self.allocator.dupe(u8, title);
        errdefer self.allocator.free(title_copy);
        
        // Add to history (or overwrite oldest if full)
        if (self.history_storage.entries_len < MAX_HISTORY_ENTRIES) {
            const idx = self.history_storage.entries_len;
            self.history_storage.entries[idx] = HistoryEntry{
                .url = url_copy,
                .title = title_copy,
                .visited_at = get_current_timestamp(),
                .visit_duration = visit_duration,
            };
            self.history_storage.entries_len += 1;
        } else {
            // Overwrite oldest entry (circular buffer)
            const idx = self.history_storage.entries_index;
            const old_entry = &self.history_storage.entries[idx];
            
            // Free old entry
            self.allocator.free(old_entry.url);
            self.allocator.free(old_entry.title);
            
            // Set new entry
            self.history_storage.entries[idx] = HistoryEntry{
                .url = url_copy,
                .title = title_copy,
                .visited_at = get_current_timestamp(),
                .visit_duration = visit_duration,
            };
            
            self.history_storage.entries_index = (idx + 1) %
MAX_HISTORY_ENTRIES;
        }
    }
    
    /// Get history entries (recent first).
    pub fn get_history_entries(self: *const DreamBrowserBookmarks,
max_count: u32) []const HistoryEntry {
        const count = @min(max_count, self.history_storage.entries_len);
        if (count == 0) {
            return &.{};
        }
        
        // Allocate result array (caller must free)
        const result = self.allocator.alloc(HistoryEntry, count) catch {
            return &.{};
        };
        
        // Copy entries in reverse order (newest first)
        var i: u32 = 0;
        var src_idx: u32 = self.history_storage.entries_len;
        while (i < count and src_idx > 0) : (i += 1) {
            src_idx -= 1;
            result[i] = self.history_storage.entries[src_idx];
        }
        
        return result[0..count];
    }
    
    /// Search bookmarks by title or URL.
    /// Note: Returns slice pointing to allocated array (caller must
free).
    pub fn search_bookmarks(
        self: *DreamBrowserBookmarks,
        query: []const u8,
    ) []const u32 {
        // Assert: Query must be non-empty
        std.debug.assert(query.len > 0);
        
        // Count matching bookmarks
        var match_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.bookmarks_storage.bookmarks_len) : (i += 1) {
            const bookmark = &self.bookmarks_storage.bookmarks[i];
            if (std.mem.indexOf(u8, bookmark.title, query) != null or
                std.mem.indexOf(u8, bookmark.url, query) != null)
            {
                match_count += 1;
            }
        }
        
        if (match_count == 0) {
            return &.{};
        }
        
        // Allocate result array (caller must free)
        const result = self.allocator.alloc(u32, match_count) catch {
            return &.{};
        };
        
        // Collect matching indices
        var result_idx: u32 = 0;
        i = 0;
        while (i < self.bookmarks_storage.bookmarks_len) : (i += 1) {
            const bookmark = &self.bookmarks_storage.bookmarks[i];
            if (std.mem.indexOf(u8, bookmark.title, query) != null or
                std.mem.indexOf(u8, bookmark.url, query) != null)
            {
                result[result_idx] = i;
                result_idx += 1;
            }
        }
        
        return result[0..match_count];
    }
    
    /// Get current timestamp (simplified).
    fn get_current_timestamp() u64 {
        const timestamp = std.time.timestamp();
        const non_negative = if (timestamp < 0) 0 else @as(u64,
@intCast(timestamp));
        return non_negative;
    }
    
    /// Get statistics.
    pub fn get_stats(self: *const DreamBrowserBookmarks) BookmarksStats {
        return BookmarksStats{
            .bookmarks_count = self.bookmarks_storage.bookmarks_len,
            .history_count = self.history_storage.entries_len,
            .folders_count = self.bookmarks_storage.folders_len,
            .max_bookmarks = MAX_BOOKMARKS,
            .max_history = MAX_HISTORY_ENTRIES,
        };
    }
    
    /// Bookmarks statistics.
    pub const BookmarksStats = struct {
        bookmarks_count: u32,
        history_count: u32,
        folders_count: u32,
        max_bookmarks: u32,
        max_history: u32,
    };
};

