// === dream_browser_nostr.zig ===

//! Dream Browser Nostr Content Loading: Parse URLs, subscribe to
events, render to browser.
//! ~<~ Glow Airbend: explicit URL parsing, bounded subscriptions.
//! ~~~~ Glow Waterbend: streaming events flow deterministically through
DAG.
//!
//! This implements:
//! - Parse Nostr URLs (`nostr:note1...`, `nostr:npub1...`)
//! - Subscribe to Nostr events
//! - Receive events (streaming, real-time)
//! - Render events to browser
//! - DAG event integration
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded structures: fixed-size buffers (no dynamic allocation
after init)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-01-XX
//! GrainStyle: Comprehensive Nostr integration, deterministic behavior,
explicit limits

const std = @import("std");
const DreamProtocol = @import("dream_protocol.zig").DreamProtocol;
const BrowserDagIntegration =
@import("dream_browser_dag_integration.zig").BrowserDagIntegration;
const DreamBrowserRenderer =
@import("dream_browser_renderer.zig").DreamBrowserRenderer;

/// Dream Browser Nostr Content Loader: Parse URLs, subscribe, receive,
render.
/// Why: Enable Nostr content loading in browser with DAG integration.
/// GrainStyle: Explicit types, bounded subscriptions, deterministic
behavior.
pub const DreamBrowserNostr = struct {
    allocator: std.mem.Allocator,
    protocol: DreamProtocol,
    browser_dag: *BrowserDagIntegration,
    renderer: *DreamBrowserRenderer,
    
    /// Bounded: Max 100 active subscriptions.
    /// Why: Prevent unbounded growth, ensure deterministic behavior.
    pub const MAX_SUBSCRIPTIONS: u32 = 100;
    
    /// Bounded: Max 1,000 events per subscription.
    /// Why: Limit event buffer size, prevent memory growth.
    pub const MAX_EVENTS_PER_SUBSCRIPTION: u32 = 1_000;
    
    /// Bounded: Max URL length (4KB).
    /// Why: Prevent unbounded URL parsing, ensure deterministic
behavior.
    pub const MAX_URL_LENGTH: u32 = 4 * 1024;
    
    /// Bounded: Max identifier length (256 chars).
    /// Why: Limit identifier size, prevent memory growth.
    pub const MAX_IDENTIFIER_LENGTH: u32 = 256;
    
    /// Bounded: Max relay URLs per subscription (10).
    /// Why: Limit relay count, prevent memory growth.
    pub const MAX_RELAYS_PER_URL: u32 = 10;
    
    /// Nostr URL type.
    pub const NostrUrlType = enum(u8) {
        note, // nostr:note1... (event ID)
        npub, // nostr:npub1... (public key)
        nprofile, // nostr:nprofile1... (profile)
        nevent, // nostr:nevent1... (event with relays)
    };
    
    /// Parsed Nostr URL.
    pub const NostrUrl = struct {
        url_type: NostrUrlType,
        identifier: []const u8, // Note ID, pubkey, etc.
        relays: []const []const u8, // Optional relay URLs
    };
    
    /// Active subscription.
    pub const Subscription = struct {
        subscription_id: []const u8,
        url: NostrUrl,
        events: []DreamProtocol.Event,
        events_len: u32,
    };
    
    /// Initialize Nostr content loader.
    /// Why: Set up Nostr integration for browser content loading.
    /// Contract: allocator must be valid, browser_dag and renderer must
be initialized.
    pub fn init(
        allocator: std.mem.Allocator,
        browser_dag: *BrowserDagIntegration,
        renderer: *DreamBrowserRenderer,
    ) DreamBrowserNostr {
        // Assert: Browser DAG must be initialized (precondition).
        std.debug.assert(browser_dag.dag.nodes_len <=
BrowserDagIntegration.MAX_DOM_NODES_PER_PAGE);
        
        return DreamBrowserNostr{
            .allocator = allocator,
            .protocol = DreamProtocol.init(allocator),
            .browser_dag = browser_dag,
            .renderer = renderer,
        };
    }
    
    /// Deinitialize Nostr content loader.
    pub fn deinit(self: *DreamBrowserNostr) void {
        self.protocol.deinit();
    }
    
    /// Parse Nostr URL (`nostr:note1...`, `nostr:npub1...`, etc.).
    /// Why: Extract identifier and type from Nostr URL.
    /// Contract: url must be valid Nostr URL, returns parsed URL.
    pub fn parseNostrUrl(self: *DreamBrowserNostr, url: []const u8)
!NostrUrl {
        // Assert: URL must be non-empty (precondition).
        if (url.len == 0) {
            return error.InvalidNostrUrl;
        }
        
        // Assert: URL must be within bounds (precondition).
        if (url.len > MAX_URL_LENGTH) {
            return error.UrlTooLong;
        }
        
        // Assert: URL must start with "nostr:" (precondition).
        if (!std.mem.startsWith(u8, url, "nostr:")) {
            return error.InvalidNostrUrl;
        }
        
        // Extract identifier (after "nostr:").
        const identifier = url[6..]; // Skip "nostr:"
        
        // Assert: Identifier must be within bounds (precondition).
        if (identifier.len > MAX_IDENTIFIER_LENGTH) {
            return error.IdentifierTooLong;
        }
        
        // Determine URL type based on prefix.
        var url_type: NostrUrlType = undefined;
        
        if (std.mem.startsWith(u8, identifier, "note1")) {
            // Event ID (bech32-encoded).
            url_type = .note;
        } else if (std.mem.startsWith(u8, identifier, "npub1")) {
            // Public key (bech32-encoded).
            url_type = .npub;
        } else if (std.mem.startsWith(u8, identifier, "nprofile1")) {
            // Profile (bech32-encoded).
            url_type = .nprofile;
        } else if (std.mem.startsWith(u8, identifier, "nevent1")) {
            // Event with relays (bech32-encoded).
            url_type = .nevent;
        } else {
            return error.InvalidNostrUrl;
        }
        
        // Parse relays (if present in URL, e.g.,
"nostr:note1...?relay=wss://...").
        var relays = std.ArrayList([]const u8).init(self.allocator);
        defer relays.deinit();
        try relays.ensureTotalCapacity(self.allocator,
MAX_RELAYS_PER_URL);
        
        // Check for query parameters.
        if (std.mem.indexOfScalar(u8, identifier, '?')) |query_start| {
            const query = identifier[query_start + 1..];
            
            // Parse relay parameters (simple: "relay=wss://...").
            var query_it = std.mem.splitScalar(u8, query, '&');
            var relay_count: u32 = 0;
            while (query_it.next()) |param| {
                // Assert: Relay count must be within bounds.
                if (relay_count >= MAX_RELAYS_PER_URL) {
                    break; // Stop parsing if max relays reached
                }
                
                if (std.mem.startsWith(u8, param, "relay=")) {
                    const relay_url = param[6..]; // Skip "relay="
                    
                    // Assert: Relay URL must be non-empty.
                    if (relay_url.len == 0) {
                        continue; // Skip empty relay URLs
                    }
                    
                    try relays.append(try self.allocator.dupe(u8,
relay_url));
                    relay_count += 1;
                }
            }
        }
        
        // Assert: URL type must be determined (postcondition).
        std.debug.assert(@intFromEnum(url_type) >= 0);
        
        return NostrUrl{
            .url_type = url_type,
            .identifier = try self.allocator.dupe(u8, identifier),
            .relays = try relays.toOwnedSlice(),
        };
    }
    
    /// Subscribe to Nostr events based on URL.
    /// Why: Create subscription for Nostr content loading.
    /// Contract: url must be valid parsed URL, returns subscription ID.
    pub fn subscribeToNostr(
        self: *DreamBrowserNostr,
        url: NostrUrl,
        relay_url: []const u8,
    ) ![]const u8 {
        // Assert: URL must be valid (precondition).
        if (url.identifier.len == 0) {
            return error.InvalidNostrUrl;
        }
        
        // Assert: Relay URL must be non-empty (precondition).
        if (relay_url.len == 0) {
            return error.InvalidNostrUrl;
        }
        
        // Assert: Relay URL must be within bounds (precondition).
        if (relay_url.len > MAX_URL_LENGTH) {
            return error.UrlTooLong;
        }
        
        // Connect to relay if not connected.
        if (self.protocol.state != .connected) {
            try self.protocol.connect(relay_url);
        }
        
        // Assert: Protocol must be connected (postcondition).
        std.debug.assert(self.protocol.state == .connected);
        
        // Create subscription ID (unique identifier).
        const subscription_id = try std.fmt.allocPrint(
            self.allocator,
            "sub_{d}",
            .{std.time.timestamp()},
        );
        
        // Build filter based on URL type.
        var filters =
std.ArrayList(DreamProtocol.Filter).init(self.allocator);
        defer filters.deinit();
        
        var filter = DreamProtocol.Filter{};
        
        switch (url.url_type) {
            .note => {
                // Subscribe to specific event ID.
                // Note: identifier is bech32-encoded, need to decode to
hex.
                // For now, use identifier as-is (simplified).
                const event_ids = [_][]const u8{url.identifier};
                filter.ids = &event_ids;
            },
            .npub => {
                // Subscribe to events from specific author.
                const authors = [_][]const u8{url.identifier};
                filter.authors = &authors;
            },
            .nprofile => {
                // Subscribe to profile metadata (kind 0).
                const authors = [_][]const u8{url.identifier};
                filter.authors = &authors;
                const kinds = [_]u32{0}; // Metadata
                filter.kinds = &kinds;
            },
            .nevent => {
                // Subscribe to specific event (with relay hints).
                const event_ids = [_][]const u8{url.identifier};
                filter.ids = &event_ids;
            },
        }
        
        try filters.append(filter);
        
        // Subscribe via protocol.
        try self.protocol.subscribe(subscription_id, try
filters.toOwnedSlice());
        
        // Assert: Subscription must be created (postcondition).
        std.debug.assert(subscription_id.len > 0);
        
        return subscription_id;
    }
    
    /// Receive events (streaming, real-time).
    /// Why: Process incoming Nostr events from relay.
    /// Contract: subscription_id must be valid, returns array of events.
    pub fn receiveEvents(
        self: *DreamBrowserNostr,
        subscription_id: []const u8,
    ) ![]DreamProtocol.Event {
        // Assert: Subscription ID must be valid (precondition).
        if (subscription_id.len == 0) {
            return error.InvalidNostrUrl;
        }
        
        // Assert: Subscription ID must be within bounds (precondition).
        if (subscription_id.len > MAX_IDENTIFIER_LENGTH) {
            return error.IdentifierTooLong;
        }
        
        // Assert: Protocol must be connected (precondition).
        if (self.protocol.state != .connected) {
            return error.ProtocolNotConnected;
        }
        
        // TODO: Read events from WebSocket stream.
        // For now, return empty array (stub).
        _ = subscription_id;
        
        // Create events array (bounded).
        var events =
std.ArrayList(DreamProtocol.Event).init(self.allocator);
        defer events.deinit();
        
        // Assert: Events must be within bounds (postcondition).
        std.debug.assert(events.items.len <=
MAX_EVENTS_PER_SUBSCRIPTION);
        
        return try events.toOwnedSlice();
    }
    
    /// Render events to browser (convert to DOM nodes).
    /// Why: Display Nostr events in browser with readonly spans for
metadata.
    /// Contract: events must be valid, returns DOM node.
    pub fn renderEventsToBrowser(
        self: *DreamBrowserNostr,
        events: []const DreamProtocol.Event,
    ) !BrowserDagIntegration.DomNode {
        // Assert: Events must be valid (precondition).
        std.debug.assert(events.len <= MAX_EVENTS_PER_SUBSCRIPTION);
        
        // Create root DOM node (div container).
        var children =
std.ArrayList(BrowserDagIntegration.DomNode).init(self.allocator);
        defer children.deinit();
        
        // Render each event as a DOM node.
        for (events) |event| {
            const event_dom = try self.renderEventToDom(event);
            try children.append(event_dom);
        }
        
        // Create root container.
        const root_attributes =
[_]BrowserDagIntegration.DomNode.Attribute{};
        
        return BrowserDagIntegration.DomNode{
            .tag_name = "div",
            .attributes = &root_attributes,
            .children = try children.toOwnedSlice(),
            .text_content = "",
            .parent_id = null,
        };
    }
    
    /// Render single event to DOM node.
    /// Why: Convert Nostr event to DOM structure with readonly spans.
    /// Contract: event must be valid, returns DOM node.
    fn renderEventToDom(
        self: *DreamBrowserNostr,
        event: DreamProtocol.Event,
    ) !BrowserDagIntegration.DomNode {
        // Assert: Event must be valid (precondition).
        std.debug.assert(event.id.len > 0);
        std.debug.assert(event.pubkey.len > 0);
        
        // Create event container (div with metadata attributes).
        var attributes =
std.ArrayList(BrowserDagIntegration.DomNode.Attribute).init(self.allocato
r);
        defer attributes.deinit();
        
        // Add readonly metadata attributes (event ID, timestamp,
author).
        try attributes.append(BrowserDagIntegration.DomNode.Attribute{
            .name = "data-event-id",
            .value = event.id,
        });
        
        try attributes.append(BrowserDagIntegration.DomNode.Attribute{
            .name = "data-timestamp",
            .value = try std.fmt.allocPrint(self.allocator, "{d}",
.{event.created_at}),
        });
        
        try attributes.append(BrowserDagIntegration.DomNode.Attribute{
            .name = "data-author",
            .value = event.pubkey,
        });
        
        // Create content node (paragraph with event content).
        const content_attributes =
[_]BrowserDagIntegration.DomNode.Attribute{};
        const content_node = BrowserDagIntegration.DomNode{
            .tag_name = "p",
            .attributes = &content_attributes,
            .children = &.{},
            .text_content = event.content,
            .parent_id = null,
        };
        
        // Create event container with content.
        const event_children =
[_]BrowserDagIntegration.DomNode{content_node};
        
        return BrowserDagIntegration.DomNode{
            .tag_name = "div",
            .attributes = try attributes.toOwnedSlice(),
            .children = &event_children,
            .text_content = "",
            .parent_id = null,
        };
    }
    
    /// Integrate events into DAG (map events to DAG events).
    /// Why: Track Nostr events in unified DAG state.
    /// Contract: events must be valid.
    pub fn integrateEventsToDag(
        self: *DreamBrowserNostr,
        events: []const DreamProtocol.Event,
    ) !void {
        // Assert: Events must be valid (precondition).
        std.debug.assert(events.len <= MAX_EVENTS_PER_SUBSCRIPTION);
        
        // Map each event to DAG event.
        for (events) |event| {
            // Get parent events (empty for now, could reference
previous events).
            const parent_events = [_]u64{};
            
            // Map event to DAG via browser-DAG integration.
            _ = try self.browser_dag.mapNostrEventToDag(event,
&parent_events);
        }
        
        // Assert: Events must be integrated (postcondition).
        // Events are now in DAG pending events.
    }
};


// === dream_browser_parser.zig ===

const std = @import("std");
const BrowserDagIntegration =
@import("dream_browser_dag_integration.zig").BrowserDagIntegration;

/// Dream Browser Parser: HTML/CSS parser for Zig-native browser.
/// ~<~ Glow Airbend: explicit parsing, bounded tree depth.
/// ~~~~ Glow Waterbend: parsing flows deterministically through DAG.
///
/// This implements a subset of HTML5 and CSS3:
/// - HTML parser (subset: div, span, p, a, img, etc.)
/// - CSS parser (subset: color, background, font-size, etc.)
/// - DOM tree construction (bounded depth, explicit nodes)
/// - Style computation (cascade, specificity)
pub const DreamBrowserParser = struct {
    allocator: std.mem.Allocator,
    
    // Bounded: Max 100 tree depth
    pub const MAX_TREE_DEPTH: u32 = 100;
    
    // Bounded: Max 10,000 DOM nodes per page
    pub const MAX_DOM_NODES: u32 = 10_000;
    
    // Bounded: Max 1,000 CSS rules per stylesheet
    pub const MAX_CSS_RULES: u32 = 1_000;
    
    // Bounded: Max HTML input size (10MB)
    pub const MAX_HTML_SIZE: u32 = 10 * 1024 * 1024;
    
    // Bounded: Max tag name length (64 chars)
    pub const MAX_TAG_NAME_LEN: u32 = 64;
    
    // Bounded: Max 100 attributes per tag
    pub const MAX_ATTRIBUTES: u32 = 100;
    
    // Bounded: Max attribute name length (256 chars)
    pub const MAX_ATTR_NAME_LEN: u32 = 256;
    
    // Bounded: Max attribute value length (4KB)
    pub const MAX_ATTR_VALUE_LEN: u32 = 4 * 1024;
    
    /// HTML element node (DOM node).
    pub const HtmlNode = struct {
        tag_name: []const u8, // "div", "span", "p", etc.
        attributes: []const Attribute,
        children: []const HtmlNode,
        text_content: []const u8, // Text content (for text nodes)
        parent: ?*HtmlNode = null,
        depth: u32 = 0, // Tree depth (for bounds checking)
    };
    
    /// HTML attribute.
    pub const Attribute = struct {
        name: []const u8,
        value: []const u8,
    };
    
    /// CSS rule (selector + declarations).
    pub const CssRule = struct {
        selector: []const u8, // "div", ".class", "#id", etc.
        declarations: []const Declaration,
    };
    
    /// CSS declaration (property + value).
    pub const Declaration = struct {
        property: []const u8, // "color", "background", "font-size", etc.
        value: []const u8, // "red", "#ff0000", "16px", etc.
    };
    
    /// Initialize parser.
    pub fn init(allocator: std.mem.Allocator) DreamBrowserParser {
        return DreamBrowserParser{
            .allocator = allocator,
        };
    }
    
    /// Deinitialize parser.
    pub fn deinit(self: *DreamBrowserParser) void {
        // No dynamic allocation to clean up
        _ = self;
    }
    
    /// Parse HTML string into DOM tree.
    pub fn parseHtml(
        self: *DreamBrowserParser,
        html: []const u8,
    ) !HtmlNode {
        // Assert: HTML must be non-empty
        std.debug.assert(html.len > 0);
        
        // Bounded: Max HTML input size
        if (html.len > MAX_HTML_SIZE) {
            return error.HtmlTooLarge;
        }
        
        // Simple HTML parser (subset of HTML5)
        // For now, parse basic structure: <tag>content</tag>
        // TODO: Implement full HTML5 parser
        
        // Find first tag
        const tag_start = std.mem.indexOf(u8, html, "<") orelse return
error.InvalidHtml;
        const tag_end = std.mem.indexOf(u8, html[tag_start..], ">")
orelse return error.InvalidHtml;
        
        // Assert: Tag must be valid
        std.debug.assert(tag_end > 0);
        std.debug.assert(tag_start + tag_end < html.len);
        
        const tag_str = html[tag_start + 1..tag_start + tag_end];
        
        // Assert: Tag string must be non-empty
        std.debug.assert(tag_str.len > 0);
        
        // Bounded: Max tag name length
        if (tag_str.len > MAX_TAG_NAME_LEN) {
            return error.TagNameTooLong;
        }
        
        // Parse tag name and attributes
        const space_idx = std.mem.indexOfScalar(u8, tag_str, ' ') orelse
tag_str.len;
        const tag_name = tag_str[0..space_idx];
        
        // Assert: Tag name must be non-empty
        std.debug.assert(tag_name.len > 0);
        
        // Parse attributes (simple: name="value")
        // Bounded: Max attributes per tag
        var attributes = std.ArrayList(Attribute){ .items = &.{},
.capacity = 0 };
        defer attributes.deinit(self.allocator);
        try attributes.ensureTotalCapacity(self.allocator, 10);
        
        var attr_start = space_idx;
        while (attr_start < tag_str.len) {
            // Bounded: Max attributes
            if (attributes.items.len >= MAX_ATTRIBUTES) {
                break;
            }
            
            // Skip whitespace
            while (attr_start < tag_str.len and tag_str[attr_start] == '
') {
                attr_start += 1;
            }
            if (attr_start >= tag_str.len) break;
            
            // Find attribute name
            const attr_name_start = attr_start;
            const attr_name_end = std.mem.indexOfScalar(u8,
tag_str[attr_name_start..], '=') orelse break;
            const attr_name = tag_str[attr_name_start..attr_name_start +
attr_name_end];
            
            // Bounded: Max attribute name length
            if (attr_name.len > MAX_ATTR_NAME_LEN) {
                return error.AttributeNameTooLong;
            }
            
            // Find attribute value
            const attr_value_start = attr_name_start + attr_name_end +
2; // Skip '='
            if (attr_value_start >= tag_str.len) break;
            
            // Assert: Attribute value must start with quote
            if (attr_value_start > 0 and tag_str[attr_value_start - 1]
!= '"') {
                return error.InvalidAttribute;
            }
            
            const attr_value_end = std.mem.indexOfScalar(u8,
tag_str[attr_value_start..], '"') orelse break;
            const attr_value =
tag_str[attr_value_start..attr_value_start + attr_value_end];
            
            // Bounded: Max attribute value length
            if (attr_value.len > MAX_ATTR_VALUE_LEN) {
                return error.AttributeValueTooLong;
            }
            
            try attributes.append(Attribute{
                .name = try self.allocator.dupe(u8, attr_name),
                .value = try self.allocator.dupe(u8, attr_value),
            });
            
            attr_start = attr_value_start + attr_value_end + 1;
        }
        
        // Find closing tag
        const closing_tag = try std.fmt.allocPrint(self.allocator,
"</{s}>", .{tag_name});
        defer self.allocator.free(closing_tag);
        
        const content_start = tag_start + tag_end + 1;
        const content_end = std.mem.indexOf(u8, html[content_start..],
closing_tag) orelse html.len;
        const content = html[content_start..content_start + content_end];
        
        // Create HTML node
        const node = HtmlNode{
            .tag_name = try self.allocator.dupe(u8, tag_name),
            .attributes = try attributes.toOwnedSlice(),
            .children = &.{}, // TODO: Parse children recursively
            .text_content = try self.allocator.dupe(u8, content),
            .parent = null,
            .depth = 0,
        };
        
        // Assert: Tree depth must be within bounds
        std.debug.assert(node.depth < MAX_TREE_DEPTH);
        
        return node;
    }
    
    /// Parse CSS string into rules.
    pub fn parseCss(
        self: *DreamBrowserParser,
        css: []const u8,
    ) ![]const CssRule {
        // Assert: CSS must be non-empty
        std.debug.assert(css.len > 0);
        
        // Simple CSS parser (subset of CSS3)
        // For now, parse basic structure: selector { property: value; }
        // TODO: Implement full CSS3 parser
        
        // Pre-allocate capacity (optimization: reduce reallocations)
        var rules = std.ArrayList(CssRule){ .items = &.{}, .capacity = 0
};
        defer rules.deinit(self.allocator);
        try rules.ensureTotalCapacity(self.allocator,
@min(MAX_CSS_RULES, 50)); // Pre-allocate for common case
        
        // Find first rule
        var pos: usize = 0;
        while (pos < css.len) {
            // Skip whitespace
            while (pos < css.len and (css[pos] == ' ' or css[pos] ==
'\n' or css[pos] == '\t')) {
                pos += 1;
            }
            if (pos >= css.len) break;
            
            // Find selector
            const selector_start = pos;
            const selector_end = std.mem.indexOfScalar(u8,
css[selector_start..], '{') orelse break;
            const selector = css[selector_start..selector_start +
selector_end];
            
            // Find declarations
            const decl_start = selector_start + selector_end + 1;
            const decl_end = std.mem.indexOfScalar(u8,
css[decl_start..], '}') orelse break;
            const decl_str = css[decl_start..decl_start + decl_end];
            
            // Parse declarations (simple: property: value;)
            // Pre-allocate capacity (optimization: reduce reallocations)
            var declarations = std.ArrayList(Declaration){ .items =
&.{}, .capacity = 0 };
            defer declarations.deinit(self.allocator);
            try declarations.ensureTotalCapacity(self.allocator, 10); //
Pre-allocate for common case
            
            var decl_pos: usize = 0;
            while (decl_pos < decl_str.len) {
                // Skip whitespace
                while (decl_pos < decl_str.len and (decl_str[decl_pos]
== ' ' or decl_str[decl_pos] == '\n' or decl_str[decl_pos] == '\t')) {
                    decl_pos += 1;
                }
                if (decl_pos >= decl_str.len) break;
                
                // Find property
                const prop_start = decl_pos;
                const prop_end = std.mem.indexOfScalar(u8,
decl_str[prop_start..], ':') orelse break;
                const property = decl_str[prop_start..prop_start +
prop_end];
                
                // Find value
                const value_start = prop_start + prop_end + 1;
                const value_end = std.mem.indexOfScalar(u8,
decl_str[value_start..], ';') orelse decl_str.len;
                const value = decl_str[value_start..value_start +
value_end];
                
                try declarations.append(Declaration{
                    .property = try self.allocator.dupe(u8, property),
                    .value = try self.allocator.dupe(u8, value),
                });
                
                decl_pos = value_start + value_end + 1;
            }
            
            // Create CSS rule
            try rules.append(CssRule{
                .selector = try self.allocator.dupe(u8, selector),
                .declarations = try declarations.toOwnedSlice(),
            });
            
            // Assert: Rule count must be within bounds
            std.debug.assert(rules.items.len <= MAX_CSS_RULES);
            
            pos = decl_start + decl_end + 1;
        }
        
        return try rules.toOwnedSlice();
    }
    
    /// Compute styles for HTML node (cascade, specificity).
    pub fn computeStyles(
        self: *DreamBrowserParser,
        node: *const HtmlNode,
        css_rules: []const CssRule,
    ) ![]const Declaration {
        // Assert: Node and CSS rules must be valid
        std.debug.assert(node.tag_name.len > 0);
        
        // Simple style computation (cascade, specificity)
        // For now, match selectors to node tag name
        // TODO: Implement full CSS cascade and specificity
        
        var styles = std.ArrayList(Declaration).init(self.allocator);
        defer styles.deinit();
        
        // Match CSS rules to node
        for (css_rules) |rule| {
            // Simple selector matching (tag name only)
            if (std.mem.eql(u8, rule.selector, node.tag_name)) {
                // Add declarations to styles
                try styles.appendSlice(rule.declarations);
            }
        }
        
        return try styles.toOwnedSlice();
    }
    
    /// Convert HTML node to BrowserDagIntegration.DomNode (for DAG
integration).
    pub fn toDomNode(
        self: *DreamBrowserParser,
        html_node: *const HtmlNode,
    ) !BrowserDagIntegration.DomNode {
        // Assert: HTML node must be valid
        std.debug.assert(html_node.tag_name.len > 0);
        
        // Convert attributes
        var attributes =
std.ArrayList(BrowserDagIntegration.DomNode.Attribute).init(self.allocato
r);
        defer attributes.deinit();
        
        for (html_node.attributes) |attr| {
            try
attributes.append(BrowserDagIntegration.DomNode.Attribute{
                .name = attr.name,
                .value = attr.value,
            });
        }
        
        // Convert children (recursive)
        var children =
std.ArrayList(BrowserDagIntegration.DomNode).init(self.allocator);
        defer children.deinit();
        
        for (html_node.children) |child| {
            const child_dom = try self.toDomNode(&child);
            try children.append(child_dom);
        }
        
        return BrowserDagIntegration.DomNode{
            .tag_name = html_node.tag_name,
            .attributes = try attributes.toOwnedSlice(),
            .children = try children.toOwnedSlice(),
            .text_content = html_node.text_content,
            .parent_id = null, // Will be set by DAG integration
        };
    }
};

test "browser parser initialization" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var parser = DreamBrowserParser.init(arena.allocator());
    defer parser.deinit();
    
    // Assert: Parser initialized (check via usage)
    _ = parser.allocator;
}

test "browser parser parse html" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var parser = DreamBrowserParser.init(arena.allocator());
    defer parser.deinit();
    
    const html = "<div>Hello, World!</div>";
    const node = try parser.parseHtml(html);
    defer {
        parser.allocator.free(node.tag_name);
        parser.allocator.free(node.text_content);
        for (node.attributes) |attr| {
            parser.allocator.free(attr.name);
            parser.allocator.free(attr.value);
        }
        parser.allocator.free(node.attributes);
    }
    
    // Assert: Node parsed correctly
    try std.testing.expect(std.mem.eql(u8, node.tag_name, "div"));
    try std.testing.expect(std.mem.eql(u8, node.text_content, "Hello,
World!"));
}

test "browser parser parse css" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var parser = DreamBrowserParser.init(arena.allocator());
    defer parser.deinit();
    
    const css = "div { color: red; background: blue; }";
    const rules = try parser.parseCss(css);
    defer {
        for (rules) |rule| {
            parser.allocator.free(rule.selector);
            for (rule.declarations) |decl| {
                parser.allocator.free(decl.property);
                parser.allocator.free(decl.value);
            }
            parser.allocator.free(rule.declarations);
        }
        parser.allocator.free(rules);
    }
    
    // Assert: Rules parsed correctly
    try std.testing.expect(rules.len == 1);
    try std.testing.expect(std.mem.eql(u8, rules[0].selector, "div"));
    try std.testing.expect(rules[0].declarations.len == 2);
}


// === dream_browser_performance.zig ===

const std = @import("std");

/// Dream Browser Performance: Frame rate control, performance
monitoring, rendering optimization.
/// ~<~ Glow Airbend: explicit frame timing, bounded performance metrics.
/// ~~~~ Glow Waterbend: performance flows deterministically through DAG.
///
/// This implements:
/// - Frame rate control (60fps target, frame timing)
/// - Performance monitoring (frame time, render time, layout time)
/// - Rendering optimization (skip frames if behind, adaptive quality)
/// - Performance metrics (FPS, frame time, render time statistics)
pub const DreamBrowserPerformance = struct {
    // Target frame rate: 60fps (16.67ms per frame)
    pub const TARGET_FPS: u32 = 60;
    pub const TARGET_FRAME_TIME_MS: u32 = 1000 / TARGET_FPS; // ~16.67ms
    
    // Bounded: Max 1000 frames in history
    pub const MAX_FRAME_HISTORY: u32 = 1000;
    
    // Bounded: Max 10,000ms frame time (10 seconds, for error detection)
    pub const MAX_FRAME_TIME_MS: u32 = 10_000;
    
    /// Frame timing information.
    pub const FrameTiming = struct {
        frame_start_time: u64, // Timestamp in milliseconds
        frame_end_time: u64, // Timestamp in milliseconds
        render_time_ms: u32, // Time spent rendering
        layout_time_ms: u32, // Time spent in layout
        total_time_ms: u32, // Total frame time
    };
    
    /// Performance metrics (aggregated statistics).
    pub const PerformanceMetrics = struct {
        frames_rendered: u32, // Total frames rendered
        average_fps: f32, // Average frames per second
        average_frame_time_ms: f32, // Average frame time in milliseconds
        average_render_time_ms: f32, // Average render time in
milliseconds
        average_layout_time_ms: f32, // Average layout time in
milliseconds
        min_frame_time_ms: u32, // Minimum frame time
        max_frame_time_ms: u32, // Maximum frame time
        dropped_frames: u32, // Frames dropped (exceeded target time)
    };
    
    /// Frame history (for performance analysis).
    pub const FrameHistory = struct {
        timings: []FrameTiming, // Frame timing history
        timings_len: u32, // Current number of frames
        timings_index: u32, // Circular buffer index
    };
    
    allocator: std.mem.Allocator,
    frame_history: FrameHistory,
    current_frame_start: u64, // Current frame start time
    last_frame_time: u64, // Last frame end time
    metrics: PerformanceMetrics,
    
    /// Initialize performance monitor.
    pub fn init(allocator: std.mem.Allocator) DreamBrowserPerformance {
        // Allocator is always valid in Zig 0.15 (no null check needed)
        
        // Allocate frame history buffer
        const timings = allocator.alloc(FrameTiming, MAX_FRAME_HISTORY)
catch {
            // Fallback: empty history if allocation fails
            return DreamBrowserPerformance{
                .allocator = allocator,
                .frame_history = FrameHistory{
                    .timings = &.{},
                    .timings_len = 0,
                    .timings_index = 0,
                },
                .current_frame_start = 0,
                .last_frame_time = 0,
                .metrics = PerformanceMetrics{
                    .frames_rendered = 0,
                    .average_fps = 0.0,
                    .average_frame_time_ms = 0.0,
                    .average_render_time_ms = 0.0,
                    .average_layout_time_ms = 0.0,
                    .min_frame_time_ms = 0,
                    .max_frame_time_ms = 0,
                    .dropped_frames = 0,
                },
            };
        };
        
        return DreamBrowserPerformance{
            .allocator = allocator,
            .frame_history = FrameHistory{
                .timings = timings,
                .timings_len = 0,
                .timings_index = 0,
            },
            .current_frame_start = 0,
            .last_frame_time = 0,
            .metrics = PerformanceMetrics{
                .frames_rendered = 0,
                .average_fps = 0.0,
                .average_frame_time_ms = 0.0,
                .average_render_time_ms = 0.0,
                .average_layout_time_ms = 0.0,
                .min_frame_time_ms = 0,
                .max_frame_time_ms = 0,
                .dropped_frames = 0,
            },
        };
    }
    
    /// Deinitialize performance monitor.
    pub fn deinit(self: *DreamBrowserPerformance) void {
        // Free frame history buffer
        if (self.frame_history.timings.len > 0) {
            self.allocator.free(self.frame_history.timings);
        }
    }
    
    /// Get current timestamp in milliseconds.
    fn get_current_time_ms() u64 {
        const timestamp = std.time.timestamp();
        const non_negative = if (timestamp < 0) 0 else @as(u64,
@intCast(timestamp));
        return non_negative * 1000; // Convert to milliseconds
(simplified)
    }
    
    /// Start frame timing (call at start of frame).
    pub fn start_frame(self: *DreamBrowserPerformance) void {
        self.current_frame_start = get_current_time_ms();
    }
    
    /// End frame timing (call at end of frame).
    pub fn end_frame(
        self: *DreamBrowserPerformance,
        render_time_ms: u32,
        layout_time_ms: u32,
    ) void {
        // Assert: Render and layout times must be within bounds
        std.debug.assert(render_time_ms <= MAX_FRAME_TIME_MS);
        std.debug.assert(layout_time_ms <= MAX_FRAME_TIME_MS);
        
        const frame_end_time = get_current_time_ms();
        const total_time_ms = @as(u32, @intCast(frame_end_time -
self.current_frame_start));
        
        // Assert: Total frame time must be within bounds
        std.debug.assert(total_time_ms <= MAX_FRAME_TIME_MS);
        
        // Create frame timing record
        const timing = FrameTiming{
            .frame_start_time = self.current_frame_start,
            .frame_end_time = frame_end_time,
            .render_time_ms = render_time_ms,
            .layout_time_ms = layout_time_ms,
            .total_time_ms = total_time_ms,
        };
        
        // Add to frame history (circular buffer)
        if (self.frame_history.timings.len > 0) {
            const index = self.frame_history.timings_index;
            self.frame_history.timings[index] = timing;
            self.frame_history.timings_index = (index + 1) %
MAX_FRAME_HISTORY;
            
            if (self.frame_history.timings_len < MAX_FRAME_HISTORY) {
                self.frame_history.timings_len += 1;
            }
        }
        
        // Update metrics
        self.metrics.frames_rendered += 1;
        
        // Update average frame time
        const total_frames = self.metrics.frames_rendered;
        if (total_frames == 1) {
            self.metrics.average_frame_time_ms = @as(f32,
@floatFromInt(total_time_ms));
            self.metrics.min_frame_time_ms = total_time_ms;
            self.metrics.max_frame_time_ms = total_time_ms;
        } else {
            // Running average: (old_avg * (n-1) + new_value) / n
            const old_avg = self.metrics.average_frame_time_ms;
            self.metrics.average_frame_time_ms = (old_avg * @as(f32,
@floatFromInt(total_frames - 1)) + @as(f32,
@floatFromInt(total_time_ms))) / @as(f32, @floatFromInt(total_frames));
            
            // Update min/max
            if (total_time_ms < self.metrics.min_frame_time_ms) {
                self.metrics.min_frame_time_ms = total_time_ms;
            }
            if (total_time_ms > self.metrics.max_frame_time_ms) {
                self.metrics.max_frame_time_ms = total_time_ms;
            }
        }
        
        // Update average render time
        if (total_frames == 1) {
            self.metrics.average_render_time_ms = @as(f32,
@floatFromInt(render_time_ms));
        } else {
            const old_avg = self.metrics.average_render_time_ms;
            self.metrics.average_render_time_ms = (old_avg * @as(f32,
@floatFromInt(total_frames - 1)) + @as(f32,
@floatFromInt(render_time_ms))) / @as(f32, @floatFromInt(total_frames));
        }
        
        // Update average layout time
        if (total_frames == 1) {
            self.metrics.average_layout_time_ms = @as(f32,
@floatFromInt(layout_time_ms));
        } else {
            const old_avg = self.metrics.average_layout_time_ms;
            self.metrics.average_layout_time_ms = (old_avg * @as(f32,
@floatFromInt(total_frames - 1)) + @as(f32,
@floatFromInt(layout_time_ms))) / @as(f32, @floatFromInt(total_frames));
        }
        
        // Update average FPS
        if (self.metrics.average_frame_time_ms > 0.0) {
            self.metrics.average_fps = 1000.0 /
self.metrics.average_frame_time_ms;
        }
        
        // Check for dropped frames (exceeded target frame time)
        if (total_time_ms > TARGET_FRAME_TIME_MS) {
            self.metrics.dropped_frames += 1;
        }
        
        self.last_frame_time = frame_end_time;
    }
    
    /// Check if we should skip this frame (if we're behind schedule).
    pub fn should_skip_frame(self: *const DreamBrowserPerformance) bool {
        // If we haven't rendered any frames yet, don't skip
        if (self.metrics.frames_rendered == 0) {
            return false;
        }
        
        // If average frame time exceeds target, skip occasionally
        if (self.metrics.average_frame_time_ms > @as(f32,
@floatFromInt(TARGET_FRAME_TIME_MS * 2))) {
            // Skip every other frame if we're more than 2x behind
            return (self.metrics.frames_rendered % 2) == 0;
        }
        
        return false;
    }
    
    /// Get current performance metrics.
    pub fn get_metrics(self: *const DreamBrowserPerformance)
PerformanceMetrics {
        return self.metrics;
    }
    
    /// Get frame history (for detailed analysis).
    pub fn get_frame_history(self: *const DreamBrowserPerformance)
[]const FrameTiming {
        if (self.frame_history.timings_len == 0) {
            return &.{};
        }
        return
self.frame_history.timings[0..self.frame_history.timings_len];
    }
    
    /// Check if we're maintaining target FPS.
    pub fn is_maintaining_target_fps(self: *const
DreamBrowserPerformance) bool {
        // Check if average FPS is within 5% of target
        const target_fps_f32 = @as(f32, @floatFromInt(TARGET_FPS));
        const fps_ratio = self.metrics.average_fps / target_fps_f32;
        return fps_ratio >= 0.95; // Within 5% of target
    }
    
    /// Get frame time budget remaining (for adaptive quality).
    pub fn get_remaining_frame_budget_ms(self: *const
DreamBrowserPerformance) u32 {
        const elapsed = @as(u32, @intCast(get_current_time_ms() -
self.current_frame_start));
        if (elapsed >= TARGET_FRAME_TIME_MS) {
            return 0; // No budget remaining
        }
        return TARGET_FRAME_TIME_MS - elapsed;
    }
    
    /// Reset performance metrics (for new measurement period).
    pub fn reset_metrics(self: *DreamBrowserPerformance) void {
        self.metrics = PerformanceMetrics{
            .frames_rendered = 0,
            .average_fps = 0.0,
            .average_frame_time_ms = 0.0,
            .average_render_time_ms = 0.0,
            .average_layout_time_ms = 0.0,
            .min_frame_time_ms = 0,
            .max_frame_time_ms = 0,
            .dropped_frames = 0,
        };
        self.frame_history.timings_len = 0;
        self.frame_history.timings_index = 0;
    }
};

test "performance initialization" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var perf = DreamBrowserPerformance.init(arena.allocator());
    defer perf.deinit();
    
    // Assert: Performance monitor initialized
    try std.testing.expect(perf.metrics.frames_rendered == 0);
    try std.testing.expect(perf.metrics.average_fps == 0.0);
}

test "performance frame timing" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var perf = DreamBrowserPerformance.init(arena.allocator());
    defer perf.deinit();
    
    perf.start_frame();
    // Simulate some work (no-op for test, timing handled by end_frame)
    perf.end_frame(1, 0);
    
    // Assert: Frame recorded
    try std.testing.expect(perf.metrics.frames_rendered == 1);
    try std.testing.expect(perf.metrics.average_render_time_ms > 0.0);
}

test "performance skip frame" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var perf = DreamBrowserPerformance.init(arena.allocator());
    defer perf.deinit();
    
    // Should not skip first frame
    try std.testing.expect(!perf.should_skip_frame());
    
    // Record some slow frames
    perf.start_frame();
    perf.end_frame(100, 0); // 100ms render time (very slow)
    
    // Should skip if behind schedule
    const should_skip = perf.should_skip_frame();
    // Note: This depends on average frame time, may vary
    _ = should_skip;
}

test "performance metrics" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var perf = DreamBrowserPerformance.init(arena.allocator());
    defer perf.deinit();
    
    // Record multiple frames
    for (0..10) |_| {
        perf.start_frame();
        perf.end_frame(10, 5); // 10ms render, 5ms layout
    }
    
    const metrics = perf.get_metrics();
    
    // Assert: Metrics calculated
    try std.testing.expect(metrics.frames_rendered == 10);
    try std.testing.expect(metrics.average_fps > 0.0);
    try std.testing.expect(metrics.average_frame_time_ms > 0.0);
}


// === dream_browser_profiler.zig ===

const std = @import("std");

/// Dream Browser Profiler: Hot path identification and optimization
guidance.
/// ~<~ Glow Airbend: explicit profiling, bounded samples.
/// ~~~~ Glow Waterbend: profiling flows deterministically through DAG.
///
/// This implements:
/// - Function call profiling (track call counts, total time, average
time)
/// - Hot path identification (functions that exceed time thresholds)
/// - Call stack sampling (identify slow call chains)
/// - Optimization recommendations (suggest optimizations for hot paths)
pub const DreamBrowserProfiler = struct {
    // Bounded: Max 1000 functions to profile
    pub const MAX_PROFILED_FUNCTIONS: u32 = 1000;
    
    // Bounded: Max 10,000 call samples
    pub const MAX_CALL_SAMPLES: u32 = 10_000;
    
    // Hot path threshold: functions taking >1ms are considered hot
    pub const HOT_PATH_THRESHOLD_US: u32 = 1000; // 1ms in microseconds
    
    // Critical path threshold: functions taking >10ms are critical
    pub const CRITICAL_PATH_THRESHOLD_US: u32 = 10_000; // 10ms in
microseconds
    
    /// Function profile (call statistics).
    pub const FunctionProfile = struct {
        function_name: []const u8, // Function name (e.g., "layout",
"render")
        call_count: u32, // Number of times called
        total_time_us: u64, // Total time spent (microseconds)
        average_time_us: u32, // Average time per call (microseconds)
        min_time_us: u32, // Minimum call time
        max_time_us: u32, // Maximum call time
        is_hot_path: bool, // Whether this is a hot path
        is_critical_path: bool, // Whether this is a critical path
    };
    
    /// Call sample (for stack trace analysis).
    pub const CallSample = struct {
        function_name: []const u8, // Function name
        timestamp_us: u64, // Timestamp when called
        duration_us: u32, // Duration of call
        parent_function: ?[]const u8 = null, // Parent function (caller)
    };
    
    /// Function profiles (indexed by function name hash).
    pub const ProfileMap = struct {
        profiles: []FunctionProfile, // Function profiles
        profiles_len: u32, // Current number of profiles
        function_names: [][]const u8, // Function name strings (owned)
        function_names_len: u32, // Current number of function names
    };
    
    /// Call samples (for analysis).
    pub const SampleBuffer = struct {
        samples: []CallSample, // Call samples
        samples_len: u32, // Current number of samples
        samples_index: u32, // Circular buffer index
    };
    
    allocator: std.mem.Allocator,
    profile_map: ProfileMap,
    sample_buffer: SampleBuffer,
    
    /// Initialize profiler.
    pub fn init(allocator: std.mem.Allocator) !DreamBrowserProfiler {
        // Pre-allocate profile map
        const profiles = try allocator.alloc(FunctionProfile,
MAX_PROFILED_FUNCTIONS);
        const function_names = try allocator.alloc([]const u8,
MAX_PROFILED_FUNCTIONS);
        
        // Pre-allocate sample buffer
        const samples = try allocator.alloc(CallSample,
MAX_CALL_SAMPLES);
        
        return DreamBrowserProfiler{
            .allocator = allocator,
            .profile_map = ProfileMap{
                .profiles = profiles,
                .profiles_len = 0,
                .function_names = function_names,
                .function_names_len = 0,
            },
            .sample_buffer = SampleBuffer{
                .samples = samples,
                .samples_len = 0,
                .samples_index = 0,
            },
        };
    }
    
    /// Deinitialize profiler.
    pub fn deinit(self: *DreamBrowserProfiler) void {
        // Free function name strings
        for
(self.profile_map.function_names[0..self.profile_map.function_names_len])
|name| {
            self.allocator.free(name);
        }
        
        // Free sample function names
        for
(self.sample_buffer.samples[0..self.sample_buffer.samples_len]) |sample|
{
            self.allocator.free(sample.function_name);
            if (sample.parent_function) |parent| {
                self.allocator.free(parent);
            }
        }
        
        // Free arrays
        self.allocator.free(self.profile_map.profiles);
        self.allocator.free(self.profile_map.function_names);
        self.allocator.free(self.sample_buffer.samples);
    }
    
    /// Get current timestamp in microseconds.
    fn get_current_time_us() u64 {
        const timestamp = std.time.timestamp();
        const non_negative = if (timestamp < 0) 0 else @as(u64,
@intCast(timestamp));
        return non_negative * 1_000_000; // Convert to microseconds
(simplified)
    }
    
    /// Start profiling a function call.
    pub fn start_function(self: *DreamBrowserProfiler, function_name:
[]const u8) u64 {
        // Self and function_name not used in start (only in
end_function)
        _ = self;
        _ = function_name;
        // Record start time
        return get_current_time_us();
    }
    
    /// End profiling a function call.
    pub fn end_function(
        self: *DreamBrowserProfiler,
        function_name: []const u8,
        start_time_us: u64,
        parent_function: ?[]const u8,
    ) !void {
        // Assert: Function name must be non-empty
        std.debug.assert(function_name.len > 0);
        std.debug.assert(function_name.len <= 256); // Bounded function
name length
        
        const end_time_us = get_current_time_us();
        const duration_us = @as(u32, @intCast(end_time_us -
start_time_us));
        
        // Assert: Duration must be reasonable
        std.debug.assert(duration_us < 1_000_000_000); // Max 1000
seconds
        
        // Find or create function profile
        var profile_index: ?u32 = null;
        var i: u32 = 0;
        while (i < self.profile_map.profiles_len) : (i += 1) {
            if (std.mem.eql(u8, self.profile_map.function_names[i],
function_name)) {
                profile_index = i;
                break;
            }
        }
        
        if (profile_index) |idx| {
            // Update existing profile
            const profile = &self.profile_map.profiles[idx];
            profile.call_count += 1;
            profile.total_time_us += duration_us;
            profile.average_time_us = @as(u32,
@intCast(profile.total_time_us / profile.call_count));
            
            // Update min/max
            if (duration_us < profile.min_time_us or profile.call_count
== 1) {
                profile.min_time_us = duration_us;
            }
            if (duration_us > profile.max_time_us) {
                profile.max_time_us = duration_us;
            }
            
            // Update hot path flags
            profile.is_hot_path = profile.average_time_us >
HOT_PATH_THRESHOLD_US;
            profile.is_critical_path = profile.average_time_us >
CRITICAL_PATH_THRESHOLD_US;
        } else {
            // Create new profile
            if (self.profile_map.profiles_len >= MAX_PROFILED_FUNCTIONS)
{
                return; // Skip if at capacity
            }
            
            const name_copy = try self.allocator.dupe(u8, function_name);
            errdefer self.allocator.free(name_copy);
            
            const idx = self.profile_map.profiles_len;
            self.profile_map.function_names[idx] = name_copy;
            self.profile_map.profiles[idx] = FunctionProfile{
                .function_name = name_copy,
                .call_count = 1,
                .total_time_us = duration_us,
                .average_time_us = duration_us,
                .min_time_us = duration_us,
                .max_time_us = duration_us,
                .is_hot_path = duration_us > HOT_PATH_THRESHOLD_US,
                .is_critical_path = duration_us >
CRITICAL_PATH_THRESHOLD_US,
            };
            self.profile_map.profiles_len += 1;
            self.profile_map.function_names_len += 1;
        }
        
        // Add call sample (for stack trace analysis)
        if (self.sample_buffer.samples_len < MAX_CALL_SAMPLES) {
            const sample_idx = self.sample_buffer.samples_len;
            const sample_name = try self.allocator.dupe(u8,
function_name);
            errdefer self.allocator.free(sample_name);
            
            const parent_name = if (parent_function) |parent| blk: {
                const parent_copy = try self.allocator.dupe(u8, parent);
                break :blk parent_copy;
            } else null;
            
            self.sample_buffer.samples[sample_idx] = CallSample{
                .function_name = sample_name,
                .timestamp_us = start_time_us,
                .duration_us = duration_us,
                .parent_function = parent_name,
            };
            self.sample_buffer.samples_len += 1;
        } else {
            // Circular buffer: overwrite oldest sample
            const sample_idx = self.sample_buffer.samples_index;
            const old_sample = &self.sample_buffer.samples[sample_idx];
            
            // Free old sample data
            self.allocator.free(old_sample.function_name);
            if (old_sample.parent_function) |parent| {
                self.allocator.free(parent);
            }
            
            // Create new sample
            const sample_name = try self.allocator.dupe(u8,
function_name);
            errdefer self.allocator.free(sample_name);
            
            const parent_name = if (parent_function) |parent| blk: {
                const parent_copy = try self.allocator.dupe(u8, parent);
                break :blk parent_copy;
            } else null;
            
            self.sample_buffer.samples[sample_idx] = CallSample{
                .function_name = sample_name,
                .timestamp_us = start_time_us,
                .duration_us = duration_us,
                .parent_function = parent_name,
            };
            
            self.sample_buffer.samples_index = (sample_idx + 1) %
MAX_CALL_SAMPLES;
        }
    }
    
    /// Get function profile by name.
    pub fn get_function_profile(
        self: *const DreamBrowserProfiler,
        function_name: []const u8,
    ) ?*const FunctionProfile {
        var i: u32 = 0;
        while (i < self.profile_map.profiles_len) : (i += 1) {
            if (std.mem.eql(u8, self.profile_map.function_names[i],
function_name)) {
                return &self.profile_map.profiles[i];
            }
        }
        return null;
    }
    
    /// Get all hot paths (functions exceeding threshold).
    pub fn get_hot_paths(self: *const DreamBrowserProfiler) []const
FunctionProfile {
        // Count hot paths
        var hot_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.profile_map.profiles_len) : (i += 1) {
            if (self.profile_map.profiles[i].is_hot_path) {
                hot_count += 1;
            }
        }
        
        if (hot_count == 0) {
            return &.{};
        }
        
        // Allocate result array
        const hot_paths = self.allocator.alloc(FunctionProfile,
hot_count) catch {
            return &.{};
        };
        
        // Copy hot paths
        var hot_idx: u32 = 0;
        i = 0;
        while (i < self.profile_map.profiles_len) : (i += 1) {
            if (self.profile_map.profiles[i].is_hot_path) {
                hot_paths[hot_idx] = self.profile_map.profiles[i];
                hot_idx += 1;
            }
        }
        
        return hot_paths[0..hot_count];
    }
    
    /// Get all critical paths (functions exceeding critical threshold).
    /// Note: Returns slice pointing to allocated array (caller must
free).
    pub fn get_critical_paths(self: *DreamBrowserProfiler) []const
FunctionProfile {
        // Count critical paths
        var critical_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.profile_map.profiles_len) : (i += 1) {
            if (self.profile_map.profiles[i].is_critical_path) {
                critical_count += 1;
            }
        }
        
        if (critical_count == 0) {
            return &.{};
        }
        
        // Allocate result array (caller must free)
        const critical_paths = self.allocator.alloc(FunctionProfile,
critical_count) catch {
            return &.{};
        };
        
        // Copy critical paths
        var critical_idx: u32 = 0;
        i = 0;
        while (i < self.profile_map.profiles_len) : (i += 1) {
            if (self.profile_map.profiles[i].is_critical_path) {
                critical_paths[critical_idx] =
self.profile_map.profiles[i];
                critical_idx += 1;
            }
        }
        
        return critical_paths[0..critical_count];
    }
    
    /// Get call samples (for stack trace analysis).
    pub fn get_call_samples(self: *const DreamBrowserProfiler) []const
CallSample {
        return
self.sample_buffer.samples[0..self.sample_buffer.samples_len];
    }
    
    /// Reset profiler (start new measurement period).
    pub fn reset(self: *DreamBrowserProfiler) void {
        // Free function name strings
        for
(self.profile_map.function_names[0..self.profile_map.function_names_len])
|name| {
            self.allocator.free(name);
        }
        
        // Free sample function names
        for
(self.sample_buffer.samples[0..self.sample_buffer.samples_len]) |sample|
{
            self.allocator.free(sample.function_name);
            if (sample.parent_function) |parent| {
                self.allocator.free(parent);
            }
        }
        
        // Reset counters
        self.profile_map.profiles_len = 0;
        self.profile_map.function_names_len = 0;
        self.sample_buffer.samples_len = 0;
        self.sample_buffer.samples_index = 0;
    }
    
    /// Get total number of function calls profiled.
    pub fn get_total_calls(self: *const DreamBrowserProfiler) u32 {
        var total: u32 = 0;
        var i: u32 = 0;
        while (i < self.profile_map.profiles_len) : (i += 1) {
            total += self.profile_map.profiles[i].call_count;
        }
        return total;
    }
    
    /// Get total time spent in all profiled functions.
    pub fn get_total_time_us(self: *const DreamBrowserProfiler) u64 {
        var total: u64 = 0;
        var i: u32 = 0;
        while (i < self.profile_map.profiles_len) : (i += 1) {
            total += self.profile_map.profiles[i].total_time_us;
        }
        return total;
    }
};

