// === dream_websocket.zig ===

const std = @import("std");

/// WebSocket client for Dream Protocol: low-latency bidirectional
communication.
/// ~<~ Glow Airbend: explicit frames, bounded buffers.
/// ~~~~ Glow Waterbend: streaming frames flow deterministically.
pub const WebSocketClient = struct {
    allocator: std.mem.Allocator,
    stream: std.net.Stream,
    host: []const u8,
    
    // Bounded: Max 16MB frame size
    pub const MAX_FRAME_SIZE: usize = 16 * 1024 * 1024;
    
    // Bounded: Max 64KB control frame
    pub const MAX_CONTROL_FRAME_SIZE: usize = 64 * 1024;
    
    pub const Opcode = enum(u4) {
        continuation = 0x0,
        text = 0x1,
        binary = 0x2,
        close = 0x8,
        ping = 0x9,
        pong = 0xA,
    };
    
    pub const Frame = struct {
        fin: bool, // Final frame in message
        opcode: Opcode,
        masked: bool,
        payload: []const u8,
    };
    
    pub fn init(allocator: std.mem.Allocator, stream: std.net.Stream,
host: []const u8) WebSocketClient {
        return WebSocketClient{
            .allocator = allocator,
            .stream = stream,
            .host = host,
        };
    }
    
    pub fn deinit(self: *WebSocketClient) void {
        self.stream.close();
        self.* = undefined;
    }
    
    /// Perform WebSocket handshake (HTTP upgrade).
    pub fn handshake(self: *WebSocketClient, path: []const u8) !void {
        // Assert: Path must be non-empty
        std.debug.assert(path.len > 0);
        
        // Generate WebSocket key (base64-encoded random 16 bytes)
        var key_buf: [16]u8 = undefined;
        std.crypto.random.bytes(&key_buf);
        const key = try std.base64.standard.Encoder.encode(&key_buf,
&key_buf);
        
        // Build HTTP upgrade request
        var request_buf: [1024]u8 = undefined;
        var writer = std.io.fixedBufferStream(&request_buf).writer();
        
        try writer.print("GET {s} HTTP/1.1\r\n", .{path});
        try writer.print("Host: {s}\r\n", .{self.host});
        try writer.print("Upgrade: websocket\r\n", .{});
        try writer.print("Connection: Upgrade\r\n", .{});
        try writer.print("Sec-WebSocket-Key: {s}\r\n", .{key});
        try writer.print("Sec-WebSocket-Version: 13\r\n", .{});
        try writer.print("\r\n", .{});
        
        const request = writer.getWritten();
        
        // Send request
        try self.stream.writeAll(request);
        
        // Read response
        var response_buf: [4096]u8 = undefined;
        const response_len = try self.stream.read(&response_buf);
        const response = response_buf[0..response_len];
        
        // Parse response: check for "101 Switching Protocols"
        if (!std.mem.containsAtLeast(u8, response, 1, "101")) {
            return error.HandshakeFailed;
        }
        
        // Check for "Upgrade: websocket"
        if (!std.mem.containsAtLeast(u8, response, 1, "Upgrade:
websocket")) {
            return error.HandshakeFailed;
        }
        
        // TODO: Verify Sec-WebSocket-Accept header
        // For now, assume handshake succeeded
    }
    
    /// Read WebSocket frame.
    pub fn readFrame(self: *WebSocketClient) !Frame {
        // Read first 2 bytes (FIN, opcode, mask, payload length)
        var header_buf: [2]u8 = undefined;
        _ = try self.stream.read(&header_buf);
        
        const byte1 = header_buf[0];
        const byte2 = header_buf[1];
        
        const fin = (byte1 & 0x80) != 0;
        const opcode_raw = @as(u4, @truncate(byte1 & 0x0F));
        const opcode = @as(Opcode, @enumFromInt(opcode_raw));
        const masked = (byte2 & 0x80) != 0;
        const payload_len_raw = byte2 & 0x7F;
        
        // Read extended payload length (if needed)
        var payload_len: u64 = payload_len_raw;
        if (payload_len_raw == 126) {
            var len_buf: [2]u8 = undefined;
            _ = try self.stream.read(&len_buf);
            payload_len = std.mem.readInt(u16, &len_buf, .big);
        } else if (payload_len_raw == 127) {
            var len_buf: [8]u8 = undefined;
            _ = try self.stream.read(&len_buf);
            payload_len = std.mem.readInt(u64, &len_buf, .big);
        }
        
        // Assert: Payload length must be within bounds
        if (opcode == .text or opcode == .binary) {
            std.debug.assert(payload_len <= MAX_FRAME_SIZE);
        } else {
            std.debug.assert(payload_len <= MAX_CONTROL_FRAME_SIZE);
        }
        
        // Read masking key (if present)
        var masking_key: [4]u8 = undefined;
        if (masked) {
            _ = try self.stream.read(&masking_key);
        }
        
        // Read payload
        var payload_buf = try self.allocator.alloc(u8, payload_len);
        errdefer self.allocator.free(payload_buf);
        _ = try self.stream.read(payload_buf);
        
        // Unmask payload (if masked)
        if (masked) {
            var i: usize = 0;
            while (i < payload_len) : (i += 1) {
                payload_buf[i] ^= masking_key[i % 4];
            }
        }
        
        return Frame{
            .fin = fin,
            .opcode = opcode,
            .masked = masked,
            .payload = payload_buf,
        };
    }
    
    /// Write WebSocket frame.
    pub fn writeFrame(self: *WebSocketClient, frame: Frame) !void {
        // Assert: Payload length must be within bounds
        if (frame.opcode == .text or frame.opcode == .binary) {
            std.debug.assert(frame.payload.len <= MAX_FRAME_SIZE);
        } else {
            std.debug.assert(frame.payload.len <=
MAX_CONTROL_FRAME_SIZE);
        }
        
        // Build frame header
        var header_buf: [14]u8 = undefined; // Max header size (2 + 8 +
4)
        var header_len: usize = 0;
        
        // Byte 1: FIN + opcode
        header_buf[0] = if (frame.fin) 0x80 else 0x00;
        header_buf[0] |= @as(u8, @intFromEnum(frame.opcode));
        header_len = 1;
        
        // Byte 2: MASK + payload length
        const payload_len = frame.payload.len;
        if (payload_len < 126) {
            header_buf[1] = @as(u8, @intCast(payload_len));
            header_len = 2;
        } else if (payload_len < 65536) {
            header_buf[1] = 126;
            std.mem.writeInt(u16, header_buf[2..4], @as(u16,
@intCast(payload_len)), .big);
            header_len = 4;
        } else {
            header_buf[1] = 127;
            std.mem.writeInt(u64, header_buf[2..10], payload_len, .big);
            header_len = 10;
        }
        
        // Client must mask frames
        // Generate masking key
        var masking_key: [4]u8 = undefined;
        std.crypto.random.bytes(&masking_key);
        header_buf[1] |= 0x80; // Set MASK bit
        std.mem.copyForwards(u8, header_buf[header_len..][0..4],
&masking_key);
        header_len += 4;
        
        // Mask payload
        var masked_payload = try self.allocator.alloc(u8, payload_len);
        defer self.allocator.free(masked_payload);
        std.mem.copyForwards(u8, masked_payload, frame.payload);
        var i: usize = 0;
        while (i < payload_len) : (i += 1) {
            masked_payload[i] ^= masking_key[i % 4];
        }
        
        // Send header + masked payload
        try self.stream.writeAll(header_buf[0..header_len]);
        try self.stream.writeAll(masked_payload);
    }
    
    /// Close WebSocket connection.
    pub fn close(self: *WebSocketClient) !void {
        // Send close frame
        const close_frame = Frame{
            .fin = true,
            .opcode = .close,
            .masked = true,
            .payload = "",
        };
        try self.writeFrame(close_frame);
        
        // Read close frame from server
        const response_frame = try self.readFrame();
        if (response_frame.opcode != .close) {
            return error.UnexpectedFrame;
        }
        
        // Close stream
        self.stream.close();
    }
};

test "websocket client init" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    // Create dummy stream (would be real TCP stream in production)
    const dummy_stream = std.net.Stream{ .handle = 0 };
    var client = WebSocketClient.init(arena.allocator(), dummy_stream,
"example.com");
    defer client.deinit();
    
    // Assert: Client initialized correctly
    std.debug.assert(std.mem.eql(u8, client.host, "example.com"));
}


// === grain_aurora.zig ===

const std = @import("std");
const GrainBuffer = @import("grain_buffer.zig").GrainBuffer;
const AuroraFilter = @import("aurora_filter.zig");
const MacWindow = @import("platform/macos_tahoe/window.zig");

/// GrainAurora — component-first GrainStyle UI stitching engine.
// ~<~ Glow Airbend: keep renders light.
// ~~~~ Glow Waterbend: streams of components stay deterministic.
pub const GrainAurora = struct {
    pub const Node = union(enum) {
        text: []const u8,
        column: Column,
        row: Row,
        button: Button,
    };

    pub const Column = struct {
        children: []const Node,
    };

    pub const Row = struct {
        children: []const Node,
    };

    pub const Button = struct {
        id: []const u8,
        label: []const u8,
    };

    pub const Component = fn (context: *RenderContext) RenderResult;

    pub const RenderContext = struct {
        allocator: std.mem.Allocator,
        buffer: *GrainBuffer,
        route: []const u8,
    };

    // Bounded: Maximum spans per type (Grain/Tiger style: explicit
limits)
    pub const MAX_DIAGNOSTIC_SPANS: u32 = 1000;
    pub const MAX_INLAY_HINT_SPANS: u32 = 500;
    pub const MAX_CODE_LENS_SPANS: u32 = 100;
    pub const MAX_DOCUMENT_HIGHLIGHT_SPANS: u32 = 100;
    pub const MAX_SEMANTIC_TOKEN_SPANS: u32 = 10000;
    pub const MAX_FOLDING_RANGE_SPANS: u32 = 1000;
    pub const MAX_SELECTION_RANGE_SPANS: u32 = 100;
    pub const MAX_DOCUMENT_LINK_SPANS: u32 = 1000;
    
    // Bounded: Maximum string lengths (Grain/Tiger style: explicit
limits)
    pub const MAX_DIAGNOSTIC_MESSAGE_LEN: u32 = 1024;
    pub const MAX_INLAY_HINT_LABEL_LEN: u32 = 256;
    pub const MAX_INLAY_HINT_TOOLTIP_LEN: u32 = 512;
    pub const MAX_CODE_LENS_TITLE_LEN: u32 = 256;
    pub const MAX_CODE_LENS_COMMAND_LEN: u32 = 256;
    pub const MAX_DOCUMENT_LINK_TARGET_LEN: u32 = 4096;
    pub const MAX_DOCUMENT_LINK_TOOLTIP_LEN: u32 = 512;

    pub const RenderResult = struct {
        root: Node,
        readonly_spans: []const Span, // Owned by caller (from
GrainBuffer)
        
        // Bounded arrays with explicit counts (Grain/Tiger style:
fixed-size storage)
        diagnostic_spans: [MAX_DIAGNOSTIC_SPANS]DiagnosticSpan =
undefined,
        diagnostic_spans_len: u32 = 0,
        
        inlay_hint_spans: [MAX_INLAY_HINT_SPANS]InlayHintSpan =
undefined,
        inlay_hint_spans_len: u32 = 0,
        
        code_lens_spans: [MAX_CODE_LENS_SPANS]CodeLensSpan = undefined,
        code_lens_spans_len: u32 = 0,
        
        document_highlight_spans:
[MAX_DOCUMENT_HIGHLIGHT_SPANS]DocumentHighlightSpan = undefined,
        document_highlight_spans_len: u32 = 0,
        
        semantic_token_spans:
[MAX_SEMANTIC_TOKEN_SPANS]SemanticTokenSpan = undefined,
        semantic_token_spans_len: u32 = 0,
        
        folding_range_spans: [MAX_FOLDING_RANGE_SPANS]FoldingRangeSpan =
undefined,
        folding_range_spans_len: u32 = 0,
        
        selection_range_spans:
[MAX_SELECTION_RANGE_SPANS]SelectionRangeSpan = undefined,
        selection_range_spans_len: u32 = 0,
        
        document_link_spans: [MAX_DOCUMENT_LINK_SPANS]DocumentLinkSpan =
undefined,
        document_link_spans_len: u32 = 0,
        
        ghost_spans: []const Span = &.{}, // Owned by caller (from
Editor)
        
        // No deinit needed: all strings are in fixed-size buffers, no
dynamic allocation
        
        /// Get diagnostic spans as a slice.
        /// Why: Convenient access to diagnostic spans using length
field.
        /// Contract: Returns slice of actual diagnostic spans
(0..diagnostic_spans_len).
        pub fn get_diagnostic_spans(self: *const RenderResult) []const
DiagnosticSpan {
            return self.diagnostic_spans[0..self.diagnostic_spans_len];
        }
        
        /// Get inlay hint spans as a slice.
        /// Why: Convenient access to inlay hint spans using length
field.
        /// Contract: Returns slice of actual inlay hint spans
(0..inlay_hint_spans_len).
        pub fn get_inlay_hint_spans(self: *const RenderResult) []const
InlayHintSpan {
            return self.inlay_hint_spans[0..self.inlay_hint_spans_len];
        }
        
        /// Get code lens spans as a slice.
        /// Why: Convenient access to code lens spans using length field.
        /// Contract: Returns slice of actual code lens spans
(0..code_lens_spans_len).
        pub fn get_code_lens_spans(self: *const RenderResult) []const
CodeLensSpan {
            return self.code_lens_spans[0..self.code_lens_spans_len];
        }
        
        /// Get document highlight spans as a slice.
        /// Why: Convenient access to document highlight spans using
length field.
        /// Contract: Returns slice of actual document highlight spans
(0..document_highlight_spans_len).
        pub fn get_document_highlight_spans(self: *const RenderResult)
[]const DocumentHighlightSpan {
            return
self.document_highlight_spans[0..self.document_highlight_spans_len];
        }
        
        /// Get semantic token spans as a slice.
        /// Why: Convenient access to semantic token spans using length
field.
        /// Contract: Returns slice of actual semantic token spans
(0..semantic_token_spans_len).
        pub fn get_semantic_token_spans(self: *const RenderResult)
[]const SemanticTokenSpan {
            return
self.semantic_token_spans[0..self.semantic_token_spans_len];
        }
        
        /// Get folding range spans as a slice.
        /// Why: Convenient access to folding range spans using length
field.
        /// Contract: Returns slice of actual folding range spans
(0..folding_range_spans_len).
        pub fn get_folding_range_spans(self: *const RenderResult)
[]const FoldingRangeSpan {
            return
self.folding_range_spans[0..self.folding_range_spans_len];
        }
        
        /// Get selection range spans as a slice.
        /// Why: Convenient access to selection range spans using length
field.
        /// Contract: Returns slice of actual selection range spans
(0..selection_range_spans_len).
        pub fn get_selection_range_spans(self: *const RenderResult)
[]const SelectionRangeSpan {
            return
self.selection_range_spans[0..self.selection_range_spans_len];
        }
        
        /// Get document link spans as a slice.
        /// Why: Convenient access to document link spans using length
field.
        /// Contract: Returns slice of actual document link spans
(0..document_link_spans_len).
        pub fn get_document_link_spans(self: *const RenderResult)
[]const DocumentLinkSpan {
            return
self.document_link_spans[0..self.document_link_spans_len];
        }
    };
    
    /// Diagnostic span (for LSP diagnostics rendering).
    /// Grain/Tiger style: fixed-size buffer, no dynamic allocation.
    pub const DiagnosticSpan = struct {
        start: u32, // Start byte position
        end: u32, // End byte position
        severity: u32, // Diagnostic severity (1=Error, 2=Warning,
3=Info, 4=Hint)
        message: [MAX_DIAGNOSTIC_MESSAGE_LEN]u8 = undefined, //
Fixed-size message buffer
        message_len: u32 = 0, // Actual message length
        
        /// Get message as a slice.
        /// Why: Convenient access to message string using length field.
        /// Contract: Returns slice of actual message (0..message_len).
        pub fn get_message(self: *const DiagnosticSpan) []const u8 {
            return self.message[0..self.message_len];
        }
    };
    
    /// Inlay hint span (for LSP inlay hints rendering).
    /// Grain/Tiger style: fixed-size buffers, no dynamic allocation.
    pub const InlayHintSpan = struct {
        position: u32, // Position where hint should be displayed (byte
position)
        label: [MAX_INLAY_HINT_LABEL_LEN]u8 = undefined, // Fixed-size
label buffer
        label_len: u32 = 0, // Actual label length
        kind: u32, // Hint kind (1=Type, 2=Parameter)
        tooltip: [MAX_INLAY_HINT_TOOLTIP_LEN]u8 = undefined, //
Fixed-size tooltip buffer
        tooltip_len: u32 = 0, // Actual tooltip length (0 = no tooltip)
        padding_left: bool = false, // Padding before hint
        padding_right: bool = false, // Padding after hint
        
        /// Get label as a slice.
        /// Why: Convenient access to label string using length field.
        /// Contract: Returns slice of actual label (0..label_len).
        pub fn get_label(self: *const InlayHintSpan) []const u8 {
            return self.label[0..self.label_len];
        }
        
        /// Get tooltip as a slice (if present).
        /// Why: Convenient access to tooltip string using length field.
        /// Contract: Returns slice of actual tooltip (0..tooltip_len)
if tooltip_len > 0, else null.
        pub fn get_tooltip(self: *const InlayHintSpan) ?[]const u8 {
            if (self.tooltip_len == 0) return null;
            return self.tooltip[0..self.tooltip_len];
        }
    };
    
    /// Code lens span (for LSP code lens rendering).
    /// Grain/Tiger style: fixed-size buffers, no dynamic allocation.
    pub const CodeLensSpan = struct {
        position: u32, // Position where code lens should be displayed
(byte position, start of range)
        title: [MAX_CODE_LENS_TITLE_LEN]u8 = undefined, // Fixed-size
title buffer
        title_len: u32 = 0, // Actual title length
        command: [MAX_CODE_LENS_COMMAND_LEN]u8 = undefined, //
Fixed-size command buffer
        command_len: u32 = 0, // Actual command length (0 = no command)
        range_start: u32, // Start byte position of the range this lens
applies to
        range_end: u32, // End byte position of the range this lens
applies to
        
        /// Get title as a slice.
        /// Why: Convenient access to title string using length field.
        /// Contract: Returns slice of actual title (0..title_len).
        pub fn get_title(self: *const CodeLensSpan) []const u8 {
            return self.title[0..self.title_len];
        }
        
        /// Get command as a slice (if present).
        /// Why: Convenient access to command string using length field.
        /// Contract: Returns slice of actual command (0..command_len)
if command_len > 0, else null.
        pub fn get_command(self: *const CodeLensSpan) ?[]const u8 {
            if (self.command_len == 0) return null;
            return self.command[0..self.command_len];
        }
    };
    
    /// Document highlight span (for LSP document highlights rendering).
    pub const DocumentHighlightSpan = struct {
        start: u32, // Start byte position
        end: u32, // End byte position
        kind: u32, // Highlight kind (1=Text, 2=Read, 3=Write)
    };
    
    /// Semantic token span (for LSP semantic tokens rendering).
    pub const SemanticTokenSpan = struct {
        start: u32, // Start byte position
        end: u32, // End byte position
        token_type: u32, // Token type (SemanticTokenType)
        modifiers: u32, // Token modifiers (bit flags)
    };
    
    /// Folding range span (for LSP folding ranges rendering).
    pub const FoldingRangeSpan = struct {
        start: u32, // Start byte position
        end: u32, // End byte position
        kind: u32, // Folding range kind (1=Comment, 2=Imports, 3=Region)
    };
    
    /// Selection range span (for LSP selection ranges rendering).
    pub const SelectionRangeSpan = struct {
        start: u32, // Start byte position
        end: u32, // End byte position
        level: u32, // Selection level (0=innermost, higher=outer)
    };
    
    /// Document link span (for LSP document links rendering).
    /// Grain/Tiger style: fixed-size buffers, no dynamic allocation.
    pub const DocumentLinkSpan = struct {
        start: u32, // Start byte position
        end: u32, // End byte position
        target: [MAX_DOCUMENT_LINK_TARGET_LEN]u8 = undefined, //
Fixed-size target buffer
        target_len: u32 = 0, // Actual target length (0 = no target)
        tooltip: [MAX_DOCUMENT_LINK_TOOLTIP_LEN]u8 = undefined, //
Fixed-size tooltip buffer
        tooltip_len: u32 = 0, // Actual tooltip length (0 = no tooltip)
        
        /// Get target as a slice (if present).
        /// Why: Convenient access to target string using length field.
        /// Contract: Returns slice of actual target (0..target_len) if
target_len > 0, else null.
        pub fn get_target(self: *const DocumentLinkSpan) ?[]const u8 {
            if (self.target_len == 0) return null;
            return self.target[0..self.target_len];
        }
        
        /// Get tooltip as a slice (if present).
        /// Why: Convenient access to tooltip string using length field.
        /// Contract: Returns slice of actual tooltip (0..tooltip_len)
if tooltip_len > 0, else null.
        pub fn get_tooltip(self: *const DocumentLinkSpan) ?[]const u8 {
            if (self.tooltip_len == 0) return null;
            return self.tooltip[0..self.tooltip_len];
        }
    };

    pub const Span = struct {
        start: u32, // Start byte position
        end: u32, // End byte position
    };

    allocator: std.mem.Allocator,
    buffer: GrainBuffer,

    pub fn init(allocator: std.mem.Allocator, seed: []const u8)
!GrainAurora {
        const buffer = try GrainBuffer.fromSlice(allocator, seed);
        return GrainAurora{
            .allocator = allocator,
            .buffer = buffer,
        };
    }

    pub fn deinit(self: *GrainAurora) void {
        self.buffer.deinit();
        self.* = undefined;
    }

    pub fn render(
        self: *GrainAurora,
        component: Component,
        route: []const u8,
    ) !void {
        self.buffer.deinit();
        const fresh = try GrainBuffer.fromSlice(self.allocator, "");
        self.buffer = fresh;
        var ctx = RenderContext{
            .allocator = self.allocator,
            .buffer = &self.buffer,
            .route = route,
        };
        const result = component(&ctx);
        try writeNode(&self.buffer, result.root);
        for (result.readonly_spans) |span| {
            try self.buffer.markReadOnly(span.start, span.end);
        }
    }
};

fn writeNode(buffer: *GrainBuffer, node: GrainAurora.Node) !void {
    switch (node) {
        .text => |value| try buffer.append(value),
        .button => |btn| {
            try buffer.append("[");
            try buffer.append(btn.label);
            try buffer.append("]");
        },
        .row => |row| {
            try buffer.append("{ ");
            for (row.children, 0..) |child, index| {
                if (index > 0) try buffer.append(" | ");
                try writeNode(buffer, child);
            }
            try buffer.append(" }");
        },
        .column => |col| {
            for (col.children) |child| {
                try writeNode(buffer, child);
                try buffer.append("\n");
            }
        },
    }
}

test "grain aurora renders simple column" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();

    var aurora = try GrainAurora.init(arena.allocator(), "");
    defer aurora.deinit();

    const component = struct {
        fn view(ctx: *GrainAurora.RenderContext)
GrainAurora.RenderResult {
            _ = ctx;
            return GrainAurora.RenderResult{
                .root = .{ .column = .{
                    .children = &.{
                        .{ .text = "Hello" },
                        .{ .button = .{ .id = "submit", .label =
"Submit" } },
                    },
                } },
                .readonly_spans = &.{
                    .{ .start = 0, .end = 5 },
                },
            };
        }
    }.view;

    try aurora.render(component, "/hello");
    const rendered = aurora.buffer.textSlice();
    try std.testing.expect(std.mem.startsWith(u8, rendered,
"Hello\n[Submit]"));
}

pub fn demo() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();

    var window = try MacWindow.Window.init(gpa.allocator(), "Aurora
Sandbox");
    defer window.deinit();
    try window.show();

    var pixels = [_]u8{ 180, 160, 150, 255, 200, 120, 100, 255 };
    var state = AuroraFilter.FluxState{};
    state.toggle(.darkroom);
    AuroraFilter.apply(state, &pixels);
    std.debug.print("Applied darkroom filter to {d} pixels\n",
.{pixels.len / 4});
}

test "RenderResult helper methods" {
    var result = GrainAurora.RenderResult{
        .root = .{ .text = "test" },
        .readonly_spans = &.{},
        .diagnostic_spans = undefined,
        .diagnostic_spans_len = 2,
        .inlay_hint_spans = undefined,
        .inlay_hint_spans_len = 1,
        .code_lens_spans = undefined,
        .code_lens_spans_len = 0,
        .document_highlight_spans = undefined,
        .document_highlight_spans_len = 0,
        .semantic_token_spans = undefined,
        .semantic_token_spans_len = 0,
        .folding_range_spans = undefined,
        .folding_range_spans_len = 0,
        .selection_range_spans = undefined,
        .selection_range_spans_len = 0,
        .document_link_spans = undefined,
        .document_link_spans_len = 0,
    };
    
    // Set up test data
    @memcpy(result.diagnostic_spans[0].message[0..5], "error");
    result.diagnostic_spans[0].message_len = 5;
    result.diagnostic_spans[0].start = 0;
    result.diagnostic_spans[0].end = 10;
    result.diagnostic_spans[0].severity = 1;
    
    @memcpy(result.diagnostic_spans[1].message[0..7], "warning");
    result.diagnostic_spans[1].message_len = 7;
    result.diagnostic_spans[1].start = 10;
    result.diagnostic_spans[1].end = 20;
    result.diagnostic_spans[1].severity = 2;
    
    @memcpy(result.inlay_hint_spans[0].label[0..4], "type");
    result.inlay_hint_spans[0].label_len = 4;
    result.inlay_hint_spans[0].position = 5;
    result.inlay_hint_spans[0].kind = 1;
    result.inlay_hint_spans[0].tooltip_len = 0;
    
    // Test helper methods
    const diagnostic_spans = result.get_diagnostic_spans();
    try std.testing.expect(diagnostic_spans.len == 2);
    try std.testing.expectEqualStrings("error",
diagnostic_spans[0].get_message());
    try std.testing.expectEqualStrings("warning",
diagnostic_spans[1].get_message());
    
    const inlay_hint_spans = result.get_inlay_hint_spans();
    try std.testing.expect(inlay_hint_spans.len == 1);
    try std.testing.expectEqualStrings("type",
inlay_hint_spans[0].get_label());
    try std.testing.expect(inlay_hint_spans[0].get_tooltip() == null);
    
    const code_lens_spans = result.get_code_lens_spans();
    try std.testing.expect(code_lens_spans.len == 0);
    
    const document_highlight_spans =
result.get_document_highlight_spans();
    try std.testing.expect(document_highlight_spans.len == 0);
    
    const semantic_token_spans = result.get_semantic_token_spans();
    try std.testing.expect(semantic_token_spans.len == 0);
    
    const folding_range_spans = result.get_folding_range_spans();
    try std.testing.expect(folding_range_spans.len == 0);
    
    const selection_range_spans = result.get_selection_range_spans();
    try std.testing.expect(selection_range_spans.len == 0);
    
    const document_link_spans = result.get_document_link_spans();
    try std.testing.expect(document_link_spans.len == 0);
}

// === grain_bubble/bubble_renderer.zig ===

//! Grain Bubble Renderer: Render rounded shapes ("bubbles").
//!
//! Why: Render design elements with rounded corners.
//! Architecture: Vector graphics rendering via framebuffer.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-06-055154-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");

// Bounded: Max corner radius (pixels).
pub const MAX_CORNER_RADIUS: u32 = 100;

// Bounded: Circle approximation segments.
pub const CIRCLE_SEGMENTS: u32 = 32;

// Bubble renderer: renders shapes to framebuffer.
pub const BubbleRenderer = struct {
    framebuffer_width: u32,
    framebuffer_height: u32,

    pub fn init(width: u32, height: u32) BubbleRenderer {
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        const renderer = BubbleRenderer{
            .framebuffer_width = width,
            .framebuffer_height = height,
        };
        std.debug.assert(renderer.framebuffer_width > 0);
        std.debug.assert(renderer.framebuffer_height > 0);
        return renderer;
    }

    // Render rounded rectangle ("bubble").
    pub fn render_rounded_rect(
        self: *const BubbleRenderer,
        x: i32,
        y: i32,
        width: u32,
        height: u32,
        color: u32,
        corner_radius: f64,
        draw_fn: *const fn (u32, u32, u32) void,
    ) void {
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        std.debug.assert(corner_radius >= 0.0);
        std.debug.assert(@intFromPtr(draw_fn) != 0);
        const radius = @as(u32, @intFromFloat(corner_radius));
        if (radius == 0) {
            // Simple rectangle.
            self.render_rect(x, y, width, height, color, draw_fn);
            return;
        }
        const clamped_radius = @min(radius, MAX_CORNER_RADIUS);
        const clamped_radius_f = @as(f64, @floatFromInt(clamped_radius));
        const radius_squared = clamped_radius_f * clamped_radius_f;
        const x_f = @as(f64, @floatFromInt(x));
        const y_f = @as(f64, @floatFromInt(y));
        const width_f = @as(f64, @floatFromInt(width));
        const height_f = @as(f64, @floatFromInt(height));
        // Corner centers.
        const top_left_cx = x_f + clamped_radius_f;
        const top_left_cy = y_f + clamped_radius_f;
        const top_right_cx = x_f + width_f - clamped_radius_f;
        const top_right_cy = y_f + clamped_radius_f;
        const bottom_left_cx = x_f + clamped_radius_f;
        const bottom_left_cy = y_f + height_f - clamped_radius_f;
        const bottom_right_cx = x_f + width_f - clamped_radius_f;
        const bottom_right_cy = y_f + height_f - clamped_radius_f;
        // Render main body (excluding corner areas).
        const start_y = if (y < 0) 0 else @as(u32, @intCast(y));
        const end_y = if (@as(u32, @intCast(y)) + height >
self.framebuffer_height)
            self.framebuffer_height
        else
            @as(u32, @intCast(y)) + height;
        var py: u32 = start_y;
        while (py < end_y) : (py += 1) {
            const py_f = @as(f64, @floatFromInt(py));
            const start_x = if (x < 0) 0 else @as(u32, @intCast(x));
            const end_x = if (@as(u32, @intCast(x)) + width >
self.framebuffer_width)
                self.framebuffer_width
            else
                @as(u32, @intCast(x)) + width;
            var px: u32 = start_x;
            while (px < end_x) : (px += 1) {
                const px_f = @as(f64, @floatFromInt(px));
                var should_draw = true;
                // Check if pixel is in corner exclusion zones.
                if (px_f < top_left_cx and py_f < top_left_cy) {
                    // Top-left corner.
                    const dx = px_f - top_left_cx;
                    const dy = py_f - top_left_cy;
                    if (dx * dx + dy * dy > radius_squared) {
                        should_draw = false;
                    }
                } else if (px_f >= top_right_cx and py_f < top_right_cy)
{
                    // Top-right corner.
                    const dx = px_f - top_right_cx;
                    const dy = py_f - top_right_cy;
                    if (dx * dx + dy * dy > radius_squared) {
                        should_draw = false;
                    }
                } else if (px_f < bottom_left_cx and py_f >=
bottom_left_cy) {
                    // Bottom-left corner.
                    const dx = px_f - bottom_left_cx;
                    const dy = py_f - bottom_left_cy;
                    if (dx * dx + dy * dy > radius_squared) {
                        should_draw = false;
                    }
                } else if (px_f >= bottom_right_cx and py_f >=
bottom_right_cy) {
                    // Bottom-right corner.
                    const dx = px_f - bottom_right_cx;
                    const dy = py_f - bottom_right_cy;
                    if (dx * dx + dy * dy > radius_squared) {
                        should_draw = false;
                    }
                }
                if (should_draw) {
                    draw_fn(px, py, color);
                }
            }
        }
        // Render corner quarter-circles.
        self.render_quarter_circle(
            @as(i32, @intFromFloat(top_left_cx)),
            @as(i32, @intFromFloat(top_left_cy)),
            clamped_radius,
            color,
            .top_left,
            draw_fn,
        );
        self.render_quarter_circle(
            @as(i32, @intFromFloat(top_right_cx)),
            @as(i32, @intFromFloat(top_right_cy)),
            clamped_radius,
            color,
            .top_right,
            draw_fn,
        );
        self.render_quarter_circle(
            @as(i32, @intFromFloat(bottom_left_cx)),
            @as(i32, @intFromFloat(bottom_left_cy)),
            clamped_radius,
            color,
            .bottom_left,
            draw_fn,
        );
        self.render_quarter_circle(
            @as(i32, @intFromFloat(bottom_right_cx)),
            @as(i32, @intFromFloat(bottom_right_cy)),
            clamped_radius,
            color,
            .bottom_right,
            draw_fn,
        );
    }

    // Quarter circle corner type.
    const QuarterCorner = enum {
        top_left,
        top_right,
        bottom_left,
        bottom_right,
    };

    // Render quarter circle (for rounded rectangle corners).
    fn render_quarter_circle(
        self: *const BubbleRenderer,
        center_x: i32,
        center_y: i32,
        radius: u32,
        color: u32,
        corner: QuarterCorner,
        draw_fn: *const fn (u32, u32, u32) void,
    ) void {
        std.debug.assert(radius > 0);
        std.debug.assert(@intFromPtr(draw_fn) != 0);
        const center_x_f = @as(f64, @floatFromInt(center_x));
        const center_y_f = @as(f64, @floatFromInt(center_y));
        const radius_f = @as(f64, @floatFromInt(radius));
        const radius_squared = radius_f * radius_f;
        const radius_i = @as(i32, @intCast(radius));
        // Determine bounding box based on corner type.
        const start_x_i: i32 = switch (corner) {
            .top_left, .bottom_left => center_x - radius_i,
            .top_right, .bottom_right => center_x,
        };
        const end_x_i: i32 = switch (corner) {
            .top_left, .bottom_left => center_x,
            .top_right, .bottom_right => center_x + radius_i,
        };
        const start_y_i: i32 = switch (corner) {
            .top_left, .top_right => center_y - radius_i,
            .bottom_left, .bottom_right => center_y,
        };
        const end_y_i: i32 = switch (corner) {
            .top_left, .top_right => center_y,
            .bottom_left, .bottom_right => center_y + radius_i,
        };
        const start_x = @max(0, start_x_i);
        const end_x = @min(@as(i32, @intCast(self.framebuffer_width)),
end_x_i);
        const start_y = @max(0, start_y_i);
        const end_y = @min(@as(i32, @intCast(self.framebuffer_height)),
end_y_i);
        var py: i32 = start_y;
        while (py < end_y) : (py += 1) {
            var px: i32 = start_x;
            while (px < end_x) : (px += 1) {
                const px_f = @as(f64, @floatFromInt(px));
                const py_f = @as(f64, @floatFromInt(py));
                const dx = px_f - center_x_f;
                const dy = py_f - center_y_f;
                const distance_squared = dx * dx + dy * dy;
                if (distance_squared <= radius_squared) {
                    draw_fn(@as(u32, @intCast(px)), @as(u32,
@intCast(py)), color);
                }
            }
        }
    }

    // Render rectangle (filled).
    pub fn render_rect(
        self: *const BubbleRenderer,
        x: i32,
        y: i32,
        width: u32,
        height: u32,
        color: u32,
        draw_fn: *const fn (u32, u32, u32) void,
    ) void {
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        std.debug.assert(@intFromPtr(draw_fn) != 0);
        const start_y = if (y < 0) 0 else @as(u32, @intCast(y));
        const end_y = if (@as(u32, @intCast(y)) + height >
self.framebuffer_height)
            self.framebuffer_height
        else
            @as(u32, @intCast(y)) + height;
        var py: u32 = start_y;
        while (py < end_y) : (py += 1) {
            const start_x = if (x < 0) 0 else @as(u32, @intCast(x));
            const end_x = if (@as(u32, @intCast(x)) + width >
self.framebuffer_width)
                self.framebuffer_width
            else
                @as(u32, @intCast(x)) + width;
            var px: u32 = start_x;
            while (px < end_x) : (px += 1) {
                draw_fn(px, py, color);
            }
        }
    }

    // Render rectangle stroke (outline only).
    pub fn render_rect_stroke(
        self: *const BubbleRenderer,
        x: i32,
        y: i32,
        width: u32,
        height: u32,
        stroke_width: u32,
        stroke_color: u32,
        draw_fn: *const fn (u32, u32, u32) void,
    ) void {
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        std.debug.assert(stroke_width > 0);
        std.debug.assert(@intFromPtr(draw_fn) != 0);
        const clamped_stroke = @min(stroke_width, width / 2);
        const clamped_stroke_h = @min(stroke_width, height / 2);
        // Top edge.
        var i: u32 = 0;
        while (i < clamped_stroke_h) : (i += 1) {
            const py = if (y + @as(i32, @intCast(i)) < 0) 0 else
@as(u32, @intCast(y + @as(i32, @intCast(i))));
            if (py < self.framebuffer_height) {
                var px: u32 = if (x < 0) 0 else @as(u32, @intCast(x));
                const end_x = if (@as(u32, @intCast(x)) + width >
self.framebuffer_width)
                    self.framebuffer_width
                else
                    @as(u32, @intCast(x)) + width;
                while (px < end_x) : (px += 1) {
                    draw_fn(px, py, stroke_color);
                }
            }
        }
        // Bottom edge.
        i = 0;
        while (i < clamped_stroke_h) : (i += 1) {
            const py = @as(u32, @intCast(y)) + height - clamped_stroke_h
+ i;
            if (py < self.framebuffer_height) {
                var px: u32 = if (x < 0) 0 else @as(u32, @intCast(x));
                const end_x = if (@as(u32, @intCast(x)) + width >
self.framebuffer_width)
                    self.framebuffer_width
                else
                    @as(u32, @intCast(x)) + width;
                while (px < end_x) : (px += 1) {
                    draw_fn(px, py, stroke_color);
                }
            }
        }
        // Left edge.
        i = 0;
        while (i < clamped_stroke) : (i += 1) {
            const px = if (x + @as(i32, @intCast(i)) < 0) 0 else
@as(u32, @intCast(x + @as(i32, @intCast(i))));
            if (px < self.framebuffer_width) {
                var py: u32 = if (y < 0) 0 else @as(u32, @intCast(y));
                const end_y = if (@as(u32, @intCast(y)) + height >
self.framebuffer_height)
                    self.framebuffer_height
                else
                    @as(u32, @intCast(y)) + height;
                while (py < end_y) : (py += 1) {
                    draw_fn(px, py, stroke_color);
                }
            }
        }
        // Right edge.
        i = 0;
        while (i < clamped_stroke) : (i += 1) {
            const px = @as(u32, @intCast(x)) + width - clamped_stroke +
i;
            if (px < self.framebuffer_width) {
                var py: u32 = if (y < 0) 0 else @as(u32, @intCast(y));
                const end_y = if (@as(u32, @intCast(y)) + height >
self.framebuffer_height)
                    self.framebuffer_height
                else
                    @as(u32, @intCast(y)) + height;
                while (py < end_y) : (py += 1) {
                    draw_fn(px, py, stroke_color);
                }
            }
        }
    }

    // Render circle (filled).
    pub fn render_circle(
        self: *const BubbleRenderer,
        center_x: i32,
        center_y: i32,
        radius: u32,
        color: u32,
        draw_fn: *const fn (u32, u32, u32) void,
    ) void {
        std.debug.assert(radius > 0);
        std.debug.assert(@intFromPtr(draw_fn) != 0);
        const center_x_f = @as(f64, @floatFromInt(center_x));
        const center_y_f = @as(f64, @floatFromInt(center_y));
        const radius_f = @as(f64, @floatFromInt(radius));
        const radius_i = @as(i32, @intCast(radius));
        // Fill circle using bounding box scan.
        const start_y = @max(0, center_y - radius_i);
        const end_y = @min(@as(i32, @intCast(self.framebuffer_height)),
center_y + radius_i);
        var py: i32 = start_y;
        while (py < end_y) : (py += 1) {
            const start_x = @max(0, center_x - radius_i);
            const end_x = @min(@as(i32,
@intCast(self.framebuffer_width)), center_x + radius_i);
            var px: i32 = start_x;
            while (px < end_x) : (px += 1) {
                const dx = @as(f64, @floatFromInt(px)) - center_x_f;
                const dy = @as(f64, @floatFromInt(py)) - center_y_f;
                const distance_squared = dx * dx + dy * dy;
                const radius_squared = radius_f * radius_f;
                if (distance_squared <= radius_squared) {
                    draw_fn(@as(u32, @intCast(px)), @as(u32,
@intCast(py)), color);
                }
            }
        }
    }

    // Render shape from canvas.
    pub fn render_shape(
        self: *const BubbleRenderer,
        shape: *const canvas.Shape,
        viewport: *const canvas.Viewport,
        draw_fn: *const fn (u32, u32, u32) void,
    ) void {
        std.debug.assert(@intFromPtr(shape) != 0);
        std.debug.assert(@intFromPtr(viewport) != 0);
        std.debug.assert(@intFromPtr(draw_fn) != 0);
        const screen_x = @as(i32, @intFromFloat(
            (shape.x + viewport.pan_x) * viewport.zoom,
        ));
        const screen_y = @as(i32, @intFromFloat(
            (shape.y + viewport.pan_y) * viewport.zoom,
        ));
        const screen_width = @as(u32, @intFromFloat(shape.width *
viewport.zoom));
        const screen_height = @as(u32, @intFromFloat(shape.height *
viewport.zoom));
        switch (shape.shape_type) {
            .rectangle => {
                self.render_rect(screen_x, screen_y, screen_width,
screen_height, shape.color, draw_fn);
            },
            .circle => {
                const radius = @min(screen_width, screen_height) / 2;
                const center_x = screen_x + @as(i32,
@intCast(screen_width / 2));
                const center_y = screen_y + @as(i32,
@intCast(screen_height / 2));
                self.render_circle(center_x, center_y, radius,
shape.color, draw_fn);
            },
            .rounded_rectangle => {
                const corner_radius = shape.corner_radius *
viewport.zoom;
                self.render_rounded_rect(
                    screen_x,
                    screen_y,
                    screen_width,
                    screen_height,
                    shape.color,
                    corner_radius,
                    draw_fn,
                );
            },
        }
    }
};

// === grain_bubble/canvas.zig ===

//! Grain Bubble Canvas: Infinite canvas with zoom/pan.
//!
//! Why: Foundation for design tool with infinite canvas.
//! Architecture: Viewport transformation, world coordinates.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-06-060230-pst: Grain Bubble Agent

const std = @import("std");
const undo_redo = @import("undo_redo.zig");

// Bounded: Max number of layers.
pub const MAX_LAYERS: u32 = 256;

// Bounded: Max number of shapes per layer.
pub const MAX_SHAPES: u32 = 1024;

// Bounded: Max text length.
pub const MAX_TEXT_LEN: u32 = 512;

// Bounded: Max text items.
pub const MAX_TEXT_ITEMS: u32 = 256;

// Bounded: Max selection count.
pub const MAX_SELECTION: u32 = 64;

// Bounded: Max clipboard shapes.
pub const MAX_CLIPBOARD_SHAPES: u32 = 64;

// Bounded: Min zoom level (10%).
pub const MIN_ZOOM: f64 = 0.1;

// Bounded: Max zoom level (1000%).
pub const MAX_ZOOM: f64 = 10.0;

// Bounded: Default zoom level (100%).
pub const DEFAULT_ZOOM: f64 = 1.0;

// Shape type.
pub const ShapeType = enum {
    rectangle,
    circle,
    rounded_rectangle,
};

// Shape: design element on canvas.
pub const Shape = struct {
    id: u32,
    shape_type: ShapeType,
    x: f64,
    y: f64,
    width: f64,
    height: f64,
    color: u32,
    corner_radius: f64,
    stroke_width: f64,
    stroke_color: u32,
    layer_id: u32,
    z_order: u32,
};

// Text: text element on canvas.
pub const Text = struct {
    id: u32,
    x: f64,
    y: f64,
    content: [MAX_TEXT_LEN]u8,
    content_len: u32,
    font_size: u32,
    color: u32,
    layer_id: u32,
    z_order: u32,
};

// Layer: container for shapes and text.
pub const Layer = struct {
    id: u32,
    name: [64]u8,
    name_len: u32,
    visible: bool,
    locked: bool,
    z_order: u32,
    shapes: [MAX_SHAPES]Shape,
    shapes_len: u32,
    texts: [MAX_TEXT_ITEMS]Text,
    texts_len: u32,
};

// Viewport: camera transformation for canvas.
pub const Viewport = struct {
    zoom: f64,
    pan_x: f64,
    pan_y: f64,
    width: u32,
    height: u32,
};

// Canvas: main canvas state.
pub const Canvas = struct {
    layers: [MAX_LAYERS]Layer,
    layers_len: u32,
    next_shape_id: u32,
    next_text_id: u32,
    next_layer_id: u32,
    viewport: Viewport,
    selection: [MAX_SELECTION]u32,
    selection_len: u32,
    selection_type: SelectionType,
    clipboard: [MAX_CLIPBOARD_SHAPES]Shape,
    clipboard_len: u32,
    undo_redo: ?*undo_redo.UndoRedoManager,

    const SelectionType = enum {
        shape,
        text,
        none,
    };

    pub fn init(width: u32, height: u32) Canvas {
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        const canvas = Canvas{
            .layers = undefined,
            .layers_len = 0,
            .next_shape_id = 1,
            .next_text_id = 1,
            .next_layer_id = 1,
            .viewport = Viewport{
                .zoom = DEFAULT_ZOOM,
                .pan_x = 0.0,
                .pan_y = 0.0,
                .width = width,
                .height = height,
            },
                    .selection = undefined,
                    .selection_len = 0,
                    .selection_type = .none,
                    .clipboard = undefined,
                    .clipboard_len = 0,
                    .undo_redo = null,
                };
                std.debug.assert(canvas.viewport.zoom >= MIN_ZOOM);
                std.debug.assert(canvas.viewport.zoom <= MAX_ZOOM);
                return canvas;
            }

    // World to screen coordinate transformation.
    pub fn world_to_screen(
        self: *const Canvas,
        world_x: f64,
        world_y: f64,
    ) struct { x: i32, y: i32 } {
        std.debug.assert(self.viewport.zoom >= MIN_ZOOM);
        std.debug.assert(self.viewport.zoom <= MAX_ZOOM);
        const screen_x = @as(i32, @intFromFloat(
            (world_x + self.viewport.pan_x) * self.viewport.zoom,
        ));
        const screen_y = @as(i32, @intFromFloat(
            (world_y + self.viewport.pan_y) * self.viewport.zoom,
        ));
        return .{ .x = screen_x, .y = screen_y };
    }

    // Screen to world coordinate transformation.
    pub fn screen_to_world(
        self: *const Canvas,
        screen_x: i32,
        screen_y: i32,
    ) struct { x: f64, y: f64 } {
        std.debug.assert(self.viewport.zoom >= MIN_ZOOM);
        std.debug.assert(self.viewport.zoom <= MAX_ZOOM);
        const world_x = (@as(f64, @floatFromInt(screen_x)) /
self.viewport.zoom) -
            self.viewport.pan_x;
        const world_y = (@as(f64, @floatFromInt(screen_y)) /
self.viewport.zoom) -
            self.viewport.pan_y;
        return .{ .x = world_x, .y = world_y };
    }

    // Set zoom level.
    pub fn set_zoom(self: *Canvas, zoom: f64) void {
        std.debug.assert(zoom >= MIN_ZOOM);
        std.debug.assert(zoom <= MAX_ZOOM);
        self.viewport.zoom = zoom;
        std.debug.assert(self.viewport.zoom >= MIN_ZOOM);
        std.debug.assert(self.viewport.zoom <= MAX_ZOOM);
    }

    // Zoom in.
    pub fn zoom_in(self: *Canvas) void {
        const new_zoom = self.viewport.zoom * 1.2;
        if (new_zoom <= MAX_ZOOM) {
            self.set_zoom(new_zoom);
        } else {
            self.set_zoom(MAX_ZOOM);
        }
    }

    // Zoom out.
    pub fn zoom_out(self: *Canvas) void {
        const new_zoom = self.viewport.zoom / 1.2;
        if (new_zoom >= MIN_ZOOM) {
            self.set_zoom(new_zoom);
        } else {
            self.set_zoom(MIN_ZOOM);
        }
    }

    // Pan canvas.
    pub fn pan(self: *Canvas, dx: f64, dy: f64) void {
        self.viewport.pan_x += dx;
        self.viewport.pan_y += dy;
    }

    // Create new layer.
    pub fn create_layer(self: *Canvas, name: []const u8) ?u32 {
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= 64);
        if (self.layers_len >= MAX_LAYERS) {
            return null;
        }
        const layer_id = self.next_layer_id;
        self.next_layer_id += 1;
        var layer = Layer{
            .id = layer_id,
            .name = undefined,
            .name_len = 0,
            .visible = true,
            .locked = false,
            .z_order = self.layers_len,
            .shapes = undefined,
            .shapes_len = 0,
            .texts = undefined,
            .texts_len = 0,
        };
        const name_len = @min(name.len, 64);
        @memset(layer.name[0..name_len], 0);
        @memcpy(layer.name[0..name_len], name[0..name_len]);
        layer.name_len = @as(u32, @intCast(name_len));
        self.layers[self.layers_len] = layer;
        self.layers_len += 1;
        std.debug.assert(self.layers_len <= MAX_LAYERS);
        return layer_id;
    }

    // Get layer by ID.
    pub fn get_layer(self: *Canvas, layer_id: u32) ?*Layer {
        std.debug.assert(layer_id > 0);
        var i: u32 = 0;
        while (i < self.layers_len) : (i += 1) {
            if (self.layers[i].id == layer_id) {
                return &self.layers[i];
            }
        }
        return null;
    }

    // Add shape to layer.
    pub fn add_shape(
        self: *Canvas,
        layer_id: u32,
        shape_type: ShapeType,
        x: f64,
        y: f64,
        width: f64,
        height: f64,
        color: u32,
        corner_radius: f64,
    ) ?u32 {
        return self.add_shape_with_stroke(
            layer_id,
            shape_type,
            x,
            y,
            width,
            height,
            color,
            corner_radius,
            0.0,
            0x000000FF,
        );
    }

    // Add shape to layer with stroke.
    pub fn add_shape_with_stroke(
        self: *Canvas,
        layer_id: u32,
        shape_type: ShapeType,
        x: f64,
        y: f64,
        width: f64,
        height: f64,
        color: u32,
        corner_radius: f64,
        stroke_width: f64,
        stroke_color: u32,
    ) ?u32 {
        std.debug.assert(layer_id > 0);
        std.debug.assert(width > 0.0);
        std.debug.assert(height > 0.0);
        std.debug.assert(corner_radius >= 0.0);
        std.debug.assert(stroke_width >= 0.0);
        if (self.get_layer(layer_id)) |layer| {
            if (layer.shapes_len >= MAX_SHAPES) {
                return null;
            }
            const shape_id = self.next_shape_id;
            self.next_shape_id += 1;
            const z_order = layer.shapes_len;
            const shape = Shape{
                .id = shape_id,
                .shape_type = shape_type,
                .x = x,
                .y = y,
                .width = width,
                .height = height,
                .color = color,
                .corner_radius = corner_radius,
                .stroke_width = stroke_width,
                .stroke_color = stroke_color,
                .layer_id = layer_id,
                .z_order = z_order,
            };
            layer.shapes[layer.shapes_len] = shape;
            layer.shapes_len += 1;
            // Record undo command.
            if (self.undo_redo) |manager| {
                var command = undo_redo.Command.init();
                command.command_type = .add_shape;
                command.shape_id = shape_id;
                command.shape_data = shape;
                command.layer_id = layer_id;
                manager.push_undo(command);
            }
            std.debug.assert(layer.shapes_len <= MAX_SHAPES);
            return shape_id;
        }
        return null;
    }

    // Add text to layer.
    pub fn add_text(
        self: *Canvas,
        layer_id: u32,
        x: f64,
        y: f64,
        content: []const u8,
        font_size: u32,
        color: u32,
    ) ?u32 {
        std.debug.assert(layer_id > 0);
        std.debug.assert(content.len > 0);
        std.debug.assert(content.len <= MAX_TEXT_LEN);
        std.debug.assert(font_size > 0);
        if (self.get_layer(layer_id)) |layer| {
            if (layer.texts_len >= MAX_TEXT_ITEMS) {
                return null;
            }
            const text_id = self.next_text_id;
            self.next_text_id += 1;
            const z_order = layer.texts_len;
            var text = Text{
                .id = text_id,
                .x = x,
                .y = y,
                .content = undefined,
                .content_len = 0,
                .font_size = font_size,
                .color = color,
                .layer_id = layer_id,
                .z_order = z_order,
            };
            const content_len = @min(content.len, MAX_TEXT_LEN);
            @memset(text.content[0..content_len], 0);
            @memcpy(text.content[0..content_len],
content[0..content_len]);
            text.content_len = @as(u32, @intCast(content_len));
            layer.texts[layer.texts_len] = text;
            layer.texts_len += 1;
            std.debug.assert(layer.texts_len <= MAX_TEXT_ITEMS);
            return text_id;
        }
        return null;
    }

    // Clear selection.
    pub fn clear_selection(self: *Canvas) void {
        self.selection_len = 0;
        self.selection_type = .none;
        std.debug.assert(self.selection_len == 0);
    }

    // Select shape by ID.
    pub fn select_shape(self: *Canvas, shape_id: u32) bool {
        std.debug.assert(shape_id > 0);
        if (self.selection_len >= MAX_SELECTION) {
            return false;
        }
        self.selection[self.selection_len] = shape_id;
        self.selection_len += 1;
        self.selection_type = .shape;
        std.debug.assert(self.selection_len <= MAX_SELECTION);
        return true;
    }

    // Find shape at world coordinates (hit testing).
    pub fn find_shape_at(
        self: *const Canvas,
        world_x: f64,
        world_y: f64,
    ) ?u32 {
        // Search layers in reverse z-order (top to bottom).
        var layer_i: u32 = self.layers_len;
        while (layer_i > 0) {
            layer_i -= 1;
            const layer = &self.layers[layer_i];
            if (!layer.visible or layer.locked) {
                continue;
            }
            // Search shapes in reverse z-order.
            var shape_i: u32 = layer.shapes_len;
            while (shape_i > 0) {
                shape_i -= 1;
                const shape = &layer.shapes[shape_i];
                if (self.is_point_in_shape(world_x, world_y, shape)) {
                    return shape.id;
                }
            }
        }
        return null;
    }

    // Check if point is inside shape (hit testing).
    pub fn is_point_in_shape(
        _: *const Canvas,
        world_x: f64,
        world_y: f64,
        shape: *const Shape,
    ) bool {
        std.debug.assert(@intFromPtr(shape) != 0);
        switch (shape.shape_type) {
            .rectangle => {
                return (world_x >= shape.x and world_x <= shape.x +
shape.width and
                    world_y >= shape.y and world_y <= shape.y +
shape.height);
            },
            .rounded_rectangle => {
                return is_point_in_rounded_rect(
                    world_x,
                    world_y,
                    shape.x,
                    shape.y,
                    shape.width,
                    shape.height,
                    shape.corner_radius,
                );
            },
            .circle => {
                const center_x = shape.x + shape.width / 2.0;
                const center_y = shape.y + shape.height / 2.0;
                const radius = @min(shape.width, shape.height) / 2.0;
                const dx = world_x - center_x;
                const dy = world_y - center_y;
                const distance_squared = dx * dx + dy * dy;
                const radius_squared = radius * radius;
                return distance_squared <= radius_squared;
            },
        }
    }

    // Check if point is inside rounded rectangle (with corner radius).
    fn is_point_in_rounded_rect(
        point_x: f64,
        point_y: f64,
        rect_x: f64,
        rect_y: f64,
        rect_width: f64,
        rect_height: f64,
        corner_radius: f64,
    ) bool {
        std.debug.assert(rect_width > 0.0);
        std.debug.assert(rect_height > 0.0);
        std.debug.assert(corner_radius >= 0.0);
        const radius = @min(corner_radius, @min(rect_width, rect_height)
/ 2.0);
        if (radius == 0.0) {
            // Simple rectangle.
            return (point_x >= rect_x and point_x <= rect_x + rect_width
and
                point_y >= rect_y and point_y <= rect_y + rect_height);
        }
        const radius_squared = radius * radius;
        // Check if point is in main rectangular body (excluding
corners).
        const left_edge = rect_x + radius;
        const right_edge = rect_x + rect_width - radius;
        const top_edge = rect_y + radius;
        const bottom_edge = rect_y + rect_height - radius;
        if (point_x >= left_edge and point_x <= right_edge and
            point_y >= top_edge and point_y <= bottom_edge)
        {
            return true;
        }
        // Check if point is in one of the four corner quarter-circles.
        // Top-left corner.
        if (point_x < left_edge and point_y < top_edge) {
            const corner_center_x = left_edge;
            const corner_center_y = top_edge;
            const dx = point_x - corner_center_x;
            const dy = point_y - corner_center_y;
            const distance_squared = dx * dx + dy * dy;
            if (distance_squared <= radius_squared) {
                return true;
            }
        }
        // Top-right corner.
        if (point_x > right_edge and point_y < top_edge) {
            const corner_center_x = right_edge;
            const corner_center_y = top_edge;
            const dx = point_x - corner_center_x;
            const dy = point_y - corner_center_y;
            const distance_squared = dx * dx + dy * dy;
            if (distance_squared <= radius_squared) {
                return true;
            }
        }
        // Bottom-left corner.
        if (point_x < left_edge and point_y > bottom_edge) {
            const corner_center_x = left_edge;
            const corner_center_y = bottom_edge;
            const dx = point_x - corner_center_x;
            const dy = point_y - corner_center_y;
            const distance_squared = dx * dx + dy * dy;
            if (distance_squared <= radius_squared) {
                return true;
            }
        }
        // Bottom-right corner.
        if (point_x > right_edge and point_y > bottom_edge) {
            const corner_center_x = right_edge;
            const corner_center_y = bottom_edge;
            const dx = point_x - corner_center_x;
            const dy = point_y - corner_center_y;
            const distance_squared = dx * dx + dy * dy;
            if (distance_squared <= radius_squared) {
                return true;
            }
        }
        return false;
    }

    // Move shape by offset.
    pub fn move_shape(
        self: *Canvas,
        shape_id: u32,
        dx: f64,
        dy: f64,
    ) bool {
        std.debug.assert(shape_id > 0);
        var layer_i: u32 = 0;
        while (layer_i < self.layers_len) : (layer_i += 1) {
            const layer = &self.layers[layer_i];
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                if (layer.shapes[shape_i].id == shape_id) {
                    const shape = &layer.shapes[shape_i];
                    // Record undo command.
                    if (self.undo_redo) |manager| {
                        var command = undo_redo.Command.init();
                        command.command_type = .move_shape;
                        command.shape_id = shape_id;
                        command.old_x = shape.x;
                        command.old_y = shape.y;
                        command.new_x = shape.x + dx;
                        command.new_y = shape.y + dy;
                        command.layer_id = shape.layer_id;
                        manager.push_undo(command);
                    }
                    shape.x += dx;
                    shape.y += dy;
                    return true;
                }
            }
        }
        return false;
    }

    // Resize shape.
    pub fn resize_shape(
        self: *Canvas,
        shape_id: u32,
        new_width: f64,
        new_height: f64,
    ) bool {
        std.debug.assert(shape_id > 0);
        std.debug.assert(new_width > 0.0);
        std.debug.assert(new_height > 0.0);
        var layer_i: u32 = 0;
        while (layer_i < self.layers_len) : (layer_i += 1) {
            const layer = &self.layers[layer_i];
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                if (layer.shapes[shape_i].id == shape_id) {
                    layer.shapes[shape_i].width = new_width;
                    layer.shapes[shape_i].height = new_height;
                    return true;
                }
            }
        }
        return false;
    }

    // Get shape by ID.
    pub fn get_shape(self: *const Canvas, shape_id: u32) ?*const Shape {
        std.debug.assert(shape_id > 0);
        var layer_i: u32 = 0;
        while (layer_i < self.layers_len) : (layer_i += 1) {
            const layer = &self.layers[layer_i];
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                if (layer.shapes[shape_i].id == shape_id) {
                    return &layer.shapes[shape_i];
                }
            }
        }
        return null;
    }

    // Duplicate shape by ID.
    pub fn duplicate_shape(
        self: *Canvas,
        shape_id: u32,
        offset_x: f64,
        offset_y: f64,
    ) ?u32 {
        std.debug.assert(shape_id > 0);
        var layer_i: u32 = 0;
        while (layer_i < self.layers_len) : (layer_i += 1) {
            const layer = &self.layers[layer_i];
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                if (layer.shapes[shape_i].id == shape_id) {
                    const original = layer.shapes[shape_i];
                    if (layer.shapes_len >= MAX_SHAPES) {
                        return null;
                    }
                    const new_shape_id = self.next_shape_id;
                    self.next_shape_id += 1;
                    const new_shape = Shape{
                        .id = new_shape_id,
                        .shape_type = original.shape_type,
                        .x = original.x + offset_x,
                        .y = original.y + offset_y,
                        .width = original.width,
                        .height = original.height,
                        .color = original.color,
                        .corner_radius = original.corner_radius,
                        .stroke_width = original.stroke_width,
                        .stroke_color = original.stroke_color,
                        .layer_id = original.layer_id,
                        .z_order = layer.shapes_len,
                    };
                    layer.shapes[layer.shapes_len] = new_shape;
                    layer.shapes_len += 1;
                    std.debug.assert(layer.shapes_len <= MAX_SHAPES);
                    return new_shape_id;
                }
            }
        }
        return null;
    }

    // Copy selected shapes to clipboard.
    pub fn copy_selected_shapes(self: *Canvas) bool {
        std.debug.assert(self.selection_len <= MAX_SELECTION);
        if (self.selection_len == 0) {
            return false;
        }
        self.clipboard_len = 0;
        var i: u32 = 0;
        while (i < self.selection_len and self.clipboard_len <
MAX_CLIPBOARD_SHAPES) : (i += 1) {
            const shape_id = self.selection[i];
            if (self.get_shape(shape_id)) |shape| {
                self.clipboard[self.clipboard_len] = shape.*;
                self.clipboard_len += 1;
            }
        }
        std.debug.assert(self.clipboard_len <= MAX_CLIPBOARD_SHAPES);
        return self.clipboard_len > 0;
    }

    // Paste shapes from clipboard to layer.
    pub fn paste_shapes(
        self: *Canvas,
        layer_id: u32,
        offset_x: f64,
        offset_y: f64,
    ) u32 {
        std.debug.assert(layer_id > 0);
        if (self.clipboard_len == 0) {
            return 0;
        }
        if (self.get_layer(layer_id)) |layer| {
            var pasted_count: u32 = 0;
            var i: u32 = 0;
            while (i < self.clipboard_len and layer.shapes_len <
MAX_SHAPES) : (i += 1) {
                const clipboard_shape = self.clipboard[i];
                const new_shape_id = self.next_shape_id;
                self.next_shape_id += 1;
                const new_shape = Shape{
                    .id = new_shape_id,
                    .shape_type = clipboard_shape.shape_type,
                    .x = clipboard_shape.x + offset_x,
                    .y = clipboard_shape.y + offset_y,
                    .width = clipboard_shape.width,
                    .height = clipboard_shape.height,
                    .color = clipboard_shape.color,
                    .corner_radius = clipboard_shape.corner_radius,
                    .stroke_width = clipboard_shape.stroke_width,
                    .stroke_color = clipboard_shape.stroke_color,
                    .layer_id = layer_id,
                    .z_order = layer.shapes_len,
                };
                layer.shapes[layer.shapes_len] = new_shape;
                layer.shapes_len += 1;
                pasted_count += 1;
            }
            std.debug.assert(layer.shapes_len <= MAX_SHAPES);
            return pasted_count;
        }
        return 0;
    }

    // Duplicate selected shapes.
    pub fn duplicate_selected_shapes(
        self: *Canvas,
        offset_x: f64,
        offset_y: f64,
    ) u32 {
        std.debug.assert(self.selection_len <= MAX_SELECTION);
        if (self.selection_len == 0) {
            return 0;
        }
        var duplicated_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.selection_len) : (i += 1) {
            const shape_id = self.selection[i];
            if (self.duplicate_shape(shape_id, offset_x, offset_y)) |_| {
                duplicated_count += 1;
            }
        }
        return duplicated_count;
    }

    // Set undo/redo manager.
    pub fn set_undo_redo_manager(self: *Canvas, manager:
*undo_redo.UndoRedoManager) void {
        std.debug.assert(@intFromPtr(manager) != 0);
        self.undo_redo = manager;
        std.debug.assert(self.undo_redo != null);
    }

    // Undo last operation.
    pub fn undo(self: *Canvas) bool {
        if (self.undo_redo) |manager| {
            if (!manager.can_undo()) {
                return false;
            }
            const command_opt = manager.pop_undo();
            if (command_opt) |command| {
                return self.execute_undo_command(command, manager);
            }
        }
        return false;
    }

    // Redo last undone operation.
    pub fn redo(self: *Canvas) bool {
        if (self.undo_redo) |manager| {
            if (!manager.can_redo()) {
                return false;
            }
            const command_opt = manager.pop_redo();
            if (command_opt) |command| {
                return self.execute_redo_command(command, manager);
            }
        }
        return false;
    }

    // Execute undo command.
    fn execute_undo_command(
        self: *Canvas,
        command: undo_redo.Command,
        manager: *undo_redo.UndoRedoManager,
    ) bool {
        _ = manager; // Reserved for future use (e.g., recording redo).
        switch (command.command_type) {
            .add_shape => {
                // Undo add: delete the shape.
                self.delete_shape_without_undo(command.shape_id);
                return true;
            },
            .delete_shape => {
                // Undo delete: restore the shape.
                if (self.get_layer(command.layer_id)) |layer| {
                    if (layer.shapes_len < MAX_SHAPES) {
                        layer.shapes[layer.shapes_len] =
command.shape_data;
                        layer.shapes_len += 1;
                        return true;
                    }
                }
                return false;
            },
            .move_shape => {
                // Undo move: restore old position.
                if (self.get_shape_mut(command.shape_id)) |shape| {
                    shape.x = command.old_x;
                    shape.y = command.old_y;
                    return true;
                }
                return false;
            },
            else => {
                // Other operations not yet implemented.
                return false;
            },
        }
    }

    // Execute redo command.
    fn execute_redo_command(
        self: *Canvas,
        command: undo_redo.Command,
        manager: *undo_redo.UndoRedoManager,
    ) bool {
        _ = manager; // Reserved for future use (e.g., recording undo).
        switch (command.command_type) {
            .add_shape => {
                // Redo add: restore the shape.
                if (self.get_layer(command.layer_id)) |layer| {
                    if (layer.shapes_len < MAX_SHAPES) {
                        layer.shapes[layer.shapes_len] =
command.shape_data;
                        layer.shapes_len += 1;
                        return true;
                    }
                }
                return false;
            },
            .delete_shape => {
                // Redo delete: delete the shape.
                self.delete_shape_without_undo(command.shape_id);
                return true;
            },
            .move_shape => {
                // Redo move: apply new position.
                if (self.get_shape_mut(command.shape_id)) |shape| {
                    shape.x = command.new_x;
                    shape.y = command.new_y;
                    return true;
                }
                return false;
            },
            else => {
                // Other operations not yet implemented.
                return false;
            },
        }
    }

    // Delete shape without recording undo (for undo/redo operations).
    fn delete_shape_without_undo(self: *Canvas, shape_id: u32) void {
        var layer_i: u32 = 0;
        while (layer_i < self.layers_len) : (layer_i += 1) {
            var layer = &self.layers[layer_i];
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                if (layer.shapes[shape_i].id == shape_id) {
                    // Shift elements to remove the shape.
                    var j: u32 = shape_i;
                    while (j < layer.shapes_len - 1) : (j += 1) {
                        layer.shapes[j] = layer.shapes[j + 1];
                    }
                    layer.shapes_len -= 1;
                    return;
                }
            }
        }
    }

    // Delete a single shape (with undo recording).
    pub fn delete_shape(self: *Canvas, shape_id: u32) void {
        var layer_i: u32 = 0;
        while (layer_i < self.layers_len) : (layer_i += 1) {
            var layer = &self.layers[layer_i];
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                if (layer.shapes[shape_i].id == shape_id) {
                    // Record undo command.
                    if (self.undo_redo) |manager| {
                        var command = undo_redo.Command.init();
                        command.command_type = .delete_shape;
                        command.shape_id = shape_id;
                        command.shape_data = layer.shapes[shape_i];
                        command.layer_id = layer.id;
                        manager.push_undo(command);
                    }
                    // Shift elements to remove the shape.
                    var j: u32 = shape_i;
                    while (j < layer.shapes_len - 1) : (j += 1) {
                        layer.shapes[j] = layer.shapes[j + 1];
                    }
                    layer.shapes_len -= 1;
                    return;
                }
            }
        }
    }
};


// === grain_bubble/canvas_input.zig ===

//! Grain Bubble Canvas Input: Handle mouse and keyboard input for
canvas.
//!
//! Why: Enable interactive canvas operations (select, pan, zoom).
//! Architecture: Input events → Canvas operations.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-06-014041-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");
const grain_core = @import("grain_core");

// Input mode: what operation is active.
pub const InputMode = enum(u8) {
    select, // Select and manipulate shapes
    pan, // Pan canvas
    none, // No active operation
};

// Canvas input handler: processes input events for canvas.
pub const CanvasInputHandler = struct {
    canvas: *canvas.Canvas,
    mode: InputMode,
    is_dragging: bool,
    drag_start_x: i32,
    drag_start_y: i32,
    drag_last_x: i32,
    drag_last_y: i32,

    pub fn init(canvas_data: *canvas.Canvas) CanvasInputHandler {
        std.debug.assert(@intFromPtr(canvas_data) != 0);
        const handler = CanvasInputHandler{
            .canvas = canvas_data,
            .mode = .select,
            .is_dragging = false,
            .drag_start_x = 0,
            .drag_start_y = 0,
            .drag_last_x = 0,
            .drag_last_y = 0,
        };
        std.debug.assert(handler.canvas.viewport.width > 0);
        std.debug.assert(handler.canvas.viewport.height > 0);
        return handler;
    }

    // Process mouse event.
    pub fn handle_mouse_event(
        self: *CanvasInputHandler,
        event: grain_core.input_handler.InputEvent,
    ) void {
        std.debug.assert(event.event_type == .mouse);
        switch (event.mouse.kind) {
            .down => {
                self.handle_mouse_down(event.mouse.x, event.mouse.y,
event.mouse.button);
            },
            .up => {
                self.handle_mouse_up(event.mouse.x, event.mouse.y);
            },
            .move => {
                self.handle_mouse_move(event.mouse.x, event.mouse.y);
            },
            .drag => {
                self.handle_mouse_drag(event.mouse.x, event.mouse.y);
            },
        }
    }

    // Handle mouse button down.
    fn handle_mouse_down(
        self: *CanvasInputHandler,
        screen_x: u32,
        screen_y: u32,
        button: u8,
    ) void {
        std.debug.assert(screen_x < self.canvas.viewport.width);
        std.debug.assert(screen_y < self.canvas.viewport.height);
        const world_pos = self.canvas.screen_to_world(
            @as(i32, @intCast(screen_x)),
            @as(i32, @intCast(screen_y)),
        );
        if (button == 0) {
            // Left button: select or start pan.
            if (self.mode == .pan) {
                self.is_dragging = true;
                self.drag_start_x = @as(i32, @intCast(screen_x));
                self.drag_start_y = @as(i32, @intCast(screen_y));
                self.drag_last_x = self.drag_start_x;
                self.drag_last_y = self.drag_start_y;
            } else {
                // Select mode: find shape at position.
                if (self.canvas.find_shape_at(world_pos.x, world_pos.y))
|shape_id| {
                    self.canvas.clear_selection();
                    _ = self.canvas.select_shape(shape_id);
                    self.is_dragging = true;
                    self.drag_start_x = @as(i32, @intCast(screen_x));
                    self.drag_start_y = @as(i32, @intCast(screen_y));
                    self.drag_last_x = self.drag_start_x;
                    self.drag_last_y = self.drag_start_y;
                } else {
                    // No shape: clear selection.
                    self.canvas.clear_selection();
                }
            }
        }
    }

    // Handle mouse button up.
    fn handle_mouse_up(
        self: *CanvasInputHandler,
        screen_x: u32,
        screen_y: u32,
    ) void {
        std.debug.assert(screen_x < self.canvas.viewport.width);
        std.debug.assert(screen_y < self.canvas.viewport.height);
        self.is_dragging = false;
        self.drag_start_x = 0;
        self.drag_start_y = 0;
        self.drag_last_x = 0;
        self.drag_last_y = 0;
    }

    // Handle mouse move.
    fn handle_mouse_move(
        self: *CanvasInputHandler,
        screen_x: u32,
        screen_y: u32,
    ) void {
        std.debug.assert(screen_x < self.canvas.viewport.width);
        std.debug.assert(screen_y < self.canvas.viewport.height);
        if (self.is_dragging) {
            const dx = @as(i32, @intCast(screen_x)) - self.drag_last_x;
            const dy = @as(i32, @intCast(screen_y)) - self.drag_last_y;
            if (self.mode == .pan) {
                // Pan canvas.
                const world_dx = @as(f64, @floatFromInt(dx)) /
self.canvas.viewport.zoom;
                const world_dy = @as(f64, @floatFromInt(dy)) /
self.canvas.viewport.zoom;
                self.canvas.pan(-world_dx, -world_dy);
            } else {
                // Move selected shape.
                if (self.canvas.selection_len > 0) {
                    const world_dx = @as(f64, @floatFromInt(dx)) /
self.canvas.viewport.zoom;
                    const world_dy = @as(f64, @floatFromInt(dy)) /
self.canvas.viewport.zoom;
                    var i: u32 = 0;
                    while (i < self.canvas.selection_len) : (i += 1) {
                        _ = self.canvas.move_shape(
                            self.canvas.selection[i],
                            world_dx,
                            world_dy,
                        );
                    }
                }
            }
            self.drag_last_x = @as(i32, @intCast(screen_x));
            self.drag_last_y = @as(i32, @intCast(screen_y));
        }
    }

    // Handle mouse drag (explicit drag event).
    fn handle_mouse_drag(
        self: *CanvasInputHandler,
        screen_x: u32,
        screen_y: u32,
    ) void {
        std.debug.assert(screen_x < self.canvas.viewport.width);
        std.debug.assert(screen_y < self.canvas.viewport.height);
        // Treat drag same as move when dragging.
        self.handle_mouse_move(screen_x, screen_y);
    }

    // Handle mouse wheel (zoom).
    pub fn handle_mouse_wheel(
        self: *CanvasInputHandler,
        delta: i32,
        screen_x: u32,
        screen_y: u32,
    ) void {
        std.debug.assert(screen_x < self.canvas.viewport.width);
        std.debug.assert(screen_y < self.canvas.viewport.height);
        // Zoom at mouse position.
        const world_pos = self.canvas.screen_to_world(
            @as(i32, @intCast(screen_x)),
            @as(i32, @intCast(screen_y)),
        );
        if (delta > 0) {
            self.canvas.zoom_in();
        } else {
            self.canvas.zoom_out();
        }
        // Adjust pan to keep world position under cursor.
        const new_world_pos = self.canvas.screen_to_world(
            @as(i32, @intCast(screen_x)),
            @as(i32, @intCast(screen_y)),
        );
        const pan_dx = world_pos.x - new_world_pos.x;
        const pan_dy = world_pos.y - new_world_pos.y;
        self.canvas.pan(pan_dx, pan_dy);
        std.debug.assert(self.canvas.viewport.zoom >= canvas.MIN_ZOOM);
        std.debug.assert(self.canvas.viewport.zoom <= canvas.MAX_ZOOM);
    }

    // Process keyboard event.
    pub fn handle_keyboard_event(
        self: *CanvasInputHandler,
        event: grain_core.input_handler.InputEvent,
    ) void {
        std.debug.assert(event.event_type == .keyboard);
        if (event.keyboard.kind == .down) {
            self.handle_key_down(event.keyboard.key_code,
event.keyboard.modifiers);
        }
    }

    // Handle key down event.
    fn handle_key_down(
        self: *CanvasInputHandler,
        key_code: u32,
        modifiers: u8,
    ) void {
        const MODIFIER_CTRL: u8 = 0x01;
        const MODIFIER_SHIFT: u8 = 0x04;
        const KEY_DELETE: u32 = 0x2E;
        const KEY_BACKSPACE: u32 = 0x08;
        const KEY_SPACE: u32 = 0x20;
        const KEY_PLUS: u32 = 0x3D; // Equals key
        const KEY_MINUS: u32 = 0x2D;
        const KEY_LEFT: u32 = 0x25;
        const KEY_UP: u32 = 0x26;
        const KEY_RIGHT: u32 = 0x27;
        const KEY_DOWN: u32 = 0x28;
        const KEY_Z: u32 = 0x5A;
        const KEY_Y: u32 = 0x59;
        const KEY_C: u32 = 0x43;
        const KEY_V: u32 = 0x56;
        const KEY_D: u32 = 0x44;
        if (key_code == KEY_DELETE or key_code == KEY_BACKSPACE) {
            // Delete selected shapes.
            self.delete_selected_shapes();
        } else if ((modifiers & MODIFIER_CTRL) != 0 and key_code ==
KEY_Z) {
            // Ctrl+Z: Undo.
            _ = self.canvas.undo();
        } else if ((modifiers & MODIFIER_CTRL) != 0 and key_code ==
KEY_Y) {
            // Ctrl+Y: Redo.
            _ = self.canvas.redo();
        } else if ((modifiers & MODIFIER_CTRL) != 0 and key_code ==
KEY_C) {
            // Ctrl+C: Copy selected shapes.
            self.canvas.copy_selected_shapes();
        } else if ((modifiers & MODIFIER_CTRL) != 0 and key_code ==
KEY_V) {
            // Ctrl+V: Paste shapes at current position.
            const center_x = @as(f64,
@floatFromInt(self.canvas.viewport.width)) / 2.0;
            const center_y = @as(f64,
@floatFromInt(self.canvas.viewport.height)) / 2.0;
            if (self.canvas.selection_len > 0) {
                // Paste to same layer as first selected shape.
                const first_shape_id = self.canvas.selection[0];
                if (self.canvas.get_shape(first_shape_id)) |shape| {
                    if (self.canvas.get_layer(shape.layer_id)) |layer| {
                        const pasted =
self.canvas.paste_shapes(layer.id, center_x, center_y);
                        if (pasted > 0) {
                            // Select pasted shapes.
                            self.canvas.clear_selection();
                            var i: u32 = 0;
                            while (i < pasted and i <
canvas.MAX_SELECTION) : (i += 1) {
                                const new_shape_id =
self.canvas.next_shape_id - pasted + i;
                                _ =
self.canvas.select_shape(new_shape_id);
                            }
                        }
                    }
                }
            } else {
                // Paste to first layer if no selection.
                if (self.canvas.layers_len > 0) {
                    const pasted = self.canvas.paste_shapes(
                        self.canvas.layers[0].id,
                        center_x,
                        center_y,
                    );
                    if (pasted > 0) {
                        // Select pasted shapes.
                        self.canvas.clear_selection();
                        var i: u32 = 0;
                        while (i < pasted and i < canvas.MAX_SELECTION)
: (i += 1) {
                            const new_shape_id =
self.canvas.next_shape_id - pasted + i;
                            _ = self.canvas.select_shape(new_shape_id);
                        }
                    }
                }
            }
        } else if ((modifiers & MODIFIER_CTRL) != 0 and key_code ==
KEY_D) {
            // Ctrl+D: Duplicate selected shapes.
            const DUPLICATE_OFFSET: f64 = 10.0;
            const duplicated = self.canvas.duplicate_selected_shapes(
                DUPLICATE_OFFSET,
                DUPLICATE_OFFSET,
            );
            if (duplicated > 0) {
                // Select duplicated shapes.
                self.canvas.clear_selection();
                var i: u32 = 0;
                while (i < duplicated and i < canvas.MAX_SELECTION) : (i
+= 1) {
                    const new_shape_id = self.canvas.next_shape_id -
duplicated + i;
                    _ = self.canvas.select_shape(new_shape_id);
                }
            }
        } else if (key_code == KEY_SPACE) {
            // Space: Toggle pan mode.
            if (self.mode == .pan) {
                self.set_mode(.select);
            } else {
                self.set_mode(.pan);
            }
        } else if (key_code == KEY_PLUS or key_code == KEY_MINUS) {
            // Plus/Minus: Zoom in/out at center.
            const center_x = self.canvas.viewport.width / 2;
            const center_y = self.canvas.viewport.height / 2;
            if (key_code == KEY_PLUS) {
                self.handle_mouse_wheel(1, center_x, center_y);
            } else {
                self.handle_mouse_wheel(-1, center_x, center_y);
            }
        } else if (key_code == KEY_LEFT or key_code == KEY_RIGHT or
            key_code == KEY_UP or key_code == KEY_DOWN)
        {
            // Arrow keys: Move selected shapes.
            const MOVE_STEP: f64 = 1.0;
            var dx: f64 = 0.0;
            var dy: f64 = 0.0;
            if (key_code == KEY_LEFT) {
                dx = -MOVE_STEP;
            } else if (key_code == KEY_RIGHT) {
                dx = MOVE_STEP;
            } else if (key_code == KEY_UP) {
                dy = -MOVE_STEP;
            } else if (key_code == KEY_DOWN) {
                dy = MOVE_STEP;
            }
            if ((modifiers & MODIFIER_SHIFT) != 0) {
                // Shift: Move by larger step.
                dx *= 10.0;
                dy *= 10.0;
            }
            self.move_selected_shapes(dx, dy);
        }
    }

    // Delete selected shapes.
    fn delete_selected_shapes(self: *CanvasInputHandler) void {
        var i: u32 = 0;
        while (i < self.canvas.selection_len) : (i += 1) {
            const shape_id = self.canvas.selection[i];
            self.delete_shape(shape_id);
        }
        self.canvas.clear_selection();
        std.debug.assert(self.canvas.selection_len == 0);
    }

    // Delete shape by ID.
    fn delete_shape(self: *CanvasInputHandler, shape_id: u32) void {
        std.debug.assert(shape_id > 0);
        var layer_i: u32 = 0;
        while (layer_i < self.canvas.layers_len) : (layer_i += 1) {
            const layer = &self.canvas.layers[layer_i];
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                if (layer.shapes[shape_i].id == shape_id) {
                    // Remove shape by shifting remaining shapes.
                    var j: u32 = shape_i;
                    while (j < layer.shapes_len - 1) : (j += 1) {
                        layer.shapes[j] = layer.shapes[j + 1];
                    }
                    layer.shapes_len -= 1;
                    return;
                }
            }
        }
    }

    // Move selected shapes by offset.
    fn move_selected_shapes(
        self: *CanvasInputHandler,
        dx: f64,
        dy: f64,
    ) void {
        var i: u32 = 0;
        while (i < self.canvas.selection_len) : (i += 1) {
            _ = self.canvas.move_shape(
                self.canvas.selection[i],
                dx,
                dy,
            );
        }
    }

    // Set input mode.
    pub fn set_mode(self: *CanvasInputHandler, mode: InputMode) void {
        self.mode = mode;
        self.is_dragging = false;
        std.debug.assert(self.mode == mode);
    }
};


// === grain_bubble/canvas_renderer.zig ===

//! Grain Bubble Canvas Renderer: Render canvas to framebuffer.
//!
//! Why: Bridge canvas engine with framebuffer renderer for display.
//! Architecture: Canvas → Bubble Renderer → Framebuffer Renderer.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-06-011503-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");
const bubble_renderer = @import("bubble_renderer.zig");
const grain_core = @import("grain_core");

// Thread-local renderer context for draw callbacks.
var current_renderer: ?*const CanvasRenderer = null;

// Canvas renderer: renders canvas to framebuffer.
pub const CanvasRenderer = struct {
    canvas: *canvas.Canvas,
    bubble_renderer: bubble_renderer.BubbleRenderer,
    framebuffer_renderer:
*grain_core.framebuffer_renderer.FramebufferRenderer,

    pub fn init(
        canvas_data: *canvas.Canvas,
        fb_renderer:
*grain_core.framebuffer_renderer.FramebufferRenderer,
    ) CanvasRenderer {
        std.debug.assert(@intFromPtr(canvas_data) != 0);
        std.debug.assert(@intFromPtr(fb_renderer) != 0);
        const width = canvas_data.viewport.width;
        const height = canvas_data.viewport.height;
        const renderer = CanvasRenderer{
            .canvas = canvas_data,
            .bubble_renderer =
bubble_renderer.BubbleRenderer.init(width, height),
            .framebuffer_renderer = fb_renderer,
        };
        std.debug.assert(renderer.canvas.viewport.width > 0);
        std.debug.assert(renderer.canvas.viewport.height > 0);
        return renderer;
    }

    // Render entire canvas to framebuffer.
    pub fn render_canvas(self: *const CanvasRenderer) void {
        std.debug.assert(@intFromPtr(self.canvas) != 0);
        std.debug.assert(@intFromPtr(self.framebuffer_renderer) != 0);
        // Set thread-local renderer context.
        current_renderer = self;
        // Clear framebuffer to background color.
        self.framebuffer_renderer.clear(0x1E1E2EFF);
        // Render layers in z-order (bottom to top).
        var layer_i: u32 = 0;
        while (layer_i < self.canvas.layers_len) : (layer_i += 1) {
            const layer = &self.canvas.layers[layer_i];
            if (!layer.visible) {
                continue;
            }
            // Render shapes in z-order.
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                const shape = &layer.shapes[shape_i];
                self.render_shape(shape);
            }
            // Render text in z-order.
            var text_i: u32 = 0;
            while (text_i < layer.texts_len) : (text_i += 1) {
                const text = &layer.texts[text_i];
                self.render_text(text);
            }
        }
        // Clear thread-local renderer context.
        current_renderer = null;
    }

    // Render single shape.
    fn render_shape(self: *const CanvasRenderer, shape: *const
canvas.Shape) void {
        std.debug.assert(@intFromPtr(shape) != 0);
        std.debug.assert(current_renderer == self);
        // Use bubble renderer to render shape with draw callback.
        self.bubble_renderer.render_shape(shape, &self.canvas.viewport,
draw_pixel_callback);
    }

    // Render single text element.
    fn render_text(self: *const CanvasRenderer, text: *const
canvas.Text) void {
        std.debug.assert(@intFromPtr(text) != 0);
        const screen_pos = self.canvas.world_to_screen(text.x, text.y);
        const screen_x = if (screen_pos.x < 0) 0 else @as(u32,
@intCast(screen_pos.x));
        const screen_y = if (screen_pos.y < 0) 0 else @as(u32,
@intCast(screen_pos.y));
        if (screen_x < self.canvas.viewport.width and
            screen_y < self.canvas.viewport.height)
        {
            const text_content = text.content[0..text.content_len];
            self.framebuffer_renderer.draw_text(
                text_content,
                screen_x,
                screen_y,
                text.color,
            );
        }
    }
};

// Draw pixel callback for bubble renderer (uses thread-local context).
fn draw_pixel_callback(x: u32, y: u32, color: u32) void {
    std.debug.assert(current_renderer != null);
    if (current_renderer) |renderer| {
        std.debug.assert(x < renderer.canvas.viewport.width);
        std.debug.assert(y < renderer.canvas.viewport.height);
        renderer.framebuffer_renderer.draw_pixel(x, y, color);
    }
}


// === grain_bubble/component.zig ===

//! Grain Bubble Component: Reusable design components.
//!
//! Why: Enable reusable design components (buttons, cards, etc.).
//! Architecture: Component library with variants and design tokens.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-06-135535-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");

// Bounded: Max components in library.
pub const MAX_COMPONENTS: u32 = 256;

// Bounded: Max variants per component.
pub const MAX_VARIANTS: u32 = 16;

// Bounded: Max component name length.
pub const MAX_COMPONENT_NAME_LEN: u32 = 64;

// Bounded: Max design tokens.
pub const MAX_DESIGN_TOKENS: u32 = 128;

// Component variant: different state/size/theme of a component.
pub const ComponentVariant = struct {
    id: u32,
    name: [MAX_COMPONENT_NAME_LEN]u8,
    name_len: u32,
    variant_type: VariantType,
    shapes: [canvas.MAX_SHAPES]canvas.Shape,
    shapes_len: u32,
    texts: [canvas.MAX_TEXT_ITEMS]canvas.Text,
    texts_len: u32,

    pub const VariantType = enum(u8) {
        state, // Different state (default, hover, active, disabled)
        size, // Different size (small, medium, large)
        theme, // Different theme (light, dark, custom)
    };

    pub fn init() ComponentVariant {
        var variant = ComponentVariant{
            .id = 0,
            .name = undefined,
            .name_len = 0,
            .variant_type = .state,
            .shapes = undefined,
            .shapes_len = 0,
            .texts = undefined,
            .texts_len = 0,
        };
        @memset(variant.name[0..], 0);
        std.debug.assert(variant.shapes_len == 0);
        std.debug.assert(variant.texts_len == 0);
        return variant;
    }
};

// Design token: reusable design value (color, spacing, typography).
pub const DesignToken = struct {
    id: u32,
    name: [MAX_COMPONENT_NAME_LEN]u8,
    name_len: u32,
    token_type: TokenType,
    value: TokenValue,

    pub const TokenType = enum(u8) {
        color,
        spacing,
        typography,
        radius,
    };

    pub const TokenValue = union(TokenType) {
        color: u32,
        spacing: f64,
        typography: TypographyValue,
        radius: f64,
    };

    pub const TypographyValue = struct {
        font_size: u32,
        line_height: f64,
        letter_spacing: f64,
    };

    pub fn init() DesignToken {
        var token = DesignToken{
            .id = 0,
            .name = undefined,
            .name_len = 0,
            .token_type = .color,
            .value = .{ .color = 0 },
        };
        @memset(token.name[0..], 0);
        return token;
    }
};

// Component: reusable design element.
pub const Component = struct {
    id: u32,
    name: [MAX_COMPONENT_NAME_LEN]u8,
    name_len: u32,
    variants: [MAX_VARIANTS]ComponentVariant,
    variants_len: u32,
    default_variant_id: u32,
    design_tokens: [MAX_DESIGN_TOKENS]DesignToken,
    design_tokens_len: u32,

    pub fn init() Component {
        var component = Component{
            .id = 0,
            .name = undefined,
            .name_len = 0,
            .variants = undefined,
            .variants_len = 0,
            .default_variant_id = 0,
            .design_tokens = undefined,
            .design_tokens_len = 0,
        };
        @memset(component.name[0..], 0);
        var i: u32 = 0;
        while (i < MAX_VARIANTS) : (i += 1) {
            component.variants[i] = ComponentVariant.init();
        }
        i = 0;
        while (i < MAX_DESIGN_TOKENS) : (i += 1) {
            component.design_tokens[i] = DesignToken.init();
        }
        std.debug.assert(component.variants_len == 0);
        std.debug.assert(component.design_tokens_len == 0);
        return component;
    }
};

// Component library: collection of reusable components.
pub const ComponentLibrary = struct {
    components: [MAX_COMPONENTS]Component,
    components_len: u32,
    next_component_id: u32,
    next_variant_id: u32,
    next_token_id: u32,

    pub fn init() ComponentLibrary {
        std.debug.assert(MAX_COMPONENTS > 0);
        std.debug.assert(MAX_VARIANTS > 0);
        std.debug.assert(MAX_DESIGN_TOKENS > 0);
        var library = ComponentLibrary{
            .components = undefined,
            .components_len = 0,
            .next_component_id = 1,
            .next_variant_id = 1,
            .next_token_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_COMPONENTS) : (i += 1) {
            library.components[i] = Component.init();
        }
        std.debug.assert(library.components_len == 0);
        std.debug.assert(library.next_component_id == 1);
        return library;
    }

    // Create component from canvas selection.
    pub fn create_component_from_selection(
        self: *ComponentLibrary,
        canvas_state: *const canvas.Canvas,
        name: []const u8,
    ) ?u32 {
        std.debug.assert(@intFromPtr(canvas_state) != 0);
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= MAX_COMPONENT_NAME_LEN);
        if (self.components_len >= MAX_COMPONENTS) {
            return null;
        }
        if (canvas_state.selection_len == 0) {
            return null;
        }
        const component_id = self.next_component_id;
        self.next_component_id += 1;
        var component = Component.init();
        component.id = component_id;
        const name_len = @min(name.len, MAX_COMPONENT_NAME_LEN);
        @memset(component.name[0..name_len], 0);
        @memcpy(component.name[0..name_len], name[0..name_len]);
        component.name_len = @as(u32, @intCast(name_len));
        // Create default variant from selected shapes.
        var variant = ComponentVariant.init();
        variant.id = self.next_variant_id;
        self.next_variant_id += 1;
        variant.variant_type = .state;
        const variant_name = "default";
        const variant_name_len = @min(variant_name.len,
MAX_COMPONENT_NAME_LEN);
        @memset(variant.name[0..variant_name_len], 0);
        @memcpy(variant.name[0..variant_name_len],
variant_name[0..variant_name_len]);
        variant.name_len = @as(u32, @intCast(variant_name_len));
        // Copy selected shapes to variant.
        var shape_i: u32 = 0;
        while (shape_i < canvas_state.selection_len and
            variant.shapes_len < canvas.MAX_SHAPES) : (shape_i += 1)
        {
            const shape_id = canvas_state.selection[shape_i];
            if (canvas_state.get_shape(shape_id)) |shape| {
                variant.shapes[variant.shapes_len] = shape.*;
                variant.shapes_len += 1;
            }
        }
        component.variants[0] = variant;
        component.variants_len = 1;
        component.default_variant_id = variant.id;
        self.components[self.components_len] = component;
        self.components_len += 1;
        std.debug.assert(self.components_len <= MAX_COMPONENTS);
        std.debug.assert(component.variants_len == 1);
        return component_id;
    }

    // Get component by ID.
    pub fn get_component(self: *ComponentLibrary, component_id: u32)
?*Component {
        std.debug.assert(component_id > 0);
        var i: u32 = 0;
        while (i < self.components_len) : (i += 1) {
            if (self.components[i].id == component_id) {
                return &self.components[i];
            }
        }
        return null;
    }

    // Get component by ID (mutable).
    pub fn get_component_mut(
        self: *ComponentLibrary,
        component_id: u32,
    ) ?*Component {
        std.debug.assert(component_id > 0);
        var i: u32 = 0;
        while (i < self.components_len) : (i += 1) {
            if (self.components[i].id == component_id) {
                return &self.components[i];
            }
        }
        return null;
    }

    // Get component by name.
    pub fn get_component_by_name(
        self: *const ComponentLibrary,
        name: []const u8,
    ) ?*const Component {
        std.debug.assert(name.len > 0);
        var i: u32 = 0;
        while (i < self.components_len) : (i += 1) {
            const component = &self.components[i];
            if (component.name_len == name.len) {
                var match = true;
                var j: u32 = 0;
                while (j < name.len) : (j += 1) {
                    if (component.name[j] != name[j]) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    return component;
                }
            }
        }
        return null;
    }

    // Instantiate component on canvas (create instance from component).
    pub fn instantiate_component(
        self: *const ComponentLibrary,
        component_id: u32,
        canvas_state: *canvas.Canvas,
        layer_id: u32,
        x: f64,
        y: f64,
    ) ?u32 {
        std.debug.assert(component_id > 0);
        std.debug.assert(@intFromPtr(canvas_state) != 0);
        std.debug.assert(layer_id > 0);
        if (self.get_component(component_id)) |component| {
            if (component.variants_len == 0) {
                return null;
            }
            // Use default variant.
            const default_variant = &component.variants[0];
            // Calculate offset from component origin.
            var min_x: f64 = std.math.inf(f64);
            var min_y: f64 = std.math.inf(f64);
            var shape_i: u32 = 0;
            while (shape_i < default_variant.shapes_len) : (shape_i +=
1) {
                const shape = &default_variant.shapes[shape_i];
                if (shape.x < min_x) min_x = shape.x;
                if (shape.y < min_y) min_y = shape.y;
            }
            // Instantiate shapes with offset.
            var first_shape_id: ?u32 = null;
            shape_i = 0;
            while (shape_i < default_variant.shapes_len) : (shape_i +=
1) {
                const shape = &default_variant.shapes[shape_i];
                const offset_x = x - min_x;
                const offset_y = y - min_y;
                const shape_id = canvas_state.add_shape_with_stroke(
                    layer_id,
                    shape.shape_type,
                    shape.x + offset_x,
                    shape.y + offset_y,
                    shape.width,
                    shape.height,
                    shape.color,
                    shape.corner_radius,
                    shape.stroke_width,
                    shape.stroke_color,
                );
                if (shape_id) |id| {
                    if (first_shape_id == null) {
                        first_shape_id = id;
                    }
                }
            }
            return first_shape_id;
        }
        return null;
    }

    // Add variant to component.
    pub fn add_variant(
        self: *ComponentLibrary,
        component_id: u32,
        name: []const u8,
        variant_type: ComponentVariant.VariantType,
    ) ?u32 {
        std.debug.assert(component_id > 0);
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= MAX_COMPONENT_NAME_LEN);
        if (self.get_component_mut(component_id)) |component| {
            if (component.variants_len >= MAX_VARIANTS) {
                return null;
            }
            const variant_id = self.next_variant_id;
            self.next_variant_id += 1;
            var variant = ComponentVariant.init();
            variant.id = variant_id;
            variant.variant_type = variant_type;
            const name_len = @min(name.len, MAX_COMPONENT_NAME_LEN);
            @memset(variant.name[0..name_len], 0);
            @memcpy(variant.name[0..name_len], name[0..name_len]);
            variant.name_len = @as(u32, @intCast(name_len));
            component.variants[component.variants_len] = variant;
            component.variants_len += 1;
            std.debug.assert(component.variants_len <= MAX_VARIANTS);
            return variant_id;
        }
        return null;
    }

    // Add design token to component.
    pub fn add_design_token(
        self: *ComponentLibrary,
        component_id: u32,
        name: []const u8,
        token_type: DesignToken.TokenType,
        value: DesignToken.TokenValue,
    ) ?u32 {
        std.debug.assert(component_id > 0);
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= MAX_COMPONENT_NAME_LEN);
        if (self.get_component_mut(component_id)) |component| {
            if (component.design_tokens_len >= MAX_DESIGN_TOKENS) {
                return null;
            }
            const token_id = self.next_token_id;
            self.next_token_id += 1;
            var token = DesignToken.init();
            token.id = token_id;
            token.token_type = token_type;
            token.value = value;
            const name_len = @min(name.len, MAX_COMPONENT_NAME_LEN);
            @memset(token.name[0..name_len], 0);
            @memcpy(token.name[0..name_len], name[0..name_len]);
            token.name_len = @as(u32, @intCast(name_len));
            component.design_tokens[component.design_tokens_len] = token;
            component.design_tokens_len += 1;
            std.debug.assert(component.design_tokens_len <=
MAX_DESIGN_TOKENS);
            return token_id;
        }
        return null;
    }
};


// === grain_bubble/court_integration.zig ===

//! Grain Bubble Court Integration: Vector search and LLM suggestions.
//!
//! Why: Enable intelligent design features via vector search and LLM.
//! Architecture: Integration with Grain Court for spatial computing.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-07-054259-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");
const component = @import("component.zig");
const grain_court = @import("grain_court");

// Bounded: Max vector dimension.
pub const MAX_VECTOR_DIM: u32 = 1536; // Typical embedding dimension

// Bounded: Max search results.
pub const MAX_SEARCH_RESULTS: u32 = 64;

// Bounded: Max suggestion text length.
pub const MAX_SUGGESTION_LEN: u32 = 512;

// Component match: result from vector search.
pub const ComponentMatch = struct {
    component_id: u32,
    similarity: f32,
    match_type: MatchType,

    pub const MatchType = enum(u8) {
        exact, // Exact match
        similar, // Similar design
        suggested, // LLM-suggested match
    };

    pub fn init() ComponentMatch {
        const match = ComponentMatch{
            .component_id = 0,
            .similarity = 0.0,
            .match_type = .similar,
        };
        std.debug.assert(match.similarity >= 0.0);
        std.debug.assert(match.similarity <= 1.0);
        return match;
    }
};

// Design suggestion: LLM-generated design suggestion.
pub const DesignSuggestion = struct {
    suggestion_id: u32,
    suggestion_text: [MAX_SUGGESTION_LEN]u8,
    suggestion_text_len: u32,
    suggestion_type: SuggestionType,
    confidence: f32,

    pub const SuggestionType = enum(u8) {
        component, // Component suggestion
        layout, // Layout suggestion
        color, // Color palette suggestion
        typography, // Typography suggestion
    };

    pub fn init() DesignSuggestion {
        var suggestion = DesignSuggestion{
            .suggestion_id = 0,
            .suggestion_text = undefined,
            .suggestion_text_len = 0,
            .suggestion_type = .component,
            .confidence = 0.0,
        };
        @memset(suggestion.suggestion_text[0..], 0);
        std.debug.assert(suggestion.confidence >= 0.0);
        std.debug.assert(suggestion.confidence <= 1.0);
        return suggestion;
    }
};

// Court integration: manages vector search and LLM suggestions.
pub const CourtIntegration = struct {
    compute: ?*grain_court.Compute.CourtCompute,
    next_suggestion_id: u32,

    pub fn init() CourtIntegration {
        const integration = CourtIntegration{
            .compute = null,
            .next_suggestion_id = 1,
        };
        std.debug.assert(integration.next_suggestion_id == 1);
        return integration;
    }

    // Set Court compute instance.
    pub fn set_compute(self: *CourtIntegration, compute:
*grain_court.Compute.CourtCompute) void {
        std.debug.assert(@intFromPtr(compute) != 0);
        self.compute = compute;
        std.debug.assert(self.compute != null);
    }

    // Search for similar components via vector search.
    pub fn search_similar_components(
        self: *CourtIntegration,
        query_vector: []const f32,
        results: []ComponentMatch,
    ) u32 {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(query_vector.len > 0);
        std.debug.assert(query_vector.len <= MAX_VECTOR_DIM);
        std.debug.assert(results.len <= MAX_SEARCH_RESULTS);
        if (self.compute == null) {
            return 0;
        }
        // Vector search via Court compute (simplified for Phase 3).
        // Full implementation will use Court's vector_search operation.
        // For now, return empty results (ready for real implementation).
        var result_count: u32 = 0;
        var i: u32 = 0;
        while (i < results.len and result_count < MAX_SEARCH_RESULTS) :
(i += 1) {
            results[i] = ComponentMatch.init();
            result_count += 1;
        }
        std.debug.assert(result_count <= MAX_SEARCH_RESULTS);
        return result_count;
    }

    // Get LLM design suggestions.
    pub fn get_design_suggestions(
        self: *CourtIntegration,
        context: []const u8,
        suggestions: []DesignSuggestion,
    ) u32 {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(context.len > 0);
        std.debug.assert(suggestions.len <= MAX_SEARCH_RESULTS);
        if (self.compute == null) {
            return 0;
        }
        // LLM inference via Court compute (simplified for Phase 3).
        // Full implementation will use Court's llm_inference operation.
        // For now, return empty suggestions (ready for real
implementation).
        var suggestion_count: u32 = 0;
        var i: u32 = 0;
        while (i < suggestions.len and suggestion_count <
MAX_SEARCH_RESULTS) : (i += 1) {
            var suggestion = DesignSuggestion.init();
            suggestion.suggestion_id = self.next_suggestion_id;
            self.next_suggestion_id += 1;
            suggestions[i] = suggestion;
            suggestion_count += 1;
        }
        std.debug.assert(suggestion_count <= MAX_SEARCH_RESULTS);
        return suggestion_count;
    }

    // Generate component embedding vector.
    pub fn generate_component_embedding(
        self: *CourtIntegration,
        comp: *const component.Component,
        embedding: []f32,
    ) bool {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(@intFromPtr(comp) != 0);
        std.debug.assert(embedding.len > 0);
        std.debug.assert(embedding.len <= MAX_VECTOR_DIM);
        if (self.compute == null) {
            return false;
        }
        // Generate embedding via Court compute (simplified for Phase 3).
        // Full implementation will use Court's data_transform operation.
        // For now, initialize with zeros (ready for real
implementation).
        var i: u32 = 0;
        while (i < embedding.len) : (i += 1) {
            embedding[i] = 0.0;
        }
        std.debug.assert(embedding.len > 0);
        return true;
    }
};


// === grain_bubble/dag_integration.zig ===

//! Grain Bubble DAG Integration: Design graph storage and version
history.
//!
//! Why: Store design operations in DAG for undo/redo and collaboration.
//! Architecture: Integration with DAG Core for event ordering.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-07-054259-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");
const component = @import("component.zig");
const dag_core = @import("dag_core");

// Bounded: Max design history entries.
pub const MAX_DESIGN_HISTORY: u32 = 256;

// Bounded: Max event data length.
pub const MAX_EVENT_DATA_LEN: u32 = 1024;

// Design event: design operation in DAG.
pub const DesignEvent = struct {
    event_id: u64,
    event_type: EventType,
    canvas_id: u32,
    component_id: u32,
    event_data: [MAX_EVENT_DATA_LEN]u8,
    event_data_len: u32,
    timestamp: u64,
    parent_events: [8]u64,
    parent_events_len: u32,

    pub const EventType = enum(u8) {
        add_shape, // Add shape to canvas
        delete_shape, // Delete shape from canvas
        move_shape, // Move shape
        resize_shape, // Resize shape
        add_component, // Add component to canvas
        delete_component, // Delete component from canvas
        create_component, // Create new component
        update_component, // Update component definition
    };

    pub fn init() DesignEvent {
        var event = DesignEvent{
            .event_id = 0,
            .event_type = .add_shape,
            .canvas_id = 0,
            .component_id = 0,
            .event_data = undefined,
            .event_data_len = 0,
            .timestamp = 0,
            .parent_events = undefined,
            .parent_events_len = 0,
        };
        @memset(event.event_data[0..], 0);
        @memset(event.parent_events[0..], 0);
        std.debug.assert(event.event_data_len == 0);
        std.debug.assert(event.parent_events_len == 0);
        return event;
    }
};

// Design version: snapshot of design state.
pub const DesignVersion = struct {
    version_id: u32,
    canvas_id: u32,
    event_id: u64,
    timestamp: u64,
    description: [64]u8,
    description_len: u32,

    pub fn init() DesignVersion {
        var version = DesignVersion{
            .version_id = 0,
            .canvas_id = 0,
            .event_id = 0,
            .timestamp = 0,
            .description = undefined,
            .description_len = 0,
        };
        @memset(version.description[0..], 0);
        std.debug.assert(version.description_len == 0);
        return version;
    }
};

// DAG integration: manages design graph and version history.
pub const DagIntegration = struct {
    dag: ?*dag_core.DagCore,
    design_history: [MAX_DESIGN_HISTORY]DesignVersion,
    design_history_len: u32,
    next_version_id: u32,
    next_event_id: u64,

    pub fn init() DagIntegration {
        var integration = DagIntegration{
            .dag = null,
            .design_history = undefined,
            .design_history_len = 0,
            .next_version_id = 1,
            .next_event_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_DESIGN_HISTORY) : (i += 1) {
            integration.design_history[i] = DesignVersion.init();
        }
        std.debug.assert(integration.design_history_len == 0);
        std.debug.assert(integration.next_version_id == 1);
        std.debug.assert(integration.next_event_id == 1);
        return integration;
    }

    // Set DAG instance.
    pub fn set_dag(self: *DagIntegration, dag: *dag_core.DagCore) void {
        std.debug.assert(@intFromPtr(dag) != 0);
        self.dag = dag;
        std.debug.assert(self.dag != null);
    }

    // Record design event in DAG.
    pub fn record_event(
        self: *DagIntegration,
        event: *const DesignEvent,
    ) bool {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(@intFromPtr(event) != 0);
        if (self.dag == null) {
            return false;
        }
        // Record event in DAG (simplified for Phase 3).
        // Full implementation will create DAG event node with proper
ordering.
        // For now, validate event and return success (ready for real
implementation).
        std.debug.assert(event.event_id > 0);
        std.debug.assert(event.event_data_len <= MAX_EVENT_DATA_LEN);
        std.debug.assert(event.parent_events_len <= 8);
        return true;
    }

    // Get event history for canvas.
    pub fn get_event_history(
        self: *const DagIntegration,
        canvas_id: u32,
        events: []DesignEvent,
    ) u32 {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(canvas_id > 0);
        std.debug.assert(events.len <= MAX_DESIGN_HISTORY);
        if (self.dag == null) {
            return 0;
        }
        // Get event history from DAG (simplified for Phase 3).
        // Full implementation will query DAG for events related to
canvas_id.
        // For now, return empty history (ready for real implementation).
        var event_count: u32 = 0;
        var i: u32 = 0;
        while (i < events.len and event_count < MAX_DESIGN_HISTORY) : (i
+= 1) {
            events[i] = DesignEvent.init();
            event_count += 1;
        }
        std.debug.assert(event_count <= MAX_DESIGN_HISTORY);
        return event_count;
    }

    // Create design version snapshot.
    pub fn create_version(
        self: *DagIntegration,
        canvas_id: u32,
        description: []const u8,
    ) ?u32 {
        std.debug.assert(canvas_id > 0);
        std.debug.assert(description.len > 0);
        std.debug.assert(description.len <= 64);
        if (self.design_history_len >= MAX_DESIGN_HISTORY) {
            return null;
        }
        const version_id = self.next_version_id;
        self.next_version_id += 1;
        var version = DesignVersion.init();
        version.version_id = version_id;
        version.canvas_id = canvas_id;
        version.event_id = self.next_event_id;
        self.next_event_id += 1;
        const desc_len = @min(description.len, 64);
        @memset(version.description[0..desc_len], 0);
        @memcpy(version.description[0..desc_len],
description[0..desc_len]);
        version.description_len = @as(u32, @intCast(desc_len));
        self.design_history[self.design_history_len] = version;
        self.design_history_len += 1;
        std.debug.assert(self.design_history_len <= MAX_DESIGN_HISTORY);
        return version_id;
    }

    // Get design version by ID.
    pub fn get_version(
        self: *const DagIntegration,
        version_id: u32,
    ) ?*const DesignVersion {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(version_id > 0);
        var i: u32 = 0;
        while (i < self.design_history_len) : (i += 1) {
            if (self.design_history[i].version_id == version_id) {
                return &self.design_history[i];
            }
        }
        return null;
    }

    // Create version snapshot from event ID.
    pub fn create_version_snapshot(
        self: *DagIntegration,
        canvas_id: u32,
        event_id: u64,
        description: []const u8,
    ) ?u32 {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(canvas_id > 0);
        std.debug.assert(event_id > 0);
        std.debug.assert(description.len > 0);
        std.debug.assert(description.len <= 64);
        if (self.design_history_len >= MAX_DESIGN_HISTORY) {
            return null;
        }
        const version_id = self.next_version_id;
        self.next_version_id += 1;
        var version = DesignVersion.init();
        version.version_id = version_id;
        version.canvas_id = canvas_id;
        version.event_id = event_id;
        const desc_len = @min(description.len, 64);
        @memset(version.description[0..desc_len], 0);
        @memcpy(version.description[0..desc_len],
description[0..desc_len]);
        version.description_len = @as(u32, @intCast(desc_len));
        self.design_history[self.design_history_len] = version;
        self.design_history_len += 1;
        std.debug.assert(self.design_history_len <= MAX_DESIGN_HISTORY);
        return version_id;
    }

    // Load version snapshot (returns event ID to replay to).
    pub fn load_version_snapshot(
        self: *const DagIntegration,
        version_id: u32,
    ) ?u64 {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(version_id > 0);
        if (self.get_version(version_id)) |version| {
            return version.event_id;
        }
        return null;
    }
};


// === grain_bubble/export_framework.zig ===

//! Grain Bubble Svelte Export: Export designs to Svelte components.
//!
//! Why: Export designs to Svelte framework components.
//! Architecture: Svelte component generation with styles.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-07-023640-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");
const component = @import("component.zig");

// Bounded: Max Svelte component content length.
pub const MAX_SVELTE_CONTENT_LEN: u32 = 2 * 1024 * 1024; // 2 MB

// Bounded: Max Svelte class name length.
pub const MAX_CLASS_NAME_LEN: u32 = 64;

// Bounded: Max component name length.
pub const MAX_COMPONENT_NAME_LEN: u32 = 64;

// Svelte component: Svelte file structure.
pub const SvelteComponent = struct {
    template_content: [MAX_SVELTE_CONTENT_LEN]u8,
    template_content_len: u32,
    style_content: [MAX_SVELTE_CONTENT_LEN]u8,
    style_content_len: u32,
    next_class_id: u32,
    component_name: [MAX_COMPONENT_NAME_LEN]u8,
    component_name_len: u32,

    pub fn init(name: []const u8) SvelteComponent {
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= MAX_COMPONENT_NAME_LEN);
        var comp = SvelteComponent{
            .template_content = undefined,
            .template_content_len = 0,
            .style_content = undefined,
            .style_content_len = 0,
            .next_class_id = 1,
            .component_name = undefined,
            .component_name_len = 0,
        };
        @memset(comp.template_content[0..], 0);
        @memset(comp.style_content[0..], 0);
        @memset(comp.component_name[0..], 0);
        const name_len = @min(name.len, MAX_COMPONENT_NAME_LEN);
        @memcpy(comp.component_name[0..name_len], name[0..name_len]);
        comp.component_name_len = @as(u32, @intCast(name_len));
        std.debug.assert(comp.component_name_len > 0);
        return comp;
    }

    // Write string to template content.
    fn write_template(self: *SvelteComponent, text: []const u8) void {
        std.debug.assert(text.len > 0);
        std.debug.assert(self.template_content_len + text.len <=
MAX_SVELTE_CONTENT_LEN);
        @memcpy(
           
self.template_content[self.template_content_len..self.template_content_le
n + text.len],
            text[0..text.len],
        );
        self.template_content_len += @as(u32, @intCast(text.len));
        std.debug.assert(self.template_content_len <=
MAX_SVELTE_CONTENT_LEN);
    }

    // Write string to style content.
    fn write_style(self: *SvelteComponent, text: []const u8) void {
        std.debug.assert(text.len > 0);
        std.debug.assert(self.style_content_len + text.len <=
MAX_SVELTE_CONTENT_LEN);
        @memcpy(
           
self.style_content[self.style_content_len..self.style_content_len +
text.len],
            text[0..text.len],
        );
        self.style_content_len += @as(u32, @intCast(text.len));
        std.debug.assert(self.style_content_len <=
MAX_SVELTE_CONTENT_LEN);
    }

    // Convert ARGB color to CSS hex color.
    fn color_to_css_hex(color: u32) [7]u8 {
        const r = (color >> 24) & 0xFF;
        const g = (color >> 16) & 0xFF;
        const b = (color >> 8) & 0xFF;
        var hex: [7]u8 = undefined;
        _ = std.fmt.bufPrint(
            hex[0..],
            "#{:02X}{:02X}{:02X}",
            .{ r, g, b },
        ) catch unreachable;
        return hex;
    }

    // Write Svelte script section.
    pub fn write_script_section(self: *SvelteComponent) void {
        std.debug.assert(self.template_content_len == 0);
        std.debug.assert(self.style_content_len == 0);
        const script = "<script>\n  // Generated by Grain
Bubble\n</script>\n\n";
        self.write_template(script);
    }

    // Write Svelte style section start.
    fn write_style_start(self: *SvelteComponent) void {
        const style = "<style>\n";
        self.write_style(style);
    }

    // Write Svelte style section end.
    fn write_style_end(self: *SvelteComponent) void {
        const style = "</style>\n";
        self.write_style(style);
    }

    // Write Svelte template section start.
    fn write_template_start(self: *SvelteComponent) void {
        const template = "<div class=\"component\">\n";
        self.write_template(template);
    }

    // Write Svelte template section end.
    fn write_template_end(self: *SvelteComponent) void {
        const template = "</div>\n";
        self.write_template(template);
    }

    // Export shape to Svelte component.
    pub fn export_shape(
        self: *SvelteComponent,
        shape: *const canvas.Shape,
    ) void {
        std.debug.assert(@intFromPtr(shape) != 0);
        var class_name_buf: [MAX_CLASS_NAME_LEN]u8 = undefined;
        const class_name = std.fmt.bufPrint(
            class_name_buf[0..],
            "shape-{}",
            .{self.next_class_id},
        ) catch return;
        self.next_class_id += 1;
        const color_hex = self.color_to_css_hex(shape.color);
        var html_buf: [512]u8 = undefined;
        const html = std.fmt.bufPrint(
            html_buf[0..],
            "    <div class=\"{s}\"></div>\n",
            .{class_name},
        ) catch return;
        self.write_template(html);
        var css_buf: [512]u8 = undefined;
        const css = std.fmt.bufPrint(
            css_buf[0..],
            ".{s} {{\n  position: absolute;\n  left: {d:.1f}px;\n  ",
            .{ class_name, shape.x },
        ) catch return;
        self.write_style(css);
        const css2 = std.fmt.bufPrint(
            css_buf[0..],
            "top: {d:.1f}px;\n  width: {d:.1f}px;\n  height:
{d:.1f}px;\n  ",
            .{ shape.y, shape.width, shape.height },
        ) catch return;
        self.write_style(css2);
        const css3 = std.fmt.bufPrint(
            css_buf[0..],
            "background-color: {s};\n",
            .{color_hex},
        ) catch return;
        self.write_style(css3);
        switch (shape.shape_type) {
            .rectangle => {
                const css4 = "  border-radius: 0;\n";
                self.write_style(css4);
            },
            .circle => {
                const css4 = "  border-radius: 50%;\n";
                self.write_style(css4);
            },
            .rounded_rectangle => {
                const css4 = std.fmt.bufPrint(
                    css_buf[0..],
                    "  border-radius: {d:.1f}px;\n",
                    .{shape.corner_radius},
                ) catch return;
                self.write_style(css4);
            },
        }
        if (shape.stroke_width > 0.0) {
            const stroke_hex = self.color_to_css_hex(shape.stroke_color);
            const css5 = std.fmt.bufPrint(
                css_buf[0..],
                "  border: {d:.1f}px solid {s};\n",
                .{ shape.stroke_width, stroke_hex },
            ) catch return;
            self.write_style(css5);
        }
        const css_close = "}\n\n";
        self.write_style(css_close);
    }

    // Export text to Svelte component.
    pub fn export_text(
        self: *SvelteComponent,
        text: *const canvas.Text,
    ) void {
        std.debug.assert(@intFromPtr(text) != 0);
        var class_name_buf: [MAX_CLASS_NAME_LEN]u8 = undefined;
        const class_name = std.fmt.bufPrint(
            class_name_buf[0..],
            "text-{}",
            .{self.next_class_id},
        ) catch return;
        self.next_class_id += 1;
        const color_hex = self.color_to_css_hex(text.color);
        const text_content = text.content[0..text.content_len];
        var html_buf: [512]u8 = undefined;
        const html = std.fmt.bufPrint(
            html_buf[0..],
            "    <div class=\"{s}\">{s}</div>\n",
            .{ class_name, text_content },
        ) catch return;
        self.write_template(html);
        var css_buf: [512]u8 = undefined;
        const css = std.fmt.bufPrint(
            css_buf[0..],
            ".{s} {{\n  position: absolute;\n  left: {d:.1f}px;\n  ",
            .{ class_name, text.x },
        ) catch return;
        self.write_style(css);
        const css2 = std.fmt.bufPrint(
            css_buf[0..],
            "top: {d:.1f}px;\n  font-size: {d}px;\n  color:
{s};\n}}\n\n",
            .{ text.y, text.font_size, color_hex },
        ) catch return;
        self.write_style(css2);
    }

    // Export canvas to Svelte component.
    pub fn export_canvas(
        self: *SvelteComponent,
        canvas_state: *const canvas.Canvas,
    ) void {
        std.debug.assert(@intFromPtr(canvas_state) != 0);
        self.write_script_section();
        self.write_template_start();
        var layer_i: u32 = 0;
        while (layer_i < canvas_state.layers_len) : (layer_i += 1) {
            const layer = &canvas_state.layers[layer_i];
            if (!layer.visible) {
                continue;
            }
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                self.export_shape(&layer.shapes[shape_i]);
            }
            var text_i: u32 = 0;
            while (text_i < layer.texts_len) : (text_i += 1) {
                self.export_text(&layer.texts[text_i]);
            }
        }
        self.write_template_end();
        self.write_style_start();
        const component_css = ".component {\n  position: relative;\n  "
++
            "width: 100%;\n  height: 100%;\n}\n\n";
        self.write_style(component_css);
        self.write_style_end();
        const style_section =
self.style_content[0..self.style_content_len];
        if (style_section.len > 0) {
            const available = MAX_SVELTE_CONTENT_LEN -
self.template_content_len;
            if (available >= style_section.len) {
                @memcpy(
                   
self.template_content[self.template_content_len..self.template_content_le
n + style_section.len],
                    style_section[0..style_section.len],
                );
                self.template_content_len += @as(u32,
@intCast(style_section.len));
            }
        }
        std.debug.assert(self.template_content_len <=
MAX_SVELTE_CONTENT_LEN);
    }

    // Export component variant to Svelte.
    pub fn export_component_variant(
        self: *SvelteComponent,
        variant: *const component.ComponentVariant,
    ) void {
        std.debug.assert(@intFromPtr(variant) != 0);
        var shape_i: u32 = 0;
        while (shape_i < variant.shapes_len) : (shape_i += 1) {
            self.export_shape(&variant.shapes[shape_i]);
        }
        var text_i: u32 = 0;
        while (text_i < variant.texts_len) : (text_i += 1) {
            self.export_text(&variant.texts[text_i]);
        }
    }

    // Get complete Svelte component content (script + template + style).
    pub fn get_content(self: *SvelteComponent) []const u8 {
        std.debug.assert(self.template_content_len > 0);
        const total_len = self.template_content_len +
self.style_content_len;
        std.debug.assert(total_len <= MAX_SVELTE_CONTENT_LEN);
        if (self.style_content_len > 0) {
            const available = MAX_SVELTE_CONTENT_LEN -
self.template_content_len;
            if (available >= self.style_content_len) {
                @memcpy(
                   
self.template_content[self.template_content_len..self.template_content_le
n + self.style_content_len],
                    self.style_content[0..self.style_content_len],
                );
                self.template_content_len += self.style_content_len;
            }
        }
        std.debug.assert(self.template_content_len <=
MAX_SVELTE_CONTENT_LEN);
        return self.template_content[0..self.template_content_len];
    }

    // Get component name as slice.
    pub fn get_component_name(self: *const SvelteComponent) []const u8 {
        std.debug.assert(self.component_name_len > 0);
        return self.component_name[0..self.component_name_len];
    }
};


// === grain_bubble/export_html.zig ===

//! Grain Bubble HTML Export: Export designs to responsive HTML.
//!
//! Why: Export designs to web-ready HTML/CSS.
//! Architecture: HTML/CSS generation with responsive design.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-07-020615-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");
const component = @import("component.zig");

// Bounded: Max HTML content length.
pub const MAX_HTML_CONTENT_LEN: u32 = 2 * 1024 * 1024; // 2 MB

// Bounded: Max CSS content length.
pub const MAX_CSS_CONTENT_LEN: u32 = 512 * 1024; // 512 KB

// Bounded: Max HTML class name length.
pub const MAX_CLASS_NAME_LEN: u32 = 64;

// HTML document: HTML file structure.
pub const HtmlDocument = struct {
    html_content: [MAX_HTML_CONTENT_LEN]u8,
    html_content_len: u32,
    css_content: [MAX_CSS_CONTENT_LEN]u8,
    css_content_len: u32,
    width: u32,
    height: u32,
    next_class_id: u32,

    pub fn init(width: u32, height: u32) HtmlDocument {
        std.debug.assert(width > 0);
        std.debug.assert(height <= 10000);
        std.debug.assert(height > 0);
        std.debug.assert(height <= 10000);
        var doc = HtmlDocument{
            .html_content = undefined,
            .html_content_len = 0,
            .css_content = undefined,
            .css_content_len = 0,
            .width = width,
            .height = height,
            .next_class_id = 1,
        };
        @memset(doc.html_content[0..], 0);
        @memset(doc.css_content[0..], 0);
        std.debug.assert(doc.width > 0);
        std.debug.assert(doc.height > 0);
        return doc;
    }

    // Write string to HTML content.
    fn write_html(self: *HtmlDocument, text: []const u8) void {
        std.debug.assert(text.len > 0);
        std.debug.assert(self.html_content_len + text.len <=
MAX_HTML_CONTENT_LEN);
        @memcpy(
           
self.html_content[self.html_content_len..self.html_content_len +
text.len],
            text[0..text.len],
        );
        self.html_content_len += @as(u32, @intCast(text.len));
        std.debug.assert(self.html_content_len <= MAX_HTML_CONTENT_LEN);
    }

    // Write string to CSS content.
    fn write_css(self: *HtmlDocument, text: []const u8) void {
        std.debug.assert(text.len > 0);
        std.debug.assert(self.css_content_len + text.len <=
MAX_CSS_CONTENT_LEN);
        @memcpy(
            self.css_content[self.css_content_len..self.css_content_len
+ text.len],
            text[0..text.len],
        );
        self.css_content_len += @as(u32, @intCast(text.len));
        std.debug.assert(self.css_content_len <= MAX_CSS_CONTENT_LEN);
    }

    // Convert ARGB color to CSS hex color.
    fn color_to_css_hex(color: u32) [7]u8 {
        const r = (color >> 24) & 0xFF;
        const g = (color >> 16) & 0xFF;
        const b = (color >> 8) & 0xFF;
        var hex: [7]u8 = undefined;
        _ = std.fmt.bufPrint(
            hex[0..],
            "#{:02X}{:02X}{:02X}",
            .{ r, g, b },
        ) catch unreachable;
        return hex;
    }

    // Write HTML header.
    pub fn write_html_header(self: *HtmlDocument) void {
        std.debug.assert(self.html_content_len == 0);
        std.debug.assert(self.css_content_len == 0);
        const header = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n";
        self.write_html(header);
        const meta = "<meta charset=\"UTF-8\">\n<meta name=\"viewport\"
";
        self.write_html(meta);
        const viewport = "content=\"width=device-width,
initial-scale=1.0\">\n";
        self.write_html(viewport);
        const title = "<title>Grain Bubble Export</title>\n";
        self.write_html(title);
        const style_tag = "<style>\n";
        self.write_html(style_tag);
    }

    // Write CSS to HTML (inserts CSS into style tag).
    fn write_css_to_html(self: *HtmlDocument) void {
        std.debug.assert(self.css_content_len > 0);
        std.debug.assert(self.html_content_len + self.css_content_len <=
MAX_HTML_CONTENT_LEN);
        @memcpy(
           
self.html_content[self.html_content_len..self.html_content_len +
self.css_content_len],
            self.css_content[0..self.css_content_len],
        );
        self.html_content_len += self.css_content_len;
        std.debug.assert(self.html_content_len <= MAX_HTML_CONTENT_LEN);
    }

    // Write HTML footer.
    pub fn write_html_footer(self: *HtmlDocument) void {
        std.debug.assert(self.html_content_len > 0);
        const style_close = "</style>\n";
        self.write_html(style_close);
        const head_close = "</head>\n<body>\n";
        self.write_html(head_close);
        const container = "<div class=\"canvas-container\">\n";
        self.write_html(container);
        const body_close = "</div>\n</body>\n</html>\n";
        self.write_html(body_close);
        std.debug.assert(self.html_content_len > 0);
    }

    // Write CSS for canvas container.
    fn write_canvas_css(self: *HtmlDocument) void {
        std.debug.assert(self.css_content_len == 0);
        var buf: [256]u8 = undefined;
        const css = std.fmt.bufPrint(
            buf[0..],
            ".canvas-container {{\n  width: {d}px;\n  height: {d}px;\n 
",
            .{ self.width, self.height },
        ) catch return;
        self.write_css(css);
        const css2 = "position: relative;\n  margin: 0 auto;\n  " ++
            "background: #ffffff;\n}}\n\n";
        self.write_css(css2);
    }

    // Export shape to HTML/CSS.
    pub fn export_shape(
        self: *HtmlDocument,
        shape: *const canvas.Shape,
    ) void {
        std.debug.assert(@intFromPtr(shape) != 0);
        var class_name_buf: [MAX_CLASS_NAME_LEN]u8 = undefined;
        const class_name = std.fmt.bufPrint(
            class_name_buf[0..],
            "shape-{}",
            .{self.next_class_id},
        ) catch return;
        self.next_class_id += 1;
        const color_hex = self.color_to_css_hex(shape.color);
        var html_buf: [512]u8 = undefined;
        const html = std.fmt.bufPrint(
            html_buf[0..],
            "  <div class=\"{s}\"></div>\n",
            .{class_name},
        ) catch return;
        self.write_html(html);
        var css_buf: [512]u8 = undefined;
        const css = std.fmt.bufPrint(
            css_buf[0..],
            ".{s} {{\n  position: absolute;\n  left: {d:.1f}px;\n  ",
            .{ class_name, shape.x },
        ) catch return;
        self.write_css(css);
        const css2 = std.fmt.bufPrint(
            css_buf[0..],
            "top: {d:.1f}px;\n  width: {d:.1f}px;\n  height:
{d:.1f}px;\n  ",
            .{ shape.y, shape.width, shape.height },
        ) catch return;
        self.write_css(css2);
        const css3 = std.fmt.bufPrint(
            css_buf[0..],
            "background-color: {s};\n",
            .{color_hex},
        ) catch return;
        self.write_css(css3);
        switch (shape.shape_type) {
            .rectangle => {
                const css4 = "  border-radius: 0;\n";
                self.write_css(css4);
            },
            .circle => {
                const css4 = "  border-radius: 50%;\n";
                self.write_css(css4);
            },
            .rounded_rectangle => {
                const css4 = std.fmt.bufPrint(
                    css_buf[0..],
                    "  border-radius: {d:.1f}px;\n",
                    .{shape.corner_radius},
                ) catch return;
                self.write_css(css4);
            },
        }
        if (shape.stroke_width > 0.0) {
            const stroke_hex = self.color_to_css_hex(shape.stroke_color);
            const css5 = std.fmt.bufPrint(
                css_buf[0..],
                "  border: {d:.1f}px solid {s};\n",
                .{ shape.stroke_width, stroke_hex },
            ) catch return;
            self.write_css(css5);
        }
        const css_close = "}\n\n";
        self.write_css(css_close);
    }

    // Export text to HTML/CSS.
    pub fn export_text(
        self: *HtmlDocument,
        text: *const canvas.Text,
    ) void {
        std.debug.assert(@intFromPtr(text) != 0);
        var class_name_buf: [MAX_CLASS_NAME_LEN]u8 = undefined;
        const class_name = std.fmt.bufPrint(
            class_name_buf[0..],
            "text-{}",
            .{self.next_class_id},
        ) catch return;
        self.next_class_id += 1;
        const color_hex = self.color_to_css_hex(text.color);
        const text_content = text.content[0..text.content_len];
        var html_buf: [512]u8 = undefined;
        const html = std.fmt.bufPrint(
            html_buf[0..],
            "  <div class=\"{s}\">{s}</div>\n",
            .{ class_name, text_content },
        ) catch return;
        self.write_html(html);
        var css_buf: [512]u8 = undefined;
        const css = std.fmt.bufPrint(
            css_buf[0..],
            ".{s} {{\n  position: absolute;\n  left: {d:.1f}px;\n  ",
            .{ class_name, text.x },
        ) catch return;
        self.write_css(css);
        const css2 = std.fmt.bufPrint(
            css_buf[0..],
            "top: {d:.1f}px;\n  font-size: {d}px;\n  color:
{s};\n}}\n\n",
            .{ text.y, text.font_size, color_hex },
        ) catch return;
        self.write_css(css2);
    }

    // Export canvas to HTML.
    pub fn export_canvas(
        self: *HtmlDocument,
        canvas_state: *const canvas.Canvas,
    ) void {
        std.debug.assert(@intFromPtr(canvas_state) != 0);
        self.write_html_header();
        self.write_canvas_css();
        var layer_i: u32 = 0;
        while (layer_i < canvas_state.layers_len) : (layer_i += 1) {
            const layer = &canvas_state.layers[layer_i];
            if (!layer.visible) {
                continue;
            }
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                self.export_shape(&layer.shapes[shape_i]);
            }
            var text_i: u32 = 0;
            while (text_i < layer.texts_len) : (text_i += 1) {
                self.export_text(&layer.texts[text_i]);
            }
        }
        self.write_css_to_html();
        self.write_html_footer();
    }

    // Export component variant to HTML.
    pub fn export_component_variant(
        self: *HtmlDocument,
        variant: *const component.ComponentVariant,
    ) void {
        std.debug.assert(@intFromPtr(variant) != 0);
        var shape_i: u32 = 0;
        while (shape_i < variant.shapes_len) : (shape_i += 1) {
            self.export_shape(&variant.shapes[shape_i]);
        }
        var text_i: u32 = 0;
        while (text_i < variant.texts_len) : (text_i += 1) {
            self.export_text(&variant.texts[text_i]);
        }
    }

    // Get HTML content as slice.
    pub fn get_html_content(self: *const HtmlDocument) []const u8 {
        std.debug.assert(self.html_content_len > 0);
        std.debug.assert(self.html_content_len <= MAX_HTML_CONTENT_LEN);
        return self.html_content[0..self.html_content_len];
    }

    // Get CSS content as slice.
    pub fn get_css_content(self: *const HtmlDocument) []const u8 {
        std.debug.assert(self.css_content_len <= MAX_CSS_CONTENT_LEN);
        return self.css_content[0..self.css_content_len];
    }
};


// === grain_bubble/export_pdf.zig ===

//! Grain Bubble PDF Export: Export designs to PDF format.
//!
//! Why: Export high-quality vector graphics to PDF.
//! Architecture: PDF document generation with vector graphics.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-06-113622-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");
const component = @import("component.zig");

// Bounded: Max PDF page width (points, 1 point = 1/72 inch).
pub const MAX_PDF_WIDTH: u32 = 10000;

// Bounded: Max PDF page height (points).
pub const MAX_PDF_HEIGHT: u32 = 10000;

// Bounded: Max PDF content length.
pub const MAX_PDF_CONTENT_LEN: u32 = 1024 * 1024; // 1 MB

// PDF document: PDF file structure.
pub const PdfDocument = struct {
    content: [MAX_PDF_CONTENT_LEN]u8,
    content_len: u32,
    width: u32,
    height: u32,

    pub fn init(width: u32, height: u32) PdfDocument {
        std.debug.assert(width > 0);
        std.debug.assert(width <= MAX_PDF_WIDTH);
        std.debug.assert(height > 0);
        std.debug.assert(height <= MAX_PDF_HEIGHT);
        var doc = PdfDocument{
            .content = undefined,
            .content_len = 0,
            .width = width,
            .height = height,
        };
        @memset(doc.content[0..], 0);
        std.debug.assert(doc.width > 0);
        std.debug.assert(doc.height > 0);
        return doc;
    }

    // Write PDF header.
    pub fn write_header(self: *PdfDocument) void {
        std.debug.assert(self.content_len == 0);
        const header = "%PDF-1.4\n";
        const header_len = header.len;
        std.debug.assert(self.content_len + header_len <=
MAX_PDF_CONTENT_LEN);
        @memcpy(
            self.content[self.content_len..self.content_len +
header_len],
            header[0..header_len],
        );
        self.content_len += @as(u32, @intCast(header_len));
        std.debug.assert(self.content_len <= MAX_PDF_CONTENT_LEN);
    }

    // Write PDF footer.
    pub fn write_footer(self: *PdfDocument) void {
        std.debug.assert(self.content_len > 0);
        const footer = "%%EOF\n";
        const footer_len = footer.len;
        std.debug.assert(self.content_len + footer_len <=
MAX_PDF_CONTENT_LEN);
        @memcpy(
            self.content[self.content_len..self.content_len +
footer_len],
            footer[0..footer_len],
        );
        self.content_len += @as(u32, @intCast(footer_len));
        std.debug.assert(self.content_len <= MAX_PDF_CONTENT_LEN);
    }

    // Write string to PDF content.
    fn write_string(self: *PdfDocument, text: []const u8) void {
        std.debug.assert(text.len > 0);
        std.debug.assert(self.content_len + text.len <=
MAX_PDF_CONTENT_LEN);
        @memcpy(
            self.content[self.content_len..self.content_len + text.len],
            text[0..text.len],
        );
        self.content_len += @as(u32, @intCast(text.len));
        std.debug.assert(self.content_len <= MAX_PDF_CONTENT_LEN);
    }

    // Write PDF color (RGB to PDF format: 0.0-1.0).
    fn write_color(self: *PdfDocument, color: u32) void {
        const r = @as(f64, @floatFromInt((color >> 24) & 0xFF)) / 255.0;
        const g = @as(f64, @floatFromInt((color >> 16) & 0xFF)) / 255.0;
        const b = @as(f64, @floatFromInt((color >> 8) & 0xFF)) / 255.0;
        var buf: [64]u8 = undefined;
        const color_str = std.fmt.bufPrint(
            buf[0..],
            "{d:.3} {d:.3} {d:.3} rg\n",
            .{ r, g, b },
        ) catch return;
        self.write_string(color_str);
    }

    // Write PDF stroke color.
    fn write_stroke_color(self: *PdfDocument, color: u32) void {
        const r = @as(f64, @floatFromInt((color >> 24) & 0xFF)) / 255.0;
        const g = @as(f64, @floatFromInt((color >> 16) & 0xFF)) / 255.0;
        const b = @as(f64, @floatFromInt((color >> 8) & 0xFF)) / 255.0;
        var buf: [64]u8 = undefined;
        const color_str = std.fmt.bufPrint(
            buf[0..],
            "{d:.3} {d:.3} {d:.3} RG\n",
            .{ r, g, b },
        ) catch return;
        self.write_string(color_str);
    }

    // Export shape to PDF.
    pub fn export_shape(
        self: *PdfDocument,
        shape: *const canvas.Shape,
    ) void {
        std.debug.assert(@intFromPtr(shape) != 0);
        // PDF uses points (1/72 inch), convert from canvas units.
        const x_pt = shape.x;
        const y_pt = shape.y;
        const width_pt = shape.width;
        const height_pt = shape.height;
        // PDF coordinate system: origin at bottom-left, Y increases
upward.
        // Canvas: origin at top-left, Y increases downward.
        // Convert Y coordinate.
        const pdf_y = @as(f64, @floatFromInt(self.height)) - y_pt -
height_pt;
        switch (shape.shape_type) {
            .rectangle => {
                self.export_rectangle(
                    x_pt,
                    pdf_y,
                    width_pt,
                    height_pt,
                    shape.color,
                    shape.stroke_width,
                    shape.stroke_color,
                );
            },
            .circle => {
                self.export_circle(
                    x_pt + width_pt / 2.0,
                    pdf_y + height_pt / 2.0,
                    @min(width_pt, height_pt) / 2.0,
                    shape.color,
                    shape.stroke_width,
                    shape.stroke_color,
                );
            },
            .rounded_rectangle => {
                self.export_rounded_rectangle(
                    x_pt,
                    pdf_y,
                    width_pt,
                    height_pt,
                    shape.corner_radius,
                    shape.color,
                    shape.stroke_width,
                    shape.stroke_color,
                );
            },
        }
    }

    // Export rectangle to PDF.
    fn export_rectangle(
        self: *PdfDocument,
        x: f64,
        y: f64,
        width: f64,
        height: f64,
        fill_color: u32,
        stroke_width: f64,
        stroke_color: u32,
    ) void {
        std.debug.assert(width > 0.0);
        std.debug.assert(height > 0.0);
        var buf: [256]u8 = undefined;
        // Draw rectangle path.
        const path_str = std.fmt.bufPrint(
            buf[0..],
            "{d:.2} {d:.2} {d:.2} {d:.2} re\n",
            .{ x, y, width, height },
        ) catch return;
        self.write_string(path_str);
        // Fill if color is not transparent.
        if ((fill_color & 0xFF) != 0) {
            self.write_color(fill_color);
            if (stroke_width > 0.0) {
                // Fill and stroke.
                const stroke_str = std.fmt.bufPrint(
                    buf[0..],
                    "{d:.2} w\n",
                    .{stroke_width},
                ) catch return;
                self.write_string(stroke_str);
                self.write_stroke_color(stroke_color);
                self.write_string("B\n"); // Fill and stroke.
            } else {
                self.write_string("f\n"); // Fill only.
            }
        } else if (stroke_width > 0.0) {
            // Stroke only.
            const stroke_str = std.fmt.bufPrint(
                buf[0..],
                "{d:.2} w\n",
                .{stroke_width},
            ) catch return;
            self.write_string(stroke_str);
            self.write_stroke_color(stroke_color);
            self.write_string("S\n"); // Stroke only.
        }
    }

    // Export circle to PDF (as a rounded rectangle with full radius).
    fn export_circle(
        self: *PdfDocument,
        center_x: f64,
        center_y: f64,
        radius: f64,
        fill_color: u32,
        stroke_width: f64,
        stroke_color: u32,
    ) void {
        std.debug.assert(radius > 0.0);
        // Draw circle using PDF arc (approximated as rounded rectangle).
        const diameter = radius * 2.0;
        self.export_rounded_rectangle(
            center_x - radius,
            center_y - radius,
            diameter,
            diameter,
            radius,
            fill_color,
            stroke_width,
            stroke_color,
        );
    }

    // Export rounded rectangle to PDF.
    fn export_rounded_rectangle(
        self: *PdfDocument,
        x: f64,
        y: f64,
        width: f64,
        height: f64,
        corner_radius: f64,
        fill_color: u32,
        stroke_width: f64,
        stroke_color: u32,
    ) void {
        std.debug.assert(width > 0.0);
        std.debug.assert(height > 0.0);
        std.debug.assert(corner_radius >= 0.0);
        const radius = @min(corner_radius, @min(width, height) / 2.0);
        if (radius == 0.0) {
            // Simple rectangle.
            self.export_rectangle(x, y, width, height, fill_color,
stroke_width, stroke_color);
            return;
        }
        // PDF rounded rectangle using bezier curves.
        // For Phase 1, approximate as rectangle (full implementation
later).
        // This is a simplified version.
        self.export_rectangle(x, y, width, height, fill_color,
stroke_width, stroke_color);
    }

    // Export text to PDF (simplified for Phase 1).
    pub fn export_text(
        self: *PdfDocument,
        text: *const canvas.Text,
    ) void {
        std.debug.assert(@intFromPtr(text) != 0);
        // PDF coordinate system: origin at bottom-left.
        const pdf_y = @as(f64, @floatFromInt(self.height)) - text.y;
        var buf: [512]u8 = undefined;
        // Basic text rendering (simplified for Phase 1).
        // Full implementation will include font embedding.
        const text_content = text.content[0..text.content_len];
        if (text_content.len > 0) {
            // Write text position and content (simplified).
            const text_str = std.fmt.bufPrint(
                buf[0..],
                "BT\n{d:.2} {d:.2} Td\n({s}) Tj\nET\n",
                .{ text.x, pdf_y, text_content },
            ) catch return;
            self.write_string(text_str);
        }
    }

    // Export canvas to PDF.
    pub fn export_canvas(
        self: *PdfDocument,
        canvas_state: *const canvas.Canvas,
    ) void {
        std.debug.assert(@intFromPtr(canvas_state) != 0);
        self.write_header();
        // Export layers in z-order.
        var layer_i: u32 = 0;
        while (layer_i < canvas_state.layers_len) : (layer_i += 1) {
            const layer = &canvas_state.layers[layer_i];
            if (!layer.visible) {
                continue;
            }
            // Export shapes.
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                self.export_shape(&layer.shapes[shape_i]);
            }
            // Export texts.
            var text_i: u32 = 0;
            while (text_i < layer.texts_len) : (text_i += 1) {
                self.export_text(&layer.texts[text_i]);
            }
        }
        self.write_footer();
    }

    // Export component variant to PDF.
    pub fn export_component_variant(
        self: *PdfDocument,
        variant: *const component.ComponentVariant,
    ) void {
        std.debug.assert(@intFromPtr(variant) != 0);
        // Export shapes from variant.
        var shape_i: u32 = 0;
        while (shape_i < variant.shapes_len) : (shape_i += 1) {
            self.export_shape(&variant.shapes[shape_i]);
        }
        // Export texts from variant.
        var text_i: u32 = 0;
        while (text_i < variant.texts_len) : (text_i += 1) {
            self.export_text(&variant.texts[text_i]);
        }
    }

    // Export component to PDF (exports default variant).
    pub fn export_component(
        self: *PdfDocument,
        comp: *const component.Component,
    ) void {
        std.debug.assert(@intFromPtr(comp) != 0);
        if (comp.variants_len == 0) {
            return;
        }
        // Export default variant (first variant).
        const default_variant = &comp.variants[0];
        self.export_component_variant(default_variant);
    }

    // Get PDF content as slice.
    pub fn get_content(self: *const PdfDocument) []const u8 {
        std.debug.assert(self.content_len > 0);
        std.debug.assert(self.content_len <= MAX_PDF_CONTENT_LEN);
        return self.content[0..self.content_len];
    }
};


// === grain_bubble/export_slc.zig ===

//! Grain Bubble SLC Export: Export designs to SLC asset bundles.
//!
//! Why: Export self-contained, ready-to-deploy demo bundles.
//! Architecture: Single-file HTML bundles with embedded CSS/JS.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-07-030523-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");
const component = @import("component.zig");

// Bounded: Max SLC bundle content length.
pub const MAX_SLC_CONTENT_LEN: u32 = 4 * 1024 * 1024; // 4 MB

// Bounded: Max class name length.
pub const MAX_CLASS_NAME_LEN: u32 = 64;

// SLC bundle: Self-contained HTML bundle.
pub const SlcBundle = struct {
    content: [MAX_SLC_CONTENT_LEN]u8,
    content_len: u32,
    next_class_id: u32,
    bundle_name: [64]u8,
    bundle_name_len: u32,

    pub fn init(name: []const u8) SlcBundle {
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= 64);
        var bundle = SlcBundle{
            .content = undefined,
            .content_len = 0,
            .next_class_id = 1,
            .bundle_name = undefined,
            .bundle_name_len = 0,
        };
        @memset(bundle.content[0..], 0);
        @memset(bundle.bundle_name[0..], 0);
        const name_len = @min(name.len, 64);
        @memcpy(bundle.bundle_name[0..name_len], name[0..name_len]);
        bundle.bundle_name_len = @as(u32, @intCast(name_len));
        std.debug.assert(bundle.bundle_name_len > 0);
        return bundle;
    }

    // Write string to content.
    fn write_content(self: *SlcBundle, text: []const u8) void {
        std.debug.assert(text.len > 0);
        std.debug.assert(self.content_len + text.len <=
MAX_SLC_CONTENT_LEN);
        @memcpy(
            self.content[self.content_len..self.content_len + text.len],
            text[0..text.len],
        );
        self.content_len += @as(u32, @intCast(text.len));
        std.debug.assert(self.content_len <= MAX_SLC_CONTENT_LEN);
    }

    // Convert ARGB color to CSS hex color.
    fn color_to_css_hex(color: u32) [7]u8 {
        const r = (color >> 24) & 0xFF;
        const g = (color >> 16) & 0xFF;
        const b = (color >> 8) & 0xFF;
        var hex: [7]u8 = undefined;
        _ = std.fmt.bufPrint(
            hex[0..],
            "#{:02X}{:02X}{:02X}",
            .{ r, g, b },
        ) catch unreachable;
        return hex;
    }

    // Write HTML header with embedded styles.
    pub fn write_header(self: *SlcBundle, width: u32, height: u32) void {
        std.debug.assert(self.content_len == 0);
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        const header = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n";
        self.write_content(header);
        const meta = "<meta charset=\"UTF-8\">\n<meta name=\"viewport\"
";
        self.write_content(meta);
        const viewport = "content=\"width=device-width,
initial-scale=1.0\">\n";
        self.write_content(viewport);
        const title = "<title>SLC Bundle</title>\n";
        self.write_content(title);
        const style_tag = "<style>\n";
        self.write_content(style_tag);
        var css_buf: [256]u8 = undefined;
        const container_css = std.fmt.bufPrint(
            css_buf[0..],
            "body {{\n  margin: 0;\n  padding: 0;\n  ",
            .{},
        ) catch return;
        self.write_content(container_css);
        const container_css2 = std.fmt.bufPrint(
            css_buf[0..],
            "font-family: system-ui, -apple-system, sans-serif;\n}}\n\n",
            .{},
        ) catch return;
        self.write_content(container_css2);
        const canvas_css = std.fmt.bufPrint(
            css_buf[0..],
            ".slc-canvas {{\n  width: {d}px;\n  height: {d}px;\n  ",
            .{ width, height },
        ) catch return;
        self.write_content(canvas_css);
        const canvas_css2 = "position: relative;\n  margin: 0 auto;\n  "
++
            "background: #ffffff;\n  box-shadow: 0 2px 8px
rgba(0,0,0,0.1);\n}}\n\n";
        self.write_content(canvas_css2);
    }

    // Write HTML footer.
    pub fn write_footer(self: *SlcBundle) void {
        std.debug.assert(self.content_len > 0);
        const style_close = "</style>\n";
        self.write_content(style_close);
        const head_close = "</head>\n<body>\n";
        self.write_content(head_close);
        const container = "<div class=\"slc-canvas\">\n";
        self.write_content(container);
        const body_close = "</div>\n</body>\n</html>\n";
        self.write_content(body_close);
        std.debug.assert(self.content_len > 0);
    }

    // Export shape to SLC bundle.
    pub fn export_shape(
        self: *SlcBundle,
        shape: *const canvas.Shape,
    ) void {
        std.debug.assert(@intFromPtr(shape) != 0);
        var class_name_buf: [MAX_CLASS_NAME_LEN]u8 = undefined;
        const class_name = std.fmt.bufPrint(
            class_name_buf[0..],
            "shape-{}",
            .{self.next_class_id},
        ) catch return;
        self.next_class_id += 1;
        const color_hex = self.color_to_css_hex(shape.color);
        var html_buf: [512]u8 = undefined;
        const html = std.fmt.bufPrint(
            html_buf[0..],
            "    <div class=\"{s}\"></div>\n",
            .{class_name},
        ) catch return;
        self.write_content(html);
        var css_buf: [512]u8 = undefined;
        const css = std.fmt.bufPrint(
            css_buf[0..],
            ".{s} {{\n  position: absolute;\n  left: {d:.1f}px;\n  ",
            .{ class_name, shape.x },
        ) catch return;
        self.write_content(css);
        const css2 = std.fmt.bufPrint(
            css_buf[0..],
            "top: {d:.1f}px;\n  width: {d:.1f}px;\n  height:
{d:.1f}px;\n  ",
            .{ shape.y, shape.width, shape.height },
        ) catch return;
        self.write_content(css2);
        const css3 = std.fmt.bufPrint(
            css_buf[0..],
            "background-color: {s};\n",
            .{color_hex},
        ) catch return;
        self.write_content(css3);
        switch (shape.shape_type) {
            .rectangle => {
                const css4 = "  border-radius: 0;\n";
                self.write_content(css4);
            },
            .circle => {
                const css4 = "  border-radius: 50%;\n";
                self.write_content(css4);
            },
            .rounded_rectangle => {
                const css4 = std.fmt.bufPrint(
                    css_buf[0..],
                    "  border-radius: {d:.1f}px;\n",
                    .{shape.corner_radius},
                ) catch return;
                self.write_content(css4);
            },
        }
        if (shape.stroke_width > 0.0) {
            const stroke_hex = self.color_to_css_hex(shape.stroke_color);
            const css5 = std.fmt.bufPrint(
                css_buf[0..],
                "  border: {d:.1f}px solid {s};\n",
                .{ shape.stroke_width, stroke_hex },
            ) catch return;
            self.write_content(css5);
        }
        const css_close = "}\n\n";
        self.write_content(css_close);
    }

    // Export text to SLC bundle.
    pub fn export_text(
        self: *SlcBundle,
        text: *const canvas.Text,
    ) void {
        std.debug.assert(@intFromPtr(text) != 0);
        var class_name_buf: [MAX_CLASS_NAME_LEN]u8 = undefined;
        const class_name = std.fmt.bufPrint(
            class_name_buf[0..],
            "text-{}",
            .{self.next_class_id},
        ) catch return;
        self.next_class_id += 1;
        const color_hex = self.color_to_css_hex(text.color);
        const text_content = text.content[0..text.content_len];
        var html_buf: [512]u8 = undefined;
        const html = std.fmt.bufPrint(
            html_buf[0..],
            "    <div class=\"{s}\">{s}</div>\n",
            .{ class_name, text_content },
        ) catch return;
        self.write_content(html);
        var css_buf: [512]u8 = undefined;
        const css = std.fmt.bufPrint(
            css_buf[0..],
            ".{s} {{\n  position: absolute;\n  left: {d:.1f}px;\n  ",
            .{ class_name, text.x },
        ) catch return;
        self.write_content(css);
        const css2 = std.fmt.bufPrint(
            css_buf[0..],
            "top: {d:.1f}px;\n  font-size: {d}px;\n  color:
{s};\n}}\n\n",
            .{ text.y, text.font_size, color_hex },
        ) catch return;
        self.write_content(css2);
    }

    // Export canvas to SLC bundle.
    pub fn export_canvas(
        self: *SlcBundle,
        canvas_state: *const canvas.Canvas,
    ) void {
        std.debug.assert(@intFromPtr(canvas_state) != 0);
        const width = canvas_state.viewport.width;
        const height = canvas_state.viewport.height;
        self.write_header(width, height);
        var layer_i: u32 = 0;
        while (layer_i < canvas_state.layers_len) : (layer_i += 1) {
            const layer = &canvas_state.layers[layer_i];
            if (!layer.visible) {
                continue;
            }
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                self.export_shape(&layer.shapes[shape_i]);
            }
            var text_i: u32 = 0;
            while (text_i < layer.texts_len) : (text_i += 1) {
                self.export_text(&layer.texts[text_i]);
            }
        }
        self.write_footer();
    }

    // Export component variant to SLC bundle.
    pub fn export_component_variant(
        self: *SlcBundle,
        variant: *const component.ComponentVariant,
    ) void {
        std.debug.assert(@intFromPtr(variant) != 0);
        var shape_i: u32 = 0;
        while (shape_i < variant.shapes_len) : (shape_i += 1) {
            self.export_shape(&variant.shapes[shape_i]);
        }
        var text_i: u32 = 0;
        while (text_i < variant.texts_len) : (text_i += 1) {
            self.export_text(&variant.texts[text_i]);
        }
    }

    // Get SLC bundle content as slice.
    pub fn get_content(self: *const SlcBundle) []const u8 {
        std.debug.assert(self.content_len > 0);
        std.debug.assert(self.content_len <= MAX_SLC_CONTENT_LEN);
        return self.content[0..self.content_len];
    }

    // Get bundle name as slice.
    pub fn get_bundle_name(self: *const SlcBundle) []const u8 {
        std.debug.assert(self.bundle_name_len > 0);
        return self.bundle_name[0..self.bundle_name_len];
    }
};


