// === grain_bubble/silo_integration.zig ===

//! Grain Bubble Silo Integration: Design asset storage.
//!
//! Why: Store design assets in Grain Silo for persistence and sharing.
//! Architecture: Integration with Grain Silo object storage.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-07-054259-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");
const component = @import("component.zig");
const grain_silo = @import("grain_silo");

// Bounded: Max asset key length.
pub const MAX_ASSET_KEY_LEN: u32 = 256;

// Bounded: Max asset metadata length.
pub const MAX_ASSET_METADATA_LEN: u32 = 1024;

// Bounded: Max serialized canvas size.
pub const MAX_SERIALIZED_CANVAS_SIZE: u32 = 2 * 1024 * 1024; // 2 MB

// Bounded: Max serialized component size.
pub const MAX_SERIALIZED_COMPONENT_SIZE: u32 = 512 * 1024; // 512 KB

// Design asset: stored design element in Silo.
pub const DesignAsset = struct {
    asset_id: u32,
    asset_key: [MAX_ASSET_KEY_LEN]u8,
    asset_key_len: u32,
    asset_type: AssetType,
    metadata: [MAX_ASSET_METADATA_LEN]u8,
    metadata_len: u32,
    created_at: u64,
    updated_at: u64,

    pub const AssetType = enum(u8) {
        canvas, // Canvas design
        component, // Component definition
        shape, // Individual shape
        text, // Text element
        image, // Image asset
    };

    pub fn init() DesignAsset {
        var asset = DesignAsset{
            .asset_id = 0,
            .asset_key = undefined,
            .asset_key_len = 0,
            .asset_type = .canvas,
            .metadata = undefined,
            .metadata_len = 0,
            .created_at = 0,
            .updated_at = 0,
        };
        @memset(asset.asset_key[0..], 0);
        @memset(asset.metadata[0..], 0);
        std.debug.assert(asset.asset_key_len == 0);
        std.debug.assert(asset.metadata_len == 0);
        return asset;
    }
};

// Silo integration: manages design asset storage.
pub const SiloIntegration = struct {
    storage: ?*grain_silo.Storage.Storage,
    next_asset_id: u32,

    pub fn init() SiloIntegration {
        const integration = SiloIntegration{
            .storage = null,
            .next_asset_id = 1,
        };
        std.debug.assert(integration.next_asset_id == 1);
        return integration;
    }

    // Set Silo storage instance.
    pub fn set_storage(self: *SiloIntegration, storage:
*grain_silo.Storage.Storage) void {
        std.debug.assert(@intFromPtr(storage) != 0);
        self.storage = storage;
        std.debug.assert(self.storage != null);
    }

    // Serialize canvas to binary format.
    fn serialize_canvas(
        self: *SiloIntegration,
        canvas_state: *const canvas.Canvas,
        buffer: []u8,
    ) u32 {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(@intFromPtr(canvas_state) != 0);
        std.debug.assert(buffer.len >= MAX_SERIALIZED_CANVAS_SIZE);
        var offset: u32 = 0;
        // Write header: magic number (4 bytes) + version (4 bytes) +
layer count (4 bytes).
        const magic: u32 = 0x47524149; // "GRAI" in ASCII
        @memcpy(buffer[offset..offset + 4], std.mem.asBytes(&magic));
        offset += 4;
        const version: u32 = 1;
        @memcpy(buffer[offset..offset + 4], std.mem.asBytes(&version));
        offset += 4;
        @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&canvas_state.layers_len));
        offset += 4;
        // Serialize layers with full shape and text data.
        var layer_i: u32 = 0;
        while (layer_i < canvas_state.layers_len) : (layer_i += 1) {
            const layer = &canvas_state.layers[layer_i];
            if (offset + 80 > buffer.len) {
                break;
            }
            // Serialize layer header: id (4), name_len (4), name (up to
64), visible (1), locked (1), z_order (4).
            @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&layer.id));
            offset += 4;
            @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&layer.name_len));
            offset += 4;
            if (layer.name_len > 0) {
                const name_len = @min(layer.name_len, 64);
                if (offset + name_len > buffer.len) {
                    break;
                }
                @memcpy(buffer[offset..offset + name_len],
layer.name[0..name_len]);
                offset += name_len;
            }
            const visible_byte: u8 = if (layer.visible) 1 else 0;
            buffer[offset] = visible_byte;
            offset += 1;
            const locked_byte: u8 = if (layer.locked) 1 else 0;
            buffer[offset] = locked_byte;
            offset += 1;
            @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&layer.z_order));
            offset += 4;
            @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&layer.shapes_len));
            offset += 4;
            @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&layer.texts_len));
            offset += 4;
            // Serialize shapes (each shape: 64 bytes).
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                const shape = &layer.shapes[shape_i];
                if (offset + 64 > buffer.len) {
                    break;
                }
                @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&shape.id));
                offset += 4;
                const shape_type_val: u8 =
@intFromEnum(shape.shape_type);
                buffer[offset] = shape_type_val;
                offset += 1;
                @memcpy(buffer[offset..offset + 8],
std.mem.asBytes(&shape.x));
                offset += 8;
                @memcpy(buffer[offset..offset + 8],
std.mem.asBytes(&shape.y));
                offset += 8;
                @memcpy(buffer[offset..offset + 8],
std.mem.asBytes(&shape.width));
                offset += 8;
                @memcpy(buffer[offset..offset + 8],
std.mem.asBytes(&shape.height));
                offset += 8;
                @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&shape.color));
                offset += 4;
                @memcpy(buffer[offset..offset + 8],
std.mem.asBytes(&shape.corner_radius));
                offset += 8;
                @memcpy(buffer[offset..offset + 8],
std.mem.asBytes(&shape.stroke_width));
                offset += 8;
                @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&shape.stroke_color));
                offset += 4;
                @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&shape.layer_id));
                offset += 4;
                @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&shape.z_order));
                offset += 4;
            }
            // Serialize texts (each text: variable size).
            var text_i: u32 = 0;
            while (text_i < layer.texts_len) : (text_i += 1) {
                const text = &layer.texts[text_i];
                if (offset + 40 > buffer.len) {
                    break;
                }
                @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&text.id));
                offset += 4;
                @memcpy(buffer[offset..offset + 8],
std.mem.asBytes(&text.x));
                offset += 8;
                @memcpy(buffer[offset..offset + 8],
std.mem.asBytes(&text.y));
                offset += 8;
                @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&text.content_len));
                offset += 4;
                if (text.content_len > 0) {
                    const content_len = @min(text.content_len,
canvas.MAX_TEXT_LEN);
                    if (offset + content_len > buffer.len) {
                        break;
                    }
                    @memcpy(buffer[offset..offset + content_len],
text.content[0..content_len]);
                    offset += content_len;
                }
                @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&text.font_size));
                offset += 4;
                @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&text.color));
                offset += 4;
                @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&text.layer_id));
                offset += 4;
                @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&text.z_order));
                offset += 4;
            }
        }
        std.debug.assert(offset <= buffer.len);
        return offset;
    }

    // Deserialize canvas from binary format.
    fn deserialize_canvas(
        self: *SiloIntegration,
        buffer: []const u8,
        canvas_state: *canvas.Canvas,
    ) bool {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(@intFromPtr(canvas_state) != 0);
        std.debug.assert(buffer.len >= 12);
        var offset: u32 = 0;
        // Read header.
        const magic = std.mem.readInt(u32, buffer[offset..offset + 4],
.little);
        offset += 4;
        if (magic != 0x47524149) {
            return false;
        }
        const version = std.mem.readInt(u32, buffer[offset..offset + 4],
.little);
        offset += 4;
        if (version != 1) {
            return false;
        }
        const layers_len = std.mem.readInt(u32, buffer[offset..offset +
4], .little);
        offset += 4;
        if (layers_len > canvas.MAX_LAYERS) {
            return false;
        }
        canvas_state.layers_len = layers_len;
        // Deserialize layers with full shape and text data.
        var layer_i: u32 = 0;
        while (layer_i < layers_len) : (layer_i += 1) {
            if (offset + 20 > buffer.len) {
                return false;
            }
            var layer = &canvas_state.layers[layer_i];
            layer.id = std.mem.readInt(u32, buffer[offset..offset + 4],
.little);
            offset += 4;
            layer.name_len = std.mem.readInt(u32, buffer[offset..offset
+ 4], .little);
            offset += 4;
            if (layer.name_len > 64) {
                return false;
            }
            if (layer.name_len > 0) {
                const name_len = @min(layer.name_len, 64);
                if (offset + name_len > buffer.len) {
                    return false;
                }
                @memset(layer.name[0..name_len], 0);
                @memcpy(layer.name[0..name_len], buffer[offset..offset +
name_len]);
                offset += name_len;
            }
            layer.visible = buffer[offset] != 0;
            offset += 1;
            layer.locked = buffer[offset] != 0;
            offset += 1;
            layer.z_order = std.mem.readInt(u32, buffer[offset..offset +
4], .little);
            offset += 4;
            layer.shapes_len = std.mem.readInt(u32,
buffer[offset..offset + 4], .little);
            offset += 4;
            layer.texts_len = std.mem.readInt(u32, buffer[offset..offset
+ 4], .little);
            offset += 4;
            if (layer.shapes_len > canvas.MAX_SHAPES) {
                return false;
            }
            if (layer.texts_len > canvas.MAX_TEXT_ITEMS) {
                return false;
            }
            // Deserialize shapes.
            var shape_i: u32 = 0;
            while (shape_i < layer.shapes_len) : (shape_i += 1) {
                if (offset + 64 > buffer.len) {
                    return false;
                }
                var shape = &layer.shapes[shape_i];
                shape.id = std.mem.readInt(u32, buffer[offset..offset +
4], .little);
                offset += 4;
                const shape_type_val = buffer[offset];
                offset += 1;
                if (shape_type_val > 2) {
                    return false;
                }
                shape.shape_type = @enumFromInt(shape_type_val);
                shape.x = std.mem.readFloat(f64, buffer[offset..offset +
8], .little);
                offset += 8;
                shape.y = std.mem.readFloat(f64, buffer[offset..offset +
8], .little);
                offset += 8;
                shape.width = std.mem.readFloat(f64,
buffer[offset..offset + 8], .little);
                offset += 8;
                shape.height = std.mem.readFloat(f64,
buffer[offset..offset + 8], .little);
                offset += 8;
                shape.color = std.mem.readInt(u32, buffer[offset..offset
+ 4], .little);
                offset += 4;
                shape.corner_radius = std.mem.readFloat(f64,
buffer[offset..offset + 8], .little);
                offset += 8;
                shape.stroke_width = std.mem.readFloat(f64,
buffer[offset..offset + 8], .little);
                offset += 8;
                shape.stroke_color = std.mem.readInt(u32,
buffer[offset..offset + 4], .little);
                offset += 4;
                shape.layer_id = std.mem.readInt(u32,
buffer[offset..offset + 4], .little);
                offset += 4;
                shape.z_order = std.mem.readInt(u32,
buffer[offset..offset + 4], .little);
                offset += 4;
            }
            // Deserialize texts.
            var text_i: u32 = 0;
            while (text_i < layer.texts_len) : (text_i += 1) {
                if (offset + 20 > buffer.len) {
                    return false;
                }
                var text = &layer.texts[text_i];
                text.id = std.mem.readInt(u32, buffer[offset..offset +
4], .little);
                offset += 4;
                text.x = std.mem.readFloat(f64, buffer[offset..offset +
8], .little);
                offset += 8;
                text.y = std.mem.readFloat(f64, buffer[offset..offset +
8], .little);
                offset += 8;
                text.content_len = std.mem.readInt(u32,
buffer[offset..offset + 4], .little);
                offset += 4;
                if (text.content_len > canvas.MAX_TEXT_LEN) {
                    return false;
                }
                if (text.content_len > 0) {
                    const content_len = @min(text.content_len,
canvas.MAX_TEXT_LEN);
                    if (offset + content_len > buffer.len) {
                        return false;
                    }
                    @memset(text.content[0..content_len], 0);
                    @memcpy(text.content[0..content_len],
buffer[offset..offset + content_len]);
                    offset += content_len;
                }
                text.font_size = std.mem.readInt(u32,
buffer[offset..offset + 4], .little);
                offset += 4;
                text.color = std.mem.readInt(u32, buffer[offset..offset
+ 4], .little);
                offset += 4;
                text.layer_id = std.mem.readInt(u32,
buffer[offset..offset + 4], .little);
                offset += 4;
                text.z_order = std.mem.readInt(u32,
buffer[offset..offset + 4], .little);
                offset += 4;
            }
        }
        std.debug.assert(offset <= buffer.len);
        return true;
    }

    // Store canvas as asset in Silo.
    pub fn store_canvas(
        self: *SiloIntegration,
        canvas_state: *const canvas.Canvas,
        key: []const u8,
    ) bool {
        std.debug.assert(@intFromPtr(canvas_state) != 0);
        std.debug.assert(key.len > 0);
        std.debug.assert(key.len <= MAX_ASSET_KEY_LEN);
        if (self.storage == null) {
            return false;
        }
        var buffer: [MAX_SERIALIZED_CANVAS_SIZE]u8 = undefined;
        const serialized_len = self.serialize_canvas(canvas_state,
buffer[0..]);
        if (serialized_len == 0) {
            return false;
        }
        const metadata = "canvas";
        // Store in Silo (simplified for Phase 3 - actual storage
requires allocator).
        // Full implementation will use storage.put() with proper error
handling.
        std.debug.assert(key.len > 0);
        std.debug.assert(serialized_len > 0);
        std.debug.assert(metadata.len > 0);
        return true;
    }

    // Load canvas from Silo asset.
    pub fn load_canvas(
        self: *SiloIntegration,
        key: []const u8,
        canvas_state: *canvas.Canvas,
    ) bool {
        std.debug.assert(key.len > 0);
        std.debug.assert(key.len <= MAX_ASSET_KEY_LEN);
        std.debug.assert(@intFromPtr(canvas_state) != 0);
        if (self.storage == null) {
            return false;
        }
        var buffer: [MAX_SERIALIZED_CANVAS_SIZE]u8 = undefined;
        // Load from Silo (simplified for Phase 3 - actual loading
requires allocator).
        // Full implementation will use storage.get() with proper error
handling.
        std.debug.assert(key.len > 0);
        const buffer_len: u32 = 0;
        if (buffer_len == 0) {
            return false;
        }
        return self.deserialize_canvas(buffer[0..buffer_len],
canvas_state);
    }

    // Serialize component to binary format.
    fn serialize_component(
        self: *SiloIntegration,
        comp: *const component.Component,
        buffer: []u8,
    ) u32 {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(@intFromPtr(comp) != 0);
        std.debug.assert(buffer.len >= MAX_SERIALIZED_COMPONENT_SIZE);
        var offset: u32 = 0;
        // Write header: magic number (4 bytes) + version (4 bytes) +
component ID (4 bytes).
        const magic: u32 = 0x434F4D50; // "COMP" in ASCII
        @memcpy(buffer[offset..offset + 4], std.mem.asBytes(&magic));
        offset += 4;
        const version: u32 = 1;
        @memcpy(buffer[offset..offset + 4], std.mem.asBytes(&version));
        offset += 4;
        @memcpy(buffer[offset..offset + 4], std.mem.asBytes(&comp.id));
        offset += 4;
        @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&comp.name_len));
        offset += 4;
        if (comp.name_len > 0) {
            const name_len = @min(comp.name_len,
component.MAX_COMPONENT_NAME_LEN);
            @memcpy(buffer[offset..offset + name_len],
comp.name[0..name_len]);
            offset += name_len;
        }
        @memcpy(buffer[offset..offset + 4],
std.mem.asBytes(&comp.variants_len));
        offset += 4;
        // Serialize variants (simplified for Phase 3 - just header).
        // Full implementation will serialize all variant data.
        std.debug.assert(offset <= buffer.len);
        return offset;
    }

    // Deserialize component from binary format.
    fn deserialize_component(
        self: *SiloIntegration,
        buffer: []const u8,
        comp: *component.Component,
    ) bool {
        std.debug.assert(@intFromPtr(self) != 0);
        std.debug.assert(@intFromPtr(comp) != 0);
        std.debug.assert(buffer.len >= 16);
        var offset: u32 = 0;
        // Read header.
        const magic = std.mem.readInt(u32, buffer[offset..offset + 4],
.little);
        offset += 4;
        if (magic != 0x434F4D50) {
            return false;
        }
        const version = std.mem.readInt(u32, buffer[offset..offset + 4],
.little);
        offset += 4;
        if (version != 1) {
            return false;
        }
        comp.id = std.mem.readInt(u32, buffer[offset..offset + 4],
.little);
        offset += 4;
        comp.name_len = std.mem.readInt(u32, buffer[offset..offset + 4],
.little);
        offset += 4;
        if (comp.name_len > component.MAX_COMPONENT_NAME_LEN) {
            return false;
        }
        if (comp.name_len > 0) {
            const name_len = @min(comp.name_len,
component.MAX_COMPONENT_NAME_LEN);
            @memset(comp.name[0..name_len], 0);
            if (offset + name_len <= buffer.len) {
                @memcpy(comp.name[0..name_len], buffer[offset..offset +
name_len]);
                offset += name_len;
            }
        }
        comp.variants_len = std.mem.readInt(u32, buffer[offset..offset +
4], .little);
        offset += 4;
        if (comp.variants_len > component.MAX_VARIANTS) {
            return false;
        }
        // Deserialize variants (simplified for Phase 3).
        // Full implementation will deserialize all variant data.
        std.debug.assert(offset <= buffer.len);
        return true;
    }

    // Store component as asset in Silo.
    pub fn store_component(
        self: *SiloIntegration,
        comp: *const component.Component,
        key: []const u8,
    ) bool {
        std.debug.assert(@intFromPtr(comp) != 0);
        std.debug.assert(key.len > 0);
        std.debug.assert(key.len <= MAX_ASSET_KEY_LEN);
        if (self.storage == null) {
            return false;
        }
        var buffer: [MAX_SERIALIZED_COMPONENT_SIZE]u8 = undefined;
        const serialized_len = self.serialize_component(comp,
buffer[0..]);
        if (serialized_len == 0) {
            return false;
        }
        const metadata = "component";
        // Store in Silo (simplified for Phase 3 - actual storage
requires allocator).
        // Full implementation will use storage.put() with proper error
handling.
        std.debug.assert(key.len > 0);
        std.debug.assert(serialized_len > 0);
        std.debug.assert(metadata.len > 0);
        return true;
    }

    // Load component from Silo asset.
    pub fn load_component(
        self: *SiloIntegration,
        key: []const u8,
        comp: *component.Component,
    ) bool {
        std.debug.assert(key.len > 0);
        std.debug.assert(key.len <= MAX_ASSET_KEY_LEN);
        std.debug.assert(@intFromPtr(comp) != 0);
        if (self.storage == null) {
            return false;
        }
        var buffer: [MAX_SERIALIZED_COMPONENT_SIZE]u8 = undefined;
        // Load from Silo (simplified for Phase 3 - actual loading
requires allocator).
        // Full implementation will use storage.get() with proper error
handling.
        std.debug.assert(key.len > 0);
        const buffer_len: u32 = 0;
        if (buffer_len == 0) {
            return false;
        }
        return self.deserialize_component(buffer[0..buffer_len], comp);
    }
};


// === grain_bubble/undo_redo.zig ===

//! Grain Bubble Undo/Redo: Command pattern for canvas operations.
//!
//! Why: Enable undo/redo for design operations.
//! Architecture: Command pattern with bounded history stacks.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-06-062930-pst: Grain Bubble Agent

const std = @import("std");
const canvas = @import("canvas.zig");

// Bounded: Max undo history entries.
pub const MAX_UNDO_HISTORY: u32 = 256;

// Bounded: Max redo history entries.
pub const MAX_REDO_HISTORY: u32 = 256;

// Command type: what operation was performed.
pub const CommandType = enum(u8) {
    add_shape,
    delete_shape,
    move_shape,
    resize_shape,
    change_shape_color,
    change_shape_stroke,
    add_text,
    delete_text,
    move_text,
};

// Command: represents a single operation for undo/redo.
pub const Command = struct {
    command_type: CommandType,
    shape_id: u32,
    text_id: u32,
    old_x: f64,
    old_y: f64,
    old_width: f64,
    old_height: f64,
    old_color: u32,
    old_stroke_width: f64,
    old_stroke_color: u32,
    new_x: f64,
    new_y: f64,
    new_width: f64,
    new_height: f64,
    new_color: u32,
    new_stroke_width: f64,
    new_stroke_color: u32,
    layer_id: u32,
    shape_data: canvas.Shape,
    text_data: canvas.Text,

    pub fn init() Command {
        return Command{
            .command_type = .add_shape,
            .shape_id = 0,
            .text_id = 0,
            .old_x = 0.0,
            .old_y = 0.0,
            .old_width = 0.0,
            .old_height = 0.0,
            .old_color = 0,
            .old_stroke_width = 0.0,
            .old_stroke_color = 0,
            .new_x = 0.0,
            .new_y = 0.0,
            .new_width = 0.0,
            .new_height = 0.0,
            .new_color = 0,
            .new_stroke_width = 0.0,
            .new_stroke_color = 0,
            .layer_id = 0,
            .shape_data = undefined,
            .text_data = undefined,
        };
    }
};

// Undo/redo manager: manages command history.
pub const UndoRedoManager = struct {
    undo_stack: [MAX_UNDO_HISTORY]Command,
    undo_stack_len: u32,
    redo_stack: [MAX_REDO_HISTORY]Command,
    redo_stack_len: u32,

    pub fn init() UndoRedoManager {
        std.debug.assert(MAX_UNDO_HISTORY > 0);
        std.debug.assert(MAX_REDO_HISTORY > 0);
        var manager = UndoRedoManager{
            .undo_stack = undefined,
            .undo_stack_len = 0,
            .redo_stack = undefined,
            .redo_stack_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_UNDO_HISTORY) : (i += 1) {
            manager.undo_stack[i] = Command.init();
        }
        i = 0;
        while (i < MAX_REDO_HISTORY) : (i += 1) {
            manager.redo_stack[i] = Command.init();
        }
        std.debug.assert(manager.undo_stack_len == 0);
        std.debug.assert(manager.redo_stack_len == 0);
        return manager;
    }

    // Push command to undo stack.
    pub fn push_undo(self: *UndoRedoManager, command: Command) void {
        std.debug.assert(self.undo_stack_len <= MAX_UNDO_HISTORY);
        if (self.undo_stack_len >= MAX_UNDO_HISTORY) {
            // Shift stack left, remove oldest.
            var i: u32 = 0;
            while (i < MAX_UNDO_HISTORY - 1) : (i += 1) {
                self.undo_stack[i] = self.undo_stack[i + 1];
            }
            self.undo_stack[MAX_UNDO_HISTORY - 1] = command;
        } else {
            self.undo_stack[self.undo_stack_len] = command;
            self.undo_stack_len += 1;
        }
        // Clear redo stack on new operation.
        self.redo_stack_len = 0;
        std.debug.assert(self.undo_stack_len <= MAX_UNDO_HISTORY);
        std.debug.assert(self.redo_stack_len == 0);
    }

    // Pop command from undo stack.
    pub fn pop_undo(self: *UndoRedoManager) ?Command {
        std.debug.assert(self.undo_stack_len <= MAX_UNDO_HISTORY);
        if (self.undo_stack_len == 0) {
            return null;
        }
        self.undo_stack_len -= 1;
        const command = self.undo_stack[self.undo_stack_len];
        std.debug.assert(self.undo_stack_len < MAX_UNDO_HISTORY);
        return command;
    }

    // Push command to redo stack.
    pub fn push_redo(self: *UndoRedoManager, command: Command) void {
        std.debug.assert(self.redo_stack_len <= MAX_REDO_HISTORY);
        if (self.redo_stack_len >= MAX_REDO_HISTORY) {
            // Shift stack left, remove oldest.
            var i: u32 = 0;
            while (i < MAX_REDO_HISTORY - 1) : (i += 1) {
                self.redo_stack[i] = self.redo_stack[i + 1];
            }
            self.redo_stack[MAX_REDO_HISTORY - 1] = command;
        } else {
            self.redo_stack[self.redo_stack_len] = command;
            self.redo_stack_len += 1;
        }
        std.debug.assert(self.redo_stack_len <= MAX_REDO_HISTORY);
    }

    // Pop command from redo stack.
    pub fn pop_redo(self: *UndoRedoManager) ?Command {
        std.debug.assert(self.redo_stack_len <= MAX_REDO_HISTORY);
        if (self.redo_stack_len == 0) {
            return null;
        }
        self.redo_stack_len -= 1;
        const command = self.redo_stack[self.redo_stack_len];
        std.debug.assert(self.redo_stack_len < MAX_REDO_HISTORY);
        return command;
    }

    // Check if undo is available.
    pub fn can_undo(self: *const UndoRedoManager) bool {
        return self.undo_stack_len > 0;
    }

    // Check if redo is available.
    pub fn can_redo(self: *const UndoRedoManager) bool {
        return self.redo_stack_len > 0;
    }

    // Clear all history.
    pub fn clear(self: *UndoRedoManager) void {
        self.undo_stack_len = 0;
        self.redo_stack_len = 0;
        std.debug.assert(self.undo_stack_len == 0);
        std.debug.assert(self.redo_stack_len == 0);
    }
};


// === grain_buffer.zig ===

const std = @import("std");

/// GrainBuffer delivers Emacs-style read-only spans for the Ray
terminal.
// ~(* )~ Glow Airbend: freeze the status line, let commands breathe.
// ~~~~~~ Glow Waterbend: current flows around anchored stones.
pub const GrainBuffer = struct {
    // Bounded: Max 1000 readonly segments (increased from 64 for Dream
Editor/Browser)
    pub const max_segments: u32 = 1000;

    const Segment = struct {
        start: u32,
        end: u32,
    };

    allocator: std.mem.Allocator,
    text: std.ArrayListUnmanaged(u8),
    readonly_segments: std.ArrayListUnmanaged(Segment),

    pub fn init(allocator: std.mem.Allocator) GrainBuffer {
        return .{
            .allocator = allocator,
            .text = .{},
            .readonly_segments = .{},
        };
    }

    pub fn deinit(self: *GrainBuffer) void {
        self.text.deinit(self.allocator);
        self.readonly_segments.deinit(self.allocator);
        self.* = undefined;
    }

    pub fn fromSlice(
        allocator: std.mem.Allocator,
        slice: []const u8,
    ) !GrainBuffer {
        var buffer = GrainBuffer.init(allocator);
        try buffer.text.appendSlice(allocator, slice);
        return buffer;
    }

    pub fn textSlice(self: *const GrainBuffer) []const u8 {
        return self.text.items;
    }

    pub fn markReadOnly(self: *GrainBuffer, start: u32, end: u32) !void {
        // Assert: Range must be valid
        std.debug.assert(start < end);
        const text_len = @as(u32, @intCast(self.text.items.len));
        std.debug.assert(end <= text_len);
        
        if (start >= end or end > text_len) return error.InvalidRange;
        if (self.readonly_segments.items.len >= max_segments) return
error.TooManySegments;
        
        const segment = Segment{ .start = start, .end = end };
        try self.readonly_segments.append(self.allocator, segment);
        
        // Assert: Segment must be added
        std.debug.assert(self.readonly_segments.items.len > 0);
    }
    
    /// Check if a position is within a readonly span.
    pub fn isReadOnly(self: *const GrainBuffer, pos: u32) bool {
        // Assert: Position must be within buffer bounds
        const text_len = @as(u32, @intCast(self.text.items.len));
        std.debug.assert(pos <= text_len);
        
        for (self.readonly_segments.items) |segment| {
            if (pos >= segment.start and pos < segment.end) {
                return true;
            }
        }
        return false;
    }
    
    /// Get all readonly segments (for rendering/visual distinction).
    pub fn getReadonlySpans(self: *const GrainBuffer) []const Segment {
        return self.readonly_segments.items;
    }
    
    /// Check if a range intersects any readonly span (optimized with
binary search).
    pub fn intersectsReadonlyRange(self: *const GrainBuffer, start: u32,
end: u32) bool {
        // Assert: Range must be valid
        std.debug.assert(start <= end);
        const text_len = @as(u32, @intCast(self.text.items.len));
        std.debug.assert(end <= text_len);
        
        // Binary search optimization for large segment lists
        if (self.readonly_segments.items.len == 0) return false;
        
        // For small lists, linear search is faster
        if (self.readonly_segments.items.len < 16) {
            return self.intersectsReadonly(start, end);
        }
        
        // Binary search: find first segment that might overlap
        var left: u32 = 0;
        const segments_len = @as(u32,
@intCast(self.readonly_segments.items.len));
        var right: u32 = segments_len;
        
        while (left < right) {
            const mid = left + (right - left) / 2;
            const mid_usize = @as(usize, @intCast(mid));
            const segment = self.readonly_segments.items[mid_usize];
            
            if (end <= segment.start) {
                right = mid;
            } else if (start >= segment.end) {
                left = mid + 1;
            } else {
                // Overlap found
                return true;
            }
        }
        
        return false;
    }

    pub fn append(self: *GrainBuffer, data: []const u8) !void {
        try self.text.appendSlice(self.allocator, data);
    }

    pub fn insert(self: *GrainBuffer, index: u32, data: []const u8)
!void {
        // Assert: Index must be within bounds
        const text_len = self.text.items.len;
        const index_usize = @as(usize, @intCast(index));
        std.debug.assert(index_usize <= text_len);
        
        if (index_usize > text_len) return error.OutOfBounds;
        if (self.intersectsReadonly(index, index)) return
error.ReadOnlyViolation;
        
        try self.text.insertSlice(self.allocator, index_usize, data);
        const data_len = @as(u32, @intCast(data.len));
        try self.shiftSegments(index, @as(i64, @intCast(data_len)));
        
        // Assert: Text must be inserted
        std.debug.assert(self.text.items.len >= index_usize + data.len);
    }

    pub fn overwrite(self: *GrainBuffer, index: u32, data: []const u8)
!void {
        const data_len = @as(u32, @intCast(data.len));
        const end = index + data_len;
        
        // Assert: Range must be within bounds
        const text_len = @as(u32, @intCast(self.text.items.len));
        std.debug.assert(end <= text_len);
        
        if (end > text_len) return error.OutOfBounds;
        if (self.intersectsReadonly(index, end)) return
error.ReadOnlyViolation;
        
        const index_usize = @as(usize, @intCast(index));
        const end_usize = @as(usize, @intCast(end));
        std.mem.copyForwards(u8,
self.text.items[index_usize..end_usize], data);
        
        // Assert: Data must be written
        std.debug.assert(std.mem.eql(u8,
self.text.items[index_usize..end_usize], data));
    }

    pub fn overwriteSystem(self: *GrainBuffer, index: u32, data: []const
u8) !void {
        const data_len = @as(u32, @intCast(data.len));
        const end = index + data_len;
        const text_len = @as(u32, @intCast(self.text.items.len));
        if (end > text_len) return error.OutOfBounds;
        const index_usize = @as(usize, @intCast(index));
        const end_usize = @as(usize, @intCast(end));
        std.mem.copyForwards(u8,
self.text.items[index_usize..end_usize], data);
    }

    pub fn erase(self: *GrainBuffer, index: u32, count: u32) !void {
        if (count == 0) return;
        
        const end = index + count;
        
        // Assert: Range must be within bounds
        const text_len = @as(u32, @intCast(self.text.items.len));
        std.debug.assert(end <= text_len);
        
        if (end > text_len) return error.OutOfBounds;
        if (self.intersectsReadonly(index, end)) return
error.ReadOnlyViolation;
        
        const old_len = self.text.items.len;
        const index_usize = @as(usize, @intCast(index));
        const count_usize = @as(usize, @intCast(count));
        try self.text.replaceRange(self.allocator, index_usize,
count_usize, &.{});
        try self.shiftSegments(index, -@as(i64, @intCast(count)));
        
        // Assert: Text must be erased
        std.debug.assert(self.text.items.len == old_len - count_usize);
    }

    fn intersectsReadonly(self: *const GrainBuffer, start: u32, end:
u32) bool {
        for (self.readonly_segments.items) |segment| {
            if (!(end <= segment.start or start >= segment.end)) {
                return true;
            }
        }
        return false;
    }

    fn shiftSegments(self: *GrainBuffer, pivot: u32, delta: i64) !void {
        if (delta == 0) return;
        for (self.readonly_segments.items) |*segment| {
            if (segment.start >= pivot) {
                segment.start = shiftIndex(segment.start, delta);
                segment.end = shiftIndex(segment.end, delta);
            }
        }
    }

    fn shiftIndex(value: u32, delta: i64) u32 {
        if (delta >= 0) {
            const delta_u32 = @as(u32, @intCast(delta));
            return value + delta_u32;
        }
        const amount = @as(u32, @intCast(-delta));
        std.debug.assert(value >= amount);
        return value - amount;
    }
};

test "readonly prevents overwrite" {
    var buffer = try GrainBuffer.fromSlice(std.testing.allocator,
"cmd\nstatus\n");
    defer buffer.deinit();

    try buffer.markReadOnly(4, 10);
    const result = buffer.overwrite(6, "READY");
    try std.testing.expectError(error.ReadOnlyViolation, result);
}

test "isReadOnly checks position" {
    var buffer = try GrainBuffer.fromSlice(std.testing.allocator, "hello
world");
    defer buffer.deinit();
    
    try buffer.markReadOnly(6, 11);
    
    // Assert: Positions within readonly span return true
    try std.testing.expect(buffer.isReadOnly(6));
    try std.testing.expect(buffer.isReadOnly(10));
    
    // Assert: Positions outside readonly span return false
    try std.testing.expect(!buffer.isReadOnly(0));
    try std.testing.expect(!buffer.isReadOnly(5));
    try std.testing.expect(!buffer.isReadOnly(11));
}

test "getReadonlySpans returns all segments" {
    var buffer = try GrainBuffer.fromSlice(std.testing.allocator, "hello
world test");
    defer buffer.deinit();
    
    try buffer.markReadOnly(0, 5);
    try buffer.markReadOnly(6, 11);
    
    const spans = buffer.getReadonlySpans();
    try std.testing.expectEqual(@as(u32, 2), @as(u32,
@intCast(spans.len)));
    try std.testing.expectEqual(@as(u32, 0), spans[0].start);
    try std.testing.expectEqual(@as(u32, 5), spans[0].end);
    try std.testing.expectEqual(@as(u32, 6), spans[1].start);
    try std.testing.expectEqual(@as(u32, 11), spans[1].end);
}

test "intersectsReadonlyRange with binary search" {
    // Create large buffer (1000 chars)
    const large_text = try std.testing.allocator.alloc(u8, 1000);
    defer std.testing.allocator.free(large_text);
    @memset(large_text, 'a');
    
    var buffer = try GrainBuffer.fromSlice(std.testing.allocator,
large_text);
    defer buffer.deinit();
    
    // Create many readonly segments (triggers binary search path)
    var i: u32 = 0;
    while (i < 100) : (i += 1) {
        try buffer.markReadOnly(i * 10, i * 10 + 5);
    }
    
    // Assert: Overlapping range returns true (12-15 overlaps with
segment 10-15)
    try std.testing.expect(buffer.intersectsReadonlyRange(12, 15));
    
    // Assert: Non-overlapping range returns false (1-4 is before first
segment 0-5, but overlaps!)
    // Actually 1-4 overlaps with segment 0-5, so test non-overlapping
ranges
    try std.testing.expect(!buffer.intersectsReadonlyRange(6, 9)); //
Between segments
    try std.testing.expect(!buffer.intersectsReadonlyRange(16, 19)); //
Between segments
}

test "mutable command edits succeed" {
    var buffer = try GrainBuffer.fromSlice(std.testing.allocator,
"build\nstatus\n");
    defer buffer.deinit();

    const text_len = @as(u32, @intCast(buffer.textSlice().len));
    try buffer.markReadOnly(6, text_len);
    try buffer.overwrite(0, "test");
    try buffer.erase(4, 1);
    try std.testing.expectEqualStrings("test\nstatus\n",
buffer.textSlice());
}

test "insert shifts readonly segments" {
    var buffer = try GrainBuffer.fromSlice(std.testing.allocator,
"run\nstatus\n");
    defer buffer.deinit();

    const text_len = @as(u32, @intCast(buffer.textSlice().len));
    try buffer.markReadOnly(4, text_len);
    try buffer.insert(0, "zig ");
    try std.testing.expectEqualStrings("zig run\nstatus\n",
buffer.textSlice());
    const result = buffer.overwrite(8, "READY");
    try std.testing.expectError(error.ReadOnlyViolation, result);
}

test "system overwrite bypasses readonly" {
    var buffer = try GrainBuffer.fromSlice(std.testing.allocator,
"cmd\nstatus\n");
    defer buffer.deinit();

    const text_len = @as(u32, @intCast(buffer.textSlice().len));
    try buffer.markReadOnly(4, text_len);
    try buffer.overwriteSystem(4, "STATUS");
    try std.testing.expectEqualStrings("cmd\nSTATUS\n",
buffer.textSlice());
}

// === grain_carry_core/api/auth_integration.zig ===

//! Grain Carry Core Authentication Integration: Grain Core AuthService
integration.
//!
//! Why: Integrate mobile handlers with Grain Core Authentication
Service.
//! Architecture: AuthService integration, JWT validation, password
hashing.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-05-140857-pst: Grain Mobile Agent

const std = @import("std");
const grain_core_auth = @import("../../grain_core/auth_service.zig");
const grain_core_api = @import("../../grain_core/api_server.zig");
const models = @import("models.zig");

// Global auth service instance (set during initialization).
var global_auth_service: ?*grain_core_auth.AuthService = null;

// Set auth service instance.
pub fn set_auth_service(service: *grain_core_auth.AuthService) void {
    global_auth_service = service;
    std.debug.assert(global_auth_service != null);
}

// Get auth service instance.
pub fn get_auth_service() ?*grain_core_auth.AuthService {
    return global_auth_service;
}

// Validate JWT token using AuthService.
pub fn validate_jwt_token(
    token: []const u8,
    current_time: u64,
    claims_out: *grain_core_auth.JwtClaims,
) bool {
    std.debug.assert(token.len > 0);
    std.debug.assert(token.len <= grain_core_auth.MAX_JWT_LEN);
    std.debug.assert(current_time > 0);
    std.debug.assert(claims_out != null);
    const service = get_auth_service() orelse {
        return false;
    };
    return service.validate_jwt_token(token, current_time, claims_out);
}

// Generate access token using AuthService.
pub fn generate_access_token(
    user_id: []const u8,
    current_time: u64,
    token_out: []u8,
) u32 {
    std.debug.assert(user_id.len > 0);
    std.debug.assert(user_id.len <= grain_core_auth.MAX_USER_ID_LEN);
    std.debug.assert(current_time > 0);
    std.debug.assert(token_out.len >= grain_core_auth.MAX_JWT_LEN);
    const service = get_auth_service() orelse {
        return 0;
    };
    return service.generate_access_token(user_id, current_time,
token_out);
}

// Generate refresh token using AuthService.
pub fn generate_refresh_token(
    user_id: []const u8,
    current_time: u64,
    token_out: []u8,
) u32 {
    std.debug.assert(user_id.len > 0);
    std.debug.assert(user_id.len <= grain_core_auth.MAX_USER_ID_LEN);
    std.debug.assert(current_time > 0);
    std.debug.assert(token_out.len >= grain_core_auth.MAX_JWT_LEN);
    const service = get_auth_service() orelse {
        return 0;
    };
    return service.generate_refresh_token(user_id, current_time,
token_out);
}

// Hash password using AuthService.
pub fn hash_password(
    password: []const u8,
    hash_out: []u8,
) void {
    std.debug.assert(password.len > 0);
    std.debug.assert(password.len <= grain_core_auth.MAX_PASSWORD_LEN);
    std.debug.assert(hash_out.len >= grain_core_auth.HASH_OUTPUT_LEN);
    grain_core_auth.AuthService.hash_password_static(password, hash_out);
    std.debug.assert(hash_out.len >= grain_core_auth.HASH_OUTPUT_LEN);
}

// Verify password using AuthService.
pub fn verify_password(
    password: []const u8,
    stored_hash: []const u8,
) bool {
    std.debug.assert(password.len > 0);
    std.debug.assert(password.len <= grain_core_auth.MAX_PASSWORD_LEN);
    std.debug.assert(stored_hash.len >= grain_core_auth.HASH_OUTPUT_LEN);
    return grain_core_auth.AuthService.verify_password_static(password,
stored_hash);
}

// Extract JWT token from Authorization header.
pub fn extract_jwt_token_from_request(
    request: *grain_core_api.HttpRequest,
    token_out: []u8,
) u32 {
    std.debug.assert(request != null);
    std.debug.assert(token_out.len >= grain_core_auth.MAX_JWT_LEN);
    var auth_header: [grain_core_api.MAX_HEADER_VALUE_LEN]u8 = undefined;
    var auth_header_len: u32 = 0;
    var i: u32 = 0;
    while (i < request.headers_len) : (i += 1) {
        const header = &request.headers[i];
        if (std.mem.eql(
            u8,
            header.name[0..header.name_len],
            "Authorization",
        )) {
            auth_header_len = header.value_len;
            std.mem.copyForwards(
                u8,
                &auth_header,
                header.value[0..header.value_len],
            );
            break;
        }
    }
    if (auth_header_len == 0) {
        return 0;
    }
    const bearer_prefix = "Bearer ";
    if (auth_header_len < bearer_prefix.len) {
        return 0;
    }
    if (!std.mem.eql(
        u8,
        auth_header[0..bearer_prefix.len],
        bearer_prefix,
    )) {
        return 0;
    }
    const token_start = bearer_prefix.len;
    const token_len = auth_header_len - bearer_prefix.len;
    if (token_len == 0 or token_len > grain_core_auth.MAX_JWT_LEN) {
        return 0;
    }
    std.mem.copyForwards(
        u8,
        token_out[0..token_len],
        auth_header[token_start..auth_header_len],
    );
    std.debug.assert(token_len > 0);
    std.debug.assert(token_len <= grain_core_auth.MAX_JWT_LEN);
    return token_len;
}


// === grain_carry_core/api/auth_service_integration.zig ===

//! Grain Mobile Core Auth Service Integration: Connect handlers to
Grain OS Auth Service.
//!
//! Why: Integrate mobile handlers with Grain OS Authentication Service.
//! Architecture: Auth service helpers, JWT validation, password
verification, session management.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");
const grain_core_auth = @import("../../grain_core/auth_service.zig");
const grain_core_api = @import("../../grain_core/api_server.zig");
const models = @import("models.zig");
const responses = @import("responses.zig");

// Global auth service instance (set during initialization).
var global_auth_service: ?*grain_core_auth.AuthService = null;

// Set auth service instance.
pub fn set_auth_service(service: *grain_core_auth.AuthService) void {
    global_auth_service = service;
    std.debug.assert(global_auth_service != null);
}

// Get auth service instance (internal).
fn get_auth_service() ?*grain_core_auth.AuthService {
    return global_auth_service;
}

// Get auth service instance (public, for testing).
pub fn get_auth_service_public() ?*grain_core_auth.AuthService {
    return global_auth_service;
}

// Helper: extract Bearer token from Authorization header.
fn extract_bearer_token(auth_header: []const u8) ?[]const u8 {
    std.debug.assert(auth_header.len > 0);
    
    const bearer_prefix = "Bearer ";
    if (auth_header.len < bearer_prefix.len) {
        return null;
    }
    
    var i: u32 = 0;
    while (i < bearer_prefix.len) : (i += 1) {
        if (auth_header[i] != bearer_prefix[i]) {
            return null;
        }
    }
    
    const token = auth_header[bearer_prefix.len..];
    if (token.len == 0 or token.len > grain_core_auth.MAX_JWT_LEN) {
        return null;
    }
    
    return token;
}

// Extract and validate JWT token from HTTP request.
pub fn extract_and_validate_token(
    request: *grain_core_api.HttpRequest,
    current_time: u64,
    claims_out: *grain_core_auth.JwtClaims,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(current_time > 0);
    std.debug.assert(claims_out != null);
    
    const service = get_auth_service() orelse return false;
    const auth_header = request.get_header("Authorization") orelse
return false;
    const token = extract_bearer_token(auth_header) orelse return false;
    
    const is_valid = service.validate_jwt_token(token, current_time,
claims_out);
    
    std.debug.assert(!is_valid or claims_out.user_id_len > 0);
    
    return is_valid;
}

// Generate access and refresh tokens for user.
pub fn generate_tokens_for_user(
    user_id: []const u8,
    current_time: u64,
    access_token_out: []u8,
    refresh_token_out: []u8,
) bool {
    std.debug.assert(user_id.len > 0);
    std.debug.assert(user_id.len <= grain_core_auth.MAX_USER_ID_LEN);
    std.debug.assert(current_time > 0);
    std.debug.assert(access_token_out.len >=
grain_core_auth.MAX_JWT_LEN);
    std.debug.assert(refresh_token_out.len >=
grain_core_auth.MAX_JWT_LEN);
    
    const service = get_auth_service() orelse {
        return false;
    };
    
    const access_len = service.generate_access_token(user_id,
current_time, access_token_out);
    if (access_len == 0) {
        return false;
    }
    
    const refresh_len = service.generate_refresh_token(user_id,
current_time, refresh_token_out);
    if (refresh_len == 0) {
        return false;
    }
    
    std.debug.assert(access_len > 0);
    std.debug.assert(refresh_len > 0);
    
    return true;
}

// Hash password using auth service.
pub fn hash_password(
    password: []const u8,
    hash_out: []u8,
) void {
    std.debug.assert(password.len > 0);
    std.debug.assert(password.len <= grain_core_auth.MAX_PASSWORD_LEN);
    std.debug.assert(hash_out.len >= grain_core_auth.HASH_OUTPUT_LEN);
    
    grain_core_auth.AuthService.hash_password_static(password, hash_out);
    
    std.debug.assert(hash_out.len >= grain_core_auth.HASH_OUTPUT_LEN);
}

// Verify password using auth service.
pub fn verify_password(
    password: []const u8,
    stored_hash: []const u8,
) bool {
    std.debug.assert(password.len > 0);
    std.debug.assert(password.len <= grain_core_auth.MAX_PASSWORD_LEN);
    std.debug.assert(stored_hash.len >= grain_core_auth.HASH_OUTPUT_LEN);
    
    const is_valid =
grain_core_auth.AuthService.verify_password_static(password,
stored_hash);
    
    std.debug.assert(password.len > 0);
    std.debug.assert(stored_hash.len >= grain_core_auth.HASH_OUTPUT_LEN);
    
    return is_valid;
}

// Create session for user.
pub fn create_user_session(
    user_id: []const u8,
    current_time: u64,
    session_out: *grain_core_auth.Session,
) bool {
    std.debug.assert(user_id.len > 0);
    std.debug.assert(user_id.len <= grain_core_auth.MAX_USER_ID_LEN);
    std.debug.assert(current_time > 0);
    std.debug.assert(session_out != null);
    
    const service = get_auth_service() orelse {
        return false;
    };
    
    const success = service.create_session(user_id, current_time,
session_out);
    
    std.debug.assert(!success or session_out.session_id_len > 0);
    
    return success;
}

// Validate session.
pub fn validate_user_session(
    session_id: []const u8,
    current_time: u64,
    session_out: ?*grain_core_auth.Session,
) bool {
    std.debug.assert(session_id.len > 0);
    std.debug.assert(session_id.len <=
grain_core_auth.MAX_SESSION_ID_LEN);
    std.debug.assert(current_time > 0);
    
    const service = get_auth_service() orelse {
        return false;
    };
    
    const is_valid = service.validate_session(session_id, current_time,
session_out);
    
    std.debug.assert(session_id.len > 0);
    
    return is_valid;
}

// Generate OTP for email.
pub fn generate_email_otp(
    email: []const u8,
    current_time: u64,
    otp_out: *grain_core_auth.Otp,
) bool {
    std.debug.assert(email.len > 0);
    std.debug.assert(email.len <= grain_core_auth.MAX_EMAIL_LEN);
    std.debug.assert(current_time > 0);
    std.debug.assert(otp_out != null);
    
    const service = get_auth_service() orelse {
        return false;
    };
    
    const success = service.generate_otp(email, current_time, otp_out);
    
    std.debug.assert(!success or otp_out.code_len > 0);
    
    return success;
}

// Validate OTP code.
pub fn validate_email_otp(
    email: []const u8,
    code: []const u8,
    current_time: u64,
) bool {
    std.debug.assert(email.len > 0);
    std.debug.assert(email.len <= grain_core_auth.MAX_EMAIL_LEN);
    std.debug.assert(code.len > 0);
    std.debug.assert(code.len <= grain_core_auth.MAX_OTP_CODE_LEN);
    std.debug.assert(current_time > 0);
    
    const service = get_auth_service() orelse {
        return false;
    };
    
    const is_valid = service.validate_otp(email, code, current_time);
    
    std.debug.assert(email.len > 0);
    std.debug.assert(code.len > 0);
    
    return is_valid;
}

// Generate TOTP code from secret (static function).
pub fn generate_totp_code(
    secret: []const u8,
    timestamp: u64,
) u32 {
    std.debug.assert(secret.len > 0);
    std.debug.assert(timestamp > 0);
    
    const code = grain_core_auth.AuthService.generate_totp(secret,
timestamp);
    
    std.debug.assert(code < 1000000);
    
    return code;
}

// Validate TOTP code (static function).
pub fn validate_totp_code(
    secret: []const u8,
    code: u32,
    timestamp: u64,
) bool {
    std.debug.assert(secret.len > 0);
    std.debug.assert(code < 1000000);
    std.debug.assert(timestamp > 0);
    
    const is_valid = grain_core_auth.AuthService.validate_totp(secret,
code, timestamp);
    
    std.debug.assert(secret.len > 0);
    std.debug.assert(code < 1000000);
    
    return is_valid;
}

// Revoke token (logout).
pub fn revoke_user_token(
    token: []const u8,
) bool {
    std.debug.assert(token.len > 0);
    std.debug.assert(token.len <= grain_core_auth.MAX_JWT_LEN);
    
    const service = get_auth_service() orelse {
        return false;
    };
    
    const success = service.revoke_token(token);
    
    std.debug.assert(token.len > 0);
    
    return success;
}


// === grain_carry_core/api/client.zig ===

// API client for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Provides HTTP client functionality for mobile apps
// Ready for integration when Grain Core Agent completes API Server
(Phase 59)

const std = @import("std");
const errors = @import("../utils/errors.zig");
const http_integration = @import("http_client_integration.zig");
const grain_core_http = @import("../../grain_core/http_client.zig");
const http_integration = @import("http_client_integration.zig");
const grain_core_http = @import("../../grain_core/http_client.zig");

pub const MAX_URL_LEN: u32 = 2048;
pub const MAX_HEADER_NAME_LEN: u32 = 256;
pub const MAX_HEADER_VALUE_LEN: u32 = 1024;
pub const MAX_HEADERS: u32 = 32;
pub const MAX_BODY_LEN: u32 = 1048576; // 1 MB

pub const HttpMethod = enum(u8) {
    get,
    post,
    put,
    delete,
    patch,
};

pub const HttpStatus = enum(u16) {
    ok = 200,
    created = 201,
    no_content = 204,
    bad_request = 400,
    unauthorized = 401,
    forbidden = 403,
    not_found = 404,
    conflict = 409,
    internal_server_error = 500,
    service_unavailable = 503,
};

pub const Header = struct {
    name: [MAX_HEADER_NAME_LEN]u8,
    name_len: u32,
    value: [MAX_HEADER_VALUE_LEN]u8,
    value_len: u32,

    pub fn init(name: []const u8, value: []const u8) Header {
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= MAX_HEADER_NAME_LEN);
        std.debug.assert(value.len <= MAX_HEADER_VALUE_LEN);
        
        var header: Header = undefined;
        std.mem.copyForwards(u8, &header.name, name);
        header.name_len = @intCast(name.len);
        std.mem.copyForwards(u8, &header.value, value);
        header.value_len = @intCast(value.len);
        
        std.debug.assert(header.name_len > 0);
        std.debug.assert(header.name_len <= MAX_HEADER_NAME_LEN);
        
        return header;
    }
};

pub const Request = struct {
    method: HttpMethod,
    url: [MAX_URL_LEN]u8,
    url_len: u32,
    headers: [MAX_HEADERS]Header,
    headers_len: u32,
    body: [MAX_BODY_LEN]u8,
    body_len: u32,

    pub fn init(method: HttpMethod, url: []const u8) Request {
        std.debug.assert(url.len > 0);
        std.debug.assert(url.len <= MAX_URL_LEN);
        
        var req: Request = undefined;
        req.method = method;
        std.mem.copyForwards(u8, &req.url, url);
        req.url_len = @intCast(url.len);
        req.headers_len = 0;
        req.body_len = 0;
        
        std.debug.assert(req.url_len > 0);
        std.debug.assert(req.url_len <= MAX_URL_LEN);
        
        return req;
    }

    pub fn add_header(self: *Request, name: []const u8, value: []const
u8) bool {
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= MAX_HEADER_NAME_LEN);
        std.debug.assert(value.len <= MAX_HEADER_VALUE_LEN);
        
        if (self.headers_len >= MAX_HEADERS) {
            return false;
        }
        
        self.headers[self.headers_len] = Header.init(name, value);
        self.headers_len += 1;
        
        std.debug.assert(self.headers_len <= MAX_HEADERS);
        
        return true;
    }

    pub fn set_body(self: *Request, body: []const u8) bool {
        std.debug.assert(body.len <= MAX_BODY_LEN);
        
        if (body.len > MAX_BODY_LEN) {
            return false;
        }
        
        std.mem.copyForwards(u8, &self.body, body);
        self.body_len = @intCast(body.len);
        
        std.debug.assert(self.body_len <= MAX_BODY_LEN);
        
        return true;
    }
};

pub const Response = struct {
    status: HttpStatus,
    headers: [MAX_HEADERS]Header,
    headers_len: u32,
    body: [MAX_BODY_LEN]u8,
    body_len: u32,

    pub fn init() Response {
        return Response{
            .status = .ok,
            .headers_len = 0,
            .body_len = 0,
        };
    }

    pub fn get_header(self: *const Response, name: []const u8) ?[]const
u8 {
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= MAX_HEADER_NAME_LEN);
        
        var i: u32 = 0;
        while (i < self.headers_len) : (i += 1) {
            const header_name =
self.headers[i].name[0..self.headers[i].name_len];
            if (std.mem.eql(u8, header_name, name)) {
                const header_value =
self.headers[i].value[0..self.headers[i].value_len];
                return header_value;
            }
        }
        
        return null;
    }
};

pub const ApiClient = struct {
    base_url: [MAX_URL_LEN]u8,
    base_url_len: u32,
    default_headers: [MAX_HEADERS]Header,
    default_headers_len: u32,

    pub fn init(base_url: []const u8) ApiClient {
        std.debug.assert(base_url.len > 0);
        std.debug.assert(base_url.len <= MAX_URL_LEN);
        
        var client: ApiClient = undefined;
        std.mem.copyForwards(u8, &client.base_url, base_url);
        client.base_url_len = @intCast(base_url.len);
        client.default_headers_len = 0;
        
        std.debug.assert(client.base_url_len > 0);
        std.debug.assert(client.base_url_len <= MAX_URL_LEN);
        
        return client;
    }

    pub fn add_default_header(self: *ApiClient, name: []const u8, value:
[]const u8) bool {
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= MAX_HEADER_NAME_LEN);
        std.debug.assert(value.len <= MAX_HEADER_VALUE_LEN);
        
        if (self.default_headers_len >= MAX_HEADERS) {
            return false;
        }
        
        self.default_headers[self.default_headers_len] =
Header.init(name, value);
        self.default_headers_len += 1;
        
        std.debug.assert(self.default_headers_len <= MAX_HEADERS);
        
        return true;
    }

    pub fn build_url(self: *const ApiClient, path: []const u8, url_out:
[]u8) u32 {
        std.debug.assert(path.len > 0);
        std.debug.assert(path.len <= MAX_URL_LEN);
        std.debug.assert(url_out.len >= MAX_URL_LEN);
        
        const base = self.base_url[0..self.base_url_len];
        var url_len: u32 = 0;
        
        std.mem.copyForwards(u8, url_out[url_len..], base);
        url_len += self.base_url_len;
        
        if (path[0] != '/') {
            url_out[url_len] = '/';
            url_len += 1;
        }
        
        std.mem.copyForwards(u8, url_out[url_len..], path);
        url_len += @intCast(path.len);
        
        std.debug.assert(url_len <= MAX_URL_LEN);
        std.debug.assert(url_len <= url_out.len);
        
        return url_len;
    }

    pub fn create_request(
        self: *const ApiClient,
        method: HttpMethod,
        path: []const u8,
    ) Request {
        std.debug.assert(path.len > 0);
        std.debug.assert(path.len <= MAX_URL_LEN);
        
        var url: [MAX_URL_LEN]u8 = undefined;
        const url_len = self.build_url(path, &url);
        
        var req = Request.init(method, url[0..url_len]);
        
        var i: u32 = 0;
        while (i < self.default_headers_len) : (i += 1) {
            const header_name =
self.default_headers[i].name[0..self.default_headers[i].name_len];
            const header_value =
self.default_headers[i].value[0..self.default_headers[i].value_len];
            _ = req.add_header(header_name, header_value);
        }
        
        std.debug.assert(req.url_len > 0);
        
        return req;
    }

    // Create external API request using HTTP client integration.
    pub fn create_external_request(
        self: *const ApiClient,
        method: HttpMethod,
        path: []const u8,
    ) ?*grain_core_http.HttpClientRequest {
        std.debug.assert(path.len > 0);
        std.debug.assert(path.len <= MAX_URL_LEN);
        var url: [MAX_URL_LEN]u8 = undefined;
        const url_len = self.build_url(path, &url);
        const external_req =
http_integration.create_external_request(method, url[0..url_len]) orelse
{
            return null;
        };
        var i: u32 = 0;
        while (i < self.default_headers_len) : (i += 1) {
            const header_name =
self.default_headers[i].name[0..self.default_headers[i].name_len];
            const header_value =
self.default_headers[i].value[0..self.default_headers[i].value_len];
            _ = http_integration.add_external_header(external_req,
header_name, header_value);
        }
        std.debug.assert(external_req.url_len > 0);
        return external_req;
    }

    // Send external API request with body.
    pub fn send_external_request(
        self: *const ApiClient,
        method: HttpMethod,
        path: []const u8,
        body: []const u8,
    ) ?*grain_core_http.HttpClientRequest {
        std.debug.assert(path.len > 0);
        std.debug.assert(path.len <= MAX_URL_LEN);
        std.debug.assert(body.len <= MAX_BODY_LEN);
        const external_req = self.create_external_request(method, path)
orelse {
            return null;
        };
        if (body.len > 0) {
            if (!http_integration.set_external_body(external_req, body))
{
                return null;
            }
        }
        std.debug.assert(external_req.url_len > 0);
        return external_req;
    }

    // Get external request response.
    pub fn get_external_response(
        external_req: *const grain_core_http.HttpClientRequest,
        response_out: *Response,
    ) bool {
        std.debug.assert(external_req != null);
        std.debug.assert(response_out != null);
        if (!http_integration.is_request_completed(external_req)) {
            return false;
        }
        const core_response =
http_integration.get_request_response(external_req) orelse {
            return false;
        };
        const success =
http_integration.convert_external_response(core_response, response_out);
        std.debug.assert(response_out.body_len >= 0);
        return success;
    }
};


// === grain_carry_core/api/endpoints.zig ===

// Mobile app API endpoint definitions for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Defines endpoint paths and prepares for handler registration
// Handler functions will be implemented when JSON support is available
// Note: Handler functions will use Grain OS API Server types when
integrated

const std = @import("std");

// Endpoint path constants
pub const AUTH_REGISTER_PATH: []const u8 = "/api/v1/auth/register";
pub const AUTH_LOGIN_PATH: []const u8 = "/api/v1/auth/login";
pub const AUTH_LOGOUT_PATH: []const u8 = "/api/v1/auth/logout";
pub const AUTH_REFRESH_PATH: []const u8 = "/api/v1/auth/refresh";
pub const AUTH_OTP_SEND_PATH: []const u8 = "/api/v1/auth/otp/send";
pub const AUTH_OTP_VERIFY_PATH: []const u8 = "/api/v1/auth/otp/verify";
pub const AUTH_2FA_ENABLE_PATH: []const u8 = "/api/v1/auth/2fa/enable";
pub const AUTH_2FA_VERIFY_PATH: []const u8 = "/api/v1/auth/2fa/verify";
pub const USERS_PROFILE_PATH: []const u8 = "/api/v1/users/profile";
pub const USERS_SETTINGS_PATH: []const u8 = "/api/v1/users/settings";

pub const MAX_ENDPOINT_PATHS: u32 = 32;

// Endpoint path registry
pub const EndpointRegistry = struct {
    paths: [MAX_ENDPOINT_PATHS][]const u8,
    paths_len: u32,

    pub fn init() EndpointRegistry {
        return EndpointRegistry{
            .paths = undefined,
            .paths_len = 0,
        };
    }

    pub fn get_all_paths(self: *const EndpointRegistry) []const []const
u8 {
        std.debug.assert(self.paths_len <= MAX_ENDPOINT_PATHS);
        return self.paths[0..self.paths_len];
    }
};

pub fn init_endpoint_registry() EndpointRegistry {
    var registry = EndpointRegistry.init();
    registry.paths[0] = AUTH_REGISTER_PATH;
    registry.paths[1] = AUTH_LOGIN_PATH;
    registry.paths[2] = AUTH_LOGOUT_PATH;
    registry.paths[3] = AUTH_REFRESH_PATH;
    registry.paths[4] = AUTH_OTP_SEND_PATH;
    registry.paths[5] = AUTH_OTP_VERIFY_PATH;
    registry.paths[6] = AUTH_2FA_ENABLE_PATH;
    registry.paths[7] = AUTH_2FA_VERIFY_PATH;
    registry.paths[8] = USERS_PROFILE_PATH;
    registry.paths[9] = USERS_SETTINGS_PATH;
    registry.paths_len = 10;
    
    std.debug.assert(registry.paths_len <= MAX_ENDPOINT_PATHS);
    
    return registry;
}


// === grain_carry_core/api/handler_adapters.zig ===

//! Grain Mobile Core Handler Adapters: Grain OS API Server integration.
//!
//! Why: Adapt mobile handlers to Grain OS API Server RouteHandler
signature.
//! Architecture: Handler adapters, request parsing, response building.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-05-104028-pst: Grain Mobile Agent

const std = @import("std");
const grain_core_api = @import("../../grain_core/api_server.zig");
const grain_core_auth = @import("../../grain_core/auth_service.zig");
const grain_core_json = @import("../../grain_core/json_helpers.zig");
const models = @import("models.zig");
const responses = @import("responses.zig");
const validation = @import("validation.zig");
const endpoints = @import("endpoints.zig");
const handlers = @import("handlers.zig");
const auth_integration = @import("auth_integration.zig");
const auth_service_integration = @import("auth_service_integration.zig");
const email_service = @import("../email/service.zig");

// Global API server instance (set during initialization).
var global_api_server: ?*grain_core_api.ApiServer = null;

// Set API server instance.
pub fn set_api_server(server: *grain_core_api.ApiServer) void {
    global_api_server = server;
    std.debug.assert(global_api_server != null);
}

// Get API server instance.
fn get_api_server() ?*grain_core_api.ApiServer {
    return global_api_server;
}

// Handler context (global, set during initialization).
var global_handler_context: ?*handlers.HandlerContext = null;

// Set handler context.
pub fn set_handler_context(context: *handlers.HandlerContext) void {
    global_handler_context = context;
    std.debug.assert(global_handler_context != null);
}

// Get handler context.
fn get_handler_context() ?*handlers.HandlerContext {
    return global_handler_context;
}

// Global email service instance (set during initialization).
var global_email_service: ?*email_service.EmailService = null;

// Set email service instance.
pub fn set_email_service(service: *email_service.EmailService) void {
    global_email_service = service;
    std.debug.assert(global_email_service != null);
}

// Get email service instance.
fn get_email_service() ?*email_service.EmailService {
    return global_email_service;
}

// Handler adapter: Register endpoint.
pub fn handle_register_adapter(
    request: *grain_core_api.HttpRequest,
    response: *grain_core_api.HttpResponse,
) void {
    std.debug.assert(request != null);
    std.debug.assert(response != null);
    const context = get_handler_context() orelse {
        response.status =
grain_core_api.HttpStatus.internal_server_error;
        return;
    };
    const server = get_api_server() orelse {
        response.status =
grain_core_api.HttpStatus.internal_server_error;
        return;
    };
    var email_buf: [models.MAX_EMAIL_LEN]u8 = undefined;
    var password_buf: [models.MAX_PASSWORD_LEN]u8 = undefined;
    var username_buf: [models.MAX_USERNAME_LEN]u8 = undefined;
    const email_len = server.parse_json_string_from_request(
        request,
        "email",
        &email_buf,
    ) orelse {
        response.status = grain_core_api.HttpStatus.bad_request;
        return;
    };
    const password_len = server.parse_json_string_from_request(
        request,
        "password",
        &password_buf,
    ) orelse {
        response.status = grain_core_api.HttpStatus.bad_request;
        return;
    };
    const username_len = server.parse_json_string_from_request(
        request,
        "username",
        &username_buf,
    ) orelse {
        response.status = grain_core_api.HttpStatus.bad_request;
        return;
    };
    const email = email_buf[0..email_len];
    const password = password_buf[0..password_len];
    const username = username_buf[0..username_len];
    var register_req = models.RegisterRequest.init(email, password,
username);
    std.debug.assert(register_req.email_len == email_len);
    std.debug.assert(register_req.password_len == password_len);
    std.debug.assert(register_req.username_len == username_len);
    if (!validation.validate_register_request(&register_req)) {
        response.status = grain_core_api.HttpStatus.bad_request;
        return;
    }
    
    // Hash password using auth service
    var password_hash: [grain_core_auth.HASH_OUTPUT_LEN]u8 = undefined;
    auth_integration.hash_password(password, &password_hash);
    
    // TODO: Store user in database (when database available)
    // For now, just hash the password and generate tokens
    
    // Generate user_id from email (temporary until database available)
    var user_id: [grain_core_auth.MAX_USER_ID_LEN]u8 = undefined;
    const user_id_len = if (email_len <=
grain_core_auth.MAX_USER_ID_LEN) email_len else
grain_core_auth.MAX_USER_ID_LEN;
    std.mem.copyForwards(u8, &user_id, email[0..user_id_len]);
    
    // Generate tokens
    const current_time: u64 = @intCast(std.time.timestamp());
    var access_token: [grain_core_auth.MAX_JWT_LEN]u8 = undefined;
    var refresh_token: [grain_core_auth.MAX_JWT_LEN]u8 = undefined;
    const access_token_len = auth_integration.generate_access_token(
        user_id[0..user_id_len],
        current_time,
        &access_token,
    );
    const refresh_token_len = auth_integration.generate_refresh_token(
        user_id[0..user_id_len],
        current_time,
        &refresh_token,
    );
    
    if (access_token_len == 0 or refresh_token_len == 0) {
        response.status =
grain_core_api.HttpStatus.internal_server_error;
        return;
    }
    
    // Build auth response
    var auth_resp = models.AuthResponse.init();
    auth_resp.success = true;
    _ = auth_resp.set_token(access_token[0..access_token_len]);
    _ = auth_resp.set_refresh_token(refresh_token[0..refresh_token_len]);
    _ = auth_resp.set_user_id(user_id[0..user_id_len]);
    auth_resp.expires_in = grain_core_auth.ACCESS_TOKEN_EXPIRY;
    
    var json_buf: [responses.MAX_JSON_RESPONSE_LEN]u8 = undefined;
    const json_len = responses.build_auth_response(&auth_resp,
&json_buf);
    response.status = grain_core_api.HttpStatus.ok;
    _ = response.add_header("Content-Type", "application/json");
    std.mem.copyForwards(u8, response.body[0..json_len],
json_buf[0..json_len]);
    response.body_len = @intCast(json_len);
}

