// Authentication response models
pub const AuthResponse = struct {
    success: bool,
    token: [MAX_TOKEN_LEN]u8,
    token_len: u32,
    refresh_token: [MAX_TOKEN_LEN]u8,
    refresh_token_len: u32,
    user_id: [MAX_USER_ID_LEN]u8,
    user_id_len: u32,
    expires_in: u64,

    pub fn init() AuthResponse {
        return AuthResponse{
            .success = false,
            .token_len = 0,
            .refresh_token_len = 0,
            .user_id_len = 0,
            .expires_in = 0,
        };
    }

    pub fn set_token(self: *AuthResponse, token: []const u8) bool {
        std.debug.assert(token.len > 0);
        std.debug.assert(token.len <= MAX_TOKEN_LEN);
        
        if (token.len > MAX_TOKEN_LEN) {
            return false;
        }
        
        std.mem.copyForwards(u8, &self.token, token);
        self.token_len = @intCast(token.len);
        
        std.debug.assert(self.token_len > 0);
        std.debug.assert(self.token_len <= MAX_TOKEN_LEN);
        
        return true;
    }

    pub fn set_refresh_token(self: *AuthResponse, refresh_token: []const
u8) bool {
        std.debug.assert(refresh_token.len > 0);
        std.debug.assert(refresh_token.len <= MAX_TOKEN_LEN);
        
        if (refresh_token.len > MAX_TOKEN_LEN) {
            return false;
        }
        
        std.mem.copyForwards(u8, &self.refresh_token, refresh_token);
        self.refresh_token_len = @intCast(refresh_token.len);
        
        std.debug.assert(self.refresh_token_len > 0);
        std.debug.assert(self.refresh_token_len <= MAX_TOKEN_LEN);
        
        return true;
    }

    pub fn set_user_id(self: *AuthResponse, user_id: []const u8) bool {
        std.debug.assert(user_id.len > 0);
        std.debug.assert(user_id.len <= MAX_USER_ID_LEN);
        
        if (user_id.len > MAX_USER_ID_LEN) {
            return false;
        }
        
        std.mem.copyForwards(u8, &self.user_id, user_id);
        self.user_id_len = @intCast(user_id.len);
        
        std.debug.assert(self.user_id_len > 0);
        std.debug.assert(self.user_id_len <= MAX_USER_ID_LEN);
        
        return true;
    }
};

// Error response model
pub const ErrorResponse = struct {
    error_code: [32]u8,
    error_code_len: u32,
    message: [MAX_MESSAGE_LEN]u8,
    message_len: u32,

    pub fn init(error_code: []const u8, message: []const u8)
ErrorResponse {
        std.debug.assert(error_code.len > 0);
        std.debug.assert(error_code.len <= 32);
        std.debug.assert(message.len > 0);
        std.debug.assert(message.len <= MAX_MESSAGE_LEN);
        
        var err: ErrorResponse = undefined;
        std.mem.copyForwards(u8, &err.error_code, error_code);
        err.error_code_len = @intCast(error_code.len);
        std.mem.copyForwards(u8, &err.message, message);
        err.message_len = @intCast(message.len);
        
        std.debug.assert(err.error_code_len > 0);
        std.debug.assert(err.message_len > 0);
        
        return err;
    }
};


// === grain_carry_core/api/os_integration.zig ===

//! Grain Mobile Core OS Integration: Register endpoints with Grain Core
API Server.
//!
//! Why: Integrate mobile endpoints with Grain Core API Server route
registration.
//! Architecture: Route registration, handler adapter setup, middleware
integration.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-05-104028-pst: Grain Mobile Agent

const std = @import("std");
const grain_core = @import("grain_core");
const grain_core_api = grain_core.api_server;
const grain_core_compositor = grain_core.compositor;
const grain_core_auth = grain_core.auth_service;
const handler_adapters = @import("handler_adapters.zig");
const auth_integration = @import("auth_integration.zig");
const route_registration = @import("route_registration.zig");
const endpoints = @import("endpoints.zig");
const handlers = @import("handlers.zig");

// Register all mobile endpoints with Grain Core API Server.
pub fn register_mobile_endpoints_with_compositor(
    compositor: *grain_core_compositor.Compositor,
    handler_context: *handlers.HandlerContext,
    auth_service: *grain_core_auth.AuthService,
) u32 {
    std.debug.assert(compositor != null);
    std.debug.assert(handler_context != null);
    std.debug.assert(auth_service != null);
    handler_adapters.set_handler_context(handler_context);
    var api_server_ptr = &compositor.api_server;
    handler_adapters.set_api_server(api_server_ptr);
    auth_integration.set_auth_service(auth_service);
    var count: u32 = 0;
    if (compositor.register_api_route(
        grain_core_api.HttpMethod.post,
        endpoints.AUTH_REGISTER_PATH,
        handler_adapters.handle_register_adapter,
    )) {
        count += 1;
    }
    if (compositor.register_api_route(
        grain_core_api.HttpMethod.post,
        endpoints.AUTH_LOGIN_PATH,
        handler_adapters.handle_login_adapter,
    )) {
        count += 1;
    }
    if (compositor.register_api_route(
        grain_core_api.HttpMethod.post,
        endpoints.AUTH_LOGOUT_PATH,
        handler_adapters.handle_logout_adapter,
    )) {
        count += 1;
    }
    if (compositor.register_api_route(
        grain_core_api.HttpMethod.post,
        endpoints.AUTH_REFRESH_PATH,
        handler_adapters.handle_refresh_adapter,
    )) {
        count += 1;
    }
    if (compositor.register_api_route(
        grain_core_api.HttpMethod.post,
        endpoints.AUTH_OTP_SEND_PATH,
        handler_adapters.handle_otp_send_adapter,
    )) {
        count += 1;
    }
    if (compositor.register_api_route(
        grain_core_api.HttpMethod.post,
        endpoints.AUTH_OTP_VERIFY_PATH,
        handler_adapters.handle_otp_verify_adapter,
    )) {
        count += 1;
    }
    if (compositor.register_api_route(
        grain_core_api.HttpMethod.post,
        endpoints.AUTH_2FA_ENABLE_PATH,
        handler_adapters.handle_2fa_enable_adapter,
    )) {
        count += 1;
    }
    if (compositor.register_api_route(
        grain_core_api.HttpMethod.post,
        endpoints.AUTH_2FA_VERIFY_PATH,
        handler_adapters.handle_2fa_verify_adapter,
    )) {
        count += 1;
    }
    if (compositor.register_api_route(
        grain_core_api.HttpMethod.get,
        endpoints.USERS_PROFILE_PATH,
        handler_adapters.handle_users_profile_adapter,
    )) {
        count += 1;
    }
    if (compositor.register_api_route(
        grain_core_api.HttpMethod.get,
        endpoints.USERS_SETTINGS_PATH,
        handler_adapters.handle_users_settings_adapter,
    )) {
        count += 1;
    }
    std.debug.assert(count <= 10);
    return count;
}


// === grain_carry_core/api/responses.zig ===

// API response helpers for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Provides helper functions for building API responses
// Ready for JSON serialization when JSON support is available

const std = @import("std");
const models = @import("models.zig");

pub const MAX_JSON_RESPONSE_LEN: u32 = 4096;

// Helper: write JSON string key
fn write_json_key(json_out: []u8, json_len: *u32, key: []const u8) void {
    std.debug.assert(key.len > 0);
    std.debug.assert(json_len.* + key.len + 4 <= json_out.len);
    
    json_out[json_len.*] = '"';
    json_len.* += 1;
    std.mem.copyForwards(u8, json_out[json_len.*..], key);
    json_len.* += @intCast(key.len);
    json_out[json_len.*] = '"';
    json_len.* += 1;
    json_out[json_len.*] = ':';
    json_len.* += 1;
}

// Helper: write JSON string value
fn write_json_string_value(json_out: []u8, json_len: *u32, value:
[]const u8) void {
    std.debug.assert(value.len > 0);
    std.debug.assert(json_len.* + value.len + 2 <= json_out.len);
    
    json_out[json_len.*] = '"';
    json_len.* += 1;
    std.mem.copyForwards(u8, json_out[json_len.*..], value);
    json_len.* += @intCast(value.len);
    json_out[json_len.*] = '"';
    json_len.* += 1;
}

// Helper: write JSON boolean value
fn write_json_bool_value(json_out: []u8, json_len: *u32, value: bool)
void {
    std.debug.assert(json_len.* + 5 <= json_out.len);
    
    if (value) {
        json_out[json_len.*] = 't';
        json_len.* += 1;
        json_out[json_len.*] = 'r';
        json_len.* += 1;
        json_out[json_len.*] = 'u';
        json_len.* += 1;
        json_out[json_len.*] = 'e';
        json_len.* += 1;
    } else {
        json_out[json_len.*] = 'f';
        json_len.* += 1;
        json_out[json_len.*] = 'a';
        json_len.* += 1;
        json_out[json_len.*] = 'l';
        json_len.* += 1;
        json_out[json_len.*] = 's';
        json_len.* += 1;
        json_out[json_len.*] = 'e';
        json_len.* += 1;
    }
}

// Build success response JSON (simplified, manual JSON construction)
pub fn build_success_response(
    message: []const u8,
    data: []const u8,
    json_out: []u8,
) u32 {
    std.debug.assert(message.len > 0);
    std.debug.assert(message.len <= models.MAX_MESSAGE_LEN);
    std.debug.assert(data.len <= MAX_JSON_RESPONSE_LEN);
    std.debug.assert(json_out.len >= MAX_JSON_RESPONSE_LEN);
    
    var json_len: u32 = 0;
    json_out[json_len] = '{';
    json_len += 1;
    
    write_json_key(json_out, &json_len, "status");
    write_json_string_value(json_out, &json_len, "success");
    
    json_out[json_len] = ',';
    json_len += 1;
    write_json_key(json_out, &json_len, "message");
    write_json_string_value(json_out, &json_len, message);
    
    if (data.len > 0) {
        json_out[json_len] = ',';
        json_len += 1;
        write_json_key(json_out, &json_len, "data");
        std.mem.copyForwards(u8, json_out[json_len..], data);
        json_len += @intCast(data.len);
    }
    
    json_out[json_len] = '}';
    json_len += 1;
    
    std.debug.assert(json_len <= MAX_JSON_RESPONSE_LEN);
    std.debug.assert(json_len <= json_out.len);
    
    return json_len;
}

// Build error response JSON (simplified, manual JSON construction)
pub fn build_error_response(
    error_code: []const u8,
    message: []const u8,
    json_out: []u8,
) u32 {
    std.debug.assert(error_code.len > 0);
    std.debug.assert(error_code.len <= 32);
    std.debug.assert(message.len > 0);
    std.debug.assert(message.len <= models.MAX_MESSAGE_LEN);
    std.debug.assert(json_out.len >= MAX_JSON_RESPONSE_LEN);
    
    var json_len: u32 = 0;
    json_out[json_len] = '{';
    json_len += 1;
    
    write_json_key(json_out, &json_len, "status");
    write_json_string_value(json_out, &json_len, "error");
    
    json_out[json_len] = ',';
    json_len += 1;
    write_json_key(json_out, &json_len, "error_code");
    write_json_string_value(json_out, &json_len, error_code);
    
    json_out[json_len] = ',';
    json_len += 1;
    write_json_key(json_out, &json_len, "message");
    write_json_string_value(json_out, &json_len, message);
    
    json_out[json_len] = '}';
    json_len += 1;
    
    std.debug.assert(json_len <= MAX_JSON_RESPONSE_LEN);
    std.debug.assert(json_len <= json_out.len);
    
    return json_len;
}

// Build auth response JSON (simplified, manual JSON construction)
pub fn build_auth_response(
    auth_resp: *const models.AuthResponse,
    json_out: []u8,
) u32 {
    std.debug.assert(auth_resp != null);
    std.debug.assert(json_out.len >= MAX_JSON_RESPONSE_LEN);
    
    var json_len: u32 = 0;
    json_out[json_len] = '{';
    json_len += 1;
    
    write_json_key(json_out, &json_len, "success");
    write_json_bool_value(json_out, &json_len, auth_resp.success);
    
    if (auth_resp.token_len > 0) {
        json_out[json_len] = ',';
        json_len += 1;
        write_json_key(json_out, &json_len, "token");
        write_json_string_value(json_out, &json_len,
auth_resp.token[0..auth_resp.token_len]);
    }
    
    if (auth_resp.user_id_len > 0) {
        json_out[json_len] = ',';
        json_len += 1;
        write_json_key(json_out, &json_len, "user_id");
        write_json_string_value(json_out, &json_len,
auth_resp.user_id[0..auth_resp.user_id_len]);
    }
    
    json_out[json_len] = '}';
    json_len += 1;
    
    std.debug.assert(json_len <= MAX_JSON_RESPONSE_LEN);
    std.debug.assert(json_len <= json_out.len);
    
    return json_len;
}

