) ?*const EndpointConfig {
    std.debug.assert(path.len > 0);
    
    var i: u32 = 0;
    while (i < MOBILE_ENDPOINTS.len) : (i += 1) {
        if (std.mem.eql(u8, MOBILE_ENDPOINTS[i].path, path)) {
            return &MOBILE_ENDPOINTS[i];
        }
    }
    
    return null;
}

// Get middleware configuration for endpoint
