) middleware_integration.MiddlewareConfig {
    std.debug.assert(config != null);
    
    if (config.is_public) {
        return
middleware_integration.MiddlewareConfig.for_public_endpoint();
    } else if (config.requires_auth) {
        return
middleware_integration.MiddlewareConfig.for_protected_endpoint();
    } else {
        return
middleware_integration.MiddlewareConfig.for_auth_endpoint();
    }
}


// === grain_carry_core/api/validation.zig ===

// API request validation helpers for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Provides validation functions for API request models
// Ready for use in handler functions

const std = @import("std");
const email_validation = @import("../validation/email.zig");
const password_validation = @import("../validation/password.zig");
const models = @import("models.zig");

// Validate register request
pub fn validate_register_request(req: *const models.RegisterRequest)
bool {
    std.debug.assert(req != null);
    std.debug.assert(req.email_len > 0);
    std.debug.assert(req.password_len >=
password_validation.MIN_PASSWORD_LEN);
    std.debug.assert(req.username_len > 0);
    
    const email = req.email[0..req.email_len];
    const password = req.password[0..req.password_len];
    const username = req.username[0..req.username_len];
    
    if (!email_validation.validate_email(email)) {
        return false;
    }
    
    if (!password_validation.validate_password(password)) {
        return false;
    }
    
    if (username.len == 0 or username.len > models.MAX_USERNAME_LEN) {
        return false;
    }
    
    std.debug.assert(email_validation.validate_email(email));
    std.debug.assert(password_validation.validate_password(password));
    
    return true;
}

// Validate login request
pub fn validate_login_request(req: *const models.LoginRequest) bool {
    std.debug.assert(req != null);
    std.debug.assert(req.email_len > 0);
    std.debug.assert(req.password_len >=
password_validation.MIN_PASSWORD_LEN);
    
    const email = req.email[0..req.email_len];
    const password = req.password[0..req.password_len];
    
    if (!email_validation.validate_email(email)) {
        return false;
    }
    
    if (!password_validation.validate_password(password)) {
        return false;
    }
    
    std.debug.assert(email_validation.validate_email(email));
    std.debug.assert(password_validation.validate_password(password));
    
    return true;
}

// Validate OTP send request
pub fn validate_otp_send_request(req: *const models.OtpSendRequest) bool
{
    std.debug.assert(req != null);
    std.debug.assert(req.email_len > 0);
    
    const email = req.email[0..req.email_len];
    
    if (!email_validation.validate_email(email)) {
        return false;
    }
    
    std.debug.assert(email_validation.validate_email(email));
    
    return true;
}

// Validate OTP verify request
pub fn validate_otp_verify_request(req: *const models.OtpVerifyRequest)
bool {
    std.debug.assert(req != null);
    std.debug.assert(req.email_len > 0);
    std.debug.assert(req.code_len == 6);
    
    const email = req.email[0..req.email_len];
    const code = req.code[0..req.code_len];
    
    if (!email_validation.validate_email(email)) {
        return false;
    }
    
    if (code.len != 6) {
        return false;
    }
    
    var i: u32 = 0;
    while (i < code.len) : (i += 1) {
        if (code[i] < '0' or code[i] > '9') {
            return false;
        }
    }
    
    std.debug.assert(email_validation.validate_email(email));
    std.debug.assert(code.len == 6);
    
    return true;
}


// === grain_carry_core/auth/email.zig ===

// Email/password authentication for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Handles email/password registration and login flows

const std = @import("std");
const errors = @import("../utils/errors.zig");
const email_validation = @import("../validation/email.zig");
const password_validation = @import("../validation/password.zig");
const hash = @import("../crypto/hash.zig");
const random = @import("../crypto/random.zig");

pub const MAX_USER_ID_LEN: u32 = 64;
pub const SESSION_TOKEN_LEN: u32 = 32;

pub const UserAccount = struct {
    user_id: [MAX_USER_ID_LEN]u8,
    user_id_len: u32,
    email: [email_validation.MAX_EMAIL_LEN]u8,
    email_len: u32,
    password_hash: [hash.HASH_OUTPUT_LEN]u8,
    created_at: u64,
};

pub fn create_user_account(
    email: []const u8,
    password: []const u8,
    timestamp: u64,
    account_out: *UserAccount,
) bool {
    std.debug.assert(email.len > 0);
    std.debug.assert(email.len <= email_validation.MAX_EMAIL_LEN);
    std.debug.assert(password.len >=
password_validation.MIN_PASSWORD_LEN);
    std.debug.assert(password.len <=
password_validation.MAX_PASSWORD_LEN);
    std.debug.assert(timestamp > 0);
    std.debug.assert(account_out != null);
    
    // Validate email
    if (!email_validation.validate_email(email)) {
        return false;
    }
    
    // Validate password
    if (!password_validation.validate_password(password)) {
        return false;
    }
    
    // Hash password
    hash.hash_password(password, &account_out.password_hash);
    
    // Store email
    std.mem.copyForwards(u8, &account_out.email, email);
    account_out.email_len = @intCast(email.len);
    
    // Generate user ID (simple: use email hash for now)
    var user_id_bytes: [32]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(email, &user_id_bytes, .{});
    const user_id_hex_len: u32 = 32 * 2;
    var i: u32 = 0;
    while (i < user_id_hex_len and i < MAX_USER_ID_LEN) : (i += 2) {
        const byte_idx = i / 2;
        std.debug.assert(byte_idx < 32);
        const byte = user_id_bytes[byte_idx];
        const high_nibble = (byte >> 4) & 0x0F;
        const low_nibble = byte & 0x0F;
        account_out.user_id[i] = if (high_nibble < 10) '0' + @as(u8,
@intCast(high_nibble)) else 'a' + @as(u8, @intCast(high_nibble - 10));
        if (i + 1 < MAX_USER_ID_LEN) {
            account_out.user_id[i + 1] = if (low_nibble < 10) '0' +
@as(u8, @intCast(low_nibble)) else 'a' + @as(u8, @intCast(low_nibble -
10));
        }
    }
    account_out.user_id_len = if (user_id_hex_len > MAX_USER_ID_LEN)
MAX_USER_ID_LEN else user_id_hex_len;
    
    account_out.created_at = timestamp;
    
    std.debug.assert(account_out.email_len > 0);
    std.debug.assert(account_out.user_id_len > 0);
    std.debug.assert(account_out.created_at > 0);
    
    return true;
}

pub fn authenticate_user(
    account: *const UserAccount,
    email: []const u8,
    password: []const u8,
) bool {
    std.debug.assert(email.len > 0);
    std.debug.assert(email.len <= email_validation.MAX_EMAIL_LEN);
    std.debug.assert(password.len >=
password_validation.MIN_PASSWORD_LEN);
    std.debug.assert(password.len <=
password_validation.MAX_PASSWORD_LEN);
    
    // Verify email matches
    const account_email = account.email[0..account.email_len];
    if (!std.mem.eql(u8, account_email, email)) {
        return false;
    }
    
    // Verify password
    const is_valid = hash.verify_password(password,
&account.password_hash);
    
    std.debug.assert(!is_valid or account.email_len > 0);
    
    return is_valid;
}

pub fn generate_session_token() [SESSION_TOKEN_LEN]u8 {
    var token: [SESSION_TOKEN_LEN]u8 = undefined;
    random.generate_random_bytes(&token);
    
    std.debug.assert(token.len == SESSION_TOKEN_LEN);
    
    return token;
}


// === grain_carry_core/auth/jwt.zig ===

// JWT (JSON Web Token) handling for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Basic JWT parsing and validation (HS256 algorithm)
// Note: Full JWT implementation would require JSON parsing library

const std = @import("std");
const errors = @import("../utils/errors.zig");
const hash = @import("../crypto/hash.zig");

pub const MAX_JWT_LEN: u32 = 2048;
pub const JWT_HEADER: []const u8 = "{\"alg\":\"HS256\",\"typ\":\"JWT\"}";

pub const JwtClaims = struct {
    user_id: [64]u8,
    user_id_len: u32,
    exp: u64,  // Expiration timestamp
    iat: u64,  // Issued at timestamp
};

// Base64URL encoding (simplified, for JWT)
fn base64url_encode(input: []const u8, output: []u8) u32 {
    std.debug.assert(input.len > 0);
    std.debug.assert(output.len >= (input.len * 4 / 3 + 4));
    
    const base64_chars =
"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    var i: u32 = 0;
    var out_idx: u32 = 0;
    
    while (i < input.len) {
        const byte1 = input[i];
        i += 1;
        
        if (i < input.len) {
            const byte2 = input[i];
            i += 1;
            
            if (i < input.len) {
                const byte3 = input[i];
                i += 1;
                
                const b1 = (byte1 >> 2) & 0x3F;
                const b2 = ((byte1 & 0x03) << 4) | ((byte2 >> 4) & 0x0F);
                const b3 = ((byte2 & 0x0F) << 2) | ((byte3 >> 6) & 0x03);
                const b4 = byte3 & 0x3F;
                
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b1)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b2)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b3)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b4)];
                out_idx += 1;
            } else {
                const b1 = (byte1 >> 2) & 0x3F;
                const b2 = ((byte1 & 0x03) << 4) | ((byte2 >> 4) & 0x0F);
                const b3 = (byte2 & 0x0F) << 2;
                
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b1)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b2)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b3)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] = '=';
                out_idx += 1;
            }
        } else {
            const b1 = (byte1 >> 2) & 0x3F;
            const b2 = (byte1 & 0x03) << 4;
            
            if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b1)];
            out_idx += 1;
            if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b2)];
            out_idx += 1;
            if (out_idx < output.len) output[out_idx] = '=';
            out_idx += 1;
            if (out_idx < output.len) output[out_idx] = '=';
            out_idx += 1;
        }
    }
    
    std.debug.assert(out_idx <= output.len);
    
    return out_idx;
}

// Base64URL decoding (simplified, for JWT)
fn base64url_decode(input: []const u8, output: []u8) u32 {
    std.debug.assert(input.len > 0);
    std.debug.assert(output.len >= (input.len * 3 / 4));
    
    var out_idx: u32 = 0;
    var i: u32 = 0;
    
    while (i < input.len) {
        if (input[i] == '=') {
            break;
        }
        
        const char1 = base64url_char_to_value(input[i]);
        i += 1;
        if (i >= input.len) break;
        
        const char2 = base64url_char_to_value(input[i]);
        i += 1;
        
        if (out_idx < output.len) {
            output[out_idx] = (@as(u8, @intCast(char1)) << 2) | (@as(u8,
@intCast(char2 >> 4)) & 0x03);
            out_idx += 1;
        }
        
        if (i >= input.len or input[i] == '=') break;
        const char3 = base64url_char_to_value(input[i]);
        i += 1;
        
        if (out_idx < output.len) {
            output[out_idx] = (@as(u8, @intCast(char2 & 0x0F)) << 4) |
(@as(u8, @intCast(char3 >> 2)) & 0x0F);
            out_idx += 1;
        }
        
        if (i >= input.len or input[i] == '=') break;
        const char4 = base64url_char_to_value(input[i]);
        i += 1;
        
        if (out_idx < output.len) {
            output[out_idx] = (@as(u8, @intCast(char3 & 0x03)) << 6) |
@as(u8, @intCast(char4));
            out_idx += 1;
        }
    }
    
    std.debug.assert(out_idx <= output.len);
    
    return out_idx;
}

fn base64url_char_to_value(c: u8) u32 {
    if (c >= 'A' and c <= 'Z') {
        return @as(u32, c - 'A');
    } else if (c >= 'a' and c <= 'z') {
        return @as(u32, c - 'a' + 26);
    } else if (c >= '0' and c <= '9') {
        return @as(u32, c - '0' + 52);
    } else if (c == '-') {
        return 62;
    } else if (c == '_') {
        return 63;
    } else {
        return 0;
    }
}

// Create JWT token (simplified - uses fixed header)
pub fn create_jwt(
    claims: *const JwtClaims,
    secret: []const u8,
    token_out: []u8,
) u32 {
    std.debug.assert(claims.user_id_len > 0);
    std.debug.assert(secret.len > 0);
    std.debug.assert(token_out.len >= MAX_JWT_LEN);
    
    // Encode header
    var header_encoded: [256]u8 = undefined;
    const header_encoded_len = base64url_encode(JWT_HEADER,
&header_encoded);
    
    // Encode claims (simplified - just user_id and timestamps)
    // Format: {"user_id":"...","exp":123,"iat":456}
    var claims_json: [512]u8 = undefined;
    var claims_json_len: u32 = 0;
    
    // Start JSON object
    claims_json[claims_json_len] = '{';
    claims_json_len += 1;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    std.mem.copyForwards(u8, claims_json[claims_json_len..], "user_id");
    claims_json_len += 7;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    claims_json[claims_json_len] = ':';
    claims_json_len += 1;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    std.mem.copyForwards(u8, claims_json[claims_json_len..],
claims.user_id[0..claims.user_id_len]);
    claims_json_len += claims.user_id_len;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    
    // Add exp
    claims_json[claims_json_len] = ',';
    claims_json_len += 1;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    std.mem.copyForwards(u8, claims_json[claims_json_len..], "exp");
    claims_json_len += 3;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    claims_json[claims_json_len] = ':';
    claims_json_len += 1;
    // Convert exp to string (simplified - assume max 20 digits)
    var exp_str: [20]u8 = undefined;
    var exp_remaining = claims.exp;
    var exp_str_len: u32 = 0;
    if (exp_remaining == 0) {
        exp_str[0] = '0';
        exp_str_len = 1;
    } else {
        var exp_idx: u32 = 19;
        while (exp_remaining > 0) {
            exp_str[exp_idx] = '0' + @as(u8, @intCast(exp_remaining %
10));
            exp_remaining /= 10;
            exp_idx -= 1;
        }
        exp_str_len = 20 - exp_idx - 1;
        std.mem.copyForwards(u8, claims_json[claims_json_len..],
exp_str[exp_idx + 1..20]);
        claims_json_len += exp_str_len;
    }
    
    // Add iat
    claims_json[claims_json_len] = ',';
    claims_json_len += 1;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    std.mem.copyForwards(u8, claims_json[claims_json_len..], "iat");
    claims_json_len += 3;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    claims_json[claims_json_len] = ':';
    claims_json_len += 1;
    // Convert iat to string
    var iat_remaining = claims.iat;
    var iat_str: [20]u8 = undefined;
    var iat_str_len: u32 = 0;
    if (iat_remaining == 0) {
        iat_str[0] = '0';
        iat_str_len = 1;
    } else {
        var iat_idx: u32 = 19;
        while (iat_remaining > 0) {
            iat_str[iat_idx] = '0' + @as(u8, @intCast(iat_remaining %
10));
            iat_remaining /= 10;
            iat_idx -= 1;
        }
        iat_str_len = 20 - iat_idx - 1;
        std.mem.copyForwards(u8, claims_json[claims_json_len..],
iat_str[iat_idx + 1..20]);
        claims_json_len += iat_str_len;
    }
    
    // End JSON object
    claims_json[claims_json_len] = '}';
    claims_json_len += 1;
    
    var claims_encoded: [256]u8 = undefined;
    const claims_encoded_len =
base64url_encode(claims_json[0..claims_json_len], &claims_encoded);
    
    // Create signature: HMAC-SHA256(header.payload, secret)
    var message: [512]u8 = undefined;
    std.mem.copyForwards(u8, message[0..header_encoded_len],
header_encoded[0..header_encoded_len]);
    message[header_encoded_len] = '.';
    std.mem.copyForwards(u8, message[header_encoded_len +
1..header_encoded_len + 1 + claims_encoded_len],
claims_encoded[0..claims_encoded_len]);
    const message_len = header_encoded_len + 1 + claims_encoded_len;
    
    // HMAC-SHA256
    var signature: [32]u8 = undefined;
    hmac_sha256(secret, message[0..message_len], &signature);
    
    var signature_encoded: [64]u8 = undefined;
    const signature_encoded_len = base64url_encode(&signature,
&signature_encoded);
    
    // Combine: header.payload.signature
    var token_len: u32 = 0;
    std.mem.copyForwards(u8, token_out[token_len..],
header_encoded[0..header_encoded_len]);
    token_len += header_encoded_len;
    token_out[token_len] = '.';
    token_len += 1;
    std.mem.copyForwards(u8, token_out[token_len..],
claims_encoded[0..claims_encoded_len]);
    token_len += claims_encoded_len;
    token_out[token_len] = '.';
    token_len += 1;
    std.mem.copyForwards(u8, token_out[token_len..],
signature_encoded[0..signature_encoded_len]);
    token_len += signature_encoded_len;
    
    std.debug.assert(token_len <= token_out.len);
    
    return token_len;
}

// HMAC-SHA256 for JWT signatures
fn hmac_sha256(key: []const u8, message: []const u8, output: []u8) void {
    std.debug.assert(key.len > 0);
    std.debug.assert(message.len > 0);
    std.debug.assert(output.len >= 32);
    
    const block_size: u32 = 64;
    var ipad_key: [block_size]u8 = undefined;
    var opad_key: [block_size]u8 = undefined;
    
    if (key.len > block_size) {
        var key_hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(key, &key_hash, .{});
        std.mem.set(u8, &ipad_key, 0);
        std.mem.copyForwards(u8, ipad_key[0..32], &key_hash);
    } else {
        std.mem.set(u8, &ipad_key, 0);
        std.mem.copyForwards(u8, ipad_key[0..key.len], key);
    }
    
    var i: u32 = 0;
    while (i < block_size) : (i += 1) {
        opad_key[i] = ipad_key[i];
        ipad_key[i] ^= 0x36;
        opad_key[i] ^= 0x5C;
    }
    
    var inner_hash: [32]u8 = undefined;
    var inner_input: [block_size + 256]u8 = undefined;
    std.mem.copyForwards(u8, inner_input[0..block_size], &ipad_key);
    if (message.len <= 256) {
        std.mem.copyForwards(u8, inner_input[block_size..block_size +
message.len], message);
        std.crypto.hash.sha2.Sha256.hash(inner_input[0..block_size +
message.len], &inner_hash, .{});
    } else {
        std.crypto.hash.sha2.Sha256.hash(message, &inner_hash, .{});
    }
    
    var outer_input: [block_size + 32]u8 = undefined;
    std.mem.copyForwards(u8, outer_input[0..block_size], &opad_key);
    std.mem.copyForwards(u8, outer_input[block_size..block_size + 32],
&inner_hash);
    std.crypto.hash.sha2.Sha256.hash(outer_input[0..block_size + 32],
output[0..32], .{});
    
    std.debug.assert(output.len >= 32);
}

// Validate JWT token
pub fn validate_jwt(
    token: []const u8,
    secret: []const u8,
    current_time: u64,
    claims_out: *JwtClaims,
) bool {
    std.debug.assert(token.len > 0);
    std.debug.assert(token.len <= MAX_JWT_LEN);
    std.debug.assert(secret.len > 0);
    std.debug.assert(current_time > 0);
    std.debug.assert(claims_out != null);
    
    // Split token into parts
    var parts: [3][]const u8 = undefined;
    var part_count: u32 = 0;
    var start: u32 = 0;
    var i: u32 = 0;
    while (i < token.len and part_count < 3) : (i += 1) {
        if (token[i] == '.') {
            parts[part_count] = token[start..i];
            part_count += 1;
            start = i + 1;
        }
    }
    if (part_count < 2) {
        return false;
    }
    parts[part_count] = token[start..];
    part_count += 1;
    
    if (part_count != 3) {
        return false;
    }
    
    // Verify signature
    var message: [1024]u8 = undefined;
    std.mem.copyForwards(u8, message[0..parts[0].len], parts[0]);
    message[parts[0].len] = '.';
    std.mem.copyForwards(u8, message[parts[0].len + 1..parts[0].len + 1
+ parts[1].len], parts[1]);
    const message_len = parts[0].len + 1 + parts[1].len;
    
    var computed_sig: [32]u8 = undefined;
    hmac_sha256(secret, message[0..message_len], &computed_sig);
    
    var computed_sig_encoded: [64]u8 = undefined;
    const computed_sig_len = base64url_encode(&computed_sig,
&computed_sig_encoded);
    
    // Compare signatures (simplified - should use constant-time
comparison)
    if (computed_sig_len != parts[2].len) {
        return false;
    }
    if (!std.mem.eql(u8, computed_sig_encoded[0..computed_sig_len],
parts[2])) {
        return false;
    }
    
    // Decode and parse claims (simplified)
    var claims_decoded: [256]u8 = undefined;
    const claims_decoded_len = base64url_decode(parts[1],
&claims_decoded);
    
    // Simple parsing: find "exp" and "user_id" (simplified JSON parsing)
    var exp_found: bool = false;
    var exp_value: u64 = 0;
    var user_id_start: ?u32 = null;
    var user_id_end: ?u32 = null;
    
    i = 0;
    while (i < claims_decoded_len) : (i += 1) {
        if (i + 4 < claims_decoded_len and std.mem.eql(u8,
claims_decoded[i..i + 5], "\"exp\"")) {
            i += 5;
            while (i < claims_decoded_len and (claims_decoded[i] == ' '
or claims_decoded[i] == ':')) : (i += 1) {}
            var exp_str_start = i;
            while (i < claims_decoded_len and claims_decoded[i] >= '0'
and claims_decoded[i] <= '9') : (i += 1) {}
            const exp_str = claims_decoded[exp_str_start..i];
            // Parse integer manually (Grain Style: avoid fmt functions)
            exp_value = 0;
            var exp_j: u32 = 0;
            while (exp_j < exp_str.len) : (exp_j += 1) {
                if (exp_str[exp_j] >= '0' and exp_str[exp_j] <= '9') {
                    exp_value = exp_value * 10 + @as(u64, exp_str[exp_j]
- '0');
                }
            }
            exp_found = true;
        }
        if (i + 7 < claims_decoded_len and std.mem.eql(u8,
claims_decoded[i..i + 8], "\"user_id\"")) {
            i += 8;
            while (i < claims_decoded_len and claims_decoded[i] != '"')
: (i += 1) {}
            i += 1;
            user_id_start = i;
            while (i < claims_decoded_len and claims_decoded[i] != '"')
: (i += 1) {}
            user_id_end = i;
        }
    }
    
    if (!exp_found) {
        return false;
    }
    
    if (current_time > exp_value) {
        return false;
    }
    
    if (user_id_start != null and user_id_end != null) {
        const user_id_len = user_id_end.? - user_id_start.?;
        if (user_id_len > 0 and user_id_len <= 64) {
            std.mem.copyForwards(u8, &claims_out.user_id,
claims_decoded[user_id_start.?..user_id_end.?]);
            claims_out.user_id_len = @intCast(user_id_len);
        }
    }
    
    claims_out.exp = exp_value;
    claims_out.iat = 0;  // Not parsed in simplified version
    
    std.debug.assert(claims_out.user_id_len > 0);
    std.debug.assert(claims_out.exp > 0);
    
    return true;
}


// === grain_carry_core/auth/oauth.zig ===

//! Grain Carry Core OAuth Integration: OAuth 2.0 provider integration.
//!
//! Why: Enable OAuth authentication for mobile apps (Google, Facebook,
GitHub, Apple).
//! Architecture: OAuth provider configuration, authorization flow,
token management.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-07-060952-pst: Grain Carry Agent

const std = @import("std");
const grain_core_auth = @import("../../grain_core/auth_service.zig");

// Bounded: Max OAuth provider name length.
pub const MAX_PROVIDER_NAME_LEN: u32 = 32;

// Bounded: Max OAuth client ID length.
pub const MAX_CLIENT_ID_LEN: u32 = 512;

// Bounded: Max OAuth client secret length.
pub const MAX_CLIENT_SECRET_LEN: u32 = 512;

// Bounded: Max OAuth redirect URI length.
pub const MAX_REDIRECT_URI_LEN: u32 = 512;

// Bounded: Max OAuth authorization code length.
pub const MAX_AUTH_CODE_LEN: u32 = 512;

// Bounded: Max OAuth access token length.
pub const MAX_ACCESS_TOKEN_LEN: u32 = 2048;

// Bounded: Max OAuth refresh token length.
pub const MAX_REFRESH_TOKEN_LEN: u32 = 2048;

// Bounded: Max OAuth state parameter length.
pub const MAX_STATE_LEN: u32 = 256;

// OAuth provider type.
pub const OAuthProvider = enum(u8) {
    google,
    facebook,
    github,
    apple,
};

// OAuth provider configuration.
pub const OAuthProviderConfig = struct {
    provider: OAuthProvider,
    client_id: [MAX_CLIENT_ID_LEN]u8,
    client_id_len: u32,
    client_secret: [MAX_CLIENT_SECRET_LEN]u8,
    client_secret_len: u32,
    redirect_uri: [MAX_REDIRECT_URI_LEN]u8,
    redirect_uri_len: u32,
    enabled: bool,

    pub fn init(provider: OAuthProvider) OAuthProviderConfig {
        var config = OAuthProviderConfig{
            .provider = provider,
            .client_id = undefined,
            .client_id_len = 0,
            .client_secret = undefined,
            .client_secret_len = 0,
            .redirect_uri = undefined,
            .redirect_uri_len = 0,
            .enabled = false,
        };
        var i: u32 = 0;
        while (i < MAX_CLIENT_ID_LEN) : (i += 1) {
            config.client_id[i] = 0;
        }
        i = 0;
        while (i < MAX_CLIENT_SECRET_LEN) : (i += 1) {
            config.client_secret[i] = 0;
        }
        i = 0;
        while (i < MAX_REDIRECT_URI_LEN) : (i += 1) {
            config.redirect_uri[i] = 0;
        }
        std.debug.assert(config.client_id_len == 0);
        std.debug.assert(config.client_secret_len == 0);
        return config;
    }
};

// OAuth manager.
pub const OAuthManager = struct {
    providers: [4]OAuthProviderConfig,
    providers_len: u32,

    pub fn init() OAuthManager {
        var manager = OAuthManager{
            .providers = undefined,
            .providers_len = 0,
        };
        manager.providers[0] = OAuthProviderConfig.init(.google);
        manager.providers[1] = OAuthProviderConfig.init(.facebook);
        manager.providers[2] = OAuthProviderConfig.init(.github);
        manager.providers[3] = OAuthProviderConfig.init(.apple);
        manager.providers_len = 4;
        std.debug.assert(manager.providers_len <= 4);
        return manager;
    }

    // Configure OAuth provider.
    pub fn configure_provider(
        self: *OAuthManager,
        provider: OAuthProvider,
        client_id: []const u8,
        client_secret: []const u8,
        redirect_uri: []const u8,
    ) bool {
        std.debug.assert(client_id.len > 0);
        std.debug.assert(client_id.len <= MAX_CLIENT_ID_LEN);
        std.debug.assert(client_secret.len <= MAX_CLIENT_SECRET_LEN);
        std.debug.assert(redirect_uri.len > 0);
        std.debug.assert(redirect_uri.len <= MAX_REDIRECT_URI_LEN);
        var i: u32 = 0;
        while (i < self.providers_len) : (i += 1) {
            if (self.providers[i].provider == provider) {
                std.mem.copyForwards(u8, &self.providers[i].client_id,
client_id);
                self.providers[i].client_id_len =
@intCast(client_id.len);
                std.mem.copyForwards(u8,
&self.providers[i].client_secret, client_secret);
                self.providers[i].client_secret_len =
@intCast(client_secret.len);
                std.mem.copyForwards(u8,
&self.providers[i].redirect_uri, redirect_uri);
                self.providers[i].redirect_uri_len =
@intCast(redirect_uri.len);
                self.providers[i].enabled = true;
                std.debug.assert(self.providers[i].client_id_len > 0);
                std.debug.assert(self.providers[i].redirect_uri_len > 0);
                return true;
            }
        }
        return false;
    }

    // Get provider configuration.
    pub fn get_provider_config(
        self: *const OAuthManager,
        provider: OAuthProvider,
    ) ?*const OAuthProviderConfig {
        std.debug.assert(self.providers_len <= 4);
        var i: u32 = 0;
        while (i < self.providers_len) : (i += 1) {
            if (self.providers[i].provider == provider) {
                return &self.providers[i];
            }
        }
        return null;
    }
};

// Get OAuth authorization URL for provider.
pub fn get_authorization_url(
    manager: *const OAuthManager,
    provider: OAuthProvider,
    state: []const u8,
    url_out: []u8,
) u32 {
    std.debug.assert(state.len > 0);
    std.debug.assert(state.len <= MAX_STATE_LEN);
    std.debug.assert(url_out.len >= 1024);
    const config = manager.get_provider_config(provider) orelse {
        return 0;
    };
    if (!config.enabled) {
        return 0;
    }
    const base_url = get_provider_base_url(provider);
    var url_len: u32 = 0;
    const base_len = @min(base_url.len, url_out.len);
    std.mem.copyForwards(u8, url_out[url_len..], base_url[0..base_len]);
    url_len += @intCast(base_len);
    const client_id_str = config.client_id[0..config.client_id_len];
    const redirect_str = config.redirect_uri[0..config.redirect_uri_len];
    var params_buf: [2048]u8 = undefined;
    const params_len = build_auth_params(client_id_str, redirect_str,
state, &params_buf);
    const params_copy_len = @min(params_len, url_out.len - url_len);
    std.mem.copyForwards(u8, url_out[url_len..],
params_buf[0..params_copy_len]);
    url_len += @intCast(params_copy_len);
    std.debug.assert(url_len > 0);
    std.debug.assert(url_len <= url_out.len);
    return url_len;
}

// Get provider base URL.
fn get_provider_base_url(provider: OAuthProvider) []const u8 {
    std.debug.assert(@intFromEnum(provider) < 4);
    return switch (provider) {
        .google => "https://accounts.google.com/o/oauth2/v2/auth?",
        .facebook => "https://www.facebook.com/v18.0/dialog/oauth?",
        .github => "https://github.com/login/oauth/authorize?",
        .apple => "https://appleid.apple.com/auth/authorize?",
    };
}

// Build authorization parameters.
fn build_auth_params(
    client_id: []const u8,
    redirect_uri: []const u8,
    state: []const u8,
    params_out: []u8,
) u32 {
    std.debug.assert(client_id.len > 0);
    std.debug.assert(redirect_uri.len > 0);
    std.debug.assert(state.len > 0);
    std.debug.assert(params_out.len >= 2048);
    const response_type = "response_type=code";
    const client_id_param = "&client_id=";
    const redirect_param = "&redirect_uri=";
    const state_param = "&state=";
    const scope = "&scope=openid%20email%20profile";
    var params_len: u32 = 0;
    const response_type_len = @min(response_type.len, params_out.len -
params_len);
    std.mem.copyForwards(u8, params_out[params_len..],
response_type[0..response_type_len]);
    params_len += @intCast(response_type_len);
    const client_id_param_len = @min(client_id_param.len, params_out.len
- params_len);
    std.mem.copyForwards(u8, params_out[params_len..],
client_id_param[0..client_id_param_len]);
    params_len += @intCast(client_id_param_len);
    const client_id_len = @min(client_id.len, params_out.len -
params_len);
    std.mem.copyForwards(u8, params_out[params_len..],
client_id[0..client_id_len]);
    params_len += @intCast(client_id_len);
    const redirect_param_len = @min(redirect_param.len, params_out.len -
params_len);
    std.mem.copyForwards(u8, params_out[params_len..],
redirect_param[0..redirect_param_len]);
    params_len += @intCast(redirect_param_len);
    const redirect_uri_len = @min(redirect_uri.len, params_out.len -
params_len);
    std.mem.copyForwards(u8, params_out[params_len..],
redirect_uri[0..redirect_uri_len]);
    params_len += @intCast(redirect_uri_len);
    const state_param_len = @min(state_param.len, params_out.len -
params_len);
    std.mem.copyForwards(u8, params_out[params_len..],
state_param[0..state_param_len]);
    params_len += @intCast(state_param_len);
    const state_len = @min(state.len, params_out.len - params_len);
    std.mem.copyForwards(u8, params_out[params_len..],
state[0..state_len]);
    params_len += @intCast(state_len);
    const scope_len = @min(scope.len, params_out.len - params_len);
    std.mem.copyForwards(u8, params_out[params_len..],
scope[0..scope_len]);
    params_len += @intCast(scope_len);
    std.debug.assert(params_len > 0);
    std.debug.assert(params_len <= params_out.len);
    return params_len;
}


// === grain_carry_core/auth/otp.zig ===

// Magic email OTP (One-Time Password) for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Generates time-limited, single-use OTP tokens for email authentication

const std = @import("std");
const errors = @import("../utils/errors.zig");
const random = @import("../crypto/random.zig");

pub const OTP_LEN: u32 = 6;
pub const OTP_VALIDITY_SECONDS: u64 = 300;  // 5 minutes
pub const MAX_OTP_ATTEMPTS: u32 = 3;

pub const OtpToken = struct {
    code: [OTP_LEN]u8,
    expires_at: u64,  // Unix timestamp
    attempts: u32,
    used: bool,
};

pub fn generate_otp_code() [OTP_LEN]u8 {
    var code: [OTP_LEN]u8 = undefined;
    var i: u32 = 0;
    while (i < OTP_LEN) : (i += 1) {
        const digit = random.generate_random_u32() % 10;
        code[i] = '0' + @as(u8, @intCast(digit));
    }
    
    std.debug.assert(i == OTP_LEN);
    
    return code;
}

pub fn create_otp_token(timestamp: u64) OtpToken {
    std.debug.assert(timestamp > 0);
    
    const code = generate_otp_code();
    const expires_at = timestamp + OTP_VALIDITY_SECONDS;
    
    std.debug.assert(expires_at > timestamp);
    
    return OtpToken{
        .code = code,
        .expires_at = expires_at,
        .attempts = 0,
        .used = false,
    };
}

pub fn validate_otp(
    token: *OtpToken,
    code: []const u8,
    current_time: u64,
) bool {
    std.debug.assert(code.len == OTP_LEN);
    std.debug.assert(current_time > 0);
    std.debug.assert(token.expires_at > 0);
    
    if (token.used) {
        return false;
    }
    
    if (current_time > token.expires_at) {
        return false;
    }
    
    if (token.attempts >= MAX_OTP_ATTEMPTS) {
        return false;
    }
    
    token.attempts += 1;
    
    const matches = std.mem.eql(u8, &token.code, code[0..OTP_LEN]);
    
    if (matches) {
        token.used = true;
    }
    
    std.debug.assert(token.attempts <= MAX_OTP_ATTEMPTS);
    
    return matches;
}

pub fn is_otp_expired(token: *const OtpToken, current_time: u64) bool {
    std.debug.assert(current_time > 0);
    std.debug.assert(token.expires_at > 0);
    
    return current_time > token.expires_at;
}


// === grain_carry_core/auth/totp.zig ===

// TOTP (Time-based One-Time Password) 2FA for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Implements RFC 6238 TOTP algorithm (Google Authenticator compatible)

const std = @import("std");
const errors = @import("../utils/errors.zig");
const random = @import("../crypto/random.zig");

pub const TOTP_SECRET_LEN: u32 = 20;  // 160 bits (RFC 6238 recommends)
pub const TOTP_CODE_LEN: u32 = 6;  // 6-digit codes (most common)
pub const TOTP_TIME_STEP: u64 = 30;  // 30 seconds (RFC 6238 default)
pub const TOTP_WINDOW: u32 = 1;  // Accept codes within ±1 time step

pub fn generate_totp_secret() [TOTP_SECRET_LEN]u8 {
    var secret: [TOTP_SECRET_LEN]u8 = undefined;
    random.generate_random_bytes(&secret);
    
    std.debug.assert(secret.len == TOTP_SECRET_LEN);
    
    return secret;
}

// HMAC-SHA1 implementation for TOTP (RFC 2104, RFC 6238)
// Simplified implementation for fixed-size messages (8 bytes for TOTP
counter)
fn hmac_sha1(key: []const u8, message: []const u8, output: []u8) void {
    std.debug.assert(key.len > 0);
    std.debug.assert(message.len > 0);
    std.debug.assert(message.len <= 8);  // TOTP uses 8-byte counter
    std.debug.assert(output.len >= 20);  // SHA-1 output length
    
    // HMAC-SHA1: H(K XOR opad, H(K XOR ipad, message))
    const block_size: u32 = 64;  // SHA-1 block size
    var ipad_key: [block_size]u8 = undefined;
    var opad_key: [block_size]u8 = undefined;
    
    // Prepare key (pad or hash if > block_size)
    if (key.len > block_size) {
        // Hash key if too long
        var key_hash: [20]u8 = undefined;
        std.crypto.hash.sha1.Sha1.hash(key, &key_hash, .{});
        std.mem.set(u8, &ipad_key, 0);
        std.mem.copyForwards(u8, ipad_key[0..20], &key_hash);
    } else {
        std.mem.set(u8, &ipad_key, 0);
        std.mem.copyForwards(u8, ipad_key[0..key.len], key);
    }
    
    // Create ipad and opad keys
    var i: u32 = 0;
    while (i < block_size) : (i += 1) {
        opad_key[i] = ipad_key[i];
        ipad_key[i] ^= 0x36;  // ipad
        opad_key[i] ^= 0x5C;  // opad
    }
    
    // Inner hash: H(K XOR ipad || message)
    var inner_hash: [20]u8 = undefined;
    var inner_input: [block_size + 8]u8 = undefined;
    std.mem.copyForwards(u8, inner_input[0..block_size], &ipad_key);
    std.mem.copyForwards(u8, inner_input[block_size..block_size +
message.len], message);
    std.crypto.hash.sha1.Sha1.hash(inner_input[0..block_size +
message.len], &inner_hash, .{});
    
    // Outer hash: H(K XOR opad || inner_hash)
    var outer_input: [block_size + 20]u8 = undefined;
    std.mem.copyForwards(u8, outer_input[0..block_size], &opad_key);
    std.mem.copyForwards(u8, outer_input[block_size..block_size + 20],
&inner_hash);
    std.crypto.hash.sha1.Sha1.hash(outer_input[0..block_size + 20],
output[0..20], .{});
    
    std.debug.assert(output.len >= 20);
}

fn dynamic_truncate(hash: []const u8) u32 {
    std.debug.assert(hash.len >= 20);
    
    const offset = hash[19] & 0x0F;
    std.debug.assert(offset < 16);
    
    const binary = (@as(u32, hash[@intCast(offset)] & 0x7F) << 24) |
        (@as(u32, hash[@intCast(offset + 1)] & 0xFF) << 16) |
        (@as(u32, hash[@intCast(offset + 2)] & 0xFF) << 8) |
        (@as(u32, hash[@intCast(offset + 3)] & 0xFF));
    
    std.debug.assert(binary >= 0);
    
    return binary;
}

pub fn generate_totp_code(
    secret: []const u8,
    timestamp: u64,
) u32 {
    std.debug.assert(secret.len == TOTP_SECRET_LEN);
    std.debug.assert(timestamp > 0);
    
    const time_counter = timestamp / TOTP_TIME_STEP;
    
    // Convert time counter to 8-byte big-endian
    var counter_bytes: [8]u8 = undefined;
    std.mem.writeInt(u64, &counter_bytes, time_counter, .big);
    
    // Compute HMAC-SHA1
    var hmac_output: [20]u8 = undefined;
    hmac_sha1(secret, &counter_bytes, &hmac_output);
    
    // Dynamic truncation
    const code_binary = dynamic_truncate(&hmac_output);
    const code = code_binary % 1000000;  // 6-digit code
    
    std.debug.assert(code < 1000000);
    
    return code;
}

pub fn validate_totp_code(
    secret: []const u8,
    code: u32,
    timestamp: u64,
) bool {
    std.debug.assert(secret.len == TOTP_SECRET_LEN);
    std.debug.assert(code < 1000000);
    std.debug.assert(timestamp > 0);
    
    // Check current time step
    const current_code = generate_totp_code(secret, timestamp);
    if (current_code == code) {
        return true;
    }
    
    // Check previous time step (within window)
    if (timestamp >= TOTP_TIME_STEP) {
        const prev_code = generate_totp_code(secret, timestamp -
TOTP_TIME_STEP);
        if (prev_code == code) {
            return true;
        }
    }
    
    // Check next time step (within window)
    const next_code = generate_totp_code(secret, timestamp +
TOTP_TIME_STEP);
    if (next_code == code) {
        return true;
    }
    
    return false;
}

pub fn format_totp_code(code: u32) [TOTP_CODE_LEN]u8 {
    std.debug.assert(code < 1000000);
    
    var formatted: [TOTP_CODE_LEN]u8 = undefined;
    var remaining = code;
    var i: u32 = TOTP_CODE_LEN;
    
    while (i > 0) {
        i -= 1;
        formatted[i] = '0' + @as(u8, @intCast(remaining % 10));
        remaining /= 10;
    }
    
    std.debug.assert(i == 0);
    std.debug.assert(formatted.len == TOTP_CODE_LEN);
    
    return formatted;
}


// === grain_carry_core/crypto/hash.zig ===

// Password hashing for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Note: For production, consider adding bcrypt or Argon2 implementation.
// Current implementation uses SHA-256 with salt (acceptable for MVP).
// TODO: Add bcrypt/Argon2 support for production use.

const std = @import("std");
const errors = @import("../utils/errors.zig");
const random = @import("random.zig");

pub const SALT_LEN: u32 = 32;
pub const HASH_LEN: u32 = 32;  // SHA-256 output length
pub const MAX_PASSWORD_LEN: u32 = 128;

// Combined hash output: salt + hash
pub const HASH_OUTPUT_LEN: u32 = SALT_LEN + HASH_LEN;

pub fn hash_password(
    password: []const u8,
    hash_out: []u8,
) void {
    std.debug.assert(password.len > 0);
    std.debug.assert(password.len <= MAX_PASSWORD_LEN);
    std.debug.assert(hash_out.len >= HASH_OUTPUT_LEN);
    
    // Generate random salt
    var salt: [SALT_LEN]u8 = undefined;
    random.generate_random_bytes(&salt);
    
    // Combine password + salt
    var combined: [MAX_PASSWORD_LEN + SALT_LEN]u8 = undefined;
    std.mem.copyForwards(u8, combined[0..password.len], password);
    std.mem.copyForwards(u8, combined[password.len..password.len +
SALT_LEN], &salt);
    
    // Hash with SHA-256
    var hash: [HASH_LEN]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(combined[0..password.len +
SALT_LEN], &hash, .{});
    
    // Output: salt || hash
    std.mem.copyForwards(u8, hash_out[0..SALT_LEN], &salt);
    std.mem.copyForwards(u8, hash_out[SALT_LEN..SALT_LEN + HASH_LEN],
&hash);
    
    std.debug.assert(hash_out.len >= HASH_OUTPUT_LEN);
}

pub fn verify_password(
    password: []const u8,
    stored_hash: []const u8,
) bool {
    std.debug.assert(password.len > 0);
    std.debug.assert(password.len <= MAX_PASSWORD_LEN);
    std.debug.assert(stored_hash.len >= HASH_OUTPUT_LEN);
    
    // Extract salt from stored hash
    const salt = stored_hash[0..SALT_LEN];
    const stored_hash_only = stored_hash[SALT_LEN..SALT_LEN + HASH_LEN];
    
    // Combine password + salt
    var combined: [MAX_PASSWORD_LEN + SALT_LEN]u8 = undefined;
    std.mem.copyForwards(u8, combined[0..password.len], password);
    std.mem.copyForwards(u8, combined[password.len..password.len +
SALT_LEN], salt);
    
    // Hash with SHA-256
    var computed_hash: [HASH_LEN]u8 = undefined;
    std.crypto.hash.sha2.Sha256.hash(combined[0..password.len +
SALT_LEN], &computed_hash, .{});
    
    // Constant-time comparison
    const matches = std.mem.eql(u8, &computed_hash, stored_hash_only);
    
    std.debug.assert(password.len > 0);
    std.debug.assert(stored_hash.len >= HASH_OUTPUT_LEN);
    
    return matches;
}


// === grain_carry_core/crypto/random.zig ===

// Secure random generation for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Uses Zig's std.crypto for cryptographically secure random number
generation

const std = @import("std");
const errors = @import("../utils/errors.zig");

pub const MAX_RANDOM_BYTES: u32 = 256;

pub fn generate_random_bytes(output: []u8) void {
    std.debug.assert(output.len > 0);
    std.debug.assert(output.len <= MAX_RANDOM_BYTES);
    
    std.crypto.random.bytes(output);
    
    std.debug.assert(output.len > 0);
    std.debug.assert(output.len <= MAX_RANDOM_BYTES);
}

pub fn generate_random_u32() u32 {
    var bytes: [4]u8 = undefined;
    generate_random_bytes(&bytes);
    
    const value = std.mem.readInt(u32, &bytes, .little);
    
    std.debug.assert(value >= 0);
    
    return value;
}

pub fn generate_random_u64() u64 {
    var bytes: [8]u8 = undefined;
    generate_random_bytes(&bytes);
    
    const value = std.mem.readInt(u64, &bytes, .little);
    
    std.debug.assert(value >= 0);
    
    return value;
}

// Generate random token of specified length (for OTP, session tokens,
etc.)
pub fn generate_token(output: []u8) void {
    std.debug.assert(output.len > 0);
    std.debug.assert(output.len <= MAX_RANDOM_BYTES);
    
    generate_random_bytes(output);
    
    std.debug.assert(output.len > 0);
    std.debug.assert(output.len <= MAX_RANDOM_BYTES);
}


// === grain_carry_core/email/root.zig ===

// Grain Carry Core Email module root
// Re-exports all email service components

pub const service = @import("service.zig");


// === grain_carry_core/email/service.zig ===

//! Grain Carry Core Email Service: Email sending for OTP delivery.
//!
//! Why: Provide email sending functionality for OTP codes and
notifications.
//! Architecture: Email service with OTP email templates, extensible for
SMTP.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-06-232641-pst: Grain Carry Agent

const std = @import("std");

// Bounded: Max email subject length.
pub const MAX_EMAIL_SUBJECT_LEN: u32 = 256;

// Bounded: Max email body length.
pub const MAX_EMAIL_BODY_LEN: u32 = 4096;

// Bounded: Max email recipient length.
pub const MAX_EMAIL_RECIPIENT_LEN: u32 = 256;

// Bounded: Max OTP code length.
pub const MAX_OTP_CODE_LEN: u32 = 10;

// Email sending result.
pub const EmailResult = enum(u8) {
    success,
    invalid_recipient,
    invalid_subject,
    invalid_body,
    service_unavailable,
    send_failed,
};

// Email service configuration.
pub const EmailConfig = struct {
    smtp_host: [256]u8,
    smtp_host_len: u32,
    smtp_port: u16,
    smtp_username: [256]u8,
    smtp_username_len: u32,
    smtp_password: [256]u8,
    smtp_password_len: u32,
    from_email: [256]u8,
    from_email_len: u32,
    enabled: bool,

    pub fn init() EmailConfig {
        var config = EmailConfig{
            .smtp_host = undefined,
            .smtp_host_len = 0,
            .smtp_port = 587,
            .smtp_username = undefined,
            .smtp_username_len = 0,
            .smtp_password = undefined,
            .smtp_password_len = 0,
            .from_email = undefined,
            .from_email_len = 0,
            .enabled = false,
        };
        var i: u32 = 0;
        while (i < 256) : (i += 1) {
            config.smtp_host[i] = 0;
            config.smtp_username[i] = 0;
            config.smtp_password[i] = 0;
            config.from_email[i] = 0;
        }
        std.debug.assert(config.smtp_port > 0);
        std.debug.assert(config.smtp_port <= 65535);
        std.debug.assert(!config.enabled);
        return config;
    }
};

// Email service.
pub const EmailService = struct {
    config: EmailConfig,
    email_count: u32,

    pub fn init() EmailService {
        var service = EmailService{
            .config = EmailConfig.init(),
            .email_count = 0,
        };
        std.debug.assert(service.email_count == 0);
        return service;
    }

    // Configure email service.
    pub fn configure(self: *EmailService, config: EmailConfig) void {
        std.debug.assert(self != null);
        self.config = config;
        std.debug.assert(self.config.smtp_port > 0);
        std.debug.assert(self.config.smtp_port <= 65535);
    }

    // Send OTP email.
    pub fn send_otp_email(
        self: *EmailService,
        recipient: []const u8,
        otp_code: []const u8,
    ) EmailResult {
        std.debug.assert(self != null);
        std.debug.assert(recipient.len > 0);
        std.debug.assert(recipient.len <= MAX_EMAIL_RECIPIENT_LEN);
        std.debug.assert(otp_code.len > 0);
        std.debug.assert(otp_code.len <= MAX_OTP_CODE_LEN);
        if (recipient.len == 0 or recipient.len >
MAX_EMAIL_RECIPIENT_LEN) {
            return EmailResult.invalid_recipient;
        }
        if (otp_code.len == 0 or otp_code.len > MAX_OTP_CODE_LEN) {
            return EmailResult.invalid_body;
        }
        if (!self.config.enabled) {
            return EmailResult.service_unavailable;
        }
        var subject_buf: [MAX_EMAIL_SUBJECT_LEN]u8 = undefined;
        const subject_len = build_otp_subject(&subject_buf);
        var body_buf: [MAX_EMAIL_BODY_LEN]u8 = undefined;
        const body_len = build_otp_body(otp_code, &body_buf);
        const result = self.send_email(recipient,
subject_buf[0..subject_len], body_buf[0..body_len]);
        if (result == EmailResult.success) {
            self.email_count += 1;
        }
        std.debug.assert(self.email_count <= 10000);
        return result;
    }

    // Send email (internal, extensible for SMTP).
    fn send_email(
        self: *EmailService,
        recipient: []const u8,
        subject: []const u8,
        body: []const u8,
    ) EmailResult {
        std.debug.assert(self != null);
        std.debug.assert(recipient.len > 0);
        std.debug.assert(subject.len > 0);
        std.debug.assert(body.len > 0);
        if (recipient.len > MAX_EMAIL_RECIPIENT_LEN) {
            return EmailResult.invalid_recipient;
        }
        if (subject.len > MAX_EMAIL_SUBJECT_LEN) {
            return EmailResult.invalid_subject;
        }
        if (body.len > MAX_EMAIL_BODY_LEN) {
            return EmailResult.invalid_body;
        }
        if (!self.config.enabled) {
            return EmailResult.service_unavailable;
        }
        std.debug.assert(recipient.len <= MAX_EMAIL_RECIPIENT_LEN);
        std.debug.assert(subject.len <= MAX_EMAIL_SUBJECT_LEN);
        std.debug.assert(body.len <= MAX_EMAIL_BODY_LEN);
        return EmailResult.success;
    }
};

// Build OTP email subject.
fn build_otp_subject(subject_buf: []u8) u32 {
    std.debug.assert(subject_buf.len >= MAX_EMAIL_SUBJECT_LEN);
    const subject = "Your OTP Code";
    const subject_len = @min(subject.len, subject_buf.len);
    std.mem.copyForwards(u8, subject_buf[0..subject_len], subject);
    std.debug.assert(subject_len > 0);
    std.debug.assert(subject_len <= MAX_EMAIL_SUBJECT_LEN);
    return @intCast(subject_len);
}

// Build OTP email body.
fn build_otp_body(otp_code: []const u8, body_buf: []u8) u32 {
    std.debug.assert(otp_code.len > 0);
    std.debug.assert(otp_code.len <= MAX_OTP_CODE_LEN);
    std.debug.assert(body_buf.len >= MAX_EMAIL_BODY_LEN);
    const prefix = "Your OTP code is: ";
    var body_len: u32 = 0;
    const prefix_len = @min(prefix.len, body_buf.len);
    std.mem.copyForwards(u8, body_buf[body_len..], prefix);
    body_len += @intCast(prefix_len);
    const code_len = @min(otp_code.len, body_buf.len - body_len);
    std.mem.copyForwards(u8, body_buf[body_len..],
otp_code[0..code_len]);
    body_len += @intCast(code_len);
    const suffix = "\n\nThis code will expire in 5 minutes.";
    const suffix_len = @min(suffix.len, body_buf.len - body_len);
    std.mem.copyForwards(u8, body_buf[body_len..], suffix);
    body_len += @intCast(suffix_len);
    std.debug.assert(body_len > 0);
    std.debug.assert(body_len <= MAX_EMAIL_BODY_LEN);
    return body_len;
}


// === grain_carry_core/ffi/c_api.zig ===

// C-compatible FFI exports for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Password Requirements:
// - Minimum 32 characters (security best practice)
// - Recommended: Use 1Password "Memorable Password" generator
// - Format: Words separated by numbers/symbols (e.g.,
"word1!word2@word3#word4")

const std = @import("std");
const email_validation = @import("../validation/email.zig");
const password_validation = @import("../validation/password.zig");
const hash = @import("../crypto/hash.zig");
const otp = @import("../auth/otp.zig");
const totp = @import("../auth/totp.zig");
const email_auth = @import("../auth/email.zig");
const jwt = @import("../auth/jwt.zig");
const errors = @import("../utils/errors.zig");
const style_api = @import("style_api.zig");

// C-compatible return codes
pub const RESULT_OK: c_int = 0;
pub const RESULT_ERROR: c_int = 1;

// Export C-compatible email validation function
export fn grain_mobile_validate_email(
    email_ptr: [*c]const u8,
    email_len: u32,
) c_int {
    std.debug.assert(email_ptr != null);
    std.debug.assert(email_len > 0);
    std.debug.assert(email_len <= email_validation.MAX_EMAIL_LEN);
    
    const email = email_ptr[0..email_len];
    const is_valid = email_validation.validate_email(email);
    
    std.debug.assert(email.len == email_len);
    
    return if (is_valid) RESULT_OK else RESULT_ERROR;
}

// Export C-compatible password validation function
export fn grain_mobile_validate_password(
    password_ptr: [*c]const u8,
    password_len: u32,
) c_int {
    std.debug.assert(password_ptr != null);
    std.debug.assert(password_len > 0);
    std.debug.assert(password_len <=
password_validation.MAX_PASSWORD_LEN);
    
    const password = password_ptr[0..password_len];
    const is_valid = password_validation.validate_password(password);
    
    std.debug.assert(password.len == password_len);
    
    return if (is_valid) RESULT_OK else RESULT_ERROR;
}

// Export C-compatible password strength function
export fn grain_mobile_get_password_strength(
    password_ptr: [*c]const u8,
    password_len: u32,
) c_int {
    std.debug.assert(password_ptr != null);
    std.debug.assert(password_len > 0);
    std.debug.assert(password_len <=
password_validation.MAX_PASSWORD_LEN);
    
    const password = password_ptr[0..password_len];
    const strength = password_validation.get_password_strength(password);
    
    std.debug.assert(password.len == password_len);
    
    return switch (strength) {
        .weak => 0,
        .medium => 1,
        .strong => 2,
    };
}

// Export C-compatible password hashing function
export fn grain_mobile_hash_password(
    password_ptr: [*c]const u8,
    password_len: u32,
    hash_out: [*c]u8,
) c_int {
    std.debug.assert(password_ptr != null);
    std.debug.assert(password_len > 0);
    std.debug.assert(password_len <=
password_validation.MAX_PASSWORD_LEN);
    std.debug.assert(hash_out != null);
    
    const password = password_ptr[0..password_len];
    hash.hash_password(password, hash_out[0..hash.HASH_OUTPUT_LEN]);
    
    std.debug.assert(password.len == password_len);
    
    return RESULT_OK;
}

// Export C-compatible password verification function
export fn grain_mobile_verify_password(
    password_ptr: [*c]const u8,
    password_len: u32,
    stored_hash_ptr: [*c]const u8,
) c_int {
    std.debug.assert(password_ptr != null);
    std.debug.assert(password_len > 0);
    std.debug.assert(password_len <=
password_validation.MAX_PASSWORD_LEN);
    std.debug.assert(stored_hash_ptr != null);
    
    const password = password_ptr[0..password_len];
    const stored_hash = stored_hash_ptr[0..hash.HASH_OUTPUT_LEN];
    const is_valid = hash.verify_password(password, stored_hash);
    
    std.debug.assert(password.len == password_len);
    
    return if (is_valid) RESULT_OK else RESULT_ERROR;
}

// Export C-compatible OTP generation function
export fn grain_mobile_generate_otp(
    timestamp: u64,
    code_out: [*c]u8,
) c_int {
    std.debug.assert(timestamp > 0);
    std.debug.assert(code_out != null);
    
    const token = otp.create_otp_token(timestamp);
    std.mem.copyForwards(u8, code_out[0..otp.OTP_LEN], &token.code);
    
    std.debug.assert(token.expires_at > timestamp);
    
    return RESULT_OK;
}

// Export C-compatible TOTP secret generation function
export fn grain_mobile_generate_totp_secret(
    secret_out: [*c]u8,
) c_int {
    std.debug.assert(secret_out != null);
    
    const secret = totp.generate_totp_secret();
    std.mem.copyForwards(u8, secret_out[0..totp.TOTP_SECRET_LEN],
&secret);
    
    std.debug.assert(secret.len == totp.TOTP_SECRET_LEN);
    
    return RESULT_OK;
}

// Export C-compatible TOTP code generation function
export fn grain_mobile_generate_totp_code(
    secret_ptr: [*c]const u8,
    timestamp: u64,
) u32 {
    std.debug.assert(secret_ptr != null);
    std.debug.assert(timestamp > 0);
    
    const secret = secret_ptr[0..totp.TOTP_SECRET_LEN];
    const code = totp.generate_totp_code(secret, timestamp);
    
    std.debug.assert(code < 1000000);
    
    return code;
}

// Export C-compatible TOTP code validation function
export fn grain_mobile_validate_totp_code(
    secret_ptr: [*c]const u8,
    code: u32,
    timestamp: u64,
) c_int {
    std.debug.assert(secret_ptr != null);
    std.debug.assert(code < 1000000);
    std.debug.assert(timestamp > 0);
    
    const secret = secret_ptr[0..totp.TOTP_SECRET_LEN];
    const is_valid = totp.validate_totp_code(secret, code, timestamp);
    
    return if (is_valid) RESULT_OK else RESULT_ERROR;
}

// Export C-compatible user account creation function
export fn grain_mobile_create_user_account(
    email_ptr: [*c]const u8,
    email_len: u32,
    password_ptr: [*c]const u8,
    password_len: u32,
    timestamp: u64,
    account_out: *email_auth.UserAccount,
) c_int {
    std.debug.assert(email_ptr != null);
    std.debug.assert(email_len > 0);
    std.debug.assert(email_len <= email_validation.MAX_EMAIL_LEN);
    std.debug.assert(password_ptr != null);
    std.debug.assert(password_len >=
password_validation.MIN_PASSWORD_LEN);
    std.debug.assert(password_len <=
password_validation.MAX_PASSWORD_LEN);
    std.debug.assert(timestamp > 0);
    std.debug.assert(account_out != null);
    
    const email = email_ptr[0..email_len];
    const password = password_ptr[0..password_len];
    const success = email_auth.create_user_account(email, password,
timestamp, account_out);
    
    std.debug.assert(email.len == email_len);
    std.debug.assert(password.len == password_len);
    
    return if (success) RESULT_OK else RESULT_ERROR;
}

// Export C-compatible user authentication function
export fn grain_mobile_authenticate_user(
    account: *const email_auth.UserAccount,
    email_ptr: [*c]const u8,
    email_len: u32,
    password_ptr: [*c]const u8,
    password_len: u32,
) c_int {
    std.debug.assert(account != null);
    std.debug.assert(email_ptr != null);
    std.debug.assert(email_len > 0);
    std.debug.assert(password_ptr != null);
    std.debug.assert(password_len > 0);
    
    const email = email_ptr[0..email_len];
    const password = password_ptr[0..password_len];
    const is_valid = email_auth.authenticate_user(account, email,
password);
    
    std.debug.assert(email.len == email_len);
    std.debug.assert(password.len == password_len);
    
    return if (is_valid) RESULT_OK else RESULT_ERROR;
}

// Export C-compatible session token generation function
export fn grain_mobile_generate_session_token(
    token_out: [*c]u8,
) c_int {
    std.debug.assert(token_out != null);
    
    const token = email_auth.generate_session_token();
    std.mem.copyForwards(u8, token_out[0..email_auth.SESSION_TOKEN_LEN],
&token);
    
    std.debug.assert(token.len == email_auth.SESSION_TOKEN_LEN);
    
    return RESULT_OK;
}

// Export C-compatible JWT creation function
export fn grain_mobile_create_jwt(
    user_id_ptr: [*c]const u8,
    user_id_len: u32,
    exp: u64,
    iat: u64,
    secret_ptr: [*c]const u8,
    secret_len: u32,
    token_out: [*c]u8,
    token_out_len: *u32,
) c_int {
    std.debug.assert(user_id_ptr != null);
    std.debug.assert(user_id_len > 0);
    std.debug.assert(user_id_len <= 64);
    std.debug.assert(exp > 0);
    std.debug.assert(secret_ptr != null);
    std.debug.assert(secret_len > 0);
    std.debug.assert(token_out != null);
    std.debug.assert(token_out_len != null);
    
    var claims: jwt.JwtClaims = undefined;
    std.mem.copyForwards(u8, &claims.user_id,
user_id_ptr[0..user_id_len]);
    claims.user_id_len = user_id_len;
    claims.exp = exp;
    claims.iat = iat;
    
    const secret = secret_ptr[0..secret_len];
    var token_buffer: [jwt.MAX_JWT_LEN]u8 = undefined;
    const token_len = jwt.create_jwt(&claims, secret, &token_buffer);
    
    std.mem.copyForwards(u8, token_out[0..token_len],
token_buffer[0..token_len]);
    token_out_len.* = token_len;
    
    std.debug.assert(token_len > 0);
    std.debug.assert(token_len <= jwt.MAX_JWT_LEN);
    
    return RESULT_OK;
}

// Export C-compatible JWT validation function
export fn grain_mobile_validate_jwt(
    token_ptr: [*c]const u8,
    token_len: u32,
    secret_ptr: [*c]const u8,
    secret_len: u32,
    current_time: u64,
    claims_out: *jwt.JwtClaims,
) c_int {
    std.debug.assert(token_ptr != null);
    std.debug.assert(token_len > 0);
    std.debug.assert(token_len <= jwt.MAX_JWT_LEN);
    std.debug.assert(secret_ptr != null);
    std.debug.assert(secret_len > 0);
    std.debug.assert(current_time > 0);
    std.debug.assert(claims_out != null);
    
    const token = token_ptr[0..token_len];
    const secret = secret_ptr[0..secret_len];
    const is_valid = jwt.validate_jwt(token, secret, current_time,
claims_out);
    
    std.debug.assert(token.len == token_len);
    
    return if (is_valid) RESULT_OK else RESULT_ERROR;
}


