// === grain_carry_core/style/breakpoints.zig ===

// Responsive breakpoints for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Defines breakpoints for responsive design
// Based on screen width in dp (Android) / points (iOS)

const std = @import("std");

pub const Breakpoint = enum(u8) {
    phone_small,   // < 360dp/375pt
    phone_medium,  // 360-414dp/375-414pt
    phone_large,   // 414-480dp/414-480pt
    tablet_small,  // 480-600dp/480-600pt
    tablet_large,  // 600-840dp/600-840pt
    desktop,       // > 840dp/840pt
};

pub const BREAKPOINT_PHONE_SMALL_MAX: u32 = 359;
pub const BREAKPOINT_PHONE_MEDIUM_MIN: u32 = 360;
pub const BREAKPOINT_PHONE_MEDIUM_MAX: u32 = 413;
pub const BREAKPOINT_PHONE_LARGE_MIN: u32 = 414;
pub const BREAKPOINT_PHONE_LARGE_MAX: u32 = 479;
pub const BREAKPOINT_TABLET_SMALL_MIN: u32 = 480;
pub const BREAKPOINT_TABLET_SMALL_MAX: u32 = 599;
pub const BREAKPOINT_TABLET_LARGE_MIN: u32 = 600;
pub const BREAKPOINT_TABLET_LARGE_MAX: u32 = 839;
pub const BREAKPOINT_DESKTOP_MIN: u32 = 840;

pub fn get_breakpoint(width_dp: u32, height_dp: u32) Breakpoint {
    std.debug.assert(width_dp > 0);
    std.debug.assert(width_dp <= 10000);
    std.debug.assert(height_dp > 0);
    std.debug.assert(height_dp <= 10000);
    
    // Use width for breakpoint determination (standard practice)
    if (width_dp < BREAKPOINT_PHONE_MEDIUM_MIN) {
        return .phone_small;
    } else if (width_dp <= BREAKPOINT_PHONE_MEDIUM_MAX) {
        return .phone_medium;
    } else if (width_dp <= BREAKPOINT_PHONE_LARGE_MAX) {
        return .phone_large;
    } else if (width_dp <= BREAKPOINT_TABLET_SMALL_MAX) {
        return .tablet_small;
    } else if (width_dp <= BREAKPOINT_TABLET_LARGE_MAX) {
        return .tablet_large;
    } else {
        return .desktop;
    }
}


// === grain_carry_core/style/colors.zig ===

// Color palettes for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Defines color palettes for light/dark themes
// Colors are RGBA (8-bit per channel)

const std = @import("std");

pub const Color = struct {
    r: u8,
    g: u8,
    b: u8,
    a: u8,

    pub fn init(r: u8, g: u8, b: u8, a: u8) Color {
        std.debug.assert(r <= 255);
        std.debug.assert(g <= 255);
        std.debug.assert(b <= 255);
        std.debug.assert(a <= 255);
        
        return Color{
            .r = r,
            .g = g,
            .b = b,
            .a = a,
        };
    }

    pub fn to_argb(self: Color) u32 {
        std.debug.assert(self.r <= 255);
        std.debug.assert(self.g <= 255);
        std.debug.assert(self.b <= 255);
        std.debug.assert(self.a <= 255);
        
        return (@as(u32, self.a) << 24) |
            (@as(u32, self.r) << 16) |
            (@as(u32, self.g) << 8) |
            @as(u32, self.b);
    }
};

pub const ColorPalette = struct {
    primary: Color,
    secondary: Color,
    background: Color,
    surface: Color,
    error: Color,
    on_primary: Color,
    on_secondary: Color,
    on_background: Color,
    on_surface: Color,
    on_error: Color,

    pub fn init_light() ColorPalette {
        return ColorPalette{
            .primary = Color.init(33, 150, 243, 255),
            .secondary = Color.init(156, 39, 176, 255),
            .background = Color.init(255, 255, 255, 255),
            .surface = Color.init(250, 250, 250, 255),
            .error = Color.init(211, 47, 47, 255),
            .on_primary = Color.init(255, 255, 255, 255),
            .on_secondary = Color.init(255, 255, 255, 255),
            .on_background = Color.init(0, 0, 0, 255),
            .on_surface = Color.init(0, 0, 0, 255),
            .on_error = Color.init(255, 255, 255, 255),
        };
    }

    pub fn init_dark() ColorPalette {
        return ColorPalette{
            .primary = Color.init(100, 181, 246, 255),
            .secondary = Color.init(186, 104, 200, 255),
            .background = Color.init(18, 18, 18, 255),
            .surface = Color.init(30, 30, 30, 255),
            .error = Color.init(239, 83, 80, 255),
            .on_primary = Color.init(0, 0, 0, 255),
            .on_secondary = Color.init(0, 0, 0, 255),
            .on_background = Color.init(255, 255, 255, 255),
            .on_surface = Color.init(255, 255, 255, 255),
            .on_error = Color.init(0, 0, 0, 255),
        };
    }
};


