// === grain_carry_core/validation/email.zig ===

// Email validation for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions

const std = @import("std");
const errors = @import("../utils/errors.zig");

pub const MAX_EMAIL_LEN: u32 = 256;
pub const MIN_EMAIL_LEN: u32 = 3;

pub fn validate_email(email: []const u8) bool {
    std.debug.assert(email.len > 0);
    
    if (email.len < MIN_EMAIL_LEN) {
        return false;
    }
    
    if (email.len > MAX_EMAIL_LEN) {
        return false;
    }
    
    std.debug.assert(email.len >= MIN_EMAIL_LEN);
    std.debug.assert(email.len <= MAX_EMAIL_LEN);
    
    const has_at = has_at_symbol(email);
    const has_dot_after_at = has_dot_after_at_symbol(email);
    const is_valid_format = has_at and has_dot_after_at;
    
    std.debug.assert(!is_valid_format or email.len >= MIN_EMAIL_LEN);
    std.debug.assert(!is_valid_format or email.len <= MAX_EMAIL_LEN);
    
    return is_valid_format;
}

fn has_at_symbol(email: []const u8) bool {
    std.debug.assert(email.len > 0);
    std.debug.assert(email.len <= MAX_EMAIL_LEN);
    
    var found: bool = false;
    var i: u32 = 0;
    while (i < email.len) : (i += 1) {
        if (email[i] == '@') {
            found = true;
            break;
        }
    }
    
    std.debug.assert(i <= email.len);
    return found;
}

fn has_dot_after_at_symbol(email: []const u8) bool {
    std.debug.assert(email.len > 0);
    std.debug.assert(email.len <= MAX_EMAIL_LEN);
    
    var at_index: ?u32 = null;
    var i: u32 = 0;
    while (i < email.len) : (i += 1) {
        if (email[i] == '@') {
            at_index = i;
            break;
        }
    }
    
    if (at_index == null) {
        return false;
    }
    
    const at_pos = at_index.?;
    std.debug.assert(at_pos < email.len);
    
    var j: u32 = at_pos + 1;
    while (j < email.len) : (j += 1) {
        if (email[j] == '.') {
            return true;
        }
    }
    
    std.debug.assert(j <= email.len);
    return false;
}


// === grain_carry_core/validation/password.zig ===

// Password validation for Grain Mobile Core
// Grain Style compliant: explicit types, bounded allocations, assertions
//
// Password Policy:
// - Minimum 32 characters required (security best practice)
// - Recommended: Use 1Password password manager with "Memorable
Password" option
// - 1Password strategy: Words + Numbers/Symbols as separators
// - Example: "aladdin!petition7inge1kalinda3TABLET" (words separated by
numbers/symbols)
// - Benefits: Easy to remember, type, and share while maintaining high
security

const std = @import("std");
const errors = @import("../utils/errors.zig");

// Password requirements aligned with 1Password memorable password
strategy
// Recommended: Use 1Password-style memorable passwords (words +
separators)
// Example: "aladdin!petition7inge1kalinda3TABLET" (32+ chars, words +
numbers/symbols)
pub const MAX_PASSWORD_LEN: u32 = 128;
pub const MIN_PASSWORD_LEN: u32 = 32;  // Require 32+ chars for security
pub const MIN_UPPERCASE: u32 = 1;
pub const MIN_LOWERCASE: u32 = 1;
pub const MIN_DIGITS: u32 = 1;
pub const MIN_SPECIAL: u32 = 1;

pub const PasswordStrength = enum(u8) {
    weak = 0,
    medium = 1,
    strong = 2,
};

pub fn validate_password(password: []const u8) bool {
    std.debug.assert(password.len > 0);
    
    if (password.len < MIN_PASSWORD_LEN) {
        return false;
    }
    
    if (password.len > MAX_PASSWORD_LEN) {
        return false;
    }
    
    std.debug.assert(password.len >= MIN_PASSWORD_LEN);
    std.debug.assert(password.len <= MAX_PASSWORD_LEN);
    
    const has_upper = count_uppercase(password) >= MIN_UPPERCASE;
    const has_lower = count_lowercase(password) >= MIN_LOWERCASE;
    const has_digit = count_digits(password) >= MIN_DIGITS;
    const has_special = count_special(password) >= MIN_SPECIAL;
    
    const is_valid = has_upper and has_lower and has_digit and
has_special;
    
    std.debug.assert(!is_valid or password.len >= MIN_PASSWORD_LEN);
    std.debug.assert(!is_valid or password.len <= MAX_PASSWORD_LEN);
    
    return is_valid;
}

// Password strength calculation favors longer passwords (32+ chars
recommended)
// 1Password-style memorable passwords (words + separators) score well
pub fn get_password_strength(password: []const u8) PasswordStrength {
    std.debug.assert(password.len > 0);
    std.debug.assert(password.len <= MAX_PASSWORD_LEN);
    
    const upper_count = count_uppercase(password);
    const lower_count = count_lowercase(password);
    const digit_count = count_digits(password);
    const special_count = count_special(password);
    
    const score = upper_count + lower_count + digit_count +
special_count;
    // Length bonus: 32+ chars (1Password recommendation) gets highest
bonus
    const length_bonus: u32 = if (password.len >= 32) 4 else if
(password.len >= 24) 3 else if (password.len >= 16) 2 else if
(password.len >= 12) 1 else 0;
    const total_score = score + length_bonus;
    
    std.debug.assert(total_score >= 0);
    
    // Adjusted thresholds for 32-char minimum requirement
    if (total_score < 6) {
        return .weak;
    } else if (total_score < 12) {
        return .medium;
    } else {
        return .strong;
    }
}

fn count_uppercase(password: []const u8) u32 {
    std.debug.assert(password.len > 0);
    std.debug.assert(password.len <= MAX_PASSWORD_LEN);
    
    var count: u32 = 0;
    var i: u32 = 0;
    while (i < password.len) : (i += 1) {
        if (password[i] >= 'A' and password[i] <= 'Z') {
            count += 1;
        }
    }
    
    std.debug.assert(count <= password.len);
    return count;
}

fn count_lowercase(password: []const u8) u32 {
    std.debug.assert(password.len > 0);
    std.debug.assert(password.len <= MAX_PASSWORD_LEN);
    
    var count: u32 = 0;
    var i: u32 = 0;
    while (i < password.len) : (i += 1) {
        if (password[i] >= 'a' and password[i] <= 'z') {
            count += 1;
        }
    }
    
    std.debug.assert(count <= password.len);
    return count;
}

fn count_digits(password: []const u8) u32 {
    std.debug.assert(password.len > 0);
    std.debug.assert(password.len <= MAX_PASSWORD_LEN);
    
    var count: u32 = 0;
    var i: u32 = 0;
    while (i < password.len) : (i += 1) {
        if (password[i] >= '0' and password[i] <= '9') {
            count += 1;
        }
    }
    
    std.debug.assert(count <= password.len);
    return count;
}

fn count_special(password: []const u8) u32 {
    std.debug.assert(password.len > 0);
    std.debug.assert(password.len <= MAX_PASSWORD_LEN);
    
    var count: u32 = 0;
    var i: u32 = 0;
    while (i < password.len) : (i += 1) {
        const c = password[i];
        const is_special = (c == '!' or c == '@' or c == '#' or c == '$'
or
            c == '%' or c == '^' or c == '&' or c == '*' or
            c == '(' or c == ')' or c == '-' or c == '_' or
            c == '+' or c == '=' or c == '[' or c == ']' or
            c == '{' or c == '}' or c == '|' or c == '\\' or
            c == ';' or c == ':' or c == '\'' or c == '"' or
            c == '<' or c == '>' or c == ',' or c == '.' or
            c == '?' or c == '/');
        if (is_special) {
            count += 1;
        }
    }
    
    std.debug.assert(count <= password.len);
    return count;
}


// === grain_carry_core/websocket/client.zig ===

//! Grain Carry Core WebSocket Client: WebSocket client for mobile apps.
//!
//! Why: Provide WebSocket client functionality for livestream
coordination.
//! Architecture: WebSocket client connection, frame sending/receiving,
message handling.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-06-033256-pst: Grain Carry Agent

const std = @import("std");
const grain_core_ws = @import("../../../grain_core/websocket.zig");
const grain_core_api = @import("../../../grain_core/api_server.zig");
const grain_core_network =
@import("../../../grain_core/network_stack.zig");

// Bounded: Max WebSocket client connections.
pub const MAX_CLIENT_CONNECTIONS: u32 = 16;

// Bounded: Max WebSocket client message size.
pub const MAX_CLIENT_MESSAGE_SIZE: u32 = grain_core_ws.MAX_MESSAGE_SIZE;

// WebSocket client connection state.
pub const ClientState = enum(u8) {
    disconnected,
    connecting,
    connected,
    closing,
    closed,
};

// WebSocket client connection.
pub const WebSocketClient = struct {
    connection_id: u32,
    state: ClientState,
    url: [256]u8,
    url_len: u32,
    socket_fd: u32,
    created_at: u64,
    last_activity: u64,
    active: bool,

    pub fn init(connection_id: u32) WebSocketClient {
        std.debug.assert(connection_id > 0);
        var client = WebSocketClient{
            .connection_id = connection_id,
            .state = ClientState.disconnected,
            .url = undefined,
            .url_len = 0,
            .socket_fd = 0,
            .created_at = 0,
            .last_activity = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < 256) : (i += 1) {
            client.url[i] = 0;
        }
        std.debug.assert(client.state == ClientState.disconnected);
        std.debug.assert(client.connection_id > 0);
        return client;
    }

    // Set URL for connection.
    pub fn set_url(self: *WebSocketClient, url: []const u8) bool {
        std.debug.assert(url.len > 0);
        std.debug.assert(url.len <= 256);
        if (url.len > 256) {
            return false;
        }
        std.mem.copyForwards(u8, &self.url, url);
        self.url_len = @intCast(url.len);
        std.debug.assert(self.url_len > 0);
        std.debug.assert(self.url_len <= 256);
        return true;
    }
};

// WebSocket client manager.
pub const WebSocketClientManager = struct {
    clients: [MAX_CLIENT_CONNECTIONS]WebSocketClient,
    clients_len: u32,
    next_connection_id: u32,

    pub fn init() WebSocketClientManager {
        var manager = WebSocketClientManager{
            .clients = undefined,
            .clients_len = 0,
            .next_connection_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_CLIENT_CONNECTIONS) : (i += 1) {
            manager.clients[i] = WebSocketClient.init(0);
        }
        std.debug.assert(manager.clients_len == 0);
        std.debug.assert(manager.next_connection_id == 1);
        return manager;
    }

    // Create new client connection.
    pub fn create_client(self: *WebSocketClientManager)
?*WebSocketClient {
        if (self.clients_len >= MAX_CLIENT_CONNECTIONS) {
            return null;
        }
        const conn_id = self.next_connection_id;
        self.next_connection_id += 1;
        self.clients[self.clients_len] = WebSocketClient.init(conn_id);
        self.clients[self.clients_len].active = true;
        const client = &self.clients[self.clients_len];
        self.clients_len += 1;
        std.debug.assert(client.connection_id > 0);
        std.debug.assert(client.state == ClientState.disconnected);
        return client;
    }

    // Find client by connection ID.
    pub fn find_client(
        self: *WebSocketClientManager,
        connection_id: u32,
    ) ?*WebSocketClient {
        std.debug.assert(connection_id > 0);
        var i: u32 = 0;
        while (i < self.clients_len) : (i += 1) {
            if (self.clients[i].connection_id == connection_id) {
                return &self.clients[i];
            }
        }
        return null;
    }

    // Remove client connection.
    pub fn remove_client(
        self: *WebSocketClientManager,
        connection_id: u32,
    ) bool {
        std.debug.assert(connection_id > 0);
        var i: u32 = 0;
        while (i < self.clients_len) : (i += 1) {
            if (self.clients[i].connection_id == connection_id) {
                self.clients[i].active = false;
                self.clients[i].state = ClientState.closed;
                var j: u32 = i;
                while (j < self.clients_len - 1) : (j += 1) {
                    self.clients[j] = self.clients[j + 1];
                }
                self.clients_len -= 1;
                return true;
            }
        }
        return false;
    }
};

// Generate WebSocket client key for handshake.
pub fn generate_client_key(key_buf: []u8) u32 {
    std.debug.assert(key_buf.len >= grain_core_ws.MAX_WEBSOCKET_KEY_LEN);
    var random_bytes: [16]u8 = undefined;
    std.crypto.random.bytes(&random_bytes);
    const base64_len = std.base64.standard.Encoder.calcSize(16);
    _ = std.base64.standard.Encoder.encode(key_buf, &random_bytes);
    std.debug.assert(base64_len <= grain_core_ws.MAX_WEBSOCKET_KEY_LEN);
    return @intCast(base64_len);
}

// Build WebSocket upgrade request.
pub fn build_upgrade_request(
    url: []const u8,
    client_key: []const u8,
    request_buf: []u8,
) u32 {
    std.debug.assert(url.len > 0);
    std.debug.assert(client_key.len > 0);
    std.debug.assert(request_buf.len >= 1024);
    var request_len: u32 = 0;
    const get_prefix = "GET ";
    std.mem.copyForwards(u8, request_buf[request_len..], get_prefix);
    request_len += @intCast(get_prefix.len);
    std.mem.copyForwards(u8, request_buf[request_len..], url);
    request_len += @intCast(url.len);
    const get_suffix = " HTTP/1.1\r\n";
    std.mem.copyForwards(u8, request_buf[request_len..], get_suffix);
    request_len += @intCast(get_suffix.len);
    const host_line = "Host: localhost\r\n";
    std.mem.copyForwards(u8, request_buf[request_len..], host_line);
    request_len += @intCast(host_line.len);
    const upgrade_line = "Upgrade: websocket\r\n";
    std.mem.copyForwards(u8, request_buf[request_len..], upgrade_line);
    request_len += @intCast(upgrade_line.len);
    const connection_line = "Connection: Upgrade\r\n";
    std.mem.copyForwards(u8, request_buf[request_len..],
connection_line);
    request_len += @intCast(connection_line.len);
    const key_header = "Sec-WebSocket-Key: ";
    std.mem.copyForwards(u8, request_buf[request_len..], key_header);
    request_len += @intCast(key_header.len);
    std.mem.copyForwards(u8, request_buf[request_len..], client_key);
    request_len += @intCast(client_key.len);
    const key_end = "\r\n";
    std.mem.copyForwards(u8, request_buf[request_len..], key_end);
    request_len += @intCast(key_end.len);
    const version_line = "Sec-WebSocket-Version: 13\r\n";
    std.mem.copyForwards(u8, request_buf[request_len..], version_line);
    request_len += @intCast(version_line.len);
    const end_line = "\r\n";
    std.mem.copyForwards(u8, request_buf[request_len..], end_line);
    request_len += @intCast(end_line.len);
    std.debug.assert(request_len <= request_buf.len);
    return request_len;
}

// Send text message via WebSocket.
pub fn send_text_message(
    client: *WebSocketClient,
    message: []const u8,
    frame_buf: []u8,
) u32 {
    std.debug.assert(client != null);
    std.debug.assert(message.len > 0);
    std.debug.assert(message.len <= MAX_CLIENT_MESSAGE_SIZE);
    std.debug.assert(frame_buf.len >= grain_core_ws.MAX_FRAME_SIZE + 14);
    if (client.state != ClientState.connected) {
        return 0;
    }
    var frame = grain_core_ws.WebSocketFrame.init();
    frame.flags.fin = true;
    frame.flags.opcode = grain_core_ws.FrameOpcode.text;
    frame.flags.masked = true;
    frame.flags.payload_len = message.len;
    std.crypto.random.bytes(&frame.flags.mask_key);
    std.mem.copyForwards(u8, &frame.payload, message);
    frame.payload_len = @intCast(message.len);
    const frame_len = grain_core_ws.generate_websocket_frame(&frame,
frame_buf);
    std.debug.assert(frame_len > 0);
    std.debug.assert(frame_len <= frame_buf.len);
    return frame_len;
}

// Send binary message via WebSocket.
pub fn send_binary_message(
    client: *WebSocketClient,
    message: []const u8,
    frame_buf: []u8,
) u32 {
    std.debug.assert(client != null);
    std.debug.assert(message.len > 0);
    std.debug.assert(message.len <= MAX_CLIENT_MESSAGE_SIZE);
    std.debug.assert(frame_buf.len >= grain_core_ws.MAX_FRAME_SIZE + 14);
    if (client.state != ClientState.connected) {
        return 0;
    }
    var frame = grain_core_ws.WebSocketFrame.init();
    frame.flags.fin = true;
    frame.flags.opcode = grain_core_ws.FrameOpcode.binary;
    frame.flags.masked = true;
    frame.flags.payload_len = message.len;
    std.crypto.random.bytes(&frame.flags.mask_key);
    std.mem.copyForwards(u8, &frame.payload, message);
    frame.payload_len = @intCast(message.len);
    const frame_len = grain_core_ws.generate_websocket_frame(&frame,
frame_buf);
    std.debug.assert(frame_len > 0);
    std.debug.assert(frame_len <= frame_buf.len);
    return frame_len;
}

// Parse received WebSocket frame.
pub fn parse_received_frame(
    buffer: []const u8,
    frame: *grain_core_ws.WebSocketFrame,
) bool {
    std.debug.assert(buffer.len > 0);
    std.debug.assert(frame != null);
    return grain_core_ws.parse_websocket_frame(buffer, frame);
}

// Handle received WebSocket frame (update client state).
pub fn handle_received_frame(
    client: *WebSocketClient,
    frame: *const grain_core_ws.WebSocketFrame,
) bool {
    std.debug.assert(client != null);
    std.debug.assert(frame != null);
    if (client.state != ClientState.connected) {
        return false;
    }
    const current_time: u64 = @intCast(std.time.timestamp());
    client.last_activity = current_time;
    std.debug.assert(client.last_activity > 0);
    return true;
}

// Send ping frame for keepalive.
pub fn send_ping(
    client: *WebSocketClient,
    frame_buf: []u8,
) u32 {
    std.debug.assert(client != null);
    std.debug.assert(frame_buf.len >= grain_core_ws.MAX_FRAME_SIZE + 14);
    if (client.state != ClientState.connected) {
        return 0;
    }
    var frame = grain_core_ws.WebSocketFrame.init();
    frame.flags.fin = true;
    frame.flags.opcode = grain_core_ws.FrameOpcode.ping;
    frame.flags.masked = true;
    frame.flags.payload_len = 0;
    std.crypto.random.bytes(&frame.flags.mask_key);
    frame.payload_len = 0;
    const frame_len = grain_core_ws.generate_websocket_frame(&frame,
frame_buf);
    std.debug.assert(frame_len > 0);
    std.debug.assert(frame_len <= frame_buf.len);
    return frame_len;
}

// Send pong frame in response to ping.
pub fn send_pong(
    client: *WebSocketClient,
    ping_payload: []const u8,
    frame_buf: []u8,
) u32 {
    std.debug.assert(client != null);
    std.debug.assert(frame_buf.len >= grain_core_ws.MAX_FRAME_SIZE + 14);
    if (client.state != ClientState.connected) {
        return 0;
    }
    var frame = grain_core_ws.WebSocketFrame.init();
    frame.flags.fin = true;
    frame.flags.opcode = grain_core_ws.FrameOpcode.pong;
    frame.flags.masked = true;
    const payload_len = if (ping_payload.len <=
grain_core_ws.MAX_FRAME_SIZE) ping_payload.len else
grain_core_ws.MAX_FRAME_SIZE;
    frame.flags.payload_len = payload_len;
    std.crypto.random.bytes(&frame.flags.mask_key);
    if (payload_len > 0) {
        std.mem.copyForwards(u8, &frame.payload,
ping_payload[0..payload_len]);
    }
    frame.payload_len = @intCast(payload_len);
    const frame_len = grain_core_ws.generate_websocket_frame(&frame,
frame_buf);
    std.debug.assert(frame_len > 0);
    std.debug.assert(frame_len <= frame_buf.len);
    return frame_len;
}

// Close WebSocket connection.
pub fn close_connection(
    client: *WebSocketClient,
    code: u16,
    reason: []const u8,
    frame_buf: []u8,
) u32 {
    std.debug.assert(client != null);
    std.debug.assert(frame_buf.len >= grain_core_ws.MAX_FRAME_SIZE + 14);
    if (client.state == ClientState.closed or client.state ==
ClientState.closing) {
        return 0;
    }
    client.state = ClientState.closing;
    var frame = grain_core_ws.WebSocketFrame.init();
    frame.flags.fin = true;
    frame.flags.opcode = grain_core_ws.FrameOpcode.close;
    frame.flags.masked = true;
    var payload_len: u32 = 2;
    frame.payload[0] = @as(u8, @truncate(code >> 8));
    frame.payload[1] = @as(u8, @truncate(code));
    const reason_len = if (reason.len <= grain_core_ws.MAX_FRAME_SIZE -
2) reason.len else grain_core_ws.MAX_FRAME_SIZE - 2;
    if (reason_len > 0) {
        std.mem.copyForwards(u8, frame.payload[2..],
reason[0..reason_len]);
        payload_len += reason_len;
    }
    frame.flags.payload_len = payload_len;
    std.crypto.random.bytes(&frame.flags.mask_key);
    frame.payload_len = payload_len;
    const frame_len = grain_core_ws.generate_websocket_frame(&frame,
frame_buf);
    std.debug.assert(frame_len > 0);
    std.debug.assert(frame_len <= frame_buf.len);
    return frame_len;
}

// Update client state to connected.
pub fn set_connected(client: *WebSocketClient) void {
    std.debug.assert(client != null);
    client.state = ClientState.connected;
    const current_time: u64 = @intCast(std.time.timestamp());
    client.created_at = current_time;
    client.last_activity = current_time;
    std.debug.assert(client.state == ClientState.connected);
    std.debug.assert(client.created_at > 0);
    std.debug.assert(client.last_activity > 0);
}

// Update client state to disconnected.
pub fn set_disconnected(client: *WebSocketClient) void {
    std.debug.assert(client != null);
    client.state = ClientState.disconnected;
    client.socket_fd = 0;
    std.debug.assert(client.state == ClientState.disconnected);
}

// Extract text message from received frame.
pub fn extract_text_message(
    frame: *const grain_core_ws.WebSocketFrame,
    message_out: []u8,
) u32 {
    std.debug.assert(frame != null);
    std.debug.assert(message_out.len >= MAX_CLIENT_MESSAGE_SIZE);
    if (frame.flags.opcode != grain_core_ws.FrameOpcode.text) {
        return 0;
    }
    if (frame.payload_len > MAX_CLIENT_MESSAGE_SIZE) {
        return 0;
    }
    const msg_len = if (frame.payload_len <= message_out.len)
frame.payload_len else message_out.len;
    std.mem.copyForwards(u8, message_out[0..msg_len],
frame.payload[0..frame.payload_len]);
    std.debug.assert(msg_len > 0);
    std.debug.assert(msg_len <= MAX_CLIENT_MESSAGE_SIZE);
    return msg_len;
}

// Extract binary message from received frame.
pub fn extract_binary_message(
    frame: *const grain_core_ws.WebSocketFrame,
    message_out: []u8,
) u32 {
    std.debug.assert(frame != null);
    std.debug.assert(message_out.len >= MAX_CLIENT_MESSAGE_SIZE);
    if (frame.flags.opcode != grain_core_ws.FrameOpcode.binary) {
        return 0;
    }
    if (frame.payload_len > MAX_CLIENT_MESSAGE_SIZE) {
        return 0;
    }
    const msg_len = if (frame.payload_len <= message_out.len)
frame.payload_len else message_out.len;
    std.mem.copyForwards(u8, message_out[0..msg_len],
frame.payload[0..frame.payload_len]);
    std.debug.assert(msg_len > 0);
    std.debug.assert(msg_len <= MAX_CLIENT_MESSAGE_SIZE);
    return msg_len;
}

// Parse port from URL string.
fn parse_port_from_url(url: []const u8, start_idx: u32, port_out: *u16,
path_start_out: *u32) bool {
    std.debug.assert(start_idx < url.len);
    std.debug.assert(port_out != null);
    std.debug.assert(path_start_out != null);
    var port_val: u32 = 0;
    var j: u32 = start_idx;
    var found_slash = false;
    while (j < url.len) : (j += 1) {
        const port_c = url[j];
        if (port_c == '/') {
            found_slash = true;
            path_start_out.* = j;
            break;
        }
        if (port_c < '0' or port_c > '9') {
            return false;
        }
        port_val = port_val * 10 + (port_c - '0');
        if (port_val > 65535) {
            return false;
        }
    }
    if (!found_slash) {
        path_start_out.* = url.len;
    }
    if (port_val == 0) {
        return false;
    }
    port_out.* = @intCast(port_val);
    std.debug.assert(port_out.* > 0);
    std.debug.assert(port_out.* <= 65535);
    return true;
}

// Extract host, port, and path from URL components.
fn extract_url_components(
    url: []const u8,
    url_offset: u32,
    host_out: []u8,
    port_out: *u16,
    path_out: []u8,
    host_end_out: *u32,
    path_start_out: *u32,
) bool {
    std.debug.assert(url_offset < url.len);
    std.debug.assert(host_out.len >= 256);
    std.debug.assert(path_out.len >= 256);
    std.debug.assert(port_out != null);
    std.debug.assert(host_end_out != null);
    std.debug.assert(path_start_out != null);
    var host_start = url_offset;
    var host_end: u32 = host_start;
    var port: u16 = 80;
    var path_start: u32 = url.len;
    var found_colon = false;
    var i: u32 = host_start;
    while (i < url.len) : (i += 1) {
        const c = url[i];
        if (c == ':') {
            if (found_colon) {
                return false;
            }
            found_colon = true;
            host_end = i;
            if (i + 1 >= url.len) {
                return false;
            }
            if (!parse_port_from_url(url, i + 1, &port, &path_start)) {
                return false;
            }
            break;
        } else if (c == '/') {
            host_end = i;
            path_start = i;
            break;
        }
    }
    if (!found_colon and path_start == url.len) {
        host_end = url.len;
    }
    const host_len = host_end - host_start;
    if (host_len == 0 or host_len > 255) {
        return false;
    }
    if (host_len > host_out.len) {
        return false;
    }
    std.mem.copyForwards(u8, host_out[0..host_len],
url[host_start..host_end]);
    const path_len = if (path_start < url.len) url.len - path_start else
0;
    if (path_len > 0) {
        if (path_len > path_out.len) {
            return false;
        }
        std.mem.copyForwards(u8, path_out[0..path_len],
url[path_start..]);
    } else {
        path_out[0] = '/';
    }
    port_out.* = port;
    host_end_out.* = host_end;
    path_start_out.* = path_start;
    std.debug.assert(host_len > 0);
    std.debug.assert(host_len <= 255);
    std.debug.assert(port > 0);
    std.debug.assert(port <= 65535);
    return true;
}

// Parse WebSocket URL (ws://host:port/path or wss://host:port/path).
pub fn parse_websocket_url(
    url: []const u8,
    host_out: []u8,
    port_out: *u16,
    path_out: []u8,
) bool {
    std.debug.assert(url.len > 0);
    std.debug.assert(host_out.len >= 256);
    std.debug.assert(path_out.len >= 256);
    std.debug.assert(port_out != null);
    if (url.len < 5) {
        return false;
    }
    const ws_prefix = "ws://";
    const wss_prefix = "wss://";
    var url_offset: u32 = 0;
    if (std.mem.startsWith(u8, url, ws_prefix)) {
        url_offset = 5;
    } else if (std.mem.startsWith(u8, url, wss_prefix)) {
        url_offset = 6;
    } else {
        return false;
    }
    if (url_offset >= url.len) {
        return false;
    }
    var host_end: u32 = 0;
    var path_start: u32 = 0;
    const success = extract_url_components(
        url,
        url_offset,
        host_out,
        port_out,
        path_out,
        &host_end,
        &path_start,
    );
    std.debug.assert(host_end > 0);
    return success;
}

// Parse HTTP response header to extract Sec-WebSocket-Accept.
pub fn parse_accept_header(
    response: []const u8,
    accept_out: []u8,
) bool {
    std.debug.assert(response.len > 0);
    std.debug.assert(accept_out.len >=
grain_core_ws.MAX_WEBSOCKET_ACCEPT_LEN);
    const accept_header = "Sec-WebSocket-Accept: ";
    var i: u32 = 0;
    while (i < response.len) : (i += 1) {
        if (i + accept_header.len > response.len) {
            break;
        }
        if (std.mem.eql(u8, response[i..i + accept_header.len],
accept_header)) {
            var accept_start = i + accept_header.len;
            var accept_end: u32 = accept_start;
            var j: u32 = accept_start;
            while (j < response.len) : (j += 1) {
                const c = response[j];
                if (c == '\r' or c == '\n') {
                    accept_end = j;
                    break;
                }
            }
            if (accept_end == accept_start) {
                return false;
            }
            const accept_len = accept_end - accept_start;
            if (accept_len > accept_out.len) {
                return false;
            }
            if (accept_len > grain_core_ws.MAX_WEBSOCKET_ACCEPT_LEN) {
                return false;
            }
            std.mem.copyForwards(u8, accept_out[0..accept_len],
response[accept_start..accept_end]);
            std.debug.assert(accept_len > 0);
            std.debug.assert(accept_len <=
grain_core_ws.MAX_WEBSOCKET_ACCEPT_LEN);
            return true;
        }
    }
    return false;
}

// Validate WebSocket accept key from server response.
pub fn validate_accept_key(
    client_key: []const u8,
    server_accept: []const u8,
) bool {
    std.debug.assert(client_key.len > 0);
    std.debug.assert(server_accept.len > 0);
    var expected_accept: [grain_core_ws.MAX_WEBSOCKET_ACCEPT_LEN]u8 =
undefined;
    const expected_len =
grain_core_ws.generate_websocket_accept(client_key, &expected_accept);
    if (expected_len != server_accept.len) {
        return false;
    }
    var i: u32 = 0;
    while (i < expected_len) : (i += 1) {
        if (expected_accept[i] != server_accept[i]) {
            return false;
        }
    }
    std.debug.assert(expected_len > 0);
    std.debug.assert(expected_len <=
grain_core_ws.MAX_WEBSOCKET_ACCEPT_LEN);
    return true;
}

// Check if HTTP response indicates successful WebSocket upgrade.
pub fn is_upgrade_successful(response: []const u8) bool {
    std.debug.assert(response.len > 0);
    const status_line = "HTTP/1.1 101";
    if (response.len < status_line.len) {
        return false;
    }
    var i: u32 = 0;
    while (i < status_line.len) : (i += 1) {
        if (response[i] != status_line[i]) {
            return false;
        }
    }
    std.debug.assert(response.len >= status_line.len);
    return true;
}


// === grain_carry_core/websocket/root.zig ===

// Grain Carry Core WebSocket module root
// Re-exports all WebSocket client components

pub const client = @import("client.zig");


// === grain_core/api_server.zig ===

//! Grain OS API Server: HTTP/REST API server for mobile and database
backends.
//!
//! Why: Provide REST API server for Grain Mobile Agent and Grain
Database Agent.
//! Architecture: HTTP/1.1 server, REST routing, JSON handling,
middleware.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");

// Bounded: Max routes.
pub const MAX_ROUTES: u32 = 128;

// Bounded: Max request size (64KB).
pub const MAX_REQUEST_SIZE: u32 = 65536;

// Bounded: Max response size (64KB).
pub const MAX_RESPONSE_SIZE: u32 = 65536;

// Bounded: Max headers per request.
pub const MAX_HEADERS: u32 = 32;

// Bounded: Max header name length.
pub const MAX_HEADER_NAME_LEN: u32 = 128;

// Bounded: Max header value length.
pub const MAX_HEADER_VALUE_LEN: u32 = 512;

// Bounded: Max path length.
pub const MAX_PATH_LEN: u32 = 2048;

// Bounded: Max query string length.
pub const MAX_QUERY_LEN: u32 = 2048;

// HTTP method.
pub const HttpMethod = enum(u8) {
    get,
    post,
    put,
    delete,
    patch,
    head,
    options,
};

// HTTP status code.
pub const HttpStatus = enum(u16) {
    ok = 200,
    created = 201,
    no_content = 204,
    bad_request = 400,
    unauthorized = 401,
    forbidden = 403,
    not_found = 404,
    conflict = 409,
    internal_server_error = 500,
    service_unavailable = 503,
};

// HTTP header.
pub const HttpHeader = struct {
    name: [MAX_HEADER_NAME_LEN]u8,
    name_len: u32,
    value: [MAX_HEADER_VALUE_LEN]u8,
    value_len: u32,

    pub fn init() HttpHeader {
        return HttpHeader{
            .name = undefined,
            .name_len = 0,
            .value = undefined,
            .value_len = 0,
        };
    }
};

// HTTP request.
pub const HttpRequest = struct {
    method: HttpMethod,
    path: [MAX_PATH_LEN]u8,
    path_len: u32,
    query: [MAX_QUERY_LEN]u8,
    query_len: u32,
    headers: [MAX_HEADERS]HttpHeader,
    headers_len: u32,
    body: [MAX_REQUEST_SIZE]u8,
    body_len: u32,

    pub fn init() HttpRequest {
        return HttpRequest{
            .method = HttpMethod.get,
            .path = undefined,
            .path_len = 0,
            .query = undefined,
            .query_len = 0,
            .headers = undefined,
            .headers_len = 0,
            .body = undefined,
            .body_len = 0,
        };
    }

    // Get header by name.
    pub fn get_header(self: *const HttpRequest, name: []const u8)
?[]const u8 {
        std.debug.assert(name.len > 0);
        var i: u32 = 0;
        while (i < self.headers_len) : (i += 1) {
            if (self.headers[i].name_len == name.len) {
                var match: bool = true;
                var j: u32 = 0;
                while (j < name.len) : (j += 1) {
                    if (self.headers[i].name[j] != name[j]) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    return
self.headers[i].value[0..self.headers[i].value_len];
                }
            }
        }
        return null;
    }

    // Add header.
    pub fn add_header(
        self: *HttpRequest,
        name: []const u8,
        value: []const u8,
    ) bool {
        std.debug.assert(name.len > 0);
        std.debug.assert(value.len > 0);
        if (self.headers_len >= MAX_HEADERS) {
            return false;
        }
        if (name.len > MAX_HEADER_NAME_LEN) {
            return false;
        }
        if (value.len > MAX_HEADER_VALUE_LEN) {
            return false;
        }
        var i: u32 = 0;
        while (i < MAX_HEADER_NAME_LEN) : (i += 1) {
            self.headers[self.headers_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_HEADER_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.headers[self.headers_len].name[i] = name[i];
        }
        self.headers[self.headers_len].name_len = @intCast(name_len);
        i = 0;
        while (i < MAX_HEADER_VALUE_LEN) : (i += 1) {
            self.headers[self.headers_len].value[i] = 0;
        }
        const value_len = @min(value.len, MAX_HEADER_VALUE_LEN);
        i = 0;
        while (i < value_len) : (i += 1) {
            self.headers[self.headers_len].value[i] = value[i];
        }
        self.headers[self.headers_len].value_len = @intCast(value_len);
        self.headers_len += 1;
        return true;
    }
};

// HTTP response.
pub const HttpResponse = struct {
    status: HttpStatus,
    headers: [MAX_HEADERS]HttpHeader,
    headers_len: u32,
    body: [MAX_RESPONSE_SIZE]u8,
    body_len: u32,

    pub fn init() HttpResponse {
        return HttpResponse{
            .status = HttpStatus.ok,
            .headers = undefined,
            .headers_len = 0,
            .body = undefined,
            .body_len = 0,
        };
    }

    // Add header.
    pub fn add_header(
        self: *HttpResponse,
        name: []const u8,
        value: []const u8,
    ) bool {
        std.debug.assert(name.len > 0);
        std.debug.assert(value.len > 0);
        if (self.headers_len >= MAX_HEADERS) {
            return false;
        }
        if (name.len > MAX_HEADER_NAME_LEN) {
            return false;
        }
        if (value.len > MAX_HEADER_VALUE_LEN) {
            return false;
        }
        var i: u32 = 0;
        while (i < MAX_HEADER_NAME_LEN) : (i += 1) {
            self.headers[self.headers_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_HEADER_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.headers[self.headers_len].name[i] = name[i];
        }
        self.headers[self.headers_len].name_len = @intCast(name_len);
        i = 0;
        while (i < MAX_HEADER_VALUE_LEN) : (i += 1) {
            self.headers[self.headers_len].value[i] = 0;
        }
        const value_len = @min(value.len, MAX_HEADER_VALUE_LEN);
        i = 0;
        while (i < value_len) : (i += 1) {
            self.headers[self.headers_len].value[i] = value[i];
        }
        self.headers[self.headers_len].value_len = @intCast(value_len);
        self.headers_len += 1;
        return true;
    }
};

// Route handler function type (runtime function pointer).
pub const RouteHandler = *const fn (*HttpRequest, *HttpResponse) void;

// Middleware function type (runtime function pointer).
pub const Middleware = *const fn (*HttpRequest, *HttpResponse) bool;

// Route: represents a registered route.
pub const Route = struct {
    method: HttpMethod,
    path_pattern: [MAX_PATH_LEN]u8,
    path_pattern_len: u32,
    handler: ?RouteHandler,
    middleware: [8]?Middleware,
    middleware_len: u32,
    active: bool,

    pub fn init() Route {
        return Route{
            .method = HttpMethod.get,
            .path_pattern = undefined,
            .path_pattern_len = 0,
            .handler = null,
            .middleware = undefined,
            .middleware_len = 0,
            .active = false,
        };
    }
};

// API server: manages HTTP server and routes.
pub const ApiServer = struct {
    routes: [MAX_ROUTES]Route,
    routes_len: u32,
    port: u16,
    running: bool,
    next_route_id: u32,
    server_process_id: u32,

    pub fn init(port: u16) ApiServer {
        std.debug.assert(port > 0);
        return ApiServer{
            .routes = undefined,
            .routes_len = 0,
            .port = port,
            .running = false,
            .next_route_id = 1,
            .server_process_id = 0,
        };
    }

    // Register route.
    pub fn register_route(
        self: *ApiServer,
        method: HttpMethod,
        path_pattern: []const u8,
        handler: RouteHandler,
    ) bool {
        std.debug.assert(path_pattern.len > 0);
        if (self.routes_len >= MAX_ROUTES) {
            return false;
        }
        if (path_pattern.len > MAX_PATH_LEN) {
            return false;
        }
        self.routes[self.routes_len] = Route.init();
        self.routes[self.routes_len].method = method;
        self.routes[self.routes_len].handler = handler;
        self.routes[self.routes_len].active = true;
        const pattern_len = @min(path_pattern.len, MAX_PATH_LEN);
        var i: u32 = 0;
        while (i < MAX_PATH_LEN) : (i += 1) {
            self.routes[self.routes_len].path_pattern[i] = 0;
        }
        i = 0;
        while (i < pattern_len) : (i += 1) {
            self.routes[self.routes_len].path_pattern[i] =
path_pattern[i];
        }
        self.routes[self.routes_len].path_pattern_len =
@intCast(pattern_len);
        self.routes_len += 1;
        return true;
    }

    // Add middleware to route.
    pub fn add_middleware_to_route(
        self: *ApiServer,
        method: HttpMethod,
        path_pattern: []const u8,
        middleware_fn: Middleware,
    ) bool {
        std.debug.assert(path_pattern.len > 0);
        if (self.find_route_by_pattern(method, path_pattern)) |route| {
            if (route.middleware_len >= 8) {
                return false;
            }
            route.middleware[route.middleware_len] = middleware_fn;
            route.middleware_len += 1;
            return true;
        }
        return false;
    }

    // Find route by method and path pattern.
    fn find_route_by_pattern(
        self: *ApiServer,
        method: HttpMethod,
        path_pattern: []const u8,
    ) ?*Route {
        std.debug.assert(path_pattern.len > 0);
        var i: u32 = 0;
        while (i < self.routes_len) : (i += 1) {
            if (self.routes[i].active and self.routes[i].method ==
method) {
                const route_pattern =
self.routes[i].path_pattern[0..self.routes[i].path_pattern_len];
                if (std.mem.eql(u8, route_pattern, path_pattern)) {
                    return &self.routes[i];
                }
            }
        }
        return null;
    }

    // Execute middleware chain for route.
    pub fn execute_middleware_chain(
        self: *const ApiServer,
        route: *const Route,
        request: *HttpRequest,
        response: *HttpResponse,
    ) bool {
        std.debug.assert(route.active);
        var i: u32 = 0;
        while (i < route.middleware_len) : (i += 1) {
            if (route.middleware[i]) |middleware_fn| {
                if (!middleware_fn(request, response)) {
                    return false;
                }
            }
        }
        return true;
    }

    // Find route by method and path.
    pub fn find_route(
        self: *const ApiServer,
        method: HttpMethod,
        path: []const u8,
    ) ?*const Route {
        std.debug.assert(path.len > 0);
        var i: u32 = 0;
        while (i < self.routes_len) : (i += 1) {
            if (self.routes[i].active and self.routes[i].method ==
method) {
                if (self.match_path_pattern(
                   
self.routes[i].path_pattern[0..self.routes[i].path_pattern_len],
                    path,
                )) {
                    return &self.routes[i];
                }
            }
        }
        return null;
    }

    // Match path pattern (simple exact match for now).
    fn match_path_pattern(
        _self: *const ApiServer,
        pattern: []const u8,
        path: []const u8,
    ) bool {
        _ = _self;
        std.debug.assert(pattern.len > 0);
        std.debug.assert(path.len > 0);
        if (pattern.len != path.len) {
            return false;
        }
        var i: u32 = 0;
        while (i < pattern.len) : (i += 1) {
            if (pattern[i] != path[i]) {
                return false;
            }
        }
        return true;
    }

    // Start server (stub for now, will use network integration).
    pub fn start(self: *ApiServer) bool {
        std.debug.assert(!self.running);
        if (self.routes_len == 0) {
            return false;
        }
        self.running = true;
        return true;
    }

    // Start server with network binding.
    pub fn start_with_network(
        self: *ApiServer,
        network_server: *@import("api_server_network.zig").NetworkServer,
    ) bool {
        std.debug.assert(!self.running);
        if (self.routes_len == 0) {
            return false;
        }
        if (network_server.bind_to_port() !=
@import("api_server_network.zig").BindResult.success) {
            return false;
        }
        if (!network_server.start_listening()) {
            return false;
        }
        self.running = true;
        return true;
    }

    // Register server process with process manager.
    pub fn register_server_process(
        self: *ApiServer,
        process_manager: *@import("process_manager.zig").ProcessManager,
        parent_process_id: u32,
        process_name: []const u8,
        cmd_line: []const u8,
        start_time: u64,
    ) ?u32 {
        std.debug.assert(process_name.len > 0);
        std.debug.assert(self.running);
        const process_id = process_manager.add_process(
            parent_process_id,
            process_name,
            cmd_line,
            start_time,
        );
        if (process_id) |pid| {
            self.server_process_id = pid;
            return pid;
        }
        return null;
    }

    // Get server process ID.
    pub fn get_server_process_id(self: *const ApiServer) ?u32 {
        if (self.server_process_id == 0) {
            return null;
        }
        return self.server_process_id;
    }

    // Update server process state.
    pub fn update_server_process_state(
        self: *ApiServer,
        process_manager: *@import("process_manager.zig").ProcessManager,
        state: @import("process_manager.zig").ProcessState,
    ) bool {
        std.debug.assert(self.running);
        if (self.server_process_id == 0) {
            return false;
        }
        return process_manager.set_process_state(self.server_process_id,
state);
    }

    // Stop server.
    pub fn stop(self: *ApiServer) void {
        self.running = false;
    }

    // Check if server is running.
    pub fn is_running(self: *const ApiServer) bool {
        return self.running;
    }

    // Get route count.
    pub fn get_route_count(self: *const ApiServer) u32 {
        return self.routes_len;
    }

    // Parse HTTP method from string.
    fn parse_http_method(method_str: []const u8) ?HttpMethod {
        std.debug.assert(method_str.len > 0);
        if (std.mem.eql(u8, method_str, "GET")) {
            return HttpMethod.get;
        } else if (std.mem.eql(u8, method_str, "POST")) {
            return HttpMethod.post;
        } else if (std.mem.eql(u8, method_str, "PUT")) {
            return HttpMethod.put;
        } else if (std.mem.eql(u8, method_str, "DELETE")) {
            return HttpMethod.delete;
        } else if (std.mem.eql(u8, method_str, "PATCH")) {
            return HttpMethod.patch;
        } else if (std.mem.eql(u8, method_str, "HEAD")) {
            return HttpMethod.head;
        } else if (std.mem.eql(u8, method_str, "OPTIONS")) {
            return HttpMethod.options;
        }
        return null;
    }

    // Find request line boundaries.
    fn find_request_line_boundaries(
        raw_request: []const u8,
        method_end: *u32,
        path_start: *u32,
        path_end: *u32,
        query_start: *u32,
    ) bool {
        std.debug.assert(raw_request.len > 0);
        method_end.* = 0;
        path_start.* = 0;
        path_end.* = 0;
        query_start.* = 0;
        var i: u32 = 0;
        while (i < raw_request.len) : (i += 1) {
            if (raw_request[i] == ' ' and method_end.* == 0) {
                method_end.* = i;
                path_start.* = i + 1;
            } else if (raw_request[i] == '?' and query_start.* == 0) {
                path_end.* = i;
                query_start.* = i + 1;
            } else if (raw_request[i] == ' ' and path_end.* == 0 and
query_start.* == 0) {
                path_end.* = i;
            } else if (raw_request[i] == '\r' and i + 1 <
raw_request.len and raw_request[i + 1] == '\n') {
                if (path_end.* == 0) {
                    path_end.* = i;
                }
                break;
            }
        }
        return method_end.* > 0 and path_start.* < raw_request.len;
    }

    // Find body start position.
    fn find_body_start(raw_request: []const u8) ?u32 {
        std.debug.assert(raw_request.len > 0);
        var i: u32 = 0;
        var header_end_count: u32 = 0;
        while (i < raw_request.len) : (i += 1) {
            if (raw_request[i] == '\r' and i + 1 < raw_request.len and
raw_request[i + 1] == '\n') {
                header_end_count += 1;
                if (header_end_count >= 2) {
                    return i + 2;
                }
                i += 1;
            }
        }
        return null;
    }

    // Parse HTTP request from raw bytes.
    pub fn parse_http_request(
        self: *ApiServer,
        raw_request: []const u8,
        request: *HttpRequest,
    ) bool {
        _ = self;
        std.debug.assert(raw_request.len > 0);
        if (raw_request.len > MAX_REQUEST_SIZE) {
            return false;
        }
        request.* = HttpRequest.init();
        var method_end: u32 = 0;
        var path_start: u32 = 0;
        var path_end: u32 = 0;
        var query_start: u32 = 0;
        if (!self.find_request_line_boundaries(
            raw_request,
            &method_end,
            &path_start,
            &path_end,
            &query_start,
        )) {
            return false;
        }
        const method_str = raw_request[0..method_end];
        const method_opt = self.parse_http_method(method_str);
        if (method_opt == null) {
            return false;
        }
        request.method = method_opt.?;
        const path_end_pos = if (path_end > 0) path_end else (if
(query_start > 0) query_start - 1 else raw_request.len);
        const path_len = @min(path_end_pos - path_start, MAX_PATH_LEN);
        var j: u32 = 0;
        while (j < path_len) : (j += 1) {
            request.path[j] = raw_request[path_start + j];
        }
        request.path_len = path_len;
        if (query_start > 0) {
            const query_end = if (path_end > query_start) path_end else
raw_request.len;
            const query_len = @min(query_end - query_start,
MAX_QUERY_LEN);
            j = 0;
            while (j < query_len) : (j += 1) {
                request.query[j] = raw_request[query_start + j];
            }
            request.query_len = query_len;
        }
        if (self.find_body_start(raw_request)) |body_start| {
            if (body_start < raw_request.len) {
                const body_len = @min(raw_request.len - body_start,
MAX_REQUEST_SIZE);
                j = 0;
                while (j < body_len) : (j += 1) {
                    request.body[j] = raw_request[body_start + j];
                }
                request.body_len = body_len;
            }
        }
        return true;
    }

    // Get HTTP status line string.
    fn get_status_line(status: HttpStatus) []const u8 {
        return switch (status) {
            HttpStatus.ok => "HTTP/1.1 200 OK\r\n",
            HttpStatus.created => "HTTP/1.1 201 Created\r\n",
            HttpStatus.no_content => "HTTP/1.1 204 No Content\r\n",
            HttpStatus.bad_request => "HTTP/1.1 400 Bad Request\r\n",
            HttpStatus.unauthorized => "HTTP/1.1 401 Unauthorized\r\n",
            HttpStatus.forbidden => "HTTP/1.1 403 Forbidden\r\n",
            HttpStatus.not_found => "HTTP/1.1 404 Not Found\r\n",
            HttpStatus.conflict => "HTTP/1.1 409 Conflict\r\n",
            HttpStatus.internal_server_error => "HTTP/1.1 500 Internal
Server Error\r\n",
            HttpStatus.service_unavailable => "HTTP/1.1 503 Service
Unavailable\r\n",
        };
    }

    // Write status line to output.
    fn write_status_line(
        status_line: []const u8,
        output: []u8,
        pos: *u32,
    ) bool {
        std.debug.assert(status_line.len > 0);
        std.debug.assert(output.len > 0);
        if (pos.* + status_line.len > output.len) {
            return false;
        }
        var i: u32 = 0;
        while (i < status_line.len) : (i += 1) {
            output[pos.*] = status_line[i];
            pos.* += 1;
        }
        return true;
    }

    // Write headers to output.
    fn write_headers(
        response: *const HttpResponse,
        output: []u8,
        pos: *u32,
    ) bool {
        std.debug.assert(output.len > 0);
        var i: u32 = 0;
        while (i < response.headers_len) : (i += 1) {
            const header_size = response.headers[i].name_len + 2 +
response.headers[i].value_len + 2;
            if (pos.* + header_size > output.len) {
                return false;
            }
            var j: u32 = 0;
            while (j < response.headers[i].name_len) : (j += 1) {
                output[pos.*] = response.headers[i].name[j];
                pos.* += 1;
            }
            output[pos.*] = ':';
            pos.* += 1;
            output[pos.*] = ' ';
            pos.* += 1;
            j = 0;
            while (j < response.headers[i].value_len) : (j += 1) {
                output[pos.*] = response.headers[i].value[j];
                pos.* += 1;
            }
            output[pos.*] = '\r';
            pos.* += 1;
            output[pos.*] = '\n';
            pos.* += 1;
        }
        return true;
    }

    // Write body to output.
    fn write_body(
        response: *const HttpResponse,
        output: []u8,
        pos: *u32,
    ) bool {
        std.debug.assert(output.len > 0);
        if (response.body_len > 0) {
            if (pos.* + response.body_len > output.len) {
                return false;
            }
            var i: u32 = 0;
            while (i < response.body_len) : (i += 1) {
                output[pos.*] = response.body[i];
                pos.* += 1;
            }
        }
        return true;
    }

    // Generate HTTP response from HttpResponse struct.
    pub fn generate_http_response(
        self: *const ApiServer,
        response: *const HttpResponse,
        output: []u8,
    ) ?u32 {
        _ = self;
        std.debug.assert(output.len > 0);
        var pos: u32 = 0;
        const status_line = self.get_status_line(response.status);
        if (!self.write_status_line(status_line, output, &pos)) {
            return null;
        }
        if (!self.write_headers(response, output, &pos)) {
            return null;
        }
        if (pos + 2 > output.len) {
            return null;
        }
        output[pos] = '\r';
        pos += 1;
        output[pos] = '\n';
        pos += 1;
        if (!self.write_body(response, output, &pos)) {
            return null;
        }
        return pos;
    }

    // Extract path parameters from path pattern.
    pub fn extract_path_parameters(
        self: *const ApiServer,
        pattern: []const u8,
        path: []const u8,
        params: []const []const u8,
    ) ?u32 {
        _ = self;
        std.debug.assert(pattern.len > 0);
        std.debug.assert(path.len > 0);
        var param_count: u32 = 0;
        var pattern_pos: u32 = 0;
        var path_pos: u32 = 0;
        var param_start: u32 = 0;
        var in_param: bool = false;
        while (pattern_pos < pattern.len and path_pos < path.len) :
(pattern_pos += 1) {
            if (pattern[pattern_pos] == '{') {
                in_param = true;
                param_start = path_pos;
            } else if (pattern[pattern_pos] == '}') {
                if (in_param and param_count < params.len) {
                    const param_end = path_pos;
                    if (param_end > param_start) {
                        params[param_count] =
path[param_start..param_end];
                        param_count += 1;
                    }
                }
                in_param = false;
            } else if (!in_param) {
                if (pattern[pattern_pos] != path[path_pos]) {
                    return null;
                }
                path_pos += 1;
            } else {
                path_pos += 1;
            }
        }
        if (pattern_pos < pattern.len or path_pos < path.len) {
            return null;
        }
        return param_count;
    }

    // Parse JSON request body (extract string value by key).
    pub fn parse_json_string_from_request(
        self: *const ApiServer,
        request: *const HttpRequest,
        key: []const u8,
        output: []u8,
    ) ?u32 {
        _ = self;
        std.debug.assert(key.len > 0);
        std.debug.assert(output.len > 0);
        if (request.body_len == 0) {
            return null;
        }
        const body = request.body[0..request.body_len];
        const json_helpers = @import("json_helpers.zig");
        if (json_helpers.find_json_key(body, key)) |result| {
            var result_mut = result;
            return json_helpers.extract_json_string_value(body,
&result_mut, output);
        }
        return null;
    }

    // Parse JSON request body (extract number value by key).
    pub fn parse_json_number_from_request(
        self: *const ApiServer,
        request: *const HttpRequest,
        key: []const u8,
    ) ?i64 {
        _ = self;
        std.debug.assert(key.len > 0);
        if (request.body_len == 0) {
            return null;
        }
        const body = request.body[0..request.body_len];
        const json_helpers = @import("json_helpers.zig");
        if (json_helpers.find_json_key(body, key)) |result| {
            var result_mut = result;
            return json_helpers.extract_json_number_value(body,
&result_mut);
        }
        return null;
    }

    // Parse JSON request body (extract boolean value by key).
    pub fn parse_json_bool_from_request(
        self: *const ApiServer,
        request: *const HttpRequest,
        key: []const u8,
    ) ?bool {
        _ = self;
        std.debug.assert(key.len > 0);
        if (request.body_len == 0) {
            return null;
        }
        const body = request.body[0..request.body_len];
        const json_helpers = @import("json_helpers.zig");
        if (json_helpers.find_json_key(body, key)) |result| {
            var result_mut = result;
            return json_helpers.extract_json_bool_value(body,
&result_mut);
        }
        return null;
    }

    // Generate JSON response body (write string key-value pair).
    pub fn write_json_string_to_response(
        self: *const ApiServer,
        response: *HttpResponse,
        key: []const u8,
        value: []const u8,
    ) bool {
        _ = self;
        std.debug.assert(key.len > 0);
        std.debug.assert(value.len > 0);
        if (response.body_len + key.len + value.len + 16 >
MAX_RESPONSE_SIZE) {
            return false;
        }
        const json_helpers = @import("json_helpers.zig");
        var pos: u32 = response.body_len;
        if (pos > 0) {
            response.body[pos] = ',';
            pos += 1;
        } else {
            response.body[pos] = '{';
            pos += 1;
        }
        if (!json_helpers.write_json_string(response.body, &pos, key)) {
            return false;
        }
        response.body[pos] = ':';
        pos += 1;
        if (!json_helpers.write_json_string(response.body, &pos, value))
{
            return false;
        }
        response.body_len = pos;
        return true;
    }

    // Generate JSON response body (write number key-value pair).
    pub fn write_json_number_to_response(
        self: *const ApiServer,
        response: *HttpResponse,
        key: []const u8,
        value: i64,
    ) bool {
        _ = self;
        std.debug.assert(key.len > 0);
        if (response.body_len + key.len + 32 > MAX_RESPONSE_SIZE) {
            return false;
        }
        const json_helpers = @import("json_helpers.zig");
        var pos: u32 = response.body_len;
        if (pos > 0) {
            response.body[pos] = ',';
            pos += 1;
        } else {
            response.body[pos] = '{';
            pos += 1;
        }
        if (!json_helpers.write_json_string(response.body, &pos, key)) {
            return false;
        }
        response.body[pos] = ':';
        pos += 1;
        if (!json_helpers.write_json_number(response.body, &pos, value))
{
            return false;
        }
        response.body_len = pos;
        return true;
    }

    // Generate JSON response body (write boolean key-value pair).
    pub fn write_json_bool_to_response(
        self: *const ApiServer,
        response: *HttpResponse,
        key: []const u8,
        value: bool,
    ) bool {
        _ = self;
        std.debug.assert(key.len > 0);
        if (response.body_len + key.len + 8 > MAX_RESPONSE_SIZE) {
            return false;
        }
        const json_helpers = @import("json_helpers.zig");
        var pos: u32 = response.body_len;
        if (pos > 0) {
            response.body[pos] = ',';
            pos += 1;
        } else {
            response.body[pos] = '{';
            pos += 1;
        }
        if (!json_helpers.write_json_string(response.body, &pos, key)) {
            return false;
        }
        response.body[pos] = ':';
        pos += 1;
        if (!json_helpers.write_json_bool(response.body, &pos, value)) {
            return false;
        }
        response.body_len = pos;
        return true;
    }

    // Finalize JSON response body (close object).
    pub fn finalize_json_response(
        self: *const ApiServer,
        response: *HttpResponse,
    ) bool {
        _ = self;
        if (response.body_len >= MAX_RESPONSE_SIZE) {
            return false;
        }
        response.body[response.body_len] = '}';
        response.body_len += 1;
        return true;
    }
};


// === grain_core/api_server_network.zig ===

//! Grain OS API Server Network Integration: Network binding and
connection handling.
//!
//! Why: Enable API server to accept actual HTTP connections from
network.
//! Architecture: Server binding, listening, connection acceptance,
request handling.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! Note: Currently uses std.net for network operations. Will migrate to
kernel
//! network syscalls when available (Phase 61: Network Stack
Enhancements).

const std = @import("std");
const api_server = @import("api_server.zig");
const connection_manager = @import("connection_manager.zig");

// Bounded: Max pending connections in listen queue.
pub const MAX_PENDING_CONNECTIONS: u32 = 128;

// Server binding result.
pub const BindResult = enum(u8) {
    success,
    port_in_use,
    network_error,
    invalid_port,
};

// Network server state.
pub const NetworkServerState = enum(u8) {
    stopped,
    binding,
    listening,
    accepting,
    error_state,
};

// Network server: manages HTTP server network operations.
pub const NetworkServer = struct {
    port: u16,
    state: NetworkServerState,
    bound: bool,
    listening: bool,

    pub fn init(port: u16) NetworkServer {
        std.debug.assert(port > 0);
        return NetworkServer{
            .port = port,
            .state = NetworkServerState.stopped,
            .bound = false,
            .listening = false,
        };
    }

    // Bind server to port (stub for now, will use kernel syscalls
later).
    pub fn bind_to_port(self: *NetworkServer) BindResult {
        std.debug.assert(self.port > 0);
        if (self.state != NetworkServerState.stopped) {
            return BindResult.network_error;
        }
        self.state = NetworkServerState.binding;
        self.bound = true;
        self.state = NetworkServerState.listening;
        self.listening = true;
        return BindResult.success;
    }

    // Start listening for connections (stub for now).
    pub fn start_listening(self: *NetworkServer) bool {
        std.debug.assert(self.port > 0);
        if (!self.bound) {
            return false;
        }
        if (self.state != NetworkServerState.listening) {
            return false;
        }
        self.state = NetworkServerState.accepting;
        return true;
    }

    // Stop listening.
    pub fn stop_listening(self: *NetworkServer) void {
        self.listening = false;
        self.bound = false;
        self.state = NetworkServerState.stopped;
    }

    // Check if server is listening.
    pub fn is_listening(self: *const NetworkServer) bool {
        return self.listening and self.state ==
NetworkServerState.accepting;
    }

    // Get server port.
    pub fn get_port(self: *const NetworkServer) u16 {
        return self.port;
    }

    // Get server state.
    pub fn get_state(self: *const NetworkServer) NetworkServerState {
        return self.state;
    }
};

// Process incoming HTTP request (stub for now).
pub fn process_http_request(
    server: *api_server.ApiServer,
    conn_mgr: *connection_manager.ConnectionManager,
    raw_request: []const u8,
    connection_idx: ?u32,
) ?api_server.HttpResponse {
    std.debug.assert(raw_request.len > 0);
    _ = conn_mgr;
    _ = connection_idx;
    var request = api_server.HttpRequest.init();
    if (!server.parse_http_request(raw_request, &request)) {
        return null;
    }
    if (server.find_route(request.method,
request.path[0..request.path_len])) |route| {
        var response = api_server.HttpResponse.init();
        if (!server.execute_middleware_chain(route, &request,
&response)) {
            return response;
        }
        if (route.handler) |handler_fn| {
            handler_fn(&request, &response);
        }
        return response;
    }
    var response = api_server.HttpResponse.init();
    response.status = api_server.HttpStatus.not_found;
    _ = response.add_header("Content-Type", "application/json");
    const error_body = "{\"error\":\"not_found\",\"message\":\"Route not
found\"}";
    const body_len = @min(error_body.len, api_server.MAX_RESPONSE_SIZE);
    var i: u32 = 0;
    while (i < body_len) : (i += 1) {
        response.body[i] = error_body[i];
    }
    response.body_len = @intCast(body_len);
    return response;
}


// === grain_core/app_launcher.zig ===

//! Grain OS Application Launcher: Quick application launcher and search.
//!
//! Why: Provide quick access to applications with search functionality.
//! Architecture: Application registry, search, favorites, recent apps.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const application = @import("application.zig");

// Bounded: Max applications in launcher.
pub const MAX_APPS: u32 = 256;

// Bounded: Max search results.
pub const MAX_SEARCH_RESULTS: u32 = 32;

// Bounded: Max favorites.
pub const MAX_FAVORITES: u32 = 16;

// Bounded: Max recent apps.
pub const MAX_RECENT_APPS: u32 = 16;

// Bounded: Max search query length.
pub const MAX_QUERY_LEN: u32 = 128;

// Launcher entry: represents an application in the launcher.
pub const LauncherEntry = struct {
    app_id: u32,
    name: [application.MAX_APP_NAME_LEN]u8,
    name_len: u32,
    icon_path: [application.MAX_APP_NAME_LEN]u8,
    icon_path_len: u32,
    favorite: bool,
    last_used: u64,
    use_count: u32,

    pub fn init() LauncherEntry {
        var entry = LauncherEntry{
            .app_id = 0,
            .name = undefined,
            .name_len = 0,
            .icon_path = undefined,
            .icon_path_len = 0,
            .favorite = false,
            .last_used = 0,
            .use_count = 0,
        };
        var i: u32 = 0;
        while (i < application.MAX_APP_NAME_LEN) : (i += 1) {
            entry.name[i] = 0;
            entry.icon_path[i] = 0;
        }
        return entry;
    }
};

// Application launcher: manages application launcher.
pub const ApplicationLauncher = struct {
    entries: [MAX_APPS]LauncherEntry,
    entries_len: u32,
    favorites: [MAX_FAVORITES]u32,
    favorites_len: u32,
    recent_apps: [MAX_RECENT_APPS]u32,
    recent_apps_len: u32,
    visible: bool,

    pub fn init() ApplicationLauncher {
        var launcher = ApplicationLauncher{
            .entries = undefined,
            .entries_len = 0,
            .favorites = undefined,
            .favorites_len = 0,
            .recent_apps = undefined,
            .recent_apps_len = 0,
            .visible = false,
        };
        var i: u32 = 0;
        while (i < MAX_APPS) : (i += 1) {
            launcher.entries[i] = LauncherEntry.init();
        }
        i = 0;
        while (i < MAX_FAVORITES) : (i += 1) {
            launcher.favorites[i] = 0;
        }
        i = 0;
        while (i < MAX_RECENT_APPS) : (i += 1) {
            launcher.recent_apps[i] = 0;
        }
        return launcher;
    }

    // Add application to launcher.
    pub fn add_app(
        self: *ApplicationLauncher,
        app_id: u32,
        name: []const u8,
        icon_path: []const u8,
    ) bool {
        if (self.entries_len >= MAX_APPS) {
            return false;
        }
        if (name.len > application.MAX_APP_NAME_LEN) {
            return false;
        }
        if (icon_path.len > application.MAX_APP_NAME_LEN) {
            return false;
        }
        // Check if app already exists.
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].app_id == app_id) {
                return false; // Already exists.
            }
        }
        // Add new entry.
        self.entries[self.entries_len] = LauncherEntry.init();
        self.entries[self.entries_len].app_id = app_id;
        var j: u32 = 0;
        while (j < application.MAX_APP_NAME_LEN) : (j += 1) {
            self.entries[self.entries_len].name[j] = 0;
            self.entries[self.entries_len].icon_path[j] = 0;
        }
        const name_len = @min(name.len, application.MAX_APP_NAME_LEN);
        j = 0;
        while (j < name_len) : (j += 1) {
            self.entries[self.entries_len].name[j] = name[j];
        }
        self.entries[self.entries_len].name_len = @intCast(name_len);
        const icon_len = @min(icon_path.len,
application.MAX_APP_NAME_LEN);
        j = 0;
        while (j < icon_len) : (j += 1) {
            self.entries[self.entries_len].icon_path[j] = icon_path[j];
        }
        self.entries[self.entries_len].icon_path_len =
@intCast(icon_len);
        self.entries_len += 1;
        return true;
    }

    // Find application by ID.
    pub fn find_app(
        self: *ApplicationLauncher,
        app_id: u32,
    ) ?*LauncherEntry {
        std.debug.assert(app_id > 0);
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].app_id == app_id) {
                return &self.entries[i];
            }
        }
        return null;
    }

    // Search applications.
    pub fn search_apps(
        self: *ApplicationLauncher,
        query: []const u8,
        results: []u32,
    ) u32 {
        std.debug.assert(query.len <= MAX_QUERY_LEN);
        if (query.len == 0) {
            return 0;
        }
        var result_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.entries_len and result_count < results.len) : (i
+= 1) {
            const entry = &self.entries[i];
            const name_slice = entry.name[0..entry.name_len];
            // Simple substring match (case-insensitive would be better).
            var match: bool = false;
            if (query.len <= name_slice.len) {
                var j: u32 = 0;
                while (j <= name_slice.len - query.len) : (j += 1) {
                    var k: u32 = 0;
                    match = true;
                    while (k < query.len) : (k += 1) {
                        if (name_slice[j + k] != query[k]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        break;
                    }
                }
            }
            if (match) {
                results[result_count] = entry.app_id;
                result_count += 1;
            }
        }
        return result_count;
    }

    // Add to favorites.
    pub fn add_favorite(self: *ApplicationLauncher, app_id: u32) bool {
        std.debug.assert(app_id > 0);
        if (self.favorites_len >= MAX_FAVORITES) {
            return false;
        }
        // Check if already favorite.
        var i: u32 = 0;
        while (i < self.favorites_len) : (i += 1) {
            if (self.favorites[i] == app_id) {
                return false; // Already favorite.
            }
        }
        // Add to favorites.
        self.favorites[self.favorites_len] = app_id;
        self.favorites_len += 1;
        // Mark entry as favorite.
        if (self.find_app(app_id)) |entry| {
            entry.favorite = true;
        }
        return true;
    }

    // Remove from favorites.
    pub fn remove_favorite(self: *ApplicationLauncher, app_id: u32) bool
{
        std.debug.assert(app_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.favorites_len) : (i += 1) {
            if (self.favorites[i] == app_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining favorites left.
        while (i < self.favorites_len - 1) : (i += 1) {
            self.favorites[i] = self.favorites[i + 1];
        }
        self.favorites_len -= 1;
        // Unmark entry as favorite.
        if (self.find_app(app_id)) |entry| {
            entry.favorite = false;
        }
        return true;
    }

    // Record app usage (adds to recent apps).
    pub fn record_app_usage(self: *ApplicationLauncher, app_id: u32)
void {
        std.debug.assert(app_id > 0);
        // Update use count and last used time.
        if (self.find_app(app_id)) |entry| {
            entry.use_count += 1;
            entry.last_used = 0; // Would use actual timestamp.
        }
        // Add to recent apps (remove if already present).
        var i: u32 = 0;
        while (i < self.recent_apps_len) : (i += 1) {
            if (self.recent_apps[i] == app_id) {
                // Move to front.
                var j: u32 = i;
                while (j > 0) : (j -= 1) {
                    self.recent_apps[j] = self.recent_apps[j - 1];
                }
                self.recent_apps[0] = app_id;
                return;
            }
        }
        // Add to front if not present.
        if (self.recent_apps_len < MAX_RECENT_APPS) {
            // Shift right.
            i = self.recent_apps_len;
            while (i > 0) : (i -= 1) {
                self.recent_apps[i] = self.recent_apps[i - 1];
            }
            self.recent_apps[0] = app_id;
            self.recent_apps_len += 1;
        } else {
            // Shift right and replace last.
            i = MAX_RECENT_APPS - 1;
            while (i > 0) : (i -= 1) {
                self.recent_apps[i] = self.recent_apps[i - 1];
            }
            self.recent_apps[0] = app_id;
        }
    }

    // Show launcher.
    pub fn show(self: *ApplicationLauncher) void {
        self.visible = true;
    }

    // Hide launcher.
    pub fn hide(self: *ApplicationLauncher) void {
        self.visible = false;
    }

    // Check if launcher is visible.
    pub fn is_visible(self: *const ApplicationLauncher) bool {
        return self.visible;
    }

    // Get app count.
    pub fn get_app_count(self: *const ApplicationLauncher) u32 {
        return self.entries_len;
    }

    // Get favorites count.
    pub fn get_favorites_count(self: *const ApplicationLauncher) u32 {
        return self.favorites_len;
    }

    // Get recent apps count.
    pub fn get_recent_apps_count(self: *const ApplicationLauncher) u32 {
        return self.recent_apps_len;
    }
};


// === grain_core/application.zig ===

//! Grain OS Application Framework: Application API and loader.
//!
//! Why: Provide application launching and management for desktop
environment.
//! Architecture: Application registry, loader, launcher integration.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const basin_kernel = @import("basin_kernel");

// Bounded: Max number of applications.
pub const MAX_APPLICATIONS: u32 = 256;

// Bounded: Max application name length.
pub const MAX_APP_NAME_LEN: u32 = 64;

// Bounded: Max application path length.
pub const MAX_APP_PATH_LEN: u32 = 256;

// Bounded: Max application command length.
pub const MAX_APP_CMD_LEN: u32 = 512;

// Application: represents a desktop application.
pub const Application = struct {
    id: u32,
    name: [MAX_APP_NAME_LEN]u8,
    name_len: u32,
    path: [MAX_APP_PATH_LEN]u8,
    path_len: u32,
    command: [MAX_APP_CMD_LEN]u8,
    command_len: u32,
    icon: u32, // Placeholder for icon ID.
    visible: bool,

    pub fn init(
        id: u32,
        name: []const u8,
        path: []const u8,
        command: []const u8,
    ) Application {
        std.debug.assert(id > 0);
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= MAX_APP_NAME_LEN);
        std.debug.assert(path.len > 0);
        std.debug.assert(path.len <= MAX_APP_PATH_LEN);
        std.debug.assert(command.len > 0);
        std.debug.assert(command.len <= MAX_APP_CMD_LEN);
        var app = Application{
            .id = id,
            .name = undefined,
            .name_len = 0,
            .path = undefined,
            .path_len = 0,
            .command = undefined,
            .command_len = 0,
            .icon = 0,
            .visible = true,
        };
        @memset(&app.name, 0);
        @memset(&app.path, 0);
        @memset(&app.command, 0);
        const name_copy_len = @min(name.len, MAX_APP_NAME_LEN);
        @memcpy(app.name[0..name_copy_len], name[0..name_copy_len]);
        app.name_len = @intCast(name_copy_len);
        const path_copy_len = @min(path.len, MAX_APP_PATH_LEN);
        @memcpy(app.path[0..path_copy_len], path[0..path_copy_len]);
        app.path_len = @intCast(path_copy_len);
        const cmd_copy_len = @min(command.len, MAX_APP_CMD_LEN);
        @memcpy(app.command[0..cmd_copy_len], command[0..cmd_copy_len]);
        app.command_len = @intCast(cmd_copy_len);
        std.debug.assert(app.id > 0);
        std.debug.assert(app.name_len > 0);
        return app;
    }
};

// Application registry: manages available applications.
pub const ApplicationRegistry = struct {
    applications: [MAX_APPLICATIONS]Application,
    applications_len: u32,
    next_app_id: u32,

    pub fn init() ApplicationRegistry {
        var registry = ApplicationRegistry{
            .applications = undefined,
            .applications_len = 0,
            .next_app_id = 1,
        };
        // Initialize all applications to zero.
        var i: u32 = 0;
        while (i < MAX_APPLICATIONS) : (i += 1) {
            registry.applications[i] = Application.init(0, "", "", "");
        }
        std.debug.assert(registry.applications_len == 0);
        std.debug.assert(registry.next_app_id > 0);
        return registry;
    }

    // Register application.
    pub fn register_application(
        self: *ApplicationRegistry,
        name: []const u8,
        path: []const u8,
        command: []const u8,
    ) ?u32 {
        std.debug.assert(name.len > 0);
        std.debug.assert(path.len > 0);
        std.debug.assert(command.len > 0);
        if (self.applications_len >= MAX_APPLICATIONS) return null;
        const app_id = self.next_app_id;
        self.next_app_id += 1;
        self.applications[self.applications_len] = Application.init(
            app_id,
            name,
            path,
            command,
        );
        self.applications_len += 1;
        std.debug.assert(self.applications_len <= MAX_APPLICATIONS);
        std.debug.assert(self.next_app_id > 0);
        return app_id;
    }

    // Get application by ID.
    pub fn get_application(self: *ApplicationRegistry, app_id: u32)
?*Application {
        std.debug.assert(app_id > 0);
        var i: u32 = 0;
        while (i < self.applications_len) : (i += 1) {
            if (self.applications[i].id == app_id) {
                return &self.applications[i];
            }
        }
        return null;
    }

    // Get application by name.
    pub fn get_application_by_name(
        self: *ApplicationRegistry,
        name: []const u8,
    ) ?*Application {
        std.debug.assert(name.len > 0);
        var i: u32 = 0;
        while (i < self.applications_len) : (i += 1) {
            const app = &self.applications[i];
            if (app.name_len == name.len) {
                var match: bool = true;
                var j: u32 = 0;
                while (j < name.len) : (j += 1) {
                    if (app.name[j] != name[j]) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    return app;
                }
            }
        }
        return null;
    }

    // Get all visible applications.
    pub fn get_visible_applications(
        self: *const ApplicationRegistry,
    ) struct { apps: []const Application, len: u32 } {
        var visible: [MAX_APPLICATIONS]Application = undefined;
        var visible_len: u32 = 0;
        var i: u32 = 0;
        while (i < self.applications_len and visible_len <
MAX_APPLICATIONS) : (i += 1) {
            if (self.applications[i].visible) {
                visible[visible_len] = self.applications[i];
                visible_len += 1;
            }
        }
        std.debug.assert(visible_len <= MAX_APPLICATIONS);
        return .{ .apps = visible[0..visible_len], .len = visible_len };
    }
};

// Application launcher: launches applications via kernel spawn.
pub const ApplicationLauncher = struct {
    registry: *ApplicationRegistry,
    syscall_fn: ?*const fn (u32, u64, u64, u64, u64) i64 = null,

    pub fn init(registry: *ApplicationRegistry) ApplicationLauncher {
        std.debug.assert(@intFromPtr(registry) != 0);
        return ApplicationLauncher{
            .registry = registry,
            .syscall_fn = null,
        };
    }

    // Set syscall function for spawning processes.
    pub fn set_syscall_fn(
        self: *ApplicationLauncher,
        fn_ptr: *const fn (u32, u64, u64, u64, u64) i64,
    ) void {
        std.debug.assert(@intFromPtr(fn_ptr) != 0);
        self.syscall_fn = fn_ptr;
        std.debug.assert(self.syscall_fn != null);
    }

    // Launch application by ID.
    pub fn launch_application(self: *ApplicationLauncher, app_id: u32)
bool {
        std.debug.assert(app_id > 0);
        std.debug.assert(self.syscall_fn != null);
        if (self.registry.get_application(app_id)) |app| {
            if (self.syscall_fn) |syscall_ptr| {
                // Spawn process using kernel spawn syscall.
                // Syscall: spawn = 1, args: path_ptr, path_len,
cmd_ptr, cmd_len
                const path_ptr = @intFromPtr(&app.path);
                const path_len: u64 = app.path_len;
                const cmd_ptr = @intFromPtr(&app.command);
                const cmd_len: u64 = app.command_len;
                const result = syscall_ptr(
                    @intFromEnum(basin_kernel.Syscall.spawn),
                    path_ptr,
                    path_len,
                    cmd_ptr,
                    cmd_len,
                );
                if (result >= 0) {
                    return true;
                }
            }
        }
        return false;
    }

    // Launch application by name.
    pub fn launch_application_by_name(
        self: *ApplicationLauncher,
        name: []const u8,
    ) bool {
        std.debug.assert(name.len > 0);
        if (self.registry.get_application_by_name(name)) |app| {
            return self.launch_application(app.id);
        }
        return false;
    }
};


// === grain_core/audio_manager.zig ===

//! Grain OS Audio Manager: Audio device and volume management.
//!
//! Why: Provide audio management for device selection and volume
control.
//! Architecture: Audio device management, volume control, mute state.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max audio devices.
pub const MAX_AUDIO_DEVICES: u32 = 16;

// Bounded: Max device name length.
pub const MAX_DEVICE_NAME_LEN: u32 = 128;

// Audio device type.
pub const AudioDeviceType = enum(u8) {
    unknown,
    speaker,
    headphone,
    microphone,
    bluetooth,
    usb,
};

// Audio device state.
pub const AudioDeviceState = enum(u8) {
    disconnected,
    connected,
    active,
    disabled,
};

// Audio device: represents an audio device.
pub const AudioDevice = struct {
    device_id: u32,
    name: [MAX_DEVICE_NAME_LEN]u8,
    name_len: u32,
    device_type: AudioDeviceType,
    state: AudioDeviceState,
    volume: u32, // 0-100 percentage.
    muted: bool,
    active: bool,

    pub fn init() AudioDevice {
        var device = AudioDevice{
            .device_id = 0,
            .name = undefined,
            .name_len = 0,
            .device_type = AudioDeviceType.unknown,
            .state = AudioDeviceState.disconnected,
            .volume = 50,
            .muted = false,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_DEVICE_NAME_LEN) : (i += 1) {
            device.name[i] = 0;
        }
        return device;
    }
};

// Audio manager: manages audio devices and volume.
pub const AudioManager = struct {
    devices: [MAX_AUDIO_DEVICES]AudioDevice,
    devices_len: u32,
    next_device_id: u32,
    master_volume: u32, // 0-100 percentage.
    master_muted: bool,
    active_output_device_id: u32,
    active_input_device_id: u32,

    pub fn init() AudioManager {
        var manager = AudioManager{
            .devices = undefined,
            .devices_len = 0,
            .next_device_id = 1,
            .master_volume = 50,
            .master_muted = false,
            .active_output_device_id = 0,
            .active_input_device_id = 0,
        };
        var i: u32 = 0;
        while (i < MAX_AUDIO_DEVICES) : (i += 1) {
            manager.devices[i] = AudioDevice.init();
        }
        return manager;
    }

    // Add audio device.
    pub fn add_device(
        self: *AudioManager,
        name: []const u8,
        device_type: AudioDeviceType,
    ) ?u32 {
        if (self.devices_len >= MAX_AUDIO_DEVICES) {
            return null;
        }
        if (name.len > MAX_DEVICE_NAME_LEN) {
            return null;
        }
        const device_id = self.next_device_id;
        self.next_device_id += 1;
        self.devices[self.devices_len] = AudioDevice.init();
        self.devices[self.devices_len].device_id = device_id;
        self.devices[self.devices_len].device_type = device_type;
        self.devices[self.devices_len].state =
AudioDeviceState.connected;
        self.devices[self.devices_len].active = true;
        var i: u32 = 0;
        while (i < MAX_DEVICE_NAME_LEN) : (i += 1) {
            self.devices[self.devices_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_DEVICE_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.devices[self.devices_len].name[i] = name[i];
        }
        self.devices[self.devices_len].name_len = @intCast(name_len);
        if (self.active_output_device_id == 0 and device_type ==
AudioDeviceType.speaker) {
            self.active_output_device_id = device_id;
        }
        if (self.active_input_device_id == 0 and device_type ==
AudioDeviceType.microphone) {
            self.active_input_device_id = device_id;
        }
        self.devices_len += 1;
        return device_id;
    }

    // Find device by ID.
    pub fn find_device(
        self: *AudioManager,
        device_id: u32,
    ) ?*AudioDevice {
        std.debug.assert(device_id > 0);
        var i: u32 = 0;
        while (i < self.devices_len) : (i += 1) {
            if (self.devices[i].device_id == device_id and
self.devices[i].active) {
                return &self.devices[i];
            }
        }
        return null;
    }

    // Set device volume.
    pub fn set_device_volume(self: *AudioManager, device_id: u32,
volume: u32) bool {
        std.debug.assert(device_id > 0);
        std.debug.assert(volume <= 100);
        if (self.find_device(device_id)) |device| {
            device.volume = volume;
            return true;
        }
        return false;
    }

    // Get device volume.
    pub fn get_device_volume(self: *AudioManager, device_id: u32) ?u32 {
        std.debug.assert(device_id > 0);
        if (self.find_device(device_id)) |device| {
            return device.volume;
        }
        return null;
    }

    // Mute device.
    pub fn mute_device(self: *AudioManager, device_id: u32) bool {
        std.debug.assert(device_id > 0);
        if (self.find_device(device_id)) |device| {
            device.muted = true;
            return true;
        }
        return false;
    }

    // Unmute device.
    pub fn unmute_device(self: *AudioManager, device_id: u32) bool {
        std.debug.assert(device_id > 0);
        if (self.find_device(device_id)) |device| {
            device.muted = false;
            return true;
        }
        return false;
    }

    // Set active output device.
    pub fn set_active_output_device(self: *AudioManager, device_id: u32)
bool {
        std.debug.assert(device_id > 0);
        if (self.find_device(device_id)) |device| {
            if (device.device_type == AudioDeviceType.speaker or
device.device_type == AudioDeviceType.headphone) {
                self.active_output_device_id = device_id;
                return true;
            }
        }
        return false;
    }

    // Set active input device.
    pub fn set_active_input_device(self: *AudioManager, device_id: u32)
bool {
        std.debug.assert(device_id > 0);
        if (self.find_device(device_id)) |device| {
            if (device.device_type == AudioDeviceType.microphone) {
                self.active_input_device_id = device_id;
                return true;
            }
        }
        return false;
    }

    // Get active output device.
    pub fn get_active_output_device(self: *const AudioManager) ?*const
AudioDevice {
        if (self.active_output_device_id == 0) {
            return null;
        }
        var i: u32 = 0;
        while (i < self.devices_len) : (i += 1) {
            if (self.devices[i].device_id ==
self.active_output_device_id) {
                return &self.devices[i];
            }
        }
        return null;
    }

    // Get active input device.
    pub fn get_active_input_device(self: *const AudioManager) ?*const
AudioDevice {
        if (self.active_input_device_id == 0) {
            return null;
        }
        var i: u32 = 0;
        while (i < self.devices_len) : (i += 1) {
            if (self.devices[i].device_id ==
self.active_input_device_id) {
                return &self.devices[i];
            }
        }
        return null;
    }

    // Set master volume.
    pub fn set_master_volume(self: *AudioManager, volume: u32) void {
        std.debug.assert(volume <= 100);
        self.master_volume = volume;
    }

    // Get master volume.
    pub fn get_master_volume(self: *const AudioManager) u32 {
        return self.master_volume;
    }

    // Mute master.
    pub fn mute_master(self: *AudioManager) void {
        self.master_muted = true;
    }

    // Unmute master.
    pub fn unmute_master(self: *AudioManager) void {
        self.master_muted = false;
    }

    // Check if master is muted.
    pub fn is_master_muted(self: *const AudioManager) bool {
        return self.master_muted;
    }

    // Remove device.
    pub fn remove_device(self: *AudioManager, device_id: u32) bool {
        std.debug.assert(device_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.devices_len) : (i += 1) {
            if (self.devices[i].device_id == device_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        if (self.active_output_device_id == device_id) {
            self.active_output_device_id = 0;
        }
        if (self.active_input_device_id == device_id) {
            self.active_input_device_id = 0;
        }
        // Shift remaining devices left.
        while (i < self.devices_len - 1) : (i += 1) {
            self.devices[i] = self.devices[i + 1];
        }
        self.devices_len -= 1;
        return true;
    }

    // Get device count.
    pub fn get_device_count(self: *const AudioManager) u32 {
        return self.devices_len;
    }
};


// === grain_core/auth_service.zig ===

//! Grain OS Authentication Service: Secure authentication for API
endpoints.
//!
//! Why: Provide JWT tokens, password hashing, 2FA, OAuth, sessions for
Mobile/Database agents.
//! Architecture: Centralized auth service with JWT, password, 2FA,
OAuth, session management.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines, max 100 chars.

const std = @import("std");
const api_server = @import("api_server.zig");

// Constants
pub const MAX_JWT_LEN: u32 = 2048;
pub const MAX_SECRET_LEN: u32 = 256;
pub const MAX_USER_ID_LEN: u32 = 64;
pub const MAX_SESSION_ID_LEN: u32 = 64;
pub const MAX_OTP_CODE_LEN: u32 = 8;
pub const MAX_EMAIL_LEN: u32 = 256;
pub const MAX_PASSWORD_LEN: u32 = 128;
pub const SALT_LEN: u32 = 32;
pub const HASH_LEN: u32 = 32; // SHA-256
pub const HASH_OUTPUT_LEN: u32 = SALT_LEN + HASH_LEN;
pub const ACCESS_TOKEN_EXPIRY: u64 = 3600; // 1 hour
pub const REFRESH_TOKEN_EXPIRY: u64 = 604800; // 7 days
pub const OTP_EXPIRY: u64 = 600; // 10 minutes
pub const SESSION_EXPIRY: u64 = 86400; // 24 hours

// JWT Claims structure
pub const JwtClaims = struct {
    user_id: [MAX_USER_ID_LEN]u8,
    user_id_len: u32,
    exp: u64, // Expiration timestamp
    iat: u64, // Issued at timestamp
    token_type: TokenType,
};

// Token types
pub const TokenType = enum(u8) {
    access,
    refresh,
};

// Session structure
pub const Session = struct {
    session_id: [MAX_SESSION_ID_LEN]u8,
    session_id_len: u32,
    user_id: [MAX_USER_ID_LEN]u8,
    user_id_len: u32,
    created_at: u64,
    expires_at: u64,
    is_active: bool,
};

// OTP structure
pub const Otp = struct {
    code: [MAX_OTP_CODE_LEN]u8,
    code_len: u32,
    email: [MAX_EMAIL_LEN]u8,
    email_len: u32,
    created_at: u64,
    expires_at: u64,
    is_used: bool,
};

// OAuth provider types
pub const OAuthProvider = enum(u8) {
    google,
    facebook,
    github,
    apple,
};

// Authentication Service
pub const AuthService = struct {
    secret: [MAX_SECRET_LEN]u8,
    secret_len: u32,
    sessions: [100]Session, // Bounded session storage
    session_count: u32,
    otps: [50]Otp, // Bounded OTP storage
    otp_count: u32,
    revoked_tokens: [200][MAX_JWT_LEN]u8, // Token blacklist
    revoked_count: u32,

    // Initialize authentication service with secret
    pub fn init(secret: []const u8) AuthService {
        std.debug.assert(secret.len > 0);
        std.debug.assert(secret.len <= MAX_SECRET_LEN);
        var service = AuthService{
            .secret = undefined,
            .secret_len = @intCast(secret.len),
            .sessions = undefined,
            .session_count = 0,
            .otps = undefined,
            .otp_count = 0,
            .revoked_tokens = undefined,
            .revoked_count = 0,
        };
        std.mem.copyForwards(u8, &service.secret, secret);
        std.mem.set(u8, &service.sessions, 0);
        std.mem.set(u8, &service.otps, 0);
        std.mem.set(u8, &service.revoked_tokens, 0);
        std.debug.assert(service.secret_len > 0);
        return service;
    }

    // Generate JWT access token
    pub fn generate_access_token(
        self: *AuthService,
        user_id: []const u8,
        current_time: u64,
        token_out: []u8,
    ) u32 {
        std.debug.assert(user_id.len > 0);
        std.debug.assert(user_id.len <= MAX_USER_ID_LEN);
        std.debug.assert(current_time > 0);
        std.debug.assert(token_out.len >= MAX_JWT_LEN);
        var claims = JwtClaims{
            .user_id = undefined,
            .user_id_len = @intCast(user_id.len),
            .exp = current_time + ACCESS_TOKEN_EXPIRY,
            .iat = current_time,
            .token_type = TokenType.access,
        };
        std.mem.copyForwards(u8, &claims.user_id, user_id);
        const token_len = generate_jwt_token(
            &claims,
            self.secret[0..self.secret_len],
            token_out,
        );
        std.debug.assert(token_len > 0);
        std.debug.assert(token_len <= MAX_JWT_LEN);
        return token_len;
    }

    // Generate JWT refresh token
    pub fn generate_refresh_token(
        self: *AuthService,
        user_id: []const u8,
        current_time: u64,
        token_out: []u8,
    ) u32 {
        std.debug.assert(user_id.len > 0);
        std.debug.assert(user_id.len <= MAX_USER_ID_LEN);
        std.debug.assert(current_time > 0);
        std.debug.assert(token_out.len >= MAX_JWT_LEN);
        var claims = JwtClaims{
            .user_id = undefined,
            .user_id_len = @intCast(user_id.len),
            .exp = current_time + REFRESH_TOKEN_EXPIRY,
            .iat = current_time,
            .token_type = TokenType.refresh,
        };
        std.mem.copyForwards(u8, &claims.user_id, user_id);
        const token_len = generate_jwt_token(
            &claims,
            self.secret[0..self.secret_len],
            token_out,
        );
        std.debug.assert(token_len > 0);
        std.debug.assert(token_len <= MAX_JWT_LEN);
        return token_len;
    }

    // Validate JWT token
    pub fn validate_jwt_token(
        self: *AuthService,
        token: []const u8,
        current_time: u64,
        claims_out: *JwtClaims,
    ) bool {
        std.debug.assert(token.len > 0);
        std.debug.assert(token.len <= MAX_JWT_LEN);
        std.debug.assert(current_time > 0);
        std.debug.assert(claims_out != null);
        if (is_token_revoked(self, token)) {
            return false;
        }
        const is_valid = validate_jwt(
            token,
            self.secret[0..self.secret_len],
            current_time,
            claims_out,
        );
        if (!is_valid) {
            return false;
        }
        if (claims_out.exp < current_time) {
            return false;
        }
        std.debug.assert(claims_out.user_id_len > 0);
        return true;
    }

    // Revoke JWT token (add to blacklist)
    pub fn revoke_token(self: *AuthService, token: []const u8) bool {
        std.debug.assert(token.len > 0);
        std.debug.assert(token.len <= MAX_JWT_LEN);
        if (self.revoked_count >= 200) {
            return false;
        }
        if (token.len > MAX_JWT_LEN) {
            return false;
        }
        std.mem.copyForwards(
            u8,
            &self.revoked_tokens[self.revoked_count],
            token,
        );
        self.revoked_count += 1;
        std.debug.assert(self.revoked_count <= 200);
        return true;
    }

    // Check if token is revoked
    fn is_token_revoked(self: *const AuthService, token: []const u8)
bool {
        std.debug.assert(token.len > 0);
        std.debug.assert(token.len <= MAX_JWT_LEN);
        var i: u32 = 0;
        while (i < self.revoked_count) : (i += 1) {
            const revoked_token = self.revoked_tokens[i][0..token.len];
            if (std.mem.eql(u8, revoked_token, token)) {
                return true;
            }
        }
        return false;
    }

    // Hash password (SHA-256 with salt) - static function
    pub fn hash_password_static(
        password: []const u8,
        hash_out: []u8,
    ) void {
        std.debug.assert(password.len > 0);
        std.debug.assert(password.len <= MAX_PASSWORD_LEN);
        std.debug.assert(hash_out.len >= HASH_OUTPUT_LEN);
        var salt: [SALT_LEN]u8 = undefined;
        std.crypto.random.bytes(&salt);
        var combined: [MAX_PASSWORD_LEN + SALT_LEN]u8 = undefined;
        std.mem.copyForwards(u8, combined[0..password.len], password);
        std.mem.copyForwards(u8, combined[password.len..password.len +
SALT_LEN], &salt);
        var hash: [HASH_LEN]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(combined[0..password.len +
SALT_LEN], &hash, .{});
        std.mem.copyForwards(u8, hash_out[0..SALT_LEN], &salt);
        std.mem.copyForwards(u8, hash_out[SALT_LEN..SALT_LEN +
HASH_LEN], &hash);
        std.debug.assert(hash_out.len >= HASH_OUTPUT_LEN);
    }

    // Verify password - static function
    pub fn verify_password_static(
        password: []const u8,
        stored_hash: []const u8,
    ) bool {
        std.debug.assert(password.len > 0);
        std.debug.assert(password.len <= MAX_PASSWORD_LEN);
        std.debug.assert(stored_hash.len >= HASH_OUTPUT_LEN);
        const salt = stored_hash[0..SALT_LEN];
        const stored_hash_only = stored_hash[SALT_LEN..SALT_LEN +
HASH_LEN];
        var combined: [MAX_PASSWORD_LEN + SALT_LEN]u8 = undefined;
        std.mem.copyForwards(u8, combined[0..password.len], password);
        std.mem.copyForwards(u8, combined[password.len..password.len +
SALT_LEN], salt);
        var computed_hash: [HASH_LEN]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(combined[0..password.len +
SALT_LEN], &computed_hash, .{});
        const matches = std.mem.eql(u8, &computed_hash,
stored_hash_only);
        std.debug.assert(password.len > 0);
        std.debug.assert(stored_hash.len >= HASH_OUTPUT_LEN);
        return matches;
    }

    // Create session
    pub fn create_session(
        self: *AuthService,
        user_id: []const u8,
        current_time: u64,
        session_out: *Session,
    ) bool {
        std.debug.assert(user_id.len > 0);
        std.debug.assert(user_id.len <= MAX_USER_ID_LEN);
        std.debug.assert(current_time > 0);
        std.debug.assert(session_out != null);
        if (self.session_count >= 100) {
            return false;
        }
        var session_id: [MAX_SESSION_ID_LEN]u8 = undefined;
        std.crypto.random.bytes(&session_id);
        std.mem.copyForwards(u8, &session_out.session_id, &session_id);
        session_out.session_id_len = MAX_SESSION_ID_LEN;
        std.mem.copyForwards(u8, &session_out.user_id, user_id);
        session_out.user_id_len = @intCast(user_id.len);
        session_out.created_at = current_time;
        session_out.expires_at = current_time + SESSION_EXPIRY;
        session_out.is_active = true;
        self.sessions[self.session_count] = session_out.*;
        self.session_count += 1;
        std.debug.assert(self.session_count <= 100);
        return true;
    }

    // Validate session
    pub fn validate_session(
        self: *AuthService,
        session_id: []const u8,
        current_time: u64,
        session_out: ?*Session,
    ) bool {
        std.debug.assert(session_id.len > 0);
        std.debug.assert(session_id.len <= MAX_SESSION_ID_LEN);
        std.debug.assert(current_time > 0);
        var i: u32 = 0;
        while (i < self.session_count) : (i += 1) {
            const session = &self.sessions[i];
            if (!session.is_active) {
                continue;
            }
            if (session.expires_at < current_time) {
                session.is_active = false;
                continue;
            }
            const session_id_bytes =
session.session_id[0..session.session_id_len];
            if (std.mem.eql(u8, session_id_bytes, session_id)) {
                if (session_out) |out| {
                    out.* = session.*;
                }
                return true;
            }
        }
        return false;
    }

    // Revoke session (logout)
    pub fn revoke_session(self: *AuthService, session_id: []const u8)
bool {
        std.debug.assert(session_id.len > 0);
        std.debug.assert(session_id.len <= MAX_SESSION_ID_LEN);
        var i: u32 = 0;
        while (i < self.session_count) : (i += 1) {
            const session = &self.sessions[i];
            const session_id_bytes =
session.session_id[0..session.session_id_len];
            if (std.mem.eql(u8, session_id_bytes, session_id)) {
                session.is_active = false;
                return true;
            }
        }
        return false;
    }

    // Generate OTP code
    pub fn generate_otp(
        self: *AuthService,
        email: []const u8,
        current_time: u64,
        otp_out: *Otp,
    ) bool {
        std.debug.assert(email.len > 0);
        std.debug.assert(email.len <= MAX_EMAIL_LEN);
        std.debug.assert(current_time > 0);
        std.debug.assert(otp_out != null);
        if (self.otp_count >= 50) {
            return false;
        }
        var code_bytes: [4]u8 = undefined;
        std.crypto.random.bytes(&code_bytes);
        var code: [MAX_OTP_CODE_LEN]u8 = undefined;
        var code_len: u32 = 0;
        var i: u32 = 0;
        while (i < 4 and code_len < MAX_OTP_CODE_LEN) : (i += 1) {
            const digit = code_bytes[i] % 10;
            code[code_len] = '0' + digit;
            code_len += 1;
        }
        std.mem.copyForwards(u8, &otp_out.code, code[0..code_len]);
        otp_out.code_len = code_len;
        std.mem.copyForwards(u8, &otp_out.email, email);
        otp_out.email_len = @intCast(email.len);
        otp_out.created_at = current_time;
        otp_out.expires_at = current_time + OTP_EXPIRY;
        otp_out.is_used = false;
        self.otps[self.otp_count] = otp_out.*;
        self.otp_count += 1;
        std.debug.assert(self.otp_count <= 50);
        return true;
    }

    // Validate OTP code
    pub fn validate_otp(
        self: *AuthService,
        email: []const u8,
        code: []const u8,
        current_time: u64,
    ) bool {
        std.debug.assert(email.len > 0);
        std.debug.assert(email.len <= MAX_EMAIL_LEN);
        std.debug.assert(code.len > 0);
        std.debug.assert(code.len <= MAX_OTP_CODE_LEN);
        std.debug.assert(current_time > 0);
        var i: u32 = 0;
        while (i < self.otp_count) : (i += 1) {
            const otp = &self.otps[i];
            if (otp.is_used) {
                continue;
            }
            if (otp.expires_at < current_time) {
                continue;
            }
            const otp_email = otp.email[0..otp.email_len];
            if (!std.mem.eql(u8, otp_email, email)) {
                continue;
            }
            const otp_code = otp.code[0..otp.code_len];
            if (std.mem.eql(u8, otp_code, code)) {
                otp.is_used = true;
                return true;
            }
        }
        return false;
    }

    // Generate TOTP code (2FA)
    pub fn generate_totp(secret: []const u8, timestamp: u64) u32 {
        std.debug.assert(secret.len > 0);
        std.debug.assert(timestamp > 0);
        const time_step: u64 = 30;
        const time_counter = timestamp / time_step;
        var time_bytes: [8]u8 = undefined;
        var i: u32 = 0;
        var counter = time_counter;
        while (i < 8) : (i += 1) {
            time_bytes[7 - i] = @truncate(counter & 0xFF);
            counter >>= 8;
        }
        var hmac: [20]u8 = undefined;
        hmac_sha1(secret, &time_bytes, &hmac);
        const offset = hmac[19] & 0x0F;
        const code = ((@as(u32, hmac[offset]) & 0x7F) << 24) |
            (@as(u32, hmac[offset + 1]) << 16) |
            (@as(u32, hmac[offset + 2]) << 8) |
            @as(u32, hmac[offset + 3]);
        const totp_code = code % 1000000;
        std.debug.assert(totp_code < 1000000);
        return totp_code;
    }

    // Validate TOTP code (2FA)
    pub fn validate_totp(
        secret: []const u8,
        code: u32,
        timestamp: u64,
    ) bool {
        std.debug.assert(secret.len > 0);
        std.debug.assert(code < 1000000);
        std.debug.assert(timestamp > 0);
        const generated = generate_totp(secret, timestamp);
        if (generated == code) {
            return true;
        }
        const time_step: u64 = 30;
        const prev_timestamp = timestamp - time_step;
        const prev_generated = generate_totp(secret, prev_timestamp);
        if (prev_generated == code) {
            return true;
        }
        const next_timestamp = timestamp + time_step;
        const next_generated = generate_totp(secret, next_timestamp);
        if (next_generated == code) {
            return true;
        }
        return false;
    }
};

// HMAC-SHA1 for TOTP
fn hmac_sha1(key: []const u8, message: []const u8, output: []u8) void {
    std.debug.assert(key.len > 0);
    std.debug.assert(message.len > 0);
    std.debug.assert(output.len >= 20);
    const block_size: u32 = 64;
    var ipad_key: [block_size]u8 = undefined;
    var opad_key: [block_size]u8 = undefined;
    if (key.len > block_size) {
        var key_hash: [20]u8 = undefined;
        std.crypto.hash.sha1.Sha1.hash(key, &key_hash, .{});
        std.mem.set(u8, &ipad_key, 0);
        std.mem.copyForwards(u8, ipad_key[0..20], &key_hash);
    } else {
        std.mem.set(u8, &ipad_key, 0);
        std.mem.copyForwards(u8, ipad_key[0..key.len], key);
    }
    var i: u32 = 0;
    while (i < block_size) : (i += 1) {
        opad_key[i] = ipad_key[i];
        ipad_key[i] ^= 0x36;
        opad_key[i] ^= 0x5C;
    }
    var inner_hash: [20]u8 = undefined;
    var inner_input: [block_size + 256]u8 = undefined;
    std.mem.copyForwards(u8, inner_input[0..block_size], &ipad_key);
    if (message.len <= 256) {
        std.mem.copyForwards(
            u8,
            inner_input[block_size..block_size + message.len],
            message,
        );
        std.crypto.hash.sha1.Sha1.hash(
            inner_input[0..block_size + message.len],
            &inner_hash,
            .{},
        );
    } else {
        std.crypto.hash.sha1.Sha1.hash(message, &inner_hash, .{});
    }
    var outer_input: [block_size + 20]u8 = undefined;
    std.mem.copyForwards(u8, outer_input[0..block_size], &opad_key);
    std.mem.copyForwards(u8, outer_input[block_size..block_size + 20],
&inner_hash);
    std.crypto.hash.sha1.Sha1.hash(
        outer_input[0..block_size + 20],
        output[0..20],
        .{},
    );
    std.debug.assert(output.len >= 20);
}

// Generate JWT token (internal helper)
fn generate_jwt_token(
    claims: *const JwtClaims,
    secret: []const u8,
    token_out: []u8,
) u32 {
    std.debug.assert(claims != null);
    std.debug.assert(secret.len > 0);
    std.debug.assert(token_out.len >= MAX_JWT_LEN);
    const header = "{\"alg\":\"HS256\",\"typ\":\"JWT\"}";
    var header_encoded: [256]u8 = undefined;
    const header_encoded_len = base64url_encode(header, &header_encoded);
    var claims_json: [512]u8 = undefined;
    var claims_json_len: u32 = 0;
    claims_json[claims_json_len] = '{';
    claims_json_len += 1;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    std.mem.copyForwards(u8, claims_json[claims_json_len..], "user_id");
    claims_json_len += 6;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    claims_json[claims_json_len] = ':';
    claims_json_len += 1;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    std.mem.copyForwards(
        u8,
        claims_json[claims_json_len..],
        claims.user_id[0..claims.user_id_len],
    );
    claims_json_len += claims.user_id_len;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    claims_json[claims_json_len] = ',';
    claims_json_len += 1;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    std.mem.copyForwards(u8, claims_json[claims_json_len..], "exp");
    claims_json_len += 3;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    claims_json[claims_json_len] = ':';
    claims_json_len += 1;
    var exp_str: [20]u8 = undefined;
    var exp_remaining = claims.exp;
    var exp_str_len: u32 = 0;
    if (exp_remaining == 0) {
        exp_str[0] = '0';
        exp_str_len = 1;
    } else {
        var exp_idx: u32 = 19;
        while (exp_remaining > 0) {
            exp_str[exp_idx] = '0' + @as(u8, @intCast(exp_remaining %
10));
            exp_remaining /= 10;
            exp_idx -= 1;
        }
        exp_str_len = 20 - exp_idx - 1;
        std.mem.copyForwards(
            u8,
            claims_json[claims_json_len..],
            exp_str[exp_idx + 1..20],
        );
        claims_json_len += exp_str_len;
    }
    claims_json[claims_json_len] = ',';
    claims_json_len += 1;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    std.mem.copyForwards(u8, claims_json[claims_json_len..], "iat");
    claims_json_len += 3;
    claims_json[claims_json_len] = '"';
    claims_json_len += 1;
    claims_json[claims_json_len] = ':';
    claims_json_len += 1;
    var iat_remaining = claims.iat;
    var iat_str: [20]u8 = undefined;
    var iat_str_len: u32 = 0;
    if (iat_remaining == 0) {
        iat_str[0] = '0';
        iat_str_len = 1;
    } else {
        var iat_idx: u32 = 19;
        while (iat_remaining > 0) {
            iat_str[iat_idx] = '0' + @as(u8, @intCast(iat_remaining %
10));
            iat_remaining /= 10;
            iat_idx -= 1;
        }
        iat_str_len = 20 - iat_idx - 1;
        std.mem.copyForwards(
            u8,
            claims_json[claims_json_len..],
            iat_str[iat_idx + 1..20],
        );
        claims_json_len += iat_str_len;
    }
    claims_json[claims_json_len] = '}';
    claims_json_len += 1;
    var claims_encoded: [512]u8 = undefined;
    const claims_encoded_len = base64url_encode(
        claims_json[0..claims_json_len],
        &claims_encoded,
    );
    var message: [1024]u8 = undefined;
    std.mem.copyForwards(
        u8,
        message[0..header_encoded_len],
        header_encoded[0..header_encoded_len],
    );
    message[header_encoded_len] = '.';
    std.mem.copyForwards(
        u8,
        message[header_encoded_len + 1..header_encoded_len + 1 +
claims_encoded_len],
        claims_encoded[0..claims_encoded_len],
    );
    const message_len = header_encoded_len + 1 + claims_encoded_len;
    var signature: [32]u8 = undefined;
    hmac_sha256(secret, message[0..message_len], &signature);
    var signature_encoded: [64]u8 = undefined;
    const signature_encoded_len = base64url_encode(&signature,
&signature_encoded);
    var token_len: u32 = 0;
    std.mem.copyForwards(
        u8,
        token_out[token_len..],
        header_encoded[0..header_encoded_len],
    );
    token_len += header_encoded_len;
    token_out[token_len] = '.';
    token_len += 1;
    std.mem.copyForwards(
        u8,
        token_out[token_len..],
        claims_encoded[0..claims_encoded_len],
    );
    token_len += claims_encoded_len;
    token_out[token_len] = '.';
    token_len += 1;
    std.mem.copyForwards(
        u8,
        token_out[token_len..],
        signature_encoded[0..signature_encoded_len],
    );
    token_len += signature_encoded_len;
    std.debug.assert(token_len <= token_out.len);
    return token_len;
}

// Validate JWT token (internal helper)
fn validate_jwt(
    token: []const u8,
    secret: []const u8,
    current_time: u64,
    claims_out: *JwtClaims,
) bool {
    std.debug.assert(token.len > 0);
    std.debug.assert(token.len <= MAX_JWT_LEN);
    std.debug.assert(secret.len > 0);
    std.debug.assert(current_time > 0);
    std.debug.assert(claims_out != null);
    var parts: [3][]const u8 = undefined;
    var part_count: u32 = 0;
    var start: u32 = 0;
    var i: u32 = 0;
    while (i < token.len and part_count < 3) : (i += 1) {
        if (token[i] == '.') {
            parts[part_count] = token[start..i];
            part_count += 1;
            start = i + 1;
        }
    }
    if (part_count < 2) {
        return false;
    }
    parts[part_count] = token[start..];
    part_count += 1;
    if (part_count != 3) {
        return false;
    }
    var message: [1024]u8 = undefined;
    std.mem.copyForwards(u8, message[0..parts[0].len], parts[0]);
    message[parts[0].len] = '.';
    std.mem.copyForwards(
        u8,
        message[parts[0].len + 1..parts[0].len + 1 + parts[1].len],
        parts[1],
    );
    const message_len = parts[0].len + 1 + parts[1].len;
    var computed_sig: [32]u8 = undefined;
    hmac_sha256(secret, message[0..message_len], &computed_sig);
    var computed_sig_encoded: [64]u8 = undefined;
    const computed_sig_len = base64url_encode(&computed_sig,
&computed_sig_encoded);
    if (computed_sig_len != parts[2].len) {
        return false;
    }
    if (!std.mem.eql(
        u8,
        computed_sig_encoded[0..computed_sig_len],
        parts[2],
    )) {
        return false;
    }
    var claims_decoded: [512]u8 = undefined;
    const claims_decoded_len = base64url_decode(parts[1],
&claims_decoded);
    var exp_found: bool = false;
    var exp_value: u64 = 0;
    var user_id_start: ?u32 = null;
    var user_id_end: ?u32 = null;
    i = 0;
    while (i < claims_decoded_len) : (i += 1) {
        if (i + 5 < claims_decoded_len and
            std.mem.eql(u8, claims_decoded[i..i + 5], "\"exp\""))
        {
            var j = i + 5;
            while (j < claims_decoded_len and claims_decoded[j] != ':')
: (j += 1) {}
            j += 1;
            while (j < claims_decoded_len and
                (claims_decoded[j] == ' ' or claims_decoded[j] == '\t'))
: (j += 1) {}
            exp_value = 0;
            while (j < claims_decoded_len and
                claims_decoded[j] >= '0' and claims_decoded[j] <= '9') :
(j += 1)
            {
                exp_value = exp_value * 10 + @as(u64,
@intCast(claims_decoded[j] - '0'));
            }
            exp_found = true;
        }
        if (i + 8 < claims_decoded_len and
            std.mem.eql(u8, claims_decoded[i..i + 8], "\"user_id\""))
        {
            var j = i + 8;
            while (j < claims_decoded_len and claims_decoded[j] != ':')
: (j += 1) {}
            j += 1;
            while (j < claims_decoded_len and
                (claims_decoded[j] == ' ' or claims_decoded[j] == '\t'))
: (j += 1) {}
            if (j < claims_decoded_len and claims_decoded[j] == '"') {
                j += 1;
                user_id_start = j;
                while (j < claims_decoded_len and claims_decoded[j] !=
'"') : (j += 1) {}
                user_id_end = j;
            }
        }
    }
    if (!exp_found) {
        return false;
    }
    claims_out.exp = exp_value;
    if (user_id_start) |start_idx| {
        if (user_id_end) |end_idx| {
            const user_id_len = end_idx - start_idx;
            if (user_id_len > MAX_USER_ID_LEN) {
                return false;
            }
            std.mem.copyForwards(
                u8,
                &claims_out.user_id,
                claims_decoded[start_idx..end_idx],
            );
            claims_out.user_id_len = user_id_len;
        } else {
            return false;
        }
    } else {
        return false;
    }
    claims_out.iat = current_time;
    claims_out.token_type = TokenType.access;
    std.debug.assert(claims_out.user_id_len > 0);
    return true;
}

// Base64URL encoding
fn base64url_encode(input: []const u8, output: []u8) u32 {
    std.debug.assert(input.len > 0);
    std.debug.assert(output.len >= (input.len * 4 / 3 + 4));
    const base64_chars =
"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    var i: u32 = 0;
    var out_idx: u32 = 0;
    while (i < input.len) {
        const byte1 = input[i];
        i += 1;
        if (i < input.len) {
            const byte2 = input[i];
            i += 1;
            if (i < input.len) {
                const byte3 = input[i];
                i += 1;
                const b1 = (byte1 >> 2) & 0x3F;
                const b2 = ((byte1 & 0x03) << 4) | ((byte2 >> 4) & 0x0F);
                const b3 = ((byte2 & 0x0F) << 2) | ((byte3 >> 6) & 0x03);
                const b4 = byte3 & 0x3F;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b1)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b2)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b3)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b4)];
                out_idx += 1;
            } else {
                const b1 = (byte1 >> 2) & 0x3F;
                const b2 = ((byte1 & 0x03) << 4) | ((byte2 >> 4) & 0x0F);
                const b3 = (byte2 & 0x0F) << 2;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b1)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b2)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b3)];
                out_idx += 1;
                if (out_idx < output.len) output[out_idx] = '=';
                out_idx += 1;
            }
        } else {
            const b1 = (byte1 >> 2) & 0x3F;
            const b2 = (byte1 & 0x03) << 4;
            if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b1)];
            out_idx += 1;
            if (out_idx < output.len) output[out_idx] =
base64_chars[@intCast(b2)];
            out_idx += 1;
            if (out_idx < output.len) output[out_idx] = '=';
            out_idx += 1;
            if (out_idx < output.len) output[out_idx] = '=';
            out_idx += 1;
        }
    }
    std.debug.assert(out_idx <= output.len);
    return out_idx;
}

// Base64URL decoding
fn base64url_decode(input: []const u8, output: []u8) u32 {
    std.debug.assert(input.len > 0);
    std.debug.assert(output.len >= (input.len * 3 / 4));
    const base64_chars =
"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_";
    var out_idx: u32 = 0;
    var i: u32 = 0;
    while (i < input.len) {
        if (input[i] == '=') {
            break;
        }
        var char_val: u8 = 255;
        var j: u32 = 0;
        while (j < 64) : (j += 1) {
            if (base64_chars[j] == input[i]) {
                char_val = @intCast(j);
                break;
            }
        }
        if (char_val == 255) {
            break;
        }
        if (i + 1 < input.len and input[i + 1] != '=') {
            var char_val2: u8 = 255;
            j = 0;
            while (j < 64) : (j += 1) {
                if (base64_chars[j] == input[i + 1]) {
                    char_val2 = @intCast(j);
                    break;
                }
            }
            if (char_val2 == 255) {
                break;
            }
            if (i + 2 < input.len and input[i + 2] != '=') {
                var char_val3: u8 = 255;
                j = 0;
                while (j < 64) : (j += 1) {
                    if (base64_chars[j] == input[i + 2]) {
                        char_val3 = @intCast(j);
                        break;
                    }
                }
                if (char_val3 == 255) {
                    break;
                }
                if (i + 3 < input.len and input[i + 3] != '=') {
                    var char_val4: u8 = 255;
                    j = 0;
                    while (j < 64) : (j += 1) {
                        if (base64_chars[j] == input[i + 3]) {
                            char_val4 = @intCast(j);
                            break;
                        }
                    }
                    if (char_val4 == 255) {
                        break;
                    }
                    if (out_idx < output.len) {
                        output[out_idx] = (char_val << 2) | (char_val2
>> 4);
                        out_idx += 1;
                    }
                    if (out_idx < output.len) {
                        output[out_idx] = ((char_val2 & 0x0F) << 4) |
(char_val3 >> 2);
                        out_idx += 1;
                    }
                    if (out_idx < output.len) {
                        output[out_idx] = ((char_val3 & 0x03) << 6) |
char_val4;
                        out_idx += 1;
                    }
                    i += 4;
                } else {
                    if (out_idx < output.len) {
                        output[out_idx] = (char_val << 2) | (char_val2
>> 4);
                        out_idx += 1;
                    }
                    if (out_idx < output.len) {
                        output[out_idx] = ((char_val2 & 0x0F) << 4) |
(char_val3 >> 2);
                        out_idx += 1;
                    }
                    i += 3;
                    break;
                }
            } else {
                if (out_idx < output.len) {
                    output[out_idx] = (char_val << 2) | (char_val2 >> 4);
                    out_idx += 1;
                }
                i += 2;
                break;
            }
        } else {
            if (out_idx < output.len) {
                output[out_idx] = char_val << 2;
                out_idx += 1;
            }
            i += 1;
            break;
        }
    }
    std.debug.assert(out_idx <= output.len);
    return out_idx;
}

// HMAC-SHA256 for JWT signatures
fn hmac_sha256(key: []const u8, message: []const u8, output: []u8) void {
    std.debug.assert(key.len > 0);
    std.debug.assert(message.len > 0);
    std.debug.assert(output.len >= 32);
    const block_size: u32 = 64;
    var ipad_key: [block_size]u8 = undefined;
    var opad_key: [block_size]u8 = undefined;
    if (key.len > block_size) {
        var key_hash: [32]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(key, &key_hash, .{});
        std.mem.set(u8, &ipad_key, 0);
        std.mem.copyForwards(u8, ipad_key[0..32], &key_hash);
    } else {
        std.mem.set(u8, &ipad_key, 0);
        std.mem.copyForwards(u8, ipad_key[0..key.len], key);
    }
    var i: u32 = 0;
    while (i < block_size) : (i += 1) {
        opad_key[i] = ipad_key[i];
        ipad_key[i] ^= 0x36;
        opad_key[i] ^= 0x5C;
    }
    var inner_hash: [32]u8 = undefined;
    var inner_input: [block_size + 256]u8 = undefined;
    std.mem.copyForwards(u8, inner_input[0..block_size], &ipad_key);
    if (message.len <= 256) {
        std.mem.copyForwards(
            u8,
            inner_input[block_size..block_size + message.len],
            message,
        );
        std.crypto.hash.sha2.Sha256.hash(
            inner_input[0..block_size + message.len],
            &inner_hash,
            .{},
        );
    } else {
        std.crypto.hash.sha2.Sha256.hash(message, &inner_hash, .{});
    }
    var outer_input: [block_size + 32]u8 = undefined;
    std.mem.copyForwards(u8, outer_input[0..block_size], &opad_key);
    std.mem.copyForwards(u8, outer_input[block_size..block_size + 32],
&inner_hash);
    std.crypto.hash.sha2.Sha256.hash(
        outer_input[0..block_size + 32],
        output[0..32],
        .{},
    );
    std.debug.assert(output.len >= 32);
}


// === grain_core/backup_manager.zig ===

//! Grain Core Backup Manager: Database backup and restore capabilities.
//!
//! Why: Provide database backup/restore for data protection (Silo
Agent).
//! Architecture: Full backup, incremental backup, restore, scheduling.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");
const file_storage = @import("file_storage.zig");

// Bounded: Max backup files.
pub const MAX_BACKUP_FILES: u32 = 100;

// Bounded: Max backup filename length.
pub const MAX_BACKUP_FILENAME_LEN: u32 = 256;

// Bounded: Max backup metadata size.
pub const MAX_BACKUP_METADATA_SIZE: u32 = 1024;

// Backup type.
pub const BackupType = enum(u8) {
    full,
    incremental,
};

// Backup state.
pub const BackupState = enum(u8) {
    pending,
    in_progress,
    completed,
    failed,
};

// Backup metadata.
pub const BackupMetadata = struct {
    backup_id: u32,
    backup_type: BackupType,
    filename: [MAX_BACKUP_FILENAME_LEN]u8,
    filename_len: u32,
    file_size: u64,
    created_at: u64,
    state: BackupState,
    checksum: [file_storage.CHECKSUM_SIZE]u8,
    metadata: [MAX_BACKUP_METADATA_SIZE]u8,
    metadata_len: u32,

    pub fn init() BackupMetadata {
        var meta = BackupMetadata{
            .backup_id = 0,
            .backup_type = BackupType.full,
            .filename = undefined,
            .filename_len = 0,
            .file_size = 0,
            .created_at = 0,
            .state = BackupState.pending,
            .checksum = undefined,
            .metadata = undefined,
            .metadata_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_BACKUP_FILENAME_LEN) : (i += 1) {
            meta.filename[i] = 0;
        }
        i = 0;
        while (i < file_storage.CHECKSUM_SIZE) : (i += 1) {
            meta.checksum[i] = 0;
        }
        i = 0;
        while (i < MAX_BACKUP_METADATA_SIZE) : (i += 1) {
            meta.metadata[i] = 0;
        }
        return meta;
    }

    pub fn set_filename(self: *BackupMetadata, filename: []const u8)
bool {
        std.debug.assert(filename.len > 0);
        std.debug.assert(filename.len <= MAX_BACKUP_FILENAME_LEN);
        const filename_len = @min(filename.len, MAX_BACKUP_FILENAME_LEN);
        var i: u32 = 0;
        while (i < MAX_BACKUP_FILENAME_LEN) : (i += 1) {
            self.filename[i] = 0;
        }
        i = 0;
        while (i < filename_len) : (i += 1) {
            self.filename[i] = filename[i];
        }
        self.filename_len = filename_len;
        return true;
    }
};

// Backup manager: manages database backups.
pub const BackupManager = struct {
    backups: [MAX_BACKUP_FILES]BackupMetadata,
    backups_len: u32,
    next_backup_id: u32,
    last_full_backup: u64,
    last_incremental_backup: u64,

    pub fn init() BackupManager {
        var manager = BackupManager{
            .backups = undefined,
            .backups_len = 0,
            .next_backup_id = 1,
            .last_full_backup = 0,
            .last_incremental_backup = 0,
        };
        var i: u32 = 0;
        while (i < MAX_BACKUP_FILES) : (i += 1) {
            manager.backups[i] = BackupMetadata.init();
        }
        return manager;
    }

    pub fn create_backup(
        self: *BackupManager,
        backup_type: BackupType,
        filename: []const u8,
        timestamp: u64,
    ) ?*BackupMetadata {
        std.debug.assert(filename.len > 0);
        std.debug.assert(timestamp > 0);
        if (self.backups_len >= MAX_BACKUP_FILES) {
            return null;
        }
        const backup_id = self.next_backup_id;
        self.next_backup_id += 1;
        self.backups[self.backups_len] = BackupMetadata.init();
        const backup = &self.backups[self.backups_len];
        backup.backup_id = backup_id;
        backup.backup_type = backup_type;
        _ = backup.set_filename(filename);
        backup.created_at = timestamp;
        backup.state = BackupState.pending;
        if (backup_type == BackupType.full) {
            self.last_full_backup = timestamp;
        } else {
            self.last_incremental_backup = timestamp;
        }
        self.backups_len += 1;
        return backup;
    }

    pub fn find_backup(
        self: *BackupManager,
        backup_id: u32,
    ) ?*BackupMetadata {
        std.debug.assert(backup_id > 0);
        var i: u32 = 0;
        while (i < self.backups_len) : (i += 1) {
            if (self.backups[i].backup_id == backup_id) {
                return &self.backups[i];
            }
        }
        return null;
    }

    pub fn update_backup_state(
        self: *BackupManager,
        backup_id: u32,
        state: BackupState,
        file_size: u64,
        checksum: []const u8,
    ) bool {
        std.debug.assert(backup_id > 0);
        std.debug.assert(checksum.len == file_storage.CHECKSUM_SIZE);
        if (self.find_backup(backup_id)) |backup| {
            backup.state = state;
            backup.file_size = file_size;
            var i: u32 = 0;
            while (i < file_storage.CHECKSUM_SIZE) : (i += 1) {
                backup.checksum[i] = checksum[i];
            }
            return true;
        }
        return false;
    }

    pub fn delete_backup(
        self: *BackupManager,
        backup_id: u32,
    ) bool {
        std.debug.assert(backup_id > 0);
        var i: u32 = 0;
        while (i < self.backups_len) : (i += 1) {
            if (self.backups[i].backup_id == backup_id) {
                var j: u32 = i;
                while (j < self.backups_len - 1) : (j += 1) {
                    self.backups[j] = self.backups[j + 1];
                }
                self.backups_len -= 1;
                return true;
            }
        }
        return false;
    }

    pub fn get_latest_full_backup(self: *const BackupManager) ?*const
BackupMetadata {
        var latest: ?*const BackupMetadata = null;
        var latest_time: u64 = 0;
        var i: u32 = 0;
        while (i < self.backups_len) : (i += 1) {
            if (self.backups[i].backup_type == BackupType.full and
                self.backups[i].state == BackupState.completed and
                self.backups[i].created_at > latest_time)
            {
                latest = &self.backups[i];
                latest_time = self.backups[i].created_at;
            }
        }
        return latest;
    }

    pub fn should_schedule_backup(
        self: *const BackupManager,
        backup_type: BackupType,
        current_time: u64,
        full_backup_interval: u64,
        incremental_backup_interval: u64,
    ) bool {
        std.debug.assert(current_time > 0);
        std.debug.assert(full_backup_interval > 0);
        std.debug.assert(incremental_backup_interval > 0);
        if (backup_type == BackupType.full) {
            if (self.last_full_backup == 0) {
                return true;
            }
            return (current_time - self.last_full_backup) >=
full_backup_interval;
        } else {
            if (self.last_incremental_backup == 0) {
                return true;
            }
            return (current_time - self.last_incremental_backup) >=
incremental_backup_interval;
        }
    }
};

// === grain_core/clipboard.zig ===

//! Grain OS Clipboard: System clipboard management for copy/paste.
//!
//! Why: Provide system-wide clipboard for copy/paste operations.
//! Architecture: Clipboard buffer, format support, history.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max clipboard data size (4KB).
pub const MAX_CLIPBOARD_SIZE: u32 = 4096;

// Bounded: Max clipboard history entries.
pub const MAX_HISTORY_ENTRIES: u32 = 16;

// Bounded: Max format name length.
pub const MAX_FORMAT_NAME_LEN: u32 = 32;

// Clipboard format types.
pub const ClipboardFormat = enum(u8) {
    text,
    html,
    image,
    custom,
};

// Clipboard entry: represents clipboard data.
pub const ClipboardEntry = struct {
    format: ClipboardFormat,
    data: [MAX_CLIPBOARD_SIZE]u8,
    data_len: u32,
    format_name: [MAX_FORMAT_NAME_LEN]u8,
    format_name_len: u32,
    timestamp: u64,

    pub fn init() ClipboardEntry {
        var entry = ClipboardEntry{
            .format = ClipboardFormat.text,
            .data = undefined,
            .data_len = 0,
            .format_name = undefined,
            .format_name_len = 0,
            .timestamp = 0,
        };
        var i: u32 = 0;
        while (i < MAX_CLIPBOARD_SIZE) : (i += 1) {
            entry.data[i] = 0;
        }
        i = 0;
        while (i < MAX_FORMAT_NAME_LEN) : (i += 1) {
            entry.format_name[i] = 0;
        }
        return entry;
    }
};

// Clipboard manager: manages system clipboard.
pub const ClipboardManager = struct {
    current_entry: ClipboardEntry,
    history: [MAX_HISTORY_ENTRIES]ClipboardEntry,
    history_len: u32,

    pub fn init() ClipboardManager {
        var manager = ClipboardManager{
            .current_entry = ClipboardEntry.init(),
            .history = undefined,
            .history_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_HISTORY_ENTRIES) : (i += 1) {
            manager.history[i] = ClipboardEntry.init();
        }
        return manager;
    }

    // Set clipboard data.
    pub fn set_data(
        self: *ClipboardManager,
        format: ClipboardFormat,
        data: []const u8,
        format_name: []const u8,
    ) bool {
        if (data.len > MAX_CLIPBOARD_SIZE) {
            return false;
        }
        if (format_name.len > MAX_FORMAT_NAME_LEN) {
            return false;
        }
        // Save current entry to history if not empty.
        if (self.current_entry.data_len > 0) {
            if (self.history_len < MAX_HISTORY_ENTRIES) {
                self.history[self.history_len] = self.current_entry;
                self.history_len += 1;
            } else {
                // Shift history left, remove oldest.
                var i: u32 = 0;
                while (i < MAX_HISTORY_ENTRIES - 1) : (i += 1) {
                    self.history[i] = self.history[i + 1];
                }
                self.history[MAX_HISTORY_ENTRIES - 1] =
self.current_entry;
            }
        }
        // Set new clipboard data.
        self.current_entry = ClipboardEntry.init();
        self.current_entry.format = format;
        var i: u32 = 0;
        while (i < MAX_CLIPBOARD_SIZE) : (i += 1) {
            self.current_entry.data[i] = 0;
        }
        i = 0;
        while (i < data.len) : (i += 1) {
            self.current_entry.data[i] = data[i];
        }
        self.current_entry.data_len = @intCast(data.len);
        i = 0;
        while (i < MAX_FORMAT_NAME_LEN) : (i += 1) {
            self.current_entry.format_name[i] = 0;
        }
        const name_len = @min(format_name.len, MAX_FORMAT_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.current_entry.format_name[i] = format_name[i];
        }
        self.current_entry.format_name_len = @intCast(name_len);
        self.current_entry.timestamp = 0; // Would use actual timestamp.
        return true;
    }

    // Get clipboard data.
    pub fn get_data(self: *const ClipboardManager) ?[]const u8 {
        if (self.current_entry.data_len == 0) {
            return null;
        }
        return self.current_entry.data[0..self.current_entry.data_len];
    }

    // Get clipboard format.
    pub fn get_format(self: *const ClipboardManager) ClipboardFormat {
        return self.current_entry.format;
    }

    // Get clipboard format name.
    pub fn get_format_name(self: *const ClipboardManager) []const u8 {
        return
self.current_entry.format_name[0..self.current_entry.format_name_len];
    }

    // Check if clipboard is empty.
    pub fn is_empty(self: *const ClipboardManager) bool {
        return self.current_entry.data_len == 0;
    }

    // Clear clipboard.
    pub fn clear(self: *ClipboardManager) void {
        self.current_entry = ClipboardEntry.init();
    }

    // Get history entry.
    pub fn get_history_entry(self: *const ClipboardManager, index: u32)
?*const ClipboardEntry {
        if (index >= self.history_len) {
            return null;
        }
        return &self.history[index];
    }

    // Get history count.
    pub fn get_history_count(self: *const ClipboardManager) u32 {
        return self.history_len;
    }

    // Clear history.
    pub fn clear_history(self: *ClipboardManager) void {
        self.history_len = 0;
    }
};


// === grain_core/compositor.zig ===

//! Grain OS Compositor: Wayland compositor for desktop environment.
//!
//! Why: Manage windows, surfaces, and input for Grain OS desktop.
//! Architecture: Wayland protocol, kernel framebuffer rendering.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const wayland = @import("wayland/protocol.zig");
const basin_kernel = @import("basin_kernel");
const tiling = @import("tiling.zig");
const framebuffer_renderer = @import("framebuffer_renderer.zig");
const layout_generator = @import("layout_generator.zig");
const input_handler = @import("input_handler.zig");
const workspace = @import("workspace.zig");
const window_snapping = @import("window_snapping.zig");
const window_switching = @import("window_switching.zig");
const window_state = @import("window_state.zig");
const window_preview = @import("window_preview.zig");
const window_visual = @import("window_visual.zig");
const window_stacking = @import("window_stacking.zig");
const window_opacity = @import("window_opacity.zig");
const window_animation = @import("window_animation.zig");
