    // Get resize handle at mouse position.
    pub fn get_resize_handle(
        self: *Compositor,
        window_id: u32,
        x: u32,
        y: u32,
    ) ?ResizeHandle {
        std.debug.assert(window_id > 0);
        if (self.get_window(window_id)) |win| {
            if (win.maximized) return ResizeHandle.none;
            const win_x = @as(u32, @intCast(win.x));
            const win_y = @as(u32, @intCast(win.y));
            const handle_size = RESIZE_HANDLE_SIZE;
            // Check corners first.
            if (x >= win_x and x < win_x + handle_size and
                y >= win_y and y < win_y + handle_size)
            {
                return ResizeHandle.top_left;
            }
            if (x >= win_x + win.width - handle_size and x < win_x +
win.width and
                y >= win_y and y < win_y + handle_size)
            {
                return ResizeHandle.top_right;
            }
            if (x >= win_x and x < win_x + handle_size and
                y >= win_y + win.height - handle_size and y < win_y +
win.height)
            {
                return ResizeHandle.bottom_left;
            }
            if (x >= win_x + win.width - handle_size and x < win_x +
win.width and
                y >= win_y + win.height - handle_size and y < win_y +
win.height)
            {
                return ResizeHandle.bottom_right;
            }
            // Check edges.
            if (x >= win_x and x < win_x + handle_size) {
                return ResizeHandle.left;
            }
            if (x >= win_x + win.width - handle_size and x < win_x +
win.width) {
                return ResizeHandle.right;
            }
            if (y >= win_y and y < win_y + handle_size) {
                return ResizeHandle.top;
            }
            if (y >= win_y + win.height - handle_size and y < win_y +
win.height) {
                return ResizeHandle.bottom;
            }
        }
        return ResizeHandle.none;
    }

    // Start window drag.
    pub fn start_drag(self: *Compositor, window_id: u32, x: u32, y: u32)
void {
        std.debug.assert(window_id > 0);
        if (self.get_window(window_id)) |win| {
            if (win.maximized) return;
            win.drag_state.active = true;
            win.drag_state.start_x = @as(i32, @intCast(x));
            win.drag_state.start_y = @as(i32, @intCast(y));
            win.drag_state.window_start_x = win.x;
            win.drag_state.window_start_y = win.y;
            _ = self.focus_window(window_id);
        }
    }

    // Handle mouse move during drag/resize.
    fn handle_mouse_move(self: *Compositor, x: u32, y: u32) void {
        // Handle dragging.
        if (self.focused_window_id > 0) {
            if (self.get_window(self.focused_window_id)) |win| {
                if (win.drag_state.active) {
                    const dx = @as(i32, @intCast(x)) -
win.drag_state.start_x;
                    const dy = @as(i32, @intCast(y)) -
win.drag_state.start_y;
                    win.x = win.drag_state.window_start_x + dx;
                    win.y = win.drag_state.window_start_y + dy;
                    // Apply window snapping if near edges/corners.
                    const snap_state = window_snapping.apply_snap(
                        &win.x,
                        &win.y,
                        &win.width,
                        &win.height,
                        self.output.width,
                        self.output.height,
                        window_snapping.SNAP_THRESHOLD,
                    );
                    // If not snapped, clamp to screen bounds.
                    if (!snap_state.snapped) {
                        const min_x: i32 = 0;
                        const min_y: i32 = @as(i32,
@intCast(self.border_width + self.title_bar_height));
                        const max_x: i32 = @as(i32,
@intCast(self.output.width)) - @as(i32, @intCast(win.width));
                        const max_y: i32 = @as(i32,
@intCast(self.output.height)) - @as(i32, @intCast(win.height)) -
@as(i32, @intCast(desktop_shell.STATUS_BAR_HEIGHT));
                        win.x = std.math.clamp(win.x, min_x, max_x);
                        win.y = std.math.clamp(win.y, min_y, max_y);
                    }
                }
            }
        }
        // Handle resizing.
        var i: u32 = 0;
        while (i < self.windows_len) : (i += 1) {
            const win = &self.windows[i];
            if (win.resize_state.active) {
                self.update_resize(win, x, y);
            }
        }
    }

    // Start window resize.
    pub fn start_resize(
        self: *Compositor,
        window_id: u32,
        handle: ResizeHandle,
        x: u32,
        y: u32,
    ) void {
        std.debug.assert(window_id > 0);
        if (self.get_window(window_id)) |win| {
            if (win.maximized) return;
            win.resize_state.active = true;
            win.resize_state.handle = handle;
            win.resize_state.start_x = @as(i32, @intCast(x));
            win.resize_state.start_y = @as(i32, @intCast(y));
            win.resize_state.window_start_width = win.width;
            win.resize_state.window_start_height = win.height;
            win.resize_state.window_start_x = win.x;
            win.resize_state.window_start_y = win.y;
            _ = self.focus_window(window_id);
        }
    }

    // Update window resize.
    fn update_resize(self: *Compositor, win: *Window, x: u32, y: u32)
void {
        std.debug.assert(win.resize_state.active);
        // Parameters x and y are used in calculations below.
        // Self is used implicitly through method calls.
        const dx = @as(i32, @intCast(x)) - win.resize_state.start_x;
        const dy = @as(i32, @intCast(y)) - win.resize_state.start_y;
        const min_size: u32 = 100;
        switch (win.resize_state.handle) {
            .top_left => {
                const new_width = if
(win.resize_state.window_start_width > @as(u32, @intCast(-dx)))
                    win.resize_state.window_start_width - @as(u32,
@intCast(-dx))
                else
                    min_size;
                const new_height = if
(win.resize_state.window_start_height > @as(u32, @intCast(-dy)))
                    win.resize_state.window_start_height - @as(u32,
@intCast(-dy))
                else
                    min_size;
                win.width = if (new_width < min_size) min_size else
new_width;
                win.height = if (new_height < min_size) min_size else
new_height;
                win.x = win.resize_state.window_start_x + dx;
                win.y = win.resize_state.window_start_y + dy;
            },
            .top => {
                const new_height = if
(win.resize_state.window_start_height > @as(u32, @intCast(-dy)))
                    win.resize_state.window_start_height - @as(u32,
@intCast(-dy))
                else
                    min_size;
                win.height = if (new_height < min_size) min_size else
new_height;
                win.y = win.resize_state.window_start_y + dy;
            },
            .top_right => {
                const new_width = win.resize_state.window_start_width +
@as(u32, @intCast(dx));
                const new_height = if
(win.resize_state.window_start_height > @as(u32, @intCast(-dy)))
                    win.resize_state.window_start_height - @as(u32,
@intCast(-dy))
                else
                    min_size;
                win.width = if (new_width < min_size) min_size else
new_width;
                win.height = if (new_height < min_size) min_size else
new_height;
                win.y = win.resize_state.window_start_y + dy;
            },
            .right => {
                const new_width = win.resize_state.window_start_width +
@as(u32, @intCast(dx));
                win.width = if (new_width < min_size) min_size else
new_width;
            },
            .bottom_right => {
                const new_width = win.resize_state.window_start_width +
@as(u32, @intCast(dx));
                const new_height = win.resize_state.window_start_height
+ @as(u32, @intCast(dy));
                win.width = if (new_width < min_size) min_size else
new_width;
                win.height = if (new_height < min_size) min_size else
new_height;
            },
            .bottom => {
                const new_height = win.resize_state.window_start_height
+ @as(u32, @intCast(dy));
                win.height = if (new_height < min_size) min_size else
new_height;
            },
            .bottom_left => {
                const new_width = if
(win.resize_state.window_start_width > @as(u32, @intCast(-dx)))
                    win.resize_state.window_start_width - @as(u32,
@intCast(-dx))
                else
                    min_size;
                const new_height = win.resize_state.window_start_height
+ @as(u32, @intCast(dy));
                win.width = if (new_width < min_size) min_size else
new_width;
                win.height = if (new_height < min_size) min_size else
new_height;
                win.x = win.resize_state.window_start_x + dx;
            },
            .left => {
                const new_width = if
(win.resize_state.window_start_width > @as(u32, @intCast(-dx)))
                    win.resize_state.window_start_width - @as(u32,
@intCast(-dx))
                else
                    min_size;
                win.width = if (new_width < min_size) min_size else
new_width;
                win.x = win.resize_state.window_start_x + dx;
            },
            .none => {},
        }
        // Apply window constraints.
        const constrained = win.constraints.apply_constraints(win.width,
win.height);
        win.width = constrained.width;
        win.height = constrained.height;
        // Clamp window to screen bounds.
        const max_width = self.output.width - (self.border_width * 2);
        const max_height = self.output.height - (self.border_width * 2)
- self.title_bar_height - desktop_shell.STATUS_BAR_HEIGHT;
        win.width = if (win.width > max_width) max_width else win.width;
        win.height = if (win.height > max_height) max_height else
win.height;
    }

    // End window drag.
    pub fn end_drag(self: *Compositor) void {
        if (self.focused_window_id > 0) {
            if (self.get_window(self.focused_window_id)) |win| {
                win.drag_state.active = false;
            }
        }
    }

    // End window resize.
    pub fn end_resize(self: *Compositor) void {
        var i: u32 = 0;
        while (i < self.windows_len) : (i += 1) {
            self.windows[i].resize_state.active = false;
            self.windows[i].resize_state.handle = ResizeHandle.none;
        }
    }
};


// === grain_core/connection_manager.zig ===

//! Grain OS Connection Manager: HTTP connection handling with
keep-alive and timeout.
//!
//! Why: Provide connection management for API server (keep-alive,
timeout, pooling).
//! Architecture: Connection state tracking, keep-alive management,
timeout handling.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");
const api_server = @import("api_server.zig");

// Bounded: Max concurrent connections.
pub const MAX_CONNECTIONS: u32 = 1024;

// Bounded: Default keep-alive timeout (seconds).
pub const DEFAULT_KEEP_ALIVE_TIMEOUT: u32 = 5;

// Bounded: Default request timeout (seconds).
pub const DEFAULT_REQUEST_TIMEOUT: u32 = 30;

// Connection state.
pub const ConnectionState = enum(u8) {
    idle,
    reading,
    writing,
    keep_alive,
    closing,
    closed,
};

// HTTP connection.
pub const HttpConnection = struct {
    connection_id: u64,
    state: ConnectionState,
    keep_alive: bool,
    keep_alive_timeout: u32,
    request_timeout: u32,
    last_activity_time: u64,
    request_count: u32,
    active: bool,

    pub fn init(connection_id: u64) HttpConnection {
        std.debug.assert(connection_id > 0);
        return HttpConnection{
            .connection_id = connection_id,
            .state = ConnectionState.idle,
            .keep_alive = false,
            .keep_alive_timeout = DEFAULT_KEEP_ALIVE_TIMEOUT,
            .request_timeout = DEFAULT_REQUEST_TIMEOUT,
            .last_activity_time = 0,
            .request_count = 0,
            .active = true,
        };
    }

    // Update activity time.
    pub fn update_activity(self: *HttpConnection, current_time: u64)
void {
        std.debug.assert(self.active);
        self.last_activity_time = current_time;
    }

    // Check if connection has timed out.
    pub fn is_timed_out(self: *const HttpConnection, current_time: u64)
bool {
        std.debug.assert(self.active);
        if (self.state == ConnectionState.keep_alive) {
            const elapsed = current_time - self.last_activity_time;
            return elapsed > self.keep_alive_timeout;
        } else {
            const elapsed = current_time - self.last_activity_time;
            return elapsed > self.request_timeout;
        }
    }

    // Set keep-alive.
    pub fn set_keep_alive(self: *HttpConnection, keep_alive: bool) void {
        std.debug.assert(self.active);
        self.keep_alive = keep_alive;
        if (keep_alive) {
            self.state = ConnectionState.keep_alive;
        }
    }

    // Increment request count.
    pub fn increment_request_count(self: *HttpConnection) void {
        std.debug.assert(self.active);
        self.request_count += 1;
    }

    // Close connection.
    pub fn close(self: *HttpConnection) void {
        std.debug.assert(self.active);
        self.state = ConnectionState.closing;
    }
};

// Connection manager: manages HTTP connections.
pub const ConnectionManager = struct {
    connections: [MAX_CONNECTIONS]HttpConnection,
    connections_len: u32,
    next_connection_id: u64,
    current_time: u64,

    pub fn init() ConnectionManager {
        return ConnectionManager{
            .connections = undefined,
            .connections_len = 0,
            .next_connection_id = 1,
            .current_time = 0,
        };
    }

    // Add connection.
    pub fn add_connection(self: *ConnectionManager) ?u32 {
        if (self.connections_len >= MAX_CONNECTIONS) {
            return null;
        }
        const connection_id = self.next_connection_id;
        self.next_connection_id += 1;
        self.connections[self.connections_len] =
HttpConnection.init(connection_id);
        self.connections[self.connections_len].last_activity_time =
self.current_time;
        const idx = self.connections_len;
        self.connections_len += 1;
        return idx;
    }

    // Get connection by index.
    pub fn get_connection(self: *ConnectionManager, idx: u32)
?*HttpConnection {
        if (idx >= self.connections_len) {
            return null;
        }
        if (!self.connections[idx].active) {
            return null;
        }
        return &self.connections[idx];
    }

    // Remove connection.
    pub fn remove_connection(self: *ConnectionManager, idx: u32) bool {
        if (idx >= self.connections_len) {
            return false;
        }
        if (!self.connections[idx].active) {
            return false;
        }
        self.connections[idx].active = false;
        self.connections[idx].state = ConnectionState.closed;
        if (idx < self.connections_len - 1) {
            self.connections[idx] =
self.connections[self.connections_len - 1];
        }
        self.connections_len -= 1;
        return true;
    }

    // Update current time.
    pub fn update_time(self: *ConnectionManager, current_time: u64) void
{
        self.current_time = current_time;
    }

    // Clean up timed out connections.
    pub fn cleanup_timeouts(self: *ConnectionManager) u32 {
        var cleaned: u32 = 0;
        var i: u32 = 0;
        while (i < self.connections_len) : (i += 1) {
            if (self.connections[i].active and
self.connections[i].is_timed_out(self.current_time)) {
                self.remove_connection(i);
                cleaned += 1;
                i -= 1;
            }
        }
        return cleaned;
    }

    // Get connection count.
    pub fn get_connection_count(self: *const ConnectionManager) u32 {
        return self.connections_len;
    }

    // Get active connection count.
    pub fn get_active_connection_count(self: *const ConnectionManager)
u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.connections_len) : (i += 1) {
            if (self.connections[i].active) {
                count += 1;
            }
        }
        return count;
    }
};


// === grain_core/desktop_shell.zig ===

//! Grain OS Desktop Shell: Status bar and launcher.
//!
//! Why: Provide basic desktop UI elements (status bar, launcher).
//! Architecture: Renders on top of compositor framebuffer.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const framebuffer_renderer = @import("framebuffer_renderer.zig");
const font_renderer = @import("font_renderer.zig");
const workspace = @import("workspace.zig");
const application = @import("application.zig");

// Bounded: Status bar height.
pub const STATUS_BAR_HEIGHT: u32 = 32;

// Bounded: Launcher width.
pub const LAUNCHER_WIDTH: u32 = 300;

// Bounded: Launcher height.
pub const LAUNCHER_HEIGHT: u32 = 400;

// Bounded: Max launcher items.
pub const MAX_LAUNCHER_ITEMS: u32 = 32;

// Bounded: Max item name length.
pub const MAX_ITEM_NAME_LEN: u32 = 64;

// Launcher item: application entry.
pub const LauncherItem = struct {
    name: [MAX_ITEM_NAME_LEN]u8,
    name_len: u32,
    command: [MAX_ITEM_NAME_LEN]u8,
    command_len: u32,
    icon: u32, // Placeholder for icon ID.

    pub fn init(name: []const u8, command: []const u8) LauncherItem {
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= MAX_ITEM_NAME_LEN);
        std.debug.assert(command.len > 0);
        std.debug.assert(command.len <= MAX_ITEM_NAME_LEN);
        var item = LauncherItem{
            .name = undefined,
            .name_len = 0,
            .command = undefined,
            .command_len = 0,
            .icon = 0,
        };
        @memset(&item.name, 0);
        @memset(&item.command, 0);
        const name_copy_len = @min(name.len, MAX_ITEM_NAME_LEN);
        @memcpy(item.name[0..name_copy_len], name[0..name_copy_len]);
        item.name_len = @intCast(name_copy_len);
        const cmd_copy_len = @min(command.len, MAX_ITEM_NAME_LEN);
        @memcpy(item.command[0..cmd_copy_len], command[0..cmd_copy_len]);
        item.command_len = @intCast(cmd_copy_len);
        std.debug.assert(item.name_len > 0);
        return item;
    }
};

// Desktop shell: status bar and launcher.
pub const DesktopShell = struct {
    renderer: *const framebuffer_renderer.FramebufferRenderer,
    font: font_renderer.FontRenderer,
    output_width: u32,
    output_height: u32,
    launcher_items: [MAX_LAUNCHER_ITEMS]LauncherItem,
    launcher_items_len: u32,
    launcher_visible: bool,
    current_workspace_id: u32,
    app_registry: ?*application.ApplicationRegistry,
    current_time_seconds: u64, // Current time in seconds since epoch

    pub fn init(
        renderer: *const framebuffer_renderer.FramebufferRenderer,
        output_width: u32,
        output_height: u32,
    ) DesktopShell {
        std.debug.assert(@intFromPtr(renderer) != 0);
        std.debug.assert(output_width > 0);
        std.debug.assert(output_height > 0);
        var shell = DesktopShell{
            .renderer = renderer,
            .font = font_renderer.FontRenderer.init(renderer),
            .output_width = output_width,
            .output_height = output_height,
            .launcher_items = undefined,
            .launcher_items_len = 0,
            .launcher_visible = false,
            .current_workspace_id = 1,
            .app_registry = null,
            .current_time_seconds = 0, // Will be updated by update_time
        };
        // Initialize launcher items array.
        var i: u32 = 0;
        while (i < MAX_LAUNCHER_ITEMS) : (i += 1) {
            shell.launcher_items[i] = LauncherItem.init("", "");
        }
        // Add default launcher items.
        _ = shell.add_launcher_item("Terminal", "terminal");
        _ = shell.add_launcher_item("Editor", "editor");
        _ = shell.add_launcher_item("Browser", "browser");
        std.debug.assert(shell.launcher_items_len > 0);
        return shell;
    }

    // Add item to launcher.
    pub fn add_launcher_item(self: *DesktopShell, name: []const u8,
command: []const u8) bool {
        std.debug.assert(name.len > 0);
        std.debug.assert(command.len > 0);
        if (self.launcher_items_len >= MAX_LAUNCHER_ITEMS) return false;
        self.launcher_items[self.launcher_items_len] =
LauncherItem.init(name, command);
        self.launcher_items_len += 1;
        std.debug.assert(self.launcher_items_len <= MAX_LAUNCHER_ITEMS);
        return true;
    }

    // Toggle launcher visibility.
    pub fn toggle_launcher(self: *DesktopShell) void {
        self.launcher_visible = !self.launcher_visible;
    }

    // Set current workspace ID.
    pub fn set_current_workspace(self: *DesktopShell, workspace_id: u32)
void {
        std.debug.assert(workspace_id > 0);
        self.current_workspace_id = workspace_id;
    }

    // Set application registry for launcher integration.
    pub fn set_app_registry(self: *DesktopShell, registry:
*application.ApplicationRegistry) void {
        std.debug.assert(@intFromPtr(registry) != 0);
        self.app_registry = registry;
        // Sync launcher items with registered applications.
        self.sync_launcher_items();
    }

    // Sync launcher items with registered applications.
    pub fn sync_launcher_items(self: *DesktopShell) void {
        if (self.app_registry) |registry| {
            self.launcher_items_len = 0;
            const visible_apps = registry.get_visible_applications();
            var i: u32 = 0;
            while (i < visible_apps.len and self.launcher_items_len <
MAX_LAUNCHER_ITEMS) : (i += 1) {
                const app = visible_apps.apps[i];
                const name_slice = app.name[0..app.name_len];
                const cmd_slice = app.command[0..app.command_len];
                self.launcher_items[self.launcher_items_len] =
LauncherItem.init(name_slice, cmd_slice);
                self.launcher_items_len += 1;
            }
            std.debug.assert(self.launcher_items_len <=
MAX_LAUNCHER_ITEMS);
        }
    }

    // Check if point is in launcher item area.
    pub fn get_launcher_item_at(
        self: *const DesktopShell,
        x: u32,
        y: u32,
    ) ?u32 {
        if (!self.launcher_visible) return null;
        std.debug.assert(x < self.output_width);
        std.debug.assert(y < self.output_height);
        const launcher_x = (self.output_width - LAUNCHER_WIDTH) / 2;
        const launcher_y = (self.output_height - LAUNCHER_HEIGHT) / 2;
        // Check if point is within launcher bounds.
        if (x < launcher_x or x >= launcher_x + LAUNCHER_WIDTH or
            y < launcher_y or y >= launcher_y + LAUNCHER_HEIGHT)
        {
            return null;
        }
        // Calculate item index from y position.
        const item_height: u32 = 32;
        const relative_y = y - launcher_y - 40; // Account for launcher
border/title.
        if (relative_y < 0) return null;
        const item_index = relative_y / item_height;
        if (item_index < self.launcher_items_len) {
            return item_index;
        }
        return null;
    }

    // Render status bar.
    pub fn render_status_bar(self: *const DesktopShell) void {
        std.debug.assert(self.output_width > 0);
        std.debug.assert(self.output_height > 0);
        // Draw status bar background.
        const status_y = self.output_height - STATUS_BAR_HEIGHT;
        self.renderer.draw_rect(
            0,
            @as(i32, @intCast(status_y)),
            self.output_width,
            STATUS_BAR_HEIGHT,
            framebuffer_renderer.COLOR_DARK_BG,
        );
        // Draw workspace indicator (simple rectangle for now).
        const workspace_x: u32 = 10;
        const workspace_y: u32 = status_y + 8;
        const workspace_width: u32 = 16;
        const workspace_height: u32 = 16;
        self.renderer.draw_rect(
            @as(i32, @intCast(workspace_x)),
            @as(i32, @intCast(workspace_y)),
            workspace_width,
            workspace_height,
            framebuffer_renderer.COLOR_BLUE,
        );
        // Draw time (right-aligned).
        self.draw_time(status_y);
    }

    // Update current time (called periodically).
    // 2025-11-25-005738-pst: Active function
    pub fn update_time(self: *DesktopShell, time_seconds: u64) void {
        self.current_time_seconds = time_seconds;
    }

    // Draw time in status bar (right-aligned).
    // 2025-11-26-130343-pst: Active function (updated to use font
renderer)
    fn draw_time(self: *const DesktopShell, status_y: u32) void {
        // Format time as HH:MM:SS.
        const hours = @as(u32, @intCast((self.current_time_seconds /
3600) % 24));
        const minutes = @as(u32, @intCast((self.current_time_seconds /
60) % 60));
        const seconds = @as(u32, @intCast(self.current_time_seconds %
60));
        // Format time string.
        var time_buf: [9]u8 = undefined;
        const time_str = std.fmt.bufPrint(
            &time_buf,
            "{d:0>2}:{d:0>2}:{d:0>2}",
            .{ hours, minutes, seconds },
        ) catch return;
        // Calculate right-aligned position.
        const time_width = @as(u32, @intCast(time_str.len)) *
font_renderer.FONT_WIDTH;
        const time_x = if (self.output_width > time_width)
            self.output_width - time_width - 8
        else
            8;
        const time_y = status_y + 8;
        // Draw time using font renderer.
        self.font.draw_text(
            time_str,
            time_x,
            time_y,
            framebuffer_renderer.COLOR_WHITE,
        );
    }

    // Draw a single digit (0-9) as simple rectangles.
    // 2025-11-25-005738-pst: Active function
    fn draw_digit(self: *const DesktopShell, x: u32, y: u32, digit: u32)
void {
        std.debug.assert(digit < 10);
        // Simple 7-segment style: draw segments as rectangles.
        const segment_width: u32 = 8;
        const segment_height: u32 = 2;
        // Top segment.
        if (digit != 1 and digit != 4) {
            self.renderer.draw_rect(
                @as(i32, @intCast(x + 1)),
                @as(i32, @intCast(y)),
                segment_width,
                segment_height,
                framebuffer_renderer.COLOR_WHITE,
            );
        }
        // Middle segment.
        if (digit != 0 and digit != 1 and digit != 7) {
            self.renderer.draw_rect(
                @as(i32, @intCast(x + 1)),
                @as(i32, @intCast(y + 6)),
                segment_width,
                segment_height,
                framebuffer_renderer.COLOR_WHITE,
            );
        }
        // Bottom segment.
        if (digit != 1 and digit != 4 and digit != 7) {
            self.renderer.draw_rect(
                @as(i32, @intCast(x + 1)),
                @as(i32, @intCast(y + 12)),
                segment_width,
                segment_height,
                framebuffer_renderer.COLOR_WHITE,
            );
        }
    }

    // Render launcher.
    pub fn render_launcher(self: *const DesktopShell) void {
        if (!self.launcher_visible) return;
        std.debug.assert(self.output_width > 0);
        std.debug.assert(self.output_height > 0);
        // Draw launcher background.
        const launcher_x = (self.output_width - LAUNCHER_WIDTH) / 2;
        const launcher_y = (self.output_height - LAUNCHER_HEIGHT) / 2;
        self.renderer.draw_rect(
            @as(i32, @intCast(launcher_x)),
            @as(i32, @intCast(launcher_y)),
            LAUNCHER_WIDTH,
            LAUNCHER_HEIGHT,
            framebuffer_renderer.COLOR_DARK_BG,
        );
        // Draw launcher border.
        self.renderer.draw_rect(
            @as(i32, @intCast(launcher_x)),
            @as(i32, @intCast(launcher_y)),
            LAUNCHER_WIDTH,
            2,
            framebuffer_renderer.COLOR_WHITE,
        );
        // Draw launcher items.
        self.draw_launcher_items(launcher_x, launcher_y);
    }

    // Draw launcher items list.
    // 2025-11-25-005738-pst: Active function
    fn draw_launcher_items(self: *const DesktopShell, launcher_x: u32,
launcher_y: u32) void {
        const item_height: u32 = 32;
        const item_padding: u32 = 8;
        var y_offset: u32 = item_padding + 2; // Start below border
        var i: u32 = 0;
        while (i < self.launcher_items_len and y_offset + item_height <
LAUNCHER_HEIGHT) : (i += 1) {
            const item = self.launcher_items[i];
            if (item.name_len == 0) continue;
            // Draw item background (highlight on hover would go here).
            const item_y = launcher_y + y_offset;
            self.renderer.draw_rect(
                @as(i32, @intCast(launcher_x + item_padding)),
                @as(i32, @intCast(item_y)),
                LAUNCHER_WIDTH - (item_padding * 2),
                item_height,
                framebuffer_renderer.COLOR_DARK_BG,
            );
            // Draw item name using font renderer.
            const name_x = launcher_x + item_padding + 4;
            const name_y = item_y + 8;
            const name_slice = item.name[0..item.name_len];
            self.font.draw_text(
                name_slice,
                name_x,
                name_y,
                framebuffer_renderer.COLOR_WHITE,
            );
            y_offset += item_height + item_padding;
        }
    }

    // Render desktop shell (status bar and launcher).
    pub fn render(self: *const DesktopShell) void {
        self.render_status_bar();
        self.render_launcher();
    }
};


// === grain_core/display_management.zig ===

//! Grain OS Display Management: Multi-monitor support and display
configuration.
//!
//! Why: Provide multi-monitor support and display configuration
management.
//! Architecture: Display detection, configuration, layout management.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max displays.
pub const MAX_DISPLAYS: u32 = 8;

// Bounded: Max display name length.
pub const MAX_DISPLAY_NAME_LEN: u32 = 64;

// Display connection type.
pub const DisplayConnection = enum(u8) {
    unknown,
    internal,
    hdmi,
    displayport,
    vga,
    dvi,
    usb_c,
};

// Display state.
pub const DisplayState = enum(u8) {
    disconnected,
    connected,
    active,
    disabled,
};

// Display: represents a physical display.
pub const Display = struct {
    display_id: u32,
    name: [MAX_DISPLAY_NAME_LEN]u8,
    name_len: u32,
    width: u32,
    height: u32,
    x: i32,
    y: i32,
    connection: DisplayConnection,
    state: DisplayState,
    primary: bool,
    active: bool,

    pub fn init() Display {
        var display = Display{
            .display_id = 0,
            .name = undefined,
            .name_len = 0,
            .width = 0,
            .height = 0,
            .x = 0,
            .y = 0,
            .connection = DisplayConnection.unknown,
            .state = DisplayState.disconnected,
            .primary = false,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_DISPLAY_NAME_LEN) : (i += 1) {
            display.name[i] = 0;
        }
        return display;
    }
};

// Display manager: manages multiple displays.
pub const DisplayManager = struct {
    displays: [MAX_DISPLAYS]Display,
    displays_len: u32,
    next_display_id: u32,
    primary_display_id: u32,

    pub fn init() DisplayManager {
        var manager = DisplayManager{
            .displays = undefined,
            .displays_len = 0,
            .next_display_id = 1,
            .primary_display_id = 0,
        };
        var i: u32 = 0;
        while (i < MAX_DISPLAYS) : (i += 1) {
            manager.displays[i] = Display.init();
        }
        return manager;
    }

    // Add display.
    pub fn add_display(
        self: *DisplayManager,
        name: []const u8,
        width: u32,
        height: u32,
        connection: DisplayConnection,
    ) ?u32 {
        if (self.displays_len >= MAX_DISPLAYS) {
            return null;
        }
        if (name.len > MAX_DISPLAY_NAME_LEN) {
            return null;
        }
        const display_id = self.next_display_id;
        self.next_display_id += 1;
        self.displays[self.displays_len] = Display.init();
        self.displays[self.displays_len].display_id = display_id;
        self.displays[self.displays_len].width = width;
        self.displays[self.displays_len].height = height;
        self.displays[self.displays_len].connection = connection;
        self.displays[self.displays_len].state = DisplayState.connected;
        self.displays[self.displays_len].active = true;
        var i: u32 = 0;
        while (i < MAX_DISPLAY_NAME_LEN) : (i += 1) {
            self.displays[self.displays_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_DISPLAY_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.displays[self.displays_len].name[i] = name[i];
        }
        self.displays[self.displays_len].name_len = @intCast(name_len);
        if (self.primary_display_id == 0) {
            self.primary_display_id = display_id;
            self.displays[self.displays_len].primary = true;
        }
        self.displays_len += 1;
        return display_id;
    }

    // Find display by ID.
    pub fn find_display(
        self: *DisplayManager,
        display_id: u32,
    ) ?*Display {
        std.debug.assert(display_id > 0);
        var i: u32 = 0;
        while (i < self.displays_len) : (i += 1) {
            if (self.displays[i].display_id == display_id) {
                return &self.displays[i];
            }
        }
        return null;
    }

    // Remove display.
    pub fn remove_display(self: *DisplayManager, display_id: u32) bool {
        std.debug.assert(display_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.displays_len) : (i += 1) {
            if (self.displays[i].display_id == display_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        const was_primary = self.displays[i].primary;
        // Shift remaining displays left.
        while (i < self.displays_len - 1) : (i += 1) {
            self.displays[i] = self.displays[i + 1];
        }
        self.displays_len -= 1;
        if (was_primary and self.displays_len > 0) {
            self.primary_display_id = self.displays[0].display_id;
            self.displays[0].primary = true;
        } else if (self.displays_len == 0) {
            self.primary_display_id = 0;
        }
        return true;
    }

    // Set display position.
    pub fn set_display_position(
        self: *DisplayManager,
        display_id: u32,
        x: i32,
        y: i32,
    ) bool {
        std.debug.assert(display_id > 0);
        if (self.find_display(display_id)) |display| {
            display.x = x;
            display.y = y;
            return true;
        }
        return false;
    }

    // Set display as primary.
    pub fn set_primary_display(self: *DisplayManager, display_id: u32)
bool {
        std.debug.assert(display_id > 0);
        if (self.find_display(display_id)) |display| {
            // Clear primary flag from all displays.
            var i: u32 = 0;
            while (i < self.displays_len) : (i += 1) {
                self.displays[i].primary = false;
            }
            display.primary = true;
            self.primary_display_id = display_id;
            return true;
        }
        return false;
    }

    // Enable display.
    pub fn enable_display(self: *DisplayManager, display_id: u32) bool {
        std.debug.assert(display_id > 0);
        if (self.find_display(display_id)) |display| {
            display.active = true;
            display.state = DisplayState.active;
            return true;
        }
        return false;
    }

    // Disable display.
    pub fn disable_display(self: *DisplayManager, display_id: u32) bool {
        std.debug.assert(display_id > 0);
        if (self.find_display(display_id)) |display| {
            display.active = false;
            display.state = DisplayState.disconnected;
            return true;
        }
        return false;
    }

    // Get primary display.
    pub fn get_primary_display(self: *const DisplayManager) ?*const
Display {
        if (self.primary_display_id == 0) {
            return null;
        }
        var i: u32 = 0;
        while (i < self.displays_len) : (i += 1) {
            if (self.displays[i].display_id == self.primary_display_id) {
                return &self.displays[i];
            }
        }
        return null;
    }

    // Get display count.
    pub fn get_display_count(self: *const DisplayManager) u32 {
        return self.displays_len;
    }

    // Get active display count.
    pub fn get_active_display_count(self: *const DisplayManager) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.displays_len) : (i += 1) {
            if (self.displays[i].active) {
                count += 1;
            }
        }
        return count;
    }
};


// === grain_core/dns_resolver.zig ===

//! Grain Core DNS Resolver: DNS query and caching support.
//!
//! Why: Provide DNS resolution for API clients and network services.
//! Architecture: DNS query (A, AAAA, MX), bounded cache, error handling.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");
const network_stack = @import("network_stack.zig");

// Bounded: Max DNS cache entries.
pub const MAX_DNS_CACHE_ENTRIES: u32 = 256;

// Bounded: Max hostname length.
pub const MAX_HOSTNAME_LEN: u32 = 255;

// Bounded: Max IP address length (IPv6).
pub const MAX_IP_ADDRESS_LEN: u32 = 16;

// Bounded: Max DNS response size.
pub const MAX_DNS_RESPONSE_SIZE: u32 = 512;

// Bounded: DNS query timeout (milliseconds).
pub const DNS_QUERY_TIMEOUT: u64 = 5000;

// DNS record type.
pub const DnsRecordType = enum(u16) {
    a = 1,
    aaaa = 28,
    mx = 15,
};

// DNS cache entry.
pub const DnsCacheEntry = struct {
    hostname: [MAX_HOSTNAME_LEN]u8,
    hostname_len: u32,
    record_type: DnsRecordType,
    ip_address: [MAX_IP_ADDRESS_LEN]u8,
    ip_address_len: u32,
    cached_at: u64,
    expires_at: u64,
    active: bool,

    pub fn init() DnsCacheEntry {
        var entry = DnsCacheEntry{
            .hostname = undefined,
            .hostname_len = 0,
            .record_type = DnsRecordType.a,
            .ip_address = undefined,
            .ip_address_len = 0,
            .cached_at = 0,
            .expires_at = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_HOSTNAME_LEN) : (i += 1) {
            entry.hostname[i] = 0;
        }
        i = 0;
        while (i < MAX_IP_ADDRESS_LEN) : (i += 1) {
            entry.ip_address[i] = 0;
        }
        return entry;
    }
};

// DNS resolver: manages DNS queries and caching.
pub const DnsResolver = struct {
    cache: [MAX_DNS_CACHE_ENTRIES]DnsCacheEntry,
    cache_len: u32,
    cache_ttl: u64,

    pub fn init(cache_ttl: u64) DnsResolver {
        std.debug.assert(cache_ttl > 0);
        var resolver = DnsResolver{
            .cache = undefined,
            .cache_len = 0,
            .cache_ttl = cache_ttl,
        };
        var i: u32 = 0;
        while (i < MAX_DNS_CACHE_ENTRIES) : (i += 1) {
            resolver.cache[i] = DnsCacheEntry.init();
        }
        return resolver;
    }

    // Find cache entry by hostname and record type.
    pub fn find_cache_entry(
        self: *DnsResolver,
        hostname: []const u8,
        record_type: DnsRecordType,
        current_time: u64,
    ) ?*DnsCacheEntry {
        std.debug.assert(hostname.len > 0);
        std.debug.assert(hostname.len <= MAX_HOSTNAME_LEN);
        var i: u32 = 0;
        while (i < self.cache_len) : (i += 1) {
            if (!self.cache[i].active) {
                continue;
            }
            if (self.cache[i].record_type != record_type) {
                continue;
            }
            if (self.cache[i].hostname_len != hostname.len) {
                continue;
            }
            const cached_hostname =
self.cache[i].hostname[0..self.cache[i].hostname_len];
            if (!std.mem.eql(u8, cached_hostname, hostname)) {
                continue;
            }
            if (current_time > self.cache[i].expires_at) {
                self.cache[i].active = false;
                continue;
            }
            return &self.cache[i];
        }
        return null;
    }

    // Add cache entry.
    pub fn add_cache_entry(
        self: *DnsResolver,
        hostname: []const u8,
        record_type: DnsRecordType,
        ip_address: []const u8,
        current_time: u64,
    ) bool {
        std.debug.assert(hostname.len > 0);
        std.debug.assert(hostname.len <= MAX_HOSTNAME_LEN);
        std.debug.assert(ip_address.len > 0);
        std.debug.assert(ip_address.len <= MAX_IP_ADDRESS_LEN);
        if (self.cache_len >= MAX_DNS_CACHE_ENTRIES) {
            return false;
        }
        const hostname_len = @min(hostname.len, MAX_HOSTNAME_LEN);
        var i: u32 = 0;
        while (i < MAX_HOSTNAME_LEN) : (i += 1) {
            self.cache[self.cache_len].hostname[i] = 0;
        }
        i = 0;
        while (i < hostname_len) : (i += 1) {
            self.cache[self.cache_len].hostname[i] = hostname[i];
        }
        self.cache[self.cache_len].hostname_len = hostname_len;
        self.cache[self.cache_len].record_type = record_type;
        const ip_len = @min(ip_address.len, MAX_IP_ADDRESS_LEN);
        i = 0;
        while (i < MAX_IP_ADDRESS_LEN) : (i += 1) {
            self.cache[self.cache_len].ip_address[i] = 0;
        }
        i = 0;
        while (i < ip_len) : (i += 1) {
            self.cache[self.cache_len].ip_address[i] = ip_address[i];
        }
        self.cache[self.cache_len].ip_address_len = ip_len;
        self.cache[self.cache_len].cached_at = current_time;
        self.cache[self.cache_len].expires_at = current_time +
self.cache_ttl;
        self.cache[self.cache_len].active = true;
        self.cache_len += 1;
        return true;
    }

    // Clear expired cache entries.
    pub fn clear_expired_cache(self: *DnsResolver, current_time: u64)
u32 {
        var cleared_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.cache_len) : (i += 1) {
            if (!self.cache[i].active) {
                continue;
            }
            if (current_time > self.cache[i].expires_at) {
                self.cache[i].active = false;
                cleared_count += 1;
            }
        }
        return cleared_count;
    }

    // Resolve hostname to IP address (stub - requires network
implementation).
    pub fn resolve_hostname(
        self: *DnsResolver,
        hostname: []const u8,
        record_type: DnsRecordType,
        current_time: u64,
        ip_out: []u8,
    ) bool {
        std.debug.assert(hostname.len > 0);
        std.debug.assert(hostname.len <= MAX_HOSTNAME_LEN);
        std.debug.assert(ip_out.len >= MAX_IP_ADDRESS_LEN);
        if (self.find_cache_entry(hostname, record_type, current_time))
|entry| {
            const ip_len = @min(entry.ip_address_len, ip_out.len);
            var i: u32 = 0;
            while (i < ip_len) : (i += 1) {
                ip_out[i] = entry.ip_address[i];
            }
            return true;
        }
        _ = current_time;
        return false;
    }
};


// === grain_core/file_manager.zig ===

//! Grain OS File Manager: File and directory management.
//!
//! Why: Provide file management functionality for file operations.
//! Architecture: File metadata, directory navigation, file operations.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max files in directory.
pub const MAX_FILES: u32 = 512;

// Bounded: Max file path length.
pub const MAX_PATH_LEN: u32 = 512;

// Bounded: Max file name length.
pub const MAX_NAME_LEN: u32 = 256;

// File type.
pub const FileType = enum(u8) {
    unknown,
    regular,
    directory,
    symlink,
    device,
    socket,
    fifo,
};

// File entry: represents a file or directory.
pub const FileEntry = struct {
    entry_id: u32,
    name: [MAX_NAME_LEN]u8,
    name_len: u32,
    path: [MAX_PATH_LEN]u8,
    path_len: u32,
    file_type: FileType,
    size: u64,
    modified_time: u64,
    active: bool,

    pub fn init() FileEntry {
        var entry = FileEntry{
            .entry_id = 0,
            .name = undefined,
            .name_len = 0,
            .path = undefined,
            .path_len = 0,
            .file_type = FileType.unknown,
            .size = 0,
            .modified_time = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_NAME_LEN) : (i += 1) {
            entry.name[i] = 0;
        }
        i = 0;
        while (i < MAX_PATH_LEN) : (i += 1) {
            entry.path[i] = 0;
        }
        return entry;
    }
};

// File manager: manages file operations.
pub const FileManager = struct {
    files: [MAX_FILES]FileEntry,
    files_len: u32,
    next_entry_id: u32,
    current_directory: [MAX_PATH_LEN]u8,
    current_directory_len: u32,

    pub fn init() FileManager {
        var manager = FileManager{
            .files = undefined,
            .files_len = 0,
            .next_entry_id = 1,
            .current_directory = undefined,
            .current_directory_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_FILES) : (i += 1) {
            manager.files[i] = FileEntry.init();
        }
        i = 0;
        while (i < MAX_PATH_LEN) : (i += 1) {
            manager.current_directory[i] = 0;
        }
        const root_path = "/";
        i = 0;
        while (i < root_path.len) : (i += 1) {
            manager.current_directory[i] = root_path[i];
        }
        manager.current_directory_len = @intCast(root_path.len);
        return manager;
    }

    // Add file entry.
    pub fn add_file_entry(
        self: *FileManager,
        name: []const u8,
        path: []const u8,
        file_type: FileType,
        size: u64,
        modified_time: u64,
    ) ?u32 {
        if (self.files_len >= MAX_FILES) {
            return null;
        }
        if (name.len > MAX_NAME_LEN) {
            return null;
        }
        if (path.len > MAX_PATH_LEN) {
            return null;
        }
        const entry_id = self.next_entry_id;
        self.next_entry_id += 1;
        self.files[self.files_len] = FileEntry.init();
        self.files[self.files_len].entry_id = entry_id;
        self.files[self.files_len].file_type = file_type;
        self.files[self.files_len].size = size;
        self.files[self.files_len].modified_time = modified_time;
        self.files[self.files_len].active = true;
        var i: u32 = 0;
        while (i < MAX_NAME_LEN) : (i += 1) {
            self.files[self.files_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.files[self.files_len].name[i] = name[i];
        }
        self.files[self.files_len].name_len = @intCast(name_len);
        i = 0;
        while (i < MAX_PATH_LEN) : (i += 1) {
            self.files[self.files_len].path[i] = 0;
        }
        const path_len = @min(path.len, MAX_PATH_LEN);
        i = 0;
        while (i < path_len) : (i += 1) {
            self.files[self.files_len].path[i] = path[i];
        }
        self.files[self.files_len].path_len = @intCast(path_len);
        self.files_len += 1;
        return entry_id;
    }

    // Find file entry by ID.
    pub fn find_file_entry(
        self: *FileManager,
        entry_id: u32,
    ) ?*FileEntry {
        std.debug.assert(entry_id > 0);
        var i: u32 = 0;
        while (i < self.files_len) : (i += 1) {
            if (self.files[i].entry_id == entry_id and
self.files[i].active) {
                return &self.files[i];
            }
        }
        return null;
    }

    // Find file entry by path.
    pub fn find_file_entry_by_path(
        self: *FileManager,
        path: []const u8,
    ) ?*FileEntry {
        var i: u32 = 0;
        while (i < self.files_len) : (i += 1) {
            if (self.files[i].active) {
                const file_path =
self.files[i].path[0..self.files[i].path_len];
                if (std.mem.eql(u8, file_path, path)) {
                    return &self.files[i];
                }
            }
        }
        return null;
    }

    // Set current directory.
    pub fn set_current_directory(self: *FileManager, path: []const u8)
bool {
        if (path.len > MAX_PATH_LEN) {
            return false;
        }
        var i: u32 = 0;
        while (i < MAX_PATH_LEN) : (i += 1) {
            self.current_directory[i] = 0;
        }
        const path_len = @min(path.len, MAX_PATH_LEN);
        i = 0;
        while (i < path_len) : (i += 1) {
            self.current_directory[i] = path[i];
        }
        self.current_directory_len = @intCast(path_len);
        return true;
    }

    // Get current directory.
    pub fn get_current_directory(self: *const FileManager) []const u8 {
        return self.current_directory[0..self.current_directory_len];
    }

    // Remove file entry.
    pub fn remove_file_entry(self: *FileManager, entry_id: u32) bool {
        std.debug.assert(entry_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.files_len) : (i += 1) {
            if (self.files[i].entry_id == entry_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining entries left.
        while (i < self.files_len - 1) : (i += 1) {
            self.files[i] = self.files[i + 1];
        }
        self.files_len -= 1;
        return true;
    }

    // Clear all file entries.
    pub fn clear_all(self: *FileManager) void {
        self.files_len = 0;
    }

    // Get file count.
    pub fn get_file_count(self: *const FileManager) u32 {
        return self.files_len;
    }
};


// === grain_core/file_storage.zig ===

//! Grain Core File Storage: Database file format and storage management.
//!
//! Why: Provide file-based storage for database persistence (Silo
Agent).
//! Architecture: Page-based storage, file locking, integrity checks,
WAL support.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");

// Bounded: Max file size (1TB).
pub const MAX_FILE_SIZE: u64 = 1024 * 1024 * 1024 * 1024;

// Bounded: Page size (4KB).
pub const PAGE_SIZE: u32 = 4096;

// Bounded: Max pages per file.
pub const MAX_PAGES: u32 = MAX_FILE_SIZE / PAGE_SIZE;

// Bounded: Max filename length.
pub const MAX_FILENAME_LEN: u32 = 256;

// Bounded: Max file handles.
pub const MAX_FILE_HANDLES: u32 = 128;

// Bounded: Checksum size (SHA-256).
pub const CHECKSUM_SIZE: u32 = 32;

// File storage mode.
pub const FileMode = enum(u8) {
    read_only,
    read_write,
    create,
};

// File handle state.
pub const FileHandleState = enum(u8) {
    closed,
    open,
    locked,
    error_state,
};

// Database file header.
pub const DatabaseFileHeader = struct {
    magic: [4]u8,
    version: u32,
    page_size: u32,
    total_pages: u32,
    checksum: [CHECKSUM_SIZE]u8,
    created_at: u64,
    updated_at: u64,

    pub fn init() DatabaseFileHeader {
        var header = DatabaseFileHeader{
            .magic = undefined,
            .version = 1,
            .page_size = PAGE_SIZE,
            .total_pages = 0,
            .checksum = undefined,
            .created_at = 0,
            .updated_at = 0,
        };
        const magic_str = "GDBF";
        var i: u32 = 0;
        while (i < 4) : (i += 1) {
            header.magic[i] = magic_str[i];
        }
        i = 0;
        while (i < CHECKSUM_SIZE) : (i += 1) {
            header.checksum[i] = 0;
        }
        return header;
    }

    pub fn validate(self: *const DatabaseFileHeader) bool {
        const expected_magic = "GDBF";
        var i: u32 = 0;
        while (i < 4) : (i += 1) {
            if (self.magic[i] != expected_magic[i]) {
                return false;
            }
        }
        if (self.version == 0) {
            return false;
        }
        if (self.page_size != PAGE_SIZE) {
            return false;
        }
        if (self.total_pages > MAX_PAGES) {
            return false;
        }
        return true;
    }
};

// File page.
pub const FilePage = struct {
    page_id: u32,
    data: [PAGE_SIZE]u8,
    checksum: [CHECKSUM_SIZE]u8,
    is_dirty: bool,

    pub fn init(page_id: u32) FilePage {
        std.debug.assert(page_id < MAX_PAGES);
        var page = FilePage{
            .page_id = page_id,
            .data = undefined,
            .checksum = undefined,
            .is_dirty = false,
        };
        var i: u32 = 0;
        while (i < PAGE_SIZE) : (i += 1) {
            page.data[i] = 0;
        }
        i = 0;
        while (i < CHECKSUM_SIZE) : (i += 1) {
            page.checksum[i] = 0;
        }
        return page;
    }

    pub fn calculate_checksum(self: *FilePage) void {
        var hash: [CHECKSUM_SIZE]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(&self.data, &hash, .{});
        var i: u32 = 0;
        while (i < CHECKSUM_SIZE) : (i += 1) {
            self.checksum[i] = hash[i];
        }
    }

    pub fn verify_checksum(self: *const FilePage) bool {
        var computed: [CHECKSUM_SIZE]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(&self.data, &computed, .{});
        var i: u32 = 0;
        while (i < CHECKSUM_SIZE) : (i += 1) {
            if (computed[i] != self.checksum[i]) {
                return false;
            }
        }
        return true;
    }
};

// File handle.
pub const FileHandle = struct {
    handle_id: u32,
    filename: [MAX_FILENAME_LEN]u8,
    filename_len: u32,
    mode: FileMode,
    state: FileHandleState,
    file_size: u64,
    page_count: u32,
    created_at: u64,
    last_access: u64,
    active: bool,

    pub fn init(handle_id: u32) FileHandle {
        std.debug.assert(handle_id > 0);
        var handle = FileHandle{
            .handle_id = handle_id,
            .filename = undefined,
            .filename_len = 0,
            .mode = FileMode.read_only,
            .state = FileHandleState.closed,
            .file_size = 0,
            .page_count = 0,
            .created_at = 0,
            .last_access = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_FILENAME_LEN) : (i += 1) {
            handle.filename[i] = 0;
        }
        return handle;
    }
};

// File storage manager.
pub const FileStorageManager = struct {
    handles: [MAX_FILE_HANDLES]FileHandle,
    handles_len: u32,
    next_handle_id: u32,

    pub fn init() FileStorageManager {
        var manager = FileStorageManager{
            .handles = undefined,
            .handles_len = 0,
            .next_handle_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_FILE_HANDLES) : (i += 1) {
            manager.handles[i] = FileHandle.init(0);
        }
        return manager;
    }

    // Open file.
    pub fn open_file(
        self: *FileStorageManager,
        filename: []const u8,
        mode: FileMode,
        current_time: u64,
    ) ?*FileHandle {
        std.debug.assert(filename.len > 0);
        std.debug.assert(filename.len <= MAX_FILENAME_LEN);
        if (self.handles_len >= MAX_FILE_HANDLES) {
            return null;
        }
        const handle_id = self.next_handle_id;
        self.next_handle_id += 1;
        self.handles[self.handles_len] = FileHandle.init(handle_id);
        const handle = &self.handles[self.handles_len];
        const filename_len = @min(filename.len, MAX_FILENAME_LEN);
        var i: u32 = 0;
        while (i < MAX_FILENAME_LEN) : (i += 1) {
            handle.filename[i] = 0;
        }
        i = 0;
        while (i < filename_len) : (i += 1) {
            handle.filename[i] = filename[i];
        }
        handle.filename_len = filename_len;
        handle.mode = mode;
        handle.state = FileHandleState.open;
        handle.created_at = current_time;
        handle.last_access = current_time;
        handle.active = true;
        self.handles_len += 1;
        return handle;
    }

    // Close file.
    pub fn close_file(
        self: *FileStorageManager,
        handle_id: u32,
    ) bool {
        std.debug.assert(handle_id > 0);
        var i: u32 = 0;
        while (i < self.handles_len) : (i += 1) {
            if (self.handles[i].handle_id == handle_id) {
                self.handles[i].state = FileHandleState.closed;
                self.handles[i].active = false;
                var j: u32 = i;
                while (j < self.handles_len - 1) : (j += 1) {
                    self.handles[j] = self.handles[j + 1];
                }
                self.handles_len -= 1;
                return true;
            }
        }
        return false;
    }

    // Find file handle by ID.
    pub fn find_handle(
        self: *FileStorageManager,
        handle_id: u32,
    ) ?*FileHandle {
        std.debug.assert(handle_id > 0);
        var i: u32 = 0;
        while (i < self.handles_len) : (i += 1) {
            if (self.handles[i].handle_id == handle_id) {
                return &self.handles[i];
            }
        }
        return null;
    }

    // Lock file.
    pub fn lock_file(
        self: *FileStorageManager,
        handle_id: u32,
    ) bool {
        std.debug.assert(handle_id > 0);
        if (self.find_handle(handle_id)) |handle| {
            if (handle.state == FileHandleState.open) {
                handle.state = FileHandleState.locked;
                return true;
            }
        }
        return false;
    }

    // Unlock file.
    pub fn unlock_file(
        self: *FileStorageManager,
        handle_id: u32,
    ) bool {
        std.debug.assert(handle_id > 0);
        if (self.find_handle(handle_id)) |handle| {
            if (handle.state == FileHandleState.locked) {
                handle.state = FileHandleState.open;
                return true;
            }
        }
        return false;
    }
};


