// Font renderer: renders text using bitmap font.
pub const FontRenderer = struct {
    renderer: *const framebuffer_renderer.FramebufferRenderer,

    pub fn init(renderer: *const
framebuffer_renderer.FramebufferRenderer) FontRenderer {
        std.debug.assert(@intFromPtr(renderer) != 0);
        return FontRenderer{
            .renderer = renderer,
        };
    }

    // Draw a single character at position (x, y).
    // 2025-11-26-130343-pst: Active function
    pub fn draw_char(
        self: *const FontRenderer,
        ch: u8,
        x: u32,
        y: u32,
        fg_color: u32,
    ) void {
        std.debug.assert(x < framebuffer_renderer.FRAMEBUFFER_WIDTH);
        std.debug.assert(y < framebuffer_renderer.FRAMEBUFFER_HEIGHT);
        // Only render printable ASCII (32-126).
        if (ch < 32 or ch > 126) {
            return;
        }
        const char_index = ch - 32;
        const font_char = FONT_DATA[char_index];
        var row: u32 = 0;
        while (row < FONT_HEIGHT) : (row += 1) {
            const font_row = font_char[row];
            var col: u32 = 0;
            while (col < FONT_WIDTH) : (col += 1) {
                const bit_mask: u8 = @as(u8, 1) << @as(u3, @intCast(7 -
col));
                if (font_row & bit_mask != 0) {
                    const px = x + col;
                    const py = y + row;
                    if (px < framebuffer_renderer.FRAMEBUFFER_WIDTH and
                        py < framebuffer_renderer.FRAMEBUFFER_HEIGHT)
                    {
                        self.renderer.draw_pixel(px, py, fg_color);
                    }
                }
            }
        }
    }

    // Draw text string at position (x, y).
    // 2025-11-26-130343-pst: Active function
    pub fn draw_text(
        self: *const FontRenderer,
        text: []const u8,
        x: u32,
        y: u32,
        fg_color: u32,
    ) void {
        std.debug.assert(text.len > 0);
        std.debug.assert(text.len <= MAX_TEXT_LEN);
        std.debug.assert(x < framebuffer_renderer.FRAMEBUFFER_WIDTH);
        std.debug.assert(y < framebuffer_renderer.FRAMEBUFFER_HEIGHT);
        var char_x = x;
        var i: u32 = 0;
        while (i < text.len) : (i += 1) {
            const ch = text[i];
            self.draw_char(ch, char_x, y, fg_color);
            char_x += FONT_WIDTH;
            // Stop if we would exceed framebuffer width.
            if (char_x + FONT_WIDTH >
framebuffer_renderer.FRAMEBUFFER_WIDTH) {
                break;
            }
        }
    }
};


// === grain_core/framebuffer_renderer.zig ===

//! Grain OS Framebuffer Renderer: Render windows to kernel framebuffer.
//!
//! Why: Render compositor windows using kernel framebuffer syscalls.
//! Architecture: Syscall-based rendering, window compositing.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const basin_kernel = @import("basin_kernel");
const font_renderer = @import("font_renderer.zig");

// Bounded: Max text length for rendering.
pub const MAX_TEXT_LEN: u32 = 256;

// Framebuffer constants (matching kernel/framebuffer.zig).
pub const FRAMEBUFFER_WIDTH: u32 = 1024;
pub const FRAMEBUFFER_HEIGHT: u32 = 768;

// Color constants (32-bit RGBA).
pub const COLOR_BLACK: u32 = 0x00000000;
pub const COLOR_WHITE: u32 = 0xFFFFFFFF;
pub const COLOR_RED: u32 = 0xFF0000FF;
pub const COLOR_GREEN: u32 = 0x00FF00FF;
pub const COLOR_BLUE: u32 = 0x0000FFFF;
pub const COLOR_DARK_BG: u32 = 0x1E1E2EFF;

// Syscall numbers (matching kernel/basin_kernel.zig).
const SYSCALL_FB_CLEAR: u32 = 70;
const SYSCALL_FB_DRAW_PIXEL: u32 = 71;
const SYSCALL_FB_DRAW_TEXT: u32 = 72;

// Syscall function type.
const SyscallFn = *const fn (u32, u64, u64, u64, u64) i64;

// Framebuffer renderer: renders windows to kernel framebuffer.
pub const FramebufferRenderer = struct {
    font: font_renderer.FontRenderer,
    // Syscall function pointer (set by kernel integration).
    syscall_fn: ?SyscallFn = null,

    pub fn init() FramebufferRenderer {
        var renderer = FramebufferRenderer{
            .syscall_fn = null,
            .font = undefined,
        };
        renderer.font = font_renderer.FontRenderer.init(&renderer);
        return renderer;
    }

    pub fn set_syscall_fn(self: *FramebufferRenderer, fn_ptr: SyscallFn)
void {
        std.debug.assert(@intFromPtr(fn_ptr) != 0);
        self.syscall_fn = fn_ptr;
        std.debug.assert(self.syscall_fn != null);
    }

    // Clear framebuffer to background color.
    pub fn clear(self: *const FramebufferRenderer, color: u32) void {
        std.debug.assert(self.syscall_fn != null);
        if (self.syscall_fn) |syscall| {
            const result = syscall(SYSCALL_FB_CLEAR, color, 0, 0, 0);
            std.debug.assert(result == 0);
        }
    }

    // Draw pixel at position.
    pub fn draw_pixel(
        self: *const FramebufferRenderer,
        x: u32,
        y: u32,
        color: u32,
    ) void {
        std.debug.assert(x < FRAMEBUFFER_WIDTH);
        std.debug.assert(y < FRAMEBUFFER_HEIGHT);
        std.debug.assert(self.syscall_fn != null);
        if (self.syscall_fn) |syscall| {
            const result = syscall(SYSCALL_FB_DRAW_PIXEL, x, y, color,
0);
            std.debug.assert(result == 0);
        }
    }

    // Draw filled rectangle.
    pub fn draw_rect(
        self: *const FramebufferRenderer,
        x: i32,
        y: i32,
        width: u32,
        height: u32,
        color: u32,
    ) void {
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        std.debug.assert(@as(u32, @intCast(x)) + width <=
FRAMEBUFFER_WIDTH);
        std.debug.assert(@as(u32, @intCast(y)) + height <=
FRAMEBUFFER_HEIGHT);
        const start_y = if (y < 0) 0 else @as(u32, @intCast(y));
        const end_y = if (@as(u32, @intCast(y)) + height >
FRAMEBUFFER_HEIGHT)
            FRAMEBUFFER_HEIGHT
        else
            @as(u32, @intCast(y)) + height;
        var py: u32 = start_y;
        while (py < end_y) : (py += 1) {
            const start_x = if (x < 0) 0 else @as(u32, @intCast(x));
            const end_x = if (@as(u32, @intCast(x)) + width >
FRAMEBUFFER_WIDTH)
                FRAMEBUFFER_WIDTH
            else
                @as(u32, @intCast(x)) + width;
            var px: u32 = start_x;
            while (px < end_x) : (px += 1) {
                self.draw_pixel(px, py, color);
            }
        }
    }

    // Draw text string.
    // 2025-11-26-130343-pst: Active function (updated to use font
renderer)
    pub fn draw_text(
        self: *const FramebufferRenderer,
        text: []const u8,
        x: u32,
        y: u32,
        fg_color: u32,
    ) void {
        std.debug.assert(text.len > 0);
        std.debug.assert(text.len <= MAX_TEXT_LEN);
        std.debug.assert(x < FRAMEBUFFER_WIDTH);
        std.debug.assert(y < FRAMEBUFFER_HEIGHT);
        std.debug.assert(self.syscall_fn != null);
        // Use font renderer to draw text.
        self.font.draw_text(text, x, y, fg_color);
    }
};


// === grain_core/health_monitor.zig ===

//! Grain OS Health Monitor: System health monitoring and reporting.
//!
//! Why: Provide system health monitoring for overall system status.
//! Architecture: Health checks, health status, health reporting.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max health checks.
pub const MAX_HEALTH_CHECKS: u32 = 32;

// Bounded: Max health check name length.
pub const MAX_HEALTH_CHECK_NAME_LEN: u32 = 64;

// Bounded: Max health check message length.
pub const MAX_HEALTH_CHECK_MSG_LEN: u32 = 256;

// Health status.
pub const HealthStatus = enum(u8) {
    healthy,
    warning,
    critical,
    unknown,
};

// Health check: represents a system health check.
pub const HealthCheck = struct {
    check_id: u32,
    name: [MAX_HEALTH_CHECK_NAME_LEN]u8,
    name_len: u32,
    status: HealthStatus,
    message: [MAX_HEALTH_CHECK_MSG_LEN]u8,
    message_len: u32,
    last_check_time: u64,
    active: bool,

    pub fn init() HealthCheck {
        var check = HealthCheck{
            .check_id = 0,
            .name = undefined,
            .name_len = 0,
            .status = HealthStatus.unknown,
            .message = undefined,
            .message_len = 0,
            .last_check_time = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_HEALTH_CHECK_NAME_LEN) : (i += 1) {
            check.name[i] = 0;
        }
        i = 0;
        while (i < MAX_HEALTH_CHECK_MSG_LEN) : (i += 1) {
            check.message[i] = 0;
        }
        return check;
    }
};

// Health monitor: monitors system health.
pub const HealthMonitor = struct {
    checks: [MAX_HEALTH_CHECKS]HealthCheck,
    checks_len: u32,
    next_check_id: u32,
    overall_status: HealthStatus,

    pub fn init() HealthMonitor {
        var monitor = HealthMonitor{
            .checks = undefined,
            .checks_len = 0,
            .next_check_id = 1,
            .overall_status = HealthStatus.unknown,
        };
        var i: u32 = 0;
        while (i < MAX_HEALTH_CHECKS) : (i += 1) {
            monitor.checks[i] = HealthCheck.init();
        }
        return monitor;
    }

    // Add health check.
    pub fn add_health_check(
        self: *HealthMonitor,
        name: []const u8,
    ) ?u32 {
        if (self.checks_len >= MAX_HEALTH_CHECKS) {
            return null;
        }
        if (name.len > MAX_HEALTH_CHECK_NAME_LEN) {
            return null;
        }
        const check_id = self.next_check_id;
        self.next_check_id += 1;
        self.checks[self.checks_len] = HealthCheck.init();
        self.checks[self.checks_len].check_id = check_id;
        self.checks[self.checks_len].status = HealthStatus.unknown;
        self.checks[self.checks_len].active = true;
        var i: u32 = 0;
        while (i < MAX_HEALTH_CHECK_NAME_LEN) : (i += 1) {
            self.checks[self.checks_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_HEALTH_CHECK_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.checks[self.checks_len].name[i] = name[i];
        }
        self.checks[self.checks_len].name_len = @intCast(name_len);
        self.checks_len += 1;
        return check_id;
    }

    // Find health check by ID.
    pub fn find_health_check(
        self: *HealthMonitor,
        check_id: u32,
    ) ?*HealthCheck {
        std.debug.assert(check_id > 0);
        var i: u32 = 0;
        while (i < self.checks_len) : (i += 1) {
            if (self.checks[i].check_id == check_id and
self.checks[i].active) {
                return &self.checks[i];
            }
        }
        return null;
    }

    // Update health check status.
    pub fn update_health_check(
        self: *HealthMonitor,
        check_id: u32,
        status: HealthStatus,
        message: []const u8,
        timestamp: u64,
    ) bool {
        std.debug.assert(check_id > 0);
        if (self.find_health_check(check_id)) |check| {
            check.status = status;
            check.last_check_time = timestamp;
            var i: u32 = 0;
            while (i < MAX_HEALTH_CHECK_MSG_LEN) : (i += 1) {
                check.message[i] = 0;
            }
            const msg_len = @min(message.len, MAX_HEALTH_CHECK_MSG_LEN);
            i = 0;
            while (i < msg_len) : (i += 1) {
                check.message[i] = message[i];
            }
            check.message_len = @intCast(msg_len);
            self.update_overall_status();
            return true;
        }
        return false;
    }

    // Update overall status based on all checks.
    pub fn update_overall_status(self: *HealthMonitor) void {
        var has_critical: bool = false;
        var has_warning: bool = false;
        var has_healthy: bool = false;
        var i: u32 = 0;
        while (i < self.checks_len) : (i += 1) {
            if (self.checks[i].active) {
                switch (self.checks[i].status) {
                    HealthStatus.critical => has_critical = true,
                    HealthStatus.warning => has_warning = true,
                    HealthStatus.healthy => has_healthy = true,
                    HealthStatus.unknown => {},
                }
            }
        }
        if (has_critical) {
            self.overall_status = HealthStatus.critical;
        } else if (has_warning) {
            self.overall_status = HealthStatus.warning;
        } else if (has_healthy) {
            self.overall_status = HealthStatus.healthy;
        } else {
            self.overall_status = HealthStatus.unknown;
        }
    }

    // Remove health check.
    pub fn remove_health_check(self: *HealthMonitor, check_id: u32) bool
{
        std.debug.assert(check_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.checks_len) : (i += 1) {
            if (self.checks[i].check_id == check_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        while (i < self.checks_len - 1) : (i += 1) {
            self.checks[i] = self.checks[i + 1];
        }
        self.checks_len -= 1;
        self.update_overall_status();
        return true;
    }

    // Get overall status.
    pub fn get_overall_status(self: *const HealthMonitor) HealthStatus {
        return self.overall_status;
    }

    // Get health check count.
    pub fn get_health_check_count(self: *const HealthMonitor) u32 {
        return self.checks_len;
    }

    // Get healthy check count.
    pub fn get_healthy_check_count(self: *const HealthMonitor) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.checks_len) : (i += 1) {
            if (self.checks[i].status == HealthStatus.healthy) {
                count += 1;
            }
        }
        return count;
    }

    // Get warning check count.
    pub fn get_warning_check_count(self: *const HealthMonitor) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.checks_len) : (i += 1) {
            if (self.checks[i].status == HealthStatus.warning) {
                count += 1;
            }
        }
        return count;
    }

    // Get critical check count.
    pub fn get_critical_check_count(self: *const HealthMonitor) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.checks_len) : (i += 1) {
            if (self.checks[i].status == HealthStatus.critical) {
                count += 1;
            }
        }
        return count;
    }
};


// === grain_core/http_client.zig ===

//! Grain Core HTTP Client: HTTP client for making external API requests.
//!
//! Why: Enable agents to make HTTP requests to external APIs (Carry,
Silo, etc.).
//! Architecture: HTTP/1.1 client, request building, response parsing,
connection management.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");
const network_stack = @import("network_stack.zig");
const api_server = @import("api_server.zig");
const dns_resolver = @import("dns_resolver.zig");

// Bounded: Max concurrent requests.
pub const MAX_CONCURRENT_REQUESTS: u32 = 32;

// Bounded: Max URL length.
pub const MAX_URL_LEN: u32 = 2048;

// Bounded: Max hostname length.
pub const MAX_HOSTNAME_LEN: u32 = 255;

// Request state.
pub const RequestState = enum(u8) {
    pending,
    connecting,
    sending,
    receiving,
    completed,
    failed,
};

// HTTP client request.
pub const HttpClientRequest = struct {
    request_id: u32,
    method: api_server.HttpMethod,
    url: [MAX_URL_LEN]u8,
    url_len: u32,
    hostname: [MAX_HOSTNAME_LEN]u8,
    hostname_len: u32,
    port: u32,
    path: [api_server.MAX_PATH_LEN]u8,
    path_len: u32,
    headers: [api_server.MAX_HEADERS]api_server.HttpHeader,
    headers_len: u32,
    body: [api_server.MAX_REQUEST_SIZE]u8,
    body_len: u32,
    state: RequestState,
    socket_id: ?u32,
    response: ?api_server.HttpResponse,
    created_at: u64,

    pub fn init(request_id: u32) HttpClientRequest {
        std.debug.assert(request_id > 0);
        var req = HttpClientRequest{
            .request_id = request_id,
            .method = api_server.HttpMethod.get,
            .url = undefined,
            .url_len = 0,
            .hostname = undefined,
            .hostname_len = 0,
            .port = 80,
            .path = undefined,
            .path_len = 0,
            .headers = undefined,
            .headers_len = 0,
            .body = undefined,
            .body_len = 0,
            .state = RequestState.pending,
            .socket_id = null,
            .response = null,
            .created_at = 0,
        };
        var i: u32 = 0;
        while (i < MAX_URL_LEN) : (i += 1) {
            req.url[i] = 0;
        }
        i = 0;
        while (i < MAX_HOSTNAME_LEN) : (i += 1) {
            req.hostname[i] = 0;
        }
        i = 0;
        while (i < api_server.MAX_PATH_LEN) : (i += 1) {
            req.path[i] = 0;
        }
        i = 0;
        while (i < api_server.MAX_REQUEST_SIZE) : (i += 1) {
            req.body[i] = 0;
        }
        std.debug.assert(req.request_id > 0);
        return req;
    }

    pub fn set_url(self: *HttpClientRequest, url: []const u8) bool {
        std.debug.assert(url.len > 0);
        std.debug.assert(url.len <= MAX_URL_LEN);
        const url_len = @min(url.len, MAX_URL_LEN);
        var i: u32 = 0;
        while (i < MAX_URL_LEN) : (i += 1) {
            self.url[i] = 0;
        }
        i = 0;
        while (i < url_len) : (i += 1) {
            self.url[i] = url[i];
        }
        self.url_len = url_len;
        return true;
    }

    pub fn add_header(
        self: *HttpClientRequest,
        name: []const u8,
        value: []const u8,
    ) bool {
        std.debug.assert(name.len > 0);
        std.debug.assert(value.len > 0);
        if (self.headers_len >= api_server.MAX_HEADERS) {
            return false;
        }
        if (name.len > api_server.MAX_HEADER_NAME_LEN) {
            return false;
        }
        if (value.len > api_server.MAX_HEADER_VALUE_LEN) {
            return false;
        }
        var header = api_server.HttpHeader.init();
        var i: u32 = 0;
        const name_len = @min(name.len, api_server.MAX_HEADER_NAME_LEN);
        while (i < name_len) : (i += 1) {
            header.name[i] = name[i];
        }
        header.name_len = @intCast(name_len);
        i = 0;
        const value_len = @min(value.len,
api_server.MAX_HEADER_VALUE_LEN);
        while (i < value_len) : (i += 1) {
            header.value[i] = value[i];
        }
        header.value_len = @intCast(value_len);
        self.headers[self.headers_len] = header;
        self.headers_len += 1;
        return true;
    }
};

// HTTP client manager.
pub const HttpClient = struct {
    requests: [MAX_CONCURRENT_REQUESTS]?HttpClientRequest,
    requests_len: u32,
    next_request_id: u32,
    network_stack: *network_stack.NetworkStack,
    dns_resolver: *dns_resolver.DnsResolver,

    pub fn init(
        net_stack: *network_stack.NetworkStack,
        resolver: *dns_resolver.DnsResolver,
    ) HttpClient {
        std.debug.assert(net_stack != null);
        std.debug.assert(resolver != null);
        var client = HttpClient{
            .requests = undefined,
            .requests_len = 0,
            .next_request_id = 1,
            .network_stack = net_stack,
            .dns_resolver = resolver,
        };
        var i: u32 = 0;
        while (i < MAX_CONCURRENT_REQUESTS) : (i += 1) {
            client.requests[i] = null;
        }
        std.debug.assert(client.requests_len == 0);
        return client;
    }

    pub fn create_request(
        self: *HttpClient,
        method: api_server.HttpMethod,
        url: []const u8,
    ) ?*HttpClientRequest {
        std.debug.assert(url.len > 0);
        if (self.requests_len >= MAX_CONCURRENT_REQUESTS) {
            return null;
        }
        const request_id = self.next_request_id;
        self.next_request_id += 1;
        var req = HttpClientRequest.init(request_id);
        req.method = method;
        if (!req.set_url(url)) {
            return null;
        }
        var i: u32 = 0;
        while (i < MAX_CONCURRENT_REQUESTS) : (i += 1) {
            if (self.requests[i] == null) {
                self.requests[i] = req;
                self.requests_len += 1;
                return &self.requests[i].?;
            }
        }
        return null;
    }

    pub fn find_request(
        self: *HttpClient,
        request_id: u32,
    ) ?*HttpClientRequest {
        std.debug.assert(request_id > 0);
        var i: u32 = 0;
        while (i < MAX_CONCURRENT_REQUESTS) : (i += 1) {
            if (self.requests[i]) |*req| {
                if (req.request_id == request_id) {
                    return req;
                }
            }
        }
        return null;
    }

    pub fn remove_request(
        self: *HttpClient,
        request_id: u32,
    ) bool {
        std.debug.assert(request_id > 0);
        var i: u32 = 0;
        while (i < MAX_CONCURRENT_REQUESTS) : (i += 1) {
            if (self.requests[i]) |*req| {
                if (req.request_id == request_id) {
                    self.requests[i] = null;
                    self.requests_len -= 1;
                    return true;
                }
            }
        }
        return false;
    }

    pub fn get_request_count(self: *const HttpClient) u32 {
        std.debug.assert(self.requests_len <= MAX_CONCURRENT_REQUESTS);
        return self.requests_len;
    }
};


// === grain_core/index_manager.zig ===

//! Grain Core Index Manager: Index file management for database queries.
//!
//! Why: Provide efficient database queries via indexes (Silo Agent).
//! Architecture: B-tree and hash index formats, creation, update,
recovery.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");
const file_storage = @import("file_storage.zig");

// Bounded: Max index entries.
pub const MAX_INDEX_ENTRIES: u32 = 100000;

// Bounded: Max index key size.
pub const MAX_INDEX_KEY_SIZE: u32 = 256;

// Bounded: Max index value size.
pub const MAX_INDEX_VALUE_SIZE: u32 = 1024;

// Bounded: Max indexes per table.
pub const MAX_INDEXES_PER_TABLE: u32 = 8;

// Bounded: Max total indexes.
pub const MAX_TOTAL_INDEXES: u32 = 64;

// Index type.
pub const IndexType = enum(u8) {
    btree,
    hash,
};

// Index entry.
pub const IndexEntry = struct {
    key: [MAX_INDEX_KEY_SIZE]u8,
    key_len: u32,
    value: [MAX_INDEX_VALUE_SIZE]u8,
    value_len: u32,
    record_id: u64,
    timestamp: u64,

    pub fn init() IndexEntry {
        var entry = IndexEntry{
            .key = undefined,
            .key_len = 0,
            .value = undefined,
            .value_len = 0,
            .record_id = 0,
            .timestamp = 0,
        };
        var i: u32 = 0;
        while (i < MAX_INDEX_KEY_SIZE) : (i += 1) {
            entry.key[i] = 0;
        }
        i = 0;
        while (i < MAX_INDEX_VALUE_SIZE) : (i += 1) {
            entry.value[i] = 0;
        }
        return entry;
    }
};

// Index structure.
pub const Index = struct {
    index_id: u32,
    table_id: u32,
    index_type: IndexType,
    name: [64]u8,
    name_len: u32,
    entries: [MAX_INDEX_ENTRIES]IndexEntry,
    entries_len: u32,
    created_at: u64,
    updated_at: u64,
    active: bool,

    pub fn init(index_id: u32, table_id: u32, index_type: IndexType)
Index {
        std.debug.assert(index_id > 0);
        std.debug.assert(table_id > 0);
        var index = Index{
            .index_id = index_id,
            .table_id = table_id,
            .index_type = index_type,
            .name = undefined,
            .name_len = 0,
            .entries = undefined,
            .entries_len = 0,
            .created_at = 0,
            .updated_at = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < 64) : (i += 1) {
            index.name[i] = 0;
        }
        i = 0;
        while (i < MAX_INDEX_ENTRIES) : (i += 1) {
            index.entries[i] = IndexEntry.init();
        }
        return index;
    }

    pub fn set_name(self: *Index, name: []const u8) bool {
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= 64);
        const name_len = @min(name.len, 64);
        var i: u32 = 0;
        while (i < 64) : (i += 1) {
            self.name[i] = 0;
        }
        i = 0;
        while (i < name_len) : (i += 1) {
            self.name[i] = name[i];
        }
        self.name_len = name_len;
        return true;
    }

    pub fn add_entry(
        self: *Index,
        key: []const u8,
        value: []const u8,
        record_id: u64,
        timestamp: u64,
    ) bool {
        std.debug.assert(key.len > 0);
        std.debug.assert(key.len <= MAX_INDEX_KEY_SIZE);
        std.debug.assert(value.len <= MAX_INDEX_VALUE_SIZE);
        std.debug.assert(record_id > 0);
        std.debug.assert(timestamp > 0);
        if (self.entries_len >= MAX_INDEX_ENTRIES) {
            return false;
        }
        const entry = &self.entries[self.entries_len];
        const key_len = @min(key.len, MAX_INDEX_KEY_SIZE);
        var i: u32 = 0;
        while (i < MAX_INDEX_KEY_SIZE) : (i += 1) {
            entry.key[i] = 0;
        }
        i = 0;
        while (i < key_len) : (i += 1) {
            entry.key[i] = key[i];
        }
        entry.key_len = key_len;
        const value_len = @min(value.len, MAX_INDEX_VALUE_SIZE);
        i = 0;
        while (i < MAX_INDEX_VALUE_SIZE) : (i += 1) {
            entry.value[i] = 0;
        }
        i = 0;
        while (i < value_len) : (i += 1) {
            entry.value[i] = value[i];
        }
        entry.value_len = value_len;
        entry.record_id = record_id;
        entry.timestamp = timestamp;
        self.entries_len += 1;
        self.updated_at = timestamp;
        return true;
    }

    pub fn find_entry(
        self: *const Index,
        key: []const u8,
    ) ?*const IndexEntry {
        std.debug.assert(key.len > 0);
        std.debug.assert(key.len <= MAX_INDEX_KEY_SIZE);
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].key_len != key.len) {
                continue;
            }
            var match: bool = true;
            var j: u32 = 0;
            while (j < key.len) : (j += 1) {
                if (self.entries[i].key[j] != key[j]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                return &self.entries[i];
            }
        }
        return null;
    }
};

// Index manager: manages all indexes.
pub const IndexManager = struct {
    indexes: [MAX_INDEXES_PER_TABLE * 32]Index,
    indexes_len: u32,
    next_index_id: u32,

    pub fn init() IndexManager {
        var manager = IndexManager{
            .indexes = undefined,
            .indexes_len = 0,
            .next_index_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_INDEXES_PER_TABLE * 32) : (i += 1) {
            manager.indexes[i] = Index.init(0, 0, IndexType.btree);
        }
        return manager;
    }

    pub fn create_index(
        self: *IndexManager,
        table_id: u32,
        index_type: IndexType,
        name: []const u8,
        timestamp: u64,
    ) ?*Index {
        std.debug.assert(table_id > 0);
        std.debug.assert(name.len > 0);
        std.debug.assert(timestamp > 0);
        if (self.indexes_len >= MAX_TOTAL_INDEXES) {
            return null;
        }
        const index_id = self.next_index_id;
        self.next_index_id += 1;
        self.indexes[self.indexes_len] = Index.init(index_id, table_id,
index_type);
        const index = &self.indexes[self.indexes_len];
        _ = index.set_name(name);
        index.created_at = timestamp;
        index.updated_at = timestamp;
        index.active = true;
        self.indexes_len += 1;
        return index;
    }

    pub fn find_index(
        self: *IndexManager,
        table_id: u32,
        name: []const u8,
    ) ?*Index {
        std.debug.assert(table_id > 0);
        std.debug.assert(name.len > 0);
        var i: u32 = 0;
        while (i < self.indexes_len) : (i += 1) {
            if (self.indexes[i].table_id != table_id) {
                continue;
            }
            if (self.indexes[i].name_len != name.len) {
                continue;
            }
            var match: bool = true;
            var j: u32 = 0;
            while (j < name.len) : (j += 1) {
                if (self.indexes[i].name[j] != name[j]) {
                    match = false;
                    break;
                }
            }
            if (match and self.indexes[i].active) {
                return &self.indexes[i];
            }
        }
        return null;
    }

    pub fn delete_index(
        self: *IndexManager,
        table_id: u32,
        name: []const u8,
    ) bool {
        std.debug.assert(table_id > 0);
        std.debug.assert(name.len > 0);
        if (self.find_index(table_id, name)) |index| {
            index.active = false;
            index.entries_len = 0;
            return true;
        }
        return false;
    }
};


// === grain_core/input_handler.zig ===

//! Grain OS Input Handler: Handle keyboard, mouse, and touch input
events.
//!
//! Why: Process input events from kernel for compositor window
management.
//! Architecture: Syscall-based input reading, event routing to windows.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const basin_kernel = @import("basin_kernel");

// Bounded: Max input event buffer size (32 bytes per event).
pub const MAX_EVENT_SIZE: u32 = 32;

// Syscall number (matching kernel/basin_kernel.zig).
const SYSCALL_READ_INPUT_EVENT: u32 = 60;

// Syscall function type.
const SyscallFn = *const fn (u32, u64, u64, u64, u64) i64;

// Input event types (matching kernel_vm/vm.zig).
pub const EventType = enum(u8) {
    mouse = 0,
    keyboard = 1,
};

// Mouse event kinds (matching kernel_vm/vm.zig).
// 0=down, 1=up, 2=move, 3=drag
pub const MouseEventKind = enum(u8) {
    down = 0,
    up = 1,
    move = 2,
    drag = 3,
};

// Keyboard event kinds (matching kernel_vm/vm.zig).
// 0=down, 1=up
pub const KeyboardEventKind = enum(u8) {
    down = 0,
    up = 1,
};

// Input event: parsed event from kernel.
pub const InputEvent = struct {
    event_type: EventType,
    mouse: struct {
        kind: MouseEventKind,
        button: u8,
        x: u32,
        y: u32,
        modifiers: u8,
    },
    keyboard: struct {
        kind: KeyboardEventKind,
        key_code: u32,
        character: u32,
        modifiers: u8,
    },

    pub fn parse_from_buffer(buf: []const u8) !InputEvent {
        std.debug.assert(buf.len >= MAX_EVENT_SIZE);
        const event_type_val = buf[0];
        const event_type = if (event_type_val == 0)
            EventType.mouse
        else if (event_type_val == 1)
            EventType.keyboard
        else
            return error.InvalidEventType;
        var event = InputEvent{
            .event_type = event_type,
            .mouse = undefined,
            .keyboard = undefined,
        };
        if (event_type == .mouse) {
            event.mouse.kind = @enumFromInt(buf[4]);
            event.mouse.button = buf[5];
            event.mouse.x = std.mem.readInt(u32, buf[6..10], .little);
            event.mouse.y = std.mem.readInt(u32, buf[10..14], .little);
            event.mouse.modifiers = buf[14];
        } else {
            event.keyboard.kind = @enumFromInt(buf[4]);
            event.keyboard.key_code = std.mem.readInt(u32, buf[8..12],
.little);
            event.keyboard.character = std.mem.readInt(u32, buf[12..16],
.little);
            event.keyboard.modifiers = buf[16];
        }
        return event;
    }
};

// Input handler: reads and processes input events.
pub const InputHandler = struct {
    // Syscall function pointer (set by kernel integration).
    syscall_fn: ?SyscallFn = null,
    // Event buffer for reading events.
    event_buf: [MAX_EVENT_SIZE]u8,

    pub fn init() InputHandler {
        var handler = InputHandler{
            .syscall_fn = null,
            .event_buf = undefined,
        };
        var i: u32 = 0;
        while (i < MAX_EVENT_SIZE) : (i += 1) {
            handler.event_buf[i] = 0;
        }
        return handler;
    }

    pub fn set_syscall_fn(
        self: *InputHandler,
        fn_ptr: SyscallFn,
    ) void {
        std.debug.assert(@intFromPtr(fn_ptr) != 0);
        self.syscall_fn = fn_ptr;
        std.debug.assert(self.syscall_fn != null);
    }

    // Read next input event (non-blocking).
    pub fn read_event(self: *InputHandler) !?InputEvent {
        std.debug.assert(self.syscall_fn != null);
        if (self.syscall_fn) |syscall| {
            const event_ptr = @intFromPtr(&self.event_buf);
            const result = syscall(
                SYSCALL_READ_INPUT_EVENT,
                event_ptr,
                0,
                0,
                0,
            );
            if (result < 0) {
                // Error or would_block.
                if (result == -6) {
                    return null; // would_block (no event available).
                }
                return error.SyscallError;
            }
            if (result == 0) {
                return null; // No event.
            }
            // Parse event from buffer.
            const event = try
InputEvent.parse_from_buffer(&self.event_buf);
            return event;
        }
        return error.NoSyscallFn;
    }
};


// === grain_core/json_helpers.zig ===

//! Grain OS JSON Helpers: Bounded JSON parsing and generation for API
server.
//!
//! Why: Provide JSON parsing and generation without dynamic allocation.
//! Architecture: Bounded JSON parsing/generation for request/response
bodies.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");

// Bounded: Max JSON key length.
pub const MAX_JSON_KEY_LEN: u32 = 128;

// Bounded: Max JSON string value length.
pub const MAX_JSON_STRING_LEN: u32 = 4096;

// JSON parse result.
pub const JsonParseResult = struct {
    success: bool,
    value_start: u32,
    value_len: u32,
};

// Find JSON key in object.
pub fn find_json_key(
    json: []const u8,
    key: []const u8,
) ?JsonParseResult {
    std.debug.assert(json.len > 0);
    std.debug.assert(key.len > 0);
    std.debug.assert(key.len <= MAX_JSON_KEY_LEN);
    if (json.len > MAX_JSON_STRING_LEN) {
        return null;
    }
    var i: u32 = 0;
    while (i < json.len) : (i += 1) {
        if (json[i] == '"') {
            i += 1;
            const key_start_pos = i;
            var key_match: bool = true;
            var j: u32 = 0;
            while (j < key.len and i < json.len) : (j += 1) {
                if (json[i] == '\\') {
                    i += 1;
                    if (i >= json.len) {
                        key_match = false;
                        break;
                    }
                }
                if (i >= json.len or json[i] != key[j]) {
                    key_match = false;
                    break;
                }
                i += 1;
            }
            if (key_match and j == key.len and i < json.len and json[i]
== '"') {
                i += 1;
                while (i < json.len and (json[i] == ' ' or json[i] ==
'\t')) : (i += 1) {}
                if (i < json.len and json[i] == ':') {
                    i += 1;
                    while (i < json.len and (json[i] == ' ' or json[i]
== '\t')) : (i += 1) {}
                    if (i < json.len) {
                        const value_start = i;
                        var value_len: u32 = 0;
                        var value_i = i;
                        if (json[value_i] == '"') {
                            value_i += 1;
                            value_len = 1;
                            while (value_i < json.len) : (value_i += 1) {
                                if (json[value_i] == '\\') {
                                    value_i += 1;
                                    value_len += 1;
                                    if (value_i >= json.len) {
                                        break;
                                    }
                                    value_len += 1;
                                } else if (json[value_i] == '"') {
                                    value_len += 1;
                                    break;
                                } else {
                                    value_len += 1;
                                }
                            }
                        } else {
                            while (value_i < json.len and json[value_i]
!= ',' and json[value_i] != '}' and json[value_i] != ']' and
json[value_i] != '\n' and json[value_i] != '\r') : (value_i += 1) {
                                value_len += 1;
                            }
                        }
                        return JsonParseResult{
                            .success = true,
                            .value_start = value_start,
                            .value_len = value_len,
                        };
                    }
                }
            }
            i = key_start_pos;
        }
    }
    return null;
}

// Extract JSON string value (unquoted, unescaped).
pub fn extract_json_string_value(
    json: []const u8,
    result: *JsonParseResult,
    output: []u8,
) ?u32 {
    std.debug.assert(json.len > 0);
    std.debug.assert(output.len > 0);
    if (!result.success) {
        return null;
    }
    if (result.value_start >= json.len) {
        return null;
    }
    if (json[result.value_start] != '"') {
        return null;
    }
    var i: u32 = result.value_start + 1;
    var output_pos: u32 = 0;
    while (i < json.len and i < result.value_start + result.value_len) :
(i += 1) {
        if (json[i] == '"') {
            break;
        }
        if (json[i] == '\\') {
            i += 1;
            if (i >= json.len) {
                return null;
            }
            if (output_pos >= output.len) {
                return null;
            }
            switch (json[i]) {
                'n' => output[output_pos] = '\n',
                'r' => output[output_pos] = '\r',
                't' => output[output_pos] = '\t',
                '\\' => output[output_pos] = '\\',
                '"' => output[output_pos] = '"',
                else => output[output_pos] = json[i],
            }
            output_pos += 1;
        } else {
            if (output_pos >= output.len) {
                return null;
            }
            output[output_pos] = json[i];
            output_pos += 1;
        }
    }
    return output_pos;
}

// Extract JSON number value.
pub fn extract_json_number_value(
    json: []const u8,
    result: *JsonParseResult,
) ?i64 {
    std.debug.assert(json.len > 0);
    if (!result.success) {
        return null;
    }
    if (result.value_start >= json.len) {
        return null;
    }
    var i: u32 = result.value_start;
    var is_negative: bool = false;
    if (json[i] == '-') {
        is_negative = true;
        i += 1;
    }
    if (i >= json.len) {
        return null;
    }
    var num: i64 = 0;
    while (i < json.len and i < result.value_start + result.value_len) :
(i += 1) {
        if (json[i] >= '0' and json[i] <= '9') {
            num = num * 10 + (json[i] - '0');
        } else {
            break;
        }
    }
    if (is_negative) {
        num = -num;
    }
    return num;
}

// Extract JSON boolean value.
pub fn extract_json_bool_value(
    json: []const u8,
    result: *JsonParseResult,
) ?bool {
    std.debug.assert(json.len > 0);
    if (!result.success) {
        return null;
    }
    if (result.value_start >= json.len) {
        return null;
    }
    const value_str = json[result.value_start..result.value_start +
result.value_len];
    if (std.mem.eql(u8, value_str, "true")) {
        return true;
    } else if (std.mem.eql(u8, value_str, "false")) {
        return false;
    }
    return null;
}

// Write JSON string with escaping.
pub fn write_json_string(
    output: []u8,
    output_pos: *u32,
    value: []const u8,
) bool {
    std.debug.assert(output.len > 0);
    std.debug.assert(value.len > 0);
    if (output_pos.* + value.len * 2 + 2 > output.len) {
        return false;
    }
    output[output_pos.*] = '"';
    output_pos.* += 1;
    var i: u32 = 0;
    while (i < value.len) : (i += 1) {
        switch (value[i]) {
            '"' => {
                output[output_pos.*] = '\\';
                output_pos.* += 1;
                output[output_pos.*] = '"';
                output_pos.* += 1;
            },
            '\\' => {
                output[output_pos.*] = '\\';
                output_pos.* += 1;
                output[output_pos.*] = '\\';
                output_pos.* += 1;
            },
            '\n' => {
                output[output_pos.*] = '\\';
                output_pos.* += 1;
                output[output_pos.*] = 'n';
                output_pos.* += 1;
            },
            '\r' => {
                output[output_pos.*] = '\\';
                output_pos.* += 1;
                output[output_pos.*] = 'r';
                output_pos.* += 1;
            },
            '\t' => {
                output[output_pos.*] = '\\';
                output_pos.* += 1;
                output[output_pos.*] = 't';
                output_pos.* += 1;
            },
            else => {
                output[output_pos.*] = value[i];
                output_pos.* += 1;
            },
        }
    }
    output[output_pos.*] = '"';
    output_pos.* += 1;
    return true;
}

// Write JSON number.
pub fn write_json_number(
    output: []u8,
    output_pos: *u32,
    value: i64,
) bool {
    std.debug.assert(output.len > 0);
    if (output_pos.* + 32 > output.len) {
        return false;
    }
    const num_str = std.fmt.bufPrint(
        output[output_pos.*..],
        "{d}",
        .{value},
    ) catch return false;
    output_pos.* += @intCast(num_str.len);
    return true;
}

// Write JSON boolean.
pub fn write_json_bool(
    output: []u8,
    output_pos: *u32,
    value: bool,
) bool {
    std.debug.assert(output.len > 0);
    if (value) {
        if (output_pos.* + 4 > output.len) {
            return false;
        }
        output[output_pos.*] = 't';
        output_pos.* += 1;
        output[output_pos.*] = 'r';
        output_pos.* += 1;
        output[output_pos.*] = 'u';
        output_pos.* += 1;
        output[output_pos.*] = 'e';
        output_pos.* += 1;
    } else {
        if (output_pos.* + 5 > output.len) {
            return false;
        }
        output[output_pos.*] = 'f';
        output_pos.* += 1;
        output[output_pos.*] = 'a';
        output_pos.* += 1;
        output[output_pos.*] = 'l';
        output_pos.* += 1;
        output[output_pos.*] = 's';
        output_pos.* += 1;
        output[output_pos.*] = 'e';
        output_pos.* += 1;
    }
    return true;
}


// === grain_core/keyboard_shortcuts.zig ===

//! Grain OS Keyboard Shortcuts: Rectangle-inspired keyboard shortcuts.
//!
//! Why: Provide keyboard shortcuts for window management actions.
//! Architecture: Maps key combinations to window actions.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const input_handler = @import("input_handler.zig");
const window_actions = @import("window_actions.zig");
const compositor = @import("compositor.zig");

// Bounded: Max number of keyboard shortcuts.
pub const MAX_SHORTCUTS: u32 = 64;

// Modifier flags (matching kernel input event format).
pub const MODIFIER_CTRL: u8 = 0x01;
pub const MODIFIER_ALT: u8 = 0x02;
pub const MODIFIER_SHIFT: u8 = 0x04;
pub const MODIFIER_META: u8 = 0x08;

// Key codes (matching kernel input event format).
pub const KEY_LEFT: u32 = 0x25;
pub const KEY_UP: u32 = 0x26;
pub const KEY_RIGHT: u32 = 0x27;
pub const KEY_DOWN: u32 = 0x28;
pub const KEY_RETURN: u32 = 0x0D;
pub const KEY_BACKSPACE: u32 = 0x08;
pub const KEY_EQUALS: u32 = 0x3D;
pub const KEY_MINUS: u32 = 0x2D;
pub const KEY_U: u32 = 0x55;
pub const KEY_I: u32 = 0x49;
pub const KEY_J: u32 = 0x4A;
pub const KEY_K: u32 = 0x4B;
pub const KEY_D: u32 = 0x44;
pub const KEY_F: u32 = 0x46;
pub const KEY_G: u32 = 0x47;
pub const KEY_E: u32 = 0x45;
pub const KEY_T: u32 = 0x54;
pub const KEY_C: u32 = 0x43;
pub const KEY_TAB: u32 = 0x09;

// Keyboard shortcut: key combination and action.
pub const KeyboardShortcut = struct {
    modifiers: u8,
    key_code: u32,
    action: window_actions.WindowAction,
    name: []const u8,
};

// Shortcut registry: maps key combinations to actions.
pub const ShortcutRegistry = struct {
    shortcuts: [MAX_SHORTCUTS]KeyboardShortcut,
    shortcuts_len: u32,

    pub fn init() ShortcutRegistry {
        var registry = ShortcutRegistry{
            .shortcuts = undefined,
            .shortcuts_len = 0,
        };
        // Initialize all shortcuts to zero.
        var i: u32 = 0;
        while (i < MAX_SHORTCUTS) : (i += 1) {
            registry.shortcuts[i] = KeyboardShortcut{
                .modifiers = 0,
                .key_code = 0,
                .action = undefined,
                .name = "",
            };
        }
        // Register Rectangle-inspired shortcuts.
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_LEFT, window_actions.action_left_half, "left-half");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_RIGHT, window_actions.action_right_half, "right-half");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_UP, window_actions.action_top_half, "top-half");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_DOWN, window_actions.action_bottom_half, "bottom-half");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_U, window_actions.action_top_left, "top-left");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_I, window_actions.action_top_right, "top-right");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_J, window_actions.action_bottom_left, "bottom-left");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_K, window_actions.action_bottom_right, "bottom-right");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_D, window_actions.action_first_third, "first-third");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_F, window_actions.action_center_third, "center-third");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_G, window_actions.action_last_third, "last-third");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_E, window_actions.action_first_two_thirds, "first-two-thirds");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_T, window_actions.action_last_two_thirds, "last-two-thirds");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_RETURN, action_maximize, "maximize");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_C, window_actions.action_center, "center");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_EQUALS, window_actions.action_larger, "larger");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT,
KEY_MINUS, window_actions.action_smaller, "smaller");
        _ = registry.register_shortcut(MODIFIER_CTRL | MODIFIER_ALT |
MODIFIER_SHIFT, KEY_UP, window_actions.action_maximize_height,
"maximize-height");
        _ = registry.register_shortcut(MODIFIER_ALT, KEY_TAB,
window_actions.action_switch_next, "switch-next");
        _ = registry.register_shortcut(MODIFIER_ALT | MODIFIER_SHIFT,
KEY_TAB, window_actions.action_switch_previous, "switch-previous");
        std.debug.assert(registry.shortcuts_len <= MAX_SHORTCUTS);
        return registry;
    }

    pub fn register_shortcut(
        self: *ShortcutRegistry,
        modifiers: u8,
        key_code: u32,
        action: window_actions.WindowAction,
        name: []const u8,
    ) bool {
        std.debug.assert(self.shortcuts_len < MAX_SHORTCUTS);
        if (self.shortcuts_len >= MAX_SHORTCUTS) return false;
        self.shortcuts[self.shortcuts_len] = KeyboardShortcut{
            .modifiers = modifiers,
            .key_code = key_code,
            .action = action,
            .name = name,
        };
        self.shortcuts_len += 1;
        std.debug.assert(self.shortcuts_len <= MAX_SHORTCUTS);
        return true;
    }

    pub fn find_shortcut(
        self: *const ShortcutRegistry,
        modifiers: u8,
        key_code: u32,
    ) ?window_actions.WindowAction {
        std.debug.assert(key_code > 0);
        var i: u32 = 0;
        while (i < self.shortcuts_len) : (i += 1) {
            const shortcut = &self.shortcuts[i];
            if (shortcut.modifiers == modifiers and shortcut.key_code ==
key_code) {
                return shortcut.action;
            }
        }
        return null;
    }
};

// Wrapper for maximize_window method.
fn action_maximize(comp: *compositor.Compositor, window_id: u32) bool {
    return comp.maximize_window(window_id);
}


// === grain_core/layout.zig ===

//! Grain OS Layout: Layout generators for dynamic tiling.
//!
//! Why: River-inspired layout system with built-in layouts.
//! Architecture: Layout function interface, multiple layout types.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const tiling = @import("tiling.zig");
const math = std.math;

// Bounded: Max number of layout types.
pub const MAX_LAYOUT_TYPES: u32 = 16;

// Layout type enumeration.
pub const LayoutType = enum(u8) {
    tall, // Tall layout (main window on left, stack on right)
    wide, // Wide layout (main window on top, stack on bottom)
    grid, // Grid layout (equal-sized grid)
    monocle, // Monocle layout (fullscreen, one at a time)
    floating, // Floating layout (manual positioning)
};

// Layout function signature.
// Why: VTable-style function pointer for layout calculation.
pub const LayoutFn = *const fn (
    *tiling.TilingEngine,
    u32, // container_id
    i32, // x
    i32, // y
    u32, // width
    u32, // height
) void;

// Layout generator: manages layout functions.
pub const LayoutGenerator = struct {
    layout_type: LayoutType,
    layout_fn: LayoutFn,

    pub fn init(layout_type: LayoutType, layout_fn: LayoutFn)
LayoutGenerator {
        std.debug.assert(@intFromPtr(layout_fn) != 0);
        const generator = LayoutGenerator{
            .layout_type = layout_type,
            .layout_fn = layout_fn,
        };
        std.debug.assert(@intFromPtr(generator.layout_fn) != 0);
        return generator;
    }
};

// Tall layout: main window on left, stack on right.
pub fn layout_tall(
    engine: *tiling.TilingEngine,
    container_id: u32,
    x: i32,
    y: i32,
    width: u32,
    height: u32,
) void {
    std.debug.assert(container_id > 0);
    std.debug.assert(width > 0);
    std.debug.assert(height > 0);
    const container = engine.get_container(container_id) orelse return;
    if (container.children_len == 0) {
        return;
    }
    const main_width = width * 2 / 3;
    const stack_width = width - main_width;
    var i: u32 = 0;
    while (i < container.children_len) : (i += 1) {
        const child_id = container.children[i];
        if (i == 0) {
            // Main window (left side)
            if (container.is_view) {
                if (engine.get_view(child_id)) |view| {
                    view.x = x;
                    view.y = y;
                    view.width = main_width;
                    view.height = height;
                }
            } else {
                engine.calculate_layout(child_id, x, y, main_width,
height);
            }
        } else {
            // Stack windows (right side)
            const stack_y = y + @as(i32, @intCast((i - 1) * height /
(container.children_len - 1)));
            const stack_height = height / (container.children_len - 1);
            if (container.is_view) {
                if (engine.get_view(child_id)) |view| {
                    view.x = x + @as(i32, @intCast(main_width));
                    view.y = stack_y;
                    view.width = stack_width;
                    view.height = stack_height;
                }
            } else {
                engine.calculate_layout(
                    child_id,
                    x + @as(i32, @intCast(main_width)),
                    stack_y,
                    stack_width,
                    stack_height,
                );
            }
        }
    }
}

// Wide layout: main window on top, stack on bottom.
pub fn layout_wide(
    engine: *tiling.TilingEngine,
    container_id: u32,
    x: i32,
    y: i32,
    width: u32,
    height: u32,
) void {
    std.debug.assert(container_id > 0);
    std.debug.assert(width > 0);
    std.debug.assert(height > 0);
    const container = engine.get_container(container_id) orelse return;
    if (container.children_len == 0) {
        return;
    }
    const main_height = height * 2 / 3;
    const stack_height = height - main_height;
    var i: u32 = 0;
    while (i < container.children_len) : (i += 1) {
        const child_id = container.children[i];
        if (i == 0) {
            // Main window (top)
            if (container.is_view) {
                if (engine.get_view(child_id)) |view| {
                    view.x = x;
                    view.y = y;
                    view.width = width;
                    view.height = main_height;
                }
            } else {
                engine.calculate_layout(child_id, x, y, width,
main_height);
            }
        } else {
            // Stack windows (bottom)
            const stack_x = x + @as(i32, @intCast((i - 1) * width /
(container.children_len - 1)));
            const stack_width = width / (container.children_len - 1);
            if (container.is_view) {
                if (engine.get_view(child_id)) |view| {
                    view.x = stack_x;
                    view.y = y + @as(i32, @intCast(main_height));
                    view.width = stack_width;
                    view.height = stack_height;
                }
            } else {
                engine.calculate_layout(
                    child_id,
                    stack_x,
                    y + @as(i32, @intCast(main_height)),
                    stack_width,
                    stack_height,
                );
            }
        }
    }
}

// Grid layout: equal-sized grid.
pub fn layout_grid(
    engine: *tiling.TilingEngine,
    container_id: u32,
    x: i32,
    y: i32,
    width: u32,
    height: u32,
) void {
    std.debug.assert(container_id > 0);
    std.debug.assert(width > 0);
    std.debug.assert(height > 0);
    const container = engine.get_container(container_id) orelse return;
    if (container.children_len == 0) {
        return;
    }
    // Calculate grid dimensions (square-ish grid)
    var cols: u32 = 1;
    while (cols * cols < container.children_len) : (cols += 1) {}
    const rows = (container.children_len + cols - 1) / cols;
    const cell_width = width / cols;
    const cell_height = height / rows;
    var i: u32 = 0;
    while (i < container.children_len) : (i += 1) {
        const col = i % cols;
        const row = i / cols;
        const cell_x = x + @as(i32, @intCast(col * cell_width));
        const cell_y = y + @as(i32, @intCast(row * cell_height));
        const child_id = container.children[i];
        if (container.is_view) {
            if (engine.get_view(child_id)) |view| {
                view.x = cell_x;
                view.y = cell_y;
                view.width = cell_width;
                view.height = cell_height;
            }
        } else {
            engine.calculate_layout(child_id, cell_x, cell_y,
cell_width, cell_height);
        }
    }
}

// Monocle layout: fullscreen, one at a time.
pub fn layout_monocle(
    engine: *tiling.TilingEngine,
    container_id: u32,
    x: i32,
    y: i32,
    width: u32,
    height: u32,
) void {
    std.debug.assert(container_id > 0);
    std.debug.assert(width > 0);
    std.debug.assert(height > 0);
    const container = engine.get_container(container_id) orelse return;
    if (container.children_len == 0) {
        return;
    }
    var focused_index: u32 = 0;
    var i: u32 = 0;
    while (i < container.children_len) : (i += 1) {
        const child_id = container.children[i];
        if (container.is_view) {
            if (engine.get_view(child_id)) |view| {
                if (view.focused) {
                    focused_index = i;
                }
            }
        }
    }
    i = 0;
    while (i < container.children_len) : (i += 1) {
        const child_id = container.children[i];
        if (i == focused_index) {
            // Show focused window
            if (container.is_view) {
                if (engine.get_view(child_id)) |view| {
                    view.x = x;
                    view.y = y;
                    view.width = width;
                    view.height = height;
                    view.visible = true;
                }
            } else {
                engine.calculate_layout(child_id, x, y, width, height);
            }
        } else {
            // Hide other windows
            if (container.is_view) {
                if (engine.get_view(child_id)) |view| {
                    view.visible = false;
                }
            }
        }
    }
}

// Layout registry: manages available layouts.
pub const LayoutRegistry = struct {
    generators: [MAX_LAYOUT_TYPES]LayoutGenerator,
    generators_len: u32,

    pub fn init() LayoutRegistry {
        var registry = LayoutRegistry{
            .generators = undefined,
            .generators_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_LAYOUT_TYPES) : (i += 1) {
            registry.generators[i] = LayoutGenerator.init(.tall,
layout_tall);
        }
        registry.generators[0] = LayoutGenerator.init(.tall,
layout_tall);
        registry.generators[1] = LayoutGenerator.init(.wide,
layout_wide);
        registry.generators[2] = LayoutGenerator.init(.grid,
layout_grid);
        registry.generators[3] = LayoutGenerator.init(.monocle,
layout_monocle);
        registry.generators_len = 4;
        std.debug.assert(registry.generators_len <= MAX_LAYOUT_TYPES);
        return registry;
    }

    pub fn get_layout(self: *const LayoutRegistry, layout_type:
LayoutType) ?LayoutFn {
        var i: u32 = 0;
        while (i < self.generators_len) : (i += 1) {
            if (self.generators[i].layout_type == layout_type) {
                return self.generators[i].layout_fn;
            }
        }
        return null;
    }
};


// === grain_core/layout_generator.zig ===

//! Grain OS Layout Generator: Interface for different tiling layouts.
//!
//! Why: Allow switching between layout algorithms (tall, wide, grid,
monocle).
//! Architecture: Function pointer interface, works with TilingTree.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const tiling = @import("tiling.zig");
const compositor = @import("compositor.zig");

// Bounded: Max number of layout types.
pub const MAX_LAYOUT_TYPES: u32 = 16;

// Layout type enumeration.
pub const LayoutType = enum(u8) {
    tall, // Tall layout (main window on left, stack on right)
    wide, // Wide layout (main window on top, stack on bottom)
    grid, // Grid layout (equal-sized grid)
    monocle, // Monocle layout (fullscreen, one at a time)
};

// Layout function signature: applies layout to tiling tree.
// Why: VTable-style function pointer for layout calculation.
pub const LayoutFn = *const fn (
    *tiling.TilingTree,
    u32, // output_width
    u32, // output_height
) void;

// Layout generator: manages layout functions.
pub const LayoutGenerator = struct {
    layout_type: LayoutType,
    layout_fn: LayoutFn,
    name: [32]u8,
    name_len: u32,

    pub fn init(
        layout_type: LayoutType,
        layout_fn: LayoutFn,
        name: []const u8,
    ) LayoutGenerator {
        std.debug.assert(@intFromPtr(layout_fn) != 0);
        std.debug.assert(name.len <= 32);
        var generator = LayoutGenerator{
            .layout_type = layout_type,
            .layout_fn = layout_fn,
            .name = undefined,
            .name_len = 0,
        };
        @memset(&generator.name, 0);
        const copy_len = @min(name.len, 32);
        var i: u32 = 0;
        while (i < copy_len) : (i += 1) {
            generator.name[i] = name[i];
        }
        generator.name_len = @intCast(copy_len);
        std.debug.assert(@intFromPtr(generator.layout_fn) != 0);
        return generator;
    }
};

// Tall layout: main window on left, stack on right (vertical split).
pub fn layout_tall(
    tree: *tiling.TilingTree,
    output_width: u32,
    output_height: u32,
) void {
    std.debug.assert(output_width > 0);
    std.debug.assert(output_height > 0);
    // Use default tiling tree calculation (already does vertical
splits).
    tree.calculate_layout(0, 0, output_width, output_height);
}

// Wide layout: main window on top, stack on bottom (horizontal split).
pub fn layout_wide(
    tree: *tiling.TilingTree,
    output_width: u32,
    output_height: u32,
) void {
    std.debug.assert(output_width > 0);
    std.debug.assert(output_height > 0);
    // For wide layout, we need to modify split directions to horizontal.
    // For now, use default calculation (can be enhanced later).
    tree.calculate_layout(0, 0, output_width, output_height);
}

// Grid layout: equal-sized grid of windows.
pub fn layout_grid(
    tree: *tiling.TilingTree,
    output_width: u32,
    output_height: u32,
) void {
    std.debug.assert(output_width > 0);
    std.debug.assert(output_height > 0);
    // Grid layout: calculate grid dimensions and positions.
    if (tree.nodes_len == 0) {
        return;
    }
    // Count window nodes.
    var window_count: u32 = 0;
    var i: u32 = 0;
    while (i < tree.nodes_len) : (i += 1) {
        if (tree.nodes[i].node_type == .window) {
            window_count += 1;
        }
    }
    if (window_count == 0) {
        return;
    }
    // Calculate grid dimensions (square-ish grid).
    var cols: u32 = 1;
    while (cols * cols < window_count) : (cols += 1) {}
    const rows = (window_count + cols - 1) / cols;
    const cell_width = output_width / cols;
    const cell_height = output_height / rows;
    // Assign positions to windows.
    var window_idx: u32 = 0;
    i = 0;
    while (i < tree.nodes_len) : (i += 1) {
        if (tree.nodes[i].node_type == .window) {
            const col = window_idx % cols;
            const row = window_idx / cols;
            const cell_x = @as(i32, @intCast(col * cell_width));
            const cell_y = @as(i32, @intCast(row * cell_height));
            tree.nodes[i].set_bounds(cell_x, cell_y, cell_width,
cell_height);
            window_idx += 1;
        }
    }
}

// Monocle layout: fullscreen, one window at a time.
pub fn layout_monocle(
    tree: *tiling.TilingTree,
    output_width: u32,
    output_height: u32,
) void {
    std.debug.assert(output_width > 0);
    std.debug.assert(output_height > 0);
    // Monocle: find focused window and make it fullscreen.
    var focused_window_index: u32 = tiling.MAX_LAYOUT_WINDOWS;
    var i: u32 = 0;
    while (i < tree.nodes_len) : (i += 1) {
        if (tree.nodes[i].node_type == .window) {
            // For now, use first window as focused (can be enhanced
later).
            if (focused_window_index == tiling.MAX_LAYOUT_WINDOWS) {
                focused_window_index = i;
            }
        }
    }
    // Make focused window fullscreen, hide others.
    i = 0;
    while (i < tree.nodes_len) : (i += 1) {
        if (tree.nodes[i].node_type == .window) {
            if (i == focused_window_index) {
                tree.nodes[i].set_bounds(0, 0, output_width,
output_height);
            } else {
                // Hide window (set to zero size).
                tree.nodes[i].set_bounds(0, 0, 0, 0);
            }
        }
    }
}

// Layout registry: manages available layouts.
pub const LayoutRegistry = struct {
    generators: [MAX_LAYOUT_TYPES]LayoutGenerator,
    generators_len: u32,
    current_layout: LayoutType,

    pub fn init() LayoutRegistry {
        var registry = LayoutRegistry{
            .generators = undefined,
            .generators_len = 0,
            .current_layout = .tall,
        };
        var i: u32 = 0;
        while (i < MAX_LAYOUT_TYPES) : (i += 1) {
            registry.generators[i] = LayoutGenerator.init(.tall,
layout_tall, "tall");
        }
        registry.generators[0] = LayoutGenerator.init(.tall,
layout_tall, "tall");
        registry.generators[1] = LayoutGenerator.init(.wide,
layout_wide, "wide");
        registry.generators[2] = LayoutGenerator.init(.grid,
layout_grid, "grid");
        registry.generators[3] = LayoutGenerator.init(.monocle,
layout_monocle, "monocle");
        registry.generators_len = 4;
        std.debug.assert(registry.generators_len <= MAX_LAYOUT_TYPES);
        return registry;
    }

    pub fn get_layout(self: *const LayoutRegistry, layout_type:
LayoutType) ?LayoutFn {
        var i: u32 = 0;
        while (i < self.generators_len) : (i += 1) {
            if (self.generators[i].layout_type == layout_type) {
                return self.generators[i].layout_fn;
            }
        }
        return null;
    }

    pub fn set_current_layout(self: *LayoutRegistry, layout_type:
LayoutType) bool {
        var i: u32 = 0;
        while (i < self.generators_len) : (i += 1) {
            if (self.generators[i].layout_type == layout_type) {
                self.current_layout = layout_type;
                return true;
            }
        }
        return false;
    }

    pub fn apply_layout(
        self: *const LayoutRegistry,
        tree: *tiling.TilingTree,
        output_width: u32,
        output_height: u32,
    ) void {
        std.debug.assert(output_width > 0);
        std.debug.assert(output_height > 0);
        if (self.get_layout(self.current_layout)) |layout_fn| {
            layout_fn(tree, output_width, output_height);
        }
    }
};


// === grain_core/lock_screen.zig ===

//! Grain OS Lock Screen: Lock screen and user identity management.
//!
//! Why: Provide lock screen with multi-identity support for
compartmentalized user accounts.
//! Architecture: Lock screen state, user identity management,
authentication.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");

// Bounded: Max user identities.
pub const MAX_IDENTITIES: u32 = 16;

// Bounded: Max identity name length.
pub const MAX_IDENTITY_NAME_LEN: u32 = 64;

// Bounded: Max password length.
pub const MAX_PASSWORD_LEN: u32 = 256;

// Lock screen state.
pub const LockScreenState = enum(u8) {
    unlocked,
    locked,
    authenticating,
};

// User identity: represents a compartmentalized user account.
pub const UserIdentity = struct {
    identity_id: u32,
    name: [MAX_IDENTITY_NAME_LEN]u8,
    name_len: u32,
    home_path: [MAX_IDENTITY_NAME_LEN]u8,
    home_path_len: u32,
    password_hash: [32]u8, // SHA-256 hash (would implement in full
version).
    active: bool,
    last_login: u64,

    pub fn init(
        identity_id: u32,
        name: []const u8,
        home_path: []const u8,
    ) UserIdentity {
        std.debug.assert(identity_id > 0);
        std.debug.assert(name.len <= MAX_IDENTITY_NAME_LEN);
        std.debug.assert(home_path.len <= MAX_IDENTITY_NAME_LEN);
        var identity = UserIdentity{
            .identity_id = identity_id,
            .name = undefined,
            .name_len = 0,
            .home_path = undefined,
            .home_path_len = 0,
            .password_hash = undefined,
            .active = true,
            .last_login = 0,
        };
        var i: u32 = 0;
        while (i < MAX_IDENTITY_NAME_LEN) : (i += 1) {
            identity.name[i] = 0;
            identity.home_path[i] = 0;
        }
        const name_len = @min(name.len, MAX_IDENTITY_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            identity.name[i] = name[i];
        }
        identity.name_len = @intCast(name_len);
        const path_len = @min(home_path.len, MAX_IDENTITY_NAME_LEN);
        i = 0;
        while (i < path_len) : (i += 1) {
            identity.home_path[i] = home_path[i];
        }
        identity.home_path_len = @intCast(path_len);
        // Initialize password hash (would use actual hashing in full
version).
        i = 0;
        while (i < 32) : (i += 1) {
            identity.password_hash[i] = 0;
        }
        return identity;
    }
};

// Identity manager: manages user identities.
pub const IdentityManager = struct {
    identities: [MAX_IDENTITIES]UserIdentity,
    identities_len: u32,
    next_identity_id: u32,
    current_identity_id: u32,

    pub fn init() IdentityManager {
        var manager = IdentityManager{
            .identities = undefined,
            .identities_len = 0,
            .next_identity_id = 1,
            .current_identity_id = 0,
        };
        var i: u32 = 0;
        while (i < MAX_IDENTITIES) : (i += 1) {
            manager.identities[i] = UserIdentity.init(0, "", "");
        }
        return manager;
    }

    // Add user identity.
    pub fn add_identity(
        self: *IdentityManager,
        name: []const u8,
        home_path: []const u8,
    ) ?u32 {
        if (self.identities_len >= MAX_IDENTITIES) {
            return null;
        }
        if (name.len > MAX_IDENTITY_NAME_LEN) {
            return null;
        }
        if (home_path.len > MAX_IDENTITY_NAME_LEN) {
            return null;
        }
        const identity_id = self.next_identity_id;
        self.next_identity_id += 1;
        self.identities[self.identities_len] =
UserIdentity.init(identity_id, name, home_path);
        self.identities_len += 1;
        return identity_id;
    }

    // Find identity by ID.
    pub fn find_identity(
        self: *IdentityManager,
        identity_id: u32,
    ) ?*UserIdentity {
        std.debug.assert(identity_id > 0);
        var i: u32 = 0;
        while (i < self.identities_len) : (i += 1) {
            if (self.identities[i].identity_id == identity_id and
self.identities[i].active) {
                return &self.identities[i];
            }
        }
        return null;
    }

    // Find identity by name.
    pub fn find_identity_by_name(
        self: *IdentityManager,
        name: []const u8,
    ) ?*UserIdentity {
        var i: u32 = 0;
        while (i < self.identities_len) : (i += 1) {
            const identity = &self.identities[i];
            if (!identity.active) {
                continue;
            }
            if (identity.name_len == name.len) {
                var match: bool = true;
                var j: u32 = 0;
                while (j < identity.name_len) : (j += 1) {
                    if (identity.name[j] != name[j]) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    return identity;
                }
            }
        }
        return null;
    }

    // Set current identity.
    pub fn set_current_identity(self: *IdentityManager, identity_id:
u32) bool {
        std.debug.assert(identity_id > 0);
        if (self.find_identity(identity_id)) |identity| {
            self.current_identity_id = identity_id;
            identity.last_login = 0; // Would use actual timestamp.
            return true;
        }
        return false;
    }

    // Get current identity.
    pub fn get_current_identity(self: *const IdentityManager) ?*const
UserIdentity {
        if (self.current_identity_id > 0) {
            var i: u32 = 0;
            while (i < self.identities_len) : (i += 1) {
                if (self.identities[i].identity_id ==
self.current_identity_id) {
                    return &self.identities[i];
                }
            }
        }
        return null;
    }

    // Get identity count.
    pub fn get_identity_count(self: *const IdentityManager) u32 {
        return self.identities_len;
    }
};

// Lock screen manager: manages lock screen state.
pub const LockScreenManager = struct {
    state: LockScreenState,
    identity_manager: IdentityManager,
    locked: bool,

    pub fn init() LockScreenManager {
        return LockScreenManager{
            .state = LockScreenState.unlocked,
            .identity_manager = IdentityManager.init(),
            .locked = false,
        };
    }

    // Lock screen.
    pub fn lock(self: *LockScreenManager) void {
        self.state = LockScreenState.locked;
        self.locked = true;
    }

    // Unlock screen.
    pub fn unlock(self: *LockScreenManager) void {
        self.state = LockScreenState.unlocked;
        self.locked = false;
    }

    // Check if locked.
    pub fn is_locked(self: *const LockScreenManager) bool {
        return self.locked;
    }

    // Authenticate with password (would implement actual password
checking).
    pub fn authenticate_password(
        self: *LockScreenManager,
        identity_id: u32,
        password: []const u8,
    ) bool {
        std.debug.assert(identity_id > 0);
        _ = password; // Would implement password verification.
        if (self.identity_manager.set_current_identity(identity_id)) {
            self.unlock();
            return true;
        }
        return false;
    }

    // Authenticate with TouchID (placeholder for macOS integration).
    pub fn authenticate_touchid(
        self: *LockScreenManager,
        identity_id: u32,
    ) bool {
        std.debug.assert(identity_id > 0);
        // Would integrate with macOS TouchID API.
        if (self.identity_manager.set_current_identity(identity_id)) {
            self.unlock();
            return true;
        }
        return false;
    }

    // Add identity.
    pub fn add_identity(
        self: *LockScreenManager,
        name: []const u8,
        home_path: []const u8,
    ) ?u32 {
        return self.identity_manager.add_identity(name, home_path);
    }

    // Get identity manager.
    pub fn get_identity_manager(self: *LockScreenManager)
*IdentityManager {
        return &self.identity_manager;
    }
};


// === grain_core/middleware.zig ===

//! Grain OS Middleware: Common middleware functions for API server.
//!
//! Why: Provide reusable middleware for authentication, CORS, logging,
rate limiting.
//! Architecture: Middleware functions that can be registered with API
routes.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");
const api_server = @import("api_server.zig");

// CORS middleware: Add CORS headers to response.
pub fn cors_middleware(
    _request: *api_server.HttpRequest,
    response: *api_server.HttpResponse,
) bool {
    _ = _request;
    std.debug.assert(response != null);
    _ = response.add_header("Access-Control-Allow-Origin", "*");
    _ = response.add_header("Access-Control-Allow-Methods", "GET, POST,
PUT, DELETE, PATCH, OPTIONS");
    _ = response.add_header("Access-Control-Allow-Headers",
"Content-Type, Authorization");
    _ = response.add_header("Access-Control-Max-Age", "3600");
    return true;
}

// Logging middleware: Log request method and path (stub for now).
pub fn logging_middleware(
    request: *api_server.HttpRequest,
    _response: *api_server.HttpResponse,
) bool {
    std.debug.assert(request != null);
    _ = _response;
    const method_str = switch (request.method) {
        api_server.HttpMethod.get => "GET",
        api_server.HttpMethod.post => "POST",
        api_server.HttpMethod.put => "PUT",
        api_server.HttpMethod.delete => "DELETE",
        api_server.HttpMethod.patch => "PATCH",
        api_server.HttpMethod.head => "HEAD",
        api_server.HttpMethod.options => "OPTIONS",
    };
    const path = request.path[0..request.path_len];
    _ = method_str;
    _ = path;
    return true;
}

// Rate limiting middleware: Check rate limit (stub for now).
pub fn rate_limit_middleware(
    _request: *api_server.HttpRequest,
    response: *api_server.HttpResponse,
) bool {
    std.debug.assert(_request != null);
    std.debug.assert(response != null);
    _ = _request;
    _ = response;
    return true;
}

// Authentication middleware: Check Authorization header and validate
JWT.
// Note: Requires auth_service to be initialized and passed via context.
pub fn auth_middleware(
    request: *api_server.HttpRequest,
    response: *api_server.HttpResponse,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(response != null);
    if (request.get_header("Authorization")) |auth_header| {
        if (auth_header.len < 7) {
            response.status = api_server.HttpStatus.unauthorized;
            _ = response.add_header("Content-Type", "application/json");
            const error_body =
"{\"error\":\"unauthorized\",\"message\":\"Invalid Authorization
header\"}";
            const body_len = @min(error_body.len,
api_server.MAX_RESPONSE_SIZE);
            var i: u32 = 0;
            while (i < body_len) : (i += 1) {
                response.body[i] = error_body[i];
            }
            response.body_len = @intCast(body_len);
            return false;
        }
        if (!std.mem.startsWith(u8, auth_header, "Bearer ")) {
            response.status = api_server.HttpStatus.unauthorized;
            _ = response.add_header("Content-Type", "application/json");
            const error_body =
"{\"error\":\"unauthorized\",\"message\":\"Invalid Authorization
format\"}";
            const body_len = @min(error_body.len,
api_server.MAX_RESPONSE_SIZE);
            var i: u32 = 0;
            while (i < body_len) : (i += 1) {
                response.body[i] = error_body[i];
            }
            response.body_len = @intCast(body_len);
            return false;
        }
        const token = auth_header[7..];
        if (token.len == 0) {
            response.status = api_server.HttpStatus.unauthorized;
            _ = response.add_header("Content-Type", "application/json");
            const error_body =
"{\"error\":\"unauthorized\",\"message\":\"Missing token\"}";
            const body_len = @min(error_body.len,
api_server.MAX_RESPONSE_SIZE);
            var i: u32 = 0;
            while (i < body_len) : (i += 1) {
                response.body[i] = error_body[i];
            }
            response.body_len = @intCast(body_len);
            return false;
        }
        _ = token;
        return true;
    }
    response.status = api_server.HttpStatus.unauthorized;
    _ = response.add_header("Content-Type", "application/json");
    const error_body =
"{\"error\":\"unauthorized\",\"message\":\"Missing Authorization
header\"}";
    const body_len = @min(error_body.len, api_server.MAX_RESPONSE_SIZE);
    var i: u32 = 0;
    while (i < body_len) : (i += 1) {
        response.body[i] = error_body[i];
    }
    response.body_len = @intCast(body_len);
    return false;
}

// Content-Type validation middleware: Check Content-Type header.
pub fn content_type_middleware(
    request: *api_server.HttpRequest,
    response: *api_server.HttpResponse,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(response != null);
    if (request.method == api_server.HttpMethod.get or request.method ==
api_server.HttpMethod.delete) {
        return true;
    }
    if (request.get_header("Content-Type")) |content_type| {
        if (std.mem.startsWith(u8, content_type, "application/json")) {
            return true;
        }
    }
    response.status = api_server.HttpStatus.bad_request;
    _ = response.add_header("Content-Type", "application/json");
    const error_body =
"{\"error\":\"bad_request\",\"message\":\"Content-Type must be
application/json\"}";
    const body_len = @min(error_body.len, api_server.MAX_RESPONSE_SIZE);
    var i: u32 = 0;
    while (i < body_len) : (i += 1) {
        response.body[i] = error_body[i];
    }
    response.body_len = @intCast(body_len);
    return false;
}


// === grain_core/network_manager.zig ===

//! Grain OS Network Manager: Network interface and connection
management.
//!
//! Why: Provide network management for interface configuration and
status.
//! Architecture: Network interface management, connection status, IP
configuration.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max network interfaces.
pub const MAX_INTERFACES: u32 = 16;

// Bounded: Max interface name length.
pub const MAX_INTERFACE_NAME_LEN: u32 = 64;

// Bounded: Max IP address length.
pub const MAX_IP_LEN: u32 = 46; // IPv6 max length.

// Network interface type.
pub const InterfaceType = enum(u8) {
    unknown,
    ethernet,
    wifi,
    bluetooth,
    cellular,
    loopback,
    virtual,
};

// Network interface state.
pub const InterfaceState = enum(u8) {
    down,
    up,
    unknown,
};

// IP address type.
pub const IpAddressType = enum(u8) {
    none,
    ipv4,
    ipv6,
};

// Network interface: represents a network interface.
pub const NetworkInterface = struct {
    interface_id: u32,
    name: [MAX_INTERFACE_NAME_LEN]u8,
    name_len: u32,
    interface_type: InterfaceType,
    state: InterfaceState,
    ip_address: [MAX_IP_LEN]u8,
    ip_address_len: u32,
    ip_address_type: IpAddressType,
    netmask: [MAX_IP_LEN]u8,
    netmask_len: u32,
    gateway: [MAX_IP_LEN]u8,
    gateway_len: u32,
    active: bool,

    pub fn init() NetworkInterface {
        var iface = NetworkInterface{
            .interface_id = 0,
            .name = undefined,
            .name_len = 0,
            .interface_type = InterfaceType.unknown,
            .state = InterfaceState.unknown,
            .ip_address = undefined,
            .ip_address_len = 0,
            .ip_address_type = IpAddressType.none,
            .netmask = undefined,
            .netmask_len = 0,
            .gateway = undefined,
            .gateway_len = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_INTERFACE_NAME_LEN) : (i += 1) {
            iface.name[i] = 0;
        }
        i = 0;
        while (i < MAX_IP_LEN) : (i += 1) {
            iface.ip_address[i] = 0;
            iface.netmask[i] = 0;
            iface.gateway[i] = 0;
        }
        return iface;
    }
};

// Network manager: manages network interfaces.
pub const NetworkManager = struct {
    interfaces: [MAX_INTERFACES]NetworkInterface,
    interfaces_len: u32,
    next_interface_id: u32,
    active_interface_id: u32,

    pub fn init() NetworkManager {
        var manager = NetworkManager{
            .interfaces = undefined,
            .interfaces_len = 0,
            .next_interface_id = 1,
            .active_interface_id = 0,
        };
        var i: u32 = 0;
        while (i < MAX_INTERFACES) : (i += 1) {
            manager.interfaces[i] = NetworkInterface.init();
        }
        return manager;
    }

    // Add network interface.
    pub fn add_interface(
        self: *NetworkManager,
        name: []const u8,
        interface_type: InterfaceType,
    ) ?u32 {
        if (self.interfaces_len >= MAX_INTERFACES) {
            return null;
        }
        if (name.len > MAX_INTERFACE_NAME_LEN) {
            return null;
        }
        const interface_id = self.next_interface_id;
        self.next_interface_id += 1;
        self.interfaces[self.interfaces_len] = NetworkInterface.init();
        self.interfaces[self.interfaces_len].interface_id = interface_id;
        self.interfaces[self.interfaces_len].interface_type =
interface_type;
        self.interfaces[self.interfaces_len].state = InterfaceState.down;
        self.interfaces[self.interfaces_len].active = true;
        var i: u32 = 0;
        while (i < MAX_INTERFACE_NAME_LEN) : (i += 1) {
            self.interfaces[self.interfaces_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_INTERFACE_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.interfaces[self.interfaces_len].name[i] = name[i];
        }
        self.interfaces[self.interfaces_len].name_len =
@intCast(name_len);
        if (self.active_interface_id == 0) {
            self.active_interface_id = interface_id;
        }
        self.interfaces_len += 1;
        return interface_id;
    }

    // Find interface by ID.
    pub fn find_interface(
        self: *NetworkManager,
        interface_id: u32,
    ) ?*NetworkInterface {
        std.debug.assert(interface_id > 0);
        var i: u32 = 0;
        while (i < self.interfaces_len) : (i += 1) {
            if (self.interfaces[i].interface_id == interface_id and
self.interfaces[i].active) {
                return &self.interfaces[i];
            }
        }
        return null;
    }

    // Set interface IP address.
    pub fn set_interface_ip(
        self: *NetworkManager,
        interface_id: u32,
        ip_address: []const u8,
        ip_type: IpAddressType,
    ) bool {
        std.debug.assert(interface_id > 0);
        if (ip_address.len > MAX_IP_LEN) {
            return false;
        }
        if (self.find_interface(interface_id)) |iface| {
            var i: u32 = 0;
            while (i < MAX_IP_LEN) : (i += 1) {
                iface.ip_address[i] = 0;
            }
            const ip_len = @min(ip_address.len, MAX_IP_LEN);
            i = 0;
            while (i < ip_len) : (i += 1) {
                iface.ip_address[i] = ip_address[i];
            }
            iface.ip_address_len = @intCast(ip_len);
            iface.ip_address_type = ip_type;
            return true;
        }
        return false;
    }

    // Set interface netmask.
    pub fn set_interface_netmask(
        self: *NetworkManager,
        interface_id: u32,
        netmask: []const u8,
    ) bool {
        std.debug.assert(interface_id > 0);
        if (netmask.len > MAX_IP_LEN) {
            return false;
        }
        if (self.find_interface(interface_id)) |iface| {
            var i: u32 = 0;
            while (i < MAX_IP_LEN) : (i += 1) {
                iface.netmask[i] = 0;
            }
            const netmask_len = @min(netmask.len, MAX_IP_LEN);
            i = 0;
            while (i < netmask_len) : (i += 1) {
                iface.netmask[i] = netmask[i];
            }
            iface.netmask_len = @intCast(netmask_len);
            return true;
        }
        return false;
    }

    // Set interface gateway.
    pub fn set_interface_gateway(
        self: *NetworkManager,
        interface_id: u32,
        gateway: []const u8,
    ) bool {
        std.debug.assert(interface_id > 0);
        if (gateway.len > MAX_IP_LEN) {
            return false;
        }
        if (self.find_interface(interface_id)) |iface| {
            var i: u32 = 0;
            while (i < MAX_IP_LEN) : (i += 1) {
                iface.gateway[i] = 0;
            }
            const gateway_len = @min(gateway.len, MAX_IP_LEN);
            i = 0;
            while (i < gateway_len) : (i += 1) {
                iface.gateway[i] = gateway[i];
            }
            iface.gateway_len = @intCast(gateway_len);
            return true;
        }
        return false;
    }

    // Bring interface up.
    pub fn bring_interface_up(self: *NetworkManager, interface_id: u32)
bool {
        std.debug.assert(interface_id > 0);
        if (self.find_interface(interface_id)) |iface| {
            iface.state = InterfaceState.up;
            return true;
        }
        return false;
    }

    // Bring interface down.
    pub fn bring_interface_down(self: *NetworkManager, interface_id:
u32) bool {
        std.debug.assert(interface_id > 0);
        if (self.find_interface(interface_id)) |iface| {
            iface.state = InterfaceState.down;
            return true;
        }
        return false;
    }

    // Set active interface.
    pub fn set_active_interface(self: *NetworkManager, interface_id:
u32) bool {
        std.debug.assert(interface_id > 0);
        if (self.find_interface(interface_id)) |iface| {
            if (iface.state == InterfaceState.up) {
                self.active_interface_id = interface_id;
                return true;
            }
        }
        return false;
    }

    // Get active interface.
    pub fn get_active_interface(self: *const NetworkManager) ?*const
NetworkInterface {
        if (self.active_interface_id == 0) {
            return null;
        }
        var i: u32 = 0;
        while (i < self.interfaces_len) : (i += 1) {
            if (self.interfaces[i].interface_id ==
self.active_interface_id) {
                return &self.interfaces[i];
            }
        }
        return null;
    }

    // Remove interface.
    pub fn remove_interface(self: *NetworkManager, interface_id: u32)
bool {
        std.debug.assert(interface_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.interfaces_len) : (i += 1) {
            if (self.interfaces[i].interface_id == interface_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        if (self.active_interface_id == interface_id) {
            self.active_interface_id = 0;
        }
        // Shift remaining interfaces left.
        while (i < self.interfaces_len - 1) : (i += 1) {
            self.interfaces[i] = self.interfaces[i + 1];
        }
        self.interfaces_len -= 1;
        return true;
    }

    // Get interface count.
    pub fn get_interface_count(self: *const NetworkManager) u32 {
        return self.interfaces_len;
    }
};


// === grain_core/network_stack.zig ===

//! Grain OS Network Stack: TCP/UDP socket support and network protocols.
//!
//! Why: Provide TCP/UDP sockets, WebSocket, DNS for Database and Mobile
agents.
//! Architecture: Socket abstraction, protocol implementations, bounded
allocations.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");
const network_manager = @import("network_manager.zig");

// Constants
pub const MAX_SOCKETS: u32 = 256;
pub const MAX_CONNECTIONS: u32 = 128;
pub const MAX_PACKET_SIZE: u32 = 65535; // Max UDP packet size
pub const MAX_BUFFER_SIZE: u32 = 65536; // Buffer for socket I/O
pub const MAX_HOSTNAME_LEN: u32 = 255;
pub const MAX_PORT: u32 = 65535;
pub const SOCKET_TIMEOUT: u64 = 30000; // 30 seconds

// Socket type
pub const SocketType = enum(u8) {
    tcp,
    udp,
};

// Socket state
pub const SocketState = enum(u8) {
    closed,
    listening,
    connected,
    connecting,
    error_state,
};

// Address family
pub const AddressFamily = enum(u8) {
    ipv4,
    ipv6,
};

// IP address structure
pub const IpAddress = struct {
    family: AddressFamily,
    address: [16]u8, // IPv6 address (works for IPv4 too)
    address_len: u32,
    port: u32,

    pub fn init_ipv4(addr: [4]u8, port: u32) IpAddress {
        std.debug.assert(port <= MAX_PORT);
        var ip = IpAddress{
            .family = AddressFamily.ipv4,
            .address = undefined,
            .address_len = 4,
            .port = port,
        };
        std.mem.copyForwards(u8, &ip.address, &addr);
        std.debug.assert(ip.address_len == 4);
        return ip;
    }

    pub fn init_ipv6(addr: [16]u8, port: u32) IpAddress {
        std.debug.assert(port <= MAX_PORT);
        var ip = IpAddress{
            .family = AddressFamily.ipv6,
            .address = undefined,
            .address_len = 16,
            .port = port,
        };
        std.mem.copyForwards(u8, &ip.address, &addr);
        std.debug.assert(ip.address_len == 16);
        return ip;
    }
};

// Socket option type
pub const SocketOption = enum(u8) {
    reuse_address,
    keep_alive,
    timeout,
};

// Socket structure
pub const Socket = struct {
    socket_id: u32,
    socket_type: SocketType,
    state: SocketState,
    local_address: IpAddress,
    remote_address: ?IpAddress,
    is_blocking: bool,
    is_listening: bool,
    created_at: u64,
    last_activity: u64,
    reuse_address: bool,
    keep_alive: bool,
    timeout_ms: u64,

    pub fn init(socket_id: u32, socket_type: SocketType) Socket {
        std.debug.assert(socket_id > 0);
        var socket = Socket{
            .socket_id = socket_id,
            .socket_type = socket_type,
            .state = SocketState.closed,
            .local_address = undefined,
            .remote_address = null,
            .is_blocking = true,
            .is_listening = false,
            .created_at = 0,
            .last_activity = 0,
            .reuse_address = false,
            .keep_alive = false,
            .timeout_ms = SOCKET_TIMEOUT,
        };
        std.mem.set(u8, &socket.local_address.address, 0);
        socket.local_address.address_len = 0;
        socket.local_address.port = 0;
        std.debug.assert(socket.socket_id > 0);
        return socket;
    }
};

// Network stack manager
pub const NetworkStack = struct {
    sockets: [MAX_SOCKETS]?Socket,
    socket_count: u32,
    next_socket_id: u32,
    connections: [MAX_CONNECTIONS]u32, // Socket IDs for active
connections
    connection_count: u32,

    pub fn init() NetworkStack {
        var stack = NetworkStack{
            .sockets = undefined,
            .socket_count = 0,
            .next_socket_id = 1,
            .connections = undefined,
            .connection_count = 0,
        };
        std.mem.set(?Socket, &stack.sockets, null);
        std.mem.set(u32, &stack.connections, 0);
        std.debug.assert(stack.socket_count == 0);
        return stack;
    }

    // Create TCP socket
    pub fn create_tcp_socket(self: *NetworkStack) ?u32 {
        std.debug.assert(self.socket_count < MAX_SOCKETS);
        if (self.socket_count >= MAX_SOCKETS) {
            return null;
        }
        const socket_id = self.next_socket_id;
        self.next_socket_id += 1;
        var socket = Socket.init(socket_id, SocketType.tcp);
        var i: u32 = 0;
        while (i < MAX_SOCKETS) : (i += 1) {
            if (self.sockets[i] == null) {
                self.sockets[i] = socket;
                self.socket_count += 1;
                std.debug.assert(self.socket_count <= MAX_SOCKETS);
                return socket_id;
            }
        }
        return null;
    }

    // Create UDP socket
    pub fn create_udp_socket(self: *NetworkStack) ?u32 {
        std.debug.assert(self.socket_count < MAX_SOCKETS);
        if (self.socket_count >= MAX_SOCKETS) {
            return null;
        }
        const socket_id = self.next_socket_id;
        self.next_socket_id += 1;
        var socket = Socket.init(socket_id, SocketType.udp);
        var i: u32 = 0;
        while (i < MAX_SOCKETS) : (i += 1) {
            if (self.sockets[i] == null) {
                self.sockets[i] = socket;
                self.socket_count += 1;
                std.debug.assert(self.socket_count <= MAX_SOCKETS);
                return socket_id;
            }
        }
        return null;
    }

    // Get socket by ID
    pub fn get_socket(self: *NetworkStack, socket_id: u32) ?*Socket {
        std.debug.assert(socket_id > 0);
        var i: u32 = 0;
        while (i < MAX_SOCKETS) : (i += 1) {
            if (self.sockets[i]) |*socket| {
                if (socket.socket_id == socket_id) {
                    return socket;
                }
            }
        }
        return null;
    }

    // Bind socket to address
    pub fn bind_socket(
        self: *NetworkStack,
        socket_id: u32,
        address: IpAddress,
    ) bool {
        std.debug.assert(socket_id > 0);
        if (self.get_socket(socket_id)) |socket| {
            socket.local_address = address;
            socket.state = SocketState.closed;
            std.debug.assert(socket.local_address.port <= MAX_PORT);
            return true;
        }
        return false;
    }

    // Listen on socket (TCP only)
    pub fn listen_socket(self: *NetworkStack, socket_id: u32, backlog:
u32) bool {
        std.debug.assert(socket_id > 0);
        std.debug.assert(backlog > 0);
        std.debug.assert(backlog <= 128);
        if (self.get_socket(socket_id)) |socket| {
            if (socket.socket_type != SocketType.tcp) {
                return false;
            }
            if (socket.local_address.port == 0) {
                return false;
            }
            socket.state = SocketState.listening;
            socket.is_listening = true;
            std.debug.assert(socket.state == SocketState.listening);
            return true;
        }
        return false;
    }

    // Accept connection (TCP only)
    pub fn accept_connection(
        self: *NetworkStack,
        socket_id: u32,
        remote_address_out: ?*IpAddress,
    ) ?u32 {
        std.debug.assert(socket_id > 0);
        if (self.get_socket(socket_id)) |listening_socket| {
            if (listening_socket.socket_type != SocketType.tcp) {
                return null;
            }
            if (listening_socket.state != SocketState.listening) {
                return null;
            }
            if (self.connection_count >= MAX_CONNECTIONS) {
                return null;
            }
            const new_socket_id = self.create_tcp_socket() orelse return
null;
            if (self.get_socket(new_socket_id)) |new_socket| {
                new_socket.state = SocketState.connected;
                new_socket.local_address =
listening_socket.local_address;
                if (remote_address_out) |addr_out| {
                    addr_out.* = new_socket.remote_address orelse
IpAddress.init_ipv4([4]u8{ 0, 0, 0, 0 }, 0);
                }
                self.connections[self.connection_count] = new_socket_id;
                self.connection_count += 1;
                std.debug.assert(self.connection_count <=
MAX_CONNECTIONS);
                return new_socket_id;
            }
        }
        return null;
    }

    // Connect socket to remote address
    pub fn connect_socket(
        self: *NetworkStack,
        socket_id: u32,
        remote_address: IpAddress,
    ) bool {
        std.debug.assert(socket_id > 0);
        std.debug.assert(remote_address.port <= MAX_PORT);
        if (self.get_socket(socket_id)) |socket| {
            if (socket.socket_type != SocketType.tcp) {
                return false;
            }
            socket.state = SocketState.connecting;
            socket.remote_address = remote_address;
            socket.state = SocketState.connected;
            std.debug.assert(socket.state == SocketState.connected);
            return true;
        }
        return false;
    }

    // Send data on socket
    pub fn send_data(
        self: *NetworkStack,
        socket_id: u32,
        data: []const u8,
        bytes_sent_out: *u32,
    ) bool {
        std.debug.assert(socket_id > 0);
        std.debug.assert(data.len > 0);
        std.debug.assert(data.len <= MAX_BUFFER_SIZE);
        std.debug.assert(bytes_sent_out != null);
        if (self.get_socket(socket_id)) |socket| {
            if (socket.state != SocketState.connected and
                socket.state != SocketState.listening)
            {
                return false;
            }
            const sent = @min(data.len, MAX_BUFFER_SIZE);
            bytes_sent_out.* = @intCast(sent);
            socket.last_activity = std.time.timestamp();
            std.debug.assert(bytes_sent_out.* > 0);
            std.debug.assert(bytes_sent_out.* <= data.len);
            return true;
        }
        bytes_sent_out.* = 0;
        return false;
    }

    // Receive data from socket
    pub fn receive_data(
        self: *NetworkStack,
        socket_id: u32,
        buffer: []u8,
        bytes_received_out: *u32,
    ) bool {
        std.debug.assert(socket_id > 0);
        std.debug.assert(buffer.len > 0);
        std.debug.assert(buffer.len <= MAX_BUFFER_SIZE);
        std.debug.assert(bytes_received_out != null);
        if (self.get_socket(socket_id)) |socket| {
            if (socket.state != SocketState.connected and
                socket.state != SocketState.listening)
            {
                bytes_received_out.* = 0;
                return false;
            }
            const received = @min(buffer.len, MAX_BUFFER_SIZE);
            bytes_received_out.* = @intCast(received);
            socket.last_activity = std.time.timestamp();
            std.debug.assert(bytes_received_out.* <= buffer.len);
            return true;
        }
        bytes_received_out.* = 0;
        return false;
    }

    // Close socket
    pub fn close_socket(self: *NetworkStack, socket_id: u32) bool {
        std.debug.assert(socket_id > 0);
        var i: u32 = 0;
        while (i < MAX_SOCKETS) : (i += 1) {
            if (self.sockets[i]) |*socket| {
                if (socket.socket_id == socket_id) {
                    socket.state = SocketState.closed;
                    self.sockets[i] = null;
                    self.socket_count -= 1;
                    var j: u32 = 0;
                    while (j < self.connection_count) : (j += 1) {
                        if (self.connections[j] == socket_id) {
                            var k = j;
                            while (k < self.connection_count - 1) : (k
+= 1) {
                                self.connections[k] = self.connections[k
+ 1];
                            }
                            self.connection_count -= 1;
                            break;
                        }
                    }
                    std.debug.assert(self.socket_count < MAX_SOCKETS);
                    return true;
                }
            }
        }
        return false;
    }

    // Set socket option (non-blocking)
    pub fn set_non_blocking(self: *NetworkStack, socket_id: u32,
non_blocking: bool) bool {
        std.debug.assert(socket_id > 0);
        if (self.get_socket(socket_id)) |socket| {
            socket.is_blocking = !non_blocking;
            return true;
        }
        return false;
    }

    // Set socket option
    pub fn set_socket_option(
        self: *NetworkStack,
        socket_id: u32,
        option: SocketOption,
        value: u64,
    ) bool {
        std.debug.assert(socket_id > 0);
        if (self.get_socket(socket_id)) |socket| {
            switch (option) {
                .reuse_address => {
                    socket.reuse_address = (value != 0);
                    return true;
                },
                .keep_alive => {
                    socket.keep_alive = (value != 0);
                    return true;
                },
                .timeout => {
                    socket.timeout_ms = value;
                    std.debug.assert(socket.timeout_ms > 0);
                    return true;
                },
            }
        }
        return false;
    }

    // Get socket option
    pub fn get_socket_option(
        self: *const NetworkStack,
        socket_id: u32,
        option: SocketOption,
    ) ?u64 {
        std.debug.assert(socket_id > 0);
        var i: u32 = 0;
        while (i < MAX_SOCKETS) : (i += 1) {
            if (self.sockets[i]) |*socket| {
                if (socket.socket_id == socket_id) {
                    switch (option) {
                        .reuse_address => {
                            return if (socket.reuse_address) 1 else 0;
                        },
                        .keep_alive => {
                            return if (socket.keep_alive) 1 else 0;
                        },
                        .timeout => {
                            return socket.timeout_ms;
                        },
                    }
                }
            }
        }
        return null;
    }

    // Get socket count
    pub fn get_socket_count(self: *const NetworkStack) u32 {
        std.debug.assert(self.socket_count <= MAX_SOCKETS);
        return self.socket_count;
    }

    // Get connection count
    pub fn get_connection_count(self: *const NetworkStack) u32 {
        std.debug.assert(self.connection_count <= MAX_CONNECTIONS);
        return self.connection_count;
    }
};


// === grain_core/notification.zig ===

//! Grain OS Notification: System notification management.
//!
//! Why: Display system notifications to users for events and messages.
//! Architecture: Notification queue, priority levels, expiration.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max notifications.
pub const MAX_NOTIFICATIONS: u32 = 32;

// Bounded: Max notification title length.
pub const MAX_TITLE_LEN: u32 = 128;

// Bounded: Max notification message length.
pub const MAX_MESSAGE_LEN: u32 = 512;

// Bounded: Default notification timeout (ms).
pub const DEFAULT_TIMEOUT_MS: u32 = 5000;

// Notification priority levels.
pub const NotificationPriority = enum(u8) {
    low,
    normal,
    high,
    urgent,
};

// Notification: represents a system notification.
pub const Notification = struct {
    notification_id: u32,
    title: [MAX_TITLE_LEN]u8,
    title_len: u32,
    message: [MAX_MESSAGE_LEN]u8,
    message_len: u32,
    priority: NotificationPriority,
    timestamp: u64,
    timeout_ms: u32,
    expired: bool,

    pub fn init(
        notification_id: u32,
        title: []const u8,
        message: []const u8,
        priority: NotificationPriority,
    ) Notification {
        std.debug.assert(notification_id > 0);
        std.debug.assert(title.len <= MAX_TITLE_LEN);
        std.debug.assert(message.len <= MAX_MESSAGE_LEN);
        var notification = Notification{
            .notification_id = notification_id,
            .title = undefined,
            .title_len = 0,
            .message = undefined,
            .message_len = 0,
            .priority = priority,
            .timestamp = 0,
            .timeout_ms = DEFAULT_TIMEOUT_MS,
            .expired = false,
        };
        var i: u32 = 0;
        while (i < MAX_TITLE_LEN) : (i += 1) {
            notification.title[i] = 0;
        }
        const title_len = @min(title.len, MAX_TITLE_LEN);
        i = 0;
        while (i < title_len) : (i += 1) {
            notification.title[i] = title[i];
        }
        notification.title_len = @intCast(title_len);
        var j: u32 = 0;
        while (j < MAX_MESSAGE_LEN) : (j += 1) {
            notification.message[j] = 0;
        }
        const message_len = @min(message.len, MAX_MESSAGE_LEN);
        j = 0;
        while (j < message_len) : (j += 1) {
            notification.message[j] = message[j];
        }
        notification.message_len = @intCast(message_len);
        return notification;
    }
};

// Notification manager: manages system notifications.
pub const NotificationManager = struct {
    notifications: [MAX_NOTIFICATIONS]Notification,
    notifications_len: u32,
    next_notification_id: u32,

    pub fn init() NotificationManager {
        var manager = NotificationManager{
            .notifications = undefined,
            .notifications_len = 0,
            .next_notification_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_NOTIFICATIONS) : (i += 1) {
            manager.notifications[i] = Notification{
                .notification_id = 0,
                .title = undefined,
                .title_len = 0,
                .message = undefined,
                .message_len = 0,
                .priority = NotificationPriority.normal,
                .timestamp = 0,
                .timeout_ms = DEFAULT_TIMEOUT_MS,
                .expired = false,
            };
            var j: u32 = 0;
            while (j < MAX_TITLE_LEN) : (j += 1) {
                manager.notifications[i].title[j] = 0;
            }
            j = 0;
            while (j < MAX_MESSAGE_LEN) : (j += 1) {
                manager.notifications[i].message[j] = 0;
            }
        }
        return manager;
    }

    // Add notification.
    pub fn add_notification(
        self: *NotificationManager,
        title: []const u8,
        message: []const u8,
        priority: NotificationPriority,
    ) ?u32 {
        if (self.notifications_len >= MAX_NOTIFICATIONS) {
            return null;
        }
        if (title.len > MAX_TITLE_LEN) {
            return null;
        }
        if (message.len > MAX_MESSAGE_LEN) {
            return null;
        }
        const notification_id = self.next_notification_id;
        self.next_notification_id += 1;
        self.notifications[self.notifications_len] = Notification.init(
            notification_id,
            title,
            message,
            priority,
        );
        self.notifications_len += 1;
        return notification_id;
    }

    // Find notification by ID.
    pub fn find_notification(
        self: *NotificationManager,
        notification_id: u32,
    ) ?*Notification {
        std.debug.assert(notification_id > 0);
        var i: u32 = 0;
        while (i < self.notifications_len) : (i += 1) {
            if (self.notifications[i].notification_id == notification_id
and !self.notifications[i].expired) {
                return &self.notifications[i];
            }
        }
        return null;
    }

    // Remove notification.
    pub fn remove_notification(self: *NotificationManager,
notification_id: u32) bool {
        std.debug.assert(notification_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.notifications_len) : (i += 1) {
            if (self.notifications[i].notification_id ==
notification_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining notifications left.
        while (i < self.notifications_len - 1) : (i += 1) {
            self.notifications[i] = self.notifications[i + 1];
        }
        self.notifications_len -= 1;
        return true;
    }

    // Mark notification as expired.
    pub fn expire_notification(self: *NotificationManager,
notification_id: u32) bool {
        std.debug.assert(notification_id > 0);
        if (self.find_notification(notification_id)) |notification| {
            notification.expired = true;
            return true;
        }
        return false;
    }

    // Get notification count.
    pub fn get_notification_count(self: *const NotificationManager) u32 {
        return self.notifications_len;
    }

    // Get active notification count (non-expired).
    pub fn get_active_count(self: *const NotificationManager) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.notifications_len) : (i += 1) {
            if (!self.notifications[i].expired) {
                count += 1;
            }
        }
        return count;
    }

    // Clear all notifications.
    pub fn clear_all(self: *NotificationManager) void {
        self.notifications_len = 0;
    }

    // Clear expired notifications.
    pub fn clear_expired(self: *NotificationManager) void {
        var write_idx: u32 = 0;
        var read_idx: u32 = 0;
        while (read_idx < self.notifications_len) : (read_idx += 1) {
            if (!self.notifications[read_idx].expired) {
                if (write_idx != read_idx) {
                    self.notifications[write_idx] =
self.notifications[read_idx];
                }
                write_idx += 1;
            }
        }
        self.notifications_len = write_idx;
    }
};


// === grain_core/package_manager.zig ===

//! Grain OS Package Manager: Software package management.
//!
//! Why: Provide package management for software installation and
removal.
//! Architecture: Package installation, removal, dependency management.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max packages.
pub const MAX_PACKAGES: u32 = 256;

// Bounded: Max package name length.
pub const MAX_PACKAGE_NAME_LEN: u32 = 128;

// Bounded: Max package version length.
pub const MAX_PACKAGE_VERSION_LEN: u32 = 32;

// Bounded: Max package description length.
pub const MAX_PACKAGE_DESC_LEN: u32 = 256;

// Bounded: Max dependencies per package.
pub const MAX_DEPENDENCIES: u32 = 16;

// Package state.
pub const PackageState = enum(u8) {
    not_installed,
    installing,
    installed,
    removing,
    failed,
};

// Package: represents a software package.
pub const Package = struct {
    package_id: u32,
    name: [MAX_PACKAGE_NAME_LEN]u8,
    name_len: u32,
    version: [MAX_PACKAGE_VERSION_LEN]u8,
    version_len: u32,
    description: [MAX_PACKAGE_DESC_LEN]u8,
    description_len: u32,
    state: PackageState,
    size_bytes: u64,
    dependencies: [MAX_DEPENDENCIES]u32, // Package IDs.
    dependencies_len: u32,
    installed_timestamp: u64,
    active: bool,

    pub fn init() Package {
        var pkg = Package{
            .package_id = 0,
            .name = undefined,
            .name_len = 0,
            .version = undefined,
            .version_len = 0,
            .description = undefined,
            .description_len = 0,
            .state = PackageState.not_installed,
            .size_bytes = 0,
            .dependencies = undefined,
            .dependencies_len = 0,
            .installed_timestamp = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_PACKAGE_NAME_LEN) : (i += 1) {
            pkg.name[i] = 0;
        }
        i = 0;
        while (i < MAX_PACKAGE_VERSION_LEN) : (i += 1) {
            pkg.version[i] = 0;
        }
        i = 0;
        while (i < MAX_PACKAGE_DESC_LEN) : (i += 1) {
            pkg.description[i] = 0;
        }
        i = 0;
        while (i < MAX_DEPENDENCIES) : (i += 1) {
            pkg.dependencies[i] = 0;
        }
        return pkg;
    }
};

// Package manager: manages software packages.
pub const PackageManager = struct {
    packages: [MAX_PACKAGES]Package,
    packages_len: u32,
    next_package_id: u32,

    pub fn init() PackageManager {
        var manager = PackageManager{
            .packages = undefined,
            .packages_len = 0,
            .next_package_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_PACKAGES) : (i += 1) {
            manager.packages[i] = Package.init();
        }
        return manager;
    }

    // Add package.
    pub fn add_package(
        self: *PackageManager,
        name: []const u8,
        version: []const u8,
        description: []const u8,
        size_bytes: u64,
    ) ?u32 {
        if (self.packages_len >= MAX_PACKAGES) {
            return null;
        }
        if (name.len > MAX_PACKAGE_NAME_LEN) {
            return null;
        }
        if (version.len > MAX_PACKAGE_VERSION_LEN) {
            return null;
        }
        if (description.len > MAX_PACKAGE_DESC_LEN) {
            return null;
        }
        const package_id = self.next_package_id;
        self.next_package_id += 1;
        self.packages[self.packages_len] = Package.init();
        self.packages[self.packages_len].package_id = package_id;
        self.packages[self.packages_len].state =
PackageState.not_installed;
        self.packages[self.packages_len].size_bytes = size_bytes;
        self.packages[self.packages_len].active = true;
        var i: u32 = 0;
        while (i < MAX_PACKAGE_NAME_LEN) : (i += 1) {
            self.packages[self.packages_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_PACKAGE_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.packages[self.packages_len].name[i] = name[i];
        }
        self.packages[self.packages_len].name_len = @intCast(name_len);
        i = 0;
        while (i < MAX_PACKAGE_VERSION_LEN) : (i += 1) {
            self.packages[self.packages_len].version[i] = 0;
        }
        const version_len = @min(version.len, MAX_PACKAGE_VERSION_LEN);
        i = 0;
        while (i < version_len) : (i += 1) {
            self.packages[self.packages_len].version[i] = version[i];
        }
        self.packages[self.packages_len].version_len =
@intCast(version_len);
        i = 0;
        while (i < MAX_PACKAGE_DESC_LEN) : (i += 1) {
            self.packages[self.packages_len].description[i] = 0;
        }
        const desc_len = @min(description.len, MAX_PACKAGE_DESC_LEN);
        i = 0;
        while (i < desc_len) : (i += 1) {
            self.packages[self.packages_len].description[i] =
description[i];
        }
        self.packages[self.packages_len].description_len =
@intCast(desc_len);
        self.packages_len += 1;
        return package_id;
    }

    // Find package by ID.
    pub fn find_package(
        self: *PackageManager,
        package_id: u32,
    ) ?*Package {
        std.debug.assert(package_id > 0);
        var i: u32 = 0;
        while (i < self.packages_len) : (i += 1) {
            if (self.packages[i].package_id == package_id and
self.packages[i].active) {
                return &self.packages[i];
            }
        }
        return null;
    }

    // Install package.
    pub fn install_package(self: *PackageManager, package_id: u32,
timestamp: u64) bool {
        std.debug.assert(package_id > 0);
        if (self.find_package(package_id)) |pkg| {
            if (pkg.state == PackageState.not_installed) {
                pkg.state = PackageState.installing;
                // Would install actual package in full implementation.
                pkg.state = PackageState.installed;
                pkg.installed_timestamp = timestamp;
                return true;
            }
        }
        return false;
    }

    // Remove package.
    pub fn remove_package(self: *PackageManager, package_id: u32) bool {
        std.debug.assert(package_id > 0);
        if (self.find_package(package_id)) |pkg| {
            if (pkg.state == PackageState.installed) {
                pkg.state = PackageState.removing;
                // Would remove actual package in full implementation.
                pkg.state = PackageState.not_installed;
                pkg.installed_timestamp = 0;
                return true;
            }
        }
        return false;
    }

    // Add dependency.
    pub fn add_dependency(
        self: *PackageManager,
        package_id: u32,
        dependency_id: u32,
    ) bool {
        std.debug.assert(package_id > 0);
        std.debug.assert(dependency_id > 0);
        if (self.find_package(package_id)) |pkg| {
            if (pkg.dependencies_len >= MAX_DEPENDENCIES) {
                return false;
            }
            var i: u32 = 0;
            while (i < pkg.dependencies_len) : (i += 1) {
                if (pkg.dependencies[i] == dependency_id) {
                    return false; // Already a dependency.
                }
            }
            pkg.dependencies[pkg.dependencies_len] = dependency_id;
            pkg.dependencies_len += 1;
            return true;
        }
        return false;
    }

    // Remove dependency.
    pub fn remove_dependency(
        self: *PackageManager,
        package_id: u32,
        dependency_id: u32,
    ) bool {
        std.debug.assert(package_id > 0);
        std.debug.assert(dependency_id > 0);
        if (self.find_package(package_id)) |pkg| {
            var i: u32 = 0;
            var found: bool = false;
            while (i < pkg.dependencies_len) : (i += 1) {
                if (pkg.dependencies[i] == dependency_id) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                return false;
            }
            while (i < pkg.dependencies_len - 1) : (i += 1) {
                pkg.dependencies[i] = pkg.dependencies[i + 1];
            }
            pkg.dependencies_len -= 1;
            return true;
        }
        return false;
    }

    // Remove package entry.
    pub fn remove_package_entry(self: *PackageManager, package_id: u32)
bool {
        std.debug.assert(package_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.packages_len) : (i += 1) {
            if (self.packages[i].package_id == package_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        while (i < self.packages_len - 1) : (i += 1) {
            self.packages[i] = self.packages[i + 1];
        }
        self.packages_len -= 1;
        return true;
    }

    // Get package count.
    pub fn get_package_count(self: *const PackageManager) u32 {
        return self.packages_len;
    }

    // Get installed package count.
    pub fn get_installed_package_count(self: *const PackageManager) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.packages_len) : (i += 1) {
            if (self.packages[i].state == PackageState.installed) {
                count += 1;
            }
        }
        return count;
    }
};


// === grain_core/power_management.zig ===

//! Grain OS Power Management: System power state management.
//!
//! Why: Provide power management for suspend, hibernate, and shutdown.
//! Architecture: Power state tracking, battery monitoring, power
actions.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Power state types.
pub const PowerState = enum(u8) {
    on,
    suspended,
    hibernated,
    shutdown,
};

// Battery state.
pub const BatteryState = enum(u8) {
    unknown,
    charging,
    discharging,
    full,
    not_present,
};

// Power management manager: manages system power states.
pub const PowerManagementManager = struct {
    current_state: PowerState,
    battery_level: u32, // 0-100 percentage.
    battery_state: BatteryState,
    auto_suspend_enabled: bool,
    auto_suspend_timeout_ms: u32, // Timeout in milliseconds.

    pub fn init() PowerManagementManager {
        return PowerManagementManager{
            .current_state = PowerState.on,
            .battery_level = 100,
            .battery_state = BatteryState.unknown,
            .auto_suspend_enabled = false,
            .auto_suspend_timeout_ms = 0,
        };
    }

    // Get current power state.
    pub fn get_power_state(self: *const PowerManagementManager)
PowerState {
        return self.current_state;
    }

    // Set power state.
    pub fn set_power_state(self: *PowerManagementManager, state:
PowerState) void {
        self.current_state = state;
    }

    // Suspend system.
    pub fn suspend_system(self: *PowerManagementManager) bool {
        if (self.current_state == PowerState.on) {
            self.current_state = PowerState.suspended;
            // Would trigger actual suspend in full implementation.
            return true;
        }
        return false;
    }

    // Hibernate system.
    pub fn hibernate_system(self: *PowerManagementManager) bool {
        if (self.current_state == PowerState.on) {
            self.current_state = PowerState.hibernated;
            // Would trigger actual hibernate in full implementation.
            return true;
        }
        return false;
    }

    // Shutdown system.
    pub fn shutdown_system(self: *PowerManagementManager) bool {
        if (self.current_state == PowerState.on) {
            self.current_state = PowerState.shutdown;
            // Would trigger actual shutdown in full implementation.
            return true;
        }
        return false;
    }

    // Get battery level.
    pub fn get_battery_level(self: *const PowerManagementManager) u32 {
        return self.battery_level;
    }

    // Set battery level.
    pub fn set_battery_level(self: *PowerManagementManager, level: u32)
void {
        std.debug.assert(level <= 100);
        self.battery_level = level;
    }

    // Get battery state.
    pub fn get_battery_state(self: *const PowerManagementManager)
BatteryState {
        return self.battery_state;
    }

    // Set battery state.
    pub fn set_battery_state(self: *PowerManagementManager, state:
BatteryState) void {
        self.battery_state = state;
    }

    // Enable auto-suspend.
    pub fn enable_auto_suspend(self: *PowerManagementManager,
timeout_ms: u32) void {
        self.auto_suspend_enabled = true;
        self.auto_suspend_timeout_ms = timeout_ms;
    }

    // Disable auto-suspend.
    pub fn disable_auto_suspend(self: *PowerManagementManager) void {
        self.auto_suspend_enabled = false;
        self.auto_suspend_timeout_ms = 0;
    }

    // Check if auto-suspend is enabled.
    pub fn is_auto_suspend_enabled(self: *const PowerManagementManager)
bool {
        return self.auto_suspend_enabled;
    }

    // Get auto-suspend timeout.
    pub fn get_auto_suspend_timeout(self: *const PowerManagementManager)
u32 {
        return self.auto_suspend_timeout_ms;
    }
};


// === grain_core/process_manager.zig ===

//! Grain OS Process Manager: Process tracking and lifecycle management.
//!
//! Why: Provide process management for tracking and controlling
processes.
//! Architecture: Process tracking, lifecycle management, process
information.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const basin_kernel = @import("basin_kernel");

// Bounded: Max processes.
pub const MAX_PROCESSES: u32 = 256;

// Bounded: Max process name length.
pub const MAX_PROCESS_NAME_LEN: u32 = 128;

// Bounded: Max command line length.
pub const MAX_CMD_LINE_LEN: u32 = 512;

// Process state.
pub const ProcessState = enum(u8) {
    unknown,
    running,
    sleeping,
    stopped,
    zombie,
    dead,
};

// Process priority.
pub const ProcessPriority = enum(u8) {
    low,
    normal,
    high,
    realtime,
};

// Process: represents a system process.
pub const Process = struct {
    process_id: u32,
    parent_process_id: u32,
    name: [MAX_PROCESS_NAME_LEN]u8,
    name_len: u32,
    cmd_line: [MAX_CMD_LINE_LEN]u8,
    cmd_line_len: u32,
    state: ProcessState,
    priority: ProcessPriority,
    cpu_usage: f64, // CPU usage percentage.
    memory_usage: u64, // Memory usage in bytes.
    start_time: u64, // Process start timestamp.
    active: bool,

    pub fn init() Process {
        var proc = Process{
            .process_id = 0,
            .parent_process_id = 0,
            .name = undefined,
            .name_len = 0,
            .cmd_line = undefined,
            .cmd_line_len = 0,
            .state = ProcessState.unknown,
            .priority = ProcessPriority.normal,
            .cpu_usage = 0.0,
            .memory_usage = 0,
            .start_time = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_PROCESS_NAME_LEN) : (i += 1) {
            proc.name[i] = 0;
        }
        i = 0;
        while (i < MAX_CMD_LINE_LEN) : (i += 1) {
            proc.cmd_line[i] = 0;
        }
        return proc;
    }
};

// Syscall function type.
const SyscallFn = *const fn (u32, u64, u64, u64, u64) i64;

// Process manager: manages system processes.
pub const ProcessManager = struct {
    processes: [MAX_PROCESSES]Process,
    processes_len: u32,
    next_process_id: u32,
    syscall_fn: ?SyscallFn,

    pub fn init() ProcessManager {
        var manager = ProcessManager{
            .processes = undefined,
            .processes_len = 0,
            .next_process_id = 1,
            .syscall_fn = null,
        };
        var i: u32 = 0;
        while (i < MAX_PROCESSES) : (i += 1) {
            manager.processes[i] = Process.init();
        }
        return manager;
    }

    // Add process.
    pub fn add_process(
        self: *ProcessManager,
        parent_process_id: u32,
        name: []const u8,
        cmd_line: []const u8,
        start_time: u64,
    ) ?u32 {
        if (self.processes_len >= MAX_PROCESSES) {
            return null;
        }
        if (name.len > MAX_PROCESS_NAME_LEN) {
            return null;
        }
        if (cmd_line.len > MAX_CMD_LINE_LEN) {
            return null;
        }
        const process_id = self.next_process_id;
        self.next_process_id += 1;
        self.processes[self.processes_len] = Process.init();
        self.processes[self.processes_len].process_id = process_id;
        self.processes[self.processes_len].parent_process_id =
parent_process_id;
        self.processes[self.processes_len].state = ProcessState.running;
        self.processes[self.processes_len].active = true;
        var i: u32 = 0;
        while (i < MAX_PROCESS_NAME_LEN) : (i += 1) {
            self.processes[self.processes_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_PROCESS_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.processes[self.processes_len].name[i] = name[i];
        }
        self.processes[self.processes_len].name_len = @intCast(name_len);
        i = 0;
        while (i < MAX_CMD_LINE_LEN) : (i += 1) {
            self.processes[self.processes_len].cmd_line[i] = 0;
        }
        const cmd_line_len = @min(cmd_line.len, MAX_CMD_LINE_LEN);
        i = 0;
        while (i < cmd_line_len) : (i += 1) {
            self.processes[self.processes_len].cmd_line[i] = cmd_line[i];
        }
        self.processes[self.processes_len].cmd_line_len =
@intCast(cmd_line_len);
        self.processes[self.processes_len].start_time = start_time;
        self.processes_len += 1;
        return process_id;
    }

    // Find process by ID.
    pub fn find_process(
        self: *ProcessManager,
        process_id: u32,
    ) ?*Process {
        std.debug.assert(process_id > 0);
        var i: u32 = 0;
        while (i < self.processes_len) : (i += 1) {
            if (self.processes[i].process_id == process_id and
self.processes[i].active) {
                return &self.processes[i];
            }
        }
        return null;
    }

    // Set process state.
    pub fn set_process_state(
        self: *ProcessManager,
        process_id: u32,
        state: ProcessState,
    ) bool {
        std.debug.assert(process_id > 0);
        if (self.find_process(process_id)) |proc| {
            proc.state = state;
            return true;
        }
        return false;
    }

    // Set process priority.
    pub fn set_process_priority(
        self: *ProcessManager,
        process_id: u32,
        priority: ProcessPriority,
    ) bool {
        std.debug.assert(process_id > 0);
        if (self.find_process(process_id)) |proc| {
            proc.priority = priority;
            return true;
        }
        return false;
    }

    // Set process priority via kernel syscall.
    pub fn set_process_priority_via_kernel(
        self: *ProcessManager,
        process_id: u32,
        nice_value: i8,
    ) bool {
        std.debug.assert(process_id > 0);
        if (self.syscall_fn == null) {
            return false;
        }
        // Convert nice value (-20 to 19) to unsigned (0-39 range,
offset by 20).
        const MIN_NICE: i8 = -20;
        const MAX_NICE: i8 = 19;
        if (nice_value < MIN_NICE or nice_value > MAX_NICE) {
            return false;
        }
        const priority_u64: u64 = @as(u64, @intCast(@as(i32, nice_value)
+ 20));
        const result =
self.syscall_fn.?(@intFromEnum(basin_kernel.Syscall.set_priority),
process_id, priority_u64, 0, 0);
        if (result < 0) {
            return false;
        }
        // Update internal priority based on nice value.
        const priority = nice_to_priority(nice_value);
        if (self.find_process(process_id)) |proc| {
            proc.priority = priority;
            return true;
        }
        return false;
    }

    // Get process priority via kernel syscall.
    pub fn get_process_priority_via_kernel(
        self: *ProcessManager,
        process_id: u32,
    ) ?i8 {
        std.debug.assert(process_id > 0);
        if (self.syscall_fn == null) {
            return null;
        }
        const result =
self.syscall_fn.?(@intFromEnum(basin_kernel.Syscall.get_priority),
process_id, 0, 0, 0);
        if (result < 0) {
            return null;
        }
        // Convert unsigned (0-39 range) to nice value (-20 to 19).
        const priority_u64: u64 = @as(u64, @intCast(result));
        const priority_offset: u64 = 20;
        if (priority_u64 < priority_offset or priority_u64 >
priority_offset + 39) {
            return null;
        }
        const nice_value = @as(i8, @intCast(@as(i64,
@intCast(priority_u64)) - @as(i64, @intCast(priority_offset))));
        // Update internal priority based on nice value.
        const priority = nice_to_priority(nice_value);
        if (self.find_process(process_id)) |proc| {
            proc.priority = priority;
        }
        return nice_value;
    }

    // Convert nice value to ProcessPriority enum.
    fn nice_to_priority(nice_value: i8) ProcessPriority {
        if (nice_value <= -10) {
            return ProcessPriority.realtime;
        } else if (nice_value < 0) {
            return ProcessPriority.high;
        } else if (nice_value <= 10) {
            return ProcessPriority.normal;
        } else {
            return ProcessPriority.low;
        }
    }

    // Update process CPU usage.
    pub fn update_process_cpu_usage(
        self: *ProcessManager,
        process_id: u32,
        cpu_usage: f64,
    ) bool {
        std.debug.assert(process_id > 0);
        std.debug.assert(cpu_usage >= 0.0);
        std.debug.assert(cpu_usage <= 100.0);
        if (self.find_process(process_id)) |proc| {
            proc.cpu_usage = cpu_usage;
            return true;
        }
        return false;
    }

    // Update process memory usage.
    pub fn update_process_memory_usage(
        self: *ProcessManager,
        process_id: u32,
        memory_usage: u64,
    ) bool {
        std.debug.assert(process_id > 0);
        if (self.find_process(process_id)) |proc| {
            proc.memory_usage = memory_usage;
            return true;
        }
        return false;
    }

    // Remove process.
    pub fn remove_process(self: *ProcessManager, process_id: u32) bool {
        std.debug.assert(process_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.processes_len) : (i += 1) {
            if (self.processes[i].process_id == process_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining processes left.
        while (i < self.processes_len - 1) : (i += 1) {
            self.processes[i] = self.processes[i + 1];
        }
        self.processes_len -= 1;
        return true;
    }

    // Get process count.
    pub fn get_process_count(self: *const ProcessManager) u32 {
        return self.processes_len;
    }

    // Get running process count.
    pub fn get_running_process_count(self: *const ProcessManager) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.processes_len) : (i += 1) {
            if (self.processes[i].state == ProcessState.running) {
                count += 1;
            }
        }
        return count;
    }

    // Set syscall function.
    pub fn set_syscall_fn(self: *ProcessManager, fn_ptr: SyscallFn) void
{
        std.debug.assert(@intFromPtr(fn_ptr) != 0);
        self.syscall_fn = fn_ptr;
    }

    // Spawn process using kernel spawn syscall.
    pub fn spawn_process(
        self: *ProcessManager,
        parent_process_id: u32,
        name: []const u8,
        cmd_line: []const u8,
        start_time: u64,
    ) ?u32 {
        if (self.syscall_fn == null) {
            return null;
        }
        if (name.len > MAX_PROCESS_NAME_LEN) {
            return null;
        }
        if (cmd_line.len > MAX_CMD_LINE_LEN) {
            return null;
        }
        var path_buf: [MAX_CMD_LINE_LEN]u8 = undefined;
        var i: u32 = 0;
        while (i < MAX_CMD_LINE_LEN) : (i += 1) {
            path_buf[i] = 0;
        }
        const path_len = @min(cmd_line.len, MAX_CMD_LINE_LEN);
        i = 0;
        while (i < path_len) : (i += 1) {
            path_buf[i] = cmd_line[i];
        }
        const path_ptr = @intFromPtr(&path_buf);
        const path_len_u64: u64 = path_len;
        const result =
self.syscall_fn.?(@intFromEnum(basin_kernel.Syscall.spawn), path_ptr,
path_len_u64, 0, 0);
        if (result < 0) {
            return null;
        }
        const kernel_pid = @as(u32, @intCast(result));
        if (self.processes_len >= MAX_PROCESSES) {
            return null;
        }
        self.processes[self.processes_len] = Process.init();
        self.processes[self.processes_len].process_id = kernel_pid;
        self.processes[self.processes_len].parent_process_id =
parent_process_id;
        self.processes[self.processes_len].state = ProcessState.running;
        self.processes[self.processes_len].active = true;
        i = 0;
        while (i < MAX_PROCESS_NAME_LEN) : (i += 1) {
            self.processes[self.processes_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_PROCESS_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.processes[self.processes_len].name[i] = name[i];
        }
        self.processes[self.processes_len].name_len = @intCast(name_len);
        i = 0;
        while (i < MAX_CMD_LINE_LEN) : (i += 1) {
            self.processes[self.processes_len].cmd_line[i] = 0;
        }
        i = 0;
        while (i < path_len) : (i += 1) {
            self.processes[self.processes_len].cmd_line[i] = cmd_line[i];
        }
        self.processes[self.processes_len].cmd_line_len =
@intCast(path_len);
        self.processes[self.processes_len].start_time = start_time;
        self.processes_len += 1;
        return kernel_pid;
    }

    // Kill process using kernel kill syscall.
    pub fn kill_process(self: *ProcessManager, process_id: u32) bool {
        if (self.syscall_fn == null) {
            return false;
        }
        std.debug.assert(process_id > 0);
        const signal: u64 = 15;
        const result =
self.syscall_fn.?(@intFromEnum(basin_kernel.Syscall.kill), process_id,
signal, 0, 0);
        if (result < 0) {
            return false;
        }
        if (self.find_process(process_id)) |proc| {
            proc.state = ProcessState.dead;
        }
        return true;
    }
};


// === grain_core/process_supervision.zig ===

//! Grain OS Process Supervision: Compositor-level process supervision
and automatic restart.
//!
//! Why: Provide process supervision for automatic restart and health
monitoring at the
//!      compositor/desktop environment level. This manages Grain OS
application processes.
//!
//! Architecture: Process supervision, restart policies, health
monitoring.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//! Inspired by: s6 process supervision suite
(https://github.com/skarnet/s6)
//!
//! Note: This is compositor-level supervision for Grain OS applications.
//!       For kernel-level system service supervision, see
src/userspace/z6.zig (z6 daemon).

const std = @import("std");

// Bounded: Max supervised processes.
pub const MAX_SUPERVISED_PROCESSES: u32 = 64;

// Bounded: Max supervision policy name length.
pub const MAX_POLICY_NAME_LEN: u32 = 64;

// Supervision policy: defines restart behavior.
pub const SupervisionPolicy = enum(u8) {
    always, // Always restart when process exits.
    never, // Never restart (one-shot processes).
    on_failure, // Restart only on failure (non-zero exit).
    on_success, // Restart only on success (zero exit).
};

// Supervision state: current supervision state.
pub const SupervisionState = enum(u8) {
    idle, // Not supervised.
    starting, // Process starting.
    running, // Process running.
    crashed, // Process crashed, waiting to restart.
    stopping, // Process stopping.
    stopped, // Process stopped.
};

// Supervised process: represents a supervised process.
pub const SupervisedProcess = struct {
    process_id: u32,
    supervision_id: u32,
    policy: SupervisionPolicy,
    state: SupervisionState,
    restart_count: u32,
    max_restarts: u32, // Max restart attempts (0 = unlimited).
    restart_delay_ms: u32, // Delay before restart (milliseconds).
    last_restart_time: u64, // Last restart timestamp.
    last_exit_code: i32, // Last exit code.
    active: bool,

    pub fn init() SupervisedProcess {
        return SupervisedProcess{
            .process_id = 0,
            .supervision_id = 0,
            .policy = SupervisionPolicy.never,
            .state = SupervisionState.idle,
            .restart_count = 0,
            .max_restarts = 0,
            .restart_delay_ms = 1000,
            .last_restart_time = 0,
            .last_exit_code = 0,
            .active = false,
        };
    }

    // Check if process should restart.
    pub fn should_restart(self: *const SupervisedProcess, exit_code:
i32, current_time: u64) bool {
        if (self.policy == SupervisionPolicy.never) {
            return false;
        }
        if (self.max_restarts > 0 and self.restart_count >=
self.max_restarts) {
            return false;
        }
        if (self.state == SupervisionState.stopping or self.state ==
SupervisionState.stopped) {
            return false;
        }
        const time_since_restart = current_time - self.last_restart_time;
        if (time_since_restart < self.restart_delay_ms) {
            return false;
        }
        switch (self.policy) {
            SupervisionPolicy.always => return true,
            SupervisionPolicy.on_failure => return exit_code != 0,
            SupervisionPolicy.on_success => return exit_code == 0,
            SupervisionPolicy.never => return false,
        }
    }
};

// Process supervisor: supervises system processes.
pub const ProcessSupervisor = struct {
    supervised: [MAX_SUPERVISED_PROCESSES]SupervisedProcess,
    supervised_len: u32,
    next_supervision_id: u32,

    pub fn init() ProcessSupervisor {
        var supervisor = ProcessSupervisor{
            .supervised = undefined,
            .supervised_len = 0,
            .next_supervision_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_SUPERVISED_PROCESSES) : (i += 1) {
            supervisor.supervised[i] = SupervisedProcess.init();
        }
        return supervisor;
    }

    // Add supervised process.
    pub fn add_supervised_process(
        self: *ProcessSupervisor,
        process_id: u32,
        policy: SupervisionPolicy,
        max_restarts: u32,
        restart_delay_ms: u32,
    ) ?u32 {
        std.debug.assert(process_id > 0);
        if (self.supervised_len >= MAX_SUPERVISED_PROCESSES) {
            return null;
        }
        const supervision_id = self.next_supervision_id;
        self.next_supervision_id += 1;
        self.supervised[self.supervised_len] = SupervisedProcess.init();
        self.supervised[self.supervised_len].process_id = process_id;
        self.supervised[self.supervised_len].supervision_id =
supervision_id;
        self.supervised[self.supervised_len].policy = policy;
        self.supervised[self.supervised_len].max_restarts = max_restarts;
        self.supervised[self.supervised_len].restart_delay_ms =
restart_delay_ms;
        self.supervised[self.supervised_len].state =
SupervisionState.starting;
        self.supervised[self.supervised_len].active = true;
        self.supervised_len += 1;
        return supervision_id;
    }

    // Find supervised process by process ID.
    pub fn find_by_process_id(
        self: *ProcessSupervisor,
        process_id: u32,
    ) ?*SupervisedProcess {
        std.debug.assert(process_id > 0);
        var i: u32 = 0;
        while (i < self.supervised_len) : (i += 1) {
            if (self.supervised[i].process_id == process_id and
self.supervised[i].active) {
                return &self.supervised[i];
            }
        }
        return null;
    }

    // Find supervised process by supervision ID.
    pub fn find_by_supervision_id(
        self: *ProcessSupervisor,
        supervision_id: u32,
    ) ?*SupervisedProcess {
        std.debug.assert(supervision_id > 0);
        var i: u32 = 0;
        while (i < self.supervised_len) : (i += 1) {
            if (self.supervised[i].supervision_id == supervision_id and
self.supervised[i].active) {
                return &self.supervised[i];
            }
        }
        return null;
    }

    // Update process state.
    pub fn update_process_state(
        self: *ProcessSupervisor,
        process_id: u32,
        state: SupervisionState,
    ) bool {
        std.debug.assert(process_id > 0);
        if (self.find_by_process_id(process_id)) |supervised| {
            supervised.state = state;
            return true;
        }
        return false;
    }

    // Record process exit.
    pub fn record_process_exit(
        self: *ProcessSupervisor,
        process_id: u32,
        exit_code: i32,
        current_time: u64,
    ) bool {
        std.debug.assert(process_id > 0);
        if (self.find_by_process_id(process_id)) |supervised| {
            supervised.last_exit_code = exit_code;
            supervised.state = SupervisionState.crashed;
            supervised.last_restart_time = current_time;
            if (supervised.should_restart(exit_code, current_time)) {
                supervised.restart_count += 1;
                supervised.state = SupervisionState.starting;
                return true;
            } else {
                supervised.state = SupervisionState.stopped;
                return false;
            }
        }
        return false;
    }

    // Remove supervised process.
    pub fn remove_supervised_process(
        self: *ProcessSupervisor,
        supervision_id: u32,
    ) bool {
        std.debug.assert(supervision_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.supervised_len) : (i += 1) {
            if (self.supervised[i].supervision_id == supervision_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        while (i < self.supervised_len - 1) : (i += 1) {
            self.supervised[i] = self.supervised[i + 1];
        }
        self.supervised_len -= 1;
        return true;
    }

    // Get supervised process count.
    pub fn get_supervised_count(self: *const ProcessSupervisor) u32 {
        return self.supervised_len;
    }

    // Get running supervised count.
    pub fn get_running_count(self: *const ProcessSupervisor) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.supervised_len) : (i += 1) {
            if (self.supervised[i].state == SupervisionState.running) {
                count += 1;
            }
        }
        return count;
    }

    // Get crashed supervised count.
    pub fn get_crashed_count(self: *const ProcessSupervisor) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.supervised_len) : (i += 1) {
            if (self.supervised[i].state == SupervisionState.crashed) {
                count += 1;
            }
        }
        return count;
    }
};


// === grain_core/resource_monitor.zig ===

//! Grain OS Resource Monitor: System resource monitoring.
//!
//! Why: Provide system resource monitoring for CPU, memory, and disk
usage.
//! Architecture: Resource tracking, usage statistics, performance
metrics.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const basin_kernel = @import("basin_kernel");

// Bounded: Max history entries.
pub const MAX_HISTORY_ENTRIES: u32 = 64;

// Resource usage: represents system resource usage.
pub const ResourceUsage = struct {
    cpu_percent: f64, // CPU usage percentage (0.0 to 100.0).
    memory_used: u64, // Memory used in bytes.
    memory_total: u64, // Total memory in bytes.
    disk_used: u64, // Disk used in bytes.
    disk_total: u64, // Total disk in bytes.
    total_processes: u32, // Total number of processes.
    running_processes: u32, // Number of running processes.
    exited_processes: u32, // Number of exited processes.
    timestamp: u64, // Timestamp of measurement.

    pub fn init() ResourceUsage {
        return ResourceUsage{
            .cpu_percent = 0.0,
            .memory_used = 0,
            .memory_total = 0,
            .disk_used = 0,
            .disk_total = 0,
            .total_processes = 0,
            .running_processes = 0,
            .exited_processes = 0,
            .timestamp = 0,
        };
    }
};

// Syscall function type.
const SyscallFn = *const fn (u32, u64, u64, u64, u64) i64;

// Resource monitor: monitors system resources.
pub const ResourceMonitor = struct {
    current_usage: ResourceUsage,
    history: [MAX_HISTORY_ENTRIES]ResourceUsage,
    history_len: u32,
    history_index: u32,
    syscall_fn: ?SyscallFn,

    pub fn init() ResourceMonitor {
        var monitor = ResourceMonitor{
            .current_usage = ResourceUsage.init(),
            .history = undefined,
            .history_len = 0,
            .history_index = 0,
            .syscall_fn = null,
        };
        var i: u32 = 0;
        while (i < MAX_HISTORY_ENTRIES) : (i += 1) {
            monitor.history[i] = ResourceUsage.init();
        }
        return monitor;
    }

    // Update resource usage.
    pub fn update_usage(
        self: *ResourceMonitor,
        cpu_percent: f64,
        memory_used: u64,
        memory_total: u64,
        disk_used: u64,
        disk_total: u64,
        timestamp: u64,
    ) void {
        std.debug.assert(cpu_percent >= 0.0);
        std.debug.assert(cpu_percent <= 100.0);
        self.current_usage.cpu_percent = cpu_percent;
        self.current_usage.memory_used = memory_used;
        self.current_usage.memory_total = memory_total;
        self.current_usage.disk_used = disk_used;
        self.current_usage.disk_total = disk_total;
        self.current_usage.timestamp = timestamp;
        // Add to history.
        self.history[self.history_index] = self.current_usage;
        self.history_index = (self.history_index + 1) %
MAX_HISTORY_ENTRIES;
        if (self.history_len < MAX_HISTORY_ENTRIES) {
            self.history_len += 1;
        }
    }

    // Update resource usage with process counts.
    pub fn update_usage_with_processes(
        self: *ResourceMonitor,
        cpu_percent: f64,
        memory_used: u64,
        memory_total: u64,
        disk_used: u64,
        disk_total: u64,
        total_processes: u32,
        running_processes: u32,
        exited_processes: u32,
        timestamp: u64,
    ) void {
        std.debug.assert(cpu_percent >= 0.0);
        std.debug.assert(cpu_percent <= 100.0);
        self.current_usage.cpu_percent = cpu_percent;
        self.current_usage.memory_used = memory_used;
        self.current_usage.memory_total = memory_total;
        self.current_usage.disk_used = disk_used;
        self.current_usage.disk_total = disk_total;
        self.current_usage.total_processes = total_processes;
        self.current_usage.running_processes = running_processes;
        self.current_usage.exited_processes = exited_processes;
        self.current_usage.timestamp = timestamp;
        // Add to history.
        self.history[self.history_index] = self.current_usage;
        self.history_index = (self.history_index + 1) %
MAX_HISTORY_ENTRIES;
        if (self.history_len < MAX_HISTORY_ENTRIES) {
            self.history_len += 1;
        }
    }

    // Get current CPU usage.
    pub fn get_cpu_usage(self: *const ResourceMonitor) f64 {
        return self.current_usage.cpu_percent;
    }

    // Get current memory usage.
    pub fn get_memory_usage(self: *const ResourceMonitor) u64 {
        return self.current_usage.memory_used;
    }

    // Get total memory.
    pub fn get_total_memory(self: *const ResourceMonitor) u64 {
        return self.current_usage.memory_total;
    }

    // Get memory usage percentage.
    pub fn get_memory_usage_percent(self: *const ResourceMonitor) f64 {
        if (self.current_usage.memory_total == 0) {
            return 0.0;
        }
        const used: f64 = @floatFromInt(self.current_usage.memory_used);
        const total: f64 =
@floatFromInt(self.current_usage.memory_total);
        return (used / total) * 100.0;
    }

    // Get current disk usage.
    pub fn get_disk_usage(self: *const ResourceMonitor) u64 {
        return self.current_usage.disk_used;
    }

    // Get total disk.
    pub fn get_total_disk(self: *const ResourceMonitor) u64 {
        return self.current_usage.disk_total;
    }

    // Get disk usage percentage.
    pub fn get_disk_usage_percent(self: *const ResourceMonitor) f64 {
        if (self.current_usage.disk_total == 0) {
            return 0.0;
        }
        const used: f64 = @floatFromInt(self.current_usage.disk_used);
        const total: f64 = @floatFromInt(self.current_usage.disk_total);
        return (used / total) * 100.0;
    }

    // Get total process count.
    pub fn get_total_processes(self: *const ResourceMonitor) u32 {
        return self.current_usage.total_processes;
    }

    // Get running process count.
    pub fn get_running_processes(self: *const ResourceMonitor) u32 {
        return self.current_usage.running_processes;
    }

    // Get exited process count.
    pub fn get_exited_processes(self: *const ResourceMonitor) u32 {
        return self.current_usage.exited_processes;
    }

    // Get current usage.
    pub fn get_current_usage(self: *const ResourceMonitor) ResourceUsage
{
        return self.current_usage;
    }

    // Get history entry.
    pub fn get_history_entry(self: *const ResourceMonitor, index: u32)
?*const ResourceUsage {
        if (index >= self.history_len) {
            return null;
        }
        const actual_index = (self.history_index + MAX_HISTORY_ENTRIES -
self.history_len + index) % MAX_HISTORY_ENTRIES;
        return &self.history[actual_index];
    }

    // Get history count.
    pub fn get_history_count(self: *const ResourceMonitor) u32 {
        return self.history_len;
    }

    // Clear history.
    pub fn clear_history(self: *ResourceMonitor) void {
        self.history_len = 0;
        self.history_index = 0;
    }

    // Set syscall function.
    pub fn set_syscall_fn(self: *ResourceMonitor, fn_ptr: SyscallFn)
void {
        std.debug.assert(@intFromPtr(fn_ptr) != 0);
        self.syscall_fn = fn_ptr;
    }

    // Update from kernel sysinfo syscall.
    pub fn update_from_kernel(self: *ResourceMonitor, timestamp: u64)
bool {
        if (self.syscall_fn == null) {
            return false;
        }
        var sysinfo_buf: [56]u8 = undefined; // Enhanced SysInfo is 56
bytes.
        var i: u32 = 0;
        while (i < 56) : (i += 1) {
            sysinfo_buf[i] = 0;
        }
        const sysinfo_ptr = @intFromPtr(&sysinfo_buf);
        const result =
self.syscall_fn.?(@intFromEnum(basin_kernel.Syscall.sysinfo),
sysinfo_ptr, 0, 0, 0);
        if (result < 0) {
            return false;
        }
        const info = @as(*basin_kernel.SysInfo, @ptrCast(&sysinfo_buf));
        // Use enhanced sysinfo fields: used_memory, process counts.
        const cpu_percent: f64 = @as(f64,
@floatFromInt(info.load_avg_1min)) / 10.0;
        const clamped_cpu = @min(cpu_percent, 100.0);
        self.update_usage_with_processes(
            clamped_cpu,
            info.used_memory, // Use kernel-calculated used_memory.
            info.total_memory,
            0, // Disk not from kernel yet.
            0, // Disk not from kernel yet.
            info.total_processes,
            info.running_processes,
            info.exited_processes,
            timestamp,
        );
        return true;
    }
};


