// === grain_core/runtime_config.zig ===

//! Grain OS Runtime Configuration: riverctl-like IPC configuration
system.
//!
//! Why: Allow runtime configuration of compositor via IPC channels.
//! Architecture: IPC channel-based command processing.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");
const layout_generator = @import("layout_generator.zig");
const keyboard_shortcuts = @import("keyboard_shortcuts.zig");

// Bounded: Max configuration command length.
pub const MAX_CMD_LEN: u32 = 256;

// Bounded: Max number of configuration commands.
pub const MAX_COMMANDS: u32 = 32;

// Configuration command type.
pub const ConfigCommand = enum(u8) {
    set_layout,
    set_shortcut,
    set_border_width,
    set_title_bar_height,
    get_layout,
    get_shortcuts,
    unknown,
};

// Configuration command parser.
pub const ConfigParser = struct {
    pub fn parse_command(cmd_str: []const u8) ConfigCommand {
        std.debug.assert(cmd_str.len > 0);
        std.debug.assert(cmd_str.len <= MAX_CMD_LEN);
        // Parse command string (format: "command arg1 arg2 ...").
        if (std.mem.eql(u8, cmd_str, "set-layout")) {
            return ConfigCommand.set_layout;
        } else if (std.mem.eql(u8, cmd_str, "set-shortcut")) {
            return ConfigCommand.set_shortcut;
        } else if (std.mem.eql(u8, cmd_str, "set-border-width")) {
            return ConfigCommand.set_border_width;
        } else if (std.mem.eql(u8, cmd_str, "set-title-bar-height")) {
            return ConfigCommand.set_title_bar_height;
        } else if (std.mem.eql(u8, cmd_str, "get-layout")) {
            return ConfigCommand.get_layout;
        } else if (std.mem.eql(u8, cmd_str, "get-shortcuts")) {
            return ConfigCommand.get_shortcuts;
        }
        return ConfigCommand.unknown;
    }

    pub fn parse_layout_type(layout_str: []const u8)
?layout_generator.LayoutType {
        std.debug.assert(layout_str.len > 0);
        if (std.mem.eql(u8, layout_str, "tall")) {
            return layout_generator.LayoutType.tall;
        } else if (std.mem.eql(u8, layout_str, "wide")) {
            return layout_generator.LayoutType.wide;
        } else if (std.mem.eql(u8, layout_str, "grid")) {
            return layout_generator.LayoutType.grid;
        } else if (std.mem.eql(u8, layout_str, "monocle")) {
            return layout_generator.LayoutType.monocle;
        }
        return null;
    }
};

// Runtime configuration manager.
pub const RuntimeConfig = struct {
    compositor_ptr: *compositor.Compositor,
    config_channel_id: u32,

    pub fn init(comp: *compositor.Compositor, channel_id: u32)
RuntimeConfig {
        std.debug.assert(@intFromPtr(comp) != 0);
        std.debug.assert(channel_id > 0);
        return RuntimeConfig{
            .compositor_ptr = comp,
            .config_channel_id = channel_id,
        };
    }

    // Process configuration command from IPC channel.
    pub fn process_command(self: *RuntimeConfig, cmd_str: []const u8)
bool {
        std.debug.assert(cmd_str.len > 0);
        std.debug.assert(cmd_str.len <= MAX_CMD_LEN);
        const cmd = ConfigParser.parse_command(cmd_str);
        switch (cmd) {
            .set_layout => {
                // Parse layout type from command (format: "set-layout
tall").
                const split_result = self.split_command(cmd_str);
                if (split_result.len >= 2) {
                    if
(ConfigParser.parse_layout_type(split_result.parts[1])) |layout_type| {
                        _ = self.compositor_ptr.set_layout(layout_type);
                        return true;
                    }
                }
                return false;
            },
            .get_layout => {
                // Return current layout type (via channel response).
                const current_layout =
self.compositor_ptr.get_current_layout();
                _ = current_layout;
                return true;
            },
            .set_border_width => {
                // Parse border width from command (format:
"set-border-width 2").
                const split_result = self.split_command(cmd_str);
                if (split_result.len >= 2) {
                    const width = self.parse_u32(split_result.parts[1]);
                    if (width) |w| {
                        self.compositor_ptr.set_border_width(w);
                        return true;
                    }
                }
                return false;
            },
            .set_title_bar_height => {
                // Parse title bar height from command (format:
"set-title-bar-height 24").
                const split_result = self.split_command(cmd_str);
                if (split_result.len >= 2) {
                    const height = self.parse_u32(split_result.parts[1]);
                    if (height) |h| {
                        self.compositor_ptr.set_title_bar_height(h);
                        return true;
                    }
                }
                return false;
            },
            .set_shortcut, .get_shortcuts, .unknown => {
                return false;
            },
        }
    }

    // Split command string into parts (space-separated).
    fn split_command(self: *RuntimeConfig, cmd_str: []const u8) struct {
parts: [MAX_COMMANDS][]const u8, len: u32 } {
        _ = self;
        std.debug.assert(cmd_str.len > 0);
        // Simple split: find spaces.
        var parts: [MAX_COMMANDS][]const u8 = undefined;
        var parts_len: u32 = 0;
        var start: u32 = 0;
        var i: u32 = 0;
        while (i < cmd_str.len and parts_len < MAX_COMMANDS) : (i += 1) {
            if (cmd_str[i] == ' ' or cmd_str[i] == '\t') {
                if (i > start) {
                    parts[parts_len] = cmd_str[start..i];
                    parts_len += 1;
                }
                start = i + 1;
            }
        }
        if (start < cmd_str.len and parts_len < MAX_COMMANDS) {
            parts[parts_len] = cmd_str[start..];
            parts_len += 1;
        }
        std.debug.assert(parts_len <= MAX_COMMANDS);
        return .{ .parts = parts, .len = parts_len };
    }

    // Parse u32 from string.
    fn parse_u32(self: *RuntimeConfig, str: []const u8) ?u32 {
        _ = self;
        std.debug.assert(str.len > 0);
        var result: u32 = 0;
        var i: u32 = 0;
        while (i < str.len) : (i += 1) {
            const c = str[i];
            if (c >= '0' and c <= '9') {
                result = result * 10 + (c - '0');
            } else {
                return null;
            }
        }
        return result;
    }
};


// === grain_core/screen_capture.zig ===

//! Grain OS Screen Capture: Screenshot and screen recording.
//!
//! Why: Provide screen capture functionality for screenshots and
recordings.
//! Architecture: Framebuffer capture, image formats, capture regions.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max capture history.
pub const MAX_CAPTURES: u32 = 16;

// Bounded: Max capture name length.
pub const MAX_CAPTURE_NAME_LEN: u32 = 128;

// Capture format.
pub const CaptureFormat = enum(u8) {
    raw,
    png,
    jpeg,
};

// Capture type.
pub const CaptureType = enum(u8) {
    screenshot,
    recording,
};

// Capture: represents a screen capture.
pub const Capture = struct {
    capture_id: u32,
    capture_type: CaptureType,
    format: CaptureFormat,
    name: [MAX_CAPTURE_NAME_LEN]u8,
    name_len: u32,
    x: i32,
    y: i32,
    width: u32,
    height: u32,
    timestamp: u64,
    active: bool,

    pub fn init() Capture {
        var capture = Capture{
            .capture_id = 0,
            .capture_type = CaptureType.screenshot,
            .format = CaptureFormat.raw,
            .name = undefined,
            .name_len = 0,
            .x = 0,
            .y = 0,
            .width = 0,
            .height = 0,
            .timestamp = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_CAPTURE_NAME_LEN) : (i += 1) {
            capture.name[i] = 0;
        }
        return capture;
    }
};

// Screen capture manager: manages screen captures.
pub const ScreenCaptureManager = struct {
    captures: [MAX_CAPTURES]Capture,
    captures_len: u32,
    next_capture_id: u32,
    recording_active: bool,
    current_recording_id: u32,

    pub fn init() ScreenCaptureManager {
        var manager = ScreenCaptureManager{
            .captures = undefined,
            .captures_len = 0,
            .next_capture_id = 1,
            .recording_active = false,
            .current_recording_id = 0,
        };
        var i: u32 = 0;
        while (i < MAX_CAPTURES) : (i += 1) {
            manager.captures[i] = Capture.init();
        }
        return manager;
    }

    // Capture screenshot.
    pub fn capture_screenshot(
        self: *ScreenCaptureManager,
        name: []const u8,
        x: i32,
        y: i32,
        width: u32,
        height: u32,
        format: CaptureFormat,
        timestamp: u64,
    ) ?u32 {
        if (self.captures_len >= MAX_CAPTURES) {
            return null;
        }
        if (name.len > MAX_CAPTURE_NAME_LEN) {
            return null;
        }
        const capture_id = self.next_capture_id;
        self.next_capture_id += 1;
        self.captures[self.captures_len] = Capture.init();
        self.captures[self.captures_len].capture_id = capture_id;
        self.captures[self.captures_len].capture_type =
CaptureType.screenshot;
        self.captures[self.captures_len].format = format;
        self.captures[self.captures_len].x = x;
        self.captures[self.captures_len].y = y;
        self.captures[self.captures_len].width = width;
        self.captures[self.captures_len].height = height;
        self.captures[self.captures_len].timestamp = timestamp;
        self.captures[self.captures_len].active = true;
        var i: u32 = 0;
        while (i < MAX_CAPTURE_NAME_LEN) : (i += 1) {
            self.captures[self.captures_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_CAPTURE_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.captures[self.captures_len].name[i] = name[i];
        }
        self.captures[self.captures_len].name_len = @intCast(name_len);
        self.captures_len += 1;
        return capture_id;
    }

    // Start recording.
    pub fn start_recording(
        self: *ScreenCaptureManager,
        name: []const u8,
        x: i32,
        y: i32,
        width: u32,
        height: u32,
        format: CaptureFormat,
        timestamp: u64,
    ) ?u32 {
        if (self.recording_active) {
            return null;
        }
        if (self.captures_len >= MAX_CAPTURES) {
            return null;
        }
        if (name.len > MAX_CAPTURE_NAME_LEN) {
            return null;
        }
        const capture_id = self.next_capture_id;
        self.next_capture_id += 1;
        self.captures[self.captures_len] = Capture.init();
        self.captures[self.captures_len].capture_id = capture_id;
        self.captures[self.captures_len].capture_type =
CaptureType.recording;
        self.captures[self.captures_len].format = format;
        self.captures[self.captures_len].x = x;
        self.captures[self.captures_len].y = y;
        self.captures[self.captures_len].width = width;
        self.captures[self.captures_len].height = height;
        self.captures[self.captures_len].timestamp = timestamp;
        self.captures[self.captures_len].active = true;
        var i: u32 = 0;
        while (i < MAX_CAPTURE_NAME_LEN) : (i += 1) {
            self.captures[self.captures_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_CAPTURE_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.captures[self.captures_len].name[i] = name[i];
        }
        self.captures[self.captures_len].name_len = @intCast(name_len);
        self.captures_len += 1;
        self.recording_active = true;
        self.current_recording_id = capture_id;
        return capture_id;
    }

    // Stop recording.
    pub fn stop_recording(self: *ScreenCaptureManager) bool {
        if (!self.recording_active) {
            return false;
        }
        self.recording_active = false;
        self.current_recording_id = 0;
        return true;
    }

    // Find capture by ID.
    pub fn find_capture(
        self: *ScreenCaptureManager,
        capture_id: u32,
    ) ?*Capture {
        std.debug.assert(capture_id > 0);
        var i: u32 = 0;
        while (i < self.captures_len) : (i += 1) {
            if (self.captures[i].capture_id == capture_id and
self.captures[i].active) {
                return &self.captures[i];
            }
        }
        return null;
    }

    // Remove capture.
    pub fn remove_capture(self: *ScreenCaptureManager, capture_id: u32)
bool {
        std.debug.assert(capture_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.captures_len) : (i += 1) {
            if (self.captures[i].capture_id == capture_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        if (self.current_recording_id == capture_id) {
            self.recording_active = false;
            self.current_recording_id = 0;
        }
        // Shift remaining captures left.
        while (i < self.captures_len - 1) : (i += 1) {
            self.captures[i] = self.captures[i + 1];
        }
        self.captures_len -= 1;
        return true;
    }

    // Check if recording is active.
    pub fn is_recording_active(self: *const ScreenCaptureManager) bool {
        return self.recording_active;
    }

    // Get current recording ID.
    pub fn get_current_recording_id(self: *const ScreenCaptureManager)
?u32 {
        if (self.recording_active) {
            return self.current_recording_id;
        }
        return null;
    }

    // Get capture count.
    pub fn get_capture_count(self: *const ScreenCaptureManager) u32 {
        return self.captures_len;
    }
};


// === grain_core/security_manager.zig ===

//! Grain OS Security Manager: User permissions and access control.
//!
//! Why: Provide security management for user permissions and access
control.
//! Architecture: Permission management, access control, security
policies.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max permissions.
pub const MAX_PERMISSIONS: u32 = 64;

// Bounded: Max permission name length.
pub const MAX_PERMISSION_NAME_LEN: u32 = 64;

// Bounded: Max users.
pub const MAX_USERS: u32 = 32;

// Bounded: Max user name length.
pub const MAX_USER_NAME_LEN: u32 = 64;

// Permission type.
pub const PermissionType = enum(u8) {
    none,
    read,
    write,
    execute,
    admin,
    full_control,
};

// User role.
pub const UserRole = enum(u8) {
    guest,
    user,
    admin,
    root,
};

// Permission: represents a permission.
pub const Permission = struct {
    permission_id: u32,
    name: [MAX_PERMISSION_NAME_LEN]u8,
    name_len: u32,
    permission_type: PermissionType,
    active: bool,

    pub fn init() Permission {
        var perm = Permission{
            .permission_id = 0,
            .name = undefined,
            .name_len = 0,
            .permission_type = PermissionType.none,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_PERMISSION_NAME_LEN) : (i += 1) {
            perm.name[i] = 0;
        }
        return perm;
    }
};

// User: represents a system user.
pub const User = struct {
    user_id: u32,
    name: [MAX_USER_NAME_LEN]u8,
    name_len: u32,
    role: UserRole,
    permissions: [MAX_PERMISSIONS]u32, // Permission IDs.
    permissions_len: u32,
    active: bool,

    pub fn init() User {
        var user = User{
            .user_id = 0,
            .name = undefined,
            .name_len = 0,
            .role = UserRole.user,
            .permissions = undefined,
            .permissions_len = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_USER_NAME_LEN) : (i += 1) {
            user.name[i] = 0;
        }
        i = 0;
        while (i < MAX_PERMISSIONS) : (i += 1) {
            user.permissions[i] = 0;
        }
        return user;
    }
};

// Security manager: manages permissions and users.
pub const SecurityManager = struct {
    permissions: [MAX_PERMISSIONS]Permission,
    permissions_len: u32,
    next_permission_id: u32,
    users: [MAX_USERS]User,
    users_len: u32,
    next_user_id: u32,
    current_user_id: u32,

    pub fn init() SecurityManager {
        var manager = SecurityManager{
            .permissions = undefined,
            .permissions_len = 0,
            .next_permission_id = 1,
            .users = undefined,
            .users_len = 0,
            .next_user_id = 1,
            .current_user_id = 0,
        };
        var i: u32 = 0;
        while (i < MAX_PERMISSIONS) : (i += 1) {
            manager.permissions[i] = Permission.init();
        }
        i = 0;
        while (i < MAX_USERS) : (i += 1) {
            manager.users[i] = User.init();
        }
        return manager;
    }

    // Add permission.
    pub fn add_permission(
        self: *SecurityManager,
        name: []const u8,
        permission_type: PermissionType,
    ) ?u32 {
        if (self.permissions_len >= MAX_PERMISSIONS) {
            return null;
        }
        if (name.len > MAX_PERMISSION_NAME_LEN) {
            return null;
        }
        const permission_id = self.next_permission_id;
        self.next_permission_id += 1;
        self.permissions[self.permissions_len] = Permission.init();
        self.permissions[self.permissions_len].permission_id =
permission_id;
        self.permissions[self.permissions_len].permission_type =
permission_type;
        self.permissions[self.permissions_len].active = true;
        var i: u32 = 0;
        while (i < MAX_PERMISSION_NAME_LEN) : (i += 1) {
            self.permissions[self.permissions_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_PERMISSION_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.permissions[self.permissions_len].name[i] = name[i];
        }
        self.permissions[self.permissions_len].name_len =
@intCast(name_len);
        self.permissions_len += 1;
        return permission_id;
    }

    // Find permission by ID.
    pub fn find_permission(
        self: *SecurityManager,
        permission_id: u32,
    ) ?*Permission {
        std.debug.assert(permission_id > 0);
        var i: u32 = 0;
        while (i < self.permissions_len) : (i += 1) {
            if (self.permissions[i].permission_id == permission_id and
self.permissions[i].active) {
                return &self.permissions[i];
            }
        }
        return null;
    }

    // Add user.
    pub fn add_user(
        self: *SecurityManager,
        name: []const u8,
        role: UserRole,
    ) ?u32 {
        if (self.users_len >= MAX_USERS) {
            return null;
        }
        if (name.len > MAX_USER_NAME_LEN) {
            return null;
        }
        const user_id = self.next_user_id;
        self.next_user_id += 1;
        self.users[self.users_len] = User.init();
        self.users[self.users_len].user_id = user_id;
        self.users[self.users_len].role = role;
        self.users[self.users_len].active = true;
        var i: u32 = 0;
        while (i < MAX_USER_NAME_LEN) : (i += 1) {
            self.users[self.users_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_USER_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.users[self.users_len].name[i] = name[i];
        }
        self.users[self.users_len].name_len = @intCast(name_len);
        if (self.current_user_id == 0) {
            self.current_user_id = user_id;
        }
        self.users_len += 1;
        return user_id;
    }

    // Find user by ID.
    pub fn find_user(
        self: *SecurityManager,
        user_id: u32,
    ) ?*User {
        std.debug.assert(user_id > 0);
        var i: u32 = 0;
        while (i < self.users_len) : (i += 1) {
            if (self.users[i].user_id == user_id and
self.users[i].active) {
                return &self.users[i];
            }
        }
        return null;
    }

    // Grant permission to user.
    pub fn grant_permission(
        self: *SecurityManager,
        user_id: u32,
        permission_id: u32,
    ) bool {
        std.debug.assert(user_id > 0);
        std.debug.assert(permission_id > 0);
        if (self.find_user(user_id)) |user| {
            if (user.permissions_len >= MAX_PERMISSIONS) {
                return false;
            }
            var i: u32 = 0;
            while (i < user.permissions_len) : (i += 1) {
                if (user.permissions[i] == permission_id) {
                    return false; // Already granted.
                }
            }
            user.permissions[user.permissions_len] = permission_id;
            user.permissions_len += 1;
            return true;
        }
        return false;
    }

    // Revoke permission from user.
    pub fn revoke_permission(
        self: *SecurityManager,
        user_id: u32,
        permission_id: u32,
    ) bool {
        std.debug.assert(user_id > 0);
        std.debug.assert(permission_id > 0);
        if (self.find_user(user_id)) |user| {
            var i: u32 = 0;
            var found: bool = false;
            while (i < user.permissions_len) : (i += 1) {
                if (user.permissions[i] == permission_id) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                return false;
            }
            while (i < user.permissions_len - 1) : (i += 1) {
                user.permissions[i] = user.permissions[i + 1];
            }
            user.permissions_len -= 1;
            return true;
        }
        return false;
    }

    // Check if user has permission.
    pub fn has_permission(
        self: *SecurityManager,
        user_id: u32,
        permission_id: u32,
    ) bool {
        std.debug.assert(user_id > 0);
        std.debug.assert(permission_id > 0);
        if (self.find_user(user_id)) |user| {
            if (user.role == UserRole.root) {
                return true; // Root has all permissions.
            }
            var i: u32 = 0;
            while (i < user.permissions_len) : (i += 1) {
                if (user.permissions[i] == permission_id) {
                    return true;
                }
            }
        }
        return false;
    }

    // Set current user.
    pub fn set_current_user(self: *SecurityManager, user_id: u32) bool {
        std.debug.assert(user_id > 0);
        if (self.find_user(user_id)) |_| {
            self.current_user_id = user_id;
            return true;
        }
        return false;
    }

    // Get current user.
    pub fn get_current_user(self: *const SecurityManager) ?*const User {
        if (self.current_user_id == 0) {
            return null;
        }
        var i: u32 = 0;
        while (i < self.users_len) : (i += 1) {
            if (self.users[i].user_id == self.current_user_id) {
                return &self.users[i];
            }
        }
        return null;
    }

    // Remove user.
    pub fn remove_user(self: *SecurityManager, user_id: u32) bool {
        std.debug.assert(user_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.users_len) : (i += 1) {
            if (self.users[i].user_id == user_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        if (self.current_user_id == user_id) {
            self.current_user_id = 0;
        }
        while (i < self.users_len - 1) : (i += 1) {
            self.users[i] = self.users[i + 1];
        }
        self.users_len -= 1;
        return true;
    }

    // Get permission count.
    pub fn get_permission_count(self: *const SecurityManager) u32 {
        return self.permissions_len;
    }

    // Get user count.
    pub fn get_user_count(self: *const SecurityManager) u32 {
        return self.users_len;
    }
};


// === grain_core/service_manager.zig ===

//! Grain OS Service Manager: System services management.
//!
//! Why: Provide service management for system services and daemons.
//! Architecture: Service lifecycle, service state, service dependencies.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max services.
pub const MAX_SERVICES: u32 = 64;

// Bounded: Max service name length.
pub const MAX_SERVICE_NAME_LEN: u32 = 128;

// Bounded: Max service description length.
pub const MAX_SERVICE_DESC_LEN: u32 = 256;

// Bounded: Max dependencies per service.
pub const MAX_DEPENDENCIES: u32 = 16;

// Service state.
pub const ServiceState = enum(u8) {
    stopped,
    starting,
    running,
    stopping,
    failed,
    disabled,
};

// Service type.
pub const ServiceType = enum(u8) {
    system,
    user,
    network,
    filesystem,
    device,
    other,
};

// Service: represents a system service.
pub const Service = struct {
    service_id: u32,
    name: [MAX_SERVICE_NAME_LEN]u8,
    name_len: u32,
    description: [MAX_SERVICE_DESC_LEN]u8,
    description_len: u32,
    service_type: ServiceType,
    state: ServiceState,
    dependencies: [MAX_DEPENDENCIES]u32, // Service IDs.
    dependencies_len: u32,
    auto_start: bool,
    restart_on_failure: bool,
    active: bool,

    pub fn init() Service {
        var service = Service{
            .service_id = 0,
            .name = undefined,
            .name_len = 0,
            .description = undefined,
            .description_len = 0,
            .service_type = ServiceType.other,
            .state = ServiceState.stopped,
            .dependencies = undefined,
            .dependencies_len = 0,
            .auto_start = false,
            .restart_on_failure = false,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_SERVICE_NAME_LEN) : (i += 1) {
            service.name[i] = 0;
        }
        i = 0;
        while (i < MAX_SERVICE_DESC_LEN) : (i += 1) {
            service.description[i] = 0;
        }
        i = 0;
        while (i < MAX_DEPENDENCIES) : (i += 1) {
            service.dependencies[i] = 0;
        }
        return service;
    }
};

// Service manager: manages system services.
pub const ServiceManager = struct {
    services: [MAX_SERVICES]Service,
    services_len: u32,
    next_service_id: u32,

    pub fn init() ServiceManager {
        var manager = ServiceManager{
            .services = undefined,
            .services_len = 0,
            .next_service_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_SERVICES) : (i += 1) {
            manager.services[i] = Service.init();
        }
        return manager;
    }

    // Add service.
    pub fn add_service(
        self: *ServiceManager,
        name: []const u8,
        description: []const u8,
        service_type: ServiceType,
    ) ?u32 {
        if (self.services_len >= MAX_SERVICES) {
            return null;
        }
        if (name.len > MAX_SERVICE_NAME_LEN) {
            return null;
        }
        if (description.len > MAX_SERVICE_DESC_LEN) {
            return null;
        }
        const service_id = self.next_service_id;
        self.next_service_id += 1;
        self.services[self.services_len] = Service.init();
        self.services[self.services_len].service_id = service_id;
        self.services[self.services_len].service_type = service_type;
        self.services[self.services_len].state = ServiceState.stopped;
        self.services[self.services_len].active = true;
        var i: u32 = 0;
        while (i < MAX_SERVICE_NAME_LEN) : (i += 1) {
            self.services[self.services_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_SERVICE_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.services[self.services_len].name[i] = name[i];
        }
        self.services[self.services_len].name_len = @intCast(name_len);
        i = 0;
        while (i < MAX_SERVICE_DESC_LEN) : (i += 1) {
            self.services[self.services_len].description[i] = 0;
        }
        const desc_len = @min(description.len, MAX_SERVICE_DESC_LEN);
        i = 0;
        while (i < desc_len) : (i += 1) {
            self.services[self.services_len].description[i] =
description[i];
        }
        self.services[self.services_len].description_len =
@intCast(desc_len);
        self.services_len += 1;
        return service_id;
    }

    // Find service by ID.
    pub fn find_service(
        self: *ServiceManager,
        service_id: u32,
    ) ?*Service {
        std.debug.assert(service_id > 0);
        var i: u32 = 0;
        while (i < self.services_len) : (i += 1) {
            if (self.services[i].service_id == service_id and
self.services[i].active) {
                return &self.services[i];
            }
        }
        return null;
    }

    // Start service.
    pub fn start_service(self: *ServiceManager, service_id: u32) bool {
        std.debug.assert(service_id > 0);
        if (self.find_service(service_id)) |service| {
            if (service.state == ServiceState.stopped or service.state
== ServiceState.failed) {
                service.state = ServiceState.starting;
                // Would start actual service in full implementation.
                service.state = ServiceState.running;
                return true;
            }
        }
        return false;
    }

    // Stop service.
    pub fn stop_service(self: *ServiceManager, service_id: u32) bool {
        std.debug.assert(service_id > 0);
        if (self.find_service(service_id)) |service| {
            if (service.state == ServiceState.running) {
                service.state = ServiceState.stopping;
                // Would stop actual service in full implementation.
                service.state = ServiceState.stopped;
                return true;
            }
        }
        return false;
    }

    // Restart service.
    pub fn restart_service(self: *ServiceManager, service_id: u32) bool {
        std.debug.assert(service_id > 0);
        if (self.stop_service(service_id)) {
            return self.start_service(service_id);
        }
        return false;
    }

    // Enable service auto-start.
    pub fn enable_auto_start(self: *ServiceManager, service_id: u32)
bool {
        std.debug.assert(service_id > 0);
        if (self.find_service(service_id)) |service| {
            service.auto_start = true;
            return true;
        }
        return false;
    }

    // Disable service auto-start.
    pub fn disable_auto_start(self: *ServiceManager, service_id: u32)
bool {
        std.debug.assert(service_id > 0);
        if (self.find_service(service_id)) |service| {
            service.auto_start = false;
            return true;
        }
        return false;
    }

    // Enable restart on failure.
    pub fn enable_restart_on_failure(self: *ServiceManager, service_id:
u32) bool {
        std.debug.assert(service_id > 0);
        if (self.find_service(service_id)) |service| {
            service.restart_on_failure = true;
            return true;
        }
        return false;
    }

    // Disable restart on failure.
    pub fn disable_restart_on_failure(self: *ServiceManager, service_id:
u32) bool {
        std.debug.assert(service_id > 0);
        if (self.find_service(service_id)) |service| {
            service.restart_on_failure = false;
            return true;
        }
        return false;
    }

    // Add dependency.
    pub fn add_dependency(
        self: *ServiceManager,
        service_id: u32,
        dependency_id: u32,
    ) bool {
        std.debug.assert(service_id > 0);
        std.debug.assert(dependency_id > 0);
        if (self.find_service(service_id)) |service| {
            if (service.dependencies_len >= MAX_DEPENDENCIES) {
                return false;
            }
            var i: u32 = 0;
            while (i < service.dependencies_len) : (i += 1) {
                if (service.dependencies[i] == dependency_id) {
                    return false; // Already a dependency.
                }
            }
            service.dependencies[service.dependencies_len] =
dependency_id;
            service.dependencies_len += 1;
            return true;
        }
        return false;
    }

    // Remove dependency.
    pub fn remove_dependency(
        self: *ServiceManager,
        service_id: u32,
        dependency_id: u32,
    ) bool {
        std.debug.assert(service_id > 0);
        std.debug.assert(dependency_id > 0);
        if (self.find_service(service_id)) |service| {
            var i: u32 = 0;
            var found: bool = false;
            while (i < service.dependencies_len) : (i += 1) {
                if (service.dependencies[i] == dependency_id) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                return false;
            }
            while (i < service.dependencies_len - 1) : (i += 1) {
                service.dependencies[i] = service.dependencies[i + 1];
            }
            service.dependencies_len -= 1;
            return true;
        }
        return false;
    }

    // Remove service.
    pub fn remove_service(self: *ServiceManager, service_id: u32) bool {
        std.debug.assert(service_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.services_len) : (i += 1) {
            if (self.services[i].service_id == service_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        while (i < self.services_len - 1) : (i += 1) {
            self.services[i] = self.services[i + 1];
        }
        self.services_len -= 1;
        return true;
    }

    // Get service count.
    pub fn get_service_count(self: *const ServiceManager) u32 {
        return self.services_len;
    }

    // Get running service count.
    pub fn get_running_service_count(self: *const ServiceManager) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.services_len) : (i += 1) {
            if (self.services[i].state == ServiceState.running) {
                count += 1;
            }
        }
        return count;
    }
};


// === grain_core/settings_manager.zig ===

//! Grain OS Settings Manager: System settings and configuration
management.
//!
//! Why: Provide centralized settings management for system
configuration.
//! Architecture: Settings storage, categories, value types, persistence.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max settings.
pub const MAX_SETTINGS: u32 = 256;

// Bounded: Max setting key length.
pub const MAX_KEY_LEN: u32 = 64;

// Bounded: Max setting value length.
pub const MAX_VALUE_LEN: u32 = 256;

// Bounded: Max categories.
pub const MAX_CATEGORIES: u32 = 16;

// Bounded: Max category name length.
pub const MAX_CATEGORY_NAME_LEN: u32 = 32;

// Setting value type.
pub const SettingValueType = enum(u8) {
    string,
    integer,
    boolean,
    float,
};

// Setting: represents a system setting.
pub const Setting = struct {
    setting_id: u32,
    category_id: u32,
    key: [MAX_KEY_LEN]u8,
    key_len: u32,
    value_type: SettingValueType,
    value_string: [MAX_VALUE_LEN]u8,
    value_string_len: u32,
    value_integer: i64,
    value_boolean: bool,
    value_float: f64,
    active: bool,

    pub fn init() Setting {
        var setting = Setting{
            .setting_id = 0,
            .category_id = 0,
            .key = undefined,
            .key_len = 0,
            .value_type = SettingValueType.string,
            .value_string = undefined,
            .value_string_len = 0,
            .value_integer = 0,
            .value_boolean = false,
            .value_float = 0.0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_KEY_LEN) : (i += 1) {
            setting.key[i] = 0;
        }
        i = 0;
        while (i < MAX_VALUE_LEN) : (i += 1) {
            setting.value_string[i] = 0;
        }
        return setting;
    }
};

// Category: represents a settings category.
pub const Category = struct {
    category_id: u32,
    name: [MAX_CATEGORY_NAME_LEN]u8,
    name_len: u32,
    active: bool,

    pub fn init() Category {
        var category = Category{
            .category_id = 0,
            .name = undefined,
            .name_len = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_CATEGORY_NAME_LEN) : (i += 1) {
            category.name[i] = 0;
        }
        return category;
    }
};

// Settings manager: manages system settings.
pub const SettingsManager = struct {
    settings: [MAX_SETTINGS]Setting,
    settings_len: u32,
    categories: [MAX_CATEGORIES]Category,
    categories_len: u32,
    next_setting_id: u32,
    next_category_id: u32,

    pub fn init() SettingsManager {
        var manager = SettingsManager{
            .settings = undefined,
            .settings_len = 0,
            .categories = undefined,
            .categories_len = 0,
            .next_setting_id = 1,
            .next_category_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_SETTINGS) : (i += 1) {
            manager.settings[i] = Setting.init();
        }
        i = 0;
        while (i < MAX_CATEGORIES) : (i += 1) {
            manager.categories[i] = Category.init();
        }
        return manager;
    }

    // Add category.
    pub fn add_category(self: *SettingsManager, name: []const u8) ?u32 {
        if (self.categories_len >= MAX_CATEGORIES) {
            return null;
        }
        if (name.len > MAX_CATEGORY_NAME_LEN) {
            return null;
        }
        const category_id = self.next_category_id;
        self.next_category_id += 1;
        self.categories[self.categories_len] = Category.init();
        self.categories[self.categories_len].category_id = category_id;
        self.categories[self.categories_len].active = true;
        var i: u32 = 0;
        while (i < MAX_CATEGORY_NAME_LEN) : (i += 1) {
            self.categories[self.categories_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_CATEGORY_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.categories[self.categories_len].name[i] = name[i];
        }
        self.categories[self.categories_len].name_len =
@intCast(name_len);
        self.categories_len += 1;
        return category_id;
    }

    // Find category by ID.
    pub fn find_category(
        self: *SettingsManager,
        category_id: u32,
    ) ?*Category {
        std.debug.assert(category_id > 0);
        var i: u32 = 0;
        while (i < self.categories_len) : (i += 1) {
            if (self.categories[i].category_id == category_id and
self.categories[i].active) {
                return &self.categories[i];
            }
        }
        return null;
    }

    // Add setting.
    pub fn add_setting(
        self: *SettingsManager,
        category_id: u32,
        key: []const u8,
        value_type: SettingValueType,
    ) ?u32 {
        if (self.settings_len >= MAX_SETTINGS) {
            return null;
        }
        if (key.len > MAX_KEY_LEN) {
            return null;
        }
        if (self.find_category(category_id) == null) {
            return null;
        }
        const setting_id = self.next_setting_id;
        self.next_setting_id += 1;
        self.settings[self.settings_len] = Setting.init();
        self.settings[self.settings_len].setting_id = setting_id;
        self.settings[self.settings_len].category_id = category_id;
        self.settings[self.settings_len].value_type = value_type;
        self.settings[self.settings_len].active = true;
        var i: u32 = 0;
        while (i < MAX_KEY_LEN) : (i += 1) {
            self.settings[self.settings_len].key[i] = 0;
        }
        const key_len = @min(key.len, MAX_KEY_LEN);
        i = 0;
        while (i < key_len) : (i += 1) {
            self.settings[self.settings_len].key[i] = key[i];
        }
        self.settings[self.settings_len].key_len = @intCast(key_len);
        self.settings_len += 1;
        return setting_id;
    }

    // Find setting by ID.
    pub fn find_setting(
        self: *SettingsManager,
        setting_id: u32,
    ) ?*Setting {
        std.debug.assert(setting_id > 0);
        var i: u32 = 0;
        while (i < self.settings_len) : (i += 1) {
            if (self.settings[i].setting_id == setting_id and
self.settings[i].active) {
                return &self.settings[i];
            }
        }
        return null;
    }

    // Find setting by key.
    pub fn find_setting_by_key(
        self: *SettingsManager,
        category_id: u32,
        key: []const u8,
    ) ?*Setting {
        std.debug.assert(category_id > 0);
        var i: u32 = 0;
        while (i < self.settings_len) : (i += 1) {
            if (self.settings[i].category_id == category_id and
self.settings[i].active) {
                const key_slice =
self.settings[i].key[0..self.settings[i].key_len];
                if (std.mem.eql(u8, key_slice, key)) {
                    return &self.settings[i];
                }
            }
        }
        return null;
    }

    // Set setting string value.
    pub fn set_setting_string(
        self: *SettingsManager,
        setting_id: u32,
        value: []const u8,
    ) bool {
        std.debug.assert(setting_id > 0);
        if (value.len > MAX_VALUE_LEN) {
            return false;
        }
        if (self.find_setting(setting_id)) |setting| {
            if (setting.value_type != SettingValueType.string) {
                return false;
            }
            var i: u32 = 0;
            while (i < MAX_VALUE_LEN) : (i += 1) {
                setting.value_string[i] = 0;
            }
            const value_len = @min(value.len, MAX_VALUE_LEN);
            i = 0;
            while (i < value_len) : (i += 1) {
                setting.value_string[i] = value[i];
            }
            setting.value_string_len = @intCast(value_len);
            return true;
        }
        return false;
    }

    // Set setting integer value.
    pub fn set_setting_integer(
        self: *SettingsManager,
        setting_id: u32,
        value: i64,
    ) bool {
        std.debug.assert(setting_id > 0);
        if (self.find_setting(setting_id)) |setting| {
            if (setting.value_type != SettingValueType.integer) {
                return false;
            }
            setting.value_integer = value;
            return true;
        }
        return false;
    }

    // Set setting boolean value.
    pub fn set_setting_boolean(
        self: *SettingsManager,
        setting_id: u32,
        value: bool,
    ) bool {
        std.debug.assert(setting_id > 0);
        if (self.find_setting(setting_id)) |setting| {
            if (setting.value_type != SettingValueType.boolean) {
                return false;
            }
            setting.value_boolean = value;
            return true;
        }
        return false;
    }

    // Set setting float value.
    pub fn set_setting_float(
        self: *SettingsManager,
        setting_id: u32,
        value: f64,
    ) bool {
        std.debug.assert(setting_id > 0);
        if (self.find_setting(setting_id)) |setting| {
            if (setting.value_type != SettingValueType.float) {
                return false;
            }
            setting.value_float = value;
            return true;
        }
        return false;
    }

    // Remove setting.
    pub fn remove_setting(self: *SettingsManager, setting_id: u32) bool {
        std.debug.assert(setting_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.settings_len) : (i += 1) {
            if (self.settings[i].setting_id == setting_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining settings left.
        while (i < self.settings_len - 1) : (i += 1) {
            self.settings[i] = self.settings[i + 1];
        }
        self.settings_len -= 1;
        return true;
    }

    // Get setting count.
    pub fn get_setting_count(self: *const SettingsManager) u32 {
        return self.settings_len;
    }

    // Get category count.
    pub fn get_category_count(self: *const SettingsManager) u32 {
        return self.categories_len;
    }
};


// === grain_core/system_diagnostics.zig ===

//! Grain OS System Diagnostics: System diagnostic information and
troubleshooting.
//!
//! Why: Provide diagnostic information for troubleshooting system
issues.
//! Architecture: Diagnostic checks, issue detection, diagnostic
reporting.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max diagnostic checks.
pub const MAX_DIAGNOSTIC_CHECKS: u32 = 32;

// Bounded: Max diagnostic check name length.
pub const MAX_CHECK_NAME_LEN: u32 = 64;

// Bounded: Max diagnostic message length.
pub const MAX_DIAGNOSTIC_MSG_LEN: u32 = 256;

// Diagnostic severity.
pub const DiagnosticSeverity = enum(u8) {
    info,
    warning,
    err,
    critical,
};

// Diagnostic check: represents a diagnostic check.
pub const DiagnosticCheck = struct {
    check_id: u32,
    name: [MAX_CHECK_NAME_LEN]u8,
    name_len: u32,
    severity: DiagnosticSeverity,
    message: [MAX_DIAGNOSTIC_MSG_LEN]u8,
    message_len: u32,
    timestamp: u64,
    active: bool,

    pub fn init() DiagnosticCheck {
        var check = DiagnosticCheck{
            .check_id = 0,
            .name = undefined,
            .name_len = 0,
            .severity = DiagnosticSeverity.info,
            .message = undefined,
            .message_len = 0,
            .timestamp = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_CHECK_NAME_LEN) : (i += 1) {
            check.name[i] = 0;
        }
        i = 0;
        while (i < MAX_DIAGNOSTIC_MSG_LEN) : (i += 1) {
            check.message[i] = 0;
        }
        return check;
    }
};

// System diagnostics: provides system diagnostic information.
pub const SystemDiagnostics = struct {
    checks: [MAX_DIAGNOSTIC_CHECKS]DiagnosticCheck,
    checks_len: u32,
    next_check_id: u32,

    pub fn init() SystemDiagnostics {
        var diagnostics = SystemDiagnostics{
            .checks = undefined,
            .checks_len = 0,
            .next_check_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_DIAGNOSTIC_CHECKS) : (i += 1) {
            diagnostics.checks[i] = DiagnosticCheck.init();
        }
        return diagnostics;
    }

    // Add diagnostic check.
    pub fn add_diagnostic_check(
        self: *SystemDiagnostics,
        name: []const u8,
        severity: DiagnosticSeverity,
        message: []const u8,
        timestamp: u64,
    ) ?u32 {
        if (self.checks_len >= MAX_DIAGNOSTIC_CHECKS) {
            return null;
        }
        if (name.len > MAX_CHECK_NAME_LEN) {
            return null;
        }
        if (message.len > MAX_DIAGNOSTIC_MSG_LEN) {
            return null;
        }
        const check_id = self.next_check_id;
        self.next_check_id += 1;
        self.checks[self.checks_len] = DiagnosticCheck.init();
        self.checks[self.checks_len].check_id = check_id;
        self.checks[self.checks_len].severity = severity;
        self.checks[self.checks_len].timestamp = timestamp;
        self.checks[self.checks_len].active = true;
        var i: u32 = 0;
        while (i < MAX_CHECK_NAME_LEN) : (i += 1) {
            self.checks[self.checks_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_CHECK_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.checks[self.checks_len].name[i] = name[i];
        }
        self.checks[self.checks_len].name_len = @intCast(name_len);
        i = 0;
        while (i < MAX_DIAGNOSTIC_MSG_LEN) : (i += 1) {
            self.checks[self.checks_len].message[i] = 0;
        }
        const msg_len = @min(message.len, MAX_DIAGNOSTIC_MSG_LEN);
        i = 0;
        while (i < msg_len) : (i += 1) {
            self.checks[self.checks_len].message[i] = message[i];
        }
        self.checks[self.checks_len].message_len = @intCast(msg_len);
        self.checks_len += 1;
        return check_id;
    }

    // Find diagnostic check by ID.
    pub fn find_diagnostic_check(
        self: *SystemDiagnostics,
        check_id: u32,
    ) ?*DiagnosticCheck {
        std.debug.assert(check_id > 0);
        var i: u32 = 0;
        while (i < self.checks_len) : (i += 1) {
            if (self.checks[i].check_id == check_id and
self.checks[i].active) {
                return &self.checks[i];
            }
        }
        return null;
    }

    // Remove diagnostic check.
    pub fn remove_diagnostic_check(
        self: *SystemDiagnostics,
        check_id: u32,
    ) bool {
        std.debug.assert(check_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.checks_len) : (i += 1) {
            if (self.checks[i].check_id == check_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        while (i < self.checks_len - 1) : (i += 1) {
            self.checks[i] = self.checks[i + 1];
        }
        self.checks_len -= 1;
        return true;
    }

    // Get diagnostic check count.
    pub fn get_diagnostic_check_count(self: *const SystemDiagnostics)
u32 {
        return self.checks_len;
    }

    // Get diagnostic check count by severity.
    pub fn get_diagnostic_check_count_by_severity(
        self: *const SystemDiagnostics,
        severity: DiagnosticSeverity,
    ) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.checks_len) : (i += 1) {
            if (self.checks[i].severity == severity) {
                count += 1;
            }
        }
        return count;
    }

    // Clear all diagnostic checks.
    pub fn clear_all(self: *SystemDiagnostics) void {
        self.checks_len = 0;
    }

    // Clear diagnostic checks by severity.
    pub fn clear_by_severity(
        self: *SystemDiagnostics,
        severity: DiagnosticSeverity,
    ) void {
        var i: u32 = 0;
        while (i < self.checks_len) : (i += 1) {
            if (self.checks[i].severity == severity) {
                var j: u32 = i;
                while (j < self.checks_len - 1) : (j += 1) {
                    self.checks[j] = self.checks[j + 1];
                }
                self.checks_len -= 1;
                i -= 1; // Re-check current index.
            }
        }
    }
};


// === grain_core/system_logger.zig ===

//! Grain OS System Logger: System event logging and log management.
//!
//! Why: Provide system logging for events, errors, and debugging.
//! Architecture: Log entry management, log levels, log filtering.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max log entries.
pub const MAX_LOG_ENTRIES: u32 = 1024;

// Bounded: Max log message length.
pub const MAX_LOG_MESSAGE_LEN: u32 = 512;

// Bounded: Max log source length.
pub const MAX_LOG_SOURCE_LEN: u32 = 64;

// Log level.
pub const LogLevel = enum(u8) {
    debug,
    info,
    warning,
    err,
    critical,
};

// Log entry: represents a log entry.
pub const LogEntry = struct {
    entry_id: u32,
    timestamp: u64, // Log timestamp.
    level: LogLevel,
    source: [MAX_LOG_SOURCE_LEN]u8,
    source_len: u32,
    message: [MAX_LOG_MESSAGE_LEN]u8,
    message_len: u32,
    active: bool,

    pub fn init() LogEntry {
        var entry = LogEntry{
            .entry_id = 0,
            .timestamp = 0,
            .level = LogLevel.info,
            .source = undefined,
            .source_len = 0,
            .message = undefined,
            .message_len = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_LOG_SOURCE_LEN) : (i += 1) {
            entry.source[i] = 0;
        }
        i = 0;
        while (i < MAX_LOG_MESSAGE_LEN) : (i += 1) {
            entry.message[i] = 0;
        }
        return entry;
    }
};

// System logger: manages system logs.
pub const SystemLogger = struct {
    entries: [MAX_LOG_ENTRIES]LogEntry,
    entries_len: u32,
    next_entry_id: u32,
    min_log_level: LogLevel, // Minimum log level to store.

    pub fn init() SystemLogger {
        var logger = SystemLogger{
            .entries = undefined,
            .entries_len = 0,
            .next_entry_id = 1,
            .min_log_level = LogLevel.debug,
        };
        var i: u32 = 0;
        while (i < MAX_LOG_ENTRIES) : (i += 1) {
            logger.entries[i] = LogEntry.init();
        }
        return logger;
    }

    // Add log entry.
    pub fn log(
        self: *SystemLogger,
        level: LogLevel,
        source: []const u8,
        message: []const u8,
        timestamp: u64,
    ) ?u32 {
        // Check if log level is above minimum.
        if (@intFromEnum(level) < @intFromEnum(self.min_log_level)) {
            return null;
        }
        if (source.len > MAX_LOG_SOURCE_LEN) {
            return null;
        }
        if (message.len > MAX_LOG_MESSAGE_LEN) {
            return null;
        }
        // Use circular buffer: overwrite oldest entry if full.
        const entry_index = if (self.entries_len < MAX_LOG_ENTRIES)
self.entries_len else (self.next_entry_id - 1) % MAX_LOG_ENTRIES;
        const entry_id = self.next_entry_id;
        self.next_entry_id += 1;
        self.entries[entry_index] = LogEntry.init();
        self.entries[entry_index].entry_id = entry_id;
        self.entries[entry_index].timestamp = timestamp;
        self.entries[entry_index].level = level;
        self.entries[entry_index].active = true;
        var i: u32 = 0;
        while (i < MAX_LOG_SOURCE_LEN) : (i += 1) {
            self.entries[entry_index].source[i] = 0;
        }
        const source_len = @min(source.len, MAX_LOG_SOURCE_LEN);
        i = 0;
        while (i < source_len) : (i += 1) {
            self.entries[entry_index].source[i] = source[i];
        }
        self.entries[entry_index].source_len = @intCast(source_len);
        i = 0;
        while (i < MAX_LOG_MESSAGE_LEN) : (i += 1) {
            self.entries[entry_index].message[i] = 0;
        }
        const message_len = @min(message.len, MAX_LOG_MESSAGE_LEN);
        i = 0;
        while (i < message_len) : (i += 1) {
            self.entries[entry_index].message[i] = message[i];
        }
        self.entries[entry_index].message_len = @intCast(message_len);
        if (self.entries_len < MAX_LOG_ENTRIES) {
            self.entries_len += 1;
        }
        return entry_id;
    }

    // Find entry by ID.
    pub fn find_entry(
        self: *SystemLogger,
        entry_id: u32,
    ) ?*const LogEntry {
        std.debug.assert(entry_id > 0);
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].entry_id == entry_id and
self.entries[i].active) {
                return &self.entries[i];
            }
        }
        return null;
    }

    // Get entry by index.
    pub fn get_entry(
        self: *const SystemLogger,
        index: u32,
    ) ?*const LogEntry {
        if (index >= self.entries_len) {
            return null;
        }
        return &self.entries[index];
    }

    // Set minimum log level.
    pub fn set_min_log_level(self: *SystemLogger, level: LogLevel) void {
        self.min_log_level = level;
    }

    // Get minimum log level.
    pub fn get_min_log_level(self: *const SystemLogger) LogLevel {
        return self.min_log_level;
    }

    // Clear all logs.
    pub fn clear_all(self: *SystemLogger) void {
        self.entries_len = 0;
        self.next_entry_id = 1;
    }

    // Get log count.
    pub fn get_log_count(self: *const SystemLogger) u32 {
        return self.entries_len;
    }

    // Get log count by level.
    pub fn get_log_count_by_level(self: *const SystemLogger, level:
LogLevel) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].level == level) {
                count += 1;
            }
        }
        return count;
    }
};


// === grain_core/system_metrics.zig ===

//! Grain OS System Metrics: Unified system metrics aggregation.
//!
//! Why: Provide unified system metrics by aggregating data from
multiple sources.
//! Architecture: Metrics aggregation, system status summary, unified
reporting.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// System status summary.
pub const SystemStatus = struct {
    overall_health: SystemHealth,
    cpu_usage_percent: f64,
    memory_usage_percent: f64,
    disk_usage_percent: f64,
    total_processes: u32,
    running_processes: u32,
    supervised_processes: u32,
    running_supervised: u32,
    crashed_supervised: u32,
    healthy_checks: u32,
    warning_checks: u32,
    critical_checks: u32,
    timestamp: u64,

    pub fn init() SystemStatus {
        return SystemStatus{
            .overall_health = SystemHealth.unknown,
            .cpu_usage_percent = 0.0,
            .memory_usage_percent = 0.0,
            .disk_usage_percent = 0.0,
            .total_processes = 0,
            .running_processes = 0,
            .supervised_processes = 0,
            .running_supervised = 0,
            .crashed_supervised = 0,
            .healthy_checks = 0,
            .warning_checks = 0,
            .critical_checks = 0,
            .timestamp = 0,
        };
    }
};

// System health (aggregated).
pub const SystemHealth = enum(u8) {
    healthy,
    warning,
    critical,
    unknown,
};

// Metrics aggregator: aggregates system metrics.
pub const MetricsAggregator = struct {
    current_status: SystemStatus,

    pub fn init() MetricsAggregator {
        return MetricsAggregator{
            .current_status = SystemStatus.init(),
        };
    }

    // Update system status from resource monitor.
    pub fn update_from_resource_monitor(
        self: *MetricsAggregator,
        cpu_percent: f64,
        memory_percent: f64,
        disk_percent: f64,
        total_processes: u32,
        running_processes: u32,
    ) void {
        std.debug.assert(cpu_percent >= 0.0);
        std.debug.assert(cpu_percent <= 100.0);
        std.debug.assert(memory_percent >= 0.0);
        std.debug.assert(memory_percent <= 100.0);
        std.debug.assert(disk_percent >= 0.0);
        std.debug.assert(disk_percent <= 100.0);
        self.current_status.cpu_usage_percent = cpu_percent;
        self.current_status.memory_usage_percent = memory_percent;
        self.current_status.disk_usage_percent = disk_percent;
        self.current_status.total_processes = total_processes;
        self.current_status.running_processes = running_processes;
    }

    // Update system status from health monitor.
    pub fn update_from_health_monitor(
        self: *MetricsAggregator,
        overall_health: SystemHealth,
        healthy_checks: u32,
        warning_checks: u32,
        critical_checks: u32,
    ) void {
        self.current_status.overall_health = overall_health;
        self.current_status.healthy_checks = healthy_checks;
        self.current_status.warning_checks = warning_checks;
        self.current_status.critical_checks = critical_checks;
    }

    // Update system status from process supervisor.
    pub fn update_from_process_supervisor(
        self: *MetricsAggregator,
        supervised_processes: u32,
        running_supervised: u32,
        crashed_supervised: u32,
    ) void {
        self.current_status.supervised_processes = supervised_processes;
        self.current_status.running_supervised = running_supervised;
        self.current_status.crashed_supervised = crashed_supervised;
    }

    // Update timestamp.
    pub fn update_timestamp(self: *MetricsAggregator, timestamp: u64)
void {
        self.current_status.timestamp = timestamp;
    }

    // Calculate overall system health.
    pub fn calculate_overall_health(self: *MetricsAggregator)
SystemHealth {
        if (self.current_status.critical_checks > 0) {
            return SystemHealth.critical;
        }
        if (self.current_status.crashed_supervised > 0) {
            return SystemHealth.critical;
        }
        if (self.current_status.warning_checks > 0) {
            return SystemHealth.warning;
        }
        if (self.current_status.cpu_usage_percent > 90.0) {
            return SystemHealth.warning;
        }
        if (self.current_status.memory_usage_percent > 90.0) {
            return SystemHealth.warning;
        }
        if (self.current_status.disk_usage_percent > 90.0) {
            return SystemHealth.warning;
        }
        if (self.current_status.healthy_checks > 0) {
            return SystemHealth.healthy;
        }
        return SystemHealth.unknown;
    }

    // Get current system status.
    pub fn get_system_status(self: *MetricsAggregator) SystemStatus {
        self.current_status.overall_health =
self.calculate_overall_health();
        return self.current_status;
    }

    // Get overall health.
    pub fn get_overall_health(self: *MetricsAggregator) SystemHealth {
        return self.calculate_overall_health();
    }
};


// === grain_core/system_tray.zig ===

//! Grain OS System Tray: System tray for background applications.
//!
//! Why: Provide system tray for background applications and system
indicators.
//! Architecture: Tray icon management, notifications, tooltips.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max tray icons.
pub const MAX_TRAY_ICONS: u32 = 32;

// Bounded: Max tooltip length.
pub const MAX_TOOLTIP_LEN: u32 = 128;

// Bounded: Max icon path length.
pub const MAX_ICON_PATH_LEN: u32 = 256;

// Tray icon: represents a system tray icon.
pub const TrayIcon = struct {
    icon_id: u32,
    app_id: u32,
    icon_path: [MAX_ICON_PATH_LEN]u8,
    icon_path_len: u32,
    tooltip: [MAX_TOOLTIP_LEN]u8,
    tooltip_len: u32,
    visible: bool,
    active: bool,

    pub fn init() TrayIcon {
        var icon = TrayIcon{
            .icon_id = 0,
            .app_id = 0,
            .icon_path = undefined,
            .icon_path_len = 0,
            .tooltip = undefined,
            .tooltip_len = 0,
            .visible = true,
            .active = true,
        };
        var i: u32 = 0;
        while (i < MAX_ICON_PATH_LEN) : (i += 1) {
            icon.icon_path[i] = 0;
        }
        i = 0;
        while (i < MAX_TOOLTIP_LEN) : (i += 1) {
            icon.tooltip[i] = 0;
        }
        return icon;
    }
};

// System tray manager: manages system tray icons.
pub const SystemTrayManager = struct {
    icons: [MAX_TRAY_ICONS]TrayIcon,
    icons_len: u32,
    next_icon_id: u32,
    visible: bool,

    pub fn init() SystemTrayManager {
        var manager = SystemTrayManager{
            .icons = undefined,
            .icons_len = 0,
            .next_icon_id = 1,
            .visible = true,
        };
        var i: u32 = 0;
        while (i < MAX_TRAY_ICONS) : (i += 1) {
            manager.icons[i] = TrayIcon.init();
        }
        return manager;
    }

    // Add tray icon.
    pub fn add_icon(
        self: *SystemTrayManager,
        app_id: u32,
        icon_path: []const u8,
        tooltip: []const u8,
    ) ?u32 {
        if (self.icons_len >= MAX_TRAY_ICONS) {
            return null;
        }
        if (icon_path.len > MAX_ICON_PATH_LEN) {
            return null;
        }
        if (tooltip.len > MAX_TOOLTIP_LEN) {
            return null;
        }
        const icon_id = self.next_icon_id;
        self.next_icon_id += 1;
        self.icons[self.icons_len] = TrayIcon.init();
        self.icons[self.icons_len].icon_id = icon_id;
        self.icons[self.icons_len].app_id = app_id;
        var i: u32 = 0;
        while (i < MAX_ICON_PATH_LEN) : (i += 1) {
            self.icons[self.icons_len].icon_path[i] = 0;
        }
        const icon_len = @min(icon_path.len, MAX_ICON_PATH_LEN);
        i = 0;
        while (i < icon_len) : (i += 1) {
            self.icons[self.icons_len].icon_path[i] = icon_path[i];
        }
        self.icons[self.icons_len].icon_path_len = @intCast(icon_len);
        i = 0;
        while (i < MAX_TOOLTIP_LEN) : (i += 1) {
            self.icons[self.icons_len].tooltip[i] = 0;
        }
        const tooltip_len = @min(tooltip.len, MAX_TOOLTIP_LEN);
        i = 0;
        while (i < tooltip_len) : (i += 1) {
            self.icons[self.icons_len].tooltip[i] = tooltip[i];
        }
        self.icons[self.icons_len].tooltip_len = @intCast(tooltip_len);
        self.icons_len += 1;
        return icon_id;
    }

    // Find icon by ID.
    pub fn find_icon(
        self: *SystemTrayManager,
        icon_id: u32,
    ) ?*TrayIcon {
        std.debug.assert(icon_id > 0);
        var i: u32 = 0;
        while (i < self.icons_len) : (i += 1) {
            if (self.icons[i].icon_id == icon_id and
self.icons[i].active) {
                return &self.icons[i];
            }
        }
        return null;
    }

    // Find icon by app ID.
    pub fn find_icon_by_app_id(
        self: *SystemTrayManager,
        app_id: u32,
    ) ?*TrayIcon {
        std.debug.assert(app_id > 0);
        var i: u32 = 0;
        while (i < self.icons_len) : (i += 1) {
            if (self.icons[i].app_id == app_id and self.icons[i].active)
{
                return &self.icons[i];
            }
        }
        return null;
    }

    // Remove tray icon.
    pub fn remove_icon(self: *SystemTrayManager, icon_id: u32) bool {
        std.debug.assert(icon_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.icons_len) : (i += 1) {
            if (self.icons[i].icon_id == icon_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining icons left.
        while (i < self.icons_len - 1) : (i += 1) {
            self.icons[i] = self.icons[i + 1];
        }
        self.icons_len -= 1;
        return true;
    }

    // Update icon tooltip.
    pub fn update_tooltip(
        self: *SystemTrayManager,
        icon_id: u32,
        tooltip: []const u8,
    ) bool {
        std.debug.assert(icon_id > 0);
        if (tooltip.len > MAX_TOOLTIP_LEN) {
            return false;
        }
        if (self.find_icon(icon_id)) |icon| {
            var i: u32 = 0;
            while (i < MAX_TOOLTIP_LEN) : (i += 1) {
                icon.tooltip[i] = 0;
            }
            const tooltip_len = @min(tooltip.len, MAX_TOOLTIP_LEN);
            i = 0;
            while (i < tooltip_len) : (i += 1) {
                icon.tooltip[i] = tooltip[i];
            }
            icon.tooltip_len = @intCast(tooltip_len);
            return true;
        }
        return false;
    }

    // Show tray icon.
    pub fn show_icon(self: *SystemTrayManager, icon_id: u32) bool {
        std.debug.assert(icon_id > 0);
        if (self.find_icon(icon_id)) |icon| {
            icon.visible = true;
            return true;
        }
        return false;
    }

    // Hide tray icon.
    pub fn hide_icon(self: *SystemTrayManager, icon_id: u32) bool {
        std.debug.assert(icon_id > 0);
        if (self.find_icon(icon_id)) |icon| {
            icon.visible = false;
            return true;
        }
        return false;
    }

    // Show system tray.
    pub fn show(self: *SystemTrayManager) void {
        self.visible = true;
    }

    // Hide system tray.
    pub fn hide(self: *SystemTrayManager) void {
        self.visible = false;
    }

    // Check if system tray is visible.
    pub fn is_visible(self: *const SystemTrayManager) bool {
        return self.visible;
    }

    // Get icon count.
    pub fn get_icon_count(self: *const SystemTrayManager) u32 {
        return self.icons_len;
    }

    // Get visible icon count.
    pub fn get_visible_icon_count(self: *const SystemTrayManager) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.icons_len) : (i += 1) {
            if (self.icons[i].visible and self.icons[i].active) {
                count += 1;
            }
        }
        return count;
    }
};


// === grain_core/theme_manager.zig ===

//! Grain OS Theme Manager: UI theme and appearance management.
//!
//! Why: Provide theme management for UI appearance customization.
//! Architecture: Theme storage, color schemes, font settings.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max themes.
pub const MAX_THEMES: u32 = 16;

// Bounded: Max theme name length.
pub const MAX_THEME_NAME_LEN: u32 = 64;

// Bounded: Max color value length (hex format).
pub const MAX_COLOR_LEN: u32 = 8;

// Theme: represents a UI theme.
pub const Theme = struct {
    theme_id: u32,
    name: [MAX_THEME_NAME_LEN]u8,
    name_len: u32,
    bg_color: [MAX_COLOR_LEN]u8,
    bg_color_len: u32,
    fg_color: [MAX_COLOR_LEN]u8,
    fg_color_len: u32,
    border_color: [MAX_COLOR_LEN]u8,
    border_color_len: u32,
    accent_color: [MAX_COLOR_LEN]u8,
    accent_color_len: u32,
    active: bool,

    pub fn init() Theme {
        var theme = Theme{
            .theme_id = 0,
            .name = undefined,
            .name_len = 0,
            .bg_color = undefined,
            .bg_color_len = 0,
            .fg_color = undefined,
            .fg_color_len = 0,
            .border_color = undefined,
            .border_color_len = 0,
            .accent_color = undefined,
            .accent_color_len = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_THEME_NAME_LEN) : (i += 1) {
            theme.name[i] = 0;
        }
        i = 0;
        while (i < MAX_COLOR_LEN) : (i += 1) {
            theme.bg_color[i] = 0;
            theme.fg_color[i] = 0;
            theme.border_color[i] = 0;
            theme.accent_color[i] = 0;
        }
        return theme;
    }
};

// Theme manager: manages UI themes.
pub const ThemeManager = struct {
    themes: [MAX_THEMES]Theme,
    themes_len: u32,
    next_theme_id: u32,
    current_theme_id: u32,

    pub fn init() ThemeManager {
        var manager = ThemeManager{
            .themes = undefined,
            .themes_len = 0,
            .next_theme_id = 1,
            .current_theme_id = 0,
        };
        var i: u32 = 0;
        while (i < MAX_THEMES) : (i += 1) {
            manager.themes[i] = Theme.init();
        }
        return manager;
    }

    // Add theme.
    pub fn add_theme(
        self: *ThemeManager,
        name: []const u8,
        bg_color: []const u8,
        fg_color: []const u8,
        border_color: []const u8,
        accent_color: []const u8,
    ) ?u32 {
        if (self.themes_len >= MAX_THEMES) {
            return null;
        }
        if (name.len > MAX_THEME_NAME_LEN) {
            return null;
        }
        if (bg_color.len > MAX_COLOR_LEN or fg_color.len > MAX_COLOR_LEN
or border_color.len > MAX_COLOR_LEN or accent_color.len > MAX_COLOR_LEN)
{
            return null;
        }
        const theme_id = self.next_theme_id;
        self.next_theme_id += 1;
        self.themes[self.themes_len] = Theme.init();
        self.themes[self.themes_len].theme_id = theme_id;
        self.themes[self.themes_len].active = true;
        var i: u32 = 0;
        while (i < MAX_THEME_NAME_LEN) : (i += 1) {
            self.themes[self.themes_len].name[i] = 0;
        }
        const name_len = @min(name.len, MAX_THEME_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.themes[self.themes_len].name[i] = name[i];
        }
        self.themes[self.themes_len].name_len = @intCast(name_len);
        const bg_len = @min(bg_color.len, MAX_COLOR_LEN);
        i = 0;
        while (i < MAX_COLOR_LEN) : (i += 1) {
            self.themes[self.themes_len].bg_color[i] = 0;
        }
        i = 0;
        while (i < bg_len) : (i += 1) {
            self.themes[self.themes_len].bg_color[i] = bg_color[i];
        }
        self.themes[self.themes_len].bg_color_len = @intCast(bg_len);
        const fg_len = @min(fg_color.len, MAX_COLOR_LEN);
        i = 0;
        while (i < MAX_COLOR_LEN) : (i += 1) {
            self.themes[self.themes_len].fg_color[i] = 0;
        }
        i = 0;
        while (i < fg_len) : (i += 1) {
            self.themes[self.themes_len].fg_color[i] = fg_color[i];
        }
        self.themes[self.themes_len].fg_color_len = @intCast(fg_len);
        const border_len = @min(border_color.len, MAX_COLOR_LEN);
        i = 0;
        while (i < MAX_COLOR_LEN) : (i += 1) {
            self.themes[self.themes_len].border_color[i] = 0;
        }
        i = 0;
        while (i < border_len) : (i += 1) {
            self.themes[self.themes_len].border_color[i] =
border_color[i];
        }
        self.themes[self.themes_len].border_color_len =
@intCast(border_len);
        const accent_len = @min(accent_color.len, MAX_COLOR_LEN);
        i = 0;
        while (i < MAX_COLOR_LEN) : (i += 1) {
            self.themes[self.themes_len].accent_color[i] = 0;
        }
        i = 0;
        while (i < accent_len) : (i += 1) {
            self.themes[self.themes_len].accent_color[i] =
accent_color[i];
        }
        self.themes[self.themes_len].accent_color_len =
@intCast(accent_len);
        if (self.current_theme_id == 0) {
            self.current_theme_id = theme_id;
        }
        self.themes_len += 1;
        return theme_id;
    }

    // Find theme by ID.
    pub fn find_theme(
        self: *ThemeManager,
        theme_id: u32,
    ) ?*Theme {
        std.debug.assert(theme_id > 0);
        var i: u32 = 0;
        while (i < self.themes_len) : (i += 1) {
            if (self.themes[i].theme_id == theme_id and
self.themes[i].active) {
                return &self.themes[i];
            }
        }
        return null;
    }

    // Set current theme.
    pub fn set_current_theme(self: *ThemeManager, theme_id: u32) bool {
        std.debug.assert(theme_id > 0);
        if (self.find_theme(theme_id)) |_| {
            self.current_theme_id = theme_id;
            return true;
        }
        return false;
    }

    // Get current theme.
    pub fn get_current_theme(self: *const ThemeManager) ?*const Theme {
        if (self.current_theme_id == 0) {
            return null;
        }
        var i: u32 = 0;
        while (i < self.themes_len) : (i += 1) {
            if (self.themes[i].theme_id == self.current_theme_id) {
                return &self.themes[i];
            }
        }
        return null;
    }

    // Remove theme.
    pub fn remove_theme(self: *ThemeManager, theme_id: u32) bool {
        std.debug.assert(theme_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.themes_len) : (i += 1) {
            if (self.themes[i].theme_id == theme_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        if (self.current_theme_id == theme_id) {
            self.current_theme_id = 0;
            if (self.themes_len > 1) {
                var j: u32 = 0;
                while (j < self.themes_len) : (j += 1) {
                    if (j != i and self.themes[j].active) {
                        self.current_theme_id = self.themes[j].theme_id;
                        break;
                    }
                }
            }
        }
        // Shift remaining themes left.
        while (i < self.themes_len - 1) : (i += 1) {
            self.themes[i] = self.themes[i + 1];
        }
        self.themes_len -= 1;
        return true;
    }

    // Get theme count.
    pub fn get_theme_count(self: *const ThemeManager) u32 {
        return self.themes_len;
    }
};


// === grain_core/tiling.zig ===

//! Grain OS Tiling: Dynamic window tiling layout.
//!
//! Why: Arrange windows in tiled layouts (master-stack, grid, etc.).
//! Architecture: Iterative algorithms (no recursion, Grain Style
requirement).
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max tree depth for tiling splits.
pub const MAX_TREE_DEPTH: u32 = 32;

// Bounded: Max windows per layout.
pub const MAX_LAYOUT_WINDOWS: u32 = 256;

// Split direction: vertical or horizontal.
pub const SplitDirection = enum {
    vertical,
    horizontal,
};

// Tiling node: represents a split or window in the tiling tree.
pub const TilingNode = struct {
    // Node type: split or window.
    node_type: NodeType,
    // Split direction (if split node).
    split_dir: SplitDirection,
    // Split ratio (0.0 to 1.0, if split node).
    split_ratio: f64,
    // Window ID (if window node).
    window_id: u32,
    // Child indices (if split node).
    left_child: u32,
    right_child: u32,
    // Parent index (for traversal).
    parent: u32,
    // Bounding box (x, y, width, height).
    x: i32,
    y: i32,
    width: u32,
    height: u32,
    // Node index in tree array.
    index: u32,

    const NodeType = enum {
        split,
        window,
    };

    pub fn init_split(
        index: u32,
        split_dir: SplitDirection,
        split_ratio: f64,
        left_child: u32,
        right_child: u32,
    ) TilingNode {
        std.debug.assert(index < MAX_LAYOUT_WINDOWS);
        std.debug.assert(split_ratio >= 0.0);
        std.debug.assert(split_ratio <= 1.0);
        std.debug.assert(left_child < MAX_LAYOUT_WINDOWS);
        std.debug.assert(right_child < MAX_LAYOUT_WINDOWS);
        return TilingNode{
            .node_type = .split,
            .split_dir = split_dir,
            .split_ratio = split_ratio,
            .window_id = 0,
            .left_child = left_child,
            .right_child = right_child,
            .parent = MAX_LAYOUT_WINDOWS, // Invalid parent (root has no
parent).
            .x = 0,
            .y = 0,
            .width = 0,
            .height = 0,
            .index = index,
        };
    }

    pub fn init_window(
        index: u32,
        window_id: u32,
    ) TilingNode {
        std.debug.assert(index < MAX_LAYOUT_WINDOWS);
        std.debug.assert(window_id > 0);
        return TilingNode{
            .node_type = .window,
            .split_dir = .vertical, // Unused for window nodes.
            .split_ratio = 0.0, // Unused for window nodes.
            .window_id = window_id,
            .left_child = MAX_LAYOUT_WINDOWS, // Invalid (no children).
            .right_child = MAX_LAYOUT_WINDOWS, // Invalid (no children).
            .parent = MAX_LAYOUT_WINDOWS, // Will be set when added to
tree.
            .x = 0,
            .y = 0,
            .width = 0,
            .height = 0,
            .index = index,
        };
    }

    pub fn set_bounds(self: *TilingNode, x: i32, y: i32, width: u32,
height: u32) void {
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        self.x = x;
        self.y = y;
        self.width = width;
        self.height = height;
    }
};

// Tiling tree: manages window tiling layout.
pub const TilingTree = struct {
    nodes: [MAX_LAYOUT_WINDOWS]TilingNode,
    nodes_len: u32,
    root_index: u32,
    next_node_index: u32,

    pub fn init() TilingTree {
        var tree = TilingTree{
            .nodes = undefined,
            .nodes_len = 0,
            .root_index = MAX_LAYOUT_WINDOWS, // Invalid (no root yet).
            .next_node_index = 0,
        };
        var i: u32 = 0;
        while (i < MAX_LAYOUT_WINDOWS) : (i += 1) {
            tree.nodes[i] = TilingNode.init_window(i, 0);
        }
        std.debug.assert(tree.nodes_len == 0);
        return tree;
    }

    pub fn add_window(self: *TilingTree, window_id: u32) !void {
        std.debug.assert(window_id > 0);
        std.debug.assert(self.nodes_len < MAX_LAYOUT_WINDOWS);
        const node_index = self.next_node_index;
        self.next_node_index += 1;
        self.nodes[node_index] = TilingNode.init_window(node_index,
window_id);
        self.nodes_len += 1;
        if (self.root_index == MAX_LAYOUT_WINDOWS) {
            // First window: set as root.
            self.root_index = node_index;
            self.nodes[node_index].parent = MAX_LAYOUT_WINDOWS;
        } else {
            // Add as split: create new split with old root and new
window.
            const old_root = self.root_index;
            const split_index = self.next_node_index;
            self.next_node_index += 1;
            std.debug.assert(self.nodes_len < MAX_LAYOUT_WINDOWS);
            self.nodes_len += 1;
            // Create vertical split (main on left, new window on right).
            self.nodes[split_index] = TilingNode.init_split(
                split_index,
                .vertical,
                0.6, // 60% main, 40% new window.
                old_root,
                node_index,
            );
            self.nodes[old_root].parent = split_index;
            self.nodes[node_index].parent = split_index;
            self.root_index = split_index;
            self.nodes[split_index].parent = MAX_LAYOUT_WINDOWS;
        }
        std.debug.assert(self.nodes_len <= MAX_LAYOUT_WINDOWS);
        std.debug.assert(self.root_index < MAX_LAYOUT_WINDOWS);
    }

    pub fn remove_window(self: *TilingTree, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        // Find window node.
        var i: u32 = 0;
        var window_index: u32 = MAX_LAYOUT_WINDOWS;
        while (i < self.nodes_len) : (i += 1) {
            if (self.nodes[i].node_type == .window and
                self.nodes[i].window_id == window_id)
            {
                window_index = i;
                break;
            }
        }
        if (window_index == MAX_LAYOUT_WINDOWS) {
            return false; // Window not found.
        }
        // Remove window node and update tree.
        const parent_index = self.nodes[window_index].parent;
        if (parent_index == MAX_LAYOUT_WINDOWS) {
            // Window is root: clear tree.
            self.root_index = MAX_LAYOUT_WINDOWS;
            self.nodes_len = 0;
            self.next_node_index = 0;
            return true;
        }
        // Replace parent split with sibling.
        const parent = &self.nodes[parent_index];
        const sibling_index = if (parent.left_child == window_index)
            parent.right_child
        else
            parent.left_child;
        std.debug.assert(sibling_index < MAX_LAYOUT_WINDOWS);
        const grandparent_index = parent.parent;
        if (grandparent_index == MAX_LAYOUT_WINDOWS) {
            // Parent is root: sibling becomes root.
            self.root_index = sibling_index;
            self.nodes[sibling_index].parent = MAX_LAYOUT_WINDOWS;
        } else {
            // Replace parent with sibling in grandparent.
            const grandparent = &self.nodes[grandparent_index];
            if (grandparent.left_child == parent_index) {
                grandparent.left_child = sibling_index;
            } else {
                grandparent.right_child = sibling_index;
            }
            self.nodes[sibling_index].parent = grandparent_index;
        }
        // Note: We don't actually remove nodes from array (just mark as
unused).
        // This is acceptable for Grain Style (bounded array, no dynamic
allocation).
        return true;
    }

    // Calculate window positions using iterative algorithm (no
recursion).
    pub fn calculate_layout(
        self: *TilingTree,
        output_x: i32,
        output_y: i32,
        output_width: u32,
        output_height: u32,
    ) void {
        std.debug.assert(output_width > 0);
        std.debug.assert(output_height > 0);
        if (self.root_index == MAX_LAYOUT_WINDOWS) {
            return; // Empty tree.
        }
        // Set root bounds.
        self.nodes[self.root_index].set_bounds(
            output_x,
            output_y,
            output_width,
            output_height,
        );
        // Iterative traversal: use stack to traverse tree.
        var stack: [MAX_TREE_DEPTH]u32 = undefined;
        var stack_len: u32 = 0;
        stack[stack_len] = self.root_index;
        stack_len += 1;
        while (stack_len > 0) {
            stack_len -= 1;
            const node_index = stack[stack_len];
            const node = &self.nodes[node_index];
            if (node.node_type == .split) {
                // Calculate child bounds based on split.
                const parent_x = node.x;
                const parent_y = node.y;
                const parent_width = node.width;
                const parent_height = node.height;
                if (node.split_dir == .vertical) {
                    // Vertical split: left and right.
                    const left_width = @as(u32, @intFromFloat(@as(f64,
@floatFromInt(parent_width)) * node.split_ratio));
                    const right_width = parent_width - left_width;
                    std.debug.assert(left_width > 0);
                    std.debug.assert(right_width > 0);
                    self.nodes[node.left_child].set_bounds(
                        parent_x,
                        parent_y,
                        left_width,
                        parent_height,
                    );
                    self.nodes[node.right_child].set_bounds(
                        parent_x + @as(i32, @intCast(left_width)),
                        parent_y,
                        right_width,
                        parent_height,
                    );
                } else {
                    // Horizontal split: top and bottom.
                    const top_height = @as(u32, @intFromFloat(@as(f64,
@floatFromInt(parent_height)) * node.split_ratio));
                    const bottom_height = parent_height - top_height;
                    std.debug.assert(top_height > 0);
                    std.debug.assert(bottom_height > 0);
                    self.nodes[node.left_child].set_bounds(
                        parent_x,
                        parent_y,
                        parent_width,
                        top_height,
                    );
                    self.nodes[node.right_child].set_bounds(
                        parent_x,
                        parent_y + @as(i32, @intCast(top_height)),
                        parent_width,
                        bottom_height,
                    );
                }
                // Push children onto stack.
                std.debug.assert(stack_len + 2 <= MAX_TREE_DEPTH);
                stack[stack_len] = node.right_child;
                stack_len += 1;
                stack[stack_len] = node.left_child;
                stack_len += 1;
            }
        }
    }

    // Get window bounds for a specific window ID.
    pub fn get_window_bounds(self: *TilingTree, window_id: u32) ?struct {
        x: i32,
        y: i32,
        width: u32,
        height: u32,
    } {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        while (i < self.nodes_len) : (i += 1) {
            if (self.nodes[i].node_type == .window and
                self.nodes[i].window_id == window_id)
            {
                return .{
                    .x = self.nodes[i].x,
                    .y = self.nodes[i].y,
                    .width = self.nodes[i].width,
                    .height = self.nodes[i].height,
                };
            }
        }
        return null;
    }
};

// === grain_core/tiling_config.zig ===

//! Grain OS Tiling Configuration: Tiling settings and preferences.
//!
//! Why: Allow users to configure tiling behavior (gaps, ratios,
layouts).
//! Architecture: Configuration structure and management functions.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const layout_generator = @import("layout_generator.zig");

// Bounded: Default window gap (pixels).
pub const DEFAULT_WINDOW_GAP: u32 = 4;

// Bounded: Default split ratio (0.0 to 1.0).
pub const DEFAULT_SPLIT_RATIO: f64 = 0.5;

// Bounded: Min split ratio.
pub const MIN_SPLIT_RATIO: f64 = 0.1;

// Bounded: Max split ratio.
pub const MAX_SPLIT_RATIO: f64 = 0.9;

// Tiling configuration: user preferences for tiling.
pub const TilingConfig = struct {
    window_gap: u32,
    split_ratio: f64,
    default_layout: layout_generator.LayoutType,
    auto_tile: bool,
    smart_gaps: bool, // Hide gaps when only one window.

    pub fn init() TilingConfig {
        return TilingConfig{
            .window_gap = DEFAULT_WINDOW_GAP,
            .split_ratio = DEFAULT_SPLIT_RATIO,
            .default_layout = .tall,
            .auto_tile = true,
            .smart_gaps = false,
        };
    }

    // Set window gap.
    pub fn set_window_gap(self: *TilingConfig, gap: u32) void {
        self.window_gap = gap;
    }

    // Get window gap.
    pub fn get_window_gap(self: *const TilingConfig) u32 {
        return self.window_gap;
    }

    // Set split ratio.
    pub fn set_split_ratio(self: *TilingConfig, ratio: f64) void {
        std.debug.assert(ratio >= MIN_SPLIT_RATIO);
        std.debug.assert(ratio <= MAX_SPLIT_RATIO);
        self.split_ratio = ratio;
    }

    // Get split ratio.
    pub fn get_split_ratio(self: *const TilingConfig) f64 {
        return self.split_ratio;
    }

    // Set default layout.
    pub fn set_default_layout(self: *TilingConfig, layout:
layout_generator.LayoutType) void {
        self.default_layout = layout;
    }

    // Get default layout.
    pub fn get_default_layout(self: *const TilingConfig)
layout_generator.LayoutType {
        return self.default_layout;
    }

    // Set auto-tile.
    pub fn set_auto_tile(self: *TilingConfig, enabled: bool) void {
        self.auto_tile = enabled;
    }

    // Get auto-tile.
    pub fn get_auto_tile(self: *const TilingConfig) bool {
        return self.auto_tile;
    }

    // Set smart gaps.
    pub fn set_smart_gaps(self: *TilingConfig, enabled: bool) void {
        self.smart_gaps = enabled;
    }

    // Get smart gaps.
    pub fn get_smart_gaps(self: *const TilingConfig) bool {
        return self.smart_gaps;
    }

    // Clamp split ratio to valid range.
    pub fn clamp_split_ratio(ratio: f64) f64 {
        if (ratio < MIN_SPLIT_RATIO) {
            return MIN_SPLIT_RATIO;
        }
        if (ratio > MAX_SPLIT_RATIO) {
            return MAX_SPLIT_RATIO;
        }
        return ratio;
    }

    // Calculate effective gap (with smart gaps).
    pub fn calc_effective_gap(
        self: *const TilingConfig,
        window_count: u32,
    ) u32 {
        if (self.smart_gaps and window_count <= 1) {
            return 0;
        }
        return self.window_gap;
    }
};


// === grain_core/time_manager.zig ===

//! Grain OS Time Manager: System time, timezone, and clock management.
//!
//! Why: Provide time and date management for system clock and timezone.
//! Architecture: Time tracking, timezone management, clock
synchronization.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max timezone name length.
pub const MAX_TIMEZONE_NAME_LEN: u32 = 64;

// Bounded: Max timezone abbreviation length.
pub const MAX_TIMEZONE_ABBR_LEN: u32 = 8;

// Time format.
pub const TimeFormat = enum(u8) {
    format_12h,
    format_24h,
};

// Date format.
pub const DateFormat = enum(u8) {
    format_iso, // YYYY-MM-DD
    format_us,  // MM/DD/YYYY
    format_eu,  // DD/MM/YYYY
};

// Timezone: represents a timezone.
pub const Timezone = struct {
    name: [MAX_TIMEZONE_NAME_LEN]u8,
    name_len: u32,
    abbreviation: [MAX_TIMEZONE_ABBR_LEN]u8,
    abbr_len: u32,
    offset_seconds: i32, // Offset from UTC in seconds.

    pub fn init() Timezone {
        var tz = Timezone{
            .name = undefined,
            .name_len = 0,
            .abbreviation = undefined,
            .abbr_len = 0,
            .offset_seconds = 0,
        };
        var i: u32 = 0;
        while (i < MAX_TIMEZONE_NAME_LEN) : (i += 1) {
            tz.name[i] = 0;
        }
        i = 0;
        while (i < MAX_TIMEZONE_ABBR_LEN) : (i += 1) {
            tz.abbreviation[i] = 0;
        }
        return tz;
    }
};

// Time manager: manages system time and timezone.
pub const TimeManager = struct {
    system_time: u64, // System time in nanoseconds since epoch.
    timezone: Timezone,
    time_format: TimeFormat,
    date_format: DateFormat,
    auto_sync_enabled: bool,

    pub fn init() TimeManager {
        var manager = TimeManager{
            .system_time = 0,
            .timezone = Timezone.init(),
            .time_format = TimeFormat.format_24h,
            .date_format = DateFormat.format_iso,
            .auto_sync_enabled = false,
        };
        // Set default timezone to UTC.
        var i: u32 = 0;
        while (i < MAX_TIMEZONE_NAME_LEN) : (i += 1) {
            manager.timezone.name[i] = 0;
        }
        const utc_name = "UTC";
        i = 0;
        while (i < utc_name.len) : (i += 1) {
            manager.timezone.name[i] = utc_name[i];
        }
        manager.timezone.name_len = @intCast(utc_name.len);
        i = 0;
        while (i < MAX_TIMEZONE_ABBR_LEN) : (i += 1) {
            manager.timezone.abbreviation[i] = 0;
        }
        const utc_abbr = "UTC";
        i = 0;
        while (i < utc_abbr.len) : (i += 1) {
            manager.timezone.abbreviation[i] = utc_abbr[i];
        }
        manager.timezone.abbr_len = @intCast(utc_abbr.len);
        manager.timezone.offset_seconds = 0;
        return manager;
    }

    // Set system time.
    pub fn set_system_time(self: *TimeManager, time_ns: u64) void {
        self.system_time = time_ns;
    }

    // Get system time.
    pub fn get_system_time(self: *const TimeManager) u64 {
        return self.system_time;
    }

    // Set timezone.
    pub fn set_timezone(
        self: *TimeManager,
        name: []const u8,
        abbreviation: []const u8,
        offset_seconds: i32,
    ) bool {
        if (name.len > MAX_TIMEZONE_NAME_LEN) {
            return false;
        }
        if (abbreviation.len > MAX_TIMEZONE_ABBR_LEN) {
            return false;
        }
        var i: u32 = 0;
        while (i < MAX_TIMEZONE_NAME_LEN) : (i += 1) {
            self.timezone.name[i] = 0;
        }
        const name_len = @min(name.len, MAX_TIMEZONE_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            self.timezone.name[i] = name[i];
        }
        self.timezone.name_len = @intCast(name_len);
        i = 0;
        while (i < MAX_TIMEZONE_ABBR_LEN) : (i += 1) {
            self.timezone.abbreviation[i] = 0;
        }
        const abbr_len = @min(abbreviation.len, MAX_TIMEZONE_ABBR_LEN);
        i = 0;
        while (i < abbr_len) : (i += 1) {
            self.timezone.abbreviation[i] = abbreviation[i];
        }
        self.timezone.abbr_len = @intCast(abbr_len);
        self.timezone.offset_seconds = offset_seconds;
        return true;
    }

    // Get timezone.
    pub fn get_timezone(self: *const TimeManager) Timezone {
        return self.timezone;
    }

    // Set time format.
    pub fn set_time_format(self: *TimeManager, format: TimeFormat) void {
        self.time_format = format;
    }

    // Get time format.
    pub fn get_time_format(self: *const TimeManager) TimeFormat {
        return self.time_format;
    }

    // Set date format.
    pub fn set_date_format(self: *TimeManager, format: DateFormat) void {
        self.date_format = format;
    }

    // Get date format.
    pub fn get_date_format(self: *const TimeManager) DateFormat {
        return self.date_format;
    }

    // Enable auto-sync.
    pub fn enable_auto_sync(self: *TimeManager) void {
        self.auto_sync_enabled = true;
    }

    // Disable auto-sync.
    pub fn disable_auto_sync(self: *TimeManager) void {
        self.auto_sync_enabled = false;
    }

    // Check if auto-sync is enabled.
    pub fn is_auto_sync_enabled(self: *const TimeManager) bool {
        return self.auto_sync_enabled;
    }

    // Get local time (system time + timezone offset).
    pub fn get_local_time(self: *const TimeManager) u64 {
        const offset_ns: i64 = @as(i64, self.timezone.offset_seconds) *
1000000000;
        const system_time_i64: i64 = @intCast(self.system_time);
        const local_time_i64 = system_time_i64 + offset_ns;
        if (local_time_i64 < 0) {
            return 0;
        }
        return @intCast(local_time_i64);
    }
};


// === grain_core/update_manager.zig ===

//! Grain OS Update Manager: System update and version management.
//!
//! Why: Provide update management for system updates and version
tracking.
//! Architecture: Update checking, update installation, version
management.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max updates.
pub const MAX_UPDATES: u32 = 16;

// Bounded: Max version string length.
pub const MAX_VERSION_LEN: u32 = 32;

// Bounded: Max update description length.
pub const MAX_UPDATE_DESC_LEN: u32 = 256;

// Bounded: Max update URL length.
pub const MAX_UPDATE_URL_LEN: u32 = 512;

// Update type.
pub const UpdateType = enum(u8) {
    security,
    bugfix,
    feature,
    major,
    minor,
};

// Update state.
pub const UpdateState = enum(u8) {
    available,
    downloading,
    downloaded,
    installing,
    installed,
    failed,
    cancelled,
};

// Update: represents a system update.
pub const Update = struct {
    update_id: u32,
    version: [MAX_VERSION_LEN]u8,
    version_len: u32,
    description: [MAX_UPDATE_DESC_LEN]u8,
    description_len: u32,
    url: [MAX_UPDATE_URL_LEN]u8,
    url_len: u32,
    update_type: UpdateType,
    state: UpdateState,
    size_bytes: u64,
    release_date: u64,
    active: bool,

    pub fn init() Update {
        var update = Update{
            .update_id = 0,
            .version = undefined,
            .version_len = 0,
            .description = undefined,
            .description_len = 0,
            .url = undefined,
            .url_len = 0,
            .update_type = UpdateType.minor,
            .state = UpdateState.available,
            .size_bytes = 0,
            .release_date = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_VERSION_LEN) : (i += 1) {
            update.version[i] = 0;
        }
        i = 0;
        while (i < MAX_UPDATE_DESC_LEN) : (i += 1) {
            update.description[i] = 0;
        }
        i = 0;
        while (i < MAX_UPDATE_URL_LEN) : (i += 1) {
            update.url[i] = 0;
        }
        return update;
    }
};

// Update manager: manages system updates.
pub const UpdateManager = struct {
    updates: [MAX_UPDATES]Update,
    updates_len: u32,
    next_update_id: u32,
    current_version: [MAX_VERSION_LEN]u8,
    current_version_len: u32,
    auto_update_enabled: bool,
    current_update_id: u32, // Currently active update operation.

    pub fn init() UpdateManager {
        var manager = UpdateManager{
            .updates = undefined,
            .updates_len = 0,
            .next_update_id = 1,
            .current_version = undefined,
            .current_version_len = 0,
            .auto_update_enabled = false,
            .current_update_id = 0,
        };
        var i: u32 = 0;
        while (i < MAX_UPDATES) : (i += 1) {
            manager.updates[i] = Update.init();
        }
        i = 0;
        while (i < MAX_VERSION_LEN) : (i += 1) {
            manager.current_version[i] = 0;
        }
        const default_version = "1.0.0";
        i = 0;
        while (i < default_version.len) : (i += 1) {
            manager.current_version[i] = default_version[i];
        }
        manager.current_version_len = @intCast(default_version.len);
        return manager;
    }

    // Add update.
    pub fn add_update(
        self: *UpdateManager,
        version: []const u8,
        description: []const u8,
        url: []const u8,
        update_type: UpdateType,
        size_bytes: u64,
        release_date: u64,
    ) ?u32 {
        if (self.updates_len >= MAX_UPDATES) {
            return null;
        }
        if (version.len > MAX_VERSION_LEN) {
            return null;
        }
        if (description.len > MAX_UPDATE_DESC_LEN) {
            return null;
        }
        if (url.len > MAX_UPDATE_URL_LEN) {
            return null;
        }
        const update_id = self.next_update_id;
        self.next_update_id += 1;
        self.updates[self.updates_len] = Update.init();
        self.updates[self.updates_len].update_id = update_id;
        self.updates[self.updates_len].update_type = update_type;
        self.updates[self.updates_len].state = UpdateState.available;
        self.updates[self.updates_len].size_bytes = size_bytes;
        self.updates[self.updates_len].release_date = release_date;
        self.updates[self.updates_len].active = true;
        var i: u32 = 0;
        while (i < MAX_VERSION_LEN) : (i += 1) {
            self.updates[self.updates_len].version[i] = 0;
        }
        const version_len = @min(version.len, MAX_VERSION_LEN);
        i = 0;
        while (i < version_len) : (i += 1) {
            self.updates[self.updates_len].version[i] = version[i];
        }
        self.updates[self.updates_len].version_len =
@intCast(version_len);
        i = 0;
        while (i < MAX_UPDATE_DESC_LEN) : (i += 1) {
            self.updates[self.updates_len].description[i] = 0;
        }
        const desc_len = @min(description.len, MAX_UPDATE_DESC_LEN);
        i = 0;
        while (i < desc_len) : (i += 1) {
            self.updates[self.updates_len].description[i] =
description[i];
        }
        self.updates[self.updates_len].description_len =
@intCast(desc_len);
        i = 0;
        while (i < MAX_UPDATE_URL_LEN) : (i += 1) {
            self.updates[self.updates_len].url[i] = 0;
        }
        const url_len = @min(url.len, MAX_UPDATE_URL_LEN);
        i = 0;
        while (i < url_len) : (i += 1) {
            self.updates[self.updates_len].url[i] = url[i];
        }
        self.updates[self.updates_len].url_len = @intCast(url_len);
        self.updates_len += 1;
        return update_id;
    }

    // Find update by ID.
    pub fn find_update(
        self: *UpdateManager,
        update_id: u32,
    ) ?*Update {
        std.debug.assert(update_id > 0);
        var i: u32 = 0;
        while (i < self.updates_len) : (i += 1) {
            if (self.updates[i].update_id == update_id and
self.updates[i].active) {
                return &self.updates[i];
            }
        }
        return null;
    }

    // Start download.
    pub fn start_download(self: *UpdateManager, update_id: u32) bool {
        std.debug.assert(update_id > 0);
        if (self.find_update(update_id)) |update| {
            if (update.state == UpdateState.available) {
                update.state = UpdateState.downloading;
                self.current_update_id = update_id;
                // Would start actual download in full implementation.
                return true;
            }
        }
        return false;
    }

    // Complete download.
    pub fn complete_download(self: *UpdateManager, update_id: u32) bool {
        std.debug.assert(update_id > 0);
        if (self.find_update(update_id)) |update| {
            if (update.state == UpdateState.downloading) {
                update.state = UpdateState.downloaded;
                return true;
            }
        }
        return false;
    }

    // Start installation.
    pub fn start_installation(self: *UpdateManager, update_id: u32) bool
{
        std.debug.assert(update_id > 0);
        if (self.find_update(update_id)) |update| {
            if (update.state == UpdateState.downloaded) {
                update.state = UpdateState.installing;
                self.current_update_id = update_id;
                // Would start actual installation in full
implementation.
                return true;
            }
        }
        return false;
    }

    // Complete installation.
    pub fn complete_installation(self: *UpdateManager, update_id: u32)
bool {
        std.debug.assert(update_id > 0);
        if (self.find_update(update_id)) |update| {
            if (update.state == UpdateState.installing) {
                update.state = UpdateState.installed;
                // Update current version.
                var i: u32 = 0;
                while (i < MAX_VERSION_LEN) : (i += 1) {
                    self.current_version[i] = 0;
                }
                i = 0;
                while (i < update.version_len) : (i += 1) {
                    self.current_version[i] = update.version[i];
                }
                self.current_version_len = update.version_len;
                if (self.current_update_id == update_id) {
                    self.current_update_id = 0;
                }
                return true;
            }
        }
        return false;
    }

    // Fail update.
    pub fn fail_update(self: *UpdateManager, update_id: u32) bool {
        std.debug.assert(update_id > 0);
        if (self.find_update(update_id)) |update| {
            if (update.state == UpdateState.downloading or update.state
== UpdateState.installing) {
                update.state = UpdateState.failed;
                if (self.current_update_id == update_id) {
                    self.current_update_id = 0;
                }
                return true;
            }
        }
        return false;
    }

    // Cancel update.
    pub fn cancel_update(self: *UpdateManager, update_id: u32) bool {
        std.debug.assert(update_id > 0);
        if (self.find_update(update_id)) |update| {
            if (update.state == UpdateState.downloading or update.state
== UpdateState.installing) {
                update.state = UpdateState.cancelled;
                if (self.current_update_id == update_id) {
                    self.current_update_id = 0;
                }
                return true;
            }
        }
        return false;
    }

    // Remove update.
    pub fn remove_update(self: *UpdateManager, update_id: u32) bool {
        std.debug.assert(update_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.updates_len) : (i += 1) {
            if (self.updates[i].update_id == update_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        if (self.current_update_id == update_id) {
            self.current_update_id = 0;
        }
        while (i < self.updates_len - 1) : (i += 1) {
            self.updates[i] = self.updates[i + 1];
        }
        self.updates_len -= 1;
        return true;
    }

    // Set current version.
    pub fn set_current_version(self: *UpdateManager, version: []const
u8) bool {
        if (version.len > MAX_VERSION_LEN) {
            return false;
        }
        var i: u32 = 0;
        while (i < MAX_VERSION_LEN) : (i += 1) {
            self.current_version[i] = 0;
        }
        const version_len = @min(version.len, MAX_VERSION_LEN);
        i = 0;
        while (i < version_len) : (i += 1) {
            self.current_version[i] = version[i];
        }
        self.current_version_len = @intCast(version_len);
        return true;
    }

    // Get current version.
    pub fn get_current_version(self: *const UpdateManager) []const u8 {
        return self.current_version[0..self.current_version_len];
    }

    // Enable auto-update.
    pub fn enable_auto_update(self: *UpdateManager) void {
        self.auto_update_enabled = true;
    }

    // Disable auto-update.
    pub fn disable_auto_update(self: *UpdateManager) void {
        self.auto_update_enabled = false;
    }

    // Check if auto-update is enabled.
    pub fn is_auto_update_enabled(self: *const UpdateManager) bool {
        return self.auto_update_enabled;
    }

    // Get update count.
    pub fn get_update_count(self: *const UpdateManager) u32 {
        return self.updates_len;
    }

    // Get available update count.
    pub fn get_available_update_count(self: *const UpdateManager) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.updates_len) : (i += 1) {
            if (self.updates[i].state == UpdateState.available) {
                count += 1;
            }
        }
        return count;
    }

    // Get current update ID.
    pub fn get_current_update_id(self: *const UpdateManager) u32 {
        return self.current_update_id;
    }
};


// === grain_core/wal_manager.zig ===

//! Grain Core WAL Manager: Write-ahead log for database transactions.
//!
//! Why: Provide ACID guarantees for database transactions (Silo Agent).
//! Architecture: WAL file format, rotation, checkpoint, recovery.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");
const file_storage = @import("file_storage.zig");

// Bounded: Max WAL file size (100MB).
pub const MAX_WAL_FILE_SIZE: u64 = 100 * 1024 * 1024;

// Bounded: Max WAL entries.
pub const MAX_WAL_ENTRIES: u32 = 10000;

// Bounded: Max WAL entry size.
pub const MAX_WAL_ENTRY_SIZE: u32 = 64 * 1024;

// Bounded: WAL checkpoint interval (entries).
pub const WAL_CHECKPOINT_INTERVAL: u32 = 1000;

// WAL entry type.
pub const WalEntryType = enum(u8) {
    insert,
    update,
    delete,
    checkpoint,
};

// WAL entry.
pub const WalEntry = struct {
    entry_id: u64,
    entry_type: WalEntryType,
    table_id: u32,
    record_id: u64,
    data: [MAX_WAL_ENTRY_SIZE]u8,
    data_len: u32,
    timestamp: u64,
    checksum: [file_storage.CHECKSUM_SIZE]u8,

    pub fn init() WalEntry {
        var entry = WalEntry{
            .entry_id = 0,
            .entry_type = WalEntryType.insert,
            .table_id = 0,
            .record_id = 0,
            .data = undefined,
            .data_len = 0,
            .timestamp = 0,
            .checksum = undefined,
        };
        var i: u32 = 0;
        while (i < MAX_WAL_ENTRY_SIZE) : (i += 1) {
            entry.data[i] = 0;
        }
        i = 0;
        while (i < file_storage.CHECKSUM_SIZE) : (i += 1) {
            entry.checksum[i] = 0;
        }
        return entry;
    }

    pub fn calculate_checksum(self: *WalEntry) void {
        var combined: [MAX_WAL_ENTRY_SIZE + 16]u8 = undefined;
        var combined_len: u32 = 0;
        var i: u32 = 0;
        while (i < self.data_len and i < MAX_WAL_ENTRY_SIZE) : (i += 1) {
            combined[combined_len] = self.data[i];
            combined_len += 1;
        }
        const table_id_bytes = std.mem.toBytes(self.table_id);
        i = 0;
        while (i < 4) : (i += 1) {
            combined[combined_len] = table_id_bytes[i];
            combined_len += 1;
        }
        const record_id_bytes = std.mem.toBytes(self.record_id);
        i = 0;
        while (i < 8) : (i += 1) {
            combined[combined_len] = record_id_bytes[i];
            combined_len += 1;
        }
        const entry_type_byte: u8 = @intFromEnum(self.entry_type);
        combined[combined_len] = entry_type_byte;
        combined_len += 1;
        var hash: [file_storage.CHECKSUM_SIZE]u8 = undefined;
        std.crypto.hash.sha2.Sha256.hash(combined[0..combined_len],
&hash, .{});
        i = 0;
        while (i < file_storage.CHECKSUM_SIZE) : (i += 1) {
            self.checksum[i] = hash[i];
        }
    }

    pub fn verify_checksum(self: *const WalEntry) bool {
        var computed: [file_storage.CHECKSUM_SIZE]u8 = undefined;
        var combined: [MAX_WAL_ENTRY_SIZE + 16]u8 = undefined;
        var combined_len: u32 = 0;
        var i: u32 = 0;
        while (i < self.data_len and i < MAX_WAL_ENTRY_SIZE) : (i += 1) {
            combined[combined_len] = self.data[i];
            combined_len += 1;
        }
        const table_id_bytes = std.mem.toBytes(self.table_id);
        i = 0;
        while (i < 4) : (i += 1) {
            combined[combined_len] = table_id_bytes[i];
            combined_len += 1;
        }
        const record_id_bytes = std.mem.toBytes(self.record_id);
        i = 0;
        while (i < 8) : (i += 1) {
            combined[combined_len] = record_id_bytes[i];
            combined_len += 1;
        }
        const entry_type_byte: u8 = @intFromEnum(self.entry_type);
        combined[combined_len] = entry_type_byte;
        combined_len += 1;
        std.crypto.hash.sha2.Sha256.hash(combined[0..combined_len],
&computed, .{});
        i = 0;
        while (i < file_storage.CHECKSUM_SIZE) : (i += 1) {
            if (computed[i] != self.checksum[i]) {
                return false;
            }
        }
        return true;
    }
};

// WAL manager: manages write-ahead log.
pub const WalManager = struct {
    entries: [MAX_WAL_ENTRIES]WalEntry,
    entries_len: u32,
    next_entry_id: u64,
    file_size: u64,
    checkpoint_count: u32,
    last_checkpoint: u64,

    pub fn init() WalManager {
        var manager = WalManager{
            .entries = undefined,
            .entries_len = 0,
            .next_entry_id = 1,
            .file_size = 0,
            .checkpoint_count = 0,
            .last_checkpoint = 0,
        };
        var i: u32 = 0;
        while (i < MAX_WAL_ENTRIES) : (i += 1) {
            manager.entries[i] = WalEntry.init();
        }
        return manager;
    }

    // Add WAL entry.
    pub fn add_entry(
        self: *WalManager,
        entry_type: WalEntryType,
        table_id: u32,
        record_id: u64,
        data: []const u8,
        timestamp: u64,
    ) ?*WalEntry {
        std.debug.assert(table_id > 0);
        std.debug.assert(record_id > 0);
        std.debug.assert(data.len > 0);
        std.debug.assert(data.len <= MAX_WAL_ENTRY_SIZE);
        std.debug.assert(timestamp > 0);
        if (self.entries_len >= MAX_WAL_ENTRIES) {
            return null;
        }
        const entry_id = self.next_entry_id;
        self.next_entry_id += 1;
        self.entries[self.entries_len] = WalEntry.init();
        const entry = &self.entries[self.entries_len];
        entry.entry_id = entry_id;
        entry.entry_type = entry_type;
        entry.table_id = table_id;
        entry.record_id = record_id;
        const data_len = @min(data.len, MAX_WAL_ENTRY_SIZE);
        var i: u32 = 0;
        while (i < MAX_WAL_ENTRY_SIZE) : (i += 1) {
            entry.data[i] = 0;
        }
        i = 0;
        while (i < data_len) : (i += 1) {
            entry.data[i] = data[i];
        }
        entry.data_len = data_len;
        entry.timestamp = timestamp;
        entry.calculate_checksum();
        const entry_size: u64 = @as(u64, @intCast(64 + data_len));
        self.file_size += entry_size;
        self.entries_len += 1;
        return entry;
    }

    // Check if checkpoint needed.
    pub fn needs_checkpoint(self: *const WalManager) bool {
        if (self.entries_len >= WAL_CHECKPOINT_INTERVAL) {
            return true;
        }
        if (self.file_size >= MAX_WAL_FILE_SIZE) {
            return true;
        }
        return false;
    }

    // Perform checkpoint.
    pub fn checkpoint(self: *WalManager, current_time: u64) bool {
        std.debug.assert(current_time > 0);
        if (self.entries_len == 0) {
            return false;
        }
        self.checkpoint_count += 1;
        self.last_checkpoint = current_time;
        var checkpoint_entry = WalEntry.init();
        checkpoint_entry.entry_id = self.next_entry_id;
        self.next_entry_id += 1;
        checkpoint_entry.entry_type = WalEntryType.checkpoint;
        checkpoint_entry.timestamp = current_time;
        checkpoint_entry.calculate_checksum();
        self.file_size = 0;
        self.entries_len = 0;
        return true;
    }

    // Get entries for recovery.
    pub fn get_recovery_entries(
        self: *const WalManager,
        entries_out: []WalEntry,
    ) u32 {
        std.debug.assert(entries_out.len >= MAX_WAL_ENTRIES);
        const count = @min(self.entries_len, entries_out.len);
        var i: u32 = 0;
        while (i < count) : (i += 1) {
            entries_out[i] = self.entries[i];
        }
        return count;
    }

    // Clear all entries.
    pub fn clear_all(self: *WalManager) void {
        self.entries_len = 0;
        self.file_size = 0;
        self.checkpoint_count = 0;
        self.last_checkpoint = 0;
    }
};


// === grain_core/wayland/protocol.zig ===

//! Wayland protocol: Core structures for Wayland compositor.
//!
//! Why: Implement Wayland protocol for window management.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max number of Wayland objects per client.
pub const MAX_OBJECTS_PER_CLIENT: u32 = 1024;

// Bounded: Max number of clients connected.
pub const MAX_CLIENTS: u32 = 64;

// Bounded: Max surface width/height (in pixels).
pub const MAX_SURFACE_WIDTH: u32 = 8192;
pub const MAX_SURFACE_HEIGHT: u32 = 8192;

// Wayland object ID type (32-bit unsigned integer).
pub const ObjectId = u32;

// Wayland interface name (bounded string).
pub const InterfaceName = struct {
    data: [64]u8,
    len: u32,

    pub fn init(name: []const u8) InterfaceName {
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= 64);
        var result = InterfaceName{
            .data = undefined,
            .len = @intCast(name.len),
        };
        var i: u32 = 0;
        while (i < 64) : (i += 1) {
            result.data[i] = 0;
        }
        i = 0;
        while (i < name.len) : (i += 1) {
            result.data[i] = name[i];
        }
        std.debug.assert(result.len <= 64);
        return result;
    }

    pub fn as_slice(self: *const InterfaceName) []const u8 {
        return self.data[0..self.len];
    }
};

// Wayland object: base structure for all Wayland objects.
pub const Object = struct {
    id: ObjectId,
    interface: InterfaceName,
    version: u32,

    pub fn init(id: ObjectId, interface: InterfaceName, version: u32)
Object {
        std.debug.assert(id > 0);
        std.debug.assert(version > 0);
        std.debug.assert(version <= 10);
        const obj = Object{
            .id = id,
            .interface = interface,
            .version = version,
        };
        std.debug.assert(obj.id > 0);
        return obj;
    }
};

// Surface: represents a drawable area (window content).
pub const Surface = struct {
    object: Object,
    width: u32,
    height: u32,
    buffer: ?[]u8,

    pub fn init(id: ObjectId, width: u32, height: u32) Surface {
        std.debug.assert(id > 0);
        std.debug.assert(width > 0);
        std.debug.assert(width <= MAX_SURFACE_WIDTH);
        std.debug.assert(height > 0);
        std.debug.assert(height <= MAX_SURFACE_HEIGHT);
        const surface = Surface{
            .object = Object.init(id, InterfaceName.init("wl_surface"),
4),
            .width = width,
            .height = height,
            .buffer = null,
        };
        std.debug.assert(surface.width > 0);
        std.debug.assert(surface.height > 0);
        return surface;
    }
};

// Output: represents a display/monitor.
pub const Output = struct {
    object: Object,
    width: u32,
    height: u32,
    physical_width: u32,
    physical_height: u32,

    pub fn init(
        id: ObjectId,
        width: u32,
        height: u32,
        physical_width: u32,
        physical_height: u32,
    ) Output {
        std.debug.assert(id > 0);
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        const output = Output{
            .object = Object.init(id, InterfaceName.init("wl_output"),
4),
            .width = width,
            .height = height,
            .physical_width = physical_width,
            .physical_height = physical_height,
        };
        std.debug.assert(output.width > 0);
        std.debug.assert(output.height > 0);
        return output;
    }
};

// Seat: represents input devices (keyboard, mouse, touch).
pub const Seat = struct {
    object: Object,
    has_keyboard: bool,
    has_pointer: bool,
    has_touch: bool,

    pub fn init(id: ObjectId) Seat {
        std.debug.assert(id > 0);
        const seat = Seat{
            .object = Object.init(id, InterfaceName.init("wl_seat"), 7),
            .has_keyboard = true,
            .has_pointer = true,
            .has_touch = false,
        };
        std.debug.assert(seat.object.id > 0);
        return seat;
    }
};

// Registry: global object registry for Wayland protocol.
pub const Registry = struct {
    object: Object,
    objects: [MAX_OBJECTS_PER_CLIENT]Object,
    objects_len: u32,

    pub fn init(id: ObjectId) Registry {
        std.debug.assert(id > 0);
        var registry = Registry{
            .object = Object.init(id, InterfaceName.init("wl_registry"),
1),
            .objects = undefined,
            .objects_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_OBJECTS_PER_CLIENT) : (i += 1) {
            registry.objects[i] = Object.init(0, InterfaceName.init(""),
0);
        }
        std.debug.assert(registry.object.id > 0);
        return registry;
    }

    pub fn bind(
        self: *Registry,
        name: u32,
        interface: InterfaceName,
        version: u32,
    ) !ObjectId {
        std.debug.assert(name > 0);
        std.debug.assert(version > 0);
        std.debug.assert(self.objects_len < MAX_OBJECTS_PER_CLIENT);
        const new_id: ObjectId = self.objects_len + 1;
        self.objects[self.objects_len] = Object.init(new_id, interface,
version);
        self.objects_len += 1;
        std.debug.assert(self.objects_len <= MAX_OBJECTS_PER_CLIENT);
        return new_id;
    }
};


// === grain_core/websocket.zig ===

//! Grain Core WebSocket: WebSocket protocol support for real-time
communication.
//!
//! Why: Provide WebSocket support for Silo Agent and Carry Agent
(livestream coordination).
//! Architecture: WebSocket handshake, frame parsing/generation,
connection management.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");
const api_server = @import("api_server.zig");

// Bounded: Max WebSocket connections.
pub const MAX_WEBSOCKET_CONNECTIONS: u32 = 128;

// Bounded: Max WebSocket frame size (64KB).
pub const MAX_FRAME_SIZE: u32 = 65536;

// Bounded: Max WebSocket message size (64KB).
pub const MAX_MESSAGE_SIZE: u32 = 65536;

// Bounded: Max WebSocket key length (base64 encoded).
pub const MAX_WEBSOCKET_KEY_LEN: u32 = 32;

// Bounded: Max WebSocket accept length (base64 encoded).
pub const MAX_WEBSOCKET_ACCEPT_LEN: u32 = 32;

// WebSocket frame opcode.
pub const FrameOpcode = enum(u4) {
    continuation = 0x0,
    text = 0x1,
    binary = 0x2,
    close = 0x8,
    ping = 0x9,
    pong = 0xA,
};

// WebSocket frame flags.
pub const FrameFlags = struct {
    fin: bool,
    rsv1: bool,
    rsv2: bool,
    rsv3: bool,
    opcode: FrameOpcode,
    masked: bool,
    payload_len: u64,
    mask_key: [4]u8,
};

// WebSocket connection state.
pub const ConnectionState = enum(u8) {
    connecting,
    open,
    closing,
    closed,
};

// WebSocket connection.
pub const WebSocketConnection = struct {
    connection_id: u32,
    state: ConnectionState,
    socket_fd: u32,
    created_at: u64,
    last_activity: u64,
    path: [api_server.MAX_PATH_LEN]u8,
    path_len: u32,
    subprotocol: [64]u8,
    subprotocol_len: u32,
    active: bool,

    pub fn init(connection_id: u32, socket_fd: u32) WebSocketConnection {
        std.debug.assert(connection_id > 0);
        std.debug.assert(socket_fd > 0);
        var conn = WebSocketConnection{
            .connection_id = connection_id,
            .state = ConnectionState.connecting,
            .socket_fd = socket_fd,
            .created_at = 0,
            .last_activity = 0,
            .path = undefined,
            .path_len = 0,
            .subprotocol = undefined,
            .subprotocol_len = 0,
            .active = false,
        };
        var i: u32 = 0;
        while (i < api_server.MAX_PATH_LEN) : (i += 1) {
            conn.path[i] = 0;
        }
        i = 0;
        while (i < 64) : (i += 1) {
            conn.subprotocol[i] = 0;
        }
        return conn;
    }
};

// WebSocket frame.
pub const WebSocketFrame = struct {
    flags: FrameFlags,
    payload: [MAX_FRAME_SIZE]u8,
    payload_len: u32,

    pub fn init() WebSocketFrame {
        var frame = WebSocketFrame{
            .flags = FrameFlags{
                .fin = false,
                .rsv1 = false,
                .rsv2 = false,
                .rsv3 = false,
                .opcode = FrameOpcode.text,
                .masked = false,
                .payload_len = 0,
                .mask_key = undefined,
            },
            .payload = undefined,
            .payload_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_FRAME_SIZE) : (i += 1) {
            frame.payload[i] = 0;
        }
        return frame;
    }
};

// WebSocket manager: manages WebSocket connections.
pub const WebSocketManager = struct {
    connections: [MAX_WEBSOCKET_CONNECTIONS]WebSocketConnection,
    connections_len: u32,
    next_connection_id: u32,

    pub fn init() WebSocketManager {
        var manager = WebSocketManager{
            .connections = undefined,
            .connections_len = 0,
            .next_connection_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_WEBSOCKET_CONNECTIONS) : (i += 1) {
            manager.connections[i] = WebSocketConnection.init(0, 0);
        }
        return manager;
    }

    // Add WebSocket connection.
    pub fn add_connection(
        self: *WebSocketManager,
        socket_fd: u32,
    ) ?*WebSocketConnection {
        std.debug.assert(socket_fd > 0);
        if (self.connections_len >= MAX_WEBSOCKET_CONNECTIONS) {
            return null;
        }
        const conn_id = self.next_connection_id;
        self.next_connection_id += 1;
        self.connections[self.connections_len] =
WebSocketConnection.init(
            conn_id,
            socket_fd,
        );
        self.connections[self.connections_len].active = true;
        const conn = &self.connections[self.connections_len];
        self.connections_len += 1;
        return conn;
    }

    // Remove WebSocket connection.
    pub fn remove_connection(
        self: *WebSocketManager,
        connection_id: u32,
    ) bool {
        std.debug.assert(connection_id > 0);
        var i: u32 = 0;
        while (i < self.connections_len) : (i += 1) {
            if (self.connections[i].connection_id == connection_id) {
                self.connections[i].active = false;
                self.connections[i].state = ConnectionState.closed;
                var j: u32 = i;
                while (j < self.connections_len - 1) : (j += 1) {
                    self.connections[j] = self.connections[j + 1];
                }
                self.connections_len -= 1;
                return true;
            }
        }
        return false;
    }

    // Find connection by ID.
    pub fn find_connection(
        self: *WebSocketManager,
        connection_id: u32,
    ) ?*WebSocketConnection {
        std.debug.assert(connection_id > 0);
        var i: u32 = 0;
        while (i < self.connections_len) : (i += 1) {
            if (self.connections[i].connection_id == connection_id) {
                return &self.connections[i];
            }
        }
        return null;
    }
};

// Generate WebSocket accept key from client key.
pub fn generate_websocket_accept(
    client_key: []const u8,
    accept_buf: []u8,
) u32 {
    std.debug.assert(client_key.len > 0);
    std.debug.assert(accept_buf.len >= MAX_WEBSOCKET_ACCEPT_LEN);
    const magic_string = "258EAFA5-E914-47DA-95CA-C5AB0DC85B11";
    var combined: [MAX_WEBSOCKET_KEY_LEN + 36]u8 = undefined;
    var combined_len: u32 = 0;
    const key_len = @min(client_key.len, MAX_WEBSOCKET_KEY_LEN);
    var i: u32 = 0;
    while (i < key_len) : (i += 1) {
        combined[combined_len] = client_key[i];
        combined_len += 1;
    }
    i = 0;
    while (i < 36) : (i += 1) {
        combined[combined_len] = magic_string[i];
        combined_len += 1;
    }
    var hash: [20]u8 = undefined;
    std.crypto.hash.Sha1.hash(combined[0..combined_len], &hash, .{});
    var base64_buf: [28]u8 = undefined;
    const base64_len = std.base64.standard.Encoder.calcSize(20);
    _ = std.base64.standard.Encoder.encode(&base64_buf, &hash);
    var j: u32 = 0;
    while (j < base64_len and j < accept_buf.len) : (j += 1) {
        accept_buf[j] = base64_buf[j];
    }
    return @intCast(base64_len);
}

// Check if HTTP request is WebSocket upgrade.
pub fn is_websocket_upgrade(request: *api_server.HttpRequest) bool {
    const upgrade_header = request.get_header("Upgrade");
    if (upgrade_header == null) {
        return false;
    }
    const upgrade_val = upgrade_header.?;
    if (upgrade_val.len < 9) {
        return false;
    }
    const websocket_str = "websocket";
    var i: u32 = 0;
    var match_count: u32 = 0;
    while (i < upgrade_val.len and match_count < 9) : (i += 1) {
        const c = upgrade_val[i];
        const ws_c = websocket_str[match_count];
        if (c == ws_c or c == (ws_c - 32)) {
            match_count += 1;
        } else {
            match_count = 0;
        }
    }
    return match_count == 9;
}

// Parse WebSocket frame from buffer.
pub fn parse_websocket_frame(
    buffer: []const u8,
    frame: *WebSocketFrame,
) bool {
    std.debug.assert(buffer.len > 0);
    if (buffer.len < 2) {
        return false;
    }
    const byte1 = buffer[0];
    const byte2 = buffer[1];
    frame.flags.fin = (byte1 & 0x80) != 0;
    frame.flags.rsv1 = (byte1 & 0x40) != 0;
    frame.flags.rsv2 = (byte1 & 0x20) != 0;
    frame.flags.rsv3 = (byte1 & 0x10) != 0;
    const opcode_val = @as(u4, @truncate(byte1 & 0x0F));
    frame.flags.opcode = @enumFromInt(opcode_val);
    frame.flags.masked = (byte2 & 0x80) != 0;
    var payload_len: u64 = @as(u64, byte2 & 0x7F);
    var header_len: u32 = 2;
    if (payload_len == 126) {
        if (buffer.len < 4) {
            return false;
        }
        payload_len = (@as(u64, buffer[2]) << 8) | @as(u64, buffer[3]);
        header_len = 4;
    } else if (payload_len == 127) {
        if (buffer.len < 10) {
            return false;
        }
        payload_len = (@as(u64, buffer[2]) << 56) |
            (@as(u64, buffer[3]) << 48) |
            (@as(u64, buffer[4]) << 40) |
            (@as(u64, buffer[5]) << 32) |
            (@as(u64, buffer[6]) << 24) |
            (@as(u64, buffer[7]) << 16) |
            (@as(u64, buffer[8]) << 8) |
            @as(u64, buffer[9]);
        header_len = 10;
    }
    if (payload_len > MAX_FRAME_SIZE) {
        return false;
    }
    frame.flags.payload_len = payload_len;
    if (frame.flags.masked) {
        if (buffer.len < header_len + 4) {
            return false;
        }
        var i: u32 = 0;
        while (i < 4) : (i += 1) {
            frame.flags.mask_key[i] = buffer[header_len + i];
        }
        header_len += 4;
    }
    if (buffer.len < header_len + payload_len) {
        return false;
    }
    const payload_start = header_len;
    var i: u32 = 0;
    while (i < payload_len) : (i += 1) {
        if (frame.flags.masked) {
            frame.payload[i] = buffer[payload_start + i] ^
                frame.flags.mask_key[i % 4];
        } else {
            frame.payload[i] = buffer[payload_start + i];
        }
    }
    frame.payload_len = @intCast(payload_len);
    return true;
}

// Generate WebSocket frame to buffer.
pub fn generate_websocket_frame(
    frame: *const WebSocketFrame,
    buffer: []u8,
) u32 {
    std.debug.assert(buffer.len >= MAX_FRAME_SIZE + 14);
    std.debug.assert(frame.payload_len <= MAX_FRAME_SIZE);
    var offset: u32 = 0;
    var byte1: u8 = 0;
    if (frame.flags.fin) {
        byte1 |= 0x80;
    }
    if (frame.flags.rsv1) {
        byte1 |= 0x40;
    }
    if (frame.flags.rsv2) {
        byte1 |= 0x20;
    }
    if (frame.flags.rsv3) {
        byte1 |= 0x10;
    }
    byte1 |= @intFromEnum(frame.flags.opcode);
    buffer[offset] = byte1;
    offset += 1;
    var byte2: u8 = 0;
    if (frame.flags.masked) {
        byte2 |= 0x80;
    }
    const payload_len = frame.payload_len;
    if (payload_len < 126) {
        byte2 |= @as(u8, @truncate(payload_len));
        buffer[offset] = byte2;
        offset += 1;
    } else if (payload_len < 65536) {
        byte2 |= 126;
        buffer[offset] = byte2;
        offset += 1;
        buffer[offset] = @as(u8, @truncate(payload_len >> 8));
        offset += 1;
        buffer[offset] = @as(u8, @truncate(payload_len));
        offset += 1;
    } else {
        byte2 |= 127;
        buffer[offset] = byte2;
        offset += 1;
        var i: u32 = 0;
        while (i < 8) : (i += 1) {
            const byte_idx: u32 = 7 - i;
            const shift_amt: u6 = @intCast(byte_idx * 8);
            buffer[offset] = @as(u8, @truncate(payload_len >>
shift_amt));
            offset += 1;
        }
    }
    if (frame.flags.masked) {
        var i: u32 = 0;
        while (i < 4) : (i += 1) {
            buffer[offset] = frame.flags.mask_key[i];
            offset += 1;
        }
    }
    var i: u32 = 0;
    while (i < payload_len) : (i += 1) {
        if (frame.flags.masked) {
            buffer[offset] = frame.payload[i] ^ frame.flags.mask_key[i %
4];
        } else {
            buffer[offset] = frame.payload[i];
        }
        offset += 1;
    }
    return offset;
}


// === grain_core/websocket_handshake.zig ===

//! Grain Core WebSocket Handshake: HTTP upgrade to WebSocket protocol.
//!
//! Why: Handle WebSocket handshake (HTTP upgrade) for API server
integration.
//! Architecture: HTTP upgrade request/response, WebSocket key
validation.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.

const std = @import("std");
const api_server = @import("api_server.zig");
const websocket = @import("websocket.zig");

// Handle WebSocket handshake (HTTP upgrade).
pub fn handle_websocket_handshake(
    request: *api_server.HttpRequest,
    response: *api_server.HttpResponse,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(response != null);
    if (!websocket.is_websocket_upgrade(request)) {
        return false;
    }
    const sec_websocket_key = request.get_header("Sec-WebSocket-Key");
    if (sec_websocket_key == null) {
        response.status = api_server.HttpStatus.bad_request;
        return false;
    }
    const key = sec_websocket_key.?;
    if (key.len == 0) {
        response.status = api_server.HttpStatus.bad_request;
        return false;
    }
    var accept_buf: [websocket.MAX_WEBSOCKET_ACCEPT_LEN]u8 = undefined;
    const accept_len = websocket.generate_websocket_accept(key,
&accept_buf);
    response.status = api_server.HttpStatus.ok;
    _ = response.add_header("Upgrade", "websocket");
    _ = response.add_header("Connection", "Upgrade");
    var accept_str: [websocket.MAX_WEBSOCKET_ACCEPT_LEN]u8 = undefined;
    var i: u32 = 0;
    while (i < accept_len and i < websocket.MAX_WEBSOCKET_ACCEPT_LEN) :
(i += 1) {
        accept_str[i] = accept_buf[i];
    }
    _ = response.add_header("Sec-WebSocket-Accept",
accept_str[0..accept_len]);
    return true;
}


// === grain_core/window_actions.zig ===

//! Grain OS Window Actions: Rectangle-inspired window management
shortcuts.
//!
//! Why: Provide keyboard shortcuts for window positioning and resizing.
//! Architecture: Window action functions for compositor integration.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");

// Window action: function that modifies window position/size.
pub const WindowAction = *const fn (*compositor.Compositor, u32) bool;

// Move window to left half of screen.
pub fn action_left_half(comp: *compositor.Compositor, window_id: u32)
bool {
    std.debug.assert(window_id > 0);
    if (comp.get_window(window_id)) |win| {
        win.x = @as(i32, @intCast(compositor.BORDER_WIDTH));
        win.y = @as(i32, @intCast(compositor.BORDER_WIDTH +
compositor.TITLE_BAR_HEIGHT));
        win.width = comp.output.width / 2;
        win.height = comp.output.height - (compositor.BORDER_WIDTH * 2)
- compositor.TITLE_BAR_HEIGHT;
        comp.recalculate_layout();
        return true;
    }
    return false;
}

// Move window to right half of screen.
pub fn action_right_half(comp: *compositor.Compositor, window_id: u32)
bool {
    std.debug.assert(window_id > 0);
    if (comp.get_window(window_id)) |win| {
        win.x = @as(i32, @intCast(comp.output.width / 2));
        win.y = @as(i32, @intCast(compositor.BORDER_WIDTH +
compositor.TITLE_BAR_HEIGHT));
        win.width = comp.output.width / 2;
        win.height = comp.output.height - (compositor.BORDER_WIDTH * 2)
- compositor.TITLE_BAR_HEIGHT;
        comp.recalculate_layout();
        return true;
    }
    return false;
}

