// Center window on screen.
pub fn action_center(comp: *compositor.Compositor, window_id: u32) bool {
    std.debug.assert(window_id > 0);
    if (comp.get_window(window_id)) |win| {
        const content_width = comp.output.width -
(compositor.BORDER_WIDTH * 2);
        const content_height = comp.output.height -
(compositor.BORDER_WIDTH * 2) - compositor.TITLE_BAR_HEIGHT;
        const center_x = (content_width - win.width) / 2;
        const center_y = (content_height - win.height) / 2;
        win.x = @as(i32, @intCast(compositor.BORDER_WIDTH + center_x));
        win.y = @as(i32, @intCast(compositor.BORDER_WIDTH +
compositor.TITLE_BAR_HEIGHT + center_y));
        comp.recalculate_layout();
        return true;
    }
    return false;
}

// Make window larger (increase size by 10%).
pub fn action_larger(comp: *compositor.Compositor, window_id: u32) bool {
    std.debug.assert(window_id > 0);
    if (comp.get_window(window_id)) |win| {
        const new_width = win.width + (win.width / 10);
        const new_height = win.height + (win.height / 10);
        const max_width = comp.output.width - (compositor.BORDER_WIDTH *
2);
        const max_height = comp.output.height - (compositor.BORDER_WIDTH
* 2) - compositor.TITLE_BAR_HEIGHT;
        win.width = if (new_width > max_width) max_width else new_width;
        win.height = if (new_height > max_height) max_height else
new_height;
        comp.recalculate_layout();
        return true;
    }
    return false;
}

// Make window smaller (decrease size by 10%).
pub fn action_smaller(comp: *compositor.Compositor, window_id: u32) bool
{
    std.debug.assert(window_id > 0);
    if (comp.get_window(window_id)) |win| {
        const min_size: u32 = 100;
        const new_width = if (win.width > win.width / 10) win.width -
(win.width / 10) else min_size;
        const new_height = if (win.height > win.height / 10) win.height
- (win.height / 10) else min_size;
        win.width = if (new_width < min_size) min_size else new_width;
        win.height = if (new_height < min_size) min_size else new_height;
        comp.recalculate_layout();
        return true;
    }
    return false;
}

// Maximize height only.
pub fn action_maximize_height(comp: *compositor.Compositor, window_id:
u32) bool {
    std.debug.assert(window_id > 0);
    if (comp.get_window(window_id)) |win| {
        win.y = @as(i32, @intCast(compositor.BORDER_WIDTH +
compositor.TITLE_BAR_HEIGHT));
        win.height = comp.output.height - (compositor.BORDER_WIDTH * 2)
- compositor.TITLE_BAR_HEIGHT;
        comp.recalculate_layout();
        return true;
    }
    return false;
}

// Switch to next window (Alt+Tab forward).
pub fn action_switch_next(comp: *compositor.Compositor, _window_id: u32)
bool {
    _ = _window_id;
    return comp.switch_to_next_window();
}

// Switch to previous window (Alt+Shift+Tab backward).
pub fn action_switch_previous(comp: *compositor.Compositor, _window_id:
u32) bool {
    _ = _window_id;
    return comp.switch_to_previous_window();
}


// === grain_core/window_animation.zig ===

//! Grain OS Window Animation: Smooth transitions for window operations.
//!
//! Why: Provide smooth animations for window move, resize, minimize,
maximize.
//! Architecture: Animation state management and interpolation.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");

// Bounded: Max active animations.
pub const MAX_ANIMATIONS: u32 = 64;

// Bounded: Animation duration (milliseconds).
pub const ANIMATION_DURATION_MS: u32 = 200;

// Animation type.
pub const AnimationType = enum(u8) {
    none,
    move,
    resize,
    minimize,
    maximize,
    opacity,
};

// Animation state.
pub const AnimationState = struct {
    window_id: u32,
    anim_type: AnimationType,
    start_x: i32,
    start_y: i32,
    start_width: u32,
    start_height: u32,
    start_opacity: u8,
    target_x: i32,
    target_y: i32,
    target_width: u32,
    target_height: u32,
    target_opacity: u8,
    start_time: u64, // Timestamp in milliseconds.
    duration_ms: u32,
    active: bool,
};

// Animation manager: manages window animations.
pub const AnimationManager = struct {
    animations: [MAX_ANIMATIONS]AnimationState,
    animations_len: u32,

    pub fn init() AnimationManager {
        var manager = AnimationManager{
            .animations = undefined,
            .animations_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_ANIMATIONS) : (i += 1) {
            manager.animations[i] = AnimationState{
                .window_id = 0,
                .anim_type = AnimationType.none,
                .start_x = 0,
                .start_y = 0,
                .start_width = 0,
                .start_height = 0,
                .start_opacity = 0,
                .target_x = 0,
                .target_y = 0,
                .target_width = 0,
                .target_height = 0,
                .target_opacity = 0,
                .start_time = 0,
                .duration_ms = 0,
                .active = false,
            };
        }
        return manager;
    }

    // Start animation for window.
    pub fn start_animation(
        self: *AnimationManager,
        window_id: u32,
        anim_type: AnimationType,
        start_x: i32,
        start_y: i32,
        start_width: u32,
        start_height: u32,
        start_opacity: u8,
        target_x: i32,
        target_y: i32,
        target_width: u32,
        target_height: u32,
        target_opacity: u8,
        start_time: u64,
    ) bool {
        std.debug.assert(window_id > 0);
        if (self.animations_len >= MAX_ANIMATIONS) {
            return false;
        }
        // Check if animation already exists, update it.
        var i: u32 = 0;
        while (i < self.animations_len) : (i += 1) {
            if (self.animations[i].window_id == window_id) {
                self.animations[i].anim_type = anim_type;
                self.animations[i].start_x = start_x;
                self.animations[i].start_y = start_y;
                self.animations[i].start_width = start_width;
                self.animations[i].start_height = start_height;
                self.animations[i].start_opacity = start_opacity;
                self.animations[i].target_x = target_x;
                self.animations[i].target_y = target_y;
                self.animations[i].target_width = target_width;
                self.animations[i].target_height = target_height;
                self.animations[i].target_opacity = target_opacity;
                self.animations[i].start_time = start_time;
                self.animations[i].duration_ms = ANIMATION_DURATION_MS;
                self.animations[i].active = true;
                return true;
            }
        }
        // Add new animation.
        self.animations[self.animations_len] = AnimationState{
            .window_id = window_id,
            .anim_type = anim_type,
            .start_x = start_x,
            .start_y = start_y,
            .start_width = start_width,
            .start_height = start_height,
            .start_opacity = start_opacity,
            .target_x = target_x,
            .target_y = target_y,
            .target_width = target_width,
            .target_height = target_height,
            .target_opacity = target_opacity,
            .start_time = start_time,
            .duration_ms = ANIMATION_DURATION_MS,
            .active = true,
        };
        self.animations_len += 1;
        return true;
    }

    // Get animation for window.
    pub fn get_animation(
        self: *AnimationManager,
        window_id: u32,
    ) ?*AnimationState {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        while (i < self.animations_len) : (i += 1) {
            if (self.animations[i].window_id == window_id and
                self.animations[i].active)
            {
                return &self.animations[i];
            }
        }
        return null;
    }

    // Remove animation for window.
    pub fn remove_animation(self: *AnimationManager, window_id: u32)
bool {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        while (i < self.animations_len) : (i += 1) {
            if (self.animations[i].window_id == window_id) {
                self.animations[i].active = false;
                return true;
            }
        }
        return false;
    }

    // Calculate interpolation progress (0.0 to 1.0).
    pub fn calc_progress(
        _self: *const AnimationManager,
        anim: *const AnimationState,
        current_time: u64,
    ) f32 {
        _ = _self;
        if (current_time < anim.start_time) {
            return 0.0;
        }
        const elapsed: u64 = current_time - anim.start_time;
        if (elapsed >= anim.duration_ms) {
            return 1.0;
        }
        const progress: f32 = @as(f32, @floatFromInt(elapsed)) /
            @as(f32, @floatFromInt(anim.duration_ms));
        return progress;
    }

    // Linear interpolation between start and target.
    pub fn lerp(start: f32, target: f32, progress: f32) f32 {
        return start + (target - start) * progress;
    }

    // Update animation and return current values.
    pub fn update_animation(
        self: *AnimationManager,
        window_id: u32,
        current_time: u64,
    ) ?struct { x: i32, y: i32, width: u32, height: u32, opacity: u8,
done: bool } {
        std.debug.assert(window_id > 0);
        if (self.get_animation(window_id)) |anim| {
            const progress = self.calc_progress(anim, current_time);
            const done = (progress >= 1.0);
            // Interpolate values.
            const x = @as(i32, @intFromFloat(AnimationManager.lerp(
                @as(f32, @floatFromInt(anim.start_x)),
                @as(f32, @floatFromInt(anim.target_x)),
                progress,
            )));
            const y = @as(i32, @intFromFloat(AnimationManager.lerp(
                @as(f32, @floatFromInt(anim.start_y)),
                @as(f32, @floatFromInt(anim.target_y)),
                progress,
            )));
            const width = @as(u32, @intFromFloat(AnimationManager.lerp(
                @as(f32, @floatFromInt(anim.start_width)),
                @as(f32, @floatFromInt(anim.target_width)),
                progress,
            )));
            const height = @as(u32, @intFromFloat(AnimationManager.lerp(
                @as(f32, @floatFromInt(anim.start_height)),
                @as(f32, @floatFromInt(anim.target_height)),
                progress,
            )));
            const opacity = @as(u8, @intFromFloat(AnimationManager.lerp(
                @as(f32, @floatFromInt(anim.start_opacity)),
                @as(f32, @floatFromInt(anim.target_opacity)),
                progress,
            )));
            if (done) {
                _ = self.remove_animation(window_id);
            }
            return .{ .x = x, .y = y, .width = width, .height = height,
.opacity = opacity, .done = done };
        }
        return null;
    }

    // Clear all animations.
    pub fn clear_all(self: *AnimationManager) void {
        var i: u32 = 0;
        while (i < self.animations_len) : (i += 1) {
            self.animations[i].active = false;
        }
        self.animations_len = 0;
    }

    // Get animation count.
    pub fn get_count(self: *const AnimationManager) u32 {
        return self.animations_len;
    }
};


// === grain_core/window_constraints.zig ===

//! Grain OS Window Constraints: Min/max size and aspect ratio limits.
//!
//! Why: Enforce window size limits and aspect ratios for proper layout.
//! Architecture: Constraint validation and application for window
resizing.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Default minimum window size.
pub const DEFAULT_MIN_WIDTH: u32 = 100;
pub const DEFAULT_MIN_HEIGHT: u32 = 100;

// Bounded: Default maximum window size (unlimited = 0).
pub const DEFAULT_MAX_WIDTH: u32 = 0; // 0 = unlimited.
pub const DEFAULT_MAX_HEIGHT: u32 = 0; // 0 = unlimited.

// Bounded: Default aspect ratio (0 = no constraint).
pub const DEFAULT_ASPECT_RATIO: f32 = 0.0; // 0 = no constraint.

// Window constraints: size and aspect ratio limits.
pub const WindowConstraints = struct {
    min_width: u32,
    min_height: u32,
    max_width: u32, // 0 = unlimited.
    max_height: u32, // 0 = unlimited.
    aspect_ratio: f32, // 0 = no constraint, >0 = width/height.

    pub fn init() WindowConstraints {
        return WindowConstraints{
            .min_width = DEFAULT_MIN_WIDTH,
            .min_height = DEFAULT_MIN_HEIGHT,
            .max_width = DEFAULT_MAX_WIDTH,
            .max_height = DEFAULT_MAX_HEIGHT,
            .aspect_ratio = DEFAULT_ASPECT_RATIO,
        };
    }

    // Apply constraints to width and height.
    pub fn apply_constraints(
        self: *const WindowConstraints,
        width: u32,
        height: u32,
    ) struct { width: u32, height: u32 } {
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        var result_width = width;
        var result_height = height;
        // Apply minimum size.
        if (result_width < self.min_width) {
            result_width = self.min_width;
        }
        if (result_height < self.min_height) {
            result_height = self.min_height;
        }
        // Apply maximum size.
        if (self.max_width > 0 and result_width > self.max_width) {
            result_width = self.max_width;
        }
        if (self.max_height > 0 and result_height > self.max_height) {
            result_height = self.max_height;
        }
        // Apply aspect ratio constraint.
        if (self.aspect_ratio > 0.0) {
            const current_ratio = @as(f32, @floatFromInt(result_width)) /
                @as(f32, @floatFromInt(result_height));
            if (current_ratio > self.aspect_ratio) {
                // Too wide, adjust height.
                result_height = @as(u32, @intFromFloat(@as(f32,
@floatFromInt(result_width)) /
                    self.aspect_ratio));
                // Re-apply min/max after aspect adjustment.
                if (result_height < self.min_height) {
                    result_height = self.min_height;
                    result_width = @as(u32, @intFromFloat(@as(f32,
@floatFromInt(result_height)) *
                        self.aspect_ratio));
                }
                if (self.max_height > 0 and result_height >
self.max_height) {
                    result_height = self.max_height;
                    result_width = @as(u32, @intFromFloat(@as(f32,
@floatFromInt(result_height)) *
                        self.aspect_ratio));
                }
            } else if (current_ratio < self.aspect_ratio) {
                // Too tall, adjust width.
                result_width = @as(u32, @intFromFloat(@as(f32,
@floatFromInt(result_height)) *
                    self.aspect_ratio));
                // Re-apply min/max after aspect adjustment.
                if (result_width < self.min_width) {
                    result_width = self.min_width;
                    result_height = @as(u32, @intFromFloat(@as(f32,
@floatFromInt(result_width)) /
                        self.aspect_ratio));
                }
                if (self.max_width > 0 and result_width >
self.max_width) {
                    result_width = self.max_width;
                    result_height = @as(u32, @intFromFloat(@as(f32,
@floatFromInt(result_width)) /
                        self.aspect_ratio));
                }
            }
        }
        std.debug.assert(result_width > 0);
        std.debug.assert(result_height > 0);
        return .{ .width = result_width, .height = result_height };
    }

    // Check if size is valid according to constraints.
    pub fn is_valid_size(
        self: *const WindowConstraints,
        width: u32,
        height: u32,
    ) bool {
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        if (width < self.min_width or height < self.min_height) {
            return false;
        }
        if (self.max_width > 0 and width > self.max_width) {
            return false;
        }
        if (self.max_height > 0 and height > self.max_height) {
            return false;
        }
        if (self.aspect_ratio > 0.0) {
            const ratio = @as(f32, @floatFromInt(width)) /
                @as(f32, @floatFromInt(height));
            const tolerance: f32 = 0.01; // Allow small floating point
errors.
            const diff = if (ratio > self.aspect_ratio)
                ratio - self.aspect_ratio
            else
                self.aspect_ratio - ratio;
            if (diff > tolerance) {
                return false;
            }
        }
        return true;
    }

    // Set minimum size.
    pub fn set_min_size(
        self: *WindowConstraints,
        min_width: u32,
        min_height: u32,
    ) void {
        std.debug.assert(min_width > 0);
        std.debug.assert(min_height > 0);
        self.min_width = min_width;
        self.min_height = min_height;
    }

    // Set maximum size.
    pub fn set_max_size(
        self: *WindowConstraints,
        max_width: u32,
        max_height: u32,
    ) void {
        std.debug.assert(max_width == 0 or max_width > 0);
        std.debug.assert(max_height == 0 or max_height > 0);
        self.max_width = max_width;
        self.max_height = max_height;
    }

    // Set aspect ratio (0 = no constraint).
    pub fn set_aspect_ratio(self: *WindowConstraints, aspect_ratio: f32)
void {
        std.debug.assert(aspect_ratio >= 0.0);
        self.aspect_ratio = aspect_ratio;
    }
};


// === grain_core/window_decorations.zig ===

//! Grain OS Window Decorations: Title bar buttons and controls.
//!
//! Why: Provide interactive title bar buttons (close, minimize,
maximize).
//! Architecture: Button rendering and hit testing for window controls.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");

// Bounded: Button size.
pub const BUTTON_SIZE: u32 = 20;

// Bounded: Button spacing.
pub const BUTTON_SPACING: u32 = 4;

// Bounded: Button margin from edge.
pub const BUTTON_MARGIN: u32 = 4;

// Button type.
pub const ButtonType = enum(u8) {
    none,
    close,
    minimize,
    maximize,
};

// Button state.
pub const ButtonState = struct {
    hovered: bool,
    pressed: bool,
};

// Get close button bounds.
pub fn get_close_button_bounds(
    win_x: i32,
    win_y: i32,
    win_width: u32,
) struct { x: i32, y: i32, width: u32, height: u32 } {
    const title_bar_x = win_x + @as(i32,
@intCast(compositor.BORDER_WIDTH));
    const title_bar_y = win_y + @as(i32,
@intCast(compositor.BORDER_WIDTH));
    const button_x = title_bar_x + @as(i32, @intCast(win_width -
compositor.BORDER_WIDTH * 2 - BUTTON_MARGIN - BUTTON_SIZE));
    const button_y = title_bar_y;
    return .{
        .x = button_x,
        .y = button_y,
        .width = BUTTON_SIZE,
        .height = compositor.TITLE_BAR_HEIGHT,
    };
}

// Get minimize button bounds.
pub fn get_minimize_button_bounds(
    win_x: i32,
    win_y: i32,
    win_width: u32,
) struct { x: i32, y: i32, width: u32, height: u32 } {
    const close_bounds = get_close_button_bounds(win_x, win_y,
win_width);
    const button_x = close_bounds.x - @as(i32, @intCast(BUTTON_SIZE +
BUTTON_SPACING));
    const button_y = close_bounds.y;
    return .{
        .x = button_x,
        .y = button_y,
        .width = BUTTON_SIZE,
        .height = compositor.TITLE_BAR_HEIGHT,
    };
}

// Get maximize button bounds.
pub fn get_maximize_button_bounds(
    win_x: i32,
    win_y: i32,
    win_width: u32,
) struct { x: i32, y: i32, width: u32, height: u32 } {
    const minimize_bounds = get_minimize_button_bounds(win_x, win_y,
win_width);
    const button_x = minimize_bounds.x - @as(i32, @intCast(BUTTON_SIZE +
BUTTON_SPACING));
    const button_y = minimize_bounds.y;
    return .{
        .x = button_x,
        .y = button_y,
        .width = BUTTON_SIZE,
        .height = compositor.TITLE_BAR_HEIGHT,
    };
}

// Check if point is in close button.
pub fn is_in_close_button(
    win_x: i32,
    win_y: i32,
    win_width: u32,
    x: u32,
    y: u32,
) bool {
    const bounds = get_close_button_bounds(win_x, win_y, win_width);
    const x_i32 = @as(i32, @intCast(x));
    const y_i32 = @as(i32, @intCast(y));
    return (x_i32 >= bounds.x and x_i32 < bounds.x + @as(i32,
@intCast(bounds.width)) and
        y_i32 >= bounds.y and y_i32 < bounds.y + @as(i32,
@intCast(bounds.height)));
}

// Check if point is in minimize button.
pub fn is_in_minimize_button(
    win_x: i32,
    win_y: i32,
    win_width: u32,
    x: u32,
    y: u32,
) bool {
    const bounds = get_minimize_button_bounds(win_x, win_y, win_width);
    const x_i32 = @as(i32, @intCast(x));
    const y_i32 = @as(i32, @intCast(y));
    return (x_i32 >= bounds.x and x_i32 < bounds.x + @as(i32,
@intCast(bounds.width)) and
        y_i32 >= bounds.y and y_i32 < bounds.y + @as(i32,
@intCast(bounds.height)));
}

// Check if point is in maximize button.
pub fn is_in_maximize_button(
    win_x: i32,
    win_y: i32,
    win_width: u32,
    x: u32,
    y: u32,
) bool {
    const bounds = get_maximize_button_bounds(win_x, win_y, win_width);
    const x_i32 = @as(i32, @intCast(x));
    const y_i32 = @as(i32, @intCast(y));
    return (x_i32 >= bounds.x and x_i32 < bounds.x + @as(i32,
@intCast(bounds.width)) and
        y_i32 >= bounds.y and y_i32 < bounds.y + @as(i32,
@intCast(bounds.height)));
}

// Get button type at point.
pub fn get_button_at(
    win_x: i32,
    win_y: i32,
    win_width: u32,
    x: u32,
    y: u32,
) ButtonType {
    if (is_in_close_button(win_x, win_y, win_width, x, y)) {
        return ButtonType.close;
    }
    if (is_in_minimize_button(win_x, win_y, win_width, x, y)) {
        return ButtonType.minimize;
    }
    if (is_in_maximize_button(win_x, win_y, win_width, x, y)) {
        return ButtonType.maximize;
    }
    return ButtonType.none;
}

// Get button color for state.
pub fn get_button_color(
    button_type: ButtonType,
    hovered: bool,
    pressed: bool,
    focused: bool,
) u32 {
    _ = focused;
    if (pressed) {
        return 0xFF666666; // Dark gray when pressed.
    }
    if (hovered) {
        if (button_type == ButtonType.close) {
            return 0xFFFF0000; // Red when hovered.
        }
        return 0xFF888888; // Light gray when hovered.
    }
    return 0xFFCCCCCC; // Light gray default.
}


// === grain_core/window_drag_drop.zig ===

//! Grain OS Window Drag and Drop: Drag windows between workspaces and
drop zones.
//!
//! Why: Allow windows to be dragged and dropped for workspace switching
and operations.
//! Architecture: Drag and drop state management and drop zone detection.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");

// Bounded: Max drop zones.
pub const MAX_DROP_ZONES: u32 = 16;

// Drop zone type.
pub const DropZoneType = enum(u8) {
    none,
    workspace,
    group,
    snap_zone,
};

// Drop zone: target for window drag and drop.
pub const DropZone = struct {
    zone_id: u32,
    zone_type: DropZoneType,
    x: i32,
    y: i32,
    width: u32,
    height: u32,
    target_id: u32, // Workspace ID, group ID, etc.
    active: bool,
};

// Drag and drop state.
pub const DragDropState = struct {
    dragging_window_id: u32,
    drag_start_x: i32,
    drag_start_y: i32,
    current_x: i32,
    current_y: i32,
    active: bool,
};

// Drop zone manager: manages drop zones.
pub const DropZoneManager = struct {
    zones: [MAX_DROP_ZONES]DropZone,
    zones_len: u32,
    next_zone_id: u32,

    pub fn init() DropZoneManager {
        var manager = DropZoneManager{
            .zones = undefined,
            .zones_len = 0,
            .next_zone_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_DROP_ZONES) : (i += 1) {
            manager.zones[i] = DropZone{
                .zone_id = 0,
                .zone_type = DropZoneType.none,
                .x = 0,
                .y = 0,
                .width = 0,
                .height = 0,
                .target_id = 0,
                .active = false,
            };
        }
        return manager;
    }

    // Add drop zone.
    pub fn add_drop_zone(
        self: *DropZoneManager,
        zone_type: DropZoneType,
        x: i32,
        y: i32,
        width: u32,
        height: u32,
        target_id: u32,
    ) ?u32 {
        if (self.zones_len >= MAX_DROP_ZONES) {
            return null;
        }
        const zone_id = self.next_zone_id;
        self.next_zone_id += 1;
        self.zones[self.zones_len] = DropZone{
            .zone_id = zone_id,
            .zone_type = zone_type,
            .x = x,
            .y = y,
            .width = width,
            .height = height,
            .target_id = target_id,
            .active = true,
        };
        self.zones_len += 1;
        return zone_id;
    }

    // Find drop zone at point.
    pub fn find_drop_zone_at(
        self: *const DropZoneManager,
        x: u32,
        y: u32,
    ) ?*const DropZone {
        const x_i32 = @as(i32, @intCast(x));
        const y_i32 = @as(i32, @intCast(y));
        var i: u32 = 0;
        while (i < self.zones_len) : (i += 1) {
            const zone = &self.zones[i];
            if (zone.active) {
                if (x_i32 >= zone.x and x_i32 < zone.x + @as(i32,
@intCast(zone.width)) and
                    y_i32 >= zone.y and y_i32 < zone.y + @as(i32,
@intCast(zone.height)))
                {
                    return zone;
                }
            }
        }
        return null;
    }

    // Remove drop zone.
    pub fn remove_drop_zone(self: *DropZoneManager, zone_id: u32) bool {
        std.debug.assert(zone_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.zones_len) : (i += 1) {
            if (self.zones[i].zone_id == zone_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining zones left.
        while (i < self.zones_len - 1) : (i += 1) {
            self.zones[i] = self.zones[i + 1];
        }
        self.zones_len -= 1;
        return true;
    }

    // Clear all drop zones.
    pub fn clear_all(self: *DropZoneManager) void {
        self.zones_len = 0;
    }

    // Get drop zone count.
    pub fn get_zone_count(self: *const DropZoneManager) u32 {
        return self.zones_len;
    }
};

// Check if window can be dragged.
pub fn can_drag_window(window_id: u32, maximized: bool) bool {
    std.debug.assert(window_id > 0);
    return !maximized;
}

// Check if window can be dropped on target.
pub fn can_drop_window(
    _window_id: u32,
    drop_zone: *const DropZone,
) bool {
    std.debug.assert(_window_id > 0);
    return drop_zone.active;
}


// === grain_core/window_effects.zig ===

//! Grain OS Window Effects: Fade, slide animations for window lifecycle.
//!
//! Why: Provide smooth visual effects for window open/close operations.
//! Architecture: Window effect management and animation integration.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");
const window_animation = @import("window_animation.zig");
const window_opacity = @import("window_opacity.zig");

// Bounded: Effect duration (milliseconds).
pub const FADE_DURATION_MS: u32 = 150;
pub const SLIDE_DURATION_MS: u32 = 200;

// Effect type.
pub const EffectType = enum(u8) {
    none,
    fade_in,
    fade_out,
    slide_in,
    slide_out,
};

// Effect direction for slide.
pub const SlideDirection = enum(u8) {
    from_top,
    from_bottom,
    from_left,
    from_right,
};

// Window effect state.
pub const WindowEffectState = struct {
    effect_type: EffectType,
    slide_direction: SlideDirection,
    active: bool,
};

// Calculate fade-in opacity.
pub fn calc_fade_in_opacity(progress: f32) u8 {
    std.debug.assert(progress >= 0.0);
    std.debug.assert(progress <= 1.0);
    const opacity_f = progress;
    return @as(u8, @intFromFloat(opacity_f * 255.0));
}

// Calculate fade-out opacity.
pub fn calc_fade_out_opacity(progress: f32) u8 {
    std.debug.assert(progress >= 0.0);
    std.debug.assert(progress <= 1.0);
    const opacity_f = 1.0 - progress;
    return @as(u8, @intFromFloat(opacity_f * 255.0));
}

// Calculate slide-in position.
pub fn calc_slide_in_position(
    _start_pos: i32,
    target_pos: i32,
    progress: f32,
    direction: SlideDirection,
    _screen_size: u32,
) i32 {
    _ = _start_pos;
    _ = _screen_size;
    std.debug.assert(progress >= 0.0);
    std.debug.assert(progress <= 1.0);
    const offset = switch (direction) {
        .from_top => -@as(i32, @intFromFloat((1.0 - progress) * 100.0)),
        .from_bottom => @as(i32, @intFromFloat((1.0 - progress) *
100.0)),
        .from_left => -@as(i32, @intFromFloat((1.0 - progress) * 100.0)),
        .from_right => @as(i32, @intFromFloat((1.0 - progress) * 100.0)),
    };
    return target_pos + offset;
}

// Calculate slide-out position.
pub fn calc_slide_out_position(
    _start_pos: i32,
    target_pos: i32,
    progress: f32,
    direction: SlideDirection,
    _screen_size: u32,
) i32 {
    _ = _start_pos;
    _ = _screen_size;
    std.debug.assert(progress >= 0.0);
    std.debug.assert(progress <= 1.0);
    const offset = switch (direction) {
        .from_top => -@as(i32, @intFromFloat(progress * 100.0)),
        .from_bottom => @as(i32, @intFromFloat(progress * 100.0)),
        .from_left => -@as(i32, @intFromFloat(progress * 100.0)),
        .from_right => @as(i32, @intFromFloat(progress * 100.0)),
    };
    return target_pos + offset;
}

// Start fade-in effect for window.
pub fn start_fade_in(
    anim_manager: *window_animation.AnimationManager,
    window_id: u32,
    start_time: u64,
) bool {
    std.debug.assert(window_id > 0);
    // Fade-in: opacity from 0 to 255.
    return anim_manager.start_animation(
        window_id,
        window_animation.AnimationType.opacity,
        0, // start_x (not used for fade).
        0, // start_y (not used for fade).
        0, // start_width (not used for fade).
        0, // start_height (not used for fade).
        0, // start_opacity (transparent).
        0, // target_x (not used for fade).
        0, // target_y (not used for fade).
        0, // target_width (not used for fade).
        0, // target_height (not used for fade).
        255, // target_opacity (opaque).
        start_time,
    );
}

// Start fade-out effect for window.
pub fn start_fade_out(
    anim_manager: *window_animation.AnimationManager,
    window_id: u32,
    current_opacity: u8,
    start_time: u64,
) bool {
    std.debug.assert(window_id > 0);
    // Fade-out: opacity from current to 0.
    return anim_manager.start_animation(
        window_id,
        window_animation.AnimationType.opacity,
        0, // start_x (not used for fade).
        0, // start_y (not used for fade).
        0, // start_width (not used for fade).
        0, // start_height (not used for fade).
        current_opacity, // start_opacity (current).
        0, // target_x (not used for fade).
        0, // target_y (not used for fade).
        0, // target_width (not used for fade).
        0, // target_height (not used for fade).
        0, // target_opacity (transparent).
        start_time,
    );
}

// Check if effect should be applied.
pub fn should_apply_effect(effect_type: EffectType) bool {
    return effect_type != EffectType.none;
}


// === grain_core/window_events.zig ===

//! Grain OS Window Events: Event system for window lifecycle
notifications.
//!
//! Why: Allow systems to be notified about window events (create,
destroy, focus, etc.).
//! Architecture: Event queue and callback system.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");

// Bounded: Max event queue size.
pub const MAX_EVENTS: u32 = 128;

// Bounded: Max event listeners.
pub const MAX_LISTENERS: u32 = 16;

// Event type.
pub const EventType = enum(u8) {
    none,
    window_created,
    window_destroyed,
    window_focused,
    window_unfocused,
    window_minimized,
    window_maximized,
    window_moved,
    window_resized,
    window_title_changed,
};

// Window event: represents a window event.
pub const WindowEvent = struct {
    event_type: EventType,
    window_id: u32,
    timestamp: u64,
    data_x: i32,
    data_y: i32,
    data_width: u32,
    data_height: u32,
};

// Event listener callback function.
pub const EventListenerFn = *const fn (
    event: *const WindowEvent,
    user_data: ?*anyopaque,
) void;

// Event listener: callback for window events.
pub const EventListener = struct {
    listener_fn: EventListenerFn,
    user_data: ?*anyopaque,
    active: bool,
};

// Event manager: manages window events and listeners.
pub const EventManager = struct {
    events: [MAX_EVENTS]WindowEvent,
    events_head: u32,
    events_tail: u32,
    events_count: u32,
    listeners: [MAX_LISTENERS]EventListener,
    listeners_len: u32,

    pub fn init() EventManager {
        var manager = EventManager{
            .events = undefined,
            .events_head = 0,
            .events_tail = 0,
            .events_count = 0,
            .listeners = undefined,
            .listeners_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_EVENTS) : (i += 1) {
            manager.events[i] = WindowEvent{
                .event_type = EventType.none,
                .window_id = 0,
                .timestamp = 0,
                .data_x = 0,
                .data_y = 0,
                .data_width = 0,
                .data_height = 0,
            };
        }
        i = 0;
        while (i < MAX_LISTENERS) : (i += 1) {
            manager.listeners[i] = EventListener{
                .listener_fn = undefined,
                .user_data = null,
                .active = false,
            };
        }
        return manager;
    }

    // Emit window event.
    pub fn emit_event(
        self: *EventManager,
        event_type: EventType,
        window_id: u32,
        timestamp: u64,
    ) void {
        std.debug.assert(window_id > 0);
        if (self.events_count >= MAX_EVENTS) {
            // Queue full, drop oldest event.
            self.events_head = (self.events_head + 1) % MAX_EVENTS;
            self.events_count -= 1;
        }
        const idx = self.events_tail;
        self.events[idx] = WindowEvent{
            .event_type = event_type,
            .window_id = window_id,
            .timestamp = timestamp,
            .data_x = 0,
            .data_y = 0,
            .data_width = 0,
            .data_height = 0,
        };
        self.events_tail = (self.events_tail + 1) % MAX_EVENTS;
        self.events_count += 1;
        // Notify listeners.
        self.notify_listeners(&self.events[idx]);
    }

    // Emit window event with position data.
    pub fn emit_event_with_position(
        self: *EventManager,
        event_type: EventType,
        window_id: u32,
        timestamp: u64,
        x: i32,
        y: i32,
    ) void {
        std.debug.assert(window_id > 0);
        if (self.events_count >= MAX_EVENTS) {
            self.events_head = (self.events_head + 1) % MAX_EVENTS;
            self.events_count -= 1;
        }
        const idx = self.events_tail;
        self.events[idx] = WindowEvent{
            .event_type = event_type,
            .window_id = window_id,
            .timestamp = timestamp,
            .data_x = x,
            .data_y = y,
            .data_width = 0,
            .data_height = 0,
        };
        self.events_tail = (self.events_tail + 1) % MAX_EVENTS;
        self.events_count += 1;
        self.notify_listeners(&self.events[idx]);
    }

    // Emit window event with size data.
    pub fn emit_event_with_size(
        self: *EventManager,
        event_type: EventType,
        window_id: u32,
        timestamp: u64,
        width: u32,
        height: u32,
    ) void {
        std.debug.assert(window_id > 0);
        if (self.events_count >= MAX_EVENTS) {
            self.events_head = (self.events_head + 1) % MAX_EVENTS;
            self.events_count -= 1;
        }
        const idx = self.events_tail;
        self.events[idx] = WindowEvent{
            .event_type = event_type,
            .window_id = window_id,
            .timestamp = timestamp,
            .data_x = 0,
            .data_y = 0,
            .data_width = width,
            .data_height = height,
        };
        self.events_tail = (self.events_tail + 1) % MAX_EVENTS;
        self.events_count += 1;
        self.notify_listeners(&self.events[idx]);
    }

    // Add event listener.
    pub fn add_listener(
        self: *EventManager,
        listener_fn: EventListenerFn,
        user_data: ?*anyopaque,
    ) bool {
        if (self.listeners_len >= MAX_LISTENERS) {
            return false;
        }
        self.listeners[self.listeners_len] = EventListener{
            .listener_fn = listener_fn,
            .user_data = user_data,
            .active = true,
        };
        self.listeners_len += 1;
        return true;
    }

    // Remove event listener.
    pub fn remove_listener(self: *EventManager, listener_fn:
EventListenerFn) bool {
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.listeners_len) : (i += 1) {
            if (self.listeners[i].listener_fn == listener_fn) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining listeners left.
        while (i < self.listeners_len - 1) : (i += 1) {
            self.listeners[i] = self.listeners[i + 1];
        }
        self.listeners_len -= 1;
        return true;
    }

    // Notify all listeners of event.
    fn notify_listeners(self: *EventManager, event: *const WindowEvent)
void {
        var i: u32 = 0;
        while (i < self.listeners_len) : (i += 1) {
            if (self.listeners[i].active) {
                self.listeners[i].listener_fn(event,
self.listeners[i].user_data);
            }
        }
    }

    // Get event count.
    pub fn get_event_count(self: *const EventManager) u32 {
        return self.events_count;
    }

    // Get listener count.
    pub fn get_listener_count(self: *const EventManager) u32 {
        return self.listeners_len;
    }

    // Clear all events.
    pub fn clear_events(self: *EventManager) void {
        self.events_head = 0;
        self.events_tail = 0;
        self.events_count = 0;
    }
};


// === grain_core/window_focus.zig ===

//! Grain OS Window Focus Management: Focus policies and tracking.
//!
//! Why: Provide flexible focus management with policies and history.
//! Architecture: Focus policy management and focus history tracking.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");

// Bounded: Max focus history entries.
pub const MAX_FOCUS_HISTORY: u32 = 64;

// Focus policy type.
pub const FocusPolicy = enum(u8) {
    click_to_focus, // Focus on click only.
    focus_follows_mouse, // Focus follows mouse movement.
    sloppy_focus, // Focus on mouse enter, unfocus on mouse leave.
};

// Focus history entry.
pub const FocusHistoryEntry = struct {
    window_id: u32,
    timestamp: u64, // Focus time in milliseconds.
};

// Focus manager: manages focus policies and history.
pub const FocusManager = struct {
    policy: FocusPolicy,
    focus_history: [MAX_FOCUS_HISTORY]FocusHistoryEntry,
    focus_history_len: u32,
    last_focus_time: u64,

    pub fn init() FocusManager {
        var manager = FocusManager{
            .policy = FocusPolicy.click_to_focus,
            .focus_history = undefined,
            .focus_history_len = 0,
            .last_focus_time = 0,
        };
        var i: u32 = 0;
        while (i < MAX_FOCUS_HISTORY) : (i += 1) {
            manager.focus_history[i] = FocusHistoryEntry{
                .window_id = 0,
                .timestamp = 0,
            };
        }
        return manager;
    }

    // Set focus policy.
    pub fn set_policy(self: *FocusManager, policy: FocusPolicy) void {
        self.policy = policy;
    }

    // Get focus policy.
    pub fn get_policy(self: *const FocusManager) FocusPolicy {
        return self.policy;
    }

    // Add focus to history.
    pub fn add_focus_history(
        self: *FocusManager,
        window_id: u32,
        timestamp: u64,
    ) void {
        std.debug.assert(window_id > 0);
        if (self.focus_history_len >= MAX_FOCUS_HISTORY) {
            // Shift history left (remove oldest).
            var i: u32 = 0;
            while (i < MAX_FOCUS_HISTORY - 1) : (i += 1) {
                self.focus_history[i] = self.focus_history[i + 1];
            }
            self.focus_history_len = MAX_FOCUS_HISTORY - 1;
        }
        self.focus_history[self.focus_history_len] = FocusHistoryEntry{
            .window_id = window_id,
            .timestamp = timestamp,
        };
        self.focus_history_len += 1;
        self.last_focus_time = timestamp;
    }

    // Get previous focused window.
    pub fn get_previous_focus(self: *const FocusManager) ?u32 {
        if (self.focus_history_len < 2) {
            return null;
        }
        // Return second-to-last entry (previous focus).
        return self.focus_history[self.focus_history_len - 2].window_id;
    }

    // Get focus history count.
    pub fn get_history_count(self: *const FocusManager) u32 {
        return self.focus_history_len;
    }

    // Clear focus history.
    pub fn clear_history(self: *FocusManager) void {
        self.focus_history_len = 0;
    }

    // Check if should focus on mouse move (focus-follows-mouse).
    pub fn should_focus_on_mouse_move(self: *const FocusManager) bool {
        return (self.policy == FocusPolicy.focus_follows_mouse or
            self.policy == FocusPolicy.sloppy_focus);
    }

    // Check if should unfocus on mouse leave (sloppy-focus).
    pub fn should_unfocus_on_mouse_leave(self: *const FocusManager) bool
{
        return self.policy == FocusPolicy.sloppy_focus;
    }
};


// === grain_core/window_grouping.zig ===

//! Grain OS Window Grouping: Group windows together for unified
management.
//!
//! Why: Allow windows to be grouped and managed as a unit.
//! Architecture: Window group management and operations.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");

// Bounded: Max groups.
pub const MAX_GROUPS: u32 = 64;

// Bounded: Max windows per group.
pub const MAX_GROUP_WINDOWS: u32 = 16;

// Window group: collection of windows managed together.
pub const WindowGroup = struct {
    group_id: u32,
    window_ids: [MAX_GROUP_WINDOWS]u32,
    window_ids_len: u32,
    name: [compositor.MAX_TITLE_LEN]u8,
    name_len: u32,

    pub fn init(group_id: u32) WindowGroup {
        var group = WindowGroup{
            .group_id = group_id,
            .window_ids = undefined,
            .window_ids_len = 0,
            .name = undefined,
            .name_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_GROUP_WINDOWS) : (i += 1) {
            group.window_ids[i] = 0;
        }
        var j: u32 = 0;
        while (j < compositor.MAX_TITLE_LEN) : (j += 1) {
            group.name[j] = 0;
        }
        return group;
    }

    // Add window to group.
    pub fn add_window(self: *WindowGroup, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        if (self.window_ids_len >= MAX_GROUP_WINDOWS) {
            return false;
        }
        // Check if window already in group.
        var i: u32 = 0;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                return true; // Already in group.
            }
        }
        self.window_ids[self.window_ids_len] = window_id;
        self.window_ids_len += 1;
        return true;
    }

    // Remove window from group.
    pub fn remove_window(self: *WindowGroup, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining windows left.
        while (i < self.window_ids_len - 1) : (i += 1) {
            self.window_ids[i] = self.window_ids[i + 1];
        }
        self.window_ids_len -= 1;
        return true;
    }

    // Check if window is in group.
    pub fn has_window(self: *const WindowGroup, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                return true;
            }
        }
        return false;
    }

    // Get window count in group.
    pub fn get_window_count(self: *const WindowGroup) u32 {
        return self.window_ids_len;
    }

    // Set group name.
    pub fn set_name(self: *WindowGroup, name: []const u8) void {
        std.debug.assert(name.len <= compositor.MAX_TITLE_LEN);
        const copy_len = @min(name.len, compositor.MAX_TITLE_LEN);
        var i: u32 = 0;
        while (i < compositor.MAX_TITLE_LEN) : (i += 1) {
            self.name[i] = 0;
        }
        i = 0;
        while (i < copy_len) : (i += 1) {
            self.name[i] = name[i];
        }
        self.name_len = @intCast(copy_len);
    }
};

// Window group manager: manages window groups.
pub const WindowGroupManager = struct {
    groups: [MAX_GROUPS]WindowGroup,
    groups_len: u32,
    next_group_id: u32,

    pub fn init() WindowGroupManager {
        var manager = WindowGroupManager{
            .groups = undefined,
            .groups_len = 0,
            .next_group_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_GROUPS) : (i += 1) {
            manager.groups[i] = WindowGroup.init(0);
        }
        return manager;
    }

    // Create new group.
    pub fn create_group(self: *WindowGroupManager) ?u32 {
        if (self.groups_len >= MAX_GROUPS) {
            return null;
        }
        const group_id = self.next_group_id;
        self.next_group_id += 1;
        self.groups[self.groups_len] = WindowGroup.init(group_id);
        self.groups_len += 1;
        return group_id;
    }

    // Get group by ID.
    pub fn get_group(self: *WindowGroupManager, group_id: u32)
?*WindowGroup {
        std.debug.assert(group_id > 0);
        var i: u32 = 0;
        while (i < self.groups_len) : (i += 1) {
            if (self.groups[i].group_id == group_id) {
                return &self.groups[i];
            }
        }
        return null;
    }

    // Find group containing window.
    pub fn find_group_for_window(
        self: *WindowGroupManager,
        window_id: u32,
    ) ?u32 {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        while (i < self.groups_len) : (i += 1) {
            if (self.groups[i].has_window(window_id)) {
                return self.groups[i].group_id;
            }
        }
        return null;
    }

    // Add window to group.
    pub fn add_window_to_group(
        self: *WindowGroupManager,
        window_id: u32,
        group_id: u32,
    ) bool {
        std.debug.assert(window_id > 0);
        std.debug.assert(group_id > 0);
        if (self.get_group(group_id)) |group| {
            return group.add_window(window_id);
        }
        return false;
    }

    // Remove window from group.
    pub fn remove_window_from_group(
        self: *WindowGroupManager,
        window_id: u32,
        group_id: u32,
    ) bool {
        std.debug.assert(window_id > 0);
        std.debug.assert(group_id > 0);
        if (self.get_group(group_id)) |group| {
            return group.remove_window(window_id);
        }
        return false;
    }

    // Remove window from all groups.
    pub fn remove_window_from_all_groups(
        self: *WindowGroupManager,
        window_id: u32,
    ) void {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        while (i < self.groups_len) : (i += 1) {
            _ = self.groups[i].remove_window(window_id);
        }
    }

    // Delete group.
    pub fn delete_group(self: *WindowGroupManager, group_id: u32) bool {
        std.debug.assert(group_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.groups_len) : (i += 1) {
            if (self.groups[i].group_id == group_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining groups left.
        while (i < self.groups_len - 1) : (i += 1) {
            self.groups[i] = self.groups[i + 1];
        }
        self.groups_len -= 1;
        return true;
    }

    // Get group count.
    pub fn get_group_count(self: *const WindowGroupManager) u32 {
        return self.groups_len;
    }
};


// === grain_core/window_opacity.zig ===

//! Grain OS Window Opacity: Transparency and opacity management.
//!
//! Why: Provide window transparency for visual effects.
//! Architecture: Opacity value management and alpha blending.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Opacity value range (0.0 to 1.0, stored as u8: 0-255).
pub const OPACITY_MIN: u8 = 0; // Fully transparent.
pub const OPACITY_MAX: u8 = 255; // Fully opaque.
pub const OPACITY_DEFAULT: u8 = 255; // Fully opaque by default.

// Opacity value: 0 = transparent, 255 = opaque.
pub const Opacity = u8;

// Apply opacity to color (alpha blending).
pub fn apply_opacity_to_color(color: u32, opacity: Opacity) u32 {
    const r = (color >> 16) & 0xFF;
    const g = (color >> 8) & 0xFF;
    const b = color & 0xFF;
    const alpha: u32 = opacity;
    return (alpha << 24) | (@as(u32, r) << 16) | (@as(u32, g) << 8) | b;
}

// Blend two colors with opacity.
pub fn blend_colors(
    foreground: u32,
    background: u32,
    opacity: Opacity,
) u32 {
    const fg_r = (foreground >> 16) & 0xFF;
    const fg_g = (foreground >> 8) & 0xFF;
    const fg_b = foreground & 0xFF;
    const bg_r = (background >> 16) & 0xFF;
    const bg_g = (background >> 8) & 0xFF;
    const bg_b = background & 0xFF;
    // Simple alpha blending: result = fg * opacity + bg * (1 - opacity).
    const opacity_f: f32 = @as(f32, @floatFromInt(opacity)) / 255.0;
    const inv_opacity_f: f32 = 1.0 - opacity_f;
    const r = @as(u8, @intFromFloat(@as(f32, @floatFromInt(fg_r)) *
opacity_f +
        @as(f32, @floatFromInt(bg_r)) * inv_opacity_f));
    const g = @as(u8, @intFromFloat(@as(f32, @floatFromInt(fg_g)) *
opacity_f +
        @as(f32, @floatFromInt(bg_g)) * inv_opacity_f));
    const b = @as(u8, @intFromFloat(@as(f32, @floatFromInt(fg_b)) *
opacity_f +
        @as(f32, @floatFromInt(bg_b)) * inv_opacity_f));
    return (255 << 24) | (@as(u32, r) << 16) | (@as(u32, g) << 8) | b;
}

// Clamp opacity value to valid range.
pub fn clamp_opacity(opacity: Opacity) Opacity {
    if (opacity > OPACITY_MAX) {
        return OPACITY_MAX;
    }
    return opacity;
}

// Check if window is fully opaque.
pub fn is_fully_opaque(opacity: Opacity) bool {
    return opacity == OPACITY_MAX;
}

// Check if window is fully transparent.
pub fn is_fully_transparent(opacity: Opacity) bool {
    return opacity == OPACITY_MIN;
}


// === grain_core/window_preview.zig ===

//! Grain OS Window Preview: Thumbnail generation for windows.
//!
//! Why: Provide visual previews of windows for switching and taskbar.
//! Architecture: Window thumbnail generation and caching.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");
const framebuffer_renderer = @import("framebuffer_renderer.zig");

// Bounded: Max preview cache size.
pub const MAX_PREVIEW_CACHE: u32 = 256;

// Bounded: Preview thumbnail dimensions.
pub const PREVIEW_WIDTH: u32 = 160;
pub const PREVIEW_HEIGHT: u32 = 90;

// Preview entry: cached window thumbnail.
pub const WindowPreview = struct {
    window_id: u32,
    width: u32,
    height: u32,
    pixels: [PREVIEW_WIDTH * PREVIEW_HEIGHT]u32,
    valid: bool,
    timestamp: u64, // Last update timestamp.

    pub fn init(window_id: u32) WindowPreview {
        std.debug.assert(window_id > 0);
        var preview = WindowPreview{
            .window_id = window_id,
            .width = PREVIEW_WIDTH,
            .height = PREVIEW_HEIGHT,
            .pixels = undefined,
            .valid = false,
            .timestamp = 0,
        };
        var i: u32 = 0;
        while (i < PREVIEW_WIDTH * PREVIEW_HEIGHT) : (i += 1) {
            preview.pixels[i] = 0;
        }
        return preview;
    }

    // Clear preview (mark invalid).
    pub fn clear(self: *WindowPreview) void {
        self.valid = false;
        self.timestamp = 0;
    }
};

// Preview manager: manages window preview cache.
pub const PreviewManager = struct {
    previews: [MAX_PREVIEW_CACHE]WindowPreview,
    previews_len: u32,

    pub fn init() PreviewManager {
        var manager = PreviewManager{
            .previews = undefined,
            .previews_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_PREVIEW_CACHE) : (i += 1) {
            manager.previews[i] = WindowPreview.init(0);
        }
        return manager;
    }

    // Get or create preview for window.
    pub fn get_preview(
        self: *PreviewManager,
        window_id: u32,
    ) ?*WindowPreview {
        std.debug.assert(window_id > 0);
        // Find existing preview.
        var i: u32 = 0;
        while (i < self.previews_len) : (i += 1) {
            if (self.previews[i].window_id == window_id) {
                return &self.previews[i];
            }
        }
        // Create new preview if space available.
        if (self.previews_len >= MAX_PREVIEW_CACHE) {
            return null;
        }
        self.previews[self.previews_len] = WindowPreview.init(window_id);
        self.previews_len += 1;
        return &self.previews[self.previews_len - 1];
    }

    // Remove preview for window.
    pub fn remove_preview(self: *PreviewManager, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.previews_len) : (i += 1) {
            if (self.previews[i].window_id == window_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining previews left.
        while (i < self.previews_len - 1) : (i += 1) {
            self.previews[i] = self.previews[i + 1];
        }
        self.previews_len -= 1;
        return true;
    }

    // Clear all previews.
    pub fn clear_all(self: *PreviewManager) void {
        var i: u32 = 0;
        while (i < self.previews_len) : (i += 1) {
            self.previews[i].clear();
        }
        self.previews_len = 0;
    }

    // Generate preview from window (downscaled thumbnail).
    pub fn generate_preview(
        self: *PreviewManager,
        window_id: u32,
        _win_x: i32,
        _win_y: i32,
        _win_width: u32,
        _win_height: u32,
        _screen_width: u32,
        _screen_height: u32,
    ) bool {
        std.debug.assert(window_id > 0);
        // Discard unused parameters (for future framebuffer sampling).
        _ = _win_x;
        _ = _win_y;
        _ = _win_width;
        _ = _win_height;
        _ = _screen_width;
        _ = _screen_height;
        if (self.get_preview(window_id)) |preview| {
            // Generate downscaled preview (simplified: solid color for
now).
            // In full implementation, would sample from framebuffer.
            const bg_color: u32 = 0xFFCCCCCC; // Light gray.
            var y: u32 = 0;
            while (y < PREVIEW_HEIGHT) : (y += 1) {
                var x: u32 = 0;
                while (x < PREVIEW_WIDTH) : (x += 1) {
                    const idx = y * PREVIEW_WIDTH + x;
                    preview.pixels[idx] = bg_color;
                }
            }
            preview.valid = true;
            preview.timestamp = 0; // Would use actual timestamp in full
impl.
            return true;
        }
        return false;
    }

    // Get preview count.
    pub fn get_count(self: *const PreviewManager) u32 {
        return self.previews_len;
    }
};


// === grain_core/window_rules.zig ===

//! Grain OS Window Rules: Automatic window configuration based on
properties.
//!
//! Why: Allow windows to be automatically configured based on title,
class, etc.
//! Architecture: Rule matching and application system.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");
const window_constraints = @import("window_constraints.zig");

// Bounded: Max window rules.
pub const MAX_RULES: u32 = 64;

// Bounded: Max rule pattern length.
pub const MAX_PATTERN_LEN: u32 = 256;

// Rule match type.
pub const MatchType = enum(u8) {
    title,
    class,
    instance,
};

// Rule action type.
pub const ActionType = enum(u8) {
    none,
    set_position,
    set_size,
    set_workspace,
    set_opacity,
    set_constraints,
    set_floating,
    set_tiled,
};

// Window rule: matches windows and applies actions.
pub const WindowRule = struct {
    rule_id: u32,
    match_type: MatchType,
    pattern: [MAX_PATTERN_LEN]u8,
    pattern_len: u32,
    action_type: ActionType,
    action_value_x: i32,
    action_value_y: i32,
    action_value_width: u32,
    action_value_height: u32,
    action_value_u32: u32,
    action_value_u8: u8,
    active: bool,
};

// Window rule manager: manages window rules.
pub const WindowRuleManager = struct {
    rules: [MAX_RULES]WindowRule,
    rules_len: u32,
    next_rule_id: u32,

    pub fn init() WindowRuleManager {
        var manager = WindowRuleManager{
            .rules = undefined,
            .rules_len = 0,
            .next_rule_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_RULES) : (i += 1) {
            manager.rules[i] = WindowRule{
                .rule_id = 0,
                .match_type = MatchType.title,
                .pattern = undefined,
                .pattern_len = 0,
                .action_type = ActionType.none,
                .action_value_x = 0,
                .action_value_y = 0,
                .action_value_width = 0,
                .action_value_height = 0,
                .action_value_u32 = 0,
                .action_value_u8 = 0,
                .active = false,
            };
            var j: u32 = 0;
            while (j < MAX_PATTERN_LEN) : (j += 1) {
                manager.rules[i].pattern[j] = 0;
            }
        }
        return manager;
    }

    // Add window rule.
    pub fn add_rule(
        self: *WindowRuleManager,
        match_type: MatchType,
        pattern: []const u8,
        action_type: ActionType,
    ) ?u32 {
        if (self.rules_len >= MAX_RULES) {
            return null;
        }
        if (pattern.len > MAX_PATTERN_LEN) {
            return null;
        }
        const rule_id = self.next_rule_id;
        self.next_rule_id += 1;
        var rule = WindowRule{
            .rule_id = rule_id,
            .match_type = match_type,
            .pattern = undefined,
            .pattern_len = 0,
            .action_type = action_type,
            .action_value_x = 0,
            .action_value_y = 0,
            .action_value_width = 0,
            .action_value_height = 0,
            .action_value_u32 = 0,
            .action_value_u8 = 0,
            .active = true,
        };
        var i: u32 = 0;
        while (i < MAX_PATTERN_LEN) : (i += 1) {
            rule.pattern[i] = 0;
        }
        const copy_len = @min(pattern.len, MAX_PATTERN_LEN);
        i = 0;
        while (i < copy_len) : (i += 1) {
            rule.pattern[i] = pattern[i];
        }
        rule.pattern_len = @intCast(copy_len);
        self.rules[self.rules_len] = rule;
        self.rules_len += 1;
        return rule_id;
    }

    // Match window against rules.
    pub fn match_window(
        self: *const WindowRuleManager,
        window_title: []const u8,
    ) ?*const WindowRule {
        var i: u32 = 0;
        while (i < self.rules_len) : (i += 1) {
            const rule = &self.rules[i];
            if (!rule.active) {
                continue;
            }
            if (rule.match_type == MatchType.title) {
                if (self.match_pattern(window_title,
rule.pattern[0..rule.pattern_len])) {
                    return rule;
                }
            }
        }
        return null;
    }

    // Match pattern against text (simple substring match).
    fn match_pattern(
        _self: *const WindowRuleManager,
        text: []const u8,
        pattern: []const u8,
    ) bool {
        _ = _self;
        if (pattern.len == 0) {
            return false;
        }
        if (pattern.len > text.len) {
            return false;
        }
        var i: u32 = 0;
        while (i <= text.len - pattern.len) : (i += 1) {
            var match: bool = true;
            var j: u32 = 0;
            while (j < pattern.len) : (j += 1) {
                if (text[i + j] != pattern[j]) {
                    match = false;
                    break;
                }
            }
            if (match) {
                return true;
            }
        }
        return false;
    }

    // Remove window rule.
    pub fn remove_rule(self: *WindowRuleManager, rule_id: u32) bool {
        std.debug.assert(rule_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.rules_len) : (i += 1) {
            if (self.rules[i].rule_id == rule_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining rules left.
        while (i < self.rules_len - 1) : (i += 1) {
            self.rules[i] = self.rules[i + 1];
        }
        self.rules_len -= 1;
        return true;
    }

    // Clear all rules.
    pub fn clear_all(self: *WindowRuleManager) void {
        self.rules_len = 0;
    }

    // Get rule count.
    pub fn get_rule_count(self: *const WindowRuleManager) u32 {
        return self.rules_len;
    }
};


// === grain_core/window_session.zig ===

//! Grain OS Window Session: Save and restore named window layouts.
//!
//! Why: Allow users to save and restore entire window layouts as
sessions.
//! Architecture: Session management with named layouts.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");
const window_state = @import("window_state.zig");

// Bounded: Max sessions.
pub const MAX_SESSIONS: u32 = 32;

// Bounded: Max session name length.
pub const MAX_SESSION_NAME_LEN: u32 = 64;

// Window session: named collection of window states.
pub const WindowSession = struct {
    session_id: u32,
    name: [MAX_SESSION_NAME_LEN]u8,
    name_len: u32,
    state_manager: window_state.WindowStateManager,
    timestamp: u64,
    active: bool,

    pub fn init(session_id: u32, name: []const u8) WindowSession {
        std.debug.assert(session_id > 0);
        std.debug.assert(name.len <= MAX_SESSION_NAME_LEN);
        var session = WindowSession{
            .session_id = session_id,
            .name = undefined,
            .name_len = 0,
            .state_manager = window_state.WindowStateManager.init(),
            .timestamp = 0,
            .active = true,
        };
        var i: u32 = 0;
        while (i < MAX_SESSION_NAME_LEN) : (i += 1) {
            session.name[i] = 0;
        }
        const copy_len = @min(name.len, MAX_SESSION_NAME_LEN);
        i = 0;
        while (i < copy_len) : (i += 1) {
            session.name[i] = name[i];
        }
        session.name_len = @intCast(copy_len);
        return session;
    }
};

// Session manager: manages window sessions.
pub const SessionManager = struct {
    sessions: [MAX_SESSIONS]WindowSession,
    sessions_len: u32,
    next_session_id: u32,

    pub fn init() SessionManager {
        var manager = SessionManager{
            .sessions = undefined,
            .sessions_len = 0,
            .next_session_id = 1,
        };
        var i: u32 = 0;
        while (i < MAX_SESSIONS) : (i += 1) {
            manager.sessions[i] = WindowSession{
                .session_id = 0,
                .name = undefined,
                .name_len = 0,
                .state_manager = window_state.WindowStateManager.init(),
                .timestamp = 0,
                .active = false,
            };
            var j: u32 = 0;
            while (j < MAX_SESSION_NAME_LEN) : (j += 1) {
                manager.sessions[i].name[j] = 0;
            }
        }
        return manager;
    }

    // Create new session.
    pub fn create_session(
        self: *SessionManager,
        name: []const u8,
    ) ?u32 {
        if (self.sessions_len >= MAX_SESSIONS) {
            return null;
        }
        if (name.len > MAX_SESSION_NAME_LEN) {
            return null;
        }
        const session_id = self.next_session_id;
        self.next_session_id += 1;
        self.sessions[self.sessions_len] =
WindowSession.init(session_id, name);
        self.sessions_len += 1;
        return session_id;
    }

    // Find session by ID.
    pub fn find_session(
        self: *SessionManager,
        session_id: u32,
    ) ?*WindowSession {
        std.debug.assert(session_id > 0);
        var i: u32 = 0;
        while (i < self.sessions_len) : (i += 1) {
            if (self.sessions[i].session_id == session_id and
self.sessions[i].active) {
                return &self.sessions[i];
            }
        }
        return null;
    }

    // Find session by name.
    pub fn find_session_by_name(
        self: *SessionManager,
        name: []const u8,
    ) ?*WindowSession {
        var i: u32 = 0;
        while (i < self.sessions_len) : (i += 1) {
            const session = &self.sessions[i];
            if (!session.active) {
                continue;
            }
            if (session.name_len == name.len) {
                var match: bool = true;
                var j: u32 = 0;
                while (j < session.name_len) : (j += 1) {
                    if (session.name[j] != name[j]) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    return session;
                }
            }
        }
        return null;
    }

    // Delete session.
    pub fn delete_session(self: *SessionManager, session_id: u32) bool {
        std.debug.assert(session_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.sessions_len) : (i += 1) {
            if (self.sessions[i].session_id == session_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining sessions left.
        while (i < self.sessions_len - 1) : (i += 1) {
            self.sessions[i] = self.sessions[i + 1];
        }
        self.sessions_len -= 1;
        return true;
    }

    // Get session count.
    pub fn get_session_count(self: *const SessionManager) u32 {
        return self.sessions_len;
    }

    // Clear all sessions.
    pub fn clear_all(self: *SessionManager) void {
        self.sessions_len = 0;
    }
};


// === grain_core/window_snapping.zig ===

//! Grain OS Window Snapping: Snap windows to edges and corners.
//!
//! Why: Provide automatic window snapping when dragging near edges.
//! Architecture: Snap detection and position calculation.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");

// Bounded: Snap threshold in pixels.
pub const SNAP_THRESHOLD: u32 = 20;

// Snap zone: which edge/corner to snap to.
pub const SnapZone = enum(u8) {
    none,
    left,
    right,
    top,
    bottom,
    top_left,
    top_right,
    bottom_left,
    bottom_right,
    center,
};

// Window snap state: tracks if window is snapped.
pub const SnapState = struct {
    snapped: bool,
    zone: SnapZone,
};

// Check if window should snap to left edge.
fn should_snap_left(win_x: i32, threshold: u32) bool {
    return win_x >= 0 and win_x <= @as(i32, @intCast(threshold));
}

// Check if window should snap to right edge.
fn should_snap_right(win_x: i32, win_width: u32, screen_width: u32,
threshold: u32) bool {
    const right_edge = win_x + @as(i32, @intCast(win_width));
    const screen_right = @as(i32, @intCast(screen_width));
    return right_edge >= screen_right - @as(i32, @intCast(threshold)) and
        right_edge <= screen_right;
}

// Check if window should snap to top edge.
fn should_snap_top(win_y: i32, threshold: u32, title_bar_height: u32)
bool {
    const top_y = @as(i32, @intCast(compositor.BORDER_WIDTH +
title_bar_height));
    return win_y >= top_y - @as(i32, @intCast(threshold)) and
        win_y <= top_y + @as(i32, @intCast(threshold));
}

// Check if window should snap to bottom edge.
fn should_snap_bottom(win_y: i32, win_height: u32, screen_height: u32,
threshold: u32, status_bar_height: u32) bool {
    const bottom_edge = win_y + @as(i32, @intCast(win_height));
    const screen_bottom = @as(i32, @intCast(screen_height -
status_bar_height));
    return bottom_edge >= screen_bottom - @as(i32, @intCast(threshold))
and
        bottom_edge <= screen_bottom;
}

// Detect snap zone for window position.
pub fn detect_snap_zone(
    win_x: i32,
    win_y: i32,
    win_width: u32,
    win_height: u32,
    screen_width: u32,
    screen_height: u32,
    threshold: u32,
) SnapZone {
    std.debug.assert(win_width > 0);
    std.debug.assert(win_height > 0);
    std.debug.assert(screen_width > 0);
    std.debug.assert(screen_height > 0);
    const title_bar_height = compositor.TITLE_BAR_HEIGHT;
    const status_bar_height = @as(u32, 24); // Desktop shell status bar
height.
    const snap_left = should_snap_left(win_x, threshold);
    const snap_right = should_snap_right(win_x, win_width, screen_width,
threshold);
    const snap_top = should_snap_top(win_y, threshold, title_bar_height);
    const snap_bottom = should_snap_bottom(win_y, win_height,
screen_height, threshold, status_bar_height);
    // Check corners first.
    if (snap_left and snap_top) {
        return SnapZone.top_left;
    }
    if (snap_right and snap_top) {
        return SnapZone.top_right;
    }
    if (snap_left and snap_bottom) {
        return SnapZone.bottom_left;
    }
    if (snap_right and snap_bottom) {
        return SnapZone.bottom_right;
    }
    // Check edges.
    if (snap_left) {
        return SnapZone.left;
    }
    if (snap_right) {
        return SnapZone.right;
    }
    if (snap_top) {
        return SnapZone.top;
    }
    if (snap_bottom) {
        return SnapZone.bottom;
    }
    return SnapZone.none;
}

// Calculate snapped position for left edge.
fn calc_snap_left(screen_width: u32, content_height: u32) struct { x:
i32, y: i32, width: u32, height: u32 } {
    const border_width = compositor.BORDER_WIDTH;
    const title_bar_height = compositor.TITLE_BAR_HEIGHT;
    return .{
        .x = @as(i32, @intCast(border_width)),
        .y = @as(i32, @intCast(border_width + title_bar_height)),
        .width = screen_width / 2,
        .height = content_height,
    };
}

// Calculate snapped position for right edge.
fn calc_snap_right(screen_width: u32, content_height: u32) struct { x:
i32, y: i32, width: u32, height: u32 } {
    const border_width = compositor.BORDER_WIDTH;
    const title_bar_height = compositor.TITLE_BAR_HEIGHT;
    return .{
        .x = @as(i32, @intCast(screen_width / 2)),
        .y = @as(i32, @intCast(border_width + title_bar_height)),
        .width = screen_width / 2,
        .height = content_height,
    };
}

// Calculate snapped position for top edge.
fn calc_snap_top(screen_width: u32, content_height: u32) struct { x:
i32, y: i32, width: u32, height: u32 } {
    const border_width = compositor.BORDER_WIDTH;
    const title_bar_height = compositor.TITLE_BAR_HEIGHT;
    return .{
        .x = @as(i32, @intCast(border_width)),
        .y = @as(i32, @intCast(border_width + title_bar_height)),
        .width = screen_width - (border_width * 2),
        .height = content_height / 2,
    };
}

// Calculate snapped position for bottom edge.
fn calc_snap_bottom(screen_width: u32, content_height: u32) struct { x:
i32, y: i32, width: u32, height: u32 } {
    const border_width = compositor.BORDER_WIDTH;
    const title_bar_height = compositor.TITLE_BAR_HEIGHT;
    return .{
        .x = @as(i32, @intCast(border_width)),
        .y = @as(i32, @intCast(border_width + title_bar_height +
content_height / 2)),
        .width = screen_width - (border_width * 2),
        .height = content_height / 2,
    };
}

// Calculate snapped position for corner zones.
fn calc_snap_corner(zone: SnapZone, screen_width: u32, content_height:
u32) struct { x: i32, y: i32, width: u32, height: u32 } {
    const border_width = compositor.BORDER_WIDTH;
    const title_bar_height = compositor.TITLE_BAR_HEIGHT;
    const half_width = screen_width / 2;
    const half_height = content_height / 2;
    switch (zone) {
        .top_left => {
            return .{
                .x = @as(i32, @intCast(border_width)),
                .y = @as(i32, @intCast(border_width + title_bar_height)),
                .width = half_width,
                .height = half_height,
            };
        },
        .top_right => {
            return .{
                .x = @as(i32, @intCast(half_width)),
                .y = @as(i32, @intCast(border_width + title_bar_height)),
                .width = half_width,
                .height = half_height,
            };
        },
        .bottom_left => {
            return .{
                .x = @as(i32, @intCast(border_width)),
                .y = @as(i32, @intCast(border_width + title_bar_height +
half_height)),
                .width = half_width,
                .height = half_height,
            };
        },
        .bottom_right => {
            return .{
                .x = @as(i32, @intCast(half_width)),
                .y = @as(i32, @intCast(border_width + title_bar_height +
half_height)),
                .width = half_width,
                .height = half_height,
            };
        },
        else => unreachable,
    }
}

// Calculate snapped position for window.
pub fn calculate_snap_position(
    zone: SnapZone,
    win_width: u32,
    win_height: u32,
    screen_width: u32,
    screen_height: u32,
) struct { x: i32, y: i32, width: u32, height: u32 } {
    std.debug.assert(win_width > 0);
    std.debug.assert(win_height > 0);
    std.debug.assert(screen_width > 0);
    std.debug.assert(screen_height > 0);
    const border_width = compositor.BORDER_WIDTH;
    const title_bar_height = compositor.TITLE_BAR_HEIGHT;
    const status_bar_height: u32 = 24;
    const content_height = screen_height - (border_width * 2) -
title_bar_height - status_bar_height;
    switch (zone) {
        .left => return calc_snap_left(screen_width, content_height),
        .right => return calc_snap_right(screen_width, content_height),
        .top => return calc_snap_top(screen_width, content_height),
        .bottom => return calc_snap_bottom(screen_width, content_height),
        .top_left, .top_right, .bottom_left, .bottom_right => {
            return calc_snap_corner(zone, screen_width, content_height);
        },
        .center, .none => {
            return .{
                .x = 0,
                .y = @as(i32, @intCast(border_width + title_bar_height)),
                .width = win_width,
                .height = win_height,
            };
        },
    }
}

// Apply snap to window position if within threshold.
pub fn apply_snap(
    win_x: *i32,
    win_y: *i32,
    win_width: *u32,
    win_height: *u32,
    screen_width: u32,
    screen_height: u32,
    threshold: u32,
) SnapState {
    std.debug.assert(win_width.* > 0);
    std.debug.assert(win_height.* > 0);
    const zone = detect_snap_zone(win_x.*, win_y.*, win_width.*,
win_height.*, screen_width, screen_height, threshold);
    if (zone != .none) {
        const snapped = calculate_snap_position(zone, win_width.*,
win_height.*, screen_width, screen_height);
        win_x.* = snapped.x;
        win_y.* = snapped.y;
        win_width.* = snapped.width;
        win_height.* = snapped.height;
        return SnapState{ .snapped = true, .zone = zone };
    }
    return SnapState{ .snapped = false, .zone = .none };
}


// === grain_core/window_stacking.zig ===

//! Grain OS Window Stacking: Z-order management for window layering.
//!
//! Why: Manage window stacking order for proper visual layering.
//! Architecture: Z-order list management and window raising/lowering.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max windows in stack.
pub const MAX_STACK_WINDOWS: u32 = 256;

// Window stack: maintains z-order of windows (bottom to top).
pub const WindowStack = struct {
    window_ids: [MAX_STACK_WINDOWS]u32,
    window_ids_len: u32,

    pub fn init() WindowStack {
        var stack = WindowStack{
            .window_ids = undefined,
            .window_ids_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_STACK_WINDOWS) : (i += 1) {
            stack.window_ids[i] = 0;
        }
        return stack;
    }

    // Add window to stack (at top).
    pub fn add_window(self: *WindowStack, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        if (self.window_ids_len >= MAX_STACK_WINDOWS) {
            return false;
        }
        // Check if window already exists.
        var i: u32 = 0;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                // Already in stack, raise to top.
                _ = self.raise_to_top(window_id);
                return true;
            }
        }
        // Add to top.
        self.window_ids[self.window_ids_len] = window_id;
        self.window_ids_len += 1;
        return true;
    }

    // Remove window from stack.
    pub fn remove_window(self: *WindowStack, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining windows left.
        while (i < self.window_ids_len - 1) : (i += 1) {
            self.window_ids[i] = self.window_ids[i + 1];
        }
        self.window_ids_len -= 1;
        return true;
    }

    // Raise window to top of stack.
    pub fn raise_to_top(self: *WindowStack, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Move to end (top of stack).
        while (i < self.window_ids_len - 1) : (i += 1) {
            self.window_ids[i] = self.window_ids[i + 1];
        }
        self.window_ids[self.window_ids_len - 1] = window_id;
        return true;
    }

    // Lower window to bottom of stack.
    pub fn lower_to_bottom(self: *WindowStack, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Move to beginning (bottom of stack).
        while (i > 0) : (i -= 1) {
            self.window_ids[i] = self.window_ids[i - 1];
        }
        self.window_ids[0] = window_id;
        return true;
    }

    // Get window at index (0 = bottom, len-1 = top).
    pub fn get_window_at(self: *const WindowStack, index: u32) ?u32 {
        if (index >= self.window_ids_len) {
            return null;
        }
        return self.window_ids[index];
    }

    // Get top window.
    pub fn get_top_window(self: *const WindowStack) ?u32 {
        if (self.window_ids_len == 0) {
            return null;
        }
        return self.window_ids[self.window_ids_len - 1];
    }

    // Get bottom window.
    pub fn get_bottom_window(self: *const WindowStack) ?u32 {
        if (self.window_ids_len == 0) {
            return null;
        }
        return self.window_ids[0];
    }

    // Get stack count.
    pub fn get_count(self: *const WindowStack) u32 {
        return self.window_ids_len;
    }

    // Clear stack.
    pub fn clear(self: *WindowStack) void {
        self.window_ids_len = 0;
    }
};


// === grain_core/window_state.zig ===

//! Grain OS Window State: Save and restore window configurations.
//!
//! Why: Persist window positions, sizes, and states across sessions.
//! Architecture: Window state serialization and restoration.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");

// Bounded: Max windows in state.
pub const MAX_STATE_WINDOWS: u32 = 256;

// Bounded: Max state name length.
pub const MAX_STATE_NAME_LEN: u32 = 64;

// Window state entry: saved window configuration.
pub const WindowStateEntry = struct {
    window_id: u32,
    x: i32,
    y: i32,
    width: u32,
    height: u32,
    minimized: bool,
    maximized: bool,
    workspace_id: u32,
    title: [compositor.MAX_TITLE_LEN]u8,
    title_len: u32,
};

// Window state manager: manages saved window states.
pub const WindowStateManager = struct {
    entries: [MAX_STATE_WINDOWS]WindowStateEntry,
    entries_len: u32,

    pub fn init() WindowStateManager {
        var manager = WindowStateManager{
            .entries = undefined,
            .entries_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_STATE_WINDOWS) : (i += 1) {
            manager.entries[i] = WindowStateEntry{
                .window_id = 0,
                .x = 0,
                .y = 0,
                .width = 0,
                .height = 0,
                .minimized = false,
                .maximized = false,
                .workspace_id = 0,
                .title = undefined,
                .title_len = 0,
            };
            var j: u32 = 0;
            while (j < compositor.MAX_TITLE_LEN) : (j += 1) {
                manager.entries[i].title[j] = 0;
            }
        }
        return manager;
    }

    // Save window state.
    pub fn save_window(
        self: *WindowStateManager,
        window_id: u32,
        x: i32,
        y: i32,
        width: u32,
        height: u32,
        minimized: bool,
        maximized: bool,
        workspace_id: u32,
        title: []const u8,
    ) bool {
        std.debug.assert(window_id > 0);
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);
        if (self.entries_len >= MAX_STATE_WINDOWS) {
            return false;
        }
        // Check if window already exists, update it.
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].window_id == window_id) {
                self.entries[i].x = x;
                self.entries[i].y = y;
                self.entries[i].width = width;
                self.entries[i].height = height;
                self.entries[i].minimized = minimized;
                self.entries[i].maximized = maximized;
                self.entries[i].workspace_id = workspace_id;
                const copy_len = @min(title.len,
compositor.MAX_TITLE_LEN);
                var j: u32 = 0;
                while (j < compositor.MAX_TITLE_LEN) : (j += 1) {
                    self.entries[i].title[j] = 0;
                }
                j = 0;
                while (j < copy_len) : (j += 1) {
                    self.entries[i].title[j] = title[j];
                }
                self.entries[i].title_len = @intCast(copy_len);
                return true;
            }
        }
        // Add new entry.
        self.entries[self.entries_len] = WindowStateEntry{
            .window_id = window_id,
            .x = x,
            .y = y,
            .width = width,
            .height = height,
            .minimized = minimized,
            .maximized = maximized,
            .workspace_id = workspace_id,
            .title = undefined,
            .title_len = 0,
        };
        const copy_len = @min(title.len, compositor.MAX_TITLE_LEN);
        var j: u32 = 0;
        while (j < compositor.MAX_TITLE_LEN) : (j += 1) {
            self.entries[self.entries_len].title[j] = 0;
        }
        j = 0;
        while (j < copy_len) : (j += 1) {
            self.entries[self.entries_len].title[j] = title[j];
        }
        self.entries[self.entries_len].title_len = @intCast(copy_len);
        self.entries_len += 1;
        return true;
    }

    // Get saved window state.
    pub fn get_window_state(
        self: *const WindowStateManager,
        window_id: u32,
    ) ?WindowStateEntry {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].window_id == window_id) {
                return self.entries[i];
            }
        }
        return null;
    }

    // Remove window state.
    pub fn remove_window(self: *WindowStateManager, window_id: u32) bool
{
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].window_id == window_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining entries left.
        while (i < self.entries_len - 1) : (i += 1) {
            self.entries[i] = self.entries[i + 1];
        }
        self.entries_len -= 1;
        return true;
    }

    // Clear all saved states.
    pub fn clear(self: *WindowStateManager) void {
        self.entries_len = 0;
    }

    // Get number of saved states.
    pub fn get_count(self: *const WindowStateManager) u32 {
        return self.entries_len;
    }
};


// === grain_core/window_switching.zig ===

//! Grain OS Window Switching: Alt+Tab style window switching.
//!
//! Why: Provide window switching to cycle through open windows.
//! Architecture: Window order management and cycling.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const compositor = @import("compositor.zig");

// Bounded: Max windows in switch list.
pub const MAX_SWITCH_WINDOWS: u32 = 256;

// Window switch order: maintains order of windows for switching.
pub const WindowSwitchOrder = struct {
    window_ids: [MAX_SWITCH_WINDOWS]u32,
    window_ids_len: u32,
    current_index: u32,

    pub fn init() WindowSwitchOrder {
        var order = WindowSwitchOrder{
            .window_ids = undefined,
            .window_ids_len = 0,
            .current_index = 0,
        };
        var i: u32 = 0;
        while (i < MAX_SWITCH_WINDOWS) : (i += 1) {
            order.window_ids[i] = 0;
        }
        return order;
    }

    // Add window to switch order.
    pub fn add_window(self: *WindowSwitchOrder, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        if (self.window_ids_len >= MAX_SWITCH_WINDOWS) {
            return false;
        }
        // Check if window already exists.
        var i: u32 = 0;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                // Move to front.
                self.move_to_front(window_id);
                return true;
            }
        }
        // Add to front.
        self.window_ids[self.window_ids_len] = window_id;
        self.window_ids_len += 1;
        self.move_to_front(window_id);
        return true;
    }

    // Remove window from switch order.
    pub fn remove_window(self: *WindowSwitchOrder, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining windows left.
        while (i < self.window_ids_len - 1) : (i += 1) {
            self.window_ids[i] = self.window_ids[i + 1];
        }
        self.window_ids_len -= 1;
        // Adjust current index if needed.
        if (self.current_index >= self.window_ids_len and
self.window_ids_len > 0) {
            self.current_index = self.window_ids_len - 1;
        }
        if (self.window_ids_len == 0) {
            self.current_index = 0;
        }
        return true;
    }

    // Move window to front of order.
    pub fn move_to_front(self: *WindowSwitchOrder, window_id: u32) void {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return;
        }
        // Shift windows before this one right.
        var j: u32 = i;
        while (j > 0) : (j -= 1) {
            self.window_ids[j] = self.window_ids[j - 1];
        }
        // Put window at front.
        self.window_ids[0] = window_id;
        self.current_index = 0;
    }

    // Get next window in cycle (forward).
    pub fn get_next(self: *WindowSwitchOrder) ?u32 {
        if (self.window_ids_len == 0) {
            return null;
        }
        self.current_index = (self.current_index + 1) %
self.window_ids_len;
        return self.window_ids[self.current_index];
    }

    // Get previous window in cycle (backward).
    pub fn get_previous(self: *WindowSwitchOrder) ?u32 {
        if (self.window_ids_len == 0) {
            return null;
        }
        if (self.current_index == 0) {
            self.current_index = self.window_ids_len - 1;
        } else {
            self.current_index -= 1;
        }
        return self.window_ids[self.current_index];
    }

    // Get current window.
    pub fn get_current(self: *const WindowSwitchOrder) ?u32 {
        if (self.window_ids_len == 0) {
            return null;
        }
        return self.window_ids[self.current_index];
    }

    // Reset to first window.
    pub fn reset(self: *WindowSwitchOrder) void {
        self.current_index = 0;
    }
};


// === grain_core/window_visual.zig ===

//! Grain OS Window Visual Enhancements: Shadows, focus indicators.
//!
//! Why: Provide visual depth and feedback for window operations.
//! Architecture: Visual enhancement rendering for windows.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const framebuffer_renderer = @import("framebuffer_renderer.zig");

// Bounded: Shadow offset and blur.
pub const SHADOW_OFFSET_X: i32 = 4;
pub const SHADOW_OFFSET_Y: i32 = 4;
pub const SHADOW_BLUR: u32 = 8;
pub const SHADOW_ALPHA: u32 = 0x80; // 50% opacity.

// Bounded: Focus glow size.
pub const FOCUS_GLOW_SIZE: u32 = 3;
pub const FOCUS_GLOW_ALPHA: u32 = 0xC0; // 75% opacity.

// Bounded: Hover highlight size.
pub const HOVER_HIGHLIGHT_SIZE: u32 = 2;

// Window visual state.
pub const WindowVisualState = struct {
    has_shadow: bool,
    has_focus_glow: bool,
    has_hover: bool,
    shadow_color: u32,
    focus_glow_color: u32,
    hover_color: u32,
};

// Initialize default visual state.
pub fn init_visual_state() WindowVisualState {
    return WindowVisualState{
        .has_shadow = true,
        .has_focus_glow = true,
        .has_hover = false,
        .shadow_color = 0x00000000 | SHADOW_ALPHA,
        .focus_glow_color = 0x0000FFFF | (FOCUS_GLOW_ALPHA << 24),
        .hover_color = 0xFFFFFF00 | 0x80000000,
    };
}

// Calculate shadow color with alpha.
pub fn calc_shadow_color(_base_color: u32, alpha: u32) u32 {
    const r = (_base_color >> 16) & 0xFF;
    const g = (_base_color >> 8) & 0xFF;
    const b = _base_color & 0xFF;
    return (alpha << 24) | (r << 16) | (g << 8) | b;
}

// Calculate focus glow color.
pub fn calc_focus_glow_color(base_color: u32) u32 {
    const r = (base_color >> 16) & 0xFF;
    const g = (base_color >> 8) & 0xFF;
    const b = base_color & 0xFF;
    return (FOCUS_GLOW_ALPHA << 24) | (r << 16) | (g << 8) | b;
}

// Check if window should have shadow.
pub fn should_render_shadow(minimized: bool) bool {
    return !minimized;
}

// Check if window should have focus glow.
pub fn should_render_focus_glow(focused: bool) bool {
    return focused;
}

// Check if window should have hover effect.
pub fn should_render_hover(hovered: bool) bool {
    return hovered;
}


// === grain_core/workspace.zig ===

//! Grain OS Workspace: Workspace management for window organization.
//!
//! Why: Organize windows into separate workspaces (River-style).
//! Architecture: Multiple workspaces, window assignment, switching.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");

// Bounded: Max number of workspaces.
pub const MAX_WORKSPACES: u32 = 10;

// Bounded: Max windows per workspace.
pub const MAX_WORKSPACE_WINDOWS: u32 = 256;

// Workspace: represents a workspace with windows.
pub const Workspace = struct {
    id: u32,
    name: [32]u8,
    name_len: u32,
    window_ids: [MAX_WORKSPACE_WINDOWS]u32,
    window_ids_len: u32,
    focused_window_id: u32,
    visible: bool,

    pub fn init(id: u32, name: []const u8) Workspace {
        std.debug.assert(id > 0);
        std.debug.assert(id <= MAX_WORKSPACES);
        std.debug.assert(name.len <= 32);
        var workspace = Workspace{
            .id = id,
            .name = undefined,
            .name_len = 0,
            .window_ids = undefined,
            .window_ids_len = 0,
            .focused_window_id = 0,
            .visible = false,
        };
        var j: u32 = 0;
        while (j < 32) : (j += 1) {
            workspace.name[j] = 0;
        }
        j = 0;
        while (j < MAX_WORKSPACE_WINDOWS) : (j += 1) {
            workspace.window_ids[j] = 0;
        }
        const copy_len = @min(name.len, 32);
        var i: u32 = 0;
        while (i < copy_len) : (i += 1) {
            workspace.name[i] = name[i];
        }
        workspace.name_len = @intCast(copy_len);
        std.debug.assert(workspace.id > 0);
        return workspace;
    }

    pub fn add_window(self: *Workspace, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        if (self.window_ids_len >= MAX_WORKSPACE_WINDOWS) {
            return false;
        }
        // Check if window already in workspace.
        var i: u32 = 0;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                return false; // Already in workspace.
            }
        }
        self.window_ids[self.window_ids_len] = window_id;
        self.window_ids_len += 1;
        std.debug.assert(self.window_ids_len <= MAX_WORKSPACE_WINDOWS);
        return true;
    }

    pub fn remove_window(self: *Workspace, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Shift remaining windows left.
        while (i < self.window_ids_len - 1) : (i += 1) {
            self.window_ids[i] = self.window_ids[i + 1];
        }
        self.window_ids_len -= 1;
        if (self.focused_window_id == window_id) {
            self.focused_window_id = 0;
        }
        return true;
    }

    pub fn set_focused_window(self: *Workspace, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        // Check if window is in workspace.
        var i: u32 = 0;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                self.focused_window_id = window_id;
                return true;
            }
        }
        return false;
    }

    pub fn has_window(self: *const Workspace, window_id: u32) bool {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        while (i < self.window_ids_len) : (i += 1) {
            if (self.window_ids[i] == window_id) {
                return true;
            }
        }
        return false;
    }
};

// Workspace manager: manages all workspaces.
pub const WorkspaceManager = struct {
    workspaces: [MAX_WORKSPACES]Workspace,
    workspaces_len: u32,
    current_workspace_id: u32,

    pub fn init() WorkspaceManager {
        var manager = WorkspaceManager{
            .workspaces = undefined,
            .workspaces_len = 0,
            .current_workspace_id = 0,
        };
        var i: u32 = 0;
        while (i < MAX_WORKSPACES) : (i += 1) {
            manager.workspaces[i] = Workspace.init(i + 1, "");
        }
        // Create default workspace.
        manager.workspaces[0] = Workspace.init(1, "main");
        manager.workspaces[0].visible = true;
        manager.workspaces_len = 1;
        manager.current_workspace_id = 1;
        std.debug.assert(manager.current_workspace_id > 0);
        return manager;
    }

    pub fn get_workspace(self: *WorkspaceManager, workspace_id: u32)
?*Workspace {
        std.debug.assert(workspace_id > 0);
        var i: u32 = 0;
        while (i < self.workspaces_len) : (i += 1) {
            if (self.workspaces[i].id == workspace_id) {
                return &self.workspaces[i];
            }
        }
        return null;
    }

    pub fn get_current_workspace(self: *WorkspaceManager) ?*Workspace {
        if (self.current_workspace_id == 0) {
            return null;
        }
        return self.get_workspace(self.current_workspace_id);
    }

    pub fn switch_workspace(self: *WorkspaceManager, workspace_id: u32)
bool {
        std.debug.assert(workspace_id > 0);
        if (self.get_workspace(workspace_id)) |workspace| {
            // Hide current workspace.
            if (self.get_current_workspace()) |current| {
                current.visible = false;
            }
            // Show new workspace.
            workspace.visible = true;
            self.current_workspace_id = workspace_id;
            std.debug.assert(self.current_workspace_id > 0);
            return true;
        }
        return false;
    }

    pub fn create_workspace(self: *WorkspaceManager, name: []const u8)
?u32 {
        std.debug.assert(name.len <= 32);
        if (self.workspaces_len >= MAX_WORKSPACES) {
            return null;
        }
        const new_id = self.workspaces_len + 1;
        std.debug.assert(new_id <= MAX_WORKSPACES);
        self.workspaces[self.workspaces_len] = Workspace.init(new_id,
name);
        self.workspaces_len += 1;
        std.debug.assert(self.workspaces_len <= MAX_WORKSPACES);
        return new_id;
    }

    pub fn assign_window_to_workspace(
        self: *WorkspaceManager,
        window_id: u32,
        workspace_id: u32,
    ) bool {
        std.debug.assert(window_id > 0);
        std.debug.assert(workspace_id > 0);
        // Remove from current workspace (if any).
        var i: u32 = 0;
        while (i < self.workspaces_len) : (i += 1) {
            _ = self.workspaces[i].remove_window(window_id);
        }
        // Add to target workspace.
        if (self.get_workspace(workspace_id)) |workspace| {
            return workspace.add_window(window_id);
        }
        return false;
    }

    pub fn get_window_workspace(
        self: *const WorkspaceManager,
        window_id: u32,
    ) ?u32 {
        std.debug.assert(window_id > 0);
        var i: u32 = 0;
        while (i < self.workspaces_len) : (i += 1) {
            if (self.workspaces[i].has_window(window_id)) {
                return self.workspaces[i].id;
            }
        }
        return null;
    }
};

// === grain_court/compute.zig ===

const std = @import("std");

/// Grain Court: WSE-wafer-scale SRAM spatial computing abstraction for
self-hostable LLM backend.
/// ~<~ Glow Airbend: explicit compute state, bounded core management.
/// ~~~~ Glow Waterbend: deterministic spatial computing, iterative
algorithms.
///
/// Represents the WSE compute layer: 44GB+ on-wafer SRAM, 900k cores,
/// court topology (2D grid with wrap-around) for parallel execution.
/// Target: Cerebras GLM4.6 API for WSE hardware.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
///
/// 2025-12-05-145359-pst: Renamed from Grain Field to Grain Court
pub const Compute = struct {
    // Bounded: Max cores per court (explicit limit)
    // 2025-12-05-145359-pst: Active constant
    pub const MAX_CORES: u32 = 1_000_000; // 900k cores + headroom

    // Bounded: Max SRAM capacity (explicit limit, in bytes)
    // 2025-12-05-145359-pst: Active constant
    pub const MAX_SRAM_CAPACITY: u64 = 47_185_920_000; // 44GB +
headroom (44 * 1024^3)

    // Bounded: Max parallel operations (explicit limit)
    // 2025-12-05-145359-pst: Active constant
    pub const MAX_PARALLEL_OPS: u32 = 10_000;

    /// Core state enumeration.
    // 2025-12-05-145359-pst: Active enum
    pub const CoreState = enum(u8) {
        idle, // Core is idle
        active, // Core is executing
        waiting, // Core is waiting for data
        error_state, // Core is in error state
    };

    /// Court core structure.
    // 2025-12-05-145359-pst: Active struct
    pub const Core = struct {
        id: u32, // Core ID (unique identifier)
        state: CoreState, // Core state
        sram_offset: u64, // SRAM offset for this core's data
        sram_size: u64, // SRAM size allocated to this core
        neighbors: []u32, // Neighboring core IDs (court topology)
        neighbors_len: u32,
    };

    /// Court compute structure.
    // 2025-12-05-145359-pst: Active struct
    pub const CourtCompute = struct {
        cores: []Core, // Cores buffer (bounded)
        cores_len: u32, // Number of cores
        sram_capacity: u64, // Total SRAM capacity (bytes)
        sram_used: u64, // SRAM used (bytes)
        sram_data: []u8, // SRAM data buffer (bounded)
        parallel_ops: []ParallelOp, // Parallel operations queue
(bounded)
        parallel_ops_len: u32, // Number of parallel operations
        allocator: std.mem.Allocator,

        /// Parallel operation structure.
        pub const ParallelOp = struct {
            op_id: u32, // Operation ID
            op_type: OpType, // Operation type
            core_ids: []u32, // Core IDs involved in operation
            core_ids_len: u32,
            data_offset: u64, // Data offset in SRAM
            data_size: u64, // Data size
            status: OpStatus, // Operation status
        };

        /// Operation type enumeration.
        pub const OpType = enum(u8) {
            vector_search, // Vector similarity search
            fulltext_search, // Full-text search (BM25)
            matrix_multiply, // Matrix multiplication
            data_transform, // Data transformation
            llm_inference, // LLM inference (GLM4.6 API target)
        };

        /// Operation status enumeration.
        // 2025-12-05-145359-pst: Active enum
        pub const OpStatus = enum(u8) {
            pending, // Operation pending
            executing, // Operation executing
            completed, // Operation completed
            error_state, // Operation error
        };

        /// Initialize court compute.
        // 2025-12-05-145359-pst: Active function
        pub fn init(allocator: std.mem.Allocator, sram_capacity: u64,
core_count: u32) !CourtCompute {

            // Assert: Capacity and core count must be bounded
            std.debug.assert(sram_capacity <= MAX_SRAM_CAPACITY);
            std.debug.assert(core_count <= MAX_CORES);

            // Pre-allocate cores buffer
            const cores = try allocator.alloc(Core, core_count);
            errdefer allocator.free(cores);

            // Pre-allocate SRAM data buffer
            const sram_data = try allocator.alloc(u8, @as(usize,
@intCast(sram_capacity)));
            errdefer allocator.free(sram_data);

            // Pre-allocate parallel operations buffer
            const parallel_ops = try allocator.alloc(ParallelOp,
MAX_PARALLEL_OPS);
            errdefer allocator.free(parallel_ops);

            // Initialize cores (toroidal topology)
            // Calculate grid dimensions (square grid for simplicity)
            const grid_size_f = @sqrt(@as(f64,
@floatFromInt(core_count)));
            var grid_size = @as(u32, @intFromFloat(@ceil(grid_size_f)));
            // Ensure grid_size is at least 1
            if (grid_size == 0) {
                grid_size = 1;
            }
            var i: u32 = 0;
            while (i < core_count) : (i += 1) {
                // Calculate toroidal neighbors (simplified: each core
has 4 neighbors)
                const neighbors = try allocator.alloc(u32, 4);

                // Toroidal topology: connect to neighbors in 2D grid
                const row = i / grid_size;
                const col = i % grid_size;
                
                // Calculate neighbor IDs (toroidal wrap-around)
                const row_down = (row + 1) % grid_size;
                const row_up = (row - 1 + grid_size) % grid_size;
                const col_right = (col + 1) % grid_size;
                const col_left = (col - 1 + grid_size) % grid_size;
                
                neighbors[0] = row_down * grid_size + col; // Down
                neighbors[1] = row_up * grid_size + col; // Up
                neighbors[2] = row * grid_size + col_right; // Right
                neighbors[3] = row * grid_size + col_left; // Left

                cores[i] = Core{
                    .id = i,
                    .state = .idle,
                    .sram_offset = 0, // Will be allocated on demand
                    .sram_size = 0,
                    .neighbors = neighbors,
                    .neighbors_len = 4,
                };
            }

            return CourtCompute{
                .cores = cores,
                .cores_len = core_count,
                .sram_capacity = sram_capacity,
                .sram_used = 0,
                .sram_data = sram_data,
                .parallel_ops = parallel_ops,
                .parallel_ops_len = 0,
                .allocator = allocator,
            };
        }

        /// Deinitialize court compute and free memory.
        pub fn deinit(self: *CourtCompute) void {
            // Assert: Allocator must be valid (allocator is used below)
            _ = self.allocator;

            // Free core neighbors
            var i: u32 = 0;
            while (i < self.cores_len) : (i += 1) {
                self.allocator.free(self.cores[i].neighbors);
            }

            // Free buffers
            self.allocator.free(self.cores);
            self.allocator.free(self.sram_data);
            self.allocator.free(self.parallel_ops);

            self.* = undefined;
        }

        /// Allocate SRAM for core.
        pub fn allocate_sram(self: *CourtCompute, core_id: u32, size:
u64) !u64 {
            // Assert: Core ID must be valid
            std.debug.assert(core_id < self.cores_len);

            // Assert: Size must be bounded
            std.debug.assert(size <= MAX_SRAM_CAPACITY);

            // Check SRAM availability
            if (self.sram_used + size > self.sram_capacity) {
                return error.OutOfSRAM;
            }

            // Allocate SRAM offset
            const offset = self.sram_used;
            self.sram_used += size;

            // Update core SRAM allocation
            self.cores[core_id].sram_offset = offset;
            self.cores[core_id].sram_size = size;

            return offset;
        }

        /// Execute parallel operation on court.
        // 2025-12-05-145359-pst: Active function
        pub fn execute_parallel(self: *CourtCompute, op_type: OpType,
core_ids: []const u32, data_offset: u64, data_size: u64) !u32 {
            // Assert: Core IDs must be valid
            var i: u32 = 0;
            while (i < core_ids.len) : (i += 1) {
                std.debug.assert(core_ids[i] < self.cores_len);
            }

            // Check parallel operations limit
            if (self.parallel_ops_len >= MAX_PARALLEL_OPS) {
                return error.TooManyParallelOps;
            }

            // Allocate core IDs copy
            const core_ids_copy = try self.allocator.alloc(u32,
core_ids.len);
            errdefer self.allocator.free(core_ids_copy);
            @memcpy(core_ids_copy, core_ids);

            // Create parallel operation
            const op_id = self.parallel_ops_len;
            self.parallel_ops[op_id] = ParallelOp{
                .op_id = op_id,
                .op_type = op_type,
                .core_ids = core_ids_copy,
                .core_ids_len = @as(u32, @intCast(core_ids.len)),
                .data_offset = data_offset,
                .data_size = data_size,
                .status = .pending,
            };
            self.parallel_ops_len += 1;

            // Mark cores as active
            i = 0;
            while (i < core_ids.len) : (i += 1) {
                self.cores[core_ids[i]].state = .active;
            }

            return op_id;
        }

        /// Get operation status.
        pub fn get_op_status(self: *CourtCompute, op_id: u32) ?OpStatus {
            if (op_id >= self.parallel_ops_len) {
                return null;
            }
            return self.parallel_ops[op_id].status;
        }

        /// Get core by ID.
        pub fn get_core(self: *CourtCompute, core_id: u32) ?*Core {
            if (core_id >= self.cores_len) {
                return null;
            }
            return &self.cores[core_id];
        }
    };
};


// === grain_court/root.zig ===

// Grain Court root module
// Re-exports all Grain Court components
// 2025-12-05-145359-pst: Renamed from Grain Field to Grain Court

pub const Compute = @import("compute.zig").Compute;


// === grain_database/api.zig ===

//! Grain Database API: REST API layer for mobile backend integration.
//!
//! Why: Expose database operations via REST API for mobile apps.
//! Architecture: Endpoint handlers, JSON serialization, middleware.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-03-175009-pst: Grain Database Agent
//!
//! Note: Integrates with Grain OS Agent's API Server (Phase 59).

const std = @import("std");
const storage_engine = @import("storage_engine.zig");
const relational = @import("relational.zig");
const graph = @import("graph.zig");
const index = @import("index.zig");

// Bounded: Max request body size (bytes).
pub const MAX_REQUEST_BODY_SIZE: u32 = 1_048_576; // 1 MB

// Bounded: Max response body size (bytes).
pub const MAX_RESPONSE_BODY_SIZE: u32 = 10_485_760; // 10 MB

// Bounded: Max routes.
pub const MAX_ROUTES: u32 = 256;

// Bounded: Max rate limit entries.
pub const MAX_RATE_LIMIT_ENTRIES: u32 = 10_000;

// HTTP method.
pub const HttpMethod = enum {
    get,
    post,
    put,
    delete,
    patch,
};

// API request context.
pub const ApiRequest = struct {
    method: HttpMethod,
    path: []const u8,
    path_len: u32,
    headers: []const Header,
    headers_len: u32,
    body: []const u8,
    body_len: u32,
    query_params: []const QueryParam,
    query_params_len: u32,
    allocator: std.mem.Allocator,

    pub const Header = struct {
        name: []const u8,
        name_len: u32,
        value: []const u8,
        value_len: u32,
    };

    pub const QueryParam = struct {
        key: []const u8,
        key_len: u32,
        value: []const u8,
        value_len: u32,
    };

    // Get header value by name.
    pub fn get_header(self: *ApiRequest, name: []const u8) ?[]const u8 {
        std.debug.assert(name.len <= 256);
        var i: u32 = 0;
        while (i < self.headers_len) : (i += 1) {
            if (std.mem.eql(u8, self.headers[i].name, name)) {
                return self.headers[i].value;
            }
        }
        return null;
    }

    // Get query parameter value by key.
    pub fn get_query_param(self: *ApiRequest, key: []const u8) ?[]const
u8 {
        std.debug.assert(key.len <= 256);
        var i: u32 = 0;
        while (i < self.query_params_len) : (i += 1) {
            if (std.mem.eql(u8, self.query_params[i].key, key)) {
                return self.query_params[i].value;
            }
        }
        return null;
    }
};

// API response.
pub const ApiResponse = struct {
    status_code: u16,
    headers: []Header,
    headers_len: u32,
    body: []u8,
    body_len: u32,
    allocator: std.mem.Allocator,

    pub const Header = struct {
        name: []const u8,
        name_len: u32,
        value: []const u8,
        value_len: u32,
    };

    // Initialize response.
    pub fn init(allocator: std.mem.Allocator) !ApiResponse {
        const headers = try allocator.alloc(Header, 32);
        errdefer allocator.free(headers);

        const body = try allocator.alloc(u8, MAX_RESPONSE_BODY_SIZE);
        errdefer allocator.free(body);

        return ApiResponse{
            .status_code = 200,
            .headers = headers,
            .headers_len = 0,
            .body = body,
            .body_len = 0,
            .allocator = allocator,
        };
    }

    // Deinitialize response and free memory.
    pub fn deinit(self: *ApiResponse) void {
        self.allocator.free(self.headers);
        self.allocator.free(self.body);
        self.* = undefined;
    }

    // Add header to response.
    pub fn add_header(
        self: *ApiResponse,
        name: []const u8,
        value: []const u8,
    ) !void {
        std.debug.assert(self.headers_len < 32);
        std.debug.assert(name.len <= 256);
        std.debug.assert(value.len <= 1024);

        if (self.headers_len >= 32) {
            return error.TooManyHeaders;
        }

        const name_copy = try self.allocator.dupe(u8, name);
        errdefer self.allocator.free(name_copy);

        const value_copy = try self.allocator.dupe(u8, value);
        errdefer self.allocator.free(value_copy);

        self.headers[self.headers_len] = Header{
            .name = name_copy,
            .name_len = @as(u32, @intCast(name_copy.len)),
            .value = value_copy,
            .value_len = @as(u32, @intCast(value_copy.len)),
        };
        self.headers_len += 1;
    }

    // Set response body (JSON).
    pub fn set_json_body(
        self: *ApiResponse,
        json: []const u8,
    ) !void {
        std.debug.assert(json.len <= MAX_RESPONSE_BODY_SIZE);

        if (json.len > self.body.len) {
            return error.BodyTooLarge;
        }

        @memcpy(self.body[0..json.len], json);
        self.body_len = @as(u32, @intCast(json.len));
    }
};

// Route handler function type.
pub const RouteHandler = *const fn (
    request: *ApiRequest,
    response: *ApiResponse,
    context: *ApiContext,
) void;

// API route definition.
pub const Route = struct {
    method: HttpMethod,
    path: []const u8,
    path_len: u32,
    handler: RouteHandler,
    requires_auth: bool,
    allocator: std.mem.Allocator,

    // Initialize route.
    pub fn init(
        allocator: std.mem.Allocator,
        method: HttpMethod,
        path: []const u8,
        handler: RouteHandler,
        requires_auth: bool,
    ) !Route {
        std.debug.assert(path.len <= 512);
        const path_copy = try allocator.dupe(u8, path);
        errdefer allocator.free(path_copy);

        return Route{
            .method = method,
            .path = path_copy,
            .path_len = @as(u32, @intCast(path_copy.len)),
            .handler = handler,
            .requires_auth = requires_auth,
            .allocator = allocator,
        };
    }

    // Deinitialize route and free memory.
    pub fn deinit(self: *Route) void {
        if (self.path_len > 0) {
            self.allocator.free(self.path);
        }
        self.* = undefined;
    }
};

// Rate limit entry.
pub const RateLimitEntry = struct {
    client_id: []const u8,
    client_id_len: u32,
    request_count: u32,
    window_start: u64,
    allocator: std.mem.Allocator,

    // Initialize rate limit entry.
    pub fn init(
        allocator: std.mem.Allocator,
        client_id: []const u8,
    ) !RateLimitEntry {
        std.debug.assert(client_id.len <= 256);
        const id_copy = try allocator.dupe(u8, client_id);
        errdefer allocator.free(id_copy);

        const now = std.time.timestamp();

        return RateLimitEntry{
            .client_id = id_copy,
            .client_id_len = @as(u32, @intCast(id_copy.len)),
            .request_count = 1,
            .window_start = @as(u64, @intCast(now)),
            .allocator = allocator,
        };
    }

    // Deinitialize entry and free memory.
    pub fn deinit(self: *RateLimitEntry) void {
        if (self.client_id_len > 0) {
            self.allocator.free(self.client_id);
        }
        self.* = undefined;
    }
};

// Rate limiter: Tracks requests per client.
pub const RateLimiter = struct {
    entries: []RateLimitEntry,
    entries_len: u32,
    max_requests_per_minute: u32,
    allocator: std.mem.Allocator,

    // Initialize rate limiter.
    pub fn init(
        allocator: std.mem.Allocator,
        max_requests_per_minute: u32,
    ) !RateLimiter {
        const entries = try allocator.alloc(
            RateLimitEntry,
            MAX_RATE_LIMIT_ENTRIES,
        );
        errdefer allocator.free(entries);

        return RateLimiter{
            .entries = entries,
            .entries_len = 0,
            .max_requests_per_minute = max_requests_per_minute,
            .allocator = allocator,
        };
    }

    // Deinitialize rate limiter and free memory.
    pub fn deinit(self: *RateLimiter) void {
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            self.entries[i].deinit();
        }
        self.allocator.free(self.entries);
        self.* = undefined;
    }

    // Check if client exceeds rate limit.
    pub fn check_rate_limit(
        self: *RateLimiter,
        client_id: []const u8,
    ) !bool {
        std.debug.assert(client_id.len <= 256);
        const now_timestamp = std.time.timestamp();
        const now = @as(u64, @intCast(if (now_timestamp < 0) 0 else
now_timestamp));
        const window_seconds: u64 = 60;

        const entry = try self.find_or_create_entry(client_id);
        if (now - entry.window_start > window_seconds) {
            entry.request_count = 1;
            entry.window_start = @as(u64, @intCast(now));
            return true;
        }

        if (entry.request_count >= self.max_requests_per_minute) {
            return false;
        }

        entry.request_count += 1;
        return true;
    }

    // Find or create rate limit entry.
    fn find_or_create_entry(
        self: *RateLimiter,
        client_id: []const u8,
    ) !*RateLimitEntry {
        std.debug.assert(client_id.len <= 256);

        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (std.mem.eql(u8, self.entries[i].client_id, client_id)) {
                return &self.entries[i];
            }
        }

        if (self.entries_len >= MAX_RATE_LIMIT_ENTRIES) {
            return error.TooManyRateLimitEntries;
        }

        var entry = try RateLimitEntry.init(self.allocator, client_id);
        errdefer entry.deinit();

        self.entries[self.entries_len] = entry;
        self.entries_len += 1;

        std.debug.assert(self.entries_len <= MAX_RATE_LIMIT_ENTRIES);
        return &self.entries[self.entries_len - 1];
    }
};

// API context: Database and configuration.
pub const ApiContext = struct {
    storage: *storage_engine.StorageEngine,
    schema: *relational.Schema,
    graph_db: *graph.Graph,
    fulltext_index: *index.InvertedIndex,
    rate_limiter: *RateLimiter,
    allocator: std.mem.Allocator,

    // Initialize API context.
    pub fn init(
        allocator: std.mem.Allocator,
        storage: *storage_engine.StorageEngine,
        schema: *relational.Schema,
        graph_db: *graph.Graph,
        fulltext_index: *index.InvertedIndex,
        rate_limiter: *RateLimiter,
    ) ApiContext {
        return ApiContext{
            .storage = storage,
            .schema = schema,
            .graph_db = graph_db,
            .fulltext_index = fulltext_index,
            .rate_limiter = rate_limiter,
            .allocator = allocator,
        };
    }
};

// API router: Manages routes and handles requests.
pub const ApiRouter = struct {
    routes: []Route,
    routes_len: u32,
    allocator: std.mem.Allocator,

    // Initialize API router.
    pub fn init(allocator: std.mem.Allocator) !ApiRouter {
        const routes = try allocator.alloc(Route, MAX_ROUTES);
        errdefer allocator.free(routes);

        return ApiRouter{
            .routes = routes,
            .routes_len = 0,
            .allocator = allocator,
        };
    }

    // Deinitialize router and free memory.
    pub fn deinit(self: *ApiRouter) void {
        var i: u32 = 0;
        while (i < self.routes_len) : (i += 1) {
            self.routes[i].deinit();
        }
        self.allocator.free(self.routes);
        self.* = undefined;
    }

    // Register route.
    pub fn register_route(
        self: *ApiRouter,
        method: HttpMethod,
        path: []const u8,
        handler: RouteHandler,
        requires_auth: bool,
    ) !void {
        std.debug.assert(self.routes_len < MAX_ROUTES);

        if (self.routes_len >= MAX_ROUTES) {
            return error.TooManyRoutes;
        }

        var route = try Route.init(
            self.allocator,
            method,
            path,
            handler,
            requires_auth,
        );
        errdefer route.deinit();

        self.routes[self.routes_len] = route;
        self.routes_len += 1;

        std.debug.assert(self.routes_len <= MAX_ROUTES);
    }

    // Find route by method and path.
    pub fn find_route(
        self: *ApiRouter,
        method: HttpMethod,
        path: []const u8,
    ) ?*Route {
        std.debug.assert(path.len <= 1024);
        var i: u32 = 0;
        while (i < self.routes_len) : (i += 1) {
            if (self.routes[i].method == method) {
                if (std.mem.eql(u8, self.routes[i].path, path)) {
                    return &self.routes[i];
                }
            }
        }
        return null;
    }
};

// CORS middleware: Add CORS headers to response.
pub fn add_cors_headers(response: *ApiResponse) !void {
    try response.add_header("Access-Control-Allow-Origin", "*");
    try response.add_header(
        "Access-Control-Allow-Methods",
        "GET, POST, PUT, DELETE, OPTIONS",
    );
    try response.add_header(
        "Access-Control-Allow-Headers",
        "Content-Type, Authorization",
    );
}

// JSON serialization helpers.
pub const JsonSerializer = struct {
    allocator: std.mem.Allocator,

    // Initialize JSON serializer.
    pub fn init(allocator: std.mem.Allocator) JsonSerializer {
        return JsonSerializer{
            .allocator = allocator,
        };
    }

    // Serialize record to JSON.
    pub fn serialize_record(
        self: *JsonSerializer,
        record: *storage_engine.Record,
        output: []u8,
    ) !u32 {
        _ = self;
        std.debug.assert(output.len >= MAX_RESPONSE_BODY_SIZE);

        var stream = std.io.fixedBufferStream(output);
        const writer = stream.writer();

        try writer.print(
            "{{\"id\":{},\"key\":\"{}\",\"value\":\"{}\"}}",
            .{ record.record_id, record.key, record.value },
        );

        const written = stream.getPos();
        return @as(u32, @intCast(written));
    }

    // Serialize error to JSON.
    pub fn serialize_error(
        self: *JsonSerializer,
        error_message: []const u8,
        output: []u8,
    ) !u32 {
        _ = self;
        std.debug.assert(output.len >= 1024);

        var stream = std.io.fixedBufferStream(output);
        const writer = stream.writer();

        try writer.print("{{\"error\":\"{}\"}}", .{error_message});

        const written = stream.getPos();
        return @as(u32, @intCast(written));
    }
};

// WebSocket support for livestream coordination.
pub const WebSocketConnection = struct {
    connection_id: u64,
    client_id: []const u8,
    client_id_len: u32,
    is_active: bool,
    last_ping: u64,
    allocator: std.mem.Allocator,

    // Initialize WebSocket connection.
    pub fn init(
        allocator: std.mem.Allocator,
        connection_id: u64,
        client_id: []const u8,
    ) !WebSocketConnection {
        std.debug.assert(client_id.len <= 256);
        const id_copy = try allocator.dupe(u8, client_id);
        errdefer allocator.free(id_copy);

        const now = std.time.timestamp();

        return WebSocketConnection{
            .connection_id = connection_id,
            .client_id = id_copy,
            .client_id_len = @as(u32, @intCast(id_copy.len)),
            .is_active = true,
            .last_ping = @as(u64, @intCast(now)),
            .allocator = allocator,
        };
    }

    // Deinitialize connection and free memory.
    pub fn deinit(self: *WebSocketConnection) void {
        if (self.client_id_len > 0) {
            self.allocator.free(self.client_id);
        }
        self.* = undefined;
    }

    // Update last ping timestamp.
    pub fn update_ping(self: *WebSocketConnection) void {
        const now = std.time.timestamp();
        self.last_ping = @as(u64, @intCast(now));
        std.debug.assert(self.last_ping > 0);
    }
};

// Bounded: Max WebSocket connections.
pub const MAX_WEBSOCKET_CONNECTIONS: u32 = 1000;

// WebSocket connection manager.
pub const WebSocketManager = struct {
    connections: []WebSocketConnection,
    connections_len: u32,
    allocator: std.mem.Allocator,

    // Initialize WebSocket manager.
    pub fn init(allocator: std.mem.Allocator) !WebSocketManager {
        const connections = try allocator.alloc(
            WebSocketConnection,
            MAX_WEBSOCKET_CONNECTIONS,
        );
        errdefer allocator.free(connections);

        return WebSocketManager{
            .connections = connections,
            .connections_len = 0,
            .allocator = allocator,
        };
    }

    // Deinitialize manager and free memory.
    pub fn deinit(self: *WebSocketManager) void {
        var i: u32 = 0;
        while (i < self.connections_len) : (i += 1) {
            self.connections[i].deinit();
        }
        self.allocator.free(self.connections);
        self.* = undefined;
    }

    // Add WebSocket connection.
    pub fn add_connection(
        self: *WebSocketManager,
        connection_id: u64,
        client_id: []const u8,
    ) !u32 {
        std.debug.assert(self.connections_len <
MAX_WEBSOCKET_CONNECTIONS);

        if (self.connections_len >= MAX_WEBSOCKET_CONNECTIONS) {
            return error.TooManyConnections;
        }

        var conn = try WebSocketConnection.init(
            self.allocator,
            connection_id,
            client_id,
        );
        errdefer conn.deinit();

        self.connections[self.connections_len] = conn;
        self.connections_len += 1;

        std.debug.assert(self.connections_len <=
MAX_WEBSOCKET_CONNECTIONS);
        return self.connections_len - 1;
    }

    // Remove WebSocket connection.
    pub fn remove_connection(
        self: *WebSocketManager,
        connection_idx: u32,
    ) void {
        std.debug.assert(connection_idx < self.connections_len);

        self.connections[connection_idx].deinit();

        if (connection_idx < self.connections_len - 1) {
            self.connections[connection_idx] =
                self.connections[self.connections_len - 1];
        }

        self.connections_len -= 1;
    }

    // Get connection by ID.
    pub fn get_connection(
        self: *WebSocketManager,
        connection_id: u64,
    ) ?*WebSocketConnection {
        var i: u32 = 0;
        while (i < self.connections_len) : (i += 1) {
            if (self.connections[i].connection_id == connection_id) {
                return &self.connections[i];
            }
        }
        return null;
    }
};

// JWT authentication middleware.
pub const AuthMiddleware = struct {
    secret: []const u8,
    secret_len: u32,
    allocator: std.mem.Allocator,

    // Initialize authentication middleware.
    pub fn init(
        allocator: std.mem.Allocator,
        secret: []const u8,
    ) !AuthMiddleware {
        std.debug.assert(secret.len > 0);
        std.debug.assert(secret.len <= 256);
        const secret_copy = try allocator.dupe(u8, secret);
        errdefer allocator.free(secret_copy);

        return AuthMiddleware{
            .secret = secret_copy,
            .secret_len = @as(u32, @intCast(secret_copy.len)),
            .allocator = allocator,
        };
    }

    // Deinitialize middleware and free memory.
    pub fn deinit(self: *AuthMiddleware) void {
        if (self.secret_len > 0) {
            self.allocator.free(self.secret);
        }
        self.* = undefined;
    }

    // Validate JWT token from Authorization header.
    pub fn validate_request(
        self: *AuthMiddleware,
        request: *ApiRequest,
    ) bool {
        std.debug.assert(request != null);

        const auth_header = request.get_header("Authorization");
        if (auth_header == null) {
            return false;
        }

        const auth_value = auth_header.?;
        if (auth_value.len < 7) {
            return false;
        }

        if (!std.mem.eql(u8, auth_value[0..7], "Bearer ")) {
            return false;
        }

        const token = auth_value[7..];
        if (token.len == 0) {
            return false;
        }

        const now = std.time.timestamp();
        const current_time = @as(u64, @intCast(now));

        var claims: struct {
            user_id: [64]u8,
            user_id_len: u32,
            exp: u64,
            iat: u64,
        } = undefined;

        return self.validate_jwt_token(token, current_time, &claims);
    }

    // Validate JWT token (simplified validation).
    fn validate_jwt_token(
        self: *AuthMiddleware,
        token: []const u8,
        current_time: u64,
        claims: *struct {
            user_id: [64]u8,
            user_id_len: u32,
            exp: u64,
            iat: u64,
        },
    ) bool {
        _ = self;
        std.debug.assert(token.len > 0);
        std.debug.assert(token.len <= 2048);
        std.debug.assert(current_time > 0);

        var parts: [3][]const u8 = undefined;
        var part_count: u32 = 0;
        var start: u32 = 0;
        var i: u32 = 0;

        while (i < token.len and part_count < 3) : (i += 1) {
            if (token[i] == '.') {
                parts[part_count] = token[start..i];
                part_count += 1;
                start = i + 1;
            }
        }

        if (part_count < 2) {
            return false;
        }

        parts[part_count] = token[start..];
        part_count += 1;

        if (part_count != 3) {
            return false;
        }

        var exp_found: bool = false;
        var exp_value: u64 = 0;
        var user_id_start: ?u32 = null;
        var user_id_end: ?u32 = null;

        var claims_decoded: [256]u8 = undefined;
        var claims_decoded_len: u32 = 0;

        i = 0;
        while (i < parts[1].len and claims_decoded_len < 256) : (i += 1)
{
            const c = parts[1][i];
            if (c == '-' or c == '_') {
                claims_decoded[claims_decoded_len] = '+';
            } else if (c == '/') {
                claims_decoded[claims_decoded_len] = '=';
            } else {
                claims_decoded[claims_decoded_len] = c;
            }
            claims_decoded_len += 1;
        }

        i = 0;
        while (i < claims_decoded_len) : (i += 1) {
            if (i + 3 < claims_decoded_len and
                std.mem.eql(u8, claims_decoded[i..i + 4], "\"exp\""))
            {
                i += 4;
                while (i < claims_decoded_len and
                    (claims_decoded[i] == ' ' or claims_decoded[i] ==
':')) : (i += 1)
                {}
                const exp_str_start = i;
                while (i < claims_decoded_len and
                    claims_decoded[i] >= '0' and claims_decoded[i] <=
'9') : (i += 1)
                {}
                const exp_str = claims_decoded[exp_str_start..i];
                exp_value = 0;
                var exp_j: u32 = 0;
                while (exp_j < exp_str.len) : (exp_j += 1) {
                    if (exp_str[exp_j] >= '0' and exp_str[exp_j] <= '9')
{
                        exp_value = exp_value * 10 + @as(u64,
exp_str[exp_j] - '0');
                    }
                }
                exp_found = true;
            }
            if (i + 7 < claims_decoded_len and
                std.mem.eql(u8, claims_decoded[i..i + 8], "\"user_id\""))
            {
                i += 8;
                while (i < claims_decoded_len and claims_decoded[i] !=
'"') : (i += 1) {}
                i += 1;
                user_id_start = i;
                while (i < claims_decoded_len and claims_decoded[i] !=
'"') : (i += 1) {}
                user_id_end = i;
            }
        }

        if (!exp_found) {
            return false;
        }

        if (current_time > exp_value) {
            return false;
        }

        if (user_id_start != null and user_id_end != null) {
            const user_id_len = user_id_end.? - user_id_start.?;
            if (user_id_len > 0 and user_id_len <= 64) {
                std.mem.copyForwards(
                    u8,
                    &claims.user_id,
                    claims_decoded[user_id_start.?..user_id_end.?],
                );
                claims.user_id_len = @as(u32, @intCast(user_id_len));
            }
        }

        claims.exp = exp_value;
        claims.iat = 0;

        std.debug.assert(claims.user_id_len > 0);
        std.debug.assert(claims.exp > 0);

        return true;
    }
};


// === grain_database/auth_integration.zig ===

//! Grain Database Authentication Integration: AuthService integration.
//!
//! Why: Integrate database authentication with Grain Core AuthService
(Phase 60).
//! Architecture: JWT validation, session management, permission checks.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-06-010807-pst: Grain Silo Agent

const std = @import("std");
const integration_os = @import("integration_os.zig");
const grain_core = @import("grain_core");
const grain_core_api_server = grain_core.api_server;
const grain_core_auth_service = grain_core.auth_service;

// Global AuthService instance (set during initialization).
var global_auth_service: ?*grain_core_auth_service.AuthService = null;

// Set AuthService instance.
pub fn set_auth_service(service: *grain_core_auth_service.AuthService)
void {
    global_auth_service = service;
    std.debug.assert(global_auth_service != null);
}

// Get AuthService instance.
pub fn get_auth_service() ?*grain_core_auth_service.AuthService {
    return global_auth_service;
}

// Extract JWT token from Authorization header.
fn extract_jwt_token(
    request: *grain_core_api_server.HttpRequest,
    token_out: []u8,
) u32 {
    std.debug.assert(request != null);
    std.debug.assert(token_out.len >=
grain_core_auth_service.MAX_JWT_LEN);
    const auth_header = request.get_header("Authorization") orelse
return 0;
    const bearer_prefix = "Bearer ";
    if (auth_header.len < bearer_prefix.len) {
        return 0;
    }
    if (!std.mem.startsWith(u8, auth_header, bearer_prefix)) {
        return 0;
    }
    const token_start = bearer_prefix.len;
    const token_len = auth_header.len - token_start;
    if (token_len == 0 or token_len >
grain_core_auth_service.MAX_JWT_LEN) {
        return 0;
    }
    std.mem.copyForwards(u8, token_out[0..token_len],
auth_header[token_start..]);
    return @intCast(token_len);
}

// Enhanced database authentication middleware using AuthService.
pub fn database_auth_middleware_enhanced(
    request: *grain_core_api_server.HttpRequest,
    response: *grain_core_api_server.HttpResponse,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(response != null);
    const auth_service = get_auth_service() orelse {
        response.status =
grain_core_api_server.HttpStatus.internal_server_error;
        return false;
    };
    var token_buf: [grain_core_auth_service.MAX_JWT_LEN]u8 = undefined;
    const token_len = extract_jwt_token(request, &token_buf);
    if (token_len == 0) {
        response.status = grain_core_api_server.HttpStatus.unauthorized;
        _ = response.add_header("Content-Type", "application/json");
        const error_body =
"{\"error\":\"unauthorized\",\"message\":\"Missing token\"}";
        const body_len = @min(error_body.len,
grain_core_api_server.MAX_RESPONSE_SIZE);
        var i: u32 = 0;
        while (i < body_len) : (i += 1) {
            response.body[i] = error_body[i];
        }
        response.body_len = @intCast(body_len);
        return false;
    }
    var claims: grain_core_auth_service.JwtClaims = undefined;
    const current_time = @as(u64, @intCast(std.time.timestamp()));
    const is_valid = auth_service.validate_jwt_token(
        token_buf[0..token_len],
        current_time,
        &claims,
    );
    if (!is_valid) {
        response.status = grain_core_api_server.HttpStatus.unauthorized;
        _ = response.add_header("Content-Type", "application/json");
        const error_body =
"{\"error\":\"unauthorized\",\"message\":\"Invalid token\"}";
        const body_len = @min(error_body.len,
grain_core_api_server.MAX_RESPONSE_SIZE);
        var i: u32 = 0;
        while (i < body_len) : (i += 1) {
            response.body[i] = error_body[i];
        }
        response.body_len = @intCast(body_len);
        return false;
    }
    std.debug.assert(token_len > 0);
    std.debug.assert(token_len <= grain_core_auth_service.MAX_JWT_LEN);
    return true;
}

// Validate session from request.
pub fn validate_session(
    request: *grain_core_api_server.HttpRequest,
    session_id_out: []u8,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(session_id_out.len >=
grain_core_auth_service.MAX_SESSION_ID_LEN);
    const auth_service = get_auth_service() orelse return false;
    const session_header = request.get_header("X-Session-ID") orelse
return false;
    if (session_header.len == 0 or session_header.len >
grain_core_auth_service.MAX_SESSION_ID_LEN) {
        return false;
    }
    std.mem.copyForwards(u8, session_id_out[0..session_header.len],
session_header);
    const current_time = @as(u64, @intCast(std.time.timestamp()));
    return
auth_service.validate_session(session_id_out[0..session_header.len],
current_time);
}

// Get user ID from JWT token in request.
pub fn get_user_id_from_request(
    request: *grain_core_api_server.HttpRequest,
    user_id_out: []u8,
) u32 {
    std.debug.assert(request != null);
    std.debug.assert(user_id_out.len >=
grain_core_auth_service.MAX_USER_ID_LEN);
    const auth_service = get_auth_service() orelse return 0;
    var token_buf: [grain_core_auth_service.MAX_JWT_LEN]u8 = undefined;
    const token_len = extract_jwt_token(request, &token_buf);
    if (token_len == 0) {
        return 0;
    }
    var claims: grain_core_auth_service.JwtClaims = undefined;
    const current_time = @as(u64, @intCast(std.time.timestamp()));
    if (!auth_service.validate_jwt_token(token_buf[0..token_len],
current_time, &claims)) {
        return 0;
    }
    const user_id_len = @min(claims.user_id_len, user_id_out.len);
    std.mem.copyForwards(u8, user_id_out[0..user_id_len],
claims.user_id[0..claims.user_id_len]);
    return user_id_len;
}

// Permission types for access control.
pub const Permission = enum(u8) {
    read,
    write,
    delete,
    admin,
};

// Check if user has permission (simplified: admin check).
pub fn check_permission(
    user_id: []const u8,
    permission: Permission,
) bool {
    std.debug.assert(user_id.len > 0);
    std.debug.assert(user_id.len <=
grain_core_auth_service.MAX_USER_ID_LEN);
    _ = permission;
    if (std.mem.startsWith(u8, user_id, "admin_")) {
        return true;
    }
    if (permission == Permission.read) {
        return true;
    }
    return false;
}

// Check permission from request (extracts user ID and checks
permission).
pub fn check_permission_from_request(
    request: *grain_core_api_server.HttpRequest,
    permission: Permission,
) bool {
    std.debug.assert(request != null);
    var user_id_buf: [grain_core_auth_service.MAX_USER_ID_LEN]u8 =
undefined;
    const user_id_len = get_user_id_from_request(request, &user_id_buf);
    if (user_id_len == 0) {
        return false;
    }
    return check_permission(user_id_buf[0..user_id_len], permission);
}

// Create session for user from request.
pub fn create_session_from_request(
    request: *grain_core_api_server.HttpRequest,
    session_out: *grain_core_auth_service.Session,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(session_out != null);
    const auth_service = get_auth_service() orelse return false;
    var user_id_buf: [grain_core_auth_service.MAX_USER_ID_LEN]u8 =
undefined;
    const user_id_len = get_user_id_from_request(request, &user_id_buf);
    if (user_id_len == 0) {
        return false;
    }
    const current_time = @as(u64, @intCast(std.time.timestamp()));
    return auth_service.create_session(user_id_buf[0..user_id_len],
current_time, session_out);
}

// Revoke session from request (logout).
pub fn revoke_session_from_request(
    request: *grain_core_api_server.HttpRequest,
) bool {
    std.debug.assert(request != null);
    const auth_service = get_auth_service() orelse return false;
    var session_id_buf: [grain_core_auth_service.MAX_SESSION_ID_LEN]u8 =
undefined;
    const session_header = request.get_header("X-Session-ID") orelse
return false;
    if (session_header.len == 0 or session_header.len >
grain_core_auth_service.MAX_SESSION_ID_LEN) {
        return false;
    }
    std.mem.copyForwards(u8, &session_id_buf, session_header);
    return
auth_service.revoke_session(session_id_buf[0..session_header.len]);
}

// Get session from request (validates and returns session).
pub fn get_session_from_request(
    request: *grain_core_api_server.HttpRequest,
    session_out: *grain_core_auth_service.Session,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(session_out != null);
    const auth_service = get_auth_service() orelse return false;
    var session_id_buf: [grain_core_auth_service.MAX_SESSION_ID_LEN]u8 =
undefined;
    const session_header = request.get_header("X-Session-ID") orelse
return false;
    if (session_header.len == 0 or session_header.len >
grain_core_auth_service.MAX_SESSION_ID_LEN) {
        return false;
    }
    std.mem.copyForwards(u8, &session_id_buf, session_header);
    const current_time = @as(u64, @intCast(std.time.timestamp()));
    return
auth_service.validate_session(session_id_buf[0..session_header.len],
current_time, session_out);
}


// === grain_database/graph.zig ===

//! Grain Database Graph: Graph data structure and traversal algorithms.
//!
//! Why: Enable graph queries and reverse lookups for relationships.
//! Architecture: Bounded nodes/edges, iterative traversal algorithms.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-03-165223-pst: Grain Database Agent

const std = @import("std");
const BTreeIndex = @import("index.zig").BTreeIndex;

// Bounded: Max nodes in graph.
pub const MAX_NODES: u32 = 10_000_000;

// Bounded: Max edges in graph.
pub const MAX_EDGES: u32 = 100_000_000;

// Bounded: Max edges per node.
pub const MAX_EDGES_PER_NODE: u32 = 1_000;

// Bounded: Max traversal depth.
pub const MAX_TRAVERSAL_DEPTH: u32 = 1_000;

// Graph node: Represents an entity (user, candidate, policy, etc.).
pub const GraphNode = struct {
    node_id: u64,
    node_type: []const u8,
    node_type_len: u32,
    properties: []const u8,
    properties_len: u32,
    created_at: u64,
    allocator: std.mem.Allocator,

    // Initialize graph node.
    pub fn init(
        allocator: std.mem.Allocator,
        node_id: u64,
        node_type: []const u8,
        properties: []const u8,
    ) !GraphNode {
        std.debug.assert(node_id > 0);
        std.debug.assert(node_type.len <= 256);
        _ = allocator;

        const type_copy = try allocator.dupe(u8, node_type);
        errdefer allocator.free(type_copy);

        const props_copy = try allocator.dupe(u8, properties);
        errdefer allocator.free(props_copy);

        const now = std.time.timestamp();

        return GraphNode{
            .node_id = node_id,
            .node_type = type_copy,
            .node_type_len = @as(u32, @intCast(type_copy.len)),
            .properties = props_copy,
            .properties_len = @as(u32, @intCast(props_copy.len)),
            .created_at = @as(u64, @intCast(now)),
            .allocator = allocator,
        };
    }

    // Deinitialize graph node and free memory.
    pub fn deinit(self: *GraphNode) void {
        _ = self.allocator;
        if (self.node_type_len > 0) {
            self.allocator.free(self.node_type);
        }
        if (self.properties_len > 0) {
            self.allocator.free(self.properties);
        }
        self.* = undefined;
    }
};

// Graph edge: Represents a relationship between nodes.
pub const GraphEdge = struct {
    edge_id: u64,
    from_node_id: u64,
    to_node_id: u64,
    relationship_type: []const u8,
    relationship_type_len: u32,
    properties: []const u8,
    properties_len: u32,
    created_at: u64,
    allocator: std.mem.Allocator,

    // Initialize graph edge.
    pub fn init(
        allocator: std.mem.Allocator,
        edge_id: u64,
        from_node_id: u64,
        to_node_id: u64,
        relationship_type: []const u8,
        properties: []const u8,
    ) !GraphEdge {
        std.debug.assert(edge_id > 0);
        std.debug.assert(from_node_id > 0);
        std.debug.assert(to_node_id > 0);
        std.debug.assert(relationship_type.len <= 256);
        _ = allocator;

        const rel_copy = try allocator.dupe(u8, relationship_type);
        errdefer allocator.free(rel_copy);

        const props_copy = try allocator.dupe(u8, properties);
        errdefer allocator.free(props_copy);

        const now = std.time.timestamp();

        return GraphEdge{
            .edge_id = edge_id,
            .from_node_id = from_node_id,
            .to_node_id = to_node_id,
            .relationship_type = rel_copy,
            .relationship_type_len = @as(u32, @intCast(rel_copy.len)),
            .properties = props_copy,
            .properties_len = @as(u32, @intCast(props_copy.len)),
            .created_at = @as(u64, @intCast(now)),
            .allocator = allocator,
        };
    }

    // Deinitialize graph edge and free memory.
    pub fn deinit(self: *GraphEdge) void {
        _ = self.allocator;
        if (self.relationship_type_len > 0) {
            self.allocator.free(self.relationship_type);
        }
        if (self.properties_len > 0) {
            self.allocator.free(self.properties);
        }
        self.* = undefined;
    }
};

// Graph: Collection of nodes and edges with traversal support.
pub const Graph = struct {
    nodes: []GraphNode,
    nodes_len: u32,
    edges: []GraphEdge,
    edges_len: u32,
    next_node_id: u64,
    next_edge_id: u64,
    forward_index: BTreeIndex,
    reverse_index: BTreeIndex,
    allocator: std.mem.Allocator,

    // Initialize graph.
    pub fn init(allocator: std.mem.Allocator) !Graph {
        _ = allocator;
        const nodes = try allocator.alloc(GraphNode, MAX_NODES);
        errdefer allocator.free(nodes);

        const edges = try allocator.alloc(GraphEdge, MAX_EDGES);
        errdefer allocator.free(edges);

        const forward_idx = try BTreeIndex.init(allocator);
        errdefer forward_idx.deinit();

        const reverse_idx = try BTreeIndex.init(allocator);
        errdefer reverse_idx.deinit();

        return Graph{
            .nodes = nodes,
            .nodes_len = 0,
            .edges = edges,
            .edges_len = 0,
            .next_node_id = 1,
            .next_edge_id = 1,
            .forward_index = forward_idx,
            .reverse_index = reverse_idx,
            .allocator = allocator,
        };
    }

    // Deinitialize graph and free memory.
    pub fn deinit(self: *Graph) void {
        _ = self.allocator;
        var i: u32 = 0;
        while (i < self.nodes_len) : (i += 1) {
            self.nodes[i].deinit();
        }
        i = 0;
        while (i < self.edges_len) : (i += 1) {
            self.edges[i].deinit();
        }
        self.allocator.free(self.nodes);
        self.allocator.free(self.edges);
        self.forward_index.deinit();
        self.reverse_index.deinit();
        self.* = undefined;
    }

    // Add node to graph.
    pub fn add_node(
        self: *Graph,
        node_type: []const u8,
        properties: []const u8,
    ) !u64 {
        std.debug.assert(self.nodes_len < MAX_NODES);

        if (self.nodes_len >= MAX_NODES) {
            return error.GraphFull;
        }

        const node_id = self.next_node_id;
        self.next_node_id += 1;

        var node = try GraphNode.init(
            self.allocator,
            node_id,
            node_type,
            properties,
        );
        errdefer node.deinit();

        self.nodes[self.nodes_len] = node;
        self.nodes_len += 1;

        std.debug.assert(self.nodes_len <= MAX_NODES);
        return node_id;
    }

    // Add edge to graph.
    pub fn add_edge(
        self: *Graph,
        from_node_id: u64,
        to_node_id: u64,
        relationship_type: []const u8,
        properties: []const u8,
    ) !u64 {
        std.debug.assert(self.edges_len < MAX_EDGES);
        std.debug.assert(from_node_id > 0);
        std.debug.assert(to_node_id > 0);

        if (self.edges_len >= MAX_EDGES) {
            return error.GraphFull;
        }

        const edge_id = self.next_edge_id;
        self.next_edge_id += 1;

        var edge = try GraphEdge.init(
            self.allocator,
            edge_id,
            from_node_id,
            to_node_id,
            relationship_type,
            properties,
        );
        errdefer edge.deinit();

        self.edges[self.edges_len] = edge;
        self.edges_len += 1;

        // Update forward index: from_node_id -> edge_id
        _ = try self.forward_index.insert(from_node_id, edge_id);

        // Update reverse index: to_node_id -> edge_id
        _ = try self.reverse_index.insert(to_node_id, edge_id);

        std.debug.assert(self.edges_len <= MAX_EDGES);
        return edge_id;
    }

    // Get node by ID.
    pub fn get_node(self: *Graph, node_id: u64) ?*GraphNode {
        std.debug.assert(node_id > 0);
        var i: u32 = 0;
        while (i < self.nodes_len) : (i += 1) {
            if (self.nodes[i].node_id == node_id) {
                return &self.nodes[i];
            }
        }
        return null;
    }

    // Get edges from node (forward traversal).
    pub fn get_edges_from(
        self: *Graph,
        node_id: u64,
        output: []u64,
    ) !u32 {
        std.debug.assert(node_id > 0);
        std.debug.assert(output.len >= MAX_EDGES_PER_NODE);
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.edges_len) : (i += 1) {
            if (self.edges[i].from_node_id == node_id) {
                if (count >= output.len) {
                    return error.TooManyEdges;
                }
                output[count] = self.edges[i].edge_id;
                count += 1;
            }
        }
        return count;
    }

    // Get edges to node (reverse traversal).
    pub fn get_edges_to(
        self: *Graph,
        node_id: u64,
        output: []u64,
    ) !u32 {
        std.debug.assert(node_id > 0);
        std.debug.assert(output.len >= MAX_EDGES_PER_NODE);
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.edges_len) : (i += 1) {
            if (self.edges[i].to_node_id == node_id) {
                if (count >= output.len) {
                    return error.TooManyEdges;
                }
                output[count] = self.edges[i].edge_id;
                count += 1;
            }
        }
        return count;
    }

    // Breadth-first search (iterative, queue-based).
    pub fn traverse_bfs(
        self: *Graph,
        start_node_id: u64,
        visitor: *const fn (node_id: u64) void,
        visited: []bool,
    ) !void {
        std.debug.assert(start_node_id > 0);
        std.debug.assert(visited.len >= MAX_NODES);

        var queue: [MAX_NODES]u64 = undefined;
        var queue_front: u32 = 0;
        var queue_back: u32 = 0;
        var depth: u32 = 0;

        @memset(visited, false);
        queue[queue_back] = start_node_id;
        queue_back += 1;
        visited[@as(usize, @intCast(start_node_id % MAX_NODES))] = true;

        while (queue_front < queue_back) {
            if (depth >= MAX_TRAVERSAL_DEPTH) {
                return error.MaxDepthExceeded;
            }

            const current_id = queue[queue_front];
            queue_front += 1;
            visitor(current_id);

            var edges: [MAX_EDGES_PER_NODE]u64 = undefined;
            const edge_count = try self.get_edges_from(current_id,
&edges);
            var i: u32 = 0;
            while (i < edge_count) : (i += 1) {
                const edge = self.find_edge(edges[i]);
                if (edge) |e| {
                    const next_id = e.to_node_id;
                    const visited_idx = @as(usize, @intCast(next_id %
MAX_NODES));
                    if (!visited[visited_idx]) {
                        visited[visited_idx] = true;
                        if (queue_back >= MAX_NODES) {
                            return error.QueueFull;
                        }
                        queue[queue_back] = next_id;
                        queue_back += 1;
                    }
                }
            }
            depth += 1;
        }
    }

    // Depth-first search (iterative, stack-based).
    pub fn traverse_dfs(
        self: *Graph,
        start_node_id: u64,
        visitor: *const fn (node_id: u64) void,
        visited: []bool,
    ) !void {
        std.debug.assert(start_node_id > 0);
        std.debug.assert(visited.len >= MAX_NODES);

        var stack: [MAX_NODES]u64 = undefined;
        var stack_len: u32 = 0;
        var depth: u32 = 0;

        @memset(visited, false);
        stack[stack_len] = start_node_id;
        stack_len += 1;

        while (stack_len > 0) {
            if (depth >= MAX_TRAVERSAL_DEPTH) {
                return error.MaxDepthExceeded;
            }

            stack_len -= 1;
            const current_id = stack[stack_len];
            const visited_idx = @as(usize, @intCast(current_id %
MAX_NODES));

            if (visited[visited_idx]) {
                continue;
            }
            visited[visited_idx] = true;
            visitor(current_id);

            var edges: [MAX_EDGES_PER_NODE]u64 = undefined;
            const edge_count = try self.get_edges_from(current_id,
&edges);
            var i: u32 = 0;
            while (i < edge_count) : (i += 1) {
                const edge = self.find_edge(edges[i]);
                if (edge) |e| {
                    const next_id = e.to_node_id;
                    const next_visited_idx = @as(usize, @intCast(next_id
% MAX_NODES));
                    if (!visited[next_visited_idx]) {
                        if (stack_len >= MAX_NODES) {
                            return error.StackFull;
                        }
                        stack[stack_len] = next_id;
                        stack_len += 1;
                    }
                }
            }
            depth += 1;
        }
    }

    // Reverse lookup: Find all nodes that have edges to target node.
    pub fn reverse_lookup(
        self: *Graph,
        target_node_id: u64,
        output: []u64,
    ) !u32 {
        std.debug.assert(target_node_id > 0);
        std.debug.assert(output.len >= MAX_NODES);
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.edges_len) : (i += 1) {
            if (self.edges[i].to_node_id == target_node_id) {
                if (count >= output.len) {
                    return error.TooManyNodes;
                }
                output[count] = self.edges[i].from_node_id;
                count += 1;
            }
        }
        return count;
    }

    // Find edge by ID (internal helper).
    fn find_edge(self: *Graph, edge_id: u64) ?*GraphEdge {
        std.debug.assert(edge_id > 0);
        var i: u32 = 0;
        while (i < self.edges_len) : (i += 1) {
            if (self.edges[i].edge_id == edge_id) {
                return &self.edges[i];
            }
        }
        return null;
    }
};


// === grain_database/index.zig ===

//! Grain Database Index: Hash, B-tree, and full-text search indexes.
//!
//! Why: Fast lookups by ID (hash), foreign keys (B-tree), and text
(inverted).
//! Architecture: Iterative algorithms, bounded allocations.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-03-173339-pst: Grain Database Agent (Phase 4: Full-Text
Search)

const std = @import("std");

// Bounded: Max hash table size (power of 2 for efficient hashing).
pub const MAX_HASH_SIZE: u32 = 1_048_576; // 2^20

// Bounded: Max B-tree nodes.
pub const MAX_BTREE_NODES: u32 = 1_000_000;

// Bounded: Max keys per B-tree node.
pub const MAX_KEYS_PER_NODE: u32 = 32;

// Hash index entry: Maps ID to record pointer.
pub const HashIndexEntry = struct {
    record_id: u64,
    record_ptr: u64, // Offset/index into records array
    next: ?u32, // Next entry in hash chain (for collisions)
};

// Hash index: Fast ID lookups.
pub const HashIndex = struct {
    buckets: []?u32, // Bucket array (indices into entries)
    entries: []HashIndexEntry, // Entry array
    entries_len: u32,
    allocator: std.mem.Allocator,

    // Initialize hash index.
    pub fn init(allocator: std.mem.Allocator) !HashIndex {
        _ = allocator;
        const buckets = try allocator.alloc(?u32, MAX_HASH_SIZE);
        errdefer allocator.free(buckets);
        var i: u32 = 0;
        while (i < MAX_HASH_SIZE) : (i += 1) {
            buckets[i] = null;
        }

        const entries = try allocator.alloc(
            HashIndexEntry,
            MAX_HASH_SIZE,
        );
        errdefer allocator.free(entries);

        return HashIndex{
            .buckets = buckets,
            .entries = entries,
            .entries_len = 0,
            .allocator = allocator,
        };
    }

    // Deinitialize hash index and free memory.
    pub fn deinit(self: *HashIndex) void {
        _ = self.allocator;
        self.allocator.free(self.buckets);
        self.allocator.free(self.entries);
        self.* = undefined;
    }

    // Insert record ID into hash index.
    pub fn insert(
        self: *HashIndex,
        record_id: u64,
        record_ptr: u64,
    ) !void {
        std.debug.assert(record_id > 0);
        std.debug.assert(self.entries_len < MAX_HASH_SIZE);

        const hash = self.hash_record_id(record_id);
        const bucket_idx = hash % MAX_HASH_SIZE;

        if (self.entries_len >= MAX_HASH_SIZE) {
            return error.HashIndexFull;
        }

        const entry_idx = self.entries_len;
        self.entries[entry_idx] = HashIndexEntry{
            .record_id = record_id,
            .record_ptr = record_ptr,
            .next = self.buckets[bucket_idx],
        };
        self.buckets[bucket_idx] = entry_idx;
        self.entries_len += 1;
    }

    // Lookup record pointer by ID.
    pub fn lookup(
        self: *HashIndex,
        record_id: u64,
    ) ?u64 {
        std.debug.assert(record_id > 0);
        const hash = self.hash_record_id(record_id);
        const bucket_idx = hash % MAX_HASH_SIZE;

        var entry_idx = self.buckets[bucket_idx];
        while (entry_idx) |idx| {
            if (self.entries[idx].record_id == record_id) {
                return self.entries[idx].record_ptr;
            }
            entry_idx = self.entries[idx].next;
        }
        return null;
    }

    // Hash record ID (simple multiplicative hash).
    fn hash_record_id(self: *HashIndex, record_id: u64) u64 {
        _ = self;
        return record_id *% 0x9e3779b97f4a7c15;
    }
};

// B-tree node: For foreign key indexing.
pub const BTreeNode = struct {
    keys: [MAX_KEYS_PER_NODE]u64,
    values: [MAX_KEYS_PER_NODE]u64,
    keys_len: u32,
    children: [MAX_KEYS_PER_NODE + 1]?u32,
    is_leaf: bool,
    parent: ?u32,

    // Initialize B-tree node.
    pub fn init(is_leaf: bool) BTreeNode {
        var node = BTreeNode{
            .keys = undefined,
            .values = undefined,
            .keys_len = 0,
            .children = undefined,
            .is_leaf = is_leaf,
            .parent = null,
        };
        var i: u32 = 0;
        while (i <= MAX_KEYS_PER_NODE) : (i += 1) {
            node.children[i] = null;
        }
        return node;
    }
};

// B-tree index: For foreign key lookups (range queries).
pub const BTreeIndex = struct {
    nodes: []BTreeNode,
    nodes_len: u32,
    root_idx: ?u32,
    allocator: std.mem.Allocator,

    // Initialize B-tree index.
    pub fn init(allocator: std.mem.Allocator) !BTreeIndex {
        _ = allocator;
        const nodes = try allocator.alloc(BTreeNode, MAX_BTREE_NODES);
        errdefer allocator.free(nodes);

        return BTreeIndex{
            .nodes = nodes,
            .nodes_len = 0,
            .root_idx = null,
            .allocator = allocator,
        };
    }

    // Deinitialize B-tree index and free memory.
    pub fn deinit(self: *BTreeIndex) void {
        _ = self.allocator;
        self.allocator.free(self.nodes);
        self.* = undefined;
    }

    // Insert key-value pair into B-tree.
    pub fn insert(
        self: *BTreeIndex,
        key: u64,
        value: u64,
    ) !void {
        std.debug.assert(key > 0);
        std.debug.assert(self.nodes_len < MAX_BTREE_NODES);

        if (self.root_idx == null) {
            const root_idx = self.nodes_len;
            self.nodes[root_idx] = BTreeNode.init(true);
            self.nodes[root_idx].keys[0] = key;
            self.nodes[root_idx].values[0] = value;
            self.nodes[root_idx].keys_len = 1;
            self.root_idx = root_idx;
            self.nodes_len += 1;
            return;
        }

        const root = self.root_idx.?;
        if (self.nodes[root].keys_len >= MAX_KEYS_PER_NODE) {
            return error.BTreeFull;
        }

        _ = try self.insert_into_node(root, key, value);
    }

    // Insert into node (internal helper).
    fn insert_into_node(
        self: *BTreeIndex,
        node_idx: u32,
        key: u64,
        value: u64,
    ) !void {
        std.debug.assert(node_idx < self.nodes_len);
        var node = &self.nodes[node_idx];

        if (node.is_leaf) {
            var i: u32 = 0;
            while (i < node.keys_len) : (i += 1) {
                if (key < node.keys[i]) {
                    var j: u32 = node.keys_len;
                    while (j > i) : (j -= 1) {
                        node.keys[j] = node.keys[j - 1];
                        node.values[j] = node.values[j - 1];
                    }
                    node.keys[i] = key;
                    node.values[i] = value;
                    node.keys_len += 1;
                    return;
                }
            }
            node.keys[node.keys_len] = key;
            node.values[node.keys_len] = value;
            node.keys_len += 1;
        } else {
            var i: u32 = 0;
            while (i < node.keys_len) : (i += 1) {
                if (key < node.keys[i]) {
                    if (node.children[i]) |child_idx| {
                        return self.insert_into_node(child_idx, key,
value);
                    }
                    break;
                }
            }
            if (node.children[node.keys_len]) |child_idx| {
                return self.insert_into_node(child_idx, key, value);
            }
        }
    }

    // Lookup value by key.
    pub fn lookup(
        self: *BTreeIndex,
        key: u64,
    ) ?u64 {
        std.debug.assert(key > 0);
        if (self.root_idx) |root| {
            return self.lookup_in_node(root, key);
        }
        return null;
    }

    // Lookup in node (internal helper).
    fn lookup_in_node(
        self: *BTreeIndex,
        node_idx: u32,
        key: u64,
    ) ?u64 {
        std.debug.assert(node_idx < self.nodes_len);
        const node = &self.nodes[node_idx];

        var i: u32 = 0;
        while (i < node.keys_len) : (i += 1) {
            if (key == node.keys[i]) {
                return node.values[i];
            }
            if (key < node.keys[i]) {
                if (node.is_leaf) {
                    return null;
                }
                if (node.children[i]) |child_idx| {
                    return self.lookup_in_node(child_idx, key);
                }
                return null;
            }
        }

        if (node.is_leaf) {
            return null;
        }
        if (node.children[node.keys_len]) |child_idx| {
            return self.lookup_in_node(child_idx, key);
        }
        return null;
    }
};

// Bounded: Max tokens per document.
pub const MAX_TOKENS_PER_DOC: u32 = 10_000;

// Bounded: Max token length.
pub const MAX_TOKEN_LEN: u32 = 256;

// Bounded: Max documents per token.
pub const MAX_DOCS_PER_TOKEN: u32 = 1_000_000;

// Bounded: Max unique tokens.
pub const MAX_UNIQUE_TOKENS: u32 = 10_000_000;

// Inverted index entry: Maps token to document IDs.
pub const InvertedIndexEntry = struct {
    token: []const u8,
    token_len: u32,
    document_ids: []u64,
    document_ids_len: u32,
    allocator: std.mem.Allocator,

    // Initialize inverted index entry.
    pub fn init(
        allocator: std.mem.Allocator,
        token: []const u8,
    ) !InvertedIndexEntry {
        std.debug.assert(token.len <= MAX_TOKEN_LEN);
        _ = allocator;

        const token_copy = try allocator.dupe(u8, token);
        errdefer allocator.free(token_copy);

        const doc_ids = try allocator.alloc(u64, MAX_DOCS_PER_TOKEN);
        errdefer allocator.free(doc_ids);

        return InvertedIndexEntry{
            .token = token_copy,
            .token_len = @as(u32, @intCast(token_copy.len)),
            .document_ids = doc_ids,
            .document_ids_len = 0,
            .allocator = allocator,
        };
    }

    // Deinitialize entry and free memory.
    pub fn deinit(self: *InvertedIndexEntry) void {
        _ = self.allocator;
        if (self.token_len > 0) {
            self.allocator.free(self.token);
        }
        self.allocator.free(self.document_ids);
        self.* = undefined;
    }

    // Add document ID to entry.
    pub fn add_document_id(self: *InvertedIndexEntry, doc_id: u64) !void
{
        std.debug.assert(doc_id > 0);
        std.debug.assert(self.document_ids_len < MAX_DOCS_PER_TOKEN);

        if (self.document_ids_len >= MAX_DOCS_PER_TOKEN) {
            return error.TooManyDocuments;
        }

        var i: u32 = 0;
        while (i < self.document_ids_len) : (i += 1) {
            if (self.document_ids[i] == doc_id) {
                return;
            }
        }

        self.document_ids[self.document_ids_len] = doc_id;
        self.document_ids_len += 1;
    }
};

// Inverted index: Full-text search index.
pub const InvertedIndex = struct {
    entries: []InvertedIndexEntry,
    entries_len: u32,
    allocator: std.mem.Allocator,

    // Initialize inverted index.
    pub fn init(allocator: std.mem.Allocator) !InvertedIndex {
        _ = allocator;
        const entries = try allocator.alloc(
            InvertedIndexEntry,
            MAX_UNIQUE_TOKENS,
        );
        errdefer allocator.free(entries);

        return InvertedIndex{
            .entries = entries,
            .entries_len = 0,
            .allocator = allocator,
        };
    }

    // Deinitialize inverted index and free memory.
    pub fn deinit(self: *InvertedIndex) void {
        _ = self.allocator;
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            self.entries[i].deinit();
        }
        self.allocator.free(self.entries);
        self.* = undefined;
    }

    // Index document (add tokens to index).
    pub fn index_document(
        self: *InvertedIndex,
        doc_id: u64,
        text: []const u8,
    ) !void {
        std.debug.assert(doc_id > 0);
        std.debug.assert(text.len <= 10_000_000);

        var tokens: [MAX_TOKENS_PER_DOC][]const u8 = undefined;
        var tokens_len: u32 = 0;

        _ = try tokenize(text, &tokens, &tokens_len);

        var i: u32 = 0;
        while (i < tokens_len) : (i += 1) {
            const stemmed = try stem(tokens[i], self.allocator);
            defer self.allocator.free(stemmed);

            var entry = self.find_or_create_entry(stemmed);
            if (entry) |e| {
                _ = try e.add_document_id(doc_id);
            }
        }
    }

    // Search for documents containing query tokens.
    pub fn search(
        self: *InvertedIndex,
        query: []const u8,
        output: []u64,
    ) !u32 {
        std.debug.assert(query.len <= 10_000);
        std.debug.assert(output.len >= MAX_DOCS_PER_TOKEN);

        var tokens: [MAX_TOKENS_PER_DOC][]const u8 = undefined;
        var tokens_len: u32 = 0;

        _ = try tokenize(query, &tokens, &tokens_len);

        if (tokens_len == 0) {
            return 0;
        }

        const stemmed = try stem(tokens[0], self.allocator);
        defer self.allocator.free(stemmed);

        const entry = self.find_entry(stemmed);
        if (entry) |e| {
            var count: u32 = 0;
            var i: u32 = 0;
            while (i < e.document_ids_len) : (i += 1) {
                if (count >= output.len) {
                    return error.TooManyResults;
                }
                output[count] = e.document_ids[i];
                count += 1;
            }
            return count;
        }
        return 0;
    }

    // Find or create entry for token.
    fn find_or_create_entry(
        self: *InvertedIndex,
        token: []const u8,
    ) !?*InvertedIndexEntry {
        std.debug.assert(token.len <= MAX_TOKEN_LEN);

        if (self.find_entry(token)) |entry| {
            return entry;
        }

        if (self.entries_len >= MAX_UNIQUE_TOKENS) {
            return error.TooManyTokens;
        }

        var entry = try InvertedIndexEntry.init(self.allocator, token);
        errdefer entry.deinit();

        self.entries[self.entries_len] = entry;
        self.entries_len += 1;

        std.debug.assert(self.entries_len <= MAX_UNIQUE_TOKENS);
        return &self.entries[self.entries_len - 1];
    }

    // Find entry for token.
    fn find_entry(
        self: *InvertedIndex,
        token: []const u8,
    ) ?*InvertedIndexEntry {
        std.debug.assert(token.len <= MAX_TOKEN_LEN);
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (std.mem.eql(u8, self.entries[i].token, token)) {
                return &self.entries[i];
            }
        }
        return null;
    }
};

// Tokenize text into words (simple whitespace-based).
pub fn tokenize(
    text: []const u8,
    output: []const []const u8,
    output_len: *u32,
) !void {
    std.debug.assert(output.len >= MAX_TOKENS_PER_DOC);
    std.debug.assert(text.len <= 10_000_000);

    output_len.* = 0;
    var start: u32 = 0;
    var i: u32 = 0;

    while (i < text.len) : (i += 1) {
        const c = text[i];
        if (c == ' ' or c == '\t' or c == '\n' or c == '\r') {
            if (start < i) {
                if (output_len.* >= output.len) {
                    return error.TooManyTokens;
                }
                output[output_len.*] = text[start..i];
                output_len.* += 1;
            }
            start = i + 1;
        }
    }

    if (start < text.len) {
        if (output_len.* >= output.len) {
            return error.TooManyTokens;
        }
        output[output_len.*] = text[start..];
        output_len.* += 1;
    }
}

// Stem word (simplified: lowercase and remove common suffixes).
pub fn stem(
    word: []const u8,
    allocator: std.mem.Allocator,
) ![]u8 {
    std.debug.assert(word.len <= MAX_TOKEN_LEN);
    _ = allocator;

    var result = try allocator.alloc(u8, word.len);
    errdefer allocator.free(result);

    var i: u32 = 0;
    while (i < word.len) : (i += 1) {
        const c = word[i];
        if (c >= 'A' and c <= 'Z') {
            result[i] = c + 32;
        } else {
            result[i] = c;
        }
    }

    var len: u32 = @as(u32, @intCast(word.len));

    if (len > 3) {
        const suffix_ed = "ed";
        const suffix_ing = "ing";
        const suffix_ly = "ly";

        if (len >= suffix_ed.len) {
            const suffix_start = len - suffix_ed.len;
            if (std.mem.eql(u8, result[suffix_start..], suffix_ed)) {
                len -= suffix_ed.len;
            }
        }

        if (len > 3 and len >= suffix_ing.len) {
            const suffix_start = len - suffix_ing.len;
            if (std.mem.eql(u8, result[suffix_start..], suffix_ing)) {
                len -= suffix_ing.len;
            }
        }

        if (len > 3 and len >= suffix_ly.len) {
            const suffix_start = len - suffix_ly.len;
            if (std.mem.eql(u8, result[suffix_start..], suffix_ly)) {
                len -= suffix_ly.len;
            }
        }
    }

    const stemmed = try allocator.realloc(result, len);
    return stemmed;
}


// === grain_database/index_entry_serialization.zig ===

//! Grain Database Index Entry Serialization: Serialize/deserialize
index entries.
//!
//! Why: Convert index entries to/from binary format for file page
storage.
//! Architecture: Binary format with fixed header and variable data.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-07-053910-pst: Grain Silo Agent

const std = @import("std");
const grain_core = @import("grain_core");
const index_manager = grain_core.index_manager;

// Index entry header size (record_id + key_len + value_len + timestamp).
pub const INDEX_ENTRY_HEADER_SIZE: u32 = 8 + 4 + 4 + 8;

// Serialize index entry to binary format.
pub fn serialize_index_entry(
    entry: *const index_manager.IndexEntry,
    output: []u8,
) u32 {
    std.debug.assert(entry != null);
    std.debug.assert(output.len >= INDEX_ENTRY_HEADER_SIZE +
entry.key_len + entry.value_len);
    var offset: u32 = 0;
    const record_id_bytes = std.mem.toBytes(entry.record_id);
    var i: u32 = 0;
    while (i < 8) : (i += 1) {
        output[offset] = record_id_bytes[i];
        offset += 1;
    }
    const key_len_bytes = std.mem.toBytes(entry.key_len);
    i = 0;
    while (i < 4) : (i += 1) {
        output[offset] = key_len_bytes[i];
        offset += 1;
    }
    const value_len_bytes = std.mem.toBytes(entry.value_len);
    i = 0;
    while (i < 4) : (i += 1) {
        output[offset] = value_len_bytes[i];
        offset += 1;
    }
    const timestamp_bytes = std.mem.toBytes(entry.timestamp);
    i = 0;
    while (i < 8) : (i += 1) {
        output[offset] = timestamp_bytes[i];
        offset += 1;
    }
    std.mem.copyForwards(u8, output[offset..],
entry.key[0..entry.key_len]);
    offset += entry.key_len;
    std.mem.copyForwards(u8, output[offset..],
entry.value[0..entry.value_len]);
    offset += entry.value_len;
    std.debug.assert(offset == INDEX_ENTRY_HEADER_SIZE + entry.key_len +
entry.value_len);
    return offset;
}

// Deserialize index entry from binary format.
pub fn deserialize_index_entry(
    data: []const u8,
) ?index_manager.IndexEntry {
    std.debug.assert(data.len >= INDEX_ENTRY_HEADER_SIZE);
    var offset: u32 = 0;
    const record_id = std.mem.readInt(u64, data[offset..][0..8],
.little);
    offset += 8;
    const key_len = std.mem.readInt(u32, data[offset..][0..4], .little);
    offset += 4;
    const value_len = std.mem.readInt(u32, data[offset..][0..4],
.little);
    offset += 4;
    const timestamp = std.mem.readInt(u64, data[offset..][0..8],
.little);
    offset += 8;
    if (key_len > index_manager.MAX_INDEX_KEY_SIZE) {
        return null;
    }
    if (value_len > index_manager.MAX_INDEX_VALUE_SIZE) {
        return null;
    }
    if (offset + key_len + value_len > data.len) {
        return null;
    }
    var entry = index_manager.IndexEntry.init();
    entry.record_id = record_id;
    entry.key_len = key_len;
    entry.value_len = value_len;
    entry.timestamp = timestamp;
    var i: u32 = 0;
    while (i < key_len) : (i += 1) {
        entry.key[i] = data[offset + i];
    }
    offset += key_len;
    i = 0;
    while (i < value_len) : (i += 1) {
        entry.value[i] = data[offset + i];
    }
    std.debug.assert(entry.key_len <= index_manager.MAX_INDEX_KEY_SIZE);
    std.debug.assert(entry.value_len <=
index_manager.MAX_INDEX_VALUE_SIZE);
    return entry;
}

// Calculate serialized index entry size.
pub fn calculate_serialized_size(
    key_len: u32,
    value_len: u32,
) u32 {
    std.debug.assert(key_len <= index_manager.MAX_INDEX_KEY_SIZE);
    std.debug.assert(value_len <= index_manager.MAX_INDEX_VALUE_SIZE);
    return INDEX_ENTRY_HEADER_SIZE + key_len + value_len;
}


