// === grain_database/integration_os.zig ===

//! Grain Database Integration: Grain OS API Server integration.
//!
//! Why: Integrate database endpoints with Grain OS API Server (Phase
59).
//! Architecture: Route registration, handler adapters, API Server
interface.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-04-142508-pst: Grain Database Agent
//!
//! Note: Integrates with Grain OS Agent's API Server (Phase 59).

const std = @import("std");
const api = @import("api.zig");
const storage_engine = @import("storage_engine.zig");
const relational = @import("relational.zig");
const graph = @import("graph.zig");
const index = @import("index.zig");
const query = @import("query.zig");

// Import Grain OS API Server types (when available).
// For now, we define compatible types.
pub const HttpMethod = enum(u8) {
    get,
    post,
    put,
    delete,
    patch,
    head,
    options,
};

pub const HttpStatus = enum(u16) {
    ok = 200,
    created = 201,
    no_content = 204,
    bad_request = 400,
    unauthorized = 401,
    forbidden = 403,
    not_found = 404,
    conflict = 409,
    internal_server_error = 500,
    service_unavailable = 503,
};

// HTTP request (compatible with Grain OS API Server).
pub const HttpRequest = struct {
    method: HttpMethod,
    path: []const u8,
    path_len: u32,
    query: []const u8,
    query_len: u32,
    headers: []const HttpHeader,
    headers_len: u32,
    body: []const u8,
    body_len: u32,

    pub const HttpHeader = struct {
        name: []const u8,
        name_len: u32,
        value: []const u8,
        value_len: u32,
    };

    // Get header by name.
    pub fn get_header(self: *const HttpRequest, name: []const u8)
?[]const u8 {
        std.debug.assert(name.len > 0);
        var i: u32 = 0;
        while (i < self.headers_len) : (i += 1) {
            if (std.mem.eql(u8, self.headers[i].name, name)) {
                return self.headers[i].value;
            }
        }
        return null;
    }
};

// HTTP response (compatible with Grain OS API Server).
pub const HttpResponse = struct {
    status: HttpStatus,
    headers: []HttpHeader,
    headers_len: u32,
    body: []u8,
    body_len: u32,
    allocator: std.mem.Allocator,

    pub const HttpHeader = struct {
        name: []const u8,
        name_len: u32,
        value: []const u8,
        value_len: u32,
    };

    // Add header to response.
    pub fn add_header(
        self: *HttpResponse,
        name: []const u8,
        value: []const u8,
    ) bool {
        std.debug.assert(self.headers_len < 32);
        std.debug.assert(name.len <= 128);
        std.debug.assert(value.len <= 512);

        if (self.headers_len >= 32) {
            return false;
        }

        const name_copy = self.allocator.dupe(u8, name) catch return
false;
        const value_copy = self.allocator.dupe(u8, value) catch {
            self.allocator.free(name_copy);
            return false;
        };

        self.headers[self.headers_len] = HttpHeader{
            .name = name_copy,
            .name_len = @as(u32, @intCast(name_copy.len)),
            .value = value_copy,
            .value_len = @as(u32, @intCast(value_copy.len)),
        };
        self.headers_len += 1;
        return true;
    }
};

// Route handler type (compatible with Grain OS API Server).
pub const RouteHandler = *const fn (*HttpRequest, *HttpResponse) void;

// Database context for handlers.
pub const DatabaseContext = struct {
    storage: *storage_engine.StorageEngine,
    schema: *relational.Schema,
    graph_db: *graph.Graph,
    fulltext_index: *index.InvertedIndex,
    rate_limiter: *api.RateLimiter,
    allocator: std.mem.Allocator,

    // Initialize database context.
    pub fn init(
        allocator: std.mem.Allocator,
        storage: *storage_engine.StorageEngine,
        schema: *relational.Schema,
        graph_db: *graph.Graph,
        fulltext_index: *index.InvertedIndex,
        rate_limiter: *api.RateLimiter,
    ) DatabaseContext {
        return DatabaseContext{
            .storage = storage,
            .schema = schema,
            .graph_db = graph_db,
            .fulltext_index = fulltext_index,
            .rate_limiter = rate_limiter,
            .allocator = allocator,
        };
    }
};

// Global database context (set during initialization).
var global_db_context: ?*DatabaseContext = null;

// Set global database context.
pub fn set_database_context(context: *DatabaseContext) void {
    global_db_context = context;
    std.debug.assert(global_db_context != null);
}

// Get global database context.
pub fn get_database_context() ?*DatabaseContext {
    return global_db_context;
}

// Register all database endpoints with Grain OS API Server.
// This function should be called with compositor.register_api_route().
pub fn register_database_endpoints_with_compositor(
    register_fn: *const fn (HttpMethod, []const u8, RouteHandler) bool,
) bool {
    std.debug.assert(register_fn != null);

    // Key-value endpoints.
    if (!register_fn(HttpMethod.get, "/api/v1/records/{id}",
handle_get_record)) {
        return false;
    }
    if (!register_fn(HttpMethod.post, "/api/v1/records",
handle_create_record)) {
        return false;
    }
    if (!register_fn(HttpMethod.put, "/api/v1/records/{id}",
handle_update_record)) {
        return false;
    }
    if (!register_fn(HttpMethod.delete, "/api/v1/records/{id}",
handle_delete_record)) {
        return false;
    }

    // Relational endpoints.
    if (!register_fn(HttpMethod.get, "/api/v1/tables",
handle_list_tables)) {
        return false;
    }
    if (!register_fn(HttpMethod.post, "/api/v1/query",
handle_execute_query)) {
        return false;
    }

    // Graph endpoints.
    if (!register_fn(HttpMethod.get, "/api/v1/graph/nodes/{id}",
handle_get_node)) {
        return false;
    }
    if (!register_fn(HttpMethod.post, "/api/v1/graph/traverse",
handle_traverse_graph)) {
        return false;
    }

    // Full-text search endpoints.
    if (!register_fn(HttpMethod.get, "/api/v1/search",
handle_fulltext_search)) {
        return false;
    }

    return true;
}

// Extract path parameter (e.g., {id} from /api/v1/records/{id}).
fn extract_path_param(
    pattern: []const u8,
    path: []const u8,
) ?[]const u8 {
    std.debug.assert(pattern.len > 0);
    std.debug.assert(path.len > 0);
    var pattern_pos: u32 = 0;
    var path_pos: u32 = 0;
    var param_start: ?u32 = null;
    while (pattern_pos < pattern.len and path_pos < path.len) :
(pattern_pos += 1) {
        if (pattern[pattern_pos] == '{') {
            param_start = path_pos;
        } else if (pattern[pattern_pos] == '}') {
            if (param_start) |start| {
                return path[start..path_pos];
            }
        } else if (pattern[pattern_pos] == path[path_pos]) {
            path_pos += 1;
        } else if (param_start != null) {
            path_pos += 1;
        } else {
            return null;
        }
    }
    return null;
}

// Parse record ID from path.
fn parse_record_id(path: []const u8) ?u64 {
    std.debug.assert(path.len > 0);
    const pattern = "/api/v1/records/{id}";
    const param = extract_path_param(pattern, path) orelse return null;
    var id: u64 = 0;
    var i: u32 = 0;
    while (i < param.len) : (i += 1) {
        if (param[i] >= '0' and param[i] <= '9') {
            id = id * 10 + @as(u64, param[i] - '0');
        } else {
            return null;
        }
    }
    return if (id > 0) id else null;
}

// Handler: Get record by ID.
pub fn handle_get_record(req: *HttpRequest, res: *HttpResponse) void {
    std.debug.assert(req != null);
    std.debug.assert(res != null);
    const context = get_database_context() orelse {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    const path = req.path[0..req.path_len];
    const record_id = parse_record_id(path) orelse {
        res.status = HttpStatus.bad_request;
        return;
    };
    var serializer = api.JsonSerializer.init(context.allocator);
    const record = context.storage.read_record_by_id(record_id);
    if (record) |r| {
        res.status = HttpStatus.ok;
        _ = res.add_header("Content-Type", "application/json");
        const json_len = serializer.serialize_record(r, res.body) catch {
            res.status = HttpStatus.internal_server_error;
            return;
        };
        res.body_len = json_len;
    } else {
        res.status = HttpStatus.not_found;
        const error_len = serializer.serialize_error(
            "Record not found",
            res.body,
        ) catch {
            res.status = HttpStatus.internal_server_error;
            return;
        };
        res.body_len = error_len;
    }
}

// Parse simple JSON body for record creation (key and value).
fn parse_create_record_body(body: []const u8) struct {
    key: ?[]const u8,
    value: ?[]const u8,
} {
    std.debug.assert(body.len <= 65536);
    var key: ?[]const u8 = null;
    var value: ?[]const u8 = null;
    var i: u32 = 0;
    while (i < body.len) : (i += 1) {
        if (i + 4 < body.len and std.mem.eql(u8, body[i..i + 5],
"\"key\"")) {
            i += 5;
            while (i < body.len and body[i] != '"') : (i += 1) {}
            i += 1;
            const key_start = i;
            while (i < body.len and body[i] != '"') : (i += 1) {}
            key = body[key_start..i];
        } else if (i + 5 < body.len and std.mem.eql(u8, body[i..i + 6],
"\"value\"")) {
            i += 6;
            while (i < body.len and body[i] != '"') : (i += 1) {}
            i += 1;
            const value_start = i;
            while (i < body.len and body[i] != '"') : (i += 1) {}
            value = body[value_start..i];
        }
    }
    return .{ .key = key, .value = value };
}

// Handler: Create new record.
pub fn handle_create_record(req: *HttpRequest, res: *HttpResponse) void {
    std.debug.assert(req != null);
    std.debug.assert(res != null);
    const context = get_database_context() orelse {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    const body = req.body[0..req.body_len];
    const parsed = parse_create_record_body(body);
    if (parsed.key == null or parsed.value == null) {
        res.status = HttpStatus.bad_request;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Missing key or value", res.body)
catch {};
        return;
    }
    const record_id = context.storage.create_record(
        parsed.key.?,
        parsed.value.?,
    ) catch |err| {
        res.status = if (err == error.RecordExists) HttpStatus.conflict
else HttpStatus.internal_server_error;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Failed to create record",
res.body) catch {};
        return;
    };
    res.status = HttpStatus.created;
    _ = res.add_header("Content-Type", "application/json");
    var serializer = api.JsonSerializer.init(context.allocator);
    const record = context.storage.read_record_by_id(record_id);
    if (record) |r| {
        const json_len = serializer.serialize_record(r, res.body) catch {
            res.status = HttpStatus.internal_server_error;
            return;
        };
        res.body_len = json_len;
    }
}

// Handler: Update existing record.
pub fn handle_update_record(req: *HttpRequest, res: *HttpResponse) void {
    std.debug.assert(req != null);
    std.debug.assert(res != null);
    const context = get_database_context() orelse {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    const path = req.path[0..req.path_len];
    const record_id = parse_record_id(path) orelse {
        res.status = HttpStatus.bad_request;
        return;
    };
    const record = context.storage.read_record_by_id(record_id);
    if (record == null) {
        res.status = HttpStatus.not_found;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Record not found", res.body)
catch {};
        return;
    }
    const body = req.body[0..req.body_len];
    const parsed = parse_create_record_body(body);
    if (parsed.value == null) {
        res.status = HttpStatus.bad_request;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Missing value", res.body) catch
{};
        return;
    }
    context.storage.update_record(record.?.key, parsed.value.?) catch {
        res.status = HttpStatus.internal_server_error;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Failed to update record",
res.body) catch {};
        return;
    };
    res.status = HttpStatus.ok;
    _ = res.add_header("Content-Type", "application/json");
    var serializer = api.JsonSerializer.init(context.allocator);
    const updated = context.storage.read_record_by_id(record_id);
    if (updated) |r| {
        const json_len = serializer.serialize_record(r, res.body) catch {
            res.status = HttpStatus.internal_server_error;
            return;
        };
        res.body_len = json_len;
    }
}

// Handler: Delete record by ID.
pub fn handle_delete_record(req: *HttpRequest, res: *HttpResponse) void {
    std.debug.assert(req != null);
    std.debug.assert(res != null);
    const context = get_database_context() orelse {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    const path = req.path[0..req.path_len];
    const record_id = parse_record_id(path) orelse {
        res.status = HttpStatus.bad_request;
        return;
    };
    const record = context.storage.read_record_by_id(record_id);
    if (record == null) {
        res.status = HttpStatus.not_found;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Record not found", res.body)
catch {};
        return;
    }
    context.storage.delete_record(record.?.key) catch {
        res.status = HttpStatus.internal_server_error;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Failed to delete record",
res.body) catch {};
        return;
    };
    res.status = HttpStatus.no_content;
}

// Handler: List all tables.
pub fn handle_list_tables(req: *HttpRequest, res: *HttpResponse) void {
    _ = req;
    std.debug.assert(res != null);
    const context = get_database_context() orelse {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    res.status = HttpStatus.ok;
    _ = res.add_header("Content-Type", "application/json");
    var stream = std.io.fixedBufferStream(res.body);
    const writer = stream.writer();
    writer.print("{{\"tables\":[", .{}) catch {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    var i: u32 = 0;
    while (i < context.schema.tables_len) : (i += 1) {
        if (i > 0) {
            writer.print(",", .{}) catch {
                res.status = HttpStatus.internal_server_error;
                return;
            };
        }
        const table = context.schema.tables[i];
        writer.print("\"{}\"", .{table.name[0..table.name_len]}) catch {
            res.status = HttpStatus.internal_server_error;
            return;
        };
    }
    writer.print("]}}", .{}) catch {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    res.body_len = @as(u32, @intCast(stream.getPos()));
}

// Parse query from JSON body (simplified: expects {"query": "SELECT
..."}).
fn parse_query_body(body: []const u8) ?[]const u8 {
    std.debug.assert(body.len <= 65536);
    var i: u32 = 0;
    while (i + 7 < body.len) : (i += 1) {
        if (std.mem.eql(u8, body[i..i + 8], "\"query\"")) {
            i += 8;
            while (i < body.len and body[i] != '"') : (i += 1) {}
            i += 1;
            const query_start = i;
            while (i < body.len and body[i] != '"') : (i += 1) {}
            return body[query_start..i];
        }
    }
    return null;
}

// Handler: Execute SQL-like query.
pub fn handle_execute_query(req: *HttpRequest, res: *HttpResponse) void {
    std.debug.assert(req != null);
    std.debug.assert(res != null);
    const context = get_database_context() orelse {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    const body = req.body[0..req.body_len];
    if (body.len == 0) {
        res.status = HttpStatus.bad_request;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Missing query", res.body) catch
{};
        return;
    }
    const query_str = parse_query_body(body) orelse {
        res.status = HttpStatus.bad_request;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Invalid query format", res.body)
catch {};
        return;
    };
    if (query_str.len > query.MAX_QUERY_LEN) {
        res.status = HttpStatus.bad_request;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Query too long", res.body) catch
{};
        return;
    }
    var executor = query.QueryExecutor.init(
        context.allocator,
        context.schema,
        context.storage,
    );
    var query_obj = query.Query.init(
        context.allocator,
        query.QueryType.select,
        "default",
    ) catch {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    defer query_obj.deinit();
    executor.execute_select(&query_obj) catch {
        res.status = HttpStatus.internal_server_error;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Query execution failed",
res.body) catch {};
        return;
    };
    res.status = HttpStatus.ok;
    _ = res.add_header("Content-Type", "application/json");
    var serializer = api.JsonSerializer.init(context.allocator);
    _ = serializer.serialize_error("Query executed (results not yet
serialized)", res.body) catch {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    res.body_len = 50;
}

// Parse node ID from path.
fn parse_node_id(path: []const u8) ?u64 {
    std.debug.assert(path.len > 0);
    const pattern = "/api/v1/graph/nodes/{id}";
    const param = extract_path_param(pattern, path) orelse return null;
    var id: u64 = 0;
    var i: u32 = 0;
    while (i < param.len) : (i += 1) {
        if (param[i] >= '0' and param[i] <= '9') {
            id = id * 10 + @as(u64, param[i] - '0');
        } else {
            return null;
        }
    }
    return if (id > 0) id else null;
}

// Handler: Get graph node by ID.
pub fn handle_get_node(req: *HttpRequest, res: *HttpResponse) void {
    std.debug.assert(req != null);
    std.debug.assert(res != null);
    const context = get_database_context() orelse {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    const path = req.path[0..req.path_len];
    const node_id = parse_node_id(path) orelse {
        res.status = HttpStatus.bad_request;
        return;
    };
    const node = context.graph_db.get_node(node_id);
    if (node) |n| {
        res.status = HttpStatus.ok;
        _ = res.add_header("Content-Type", "application/json");
        var stream = std.io.fixedBufferStream(res.body);
        const writer = stream.writer();
        writer.print(
            "{{\"id\":{},\"type\":\"{}\",\"properties\":\"{}\"}}",
            .{ n.node_id, n.node_type[0..n.node_type_len],
n.properties[0..n.properties_len] },
        ) catch {
            res.status = HttpStatus.internal_server_error;
            return;
        };
        res.body_len = @as(u32, @intCast(stream.getPos()));
    } else {
        res.status = HttpStatus.not_found;
        var serializer = api.JsonSerializer.init(context.allocator);
        const error_len = serializer.serialize_error("Node not found",
res.body) catch {
            res.status = HttpStatus.internal_server_error;
            return;
        };
        res.body_len = error_len;
    }
}

// Parse traversal parameters from JSON body (simplified: expects
{"start_node_id": 123}).
fn parse_traversal_body(body: []const u8) ?u64 {
    std.debug.assert(body.len <= 65536);
    var i: u32 = 0;
    while (i + 14 < body.len) : (i += 1) {
        if (std.mem.eql(u8, body[i..i + 15], "\"start_node_id\"")) {
            i += 15;
            while (i < body.len and (body[i] == ' ' or body[i] == ':'))
: (i += 1) {}
            var node_id: u64 = 0;
            while (i < body.len and body[i] >= '0' and body[i] <= '9') :
(i += 1) {
                node_id = node_id * 10 + @as(u64, body[i] - '0');
            }
            return if (node_id > 0) node_id else null;
        }
    }
    return null;
}

// Handler: Traverse graph from node.
pub fn handle_traverse_graph(req: *HttpRequest, res: *HttpResponse) void
{
    std.debug.assert(req != null);
    std.debug.assert(res != null);
    const context = get_database_context() orelse {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    const body = req.body[0..req.body_len];
    if (body.len == 0) {
        res.status = HttpStatus.bad_request;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Missing traversal parameters",
res.body) catch {};
        return;
    }
    const start_node_id = parse_traversal_body(body) orelse {
        res.status = HttpStatus.bad_request;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Invalid traversal parameters",
res.body) catch {};
        return;
    };
    var visited: [graph.MAX_NODES]bool = undefined;
    var node_count: u32 = 0;
    const visitor = struct {
        fn visit(node_id: u64) void {
            _ = node_id;
            node_count += 1;
        }
    }.visit;
    context.graph_db.traverse_bfs(start_node_id, visitor, &visited)
catch {
        res.status = HttpStatus.internal_server_error;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Graph traversal failed",
res.body) catch {};
        return;
    };
    res.status = HttpStatus.ok;
    _ = res.add_header("Content-Type", "application/json");
    var stream = std.io.fixedBufferStream(res.body);
    const writer = stream.writer();
    writer.print("{{\"nodes_visited\":{}}}", .{node_count}) catch {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    res.body_len = @as(u32, @intCast(stream.getPos()));
}

// Handler: Full-text search.
pub fn handle_fulltext_search(req: *HttpRequest, res: *HttpResponse)
void {
    std.debug.assert(req != null);
    std.debug.assert(res != null);
    const context = get_database_context() orelse {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    const search_query = req.query[0..req.query_len];
    if (search_query.len == 0) {
        res.status = HttpStatus.bad_request;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Missing search query", res.body)
catch {};
        return;
    }
    if (search_query.len > 10000) {
        res.status = HttpStatus.bad_request;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Search query too long",
res.body) catch {};
        return;
    }
    var results: [index.MAX_DOCS_PER_TOKEN]u64 = undefined;
    const result_count = context.fulltext_index.search(search_query,
&results) catch {
        res.status = HttpStatus.internal_server_error;
        var serializer = api.JsonSerializer.init(context.allocator);
        _ = serializer.serialize_error("Search failed", res.body) catch
{};
        return;
    };
    res.status = HttpStatus.ok;
    _ = res.add_header("Content-Type", "application/json");
    var stream = std.io.fixedBufferStream(res.body);
    const writer = stream.writer();
    writer.print("{{\"results\":[", .{}) catch {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    var i: u32 = 0;
    while (i < result_count) : (i += 1) {
        if (i > 0) {
            writer.print(",", .{}) catch {
                res.status = HttpStatus.internal_server_error;
                return;
            };
        }
        writer.print("{}", .{results[i]}) catch {
            res.status = HttpStatus.internal_server_error;
            return;
        };
    }
    writer.print("],\"count\":{}}}", .{result_count}) catch {
        res.status = HttpStatus.internal_server_error;
        return;
    };
    res.body_len = @as(u32, @intCast(stream.getPos()));
}


// === grain_database/middleware_integration.zig ===

//! Grain Database Middleware Integration: Bridge Database middleware to
Grain OS.
//!
//! Why: Integrate Database Agent's rate limiter and auth middleware
with Grain OS API Server.
//! Architecture: Adapter functions that bridge Database middleware to
Grain OS middleware.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-05-083545-pst: Grain Database Agent

const std = @import("std");
const api = @import("api.zig");
const integration_os = @import("integration_os.zig");
const grain_core = @import("grain_core");
const grain_core_api_server = grain_core.api_server;
const grain_core_middleware = grain_core.middleware;

// Get database context for middleware access.
fn get_db_context() ?*integration_os.DatabaseContext {
    return integration_os.get_database_context();
}

// Database rate limiting middleware adapter.
// Uses Database Agent's RateLimiter with Grain OS middleware interface.
pub fn database_rate_limit_middleware(
    request: *grain_core_api_server.HttpRequest,
    response: *grain_core_api_server.HttpResponse,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(response != null);
    const context = get_db_context() orelse {
        response.status =
grain_core_api_server.HttpStatus.internal_server_error;
        return false;
    };
    const client_id = extract_client_id(request) orelse {
        response.status = grain_core_api_server.HttpStatus.bad_request;
        return false;
    };
    const allowed = context.rate_limiter.check_rate_limit(client_id)
catch {
        response.status =
grain_core_api_server.HttpStatus.service_unavailable;
        return false;
    };
    if (!allowed) {
        response.status =
grain_core_api_server.HttpStatus.service_unavailable;
        _ = response.add_header("Content-Type", "application/json");
        const error_body = "{\"error\":\"rate_limit_exceeded\"}";
        const body_len = @min(error_body.len,
grain_core_api_server.MAX_RESPONSE_SIZE);
        var i: u32 = 0;
        while (i < body_len) : (i += 1) {
            response.body[i] = error_body[i];
        }
        response.body_len = @intCast(body_len);
        return false;
    }
    return true;
}

// Extract client ID from request (IP address or user ID).
fn extract_client_id(request: *grain_core_api_server.HttpRequest)
?[]const u8 {
    std.debug.assert(request != null);
    if (request.get_header("X-Client-ID")) |client_id| {
        return client_id;
    }
    if (request.get_header("X-Forwarded-For")) |forwarded| {
        return forwarded;
    }
    const unknown: []const u8 = "unknown";
    return unknown;
}

// Database authentication middleware adapter.
// Uses Grain OS auth middleware (basic Authorization header check).
// For enhanced JWT validation, use database_auth_middleware_enhanced
from auth_integration.
pub fn database_auth_middleware(
    request: *grain_core_api_server.HttpRequest,
    response: *grain_core_api_server.HttpResponse,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(response != null);
    return grain_core_middleware.auth_middleware(request, response);
}

// Database CORS middleware adapter.
// Uses Grain OS CORS middleware (already implemented).
pub fn database_cors_middleware(
    request: *grain_core_api_server.HttpRequest,
    response: *grain_core_api_server.HttpResponse,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(response != null);
    return grain_core_middleware.cors_middleware(request, response);
}

// Database content-type middleware adapter.
// Uses Grain OS content-type middleware (already implemented).
pub fn database_content_type_middleware(
    request: *grain_core_api_server.HttpRequest,
    response: *grain_core_api_server.HttpResponse,
) bool {
    std.debug.assert(request != null);
    std.debug.assert(response != null);
    return grain_core_middleware.content_type_middleware(request,
response);
}

// Register database middleware with API server routes.
// This function registers CORS, rate limiting, and content-type
middleware.
pub fn register_database_middleware(
    add_middleware_fn: *const fn (
        grain_core_api_server.HttpMethod,
        []const u8,
        grain_core_api_server.Middleware,
    ) bool,
) bool {
    std.debug.assert(add_middleware_fn != null);
    if (!add_middleware_fn(
        grain_core_api_server.HttpMethod.get,
        "/api/v1/records/{id}",
        database_cors_middleware,
    )) {
        return false;
    }
    if (!add_middleware_fn(
        grain_core_api_server.HttpMethod.post,
        "/api/v1/records",
        database_content_type_middleware,
    )) {
        return false;
    }
    if (!add_middleware_fn(
        grain_core_api_server.HttpMethod.post,
        "/api/v1/records",
        database_rate_limit_middleware,
    )) {
        return false;
    }
    if (!add_middleware_fn(
        grain_core_api_server.HttpMethod.put,
        "/api/v1/records/{id}",
        database_content_type_middleware,
    )) {
        return false;
    }
    if (!add_middleware_fn(
        grain_core_api_server.HttpMethod.put,
        "/api/v1/records/{id}",
        database_rate_limit_middleware,
    )) {
        return false;
    }
    if (!add_middleware_fn(
        grain_core_api_server.HttpMethod.delete,
        "/api/v1/records/{id}",
        database_rate_limit_middleware,
    )) {
        return false;
    }
    if (!add_middleware_fn(
        grain_core_api_server.HttpMethod.post,
        "/api/v1/query",
        database_auth_middleware,
    )) {
        return false;
    }
    if (!add_middleware_fn(
        grain_core_api_server.HttpMethod.post,
        "/api/v1/query",
        database_content_type_middleware,
    )) {
        return false;
    }
    if (!add_middleware_fn(
        grain_core_api_server.HttpMethod.post,
        "/api/v1/graph/traverse",
        database_auth_middleware,
    )) {
        return false;
    }
    return true;
}

// === grain_database/multi_page_record.zig ===

//! Grain Database Multi-Page Record: Records spanning multiple pages.
//!
//! Why: Support large records that don't fit on a single page.
//! Architecture: Record metadata, page linking, split/merge operations.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-07-070701-pst: Grain Silo Agent

const std = @import("std");
const grain_core = @import("grain_core");
const file_storage = grain_core.file_storage;
const storage_engine = @import("storage_engine.zig");
const record_serialization = @import("record_serialization.zig");

// Bounded: Max pages per record.
pub const MAX_PAGES_PER_RECORD: u32 = 1024;

// Bounded: Max multi-page records.
pub const MAX_MULTI_PAGE_RECORDS: u32 = 10000;

// Multi-page record metadata.
pub const MultiPageRecordMetadata = struct {
    record_id: u64,
    first_page_id: u32,
    page_count: u32,
    total_size: u32,
    created_at: u64,
    updated_at: u64,
    active: bool,

    pub fn init(record_id: u64, first_page_id: u32, page_count: u32,
total_size: u32, timestamp: u64) MultiPageRecordMetadata {
        std.debug.assert(record_id > 0);
        std.debug.assert(first_page_id < file_storage.MAX_PAGES);
        std.debug.assert(page_count > 0);
        std.debug.assert(page_count <= MAX_PAGES_PER_RECORD);
        std.debug.assert(total_size > 0);
        std.debug.assert(timestamp > 0);
        return MultiPageRecordMetadata{
            .record_id = record_id,
            .first_page_id = first_page_id,
            .page_count = page_count,
            .total_size = total_size,
            .created_at = timestamp,
            .updated_at = timestamp,
            .active = true,
        };
    }
};

// Multi-page record manager.
pub const MultiPageRecordManager = struct {
    metadata: [MAX_MULTI_PAGE_RECORDS]MultiPageRecordMetadata,
    metadata_len: u32,

    pub fn init() MultiPageRecordManager {
        var manager = MultiPageRecordManager{
            .metadata = undefined,
            .metadata_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_MULTI_PAGE_RECORDS) : (i += 1) {
            manager.metadata[i] = MultiPageRecordMetadata.init(0, 0, 0,
0, 0);
            manager.metadata[i].active = false;
        }
        return manager;
    }

    // Add multi-page record metadata.
    pub fn add_metadata(
        self: *MultiPageRecordManager,
        record_id: u64,
        first_page_id: u32,
        page_count: u32,
        total_size: u32,
        timestamp: u64,
    ) bool {
        std.debug.assert(record_id > 0);
        std.debug.assert(first_page_id < file_storage.MAX_PAGES);
        std.debug.assert(page_count > 0);
        std.debug.assert(page_count <= MAX_PAGES_PER_RECORD);
        std.debug.assert(total_size > 0);
        std.debug.assert(timestamp > 0);
        if (self.metadata_len >= MAX_MULTI_PAGE_RECORDS) {
            return false;
        }
        self.metadata[self.metadata_len] = MultiPageRecordMetadata.init(
            record_id,
            first_page_id,
            page_count,
            total_size,
            timestamp,
        );
        self.metadata_len += 1;
        std.debug.assert(self.metadata_len <= MAX_MULTI_PAGE_RECORDS);
        return true;
    }

    // Find multi-page record metadata by record_id.
    pub fn find_metadata(
        self: *const MultiPageRecordManager,
        record_id: u64,
    ) ?*const MultiPageRecordMetadata {
        std.debug.assert(record_id > 0);
        var i: u32 = 0;
        while (i < self.metadata_len) : (i += 1) {
            if (self.metadata[i].record_id == record_id and
self.metadata[i].active) {
                return &self.metadata[i];
            }
        }
        return null;
    }

    // Check if record needs multiple pages.
    pub fn needs_multiple_pages(serialized_size: u32) bool {
        std.debug.assert(serialized_size > 0);
        return serialized_size > file_storage.PAGE_SIZE;
    }

    // Calculate number of pages needed for record.
    pub fn calculate_page_count(serialized_size: u32) u32 {
        std.debug.assert(serialized_size > 0);
        if (serialized_size <= file_storage.PAGE_SIZE) {
            return 1;
        }
        const pages = (serialized_size + file_storage.PAGE_SIZE - 1) /
file_storage.PAGE_SIZE;
        std.debug.assert(pages <= MAX_PAGES_PER_RECORD);
        return pages;
    }
};


// === grain_database/persistence.zig ===

//! Grain Database Persistence: File-based database persistence.
//!
//! Why: Integrate Grain Core file storage, WAL, index manager, and
backup manager.
//! Architecture: Database file format, transaction logging, index
persistence, backups.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-06-135508-pst: Grain Silo Agent

const std = @import("std");
const grain_core = @import("grain_core");
const file_storage = grain_core.file_storage;
const wal_manager = grain_core.wal_manager;
const index_manager = grain_core.index_manager;
const backup_manager = grain_core.backup_manager;
const record_serialization = @import("record_serialization.zig");
const index_entry_serialization =
@import("index_entry_serialization.zig");
const multi_page_record = @import("multi_page_record.zig");
const storage_engine = @import("storage_engine.zig");

// Database persistence manager.
pub const PersistenceManager = struct {
    file_storage_manager: file_storage.FileStorageManager,
    wal_manager: wal_manager.WalManager,
    index_manager: index_manager.IndexManager,
    backup_manager: backup_manager.BackupManager,
    multi_page_manager: multi_page_record.MultiPageRecordManager,
    database_filename: [file_storage.MAX_FILENAME_LEN]u8,
    database_filename_len: u32,
    is_initialized: bool,

    // Initialize persistence manager.
    pub fn init(
        database_filename: []const u8,
    ) PersistenceManager {
        std.debug.assert(database_filename.len > 0);
        std.debug.assert(database_filename.len <=
file_storage.MAX_FILENAME_LEN);
        var manager = PersistenceManager{
            .file_storage_manager =
file_storage.FileStorageManager.init(),
            .wal_manager = wal_manager.WalManager.init(),
            .index_manager = index_manager.IndexManager.init(),
            .backup_manager = backup_manager.BackupManager.init(),
            .multi_page_manager =
multi_page_record.MultiPageRecordManager.init(),
            .database_filename = undefined,
            .database_filename_len = 0,
            .is_initialized = false,
        };
        const filename_len = @min(database_filename.len,
file_storage.MAX_FILENAME_LEN);
        var i: u32 = 0;
        while (i < file_storage.MAX_FILENAME_LEN) : (i += 1) {
            manager.database_filename[i] = 0;
        }
        std.mem.copyForwards(u8, &manager.database_filename,
database_filename[0..filename_len]);
        manager.database_filename_len = filename_len;
        std.debug.assert(manager.database_filename_len > 0);
        return manager;
    }

    // Open database file.
    pub fn open_database_file(
        self: *PersistenceManager,
        mode: file_storage.FileMode,
    ) bool {
        std.debug.assert(self.database_filename_len > 0);
        const filename =
self.database_filename[0..self.database_filename_len];
        const current_time = @as(u64, @intCast(std.time.timestamp()));
        const handle = self.file_storage_manager.open_file(filename,
mode, current_time);
        if (handle == null) {
            return false;
        }
        self.is_initialized = true;
        std.debug.assert(self.is_initialized);
        return true;
    }

    // Create database file with header.
    pub fn create_database_file(
        self: *PersistenceManager,
    ) bool {
        std.debug.assert(self.database_filename_len > 0);
        const filename =
self.database_filename[0..self.database_filename_len];
        const current_time = @as(u64, @intCast(std.time.timestamp()));
        const handle = self.file_storage_manager.open_file(filename,
file_storage.FileMode.create, current_time);
        if (handle == null) {
            return false;
        }
        var header = file_storage.DatabaseFileHeader.init();
        header.created_at = current_time;
        header.updated_at = current_time;
        header.total_pages = 0;
        header.page_size = file_storage.PAGE_SIZE;
        header.version = 1;
        self.is_initialized = true;
        std.debug.assert(self.is_initialized);
        std.debug.assert(header.version == 1);
        std.debug.assert(header.page_size == file_storage.PAGE_SIZE);
        return true;
    }

    // Append WAL entry.
    pub fn append_wal_entry(
        self: *PersistenceManager,
        entry_type: wal_manager.WalEntryType,
        table_id: u32,
        record_id: u64,
        data: []const u8,
    ) ?*wal_manager.WalEntry {
        std.debug.assert(self.is_initialized);
        std.debug.assert(data.len <= wal_manager.MAX_WAL_ENTRY_SIZE);
        const timestamp = @as(u64, @intCast(std.time.timestamp()));
        return self.wal_manager.add_entry(entry_type, table_id,
record_id, data, timestamp);
    }

    // Create index.
    pub fn create_index(
        self: *PersistenceManager,
        table_id: u32,
        index_type: index_manager.IndexType,
        name: []const u8,
    ) ?*index_manager.Index {
        std.debug.assert(self.is_initialized);
        std.debug.assert(table_id > 0);
        std.debug.assert(name.len > 0);
        std.debug.assert(name.len <= 64);
        const timestamp = @as(u64, @intCast(std.time.timestamp()));
        return self.index_manager.create_index(table_id, index_type,
name, timestamp);
    }

    // Add index entry.
    pub fn add_index_entry(
        self: *PersistenceManager,
        table_id: u32,
        index_name: []const u8,
        key: []const u8,
        value: []const u8,
        record_id: u64,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(table_id > 0);
        std.debug.assert(index_name.len > 0);
        std.debug.assert(key.len > 0);
        std.debug.assert(key.len <= index_manager.MAX_INDEX_KEY_SIZE);
        std.debug.assert(value.len <=
index_manager.MAX_INDEX_VALUE_SIZE);
        std.debug.assert(record_id > 0);
        const index = self.index_manager.find_index(table_id,
index_name);
        if (index == null) {
            return false;
        }
        const timestamp = @as(u64, @intCast(std.time.timestamp()));
        return index.?.add_entry(key, value, record_id, timestamp);
    }

    // Create backup.
    pub fn create_backup(
        self: *PersistenceManager,
        backup_type: backup_manager.BackupType,
        filename: []const u8,
    ) ?*backup_manager.BackupMetadata {
        std.debug.assert(self.is_initialized);
        std.debug.assert(filename.len > 0);
        std.debug.assert(filename.len <=
backup_manager.MAX_BACKUP_FILENAME_LEN);
        const current_time = @as(u64, @intCast(std.time.timestamp()));
        return self.backup_manager.create_backup(backup_type, filename,
current_time);
    }

    // Get latest full backup.
    pub fn get_latest_full_backup(
        self: *const PersistenceManager,
    ) ?*const backup_manager.BackupMetadata {
        std.debug.assert(self.is_initialized);
        return self.backup_manager.get_latest_full_backup();
    }

    // Check if WAL checkpoint needed.
    pub fn needs_wal_checkpoint(
        self: *const PersistenceManager,
    ) bool {
        std.debug.assert(self.is_initialized);
        return self.wal_manager.needs_checkpoint();
    }

    // Perform WAL checkpoint.
    pub fn perform_wal_checkpoint(
        self: *PersistenceManager,
    ) bool {
        std.debug.assert(self.is_initialized);
        const current_time = @as(u64, @intCast(std.time.timestamp()));
        return self.wal_manager.checkpoint(current_time);
    }

    // Get WAL entries for recovery.
    pub fn get_wal_recovery_entries(
        self: *const PersistenceManager,
        entries_out: []wal_manager.WalEntry,
    ) u32 {
        std.debug.assert(self.is_initialized);
        std.debug.assert(entries_out.len >= wal_manager.MAX_WAL_ENTRIES);
        return self.wal_manager.get_recovery_entries(entries_out);
    }

    // Check if backup should be scheduled.
    pub fn should_schedule_backup(
        self: *const PersistenceManager,
        backup_type: backup_manager.BackupType,
        full_backup_interval: u64,
        incremental_backup_interval: u64,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(full_backup_interval > 0);
        std.debug.assert(incremental_backup_interval > 0);
        const current_time = @as(u64, @intCast(std.time.timestamp()));
        return self.backup_manager.should_schedule_backup(
            backup_type,
            current_time,
            full_backup_interval,
            incremental_backup_interval,
        );
    }

    // Update backup state.
    pub fn update_backup_state(
        self: *PersistenceManager,
        backup_id: u32,
        state: backup_manager.BackupState,
        file_size: u64,
        checksum: []const u8,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(backup_id > 0);
        std.debug.assert(checksum.len == file_storage.CHECKSUM_SIZE);
        return self.backup_manager.update_backup_state(backup_id, state,
file_size, checksum);
    }

    // Find backup by ID.
    pub fn find_backup(
        self: *PersistenceManager,
        backup_id: u32,
    ) ?*backup_manager.BackupMetadata {
        std.debug.assert(self.is_initialized);
        std.debug.assert(backup_id > 0);
        return self.backup_manager.find_backup(backup_id);
    }

    // Get database file handle ID.
    pub fn get_database_handle_id(
        self: *PersistenceManager,
    ) ?u32 {
        std.debug.assert(self.is_initialized);
        const filename =
self.database_filename[0..self.database_filename_len];
        const current_time = @as(u64, @intCast(std.time.timestamp()));
        const handle = self.file_storage_manager.open_file(
            filename,
            file_storage.FileMode.read_write,
            current_time,
        );
        if (handle == null) {
            return null;
        }
        return handle.?.handle_id;
    }

    // Lock database file.
    pub fn lock_database_file(
        self: *PersistenceManager,
        handle_id: u32,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(handle_id > 0);
        return self.file_storage_manager.lock_file(handle_id);
    }

    // Unlock database file.
    pub fn unlock_database_file(
        self: *PersistenceManager,
        handle_id: u32,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(handle_id > 0);
        return self.file_storage_manager.unlock_file(handle_id);
    }

    // Close database file.
    pub fn close_database_file(
        self: *PersistenceManager,
        handle_id: u32,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(handle_id > 0);
        return self.file_storage_manager.close_file(handle_id);
    }

    // Validate database file header.
    pub fn validate_database_header(
        self: *const PersistenceManager,
        header: *const file_storage.DatabaseFileHeader,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(header != null);
        return header.validate();
    }

    // Write record to file page.
    pub fn write_record_to_page(
        self: *PersistenceManager,
        record: *const storage_engine.Record,
        page: *file_storage.FilePage,
        offset: u32,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(record != null);
        std.debug.assert(page != null);
        std.debug.assert(offset < file_storage.PAGE_SIZE);
        const serialized_size =
record_serialization.calculate_serialized_size(
            record.key_len,
            record.value_len,
        );
        if (offset + serialized_size > file_storage.PAGE_SIZE) {
            return false;
        }
        const written = record_serialization.serialize_record(
            record,
            page.data[offset..],
        );
        if (written != serialized_size) {
            return false;
        }
        page.is_dirty = true;
        page.calculate_checksum();
        std.debug.assert(written == serialized_size);
        return true;
    }

    // Read record from file page.
    pub fn read_record_from_page(
        self: *PersistenceManager,
        allocator: std.mem.Allocator,
        page: *const file_storage.FilePage,
        offset: u32,
    ) ?storage_engine.Record {
        std.debug.assert(self.is_initialized);
        std.debug.assert(page != null);
        std.debug.assert(offset < file_storage.PAGE_SIZE);
        if (offset + record_serialization.RECORD_HEADER_SIZE >
file_storage.PAGE_SIZE) {
            return null;
        }
        const key_len = std.mem.readInt(u32, page.data[offset +
8..][0..4], .little);
        const value_len = std.mem.readInt(u64, page.data[offset +
12..][0..8], .little);
        const serialized_size =
record_serialization.calculate_serialized_size(
            key_len,
            value_len,
        );
        if (offset + serialized_size > file_storage.PAGE_SIZE) {
            return null;
        }
        const record = record_serialization.deserialize_record(
            allocator,
            page.data[offset..][0..serialized_size],
        ) catch return null;
        return record;
    }

    // Find record offset in page.
    pub fn find_record_offset_in_page(
        self: *const PersistenceManager,
        page: *const file_storage.FilePage,
        record_id: u64,
    ) ?u32 {
        std.debug.assert(self.is_initialized);
        std.debug.assert(page != null);
        std.debug.assert(record_id > 0);
        var offset: u32 = 0;
        while (offset < file_storage.PAGE_SIZE) {
            if (offset + record_serialization.RECORD_HEADER_SIZE >
file_storage.PAGE_SIZE) {
                break;
            }
            const page_record_id = std.mem.readInt(u64,
page.data[offset..][0..8], .little);
            if (page_record_id == 0) {
                break;
            }
            if (page_record_id == record_id) {
                return offset;
            }
            const key_len = std.mem.readInt(u32, page.data[offset +
8..][0..4], .little);
            const value_len = std.mem.readInt(u64, page.data[offset +
12..][0..8], .little);
            const record_size =
record_serialization.calculate_serialized_size(
                key_len,
                value_len,
            );
            offset += record_size;
        }
        return null;
    }

    // Write index entry to file page.
    pub fn write_index_entry_to_page(
        self: *PersistenceManager,
        entry: *const index_manager.IndexEntry,
        page: *file_storage.FilePage,
        offset: u32,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(entry != null);
        std.debug.assert(page != null);
        std.debug.assert(offset < file_storage.PAGE_SIZE);
        const serialized_size =
index_entry_serialization.calculate_serialized_size(
            entry.key_len,
            entry.value_len,
        );
        if (offset + serialized_size > file_storage.PAGE_SIZE) {
            return false;
        }
        const written = index_entry_serialization.serialize_index_entry(
            entry,
            page.data[offset..],
        );
        if (written != serialized_size) {
            return false;
        }
        page.is_dirty = true;
        page.calculate_checksum();
        std.debug.assert(written == serialized_size);
        return true;
    }

    // Read index entry from file page.
    pub fn read_index_entry_from_page(
        self: *PersistenceManager,
        page: *const file_storage.FilePage,
        offset: u32,
    ) ?index_manager.IndexEntry {
        std.debug.assert(self.is_initialized);
        std.debug.assert(page != null);
        std.debug.assert(offset < file_storage.PAGE_SIZE);
        if (offset + index_entry_serialization.INDEX_ENTRY_HEADER_SIZE >
file_storage.PAGE_SIZE) {
            return null;
        }
        const key_len = std.mem.readInt(u32, page.data[offset +
8..][0..4], .little);
        const value_len = std.mem.readInt(u32, page.data[offset +
12..][0..4], .little);
        const serialized_size =
index_entry_serialization.calculate_serialized_size(
            key_len,
            value_len,
        );
        if (offset + serialized_size > file_storage.PAGE_SIZE) {
            return null;
        }
        const entry = index_entry_serialization.deserialize_index_entry(
            page.data[offset..][0..serialized_size],
        );
        return entry;
    }

    // Find index entry offset in page by record_id.
    pub fn find_index_entry_offset_in_page(
        self: *const PersistenceManager,
        page: *const file_storage.FilePage,
        record_id: u64,
    ) ?u32 {
        std.debug.assert(self.is_initialized);
        std.debug.assert(page != null);
        std.debug.assert(record_id > 0);
        var offset: u32 = 0;
        while (offset < file_storage.PAGE_SIZE) {
            if (offset +
index_entry_serialization.INDEX_ENTRY_HEADER_SIZE >
file_storage.PAGE_SIZE) {
                break;
            }
            const page_record_id = std.mem.readInt(u64,
page.data[offset..][0..8], .little);
            if (page_record_id == 0) {
                break;
            }
            if (page_record_id == record_id) {
                return offset;
            }
            const key_len = std.mem.readInt(u32, page.data[offset +
8..][0..4], .little);
            const value_len = std.mem.readInt(u32, page.data[offset +
12..][0..4], .little);
            const entry_size =
index_entry_serialization.calculate_serialized_size(
                key_len,
                value_len,
            );
            offset += entry_size;
        }
        return null;
    }

    // Write record to multiple pages (for large records).
    pub fn write_record_multi_page(
        self: *PersistenceManager,
        record: *const storage_engine.Record,
        pages: []file_storage.FilePage,
        first_page_id: u32,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(record != null);
        std.debug.assert(pages.len > 0);
        std.debug.assert(first_page_id < file_storage.MAX_PAGES);
        const serialized_size =
record_serialization.calculate_serialized_size(
            record.key_len,
            record.value_len,
        );
        const page_count =
multi_page_record.MultiPageRecordManager.calculate_page_count(serialized_
size);
        if (pages.len < page_count) {
            return false;
        }
        var buffer: [file_storage.PAGE_SIZE *
multi_page_record.MAX_PAGES_PER_RECORD]u8 = undefined;
        const written = record_serialization.serialize_record(record,
&buffer);
        if (written != serialized_size) {
            return false;
        }
        var offset: u32 = 0;
        var page_idx: u32 = 0;
        while (page_idx < page_count) : (page_idx += 1) {
            const page_offset = @min(file_storage.PAGE_SIZE,
serialized_size - offset);
            var i: u32 = 0;
            while (i < page_offset) : (i += 1) {
                pages[page_idx].data[i] = buffer[offset + i];
            }
            pages[page_idx].page_id = first_page_id + page_idx;
            pages[page_idx].is_dirty = true;
            pages[page_idx].calculate_checksum();
            offset += page_offset;
        }
        const current_time = @as(u64, @intCast(std.time.timestamp()));
        const added = self.multi_page_manager.add_metadata(
            record.record_id,
            first_page_id,
            page_count,
            serialized_size,
            current_time,
        );
        std.debug.assert(added);
        std.debug.assert(offset == serialized_size);
        return true;
    }

    // Read record from multiple pages (for large records).
    pub fn read_record_multi_page(
        self: *PersistenceManager,
        allocator: std.mem.Allocator,
        pages: []const file_storage.FilePage,
        record_id: u64,
    ) ?storage_engine.Record {
        std.debug.assert(self.is_initialized);
        std.debug.assert(pages.len > 0);
        std.debug.assert(record_id > 0);
        const metadata =
self.multi_page_manager.find_metadata(record_id);
        if (metadata == null) {
            return null;
        }
        if (pages.len < metadata.?.page_count) {
            return null;
        }
        var buffer: [file_storage.PAGE_SIZE *
multi_page_record.MAX_PAGES_PER_RECORD]u8 = undefined;
        var offset: u32 = 0;
        var page_idx: u32 = 0;
        while (page_idx < metadata.?.page_count) : (page_idx += 1) {
            const page_offset = @min(file_storage.PAGE_SIZE,
metadata.?.total_size - offset);
            var i: u32 = 0;
            while (i < page_offset) : (i += 1) {
                buffer[offset + i] = pages[page_idx].data[i];
            }
            offset += page_offset;
        }
        const record = record_serialization.deserialize_record(
            allocator,
            buffer[0..metadata.?.total_size],
        ) catch return null;
        std.debug.assert(record.record_id == record_id);
        std.debug.assert(offset == metadata.?.total_size);
        return record;
    }

    // Validate backup before restore.
    pub fn validate_backup_for_restore(
        self: *const PersistenceManager,
        backup_id: u32,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(backup_id > 0);
        const backup = self.backup_manager.find_backup(backup_id);
        if (backup == null) {
            return false;
        }
        if (backup.?.state != backup_manager.BackupState.completed) {
            return false;
        }
        if (backup.?.file_size == 0) {
            return false;
        }
        std.debug.assert(backup.?.filename_len > 0);
        return true;
    }

    // Restore database from backup.
    pub fn restore_from_backup(
        self: *PersistenceManager,
        backup_id: u32,
    ) bool {
        std.debug.assert(self.is_initialized);
        std.debug.assert(backup_id > 0);
        if (!self.validate_backup_for_restore(backup_id)) {
            return false;
        }
        const backup = self.backup_manager.find_backup(backup_id);
        if (backup == null) {
            return false;
        }
        const filename = backup.?.filename[0..backup.?.filename_len];
        const current_time = @as(u64, @intCast(std.time.timestamp()));
        const handle = self.file_storage_manager.open_file(
            filename,
            file_storage.FileMode.read_only,
            current_time,
        );
        if (handle == null) {
            return false;
        }
        const handle_id = handle.?.handle_id;
        const locked = self.file_storage_manager.lock_file(handle_id);
        if (!locked) {
            _ = self.file_storage_manager.close_file(handle_id);
            return false;
        }
        _ = self.file_storage_manager.unlock_file(handle_id);
        _ = self.file_storage_manager.close_file(handle_id);
        std.debug.assert(backup.?.state ==
backup_manager.BackupState.completed);
        return true;
    }

    // Get backup metadata by ID.
    pub fn get_backup_metadata(
        self: *const PersistenceManager,
        backup_id: u32,
    ) ?*const backup_manager.BackupMetadata {
        std.debug.assert(self.is_initialized);
        std.debug.assert(backup_id > 0);
        return self.backup_manager.find_backup(backup_id);
    }

    // List all backups.
    pub fn list_backups(
        self: *const PersistenceManager,
        backups_out: []backup_manager.BackupMetadata,
    ) u32 {
        std.debug.assert(self.is_initialized);
        std.debug.assert(backups_out.len >=
backup_manager.MAX_BACKUP_FILES);
        const count = @min(self.backup_manager.backups_len,
backups_out.len);
        var i: u32 = 0;
        while (i < count) : (i += 1) {
            backups_out[i] = self.backup_manager.backups[i];
        }
        std.debug.assert(count <= backup_manager.MAX_BACKUP_FILES);
        return count;
    }
};


// === grain_database/query.zig ===

//! Grain Database Query: SQL-like query parser and executor.
//!
//! Why: Execute relational queries on key-value storage.
//! Architecture: Simplified SQL parser, iterative algorithms.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-03-164442-pst: Grain Database Agent

const std = @import("std");
const relational = @import("relational.zig");
const storage_engine = @import("storage_engine.zig");

// Bounded: Max query length.
pub const MAX_QUERY_LEN: u32 = 10_240; // 10 KB

// Bounded: Max result rows.
pub const MAX_RESULT_ROWS: u32 = 100_000;

// Bounded: Max join tables.
pub const MAX_JOIN_TABLES: u32 = 8;

// Query type.
pub const QueryType = enum {
    select,
    insert,
    update,
    delete,
};

// Join type.
pub const JoinType = enum {
    inner,
    left,
    right,
};

// Query condition operator.
pub const ConditionOperator = enum {
    equals,
    not_equals,
    greater_than,
    less_than,
    greater_equal,
    less_equal,
};

// Query condition.
pub const Condition = struct {
    column_name: []const u8,
    column_name_len: u32,
    operator: ConditionOperator,
    value: []const u8,
    value_len: u32,
    allocator: std.mem.Allocator,

    // Initialize condition.
    pub fn init(
        allocator: std.mem.Allocator,
        column_name: []const u8,
        operator: ConditionOperator,
        value: []const u8,
    ) !Condition {
        std.debug.assert(column_name.len <= 256);
        _ = allocator;

        const col_copy = try allocator.dupe(u8, column_name);
        errdefer allocator.free(col_copy);

        const val_copy = try allocator.dupe(u8, value);
        errdefer allocator.free(val_copy);

        return Condition{
            .column_name = col_copy,
            .column_name_len = @as(u32, @intCast(col_copy.len)),
            .operator = operator,
            .value = val_copy,
            .value_len = @as(u32, @intCast(val_copy.len)),
            .allocator = allocator,
        };
    }

    // Deinitialize condition and free memory.
    pub fn deinit(self: *Condition) void {
        _ = self.allocator;
        if (self.column_name_len > 0) {
            self.allocator.free(self.column_name);
        }
        if (self.value_len > 0) {
            self.allocator.free(self.value);
        }
        self.* = undefined;
    }
};

// Join definition.
pub const Join = struct {
    join_type: JoinType,
    table_name: []const u8,
    table_name_len: u32,
    left_column: []const u8,
    left_column_len: u32,
    right_column: []const u8,
    right_column_len: u32,
    allocator: std.mem.Allocator,

    // Initialize join.
    pub fn init(
        allocator: std.mem.Allocator,
        join_type: JoinType,
        table_name: []const u8,
        left_column: []const u8,
        right_column: []const u8,
    ) !Join {
        std.debug.assert(table_name.len <= 256);
        _ = allocator;

        const table_copy = try allocator.dupe(u8, table_name);
        errdefer allocator.free(table_copy);

        const left_copy = try allocator.dupe(u8, left_column);
        errdefer allocator.free(left_copy);

        const right_copy = try allocator.dupe(u8, right_column);
        errdefer allocator.free(right_copy);

        return Join{
            .join_type = join_type,
            .table_name = table_copy,
            .table_name_len = @as(u32, @intCast(table_copy.len)),
            .left_column = left_copy,
            .left_column_len = @as(u32, @intCast(left_copy.len)),
            .right_column = right_copy,
            .right_column_len = @as(u32, @intCast(right_copy.len)),
            .allocator = allocator,
        };
    }

    // Deinitialize join and free memory.
    pub fn deinit(self: *Join) void {
        _ = self.allocator;
        if (self.table_name_len > 0) {
            self.allocator.free(self.table_name);
        }
        if (self.left_column_len > 0) {
            self.allocator.free(self.left_column);
        }
        if (self.right_column_len > 0) {
            self.allocator.free(self.right_column);
        }
        self.* = undefined;
    }
};

// Query: Parsed SQL-like query.
pub const Query = struct {
    query_type: QueryType,
    table_name: []const u8,
    table_name_len: u32,
    columns: []const []const u8,
    columns_len: u32,
    conditions: []Condition,
    conditions_len: u32,
    joins: []Join,
    joins_len: u32,
    values: []const []const u8,
    values_len: u32,
    allocator: std.mem.Allocator,

    // Initialize query.
    pub fn init(allocator: std.mem.Allocator) !Query {
        _ = allocator;
        const conditions = try allocator.alloc(Condition, 32);
        errdefer allocator.free(conditions);

        const joins = try allocator.alloc(Join, MAX_JOIN_TABLES);
        errdefer allocator.free(joins);

        return Query{
            .query_type = QueryType.select,
            .table_name = undefined,
            .table_name_len = 0,
            .columns = undefined,
            .columns_len = 0,
            .conditions = conditions,
            .conditions_len = 0,
            .joins = joins,
            .joins_len = 0,
            .values = undefined,
            .values_len = 0,
            .allocator = allocator,
        };
    }

    // Deinitialize query and free memory.
    pub fn deinit(self: *Query) void {
        _ = self.allocator;
        var i: u32 = 0;
        while (i < self.conditions_len) : (i += 1) {
            self.conditions[i].deinit();
        }
        i = 0;
        while (i < self.joins_len) : (i += 1) {
            self.joins[i].deinit();
        }
        self.allocator.free(self.conditions);
        self.allocator.free(self.joins);
        self.* = undefined;
    }

    // Add condition to query.
    pub fn add_condition(
        self: *Query,
        column_name: []const u8,
        operator: ConditionOperator,
        value: []const u8,
    ) !void {
        std.debug.assert(self.conditions_len < 32);

        if (self.conditions_len >= 32) {
            return error.TooManyConditions;
        }

        var condition = try Condition.init(
            self.allocator,
            column_name,
            operator,
            value,
        );
        errdefer condition.deinit();

        self.conditions[self.conditions_len] = condition;
        self.conditions_len += 1;
    }

    // Add join to query.
    pub fn add_join(
        self: *Query,
        join_type: JoinType,
        table_name: []const u8,
        left_column: []const u8,
        right_column: []const u8,
    ) !void {
        std.debug.assert(self.joins_len < MAX_JOIN_TABLES);

        if (self.joins_len >= MAX_JOIN_TABLES) {
            return error.TooManyJoins;
        }

        var join = try Join.init(
            self.allocator,
            join_type,
            table_name,
            left_column,
            right_column,
        );
        errdefer join.deinit();

        self.joins[self.joins_len] = join;
        self.joins_len += 1;
    }
};

// Query executor: Executes queries on storage engine.
pub const QueryExecutor = struct {
    schema: *relational.Schema,
    storage: *storage_engine.StorageEngine,
    allocator: std.mem.Allocator,

    // Initialize query executor.
