// === grain_database/storage_engine.zig ===

//! Grain Database Storage Engine: Key-value storage extending Grain
Silo.
//!
//! Why: Extend Grain Silo with database-specific features (indexes,
transactions).
//! Architecture: Key-value foundation with bounded allocations.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-03-163155-pst: Grain Database Agent

const std = @import("std");
const grain_silo = @import("grain_silo");

// Bounded: Max key length (bytes).
pub const MAX_KEY_LEN: u32 = 1_024;

// Bounded: Max value length (bytes).
pub const MAX_VALUE_LEN: u64 = 1_073_741_824; // 1 GB

// Bounded: Max records in storage engine.
pub const MAX_RECORDS: u32 = 10_000_000;

// Record: Key-value pair with metadata.
pub const Record = struct {
    key: []const u8,
    key_len: u32,
    value: []const u8,
    value_len: u64,
    record_id: u64,
    created_at: u64,
    updated_at: u64,
    allocator: std.mem.Allocator,

    // Initialize record.
    pub fn init(
        allocator: std.mem.Allocator,
        key: []const u8,
        value: []const u8,
        record_id: u64,
    ) !Record {
        std.debug.assert(key.len <= MAX_KEY_LEN);
        std.debug.assert(value.len <= MAX_VALUE_LEN);
        std.debug.assert(record_id > 0);

        const key_copy = try allocator.dupe(u8, key);
        errdefer allocator.free(key_copy);

        const value_copy = try allocator.dupe(u8, value);
        errdefer allocator.free(value_copy);

        const now = std.time.timestamp();

        return Record{
            .key = key_copy,
            .key_len = @as(u32, @intCast(key_copy.len)),
            .value = value_copy,
            .value_len = @as(u64, @intCast(value_copy.len)),
            .record_id = record_id,
            .created_at = @as(u64, @intCast(now)),
            .updated_at = @as(u64, @intCast(now)),
            .allocator = allocator,
        };
    }

    // Deinitialize record and free memory.
    pub fn deinit(self: *Record) void {
        _ = self.allocator;
        if (self.key_len > 0) {
            self.allocator.free(self.key);
        }
        if (self.value_len > 0) {
            self.allocator.free(self.value);
        }
        self.* = undefined;
    }
};

// Storage engine: Key-value storage extending Grain Silo.
pub const StorageEngine = struct {
    records: []Record,
    records_len: u32,
    next_record_id: u64,
    silo: grain_silo.Storage.ObjectStorage,
    allocator: std.mem.Allocator,

    // Initialize storage engine.
    pub fn init(
        allocator: std.mem.Allocator,
        hot_cache_size: u64,
    ) !StorageEngine {
        _ = allocator;
        const silo = try grain_silo.Storage.ObjectStorage.init(
            allocator,
            hot_cache_size,
        );
        errdefer silo.deinit();

        const records = try allocator.alloc(Record, MAX_RECORDS);
        errdefer allocator.free(records);

        return StorageEngine{
            .records = records,
            .records_len = 0,
            .next_record_id = 1,
            .silo = silo,
            .allocator = allocator,
        };
    }

    // Deinitialize storage engine and free memory.
    pub fn deinit(self: *StorageEngine) void {
        _ = self.allocator;
        var i: u32 = 0;
        while (i < self.records_len) : (i += 1) {
            self.records[i].deinit();
        }
        self.allocator.free(self.records);
        self.silo.deinit();
        self.* = undefined;
    }

    // Create record (insert key-value pair).
    pub fn create_record(
        self: *StorageEngine,
        key: []const u8,
        value: []const u8,
    ) !u64 {
        std.debug.assert(key.len <= MAX_KEY_LEN);
        std.debug.assert(value.len <= MAX_VALUE_LEN);
        std.debug.assert(self.records_len < MAX_RECORDS);

        if (self.find_record_by_key(key)) |_| {
            return error.RecordExists;
        }

        const record_id = self.next_record_id;
        self.next_record_id += 1;

        var record = try Record.init(
            self.allocator,
            key,
            value,
            record_id,
        );
        errdefer record.deinit();

        self.records[self.records_len] = record;
        self.records_len += 1;

        std.debug.assert(self.records_len <= MAX_RECORDS);
        return record_id;
    }

    // Read record by key.
    pub fn read_record_by_key(
        self: *StorageEngine,
        key: []const u8,
    ) ?*Record {
        std.debug.assert(key.len <= MAX_KEY_LEN);
        return self.find_record_by_key(key);
    }

    // Read record by ID.
    pub fn read_record_by_id(
        self: *StorageEngine,
        record_id: u64,
    ) ?*Record {
        std.debug.assert(record_id > 0);
        return self.find_record_by_id(record_id);
    }

    // Update record value.
    pub fn update_record(
        self: *StorageEngine,
        key: []const u8,
        new_value: []const u8,
    ) !void {
        std.debug.assert(key.len <= MAX_KEY_LEN);
        std.debug.assert(new_value.len <= MAX_VALUE_LEN);

        if (self.find_record_by_key(key)) |record| {
            if (new_value.len > 0) {
                self.allocator.free(record.value);
                const value_copy = try self.allocator.dupe(u8,
new_value);
                record.value = value_copy;
                record.value_len = @as(u64, @intCast(value_copy.len));
            }
            const now = std.time.timestamp();
            record.updated_at = @as(u64, @intCast(now));
        } else {
            return error.RecordNotFound;
        }
    }

    // Delete record by key.
    pub fn delete_record(
        self: *StorageEngine,
        key: []const u8,
    ) !void {
        std.debug.assert(key.len <= MAX_KEY_LEN);

        var i: u32 = 0;
        while (i < self.records_len) : (i += 1) {
            if (std.mem.eql(u8, self.records[i].key, key)) {
                self.records[i].deinit();
                var j: u32 = i;
                while (j < self.records_len - 1) : (j += 1) {
                    self.records[j] = self.records[j + 1];
                }
                self.records_len -= 1;
                return;
            }
        }
        return error.RecordNotFound;
    }

    // Find record by key (internal helper).
    fn find_record_by_key(
        self: *StorageEngine,
        key: []const u8,
    ) ?*Record {
        std.debug.assert(key.len <= MAX_KEY_LEN);
        var i: u32 = 0;
        while (i < self.records_len) : (i += 1) {
            if (std.mem.eql(u8, self.records[i].key, key)) {
                return &self.records[i];
            }
        }
        return null;
    }

    // Find record by ID (internal helper).
    fn find_record_by_id(
        self: *StorageEngine,
        record_id: u64,
    ) ?*Record {
        std.debug.assert(record_id > 0);
        var i: u32 = 0;
        while (i < self.records_len) : (i += 1) {
            if (self.records[i].record_id == record_id) {
                return &self.records[i];
            }
        }
        return null;
    }
};


// === grain_database/storage_persistence.zig ===

//! Grain Database Storage Persistence: Integration between
StorageEngine and PersistenceManager.
//!
//! Why: Bridge in-memory storage engine with file-based persistence for
durability.
//! Architecture: WAL logging, index updates, backup coordination.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-07-020414-pst: Grain Silo Agent

const std = @import("std");
const storage_engine = @import("storage_engine.zig");
const persistence = @import("persistence.zig");
const grain_core = @import("grain_core");
const wal_manager = grain_core.wal_manager;

// Storage persistence integration.
pub const StoragePersistence = struct {
    persistence_manager: *persistence.PersistenceManager,
    storage_engine: *storage_engine.StorageEngine,
    table_id: u32,

    // Initialize storage persistence.
    pub fn init(
        persistence_manager: *persistence.PersistenceManager,
        storage_engine: *storage_engine.StorageEngine,
        table_id: u32,
    ) StoragePersistence {
        std.debug.assert(persistence_manager != null);
        std.debug.assert(storage_engine != null);
        std.debug.assert(table_id > 0);
        return StoragePersistence{
            .persistence_manager = persistence_manager,
            .storage_engine = storage_engine,
            .table_id = table_id,
        };
    }

    // Create record with WAL logging.
    pub fn create_record_with_wal(
        self: *StoragePersistence,
        key: []const u8,
        value: []const u8,
    ) !u64 {
        std.debug.assert(key.len > 0);
        std.debug.assert(key.len <= storage_engine.MAX_KEY_LEN);
        std.debug.assert(value.len <= storage_engine.MAX_VALUE_LEN);
        const record_id = try self.storage_engine.create_record(key,
value);
        const record_data = try std.fmt.allocPrint(
            self.storage_engine.allocator,
            "{s}:{s}",
            .{ key, value },
        );
        defer self.storage_engine.allocator.free(record_data);
        _ = self.persistence_manager.append_wal_entry(
            wal_manager.WalEntryType.insert,
            self.table_id,
            record_id,
            record_data,
        );
        std.debug.assert(record_id > 0);
        return record_id;
    }

    // Update record with WAL logging.
    pub fn update_record_with_wal(
        self: *StoragePersistence,
        key: []const u8,
        new_value: []const u8,
    ) !void {
        std.debug.assert(key.len > 0);
        std.debug.assert(key.len <= storage_engine.MAX_KEY_LEN);
        std.debug.assert(new_value.len <= storage_engine.MAX_VALUE_LEN);
        const record = self.storage_engine.read_record_by_key(key);
        if (record == null) {
            return error.RecordNotFound;
        }
        const record_id = record.?.record_id;
        try self.storage_engine.update_record(key, new_value);
        const record_data = try std.fmt.allocPrint(
            self.storage_engine.allocator,
            "{s}:{s}",
            .{ key, new_value },
        );
        defer self.storage_engine.allocator.free(record_data);
        _ = self.persistence_manager.append_wal_entry(
            wal_manager.WalEntryType.update,
            self.table_id,
            record_id,
            record_data,
        );
    }

    // Delete record with WAL logging.
    pub fn delete_record_with_wal(
        self: *StoragePersistence,
        key: []const u8,
    ) !void {
        std.debug.assert(key.len > 0);
        std.debug.assert(key.len <= storage_engine.MAX_KEY_LEN);
        const record = self.storage_engine.read_record_by_key(key);
        if (record == null) {
            return error.RecordNotFound;
        }
        const record_id = record.?.record_id;
        try self.storage_engine.delete_record(key);
        const record_data = try std.fmt.allocPrint(
            self.storage_engine.allocator,
            "{s}:",
            .{key},
        );
        defer self.storage_engine.allocator.free(record_data);
        _ = self.persistence_manager.append_wal_entry(
            wal_manager.WalEntryType.delete,
            self.table_id,
            record_id,
            record_data,
        );
    }

    // Perform WAL checkpoint if needed.
    pub fn checkpoint_if_needed(
        self: *StoragePersistence,
    ) bool {
        if (!self.persistence_manager.needs_wal_checkpoint()) {
            return false;
        }
        return self.persistence_manager.perform_wal_checkpoint();
    }
};


// === grain_database/transaction.zig ===

//! Grain Database Transaction: ACID transaction management.
//!
//! Why: Ensure atomicity, consistency, isolation, durability.
//! Architecture: Bounded transactions, iterative algorithms.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-03-163155-pst: Grain Database Agent

const std = @import("std");

// Bounded: Max active transactions.
pub const MAX_TRANSACTIONS: u32 = 10_000;

// Bounded: Max operations per transaction.
pub const MAX_OPERATIONS_PER_TX: u32 = 1_000;

// Transaction state.
pub const TransactionState = enum {
    active,
    committed,
    aborted,
};

// Transaction operation.
pub const TransactionOperation = struct {
    operation_type: OperationType,
    record_id: u64,
    key: []const u8,
    key_len: u32,
    value: []const u8,
    value_len: u64,
    allocator: std.mem.Allocator,

    const OperationType = enum {
        insert,
        update,
        delete,
    };

    // Initialize transaction operation.
    pub fn init(
        allocator: std.mem.Allocator,
        operation_type: OperationType,
        record_id: u64,
        key: []const u8,
        value: []const u8,
    ) !TransactionOperation {
        std.debug.assert(record_id > 0);
        std.debug.assert(key.len <= 1_024);

        const key_copy = try allocator.dupe(u8, key);
        errdefer allocator.free(key_copy);

        const value_copy = try allocator.dupe(u8, value);
        errdefer allocator.free(value_copy);

        return TransactionOperation{
            .operation_type = operation_type,
            .record_id = record_id,
            .key = key_copy,
            .key_len = @as(u32, @intCast(key_copy.len)),
            .value = value_copy,
            .value_len = @as(u64, @intCast(value_copy.len)),
            .allocator = allocator,
        };
    }

    // Deinitialize transaction operation and free memory.
    pub fn deinit(self: *TransactionOperation) void {
        _ = self.allocator;
        if (self.key_len > 0) {
            self.allocator.free(self.key);
        }
        if (self.value_len > 0) {
            self.allocator.free(self.value);
        }
        self.* = undefined;
    }
};

// Transaction: ACID transaction management.
pub const Transaction = struct {
    transaction_id: u64,
    state: TransactionState,
    operations: []TransactionOperation,
    operations_len: u32,
    created_at: u64,
    allocator: std.mem.Allocator,

    // Initialize transaction.
    pub fn init(allocator: std.mem.Allocator, transaction_id: u64)
!Transaction {
        std.debug.assert(transaction_id > 0);
        _ = allocator;

        const operations = try allocator.alloc(
            TransactionOperation,
            MAX_OPERATIONS_PER_TX,
        );
        errdefer allocator.free(operations);

        const now = std.time.timestamp();

        return Transaction{
            .transaction_id = transaction_id,
            .state = TransactionState.active,
            .operations = operations,
            .operations_len = 0,
            .created_at = @as(u64, @intCast(now)),
            .allocator = allocator,
        };
    }

    // Deinitialize transaction and free memory.
    pub fn deinit(self: *Transaction) void {
        _ = self.allocator;
        var i: u32 = 0;
        while (i < self.operations_len) : (i += 1) {
            self.operations[i].deinit();
        }
        self.allocator.free(self.operations);
        self.* = undefined;
    }

    // Add operation to transaction.
    pub fn add_operation(
        self: *Transaction,
        operation_type: TransactionOperation.OperationType,
        record_id: u64,
        key: []const u8,
        value: []const u8,
    ) !void {
        std.debug.assert(self.state == TransactionState.active);
        std.debug.assert(self.operations_len < MAX_OPERATIONS_PER_TX);

        if (self.operations_len >= MAX_OPERATIONS_PER_TX) {
            return error.TransactionFull;
        }

        var operation = try TransactionOperation.init(
            self.allocator,
            operation_type,
            record_id,
            key,
            value,
        );
        errdefer operation.deinit();

        self.operations[self.operations_len] = operation;
        self.operations_len += 1;

        std.debug.assert(self.operations_len <= MAX_OPERATIONS_PER_TX);
    }

    // Commit transaction.
    pub fn commit(self: *Transaction) void {
        std.debug.assert(self.state == TransactionState.active);
        self.state = TransactionState.committed;
    }

    // Abort transaction.
    pub fn abort(self: *Transaction) void {
        std.debug.assert(self.state == TransactionState.active);
        self.state = TransactionState.aborted;
    }

    // Check if transaction is active.
    pub fn is_active(self: *Transaction) bool {
        return self.state == TransactionState.active;
    }

    // Check if transaction is committed.
    pub fn is_committed(self: *Transaction) bool {
        return self.state == TransactionState.committed;
    }
};


// === grain_database/wal.zig ===

//! Grain Database WAL: Write-ahead log for durability.
//!
//! Why: Ensure durability by logging all writes before applying them.
//! Architecture: Bounded log entries, iterative algorithms.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
max 70 lines.
//!
//! 2025-12-03-163155-pst: Grain Database Agent

const std = @import("std");

// Bounded: Max log entries in WAL.
pub const MAX_LOG_ENTRIES: u32 = 1_000_000;

// Bounded: Max log entry size (bytes).
pub const MAX_LOG_ENTRY_SIZE: u32 = 1_048_576; // 1 MB

// Log entry type.
pub const LogEntryType = enum {
    insert,
    update,
    delete,
    commit,
    abort,
};

// WAL log entry.
pub const LogEntry = struct {
    entry_type: LogEntryType,
    record_id: u64,
    key: []const u8,
    key_len: u32,
    value: []const u8,
    value_len: u64,
    timestamp: u64,
    transaction_id: u64,
    allocator: std.mem.Allocator,

    // Initialize log entry.
    pub fn init(
        allocator: std.mem.Allocator,
        entry_type: LogEntryType,
        record_id: u64,
        key: []const u8,
        value: []const u8,
        transaction_id: u64,
    ) !LogEntry {
        std.debug.assert(key.len <= MAX_LOG_ENTRY_SIZE);
        std.debug.assert(value.len <= MAX_LOG_ENTRY_SIZE);
        std.debug.assert(record_id > 0);

        const key_copy = try allocator.dupe(u8, key);
        errdefer allocator.free(key_copy);

        const value_copy = try allocator.dupe(u8, value);
        errdefer allocator.free(value_copy);

        const now = std.time.timestamp();

        return LogEntry{
            .entry_type = entry_type,
            .record_id = record_id,
            .key = key_copy,
            .key_len = @as(u32, @intCast(key_copy.len)),
            .value = value_copy,
            .value_len = @as(u64, @intCast(value_copy.len)),
            .timestamp = @as(u64, @intCast(now)),
            .transaction_id = transaction_id,
            .allocator = allocator,
        };
    }

    // Deinitialize log entry and free memory.
    pub fn deinit(self: *LogEntry) void {
        _ = self.allocator;
        if (self.key_len > 0) {
            self.allocator.free(self.key);
        }
        if (self.value_len > 0) {
            self.allocator.free(self.value);
        }
        self.* = undefined;
    }
};

// Write-ahead log: Logs all writes for durability.
pub const WAL = struct {
    entries: []LogEntry,
    entries_len: u32,
    next_entry_id: u64,
    allocator: std.mem.Allocator,

    // Initialize WAL.
    pub fn init(allocator: std.mem.Allocator) !WAL {
        _ = allocator;
        const entries = try allocator.alloc(LogEntry, MAX_LOG_ENTRIES);
        errdefer allocator.free(entries);

        return WAL{
            .entries = entries,
            .entries_len = 0,
            .next_entry_id = 1,
            .allocator = allocator,
        };
    }

    // Deinitialize WAL and free memory.
    pub fn deinit(self: *WAL) void {
        _ = self.allocator;
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            self.entries[i].deinit();
        }
        self.allocator.free(self.entries);
        self.* = undefined;
    }

    // Append log entry.
    pub fn append(
        self: *WAL,
        entry_type: LogEntryType,
        record_id: u64,
        key: []const u8,
        value: []const u8,
        transaction_id: u64,
    ) !u64 {
        std.debug.assert(self.entries_len < MAX_LOG_ENTRIES);
        std.debug.assert(key.len <= MAX_LOG_ENTRY_SIZE);
        std.debug.assert(value.len <= MAX_LOG_ENTRY_SIZE);

        if (self.entries_len >= MAX_LOG_ENTRIES) {
            return error.WALFull;
        }

        const entry_id = self.next_entry_id;
        self.next_entry_id += 1;

        var entry = try LogEntry.init(
            self.allocator,
            entry_type,
            record_id,
            key,
            value,
            transaction_id,
        );
        errdefer entry.deinit();

        self.entries[self.entries_len] = entry;
        self.entries_len += 1;

        std.debug.assert(self.entries_len <= MAX_LOG_ENTRIES);
        return entry_id;
    }

    // Get log entry by index.
    pub fn get_entry(
        self: *WAL,
        entry_idx: u32,
    ) ?*LogEntry {
        std.debug.assert(entry_idx < MAX_LOG_ENTRIES);
        if (entry_idx >= self.entries_len) {
            return null;
        }
        return &self.entries[entry_idx];
    }

    // Clear all log entries (after checkpoint).
    pub fn clear(self: *WAL) void {
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            self.entries[i].deinit();
        }
        self.entries_len = 0;
        self.next_entry_id = 1;
    }
};


// === grain_flow/agent_coordinator.zig ===

//! Grain Flow Agent Coordinator: Agent registry, health monitoring, and
RPC.
//!
//! Why: Provides agent coordination services for the Grain OS ecosystem.
//! Agents register with the coordinator, which tracks their health,
capabilities,
//! and enables agent-to-agent RPC communication.
//!
//! Architecture: Agent registry, health monitoring, capability
discovery, RPC.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-07-071000-pst: Phase 2 Agent Coordinator Foundation

const std = @import("std");
const event_bus = @import("event_bus.zig");

// Bounded: Max agents in registry.
pub const MAX_AGENTS: u32 = 64;

// Bounded: Max RPC requests in queue.
pub const MAX_RPC_REQUESTS: u32 = 1000;

// Bounded: Max agent name length.
pub const MAX_AGENT_NAME_LEN: u32 = 64;

// Bounded: Max capabilities per agent.
pub const MAX_CAPABILITIES: u32 = 32;

// Bounded: Max capability name length.
pub const MAX_CAPABILITY_NAME_LEN: u32 = 64;

// Agent status.
pub const AgentStatus = enum(u8) {
    inactive = 0,
    active = 1,
    unhealthy = 2,
    unknown = 3,
};

// Agent capability: represents a capability an agent provides.
pub const AgentCapability = struct {
    name: [MAX_CAPABILITY_NAME_LEN]u8,
    name_len: u32,
    version: u32,

    pub fn init() AgentCapability {
        var cap = AgentCapability{
            .name = undefined,
            .name_len = 0,
            .version = 0,
        };
        var i: u32 = 0;
        while (i < MAX_CAPABILITY_NAME_LEN) : (i += 1) {
            cap.name[i] = 0;
        }
        return cap;
    }

    pub fn set_name(self: *AgentCapability, name: []const u8) bool {
        std.debug.assert(name.len > 0);
        if (name.len > MAX_CAPABILITY_NAME_LEN) {
            return false;
        }
        var i: u32 = 0;
        while (i < name.len) : (i += 1) {
            self.name[i] = name[i];
        }
        self.name_len = @intCast(name.len);
        return true;
    }
};

// Agent: represents a registered agent.
pub const Agent = struct {
    agent_id: u32,
    name: [MAX_AGENT_NAME_LEN]u8,
    name_len: u32,
    status: AgentStatus,
    last_health_check: u64,
    capabilities: [MAX_CAPABILITIES]AgentCapability,
    capabilities_len: u32,
    registered_at: u64,
    active: bool,

    pub fn init(agent_id: u32, name: []const u8, timestamp: u64) Agent {
        std.debug.assert(agent_id > 0);
        std.debug.assert(name.len > 0);
        std.debug.assert(timestamp > 0);
        var agent = Agent{
            .agent_id = agent_id,
            .name = undefined,
            .name_len = 0,
            .status = AgentStatus.inactive,
            .last_health_check = 0,
            .capabilities = undefined,
            .capabilities_len = 0,
            .registered_at = timestamp,
            .active = false,
        };
        var i: u32 = 0;
        while (i < MAX_AGENT_NAME_LEN) : (i += 1) {
            agent.name[i] = 0;
        }
        i = 0;
        while (i < MAX_CAPABILITIES) : (i += 1) {
            agent.capabilities[i] = AgentCapability.init();
        }
        const name_len = @min(name.len, MAX_AGENT_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            agent.name[i] = name[i];
        }
        agent.name_len = @intCast(name_len);
        return agent;
    }

    pub fn add_capability(self: *Agent, capability: AgentCapability)
bool {
        std.debug.assert(self.capabilities_len < MAX_CAPABILITIES);
        if (self.capabilities_len >= MAX_CAPABILITIES) {
            return false;
        }
        self.capabilities[self.capabilities_len] = capability;
        self.capabilities_len += 1;
        return true;
    }
};

// RPC request: represents an RPC request between agents.
pub const RpcRequest = struct {
    request_id: u32,
    from_agent_id: u32,
    to_agent_id: u32,
    method: [MAX_CAPABILITY_NAME_LEN]u8,
    method_len: u32,
    payload: [event_bus.MAX_PAYLOAD_SIZE]u8,
    payload_len: u32,
    timestamp: u64,
    processed: bool,

    pub fn init(
        request_id: u32,
        from_agent_id: u32,
        to_agent_id: u32,
        method: []const u8,
        timestamp: u64,
    ) RpcRequest {
        std.debug.assert(request_id > 0);
        std.debug.assert(from_agent_id > 0);
        std.debug.assert(to_agent_id > 0);
        std.debug.assert(method.len > 0);
        std.debug.assert(timestamp > 0);
        var req = RpcRequest{
            .request_id = request_id,
            .from_agent_id = from_agent_id,
            .to_agent_id = to_agent_id,
            .method = undefined,
            .method_len = 0,
            .payload = undefined,
            .payload_len = 0,
            .timestamp = timestamp,
            .processed = false,
        };
        var i: u32 = 0;
        while (i < MAX_CAPABILITY_NAME_LEN) : (i += 1) {
            req.method[i] = 0;
        }
        i = 0;
        while (i < event_bus.MAX_PAYLOAD_SIZE) : (i += 1) {
            req.payload[i] = 0;
        }
        const method_len = @min(method.len, MAX_CAPABILITY_NAME_LEN);
        i = 0;
        while (i < method_len) : (i += 1) {
            req.method[i] = method[i];
        }
        req.method_len = @intCast(method_len);
        return req;
    }

    pub fn set_payload(self: *RpcRequest, data: []const u8) bool {
        std.debug.assert(data.len > 0);
        if (data.len > event_bus.MAX_PAYLOAD_SIZE) {
            return false;
        }
        var i: u32 = 0;
        while (i < data.len) : (i += 1) {
            self.payload[i] = data[i];
        }
        self.payload_len = @intCast(data.len);
        return true;
    }
};

// Agent coordinator: manages agent registry and coordination.
pub const AgentCoordinator = struct {
    agents: [MAX_AGENTS]Agent,
    agents_len: u32,
    next_agent_id: u32,
    rpc_requests: [MAX_RPC_REQUESTS]RpcRequest,
    rpc_requests_head: u32,
    rpc_requests_tail: u32,
    rpc_requests_count: u32,
    next_request_id: u32,
    event_bus: *event_bus.EventBus,

    pub fn init(event_bus_instance: *event_bus.EventBus)
AgentCoordinator {
        std.debug.assert(event_bus_instance != null);
        var coordinator = AgentCoordinator{
            .agents = undefined,
            .agents_len = 0,
            .next_agent_id = 1,
            .rpc_requests = undefined,
            .rpc_requests_head = 0,
            .rpc_requests_tail = 0,
            .rpc_requests_count = 0,
            .next_request_id = 1,
            .event_bus = event_bus_instance,
        };
        var i: u32 = 0;
        while (i < MAX_AGENTS) : (i += 1) {
            coordinator.agents[i] = Agent.init(0, "", 0);
        }
        i = 0;
        while (i < MAX_RPC_REQUESTS) : (i += 1) {
            coordinator.rpc_requests[i] = RpcRequest.init(0, 0, 0, "",
0);
        }
        return coordinator;
    }

    // Register agent with coordinator.
    pub fn register_agent(
        self: *AgentCoordinator,
        name: []const u8,
        timestamp: u64,
    ) ?u32 {
        std.debug.assert(name.len > 0);
        std.debug.assert(timestamp > 0);
        if (self.agents_len >= MAX_AGENTS) {
            return null;
        }
        const agent_id = self.next_agent_id;
        self.next_agent_id += 1;
        self.agents[self.agents_len] = Agent.init(agent_id, name,
timestamp);
        self.agents[self.agents_len].status = AgentStatus.active;
        self.agents[self.agents_len].active = true;
        self.agents_len += 1;
        // Publish agent_started event.
        _ = self.event_bus.publish_event(
            event_bus.EventType.agent_started,
            agent_id,
            0,
            timestamp,
        );
        return agent_id;
    }

    // Unregister agent from coordinator.
    pub fn unregister_agent(
        self: *AgentCoordinator,
        agent_id: u32,
        timestamp: u64,
    ) bool {
        std.debug.assert(agent_id > 0);
        std.debug.assert(timestamp > 0);
        var i: u32 = 0;
        var found: bool = false;
        while (i < self.agents_len) : (i += 1) {
            if (self.agents[i].agent_id == agent_id) {
                found = true;
                break;
            }
        }
        if (!found) {
            return false;
        }
        self.agents[i].active = false;
        self.agents[i].status = AgentStatus.inactive;
        // Publish agent_stopped event.
        _ = self.event_bus.publish_event(
            event_bus.EventType.agent_stopped,
            agent_id,
            0,
            timestamp,
        );
        // Shift remaining agents left.
        while (i < self.agents_len - 1) : (i += 1) {
            self.agents[i] = self.agents[i + 1];
        }
        self.agents_len -= 1;
        return true;
    }

    // Find agent by ID.
    pub fn find_agent(self: *const AgentCoordinator, agent_id: u32)
?*const Agent {
        std.debug.assert(agent_id > 0);
        var i: u32 = 0;
        while (i < self.agents_len) : (i += 1) {
            if (self.agents[i].agent_id == agent_id) {
                return &self.agents[i];
            }
        }
        return null;
    }

    // Update agent health status.
    pub fn update_agent_health(
        self: *AgentCoordinator,
        agent_id: u32,
        status: AgentStatus,
        timestamp: u64,
    ) bool {
        std.debug.assert(agent_id > 0);
        std.debug.assert(timestamp > 0);
        var i: u32 = 0;
        while (i < self.agents_len) : (i += 1) {
            if (self.agents[i].agent_id == agent_id) {
                self.agents[i].status = status;
                self.agents[i].last_health_check = timestamp;
                // Publish health check event.
                _ = self.event_bus.publish_event(
                    event_bus.EventType.agent_health_check,
                    agent_id,
                    0,
                    timestamp,
                );
                return true;
            }
        }
        return false;
    }

    // Add capability to agent.
    pub fn add_agent_capability(
        self: *AgentCoordinator,
        agent_id: u32,
        capability: AgentCapability,
    ) bool {
        std.debug.assert(agent_id > 0);
        var i: u32 = 0;
        while (i < self.agents_len) : (i += 1) {
            if (self.agents[i].agent_id == agent_id) {
                return self.agents[i].add_capability(capability);
            }
        }
        return false;
    }

    // Find agents by capability.
    pub fn find_agents_by_capability(
        self: *const AgentCoordinator,
        capability_name: []const u8,
        results: []u32,
    ) u32 {
        std.debug.assert(capability_name.len > 0);
        std.debug.assert(results.len > 0);
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.agents_len and count < results.len) : (i += 1) {
            if (!self.agents[i].active) {
                continue;
            }
            var j: u32 = 0;
            while (j < self.agents[i].capabilities_len) : (j += 1) {
                const cap = &self.agents[i].capabilities[j];
                if (cap.name_len == capability_name.len) {
                    var match: bool = true;
                    var k: u32 = 0;
                    while (k < cap.name_len) : (k += 1) {
                        if (cap.name[k] != capability_name[k]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        results[count] = self.agents[i].agent_id;
                        count += 1;
                        break;
                    }
                }
            }
        }
        return count;
    }

    // Send RPC request to agent.
    pub fn send_rpc_request(
        self: *AgentCoordinator,
        from_agent_id: u32,
        to_agent_id: u32,
        method: []const u8,
        payload: []const u8,
        timestamp: u64,
    ) ?u32 {
        std.debug.assert(from_agent_id > 0);
        std.debug.assert(to_agent_id > 0);
        std.debug.assert(method.len > 0);
        std.debug.assert(timestamp > 0);
        if (self.rpc_requests_count >= MAX_RPC_REQUESTS) {
            return null;
        }
        const request_id = self.next_request_id;
        self.next_request_id += 1;
        const idx = self.rpc_requests_tail;
        self.rpc_requests[idx] = RpcRequest.init(
            request_id,
            from_agent_id,
            to_agent_id,
            method,
            timestamp,
        );
        if (payload.len > 0) {
            _ = self.rpc_requests[idx].set_payload(payload);
        }
        self.rpc_requests_tail = (self.rpc_requests_tail + 1) %
MAX_RPC_REQUESTS;
        self.rpc_requests_count += 1;
        return request_id;
    }

    // Get RPC request by ID.
    pub fn get_rpc_request(
        self: *const AgentCoordinator,
        request_id: u32,
    ) ?*const RpcRequest {
        std.debug.assert(request_id > 0);
        var i: u32 = 0;
        while (i < self.rpc_requests_count) : (i += 1) {
            const idx = (self.rpc_requests_head + i) % MAX_RPC_REQUESTS;
            const req = &self.rpc_requests[idx];
            if (req.request_id == request_id) {
                return req;
            }
        }
        return null;
    }

    // Get agent count.
    pub fn get_agent_count(self: *const AgentCoordinator) u32 {
        return self.agents_len;
    }

    // Get active agent count.
    pub fn get_active_agent_count(self: *const AgentCoordinator) u32 {
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.agents_len) : (i += 1) {
            if (self.agents[i].active) {
                count += 1;
            }
        }
        return count;
    }

    // Get RPC request count.
    pub fn get_rpc_request_count(self: *const AgentCoordinator) u32 {
        return self.rpc_requests_count;
    }
};

// === grain_flow/event_bus.zig ===

//! Grain Flow Event Bus: Centralized event routing for agent
communication.
//!
//! Why: Provides centralized event routing for agent-to-agent
communication.
//! Agents publish events and subscribe to event types. Event bus routes
events
//! to subscribed agents using iterative matching (no recursion).
//!
//! Architecture: Event queue, subscription registry, iterative routing.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-07-054000-pst: Phase 1 Event Bus Foundation

const std = @import("std");

// Bounded: Max events in queue.
pub const MAX_EVENTS: u32 = 10000;

// Bounded: Max subscribers per event type.
pub const MAX_SUBSCRIBERS: u32 = 256;

// Bounded: Max event payload size (64KB).
pub const MAX_PAYLOAD_SIZE: u32 = 65536;

// Bounded: Max agent ID length.
pub const MAX_AGENT_ID_LEN: u32 = 64;

// Event type: enum-based event types for agent communication.
pub const EventType = enum(u16) {
    none = 0,
    agent_started = 1,
    agent_stopped = 2,
    agent_health_check = 3,
    workflow_started = 4,
    workflow_completed = 5,
    workflow_failed = 6,
    task_completed = 7,
    task_failed = 8,
    data_backup_started = 9,
    data_backup_completed = 10,
    data_backup_failed = 11,
    database_query_completed = 12,
    api_request_completed = 13,
    custom = 1000,
};

// Event: represents an event in the event bus.
pub const Event = struct {
    event_type: EventType,
    source_agent_id: u32,
    destination_agent_id: u32,
    timestamp: u64,
    payload: [MAX_PAYLOAD_SIZE]u8,
    payload_len: u32,
    processed: bool,

    pub fn init(
        event_type: EventType,
        source_agent_id: u32,
        destination_agent_id: u32,
        timestamp: u64,
    ) Event {
        std.debug.assert(source_agent_id > 0);
        std.debug.assert(timestamp > 0);
        var event = Event{
            .event_type = event_type,
            .source_agent_id = source_agent_id,
            .destination_agent_id = destination_agent_id,
            .timestamp = timestamp,
            .payload = undefined,
            .payload_len = 0,
            .processed = false,
        };
        var i: u32 = 0;
        while (i < MAX_PAYLOAD_SIZE) : (i += 1) {
            event.payload[i] = 0;
        }
        return event;
    }

    pub fn set_payload(self: *Event, data: []const u8) bool {
        std.debug.assert(data.len > 0);
        if (data.len > MAX_PAYLOAD_SIZE) {
            return false;
        }
        var i: u32 = 0;
        while (i < data.len) : (i += 1) {
            self.payload[i] = data[i];
        }
        self.payload_len = @intCast(data.len);
        return true;
    }
};

// Event subscriber callback function.
pub const EventSubscriberFn = *const fn (
    event: *const Event,
    user_data: ?*anyopaque,
) void;

// Event subscriber: callback for event types.
pub const EventSubscriber = struct {
    subscriber_fn: EventSubscriberFn,
    user_data: ?*anyopaque,
    agent_id: u32,
    active: bool,
};

// Event bus: manages events and subscriptions.
pub const EventBus = struct {
    events: [MAX_EVENTS]Event,
    events_head: u32,
    events_tail: u32,
    events_count: u32,
    subscribers: [MAX_SUBSCRIBERS]EventSubscriber,
    subscribers_len: u32,
    subscribers_by_type: [256][MAX_SUBSCRIBERS]u32,
    subscribers_count_by_type: [256]u32,

    pub fn init() EventBus {
        var bus = EventBus{
            .events = undefined,
            .events_head = 0,
            .events_tail = 0,
            .events_count = 0,
            .subscribers = undefined,
            .subscribers_len = 0,
            .subscribers_by_type = undefined,
            .subscribers_count_by_type = undefined,
        };
        var i: u32 = 0;
        while (i < MAX_EVENTS) : (i += 1) {
            bus.events[i] = Event.init(
                EventType.none,
                0,
                0,
                0,
            );
        }
        i = 0;
        while (i < MAX_SUBSCRIBERS) : (i += 1) {
            bus.subscribers[i] = EventSubscriber{
                .subscriber_fn = undefined,
                .user_data = null,
                .agent_id = 0,
                .active = false,
            };
        }
        i = 0;
        while (i < 256) : (i += 1) {
            bus.subscribers_count_by_type[i] = 0;
            var j: u32 = 0;
            while (j < MAX_SUBSCRIBERS) : (j += 1) {
                bus.subscribers_by_type[i][j] = 0;
            }
        }
        return bus;
    }

    // Publish event to event bus.
    pub fn publish_event(
        self: *EventBus,
        event_type: EventType,
        source_agent_id: u32,
        destination_agent_id: u32,
        timestamp: u64,
    ) bool {
        std.debug.assert(source_agent_id > 0);
        std.debug.assert(timestamp > 0);
        // destination_agent_id can be 0 (broadcast to all subscribers)
        if (self.events_count >= MAX_EVENTS) {
            // Queue full, drop oldest event.
            self.events_head = (self.events_head + 1) % MAX_EVENTS;
            self.events_count -= 1;
        }
        const idx = self.events_tail;
        self.events[idx] = Event.init(
            event_type,
            source_agent_id,
            destination_agent_id,
            timestamp,
        );
        self.events_tail = (self.events_tail + 1) % MAX_EVENTS;
        self.events_count += 1;
        // Route event to subscribers.
        self.route_event(&self.events[idx]);
        return true;
    }

    // Publish event with payload.
    pub fn publish_event_with_payload(
        self: *EventBus,
        event_type: EventType,
        source_agent_id: u32,
        destination_agent_id: u32,
        timestamp: u64,
        payload: []const u8,
    ) bool {
        std.debug.assert(source_agent_id > 0);
        std.debug.assert(timestamp > 0);
        if (self.events_count >= MAX_EVENTS) {
            self.events_head = (self.events_head + 1) % MAX_EVENTS;
            self.events_count -= 1;
        }
        const idx = self.events_tail;
        self.events[idx] = Event.init(
            event_type,
            source_agent_id,
            destination_agent_id,
            timestamp,
        );
        if (!self.events[idx].set_payload(payload)) {
            return false;
        }
        self.events_tail = (self.events_tail + 1) % MAX_EVENTS;
        self.events_count += 1;
        self.route_event(&self.events[idx]);
        return true;
    }

    // Subscribe to event type.
    pub fn subscribe(
        self: *EventBus,
        event_type: EventType,
        agent_id: u32,
        subscriber_fn: EventSubscriberFn,
        user_data: ?*anyopaque,
    ) bool {
        std.debug.assert(agent_id > 0);
        if (self.subscribers_len >= MAX_SUBSCRIBERS) {
            return false;
        }
        const type_idx = @intFromEnum(event_type);
        if (type_idx >= 256) {
            return false;
        }
        if (self.subscribers_count_by_type[type_idx] >= MAX_SUBSCRIBERS)
{
            return false;
        }
        const sub_idx = self.subscribers_len;
        self.subscribers[sub_idx] = EventSubscriber{
            .subscriber_fn = subscriber_fn,
            .user_data = user_data,
            .agent_id = agent_id,
            .active = true,
        };
        self.subscribers_len += 1;
        const type_sub_idx = self.subscribers_count_by_type[type_idx];
        self.subscribers_by_type[type_idx][type_sub_idx] = sub_idx;
        self.subscribers_count_by_type[type_idx] += 1;
        return true;
    }

    // Unsubscribe from event type.
    pub fn unsubscribe(
        self: *EventBus,
        event_type: EventType,
        agent_id: u32,
    ) bool {
        std.debug.assert(agent_id > 0);
        const type_idx = @intFromEnum(event_type);
        if (type_idx >= 256) {
            return false;
        }
        var found: bool = false;
        var sub_idx: u32 = 0;
        var type_sub_idx: u32 = 0;
        var i: u32 = 0;
        while (i < self.subscribers_count_by_type[type_idx]) : (i += 1) {
            const idx = self.subscribers_by_type[type_idx][i];
            if (self.subscribers[idx].agent_id == agent_id) {
                found = true;
                sub_idx = idx;
                type_sub_idx = i;
                break;
            }
        }
        if (!found) {
            return false;
        }
        // Mark subscriber as inactive.
        self.subscribers[sub_idx].active = false;
        // Remove from type-specific list.
        i = type_sub_idx;
        while (i < self.subscribers_count_by_type[type_idx] - 1) : (i +=
1) {
            self.subscribers_by_type[type_idx][i] =
                self.subscribers_by_type[type_idx][i + 1];
        }
        self.subscribers_count_by_type[type_idx] -= 1;
        return true;
    }

    // Route event to subscribers (iterative, no recursion).
    fn route_event(self: *EventBus, event: *Event) void {
        std.debug.assert(event.processed == false);
        const type_idx = @intFromEnum(event.event_type);
        if (type_idx >= 256) {
            return;
        }
        var i: u32 = 0;
        while (i < self.subscribers_count_by_type[type_idx]) : (i += 1) {
            const sub_idx = self.subscribers_by_type[type_idx][i];
            const subscriber = &self.subscribers[sub_idx];
            if (!subscriber.active) {
                continue;
            }
            // Filter by destination if specified.
            if (event.destination_agent_id > 0) {
                if (subscriber.agent_id != event.destination_agent_id) {
                    continue;
                }
            }
            // Filter by source if needed (future enhancement).
            subscriber.subscriber_fn(event, subscriber.user_data);
        }
        event.processed = true;
    }

    // Process all pending events (iterative).
    pub fn process_events(self: *EventBus) void {
        var processed: u32 = 0;
        const max_iterations: u32 = self.events_count;
        var iterations: u32 = 0;
        while (iterations < max_iterations and processed <
self.events_count) : (iterations += 1) {
            const idx = (self.events_head + processed) % MAX_EVENTS;
            const event = &self.events[idx];
            if (event.processed) {
                processed += 1;
                continue;
            }
            if (event.event_type == EventType.none) {
                processed += 1;
                continue;
            }
            self.route_event(event);
            processed += 1;
        }
    }

    // Get event count.
    pub fn get_event_count(self: *const EventBus) u32 {
        return self.events_count;
    }

    // Get subscriber count.
    pub fn get_subscriber_count(self: *const EventBus) u32 {
        return self.subscribers_len;
    }

    // Get subscriber count for event type.
    pub fn get_subscriber_count_for_type(
        self: *const EventBus,
        event_type: EventType,
    ) u32 {
        const type_idx = @intFromEnum(event_type);
        if (type_idx >= 256) {
            return 0;
        }
        return self.subscribers_count_by_type[type_idx];
    }

    // Clear all events.
    pub fn clear_events(self: *EventBus) void {
        self.events_head = 0;
        self.events_tail = 0;
        self.events_count = 0;
    }
};

// === grain_flow/root.zig ===

//! Grain Flow: Workflow orchestration, agent coordination, and
automation flows.
//!
//! Why: Provides the orchestration layer that coordinates multiple
agents using
//! Core's system services. Flow Agent integrates seamlessly with Grain
Core
//! orchestration, enabling event-driven workflows and agent-to-agent
coordination.
//!
//! Architecture: Flow depends on Core (API Server, WebSocket, Auth) and
//! coordinates all other agents via event bus and workflows. Flow
provides:
//! - Event Bus: Centralized event routing for agent communication
//! - Agent Coordinator: Agent registry, health monitoring, RPC
//! - Workflow Engine: DAG-based workflow execution
//! - Workflow Visualizer: Visual workflow representation
//!
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-07-040000-pst: Initial module structure

const std = @import("std");

// Event bus for agent-to-agent communication.
pub const event_bus = @import("event_bus.zig");

// Agent coordinator for agent registry and coordination.
pub const agent_coordinator = @import("agent_coordinator.zig");

// Workflow engine for DAG-based workflow execution.
pub const workflow_engine = @import("workflow_engine.zig");

// Workflow visualizer for visual workflow representation.
// pub const workflow_visualizer = @import("workflow_visualizer.zig");

// Module exports.
pub const EventBus = event_bus.EventBus;
pub const EventType = event_bus.EventType;
pub const Event = event_bus.Event;

pub const AgentCoordinator = agent_coordinator.AgentCoordinator;
pub const Agent = agent_coordinator.Agent;
pub const AgentStatus = agent_coordinator.AgentStatus;
pub const AgentCapability = agent_coordinator.AgentCapability;
pub const RpcRequest = agent_coordinator.RpcRequest;
pub const WorkflowEngine = workflow_engine.WorkflowEngine;
pub const Workflow = workflow_engine.Workflow;
pub const WorkflowNode = workflow_engine.WorkflowNode;
pub const WorkflowEdge = workflow_engine.WorkflowEdge;
pub const WorkflowStatus = workflow_engine.WorkflowStatus;
pub const NodeStatus = workflow_engine.NodeStatus;
pub const EdgeType = workflow_engine.EdgeType;
// pub const WorkflowVisualizer = workflow_visualizer.WorkflowVisualizer;

// === grain_flow/workflow_engine.zig ===

//! Grain Flow Workflow Engine: DAG-based workflow execution.
//!
//! Why: Provides DAG-based workflow execution for coordinating multiple
agents.
//! Workflows define nodes (tasks/agents) and edges (dependencies), and
the engine
//! executes them iteratively in topological order.
//!
//! Architecture: Workflow DAG, iterative execution, state management,
error handling.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-07-072000-pst: Phase 3 Workflow Engine Foundation

const std = @import("std");
const event_bus = @import("event_bus.zig");
const agent_coordinator = @import("agent_coordinator.zig");

// Bounded: Max workflow depth (max path length).
pub const MAX_WORKFLOW_DEPTH: u32 = 1000;

// Bounded: Max workflow nodes.
pub const MAX_WORKFLOW_NODES: u32 = 10000;

// Bounded: Max workflow edges.
pub const MAX_WORKFLOW_EDGES: u32 = 100000;

// Bounded: Max node name length.
pub const MAX_NODE_NAME_LEN: u32 = 128;

// Bounded: Max state data size.
pub const MAX_STATE_DATA_SIZE: u32 = 65536;

// Workflow node status.
pub const NodeStatus = enum(u8) {
    pending = 0,
    running = 1,
    completed = 2,
    failed = 3,
    skipped = 4,
};

// Workflow status.
pub const WorkflowStatus = enum(u8) {
    pending = 0,
    running = 1,
    completed = 2,
    failed = 3,
    cancelled = 4,
};

// Workflow node: represents a task/agent in the workflow.
pub const WorkflowNode = struct {
    node_id: u32,
    name: [MAX_NODE_NAME_LEN]u8,
    name_len: u32,
    agent_id: u32,
    status: NodeStatus,
    started_at: u64,
    completed_at: u64,
    error_message: [256]u8,
    error_message_len: u32,
    state_data: [MAX_STATE_DATA_SIZE]u8,
    state_data_len: u32,

    pub fn init(node_id: u32, name: []const u8, agent_id: u32)
WorkflowNode {
        std.debug.assert(node_id > 0);
        std.debug.assert(name.len > 0);
        std.debug.assert(agent_id > 0);
        var node = WorkflowNode{
            .node_id = node_id,
            .name = undefined,
            .name_len = 0,
            .agent_id = agent_id,
            .status = NodeStatus.pending,
            .started_at = 0,
            .completed_at = 0,
            .error_message = undefined,
            .error_message_len = 0,
            .state_data = undefined,
            .state_data_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_NODE_NAME_LEN) : (i += 1) {
            node.name[i] = 0;
        }
        i = 0;
        while (i < 256) : (i += 1) {
            node.error_message[i] = 0;
        }
        i = 0;
        while (i < MAX_STATE_DATA_SIZE) : (i += 1) {
            node.state_data[i] = 0;
        }
        const name_len = @min(name.len, MAX_NODE_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            node.name[i] = name[i];
        }
        node.name_len = @intCast(name_len);
        return node;
    }

    pub fn set_error(self: *WorkflowNode, message: []const u8) bool {
        std.debug.assert(message.len > 0);
        if (message.len > 256) {
            return false;
        }
        var i: u32 = 0;
        while (i < message.len) : (i += 1) {
            self.error_message[i] = message[i];
        }
        self.error_message_len = @intCast(message.len);
        return true;
    }

    pub fn set_state_data(self: *WorkflowNode, data: []const u8) bool {
        std.debug.assert(data.len > 0);
        if (data.len > MAX_STATE_DATA_SIZE) {
            return false;
        }
        var i: u32 = 0;
        while (i < data.len) : (i += 1) {
            self.state_data[i] = data[i];
        }
        self.state_data_len = @intCast(data.len);
        return true;
    }
};

// Workflow edge: represents a dependency between nodes.
pub const WorkflowEdge = struct {
    from_node_id: u32,
    to_node_id: u32,
    edge_type: EdgeType,

    pub fn init(from_node_id: u32, to_node_id: u32, edge_type: EdgeType)
WorkflowEdge {
        std.debug.assert(from_node_id > 0);
        std.debug.assert(to_node_id > 0);
        std.debug.assert(from_node_id != to_node_id);
        return WorkflowEdge{
            .from_node_id = from_node_id,
            .to_node_id = to_node_id,
            .edge_type = edge_type,
        };
    }
};

// Edge type: type of dependency.
pub const EdgeType = enum(u8) {
    dependency = 0,
    data_flow = 1,
    conditional = 2,
};

// Workflow: represents a complete workflow DAG.
pub const Workflow = struct {
    workflow_id: u32,
    name: [MAX_NODE_NAME_LEN]u8,
    name_len: u32,
    nodes: [MAX_WORKFLOW_NODES]WorkflowNode,
    nodes_len: u32,
    edges: [MAX_WORKFLOW_EDGES]WorkflowEdge,
    edges_len: u32,
    status: WorkflowStatus,
    created_at: u64,
    started_at: u64,
    completed_at: u64,

    pub fn init(workflow_id: u32, name: []const u8, timestamp: u64)
Workflow {
        std.debug.assert(workflow_id > 0);
        std.debug.assert(name.len > 0);
        std.debug.assert(timestamp > 0);
        var workflow = Workflow{
            .workflow_id = workflow_id,
            .name = undefined,
            .name_len = 0,
            .nodes = undefined,
            .nodes_len = 0,
            .edges = undefined,
            .edges_len = 0,
            .status = WorkflowStatus.pending,
            .created_at = timestamp,
            .started_at = 0,
            .completed_at = 0,
        };
        var i: u32 = 0;
        while (i < MAX_NODE_NAME_LEN) : (i += 1) {
            workflow.name[i] = 0;
        }
        i = 0;
        while (i < MAX_WORKFLOW_NODES) : (i += 1) {
            workflow.nodes[i] = WorkflowNode.init(0, "", 0);
        }
        i = 0;
        while (i < MAX_WORKFLOW_EDGES) : (i += 1) {
            workflow.edges[i] = WorkflowEdge.init(0, 0,
EdgeType.dependency);
        }
        const name_len = @min(name.len, MAX_NODE_NAME_LEN);
        i = 0;
        while (i < name_len) : (i += 1) {
            workflow.name[i] = name[i];
        }
        workflow.name_len = @intCast(name_len);
        return workflow;
    }

    pub fn add_node(self: *Workflow, node: WorkflowNode) bool {
        std.debug.assert(node.node_id > 0);
        if (self.nodes_len >= MAX_WORKFLOW_NODES) {
            return false;
        }
        self.nodes[self.nodes_len] = node;
        self.nodes_len += 1;
        return true;
    }

    pub fn add_edge(self: *Workflow, edge: WorkflowEdge) bool {
        std.debug.assert(edge.from_node_id > 0);
        std.debug.assert(edge.to_node_id > 0);
        if (self.edges_len >= MAX_WORKFLOW_EDGES) {
            return false;
        }
        self.edges[self.edges_len] = edge;
        self.edges_len += 1;
        return true;
    }

    pub fn find_node(self: *const Workflow, node_id: u32) ?*const
WorkflowNode {
        std.debug.assert(node_id > 0);
        var i: u32 = 0;
        while (i < self.nodes_len) : (i += 1) {
            if (self.nodes[i].node_id == node_id) {
                return &self.nodes[i];
            }
        }
        return null;
    }
};

// Workflow engine: executes workflows.
pub const WorkflowEngine = struct {
    workflows: [64]Workflow,
    workflows_len: u32,
    next_workflow_id: u32,
    event_bus: *event_bus.EventBus,
    agent_coordinator: *agent_coordinator.AgentCoordinator,

    pub fn init(
        event_bus_instance: *event_bus.EventBus,
        coordinator_instance: *agent_coordinator.AgentCoordinator,
    ) WorkflowEngine {
        std.debug.assert(event_bus_instance != null);
        std.debug.assert(coordinator_instance != null);
        var engine = WorkflowEngine{
            .workflows = undefined,
            .workflows_len = 0,
            .next_workflow_id = 1,
            .event_bus = event_bus_instance,
            .agent_coordinator = coordinator_instance,
        };
        var i: u32 = 0;
        while (i < 64) : (i += 1) {
            engine.workflows[i] = Workflow.init(0, "", 0);
        }
        return engine;
    }

    // Create workflow.
    pub fn create_workflow(
        self: *WorkflowEngine,
        name: []const u8,
        timestamp: u64,
    ) ?u32 {
        std.debug.assert(name.len > 0);
        std.debug.assert(timestamp > 0);
        if (self.workflows_len >= 64) {
            return null;
        }
        const workflow_id = self.next_workflow_id;
        self.next_workflow_id += 1;
        self.workflows[self.workflows_len] = Workflow.init(workflow_id,
name, timestamp);
        self.workflows_len += 1;
        return workflow_id;
    }

    // Find workflow by ID.
    pub fn find_workflow(self: *WorkflowEngine, workflow_id: u32)
?*Workflow {
        std.debug.assert(workflow_id > 0);
        var i: u32 = 0;
        while (i < self.workflows_len) : (i += 1) {
            if (self.workflows[i].workflow_id == workflow_id) {
                return &self.workflows[i];
            }
        }
        return null;
    }

    // Execute workflow (iterative topological sort).
    pub fn execute_workflow(
        self: *WorkflowEngine,
        workflow_id: u32,
        timestamp: u64,
    ) bool {
        std.debug.assert(workflow_id > 0);
        std.debug.assert(timestamp > 0);
        const workflow = self.find_workflow(workflow_id);
        if (workflow == null) {
            return false;
        }
        if (workflow.?.status != WorkflowStatus.pending) {
            return false;
        }
        workflow.?.status = WorkflowStatus.running;
        workflow.?.started_at = timestamp;
        _ = self.event_bus.publish_event(
            event_bus.EventType.workflow_started,
            workflow_id,
            0,
            timestamp,
        );
        // Topological sort (iterative, no recursion).
        var ready_nodes: [MAX_WORKFLOW_NODES]u32 = undefined;
        var ready_count: u32 = 0;
        var in_degree: [MAX_WORKFLOW_NODES]u32 = undefined;
        var i: u32 = 0;
        while (i < workflow.?.nodes_len) : (i += 1) {
            in_degree[i] = 0;
        }
        i = 0;
        while (i < workflow.?.edges_len) : (i += 1) {
            const edge = &workflow.?.edges[i];
            var j: u32 = 0;
            var to_idx: u32 = 0;
            var found: bool = false;
            while (j < workflow.?.nodes_len) : (j += 1) {
                if (workflow.?.nodes[j].node_id == edge.to_node_id) {
                    to_idx = j;
                    found = true;
                    break;
                }
            }
            if (found) {
                in_degree[to_idx] += 1;
            }
        }
        i = 0;
        while (i < workflow.?.nodes_len) : (i += 1) {
            if (in_degree[i] == 0) {
                ready_nodes[ready_count] = i;
                ready_count += 1;
            }
        }
        var processed: u32 = 0;
        while (processed < ready_count) {
            const node_idx = ready_nodes[processed];
            const node = &workflow.?.nodes[node_idx];
            node.status = NodeStatus.running;
            node.started_at = timestamp;
            // Execute node (placeholder - actual execution via agent
coordinator).
            node.status = NodeStatus.completed;
            node.completed_at = timestamp;
            _ = self.event_bus.publish_event(
                event_bus.EventType.task_completed,
                node.agent_id,
                workflow_id,
                timestamp,
            );
            processed += 1;
            i = 0;
            while (i < workflow.?.edges_len) : (i += 1) {
                const edge = &workflow.?.edges[i];
                if (edge.from_node_id == node.node_id) {
                    var j: u32 = 0;
                    var to_idx: u32 = 0;
                    var found: bool = false;
                    while (j < workflow.?.nodes_len) : (j += 1) {
                        if (workflow.?.nodes[j].node_id ==
edge.to_node_id) {
                            to_idx = j;
                            found = true;
                            break;
                        }
                    }
                    if (found) {
                        in_degree[to_idx] -= 1;
                        if (in_degree[to_idx] == 0) {
                            ready_nodes[ready_count] = to_idx;
                            ready_count += 1;
                        }
                    }
                }
            }
        }
        if (processed == workflow.?.nodes_len) {
            workflow.?.status = WorkflowStatus.completed;
            workflow.?.completed_at = timestamp;
            _ = self.event_bus.publish_event(
                event_bus.EventType.workflow_completed,
                workflow_id,
                0,
                timestamp,
            );
        } else {
            workflow.?.status = WorkflowStatus.failed;
            workflow.?.completed_at = timestamp;
            _ = self.event_bus.publish_event(
                event_bus.EventType.workflow_failed,
                workflow_id,
                0,
                timestamp,
            );
        }
        return true;
    }

    // Get workflow count.
    pub fn get_workflow_count(self: *const WorkflowEngine) u32 {
        return self.workflows_len;
    }
};

