// Grain Silo root module
// Re-exports all Grain Silo components

pub const Storage = @import("storage.zig").Storage;


// === grain_silo/storage.zig ===

const std = @import("std");

/// Grain Silo: Object storage abstraction (Turbopuffer replacement).
/// ~<~ Glow Airbend: explicit storage state, bounded object management.
/// ~~~~ Glow Waterbend: deterministic storage operations, iterative
algorithms.
///
/// Represents the storage layer: S3-compatible object storage for cold
data,
/// with hot cache integration via Grain Field SRAM.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
///
/// 2025-11-23-114146-pst: Active implementation
pub const Storage = struct {
    // Bounded: Max object key length (explicit limit)
    // 2025-11-23-114146-pst: Active constant
    pub const MAX_OBJECT_KEY_LEN: u32 = 1_024;

    // Bounded: Max object size (explicit limit, in bytes)
    // 2025-11-23-114146-pst: Active constant
    pub const MAX_OBJECT_SIZE: u64 = 1_073_741_824; // 1 GB

    // Bounded: Max objects (explicit limit)
    // 2025-11-23-114146-pst: Active constant
    pub const MAX_OBJECTS: u32 = 1_000_000;

    // Bounded: Max metadata size (explicit limit, in bytes)
    // 2025-11-23-114146-pst: Active constant
    pub const MAX_METADATA_SIZE: u32 = 65_536; // 64 KB

    /// Object structure.
    // 2025-11-23-114146-pst: Active struct
    pub const Object = struct {
        key: []const u8, // Object key (bounded)
        key_len: u32,
        data: []const u8, // Object data (bounded)
        data_len: u64,
        metadata: []const u8, // Object metadata (bounded)
        metadata_len: u32,
        created_at: u64, // Creation timestamp (Unix epoch)
        updated_at: u64, // Last update timestamp (Unix epoch)
        is_hot: bool, // Is object in hot cache (Grain Toroid SRAM)?
        hot_cache_offset: ?u64, // Hot cache offset (if in SRAM)
        allocator: std.mem.Allocator,

        /// Initialize object.
        // 2025-11-23-114146-pst: Active function
        pub fn init(allocator: std.mem.Allocator, key: []const u8, data:
[]const u8, metadata: []const u8) !Object {

            // Assert: Key, data, and metadata must be bounded
            std.debug.assert(key.len <= MAX_OBJECT_KEY_LEN);
            std.debug.assert(data.len <= MAX_OBJECT_SIZE);
            std.debug.assert(metadata.len <= MAX_METADATA_SIZE);

            // Get current timestamp
            const now = std.time.timestamp();

            // Allocate key
            const key_copy = try allocator.dupe(u8, key);
            errdefer allocator.free(key_copy);

            // Allocate data
            const data_copy = try allocator.dupe(u8, data);
            errdefer allocator.free(data_copy);

            // Allocate metadata
            const metadata_copy = try allocator.dupe(u8, metadata);
            errdefer allocator.free(metadata_copy);

            return Object{
                .key = key_copy,
                .key_len = @as(u32, @intCast(key_copy.len)),
                .data = data_copy,
                .data_len = @as(u64, @intCast(data_copy.len)),
                .metadata = metadata_copy,
                .metadata_len = @as(u32, @intCast(metadata_copy.len)),
                .created_at = @as(u64, @intCast(now)),
                .updated_at = @as(u64, @intCast(now)),
                .is_hot = false,
                .hot_cache_offset = null,
                .allocator = allocator,
            };
        }

        /// Deinitialize object and free memory.
        pub fn deinit(self: *Object) void {
            // Assert: Allocator must be valid (allocator is used below)
            _ = self.allocator;

            // Free key
            if (self.key_len > 0) {
                self.allocator.free(self.key);
            }

            // Free data
            if (self.data_len > 0) {
                self.allocator.free(self.data);
            }

            // Free metadata
            if (self.metadata_len > 0) {
                self.allocator.free(self.metadata);
            }

            self.* = undefined;
        }

        /// Mark object as hot (in SRAM cache).
        pub fn mark_hot(self: *Object, cache_offset: u64) void {
            self.is_hot = true;
            self.hot_cache_offset = cache_offset;
        }

        /// Mark object as cold (not in SRAM cache).
        pub fn mark_cold(self: *Object) void {
            self.is_hot = false;
            self.hot_cache_offset = null;
        }
    };

    /// Object storage structure.
    // 2025-11-23-114146-pst: Active struct
    pub const ObjectStorage = struct {
        objects: []Object, // Objects buffer (bounded)
        objects_len: u32, // Number of objects
        hot_cache_size: u64, // Hot cache size (SRAM capacity)
        hot_cache_used: u64, // Hot cache used (bytes)
        allocator: std.mem.Allocator,

        /// Initialize object storage.
        // 2025-11-23-114146-pst: Active function
        pub fn init(allocator: std.mem.Allocator, hot_cache_size: u64)
!ObjectStorage {
            // Assert: Allocator must be valid (allocator is used below)

            // Pre-allocate objects buffer
            const objects = try allocator.alloc(Object, MAX_OBJECTS);
            errdefer allocator.free(objects);

            return ObjectStorage{
                .objects = objects,
                .objects_len = 0,
                .hot_cache_size = hot_cache_size,
                .hot_cache_used = 0,
                .allocator = allocator,
            };
        }

        /// Deinitialize object storage and free memory.
        pub fn deinit(self: *ObjectStorage) void {
            // Assert: Allocator must be valid (check by attempting
allocation)
            _ = self.allocator;

            // Deinitialize all objects
            var i: u32 = 0;
            while (i < self.objects_len) : (i += 1) {
                self.objects[i].deinit();
            }

            // Free objects buffer
            self.allocator.free(self.objects);

            self.* = undefined;
        }

        /// Store object (cold storage).
        // 2025-11-23-114146-pst: Active function
        pub fn store_object(self: *ObjectStorage, key: []const u8, data:
[]const u8, metadata: []const u8) !void {
            // Check objects limit
            if (self.objects_len >= MAX_OBJECTS) {
                return error.TooManyObjects;
            }

            // Check if object already exists
            if (self.find_object(key)) |_| {
                return error.ObjectExists;
            }

            // Create object
            var object = try Object.init(self.allocator, key, data,
metadata);
            errdefer object.deinit();

            // Store object
            self.objects[self.objects_len] = object;
            self.objects_len += 1;
        }

        /// Get object by key.
        pub fn get_object(self: *ObjectStorage, key: []const u8)
?*Object {
            return self.find_object(key);
        }

        /// Promote object to hot cache (move to SRAM).
        // 2025-11-23-114146-pst: Active function
        pub fn promote_to_hot(self: *ObjectStorage, key: []const u8,
cache_offset: u64) !void {
            if (self.find_object(key)) |object| {
                // Check hot cache capacity
                if (self.hot_cache_used + object.data_len >
self.hot_cache_size) {
                    return error.HotCacheFull;
                }

                // Mark as hot
                object.mark_hot(cache_offset);
                self.hot_cache_used += object.data_len;
            } else {
                return error.ObjectNotFound;
            }
        }

        /// Demote object from hot cache (move to cold storage).
        pub fn demote_from_hot(self: *ObjectStorage, key: []const u8)
void {
            if (self.find_object(key)) |object| {
                if (object.is_hot) {
                    self.hot_cache_used -= object.data_len;
                    object.mark_cold();
                }
            }
        }

        /// Find object by key (internal helper).
        fn find_object(self: *ObjectStorage, key: []const u8) ?*Object {
            var i: u32 = 0;
            while (i < self.objects_len) : (i += 1) {
                if (std.mem.eql(u8, self.objects[i].key, key)) {
                    return &self.objects[i];
                }
            }
            return null;
        }
    };
};


// === grain_skate/ai_insights.zig ===

const std = @import("std");
const EditorDagIntegration =
@import("editor_dag_integration.zig").EditorDagIntegration;
const Block = @import("block.zig").Block;
const Glm46Client = @import("../aurora_glm46.zig").Glm46Client;

/// AI-Powered Graph Insights: GLM-4.6 powered insights for knowledge
graph.
/// ~<~ Glow Airbend: explicit AI suggestions, bounded analysis.
/// ~~~~ Glow Waterbend: AI insights flow deterministically through DAG.
///
/// This implements AI-powered knowledge graph management:
/// - Auto-suggest connections between blocks (semantic similarity)
/// - Detect knowledge gaps (missing links between related blocks)
/// - Summarize subgraphs (AI-generated summaries)
/// - Generate block titles from content (auto-titling)
/// - Semantic clustering (group related blocks visually)
pub const AiInsights = struct {
    allocator: std.mem.Allocator,
    dag_integration: *EditorDagIntegration,
    block_storage: *Block.BlockStorage,
    glm46_client: ?Glm46Client, // Optional GLM-4.6 client (if API key
provided)
    
    // Bounded: Max 100 AI suggestions per session
    pub const MAX_AI_SUGGESTIONS: u32 = 100;
    
    // Bounded: Max 10 blocks per analysis batch
    pub const MAX_BLOCKS_PER_BATCH: u32 = 10;
    
    /// AI suggestion for block connection.
    pub const ConnectionSuggestion = struct {
        from_block_id: u64,
        to_block_id: u64,
        confidence: f32, // 0.0 to 1.0
        reason: []const u8, // AI-generated reason for connection
        reason_len: u32,
    };
    
    /// AI suggestion for block title.
    pub const TitleSuggestion = struct {
        block_id: u64,
        suggested_title: []const u8,
        title_len: u32,
        confidence: f32, // 0.0 to 1.0
    };
    
    /// Initialize AI insights (without GLM-4.6 client).
    pub fn init(
        allocator: std.mem.Allocator,
        dag_integration: *EditorDagIntegration,
        block_storage: *Block.BlockStorage,
    ) AiInsights {
        // Assert: Allocator must be valid
        std.debug.assert(allocator.ptr != null);
        
        // Assert: DAG integration must be valid
        std.debug.assert(dag_integration.buffer_node_id != null);
        
        // Assert: Block storage must be valid
        _ = block_storage;
        
        return AiInsights{
            .allocator = allocator,
            .dag_integration = dag_integration,
            .block_storage = block_storage,
            .glm46_client = null,
        };
    }
    
    /// Initialize AI insights with GLM-4.6 client (for AI-powered
features).
    pub fn init_with_glm46(
        allocator: std.mem.Allocator,
        dag_integration: *EditorDagIntegration,
        block_storage: *Block.BlockStorage,
        api_key: []const u8,
    ) AiInsights {
        // Assert: Allocator must be valid
        std.debug.assert(allocator.ptr != null);
        
        // Assert: DAG integration must be valid
        std.debug.assert(dag_integration.buffer_node_id != null);
        
        // Assert: API key must be provided
        std.debug.assert(api_key.len > 0);
        
        // Assert: Block storage must be valid
        _ = block_storage;
        
        const glm46_client = Glm46Client.init(allocator, api_key);
        
        return AiInsights{
            .allocator = allocator,
            .dag_integration = dag_integration,
            .block_storage = block_storage,
            .glm46_client = glm46_client,
        };
    }
    
    /// Deinitialize AI insights (cleanup GLM-4.6 client if present).
    pub fn deinit(self: *AiInsights) void {
        if (self.glm46_client) |*client| {
            client.deinit();
        }
        self.* = undefined;
    }
    
    /// Global buffer for collecting streaming responses
(single-threaded use).
    /// Note: This is a workaround for callback limitations in GLM-4.6
client.
    var global_response_buffer: ?*std.ArrayList(u8) = null;
    
    /// Callback for collecting streaming GLM-4.6 response chunks.
    fn collect_chunk_callback(chunk: []const u8) void {
        if (global_response_buffer) |buffer| {
            buffer.writer().writeAll(chunk) catch {};
        }
    }
    
    /// Collect streaming GLM-4.6 response into a single string.
    fn collect_glm46_response(
        self: *AiInsights,
        messages: []const Glm46Client.Message,
    ) ![]const u8 {
        // Assert: GLM-4.6 client must be available
        std.debug.assert(self.glm46_client != null);
        
        // Assert: Messages must be within bounds
        std.debug.assert(messages.len > 0);
        
        var response_buffer_local =
std.ArrayList(u8).init(self.allocator);
        errdefer response_buffer_local.deinit();
        
        const client = &self.glm46_client.?;
        
        // Set global buffer (single-threaded use)
        global_response_buffer = &response_buffer_local;
        defer global_response_buffer = null;
        
        // Collect streaming chunks
        try client.requestCompletion(messages, collect_chunk_callback);
        
        return try response_buffer_local.toOwnedSlice();
    }
    
    /// Analyze blocks and suggest connections (semantic similarity).
    /// Returns array of connection suggestions.
    pub fn suggest_connections(
        self: *AiInsights,
        block_ids: []const u64,
    ) ![]const ConnectionSuggestion {
        // Assert: Block count must be within bounds
        std.debug.assert(block_ids.len <= MAX_BLOCKS_PER_BATCH);
        
        // Assert: Block count must be at least 2 for connections
        std.debug.assert(block_ids.len >= 2);
        
        // If GLM-4.6 client not available, return empty suggestions
        if (self.glm46_client == null) {
            return &[_]ConnectionSuggestion{};
        }
        
        // Get block contents
        var block_contents = std.ArrayList([]const
u8).init(self.allocator);
        defer {
            for (block_contents.items) |content| {
                self.allocator.free(content);
            }
            block_contents.deinit();
        }
        
        for (block_ids) |block_id| {
            const block = self.block_storage.get_block(@as(u32,
@intCast(block_id))) orelse continue;
            const content = try self.allocator.dupe(u8,
block.content[0..block.content_len]);
            try block_contents.append(content);
        }
        
        // Build prompt for GLM-4.6
        var prompt = std.ArrayList(u8).init(self.allocator);
        defer prompt.deinit();
        
        const writer = prompt.writer();
        try writer.writeAll("Analyze these knowledge graph blocks and
suggest connections between them based on semantic similarity. For each
suggested connection, provide: block1_id, block2_id, confidence
(0.0-1.0), and reason.\n\n");
        
        for (block_ids, 0..) |block_id, i| {
            if (i < block_contents.items.len) {
                try writer.print("Block {d}:\n{s}\n\n", .{ block_id,
block_contents.items[i] });
            }
        }
        
        try writer.writeAll("Format:
block1_id,block2_id,confidence,reason (one per line)");
        
        const messages = [_]Glm46Client.Message{
            .{ .role = "system", .content = "You are a knowledge graph
analysis assistant. Analyze blocks and suggest semantic connections." },
            .{ .role = "user", .content = try prompt.toOwnedSlice() },
        };
        defer self.allocator.free(messages[1].content);
        
        // Get AI response
        const response = try self.collect_glm46_response(&messages);
        defer self.allocator.free(response);
        
        // Parse response (simple CSV-like format)
        var suggestions =
std.ArrayList(ConnectionSuggestion).init(self.allocator);
        errdefer {
            for (suggestions.items) |*suggestion| {
                self.allocator.free(suggestion.reason);
            }
            suggestions.deinit();
        }
        
        // Parse lines (simple implementation)
        var lines = std.mem.split(u8, response, "\n");
        while (lines.next()) |line| {
            if (line.len == 0) continue;
            
            var fields = std.mem.split(u8, line, ",");
            const from_id_str = fields.next() orelse continue;
            const to_id_str = fields.next() orelse continue;
            const conf_str = fields.next() orelse continue;
            const reason_str = fields.rest();
            
            const from_id = std.fmt.parseInt(u64, from_id_str, 10) catch
continue;
            const to_id = std.fmt.parseInt(u64, to_id_str, 10) catch
continue;
            const confidence = std.fmt.parseFloat(f32, conf_str) catch
0.5;
            
            const reason = try self.allocator.dupe(u8, reason_str);
            
            try suggestions.append(ConnectionSuggestion{
                .from_block_id = from_id,
                .to_block_id = to_id,
                .confidence = confidence,
                .reason = reason,
                .reason_len = @as(u32, @intCast(reason.len)),
            });
        }
        
        return try suggestions.toOwnedSlice();
    }
    
    /// Detect knowledge gaps (missing links between related blocks).
    /// Returns array of block ID pairs that should be linked.
    pub fn detect_knowledge_gaps(
        self: *AiInsights,
        block_ids: []const u64,
    ) ![]const struct { from_block_id: u64, to_block_id: u64 } {
        // Assert: Block count must be within bounds
        std.debug.assert(block_ids.len <= MAX_BLOCKS_PER_BATCH);
        
        // If GLM-4.6 client not available, return empty gaps
        if (self.glm46_client == null) {
            return &[_]struct { from_block_id: u64, to_block_id: u64 }{};
        }
        
        // Get block contents and existing links
        var block_contents = std.ArrayList([]const
u8).init(self.allocator);
        defer {
            for (block_contents.items) |content| {
                self.allocator.free(content);
            }
            block_contents.deinit();
        }
        
        for (block_ids) |block_id| {
            const block = self.block_storage.get_block(@as(u32,
@intCast(block_id))) orelse continue;
            const content = try self.allocator.dupe(u8,
block.content[0..block.content_len]);
            try block_contents.append(content);
        }
        
        // Build prompt for GLM-4.6
        var prompt = std.ArrayList(u8).init(self.allocator);
        defer prompt.deinit();
        
        const writer = prompt.writer();
        try writer.writeAll("Analyze these knowledge graph blocks and
identify missing connections (knowledge gaps). For each gap, provide:
block1_id,block2_id (one per line).\n\n");
        
        for (block_ids, 0..) |block_id, i| {
            if (i < block_contents.items.len) {
                try writer.print("Block {d}:\n{s}\n\n", .{ block_id,
block_contents.items[i] });
            }
        }
        
        const messages = [_]Glm46Client.Message{
            .{ .role = "system", .content = "You are a knowledge graph
analysis assistant. Identify missing connections between related
blocks." },
            .{ .role = "user", .content = try prompt.toOwnedSlice() },
        };
        defer self.allocator.free(messages[1].content);
        
        // Get AI response
        const response = try self.collect_glm46_response(&messages);
        defer self.allocator.free(response);
        
        // Parse response (simple CSV-like format)
        var gaps = std.ArrayList(struct { from_block_id: u64,
to_block_id: u64 }).init(self.allocator);
        errdefer gaps.deinit();
        
        // Parse lines
        var lines = std.mem.split(u8, response, "\n");
        while (lines.next()) |line| {
            if (line.len == 0) continue;
            
            var fields = std.mem.split(u8, line, ",");
            const from_id_str = fields.next() orelse continue;
            const to_id_str = fields.next() orelse continue;
            
            const from_id = std.fmt.parseInt(u64, from_id_str, 10) catch
continue;
            const to_id = std.fmt.parseInt(u64, to_id_str, 10) catch
continue;
            
            try gaps.append(.{
                .from_block_id = from_id,
                .to_block_id = to_id,
            });
        }
        
        return try gaps.toOwnedSlice();
    }
    
    /// Generate block title from content (auto-titling).
    /// Returns suggested title for the block.
    pub fn suggest_title(
        self: *AiInsights,
        block_id: u64,
    ) !?TitleSuggestion {
        // Assert: Block ID must be valid
        _ = block_id;
        
        // If GLM-4.6 client not available, return null
        if (self.glm46_client == null) {
            return null;
        }
        
        // Get block content
        const block = self.block_storage.get_block(@as(u32,
@intCast(block_id))) orelse return null;
        
        // Build prompt for GLM-4.6
        var prompt = std.ArrayList(u8).init(self.allocator);
        defer prompt.deinit();
        
        const writer = prompt.writer();
        try writer.print("Generate a concise title (max 50 characters)
for this knowledge graph block:\n\n{s}\n\nTitle only, no explanation.",
.{block.content[0..block.content_len]});
        
        const messages = [_]Glm46Client.Message{
            .{ .role = "system", .content = "You are a knowledge graph
assistant. Generate concise, descriptive titles for blocks." },
            .{ .role = "user", .content = try prompt.toOwnedSlice() },
        };
        defer self.allocator.free(messages[1].content);
        
        // Get AI response
        const response = try self.collect_glm46_response(&messages);
        defer self.allocator.free(response);
        
        // Trim whitespace and limit length
        const trimmed = std.mem.trim(u8, response, " \n\r\t");
        const max_len = @min(trimmed.len, Block.MAX_BLOCK_TITLE);
        const title = try self.allocator.dupe(u8, trimmed[0..max_len]);
        
        return TitleSuggestion{
            .block_id = block_id,
            .suggested_title = title,
            .title_len = @as(u32, @intCast(max_len)),
            .confidence = 0.8, // Default confidence
        };
    }
    
    /// Summarize subgraph (AI-generated summary).
    /// Returns summary text for the subgraph.
    pub fn summarize_subgraph(
        self: *AiInsights,
        block_ids: []const u64,
    ) !?[]const u8 {
        // Assert: Block count must be within bounds
        std.debug.assert(block_ids.len <= MAX_BLOCKS_PER_BATCH);
        
        // If GLM-4.6 client not available, return null
        if (self.glm46_client == null) {
            return null;
        }
        
        // Get block contents
        var block_contents = std.ArrayList([]const
u8).init(self.allocator);
        defer {
            for (block_contents.items) |content| {
                self.allocator.free(content);
            }
            block_contents.deinit();
        }
        
        for (block_ids) |block_id| {
            const block = self.block_storage.get_block(@as(u32,
@intCast(block_id))) orelse continue;
            const content = try self.allocator.dupe(u8,
block.content[0..block.content_len]);
            try block_contents.append(content);
        }
        
        // Build prompt for GLM-4.6
        var prompt = std.ArrayList(u8).init(self.allocator);
        defer prompt.deinit();
        
        const writer = prompt.writer();
        try writer.writeAll("Summarize this knowledge graph subgraph in
2-3 sentences:\n\n");
        
        for (block_ids, 0..) |block_id, i| {
            if (i < block_contents.items.len) {
                try writer.print("Block {d}:\n{s}\n\n", .{ block_id,
block_contents.items[i] });
            }
        }
        
        const messages = [_]Glm46Client.Message{
            .{ .role = "system", .content = "You are a knowledge graph
assistant. Provide concise summaries of subgraphs." },
            .{ .role = "user", .content = try prompt.toOwnedSlice() },
        };
        defer self.allocator.free(messages[1].content);
        
        // Get AI response
        const response = try self.collect_glm46_response(&messages);
        
        // Return summary (caller owns the memory)
        return response;
    }
    
    /// Store AI suggestion as DAG event (for deterministic replay).
    pub fn store_suggestion_as_dag_event(
        self: *AiInsights,
        suggestion_type: SuggestionType,
        suggestion_data: []const u8,
    ) !u64 {
        // Assert: Buffer node must exist
        std.debug.assert(self.dag_integration.buffer_node_id != null);
        
        // Assert: Event count must be within bounds
        std.debug.assert(self.dag_integration.dag.pending_events_len <
EditorDagIntegration.MAX_EVENTS_PER_SESSION);
        
        // Create event data (suggestion type + data)
        var event_data = std.ArrayList(u8).init(self.allocator);
        defer event_data.deinit();
        
        const writer = event_data.writer();
        try writer.print("ai_suggestion:{s}:",
.{@tagName(suggestion_type)});
        try writer.writeAll(suggestion_data);
        
        // Create parent event IDs (reference last event)
        var parent_events: []const u64 = &.{};
        const last_event_id = self.dag_integration.get_last_event_id();
        if (last_event_id > 0) {
            parent_events = &.{last_event_id};
        }
        
        // Add event to DAG (ai_completion type) and update last event ID
        const event_id = try
self.dag_integration.add_event_and_update_last(
            .ai_completion,
            try event_data.toOwnedSlice(),
            parent_events,
        );
        
        return event_id;
    }
    
    /// Type of AI suggestion.
    pub const SuggestionType = enum(u8) {
        connection, // Connection suggestion between blocks
        title, // Title suggestion for block
        summary, // Summary suggestion for subgraph
        gap, // Knowledge gap detection
    };
};

test "ai insights initialization" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag_integration = try
EditorDagIntegration.init(arena.allocator());
    defer dag_integration.deinit();
    
    const content = "line1\nline2\nline3";
    _ = try dag_integration.create_buffer_node(content);
    
    var block_storage = try Block.BlockStorage.init(arena.allocator());
    defer block_storage.deinit();
    
    var ai_insights = AiInsights.init(arena.allocator(),
&dag_integration, &block_storage);
    
    // Assert: AI insights initialized
    _ = ai_insights;
}

test "ai insights store suggestion as dag event" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag_integration = try
EditorDagIntegration.init(arena.allocator());
    defer dag_integration.deinit();
    
    const content = "line1\nline2\nline3";
    _ = try dag_integration.create_buffer_node(content);
    
    var block_storage = try Block.BlockStorage.init(arena.allocator());
    defer block_storage.deinit();
    
    var ai_insights = AiInsights.init(arena.allocator(),
&dag_integration, &block_storage);
    
    // Store suggestion as DAG event
    const event_id = try ai_insights.store_suggestion_as_dag_event(
        .connection,
        "block1->block2:high_similarity",
    );
    
    // Assert: Event was created
    try std.testing.expect(event_id > 0);
    try std.testing.expect(dag_integration.dag.pending_events_len == 1);
}


// === grain_skate/app.zig ===

//! Grain Skate Application: Main application integrating all components.
//!
//! Why: Unified application connecting window, editor, graph, and
blocks.
//! Architecture: Component integration, event-driven updates.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-11-24-111000-pst: Active implementation

const std = @import("std");
const Block = @import("block.zig").Block;
const Editor = @import("editor.zig").Editor;
const SkateWindow = @import("window.zig").SkateWindow;
const ModalEditor = @import("modal_editor.zig").ModalEditor;
const GraphVisualization = @import("graph_viz.zig").GraphVisualization;
const Social = @import("social.zig").Social;
const StorageIntegration =
@import("storage_integration.zig").StorageIntegration;
const events = @import("platform/events.zig");

// Bounded: Max blocks in application.
// 2025-11-24-111000-pst: Active constant
pub const MAX_APP_BLOCKS: u32 = 10_000;

// Bounded: Max pending operations.
// 2025-11-24-111000-pst: Active constant
pub const MAX_PENDING_OPS: u32 = 256;

// Auto-save timeout (seconds of inactivity before auto-save)
// 2025-12-02-170157-pst: Active constant
pub const AUTO_SAVE_TIMEOUT_SEC: u64 = 30; // 30 seconds

// Application state.
// 2025-11-24-111000-pst: Active struct
pub const GrainSkateApp = struct {
    block_storage: *Block.BlockStorage,
    window: *SkateWindow,
    modal_editor: ?*ModalEditor,
    graph_viz: *GraphVisualization,
    social_manager: *Social.SocialManager,
    storage_integration: ?*StorageIntegration.Integration,
    last_edit_time: u64, // Last edit timestamp (Unix seconds) for
auto-save
    allocator: std.mem.Allocator,

    /// Initialize Grain Skate application.
    // 2025-11-24-111000-pst: Active function
    pub fn init(
        allocator: std.mem.Allocator,
        block_storage: *Block.BlockStorage,
        window: *SkateWindow,
    ) !GrainSkateApp {
        // Initialize graph visualization
        const graph_viz = try allocator.create(GraphVisualization);
        graph_viz.* = GraphVisualization.init(allocator);
        errdefer allocator.destroy(graph_viz);

        // Initialize social manager
        const social_manager = try
allocator.create(Social.SocialManager);
        social_manager.* = try Social.SocialManager.init(allocator,
block_storage);
        errdefer social_manager.deinit();
        errdefer allocator.destroy(social_manager);

        const now = std.time.timestamp();
        return GrainSkateApp{
            .block_storage = block_storage,
            .window = window,
            .modal_editor = null,
            .graph_viz = graph_viz,
            .social_manager = social_manager,
            .storage_integration = null,
            .last_edit_time = @as(u64, @intCast(now)),
            .allocator = allocator,
        };
    }

    /// Deinitialize Grain Skate application.
    // 2025-11-24-111000-pst: Active function
    pub fn deinit(self: *GrainSkateApp) void {
        // Clean up modal editor
        if (self.modal_editor) |modal_editor| {
            modal_editor.deinit();
            self.allocator.destroy(modal_editor);
        }

        // Clean up storage integration
        if (self.storage_integration) |storage_integration| {
            storage_integration.deinit();
            self.allocator.destroy(storage_integration);
        }

        // Clean up social manager
        self.social_manager.deinit();
        self.allocator.destroy(self.social_manager);

        // Clean up graph visualization
        self.allocator.destroy(self.graph_viz);

        self.* = undefined;
    }

    /// Load blocks into graph visualization.
    // 2025-11-24-111000-pst: Active function
    pub fn load_blocks_to_graph(self: *GrainSkateApp) void {
        // Clear existing graph
        self.graph_viz.nodes_len = 0;
        self.graph_viz.edges_len = 0;

        // Add all blocks as nodes
        var i: u32 = 0;
        while (i < self.block_storage.blocks_len) : (i += 1) {
            const block = &self.block_storage.blocks[i];
            if (block.id > 0) {
                self.graph_viz.add_block(block.id);

                // Add links as edges
                var j: u32 = 0;
                while (j < block.links_len) : (j += 1) {
                    self.graph_viz.add_link(block.id, block.links[j]);
                }
            }
        }

        // Calculate layout
        self.graph_viz.calculate_layout(50);

        // Set graph visualization in window for rendering
        try self.window.set_graph_viz(self.graph_viz);

        // Set block storage for title rendering
        self.window.set_block_storage(self.block_storage);
    }

    /// Open block for editing.
    // 2025-11-24-111000-pst: Active function
    pub fn open_block(self: *GrainSkateApp, block_id: u32) !void {
        std.debug.assert(block_id > 0);
        const block = self.block_storage.get_block(block_id) orelse
return;

        // Set block in window
        try self.window.set_current_block(block);

        // Initialize modal editor if needed
        if (self.window.get_editor()) |editor| {
            if (self.modal_editor == null) {
                const modal_editor = try
self.allocator.create(ModalEditor);
                modal_editor.* = try ModalEditor.init(self.allocator,
editor);
                self.modal_editor = modal_editor;
            }
        }

        // Select block in graph
        self.graph_viz.select_block(block_id);
    }

    /// Create new block.
    // 2025-11-24-111000-pst: Active function
    pub fn create_block(self: *GrainSkateApp, title: []const u8,
content: []const u8) !u32 {
        const block_id = try self.block_storage.create_block(title,
content);
        // Add to graph
        self.graph_viz.add_block(block_id);
        // Recalculate layout
        self.graph_viz.calculate_layout(50);
        return block_id;
    }

    /// Link two blocks.
    // 2025-11-24-111000-pst: Active function
    pub fn link_blocks(self: *GrainSkateApp, from_id: u32, to_id: u32)
!void {
        std.debug.assert(from_id > 0);
        std.debug.assert(to_id > 0);
        try self.block_storage.link_blocks(from_id, to_id);
        // Add link to graph
        self.graph_viz.add_link(from_id, to_id);
        // Recalculate layout
        self.graph_viz.calculate_layout(50);
    }

    /// Update current block content.
    // 2025-11-24-111000-pst: Active function
    pub fn update_current_block(self: *GrainSkateApp, new_content:
[]const u8) !void {
        const block_id = self.window.get_current_block_id() orelse
return;
        try self.block_storage.update_content(block_id, new_content);
        // Reset last edit time after save (manual or auto)
        const now = std.time.timestamp();
        self.last_edit_time = @as(u64, @intCast(now));
    }

    /// Perform auto-save if content is modified and timeout elapsed.
    // 2025-12-02-170157-pst: Active function
    pub fn check_auto_save(self: *GrainSkateApp) void {
        // Only auto-save if editor is active and has modified content
        if (self.window.get_editor()) |editor| {
            if (self.window.get_editor_renderer()) |renderer| {
                if (!renderer.modified) {
                    return; // No modifications, skip auto-save
                }
                // Check if auto-save timeout has elapsed
                const now = std.time.timestamp();
                const now_u64 = @as(u64, @intCast(now));
                const elapsed = if (now_u64 > self.last_edit_time)
                    now_u64 - self.last_edit_time
                else
                    0;
                if (elapsed >= AUTO_SAVE_TIMEOUT_SEC) {
                    // Perform auto-save
                    const content = editor.buffer.get_content() catch
|err| {
                        // Display error message
                        if (self.window.get_editor_renderer())
|renderer| {
                            const err_msg = "Failed to get content";
                            renderer.set_error(err_msg, 5); // 5 second
timeout
                        }
                        return;
                    };
                    defer editor.allocator.free(content);
                    self.update_current_block(content) catch |err| {
                        // Display error message
                        if (self.window.get_editor_renderer())
|renderer| {
                            const err_msg = "Failed to save block";
                            renderer.set_error(err_msg, 5); // 5 second
timeout
                        }
                        return;
                    };
                    // Clear modified flag after successful auto-save
                    renderer.set_modified(false);
                }
            }
        }
    }

    /// Update last edit time (call when content is modified).
    // 2025-12-02-170157-pst: Active function
    pub fn update_last_edit_time(self: *GrainSkateApp) void {
        const now = std.time.timestamp();
        self.last_edit_time = @as(u64, @intCast(now));
    }

    /// Get graph visualization.
    // 2025-11-24-111000-pst: Active function
    pub fn get_graph(self: *const GrainSkateApp) *GraphVisualization {
        return self.graph_viz;
    }

    /// Get social manager.
    // 2025-11-24-111000-pst: Active function
    pub fn get_social(self: *const GrainSkateApp) *Social.SocialManager {
        return self.social_manager;
    }

    /// Handle mouse click on graph (open block if node clicked).
    // 2025-11-24-172500-pst: Active function
    pub fn handle_graph_click(self: *GrainSkateApp, x: f64, y: f64) void
{
        if (self.window.handle_mouse_click(x, y)) |block_id| {
            // Open block if node was clicked
            self.open_block(block_id) catch |err| {
                // Ignore errors (block might not exist)
                _ = err;
            };
        }
    }

    /// Handle window resize event (update graph renderer and layout).
    // 2025-11-24-181000-pst: Active function
    pub fn handle_window_resize(self: *GrainSkateApp, new_width: u32,
new_height: u32) !void {
        // Update window and renderer
        try self.window.handle_resize(new_width, new_height);
        // Graph visualization layout will adapt automatically on next
render
    }

    /// Handle keyboard event (route to modal editor if editor is
active).
    // 2025-12-02-151416-pst: Active function
    pub fn handle_keyboard_event(self: *GrainSkateApp, event:
events.KeyboardEvent) bool {
        // Don't intercept Ctrl+Alt (for OS window management)
        if (event.modifiers.control and event.modifiers.option) {
            return false; // Let OS handle it
        }
        // Only handle key down events
        if (event.kind != .down) {
            return false;
        }
        // Route to modal editor if editor is active
        if (self.modal_editor) |modal_editor| {
            modal_editor.handle_key_event(event) catch |err| {
                // Display error message
                if (self.window.get_editor_renderer()) |renderer| {
                    const err_msg = "Failed to handle key event";
                    renderer.set_error(err_msg, 3); // 3 second timeout
                }
                return false;
            };
            // Check for command results (save, quit, etc.)
            const cmd_result = modal_editor.get_last_command_result();
            if (cmd_result == .save or cmd_result == .save_quit) {
                // Save editor content to block storage
                if (self.window.get_editor()) |editor| {
                    const content = editor.buffer.get_content() catch
|err| {
                        // Display error message
                        if (self.window.get_editor_renderer())
|renderer| {
                            const err_msg = "Failed to get content";
                            renderer.set_error(err_msg, 5); // 5 second
timeout
                        }
                    } else {
                        self.update_current_block(content) catch |err| {
                            // Display error message
                            if (self.window.get_editor_renderer())
|renderer| {
                                const err_msg = "Failed to save block";
                                renderer.set_error(err_msg, 5); // 5
second timeout
                            }
                        } else {
                            // Clear error on successful save
                            if (self.window.get_editor_renderer())
|renderer| {
                                renderer.clear_error();
                                renderer.set_modified(false);
                            }
                        }
                        // Free temporary content buffer
                        editor.allocator.free(content);
                    }
                }
            }
            // Handle quit commands
            var editor_was_closed = false;
            if (cmd_result == .save_quit or cmd_result == .quit or
cmd_result == .force_quit) {
                // Quit: close editor and return to graph view
                self.window.close_editor();
                // Clear modal editor reference
                if (self.modal_editor) |modal_editor| {
                    modal_editor.deinit();
                    self.allocator.destroy(modal_editor);
                    self.modal_editor = null;
                }
                editor_was_closed = true;
            }
            // Mark content as modified if editor has undo history
(indicates edits)
            if (!editor_was_closed and self.window.get_editor())
|editor| {
                if (editor.undo_history_len > 0) {
                    if (self.window.get_editor_renderer()) |renderer| {
                        renderer.set_modified(true);
                        // Update last edit time for auto-save tracking
                        self.update_last_edit_time();
                    }
                }
            }
            // Check for auto-save (only if editor is still active)
            if (!editor_was_closed) {
                self.check_auto_save();
            }
            // Render appropriate view (editor or graph)
            if (!editor_was_closed and self.window.get_editor())
|editor| {
                // Get command buffer for command mode display
                if (self.modal_editor) |modal_editor| {
                    const cmd_buf = if (editor.mode == .command)
                        modal_editor.get_command_string()
                    else
                        "";
                    // Render editor with command buffer and present
window
                    self.window.render_editor(cmd_buf);
                }
            } else {
                // Editor closed, render graph view instead
                self.window.render_graph();
            }
            self.window.window.present() catch |err| {
                _ = err;
            };
            return true; // Event was handled
        }
        return false; // No editor active, didn't handle
    }
};


// === grain_skate/block.zig ===

const std = @import("std");

/// Grain Skate Block: Text block with links in knowledge graph.
/// ~<~ Glow Airbend: explicit block state, bounded block storage.
/// ~~~~ Glow Waterbend: deterministic block linking, iterative
algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
///
/// 2025-11-23-114146-pst: Active implementation
pub const Block = struct {
    // Bounded: Max block content length (explicit limit, in bytes)
    // 2025-11-23-114146-pst: Active constant
    pub const MAX_BLOCK_CONTENT: u32 = 1_048_576; // 1 MB

    // Bounded: Max links per block (explicit limit)
    // 2025-11-23-114146-pst: Active constant
    pub const MAX_LINKS_PER_BLOCK: u32 = 256;

    // Bounded: Max block title length (explicit limit)
    // 2025-11-23-114146-pst: Active constant
    pub const MAX_BLOCK_TITLE: u32 = 512;

    /// Block structure.
    // 2025-11-23-114146-pst: Active struct
    pub const BlockData = struct {
        id: u32, // Block ID (unique identifier)
        title: []const u8, // Block title (bounded)
        title_len: u32,
        content: []const u8, // Block content (bounded)
        content_len: u32,
        created_at: u64, // Creation timestamp (Unix epoch)
        updated_at: u64, // Last update timestamp (Unix epoch)
        links: []u32, // Linked block IDs (bounded)
        links_len: u32,
        backlinks: []u32, // Blocks that link to this block (bounded)
        backlinks_len: u32,
        dag_node_id: ?u32, // Associated DAG node ID (if using DAG)
        allocator: std.mem.Allocator,

        /// Initialize block data.
        // 2025-11-23-114146-pst: Active function
        pub fn init(allocator: std.mem.Allocator, id: u32, title:
[]const u8, content: []const u8) !BlockData {

            // Assert: Title and content must be bounded
            std.debug.assert(title.len <= MAX_BLOCK_TITLE);
            std.debug.assert(content.len <= MAX_BLOCK_CONTENT);

            // Get current timestamp
            const now = std.time.timestamp();

            // Allocate title
            const title_copy = try allocator.dupe(u8, title);
            errdefer allocator.free(title_copy);

            // Allocate content
            const content_copy = try allocator.dupe(u8, content);
            errdefer allocator.free(content_copy);

            // Pre-allocate links buffer
            const links = try allocator.alloc(u32, MAX_LINKS_PER_BLOCK);
            errdefer allocator.free(links);

            // Pre-allocate backlinks buffer
            const backlinks = try allocator.alloc(u32,
MAX_LINKS_PER_BLOCK);
            errdefer allocator.free(backlinks);

            return BlockData{
                .id = id,
                .title = title_copy,
                .title_len = @as(u32, @intCast(title_copy.len)),
                .content = content_copy,
                .content_len = @as(u32, @intCast(content_copy.len)),
                .created_at = @as(u64, @intCast(now)),
                .updated_at = @as(u64, @intCast(now)),
                .links = links,
                .links_len = 0,
                .backlinks = backlinks,
                .backlinks_len = 0,
                .dag_node_id = null,
                .allocator = allocator,
            };
        }

        /// Deinitialize block data and free memory.
        pub fn deinit(self: *BlockData) void {
            // Assert: Allocator must be valid (check by attempting
deallocation)
            _ = self.allocator;

            // Free title
            if (self.title_len > 0) {
                self.allocator.free(self.title);
            }

            // Free content
            if (self.content_len > 0) {
                self.allocator.free(self.content);
            }

            // Free links
            self.allocator.free(self.links);

            // Free backlinks
            self.allocator.free(self.backlinks);

            self.* = undefined;
        }

        /// Add link to another block.
        pub fn add_link(self: *BlockData, target_block_id: u32) !void {
            // Check links limit
            if (self.links_len >= MAX_LINKS_PER_BLOCK) {
                return error.TooManyLinks;
            }

            // Check if link already exists
            var i: u32 = 0;
            while (i < self.links_len) : (i += 1) {
                if (self.links[i] == target_block_id) {
                    return; // Link already exists
                }
            }

            self.links[self.links_len] = target_block_id;
            self.links_len += 1;

            // Update timestamp
            const now = std.time.timestamp();
            self.updated_at = @as(u64, @intCast(now));
        }

        /// Remove link to another block.
        pub fn remove_link(self: *BlockData, target_block_id: u32) void {
            var i: u32 = 0;
            while (i < self.links_len) : (i += 1) {
                if (self.links[i] == target_block_id) {
                    // Shift remaining links left
                    var j: u32 = i;
                    while (j < self.links_len - 1) : (j += 1) {
                        self.links[j] = self.links[j + 1];
                    }
                    self.links_len -= 1;

                    // Update timestamp
                    const now = std.time.timestamp();
                    self.updated_at = @as(u64, @intCast(now));
                    return;
                }
            }
        }

        /// Add backlink (block that links to this block).
        pub fn add_backlink(self: *BlockData, source_block_id: u32)
!void {
            // Check backlinks limit
            if (self.backlinks_len >= MAX_LINKS_PER_BLOCK) {
                return error.TooManyBacklinks;
            }

            // Check if backlink already exists
            var i: u32 = 0;
            while (i < self.backlinks_len) : (i += 1) {
                if (self.backlinks[i] == source_block_id) {
                    return; // Backlink already exists
                }
            }

            self.backlinks[self.backlinks_len] = source_block_id;
            self.backlinks_len += 1;
        }

        /// Remove backlink.
        pub fn remove_backlink(self: *BlockData, source_block_id: u32)
void {
            var i: u32 = 0;
            while (i < self.backlinks_len) : (i += 1) {
                if (self.backlinks[i] == source_block_id) {
                    // Shift remaining backlinks left
                    var j: u32 = i;
                    while (j < self.backlinks_len - 1) : (j += 1) {
                        self.backlinks[j] = self.backlinks[j + 1];
                    }
                    self.backlinks_len -= 1;
                    return;
                }
            }
        }

        /// Update block content.
        pub fn update_content(self: *BlockData, new_content: []const u8)
!void {
            // Assert: Content must be bounded
            std.debug.assert(new_content.len <= MAX_BLOCK_CONTENT);

            // Free old content
            if (self.content_len > 0) {
                self.allocator.free(self.content);
            }

            // Allocate new content
            const content_copy = try self.allocator.dupe(u8,
new_content);
            self.content = content_copy;
            self.content_len = @as(u32, @intCast(content_copy.len));

            // Update timestamp
            const now = std.time.timestamp();
            self.updated_at = @as(u64, @intCast(now));
        }

        /// Update block title.
        pub fn update_title(self: *BlockData, new_title: []const u8)
!void {
            // Assert: Title must be bounded
            std.debug.assert(new_title.len <= MAX_BLOCK_TITLE);

            // Free old title
            if (self.title_len > 0) {
                self.allocator.free(self.title);
            }

            // Allocate new title
            const title_copy = try self.allocator.dupe(u8, new_title);
            self.title = title_copy;
            self.title_len = @as(u32, @intCast(title_copy.len));

            // Update timestamp
            const now = std.time.timestamp();
            self.updated_at = @as(u64, @intCast(now));
        }
    };

    /// Block storage manager.
    // 2025-11-23-114146-pst: Active struct
    pub const BlockStorage = struct {
        // Bounded: Max blocks (explicit limit)
        pub const MAX_BLOCKS: u32 = 100_000;

        blocks: []BlockData, // Blocks buffer (bounded)
        blocks_len: u32, // Number of blocks
        next_block_id: u32, // Next available block ID
        allocator: std.mem.Allocator,

        /// Initialize block storage.
        // 2025-11-23-114146-pst: Active function
        pub fn init(allocator: std.mem.Allocator) !BlockStorage {

            // Pre-allocate blocks buffer
            const blocks = try allocator.alloc(BlockData, MAX_BLOCKS);
            errdefer allocator.free(blocks);

            return BlockStorage{
                .blocks = blocks,
                .blocks_len = 0,
                .next_block_id = 1, // Start at 1
                .allocator = allocator,
            };
        }

        /// Deinitialize block storage and free memory.
        pub fn deinit(self: *BlockStorage) void {
            // Assert: Allocator must be valid (check by attempting
deallocation)
            _ = self.allocator;

            // Deinitialize all blocks
            var i: u32 = 0;
            while (i < self.blocks_len) : (i += 1) {
                self.blocks[i].deinit();
            }

            // Free blocks buffer
            self.allocator.free(self.blocks);

            self.* = undefined;
        }

        /// Create new block.
        // 2025-11-23-114146-pst: Active function
        pub fn create_block(self: *BlockStorage, title: []const u8,
content: []const u8) !u32 {
            // Check blocks limit
            if (self.blocks_len >= MAX_BLOCKS) {
                return error.TooManyBlocks;
            }

            // Create block
            const block_id = self.next_block_id;
            self.next_block_id += 1;

            var block_data = try BlockData.init(self.allocator,
block_id, title, content);
            errdefer block_data.deinit();

            // Store block
            self.blocks[self.blocks_len] = block_data;
            self.blocks_len += 1;

            return block_id;
        }

        /// Get block by ID.
        pub fn get_block(self: *BlockStorage, block_id: u32) ?*BlockData
{
            return self.find_block(block_id);
        }

        /// Link two blocks (bidirectional).
        // 2025-11-23-114146-pst: Active function
        pub fn link_blocks(self: *BlockStorage, source_id: u32,
target_id: u32) !void {
            if (self.find_block(source_id)) |source| {
                if (self.find_block(target_id)) |target| {
                    // Add link from source to target
                    try source.add_link(target_id);

                    // Add backlink from target to source
                    try target.add_backlink(source_id);
                } else {
                    return error.BlockNotFound;
                }
            } else {
                return error.BlockNotFound;
            }
        }

        /// Unlink two blocks (bidirectional).
        pub fn unlink_blocks(self: *BlockStorage, source_id: u32,
target_id: u32) void {
            if (self.find_block(source_id)) |source| {
                if (self.find_block(target_id)) |target| {
                    // Remove link from source to target
                    source.remove_link(target_id);

                    // Remove backlink from target to source
                    target.remove_backlink(source_id);
                }
            }
        }

        /// Find block by ID (internal helper).
        fn find_block(self: *BlockStorage, block_id: u32) ?*BlockData {
            var i: u32 = 0;
            while (i < self.blocks_len) : (i += 1) {
                if (self.blocks[i].id == block_id) {
                    return &self.blocks[i];
                }
            }
            return null;
        }
    };
};


// === grain_skate/bracket_matching.zig ===

//! Bracket Matching: Find and highlight matching
brackets/parentheses/braces.
//!
//! Why: Help users navigate nested code structures by highlighting
matching brackets.
//! Architecture: Iterative bracket matching using stack-based algorithm.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-03-162613-pst: Active implementation

const std = @import("std");
const Editor = @import("editor.zig").Editor;

// Bounded: Max bracket stack depth (explicit limit)
// 2025-12-03-162613-pst: Active constant
pub const MAX_BRACKET_STACK_DEPTH: u32 = 1024;

// Bracket type enumeration.
// 2025-12-03-162613-pst: Active enum
pub const BracketType = enum(u8) {
    none, // No bracket
    paren_open, // (
    paren_close, // )
    bracket_open, // [
    bracket_close, // ]
    brace_open, // {
    brace_close, // }
    angle_open, // <
    angle_close, // >
};

// Bracket match result.
// 2025-12-03-162613-pst: Active struct
pub const BracketMatch = struct {
    found: bool, // Whether a match was found
    line: u32, // Line index of matching bracket (0-indexed)
    column: u32, // Column index of matching bracket (0-indexed)
    
    /// Initialize empty bracket match (no match found).
    // 2025-12-03-162613-pst: Active function
    pub fn no_match() BracketMatch {
        return BracketMatch{
            .found = false,
            .line = 0,
            .column = 0,
        };
    }
    
    /// Initialize bracket match with position.
    // 2025-12-03-162613-pst: Active function
    pub fn init(line: u32, column: u32) BracketMatch {
        std.debug.assert(line < Editor.MAX_BUFFER_SIZE /
Editor.MAX_LINE_LEN); // Precondition
        std.debug.assert(column < Editor.MAX_LINE_LEN); // Precondition
        
        const match = BracketMatch{
            .found = true,
            .line = line,
            .column = column,
        };
        
        std.debug.assert(match.found == true); // Postcondition
        std.debug.assert(match.line < Editor.MAX_BUFFER_SIZE /
Editor.MAX_LINE_LEN); // Postcondition
        
        return match;
    }
};

// Bracket matching state.
// 2025-12-03-162613-pst: Active struct
pub const BracketMatcher = struct {
    /// Get bracket type from character.
    // 2025-12-03-162613-pst: Active function
    pub fn get_bracket_type(ch: u8) BracketType {
        return switch (ch) {
            '(' => .paren_open,
            ')' => .paren_close,
            '[' => .bracket_open,
            ']' => .bracket_close,
            '{' => .brace_open,
            '}' => .brace_close,
            '<' => .angle_open,
            '>' => .angle_close,
            else => .none,
        };
    }
    
    /// Check if bracket is opening bracket.
    // 2025-12-03-162613-pst: Active function
    pub fn is_open_bracket(bracket_type: BracketType) bool {
        return switch (bracket_type) {
            .paren_open, .bracket_open, .brace_open, .angle_open => true,
            else => false,
        };
    }
    
    /// Check if bracket is closing bracket.
    // 2025-12-03-162613-pst: Active function
    pub fn is_close_bracket(bracket_type: BracketType) bool {
        return switch (bracket_type) {
            .paren_close, .bracket_close, .brace_close, .angle_close =>
true,
            else => false,
        };
    }
    
    /// Get matching bracket type (open -> close, close -> open).
    // 2025-12-03-162613-pst: Active function
    pub fn get_matching_bracket(bracket_type: BracketType) BracketType {
        return switch (bracket_type) {
            .paren_open => .paren_close,
            .paren_close => .paren_open,
            .bracket_open => .bracket_close,
            .bracket_close => .bracket_open,
            .brace_open => .brace_close,
            .brace_close => .brace_open,
            .angle_open => .angle_close,
            .angle_close => .angle_open,
            else => .none,
        };
    }
    
    /// Find matching bracket at cursor position (iterative,
stack-based).
    // Returns matching bracket position or no match if not found.
    // 2025-12-03-162613-pst: Active function
    pub fn find_matching_bracket(
        editor: *const Editor.EditorState,
        cursor_line: u32,
        cursor_column: u32,
    ) BracketMatch {
        // Precondition: Cursor must be valid
        std.debug.assert(cursor_line < editor.buffer.lines_len);
        std.debug.assert(cursor_column <= Editor.MAX_LINE_LEN);
        
        // Get bracket at cursor position
        if (cursor_line >= editor.buffer.lines_len) {
            return BracketMatch.no_match();
        }
        const line_text = editor.buffer.lines[cursor_line];
        if (cursor_column >= line_text.len) {
            return BracketMatch.no_match();
        }
        const ch = line_text[cursor_column];
        const bracket_type = get_bracket_type(ch);
        
        if (bracket_type == .none) {
            return BracketMatch.no_match();
        }
        
        // Find matching bracket based on bracket type
        if (is_open_bracket(bracket_type)) {
            return find_matching_close_bracket(editor, cursor_line,
cursor_column, bracket_type);
        } else if (is_close_bracket(bracket_type)) {
            return find_matching_open_bracket(editor, cursor_line,
cursor_column, bracket_type);
        }
        
        return BracketMatch.no_match();
    }
    
    /// Find matching closing bracket for opening bracket (iterative,
forward search).
    // 2025-12-03-162613-pst: Active function
    fn find_matching_close_bracket(
        editor: *const Editor.EditorState,
        start_line: u32,
        start_column: u32,
        open_bracket: BracketType,
    ) BracketMatch {
        std.debug.assert(start_line < editor.buffer.lines_len); //
Precondition
        std.debug.assert(is_open_bracket(open_bracket)); // Precondition
        
        const close_bracket = get_matching_bracket(open_bracket);
        var depth: u32 = 1; // Track nesting depth (start at 1 for
initial bracket)
        
        // Search forward from cursor position
        var line: u32 = start_line;
        var column: u32 = start_column + 1;
        
        while (line < editor.buffer.lines_len) : (line += 1) {
            const line_text = editor.buffer.lines[line];
            const start_col = if (line == start_line) column else 0;
            
            var col: u32 = start_col;
            while (col < line_text.len) : (col += 1) {
                std.debug.assert(depth <= MAX_BRACKET_STACK_DEPTH); //
Invariant
                
                const ch = line_text[col];
                const bracket_type = get_bracket_type(ch);
                
                if (bracket_type == open_bracket) {
                    // Found another opening bracket of same type
(increase depth)
                    depth += 1;
                    if (depth > MAX_BRACKET_STACK_DEPTH) {
                        return BracketMatch.no_match(); // Stack overflow
                    }
                } else if (bracket_type == close_bracket) {
                    // Found closing bracket of same type (decrease
depth)
                    depth -= 1;
                    if (depth == 0) {
                        // Found matching closing bracket
                        std.debug.assert(line <
editor.buffer.lines_len); // Postcondition
                        std.debug.assert(col < Editor.MAX_LINE_LEN); //
Postcondition
                        return BracketMatch.init(line, col);
                    }
                }
            }
        }
        
        // No matching closing bracket found
        return BracketMatch.no_match();
    }
    
    /// Find matching opening bracket for closing bracket (iterative,
backward search).
    // 2025-12-03-162613-pst: Active function
    fn find_matching_open_bracket(
        editor: *const Editor.EditorState,
        start_line: u32,
        start_column: u32,
        close_bracket: BracketType,
    ) BracketMatch {
        std.debug.assert(start_line < editor.buffer.lines_len); //
Precondition
        std.debug.assert(is_close_bracket(close_bracket)); //
Precondition
        
        const open_bracket = get_matching_bracket(close_bracket);
        var depth: u32 = 1; // Track nesting depth (start at 1 for
initial bracket)
        
        // Search backward from cursor position
        var line: u32 = start_line;
        var col: u32 = if (start_column > 0) start_column - 1 else 0;
        
        while (true) {
            if (line >= editor.buffer.lines_len) {
                break;
            }
            const line_text = editor.buffer.lines[line];
            
            // Adjust column for current line (start at end of line if
not on start line)
            if (line < start_line) {
                col = if (line_text.len > 0) line_text.len - 1 else 0;
            }
            
            while (true) {
                std.debug.assert(depth <= MAX_BRACKET_STACK_DEPTH); //
Invariant
                
                if (col >= line_text.len) {
                    break;
                }
                const ch = line_text[col];
                const bracket_type = get_bracket_type(ch);
                
                if (bracket_type == close_bracket) {
                    // Found another closing bracket of same type
(increase depth)
                    depth += 1;
                    if (depth > MAX_BRACKET_STACK_DEPTH) {
                        return BracketMatch.no_match(); // Stack overflow
                    }
                } else if (bracket_type == open_bracket) {
                    // Found opening bracket of same type (decrease
depth)
                    depth -= 1;
                    if (depth == 0) {
                        // Found matching opening bracket
                        std.debug.assert(line <
editor.buffer.lines_len); // Postcondition
                        std.debug.assert(col < Editor.MAX_LINE_LEN); //
Postcondition
                        return BracketMatch.init(line, col);
                    }
                }
                
                if (col == 0) {
                    break;
                }
                col -= 1;
            }
            
            if (line == 0) {
                break;
            }
            line -= 1;
        }
        
        // No matching opening bracket found
        return BracketMatch.no_match();
    }
};


// === grain_skate/editor.zig ===

const std = @import("std");
const LineBufferAdapter =
@import("line_buffer_adapter.zig").LineBufferAdapter;
const EditorDagIntegration =
@import("editor_dag_integration.zig").EditorDagIntegration;

/// Grain Skate Editor: Text editor with Vim bindings for block editing.
/// ~<~ Glow Airbend: explicit editor state, bounded text buffer.
/// ~~~~ Glow Waterbend: deterministic editing operations, iterative
algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const Editor = struct {
    // Bounded: Max buffer size (explicit limit, in bytes)
    pub const MAX_BUFFER_SIZE: u32 = 10_485_760; // 10 MB

    // Bounded: Max undo history (explicit limit)
    pub const MAX_UNDO_HISTORY: u32 = 1_024;

    // Bounded: Max line length (explicit limit)
    pub const MAX_LINE_LEN: u32 = 65_536; // 64 KB

    // Bounded: Max yank buffer size (explicit limit, in bytes)
    pub const MAX_YANK_BUFFER: u32 = 1_048_576; // 1 MB

    // Bounded: Max search pattern size (explicit limit, in bytes)
    pub const MAX_SEARCH_PATTERN: u32 = 256;

    // Bounded: Max replace pattern size (explicit limit, in bytes)
    pub const MAX_REPLACE_PATTERN: u32 = 256;

    /// Editor mode enumeration.
    pub const EditorMode = enum(u8) {
        normal, // Normal mode (Vim)
        insert, // Insert mode (Vim)
        visual, // Visual mode (Vim)
        visual_line, // Visual line mode (Vim 'V')
        visual_block, // Visual block mode (Vim Ctrl+v)
        command, // Command mode (Vim)
        search, // Search mode (Vim '/')
    };

    /// Search direction enumeration.
    pub const SearchDirection = enum(u8) {
        forward, // Search forward (/)
        backward, // Search backward (?)
    };

    // TextBuffer removed: Now using LineBufferAdapter (wraps
GrainBuffer)
    // 2025-12-06-060914-pst: Migrated to LineBufferAdapter for Phase 2:
Text Buffer Unification

    /// Undo/redo operation structure.
    pub const UndoOperation = struct {
        operation_type: OperationType,
        line_num: u32,
        column: u32,
        text: []const u8, // Text inserted/deleted
        text_len: u32,
        allocator: std.mem.Allocator,

        /// Operation type enumeration.
        pub const OperationType = enum(u8) {
            insert, // Text inserted
            delete, // Text deleted
            replace, // Text replaced
        };

        /// Initialize undo operation.
        // 2025-11-23-114146-pst: Active function
        pub fn init(allocator: std.mem.Allocator, op_type:
OperationType, line_num: u32, column: u32, text: []const u8)
!UndoOperation {

            // Allocate text copy
            const text_copy = try allocator.dupe(u8, text);
            errdefer allocator.free(text_copy);

            return UndoOperation{
                .operation_type = op_type,
                .line_num = line_num,
                .column = column,
                .text = text_copy,
                .text_len = @as(u32, @intCast(text_copy.len)),
                .allocator = allocator,
            };
        }

        /// Deinitialize undo operation and free memory.
        pub fn deinit(self: *UndoOperation) void {
            // Assert: Allocator must be valid
            // Assert: Allocator must be valid (check by attempting
deallocation)
            _ = self.allocator;

            // Free text
            if (self.text_len > 0) {
                self.allocator.free(self.text);
            }

            self.* = undefined;
        }
    };

    /// Editor state structure.
    pub const EditorState = struct {
        buffer: LineBufferAdapter, // Text buffer (wraps GrainBuffer)
        mode: EditorMode, // Current mode
        cursor_line: u32, // Cursor line (0-indexed)
        cursor_column: u32, // Cursor column (0-indexed)
        undo_history: []UndoOperation, // Undo history (bounded)
        undo_history_len: u32,
        redo_history: []UndoOperation, // Redo history (bounded)
        redo_history_len: u32,
        yank_buffer: ?[]u8, // Yank (copy) buffer
        yank_buffer_len: u32,
        visual_anchor_line: u32, // Visual mode selection anchor line
        visual_anchor_column: u32, // Visual mode selection anchor column
        search_pattern: [MAX_SEARCH_PATTERN]u8, // Search pattern buffer
        search_pattern_len: u32, // Search pattern length
        search_direction: SearchDirection, // Search direction
(forward/backward)
        dag_integration: ?*EditorDagIntegration, // Optional DAG
integration (for event ordering)
        allocator: std.mem.Allocator,

        /// Initialize editor state.
        // 2025-11-23-122043-pst: Active function
        pub fn init(allocator: std.mem.Allocator, initial_content:
[]const u8) !EditorState {

            // Initialize text buffer (using LineBufferAdapter wrapping
GrainBuffer)
            var buffer = try LineBufferAdapter.init(allocator,
initial_content);
            errdefer buffer.deinit();

            // Pre-allocate undo history
            const undo_history = try allocator.alloc(UndoOperation,
MAX_UNDO_HISTORY);
            errdefer allocator.free(undo_history);

            // Pre-allocate redo history
            const redo_history = try allocator.alloc(UndoOperation,
MAX_UNDO_HISTORY);
            errdefer allocator.free(redo_history);

            return EditorState{
                .buffer = buffer,
                .mode = .normal,
                .cursor_line = 0,
                .cursor_column = 0,
                .undo_history = undo_history,
                .undo_history_len = 0,
                .redo_history = redo_history,
                .redo_history_len = 0,
                .yank_buffer = null,
                .yank_buffer_len = 0,
                .visual_anchor_line = 0,
                .visual_anchor_column = 0,
                .search_pattern = undefined,
                .search_pattern_len = 0,
                .search_direction = .forward,
                .dag_integration = null, // DAG integration optional
(can be enabled later)
                .allocator = allocator,
            };
        }
        
        /// Initialize editor state with DAG integration.
        pub fn init_with_dag(
            allocator: std.mem.Allocator,
            initial_content: []const u8,
            dag_integration: *EditorDagIntegration,
        ) !EditorState {
            // Initialize editor state
            var editor = try init(allocator, initial_content);
            errdefer editor.deinit();
            
            // Create buffer node in DAG
            _ = try dag_integration.create_buffer_node(initial_content);
            
            // Set DAG integration
            editor.dag_integration = dag_integration;
            
            return editor;
        }

        /// Deinitialize editor state and free memory.
        pub fn deinit(self: *EditorState) void {
            // Assert: Allocator must be valid
            // Assert: Allocator must be valid (check by attempting
deallocation)
            _ = self.allocator;

            // Deinitialize buffer
            self.buffer.deinit();

            // Deinitialize undo history
            var i: u32 = 0;
            while (i < self.undo_history_len) : (i += 1) {
                self.undo_history[i].deinit();
            }
            self.allocator.free(self.undo_history);

            // Deinitialize redo history
            i = 0;
            while (i < self.redo_history_len) : (i += 1) {
                self.redo_history[i].deinit();
            }
            self.allocator.free(self.redo_history);

            // Deinitialize yank buffer
            if (self.yank_buffer) |yank_buf| {
                self.allocator.free(yank_buf);
            }

            self.* = undefined;
        }

        /// Move cursor left (Vim 'h').
        pub fn move_left(self: *EditorState) void {
            if (self.cursor_column > 0) {
                self.cursor_column -= 1;
            } else if (self.cursor_line > 0) {
                self.cursor_line -= 1;
                self.cursor_column = @as(u32,
@intCast(self.buffer.lines[self.cursor_line].len));
            }
        }

        /// Move cursor right (Vim 'l').
        pub fn move_right(self: *EditorState) void {
            const current_line_len = if (self.cursor_line <
self.buffer.lines_len)
                @as(u32,
@intCast(self.buffer.lines[self.cursor_line].len))
            else
                0;

            if (self.cursor_column < current_line_len) {
                self.cursor_column += 1;
            } else if (self.cursor_line < self.buffer.lines_len - 1) {
                self.cursor_line += 1;
                self.cursor_column = 0;
            }
        }

        /// Move cursor up (Vim 'k').
        pub fn move_up(self: *EditorState) void {
            if (self.cursor_line > 0) {
                self.cursor_line -= 1;
                const line_len = @as(u32,
@intCast(self.buffer.lines[self.cursor_line].len));
                if (self.cursor_column > line_len) {
                    self.cursor_column = line_len;
                }
            }
        }

        /// Move cursor down (Vim 'j').
        pub fn move_down(self: *EditorState) void {
            if (self.cursor_line < self.buffer.lines_len - 1) {
                self.cursor_line += 1;
                const line_len = @as(u32,
@intCast(self.buffer.lines[self.cursor_line].len));
                if (self.cursor_column > line_len) {
                    self.cursor_column = line_len;
                }
            }
        }

        /// Check if character is word character (alphanumeric or
underscore).
        // 2025-12-02-133014-pst: Active function
        fn is_word_char(ch: u8) bool {
            return (ch >= 'a' and ch <= 'z') or
                (ch >= 'A' and ch <= 'Z') or
                (ch >= '0' and ch <= '9') or
                (ch == '_');
        }

        /// Move to start of next word (Vim 'w').
        // 2025-12-02-133014-pst: Active function
        pub fn move_word_forward(self: *EditorState) void {
            std.debug.assert(self.cursor_line < self.buffer.lines_len);
            const line = self.buffer.lines[self.cursor_line];
            const line_len = @as(u32, @intCast(line.len));
            // If at end of line, move to start of next line
            if (self.cursor_column >= line_len) {
                if (self.cursor_line < self.buffer.lines_len - 1) {
                    self.cursor_line += 1;
                    self.cursor_column = 0;
                }
                return;
            }
            // Skip current word if we're in the middle of one
            var pos = self.cursor_column;
            if (pos < line_len and is_word_char(line[pos])) {
                // Skip to end of current word
                while (pos < line_len and is_word_char(line[pos])) :
(pos += 1) {}
            }
            // Skip whitespace
            while (pos < line_len and !is_word_char(line[pos])) : (pos
+= 1) {}
            // If we found a word, move to its start
            if (pos < line_len) {
                self.cursor_column = pos;
            } else {
                // No word found on this line, move to start of next line
                if (self.cursor_line < self.buffer.lines_len - 1) {
                    self.cursor_line += 1;
                    self.cursor_column = 0;
                } else {
                    // Already at last line, move to end
                    self.cursor_column = line_len;
                }
            }
        }

        /// Move to start of previous word (Vim 'b').
        // 2025-12-02-133014-pst: Active function
        pub fn move_word_backward(self: *EditorState) void {
            std.debug.assert(self.cursor_line < self.buffer.lines_len);
            const line = self.buffer.lines[self.cursor_line];
            const line_len = @as(u32, @intCast(line.len));
            // If at start of line, move to end of previous line
            if (self.cursor_column == 0) {
                if (self.cursor_line > 0) {
                    self.cursor_line -= 1;
                    const prev_line =
self.buffer.lines[self.cursor_line];
                    self.cursor_column = @as(u32,
@intCast(prev_line.len));
                }
                return;
            }
            var pos = self.cursor_column;
            // If we're in the middle of a word, move to its start
            if (pos > 0 and pos <= line_len and is_word_char(line[pos -
1])) {
                // Move back to start of current word
                while (pos > 0 and is_word_char(line[pos - 1])) : (pos
-= 1) {}
                self.cursor_column = pos;
                return;
            }
            // Skip whitespace backward
            while (pos > 0 and !is_word_char(line[pos - 1])) : (pos -=
1) {}
            // If we found a word, move to its start
            if (pos > 0) {
                // Move back to start of word
                while (pos > 0 and is_word_char(line[pos - 1])) : (pos
-= 1) {}
                self.cursor_column = pos;
            } else {
                // No word found on this line, move to end of previous
line
                if (self.cursor_line > 0) {
                    self.cursor_line -= 1;
                    const prev_line =
self.buffer.lines[self.cursor_line];
                    self.cursor_column = @as(u32,
@intCast(prev_line.len));
                } else {
                    // Already at first line, move to start
                    self.cursor_column = 0;
                }
            }
        }

        /// Move to beginning of line (Vim '0').
        // 2025-12-02-141446-pst: Active function
        pub fn move_line_start(self: *EditorState) void {
            std.debug.assert(self.cursor_line < self.buffer.lines_len);
            self.cursor_column = 0;
        }

        /// Move to end of line (Vim '$').
        // 2025-12-02-141446-pst: Active function
        pub fn move_line_end(self: *EditorState) void {
            std.debug.assert(self.cursor_line < self.buffer.lines_len);
            const line = self.buffer.lines[self.cursor_line];
            self.cursor_column = @as(u32, @intCast(line.len));
        }

        /// Move to first non-whitespace character on line (Vim '^').
        // 2025-12-02-141446-pst: Active function
        pub fn move_line_start_nonblank(self: *EditorState) void {
            std.debug.assert(self.cursor_line < self.buffer.lines_len);
            const line = self.buffer.lines[self.cursor_line];
            const line_len = @as(u32, @intCast(line.len));
            var pos: u32 = 0;
            // Skip whitespace
            while (pos < line_len and (line[pos] == ' ' or line[pos] ==
'\t')) : (pos += 1) {}
            self.cursor_column = pos;
        }

        /// Move to beginning of file (Vim 'gg').
        // 2025-12-02-141446-pst: Active function
        pub fn move_file_start(self: *EditorState) void {
            self.cursor_line = 0;
            self.cursor_column = 0;
        }

        /// Move to end of file (Vim 'G').
        // 2025-12-02-141446-pst: Active function
        pub fn move_file_end(self: *EditorState) void {
            if (self.buffer.lines_len > 0) {
                self.cursor_line = self.buffer.lines_len - 1;
                const line = self.buffer.lines[self.cursor_line];
                self.cursor_column = @as(u32, @intCast(line.len));
            } else {
                self.cursor_line = 0;
                self.cursor_column = 0;
            }
        }

        /// Move to end of current/next word (Vim 'e').
        // 2025-12-02-133014-pst: Active function
        pub fn move_word_end(self: *EditorState) void {
            std.debug.assert(self.cursor_line < self.buffer.lines_len);
            const line = self.buffer.lines[self.cursor_line];
            const line_len = @as(u32, @intCast(line.len));
            // If at end of line, move to end of first word on next line
            if (self.cursor_column >= line_len) {
                if (self.cursor_line < self.buffer.lines_len - 1) {
                    self.cursor_line += 1;
                    const next_line =
self.buffer.lines[self.cursor_line];
                    const next_line_len = @as(u32,
@intCast(next_line.len));
                    var pos: u32 = 0;
                    // Find first word
                    while (pos < next_line_len and
!is_word_char(next_line[pos])) : (pos += 1) {}
                    // Move to end of word
                    while (pos < next_line_len and
is_word_char(next_line[pos])) : (pos += 1) {}
                    self.cursor_column = pos;
                }
                return;
            }
            var pos = self.cursor_column;
            // If we're in the middle of a word, move to its end
            if (pos < line_len and is_word_char(line[pos])) {
                // Move to end of current word
                while (pos < line_len and is_word_char(line[pos])) :
(pos += 1) {}
                self.cursor_column = pos;
                return;
            }
            // Skip whitespace forward
            while (pos < line_len and !is_word_char(line[pos])) : (pos
+= 1) {}
            // If we found a word, move to its end
            if (pos < line_len) {
                // Move to end of word
                while (pos < line_len and is_word_char(line[pos])) :
(pos += 1) {}
                self.cursor_column = pos;
            } else {
                // No word found on this line, move to end of first word
on next line
                if (self.cursor_line < self.buffer.lines_len - 1) {
                    self.cursor_line += 1;
                    const next_line =
self.buffer.lines[self.cursor_line];
                    const next_line_len = @as(u32,
@intCast(next_line.len));
                    var next_pos: u32 = 0;
                    // Find first word
                    while (next_pos < next_line_len and
!is_word_char(next_line[next_pos])) : (next_pos += 1) {}
                    // Move to end of word
                    while (next_pos < next_line_len and
is_word_char(next_line[next_pos])) : (next_pos += 1) {}
                    self.cursor_column = next_pos;
                } else {
                    // Already at last line, move to end
                    self.cursor_column = line_len;
                }
            }
        }

        /// Enter insert mode (Vim 'i').
        pub fn enter_insert_mode(self: *EditorState) void {
            self.mode = .insert;
        }

        /// Exit insert mode (Vim ESC).
        pub fn exit_insert_mode(self: *EditorState) void {
            self.mode = .normal;
        }

        /// Enter visual mode (Vim 'v').
        // 2025-12-02-121512-pst: Active function
        pub fn enter_visual_mode(self: *EditorState) void {
            self.mode = .visual;
            // Set selection anchor to current cursor position
            self.visual_anchor_line = self.cursor_line;
            self.visual_anchor_column = self.cursor_column;
        }

        /// Enter visual line mode (Vim 'V').
        // 2025-12-02-130235-pst: Active function
        pub fn enter_visual_line_mode(self: *EditorState) void {
            self.mode = .visual_line;
            // Set selection anchor to current line (full line selection)
            self.visual_anchor_line = self.cursor_line;
            self.visual_anchor_column = 0;
        }

        /// Enter visual block mode (Vim Ctrl+v).
        // 2025-12-02-135701-pst: Active function
        pub fn enter_visual_block_mode(self: *EditorState) void {
            self.mode = .visual_block;
            // Set selection anchor to current cursor position
            self.visual_anchor_line = self.cursor_line;
            self.visual_anchor_column = self.cursor_column;
        }

        /// Enter visual block mode (Vim Ctrl+v).
        // 2025-12-02-135701-pst: Active function
        pub fn enter_visual_block_mode(self: *EditorState) void {
            self.mode = .visual_block;
            // Set selection anchor to current cursor position
            self.visual_anchor_line = self.cursor_line;
            self.visual_anchor_column = self.cursor_column;
        }

        /// Exit visual mode (Vim ESC).
        // 2025-12-02-121512-pst: Active function
        pub fn exit_visual_mode(self: *EditorState) void {
            self.mode = .normal;
        }

        /// Switch editor mode.
        pub fn switch_mode(self: *EditorState, new_mode: EditorMode)
void {
            if (self.mode == .visual or self.mode == .visual_line or
self.mode == .visual_block) {
                self.exit_visual_mode();
            } else if (self.mode == .search) {
                self.exit_search_mode();
            }
            self.mode = new_mode;
            if (new_mode == .visual) {
                self.enter_visual_mode();
            } else if (new_mode == .visual_line) {
                self.enter_visual_line_mode();
            } else if (new_mode == .visual_block) {
                self.enter_visual_block_mode();
            } else if (new_mode == .search) {
                self.enter_search_mode();
            }
        }

        /// Enter search mode (Vim '/').
        // 2025-12-02-133808-pst: Active function
        pub fn enter_search_mode(self: *EditorState) void {
            self.mode = .search;
            self.search_pattern_len = 0;
            self.search_direction = .forward;
        }

        /// Enter search backward mode (Vim '?').
        // 2025-12-02-133808-pst: Active function
        pub fn enter_search_backward_mode(self: *EditorState) void {
            self.mode = .search;
            self.search_pattern_len = 0;
            self.search_direction = .backward;
        }

        /// Exit search mode (Vim ESC).
        // 2025-12-02-133808-pst: Active function
        pub fn exit_search_mode(self: *EditorState) void {
            self.mode = .normal;
        }

        /// Add character to search pattern.
        // 2025-12-02-133808-pst: Active function
        pub fn add_search_char(self: *EditorState, ch: u8) void {
            if (self.search_pattern_len < MAX_SEARCH_PATTERN - 1) {
                self.search_pattern[self.search_pattern_len] = ch;
                self.search_pattern_len += 1;
            }
        }

        /// Remove last character from search pattern (backspace).
        // 2025-12-02-133808-pst: Active function
        pub fn remove_search_char(self: *EditorState) void {
            if (self.search_pattern_len > 0) {
                self.search_pattern_len -= 1;
            }
        }

        /// Get current search pattern.
        // 2025-12-02-133808-pst: Active function
        pub fn get_search_pattern(self: *const EditorState) []const u8 {
            return self.search_pattern[0..self.search_pattern_len];
        }

        /// Find next occurrence of search pattern.
        // 2025-12-02-133808-pst: Active function
        pub fn find_next(self: *EditorState) bool {
            if (self.search_pattern_len == 0) {
                return false;
            }
            const pattern =
self.search_pattern[0..self.search_pattern_len];
            return self.find_pattern_forward(pattern);
        }

        /// Find previous occurrence of search pattern.
        // 2025-12-02-133808-pst: Active function
        pub fn find_previous(self: *EditorState) bool {
            if (self.search_pattern_len == 0) {
                return false;
            }
            const pattern =
self.search_pattern[0..self.search_pattern_len];
            return self.find_pattern_backward(pattern);
        }

        /// Find pattern forward from cursor (helper).
        // 2025-12-02-133808-pst: Active function
        fn find_pattern_forward(self: *EditorState, pattern: []const u8)
bool {
            var start_line = self.cursor_line;
            var start_col = self.cursor_column + 1;
            // Search from current position forward
            var line: u32 = start_line;
            while (line < self.buffer.lines_len) : (line += 1) {
                const line_text = self.buffer.lines[line];
                const line_len = @as(u32, @intCast(line_text.len));
                const search_start = if (line == start_line) start_col
else 0;
                var col: u32 = search_start;
                while (col <= line_len - pattern.len) : (col += 1) {
                    var match: bool = true;
                    var i: u32 = 0;
                    while (i < pattern.len) : (i += 1) {
                        if (col + i >= line_len or line_text[col + i] !=
pattern[i]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        self.cursor_line = line;
                        self.cursor_column = col;
                        return true;
                    }
                }
            }
            // Wrap to beginning
            line = 0;
            while (line <= start_line) : (line += 1) {
                const line_text = self.buffer.lines[line];
                const line_len = @as(u32, @intCast(line_text.len));
                const search_end = if (line == start_line) start_col
else line_len;
                var col: u32 = 0;
                while (col < search_end and col <= line_len -
pattern.len) : (col += 1) {
                    var match: bool = true;
                    var i: u32 = 0;
                    while (i < pattern.len) : (i += 1) {
                        if (col + i >= line_len or line_text[col + i] !=
pattern[i]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        self.cursor_line = line;
                        self.cursor_column = col;
                        return true;
                    }
                }
            }
            return false;
        }

        /// Find pattern backward from cursor (helper).
        // 2025-12-02-133808-pst: Active function
        fn find_pattern_backward(self: *EditorState, pattern: []const
u8) bool {
            var start_line = self.cursor_line;
            var start_col = if (self.cursor_column > 0)
self.cursor_column - 1 else 0;
            // Search backward from current position
            var line: u32 = start_line;
            while (true) : (line -= 1) {
                const line_text = self.buffer.lines[line];
                const line_len = @as(u32, @intCast(line_text.len));
                const search_end = if (line == start_line) start_col + 1
else line_len;
                var col: u32 = if (search_end >= pattern.len) search_end
- pattern.len else 0;
                while (true) : (col -= 1) {
                    if (col > line_len - pattern.len) {
                        break;
                    }
                    var match: bool = true;
                    var i: u32 = 0;
                    while (i < pattern.len) : (i += 1) {
                        if (col + i >= line_len or line_text[col + i] !=
pattern[i]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        self.cursor_line = line;
                        self.cursor_column = col;
                        return true;
                    }
                    if (col == 0) {
                        break;
                    }
                }
                if (line == 0) {
                    break;
                }
            }
            // Wrap to end
            var wrap_line: u32 = self.buffer.lines_len - 1;
            while (wrap_line > start_line) : (wrap_line -= 1) {
                const line_text = self.buffer.lines[wrap_line];
                const line_len = @as(u32, @intCast(line_text.len));
                var col: u32 = if (line_len >= pattern.len) line_len -
pattern.len else 0;
                while (true) : (col -= 1) {
                    if (col > line_len - pattern.len) {
                        break;
                    }
                    var match: bool = true;
                    var i: u32 = 0;
                    while (i < pattern.len) : (i += 1) {
                        if (col + i >= line_len or line_text[col + i] !=
pattern[i]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        self.cursor_line = wrap_line;
                        self.cursor_column = col;
                        return true;
                    }
                    if (col == 0) {
                        break;
                    }
                }
            }
            return false;
        }

        /// Replace first occurrence of pattern with replacement on
current line.
        // 2025-12-02-140535-pst: Active function
        pub fn replace_on_line(self: *EditorState, pattern: []const u8,
replacement: []const u8) !bool {
            if (self.cursor_line >= self.buffer.lines_len) {
                return false;
            }
            const line_text = self.buffer.lines[self.cursor_line];
            const line_len = @as(u32, @intCast(line_text.len));
            // Search for pattern in current line
            var col: u32 = 0;
            while (col <= line_len - pattern.len) : (col += 1) {
                var match: bool = true;
                var i: u32 = 0;
                while (i < pattern.len) : (i += 1) {
                    if (col + i >= line_len or line_text[col + i] !=
pattern[i]) {
                        match = false;
                        break;
                    }
                }
                if (match) {
                    // Replace pattern with replacement
                    const before_len = col;
                    const after_len = line_len - col - pattern.len;
                    const new_line_len = before_len + @as(u32,
@intCast(replacement.len)) + after_len;
                    if (new_line_len > MAX_LINE_LEN) {
                        return error.LineTooLong;
                    }
                    const new_line = try self.allocator.alloc(u8,
new_line_len);
                    errdefer self.allocator.free(new_line);
                    if (before_len > 0) {
                        @memcpy(new_line[0..before_len],
line_text[0..col]);
                    }
                    @memcpy(new_line[before_len..][0..replacement.len],
replacement);
                    if (after_len > 0) {
                        @memcpy(new_line[before_len +
replacement.len..], line_text[col + pattern.len..]);
                    }
                    // Save to undo history
                    const old_text = line_text[col..col + pattern.len];
                    if (self.undo_history_len < MAX_UNDO_HISTORY) {
                        const undo_op =
&self.undo_history[self.undo_history_len];
                        undo_op.* = .{
                            .operation = .replace,
                            .line_num = self.cursor_line,
                            .column = col,
                            .text = old_text.ptr,
                            .text_len = @as(u32, @intCast(old_text.len)),
                        };
                        self.undo_history_len += 1;
                    }
                    // Replace line
                    try self.buffer.replace_line(self.cursor_line,
new_line);
                    self.allocator.free(new_line);
                    // Update cursor position
                    self.cursor_column = col + @as(u32,
@intCast(replacement.len));
                    return true;
                }
            }
            return false;
        }

        /// Replace all occurrences of pattern with replacement on
current line.
        // 2025-12-02-140535-pst: Active function
        pub fn replace_all_on_line(self: *EditorState, pattern: []const
u8, replacement: []const u8) !u32 {
            if (self.cursor_line >= self.buffer.lines_len) {
                return 0;
            }
            var count: u32 = 0;
            var line_text = self.buffer.lines[self.cursor_line];
            var line_len = @as(u32, @intCast(line_text.len));
            // Build new line with replacements
            var new_line_buf: [MAX_LINE_LEN]u8 = undefined;
            var new_line_len: u32 = 0;
            var col: u32 = 0;
            while (col < line_len) {
                // Check if pattern matches at current position
                if (col <= line_len - pattern.len) {
                    var match: bool = true;
                    var i: u32 = 0;
                    while (i < pattern.len) : (i += 1) {
                        if (line_text[col + i] != pattern[i]) {
                            match = false;
                            break;
                        }
                    }
                    if (match) {
                        // Add replacement
                        if (new_line_len + replacement.len >
MAX_LINE_LEN) {
                            return error.LineTooLong;
                        }
                       
@memcpy(new_line_buf[new_line_len..][0..replacement.len], replacement);
                        new_line_len += @as(u32,
@intCast(replacement.len));
                        col += pattern.len;
                        count += 1;
                        continue;
                    }
                }
                // Add current character
                if (new_line_len >= MAX_LINE_LEN) {
                    return error.LineTooLong;
                }
                new_line_buf[new_line_len] = line_text[col];
                new_line_len += 1;
                col += 1;
            }
            if (count > 0) {
                // Create new line
                const new_line = try self.allocator.alloc(u8,
new_line_len);
                errdefer self.allocator.free(new_line);
                @memcpy(new_line, new_line_buf[0..new_line_len]);
                // Save to undo history
                if (self.undo_history_len < MAX_UNDO_HISTORY) {
                    const undo_op =
&self.undo_history[self.undo_history_len];
                    undo_op.* = .{
                        .operation = .replace,
                        .line_num = self.cursor_line,
                        .column = 0,
                        .text = line_text.ptr,
                        .text_len = line_len,
                    };
                    self.undo_history_len += 1;
                }
                // Replace line
                try self.buffer.replace_line(self.cursor_line, new_line);
                self.allocator.free(new_line);
            }
            return count;
        }

        /// Replace all occurrences of pattern with replacement in
entire buffer.
        // 2025-12-02-140535-pst: Active function
        pub fn replace_all_in_buffer(self: *EditorState, pattern:
[]const u8, replacement: []const u8) !u32 {
            var total_count: u32 = 0;
            var line: u32 = 0;
            while (line < self.buffer.lines_len) : (line += 1) {
                // Save current cursor line
                const saved_line = self.cursor_line;
                self.cursor_line = line;
                // Replace all on this line
                const count = try self.replace_all_on_line(pattern,
replacement);
                total_count += count;
                // Restore cursor line
                self.cursor_line = saved_line;
            }
            return total_count;
        }

        /// Get visual selection bounds (normalized: start <= end).
        // 2025-12-02-121512-pst: Active function
        pub fn get_visual_selection(self: *const EditorState) struct {
            start_line: u32,
            start_column: u32,
            end_line: u32,
            end_column: u32,
        } {
            std.debug.assert(self.mode == .visual or self.mode ==
.visual_line);
            const anchor_line = self.visual_anchor_line;
            const cursor_line = self.cursor_line;
            // Normalize selection (start <= end)
            const start_line = if (anchor_line <= cursor_line)
anchor_line else cursor_line;
            const end_line = if (anchor_line <= cursor_line) cursor_line
else anchor_line;
            if (self.mode == .visual_line) {
                // Visual line mode: always select entire lines
                std.debug.assert(start_line < self.buffer.lines_len);
                std.debug.assert(end_line < self.buffer.lines_len);
                const start_line_len = @as(u32,
@intCast(self.buffer.lines[start_line].len));
                const end_line_len = @as(u32,
@intCast(self.buffer.lines[end_line].len));
                return .{
                    .start_line = start_line,
                    .start_column = 0,
                    .end_line = end_line,
                    .end_column = end_line_len,
                };
            } else {
                // Visual mode: character-based selection
                const anchor_col = self.visual_anchor_column;
                const cursor_col = self.cursor_column;
                const anchor_before = (anchor_line < cursor_line) or
                    (anchor_line == cursor_line and anchor_col <=
cursor_col);
                if (anchor_before) {
                    return .{
                        .start_line = anchor_line,
                        .start_column = anchor_col,
                        .end_line = cursor_line,
                        .end_column = cursor_col,
                    };
                } else {
                    return .{
                        .start_line = cursor_line,
                        .start_column = cursor_col,
                        .end_line = anchor_line,
                        .end_column = anchor_col,
                    };
                }
            }
        }

        /// Yank selected text in visual mode.
        // 2025-12-02-121512-pst: Active function
        pub fn yank_selection(self: *EditorState) !void {
            std.debug.assert(self.mode == .visual or self.mode ==
.visual_line);
            const selection = self.get_visual_selection();
            // Calculate total size of selected text
            const total_size = try
self.calculate_selection_size(selection);
            if (total_size > MAX_YANK_BUFFER) {
                return error.YankBufferTooLarge;
            }
            // Free existing yank buffer
            if (self.yank_buffer) |yank_buf| {
                self.allocator.free(yank_buf);
                self.yank_buffer = null;
            }
            // Allocate yank buffer
            const yank_buf = try self.allocator.alloc(u8, total_size);
            errdefer self.allocator.free(yank_buf);
            // Copy selected text
            const actual_size = try
self.copy_selection_to_buffer(selection, yank_buf);
            self.yank_buffer = yank_buf;
            self.yank_buffer_len = actual_size;
        }

        /// Calculate size of visual selection (helper).
        // 2025-12-02-121512-pst: Active function
        fn calculate_selection_size(
            self: *const EditorState,
            selection: struct {
                start_line: u32,
                start_column: u32,
                end_line: u32,
                end_column: u32,
            },
        ) !u32 {
            var total_size: u32 = 0;
            var line: u32 = selection.start_line;
            while (line <= selection.end_line) : (line += 1) {
                std.debug.assert(line < self.buffer.lines_len);
                const line_text = self.buffer.lines[line];
                const line_len = @as(u32, @intCast(line_text.len));
                if (line == selection.start_line and line ==
selection.end_line) {
                    total_size += selection.end_column -
selection.start_column;
                } else if (line == selection.start_line) {
                    total_size += line_len - selection.start_column + 1;
                } else if (line == selection.end_line) {
                    total_size += selection.end_column;
                } else {
                    total_size += line_len + 1;
                }
            }
            return total_size;
        }

        /// Copy visual selection to buffer (helper).
        // 2025-12-02-121512-pst: Active function
        fn copy_selection_to_buffer(
            self: *const EditorState,
            selection: struct {
                start_line: u32,
                start_column: u32,
                end_line: u32,
                end_column: u32,
            },
            buffer: []u8,
        ) !u32 {
            var pos: u32 = 0;
            var line: u32 = selection.start_line;
            while (line <= selection.end_line) : (line += 1) {
                const line_text = self.buffer.lines[line];
                const line_len = @as(u32, @intCast(line_text.len));
                if (line == selection.start_line and line ==
selection.end_line) {
                    const copy_len = selection.end_column -
selection.start_column;
                    if (copy_len > 0) {
                        @memcpy(buffer[pos..][0..copy_len],
line_text[selection.start_column..selection.end_column]);
                        pos += copy_len;
                    }
                } else if (line == selection.start_line) {
                    const copy_len = line_len - selection.start_column;
                    if (copy_len > 0) {
                        @memcpy(buffer[pos..][0..copy_len],
line_text[selection.start_column..]);
                        pos += copy_len;
                    }
                    buffer[pos] = '\n';
                    pos += 1;
                } else if (line == selection.end_line) {
                    if (selection.end_column > 0) {
                        @memcpy(buffer[pos..][0..selection.end_column],
line_text[0..selection.end_column]);
                        pos += selection.end_column;
                    }
                } else {
                    if (line_len > 0) {
                        @memcpy(buffer[pos..][0..line_len], line_text);
                        pos += line_len;
                    }
                    buffer[pos] = '\n';
                    pos += 1;
                }
            }
            return pos;
        }

        /// Delete selected text in visual mode.
        // 2025-12-02-124119-pst: Active function
        pub fn delete_selection(self: *EditorState) !void {
            std.debug.assert(self.mode == .visual or self.mode ==
.visual_line);
            const selection = self.get_visual_selection();
            // Get selection text for undo before deleting
            const deleted_text = try
self.get_selection_text_for_undo(selection);
            defer self.allocator.free(deleted_text);
            // Yank selection (for redo and paste)
            try self.yank_selection();
            // Delete the selected text (undo operation will copy
deleted_text)
            if (selection.start_line == selection.end_line) {
                try self.delete_single_line_selection(selection,
deleted_text);
            } else {
                try self.delete_multi_line_selection(selection,
deleted_text);
            }
            // Move cursor to selection start
            self.cursor_line = selection.start_line;
            self.cursor_column = selection.start_column;
            // Exit visual mode
            self.exit_visual_mode();
        }

        /// Delete single line selection (helper).
        // 2025-12-02-124119-pst: Active function
        fn delete_single_line_selection(
            self: *EditorState,
            selection: struct {
                start_line: u32,
                start_column: u32,
                end_line: u32,
                end_column: u32,
            },
            deleted_text: []const u8,
        ) !void {
            std.debug.assert(selection.start_line == selection.end_line);
            const line_idx = selection.start_line;
            std.debug.assert(line_idx < self.buffer.lines_len);
            const line_text = self.buffer.lines[line_idx];
            const line_len = @as(u32, @intCast(line_text.len));
            const start_col = selection.start_column;
            const end_col = selection.end_column;
            // Create new line without selected portion
            const before_len = start_col;
            const after_len = line_len - end_col;
            const new_line_len = before_len + after_len;
            const new_line = if (new_line_len > 0) blk: {
                const new_line_buf = try self.allocator.alloc(u8,
new_line_len);
                errdefer self.allocator.free(new_line_buf);
                if (before_len > 0) {
                    @memcpy(new_line_buf[0..before_len],
line_text[0..start_col]);
                }
                if (after_len > 0) {
                    @memcpy(new_line_buf[before_len..],
line_text[end_col..]);
                }
                break :blk new_line_buf;
            } else "";
            // Save to undo history
            if (self.undo_history_len < MAX_UNDO_HISTORY) {
                const undo_op = try UndoOperation.init(
                    self.allocator,
                    .delete,
                    line_idx,
                    start_col,
                    deleted_text,
                );
                self.undo_history[self.undo_history_len] = undo_op;
                self.undo_history_len += 1;
                var i: u32 = 0;
                while (i < self.redo_history_len) : (i += 1) {
                    self.redo_history[i].deinit();
                }
                self.redo_history_len = 0;
            }
            // Record DAG event (if DAG integration enabled)
            if (self.dag_integration) |dag| {
                _ = dag.map_operation_to_event(
                    .delete,
                    line_idx,
                    start_col,
                    deleted_text,
                    "",
                ) catch |err| {
                    // DAG event recording failed, but continue with
operation
                    _ = err;
                };
            }
            // Replace line in buffer
            try self.buffer.replace_line(line_idx, new_line);
        }

        /// Delete multi-line selection (helper).
        // 2025-12-02-124119-pst: Active function
        fn delete_multi_line_selection(
            self: *EditorState,
            selection: struct {
                start_line: u32,
                start_column: u32,
                end_line: u32,
                end_column: u32,
            },
            deleted_text: []const u8,
        ) !void {
            std.debug.assert(selection.start_line < selection.end_line);
            const start_line = selection.start_line;
            const end_line = selection.end_line;
            std.debug.assert(start_line < self.buffer.lines_len);
            std.debug.assert(end_line < self.buffer.lines_len);
            // Get start and end line text
            const start_line_text = self.buffer.lines[start_line];
            const end_line_text = self.buffer.lines[end_line];
            const start_line_len = @as(u32,
@intCast(start_line_text.len));
            const end_line_len = @as(u32, @intCast(end_line_text.len));
            // Create merged line from start and end
            const start_prefix_len = selection.start_column;
            const end_suffix_len = end_line_len - selection.end_column;
            const merged_line_len = start_prefix_len + end_suffix_len;
            const merged_line = if (merged_line_len > 0) blk: {
                const merged_buf = try self.allocator.alloc(u8,
merged_line_len);
                errdefer self.allocator.free(merged_buf);
                if (start_prefix_len > 0) {
                    @memcpy(merged_buf[0..start_prefix_len],
start_line_text[0..selection.start_column]);
                }
                if (end_suffix_len > 0) {
                    @memcpy(merged_buf[start_prefix_len..],
end_line_text[selection.end_column..]);
                }
                break :blk merged_buf;
            } else "";
            // Calculate number of lines to remove
            const lines_to_remove = end_line - start_line;
            // Create new lines array
            const new_lines_len = self.buffer.lines_len -
lines_to_remove;
            const new_lines = try self.allocator.alloc([]const u8,
new_lines_len);
            errdefer self.allocator.free(new_lines);
            // Copy lines before selection
            var i: u32 = 0;
            while (i < start_line) : (i += 1) {
                new_lines[i] = self.buffer.lines[i];
            }
            // Add merged line
            new_lines[i] = merged_line;
            i += 1;
            // Copy lines after selection
            var j: u32 = end_line + 1;
            while (j < self.buffer.lines_len) : (j += 1) {
                new_lines[i] = self.buffer.lines[j];
                i += 1;
            }
            // Save to undo history
            if (self.undo_history_len < MAX_UNDO_HISTORY) {
                const undo_op = try UndoOperation.init(
                    self.allocator,
                    .delete,
                    start_line,
                    selection.start_column,
                    deleted_text,
                );
                self.undo_history[self.undo_history_len] = undo_op;
                self.undo_history_len += 1;
                var k: u32 = 0;
                while (k < self.redo_history_len) : (k += 1) {
                    self.redo_history[k].deinit();
                }
                self.redo_history_len = 0;
            }
            // Record DAG event (if DAG integration enabled)
            if (self.dag_integration) |dag| {
                _ = dag.map_operation_to_event(
                    .delete,
                    start_line,
                    selection.start_column,
                    deleted_text,
                    "",
                ) catch |err| {
                    // DAG event recording failed, but continue with
operation
                    _ = err;
                };
            }
            // Replace buffer lines
            self.allocator.free(self.buffer.lines);
            self.buffer.lines = new_lines;
            self.buffer.lines_len = new_lines_len;
        }

        /// Get selection text for undo history (helper).
        // 2025-12-02-124119-pst: Active function
        fn get_selection_text_for_undo(
            self: *const EditorState,
            selection: struct {
                start_line: u32,
                start_column: u32,
                end_line: u32,
                end_column: u32,
            },
        ) ![]const u8 {
            // Calculate size
            var total_size: u32 = 0;
            var line: u32 = selection.start_line;
            while (line <= selection.end_line) : (line += 1) {
                const line_text = self.buffer.lines[line];
                const line_len = @as(u32, @intCast(line_text.len));
                if (line == selection.start_line and line ==
selection.end_line) {
                    total_size += selection.end_column -
selection.start_column;
                } else if (line == selection.start_line) {
                    total_size += line_len - selection.start_column + 1;
                } else if (line == selection.end_line) {
                    total_size += selection.end_column;
                } else {
                    total_size += line_len + 1;
                }
            }
            // Allocate and copy
            const text = try self.allocator.alloc(u8, total_size);
            errdefer self.allocator.free(text);
            _ = try self.copy_selection_to_buffer(selection, text);
            return text;
        }

        /// Insert character at cursor (insert mode).
        // 2025-12-02-112844-pst: Active function
        pub fn insert_char(self: *EditorState, ch: u8) !void {
            // Assert: Must be in insert mode
            std.debug.assert(self.mode == .insert);
            std.debug.assert(self.cursor_line < self.buffer.lines_len);
            // Get current line
            const current_line = self.buffer.lines[self.cursor_line];
            const line_len = @as(u32, @intCast(current_line.len));
            std.debug.assert(self.cursor_column <= line_len);
            // Check line length limit
            if (line_len >= MAX_LINE_LEN) {
                return error.LineTooLong;
            }
            // Create new line with character inserted
            const new_line_len = line_len + 1;
            const new_line = try self.allocator.alloc(u8, new_line_len);
            errdefer self.allocator.free(new_line);
            // Copy before cursor
            if (self.cursor_column > 0) {
                @memcpy(new_line[0..self.cursor_column],
current_line[0..self.cursor_column]);
            }
            // Insert character
            new_line[self.cursor_column] = ch;
            // Copy after cursor
            if (self.cursor_column < line_len) {
                @memcpy(
                    new_line[self.cursor_column + 1..],
                    current_line[self.cursor_column..],
                );
            }
            // Save to undo history
            if (self.undo_history_len < MAX_UNDO_HISTORY) {
                const undo_op = try UndoOperation.init(
                    self.allocator,
                    .insert,
                    self.cursor_line,
                    self.cursor_column,
                    &[_]u8{ch},
                );
                self.undo_history[self.undo_history_len] = undo_op;
                self.undo_history_len += 1;
                // Clear redo history on new edit
                var i: u32 = 0;
                while (i < self.redo_history_len) : (i += 1) {
                    self.redo_history[i].deinit();
                }
                self.redo_history_len = 0;
            }
            // Record DAG event (if DAG integration enabled)
            if (self.dag_integration) |dag| {
                _ = dag.map_operation_to_event(
                    .insert,
                    self.cursor_line,
                    self.cursor_column,
                    "",
                    &[_]u8{ch},
                ) catch |err| {
                    // DAG event recording failed, but continue with
operation
                    _ = err;
                };
            }
            // Replace line in buffer
            try self.buffer.replace_line(self.cursor_line, new_line);
            // Move cursor right
            self.cursor_column += 1;
        }

        /// Delete character at cursor (Vim 'x').
        // 2025-12-02-112844-pst: Active function
        pub fn delete_char(self: *EditorState) !void {
            // Assert: Must be in normal mode
            std.debug.assert(self.mode == .normal);
            std.debug.assert(self.cursor_line < self.buffer.lines_len);
            // Get current line
            const current_line = self.buffer.lines[self.cursor_line];
            const line_len = @as(u32, @intCast(current_line.len));
            // Check if there's a character to delete
            if (self.cursor_column >= line_len) {
                return; // Nothing to delete
            }
            // Get character being deleted for undo
            const deleted_char = current_line[self.cursor_column];
            // Create new line without deleted character
            const new_line_len = if (line_len > 0) line_len - 1 else 0;
            const new_line = if (new_line_len > 0) blk: {
                const new_line_buf = try self.allocator.alloc(u8,
new_line_len);
                errdefer self.allocator.free(new_line_buf);
                // Copy before cursor
                if (self.cursor_column > 0) {
                    @memcpy(new_line_buf[0..self.cursor_column],
current_line[0..self.cursor_column]);
                }
                // Copy after cursor (skip deleted character)
                if (self.cursor_column + 1 < line_len) {
                    @memcpy(
                        new_line_buf[self.cursor_column..],
                        current_line[self.cursor_column + 1..],
                    );
                }
                break :blk new_line_buf;
            } else "";
            // Save to undo history
            if (self.undo_history_len < MAX_UNDO_HISTORY) {
                const undo_op = try UndoOperation.init(
                    self.allocator,
                    .delete,
                    self.cursor_line,
                    self.cursor_column,
                    &[_]u8{deleted_char},
                );
                self.undo_history[self.undo_history_len] = undo_op;
                self.undo_history_len += 1;
                // Clear redo history on new edit
                var i: u32 = 0;
                while (i < self.redo_history_len) : (i += 1) {
                    self.redo_history[i].deinit();
                }
                self.redo_history_len = 0;
            }
            // Record DAG event (if DAG integration enabled)
            if (self.dag_integration) |dag| {
                _ = dag.map_operation_to_event(
                    .delete,
                    self.cursor_line,
                    self.cursor_column,
                    &[_]u8{deleted_char},
                    "",
                ) catch |err| {
                    // DAG event recording failed, but continue with
operation
                    _ = err;
                };
            }
            // Replace line in buffer
            if (new_line_len > 0) {
                try self.buffer.replace_line(self.cursor_line, new_line);
            } else {
                try self.buffer.replace_line(self.cursor_line, "");
            }
            // Cursor stays at same position (character deleted)
        }

        /// Undo last operation.
        // 2025-12-02-114747-pst: Active function
        pub fn undo(self: *EditorState) !void {
            // Check if there's anything to undo
            if (self.undo_history_len == 0) {
                return; // Nothing to undo
            }
            // Get last undo operation
            const undo_op = &self.undo_history[self.undo_history_len -
1];
            std.debug.assert(undo_op.line_num < self.buffer.lines_len);
            // Restore based on operation type
            switch (undo_op.operation_type) {
                .insert => try self.undo_insert(undo_op),
                .delete => try self.undo_delete(undo_op),
                .replace => try self.undo_replace(undo_op),
            }
            // Remove from undo history
            undo_op.deinit();
            self.undo_history_len -= 1;
        }

        /// Undo insert operation (helper).
        // 2025-12-02-114747-pst: Active function
        fn undo_insert(self: *EditorState, undo_op: *UndoOperation)
!void {
            const current_line = self.buffer.lines[undo_op.line_num];
            const line_len = @as(u32, @intCast(current_line.len));
            const text_len = undo_op.text_len;
            std.debug.assert(undo_op.column + text_len <= line_len);
            // Create new line without inserted text
            const new_line_len = line_len - text_len;
            const new_line = if (new_line_len > 0) blk: {
                const new_line_buf = try self.allocator.alloc(u8,
new_line_len);
                errdefer self.allocator.free(new_line_buf);
                if (undo_op.column > 0) {
                    @memcpy(new_line_buf[0..undo_op.column],
current_line[0..undo_op.column]);
                }
                if (undo_op.column + text_len < line_len) {
                    @memcpy(
                        new_line_buf[undo_op.column..],
                        current_line[undo_op.column + text_len..],
                    );
                }
                break :blk new_line_buf;
            } else "";
            // Save to redo history
            if (self.redo_history_len < MAX_UNDO_HISTORY) {
                const redo_op = try UndoOperation.init(
                    self.allocator,
                    .insert,
                    undo_op.line_num,
                    undo_op.column,
                    undo_op.text,
                );
                self.redo_history[self.redo_history_len] = redo_op;
                self.redo_history_len += 1;
            }
            // Replace line and restore cursor
            if (new_line_len > 0) {
                try self.buffer.replace_line(undo_op.line_num, new_line);
            } else {
                try self.buffer.replace_line(undo_op.line_num, "");
            }
            self.cursor_line = undo_op.line_num;
            self.cursor_column = undo_op.column;
        }

        /// Undo delete operation (helper).
        // 2025-12-02-114747-pst: Active function
        fn undo_delete(self: *EditorState, undo_op: *UndoOperation)
!void {
            const current_line = self.buffer.lines[undo_op.line_num];
            const line_len = @as(u32, @intCast(current_line.len));
            const text_len = undo_op.text_len;
            const new_line_len = line_len + text_len;
            std.debug.assert(new_line_len <= MAX_LINE_LEN);
            // Create new line with deleted text reinserted
            const new_line = try self.allocator.alloc(u8, new_line_len);
            errdefer self.allocator.free(new_line);
            if (undo_op.column > 0) {
                @memcpy(new_line[0..undo_op.column],
current_line[0..undo_op.column]);
            }
            @memcpy(new_line[undo_op.column..][0..text_len],
undo_op.text);
            if (undo_op.column < line_len) {
                @memcpy(
                    new_line[undo_op.column + text_len..],
                    current_line[undo_op.column..],
                );
            }
            // Save to redo history
            if (self.redo_history_len < MAX_UNDO_HISTORY) {
                const redo_op = try UndoOperation.init(
                    self.allocator,
                    .delete,
                    undo_op.line_num,
                    undo_op.column,
                    undo_op.text,
                );
                self.redo_history[self.redo_history_len] = redo_op;
                self.redo_history_len += 1;
            }
            // Replace line and restore cursor
            try self.buffer.replace_line(undo_op.line_num, new_line);
            self.cursor_line = undo_op.line_num;
            self.cursor_column = undo_op.column + text_len;
        }

        /// Redo last undone operation.
        // 2025-12-02-114747-pst: Active function
        pub fn redo(self: *EditorState) !void {
            // Check if there's anything to redo
            if (self.redo_history_len == 0) {
                return; // Nothing to redo
            }
            // Get last redo operation
            const redo_op = &self.redo_history[self.redo_history_len -
1];
            std.debug.assert(redo_op.line_num < self.buffer.lines_len);
            // Reapply based on operation type
            switch (redo_op.operation_type) {
                .insert => try self.redo_insert(redo_op),
                .delete => try self.redo_delete(redo_op),
                .replace => try self.redo_replace(redo_op),
            }
            // Remove from redo history
            redo_op.deinit();
            self.redo_history_len -= 1;
        }

