        /// Undo replace operation (helper).
        // 2025-12-02-125904-pst: Active function
        fn undo_replace(self: *EditorState, undo_op: *UndoOperation)
!void {
            // For replace, undo_op.text contains the original text that
was replaced
            std.debug.assert(undo_op.line_num < self.buffer.lines_len);
            const current_line = self.buffer.lines[undo_op.line_num];
            const line_len = @as(u32, @intCast(current_line.len));
            // Get replacement text (current text from column to end)
            const replacement_text = if (undo_op.column < line_len)
                current_line[undo_op.column..]
            else
                "";
            const original_text = undo_op.text;
            const original_len = undo_op.text_len;
            // Create new line with original text restored
            const before_len = undo_op.column;
            const new_line_len = before_len + original_len;
            if (new_line_len > MAX_LINE_LEN) {
                return error.LineTooLong;
            }
            const new_line = try self.allocator.alloc(u8, new_line_len);
            errdefer self.allocator.free(new_line);
            if (before_len > 0) {
                @memcpy(new_line[0..before_len],
current_line[0..undo_op.column]);
            }
            @memcpy(new_line[before_len..][0..original_len],
original_text);
            // Save to redo history (save replacement text)
            if (self.redo_history_len < MAX_UNDO_HISTORY) {
                const redo_op = try UndoOperation.init(
                    self.allocator,
                    .replace,
                    undo_op.line_num,
                    undo_op.column,
                    replacement_text,
                );
                self.redo_history[self.redo_history_len] = redo_op;
                self.redo_history_len += 1;
            }
            // Replace line and restore cursor
            try self.buffer.replace_line(undo_op.line_num, new_line);
            self.cursor_line = undo_op.line_num;
            self.cursor_column = undo_op.column;
        }

        /// Redo replace operation (helper).
        // 2025-12-02-125904-pst: Active function
        fn redo_replace(self: *EditorState, redo_op: *UndoOperation)
!void {
            // For replace, redo_op.text contains the replacement text
            std.debug.assert(redo_op.line_num < self.buffer.lines_len);
            const current_line = self.buffer.lines[redo_op.line_num];
            const line_len = @as(u32, @intCast(current_line.len));
            // Get current text at position (original text)
            const original_text = if (redo_op.column < line_len)
                current_line[redo_op.column..]
            else
                "";
            const replacement_text = redo_op.text;
            const replacement_len = redo_op.text_len;
            // Create new line with replacement text
            const before_len = redo_op.column;
            const new_line_len = before_len + replacement_len;
            if (new_line_len > MAX_LINE_LEN) {
                return error.LineTooLong;
            }
            const new_line = try self.allocator.alloc(u8, new_line_len);
            errdefer self.allocator.free(new_line);
            if (before_len > 0) {
                @memcpy(new_line[0..before_len],
current_line[0..redo_op.column]);
            }
            @memcpy(new_line[before_len..][0..replacement_len],
replacement_text);
            // Save to undo history (save original text)
            if (self.undo_history_len < MAX_UNDO_HISTORY) {
                const undo_op = try UndoOperation.init(
                    self.allocator,
                    .replace,
                    redo_op.line_num,
                    redo_op.column,
                    original_text,
                );
                self.undo_history[self.undo_history_len] = undo_op;
                self.undo_history_len += 1;
            }
            // Replace line and update cursor
            try self.buffer.replace_line(redo_op.line_num, new_line);
            self.cursor_line = redo_op.line_num;
            self.cursor_column = redo_op.column;
        }

        /// Yank (copy) current line to yank buffer.
        // 2025-12-02-115753-pst: Active function
        pub fn yank_line(self: *EditorState) !void {
            std.debug.assert(self.cursor_line < self.buffer.lines_len);
            const line = self.buffer.lines[self.cursor_line];
            const line_len = @as(u32, @intCast(line.len));
            if (line_len > MAX_YANK_BUFFER) {
                return error.YankBufferTooLarge;
            }
            if (self.yank_buffer) |yank_buf| {
                self.allocator.free(yank_buf);
                self.yank_buffer = null;
            }
            const yank_buf = try self.allocator.alloc(u8, line_len);
            errdefer self.allocator.free(yank_buf);
            @memcpy(yank_buf, line);
            self.yank_buffer = yank_buf;
            self.yank_buffer_len = line_len;
        }

        /// Paste yank buffer at cursor (normal mode).
        // 2025-12-02-115753-pst: Active function
        pub fn paste(self: *EditorState) !void {
            std.debug.assert(self.mode == .normal);
            if (self.yank_buffer == null or self.yank_buffer_len == 0) {
                return;
            }
            const yank_buf = self.yank_buffer.?;
            std.debug.assert(self.cursor_line < self.buffer.lines_len);
            const current_line = self.buffer.lines[self.cursor_line];
            const line_len = @as(u32, @intCast(current_line.len));
            const new_line_len = line_len + self.yank_buffer_len;
            if (new_line_len > MAX_LINE_LEN) {
                return error.LineTooLong;
            }
            const paste_pos = self.cursor_column;
            const new_line = try self.allocator.alloc(u8, new_line_len);
            errdefer self.allocator.free(new_line);
            if (paste_pos > 0) {
                @memcpy(new_line[0..paste_pos],
current_line[0..paste_pos]);
            }
            @memcpy(new_line[paste_pos..][0..self.yank_buffer_len],
yank_buf);
            if (paste_pos < line_len) {
                @memcpy(
                    new_line[paste_pos + self.yank_buffer_len..],
                    current_line[paste_pos..],
                );
            }
            if (self.undo_history_len < MAX_UNDO_HISTORY) {
                const undo_op = try UndoOperation.init(
                    self.allocator,
                    .insert,
                    self.cursor_line,
                    paste_pos,
                    yank_buf,
                );
                self.undo_history[self.undo_history_len] = undo_op;
                self.undo_history_len += 1;
                var i: u32 = 0;
                while (i < self.redo_history_len) : (i += 1) {
                    self.redo_history[i].deinit();
                }
                self.redo_history_len = 0;
            }
            try self.buffer.replace_line(self.cursor_line, new_line);
            self.cursor_column = paste_pos + self.yank_buffer_len;
        }

        /// Paste yank buffer replacing selection (visual mode).
        // 2025-12-02-124933-pst: Active function
        pub fn paste_selection(self: *EditorState) !void {
            std.debug.assert(self.mode == .visual or self.mode ==
.visual_line);
            if (self.yank_buffer == null or self.yank_buffer_len == 0) {
                // Nothing to paste, just exit visual mode
                self.exit_visual_mode();
                return;
            }
            const selection = self.get_visual_selection();
            // Get selection text for undo before replacing
            const deleted_text = try
self.get_selection_text_for_undo(selection);
            defer self.allocator.free(deleted_text);
            const yank_buf = self.yank_buffer.?;
            // Replace selection with yank buffer
            if (selection.start_line == selection.end_line) {
                try self.replace_single_line_selection(selection,
yank_buf, deleted_text);
            } else {
                try self.replace_multi_line_selection(selection,
yank_buf, deleted_text);
            }
            // Move cursor to selection start
            self.cursor_line = selection.start_line;
            self.cursor_column = selection.start_column;
            // Exit visual mode
            self.exit_visual_mode();
        }

        /// Replace single line selection with text (helper).
        // 2025-12-02-124933-pst: Active function
        fn replace_single_line_selection(
            self: *EditorState,
            selection: struct {
                start_line: u32,
                start_column: u32,
                end_line: u32,
                end_column: u32,
            },
            replacement: []const u8,
            deleted_text: []const u8,
        ) !void {
            std.debug.assert(selection.start_line == selection.end_line);
            const line_idx = selection.start_line;
            std.debug.assert(line_idx < self.buffer.lines_len);
            const line_text = self.buffer.lines[line_idx];
            const line_len = @as(u32, @intCast(line_text.len));
            const start_col = selection.start_column;
            const end_col = selection.end_column;
            const before_len = start_col;
            const after_len = line_len - end_col;
            const new_line_len = before_len + @as(u32,
@intCast(replacement.len)) + after_len;
            if (new_line_len > MAX_LINE_LEN) {
                return error.LineTooLong;
            }
            const new_line = try self.allocator.alloc(u8, new_line_len);
            errdefer self.allocator.free(new_line);
            if (before_len > 0) {
                @memcpy(new_line[0..before_len],
line_text[0..start_col]);
            }
            @memcpy(new_line[before_len..][0..replacement.len],
replacement);
            if (after_len > 0) {
                @memcpy(new_line[before_len + replacement.len..],
line_text[end_col..]);
            }
            // Save to undo history
            if (self.undo_history_len < MAX_UNDO_HISTORY) {
                const undo_op = try UndoOperation.init(
                    self.allocator,
                    .replace,
                    line_idx,
                    start_col,
                    deleted_text,
                );
                self.undo_history[self.undo_history_len] = undo_op;
                self.undo_history_len += 1;
                var i: u32 = 0;
                while (i < self.redo_history_len) : (i += 1) {
                    self.redo_history[i].deinit();
                }
                self.redo_history_len = 0;
            }
            // Replace line in buffer
            try self.buffer.replace_line(line_idx, new_line);
        }

        /// Replace multi-line selection with text (helper).
        // 2025-12-02-124933-pst: Active function
        fn replace_multi_line_selection(
            self: *EditorState,
            selection: struct {
                start_line: u32,
                start_column: u32,
                end_line: u32,
                end_column: u32,
            },
            replacement: []const u8,
            deleted_text: []const u8,
        ) !void {
            std.debug.assert(selection.start_line < selection.end_line);
            const replacement_lines = try
self.parse_text_to_lines(replacement);
            defer self.allocator.free(replacement_lines.lines);
            const lines_to_remove = selection.end_line -
selection.start_line;
            const new_lines_len = self.buffer.lines_len -
lines_to_remove + replacement_lines.lines_len;
            const new_lines = try self.allocator.alloc([]const u8,
new_lines_len);
            errdefer self.allocator.free(new_lines);
            var i = try self.copy_lines_before_selection(new_lines,
selection.start_line);
            i = try self.merge_replacement_lines(new_lines, i,
selection, replacement_lines);
            i = try self.merge_end_suffix(new_lines, i, selection);
            i = try self.copy_lines_after_selection(new_lines, i,
selection.end_line);
            try self.save_replace_to_undo(selection, deleted_text);
            self.allocator.free(self.buffer.lines);
            self.buffer.lines = new_lines;
            self.buffer.lines_len = new_lines_len;
        }

        /// Copy lines before selection (helper).
        // 2025-12-02-124933-pst: Active function
        fn copy_lines_before_selection(
            self: *const EditorState,
            new_lines: []const []const u8,
            start_line: u32,
        ) !u32 {
            var i: u32 = 0;
            while (i < start_line) : (i += 1) {
                new_lines[i] = self.buffer.lines[i];
            }
            return i;
        }

        /// Merge replacement lines into new lines array (helper).
        // 2025-12-02-124933-pst: Active function
        fn merge_replacement_lines(
            self: *EditorState,
            new_lines: []const []const u8,
            start_idx: u32,
            selection: struct {
                start_line: u32,
                start_column: u32,
                end_line: u32,
                end_column: u32,
            },
            replacement_lines: struct {
                lines: []const []const u8,
                lines_len: u32,
            },
        ) !u32 {
            var i = start_idx;
            const start_line_text =
self.buffer.lines[selection.start_line];
            const start_prefix =
start_line_text[0..selection.start_column];
            if (replacement_lines.lines_len > 0) {
                const first_repl = replacement_lines.lines[0];
                const merged_first_len = start_prefix.len +
first_repl.len;
                if (merged_first_len > MAX_LINE_LEN) {
                    return error.LineTooLong;
                }
                const merged_first = try self.allocator.alloc(u8,
merged_first_len);
                errdefer self.allocator.free(merged_first);
                @memcpy(merged_first[0..start_prefix.len], start_prefix);
                @memcpy(merged_first[start_prefix.len..], first_repl);
                new_lines[i] = merged_first;
                i += 1;
                var j: u32 = 1;
                while (j < replacement_lines.lines_len) : (j += 1) {
                    new_lines[i] = replacement_lines.lines[j];
                    i += 1;
                }
            } else {
                const prefix_copy = try self.allocator.dupe(u8,
start_prefix);
                new_lines[i] = prefix_copy;
                i += 1;
            }
            return i;
        }

        /// Merge end line suffix with last replacement line (helper).
        // 2025-12-02-124933-pst: Active function
        fn merge_end_suffix(
            self: *EditorState,
            new_lines: []const []const u8,
            last_idx: u32,
            selection: struct {
                start_line: u32,
                start_column: u32,
                end_line: u32,
                end_column: u32,
            },
        ) !u32 {
            const end_line_text = self.buffer.lines[selection.end_line];
            const end_suffix = end_line_text[selection.end_column..];
            if (end_suffix.len > 0 and last_idx > 0) {
                const idx = last_idx - 1;
                const last_line = new_lines[idx];
                const merged_last_len = last_line.len + end_suffix.len;
                if (merged_last_len > MAX_LINE_LEN) {
                    return error.LineTooLong;
                }
                const merged_last = try self.allocator.alloc(u8,
merged_last_len);
                errdefer self.allocator.free(merged_last);
                @memcpy(merged_last[0..last_line.len], last_line);
                @memcpy(merged_last[last_line.len..], end_suffix);
                new_lines[idx] = merged_last;
            }
            return last_idx;
        }

        /// Copy lines after selection (helper).
        // 2025-12-02-124933-pst: Active function
        fn copy_lines_after_selection(
            self: *const EditorState,
            new_lines: []const []const u8,
            start_idx: u32,
            end_line: u32,
        ) !u32 {
            var i = start_idx;
            var k: u32 = end_line + 1;
            while (k < self.buffer.lines_len) : (k += 1) {
                new_lines[i] = self.buffer.lines[k];
                i += 1;
            }
            return i;
        }

        /// Save replace operation to undo history (helper).
        // 2025-12-02-124933-pst: Active function
        fn save_replace_to_undo(
            self: *EditorState,
            selection: struct {
                start_line: u32,
                start_column: u32,
                end_line: u32,
                end_column: u32,
            },
            deleted_text: []const u8,
        ) !void {
            if (self.undo_history_len < MAX_UNDO_HISTORY) {
                const undo_op = try UndoOperation.init(
                    self.allocator,
                    .replace,
                    selection.start_line,
                    selection.start_column,
                    deleted_text,
                );
                self.undo_history[self.undo_history_len] = undo_op;
                self.undo_history_len += 1;
                var i: u32 = 0;
                while (i < self.redo_history_len) : (i += 1) {
                    self.redo_history[i].deinit();
                }
                self.redo_history_len = 0;
            }
        }

        /// Parse text into lines (helper).
        // 2025-12-02-124933-pst: Active function
        fn parse_text_to_lines(self: *EditorState, text: []const u8)
!struct {
            lines: []const []const u8,
            lines_len: u32,
        } {
            // Count lines
            var line_count: u32 = 0;
            var i: u32 = 0;
            while (i < text.len) : (i += 1) {
                if (text[i] == '\n') {
                    line_count += 1;
                }
            }
            if (text.len > 0 and text[text.len - 1] != '\n') {
                line_count += 1;
            }
            if (line_count == 0) {
                line_count = 1; // At least one line
            }
            // Allocate lines array
            const lines = try self.allocator.alloc([]const u8,
line_count);
            errdefer self.allocator.free(lines);
            // Split text into lines
            var start: u32 = 0;
            var line_idx: u32 = 0;
            i = 0;
            while (i < text.len) : (i += 1) {
                if (text[i] == '\n') {
                    const line = text[start..i];
                    lines[line_idx] = line;
                    line_idx += 1;
                    start = i + 1;
                }
            }
            if (start < text.len) {
                const line = text[start..];
                lines[line_idx] = line;
                line_idx += 1;
            } else if (text.len > 0 and text[text.len - 1] == '\n') {
                lines[line_idx] = "";
                line_idx += 1;
            }
            return .{
                .lines = lines,
                .lines_len = line_idx,
            };
        }

        /// Delete current line (Vim 'dd').
        // 2025-12-02-115753-pst: Active function
        pub fn delete_line(self: *EditorState) !void {
            std.debug.assert(self.mode == .normal);
            std.debug.assert(self.cursor_line < self.buffer.lines_len);
            const line_to_delete = self.buffer.lines[self.cursor_line];
            const line_len = @as(u32, @intCast(line_to_delete.len));
            if (line_len > 0 and line_len <= MAX_YANK_BUFFER) {
                if (self.yank_buffer) |yank_buf| {
                    self.allocator.free(yank_buf);
                }
                const yank_buf = try self.allocator.alloc(u8, line_len);
                errdefer self.allocator.free(yank_buf);
                @memcpy(yank_buf, line_to_delete);
                self.yank_buffer = yank_buf;
                self.yank_buffer_len = line_len;
            }
            if (self.undo_history_len < MAX_UNDO_HISTORY) {
                const undo_op = try UndoOperation.init(
                    self.allocator,
                    .delete,
                    self.cursor_line,
                    0,
                    line_to_delete,
                );
                self.undo_history[self.undo_history_len] = undo_op;
                self.undo_history_len += 1;
                var i: u32 = 0;
                while (i < self.redo_history_len) : (i += 1) {
                    self.redo_history[i].deinit();
                }
                self.redo_history_len = 0;
            }
            // Remove line from buffer
            try self.buffer.remove_line(self.cursor_line);
            if (self.cursor_line >= self.buffer.lines_len and
self.buffer.lines_len > 0) {
                self.cursor_line = self.buffer.lines_len - 1;
            } else if (self.buffer.lines_len == 0) {
                const empty_lines = try self.allocator.alloc([]const u8,
1);
                empty_lines[0] = "";
                self.buffer.lines = empty_lines;
                self.buffer.lines_len = 1;
                self.cursor_line = 0;
                self.cursor_column = 0;
            }
            if (self.cursor_line < self.buffer.lines_len) {
                const new_line_len = @as(u32,
@intCast(self.buffer.lines[self.cursor_line].len));
                if (self.cursor_column > new_line_len) {
                    self.cursor_column = new_line_len;
                }
            }
        }
    };
};


// === grain_skate/editor_dag_integration.zig ===

const std = @import("std");
const DagCore = @import("../dag_core.zig").DagCore;

/// Editor-DAG Integration: Maps Grain Skate editor operations to DAG
events.
/// ~<~ Glow Airbend: explicit editor-to-DAG mapping, bounded
conversions.
/// ~~~~ Glow Waterbend: editor operations stream through DAG
deterministically.
///
/// This implements HashDAG-style event ordering for deterministic
undo/redo:
/// - Editor buffer becomes DAG node
/// - Editor operations (insert, delete, replace) become DAG events
/// - Parent event IDs maintain ordering (HashDAG-style)
/// - Foundation for collaborative editing
pub const EditorDagIntegration = struct {
    allocator: std.mem.Allocator,
    dag: DagCore,
    buffer_node_id: ?u32, // DAG node ID for editor buffer
    last_event_id: u64, // Last event ID (for parent references)
    processed_events: []ProcessedEvent, // History of processed events
(for temporal queries)
    processed_events_len: u32, // Number of processed events
    
    // Bounded: Max 1,000 events per editor session
    pub const MAX_EVENTS_PER_SESSION: u32 = 1_000;
    
    // Bounded: Max 100 operations per second
    pub const MAX_OPERATIONS_PER_SECOND: u32 = 100;
    
    // Bounded: Max 10,000 processed events in history
    pub const MAX_PROCESSED_EVENTS: u32 = 10_000;
    
    /// Processed event (for temporal queries).
    pub const ProcessedEvent = struct {
        event_id: u64,
        timestamp: u64, // Unix timestamp
        operation_type: OperationType,
        line_num: u32,
        column: u32,
    };
    
    /// Initialize editor-DAG integration.
    pub fn init(allocator: std.mem.Allocator) !EditorDagIntegration {
        // Assert: Allocator must be valid
        std.debug.assert(allocator.ptr != null);
        
        const dag = try DagCore.init(allocator);
        errdefer dag.deinit();
        
        // Pre-allocate processed events history
        const processed_events = try allocator.alloc(ProcessedEvent,
MAX_PROCESSED_EVENTS);
        errdefer allocator.free(processed_events);
        
        return EditorDagIntegration{
            .allocator = allocator,
            .dag = dag,
            .buffer_node_id = null,
            .last_event_id = 0,
            .processed_events = processed_events,
            .processed_events_len = 0,
        };
    }
    
    /// Deinitialize editor-DAG integration.
    pub fn deinit(self: *EditorDagIntegration) void {
        self.dag.deinit();
        self.allocator.free(self.processed_events);
    }
    
    /// Create DAG node for editor buffer.
    /// Returns node ID for the buffer.
    pub fn create_buffer_node(
        self: *EditorDagIntegration,
        initial_content: []const u8,
    ) !u32 {
        // Assert: Buffer node not already created
        std.debug.assert(self.buffer_node_id == null);
        
        // Create node data (buffer content)
        const node_data = try self.allocator.dupe(u8, initial_content);
        errdefer self.allocator.free(node_data);
        
        // Create DAG node (ui_component type for editor buffer)
        const node_id = try self.dag.addNode(
            .ui_component,
            node_data,
            .{
                .is_readonly = false,
                .readonly_start = 0,
                .readonly_end = @as(u32, @intCast(initial_content.len)),
                .metadata = "",
                .metadata_len = 0,
            },
        );
        
        self.buffer_node_id = node_id;
        
        // Assert: Node was created
        std.debug.assert(self.buffer_node_id.? == node_id);
        
        return node_id;
    }
    
    /// Map editor operation to DAG event (HashDAG-style).
    /// Returns event ID for the operation.
    pub fn map_operation_to_event(
        self: *EditorDagIntegration,
        op_type: OperationType,
        line_num: u32,
        column: u32,
        old_text: []const u8,
        new_text: []const u8,
    ) !u64 {
        // Assert: Buffer node must be created
        std.debug.assert(self.buffer_node_id != null);
        
        // Assert: Event count must be within bounds
        std.debug.assert(self.dag.pending_events_len <
MAX_EVENTS_PER_SESSION);
        
        // Create event data (operation type + line/column + old/new
text)
        var event_data = std.ArrayList(u8).init(self.allocator);
        defer event_data.deinit();
        
        const writer = event_data.writer();
        try writer.print("{s}:", .{@tagName(op_type)});
        try writer.print("line:{d}:", .{line_num});
        try writer.print("col:{d}:", .{column});
        try writer.print("old:{d}:", .{old_text.len});
        try writer.print("new:{d}:", .{new_text.len});
        try writer.writeAll(old_text);
        try writer.writeAll(new_text);
        
        // Create parent event IDs (HashDAG-style: reference last event)
        var parent_events: []const u64 = &.{};
        if (self.last_event_id > 0) {
            parent_events = &.{self.last_event_id};
        }
        
        // Add event to DAG (code_edit type)
        const event_id = try self.dag.addEvent(
            .code_edit,
            self.buffer_node_id.?,
            try event_data.toOwnedSlice(),
            parent_events,
        );
        
        // Update last event ID
        self.last_event_id = event_id;
        
        // Assert: Event was added
        std.debug.assert(event_id > 0);
        
        return event_id;
    }
    
    /// Type of editor operation.
    pub const OperationType = enum(u8) {
        insert, // Insert text
        delete, // Delete text
        replace, // Replace text
    };
    
    /// Process pending events (deterministic ordering).
    pub fn process_events(self: *EditorDagIntegration) !void {
        // Assert: Processed events count must be within bounds
        std.debug.assert(self.processed_events_len <
MAX_PROCESSED_EVENTS);
        
        // Store pending events in history before processing
        const pending_count = self.dag.pending_events_len;
        var i: u32 = 0;
        while (i < pending_count) : (i += 1) {
            const event = &self.dag.pending_events[i];
            
            // Parse operation type from event data
            const op_type = if (std.mem.indexOf(u8, event.data,
"insert") != null) {
                OperationType.insert
            } else if (std.mem.indexOf(u8, event.data, "delete") !=
null) {
                OperationType.delete
            } else {
                OperationType.replace
            };
            
            // Parse line and column from event data (format:
"op_type:line:X:col:Y:...")
            var line_num: u32 = 0;
            var column: u32 = 0;
            if (std.mem.indexOf(u8, event.data, "line:") != null) {
                // Simple parsing (can be improved)
                const line_start = std.mem.indexOf(u8, event.data,
"line:") orelse 0;
                const line_end = std.mem.indexOf(u8,
event.data[line_start + 5..], ":") orelse 0;
                if (line_end > 0) {
                    const line_str = event.data[line_start +
5..line_start + 5 + line_end];
                    line_num = std.fmt.parseInt(u32, line_str, 10) catch
0;
                }
            }
            if (std.mem.indexOf(u8, event.data, "col:") != null) {
                const col_start = std.mem.indexOf(u8, event.data,
"col:") orelse 0;
                const col_end = std.mem.indexOf(u8, event.data[col_start
+ 4..], ":") orelse 0;
                if (col_end > 0) {
                    const col_str = event.data[col_start + 4..col_start
+ 4 + col_end];
                    column = std.fmt.parseInt(u32, col_str, 10) catch 0;
                }
            }
            
            // Store in processed events history
            if (self.processed_events_len < MAX_PROCESSED_EVENTS) {
                self.processed_events[self.processed_events_len] =
ProcessedEvent{
                    .event_id = event.id,
                    .timestamp = event.timestamp,
                    .operation_type = op_type,
                    .line_num = line_num,
                    .column = column,
                };
                self.processed_events_len += 1;
            }
        }
        
        // Process events in DAG (TigerBeetle-style state machine)
        try self.dag.processEvents();
        
        // Assert: Events were processed
        std.debug.assert(self.dag.pending_events_len == 0);
    }
    
    /// Query events by timestamp range (temporal queries).
    /// Returns count of events within the time range.
    /// Caller should use get_processed_events() and filter by timestamp.
    pub fn count_events_by_time_range(
        self: *const EditorDagIntegration,
        start_timestamp: u64,
        end_timestamp: u64,
    ) u32 {
        // Assert: Time range must be valid
        std.debug.assert(start_timestamp <= end_timestamp);
        
        // Count matching events
        var count: u32 = 0;
        var i: u32 = 0;
        while (i < self.processed_events_len) : (i += 1) {
            const event = self.processed_events[i];
            if (event.timestamp >= start_timestamp and event.timestamp
<= end_timestamp) {
                count += 1;
            }
        }
        
        return count;
    }
    
    /// Get all processed events (for temporal queries).
    pub fn get_processed_events(self: *const EditorDagIntegration)
[]const ProcessedEvent {
        return self.processed_events[0..self.processed_events_len];
    }
    
    /// Query events up to a specific timestamp (time-travel).
    /// Returns all events that occurred before or at the given
timestamp.
    pub fn query_events_up_to_timestamp(
        self: *const EditorDagIntegration,
        timestamp: u64,
    ) []const ProcessedEvent {
        // Find last event before or at timestamp
        var last_idx: u32 = 0;
        var i: u32 = 0;
        while (i < self.processed_events_len) : (i += 1) {
            if (self.processed_events[i].timestamp <= timestamp) {
                last_idx = i + 1;
            }
        }
        
        // Return slice up to last matching event
        return self.processed_events[0..last_idx];
    }
    
    /// Get earliest event timestamp (for time slider range).
    pub fn get_earliest_timestamp(self: *const EditorDagIntegration)
?u64 {
        if (self.processed_events_len == 0) {
            return null;
        }
        
        var earliest: u64 = self.processed_events[0].timestamp;
        var i: u32 = 1;
        while (i < self.processed_events_len) : (i += 1) {
            if (self.processed_events[i].timestamp < earliest) {
                earliest = self.processed_events[i].timestamp;
            }
        }
        
        return earliest;
    }
    
    /// Get latest event timestamp (for time slider range).
    pub fn get_latest_timestamp(self: *const EditorDagIntegration) ?u64 {
        if (self.processed_events_len == 0) {
            return null;
        }
        
        var latest: u64 = self.processed_events[0].timestamp;
        var i: u32 = 1;
        while (i < self.processed_events_len) : (i += 1) {
            if (self.processed_events[i].timestamp > latest) {
                latest = self.processed_events[i].timestamp;
            }
        }
        
        return latest;
    }
    
    /// Get last event ID (for undo/redo navigation).
    pub fn get_last_event_id(self: *const EditorDagIntegration) u64 {
        return self.last_event_id;
    }
    
    /// Get buffer node ID.
    pub fn get_buffer_node_id(self: *const EditorDagIntegration) ?u32 {
        return self.buffer_node_id;
    }
    
    /// Get pending events count.
    pub fn get_pending_events_count(self: *const EditorDagIntegration)
u32 {
        return self.dag.pending_events_len;
    }
    
    /// Add event and update last event ID (for external event creation).
    /// This allows other modules (like AI insights) to add events and
maintain parent references.
    pub fn add_event_and_update_last(
        self: *EditorDagIntegration,
        event_type: DagCore.EventType,
        data: []const u8,
        parents: []const u64,
    ) !u64 {
        // Assert: Buffer node must exist
        std.debug.assert(self.buffer_node_id != null);
        
        // Add event to DAG
        const event_id = try self.dag.addEvent(
            event_type,
            self.buffer_node_id.?,
            data,
            parents,
        );
        
        // Update last event ID
        self.last_event_id = event_id;
        
        return event_id;
    }
};

test "editor dag integration initialization" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var integration = try EditorDagIntegration.init(arena.allocator());
    defer integration.deinit();
    
    // Assert: Integration initialized
    try std.testing.expect(integration.dag.nodes_len == 0);
    try std.testing.expect(integration.dag.edges_len == 0);
    try std.testing.expect(integration.buffer_node_id == null);
    try std.testing.expect(integration.last_event_id == 0);
}

test "editor dag create buffer node" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var integration = try EditorDagIntegration.init(arena.allocator());
    defer integration.deinit();
    
    const content = "line1\nline2\nline3";
    const node_id = try integration.create_buffer_node(content);
    
    // Assert: Buffer node created
    try std.testing.expect(node_id < DagCore.MAX_NODES);
    try std.testing.expect(integration.buffer_node_id == node_id);
    try std.testing.expect(integration.dag.nodes_len == 1);
}

test "editor dag map operation to event" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var integration = try EditorDagIntegration.init(arena.allocator());
    defer integration.deinit();
    
    const content = "line1\nline2\nline3";
    _ = try integration.create_buffer_node(content);
    
    // Map insert operation to event
    const event_id = try integration.map_operation_to_event(
        .insert,
        1,
        5,
        "",
        "new",
    );
    
    // Assert: Event was created
    try std.testing.expect(event_id > 0);
    try std.testing.expect(integration.dag.pending_events_len == 1);
    try std.testing.expect(integration.last_event_id == event_id);
}

test "editor dag event parent references" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var integration = try EditorDagIntegration.init(arena.allocator());
    defer integration.deinit();
    
    const content = "line1\nline2\nline3";
    _ = try integration.create_buffer_node(content);
    
    // Create first event
    const event1_id = try integration.map_operation_to_event(
        .insert,
        1,
        5,
        "",
        "new1",
    );
    
    // Create second event (should reference first as parent)
    const event2_id = try integration.map_operation_to_event(
        .insert,
        1,
        9,
        "",
        "new2",
    );
    
    // Assert: Events created with parent references
    try std.testing.expect(event1_id > 0);
    try std.testing.expect(event2_id > event1_id);
    try std.testing.expect(integration.dag.pending_events_len == 2);
    try std.testing.expect(integration.last_event_id == event2_id);
}

test "editor dag process events" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var integration = try EditorDagIntegration.init(arena.allocator());
    defer integration.deinit();
    
    const content = "line1\nline2\nline3";
    _ = try integration.create_buffer_node(content);
    
    // Create events
    _ = try integration.map_operation_to_event(.insert, 1, 5, "",
"new1");
    _ = try integration.map_operation_to_event(.insert, 1, 9, "",
"new2");
    
    // Process events
    try integration.process_events();
    
    // Assert: Events were processed
    try std.testing.expect(integration.dag.pending_events_len == 0);
    try std.testing.expect(integration.processed_events_len == 2);
}

test "editor dag temporal queries" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var integration = try EditorDagIntegration.init(arena.allocator());
    defer integration.deinit();
    
    const content = "line1\nline2\nline3";
    _ = try integration.create_buffer_node(content);
    
    // Create events with delays
    const event1_id = try integration.map_operation_to_event(.insert, 1,
5, "", "new1");
    _ = event1_id;
    
    // Note: Timestamps are set automatically by DAG, so events will
have different timestamps
    const event2_id = try integration.map_operation_to_event(.insert, 1,
9, "", "new2");
    _ = event2_id;
    
    // Process events
    try integration.process_events();
    
    // Assert: Events were stored in history
    try std.testing.expect(integration.processed_events_len == 2);
    
    // Test temporal queries
    const earliest = integration.get_earliest_timestamp();
    const latest = integration.get_latest_timestamp();
    
    try std.testing.expect(earliest != null);
    try std.testing.expect(latest != null);
    try std.testing.expect(latest.? >= earliest.?);
    
    // Test query events up to timestamp
    const all_events =
integration.query_events_up_to_timestamp(latest.?);
    try std.testing.expect(all_events.len == 2);
    
    // Test count events by time range
    const count = integration.count_events_by_time_range(earliest.?,
latest.?);
    try std.testing.expect(count == 2);
}


// === grain_skate/editor_renderer.zig ===

//! Grain Skate Editor Renderer: Renders editor text to pixel buffer.
//!
//! Why: Display editor content, cursor, selections, and status in
window.
//! Architecture: Pixel buffer rendering, monospace font, line-based
layout.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-05-172208-pst: Active implementation (migrated to shared
font renderer)

const std = @import("std");
const Editor = @import("editor.zig").Editor;
const LanguageDetector =
@import("language_detector.zig").LanguageDetector;
const Language = @import("language_detector.zig").Language;
const LanguageKeywords =
@import("language_keywords.zig").LanguageKeywords;
const BracketMatcher = @import("bracket_matching.zig").BracketMatcher;
const BracketMatch = @import("bracket_matching.zig").BracketMatch;
const FontRenderer = @import("../shared/font_renderer.zig").FontRenderer;

// Bounded: Max buffer width (explicit limit, in pixels)
// 2025-12-02-142853-pst: Active constant
pub const MAX_BUFFER_WIDTH: u32 = 4096;

// Bounded: Max buffer height (explicit limit, in pixels)
// 2025-12-02-142853-pst: Active constant
pub const MAX_BUFFER_HEIGHT: u32 = 4096;

// Bounded: Max visible lines (explicit limit)
// 2025-12-02-142853-pst: Active constant
pub const MAX_VISIBLE_LINES: u32 = 1000;

// Bounded: Max characters per line (explicit limit)
// 2025-12-02-142853-pst: Active constant
pub const MAX_CHARS_PER_LINE: u32 = 200;

// Font dimensions (8x8 bitmap font via shared font renderer)
// 2025-12-05-172208-pst: Active constants (migrated to shared font
renderer)
pub const CHAR_WIDTH: u32 = 9; // 8 pixels + 1 spacing
pub const CHAR_HEIGHT: u32 = 9; // 8 pixels + 1 spacing
pub const LINE_SPACING: u32 = 2; // Additional spacing between lines

// Color constants (RGBA format)
// 2025-12-02-142853-pst: Active constants
pub const COLOR_BACKGROUND: u32 = 0xFF1E1E1E; // Dark gray background
pub const COLOR_TEXT: u32 = 0xFFFFFFFF; // White text
pub const COLOR_CURSOR: u32 = 0xFFFFFFFF; // White cursor
pub const COLOR_SELECTION: u32 = 0xFF4A90E2; // Blue selection
pub const COLOR_STATUS_BG: u32 = 0xFF2D2D2D; // Darker gray for status
line
pub const COLOR_COMMAND_LINE: u32 = 0xFFFFFF00; // Yellow for command
line
pub const COLOR_LINE_NUMBERS: u32 = 0xFF808080; // Gray for line numbers
pub const COLOR_LINE_NUMBERS_BG: u32 = 0xFF252525; // Slightly darker
gray for line number column
pub const COLOR_ERROR: u32 = 0xFFFF0000; // Red for error messages
pub const COLOR_KEYWORD: u32 = 0xFF569CD6; // Blue for keywords
pub const COLOR_STRING: u32 = 0xFFCE9178; // Orange for strings
pub const COLOR_COMMENT: u32 = 0xFF6A9955; // Green for comments
pub const COLOR_NUMBER: u32 = 0xFFB5CEA8; // Light green for numbers
pub const COLOR_BRACKET_MATCH: u32 = 0xFFFFFF00; // Yellow for matching
brackets

// Font patterns removed - now using shared font renderer
// 2025-12-05-172208-pst: Migrated to shared font renderer

// Editor renderer state.
// 2025-12-02-142853-pst: Active struct
pub const EditorRenderer = struct {
    editor: *Editor.EditorState,
    buffer_width: u32,
    buffer_height: u32,
    viewport_line: u32, // First visible line (for scrolling)
    viewport_column: u32, // First visible column (for horizontal
scrolling)
    command_buffer: []const u8, // Command buffer for command mode
display
    block_title: []const u8, // Block title for status line display
    modified: bool, // Whether editor content has been modified since
last save
    error_message: []const u8, // Error message to display (empty if no
error)
    error_message_timeout: u64, // Timestamp when error message should
be cleared (0 = no timeout)
    syntax_highlighting_enabled: bool, // Whether syntax highlighting is
enabled
    detected_language: Language, // Detected programming language (for
language-specific highlighting)

    /// Initialize editor renderer.
    // 2025-12-05-172208-pst: Active function (migrated to shared font
renderer)
    pub fn init(editor: *Editor.EditorState, buffer_width: u32,
buffer_height: u32) EditorRenderer {
        std.debug.assert(buffer_width > 0);
        std.debug.assert(buffer_width <= MAX_BUFFER_WIDTH);
        std.debug.assert(buffer_height > 0);
        std.debug.assert(buffer_height <= MAX_BUFFER_HEIGHT);
        std.debug.assert(editor.buffer.lines_len > 0 or
editor.buffer.lines_len == 0);

        // Initialize shared font renderer (8x8 font, ASCII basic
character set)
        const font_renderer = FontRenderer.init(.font_8x8, .ascii_basic);

        return EditorRenderer{
            .editor = editor,
            .buffer_width = buffer_width,
            .buffer_height = buffer_height,
            .viewport_line = 0,
            .viewport_column = 0,
            .command_buffer = "",
            .block_title = "",
            .modified = false,
            .error_message = "",
            .error_message_timeout = 0,
            .syntax_highlighting_enabled = true, // Enable by default
            .detected_language = .unknown, // Default to unknown language
            .font_renderer = font_renderer,
        };
    }

    /// Update viewport to keep cursor visible.
    // 2025-12-02-142853-pst: Active function
    pub fn update_viewport(self: *EditorRenderer) void {
        const visible_lines = self.get_visible_line_count();
        const visible_cols = self.get_visible_column_count();
        // Adjust viewport to keep cursor visible
        if (self.editor.cursor_line < self.viewport_line) {
            self.viewport_line = self.editor.cursor_line;
        } else if (self.editor.cursor_line >= self.viewport_line +
visible_lines) {
            self.viewport_line = if (self.editor.cursor_line >=
visible_lines)
                self.editor.cursor_line - visible_lines + 1
            else
                0;
        }
        if (self.editor.cursor_column < self.viewport_column) {
            self.viewport_column = self.editor.cursor_column;
        } else if (self.editor.cursor_column >= self.viewport_column +
visible_cols) {
            self.viewport_column = if (self.editor.cursor_column >=
visible_cols)
                self.editor.cursor_column - visible_cols + 1
            else
                0;
        }
    }

    /// Get number of visible lines.
    // 2025-12-02-142853-pst: Active function
    fn get_visible_line_count(self: *const EditorRenderer) u32 {
        const status_height = CHAR_HEIGHT + LINE_SPACING;
        const available_height = if (self.buffer_height > status_height)
            self.buffer_height - status_height
        else
            self.buffer_height;
        const line_height = CHAR_HEIGHT + LINE_SPACING;
        return if (line_height > 0) available_height / line_height else
1;
    }

    /// Get number of visible columns (accounting for line number
column).
    // 2025-12-02-163144-pst: Active function
    fn get_visible_column_count(self: *const EditorRenderer) u32 {
        const line_num_width = self.get_line_number_column_width();
        const available_width = if (self.buffer_width > line_num_width)
            self.buffer_width - line_num_width
        else
            0;
        return if (CHAR_WIDTH > 0) available_width / CHAR_WIDTH else 1;
    }

    /// Get line number column width in pixels.
    // 2025-12-02-163144-pst: Active function
    fn get_line_number_column_width(self: *const EditorRenderer) u32 {
        const total_lines = self.editor.buffer.lines_len;
        // Calculate number of digits needed (max 6 digits for line
numbers)
        const max_line_num = @max(total_lines, 1);
        var digit_count: u32 = 1;
        var num = max_line_num;
        while (num >= 10) : (num /= 10) {
            digit_count += 1;
        }
        // Limit to 6 digits max (999,999 lines)
        digit_count = @min(digit_count, 6);
        // Add padding: digits + 2 spaces on each side = (digits + 4) *
CHAR_WIDTH
        const column_width = (digit_count + 4) * CHAR_WIDTH;
        return column_width;
    }

    /// Render editor to RGBA buffer.
    // 2025-12-02-142853-pst: Active function
    pub fn render(self: *EditorRenderer, buffer: []u8) void {
        std.debug.assert(buffer.len >= self.buffer_width *
self.buffer_height * 4);
        // Check and clear expired error messages
        self.check_error_timeout();
        // Update viewport to keep cursor visible
        self.update_viewport();
        // Clear buffer with background color
        self.clear_buffer(buffer);
        // Render line number column background
        self.render_line_number_column(buffer);
        // Render line numbers
        self.render_line_numbers(buffer);
        // Render text lines
        self.render_text_lines(buffer);
        // Render visual mode selections
        if (self.editor.mode == .visual or self.editor.mode ==
.visual_line or self.editor.mode == .visual_block) {
            self.render_selection(buffer);
        }
        // Render bracket matching (highlight matching bracket if cursor
is on bracket)
        self.render_bracket_match(buffer);
        // Render cursor
        self.render_cursor(buffer);
        // Render status line
        self.render_status_line(buffer);
        // Render command line or search pattern if active
        if (self.editor.mode == .command) {
            self.render_command_line(buffer);
        } else if (self.editor.mode == .search) {
            self.render_search_line(buffer);
        }
    }

    /// Clear buffer with background color.
    // 2025-12-02-142853-pst: Active function
    fn clear_buffer(self: *const EditorRenderer, buffer: []u8) void {
        const bg_r = @as(u8, @truncate((COLOR_BACKGROUND >> 16) & 0xFF));
        const bg_g = @as(u8, @truncate((COLOR_BACKGROUND >> 8) & 0xFF));
        const bg_b = @as(u8, @truncate(COLOR_BACKGROUND & 0xFF));
        const bg_a = @as(u8, @truncate((COLOR_BACKGROUND >> 24) & 0xFF));
        var i: u32 = 0;
        const total_pixels = self.buffer_width * self.buffer_height;
        while (i < total_pixels) : (i += 1) {
            const idx = i * 4;
            buffer[idx + 0] = bg_r;
            buffer[idx + 1] = bg_g;
            buffer[idx + 2] = bg_b;
            buffer[idx + 3] = bg_a;
        }
    }

    /// Render line number column background.
    // 2025-12-02-163144-pst: Active function
    fn render_line_number_column(self: *const EditorRenderer, buffer:
[]u8) void {
        const line_num_width = self.get_line_number_column_width();
        const visible_lines = self.get_visible_line_count();
        const status_height = CHAR_HEIGHT + LINE_SPACING;
        const content_height = self.buffer_height - status_height;
        const bg_r = @as(u8, @truncate((COLOR_LINE_NUMBERS_BG >> 16) &
0xFF));
        const bg_g = @as(u8, @truncate((COLOR_LINE_NUMBERS_BG >> 8) &
0xFF));
        const bg_b = @as(u8, @truncate(COLOR_LINE_NUMBERS_BG & 0xFF));
        const bg_a = @as(u8, @truncate((COLOR_LINE_NUMBERS_BG >> 24) &
0xFF));
        self.draw_rect(buffer, 0, 0, line_num_width, content_height,
bg_r, bg_g, bg_b, bg_a);
    }

    /// Render line numbers for visible lines.
    // 2025-12-02-163144-pst: Active function
    fn render_line_numbers(self: *const EditorRenderer, buffer: []u8)
void {
        const visible_lines = self.get_visible_line_count();
        const line_num_r = @as(u8, @truncate((COLOR_LINE_NUMBERS >> 16)
& 0xFF));
        const line_num_g = @as(u8, @truncate((COLOR_LINE_NUMBERS >> 8) &
0xFF));
        const line_num_b = @as(u8, @truncate(COLOR_LINE_NUMBERS & 0xFF));
        const line_num_a = @as(u8, @truncate((COLOR_LINE_NUMBERS >> 24)
& 0xFF));
        const total_lines = self.editor.buffer.lines_len;
        var line_idx: u32 = 0;
        while (line_idx < visible_lines and self.viewport_line +
line_idx < total_lines) : (line_idx += 1) {
            const line_num = self.viewport_line + line_idx + 1; //
1-based line numbers
            const line_y = line_idx * (CHAR_HEIGHT + LINE_SPACING);
            // Format line number as string
            var num_buf: [16]u8 = undefined;
            const num_str = self.format_number(line_num, &num_buf);
            // Right-align line number (calculate padding)
            const line_num_width = self.get_line_number_column_width();
            const num_width = num_str.len * CHAR_WIDTH;
            const padding = if (line_num_width > num_width + 2 *
CHAR_WIDTH)
                line_num_width - num_width - 2 * CHAR_WIDTH
            else
                0;
            const num_x = padding;
            // Render line number
            self.draw_text(buffer, num_str, num_x, line_y, line_num_r,
line_num_g, line_num_b, line_num_a);
        }
    }

    /// Render text lines from editor buffer.
    // 2025-12-02-142853-pst: Active function
    fn render_text_lines(self: *const EditorRenderer, buffer: []u8) void
{
        const visible_lines = self.get_visible_line_count();
        var line_idx: u32 = 0;
        while (line_idx < visible_lines and self.viewport_line +
line_idx < self.editor.buffer.lines_len) : (line_idx += 1) {
            const buffer_line = self.viewport_line + line_idx;
            const line_text = self.editor.buffer.lines[buffer_line];
            const line_y = line_idx * (CHAR_HEIGHT + LINE_SPACING);
            // Render line text (truncate to visible columns)
            const visible_cols = self.get_visible_column_count();
            const start_col = self.viewport_column;
            const end_col = @min(start_col + visible_cols, @as(u32,
@intCast(line_text.len)));
            if (start_col < line_text.len) {
                const visible_text = line_text[start_col..end_col];
                const line_num_width =
self.get_line_number_column_width();
                // Render with syntax highlighting if enabled
                if (self.syntax_highlighting_enabled) {
                    self.render_text_with_syntax(buffer, visible_text,
line_num_width, line_y, start_col);
                } else {
                    // Render without syntax highlighting
                    const text_r = @as(u8, @truncate((COLOR_TEXT >> 16)
& 0xFF));
                    const text_g = @as(u8, @truncate((COLOR_TEXT >> 8) &
0xFF));
                    const text_b = @as(u8, @truncate(COLOR_TEXT & 0xFF));
                    const text_a = @as(u8, @truncate((COLOR_TEXT >> 24)
& 0xFF));
                    self.draw_text(buffer, visible_text, line_num_width,
line_y, text_r, text_g, text_b, text_a);
                }
            }
        }
    }

    /// Render text with syntax highlighting.
    // 2025-12-02-180222-pst: Active function
    fn render_text_with_syntax(self: *const EditorRenderer, buffer:
[]u8, text: []const u8, x: u32, y: u32, line_start_col: u32) void {
        // Default text color
        const default_r = @as(u8, @truncate((COLOR_TEXT >> 16) & 0xFF));
        const default_g = @as(u8, @truncate((COLOR_TEXT >> 8) & 0xFF));
        const default_b = @as(u8, @truncate(COLOR_TEXT & 0xFF));
        const default_a = @as(u8, @truncate((COLOR_TEXT >> 24) & 0xFF));
        // Syntax colors
        const keyword_r = @as(u8, @truncate((COLOR_KEYWORD >> 16) &
0xFF));
        const keyword_g = @as(u8, @truncate((COLOR_KEYWORD >> 8) &
0xFF));
        const keyword_b = @as(u8, @truncate(COLOR_KEYWORD & 0xFF));
        const keyword_a = @as(u8, @truncate((COLOR_KEYWORD >> 24) &
0xFF));
        const string_r = @as(u8, @truncate((COLOR_STRING >> 16) & 0xFF));
        const string_g = @as(u8, @truncate((COLOR_STRING >> 8) & 0xFF));
        const string_b = @as(u8, @truncate(COLOR_STRING & 0xFF));
        const string_a = @as(u8, @truncate((COLOR_STRING >> 24) & 0xFF));
        const comment_r = @as(u8, @truncate((COLOR_COMMENT >> 16) &
0xFF));
        const comment_g = @as(u8, @truncate((COLOR_COMMENT >> 8) &
0xFF));
        const comment_b = @as(u8, @truncate(COLOR_COMMENT & 0xFF));
        const comment_a = @as(u8, @truncate((COLOR_COMMENT >> 24) &
0xFF));
        const number_r = @as(u8, @truncate((COLOR_NUMBER >> 16) & 0xFF));
        const number_g = @as(u8, @truncate((COLOR_NUMBER >> 8) & 0xFF));
        const number_b = @as(u8, @truncate(COLOR_NUMBER & 0xFF));
        const number_a = @as(u8, @truncate((COLOR_NUMBER >> 24) & 0xFF));
        // Parse syntax and render segments
        var i: u32 = 0;
        var char_x = x;
        var in_string = false;
        var string_char: u8 = 0; // ' or "
        var in_block_comment = false;
        while (i < text.len) : (i += 1) {
            const ch = text[i];
            // Check for comment start (// or /*)
            if (!in_string and !in_block_comment) {
                if (i + 1 < text.len) {
                    const next_ch = text[i + 1];
                    if (ch == '/' and next_ch == '/') {
                        // Single-line comment
                        const remaining = text[i..];
                        self.draw_text(buffer, remaining, char_x, y,
comment_r, comment_g, comment_b, comment_a);
                        break; // Rest of line is comment
                    }
                    if (ch == '/' and next_ch == '*') {
                        // Block comment start
                        in_block_comment = true;
                        self.draw_char(buffer, ch, char_x, y, comment_r,
comment_g, comment_b, comment_a);
                        char_x += CHAR_WIDTH;
                        i += 1;
                        if (i < text.len) {
                            self.draw_char(buffer, next_ch, char_x, y,
comment_r, comment_g, comment_b, comment_a);
                            char_x += CHAR_WIDTH;
                        }
                        continue;
                    }
                }
            }
            // Check for block comment end (*/)
            if (in_block_comment) {
                if (i + 1 < text.len and ch == '*' and text[i + 1] ==
'/') {
                    in_block_comment = false;
                    self.draw_char(buffer, ch, char_x, y, comment_r,
comment_g, comment_b, comment_a);
                    char_x += CHAR_WIDTH;
                    i += 1;
                    if (i < text.len) {
                        self.draw_char(buffer, text[i], char_x, y,
comment_r, comment_g, comment_b, comment_a);
                        char_x += CHAR_WIDTH;
                    }
                    continue;
                }
                // Still in block comment
                self.draw_char(buffer, ch, char_x, y, comment_r,
comment_g, comment_b, comment_a);
                char_x += CHAR_WIDTH;
                continue;
            }
            // Check for string start/end
            if (!in_block_comment) {
                if ((ch == '"' or ch == '\'') and (i == 0 or text[i - 1]
!= '\\')) {
                    if (!in_string) {
                        in_string = true;
                        string_char = ch;
                    } else if (ch == string_char) {
                        in_string = false;
                    }
                }
            }
            // Determine color based on syntax state
            var r = default_r;
            var g = default_g;
            var b = default_b;
            var a = default_a;
            if (in_string) {
                r = string_r;
                g = string_g;
                b = string_b;
                a = string_a;
            } else if (in_block_comment) {
                r = comment_r;
                g = comment_g;
                b = comment_b;
                a = comment_a;
            } else if (self.is_digit_start(ch)) {
                // Check if this is a number
                var j = i;
                var is_number = true;
                while (j < text.len and (self.is_digit(text[j]) or
text[j] == '.' or text[j] == '_')) : (j += 1) {
                    if (text[j] == '.' and j + 1 < text.len and
!self.is_digit(text[j + 1])) {
                        is_number = false;
                        break;
                    }
                }
                if (is_number and j > i) {
                    // Render number
                    const num_text = text[i..j];
                    self.draw_text(buffer, num_text, char_x, y,
number_r, number_g, number_b, number_a);
                    char_x += @as(u32, @intCast(num_text.len)) *
CHAR_WIDTH;
                    i = j - 1; // Will increment in loop
                    continue;
                }
            } else if (self.is_word_start(ch)) {
                // Check if this is a keyword
                var j = i;
                while (j < text.len and self.is_word_char(text[j])) : (j
+= 1) {}
                const word = text[i..j];
                if (self.is_keyword(word)) {
                    // Render keyword
                    self.draw_text(buffer, word, char_x, y, keyword_r,
keyword_g, keyword_b, keyword_a);
                    char_x += @as(u32, @intCast(word.len)) * CHAR_WIDTH;
                    i = j - 1; // Will increment in loop
                    continue;
                }
            }
            // Render character with determined color
            if (self.draw_char(buffer, ch, char_x, y, r, g, b, a)) {
                char_x += CHAR_WIDTH;
            }
        }
    }

    /// Render visual mode selection.
    // 2025-12-02-142853-pst: Active function
    fn render_selection(self: *const EditorRenderer, buffer: []u8) void {
        const selection = self.editor.get_visual_selection();
        const sel_r = @as(u8, @truncate((COLOR_SELECTION >> 16) & 0xFF));
        const sel_g = @as(u8, @truncate((COLOR_SELECTION >> 8) & 0xFF));
        const sel_b = @as(u8, @truncate(COLOR_SELECTION & 0xFF));
        const sel_a = @as(u8, @truncate((COLOR_SELECTION >> 24) & 0xFF));
        // Render selection rectangle
        var line: u32 = selection.start_line;
        while (line <= selection.end_line and line <
self.editor.buffer.lines_len) : (line += 1) {
            if (line < self.viewport_line or line >= self.viewport_line
+ self.get_visible_line_count()) {
                continue; // Line not visible
            }
            const line_text = self.editor.buffer.lines[line];
            const line_len = @as(u32, @intCast(line_text.len));
            const start_col = if (line == selection.start_line)
selection.start_column else 0;
            const end_col = if (line == selection.end_line)
selection.end_column else line_len;
            if (start_col < self.viewport_column +
self.get_visible_column_count() and end_col >= self.viewport_column) {
                const vis_start = if (start_col > self.viewport_column)
start_col - self.viewport_column else 0;
                const vis_end = @min(end_col - self.viewport_column,
self.get_visible_column_count());
                const line_y = (line - self.viewport_line) *
(CHAR_HEIGHT + LINE_SPACING);
                const line_num_width =
self.get_line_number_column_width();
                const sel_x = line_num_width + vis_start * CHAR_WIDTH;
                const sel_w = (vis_end - vis_start) * CHAR_WIDTH;
                const sel_y = line_y;
                const sel_h = CHAR_HEIGHT;
                self.draw_rect(buffer, sel_x, sel_y, sel_w, sel_h,
sel_r, sel_g, sel_b, sel_a / 2);
            }
        }
    }

    /// Render cursor.
    // 2025-12-02-142853-pst: Active function
    fn render_cursor(self: *const EditorRenderer, buffer: []u8) void {
        if (self.editor.cursor_line < self.viewport_line or
            self.editor.cursor_line >= self.viewport_line +
self.get_visible_line_count())
        {
            return; // Cursor not visible
        }
        if (self.editor.cursor_column < self.viewport_column or
            self.editor.cursor_column >= self.viewport_column +
self.get_visible_column_count())
        {
            return; // Cursor not visible
        }
        const cursor_r = @as(u8, @truncate((COLOR_CURSOR >> 16) & 0xFF));
        const cursor_g = @as(u8, @truncate((COLOR_CURSOR >> 8) & 0xFF));
        const cursor_b = @as(u8, @truncate(COLOR_CURSOR & 0xFF));
        const cursor_a = @as(u8, @truncate((COLOR_CURSOR >> 24) & 0xFF));
        const line_num_width = self.get_line_number_column_width();
        const cursor_x = line_num_width + (self.editor.cursor_column -
self.viewport_column) * CHAR_WIDTH;
        const cursor_y = (self.editor.cursor_line - self.viewport_line)
* (CHAR_HEIGHT + LINE_SPACING);
        // Draw vertical line cursor (1 pixel wide)
        self.draw_rect(buffer, cursor_x, cursor_y, 1, CHAR_HEIGHT,
cursor_r, cursor_g, cursor_b, cursor_a);
    }

    /// Render status line (mode, line/column info).
    // 2025-12-02-142853-pst: Active function
    fn render_status_line(self: *const EditorRenderer, buffer: []u8)
void {
        const status_y = self.buffer_height - CHAR_HEIGHT - LINE_SPACING;
        // Draw status line background
        const bg_r = @as(u8, @truncate((COLOR_STATUS_BG >> 16) & 0xFF));
        const bg_g = @as(u8, @truncate((COLOR_STATUS_BG >> 8) & 0xFF));
        const bg_b = @as(u8, @truncate(COLOR_STATUS_BG & 0xFF));
        const bg_a = @as(u8, @truncate((COLOR_STATUS_BG >> 24) & 0xFF));
        self.draw_rect(buffer, 0, status_y, self.buffer_width,
CHAR_HEIGHT + LINE_SPACING, bg_r, bg_g, bg_b, bg_a);
        // Build status text
        var status_buf: [128]u8 = undefined;
        var status_len: u32 = 0;
        // Block title (if available)
        if (self.block_title.len > 0) {
            const title_len = @min(self.block_title.len, 32); // Limit
title length
            @memcpy(status_buf[status_len..][0..title_len],
self.block_title[0..title_len]);
            status_len += title_len;
            status_buf[status_len] = ' ';
            status_len += 1;
        }
        // Mode indicator
        const mode_str = switch (self.editor.mode) {
            .normal => "NORMAL",
            .insert => "INSERT",
            .visual => "VISUAL",
            .visual_line => "VISUAL LINE",
            .visual_block => "VISUAL BLOCK",
            .command => "COMMAND",
            .search => "SEARCH",
        };
        @memcpy(status_buf[status_len..][0..mode_str.len], mode_str);
        status_len += @as(u32, @intCast(mode_str.len));
        // Add separator
        status_buf[status_len] = ' ';
        status_len += 1;
        // Line/column info
        const line_str = "L:";
        @memcpy(status_buf[status_len..][0..line_str.len], line_str);
        status_len += @as(u32, @intCast(line_str.len));
        var num_buf: [16]u8 = undefined;
        const line_num_str = self.format_number(self.editor.cursor_line
+ 1, &num_buf);
        @memcpy(status_buf[status_len..][0..line_num_str.len],
line_num_str);
        status_len += @as(u32, @intCast(line_num_str.len));
        status_buf[status_len] = ' ';
        status_len += 1;
        const col_str = "C:";
        @memcpy(status_buf[status_len..][0..col_str.len], col_str);
        status_len += @as(u32, @intCast(col_str.len));
        const col_num_str = self.format_number(self.editor.cursor_column
+ 1, &num_buf);
        @memcpy(status_buf[status_len..][0..col_num_str.len],
col_num_str);
        status_len += @as(u32, @intCast(col_num_str.len));
        // Add modified indicator if content has unsaved changes
        if (self.modified) {
            status_buf[status_len] = ' ';
            status_len += 1;
            const mod_str = "[+]";
            @memcpy(status_buf[status_len..][0..mod_str.len], mod_str);
            status_len += @as(u32, @intCast(mod_str.len));
        }
        // Add error message if present (replaces normal status info)
        var use_error_color = false;
        if (self.error_message.len > 0) {
            status_buf[status_len] = ' ';
            status_len += 1;
            const err_prefix = "ERROR:";
            @memcpy(status_buf[status_len..][0..err_prefix.len],
err_prefix);
            status_len += @as(u32, @intCast(err_prefix.len));
            status_buf[status_len] = ' ';
            status_len += 1;
            const err_len = @min(self.error_message.len, 64); // Limit
error message length
            @memcpy(status_buf[status_len..][0..err_len],
self.error_message[0..err_len]);
            status_len += @as(u32, @intCast(err_len));
            use_error_color = true;
        }
        // Render status text (use error color if error message present)
        const text_r = if (use_error_color)
            @as(u8, @truncate((COLOR_ERROR >> 16) & 0xFF))
        else
            @as(u8, @truncate((COLOR_TEXT >> 16) & 0xFF));
        const text_g = if (use_error_color)
            @as(u8, @truncate((COLOR_ERROR >> 8) & 0xFF))
        else
            @as(u8, @truncate((COLOR_TEXT >> 8) & 0xFF));
        const text_b = if (use_error_color)
            @as(u8, @truncate(COLOR_ERROR & 0xFF))
        else
            @as(u8, @truncate(COLOR_TEXT & 0xFF));
        const text_a = if (use_error_color)
            @as(u8, @truncate((COLOR_ERROR >> 24) & 0xFF))
        else
            @as(u8, @truncate((COLOR_TEXT >> 24) & 0xFF));
        self.draw_text(buffer, status_buf[0..status_len], 0, status_y,
text_r, text_g, text_b, text_a);
    }

    /// Set command buffer for command mode display.
    // 2025-12-02-154746-pst: Active function
    pub fn set_command_buffer(self: *EditorRenderer, cmd_buf: []const
u8) void {
        self.command_buffer = cmd_buf;
    }

    /// Set block title for status line display.
    // 2025-12-02-160032-pst: Active function
    pub fn set_block_title(self: *EditorRenderer, title: []const u8)
void {
        self.block_title = title;
    }

    /// Set modified flag (content has unsaved changes).
    // 2025-12-02-164404-pst: Active function
    pub fn set_modified(self: *EditorRenderer, modified: bool) void {
        self.modified = modified;
    }

    /// Detect and set language from block title/filename and content.
    // 2025-12-03-141818-pst: Active function
    pub fn detect_language(self: *EditorRenderer, filename: []const u8,
content: []const u8) void {
        self.detected_language = LanguageDetector.detect(filename,
content);
    }

    /// Render bracket matching highlight (highlight matching bracket if
cursor is on bracket).
    // 2025-12-03-162613-pst: Active function
    fn render_bracket_match(self: *const EditorRenderer, buffer: []u8)
void {
        // Find matching bracket at cursor position
        const match = BracketMatcher.find_matching_bracket(
            self.editor,
            self.editor.cursor_line,
            self.editor.cursor_column,
        );
        
        if (!match.found) {
            return; // No matching bracket found
        }
        
        // Highlight matching bracket if visible
        if (match.line >= self.viewport_line and
            match.line < self.viewport_line +
self.get_visible_line_count())
        {
            const line_text = self.editor.buffer.lines[match.line];
            if (match.column < line_text.len) {
                if (match.column >= self.viewport_column and
                    match.column < self.viewport_column +
self.get_visible_column_count())
                {
                    // Match is visible, highlight it
                    const match_r = @as(u8,
@truncate((COLOR_BRACKET_MATCH >> 16) & 0xFF));
                    const match_g = @as(u8,
@truncate((COLOR_BRACKET_MATCH >> 8) & 0xFF));
                    const match_b = @as(u8,
@truncate(COLOR_BRACKET_MATCH & 0xFF));
                    const match_a = @as(u8,
@truncate((COLOR_BRACKET_MATCH >> 24) & 0xFF));
                    const line_num_width =
self.get_line_number_column_width();
                    const match_x = line_num_width + (match.column -
self.viewport_column) * CHAR_WIDTH;
                    const match_y = (match.line - self.viewport_line) *
(CHAR_HEIGHT + LINE_SPACING);
                    // Draw highlight rectangle (full character
width/height)
                    self.draw_rect(buffer, match_x, match_y, CHAR_WIDTH,
CHAR_HEIGHT, match_r, match_g, match_b, match_a / 2);
                }
            }
        }
    }

    /// Set error message to display (with timeout in seconds).
    // 2025-12-02-171119-pst: Active function
    pub fn set_error(self: *EditorRenderer, message: []const u8,
timeout_sec: u64) void {
        self.error_message = message;
        if (timeout_sec > 0) {
            const now = std.time.timestamp();
            const now_u64 = @as(u64, @intCast(now));
            self.error_message_timeout = now_u64 + timeout_sec;
        } else {
            self.error_message_timeout = 0; // No timeout
        }
    }

    /// Clear error message.
    // 2025-12-02-171119-pst: Active function
    pub fn clear_error(self: *EditorRenderer) void {
        self.error_message = "";
        self.error_message_timeout = 0;
    }

    /// Check and clear expired error messages.
    // 2025-12-02-171119-pst: Active function
    fn check_error_timeout(self: *EditorRenderer) void {
        if (self.error_message_timeout > 0) {
            const now = std.time.timestamp();
            const now_u64 = @as(u64, @intCast(now));
            if (now_u64 >= self.error_message_timeout) {
                self.clear_error();
            }
        }
    }

    /// Check if character is a word start character.
    // 2025-12-02-180222-pst: Active function
    fn is_word_start(self: *const EditorRenderer, ch: u8) bool {
        _ = self;
        return (ch >= 'a' and ch <= 'z') or (ch >= 'A' and ch <= 'Z') or
ch == '_';
    }

    /// Check if character is a word character.
    // 2025-12-02-180222-pst: Active function
    fn is_word_char(self: *const EditorRenderer, ch: u8) bool {
        _ = self;
        return (ch >= 'a' and ch <= 'z') or (ch >= 'A' and ch <= 'Z') or
(ch >= '0' and ch <= '9') or ch == '_';
    }

    /// Check if character is a digit start (digit or sign + digit).
    // 2025-12-02-180222-pst: Active function
    fn is_digit_start(self: *const EditorRenderer, ch: u8) bool {
        _ = self;
        return ch >= '0' and ch <= '9';
    }

    /// Check if character is a digit.
    // 2025-12-02-180222-pst: Active function
    fn is_digit(self: *const EditorRenderer, ch: u8) bool {
        _ = self;
        return ch >= '0' and ch <= '9';
    }

    /// Check if word is a keyword (language-aware).
    // 2025-12-03-141818-pst: Active function
    fn is_keyword(self: *const EditorRenderer, word: []const u8) bool {
        // Use language-specific keywords if language is detected
        if (self.detected_language != .unknown) {
            return LanguageKeywords.is_keyword(self.detected_language,
word);
        }
        // Fall back to generic keywords (Zig-focused but
language-agnostic)
        const keywords = [_][]const u8{ "if", "else", "while", "for",
"fn", "var", "const", "return", "break", "continue", "pub", "priv",
"struct", "enum", "union", "error", "try", "catch", "defer", "switch",
"case", "default", "true", "false", "null", "undefined", "void", "bool",
"u8", "u16", "u32", "u64", "i8", "i16", "i32", "i64", "f32", "f64",
"usize", "isize", "comptime", "inline", "noinline", "export", "extern",
"packed", "align", "test", "async", "await", "suspend", "resume" };
        for (keywords) |keyword| {
            if (word.len == keyword.len and std.mem.eql(u8, word,
keyword)) {
                return true;
            }
        }
        return false;
    }

    /// Enable or disable syntax highlighting.
    // 2025-12-02-180222-pst: Active function
    pub fn set_syntax_highlighting(self: *EditorRenderer, enabled: bool)
void {
        self.syntax_highlighting_enabled = enabled;
    }

    /// Render command line (command mode input).
    // 2025-12-02-142853-pst: Active function
    fn render_command_line(self: *const EditorRenderer, buffer: []u8)
void {
        // Command line is rendered in status line area
        const status_y = self.buffer_height - CHAR_HEIGHT - LINE_SPACING;
        const cmd_r = @as(u8, @truncate((COLOR_COMMAND_LINE >> 16) &
0xFF));
        const cmd_g = @as(u8, @truncate((COLOR_COMMAND_LINE >> 8) &
0xFF));
        const cmd_b = @as(u8, @truncate(COLOR_COMMAND_LINE & 0xFF));
        const cmd_a = @as(u8, @truncate((COLOR_COMMAND_LINE >> 24) &
0xFF));
        const cmd_prompt = ":";
        self.draw_text(buffer, cmd_prompt, 0, status_y, cmd_r, cmd_g,
cmd_b, cmd_a);
        // Render command buffer if present
        if (self.command_buffer.len > 0) {
            self.draw_text(buffer, self.command_buffer, CHAR_WIDTH,
status_y, cmd_r, cmd_g, cmd_b, cmd_a);
        }
    }

    /// Render search line (search mode input).
    // 2025-12-02-142853-pst: Active function
    fn render_search_line(self: *const EditorRenderer, buffer: []u8)
void {
        // Search line is rendered in status line area
        const status_y = self.buffer_height - CHAR_HEIGHT - LINE_SPACING;
        const search_r = @as(u8, @truncate((COLOR_COMMAND_LINE >> 16) &
0xFF));
        const search_g = @as(u8, @truncate((COLOR_COMMAND_LINE >> 8) &
0xFF));
        const search_b = @as(u8, @truncate(COLOR_COMMAND_LINE & 0xFF));
        const search_a = @as(u8, @truncate((COLOR_COMMAND_LINE >> 24) &
0xFF));
        const search_prompt = if (self.editor.search_direction ==
.forward) "/" else "?";
        self.draw_text(buffer, search_prompt, 0, status_y, search_r,
search_g, search_b, search_a);
        // Render search pattern
        const pattern = self.editor.get_search_pattern();
        if (pattern.len > 0) {
            self.draw_text(buffer, pattern, CHAR_WIDTH, status_y,
search_r, search_g, search_b, search_a);
        }
    }

    /// Draw rectangle (filled).
    // 2025-12-02-142853-pst: Active function
    fn draw_rect(self: *const EditorRenderer, buffer: []u8, x: u32, y:
u32, w: u32, h: u32, r: u8, g: u8, b: u8, a: u8) void {
        var py: u32 = 0;
        while (py < h) : (py += 1) {
            const draw_y = y + py;
            if (draw_y >= self.buffer_height) {
                break;
            }
            var px: u32 = 0;
            while (px < w) : (px += 1) {
                const draw_x = x + px;
                if (draw_x >= self.buffer_width) {
                    break;
                }
                const idx = (draw_y * self.buffer_width + draw_x) * 4;
                buffer[idx + 0] = r;
                buffer[idx + 1] = g;
                buffer[idx + 2] = b;
                buffer[idx + 3] = a;
            }
        }
    }

    /// Draw text string (using shared font renderer).
    // 2025-12-05-172208-pst: Active function (migrated to shared font
renderer)
    fn draw_text(self: *const EditorRenderer, buffer: []u8, text:
[]const u8, x: u32, y: u32, r: u8, g: u8, b: u8, a: u8) void {
        std.debug.assert(x < self.buffer_width); // Precondition
        std.debug.assert(y < self.buffer_height); // Precondition
        
        const text_len = @min(text.len, MAX_CHARS_PER_LINE);
        var char_x = x;
        var i: u32 = 0;
        while (i < text_len) : (i += 1) {
            const ch = text[i];
            if (self.draw_char(buffer, ch, char_x, y, r, g, b, a)) {
                char_x += CHAR_WIDTH;
            }
        }
        
        std.debug.assert(char_x <= x + (text_len * CHAR_WIDTH)); //
Postcondition
    }

    /// Draw single character (using shared font renderer).
    // 2025-12-05-172208-pst: Active function (migrated to shared font
renderer)
    fn draw_char(self: *const EditorRenderer, buffer: []u8, ch: u8, x:
u32, y: u32, r: u8, g: u8, b: u8, a: u8) bool {
        std.debug.assert(x < self.buffer_width); // Precondition
        std.debug.assert(y < self.buffer_height); // Precondition
        
        // Get background color from buffer at this position (or use
default)
        const bg_r = @as(u8, @truncate((COLOR_BACKGROUND >> 16) & 0xFF));
        const bg_g = @as(u8, @truncate((COLOR_BACKGROUND >> 8) & 0xFF));
        const bg_b = @as(u8, @truncate(COLOR_BACKGROUND & 0xFF));
        const bg_a = @as(u8, @truncate((COLOR_BACKGROUND >> 24) & 0xFF));
        
        // Allocate temporary pixel buffer for character
        const char_w = self.font_renderer.get_char_width();
        const char_h = self.font_renderer.get_char_height();
        var char_pixels: [9 * 9 * 4]u8 = undefined; // Max 9x9 pixels
        const pixel_buf = char_pixels[0..(char_w * char_h * 4)];
        
        // Render character to pixel buffer
        if (!self.font_renderer.render_char_to_pixels(ch, r, g, b, a,
bg_r, bg_g, bg_b, bg_a, pixel_buf)) {
            return false; // Character not supported
        }
        
        // Copy pixel buffer to main buffer
        var row: u32 = 0;
        while (row < char_h) : (row += 1) {
            const py = y + row;
            if (py >= self.buffer_height) {
                break;
            }
            var col: u32 = 0;
            while (col < char_w) : (col += 1) {
                const px = x + col;
                if (px >= self.buffer_width) {
                    break;
                }
                const src_idx = (row * char_w + col) * 4;
                const dst_idx = (py * self.buffer_width + px) * 4;
                buffer[dst_idx + 0] = pixel_buf[src_idx + 0];
                buffer[dst_idx + 1] = pixel_buf[src_idx + 1];
                buffer[dst_idx + 2] = pixel_buf[src_idx + 2];
                buffer[dst_idx + 3] = pixel_buf[src_idx + 3];
            }
        }
        
        return true;
    }

    /// Format number as string (helper).
    // 2025-12-02-142853-pst: Active function
    fn format_number(self: *const EditorRenderer, num: u32, buf: []u8)
[]const u8 {
        _ = self;
        if (num == 0) {
            if (buf.len > 0) {
                buf[0] = '0';
                return buf[0..1];
            }
            return "";
        }
        var n = num;
        var i: u32 = 0;
        const max_digits = @min(buf.len, 16);
        while (n > 0 and i < max_digits) : (i += 1) {
            buf[max_digits - 1 - i] = @as(u8, @intCast('0' + (n % 10)));
            n /= 10;
        }
        return buf[max_digits - i..max_digits];
    }
};


// === grain_skate/graph_renderer.zig ===

//! Grain Skate Graph Renderer: Renders graph visualization to pixel
buffer.
//!
//! Why: Draw nodes and edges to window buffer for display.
//! Architecture: Pixel buffer rendering, coordinate transformation.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-11-24-121500-pst: Active implementation

const std = @import("std");
const GraphVisualization = @import("graph_viz.zig").GraphVisualization;
const Block = @import("block.zig").Block;

// Bounded: Max buffer width (explicit limit, in pixels)
// 2025-11-24-121500-pst: Active constant
pub const MAX_BUFFER_WIDTH: u32 = 4096;

// Bounded: Max buffer height (explicit limit, in pixels)
// 2025-11-24-121500-pst: Active constant
pub const MAX_BUFFER_HEIGHT: u32 = 4096;

// Color constants (RGBA format)
// 2025-11-24-121500-pst: Active constants
pub const COLOR_BACKGROUND: u32 = 0xFF1E1E1E; // Dark gray background
pub const COLOR_NODE: u32 = 0xFF4A90E2; // Blue node
pub const COLOR_NODE_SELECTED: u32 = 0xFFE24A4A; // Red selected node
pub const COLOR_EDGE: u32 = 0xFF666666; // Gray edge
pub const COLOR_TEXT: u32 = 0xFFFFFFFF; // White text
pub const COLOR_LABEL_BG: u32 = 0x80000000; // Semi-transparent black
background for labels

// Bounded: Max label length (explicit limit, in characters)
// 2025-11-24-171200-pst: Active constant
pub const MAX_LABEL_LEN: u32 = 32;

// Bounded: Max content preview length (explicit limit, in characters)
// 2025-12-04-095210-pst: Active constant
pub const MAX_CONTENT_PREVIEW_LEN: u32 = 20;

// Letter patterns for 5x7 bitmap font (A-Z).
// 2025-11-24-171200-pst: Active constant
const LETTER_PATTERNS = [26][7]u5{
    // A
    .{ 0b01110, 0b10001, 0b10001, 0b11111, 0b10001, 0b10001, 0b10001 },
    // B
    .{ 0b11110, 0b10001, 0b10001, 0b11110, 0b10001, 0b10001, 0b11110 },
    // C
    .{ 0b01110, 0b10001, 0b10000, 0b10000, 0b10000, 0b10001, 0b01110 },
    // D
    .{ 0b11110, 0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b11110 },
    // E
    .{ 0b11111, 0b10000, 0b10000, 0b11110, 0b10000, 0b10000, 0b11111 },
    // F
    .{ 0b11111, 0b10000, 0b10000, 0b11110, 0b10000, 0b10000, 0b10000 },
    // G
    .{ 0b01110, 0b10001, 0b10000, 0b10111, 0b10001, 0b10001, 0b01110 },
    // H
    .{ 0b10001, 0b10001, 0b10001, 0b11111, 0b10001, 0b10001, 0b10001 },
    // I
    .{ 0b01110, 0b00100, 0b00100, 0b00100, 0b00100, 0b00100, 0b01110 },
    // J
    .{ 0b00111, 0b00010, 0b00010, 0b00010, 0b10010, 0b10010, 0b01100 },
    // K
    .{ 0b10001, 0b10010, 0b10100, 0b11000, 0b10100, 0b10010, 0b10001 },
    // L
    .{ 0b10000, 0b10000, 0b10000, 0b10000, 0b10000, 0b10000, 0b11111 },
    // M
    .{ 0b10001, 0b11011, 0b10101, 0b10001, 0b10001, 0b10001, 0b10001 },
    // N
    .{ 0b10001, 0b11001, 0b10101, 0b10011, 0b10001, 0b10001, 0b10001 },
    // O
    .{ 0b01110, 0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b01110 },
    // P
    .{ 0b11110, 0b10001, 0b10001, 0b11110, 0b10000, 0b10000, 0b10000 },
    // Q
    .{ 0b01110, 0b10001, 0b10001, 0b10001, 0b10101, 0b10010, 0b01101 },
    // R
    .{ 0b11110, 0b10001, 0b10001, 0b11110, 0b10100, 0b10010, 0b10001 },
    // S
    .{ 0b01110, 0b10001, 0b10000, 0b01110, 0b00001, 0b10001, 0b01110 },
    // T
    .{ 0b11111, 0b00100, 0b00100, 0b00100, 0b00100, 0b00100, 0b00100 },
    // U
    .{ 0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b01110 },
    // V
    .{ 0b10001, 0b10001, 0b10001, 0b10001, 0b10001, 0b01010, 0b00100 },
    // W
    .{ 0b10001, 0b10001, 0b10001, 0b10001, 0b10101, 0b11011, 0b10001 },
    // X
    .{ 0b10001, 0b01010, 0b00100, 0b00100, 0b00100, 0b01010, 0b10001 },
    // Y
    .{ 0b10001, 0b10001, 0b01010, 0b00100, 0b00100, 0b00100, 0b00100 },
    // Z
    .{ 0b11111, 0b00001, 0b00010, 0b00100, 0b01000, 0b10000, 0b11111 },
};

// Graph renderer state.
// 2025-11-24-121500-pst: Active struct
pub const GraphRenderer = struct {
    graph_viz: *GraphVisualization,
    block_storage: ?*Block.BlockStorage,
    buffer_width: u32,
    buffer_height: u32,

    /// Initialize graph renderer.
    // 2025-11-24-121500-pst: Active function
    pub fn init(graph_viz: *GraphVisualization, buffer_width: u32,
buffer_height: u32) GraphRenderer {
        std.debug.assert(buffer_width > 0);
        std.debug.assert(buffer_width <= MAX_BUFFER_WIDTH);
        std.debug.assert(buffer_height > 0);
        std.debug.assert(buffer_height <= MAX_BUFFER_HEIGHT);
        std.debug.assert(graph_viz.zoom > 0.0);

        return GraphRenderer{
            .graph_viz = graph_viz,
            .block_storage = null,
            .buffer_width = buffer_width,
            .buffer_height = buffer_height,
        };
    }

    /// Set block storage for title lookup.
    // 2025-11-24-171200-pst: Active function
    pub fn set_block_storage(self: *GraphRenderer, block_storage:
*Block.BlockStorage) void {
        self.block_storage = block_storage;
    }

    /// Render graph to RGBA buffer.
    // 2025-11-24-121500-pst: Active function
    pub fn render(self: *const GraphRenderer, buffer: []u8) void {
        std.debug.assert(buffer.len >= self.buffer_width *
self.buffer_height * 4);
        std.debug.assert(self.graph_viz.zoom > 0.0);

        // Clear buffer with background color
        self.clear_buffer(buffer);

        // Render edges first (so nodes appear on top)
        self.render_edges(buffer);

        // Render nodes
        self.render_nodes(buffer);

        // Render node labels
        self.render_labels(buffer);
    }

    /// Clear buffer with background color.
    // 2025-11-24-121500-pst: Active function
    fn clear_buffer(self: *const GraphRenderer, buffer: []u8) void {
        const bg_r = @as(u8, @truncate((COLOR_BACKGROUND >> 16) & 0xFF));
        const bg_g = @as(u8, @truncate((COLOR_BACKGROUND >> 8) & 0xFF));
        const bg_b = @as(u8, @truncate(COLOR_BACKGROUND & 0xFF));
        const bg_a = @as(u8, @truncate((COLOR_BACKGROUND >> 24) & 0xFF));

        var y: u32 = 0;
        while (y < self.buffer_height) : (y += 1) {
            var x: u32 = 0;
            while (x < self.buffer_width) : (x += 1) {
                const idx = (y * self.buffer_width + x) * 4;
                buffer[idx + 0] = bg_r;
                buffer[idx + 1] = bg_g;
                buffer[idx + 2] = bg_b;
                buffer[idx + 3] = bg_a;
            }
        }
    }

    /// Render edges to buffer.
    // 2025-11-24-121500-pst: Active function
    fn render_edges(self: *const GraphRenderer, buffer: []u8) void {
        const edge_r = @as(u8, @truncate((COLOR_EDGE >> 16) & 0xFF));
        const edge_g = @as(u8, @truncate((COLOR_EDGE >> 8) & 0xFF));
        const edge_b = @as(u8, @truncate(COLOR_EDGE & 0xFF));
        const edge_a = @as(u8, @truncate((COLOR_EDGE >> 24) & 0xFF));

        var e: u32 = 0;
        while (e < self.graph_viz.edges_len) : (e += 1) {
            if (!self.graph_viz.edges[e].visible) {
                continue;
            }

            const from_node =
self.graph_viz.find_node(self.graph_viz.edges[e].from_block_id);
            const to_node =
self.graph_viz.find_node(self.graph_viz.edges[e].to_block_id);
            if (from_node == null or to_node == null) {
                continue;
            }

            const from_idx = from_node.?;
            const to_idx = to_node.?;

            // Transform normalized coordinates to pixel coordinates
            const x1 =
self.normalized_to_pixel_x(self.graph_viz.nodes[from_idx].position.x);
            const y1 =
self.normalized_to_pixel_y(self.graph_viz.nodes[from_idx].position.y);
            const x2 =
self.normalized_to_pixel_x(self.graph_viz.nodes[to_idx].position.x);
            const y2 =
self.normalized_to_pixel_y(self.graph_viz.nodes[to_idx].position.y);

            // Draw line using Bresenham's algorithm (iterative)
            self.draw_line(buffer, x1, y1, x2, y2, edge_r, edge_g,
edge_b, edge_a);
        }
    }

    /// Render nodes to buffer.
    // 2025-11-24-121500-pst: Active function
    fn render_nodes(self: *const GraphRenderer, buffer: []u8) void {
        var n: u32 = 0;
        while (n < self.graph_viz.nodes_len) : (n += 1) {
            if (!self.graph_viz.nodes[n].visible) {
                continue;
            }

            // Choose color based on selection state
            const color = if (self.graph_viz.nodes[n].selected)
COLOR_NODE_SELECTED else COLOR_NODE;
            const node_r = @as(u8, @truncate((color >> 16) & 0xFF));
            const node_g = @as(u8, @truncate((color >> 8) & 0xFF));
            const node_b = @as(u8, @truncate(color & 0xFF));
            const node_a = @as(u8, @truncate((color >> 24) & 0xFF));

            // Transform normalized coordinates to pixel coordinates
            const center_x =
self.normalized_to_pixel_x(self.graph_viz.nodes[n].position.x);
            const center_y =
self.normalized_to_pixel_y(self.graph_viz.nodes[n].position.y);
            const radius = @as(u32,
@intFromFloat(self.graph_viz.nodes[n].radius * self.graph_viz.zoom));

            // Draw filled circle
            self.draw_circle(buffer, center_x, center_y, radius, node_r,
node_g, node_b, node_a);
        }
    }

    /// Draw line using Bresenham's algorithm (iterative).
    // 2025-11-24-121500-pst: Active function
    fn draw_line(self: *const GraphRenderer, buffer: []u8, x1: u32, y1:
u32, x2: u32, y2: u32, r: u8, g: u8, b: u8, a: u8) void {
        var x0 = @as(i32, @intCast(x1));
        var y0 = @as(i32, @intCast(y1));
        const x1_i = @as(i32, @intCast(x2));
        const y1_i = @as(i32, @intCast(y2));

        const dx = std.math.absInt(x1_i - x0) catch 0;
        const dy = std.math.absInt(y1_i - y0) catch 0;
        const sx: i32 = if (x0 < x1_i) 1 else -1;
        const sy: i32 = if (y0 < y1_i) 1 else -1;
        var err = dx - dy;

        while (true) {
            if (x0 >= 0 and x0 < @as(i32, @intCast(self.buffer_width))
and y0 >= 0 and y0 < @as(i32, @intCast(self.buffer_height))) {
                const idx = (@as(u32, @intCast(y0)) * self.buffer_width
+ @as(u32, @intCast(x0))) * 4;
                buffer[idx + 0] = r;
                buffer[idx + 1] = g;
                buffer[idx + 2] = b;
                buffer[idx + 3] = a;
            }

            if (x0 == x1_i and y0 == y1_i) {
                break;
            }

            const e2 = 2 * err;
            if (e2 > -dy) {
                err -= dy;
                x0 += sx;
            }
            if (e2 < dx) {
                err += dx;
                y0 += sy;
            }
        }
    }

    /// Draw filled circle (iterative).
    // 2025-11-24-121500-pst: Active function
    fn draw_circle(self: *const GraphRenderer, buffer: []u8, center_x:
u32, center_y: u32, radius: u32, r: u8, g: u8, b: u8, a: u8) void {
        if (radius == 0) {
            return;
        }

        const radius_i = @as(i32, @intCast(radius));
        const center_x_i = @as(i32, @intCast(center_x));
        const center_y_i = @as(i32, @intCast(center_y));

        var y: i32 = -radius_i;
        while (y <= radius_i) : (y += 1) {
            var x: i32 = -radius_i;
            while (x <= radius_i) : (x += 1) {
                const dist_sq = x * x + y * y;
                if (dist_sq <= radius_i * radius_i) {
                    const px = center_x_i + x;
                    const py = center_y_i + y;
                    if (px >= 0 and px < @as(i32,
@intCast(self.buffer_width)) and py >= 0 and py < @as(i32,
@intCast(self.buffer_height))) {
                        const idx = (@as(u32, @intCast(py)) *
self.buffer_width + @as(u32, @intCast(px))) * 4;
                        buffer[idx + 0] = r;
                        buffer[idx + 1] = g;
                        buffer[idx + 2] = b;
                        buffer[idx + 3] = a;
                    }
                }
            }
        }
    }

    /// Transform normalized X coordinate to pixel coordinate.
    // 2025-11-24-121500-pst: Active function
    fn normalized_to_pixel_x(self: *const GraphRenderer, normalized_x:
f32) u32 {
        std.debug.assert(normalized_x >= 0.0);
        std.debug.assert(normalized_x <= 1.0);
        const offset_x = (normalized_x - self.graph_viz.center_x) *
self.graph_viz.zoom;
        const pixel_x = (@as(f32, @floatFromInt(self.buffer_width)) *
0.5) + (offset_x * @as(f32, @floatFromInt(self.buffer_width)));
        const clamped = std.math.clamp(pixel_x, 0.0, @as(f32,
@floatFromInt(self.buffer_width - 1)));
        return @as(u32, @intFromFloat(clamped));
    }

    /// Transform normalized Y coordinate to pixel coordinate.
    // 2025-11-24-121500-pst: Active function
    fn normalized_to_pixel_y(self: *const GraphRenderer, normalized_y:
f32) u32 {
        std.debug.assert(normalized_y >= 0.0);
        std.debug.assert(normalized_y <= 1.0);
        const offset_y = (normalized_y - self.graph_viz.center_y) *
self.graph_viz.zoom;
        const pixel_y = (@as(f32, @floatFromInt(self.buffer_height)) *
0.5) + (offset_y * @as(f32, @floatFromInt(self.buffer_height)));
        const clamped = std.math.clamp(pixel_y, 0.0, @as(f32,
@floatFromInt(self.buffer_height - 1)));
        return @as(u32, @intFromFloat(clamped));
    }

    /// Render node labels (block titles with background, centered,
truncated with ellipsis).
    // 2025-12-04-095210-pst: Active function
    fn render_labels(self: *const GraphRenderer, buffer: []u8) void {
        const text_r = @as(u8, @truncate((COLOR_TEXT >> 16) & 0xFF));
        const text_g = @as(u8, @truncate((COLOR_TEXT >> 8) & 0xFF));
        const text_b = @as(u8, @truncate(COLOR_TEXT & 0xFF));
        const text_a = @as(u8, @truncate((COLOR_TEXT >> 24) & 0xFF));
        const bg_r = @as(u8, @truncate((COLOR_LABEL_BG >> 16) & 0xFF));
        const bg_g = @as(u8, @truncate((COLOR_LABEL_BG >> 8) & 0xFF));
        const bg_b = @as(u8, @truncate(COLOR_LABEL_BG & 0xFF));
        const bg_a = @as(u8, @truncate((COLOR_LABEL_BG >> 24) & 0xFF));

        var n: u32 = 0;
        while (n < self.graph_viz.nodes_len) : (n += 1) {
            if (!self.graph_viz.nodes[n].visible) {
                continue;
            }

            // Transform normalized coordinates to pixel coordinates
            const center_x =
self.normalized_to_pixel_x(self.graph_viz.nodes[n].position.x);
            const center_y =
self.normalized_to_pixel_y(self.graph_viz.nodes[n].position.y);
            const radius = @as(u32,
@intFromFloat(self.graph_viz.nodes[n].radius * self.graph_viz.zoom));

            // Label position: below node (center_y + radius + offset)
            const label_y = center_y + radius + 12;

            // Get label text (title or block ID)
            var label_text: []const u8 = undefined;
            var label_text_len: u32 = 0;
            var is_number: bool = false;
            
            if (self.block_storage) |storage| {
                if (storage.get_block(self.graph_viz.nodes[n].block_id))
|block| {
                    if (block.title_len > 0) {
                        label_text = block.title[0..block.title_len];
                        label_text_len = block.title_len;
                    } else {
                        is_number = true;
                    }
                } else {
                    is_number = true;
                }
            } else {
                is_number = true;
            }

            // Handle number labels (block ID)
            if (is_number) {
                const num_digits =
self.count_digits(self.graph_viz.nodes[n].block_id);
                const text_width = num_digits * 6; // 6 pixels per digit
                const text_x = if (text_width < center_x) center_x -
(text_width / 2) else 0;
                const bg_width = text_width + 4; // Padding
                const bg_height: u32 = 9; // 7 pixels + 2 padding
                const bg_x = if (bg_width < center_x) center_x -
(bg_width / 2) else 0;
                const bg_y = label_y - 1; // 1 pixel padding above
                self.draw_rect(buffer, bg_x, bg_y, bg_width, bg_height,
bg_r, bg_g, bg_b, bg_a);
                self.draw_number(buffer,
self.graph_viz.nodes[n].block_id, text_x, label_y, text_r, text_g,
text_b, text_a);
                continue;
            }

            // Truncate text with ellipsis if needed
            var truncated_text: [MAX_LABEL_LEN + 3]u8 = undefined;
            var final_text: []const u8 = undefined;
            
            if (label_text_len > MAX_LABEL_LEN) {
                const trunc_len = MAX_LABEL_LEN - 3; // Reserve 3 chars
for "..."
                @memcpy(truncated_text[0..trunc_len],
label_text[0..trunc_len]);
                truncated_text[trunc_len] = '.';
                truncated_text[trunc_len + 1] = '.';
                truncated_text[trunc_len + 2] = '.';
                final_text = truncated_text[0..MAX_LABEL_LEN];
            } else {
                final_text = label_text;
            }

            // Calculate text width for centering
            const text_width = self.calculate_text_width(final_text);
            const text_x = if (text_width < center_x) center_x -
(text_width / 2) else 0;
            
            // Draw background rectangle (centered)
            const bg_width = text_width + 4; // Padding
            const bg_height: u32 = 9; // 7 pixels + 2 padding
            const bg_x = if (bg_width < center_x) center_x - (bg_width /
2) else 0;
            const bg_y = label_y - 1; // 1 pixel padding above
            self.draw_rect(buffer, bg_x, bg_y, bg_width, bg_height,
bg_r, bg_g, bg_b, bg_a);
            
            // Draw text (centered)
            self.draw_text(buffer, final_text, text_x, label_y, text_r,
text_g, text_b, text_a);
        }
    }

    /// Draw number at position (simple 5x7 bitmap font for digits).
    // 2025-11-24-170000-pst: Active function
    fn draw_number(self: *const GraphRenderer, buffer: []u8, number:
u32, x: u32, y: u32, r: u8, g: u8, b: u8, a: u8) void {
        // Convert number to string (max 10 digits for u32)
        var digits: [10]u8 = undefined;
        var num = number;
        var digit_count: u32 = 0;

        if (num == 0) {
            digits[0] = '0';
            digit_count = 1;
        } else {
            while (num > 0 and digit_count < 10) : (digit_count += 1) {
                digits[9 - digit_count] = @as(u8, @intCast('0' + (num %
10)));
                num /= 10;
            }
        }

        // Draw each digit
        var i: u32 = 0;
        while (i < digit_count) : (i += 1) {
            const digit = digits[10 - digit_count + i];
            const digit_x = x + (i * 6); // 6 pixels per digit (5 width
+ 1 spacing)
            self.draw_digit(buffer, digit, digit_x, y, r, g, b, a);
        }
    }

    /// Draw single digit using simple 5x7 bitmap font.
    // 2025-11-24-170000-pst: Active function
    fn draw_digit(self: *const GraphRenderer, buffer: []u8, digit: u8,
x: u32, y: u32, r: u8, g: u8, b: u8, a: u8) void {
        // Simple 5x7 bitmap patterns for digits 0-9
        const patterns = [10][7]u5{
            // 0
            .{ 0b01110, 0b10001, 0b10001, 0b10001, 0b10001, 0b10001,
0b01110 },
            // 1
            .{ 0b00100, 0b01100, 0b00100, 0b00100, 0b00100, 0b00100,
0b01110 },
            // 2
            .{ 0b01110, 0b10001, 0b00001, 0b00110, 0b01000, 0b10000,
0b11111 },
            // 3
            .{ 0b01110, 0b10001, 0b00001, 0b00110, 0b00001, 0b10001,
0b01110 },
            // 4
            .{ 0b00010, 0b00110, 0b01010, 0b10010, 0b11111, 0b00010,
0b00010 },
            // 5
            .{ 0b11111, 0b10000, 0b11110, 0b00001, 0b00001, 0b10001,
0b01110 },
            // 6
            .{ 0b00110, 0b01000, 0b10000, 0b11110, 0b10001, 0b10001,
0b01110 },
            // 7
            .{ 0b11111, 0b00001, 0b00010, 0b00100, 0b01000, 0b01000,
0b01000 },
            // 8
            .{ 0b01110, 0b10001, 0b10001, 0b01110, 0b10001, 0b10001,
0b01110 },
            // 9
            .{ 0b01110, 0b10001, 0b10001, 0b01111, 0b00001, 0b00010,
0b01100 },
        };

        if (digit < '0' or digit > '9') {
            return; // Invalid digit
        }

        const pattern_idx = digit - '0';
        const pattern = patterns[pattern_idx];

        // Draw pattern (5x7)
        var row: u32 = 0;
        while (row < 7) : (row += 1) {
            var col: u32 = 0;
            while (col < 5) : (col += 1) {
                if ((pattern[row] & (@as(u5, 1) << @as(u3, @intCast(4 -
col)))) != 0) {
                    const px = x + col;
                    const py = y + row;
                    if (px < self.buffer_width and py <
self.buffer_height) {
                        const idx = (py * self.buffer_width + px) * 4;
                        buffer[idx + 0] = r;
                        buffer[idx + 1] = g;
                        buffer[idx + 2] = b;
                        buffer[idx + 3] = a;
                    }
                }
            }
        }
    }

    /// Draw text string (supports alphanumeric and basic punctuation).
    // 2025-11-24-171200-pst: Active function
    fn draw_text(self: *const GraphRenderer, buffer: []u8, text: []const
u8, x: u32, y: u32, r: u8, g: u8, b: u8, a: u8) void {
        // Truncate text to max label length
        const text_len = @min(text.len, MAX_LABEL_LEN);
        var char_x = x;

        // Draw each character
        var i: u32 = 0;
        while (i < text_len) : (i += 1) {
            const ch = text[i];
            if (self.draw_char(buffer, ch, char_x, y, r, g, b, a)) {
                char_x += 6; // 6 pixels per character (5 width + 1
spacing)
            }
        }
    }

    /// Draw single character (supports digits, letters, space, basic
punctuation).
    // 2025-11-24-171200-pst: Active function
    fn draw_char(self: *const GraphRenderer, buffer: []u8, ch: u8, x:
u32, y: u32, r: u8, g: u8, b: u8, a: u8) bool {
        // Handle digits (already implemented)
        if (ch >= '0' and ch <= '9') {
            self.draw_digit(buffer, ch, x, y, r, g, b, a);
            return true;
        }

        // Handle space
        if (ch == ' ') {
            return true; // Skip space (no rendering needed)
        }

        // Handle uppercase letters (A-Z)
        if (ch >= 'A' and ch <= 'Z') {
            self.draw_letter_upper(buffer, ch, x, y, r, g, b, a);
            return true;
        }

        // Handle lowercase letters (a-z) - render as uppercase for
simplicity
        if (ch >= 'a' and ch <= 'z') {
            const upper_ch = ch - ('a' - 'A');
            self.draw_letter_upper(buffer, upper_ch, x, y, r, g, b, a);
            return true;
        }

        // Unsupported character - skip
        return false;
    }

    /// Draw uppercase letter using simple 5x7 bitmap font.
    // 2025-11-24-171200-pst: Active function
    fn draw_letter_upper(self: *const GraphRenderer, buffer: []u8,
letter: u8, x: u32, y: u32, r: u8, g: u8, b: u8, a: u8) void {
        if (letter < 'A' or letter > 'Z') {
            return; // Invalid letter
        }

        const pattern_idx = letter - 'A';
        const pattern = LETTER_PATTERNS[pattern_idx];

        // Draw pattern (5x7)
        self.draw_pattern(buffer, pattern, x, y, r, g, b, a);
    }

    /// Draw 5x7 pattern to buffer.
    // 2025-11-24-171200-pst: Active function
    fn draw_pattern(self: *const GraphRenderer, buffer: []u8, pattern:
[7]u5, x: u32, y: u32, r: u8, g: u8, b: u8, a: u8) void {
        var row: u32 = 0;
        while (row < 7) : (row += 1) {
            var col: u32 = 0;
            while (col < 5) : (col += 1) {
                if ((pattern[row] & (@as(u5, 1) << @as(u3, @intCast(4 -
col)))) != 0) {
                    const px = x + col;
                    const py = y + row;
                    if (px < self.buffer_width and py <
self.buffer_height) {
                        const idx = (py * self.buffer_width + px) * 4;
                        buffer[idx + 0] = r;
                        buffer[idx + 1] = g;
                        buffer[idx + 2] = b;
                        buffer[idx + 3] = a;
                    }
                }
            }
        }
    }

    /// Draw filled rectangle (iterative).
    // 2025-12-04-095210-pst: Active function
    fn draw_rect(self: *const GraphRenderer, buffer: []u8, x: u32, y:
u32, w: u32, h: u32, r: u8, g: u8, b: u8, a: u8) void {
        std.debug.assert(x < self.buffer_width); // Precondition
        std.debug.assert(y < self.buffer_height); // Precondition
        
        var py: u32 = 0;
        while (py < h) : (py += 1) {
            const draw_y = y + py;
            if (draw_y >= self.buffer_height) {
                break;
            }
            var px: u32 = 0;
            while (px < w) : (px += 1) {
                const draw_x = x + px;
                if (draw_x >= self.buffer_width) {
                    break;
                }
                const idx = (draw_y * self.buffer_width + draw_x) * 4;
                buffer[idx + 0] = r;
                buffer[idx + 1] = g;
                buffer[idx + 2] = b;
                buffer[idx + 3] = a;
            }
        }
        
        std.debug.assert(py <= h); // Postcondition
    }

    /// Calculate text width in pixels (for centering).
    // 2025-12-04-095210-pst: Active function
    fn calculate_text_width(self: *const GraphRenderer, text: []const
u8) u32 {
        _ = self;
        std.debug.assert(text.len <= MAX_LABEL_LEN); // Precondition
        
        var width: u32 = 0;
        var i: u32 = 0;
        while (i < text.len) : (i += 1) {
            const ch = text[i];
            if (ch == ' ') {
                width += 6; // Space is 6 pixels wide
            } else if ((ch >= '0' and ch <= '9') or (ch >= 'A' and ch <=
'Z') or (ch >= 'a' and ch <= 'z')) {
                width += 6; // 6 pixels per character (5 width + 1
spacing)
            } else {
                width += 6; // Default to 6 pixels for other characters
            }
        }
        
        std.debug.assert(width <= MAX_LABEL_LEN * 6); // Postcondition
        return width;
    }

    /// Count digits in a number (for width calculation).
    // 2025-12-04-095210-pst: Active function
    fn count_digits(self: *const GraphRenderer, number: u32) u32 {
        _ = self;
        std.debug.assert(number <= 0xFFFFFFFF); // Precondition
        
        if (number == 0) {
            return 1;
        }
        
        var count: u32 = 0;
        var num = number;
        while (num > 0) : (count += 1) {
            num /= 10;
        }
        
        std.debug.assert(count > 0); // Postcondition
        std.debug.assert(count <= 10); // Postcondition (u32 max is 10
digits)
        return count;
    }
};


// === grain_skate/graph_viz.zig ===

//! Grain Skate Graph Visualization: Visual representation of knowledge
graph.
//!
//! Why: Interactive graph visualization for blocks and links.
//! Architecture: Force-directed layout, iterative algorithms.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-11-24-110000-pst: Active implementation

const std = @import("std");
const Block = @import("block.zig").Block;

// Bounded: Max nodes in graph visualization.
// 2025-11-24-110000-pst: Active constant
pub const MAX_NODES: u32 = 1024;

// Bounded: Max edges in graph visualization.
// 2025-11-24-110000-pst: Active constant
pub const MAX_EDGES: u32 = 4096;

// Bounded: Max iterations for force-directed layout.
// 2025-11-24-110000-pst: Active constant
pub const MAX_ITERATIONS: u32 = 100;

// Node position in graph.
// 2025-11-24-110000-pst: Active struct
pub const NodePosition = struct {
    x: f32, // X position (normalized 0.0-1.0)
    y: f32, // Y position (normalized 0.0-1.0)
    vx: f32, // X velocity (for force-directed)
    vy: f32, // Y velocity (for force-directed)
};

// Graph node (represents a block).
// 2025-11-24-110000-pst: Active struct
pub const GraphNode = struct {
    block_id: u32, // Block ID
    position: NodePosition, // Node position
    radius: f32, // Node radius (for rendering)
    selected: bool, // Selection state
    visible: bool, // Visibility state
};

// Graph edge (represents a link).
// 2025-11-24-110000-pst: Active struct
pub const GraphEdge = struct {
    from_block_id: u32, // Source block ID
    to_block_id: u32, // Target block ID
    visible: bool, // Visibility state
};

// Graph visualization state.
// 2025-11-24-110000-pst: Active struct
pub const GraphVisualization = struct {
    nodes: [MAX_NODES]GraphNode, // Graph nodes
    nodes_len: u32, // Number of nodes
    edges: [MAX_EDGES]GraphEdge, // Graph edges
    edges_len: u32, // Number of edges
    center_x: f32, // View center X (normalized)
    center_y: f32, // View center Y (normalized)
    zoom: f32, // Zoom level (1.0 = normal)
    selected_block_id: ?u32, // Currently selected block
    allocator: std.mem.Allocator,

    /// Initialize graph visualization.
    // 2025-11-24-110000-pst: Active function
    pub fn init(allocator: std.mem.Allocator) GraphVisualization {
        var viz = GraphVisualization{
            .nodes = undefined,
            .nodes_len = 0,
            .edges = undefined,
            .edges_len = 0,
            .center_x = 0.5,
            .center_y = 0.5,
            .zoom = 1.0,
            .selected_block_id = null,
            .allocator = allocator,
        };
        var i: u32 = 0;
        while (i < MAX_NODES) : (i += 1) {
            viz.nodes[i] = GraphNode{
                .block_id = 0,
                .position = NodePosition{ .x = 0.0, .y = 0.0, .vx = 0.0,
.vy = 0.0 },
                .radius = 10.0,
                .selected = false,
                .visible = true,
            };
        }
        i = 0;
        while (i < MAX_EDGES) : (i += 1) {
            viz.edges[i] = GraphEdge{
                .from_block_id = 0,
                .to_block_id = 0,
                .visible = true,
            };
        }
        std.debug.assert(viz.zoom > 0.0);
        return viz;
    }

    /// Add block to graph.
    // 2025-11-24-110000-pst: Active function
    pub fn add_block(self: *GraphVisualization, block_id: u32) void {
        std.debug.assert(block_id > 0);
        std.debug.assert(self.nodes_len < MAX_NODES);
        const node = GraphNode{
            .block_id = block_id,
            .position = NodePosition{
                .x = 0.5 + (std.math.sin(@as(f32,
@floatFromInt(block_id))) * 0.2),
                .y = 0.5 + (std.math.cos(@as(f32,
@floatFromInt(block_id))) * 0.2),
                .vx = 0.0,
                .vy = 0.0,
            },
            .radius = 10.0,
            .selected = false,
            .visible = true,
        };
        self.nodes[self.nodes_len] = node;
        self.nodes_len += 1;
        std.debug.assert(self.nodes_len <= MAX_NODES);
    }

    /// Add link to graph.
    // 2025-11-24-110000-pst: Active function
    pub fn add_link(self: *GraphVisualization, from_id: u32, to_id: u32)
void {
        std.debug.assert(from_id > 0);
        std.debug.assert(to_id > 0);
        std.debug.assert(self.edges_len < MAX_EDGES);
        const edge = GraphEdge{
            .from_block_id = from_id,
            .to_block_id = to_id,
            .visible = true,
        };
        self.edges[self.edges_len] = edge;
        self.edges_len += 1;
        std.debug.assert(self.edges_len <= MAX_EDGES);
    }

    /// Calculate force-directed layout (iterative, no recursion).
    // 2025-11-24-110000-pst: Active function
    pub fn calculate_layout(self: *GraphVisualization, iterations: u32)
void {
        std.debug.assert(iterations > 0);
        std.debug.assert(iterations <= MAX_ITERATIONS);
        if (self.nodes_len == 0) {
            return;
        }

        // Force-directed layout parameters
        const k: f32 = 1.0; // Spring constant
        const repulsion: f32 = 100.0; // Repulsion force
        const damping: f32 = 0.9; // Velocity damping

        var iter: u32 = 0;
        while (iter < iterations) : (iter += 1) {
            self.reset_velocities();
            self.calculate_repulsion_forces(repulsion);
            self.calculate_attraction_forces(k);
            self.update_positions(damping);
        }
    }

    /// Reset all node velocities.
    // 2025-11-24-110000-pst: Active function
    fn reset_velocities(self: *GraphVisualization) void {
        var i: u32 = 0;
        while (i < self.nodes_len) : (i += 1) {
            self.nodes[i].position.vx = 0.0;
            self.nodes[i].position.vy = 0.0;
        }
    }

    /// Calculate repulsion forces between all node pairs.
    // 2025-11-24-110000-pst: Active function
    fn calculate_repulsion_forces(self: *GraphVisualization, repulsion:
f32) void {
        var i: u32 = 0;
        while (i < self.nodes_len) : (i += 1) {
            var j: u32 = i + 1;
            while (j < self.nodes_len) : (j += 1) {
                const dx = self.nodes[j].position.x -
self.nodes[i].position.x;
                const dy = self.nodes[j].position.y -
self.nodes[i].position.y;
                const dist_sq = (dx * dx) + (dy * dy);
                if (dist_sq < 0.0001) {
                    continue; // Avoid division by zero
                }
                const dist = std.math.sqrt(dist_sq);
                const force = repulsion / dist_sq;
                const fx = (dx / dist) * force;
                const fy = (dy / dist) * force;
                self.nodes[i].position.vx -= fx;
                self.nodes[i].position.vy -= fy;
                self.nodes[j].position.vx += fx;
                self.nodes[j].position.vy += fy;
            }
        }
    }

    /// Calculate attraction forces along edges.
    // 2025-11-24-110000-pst: Active function
    fn calculate_attraction_forces(self: *GraphVisualization, k: f32)
void {
        var e: u32 = 0;
        while (e < self.edges_len) : (e += 1) {
            const from_node =
self.find_node(self.edges[e].from_block_id);
            const to_node = self.find_node(self.edges[e].to_block_id);
            if (from_node == null or to_node == null) {
                continue;
            }
            const from_idx = from_node.?;
            const to_idx = to_node.?;
            const dx = self.nodes[to_idx].position.x -
self.nodes[from_idx].position.x;
            const dy = self.nodes[to_idx].position.y -
self.nodes[from_idx].position.y;
            const dist_sq = (dx * dx) + (dy * dy);
            if (dist_sq < 0.0001) {
                continue;
            }
            const dist = std.math.sqrt(dist_sq);
            const force = k * dist;
            const fx = (dx / dist) * force;
            const fy = (dy / dist) * force;
            self.nodes[from_idx].position.vx += fx;
            self.nodes[from_idx].position.vy += fy;
            self.nodes[to_idx].position.vx -= fx;
            self.nodes[to_idx].position.vy -= fy;
        }
    }

    /// Update node positions with damping and bounds clamping.
    // 2025-11-24-110000-pst: Active function
    fn update_positions(self: *GraphVisualization, damping: f32) void {
        var i: u32 = 0;
        while (i < self.nodes_len) : (i += 1) {
            self.nodes[i].position.x += self.nodes[i].position.vx *
damping;
            self.nodes[i].position.y += self.nodes[i].position.vy *
damping;
            // Clamp to bounds
            if (self.nodes[i].position.x < 0.0) {
                self.nodes[i].position.x = 0.0;
            }
            if (self.nodes[i].position.x > 1.0) {
                self.nodes[i].position.x = 1.0;
            }
            if (self.nodes[i].position.y < 0.0) {
                self.nodes[i].position.y = 0.0;
            }
            if (self.nodes[i].position.y > 1.0) {
                self.nodes[i].position.y = 1.0;
            }
        }
    }

    /// Find node index by block ID.
    // 2025-11-24-110000-pst: Active function
    fn find_node(self: *const GraphVisualization, block_id: u32) ?u32 {
        std.debug.assert(block_id > 0);
        var i: u32 = 0;
        while (i < self.nodes_len) : (i += 1) {
            if (self.nodes[i].block_id == block_id) {
                return i;
            }
        }
        return null;
    }

    /// Select block in graph.
    // 2025-11-24-110000-pst: Active function
    pub fn select_block(self: *GraphVisualization, block_id: u32) void {
        std.debug.assert(block_id > 0);
        // Deselect all
        var i: u32 = 0;
        while (i < self.nodes_len) : (i += 1) {
            self.nodes[i].selected = false;
        }
        // Select target
        if (self.find_node(block_id)) |idx| {
            self.nodes[idx].selected = true;
            self.selected_block_id = block_id;
        }
    }

    /// Pan view (move center).
    // 2025-11-24-110000-pst: Active function
    pub fn pan(self: *GraphVisualization, dx: f32, dy: f32) void {
        self.center_x += dx;
        self.center_y += dy;
        // Clamp to bounds
        if (self.center_x < 0.0) {
            self.center_x = 0.0;
        }
        if (self.center_x > 1.0) {
            self.center_x = 1.0;
        }
        if (self.center_y < 0.0) {
            self.center_y = 0.0;
        }
        if (self.center_y > 1.0) {
            self.center_y = 1.0;
        }
    }

    /// Zoom view.
    // 2025-11-24-110000-pst: Active function
    pub fn zoom_view(self: *GraphVisualization, delta: f32) void {
        self.zoom += delta;
        // Clamp zoom
        if (self.zoom < 0.1) {
            self.zoom = 0.1;
        }
        if (self.zoom > 10.0) {
            self.zoom = 10.0;
        }
        std.debug.assert(self.zoom > 0.0);
    }

    /// Find node at pixel coordinates (hit testing).
    // 2025-11-24-172500-pst: Active function
    pub fn find_node_at_pixel(self: *const GraphVisualization, pixel_x:
u32, pixel_y: u32, buffer_width: u32, buffer_height: u32) ?u32 {
        std.debug.assert(pixel_x < buffer_width);
        std.debug.assert(pixel_y < buffer_height);
        std.debug.assert(buffer_width > 0);
        std.debug.assert(buffer_height > 0);

        // Transform pixel coordinates to normalized coordinates
        const normalized_x = self.pixel_to_normalized_x(pixel_x,
buffer_width);
        const normalized_y = self.pixel_to_normalized_y(pixel_y,
buffer_height);

        // Check each node (reverse order for top-to-bottom hit testing)
        var i: u32 = self.nodes_len;
        while (i > 0) : (i -= 1) {
            const node_idx = i - 1;
            if (!self.nodes[node_idx].visible) {
                continue;
            }

            const node_x = self.nodes[node_idx].position.x;
            const node_y = self.nodes[node_idx].position.y;
            const node_radius = self.nodes[node_idx].radius * self.zoom;

            // Calculate distance from click to node center
            const dx = normalized_x - node_x;
            const dy = normalized_y - node_y;
            const dist_sq = (dx * dx) + (dy * dy);
            const radius_sq = node_radius * node_radius;

            // Check if click is within node radius
            if (dist_sq <= radius_sq) {
                return self.nodes[node_idx].block_id;
            }
        }

        return null;
    }

    /// Transform pixel X coordinate to normalized coordinate.
    // 2025-11-24-172500-pst: Active function
    fn pixel_to_normalized_x(self: *const GraphVisualization, pixel_x:
u32, buffer_width: u32) f32 {
        const offset_x = (@as(f32, @floatFromInt(pixel_x)) - (@as(f32,
@floatFromInt(buffer_width)) * 0.5)) / self.zoom;
        const normalized_x = self.center_x + (offset_x / @as(f32,
@floatFromInt(buffer_width)));
        return std.math.clamp(normalized_x, 0.0, 1.0);
    }

    /// Transform pixel Y coordinate to normalized coordinate.
    // 2025-11-24-172500-pst: Active function
    fn pixel_to_normalized_y(self: *const GraphVisualization, pixel_y:
u32, buffer_height: u32) f32 {
        const offset_y = (@as(f32, @floatFromInt(pixel_y)) - (@as(f32,
@floatFromInt(buffer_height)) * 0.5)) / self.zoom;
        const normalized_y = self.center_y + (offset_y / @as(f32,
@floatFromInt(buffer_height)));
        return std.math.clamp(normalized_y, 0.0, 1.0);
    }
};


// === grain_skate/language_detector.zig ===

//! Language Detector: Detects programming language from file extension
and shebang.
//!
//! Why: Enable language-specific syntax highlighting in Grain Skate
editor.
//! Architecture: Extension-based and shebang-based detection.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-03-141818-pst: Active implementation

const std = @import("std");

// Bounded: Max filename length (explicit limit, in bytes)
// 2025-12-03-141818-pst: Active constant
pub const MAX_FILENAME_LEN: u32 = 512;

// Bounded: Max shebang line length (explicit limit, in bytes)
// 2025-12-03-141818-pst: Active constant
pub const MAX_SHEBANG_LEN: u32 = 256;

// Programming language enumeration.
// 2025-12-03-141818-pst: Active enum
pub const Language = enum(u8) {
    unknown, // Unknown language (no highlighting)
    zig, // Zig
    rust, // Rust
    c, // C
    cpp, // C++
    python, // Python
    javascript, // JavaScript
    typescript, // TypeScript
    go, // Go
    java, // Java
    markdown, // Markdown
    json, // JSON
    yaml, // YAML
    shell, // Shell script
    html, // HTML
    css, // CSS
};

// Language detector state.
// 2025-12-03-141818-pst: Active struct
pub const LanguageDetector = struct {
    /// Detect language from filename (extension-based).
    // 2025-12-03-141818-pst: Active function
    pub fn detect_from_filename(filename: []const u8) Language {
        // Assert: Filename must be bounded
        std.debug.assert(filename.len <= MAX_FILENAME_LEN);
        // Find last dot (extension separator)
        var dot_idx: ?u32 = null;
        var i: u32 = 0;
        while (i < filename.len) : (i += 1) {
            if (filename[i] == '.') {
                dot_idx = i;
            }
        }
        if (dot_idx) |idx| {
            if (idx + 1 < filename.len) {
                const ext = filename[idx + 1..];
                return detect_from_extension(ext);
            }
        }
        return .unknown;
    }

    /// Detect language from file extension.
    // 2025-12-03-141818-pst: Active function
    fn detect_from_extension(ext: []const u8) Language {
        // Normalize extension to lowercase for comparison
        if (ext.len == 0) {
            return .unknown;
        }
        // Common extensions (case-insensitive comparison)
        if (std.mem.eql(u8, ext, "zig") or std.mem.eql(u8, ext, "ZIG")) {
            return .zig;
        }
        if (std.mem.eql(u8, ext, "rs") or std.mem.eql(u8, ext, "RS")) {
            return .rust;
        }
        if (std.mem.eql(u8, ext, "c") or std.mem.eql(u8, ext, "C")) {
            return .c;
        }
        if (std.mem.eql(u8, ext, "cpp") or std.mem.eql(u8, ext, "CPP")
or std.mem.eql(u8, ext, "cc") or std.mem.eql(u8, ext, "CC") or
std.mem.eql(u8, ext, "cxx") or std.mem.eql(u8, ext, "CXX")) {
            return .cpp;
        }
        if (std.mem.eql(u8, ext, "py") or std.mem.eql(u8, ext, "PY")) {
            return .python;
        }
        if (std.mem.eql(u8, ext, "js") or std.mem.eql(u8, ext, "JS")) {
            return .javascript;
        }
        if (std.mem.eql(u8, ext, "ts") or std.mem.eql(u8, ext, "TS")) {
            return .typescript;
        }
        if (std.mem.eql(u8, ext, "go") or std.mem.eql(u8, ext, "GO")) {
            return .go;
        }
        if (std.mem.eql(u8, ext, "java") or std.mem.eql(u8, ext,
"JAVA")) {
            return .java;
        }
        if (std.mem.eql(u8, ext, "md") or std.mem.eql(u8, ext, "MD") or
std.mem.eql(u8, ext, "markdown") or std.mem.eql(u8, ext, "MARKDOWN")) {
            return .markdown;
        }
        if (std.mem.eql(u8, ext, "json") or std.mem.eql(u8, ext,
"JSON")) {
            return .json;
        }
        if (std.mem.eql(u8, ext, "yaml") or std.mem.eql(u8, ext, "YAML")
or std.mem.eql(u8, ext, "yml") or std.mem.eql(u8, ext, "YML")) {
            return .yaml;
        }
        if (std.mem.eql(u8, ext, "sh") or std.mem.eql(u8, ext, "SH") or
std.mem.eql(u8, ext, "bash") or std.mem.eql(u8, ext, "BASH")) {
            return .shell;
        }
        if (std.mem.eql(u8, ext, "html") or std.mem.eql(u8, ext, "HTML")
or std.mem.eql(u8, ext, "htm") or std.mem.eql(u8, ext, "HTM")) {
            return .html;
        }
        if (std.mem.eql(u8, ext, "css") or std.mem.eql(u8, ext, "CSS")) {
            return .css;
        }
        return .unknown;
    }

    /// Detect language from shebang line (first line of file).
    // 2025-12-03-141818-pst: Active function
    pub fn detect_from_shebang(content: []const u8) Language {
        // Assert: Content must be bounded
        std.debug.assert(content.len <= MAX_SHEBANG_LEN);
        // Check for shebang (#!)
        if (content.len < 2) {
            return .unknown;
        }
        if (content[0] != '#' or content[1] != '!') {
            return .unknown;
        }
        // Find end of first line
        var line_end: u32 = 2;
        while (line_end < content.len and content[line_end] != '\n') :
(line_end += 1) {}
        const shebang_line = content[0..line_end];
        // Check for common interpreters
        if (std.mem.indexOf(u8, shebang_line, "python") != null or
std.mem.indexOf(u8, shebang_line, "python3") != null) {
            return .python;
        }
        if (std.mem.indexOf(u8, shebang_line, "node") != null) {
            return .javascript;
        }
        if (std.mem.indexOf(u8, shebang_line, "sh") != null or
std.mem.indexOf(u8, shebang_line, "bash") != null) {
            return .shell;
        }
        if (std.mem.indexOf(u8, shebang_line, "zig") != null) {
            return .zig;
        }
        return .unknown;
    }

    /// Detect language from filename and content (combined detection).
    // 2025-12-03-141818-pst: Active function
    pub fn detect(filename: []const u8, content: []const u8) Language {
        // Try filename first (more reliable)
        const lang_from_filename = detect_from_filename(filename);
        if (lang_from_filename != .unknown) {
            return lang_from_filename;
        }
        // Fall back to shebang if filename detection failed
        if (content.len > 0) {
            const lang_from_shebang = detect_from_shebang(content);
            if (lang_from_shebang != .unknown) {
                return lang_from_shebang;
            }
        }
        return .unknown;
    }
};


// === grain_skate/language_keywords.zig ===

//! Language Keywords: Language-specific keyword sets for syntax
highlighting.
//!
//! Why: Enable language-specific syntax highlighting in Grain Skate
editor.
//! Architecture: Keyword sets per language, efficient lookup.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-03-141818-pst: Active implementation

const std = @import("std");
const Language = @import("language_detector.zig").Language;

// Bounded: Max keywords per language (explicit limit)
// 2025-12-03-141818-pst: Active constant
pub const MAX_KEYWORDS_PER_LANG: u32 = 256;

// Language keywords module.
// 2025-12-03-141818-pst: Active struct
pub const LanguageKeywords = struct {
    /// Check if word is a keyword for given language.
    // 2025-12-03-141818-pst: Active function
    pub fn is_keyword(lang: Language, word: []const u8) bool {
        return switch (lang) {
            .zig => is_zig_keyword(word),
            .rust => is_rust_keyword(word),
            .c, .cpp => is_c_keyword(word),
            .python => is_python_keyword(word),
            .javascript, .typescript => is_javascript_keyword(word),
            .go => is_go_keyword(word),
            .java => is_java_keyword(word),
            .shell => is_shell_keyword(word),
            .html => is_html_keyword(word),
            .css => is_css_keyword(word),
            else => false, // Unknown language or no keywords
        };
    }

    /// Check if word is a Zig keyword.
    // 2025-12-03-141818-pst: Active function
    fn is_zig_keyword(word: []const u8) bool {
        const keywords = [_][]const u8{ "if", "else", "while", "for",
"fn", "var", "const", "return", "break", "continue", "pub", "priv",
"struct", "enum", "union", "error", "try", "catch", "defer", "switch",
"case", "default", "true", "false", "null", "undefined", "void", "bool",
"u8", "u16", "u32", "u64", "i8", "i16", "i32", "i64", "f32", "f64",
"usize", "isize", "comptime", "inline", "noinline", "export", "extern",
"packed", "align", "test", "async", "await", "suspend", "resume",
"anytype", "anyframe", "allowzero", "volatile", "linksection",
"callconv", "nakedcc", "stdcallcc", "asm", "usingnamespace" };
        for (keywords) |keyword| {
            if (word.len == keyword.len and std.mem.eql(u8, word,
keyword)) {
                return true;
            }
        }
        return false;
    }

    /// Check if word is a Rust keyword.
    // 2025-12-03-141818-pst: Active function
    fn is_rust_keyword(word: []const u8) bool {
        const keywords = [_][]const u8{ "as", "async", "await", "break",
"const", "continue", "crate", "dyn", "else", "enum", "extern", "false",
