// === grain_skate/line_buffer_adapter.zig ===

//! Grain Skate Line Buffer Adapter: Wraps GrainBuffer with line-based
API.
//!
//! Why: Editor uses line-based operations (lines array, replace_line,
remove_line),
//!      but GrainBuffer is byte-based (flat buffer). This adapter
bridges the gap.
//! Architecture: Maintains line index cache, converts between
line/column and byte offsets.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions,
iterative algorithms.
//!
//! 2025-12-06-054343-pst: Active implementation (Phase 2: Text Buffer
Unification)

const std = @import("std");
const GrainBuffer = @import("../grain_buffer.zig").GrainBuffer;

/// Line buffer adapter: Wraps GrainBuffer with line-based API.
// 2025-12-06-054343-pst: Active struct
pub const LineBufferAdapter = struct {
    // Bounded: Max buffer size (explicit limit, in bytes)
    pub const MAX_BUFFER_SIZE: u32 = 10_485_760; // 10 MB

    // Bounded: Max line length (explicit limit)
    pub const MAX_LINE_LEN: u32 = 65_536; // 64 KB

    // Bounded: Max lines (explicit limit)
    pub const MAX_LINES: u32 = MAX_BUFFER_SIZE / 64; // Max lines
estimate

    /// Underlying GrainBuffer (byte-based)
    buffer: GrainBuffer,

    /// Cached lines array (computed from buffer)
    lines: []const []const u8,

    /// Number of lines
    lines_len: u32,

    /// Allocator for line cache
    allocator: std.mem.Allocator,

    /// Line index cache: byte offsets of line starts (for efficient
updates)
    line_starts: []u32,

    /// Whether line cache is valid (false after buffer modifications)
    cache_valid: bool,

    /// Initialize line buffer adapter from content.
    // 2025-12-06-054343-pst: Active function
    pub fn init(allocator: std.mem.Allocator, content: []const u8)
!LineBufferAdapter {
        // Assert: Content must be bounded
        std.debug.assert(content.len <= MAX_BUFFER_SIZE);

        // Initialize GrainBuffer from content
        var buffer = try GrainBuffer.fromSlice(allocator, content);

        // Build line index cache
        var line_starts = try allocator.alloc(u32, MAX_LINES);
        errdefer allocator.free(line_starts);
        var line_starts_len: u32 = 0;

        var pos: u32 = 0;
        line_starts[0] = 0;
        line_starts_len = 1;

        var i: u32 = 0;
        while (i < content.len) : (i += 1) {
            if (content[i] == '\n') {
                if (line_starts_len >= MAX_LINES) {
                    return error.TooManyLines;
                }
                line_starts[line_starts_len] = i + 1;
                line_starts_len += 1;
                pos = i + 1;
            }
        }

        // Add last line if no trailing newline
        if (pos < content.len) {
            if (line_starts_len >= MAX_LINES) {
                return error.TooManyLines;
            }
            line_starts[line_starts_len] = pos;
            line_starts_len += 1;
        } else if (content.len > 0 and content[content.len - 1] == '\n')
{
            // Empty line at end
            if (line_starts_len >= MAX_LINES) {
                return error.TooManyLines;
            }
            line_starts[line_starts_len] = content.len;
            line_starts_len += 1;
        }

        // Trim line_starts to actual size
        const line_starts_trimmed = try allocator.realloc(line_starts,
line_starts_len);
        line_starts = line_starts_trimmed;

        // Build lines array from line index cache
        const lines = try allocator.alloc([]const u8, line_starts_len);
        errdefer allocator.free(lines);

        const text_slice = buffer.textSlice();
        var line_idx: u32 = 0;
        while (line_idx < line_starts_len) : (line_idx += 1) {
            const line_start = line_starts[line_idx];
            const line_end = if (line_idx + 1 < line_starts_len)
                line_starts[line_idx + 1] - 1 // Exclude newline
            else
                @as(u32, @intCast(text_slice.len));

            if (line_end > line_start) {
                const line_len = line_end - line_start;
                if (line_len > MAX_LINE_LEN) {
                    return error.LineTooLong;
                }
                lines[line_idx] = text_slice[line_start..line_end];
            } else {
                lines[line_idx] = text_slice[line_start..line_start]; //
Empty line
            }
        }

        return LineBufferAdapter{
            .buffer = buffer,
            .lines = lines,
            .lines_len = line_starts_len,
            .allocator = allocator,
            .line_starts = line_starts,
            .cache_valid = true,
        };
    }

    /// Deinitialize line buffer adapter and free memory.
    // 2025-12-06-054343-pst: Active function
    pub fn deinit(self: *LineBufferAdapter) void {
        // Assert: Allocator must be valid
        _ = self.allocator;

        // Free GrainBuffer
        self.buffer.deinit();

        // Free lines array
        if (self.lines.len > 0) {
            self.allocator.free(self.lines);
        }

        // Free line index cache
        if (self.line_starts.len > 0) {
            self.allocator.free(self.line_starts);
        }

        self.* = undefined;
    }

    /// Get content as single string.
    // 2025-12-06-054343-pst: Active function
    pub fn get_content(self: *const LineBufferAdapter) ![]const u8 {
        // Use GrainBuffer's text slice directly
        const text_slice = self.buffer.textSlice();
        const content = try self.allocator.alloc(u8, text_slice.len);
        errdefer self.allocator.free(content);
        @memcpy(content, text_slice);
        return content;
    }

    /// Replace a line in the buffer.
    // 2025-12-06-054343-pst: Active function
    pub fn replace_line(self: *LineBufferAdapter, line_index: u32,
new_line: []const u8) !void {
        std.debug.assert(line_index < self.lines_len);
        std.debug.assert(new_line.len <= MAX_LINE_LEN);

        // Invalidate cache
        self.cache_valid = false;

        // Get line byte range (line content only, excluding newline)
        const line_start = self.line_starts[line_index];
        const text_slice = self.buffer.textSlice();
        const line_end = if (line_index + 1 < self.lines_len)
            self.line_starts[line_index + 1] - 1 // Exclude newline
        else
            @as(u32, @intCast(text_slice.len));

        const old_line_len = line_end - line_start;

        // Replace line content in GrainBuffer (preserve newline
structure)
        if (old_line_len == new_line.len) {
            // Same length: overwrite
            try self.buffer.overwrite(line_start, new_line);
        } else {
            // Different length: erase old content, insert new content
            // Note: We don't touch the newline character (it's between
lines)
            try self.buffer.erase(line_start, old_line_len);
            try self.buffer.insert(line_start, new_line);
        }

        // Update line index cache (shift subsequent lines)
        const delta: i64 = @as(i64, @intCast(new_line.len)) - @as(i64,
@intCast(old_line_len));
        var i: u32 = line_index + 1;
        while (i < self.lines_len) : (i += 1) {
            if (delta >= 0) {
                self.line_starts[i] = @as(u32, @intCast(@as(i64,
@intCast(self.line_starts[i])) + delta));
            } else {
                const delta_u32 = @as(u32, @intCast(-delta));
                std.debug.assert(self.line_starts[i] >= delta_u32);
                self.line_starts[i] -= delta_u32;
            }
        }

        // Rebuild lines array
        try self.rebuild_lines_cache();
    }

    /// Remove a line from the buffer.
    // 2025-12-06-054343-pst: Active function
    pub fn remove_line(self: *LineBufferAdapter, line_index: u32) !void {
        std.debug.assert(line_index < self.lines_len);

        // Invalidate cache
        self.cache_valid = false;

        // Get line byte range (including newline if not last line)
        const line_start = self.line_starts[line_index];
        const line_end = if (line_index + 1 < self.lines_len)
            self.line_starts[line_index + 1] // Include newline
        else
            @as(u32, @intCast(self.buffer.textSlice().len));

        const line_len = line_end - line_start;

        // Remove line from GrainBuffer
        try self.buffer.erase(line_start, line_len);

        // Update line index cache (remove entry, shift subsequent lines)
        var i: u32 = line_index;
        while (i + 1 < self.lines_len) : (i += 1) {
            self.line_starts[i] = self.line_starts[i + 1] - line_len;
        }
        self.lines_len -= 1;

        // Trim line_starts array
        const line_starts_trimmed = try
self.allocator.realloc(self.line_starts, self.lines_len);
        self.line_starts = line_starts_trimmed;

        // Rebuild lines array
        try self.rebuild_lines_cache();
    }

    /// Rebuild lines cache from GrainBuffer and line index cache.
    // 2025-12-06-054343-pst: Active function
    fn rebuild_lines_cache(self: *LineBufferAdapter) !void {
        // Free old lines array
        if (self.lines.len > 0) {
            self.allocator.free(self.lines);
        }

        // Build new lines array
        const lines = try self.allocator.alloc([]const u8,
self.lines_len);
        errdefer self.allocator.free(lines);

        const text_slice = self.buffer.textSlice();
        var line_idx: u32 = 0;
        while (line_idx < self.lines_len) : (line_idx += 1) {
            const line_start = self.line_starts[line_idx];
            const line_end = if (line_idx + 1 < self.lines_len)
                self.line_starts[line_idx + 1] - 1 // Exclude newline
            else
                @as(u32, @intCast(text_slice.len));

            if (line_end > line_start) {
                lines[line_idx] = text_slice[line_start..line_end];
            } else {
                lines[line_idx] = text_slice[line_start..line_start]; //
Empty line
            }
        }

        self.lines = lines;
        self.cache_valid = true;
    }
};


// === grain_skate/modal_editor.zig ===

const std = @import("std");
const Editor = @import("editor.zig").Editor;
const events = @import("events");

/// Grain Skate Modal Editor: Vim/Kakoune keybindings for block editing.
/// ~<~ Glow Airbend: explicit keybinding state, bounded command buffers.
/// ~~~~ Glow Waterbend: deterministic key handling, iterative command
processing.
///
/// 2025-11-23-170000-pst: Active implementation
pub const ModalEditor = struct {
    // Bounded: Max command buffer size (explicit limit, in bytes)
    // 2025-11-23-170000-pst: Active constant
    pub const MAX_COMMAND_BUFFER: u32 = 256;

    // Bounded: Max key sequence length (explicit limit)
    // 2025-11-23-170000-pst: Active constant
    pub const MAX_KEY_SEQUENCE: u32 = 16;

    /// Keybinding action enumeration.
    // 2025-11-23-170000-pst: Active enum
    pub const Action = enum(u8) {
        move_left, // Move cursor left (h)
        move_right, // Move cursor right (l)
        move_up, // Move cursor up (k)
        move_down, // Move cursor down (j)
        move_word_forward, // Move to start of next word (w)
        move_word_backward, // Move to start of previous word (b)
        move_word_end, // Move to end of current/next word (e)
        move_line_start, // Move to beginning of line (0)
        move_line_end, // Move to end of line ($)
        move_line_start_nonblank, // Move to first non-whitespace (^)
        move_file_start, // Move to beginning of file (gg)
        move_file_end, // Move to end of file (G)
        insert_mode, // Enter insert mode (i)
        normal_mode, // Enter normal mode (Esc)
        visual_mode, // Enter visual mode (v)
        visual_line_mode, // Enter visual line mode (V)
        visual_block_mode, // Enter visual block mode (Ctrl+v)
        command_mode, // Enter command mode (:)
        search_mode, // Enter search mode (/)
        search_backward_mode, // Enter search backward mode (?)
        find_next, // Find next occurrence (n)
        find_previous, // Find previous occurrence (N)
        delete_char, // Delete character (x)
        delete_line, // Delete line (dd)
        yank, // Yank (copy) (y)
        paste, // Paste (p)
        undo, // Undo (u)
        redo, // Redo (Ctrl+r)
        save, // Save block (w)
        quit, // Quit (q)
        no_action, // No action
    };

    /// Modal editor state.
    // 2025-11-23-170000-pst: Active struct
    editor: *Editor.EditorState,
    command_buffer: [MAX_COMMAND_BUFFER]u8,
    command_buffer_len: u32,
    key_sequence: [MAX_KEY_SEQUENCE]u32, // Key sequence buffer for
multi-key commands
    key_sequence_len: u32, // Current key sequence length
    key_sequence_timeout: u64, // Timestamp for key sequence timeout
    last_command_result: CommandResult, // Last command execution result
    allocator: std.mem.Allocator,

    /// Initialize modal editor.
    // 2025-11-23-170000-pst: Active function
    pub fn init(allocator: std.mem.Allocator, editor:
*Editor.EditorState) !ModalEditor {
        // Assert: Editor must be valid
        // Parameters are used in struct initialization below

        return ModalEditor{
            .editor = editor,
            .command_buffer = undefined,
            .command_buffer_len = 0,
            .key_sequence = undefined,
            .key_sequence_len = 0,
            .key_sequence_timeout = 0,
            .last_command_result = .none,
            .allocator = allocator,
        };
    }

    /// Deinitialize modal editor.
    // 2025-11-23-170000-pst: Active function
    pub fn deinit(self: *ModalEditor) void {
        // Editor is owned by caller, don't deinit here
        self.* = undefined;
    }

    /// Handle keyboard event.
    // 2025-11-23-170000-pst: Active function
    pub fn handle_key_event(self: *ModalEditor, event:
events.KeyboardEvent) !void {
        // Assert: Event must be valid
        std.debug.assert(event.key_code < 256);

        // Get current editor mode
        const mode = self.editor.mode;

        // Handle key based on mode
        switch (mode) {
            .normal => try self.handle_normal_mode(event),
            .insert => try self.handle_insert_mode(event),
            .visual => try self.handle_visual_mode(event),
            .visual_line => try self.handle_visual_line_mode(event),
            .command => try self.handle_command_mode(event),
            .search => try self.handle_search_mode(event),
        }
    }

    /// Handle normal mode key event.
    // 2025-11-23-170000-pst: Active function
    fn handle_normal_mode(self: *ModalEditor, event:
events.KeyboardEvent) !void {
        // Map key to action
        const action = self.map_key_to_action(event);

        // Execute action
        switch (action) {
            .move_left => {
                // Move cursor left (h)
                self.editor.move_left();
            },
            .move_right => {
                // Move cursor right (l)
                self.editor.move_right();
            },
            .move_up => {
                // Move cursor up (k)
                self.editor.move_up();
            },
            .move_down => {
                // Move cursor down (j)
                self.editor.move_down();
            },
            .move_word_forward => {
                // Move to start of next word (w)
                self.editor.move_word_forward();
            },
            .move_word_backward => {
                // Move to start of previous word (b)
                self.editor.move_word_backward();
            },
            .move_word_end => {
                // Move to end of current/next word (e)
                self.editor.move_word_end();
            },
            .move_line_start => {
                // Move to beginning of line (0)
                self.editor.move_line_start();
            },
            .move_line_end => {
                // Move to end of line ($)
                self.editor.move_line_end();
            },
            .move_line_start_nonblank => {
                // Move to first non-whitespace (^)
                self.editor.move_line_start_nonblank();
            },
            .move_file_start => {
                // Move to beginning of file (gg)
                self.editor.move_file_start();
            },
            .move_file_end => {
                // Move to end of file (G)
                self.editor.move_file_end();
            },
            .insert_mode => {
                // Enter insert mode (i)
                self.editor.enter_insert_mode();
            },
            .visual_mode => {
                // Enter visual mode (v)
                self.editor.enter_visual_mode();
            },
            .visual_line_mode => {
                // Enter visual line mode (V)
                self.editor.enter_visual_line_mode();
            },
            .visual_block_mode => {
                // Enter visual block mode (Ctrl+v)
                self.editor.enter_visual_block_mode();
            },
            .search_mode => {
                // Enter search mode (/)
                self.editor.enter_search_mode();
            },
            .search_backward_mode => {
                // Enter search backward mode (?)
                self.editor.enter_search_backward_mode();
            },
            .find_next => {
                // Find next occurrence (n)
                _ = self.editor.find_next();
            },
            .find_previous => {
                // Find previous occurrence (N)
                _ = self.editor.find_previous();
            },
            .command_mode => {
                // Enter command mode (:)
                self.editor.mode = .command;
            },
            .delete_char => {
                // Delete character (x)
                self.editor.delete_char();
            },
            .undo => {
                // Undo (u)
                self.editor.undo() catch |err| {
                    // Handle undo error (e.g., out of memory)
                    _ = err;
                };
            },
            .redo => {
                // Redo (Ctrl+r)
                self.editor.redo() catch |err| {
                    // Handle redo error (e.g., out of memory)
                    _ = err;
                };
            },
            .yank => {
                // Yank (copy) line (y)
                self.editor.yank_line() catch |err| {
                    // Handle yank error (e.g., out of memory)
                    _ = err;
                };
            },
            .paste => {
                // Paste (p)
                self.editor.paste() catch |err| {
                    // Handle paste error (e.g., out of memory)
                    _ = err;
                };
            },
            .delete_line => {
                // Delete line (dd)
                self.editor.delete_line() catch |err| {
                    // Handle delete line error (e.g., out of memory)
                    _ = err;
                };
            },
            .no_action => {
                // No action
            },
            else => {
                // Other actions not yet implemented
            },
        }
    }

    /// Handle insert mode key event.
    // 2025-11-23-170000-pst: Active function
    fn handle_insert_mode(self: *ModalEditor, event:
events.KeyboardEvent) !void {
        // In insert mode, most keys insert characters
        if (event.key_code == 27) {
            // Escape key: return to normal mode
            self.editor.switch_mode(.normal);
        } else if (event.key_code >= 32 and event.key_code < 127) {
            // Printable ASCII character: insert it
            const char = @as(u8, @intCast(event.key_code));
            self.editor.insert_char(char);
        }
    }

    /// Handle visual block mode key event.
    // 2025-12-02-135701-pst: Active function
    fn handle_visual_block_mode(self: *ModalEditor, event:
events.KeyboardEvent) !void {
        // Visual block mode: similar to visual mode but with
column-based selection
        if (event.key_code == 27) {
            // Escape key: return to normal mode
            self.editor.exit_visual_mode();
        } else {
            // Map key to action
            const action = self.map_key_to_action(event);
            // Execute action (movement extends block selection)
            switch (action) {
                .move_left => self.editor.move_left(),
                .move_right => self.editor.move_right(),
                .move_up => self.editor.move_up(),
                .move_down => self.editor.move_down(),
                .move_word_forward => self.editor.move_word_forward(),
                .move_word_backward => self.editor.move_word_backward(),
                .move_word_end => self.editor.move_word_end(),
                .move_line_start => self.editor.move_line_start(),
                .move_line_end => self.editor.move_line_end(),
                .move_line_start_nonblank =>
self.editor.move_line_start_nonblank(),
                .move_file_start => self.editor.move_file_start(),
                .move_file_end => self.editor.move_file_end(),
                .yank => {
                    // Yank selected block (y)
                    self.editor.yank_selection() catch |err| {
                        _ = err;
                    };
                    self.editor.exit_visual_mode();
                },
                .delete_char => {
                    // Delete selected block (x)
                    self.editor.delete_selection() catch |err| {
                        _ = err;
                    };
                },
                .paste => {
                    // Paste (replace selection with yank buffer) (p)
                    self.editor.paste_selection() catch |err| {
                        _ = err;
                    };
                },
                .normal_mode => {
                    // Return to normal mode
                    self.editor.exit_visual_mode();
                },
                else => {
                    // Other actions not handled in visual block mode
                },
            }
        }
    }

    /// Handle visual line mode key event.
