            if (output_len + json_start.len > output.len) return
error.OutputTooSmall;
            @memcpy(output[output_len..][0..json_start.len], json_start);
            output_len += @as(u32, @intCast(json_start.len));

            // Export ID
            const id_str = try std.fmt.bufPrint(output[output_len..],
"\"id\":{}", .{block.id});
            if (output_len + id_str.len > output.len) return
error.OutputTooSmall;
            output_len += @as(u32, @intCast(id_str.len));

            // Export title
