                const title_comma = ",\"title\":\"";
                if (output_len + title_comma.len > output.len) return
error.OutputTooSmall;
                @memcpy(output[output_len..][0..title_comma.len],
title_comma);
                output_len += @as(u32, @intCast(title_comma.len));

                // Escape JSON in title
