                        },
                        '\\' => {
                            if (output_len + 2 > output.len) return
error.OutputTooSmall;
                            @memcpy(output[output_len..][0..2], "\\\\");
                            output_len += 2;
                        },
                        '\n' => {
                            if (output_len + 2 > output.len) return
error.OutputTooSmall;
                            @memcpy(output[output_len..][0..2], "\\n");
                            output_len += 2;
                        },
                        '\r' => {
                            if (output_len + 2 > output.len) return
error.OutputTooSmall;
                            @memcpy(output[output_len..][0..2], "\\r");
                            output_len += 2;
                        },
                        '\t' => {
                            if (output_len + 2 > output.len) return
error.OutputTooSmall;
                            @memcpy(output[output_len..][0..2], "\\t");
                            output_len += 2;
                        },
