        /// Export block to Markdown format.
        // 2025-11-23-124357-pst: Active function
        pub fn export_block_markdown(self: *ExportManager, block_id:
u32, output: []u8) !u32 {
            const block = self.block_storage.get_block(block_id) orelse
return error.BlockNotFound;

            var output_len: u32 = 0;

            // Title as heading
            if (block.title_len > 0) {
                const heading = "# ";
                if (output_len + heading.len > output.len) return
error.OutputTooSmall;
                @memcpy(output[output_len..][0..heading.len], heading);
                output_len += @as(u32, @intCast(heading.len));

                if (output_len + block.title_len > output.len) return
error.OutputTooSmall;
                @memcpy(output[output_len..][0..block.title_len],
block.title);
                output_len += block.title_len;

                const newline = "\n\n";
                if (output_len + newline.len > output.len) return
error.OutputTooSmall;
                @memcpy(output[output_len..][0..newline.len], newline);
                output_len += @as(u32, @intCast(newline.len));
            }

            // Content
            if (block.content_len > 0) {
                if (output_len + block.content_len > output.len) return
error.OutputTooSmall;
                @memcpy(output[output_len..][0..block.content_len],
block.content);
                output_len += block.content_len;
            }

            // Export links as Markdown links
            if (block.links_len > 0) {
                const links_header = "\n\n## Links\n\n";
                if (output_len + links_header.len > output.len) return
error.OutputTooSmall;
                @memcpy(output[output_len..][0..links_header.len],
links_header);
                output_len += @as(u32, @intCast(links_header.len));

                var i: u32 = 0;
                while (i < block.links_len) : (i += 1) {
                    const link_block =
self.block_storage.get_block(block.links[i]);
                    if (link_block) |linked| {
                        const link_md = try std.fmt.bufPrint(
                            output[output_len..],
                            "- [{}](block:{})\n",
                            .{ linked.title, block.links[i] }
                        );
                        if (output_len + link_md.len > output.len)
return error.OutputTooSmall;
                        output_len += @as(u32, @intCast(link_md.len));
                    } else {
                        const link_md = try std.fmt.bufPrint(
                            output[output_len..],
                            "- [Block {}](block:{})\n",
                            .{ block.links[i], block.links[i] }
                        );
                        if (output_len + link_md.len > output.len)
return error.OutputTooSmall;
                        output_len += @as(u32, @intCast(link_md.len));
                    }
                }
            }

            // Export metadata as frontmatter
            const frontmatter = try std.fmt.bufPrint(
                output[output_len..],
                "\n\n---\nid: {}\ncreated_at: {}\nupdated_at: {}\n---\n",
                .{ block.id, block.created_at, block.updated_at }
            );
            if (output_len + frontmatter.len > output.len) return
error.OutputTooSmall;
            output_len += @as(u32, @intCast(frontmatter.len));

            return output_len;
        }

        /// Import block from JSON format.
        // 2025-11-23-124357-pst: Active function
        pub fn import_block_json(self: *ExportManager, json_data:
[]const u8) !u32 {
            // Simple JSON parser (iterative, no recursion)
            // Parse:
{"id":123,"title":"...","content":"...","created_at":...,"updated_at":...
,"links":[...]}

            var pos: u32 = 0;
            var id: ?u32 = null;
            var title: ?[]const u8 = null;
            var content: ?[]const u8 = null;
            var created_at: ?u64 = null;
            var updated_at: ?u64 = null;
            // Bounded: Max links per block (use fixed array instead of
ArrayList)
            var links: [Block.MAX_LINKS_PER_BLOCK]u32 = undefined;
            var links_len: u32 = 0;

            // Skip whitespace
            while (pos < json_data.len and
std.ascii.isWhitespace(json_data[pos])) {
                pos += 1;
            }

            // Expect '{'
            if (pos >= json_data.len or json_data[pos] != '{') {
                return error.InvalidJson;
            }
            pos += 1;

            // Parse fields iteratively
            var first_field = true;
            while (pos < json_data.len) {
                // Skip whitespace
                while (pos < json_data.len and
std.ascii.isWhitespace(json_data[pos])) {
                    pos += 1;
                }

                // Check for closing brace
                if (json_data[pos] == '}') {
                    pos += 1;
                    break;
                }

                // Expect comma (except first field)
                if (!first_field) {
                    if (pos >= json_data.len or json_data[pos] != ',') {
                        return error.InvalidJson;
                    }
                    pos += 1;
                }
                first_field = false;

                // Skip whitespace
                while (pos < json_data.len and
std.ascii.isWhitespace(json_data[pos])) {
                    pos += 1;
                }

                // Parse field name
                if (pos >= json_data.len or json_data[pos] != '"') {
                    return error.InvalidJson;
                }
                pos += 1;

                const field_name_start = pos;
                while (pos < json_data.len and json_data[pos] != '"') {
                    pos += 1;
                }
                if (pos >= json_data.len) {
                    return error.InvalidJson;
                }
                const field_name = json_data[field_name_start..pos];
                pos += 1;

                // Skip whitespace and ':'
                while (pos < json_data.len and
std.ascii.isWhitespace(json_data[pos])) {
                    pos += 1;
                }
                if (pos >= json_data.len or json_data[pos] != ':') {
                    return error.InvalidJson;
                }
                pos += 1;
                while (pos < json_data.len and
std.ascii.isWhitespace(json_data[pos])) {
                    pos += 1;
                }

                // Parse field value based on field name
                if (std.mem.eql(u8, field_name, "id")) {
                    // Parse number
                    const num_start = pos;
                    while (pos < json_data.len and
std.ascii.isDigit(json_data[pos])) {
                        pos += 1;
                    }
                    const num_str = json_data[num_start..pos];
                    id = try std.fmt.parseInt(u32, num_str, 10);
                } else if (std.mem.eql(u8, field_name, "title")) {
                    // Parse string
                    if (pos >= json_data.len or json_data[pos] != '"') {
                        return error.InvalidJson;
                    }
                    pos += 1;
                    const str_start = pos;
                    while (pos < json_data.len and json_data[pos] !=
'"') {
                        if (json_data[pos] == '\\' and pos + 1 <
json_data.len) {
                            pos += 2; // Skip escape sequence
                        } else {
                            pos += 1;
                        }
                    }
                    if (pos >= json_data.len) {
                        return error.InvalidJson;
                    }
                    title = json_data[str_start..pos];
                    pos += 1;
                } else if (std.mem.eql(u8, field_name, "content")) {
                    // Parse string
                    if (pos >= json_data.len or json_data[pos] != '"') {
                        return error.InvalidJson;
                    }
                    pos += 1;
                    const str_start = pos;
                    while (pos < json_data.len and json_data[pos] !=
'"') {
                        if (json_data[pos] == '\\' and pos + 1 <
json_data.len) {
                            pos += 2; // Skip escape sequence
                        } else {
                            pos += 1;
                        }
                    }
                    if (pos >= json_data.len) {
                        return error.InvalidJson;
                    }
                    content = json_data[str_start..pos];
                    pos += 1;
                } else if (std.mem.eql(u8, field_name, "created_at")) {
                    const num_start = pos;
                    while (pos < json_data.len and
std.ascii.isDigit(json_data[pos])) {
                        pos += 1;
                    }
                    const num_str = json_data[num_start..pos];
                    created_at = try std.fmt.parseInt(u64, num_str, 10);
                } else if (std.mem.eql(u8, field_name, "updated_at")) {
                    const num_start = pos;
                    while (pos < json_data.len and
std.ascii.isDigit(json_data[pos])) {
                        pos += 1;
                    }
                    const num_str = json_data[num_start..pos];
                    updated_at = try std.fmt.parseInt(u64, num_str, 10);
                } else if (std.mem.eql(u8, field_name, "links")) {
                    // Parse array
                    if (pos >= json_data.len or json_data[pos] != '[') {
                        return error.InvalidJson;
                    }
                    pos += 1;

                    var first_link = true;
                    while (pos < json_data.len) {
                        while (pos < json_data.len and
std.ascii.isWhitespace(json_data[pos])) {
                            pos += 1;
                        }
                        if (json_data[pos] == ']') {
                            pos += 1;
                            break;
                        }
                        if (!first_link) {
                            if (json_data[pos] != ',') {
                                return error.InvalidJson;
                            }
                            pos += 1;
                        }
                        first_link = false;

                        const link_start = pos;
                        while (pos < json_data.len and
std.ascii.isDigit(json_data[pos])) {
                            pos += 1;
                        }
                        const link_str = json_data[link_start..pos];
                        const link_id = try std.fmt.parseInt(u32,
link_str, 10);
                        if (links_len >= Block.MAX_LINKS_PER_BLOCK) {
                            return error.TooManyLinks;
                        }
                        links[links_len] = link_id;
                        links_len += 1;
                    }
                }
            }

            // Create block from parsed data
            _ = id orelse return error.MissingField;
            const block_title = title orelse "";
            const block_content = content orelse "";

            const new_block_id = try
self.block_storage.create_block(block_title, block_content);

            // Restore links (if any)
            var i: u32 = 0;
            while (i < links_len) : (i += 1) {
                // Note: Linked blocks must exist for this to work
                // In a full implementation, we'd create missing blocks
or handle errors
                try self.block_storage.link_blocks(new_block_id,
links[i]);
            }

            return new_block_id;
        }
    };
};


// === grain_skate/storage_integration.zig ===

const std = @import("std");
const Block = @import("block.zig").Block;
const grain_court = @import("grain_court");
const grain_silo = @import("grain_silo");
const CourtCompute = grain_court.Compute.CourtCompute;
const ObjectStorage = grain_silo.Storage.ObjectStorage;

/// Grain Skate Storage Integration: Integrates Grain Court and Grain
Silo with block storage.
/// ~<~ Glow Airbend: explicit integration state, bounded
block-to-object mapping.
/// ~~~~ Glow Waterbend: deterministic storage operations, iterative
algorithms.
///
/// 2025-11-23-114146-pst: Active implementation
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const StorageIntegration = struct {
    // Bounded: Max block-to-object mappings (explicit limit)
    pub const MAX_BLOCK_MAPPINGS: u32 = 100_000;

    /// Block-to-object mapping structure.
    // 2025-11-23-114146-pst: Active struct
    pub const BlockMapping = struct {
        block_id: u32, // Block ID
        object_key: []const u8, // Object key in Grain Silo
        object_key_len: u32,
        is_hot: bool, // Is block in hot cache (Grain Court SRAM)?
        hot_cache_offset: ?u64, // Hot cache offset (if in SRAM)
        allocator: std.mem.Allocator,

        /// Initialize block mapping.
        // 2025-11-23-124357-pst: Active function
        pub fn init(allocator: std.mem.Allocator, block_id: u32,
object_key: []const u8) !BlockMapping {

            // Allocate object key
            const key_copy = try allocator.dupe(u8, object_key);
            errdefer allocator.free(key_copy);

            return BlockMapping{
                .block_id = block_id,
                .object_key = key_copy,
                .object_key_len = @as(u32, @intCast(key_copy.len)),
                .is_hot = false,
                .hot_cache_offset = null,
                .allocator = allocator,
            };
        }

        /// Deinitialize block mapping and free memory.
        pub fn deinit(self: *BlockMapping) void {
            // Assert: Allocator must be valid
            // Assert: Allocator must be valid (check by attempting
deallocation)
            _ = self.allocator;

            // Free object key
            if (self.object_key_len > 0) {
                self.allocator.free(self.object_key);
            }

            self.* = undefined;
        }
    };

    /// Storage integration structure.
    // 2025-11-23-114146-pst: Active struct
    pub const Integration = struct {
        block_storage: *Block.BlockStorage, // Block storage
        court_compute: *CourtCompute, // Grain Court compute layer
        object_storage: *ObjectStorage, // Grain Silo object storage
        mappings: []BlockMapping, // Block-to-object mappings (bounded)
        mappings_len: u32, // Number of mappings
        allocator: std.mem.Allocator,

        /// Initialize storage integration.
        // 2025-11-23-114146-pst: Active function
        pub fn init(
            allocator: std.mem.Allocator,
            block_storage: *Block.BlockStorage,
            court_compute: *CourtCompute,
            object_storage: *ObjectStorage,
        ) !Integration {
            // Assert: Allocator must be valid (check by attempting
allocation)
            // allocator is used in pre-allocate calls below

            // Pre-allocate mappings buffer
            const mappings = try allocator.alloc(BlockMapping,
MAX_BLOCK_MAPPINGS);
            errdefer allocator.free(mappings);

            return Integration{
                .block_storage = block_storage,
                .court_compute = court_compute,
                .object_storage = object_storage,
                .mappings = mappings,
                .mappings_len = 0,
                .allocator = allocator,
            };
        }

        /// Deinitialize storage integration and free memory.
        pub fn deinit(self: *Integration) void {
            // Assert: Allocator must be valid
            // Assert: Allocator must be valid (check by attempting
deallocation)
            _ = self.allocator;

            // Deinitialize all mappings
            var i: u32 = 0;
            while (i < self.mappings_len) : (i += 1) {
                self.mappings[i].deinit();
            }

            // Free mappings buffer
            self.allocator.free(self.mappings);

            self.* = undefined;
        }

        /// Persist block to Grain Silo (cold storage).
        // 2025-11-23-114146-pst: Active function
        pub fn persist_block(self: *Integration, block_id: u32) !void {
            if (self.block_storage.get_block(block_id)) |block| {
                // Create object key from block ID
                var key_buf: [64]u8 = undefined;
                const key = try std.fmt.bufPrint(&key_buf, "block-{}",
.{block_id});

                // Serialize block data (simplified: just content for
now)
                const metadata = try std.fmt.allocPrint(self.allocator,
"title:{s}", .{block.title});
                defer self.allocator.free(metadata);

                // Store in Grain Silo
                try self.object_storage.store_object(key, block.content,
metadata);

                // Create mapping
                if (self.mappings_len >= MAX_BLOCK_MAPPINGS) {
                    return error.TooManyMappings;
                }

                var mapping = try BlockMapping.init(self.allocator,
block_id, key);
                errdefer mapping.deinit();

                self.mappings[self.mappings_len] = mapping;
                self.mappings_len += 1;
            } else {
                return error.BlockNotFound;
            }
        }

        /// Load block from Grain Silo (cold storage).
        // 2025-11-23-114146-pst: Active function
        pub fn load_block(self: *Integration, block_id: u32) !void {
            // Find mapping
            var i: u32 = 0;
            while (i < self.mappings_len) : (i += 1) {
                if (self.mappings[i].block_id == block_id) {
                    const mapping = &self.mappings[i];

                    // Get object from Grain Silo
                    if
(self.object_storage.get_object(mapping.object_key)) |object| {
                        // Update block content (block must already
exist)
                        if (self.block_storage.get_block(block_id))
|block| {
                            try block.update_content(object.data);
                        } else {
                            return error.BlockNotFound;
                        }
                    } else {
                        return error.ObjectNotFound;
                    }
                    return;
                }
            }
            return error.MappingNotFound;
        }

        /// Promote block to hot cache (Grain Court SRAM).
        // 2025-12-05-145359-pst: Active function
        pub fn promote_block_to_hot(self: *Integration, block_id: u32)
!void {
            // Find mapping
            var i: u32 = 0;
            while (i < self.mappings_len) : (i += 1) {
                if (self.mappings[i].block_id == block_id) {
                    const mapping = &self.mappings[i];

                    // Get block
                    if (self.block_storage.get_block(block_id)) |block| {
                        // Allocate SRAM for block content
                        const cache_offset = try
self.court_compute.allocate_sram(0, @as(u64,
@intCast(block.content_len)));

                        // Promote object to hot cache
                        try
self.object_storage.promote_to_hot(mapping.object_key, cache_offset);

                        // Update mapping
                        mapping.is_hot = true;
                        mapping.hot_cache_offset = cache_offset;
                    } else {
                        return error.BlockNotFound;
                    }
                    return;
                }
            }
            return error.MappingNotFound;
        }

        /// Demote block from hot cache (move to cold storage).
        // 2025-11-23-114146-pst: Active function
        pub fn demote_block_from_hot(self: *Integration, block_id: u32)
void {
            // Find mapping
            var i: u32 = 0;
            while (i < self.mappings_len) : (i += 1) {
                if (self.mappings[i].block_id == block_id) {
                    const mapping = &self.mappings[i];

                    if (mapping.is_hot) {
                        // Demote object from hot cache
                       
self.object_storage.demote_from_hot(mapping.object_key);

                        // Update mapping
                        mapping.is_hot = false;
                        mapping.hot_cache_offset = null;
                    }
                    return;
                }
            }
        }
    };
};


// === grain_skate/temporal_graph.zig ===

const std = @import("std");
const EditorDagIntegration =
@import("editor_dag_integration.zig").EditorDagIntegration;

/// Temporal Knowledge Graph: Time-travel mode for knowledge graph.
/// ~<~ Glow Airbend: explicit temporal queries, bounded history.
/// ~~~~ Glow Waterbend: time-travel flows deterministically through DAG.
///
/// This implements time-travel capabilities for knowledge graphs:
/// - View graph at any point in time
/// - Block version history with branching
/// - Temporal queries ("What did I know on [date]?")
/// - Animated transitions showing graph growth
pub const TemporalGraph = struct {
    allocator: std.mem.Allocator,
    dag_integration: *EditorDagIntegration,
    current_timestamp: ?u64, // Current time-travel timestamp (null =
present)
    
    // Bounded: Max 1,000 temporal snapshots
    pub const MAX_TEMPORAL_SNAPSHOTS: u32 = 1_000;
    
    /// Initialize temporal graph.
    pub fn init(
        allocator: std.mem.Allocator,
        dag_integration: *EditorDagIntegration,
    ) TemporalGraph {
        // Assert: Allocator must be valid
        std.debug.assert(allocator.ptr != null);
        
        // Assert: DAG integration must be valid
        std.debug.assert(dag_integration.buffer_node_id != null);
        
        return TemporalGraph{
            .allocator = allocator,
            .dag_integration = dag_integration,
            .current_timestamp = null, // Start at present
        };
    }
    
    /// Get time range for time slider (earliest to latest).
    pub fn get_time_range(self: *const TemporalGraph) struct { earliest:
?u64, latest: ?u64 } {
        const earliest = self.dag_integration.get_earliest_timestamp();
        const latest = self.dag_integration.get_latest_timestamp();
        
        return .{
            .earliest = earliest,
            .latest = latest,
        };
    }
    
    /// Set current time-travel timestamp (null = present).
    pub fn set_timestamp(self: *TemporalGraph, timestamp: ?u64) void {
        // Assert: If timestamp is set, it must be within valid range
        if (timestamp) |ts| {
            const latest = self.dag_integration.get_latest_timestamp();
            if (latest) |l| {
                std.debug.assert(ts <= l);
            }
        }
        
        self.current_timestamp = timestamp;
    }
    
    /// Get current time-travel timestamp (null = present).
    pub fn get_timestamp(self: *const TemporalGraph) ?u64 {
        return self.current_timestamp;
    }
    
    /// Query events up to current timestamp (time-travel query).
    pub fn query_events_at_current_time(self: *const TemporalGraph)
[]const EditorDagIntegration.ProcessedEvent {
        if (self.current_timestamp) |ts| {
            return self.dag_integration.query_events_up_to_timestamp(ts);
        } else {
            // Present: return all events
            return self.dag_integration.get_processed_events();
        }
    }
    
    /// Query events in a date range (temporal query).
    /// start_date and end_date are Unix timestamps.
    pub fn query_events_by_date_range(
        self: *const TemporalGraph,
        start_date: u64,
        end_date: u64,
    ) u32 {
        // Assert: Date range must be valid
        std.debug.assert(start_date <= end_date);
        
        return
self.dag_integration.count_events_by_time_range(start_date, end_date);
    }
    
    /// Get events for a specific date (Unix timestamp).
    pub fn get_events_for_date(self: *const TemporalGraph,
date_timestamp: u64) []const EditorDagIntegration.ProcessedEvent {
        // Get start and end of day (24 hours)
        const start_of_day = date_timestamp;
        const end_of_day = date_timestamp + (24 * 60 * 60); // 24 hours
in seconds
        
        // Query events in day range
        const all_events = self.dag_integration.get_processed_events();
        var matching_count: u32 = 0;
        var i: u32 = 0;
        while (i < all_events.len) : (i += 1) {
            const event = all_events[i];
            if (event.timestamp >= start_of_day and event.timestamp <=
end_of_day) {
                matching_count += 1;
            }
        }
        
        // Return matching events (caller should filter from all_events)
        _ = matching_count;
        return all_events;
    }
    
    /// Check if time-travel mode is active (timestamp set).
    pub fn is_time_travel_mode(self: *const TemporalGraph) bool {
        return self.current_timestamp != null;
    }
    
    /// Reset to present (exit time-travel mode).
    pub fn reset_to_present(self: *TemporalGraph) void {
        self.current_timestamp = null;
    }
};

test "temporal graph initialization" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag_integration = try
EditorDagIntegration.init(arena.allocator());
    defer dag_integration.deinit();
    
    const content = "line1\nline2\nline3";
    _ = try dag_integration.create_buffer_node(content);
    
    var temporal = TemporalGraph.init(arena.allocator(),
&dag_integration);
    
    // Assert: Temporal graph initialized
    try std.testing.expect(temporal.current_timestamp == null);
    try std.testing.expect(!temporal.is_time_travel_mode());
}

test "temporal graph time range" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag_integration = try
EditorDagIntegration.init(arena.allocator());
    defer dag_integration.deinit();
    
    const content = "line1\nline2\nline3";
    _ = try dag_integration.create_buffer_node(content);
    
    // Create and process events
    _ = try dag_integration.map_operation_to_event(.insert, 1, 5, "",
"new1");
    _ = try dag_integration.map_operation_to_event(.insert, 1, 9, "",
"new2");
    try dag_integration.process_events();
    
    var temporal = TemporalGraph.init(arena.allocator(),
&dag_integration);
    
    // Get time range
    const range = temporal.get_time_range();
    
    // Assert: Time range is valid
    try std.testing.expect(range.earliest != null);
    try std.testing.expect(range.latest != null);
    try std.testing.expect(range.latest.? >= range.earliest.?);
}

test "temporal graph time travel" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag_integration = try
EditorDagIntegration.init(arena.allocator());
    defer dag_integration.deinit();
    
    const content = "line1\nline2\nline3";
    _ = try dag_integration.create_buffer_node(content);
    
    // Create and process events
    _ = try dag_integration.map_operation_to_event(.insert, 1, 5, "",
"new1");
    _ = try dag_integration.map_operation_to_event(.insert, 1, 9, "",
"new2");
    try dag_integration.process_events();
    
    var temporal = TemporalGraph.init(arena.allocator(),
&dag_integration);
    
    // Get latest timestamp
    const latest = dag_integration.get_latest_timestamp();
    try std.testing.expect(latest != null);
    
    // Set timestamp to latest (time-travel)
    temporal.set_timestamp(latest);
    
    // Assert: Time-travel mode active
    try std.testing.expect(temporal.is_time_travel_mode());
    try std.testing.expect(temporal.get_timestamp() == latest);
    
    // Query events at current time
    const events = temporal.query_events_at_current_time();
    try std.testing.expect(events.len > 0);
    
    // Reset to present
    temporal.reset_to_present();
    try std.testing.expect(!temporal.is_time_travel_mode());
}


// === grain_skate/window.zig ===

const std = @import("std");
const MacWindow = @import("macos_window");
const Editor = @import("editor.zig").Editor;
const Block = @import("block.zig").Block;
const GraphVisualization = @import("graph_viz.zig").GraphVisualization;
const GraphRenderer = @import("graph_renderer.zig").GraphRenderer;
const EditorRenderer = @import("editor_renderer.zig").EditorRenderer;
const events = @import("platform/events.zig");

/// Grain Skate Window: Native macOS window management for knowledge
graph application.
/// ~<~ Glow Airbend: explicit window state, bounded UI buffers.
/// ~~~~ Glow Waterbend: deterministic rendering, iterative UI updates.
///
/// 2025-11-23-170000-pst: Active implementation
pub const SkateWindow = struct {
    // Bounded: Max window title length (explicit limit)
    // 2025-11-23-170000-pst: Active constant
    pub const MAX_TITLE_LEN: u32 = 256;

    // Bounded: Max window width (explicit limit, in pixels)
    // 2025-11-23-170000-pst: Active constant
    pub const MAX_WIDTH: u32 = 4096;

    // Bounded: Max window height (explicit limit, in pixels)
    // 2025-11-23-170000-pst: Active constant
    pub const MAX_HEIGHT: u32 = 4096;

    /// Window state.
    // 2025-11-23-170000-pst: Active struct
    window: *MacWindow.Window,
    editor: ?*Editor.EditorState,
    current_block_id: ?u32,
    graph_renderer: ?*GraphRenderer,
    editor_renderer: ?*EditorRenderer,
    allocator: std.mem.Allocator,
    split_pane_enabled: bool, // Whether split pane mode is enabled
    split_position: u32, // Split position in pixels (0 = left edge,
width = right edge)

    /// Initialize Grain Skate window.
    // 2025-11-23-170000-pst: Active function
    pub fn init(allocator: std.mem.Allocator, title: []const u8, width:
u32, height: u32) !SkateWindow {
        // Assert: Title must be bounded
        std.debug.assert(title.len <= MAX_TITLE_LEN);
        std.debug.assert(width > 0 and width <= MAX_WIDTH);
        std.debug.assert(height > 0 and height <= MAX_HEIGHT);

        // Create macOS window
        const window = try allocator.create(MacWindow.Window);
        window.* = MacWindow.Window.init(allocator, title);
        window.width = width;
        window.height = height;

        return SkateWindow{
            .window = window,
            .editor = null,
            .current_block_id = null,
            .graph_renderer = null,
            .editor_renderer = null,
            .allocator = allocator,
            .split_pane_enabled = false,
            .split_position = width / 2, // Default: 50/50 split
        };
    }

    /// Deinitialize Grain Skate window.
    // 2025-11-23-170000-pst: Active function
    pub fn deinit(self: *SkateWindow) void {
        // Clean up graph renderer if present
        if (self.graph_renderer) |renderer| {
            self.allocator.destroy(renderer);
        }
        // Clean up editor renderer if present
        if (self.editor_renderer) |renderer| {
            self.allocator.destroy(renderer);
        }
        // Clean up editor if present
        if (self.editor) |editor| {
            editor.deinit();
            self.allocator.destroy(editor);
        }

        // Clean up window
        self.window.deinit();
        self.allocator.destroy(self.window);

        self.* = undefined;
    }

    /// Show window.
    // 2025-11-23-170000-pst: Active function
    pub fn show(self: *SkateWindow) void {
        self.window.show();
    }

    /// Set current block for editing.
    // 2025-11-23-170000-pst: Active function
    pub fn set_current_block(self: *SkateWindow, block:
*Block.BlockData) !void {
        // Assert: Block must be valid
        std.debug.assert(block.id > 0);

        // Create or update editor with block content
        if (self.editor) |editor| {
            // Update existing editor: deinit old and create new with
block content
            editor.deinit();
            self.allocator.destroy(editor);
            self.editor = null;
        }
        // Create new editor with block content
        const editor = try self.allocator.create(Editor.EditorState);
        errdefer self.allocator.destroy(editor);
        editor.* = try Editor.EditorState.init(self.allocator,
block.content);
        self.editor = editor;

        // Create or update editor renderer
        if (self.editor_renderer) |renderer| {
            self.allocator.destroy(renderer);
            self.editor_renderer = null;
        }
        const editor_renderer = try
self.allocator.create(EditorRenderer);
        editor_renderer.* = EditorRenderer.init(editor,
self.window.width, self.window.height);
        // Set block title for status line display
        if (block.title_len > 0) {
           
editor_renderer.set_block_title(block.title[0..block.title_len]);
            // Detect language from block title (as filename) and content
            const block_content = if (block.content_len > 0)
block.content[0..block.content_len] else "";
           
editor_renderer.detect_language(block.title[0..block.title_len],
block_content);
        }
        self.editor_renderer = editor_renderer;

        self.current_block_id = block.id;
    }

    /// Close editor and return to graph view.
    // 2025-12-02-160942-pst: Active function
    pub fn close_editor(self: *SkateWindow) void {
        // Clean up editor renderer
        if (self.editor_renderer) |renderer| {
            self.allocator.destroy(renderer);
            self.editor_renderer = null;
        }
        // Clean up editor
        if (self.editor) |editor| {
            editor.deinit();
            self.allocator.destroy(editor);
            self.editor = null;
        }
        // Clear current block ID
        self.current_block_id = null;
    }

    /// Get current block ID.
    // 2025-11-23-170000-pst: Active function
    pub fn get_current_block_id(self: *const SkateWindow) ?u32 {
        return self.current_block_id;
    }

    /// Get editor state.
    // 2025-11-23-170000-pst: Active function
    pub fn get_editor(self: *const SkateWindow) ?*Editor.EditorState {
        return self.editor;
    }

    /// Get editor renderer.
    // 2025-12-02-164404-pst: Active function
    pub fn get_editor_renderer(self: *SkateWindow) ?*EditorRenderer {
        return self.editor_renderer;
    }

    /// Set graph visualization for rendering.
    // 2025-11-24-163500-pst: Active function
    pub fn set_graph_viz(self: *SkateWindow, graph_viz:
*GraphVisualization) !void {
        std.debug.assert(graph_viz.zoom > 0.0);
        // Clean up existing renderer if present
        if (self.graph_renderer) |renderer| {
            self.allocator.destroy(renderer);
            self.graph_renderer = null;
        }
        // Create new renderer with current window dimensions
        const buffer_width = self.window.width;
        const buffer_height = self.window.height;
        const renderer = try self.allocator.create(GraphRenderer);
        renderer.* = GraphRenderer.init(graph_viz, buffer_width,
buffer_height);
        self.graph_renderer = renderer;
    }

    /// Handle window resize event (update renderer and layout).
    // 2025-11-24-181000-pst: Active function
    pub fn handle_resize(self: *SkateWindow, new_width: u32, new_height:
u32) !void {
        std.debug.assert(new_width > 0 and new_width <= MAX_WIDTH);
        std.debug.assert(new_height > 0 and new_height <= MAX_HEIGHT);

        // Update window dimensions
        self.window.width = new_width;
        self.window.height = new_height;

        // Update graph renderer if present
        if (self.graph_renderer) |renderer| {
            // Recreate renderer with new dimensions
            const graph_viz = renderer.graph_viz;
            const block_storage = if (renderer.block_storage) |bs| bs
else null;
            self.allocator.destroy(renderer);
            const new_renderer = try
self.allocator.create(GraphRenderer);
            new_renderer.* = GraphRenderer.init(graph_viz, new_width,
new_height);
            if (block_storage) |bs| {
                new_renderer.set_block_storage(bs);
            }
            self.graph_renderer = new_renderer;
        }
        // Update editor renderer if present
        if (self.editor_renderer) |renderer| {
            const editor = renderer.editor;
            self.allocator.destroy(renderer);
            const new_renderer = try
self.allocator.create(EditorRenderer);
            new_renderer.* = EditorRenderer.init(editor, new_width,
new_height);
            self.editor_renderer = new_renderer;
        }
    }

    /// Set block storage for title rendering.
    // 2025-11-24-171200-pst: Active function
    pub fn set_block_storage(self: *SkateWindow, block_storage:
*Block.BlockStorage) void {
        if (self.graph_renderer) |renderer| {
            renderer.set_block_storage(block_storage);
        }
    }

    /// Render graph to window buffer.
    // 2025-11-24-163500-pst: Active function
    pub fn render_graph(self: *SkateWindow) void {
        if (self.graph_renderer) |renderer| {
            const buffer = self.window.getBuffer();
            renderer.render(buffer);
        }
    }

    /// Render graph to sub-rectangle of buffer (for split pane).
    // 2025-12-02-173853-pst: Active function
    fn render_graph_to_rect(self: *SkateWindow, buffer: []u8, x: u32, y:
u32, width: u32, height: u32) void {
        if (self.graph_renderer) |renderer| {
            // Create temporary renderer with pane dimensions
            const graph_viz = renderer.graph_viz;
            const block_storage = if (renderer.block_storage) |bs| bs
else null;
            var temp_renderer = GraphRenderer.init(graph_viz, width,
height);
            if (block_storage) |bs| {
                temp_renderer.set_block_storage(bs);
            }
            // Render to temporary buffer (use sub-rectangle of main
buffer)
            const temp_buffer = buffer[(y * self.window.width + x) *
4..][0..(width * height * 4)];
            temp_renderer.render(temp_buffer);
        }
    }

    /// Render editor to window buffer.
    // 2025-12-02-142853-pst: Active function
    pub fn render_editor(self: *SkateWindow, command_buffer: []const u8)
void {
        if (self.editor_renderer) |renderer| {
            // Set command buffer for command mode display
            renderer.set_command_buffer(command_buffer);
            const buffer = self.window.getBuffer();
            renderer.render(buffer);
        }
    }

    /// Render editor to sub-rectangle of buffer (for split pane).
    // 2025-12-02-173853-pst: Active function
    fn render_editor_to_rect(self: *SkateWindow, buffer: []u8,
command_buffer: []const u8, x: u32, y: u32, width: u32, height: u32)
void {
        if (self.editor_renderer) |renderer| {
            // Create temporary renderer with pane dimensions
            const editor = renderer.editor;
            var temp_renderer = EditorRenderer.init(editor, width,
height);
            // Copy state from original renderer
            temp_renderer.set_command_buffer(command_buffer);
            if (renderer.block_title.len > 0) {
                temp_renderer.set_block_title(renderer.block_title);
            }
            temp_renderer.set_modified(renderer.modified);
            // Render to temporary buffer (use sub-rectangle of main
buffer)
            const temp_buffer = buffer[(y * self.window.width + x) *
4..][0..(width * height * 4)];
            temp_renderer.render(temp_buffer);
        }
    }

    /// Copy rectangle from source buffer to destination buffer.
    // 2025-12-02-173853-pst: Active function
    fn copy_buffer_rect(self: *SkateWindow, src_buffer: []u8,
dst_buffer: []u8, src_x: u32, src_y: u32, src_width: u32, src_height:
u32, dst_x: u32, dst_y: u32, dst_width: u32, dst_height: u32) void {
        const window_width = self.window.width;
        const window_height = self.window.height;
        // Calculate copy dimensions (min of source and destination)
        const copy_width = @min(@min(src_width - src_x, dst_width -
dst_x), window_width - dst_x);
        const copy_height = @min(@min(src_height - src_y, dst_height -
dst_y), window_height - dst_y);
        // Copy pixel rows
        var row: u32 = 0;
        while (row < copy_height) : (row += 1) {
            const src_row_start = ((src_y + row) * src_width + src_x) *
4;
            const dst_row_start = ((dst_y + row) * window_width + dst_x)
* 4;
            const row_size = copy_width * 4;
            @memcpy(dst_buffer[dst_row_start..][0..row_size],
src_buffer[src_row_start..][0..row_size]);
        }
    }

    /// Present window (render graph/editor and display).
    // 2025-11-24-163500-pst: Active function
    pub fn present(self: *SkateWindow) !void {
        const buffer = self.window.getBuffer();
        // Clear buffer with background color
        const bg_color: u32 = 0xFF1E1E1E; // Dark gray
        const bg_r = @as(u8, @truncate((bg_color >> 16) & 0xFF));
        const bg_g = @as(u8, @truncate((bg_color >> 8) & 0xFF));
        const bg_b = @as(u8, @truncate(bg_color & 0xFF));
        const bg_a = @as(u8, @truncate((bg_color >> 24) & 0xFF));
        const buffer_size = self.window.width * self.window.height * 4;
        var i: u32 = 0;
        while (i < buffer_size) : (i += 4) {
            buffer[i + 0] = bg_r;
            buffer[i + 1] = bg_g;
            buffer[i + 2] = bg_b;
            buffer[i + 3] = bg_a;
        }
        // Render based on split pane mode
        if (self.split_pane_enabled and self.graph_renderer != null and
self.editor_renderer != null) {
            // Split pane mode: render both views side-by-side
            const split_x = @min(self.split_position, self.window.width
- 1);
            const graph_width = split_x;
            const editor_x = split_x + 1; // +1 for divider
            const editor_width = self.window.width - editor_x;
            const height = self.window.height;
            // Render graph to left pane
            if (graph_width > 0) {
                self.render_graph_to_rect(buffer, 0, 0, graph_width,
height);
            }
            // Render divider line
            if (split_x < self.window.width) {
                var y: u32 = 0;
                const divider_color: u32 = 0xFF666666; // Gray divider
                const div_r = @as(u8, @truncate((divider_color >> 16) &
0xFF));
                const div_g = @as(u8, @truncate((divider_color >> 8) &
0xFF));
                const div_b = @as(u8, @truncate(divider_color & 0xFF));
                const div_a = @as(u8, @truncate((divider_color >> 24) &
0xFF));
                while (y < height) : (y += 1) {
                    const idx = (y * self.window.width + split_x) * 4;
                    buffer[idx + 0] = div_r;
                    buffer[idx + 1] = div_g;
                    buffer[idx + 2] = div_b;
                    buffer[idx + 3] = div_a;
                }
            }
            // Render editor to right pane
            if (editor_width > 0) {
                self.render_editor_to_rect(buffer, "", editor_x, 0,
editor_width, height);
            }
        } else {
            // Single pane mode: render editor if present (editor takes
priority over graph)
            if (self.editor_renderer != null) {
                self.render_editor(""); // Empty command buffer for
normal rendering
            } else {
                // Render graph if renderer is set
                self.render_graph();
            }
        }
        // Present window buffer
        try self.window.present();
    }

    /// Handle mouse click event (find node at click position).
    // 2025-11-24-172500-pst: Active function
    pub fn handle_mouse_click(self: *SkateWindow, x: f64, y: f64) ?u32 {
        if (self.graph_renderer == null) {
            return null;
        }

        const graph_viz = self.graph_renderer.?.graph_viz;
        const buffer_width = self.graph_renderer.?.buffer_width;
        const buffer_height = self.graph_renderer.?.buffer_height;

        // Convert window coordinates to buffer coordinates
        // Window coordinates: 0,0 is bottom-left (macOS convention)
        // Buffer coordinates: 0,0 is top-left
        const buffer_x = @as(u32, @intFromFloat(x));
        const buffer_y = @as(u32, @intFromFloat(@as(f64,
@floatFromInt(buffer_height)) - y));

        // Bounds check
        if (buffer_x >= buffer_width or buffer_y >= buffer_height) {
            return null;
        }

        // Find node at click position
        return graph_viz.find_node_at_pixel(buffer_x, buffer_y,
buffer_width, buffer_height);
    }

    /// Handle keyboard event (route to modal editor if editor is
active).
    // 2025-12-02-151416-pst: Active function
    pub fn handle_keyboard_event(self: *SkateWindow, event:
events.KeyboardEvent) bool {
        // Don't intercept Ctrl+Alt (for OS window management)
        if (event.modifiers.control and event.modifiers.option) {
            return false; // Let OS handle it
        }
        // Only handle key down events
        if (event.kind != .down) {
            return false;
        }
        // If editor is active, we'll handle it (but need modal editor)
        // For now, return false to indicate we didn't handle it
        // The app will route it to modal editor
        return false;
    }

    /// Enable or disable split pane mode.
    // 2025-12-02-173853-pst: Active function
    pub fn set_split_pane(self: *SkateWindow, enabled: bool) void {
        self.split_pane_enabled = enabled;
        // Update default split position if enabling
        if (enabled) {
            self.split_position = self.window.width / 2;
        }
    }

    /// Set split position (in pixels from left edge).
    // 2025-12-02-173853-pst: Active function
    pub fn set_split_position(self: *SkateWindow, position: u32) void {
        // Clamp split position to valid range (leave at least 100px for
each pane)
        const min_pos: u32 = 100;
        const max_pos = if (self.window.width > 200) self.window.width -
100 else self.window.width;
        self.split_position = std.math.clamp(position, min_pos, max_pos);
    }

    /// Get split pane enabled state.
    // 2025-12-02-173853-pst: Active function
    pub fn is_split_pane_enabled(self: *const SkateWindow) bool {
        return self.split_pane_enabled;
    }
};


// === grain_skate_main.zig ===

//! Grain Skate Main Entry Point: Native macOS knowledge graph
application.
//!
//! Why: Main entry point for Grain Skate application.
//! Architecture: Application initialization, event loop, window
management.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.

const std = @import("std");
const grain_skate = @import("grain_skate");
const Block = grain_skate.Block;
const SkateWindow = grain_skate.SkateWindow;
const GrainSkateApp = grain_skate.GrainSkateApp;
const events = @import("platform/events.zig");

/// Main entry point for Grain Skate application.
pub fn main() void {
    // Wrap in error handler to catch panics.
    mainImpl() catch |err| {
        const err_msg = switch (err) {
            error.OutOfMemory => "Out of memory",
            else => @errorName(err),
        };
        std.debug.print("Error: {s}\n", .{err_msg});
        std.process.exit(1);
    };
}

fn mainImpl() !void {
    std.debug.print("[grain_skate] Starting Grain Skate
application...\n", .{});

    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    std.debug.print("[grain_skate] Allocator initialized.\n", .{});

    // Initialize block storage.
    std.debug.print("[grain_skate] Initializing block storage...\n",
.{});
    var block_storage = Block.BlockStorage.init(allocator);
    defer block_storage.deinit();

    // Create initial block for testing.
    _ = try block_storage.create_block("Welcome", "Welcome to Grain
Skate!\n\nThis is a knowledge graph application.\n\nPress 'i' to enter
insert mode.\nPress 'Esc' to return to normal mode.\n\nClick on graph
nodes to open blocks for editing.");

    // Initialize window.
    std.debug.print("[grain_skate] Initializing window...\n", .{});
    var window = try SkateWindow.init(allocator, "Grain Skate", 1200,
800);
    defer window.deinit();

    // Initialize application.
    std.debug.print("[grain_skate] Initializing application...\n", .{});
    var app = try GrainSkateApp.init(allocator, &block_storage, &window);
    defer app.deinit();

    // Load blocks into graph visualization.
    std.debug.print("[grain_skate] Loading blocks into graph...\n", .{});
    app.load_blocks_to_graph();

    // Show window.
    std.debug.print("[grain_skate] Showing window...\n", .{});
    try window.window.show();

    // Render initial graph view.
    std.debug.print("[grain_skate] Rendering initial graph view...\n",
.{});
    window.render_graph();
    try window.window.present();

    std.debug.print("[grain_skate] Window ready. Running event
loop...\n", .{});
    std.debug.print("[grain_skate] To quit: Close window, press Cmd+Q,
or Ctrl+C in terminal\n", .{});

    // Run event loop: blocks until app terminates.
    // This is normal macOS GUI app behavior - the event loop must run
to process
    // window events, keyboard input, etc. It will block until the user
quits.
    window.window.runEventLoop();

    std.debug.print("[grain_skate] Event loop exited (application
terminated).\n", .{});
}


// === grain_store.zig ===

const std = @import("std");
const foundations = @import("grain-foundations");

const GrainDevName = foundations.GrainDevName;

pub const ManifestEntry = struct {
    platform: []const u8,
    org: []const u8,
    repo: []const u8,
};

pub const GrainStore = struct {
    allocator: std.mem.Allocator,
    devname: GrainDevName,
    base_dir: []const u8,

    pub fn init(
        allocator: std.mem.Allocator,
        dev_input: []const u8,
    ) !GrainStore {
        const name = try foundations.graindevname.normalize(
            allocator,
            dev_input,
        );

        return .{
            .allocator = allocator,
            .devname = name,
            .base_dir = "grainstore",
        };
    }

    pub fn deinit(self: *GrainStore) void {
        self.allocator.free(self.devname.name);
    }

    pub fn ensure_platforms(
        self: GrainStore,
        platforms: []const []const u8,
    ) !void {
        const cwd = std.fs.cwd();
        try cwd.makePath(self.base_dir);

        for (platforms) |platform| {
            const path = try std.fmt.allocPrint(
                self.allocator,
                "{s}/{s}",
                .{ self.base_dir, platform },
            );
            defer self.allocator.free(path);
            try cwd.makePath(path);
        }
    }

    pub fn repo_path(
        self: GrainStore,
        platform: []const u8,
        org: []const u8,
        repo: []const u8,
    ) ![]u8 {
        return std.fmt.allocPrint(
            self.allocator,
            "{s}/{s}/{s}/{s}",
            .{ self.base_dir, platform, org, repo },
        );
    }

    pub fn sync_manifest_entries(
        self: GrainStore,
        entries: []const ManifestEntry,
    ) !void {
        const cwd = std.fs.cwd();
        for (entries) |entry| {
            const dir = try self.repo_path(
                entry.platform,
                entry.org,
                entry.repo,
            );
            defer self.allocator.free(dir);
            try cwd.makePath(dir);
        }
    }
};

test "grainstore sync manifest entries" {
    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const allocator = std.testing.allocator;

    const original = try std.fs.cwd().realpathAlloc(allocator, ".");
    defer allocator.free(original);
    defer std.os.chdir(original) catch {};
    try std.os.chdir(tmp.dir.path.?);

    var store = try GrainStore.init(allocator, "@test");
    defer store.deinit();

    const base_dir = try allocator.dupe(u8, "grainstore");
    defer allocator.free(base_dir);
    store.base_dir = base_dir;

    const platforms = [_][]const u8{ "codeberg", "github", "gitab" };
    try store.ensure_platforms(&platforms);

    const manifest_entries = @import("grain_manifest.zig").entries;
    try store.sync_manifest_entries(manifest_entries[0..]);

    for (manifest_entries) |entry| {
        const path = try std.fmt.allocPrint(
            allocator,
            "grainstore/{s}/{s}/{s}",
            .{ entry.platform, entry.org, entry.repo },
        );
        defer allocator.free(path);
        try tmp.dir.access(path, .{});
    }
}

// === grain_terminal/aurora_renderer.zig ===

const std = @import("std");
const Terminal = @import("terminal.zig").Terminal;
const Tab = @import("tab.zig").Tab;
const Pane = @import("pane.zig").Pane;
const Config = @import("config.zig").Config;

// Note: GrainAurora import will be resolved via build.zig module
dependencies
// For now, we'll use a forward declaration approach
pub const GrainAurora = struct {
    pub const Node = union(enum) {
        text: []const u8,
        column: Column,
        row: Row,
        button: Button,
    };
    
    pub const Column = struct {
        children: []const Node,
    };
    
    pub const Row = struct {
        children: []const Node,
    };
    
    pub const Button = struct {
        id: []const u8,
        label: []const u8,
    };
    
    pub const RenderResult = struct {
        root: Node,
        readonly_spans: []const Span,
    };
    
    pub const Span = struct {
        start: usize,
        end: usize,
    };
};

/// Grain Terminal Aurora Renderer: Converts terminal cells to Aurora
components.
/// ~<~ Glow Airbend: explicit rendering state, bounded components.
/// ~~~~ Glow Waterbend: deterministic rendering, iterative algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const AuroraRenderer = struct {
    // Bounded: Max terminal cells per render (explicit limit)
    pub const MAX_CELLS_PER_RENDER: u32 = 10_000;
    
    // Bounded: Max lines per terminal view (explicit limit)
    pub const MAX_LINES: u32 = 1_000;
    
    // Bounded: Max columns per terminal view (explicit limit)
    pub const MAX_COLUMNS: u32 = 500;
    
    allocator: std.mem.Allocator,
    
    /// Initialize Aurora renderer.
    pub fn init(allocator: std.mem.Allocator) AuroraRenderer {
        // Assert: Allocator must be valid
        std.debug.assert(allocator.ptr != null);
        
        return AuroraRenderer{
            .allocator = allocator,
        };
    }
    
    /// Render terminal tab to Aurora component.
    /// Contract:
    ///   Input: tab, config, width, height
    ///   Output: Aurora RenderResult with terminal content as text nodes
    ///   Errors: Allocation errors
    pub fn render_tab(
        self: *AuroraRenderer,
        tab: *Tab,
        config: *const Config,
        width: u32,
        height: u32,
    ) !GrainAurora.RenderResult {
        // Assert: Tab must be valid
        std.debug.assert(@intFromPtr(tab) != 0);
        std.debug.assert(@intFromPtr(config) != 0);
        
        // Assert: Dimensions must be valid
        std.debug.assert(width > 0 and width <= MAX_COLUMNS);
        std.debug.assert(height > 0 and height <= MAX_LINES);
        
        // Assert: Terminal dimensions must match
        std.debug.assert(tab.terminal.width == width);
        std.debug.assert(tab.terminal.height == height);
        
        // Get terminal cells
        const cells = tab.cells;
        std.debug.assert(cells.len >= width * height);
        
        // Build text lines (iterative, no recursion)
        var lines = try std.ArrayList([]const
u8).initCapacity(self.allocator, height);
        defer {
            for (lines.items) |line| {
                self.allocator.free(line);
            }
            lines.deinit();
        }
        
        var y: u32 = 0;
        while (y < height) : (y += 1) {
            // Build line text
            var line_buf = try
std.ArrayList(u8).initCapacity(self.allocator, width);
            defer line_buf.deinit();
            
            var x: u32 = 0;
            while (x < width) : (x += 1) {
                const cell_idx = y * width + x;
                std.debug.assert(cell_idx < cells.len);
                
                const cell = cells[cell_idx];
                try line_buf.append(cell.ch);
            }
            
            const line = try line_buf.toOwnedSlice();
            try lines.append(line);
        }
        
        // Convert lines to Aurora text nodes
        var text_nodes = try self.allocator.alloc(GrainAurora.Node,
lines.items.len);
        errdefer self.allocator.free(text_nodes);
        
        for (lines.items, 0..) |line, i| {
            text_nodes[i] = GrainAurora.Node{
                .text = line,
            };
        }
        
        // Create column component with text nodes
        const column = GrainAurora.Column{
            .children = text_nodes,
        };
        
        const root = GrainAurora.Node{
            .column = column,
        };
        
        // Create readonly spans for tab title (first line)
        const readonly_spans = if (lines.items.len > 0) blk: {
            const title_span = try
self.allocator.alloc(GrainAurora.Span, 1);
            title_span[0] = GrainAurora.Span{
                .start = 0,
                .end = lines.items[0].len,
            };
            break :blk title_span;
        } else &.{};
        
        return GrainAurora.RenderResult{
            .root = root,
            .readonly_spans = readonly_spans,
        };
    }
    
    /// Render pane with tabs to Aurora component.
    /// Contract:
    ///   Input: pane, config
    ///   Output: Aurora RenderResult with pane layout
    ///   Errors: Allocation errors
    pub fn render_pane(
        self: *AuroraRenderer,
        pane: *Pane,
        config: *const Config,
    ) !GrainAurora.RenderResult {
        // Assert: Pane must be valid
        std.debug.assert(@intFromPtr(pane) != 0);
        std.debug.assert(@intFromPtr(config) != 0);
        
        // If leaf pane with tab, render tab
        if (pane.is_leaf()) {
            if (pane.tab) |tab| {
                return try self.render_tab(tab, config, pane.width,
pane.height);
            } else {
                // Empty pane: return empty column
                const empty_text = try self.allocator.dupe(u8, "");
                errdefer self.allocator.free(empty_text);
                
                const text_node = GrainAurora.Node{
                    .text = empty_text,
                };
                
                const column = GrainAurora.Column{
                    .children = &.{text_node},
                };
                
                return GrainAurora.RenderResult{
                    .root = .{ .column = column },
                    .readonly_spans = &.{},
                };
            }
        }
        
        // Split pane: render children (iterative, no recursion)
        var child_results = try
std.ArrayList(GrainAurora.RenderResult).initCapacity(
            self.allocator,
            pane.children_len,
        );
        defer {
            for (child_results.items) |*result| {
                // Free readonly spans
                self.allocator.free(result.readonly_spans);
            }
            child_results.deinit();
        }
        
        var i: u32 = 0;
        while (i < pane.children_len) : (i += 1) {
            const child_result = try self.render_pane(&pane.children[i],
config);
            try child_results.append(child_result);
        }
        
        // Convert child results to nodes
        var child_nodes = try self.allocator.alloc(GrainAurora.Node,
child_results.items.len);
        errdefer self.allocator.free(child_nodes);
        
        for (child_results.items, 0..) |*result, j| {
            child_nodes[j] = result.root;
        }
        
        // Create row or column based on split direction
        const root = if (pane.split_direction == .horizontal) blk: {
            const row = GrainAurora.Row{
                .children = child_nodes,
            };
            break :blk GrainAurora.Node{ .row = row };
        } else blk: {
            const column = GrainAurora.Column{
                .children = child_nodes,
            };
            break :blk GrainAurora.Node{ .column = column };
        };
        
        // Combine readonly spans from children
        var total_spans: u32 = 0;
        for (child_results.items) |result| {
            total_spans += @as(u32, @intCast(result.readonly_spans.len));
        }
        
        const readonly_spans = try
self.allocator.alloc(GrainAurora.Span, total_spans);
        errdefer self.allocator.free(readonly_spans);
        
        var span_idx: u32 = 0;
        for (child_results.items) |result| {
            for (result.readonly_spans) |span| {
                readonly_spans[span_idx] = span;
                span_idx += 1;
            }
        }
        
        return GrainAurora.RenderResult{
            .root = root,
            .readonly_spans = readonly_spans,
        };
    }
    
    /// Render tab bar to Aurora component.
    /// Contract:
    ///   Input: tabs array, active_tab_id, config
    ///   Output: Aurora RenderResult with tab bar as row of buttons
    ///   Errors: Allocation errors
    pub fn render_tab_bar(
        self: *AuroraRenderer,
        tabs: []const *Tab,
        _: u32, // active_tab_id (unused for now)
        config: *const Config,
    ) !GrainAurora.RenderResult {
        // Assert: Config must be valid
        std.debug.assert(@intFromPtr(config) != 0);
        
        // Assert: Tabs array must be bounded
        std.debug.assert(tabs.len <= Tab.MAX_TITLE_LEN); // Reuse
constant for max tabs
        
        // If tabs not shown, return empty
        if (!config.show_tabs) {
            const empty_text = try self.allocator.dupe(u8, "");
            errdefer self.allocator.free(empty_text);
            
            const text_node = GrainAurora.Node{
                .text = empty_text,
            };
            
            const row = GrainAurora.Row{
                .children = &.{text_node},
            };
            
            return GrainAurora.RenderResult{
                .root = .{ .row = row },
                .readonly_spans = &.{},
            };
        }
        
        // Create button nodes for each tab
        var button_nodes = try self.allocator.alloc(GrainAurora.Node,
tabs.len);
        errdefer self.allocator.free(button_nodes);
        
        for (tabs, 0..) |tab, i| {
            // Create tab ID string
            const tab_id_buf = try std.fmt.allocPrint(self.allocator,
"tab_{d}", .{tab.id});
            errdefer self.allocator.free(tab_id_buf);
            
            // Use tab title or default
            const label = if (tab.title_len > 0) tab.title else
"Terminal";
            
            const button = GrainAurora.Button{
                .id = tab_id_buf,
                .label = label,
            };
            
            button_nodes[i] = GrainAurora.Node{
                .button = button,
            };
        }
        
        // Create row component with tab buttons
        const row = GrainAurora.Row{
            .children = button_nodes,
        };
        
        return GrainAurora.RenderResult{
            .root = .{ .row = row },
            .readonly_spans = &.{},
        };
    }
};


// === grain_terminal/config.zig ===

const std = @import("std");

/// Grain Terminal Configuration: Theme, font, and settings management.
/// ~<~ Glow Airbend: explicit configuration state, bounded settings.
/// ~~~~ Glow Waterbend: deterministic configuration, iterative
algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const Config = struct {
    // Bounded: Max configuration key length (explicit limit)
    pub const MAX_KEY_LEN: u32 = 256;

    // Bounded: Max configuration value length (explicit limit)
    pub const MAX_VALUE_LEN: u32 = 4_096;

    // Bounded: Max configuration entries (explicit limit)
    pub const MAX_CONFIG_ENTRIES: u32 = 1_024;

    /// Theme enumeration.
    pub const Theme = enum(u8) {
        dark, // Dark theme (default)
        light, // Light theme
        solarized_dark, // Solarized dark
        solarized_light, // Solarized light
        gruvbox_dark, // Gruvbox dark
        gruvbox_light, // Gruvbox light
    };

    /// Font size enumeration.
    pub const FontSize = enum(u8) {
        small, // 8pt
        medium, // 12pt (default)
        large, // 16pt
        xlarge, // 20pt
    };

    /// Configuration entry (key-value pair).
    pub const ConfigEntry = struct {
        key: []const u8, // Configuration key (bounded)
        key_len: u32,
        value: []const u8, // Configuration value (bounded)
        value_len: u32,
    };

    /// Terminal configuration state.
    theme: Theme, // Current theme
    font_size: FontSize, // Current font size
    font_family: []const u8, // Font family name (bounded)
    font_family_len: u32,
    show_tabs: bool, // Show tab bar
    show_scrollbar: bool, // Show scrollbar
    scrollback_lines: u32, // Number of scrollback lines
    cursor_blink: bool, // Cursor blinking
    cursor_shape: CursorShape, // Cursor shape
    entries: []ConfigEntry, // Configuration entries (bounded)
    entries_len: u32, // Number of entries

    /// Cursor shape enumeration.
    pub const CursorShape = enum(u8) {
        block, // Block cursor (default)
        underline, // Underline cursor
        bar, // Bar cursor
    };

    /// Initialize default configuration.
    pub fn init(allocator: std.mem.Allocator) !Config {
        // Assert: Allocator must be valid
        // Assert: Allocator must be valid (allocator is used below)

        // Pre-allocate entries buffer
        const entries = try allocator.alloc(ConfigEntry,
MAX_CONFIG_ENTRIES);
        errdefer allocator.free(entries);

        // Default font family
        const default_font = try allocator.dupe(u8, "monospace");
        errdefer allocator.free(default_font);

        return Config{
            .theme = .dark,
            .font_size = .medium,
            .font_family = default_font,
            .font_family_len = @as(u32, @intCast(default_font.len)),
            .show_tabs = true,
            .show_scrollbar = true,
            .scrollback_lines = 10_000,
            .cursor_blink = true,
            .cursor_shape = .block,
            .entries = entries,
            .entries_len = 0,
        };
    }

    /// Deinitialize configuration and free memory.
    pub fn deinit(self: *Config, allocator: std.mem.Allocator) void {
        // Assert: Allocator must be valid
        // Assert: Allocator must be valid (allocator is used below)

        // Free all entry keys and values
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].key_len > 0) {
                allocator.free(self.entries[i].key);
            }
            if (self.entries[i].value_len > 0) {
                allocator.free(self.entries[i].value);
            }
        }

        // Free font family
        if (self.font_family_len > 0) {
            allocator.free(self.font_family);
        }

        // Free entries buffer
        allocator.free(self.entries);

        self.* = undefined;
    }

    /// Set configuration value.
    pub fn set(self: *Config, allocator: std.mem.Allocator, key: []const
u8, value: []const u8) !void {
        // Assert: Key and value must be bounded
        std.debug.assert(key.len <= MAX_KEY_LEN);
        std.debug.assert(value.len <= MAX_VALUE_LEN);

        // Check if entry already exists
        if (self.find_entry(key)) |entry| {
            // Update existing entry
            allocator.free(entry.value);
            const new_value = try allocator.dupe(u8, value);
            entry.value = new_value;
            entry.value_len = @as(u32, @intCast(new_value.len));
            return;
        }

        // Check entry limit
        if (self.entries_len >= MAX_CONFIG_ENTRIES) {
            return error.TooManyEntries;
        }

        // Allocate key and value
        const key_copy = try allocator.dupe(u8, key);
        errdefer allocator.free(key_copy);
        const value_copy = try allocator.dupe(u8, value);
        errdefer allocator.free(value_copy);

        // Store entry
        self.entries[self.entries_len] = ConfigEntry{
            .key = key_copy,
            .key_len = @as(u32, @intCast(key_copy.len)),
            .value = value_copy,
            .value_len = @as(u32, @intCast(value_copy.len)),
        };
        self.entries_len += 1;
    }

    /// Get configuration value.
    pub fn get(self: *const Config, key: []const u8) ?[]const u8 {
        if (self.find_entry(key)) |entry| {
            return entry.value;
        }
        return null;
    }

    /// Find configuration entry by key.
    fn find_entry(self: *const Config, key: []const u8) ?*ConfigEntry {
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (std.mem.eql(u8, self.entries[i].key, key)) {
                return &self.entries[i];
            }
        }
        return null;
    }

    /// Set theme.
    pub fn set_theme(self: *Config, theme: Theme) void {
        self.theme = theme;
    }

    /// Get theme.
    pub fn get_theme(self: *const Config) Theme {
        return self.theme;
    }

    /// Set font size.
    pub fn set_font_size(self: *Config, font_size: FontSize) void {
        self.font_size = font_size;
    }

    /// Get font size.
    pub fn get_font_size(self: *const Config) FontSize {
        return self.font_size;
    }

    /// Get font size in points.
    pub fn get_font_size_points(self: *const Config) u32 {
        return switch (self.font_size) {
            .small => 8,
            .medium => 12,
            .large => 16,
            .xlarge => 20,
        };
    }
};


// === grain_terminal/grainscript_integration.zig ===

const std = @import("std");
const grainscript = @import("grainscript");
const Lexer = grainscript.Lexer;
const Parser = grainscript.Parser;
const Interpreter = grainscript.Interpreter;

/// Grain Terminal Grainscript Integration: Execute Grainscript in
terminal.
/// ~<~ Glow Airbend: explicit command execution, bounded output capture.
/// ~~~~ Glow Waterbend: deterministic script execution, iterative
algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const GrainscriptIntegration = struct {
    // Bounded: Max output buffer size (explicit limit, in bytes)
    pub const MAX_OUTPUT_BUFFER: u32 = 1_048_576; // 1 MB

    // Bounded: Max command line length (explicit limit)
    pub const MAX_COMMAND_LEN: u32 = 65_536; // 64 KB

    // Bounded: Max REPL history entries (explicit limit)
    pub const MAX_REPL_HISTORY: u32 = 1_024;

    /// Output capture structure.
    pub const OutputCapture = struct {
        stdout: []u8, // Captured stdout (bounded)
        stdout_len: u32,
        stderr: []u8, // Captured stderr (bounded)
        stderr_len: u32,
        exit_code: u32, // Exit code
        allocator: std.mem.Allocator,

        /// Initialize output capture.
        pub fn init(allocator: std.mem.Allocator) !OutputCapture {
            // Assert: Allocator must be valid
            // Assert: Allocator must be valid (allocator is used below)

            // Pre-allocate stdout buffer
            const stdout = try allocator.alloc(u8, MAX_OUTPUT_BUFFER);
            errdefer allocator.free(stdout);

            // Pre-allocate stderr buffer
            const stderr = try allocator.alloc(u8, MAX_OUTPUT_BUFFER);
            errdefer allocator.free(stderr);

            return OutputCapture{
                .stdout = stdout,
                .stdout_len = 0,
                .stderr = stderr,
                .stderr_len = 0,
                .exit_code = 0,
                .allocator = allocator,
            };
        }

        /// Deinitialize output capture and free memory.
        pub fn deinit(self: *OutputCapture) void {
            // Assert: Allocator must be valid
            // Assert: Allocator must be valid (allocator is used below)

            self.allocator.free(self.stdout);
            self.allocator.free(self.stderr);

            self.* = undefined;
        }

        /// Append to stdout.
        pub fn append_stdout(self: *OutputCapture, data: []const u8)
!void {
            // Check buffer limit
            if (self.stdout_len + data.len > MAX_OUTPUT_BUFFER) {
                return error.OutputBufferFull;
            }

            @memcpy(self.stdout[self.stdout_len..][0..data.len], data);
            self.stdout_len += @as(u32, @intCast(data.len));
        }

        /// Append to stderr.
        pub fn append_stderr(self: *OutputCapture, data: []const u8)
!void {
            // Check buffer limit
            if (self.stderr_len + data.len > MAX_OUTPUT_BUFFER) {
                return error.OutputBufferFull;
            }

            @memcpy(self.stderr[self.stderr_len..][0..data.len], data);
            self.stderr_len += @as(u32, @intCast(data.len));
        }
    };

    /// REPL state structure.
    pub const ReplState = struct {
        history: []?[]const u8, // Command history (bounded, nullable
for shifting)
        history_len: u32,
        history_index: u32, // Current history index
        allocator: std.mem.Allocator,

        /// Initialize REPL state.
        pub fn init(allocator: std.mem.Allocator) !ReplState {
            // Assert: Allocator must be valid
            // Assert: Allocator must be valid (allocator is used below)

            // Pre-allocate history buffer
            const history = try allocator.alloc(?[]const u8,
MAX_REPL_HISTORY);
            @memset(history, null);
            errdefer allocator.free(history);

            return ReplState{
                .history = history,
                .history_len = 0,
                .history_index = 0,
                .allocator = allocator,
            };
        }

        /// Deinitialize REPL state and free memory.
        pub fn deinit(self: *ReplState) void {
            // Assert: Allocator must be valid
            // Assert: Allocator must be valid (allocator is used below)

            // Free all history entries
            var i: u32 = 0;
            while (i < self.history_len) : (i += 1) {
                if (self.history[i]) |cmd| {
                    self.allocator.free(cmd);
                }
            }

            // Free history buffer
            self.allocator.free(self.history);

            self.* = undefined;
        }

        /// Add command to history.
        pub fn add_command(self: *ReplState, command: []const u8) !void {
            // Check history limit
            if (self.history_len >= MAX_REPL_HISTORY) {
                // Remove oldest entry (shift left)
                if (self.history[0]) |old_cmd| {
                    self.allocator.free(old_cmd);
                }
                var i: u32 = 0;
                while (i < self.history_len - 1) : (i += 1) {
                    self.history[i] = self.history[i + 1];
                }
                self.history[self.history_len - 1] = null;
                self.history_len -= 1;
            }

            // Allocate command copy
            const command_copy = try self.allocator.dupe(u8, command);
            errdefer self.allocator.free(command_copy);

            self.history[self.history_len] = command_copy; // Store as
non-null
            self.history_len += 1;
            self.history_index = self.history_len; // Reset to end
        }

        /// Get previous command from history.
        pub fn get_previous(self: *ReplState) ?[]const u8 {
            if (self.history_index == 0) {
                return null;
            }
            self.history_index -= 1;
            if (self.history[self.history_index]) |cmd| {
                return cmd;
            }
            return "";
        }

        /// Get next command from history.
        pub fn get_next(self: *ReplState) ?[]const u8 {
            if (self.history_index >= self.history_len) {
                return null;
            }
            self.history_index += 1;
            if (self.history_index >= self.history_len) {
                return null;
            }
            return self.history[self.history_index];
        }
    };

    /// Execute Grainscript command and capture output.
    pub fn execute_command(allocator: std.mem.Allocator, source: []const
u8) !OutputCapture {
        // Assert: Allocator must be valid
            // Assert: Allocator must be valid (allocator is used below)

        // Assert: Source must be bounded
        std.debug.assert(source.len <= MAX_COMMAND_LEN);

        // Initialize output capture
        var capture = try OutputCapture.init(allocator);
        errdefer capture.deinit();

        // Create lexer
        var lexer = try Lexer.init(allocator, source);
        defer lexer.deinit();

        // Tokenize
        try lexer.tokenize();

        // Create parser
        var parser = try Parser.init(allocator, &lexer);
        defer parser.deinit();

        // Parse
        try parser.parse();

        // Create interpreter
        var interpreter = try Interpreter.init(allocator, &parser);
        defer interpreter.deinit();

        // Execute (capture output would go here)
        try interpreter.execute();

        // Get exit code
        capture.exit_code = interpreter.exit_code;

        return capture;
    }

    /// Execute Grainscript script from file.
    pub fn execute_script(allocator: std.mem.Allocator, file_path:
[]const u8) !OutputCapture {
        // Assert: Allocator must be valid
            // Assert: Allocator must be valid (allocator is used below)

        // Read file (bounded)
        const file = try std.fs.cwd().openFile(file_path, .{});
        defer file.close();

        const file_size = try file.getEndPos();
        if (file_size > MAX_COMMAND_LEN) {
            return error.FileTooLarge;
        }

        const source = try allocator.alloc(u8, @as(usize,
@intCast(file_size)));
        defer allocator.free(source);

        _ = try file.readAll(source);

        // Execute command
        return execute_command(allocator, source);
    }
};



// === grain_terminal/pane.zig ===

const std = @import("std");
const Tab = @import("tab.zig").Tab;

/// Grain Terminal Pane: Represents a split pane in terminal.
/// ~<~ Glow Airbend: explicit pane state, bounded split management.
/// ~~~~ Glow Waterbend: deterministic pane layout, iterative algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const Pane = struct {
    // Bounded: Max panes per split (explicit limit)
    pub const MAX_PANES: u32 = 16;

    /// Split direction enumeration.
    pub const SplitDirection = enum(u8) {
        horizontal, // Horizontal split (panes side by side)
        vertical, // Vertical split (panes stacked)
    };

    /// Pane structure.
    id: u32, // Pane ID (unique identifier)
    x: u32, // Pane X position (pixels)
    y: u32, // Pane Y position (pixels)
    width: u32, // Pane width (pixels)
    height: u32, // Pane height (pixels)
    tab: ?*Tab, // Associated tab (if leaf pane)
    split_direction: ?SplitDirection, // Split direction (if split pane)
    children: []Pane, // Child panes (if split pane)
    children_len: u32, // Number of children
    allocator: std.mem.Allocator,

    /// Initialize leaf pane (no split).
    pub fn init_leaf(allocator: std.mem.Allocator, id: u32, x: u32, y:
u32, width: u32, height: u32) !Pane {
        // Assert: Allocator must be valid
        // Assert: Allocator must be valid (allocator is used below)

        // Assert: Dimensions must be valid
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);

        // Pre-allocate children buffer (even for leaf, for consistency)
        const children = try allocator.alloc(Pane, MAX_PANES);
        errdefer allocator.free(children);

        return Pane{
            .id = id,
            .x = x,
            .y = y,
            .width = width,
            .height = height,
            .tab = null,
            .split_direction = null,
            .children = children,
            .children_len = 0,
            .allocator = allocator,
        };
    }

    /// Initialize split pane.
    pub fn init_split(allocator: std.mem.Allocator, id: u32, x: u32, y:
u32, width: u32, height: u32, direction: SplitDirection) !Pane {
        // Assert: Allocator must be valid
        // Assert: Allocator must be valid (allocator is used below)

        // Assert: Dimensions must be valid
        std.debug.assert(width > 0);
        std.debug.assert(height > 0);

        // Pre-allocate children buffer
        const children = try allocator.alloc(Pane, MAX_PANES);
        errdefer allocator.free(children);

        return Pane{
            .id = id,
            .x = x,
            .y = y,
            .width = width,
            .height = height,
            .tab = null,
            .split_direction = direction,
            .children = children,
            .children_len = 0,
            .allocator = allocator,
        };
    }

    /// Deinitialize pane and free memory.
    pub fn deinit(self: *Pane) void {
        // Assert: Allocator must be valid
        _ = self.allocator; // Allocator is used below

        // Deinitialize children
        var i: u32 = 0;
        while (i < self.children_len) : (i += 1) {
            self.children[i].deinit();
        }

        // Free children buffer
        self.allocator.free(self.children);

        self.* = undefined;
    }

    /// Add child pane to split.
    pub fn add_child(self: *Pane, child: Pane) !void {
        // Assert: Must be split pane
        std.debug.assert(self.split_direction != null);

        // Check children limit
        if (self.children_len >= MAX_PANES) {
            return error.TooManyPanes;
        }

        self.children[self.children_len] = child;
        self.children_len += 1;
    }

    /// Split pane (create split with two children).
    pub fn split(self: *Pane, allocator: std.mem.Allocator, direction:
SplitDirection, split_pos: u32) !Pane {
        // Assert: Must be leaf pane
        std.debug.assert(self.split_direction == null);

        // Assert: Split position must be valid
        std.debug.assert(split_pos > 0);
        if (direction == .horizontal) {
            std.debug.assert(split_pos < self.width);
        } else {
            std.debug.assert(split_pos < self.height);
        }

        // Create new split pane
        var split_pane = try Pane.init_split(allocator, self.id, self.x,
self.y, self.width, self.height, direction);

        // Create two child panes
        if (direction == .horizontal) {
            // Horizontal split: left and right panes
            var left_pane = try Pane.init_leaf(allocator, self.id + 1,
self.x, self.y, split_pos, self.height);
            const right_pane = try Pane.init_leaf(allocator, self.id +
2, self.x + split_pos, self.y, self.width - split_pos, self.height);

            // Copy tab to left pane
            left_pane.tab = self.tab;

            try split_pane.add_child(left_pane);
            try split_pane.add_child(right_pane);
        } else {
            // Vertical split: top and bottom panes
            var top_pane = try Pane.init_leaf(allocator, self.id + 1,
self.x, self.y, self.width, split_pos);
            const bottom_pane = try Pane.init_leaf(allocator, self.id +
2, self.x, self.y + split_pos, self.width, self.height - split_pos);

            // Copy tab to top pane
            top_pane.tab = self.tab;

            try split_pane.add_child(top_pane);
            try split_pane.add_child(bottom_pane);
        }

        return split_pane;
    }

    /// Check if pane is leaf (has tab).
    pub fn is_leaf(self: *const Pane) bool {
        return self.split_direction == null;
    }

    /// Get pane at position (for mouse clicks) - iterative
implementation.
    pub fn get_pane_at(self: *const Pane, x: u32, y: u32) ?*Pane {
        // Assert: Position must be valid
        std.debug.assert(x < 0xFFFFFFFF);
        std.debug.assert(y < 0xFFFFFFFF);

        // Use stack-based search (no recursion)
        var stack: [MAX_PANES]*Pane = undefined;
        var stack_len: u32 = 0;

        // Start with root pane (cast const to mutable for return type)
        stack[stack_len] = @constCast(self);
        stack_len += 1;

        // Iterative search
        while (stack_len > 0) {
            stack_len -= 1;
            const current = stack[stack_len];

            // Check if point is within current pane
            if (x < current.x or x >= current.x + current.width or y <
current.y or y >= current.y + current.height) {
                continue;
            }

            // If leaf, return it (cast const to mutable for return type)
            if (current.is_leaf()) {
                return @constCast(current);
            }

            // Add children to stack (search in reverse order for
depth-first)
            var i: u32 = current.children_len;
            while (i > 0) {
                i -= 1;
                if (stack_len < MAX_PANES) {
                    stack[stack_len] = &current.children[i];
                    stack_len += 1;
                }
            }
        }

        return null;
    }

    /// Set pane tab.
    pub fn set_tab(self: *Pane, tab: *Tab) void {
        // Assert: Must be leaf pane
        std.debug.assert(self.is_leaf());
        self.tab = tab;
    }

    /// Get pane tab.
    pub fn get_tab(self: *const Pane) ?*Tab {
        return self.tab;
    }
};


// === grain_terminal/plugin.zig ===

const std = @import("std");
const Tab = @import("tab.zig").Tab;
const Terminal = @import("terminal.zig").Terminal;

/// Grain Terminal Plugin: Plugin architecture for terminal extensions.
/// ~<~ Glow Airbend: explicit plugin state, bounded plugin management.
/// ~~~~ Glow Waterbend: deterministic plugin loading, iterative
algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const Plugin = struct {
    // Bounded: Max plugin name length (explicit limit)
    pub const MAX_PLUGIN_NAME_LEN: u32 = 256;

    // Bounded: Max plugins (explicit limit)
    pub const MAX_PLUGINS: u32 = 256;

    // Bounded: Max plugin path length (explicit limit)
    pub const MAX_PLUGIN_PATH_LEN: u32 = 4_096;

    /// Plugin state enumeration.
    pub const PluginState = enum(u8) {
        loaded, // Plugin loaded
        unloaded, // Plugin unloaded
        error_state, // Plugin error state
    };

    /// Plugin structure.
    pub const PluginData = struct {
        id: u32, // Plugin ID (unique identifier)
        name: []const u8, // Plugin name (bounded)
        name_len: u32,
        path: []const u8, // Plugin file path (bounded)
        path_len: u32,
        state: PluginState, // Plugin state
        version: u32, // Plugin version (semantic version as u32: major
<< 16 | minor << 8 | patch)
        allocator: std.mem.Allocator,

        /// Initialize plugin data.
        pub fn init(allocator: std.mem.Allocator, id: u32, name: []const
u8, path: []const u8, version: u32) !PluginData {
            // Assert: Allocator must be valid (allocator is used below)

            // Assert: Name and path must be bounded
            std.debug.assert(name.len <= MAX_PLUGIN_NAME_LEN);
            std.debug.assert(path.len <= MAX_PLUGIN_PATH_LEN);

            // Allocate name
            const name_copy = try allocator.dupe(u8, name);
            errdefer allocator.free(name_copy);

            // Allocate path
            const path_copy = try allocator.dupe(u8, path);
            errdefer allocator.free(path_copy);

            return PluginData{
                .id = id,
                .name = name_copy,
                .name_len = @as(u32, @intCast(name_copy.len)),
                .path = path_copy,
                .path_len = @as(u32, @intCast(path_copy.len)),
                .state = .unloaded,
                .version = version,
                .allocator = allocator,
            };
        }

        /// Deinitialize plugin data and free memory.
        pub fn deinit(self: *PluginData) void {
            // Assert: Allocator must be valid (allocator is used below)
            _ = self.allocator;

            // Free name
            if (self.name_len > 0) {
                self.allocator.free(self.name);
            }

            // Free path
            if (self.path_len > 0) {
                self.allocator.free(self.path);
            }

            self.* = undefined;
        }
    };

    /// Plugin API structure (functions plugins can implement).
    pub const PluginApi = struct {
        /// Plugin initialization callback.
        on_init: ?*const fn (plugin: *PluginData, allocator:
std.mem.Allocator) anyerror!void = null,

        /// Plugin deinitialization callback.
        on_deinit: ?*const fn (plugin: *PluginData) void = null,

        /// Terminal character processing hook.
        on_char: ?*const fn (plugin: *PluginData, tab: *Tab, ch: u8)
anyerror!void = null,

        /// Terminal escape sequence hook.
        on_escape: ?*const fn (plugin: *PluginData, tab: *Tab, sequence:
[]const u8) anyerror!void = null,

        /// Tab creation hook.
        on_tab_create: ?*const fn (plugin: *PluginData, tab: *Tab)
anyerror!void = null,

        /// Tab destruction hook.
        on_tab_destroy: ?*const fn (plugin: *PluginData, tab: *Tab) void
= null,
    };

    /// Plugin manager structure.
    plugins: []PluginData, // Plugins buffer (bounded)
    plugins_len: u32, // Number of plugins
    next_plugin_id: u32, // Next available plugin ID
    allocator: std.mem.Allocator,

    /// Initialize plugin manager.
    pub fn init(allocator: std.mem.Allocator) !Plugin {
        // Assert: Allocator must be valid (allocator is used below)

        // Pre-allocate plugins buffer
        const plugins = try allocator.alloc(PluginData, MAX_PLUGINS);
        errdefer allocator.free(plugins);

        return Plugin{
            .plugins = plugins,
            .plugins_len = 0,
            .next_plugin_id = 1, // Start at 1
            .allocator = allocator,
        };
    }

    /// Deinitialize plugin manager and free memory.
    pub fn deinit(self: *Plugin) void {
        // Assert: Allocator must be valid (allocator is used below)
        _ = self.allocator;

        // Unload and deinitialize all plugins
        var i: u32 = 0;
        while (i < self.plugins_len) : (i += 1) {
            if (self.plugins[i].state == .loaded) {
                _ = self.unload_plugin(self.plugins[i].id) catch {};
            }
            self.plugins[i].deinit();
        }

        // Free plugins buffer
        self.allocator.free(self.plugins);

        self.* = undefined;
    }

    /// Load plugin from file path.
    pub fn load_plugin(self: *Plugin, name: []const u8, path: []const
u8, version: u32) !u32 {
        // Assert: Name and path must be bounded
        std.debug.assert(name.len <= MAX_PLUGIN_NAME_LEN);
        std.debug.assert(path.len <= MAX_PLUGIN_PATH_LEN);

        // Check plugins limit
        if (self.plugins_len >= MAX_PLUGINS) {
            return error.TooManyPlugins;
        }

        // Check if plugin already loaded
        if (self.find_plugin_by_name(name)) |_| {
            return error.PluginAlreadyLoaded;
        }

        // Create plugin data
        const plugin_id = self.next_plugin_id;
        self.next_plugin_id += 1;

        var plugin_data = try PluginData.init(self.allocator, plugin_id,
name, path, version);
        errdefer plugin_data.deinit();

        // Load plugin (in a full implementation, this would load a
shared library)
        // For now, we just mark it as loaded
        plugin_data.state = .loaded;

        // Store plugin
        self.plugins[self.plugins_len] = plugin_data;
        self.plugins_len += 1;

        return plugin_id;
    }

    /// Unload plugin.
    pub fn unload_plugin(self: *Plugin, plugin_id: u32) !void {
        if (self.find_plugin(plugin_id)) |plugin| {
            if (plugin.state == .loaded) {
                plugin.state = .unloaded;
                // In a full implementation, we would unload the shared
library here
            } else {
                return error.PluginNotLoaded;
            }
        } else {
            return error.PluginNotFound;
        }
    }

    /// Get plugin by ID.
    pub fn get_plugin(self: *Plugin, plugin_id: u32) ?*PluginData {
        return self.find_plugin(plugin_id);
    }

    /// Find plugin by ID (internal helper).
    fn find_plugin(self: *Plugin, plugin_id: u32) ?*PluginData {
        var i: u32 = 0;
        while (i < self.plugins_len) : (i += 1) {
            if (self.plugins[i].id == plugin_id) {
                return &self.plugins[i];
            }
        }
        return null;
    }

    /// Find plugin by name (internal helper).
    fn find_plugin_by_name(self: *Plugin, name: []const u8) ?*PluginData
{
        var i: u32 = 0;
        while (i < self.plugins_len) : (i += 1) {
            if (std.mem.eql(u8, self.plugins[i].name, name)) {
                return &self.plugins[i];
            }
        }
        return null;
    }

    /// Call plugin hook for character processing.
    pub fn call_on_char(self: *Plugin, tab: *Tab, ch: u8) void {
        var i: u32 = 0;
        while (i < self.plugins_len) : (i += 1) {
            if (self.plugins[i].state == .loaded) {
                // In a full implementation, we would call the plugin's
on_char hook
                // For now, this is a placeholder
                _ = tab;
                _ = ch;
            }
        }
    }

    /// Call plugin hook for tab creation.
    pub fn call_on_tab_create(self: *Plugin, tab: *Tab) void {
        var i: u32 = 0;
        while (i < self.plugins_len) : (i += 1) {
            if (self.plugins[i].state == .loaded) {
                // In a full implementation, we would call the plugin's
on_tab_create hook
                // For now, this is a placeholder
                _ = tab;
            }
        }
    }

    /// Call plugin hook for tab destruction.
    pub fn call_on_tab_destroy(self: *Plugin, tab: *Tab) void {
        var i: u32 = 0;
        while (i < self.plugins_len) : (i += 1) {
            if (self.plugins[i].state == .loaded) {
                // In a full implementation, we would call the plugin's
on_tab_destroy hook
                // For now, this is a placeholder
                _ = tab;
            }
        }
    }
};


// === grain_terminal/renderer.zig ===

const std = @import("std");
const Terminal = @import("terminal.zig").Terminal;

/// Grain Terminal Renderer: Renders terminal cells to framebuffer.
/// ~<~ Glow Airbend: explicit rendering state, bounded buffers.
/// ~~~~ Glow Waterbend: deterministic rendering, iterative algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const Renderer = struct {
    // Bounded: Max character width in pixels (explicit limit)
    pub const CHAR_WIDTH: u32 = 8;

    // Bounded: Max character height in pixels (explicit limit)
    pub const CHAR_HEIGHT: u32 = 16;

    // ANSI color palette (16 colors: 0-7 standard, 8-15 bright)
    pub const ANSI_COLORS: [16]u32 = .{
        0x000000FF, // 0: Black
        0x800000FF, // 1: Red
        0x008000FF, // 2: Green
        0x808000FF, // 3: Yellow
        0x000080FF, // 4: Blue
        0x800080FF, // 5: Magenta
        0x008080FF, // 6: Cyan
        0xC0C0C0FF, // 7: White (light gray)
        0x808080FF, // 8: Bright Black (dark gray)
        0xFF0000FF, // 9: Bright Red
        0x00FF00FF, // 10: Bright Green
        0xFFFF00FF, // 11: Bright Yellow
        0x0000FFFF, // 12: Bright Blue
        0xFF00FFFF, // 13: Bright Magenta
        0x00FFFFFF, // 14: Bright Cyan
        0xFFFFFFFF, // 15: Bright White
    };

    /// Render terminal cells to framebuffer.
    /// Contract:
    ///   Input: terminal, cells array, framebuffer memory
    ///   Output: Renders cells to framebuffer
    ///   Errors: None (assertions for bounds checking)
    pub fn render_cells(
        terminal: *const Terminal,
        cells: []const Terminal.Cell,
        framebuffer_memory: []u8,
        fb_width: u32,
        fb_height: u32,
        offset_x: u32,
        offset_y: u32,
    ) void {
        // Assert: Terminal must be valid
        std.debug.assert(terminal.width > 0 and terminal.width <=
Terminal.MAX_WIDTH);
        std.debug.assert(terminal.height > 0 and terminal.height <=
Terminal.MAX_HEIGHT);

        // Assert: Cells buffer must be valid
        std.debug.assert(cells.len >= terminal.width * terminal.height);

        // Assert: Framebuffer must be valid
        std.debug.assert(fb_width > 0);
        std.debug.assert(fb_height > 0);
        std.debug.assert(framebuffer_memory.len >= fb_width * fb_height
* 4);

        // Render each cell
        var y: u32 = 0;
        while (y < terminal.height) : (y += 1) {
            var x: u32 = 0;
            while (x < terminal.width) : (x += 1) {
                const cell_idx = y * terminal.width + x;
                const cell = cells[cell_idx];

                // Calculate pixel position
                const px = offset_x + x * CHAR_WIDTH;
                const py = offset_y + y * CHAR_HEIGHT;

                // Get colors
                var fg_color = ANSI_COLORS[cell.attrs.fg_color];
                var bg_color = ANSI_COLORS[cell.attrs.bg_color];

                // Apply reverse video
                if (cell.attrs.reverse) {
                    const temp = fg_color;
                    fg_color = bg_color;
                    bg_color = temp;
                }

                // Render character cell
                render_char_cell(
                    cell.ch,
                    px,
                    py,
                    fg_color,
                    bg_color,
                    cell.attrs.bold,
                    framebuffer_memory,
                    fb_width,
                    fb_height,
                );
            }
        }
    }

    /// Render single character cell.
    fn render_char_cell(
        ch: u8,
        x: u32,
        y: u32,
        fg_color: u32,
        bg_color: u32,
        bold: bool,
        framebuffer_memory: []u8,
        fb_width: u32,
        fb_height: u32,
    ) void {
        // Assert: Position must be within bounds
        std.debug.assert(x + CHAR_WIDTH <= fb_width);
        std.debug.assert(y + CHAR_HEIGHT <= fb_height);
        std.debug.assert(framebuffer_memory.len >= fb_width * fb_height
* 4);

        // Get character pattern (simplified 8x8 bitmap)
        const pattern = get_char_pattern(ch);

        // Extract colors
        const fg_r: u8 = @truncate((fg_color >> 24) & 0xFF);
        const fg_g: u8 = @truncate((fg_color >> 16) & 0xFF);
        const fg_b: u8 = @truncate((fg_color >> 8) & 0xFF);
        const bg_r: u8 = @truncate((bg_color >> 24) & 0xFF);
        const bg_g: u8 = @truncate((bg_color >> 16) & 0xFF);
        const bg_b: u8 = @truncate((bg_color >> 8) & 0xFF);

        // Render character (8x8 pixels, centered in 8x16 cell)
        var py: u32 = 0;
        while (py < CHAR_HEIGHT) : (py += 1) {
            var px: u32 = 0;
            while (px < CHAR_WIDTH) : (px += 1) {
                const pixel_x = x + px;
                const pixel_y = y + py;

                // Check bounds
                if (pixel_x >= fb_width or pixel_y >= fb_height) {
                    continue;
                }

                const offset: u32 = (pixel_y * fb_width + pixel_x) * 4;
                std.debug.assert(offset + 3 < framebuffer_memory.len);

                // Use pattern for top 8 rows, background for bottom 8
rows
                var bit: u1 = 0;
                if (py < 8 and px < 8) {
                    const bit_idx = py * 8 + px;
                    const shift: u6 = @as(u6, @intCast(63 - bit_idx));
                    bit = @as(u1, @truncate((pattern >> shift) & 1));
                }

                if (bit == 1) {
                    // Foreground color (apply bold by making it
brighter)
                    if (bold) {
                        framebuffer_memory[offset + 0] = @min(255, fg_r
+ 64);
                        framebuffer_memory[offset + 1] = @min(255, fg_g
+ 64);
                        framebuffer_memory[offset + 2] = @min(255, fg_b
+ 64);
                    } else {
                        framebuffer_memory[offset + 0] = fg_r;
                        framebuffer_memory[offset + 1] = fg_g;
                        framebuffer_memory[offset + 2] = fg_b;
                    }
                } else {
                    // Background color
                    framebuffer_memory[offset + 0] = bg_r;
                    framebuffer_memory[offset + 1] = bg_g;
                    framebuffer_memory[offset + 2] = bg_b;
                }
                framebuffer_memory[offset + 3] = 0xFF; // Alpha
            }
        }
    }

    /// Get character pattern (8x8 bitmap, 64 bits).
    /// Simplified font pattern for ASCII characters.
    pub fn get_char_pattern(ch: u8) u64 {
        // Basic 8x8 font patterns for ASCII characters
        // This is a simplified implementation; a full font would have
all 256 characters
        return switch (ch) {
            ' ' => 0x0000000000000000, // Space
            '!' => 0x1818181818001800,
            '"' => 0x3636000000000000,
            '#' => 0x36367F367F363600,
            '$' => 0x0C3E033E301E0000,
            '%' => 0x006333180C666300,
            '&' => 0x1E33331E6E333E00,
            '\'' => 0x0606000000000000,
            '(' => 0x0C18181818180C00,
            ')' => 0x180C0C0C0C0C1800,
            '*' => 0x0000361C7F1C3600,
            '+' => 0x00000C0C3F0C0C00,
            ',' => 0x00000000000C0C18,
            '-' => 0x000000003F000000,
            '.' => 0x0000000000181800,
            '/' => 0x0030180C06030100,
            '0' => 0x1E33373F3B331E00,
            '1' => 0x0E0C0C0C0C0C1E00,
            '2' => 0x1E3303060C18331F,
            '3' => 0x1E3303060E03331E,
            '4' => 0x060E1E36367F0606,
            '5' => 0x1F031F300303331E,
            '6' => 0x1E33031F3333331E,
            '7' => 0x3F3303060C0C0C0C,
            '8' => 0x1E33331E3333331E,
            '9' => 0x1E33333E3003031E,
            ':' => 0x0000181800181800,
            ';' => 0x0000181800181830,
            '<' => 0x060C18180C060000,
            '=' => 0x00003F00003F0000,
            '>' => 0x180C0606060C1800,
            '?' => 0x1E3303060C000C00,
            '@' => 0x1E33373B3B031E00,
            'A' => 0x0C1E33333F333300,
            'B' => 0x1F33331F3333331F,
            'C' => 0x1E3303030303331E,
            'D' => 0x1F3633333333361F,
            'E' => 0x3F03031F0303033F,
            'F' => 0x3F03031F03030303,
            'G' => 0x1E3303033B33331E,
            'H' => 0x3333333F33333333,
            'I' => 0x1E0C0C0C0C0C0C1E,
            'J' => 0x1E3030303030331E,
            'K' => 0x33331E0C0C1E3333,
            'L' => 0x030303030303033F,
            'M' => 0x63777F7F6B636363,
            'N' => 0x33373F3B3B333333,
            'O' => 0x1E3333333333331E,
            'P' => 0x1F33331F03030303,
            'Q' => 0x1E333333333B361D,
            'R' => 0x1F33331F1B333333,
            'S' => 0x1E33031E3003331E,
            'T' => 0x3F0C0C0C0C0C0C0C,
            'U' => 0x333333333333331E,
            'V' => 0x3333333333331E0C,
            'W' => 0x6363636B7F7F7763,
            'X' => 0x33331E0C0C1E3333,
            'Y' => 0x3333331E0C0C0C0C,
            'Z' => 0x3F30060C1830033F,
            '[' => 0x1E0606060606061E,
            '\\' => 0x000103060C183060,
            ']' => 0x1E1818181818181E,
            '^' => 0x0C1E330000000000,
            '_' => 0x000000000000003F,
            '`' => 0x180C000000000000,
            'a' => 0x00001E303E333E00,
            'b' => 0x03031F3333331F00,
            'c' => 0x00001E3303331E00,
            'd' => 0x30303E3333333E00,
            'e' => 0x00001E333F031E00,
            'f' => 0x1C36061F06060606,
            'g' => 0x00003E33333E301E,
            'h' => 0x03031F3333333300,
            'i' => 0x0C000C0C0C0C0C00,
            'j' => 0x1800181818181B0E,
            'k' => 0x0303331E0E1B3300,
            'l' => 0x0C0C0C0C0C0C0C00,
            'm' => 0x00001F7F6B6B6300,
            'n' => 0x00001F3333333300,
            'o' => 0x00001E3333331E00,
            'p' => 0x00001F33331F0303,
            'q' => 0x00003E33333E3030,
            'r' => 0x00001B0E06060600,
            's' => 0x00001E031E301E00,
            't' => 0x06061F060606360C,
            'u' => 0x0000333333333E00,
            'v' => 0x00003333331E0C00,
            'w' => 0x0000636B7F3E3600,
            'x' => 0x0000331E0C1E3300,
            'y' => 0x00003333333E301E,
            'z' => 0x00003F180C063F00,
            '{' => 0x1C180C0C180C181C,
            '|' => 0x0C0C0C0C0C0C0C0C,
            '}' => 0x1C0C1818180C0C1C,
            '~' => 0x0000001B36000000,
            else => 0x3F3F3F3F3F3F3F3F, // Unknown character (filled
block)
        };
    }
};


