// === grain_terminal/session.zig ===

const std = @import("std");
const Tab = @import("tab.zig").Tab;
const Config = @import("config.zig").Config;

/// Grain Terminal Session: Save/restore terminal sessions.
/// ~<~ Glow Airbend: explicit session state, bounded session storage.
/// ~~~~ Glow Waterbend: deterministic session management, iterative
algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const Session = struct {
    // Bounded: Max session name length (explicit limit)
    pub const MAX_SESSION_NAME_LEN: u32 = 256;

    // Bounded: Max sessions (explicit limit)
    pub const MAX_SESSIONS: u32 = 1_024;

    // Bounded: Max tabs per session (explicit limit)
    pub const MAX_TABS_PER_SESSION: u32 = 256;

    // Bounded: Max session data size (explicit limit, in bytes)
    pub const MAX_SESSION_DATA_SIZE: u32 = 10_485_760; // 10 MB

    /// Session state enumeration.
    pub const SessionState = enum(u8) {
        active, // Active session
        saved, // Saved session
        restored, // Restored session
    };

    /// Session structure.
    pub const SessionData = struct {
        id: u32, // Session ID (unique identifier)
        name: []const u8, // Session name (bounded)
        name_len: u32,
        state: SessionState, // Session state
        created_at: u64, // Creation timestamp (Unix epoch)
        updated_at: u64, // Last update timestamp (Unix epoch)
        tab_ids: []u32, // Tab IDs in this session (bounded)
        tab_ids_len: u32,
        active_tab_id: u32, // Active tab ID
        config_snapshot: Config, // Configuration snapshot
        allocator: std.mem.Allocator,
    };

    /// Session manager structure.
    sessions: []SessionData, // Sessions buffer (bounded)
    sessions_len: u32, // Number of sessions
    next_session_id: u32, // Next available session ID
    allocator: std.mem.Allocator,

    /// Initialize session manager.
    pub fn init(allocator: std.mem.Allocator) !Session {
        // Assert: Allocator must be valid (allocator is used below)

        // Pre-allocate sessions buffer
        const sessions = try allocator.alloc(SessionData, MAX_SESSIONS);
        errdefer allocator.free(sessions);

        return Session{
            .sessions = sessions,
            .sessions_len = 0,
            .next_session_id = 1, // Start at 1
            .allocator = allocator,
        };
    }

    /// Deinitialize session manager and free memory.
    pub fn deinit(self: *Session) void {
        // Assert: Allocator must be valid
        _ = self.allocator; // Allocator is used below

        // Deinitialize all sessions
        var i: u32 = 0;
        while (i < self.sessions_len) : (i += 1) {
            session_data_deinit(&self.sessions[i]);
        }

        // Free sessions buffer
        self.allocator.free(self.sessions);

        self.* = undefined;
    }

    /// Create new session.
    pub fn create_session(self: *Session, name: []const u8, config:
*const Config) !u32 {
        // Assert: Name must be bounded
        std.debug.assert(name.len <= MAX_SESSION_NAME_LEN);

        // Check sessions limit
        if (self.sessions_len >= MAX_SESSIONS) {
            return error.TooManySessions;
        }

        // Get current timestamp
        const now = std.time.timestamp();

        // Allocate name
        const name_copy = try self.allocator.dupe(u8, name);
        errdefer self.allocator.free(name_copy);

        // Pre-allocate tab IDs buffer
        const tab_ids = try self.allocator.alloc(u32,
MAX_TABS_PER_SESSION);
        errdefer self.allocator.free(tab_ids);

        // Create config snapshot (copy)
        const config_snapshot = try self.copy_config(config);
        errdefer config_snapshot.deinit(self.allocator);

        // Create session
        const session_id = self.next_session_id;
        self.next_session_id += 1;

        self.sessions[self.sessions_len] = SessionData{
            .id = session_id,
            .name = name_copy,
            .name_len = @as(u32, @intCast(name_copy.len)),
            .state = .active,
            .created_at = @as(u64, @intCast(now)),
            .updated_at = @as(u64, @intCast(now)),
            .tab_ids = tab_ids,
            .tab_ids_len = 0,
            .active_tab_id = 0, // No active tab initially
            .config_snapshot = config_snapshot,
            .allocator = self.allocator,
        };
        self.sessions_len += 1;

        return session_id;
    }

    /// Save session (mark as saved, update timestamp).
    pub fn save_session(self: *Session, session_id: u32) !void {
        if (self.find_session(session_id)) |session| {
            session.state = .saved;
            const now = std.time.timestamp();
            session.updated_at = @as(u64, @intCast(now));
        } else {
            return error.SessionNotFound;
        }
    }

    /// Restore session (mark as restored, update timestamp).
    pub fn restore_session(self: *Session, session_id: u32) !void {
        if (self.find_session(session_id)) |session| {
            session.state = .restored;
            const now = std.time.timestamp();
            session.updated_at = @as(u64, @intCast(now));
        } else {
            return error.SessionNotFound;
        }
    }

    /// Add tab to session.
    pub fn add_tab(self: *Session, session_id: u32, tab_id: u32) !void {
        if (self.find_session(session_id)) |session| {
            // Check tab limit
            if (session.tab_ids_len >= MAX_TABS_PER_SESSION) {
                return error.TooManyTabs;
            }

            session.tab_ids[session.tab_ids_len] = tab_id;
            session.tab_ids_len += 1;

            // Update timestamp
            const now = std.time.timestamp();
            session.updated_at = @as(u64, @intCast(now));
        } else {
            return error.SessionNotFound;
        }
    }

    /// Set active tab in session.
    pub fn set_active_tab(self: *Session, session_id: u32, tab_id: u32)
!void {
        if (self.find_session(session_id)) |session| {
            session.active_tab_id = tab_id;

            // Update timestamp
            const now = std.time.timestamp();
            session.updated_at = @as(u64, @intCast(now));
        } else {
            return error.SessionNotFound;
        }
    }

    /// Get session by ID.
    pub fn get_session(self: *Session, session_id: u32) ?*SessionData {
        return self.find_session(session_id);
    }

    /// Find session by ID (internal helper).
    fn find_session(self: *Session, session_id: u32) ?*SessionData {
        var i: u32 = 0;
        while (i < self.sessions_len) : (i += 1) {
            if (self.sessions[i].id == session_id) {
                return &self.sessions[i];
            }
        }
        return null;
    }

    /// Copy configuration (create snapshot).
    // 2025-11-23-150318-pst: Active function
    fn copy_config(self: *Session, config: *const Config) !Config {
        // self will be used in full implementation for session-specific
config
        // Create a new config with same settings
        // In a full implementation, we'd deep copy all config entries
        var new_config = try Config.init(self.allocator);
        new_config.theme = config.theme;
        new_config.font_size = config.font_size;
        new_config.show_tabs = config.show_tabs;
        new_config.show_scrollbar = config.show_scrollbar;
        new_config.scrollback_lines = config.scrollback_lines;
        new_config.cursor_blink = config.cursor_blink;
        new_config.cursor_shape = config.cursor_shape;
        
        // Copy font family
        if (config.font_family_len > 0) {
            self.allocator.free(new_config.font_family);
            new_config.font_family = try self.allocator.dupe(u8,
config.font_family);
            new_config.font_family_len = config.font_family_len;
        }
        
        return new_config;
    }
};

/// SessionData deinitialization.
pub fn session_data_deinit(data: *Session.SessionData) void {
    // Free name
    if (data.name_len > 0) {
        data.allocator.free(data.name);
    }

    // Free tab IDs
    data.allocator.free(data.tab_ids);

    // Deinitialize config snapshot
    data.config_snapshot.deinit(data.allocator);

    data.* = undefined;
}


// === grain_terminal/tab.zig ===

const std = @import("std");
const Terminal = @import("terminal.zig").Terminal;

/// Grain Terminal Tab: Represents a single terminal tab.
/// ~<~ Glow Airbend: explicit tab state, bounded terminal instances.
/// ~~~~ Glow Waterbend: deterministic tab management, iterative
algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const Tab = struct {
    // Bounded: Max tab title length (explicit limit)
    pub const MAX_TITLE_LEN: u32 = 256;

    /// Tab state enumeration.
    pub const TabState = enum(u8) {
        active, // Active tab
        inactive, // Inactive tab
        closed, // Closed tab (for cleanup)
    };

    /// Tab structure.
    id: u32, // Tab ID (unique identifier)
    title: []const u8, // Tab title (bounded)
    title_len: u32,
    state: TabState, // Tab state
    terminal: Terminal, // Terminal instance
    cells: []Terminal.Cell, // Terminal cells buffer
    allocator: std.mem.Allocator,

    /// Initialize tab with terminal dimensions.
    pub fn init(allocator: std.mem.Allocator, id: u32, width: u32,
height: u32, title: []const u8) !Tab {
        // Assert: Allocator must be valid
        // Assert: Allocator must be valid (allocator is used below)

        // Assert: Dimensions must be valid
        std.debug.assert(width > 0 and width <= Terminal.MAX_WIDTH);
        std.debug.assert(height > 0 and height <= Terminal.MAX_HEIGHT);

        // Assert: Title must be bounded
        std.debug.assert(title.len <= MAX_TITLE_LEN);

        // Initialize terminal
        const terminal = Terminal.init(width, height);

        // Allocate cells buffer
        const cells = try allocator.alloc(Terminal.Cell, width * height);
        errdefer allocator.free(cells);

        // Initialize cells to spaces
        var i: u32 = 0;
        while (i < width * height) : (i += 1) {
            cells[i] = Terminal.Cell{
                .ch = ' ',
                .attrs = Terminal.CellAttributes{
                    .fg_color = 7,
                    .bg_color = 0,
                    .bold = false,
                    .italic = false,
                    .underline = false,
                    .blink = false,
                    .reverse = false,
                },
            };
        }

        // Allocate title
        const title_copy = try allocator.dupe(u8, title);
        errdefer allocator.free(title_copy);

        return Tab{
            .id = id,
            .title = title_copy,
            .title_len = @as(u32, @intCast(title_copy.len)),
            .state = .inactive,
            .terminal = terminal,
            .cells = cells,
            .allocator = allocator,
        };
    }

    /// Deinitialize tab and free memory.
    pub fn deinit(self: *Tab) void {
        // Assert: Allocator must be valid
        _ = self.allocator; // Allocator is used below

        // Free title
        if (self.title_len > 0) {
            self.allocator.free(self.title);
        }

        // Free cells buffer
        self.allocator.free(self.cells);

        self.* = undefined;
    }

    /// Process input character in tab's terminal.
    pub fn process_char(self: *Tab, ch: u8) void {
        self.terminal.process_char(ch, self.cells);
    }

    /// Clear tab's terminal.
    pub fn clear(self: *Tab) void {
        self.terminal.clear(self.cells);
    }

    /// Get terminal cells.
    pub fn get_cells(self: *const Tab) []const Terminal.Cell {
        return self.cells;
    }

    /// Get terminal instance.
    pub fn get_terminal(self: *Tab) *Terminal {
        return &self.terminal;
    }

    /// Set tab title.
    pub fn set_title(self: *Tab, title: []const u8) !void {
        // Assert: Title must be bounded
        std.debug.assert(title.len <= MAX_TITLE_LEN);

        // Free old title
        if (self.title_len > 0) {
            self.allocator.free(self.title);
        }

        // Allocate new title
        const title_copy = try self.allocator.dupe(u8, title);
        self.title = title_copy;
        self.title_len = @as(u32, @intCast(title_copy.len));
    }

    /// Set tab state.
    pub fn set_state(self: *Tab, state: TabState) void {
        self.state = state;
    }

    /// Get tab state.
    pub fn get_state(self: *const Tab) TabState {
        return self.state;
    }
};


// === grain_terminal/terminal.zig ===

const std = @import("std");

/// Grain Terminal: Terminal emulator for Grain OS.
/// ~<~ Glow Airbend: explicit character cells, bounded terminal state.
/// ~~~~ Glow Waterbend: deterministic rendering, iterative algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const Terminal = struct {
    // Bounded: Max terminal width (explicit limit)
    pub const MAX_WIDTH: u32 = 256;

    // Bounded: Max terminal height (explicit limit)
    pub const MAX_HEIGHT: u32 = 256;

    // Bounded: Max scrollback lines (explicit limit)
    pub const MAX_SCROLLBACK: u32 = 10_000;

    // Bounded: Max escape sequence length (explicit limit)
    pub const MAX_ESCAPE_SEQ: u32 = 256;

    /// Character cell attributes.
    pub const CellAttributes = struct {
        fg_color: u8, // Foreground color index (0-15 for ANSI, 0-255
for 256-color)
        bg_color: u8, // Background color index (0-15 for ANSI, 0-255
for 256-color)
        fg_rgb: ?[3]u8, // Foreground RGB (true color, null if using
indexed color)
        bg_rgb: ?[3]u8, // Background RGB (true color, null if using
indexed color)
        bold: bool, // Bold text
        italic: bool, // Italic text
        underline: bool, // Underline text
        blink: bool, // Blinking text
        reverse: bool, // Reverse video
    };

    /// Character cell (single cell in terminal grid).
    pub const Cell = struct {
        ch: u8, // Character (ASCII/UTF-8)
        attrs: CellAttributes, // Cell attributes
    };

    /// Terminal state enumeration.
    pub const State = enum(u8) {
        normal, // Normal text input
        escape, // Processing escape sequence
        csi, // Control Sequence Introducer (CSI)
        osc, // Operating System Command (OSC)
    };

    /// Terminal dimensions and state.
    width: u32, // Terminal width (columns)
    height: u32, // Terminal height (rows)
    cursor_x: u32, // Cursor X position (0-based)
    cursor_y: u32, // Cursor Y position (0-based)
    saved_cursor_x: u32, // Saved cursor X position
    saved_cursor_y: u32, // Saved cursor Y position
    state: State, // Current terminal state
    escape_buffer: [MAX_ESCAPE_SEQ]u8, // Escape sequence buffer
    escape_len: u32, // Escape sequence length
    scrollback_lines: u32, // Number of scrollback lines
    scrollback_offset: u32, // Current scrollback offset (0 = at bottom,
showing latest)
    scroll_top: u32, // Top margin of scrolling region (0-based)
    scroll_bottom: u32, // Bottom margin of scrolling region (0-based,
exclusive)
    dec_ckm: bool, // DEC Cursor Keys Mode (application vs cursor keys)
    dec_om: bool, // DEC Origin Mode (relative vs absolute origin)
    dec_awm: bool, // DEC Auto Wrap Mode (wrap vs truncate)
    dec_tcem: bool, // DEC Text Cursor Enable Mode (show vs hide cursor)
    tab_stops: [256]bool, // Tab stops (one per column, bounded by
MAX_WIDTH)
    default_fg: u8, // Default foreground color
    default_bg: u8, // Default background color
    current_attrs: CellAttributes, // Current cell attributes
    window_title: [256]u8, // Window title (OSC 0/2)
    window_title_len: u32, // Window title length

    /// Initialize terminal with dimensions.
    pub fn init(width: u32, height: u32) Terminal {
        // Assert: Dimensions must be within bounds
        std.debug.assert(width > 0 and width <= MAX_WIDTH);
        std.debug.assert(height > 0 and height <= MAX_HEIGHT);

        return Terminal{
            .width = width,
            .height = height,
            .cursor_x = 0,
            .cursor_y = 0,
            .saved_cursor_x = 0,
            .saved_cursor_y = 0,
            .state = .normal,
            .escape_buffer = [_]u8{0} ** MAX_ESCAPE_SEQ,
            .escape_len = 0,
            .scrollback_lines = 0,
            .scrollback_offset = 0,
            .scroll_top = 0,
            .scroll_bottom = height,
            .dec_ckm = false,
            .dec_om = false,
            .dec_awm = true,
            .dec_tcem = true,
            .tab_stops = init: {
                var stops: [256]bool = undefined;
                // Initialize tab stops every 8 columns (standard)
                var i: u32 = 0;
                while (i < 256) : (i += 1) {
                    stops[i] = (i % 8 == 7);
                }
                break :init stops;
            },
            .default_fg = 7, // Default: white foreground
            .default_bg = 0, // Default: black background
            .window_title = [_]u8{0} ** 256,
            .window_title_len = 0,
            .current_attrs = CellAttributes{
                .fg_color = 7,
                .bg_color = 0,
                .fg_rgb = null,
                .bg_rgb = null,
                .bold = false,
                .italic = false,
                .underline = false,
                .blink = false,
                .reverse = false,
            },
        };
    }

    /// Process input character (VT100/VT220 escape sequence handling).
    pub fn process_char(self: *Terminal, ch: u8, cells: []Cell) void {
        // Assert: Terminal must be valid
        std.debug.assert(self.width > 0 and self.height > 0);
        std.debug.assert(self.cursor_x < self.width);
        std.debug.assert(self.cursor_y < self.height);

        // Assert: Cells buffer must be valid
        std.debug.assert(cells.len >= self.width * self.height);

        switch (self.state) {
            .normal => {
                if (ch == 0x1B) { // ESC
                    self.state = .escape;
                    self.escape_len = 0;
                } else if (ch == '\r') { // Carriage return
                    self.cursor_x = 0;
                } else if (ch == '\n') { // Line feed
                    self.cursor_y += 1;
                    if (self.cursor_y >= self.scroll_bottom) {
                        self.scroll_up_region(cells);
                        self.cursor_y = self.scroll_bottom - 1;
                    }
                } else if (ch == '\t') { // Tab
                    self.handle_tab();
                } else if (ch == 0x07) { // BEL (bell/beep)
                    self.handle_bell();
                } else if (ch >= 0x20 and ch < 0x7F) { // Printable ASCII
                    self.write_char(ch, cells);
                    self.cursor_x += 1;
                    if (self.cursor_x >= self.width) {
                        if (self.dec_awm) {
                            // Auto wrap: move to next line
                            self.cursor_x = 0;
                            self.cursor_y += 1;
                            if (self.cursor_y >= self.scroll_bottom) {
                                self.scroll_up_region(cells);
                                self.cursor_y = self.scroll_bottom - 1;
                            }
                        } else {
                            // No wrap: stay at right margin
                            self.cursor_x = self.width - 1;
                        }
                    }
                }
            },
            .escape => {
                if (ch == '[') {
                    self.state = .csi;
                    self.escape_len = 0;
                } else if (ch == ']') {
                    self.state = .osc;
                    self.escape_len = 0;
                } else {
                    // Single-character escape sequence
                    self.handle_escape_sequence(ch);
                    self.state = .normal;
                    self.escape_len = 0;
                }
            },
            .csi => {
                if (ch >= 0x40 and ch <= 0x7E) { // Final character
                    self.escape_buffer[self.escape_len] = ch;
                    self.escape_len += 1;
                    self.handle_csi_sequence(cells);
                    self.state = .normal;
                    self.escape_len = 0;
                } else if (self.escape_len < MAX_ESCAPE_SEQ - 1) {
                    self.escape_buffer[self.escape_len] = ch;
                    self.escape_len += 1;
                }
            },
            .osc => {
                if (ch == 0x07 or ch == 0x1B) { // BEL or ESC
                    self.handle_osc_sequence();
                    self.state = .normal;
                    self.escape_len = 0;
                } else if (self.escape_len < MAX_ESCAPE_SEQ - 1) {
                    self.escape_buffer[self.escape_len] = ch;
                    self.escape_len += 1;
                }
            },
        }
    }

    /// Write character to current cursor position.
    fn write_char(self: *Terminal, ch: u8, cells: []Cell) void {
        // Assert: Cursor position must be valid
        std.debug.assert(self.cursor_x < self.width);
        std.debug.assert(self.cursor_y < self.height);

        const idx = self.cursor_y * self.width + self.cursor_x;
        std.debug.assert(idx < cells.len);

        cells[idx] = Cell{
            .ch = ch,
            .attrs = self.current_attrs,
        };
    }

    /// Scroll scrolling region up (add new line at bottom of region).
    // 2025-11-24-212700-pst: Active function
    fn scroll_up_region(self: *Terminal, cells: []Cell) void {
        // Assert: Cells buffer must be valid
        std.debug.assert(cells.len >= self.width * self.height);

        // Scroll lines within scrolling region
        var y: u32 = self.scroll_top;
        while (y < self.scroll_bottom - 1) : (y += 1) {
            const src_line_start = (y + 1) * self.width;
            const dst_line_start = y * self.width;
            var x: u32 = 0;
            while (x < self.width) : (x += 1) {
                const src_idx = src_line_start + x;
                const dst_idx = dst_line_start + x;
                cells[dst_idx] = cells[src_idx];
            }
        }

        // Clear bottom line of scrolling region
        const bottom_line_start = (self.scroll_bottom - 1) * self.width;
        var x: u32 = 0;
        while (x < self.width) : (x += 1) {
            const idx = bottom_line_start + x;
            cells[idx] = Cell{
                .ch = ' ',
                .attrs = self.current_attrs,
            };
        }

        // Update scrollback
        self.scrollback_lines += 1;
        if (self.scrollback_lines > MAX_SCROLLBACK) {
            self.scrollback_lines = MAX_SCROLLBACK;
        }
    }

    /// Scroll terminal up (add new line at bottom).
    fn scroll_up(self: *Terminal, cells: []Cell) void {
        // Assert: Cells buffer must be valid
        std.debug.assert(cells.len >= self.width * self.height);

        // Move all lines up by one
        var y: u32 = 1;
        while (y < self.height) : (y += 1) {
            var x: u32 = 0;
            while (x < self.width) : (x += 1) {
                const src_idx = y * self.width + x;
                const dst_idx = (y - 1) * self.width + x;
                cells[dst_idx] = cells[src_idx];
            }
        }

        // Clear bottom line
        var x: u32 = 0;
        while (x < self.width) : (x += 1) {
            const idx = (self.height - 1) * self.width + x;
            cells[idx] = Cell{
                .ch = ' ',
                .attrs = CellAttributes{
                    .fg_color = self.default_fg,
                    .bg_color = self.default_bg,
                    .fg_rgb = null,
                    .bg_rgb = null,
                    .bold = false,
                    .italic = false,
                    .underline = false,
                    .blink = false,
                    .reverse = false,
                },
            };
        }

        // Increment scrollback counter
        if (self.scrollback_lines < MAX_SCROLLBACK) {
            self.scrollback_lines += 1;
        }
        // Reset scrollback offset when new content is added
        self.scrollback_offset = 0;
    }

    /// Scroll up in scrollback (view older content).
    // 2025-11-24-174000-pst: Active function
    pub fn scrollback_up(self: *Terminal) void {
        if (self.scrollback_offset < self.scrollback_lines) {
            self.scrollback_offset += 1;
        }
    }

    /// Scroll down in scrollback (view newer content).
    // 2025-11-24-174000-pst: Active function
    pub fn scrollback_down(self: *Terminal) void {
        if (self.scrollback_offset > 0) {
            self.scrollback_offset -= 1;
        }
    }

    /// Jump to top of scrollback (oldest content).
    // 2025-11-24-174000-pst: Active function
    pub fn scrollback_to_top(self: *Terminal) void {
        self.scrollback_offset = self.scrollback_lines;
    }

    /// Jump to bottom of scrollback (latest content).
    // 2025-11-24-174000-pst: Active function
    pub fn scrollback_to_bottom(self: *Terminal) void {
        self.scrollback_offset = 0;
    }

    /// Get current scrollback offset.
    // 2025-11-24-174000-pst: Active function
    pub fn get_scrollback_offset(self: *const Terminal) u32 {
        return self.scrollback_offset;
    }

    /// Get total scrollback lines.
    // 2025-11-24-174000-pst: Active function
    pub fn get_scrollback_lines(self: *const Terminal) u32 {
        return self.scrollback_lines;
    }

    /// Handle single-character escape sequence.
    fn handle_escape_sequence(self: *Terminal, ch: u8) void {
        switch (ch) {
            '7' => {
                // Save cursor position
                self.saved_cursor_x = self.cursor_x;
                self.saved_cursor_y = self.cursor_y;
            },
            '8' => {
                // Restore cursor position
                self.cursor_x = self.saved_cursor_x;
                self.cursor_y = self.saved_cursor_y;
                if (self.cursor_x >= self.width) {
                    self.cursor_x = self.width - 1;
                }
                if (self.cursor_y >= self.height) {
                    self.cursor_y = self.height - 1;
                }
            },
            'H' => {
                // Horizontal Tab Set (HTS) - set tab stop at current
column
                if (self.cursor_x < MAX_WIDTH) {
                    self.tab_stops[self.cursor_x] = true;
                }
            },
            'c' => {
                // Reset terminal
                self.cursor_x = 0;
                self.cursor_y = 0;
                self.current_attrs = CellAttributes{
                    .fg_color = self.default_fg,
                    .bg_color = self.default_bg,
                    .fg_rgb = null,
                    .bg_rgb = null,
                    .bold = false,
                    .italic = false,
                    .underline = false,
                    .blink = false,
                    .reverse = false,
                };
                // Reset tab stops to default (every 8 columns)
                var i: u32 = 0;
                while (i < MAX_WIDTH) : (i += 1) {
                    self.tab_stops[i] = (i % 8 == 7);
                }
            },
            else => {
                // Unknown escape sequence, ignore
            },
        }
    }

    /// Handle CSI (Control Sequence Introducer) sequence.
    fn handle_csi_sequence(self: *Terminal, cells: []Cell) void {
        // Assert: Escape buffer must have at least final character
        std.debug.assert(self.escape_len > 0);

        const final_char = self.escape_buffer[self.escape_len - 1];
        const params = self.escape_buffer[0..self.escape_len - 1];

        switch (final_char) {
            'A' => {
                // Cursor Up
                const n = self.parse_csi_param(params, 1);
                if (self.cursor_y >= n) {
                    self.cursor_y -= n;
                } else {
                    self.cursor_y = 0;
                }
            },
            'B' => {
                // Cursor Down
                const n = self.parse_csi_param(params, 1);
                self.cursor_y += n;
                if (self.cursor_y >= self.height) {
                    self.cursor_y = self.height - 1;
                }
            },
            'C' => {
                // Cursor Forward
                const n = self.parse_csi_param(params, 1);
                self.cursor_x += n;
                if (self.cursor_x >= self.width) {
                    self.cursor_x = self.width - 1;
                }
            },
            'D' => {
                // Cursor Backward
                const n = self.parse_csi_param(params, 1);
                if (self.cursor_x >= n) {
                    self.cursor_x -= n;
                } else {
                    self.cursor_x = 0;
                }
            },
            'H' => {
                // Cursor Position
                var params_iter = std.mem.splitScalar(u8, params, ';');
                const row_str = params_iter.next() orelse "1";
                const col_str = params_iter.next() orelse "1";
                const row = self.parse_number(row_str, 1);
                const col = self.parse_number(col_str, 1);
                self.cursor_y = if (row > 0) row - 1 else 0;
                self.cursor_x = if (col > 0) col - 1 else 0;
                if (self.cursor_y >= self.height) {
                    self.cursor_y = self.height - 1;
                }
                if (self.cursor_x >= self.width) {
                    self.cursor_x = self.width - 1;
                }
            },
            'f' => {
                // Cursor Position (same as 'H')
                var params_iter = std.mem.splitScalar(u8, params, ';');
                const row_str = params_iter.next() orelse "1";
                const col_str = params_iter.next() orelse "1";
                const row = self.parse_number(row_str, 1);
                const col = self.parse_number(col_str, 1);
                self.cursor_y = if (row > 0) row - 1 else 0;
                self.cursor_x = if (col > 0) col - 1 else 0;
                if (self.cursor_y >= self.height) {
                    self.cursor_y = self.height - 1;
                }
                if (self.cursor_x >= self.width) {
                    self.cursor_x = self.width - 1;
                }
            },
            's' => {
                // Save cursor position (DEC)
                self.saved_cursor_x = self.cursor_x;
                self.saved_cursor_y = self.cursor_y;
            },
            'u' => {
                // Restore cursor position (DEC)
                self.cursor_x = self.saved_cursor_x;
                self.cursor_y = self.saved_cursor_y;
                if (self.cursor_x >= self.width) {
                    self.cursor_x = self.width - 1;
                }
                if (self.cursor_y >= self.height) {
                    self.cursor_y = self.height - 1;
                }
            },
            'E' => {
                // Cursor Next Line (move to beginning of next line)
                const n = self.parse_csi_param(params, 1);
                self.cursor_y += n;
                self.cursor_x = 0;
                if (self.cursor_y >= self.height) {
                    self.cursor_y = self.height - 1;
                }
            },
            'F' => {
                // Cursor Previous Line (move to beginning of previous
line)
                const n = self.parse_csi_param(params, 1);
                if (self.cursor_y >= n) {
                    self.cursor_y -= n;
                } else {
                    self.cursor_y = 0;
                }
                self.cursor_x = 0;
            },
            'G' => {
                // Cursor Horizontal Absolute (move to column)
                const n = self.parse_csi_param(params, 1);
                if (n > 0) {
                    self.cursor_x = n - 1;
                } else {
                    self.cursor_x = 0;
                }
                if (self.cursor_x >= self.width) {
                    self.cursor_x = self.width - 1;
                }
            },
            'd' => {
                // Cursor Vertical Absolute (move to row)
                const n = self.parse_csi_param(params, 1);
                if (n > 0) {
                    self.cursor_y = n - 1;
                } else {
                    self.cursor_y = 0;
                }
                if (self.cursor_y >= self.height) {
                    self.cursor_y = self.height - 1;
                }
            },
            'n' => {
                // Device Status Report (DSR) - respond with cursor
position
                // Format: ESC [ row ; col R
                // For now, we ignore (would need output mechanism)
                _ = params;
                _ = self;
            },
            'h' => {
                // Set Mode (SM) - enable terminal features
                // For now, we ignore most modes
                _ = params;
            },
            'l' => {
                // Reset Mode (RM) - disable terminal features
                // For now, we ignore most modes
                _ = params;
            },
            'J' => {
                // Erase in Display
                const n = self.parse_csi_param(params, 0);
                self.erase_display(n, cells);
            },
            'K' => {
                // Erase in Line
                const n = self.parse_csi_param(params, 0);
                self.erase_line(n, cells);
            },
            'm' => {
                // Select Graphic Rendition (SGR)
                self.handle_sgr_sequence(params);
            },
            '@' => {
                // Insert Character (ICH) - insert blank characters at
cursor
                const n = self.parse_csi_param(params, 1);
                self.insert_characters(n, cells);
            },
            'P' => {
                // Delete Character (DCH) - delete characters at cursor
                const n = self.parse_csi_param(params, 1);
                self.delete_characters(n, cells);
            },
            'L' => {
                // Insert Line (IL) - insert blank lines at cursor
                const n = self.parse_csi_param(params, 1);
                self.insert_lines(n, cells);
            },
            'M' => {
                // Delete Line (DL) - delete lines at cursor
                const n = self.parse_csi_param(params, 1);
                self.delete_lines(n, cells);
            },
            'r' => {
                // Set Scrolling Region (DECSTBM) - CSI <top> ; <bottom>
r
                self.set_scrolling_region(params);
            },
            'g' => {
                // Tab Clear (TBC) - clear tab stop
                // 0: clear tab stop at current column
                // 3: clear all tab stops
                const n = self.parse_csi_param(params, 0);
                if (n == 0) {
                    // Clear tab stop at current column
                    if (self.cursor_x < MAX_WIDTH) {
                        self.tab_stops[self.cursor_x] = false;
                    }
                } else if (n == 3) {
                    // Clear all tab stops
                    var i: u32 = 0;
                    while (i < MAX_WIDTH) : (i += 1) {
                        self.tab_stops[i] = false;
                    }
                }
            },
            else => {
                // Unknown CSI sequence, ignore
            },
        }
    }

    /// Handle OSC (Operating System Command) sequence.
    // 2025-11-24-180000-pst: Active function
    fn handle_osc_sequence(self: *Terminal) void {
        // Assert: Escape buffer must have content
        std.debug.assert(self.escape_len > 0);

        // Parse OSC sequence: ESC ] <number> ; <text> BEL/ESC
        // Common sequences:
        // 0: Set window title and icon name
        // 1: Set icon name
        // 2: Set window title
        if (self.escape_len < 2) {
            return;
        }

        // Parse number (first character should be digit)
        var num_start: u32 = 0;
        while (num_start < self.escape_len and
self.escape_buffer[num_start] == ' ') : (num_start += 1) {}
        if (num_start >= self.escape_len) {
            return;
        }

        // Find semicolon
        var semicolon_idx: u32 = num_start;
        while (semicolon_idx < self.escape_len and
self.escape_buffer[semicolon_idx] != ';') : (semicolon_idx += 1) {}
        if (semicolon_idx >= self.escape_len) {
            return;
        }

        // Parse number
        const num_str = self.escape_buffer[num_start..semicolon_idx];
        const osc_code = self.parse_number(num_str, 0);

        // Get text (after semicolon, before BEL/ESC)
        const text_start = semicolon_idx + 1;
        const text_end = self.escape_len;
        if (text_start >= text_end) {
            return;
        }

        // Handle window title sequences (0, 2)
        if (osc_code == 0 or osc_code == 2) {
            const text = self.escape_buffer[text_start..text_end];
            const copy_len = @min(text.len, 255);
            @memset(self.window_title[0..], 0);
            @memcpy(self.window_title[0..copy_len], text[0..copy_len]);
            self.window_title_len = copy_len;
        }
        // Icon name (1) is ignored for now
    }

    /// Set scrolling region (DECSTBM).
    // 2025-11-24-212700-pst: Active function
    fn set_scrolling_region(self: *Terminal, params: []const u8) void {
        // Parse parameters: CSI <top> ; <bottom> r
        // Default: top = 1, bottom = height
        if (params.len == 0) {
            // Reset to full screen
            self.scroll_top = 0;
            self.scroll_bottom = self.height;
            return;
        }

        // Parse parameters (handle semicolon-separated)
        var params_list: [2]u32 = undefined;
        var params_count: u32 = 0;
        var params_iter = std.mem.splitScalar(u8, params, ';');
        while (params_iter.next()) |param_str| {
            if (params_count >= 2) {
                break; // Bounded: max 2 parameters
            }
            const code = self.parse_number(param_str, 0);
            params_list[params_count] = code;
            params_count += 1;
        }

        // Set scrolling region (1-based to 0-based conversion)
        if (params_count >= 1) {
            const top = params_list[0];
            if (top > 0) {
                self.scroll_top = top - 1;
            } else {
                self.scroll_top = 0;
            }
        } else {
            self.scroll_top = 0;
        }

        if (params_count >= 2) {
            const bottom = params_list[1];
            if (bottom > 0) {
                self.scroll_bottom = bottom;
            } else {
                self.scroll_bottom = self.height;
            }
        } else {
            self.scroll_bottom = self.height;
        }

        // Bounds checking
        if (self.scroll_top >= self.height) {
            self.scroll_top = self.height - 1;
        }
        if (self.scroll_bottom > self.height) {
            self.scroll_bottom = self.height;
        }
        if (self.scroll_top >= self.scroll_bottom) {
            self.scroll_top = 0;
            self.scroll_bottom = self.height;
        }

        // Move cursor to home position (top-left of scrolling region)
        self.cursor_x = 0;
        self.cursor_y = self.scroll_top;
    }

    /// Handle tab character (move to next tab stop).
    // 2025-11-24-215700-pst: Active function
    fn handle_tab(self: *Terminal) void {
        // Find next tab stop
        var x: u32 = self.cursor_x + 1;
        while (x < self.width and x < MAX_WIDTH) : (x += 1) {
            if (self.tab_stops[x]) {
                self.cursor_x = x;
                return;
            }
        }
        // No tab stop found, move to end of line
        self.cursor_x = self.width - 1;
    }

    /// Handle Set Mode (SM) - CSI ? <n> h (DEC private modes).
    // 2025-11-24-214900-pst: Active function
    fn handle_set_mode(self: *Terminal, params: []const u8) void {
        // Parse parameters (handle semicolon-separated)
        var params_list: [16]u32 = undefined;
        var params_count: u32 = 0;
        var params_iter = std.mem.splitScalar(u8, params, ';');
        while (params_iter.next()) |param_str| {
            if (params_count >= 16) {
                break; // Bounded: max 16 parameters
            }
            const code = self.parse_number(param_str, 0);
            params_list[params_count] = code;
            params_count += 1;
        }

        // Process parameters
        var i: u32 = 0;
        while (i < params_count) : (i += 1) {
            const code = params_list[i];
            // Check if DEC private mode (starts with ?)
            if (i == 0 and params.len > 0 and params[0] == '?') {
                // DEC private modes
                switch (code) {
                    1 => {
                        // DECCKM - Cursor Keys Mode (application keys)
                        self.dec_ckm = true;
                    },
                    6 => {
                        // DECOM - Origin Mode (relative origin)
                        self.dec_om = true;
                    },
                    7 => {
                        // DECAWM - Auto Wrap Mode (wrap at right margin)
                        self.dec_awm = true;
                    },
                    25 => {
                        // DECTCEM - Text Cursor Enable Mode (show
cursor)
                        self.dec_tcem = true;
                    },
                    else => {
                        // Unknown DEC private mode, ignore
                    },
                }
            } else {
                // ANSI modes (not implemented yet)
                _ = code;
            }
        }
    }

