        _ = self;
        _ = language;

        return false;
    }

    /// Add breakpoint.
    // 2025-12-04-131701-pst: Active function
    pub fn add_breakpoint(
        self: *DevToolsApp,
        file_path: []const u8,
        line_number: u32,
    ) ?u32 {
        // Precondition: Must have space for breakpoint
        std.debug.assert(self.breakpoints_len < MAX_BREAKPOINTS);
        std.debug.assert(file_path.len > 0);
        std.debug.assert(file_path.len <= MAX_FILE_PATH_LEN);
        std.debug.assert(line_number > 0);

        const breakpoint_id = self.breakpoints_len + 1;
        var bp = Breakpoint{
            .breakpoint_id = breakpoint_id,
            .file_path = undefined,
            .file_path_len = @as(u32, @intCast(file_path.len)),
            .line_number = line_number,
            .enabled = true,
            .hit_count = 0,
        };

        // Set file path
        @memset(&bp.file_path, 0);
        const path_len = @min(file_path.len, MAX_FILE_PATH_LEN);
        @memcpy(bp.file_path[0..path_len], file_path[0..path_len]);
        bp.file_path_len = @as(u32, @intCast(path_len));

        self.breakpoints[self.breakpoints_len] = bp;
        self.breakpoints_len += 1;

        // Postcondition: Breakpoint count increased
        std.debug.assert(self.breakpoints_len > 0);
        std.debug.assert(self.breakpoints_len <= MAX_BREAKPOINTS);

        return breakpoint_id;
    }

    /// Remove breakpoint.
    // 2025-12-04-131701-pst: Active function
    pub fn remove_breakpoint(
        self: *DevToolsApp,
        breakpoint_id: u32,
    ) bool {
        // Precondition: Breakpoint ID must be valid
        std.debug.assert(breakpoint_id > 0);

        var i: u32 = 0;
        while (i < self.breakpoints_len) : (i += 1) {
            if (self.breakpoints[i]) |bp| {
                if (bp.breakpoint_id == breakpoint_id) {
                    // Shift remaining breakpoints left
                    var j: u32 = i;
                    while (j + 1 < self.breakpoints_len) : (j += 1) {
                        self.breakpoints[j] = self.breakpoints[j + 1];
                    }
                    self.breakpoints_len -= 1;
                    self.breakpoints[self.breakpoints_len] = null;
                    return true;
                }
            }
        }

        return false;
    }

    /// Add watchpoint.
    // 2025-12-04-131701-pst: Active function
    pub fn add_watchpoint(
        self: *DevToolsApp,
        variable_name: []const u8,
        expression: []const u8,
    ) ?u32 {
        // Precondition: Must have space for watchpoint
        std.debug.assert(self.watchpoints_len < MAX_WATCHPOINTS);
        std.debug.assert(variable_name.len > 0);
        std.debug.assert(variable_name.len <= 64);
        std.debug.assert(expression.len <= 256);

        const watchpoint_id = self.watchpoints_len + 1;
        var wp = Watchpoint{
            .watchpoint_id = watchpoint_id,
            .variable_name = undefined,
            .variable_name_len = @as(u32, @intCast(variable_name.len)),
            .expression = undefined,
            .expression_len = @as(u32, @intCast(expression.len)),
            .enabled = true,
        };

        // Set variable name
        @memset(&wp.variable_name, 0);
        const var_len = @min(variable_name.len, 64);
        @memcpy(wp.variable_name[0..var_len], variable_name[0..var_len]);
        wp.variable_name_len = @as(u32, @intCast(var_len));

        // Set expression
        @memset(&wp.expression, 0);
        const expr_len = @min(expression.len, 256);
        if (expr_len > 0) {
            @memcpy(wp.expression[0..expr_len], expression[0..expr_len]);
        }
        wp.expression_len = @as(u32, @intCast(expr_len));

        self.watchpoints[self.watchpoints_len] = wp;
        self.watchpoints_len += 1;

        // Postcondition: Watchpoint count increased
        std.debug.assert(self.watchpoints_len > 0);
        std.debug.assert(self.watchpoints_len <= MAX_WATCHPOINTS);

        return watchpoint_id;
    }

    /// Add linter message.
    // 2025-12-04-131701-pst: Active function
    pub fn add_linter_message(
        self: *DevToolsApp,
        file_path: []const u8,
        line_number: u32,
        column_number: u32,
        severity: LinterSeverity,
        message: []const u8,
    ) bool {
        // Precondition: Must have space for message
        std.debug.assert(self.linter_messages_len < 256);
        std.debug.assert(file_path.len > 0);
        std.debug.assert(file_path.len <= MAX_FILE_PATH_LEN);
        std.debug.assert(message.len > 0);
        std.debug.assert(message.len <= 256);

        var msg = LinterMessage{
            .file_path = undefined,
            .file_path_len = @as(u32, @intCast(file_path.len)),
            .line_number = line_number,
            .column_number = column_number,
            .severity = severity,
            .message = undefined,
            .message_len = @as(u32, @intCast(message.len)),
        };

        // Set file path
        @memset(&msg.file_path, 0);
        const path_len = @min(file_path.len, MAX_FILE_PATH_LEN);
        @memcpy(msg.file_path[0..path_len], file_path[0..path_len]);
        msg.file_path_len = @as(u32, @intCast(path_len));

        // Set message
        @memset(&msg.message, 0);
        const msg_len = @min(message.len, 256);
        @memcpy(msg.message[0..msg_len], message[0..msg_len]);
        msg.message_len = @as(u32, @intCast(msg_len));

        self.linter_messages[self.linter_messages_len] = msg;
        self.linter_messages_len += 1;

        // Postcondition: Message count increased
        std.debug.assert(self.linter_messages_len > 0);
        std.debug.assert(self.linter_messages_len <= 256);

        return true;
    }

    /// Add test result.
    // 2025-12-04-131701-pst: Active function
    pub fn add_test_result(
        self: *DevToolsApp,
        test_name: []const u8,
        file_path: []const u8,
        passed: bool,
        execution_time_ms: u64,
        error_message: []const u8,
    ) bool {
        // Precondition: Must have space for test result
        std.debug.assert(self.test_results_len < MAX_TEST_FILES);
        std.debug.assert(test_name.len > 0);
        std.debug.assert(test_name.len <= 128);
        std.debug.assert(file_path.len > 0);
        std.debug.assert(file_path.len <= MAX_FILE_PATH_LEN);
        std.debug.assert(error_message.len <= 256);

        var result = TestResult{
            .test_name = undefined,
            .test_name_len = @as(u32, @intCast(test_name.len)),
            .file_path = undefined,
            .file_path_len = @as(u32, @intCast(file_path.len)),
            .passed = passed,
            .execution_time_ms = execution_time_ms,
            .error_message = undefined,
            .error_message_len = @as(u32, @intCast(error_message.len)),
        };

        // Set test name
        @memset(&result.test_name, 0);
        const name_len = @min(test_name.len, 128);
        @memcpy(result.test_name[0..name_len], test_name[0..name_len]);
        result.test_name_len = @as(u32, @intCast(name_len));

        // Set file path
        @memset(&result.file_path, 0);
        const path_len = @min(file_path.len, MAX_FILE_PATH_LEN);
        @memcpy(result.file_path[0..path_len], file_path[0..path_len]);
        result.file_path_len = @as(u32, @intCast(path_len));

        // Set error message
        @memset(&result.error_message, 0);
        const err_len = @min(error_message.len, 256);
        if (err_len > 0) {
            @memcpy(result.error_message[0..err_len],
error_message[0..err_len]);
        }
        result.error_message_len = @as(u32, @intCast(err_len));

        self.test_results[self.test_results_len] = result;
        self.test_results_len += 1;

        // Postcondition: Test result count increased
        std.debug.assert(self.test_results_len > 0);
        std.debug.assert(self.test_results_len <= MAX_TEST_FILES);

        return true;
    }

    /// Add profiler sample.
    // 2025-12-04-131701-pst: Active function
    pub fn add_profiler_sample(
        self: *DevToolsApp,
        function_name: []const u8,
        file_path: []const u8,
        line_number: u32,
        execution_time_us: u64,
        memory_used_bytes: u64,
        call_count: u32,
    ) bool {
        // Precondition: Must have space for sample
        std.debug.assert(self.profiler_samples_len < 256);
        std.debug.assert(function_name.len > 0);
        std.debug.assert(function_name.len <= 128);
        std.debug.assert(file_path.len > 0);
        std.debug.assert(file_path.len <= MAX_FILE_PATH_LEN);

        var sample = ProfilerSample{
            .function_name = undefined,
            .function_name_len = @as(u32, @intCast(function_name.len)),
            .file_path = undefined,
            .file_path_len = @as(u32, @intCast(file_path.len)),
            .line_number = line_number,
            .execution_time_us = execution_time_us,
            .memory_used_bytes = memory_used_bytes,
            .call_count = call_count,
        };

        // Set function name
        @memset(&sample.function_name, 0);
        const func_len = @min(function_name.len, 128);
        @memcpy(sample.function_name[0..func_len],
function_name[0..func_len]);
        sample.function_name_len = @as(u32, @intCast(func_len));

        // Set file path
        @memset(&sample.file_path, 0);
        const path_len = @min(file_path.len, MAX_FILE_PATH_LEN);
        @memcpy(sample.file_path[0..path_len], file_path[0..path_len]);
        sample.file_path_len = @as(u32, @intCast(path_len));

        self.profiler_samples[self.profiler_samples_len] = sample;
        self.profiler_samples_len += 1;

        // Postcondition: Sample count increased
        std.debug.assert(self.profiler_samples_len > 0);
        std.debug.assert(self.profiler_samples_len <= 256);

        return true;
    }

    /// Clear all breakpoints.
    // 2025-12-04-131701-pst: Active function
    pub fn clear_breakpoints(self: *DevToolsApp) void {
        // Precondition: App must be valid
        std.debug.assert(@intFromPtr(self) != 0);

        self.breakpoints_len = 0;
        var i: u32 = 0;
        while (i < MAX_BREAKPOINTS) : (i += 1) {
            self.breakpoints[i] = null;
        }

        // Postcondition: Breakpoints must be cleared
        std.debug.assert(self.breakpoints_len == 0);
    }

    /// Clear all linter messages.
    // 2025-12-04-131701-pst: Active function
    pub fn clear_linter_messages(self: *DevToolsApp) void {
        // Precondition: App must be valid
        std.debug.assert(@intFromPtr(self) != 0);

        self.linter_messages_len = 0;
        var i: u32 = 0;
        while (i < 256) : (i += 1) {
            self.linter_messages[i] = null;
        }

        // Postcondition: Messages must be cleared
        std.debug.assert(self.linter_messages_len == 0);
    }
};


// === grain_workspace/file_manager/app.zig ===

//! Grain File Manager: Graphical file system browser.
//!
//! Why: Provide GUI for file browsing and operations.
//! Architecture: File browsing, operations, preview, search.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-04-092542-pst: Active implementation
//! 2025-12-07-025947-pst: Phase 10.4 WebSocket integration for
real-time file system notifications
//! 2025-12-07-071409-pst: Phase 13 File Storage integration for
database file support
//! 2025-12-07-084440-pst: Phase 14 Backup Manager integration for data
protection

const std = @import("std");
const grain_core = @import("grain_core");

// Bounded: Max search results (explicit limit)
// 2025-12-04-092542-pst: Active constant
pub const MAX_SEARCH_RESULTS: u32 = 256;

// Bounded: Max preview size (explicit limit, in bytes)
// 2025-12-04-092542-pst: Active constant
pub const MAX_PREVIEW_SIZE: u32 = 8192;

// Bounded: Max clipboard entries (explicit limit)
// 2025-12-04-092542-pst: Active constant
pub const MAX_CLIPBOARD_ENTRIES: u32 = 16;

// Bounded: Max WebSocket clients (explicit limit)
// 2025-12-07-025947-pst: Phase 10.4 WebSocket integration
pub const MAX_WEBSOCKET_CLIENTS: u32 = 32;

// Bounded: Max database file handles (explicit limit)
// 2025-12-07-071409-pst: Phase 13 File Storage integration
pub const MAX_DATABASE_FILE_HANDLES: u32 = 32;

// Bounded: Max backup operations (explicit limit)
// 2025-12-07-084440-pst: Phase 14 Backup Manager integration
pub const MAX_BACKUP_OPERATIONS: u32 = 16;

// File operation type.
// 2025-12-04-092542-pst: Active enum
pub const FileOperation = enum(u8) {
    copy, // Copy file
    move, // Move file
    delete, // Delete file
    rename, // Rename file
};

// Clipboard entry for copy/move operations.
// 2025-12-04-092542-pst: Active struct
pub const ClipboardEntry = struct {
    entry_id: u32,
    operation: FileOperation,
    path: [grain_core.file_manager.MAX_PATH_LEN]u8,
    path_len: u32,
};

// Database file handle tracking.
// 2025-12-07-071409-pst: Phase 13 File Storage integration
pub const DatabaseFileHandle = struct {
    handle_id: u32,
    entry_id: u32,
    filename: [grain_core.file_storage.MAX_FILENAME_LEN]u8,
    filename_len: u32,
    active: bool,
};

// Backup operation tracking.
// 2025-12-07-084440-pst: Phase 14 Backup Manager integration
pub const BackupOperation = struct {
    operation_id: u32,
    entry_id: u32,
    backup_id: u32,
    backup_type: grain_core.backup_manager.BackupType,
    state: grain_core.backup_manager.BackupState,
    active: bool,
};

// File Manager UI application state.
// 2025-12-04-092542-pst: Active struct
// 2025-12-07-025947-pst: Phase 10.4 WebSocket integration
// 2025-12-07-071409-pst: Phase 13 File Storage integration
// 2025-12-07-084440-pst: Phase 14 Backup Manager integration
pub const FileManagerUI = struct {
    file_manager: *grain_core.file_manager.FileManager,
    file_storage_manager: *grain_core.file_storage.FileStorageManager,
    backup_manager: *grain_core.backup_manager.BackupManager,
    search_query: [grain_core.file_manager.MAX_NAME_LEN]u8,
    search_query_len: u32,
    selected_entry_id: u32,
    clipboard: [MAX_CLIPBOARD_ENTRIES]?ClipboardEntry,
    clipboard_len: u32,
    preview_buffer: [MAX_PREVIEW_SIZE]u8,
    preview_size: u32,
    websocket_manager: *grain_core.websocket.WebSocketManager,
    websocket_clients: [MAX_WEBSOCKET_CLIENTS]u32,
    websocket_clients_len: u32,
    database_file_handles:
[MAX_DATABASE_FILE_HANDLES]?DatabaseFileHandle,
    database_file_handles_len: u32,
    backup_operations: [MAX_BACKUP_OPERATIONS]?BackupOperation,
    backup_operations_len: u32,
    next_backup_operation_id: u32,
    allocator: std.mem.Allocator,

    /// Initialize file manager UI.
    // 2025-12-04-092542-pst: Active function
    // 2025-12-07-025947-pst: Phase 10.4 WebSocket integration
    // 2025-12-07-071409-pst: Phase 13 File Storage integration
    // 2025-12-07-084440-pst: Phase 14 Backup Manager integration
    pub fn init(
        allocator: std.mem.Allocator,
        fm: *grain_core.file_manager.FileManager,
        ws_manager: *grain_core.websocket.WebSocketManager,
        storage_mgr: *grain_core.file_storage.FileStorageManager,
        backup_mgr: *grain_core.backup_manager.BackupManager,
    ) FileManagerUI {
        // Precondition: Allocator and managers must be valid
        std.debug.assert(allocator.ptr != null);
        std.debug.assert(@intFromPtr(fm) != 0);
        std.debug.assert(@intFromPtr(ws_manager) != 0);
        std.debug.assert(@intFromPtr(storage_mgr) != 0);
        std.debug.assert(@intFromPtr(backup_mgr) != 0);

        var ui = FileManagerUI{
            .file_manager = fm,
            .file_storage_manager = storage_mgr,
            .backup_manager = backup_mgr,
            .search_query = undefined,
            .search_query_len = 0,
            .selected_entry_id = 0,
            .clipboard = undefined,
            .clipboard_len = 0,
            .preview_buffer = undefined,
            .preview_size = 0,
            .websocket_manager = ws_manager,
            .websocket_clients = undefined,
            .websocket_clients_len = 0,
            .database_file_handles = undefined,
            .database_file_handles_len = 0,
            .backup_operations = undefined,
            .backup_operations_len = 0,
            .next_backup_operation_id = 1,
            .allocator = allocator,
        };

        // Initialize search query
        @memset(&ui.search_query, 0);

        // Initialize clipboard
        var i: u32 = 0;
        while (i < MAX_CLIPBOARD_ENTRIES) : (i += 1) {
            ui.clipboard[i] = null;
        }

        // Initialize preview buffer
        @memset(&ui.preview_buffer, 0);

        // Initialize WebSocket clients array
        i = 0;
        while (i < MAX_WEBSOCKET_CLIENTS) : (i += 1) {
            ui.websocket_clients[i] = 0;
        }

        // Initialize database file handles array
        i = 0;
        while (i < MAX_DATABASE_FILE_HANDLES) : (i += 1) {
            ui.database_file_handles[i] = null;
        }

        // Initialize backup operations array
        i = 0;
        while (i < MAX_BACKUP_OPERATIONS) : (i += 1) {
            ui.backup_operations[i] = null;
        }

        // Postcondition: UI must be valid
        std.debug.assert(ui.search_query_len == 0);
        std.debug.assert(ui.clipboard_len == 0);
        std.debug.assert(ui.websocket_clients_len == 0);
        std.debug.assert(ui.database_file_handles_len == 0);
        std.debug.assert(ui.backup_operations_len == 0);

        return ui;
    }

    /// Set search query.
    // 2025-12-04-092542-pst: Active function
    pub fn set_search_query(
        self: *FileManagerUI,
        query: []const u8,
    ) void {
        // Precondition: Query must be bounded
        std.debug.assert(query.len <=
grain_core.file_manager.MAX_NAME_LEN);

        @memset(&self.search_query, 0);
        const query_len = @min(query.len,
grain_core.file_manager.MAX_NAME_LEN);
        if (query_len > 0) {
            @memcpy(self.search_query[0..query_len],
query[0..query_len]);
        }
        self.search_query_len = @as(u32, @intCast(query_len));

        // Postcondition: Query must be valid
        std.debug.assert(self.search_query_len <=
grain_core.file_manager.MAX_NAME_LEN);
    }

    /// Navigate to directory.
    // 2025-12-04-092542-pst: Active function
    pub fn navigate_to_directory(
        self: *FileManagerUI,
        path: []const u8,
    ) bool {
        // Precondition: Path must be valid
        std.debug.assert(path.len > 0);

        const result = self.file_manager.set_current_directory(path);
        if (result) {
            self.selected_entry_id = 0;
            // Broadcast directory change to WebSocket clients
            self.broadcast_directory_change(path);
        }

        // Postcondition: Directory must be set if successful
        std.debug.assert(!result or
self.file_manager.current_directory_len > 0);

        return result;
    }

    /// Get current directory.
    // 2025-12-04-092542-pst: Active function
    pub fn get_current_directory(self: *const FileManagerUI) []const u8 {
        // Precondition: File manager must be valid
        std.debug.assert(@intFromPtr(self.file_manager) != 0);

        return self.file_manager.get_current_directory();
    }

    /// Get file entries in current directory.
    // 2025-12-04-092542-pst: Active function
    pub fn get_file_entries(
        self: *const FileManagerUI,
        entries: []*grain_core.file_manager.FileEntry,
        entries_len: *u32,
    ) void {
        // Precondition: Entries buffer must be valid
        std.debug.assert(entries.len > 0);
        std.debug.assert(entries_len != null);

        entries_len.* = 0;

        var i: u32 = 0;
        while (i < self.file_manager.files_len and entries_len.* <
entries.len) : (i += 1) {
            const entry = &self.file_manager.files[i];
            if (entry.active) {
                entries[entries_len.*] = entry;
                entries_len.* += 1;
            }
        }
    }

    /// Search files by name.
    // 2025-12-04-092542-pst: Active function
    pub fn search_files(
        self: *const FileManagerUI,
        results: []u32,
        results_len: *u32,
    ) void {
        // Precondition: Results buffer must be valid
        std.debug.assert(results.len > 0);
        std.debug.assert(results_len != null);

        results_len.* = 0;

        if (self.search_query_len == 0) {
            return;
        }

        const query_slice = self.search_query[0..self.search_query_len];
        var i: u32 = 0;
        while (i < self.file_manager.files_len and results_len.* <
results.len) : (i += 1) {
            const entry = &self.file_manager.files[i];
            if (!entry.active) {
                continue;
            }

            // Search in name
            const name_slice = entry.name[0..entry.name_len];
            if (std.mem.indexOf(u8, name_slice, query_slice) != null) {
                results[results_len.*] = entry.entry_id;
                results_len.* += 1;
            }
        }
    }

    /// Copy file to clipboard.
    // 2025-12-04-092542-pst: Active function
    pub fn copy_to_clipboard(
        self: *FileManagerUI,
        entry_id: u32,
    ) bool {
        // Precondition: Entry ID and clipboard space must be valid
        std.debug.assert(entry_id > 0);
        std.debug.assert(self.clipboard_len < MAX_CLIPBOARD_ENTRIES);

        const entry = self.file_manager.find_file_entry(entry_id);
        if (entry == null) {
            return false;
        }

        const path_slice = entry.?.path[0..entry.?.path_len];
        var clipboard_entry = ClipboardEntry{
            .entry_id = entry_id,
            .operation = .copy,
            .path = undefined,
            .path_len = @as(u32, @intCast(path_slice.len)),
        };

        @memset(&clipboard_entry.path, 0);
        @memcpy(clipboard_entry.path[0..path_slice.len], path_slice);

        self.clipboard[self.clipboard_len] = clipboard_entry;
        self.clipboard_len += 1;

        // Postcondition: Clipboard must have entry
        std.debug.assert(self.clipboard_len > 0);

        return true;
    }

    /// Move file to clipboard.
    // 2025-12-04-092542-pst: Active function
    pub fn move_to_clipboard(
        self: *FileManagerUI,
        entry_id: u32,
    ) bool {
        // Precondition: Entry ID and clipboard space must be valid
        std.debug.assert(entry_id > 0);
        std.debug.assert(self.clipboard_len < MAX_CLIPBOARD_ENTRIES);

        const entry = self.file_manager.find_file_entry(entry_id);
        if (entry == null) {
            return false;
        }

        const path_slice = entry.?.path[0..entry.?.path_len];
        var clipboard_entry = ClipboardEntry{
            .entry_id = entry_id,
            .operation = .move,
            .path = undefined,
            .path_len = @as(u32, @intCast(path_slice.len)),
        };

        @memset(&clipboard_entry.path, 0);
        @memcpy(clipboard_entry.path[0..path_slice.len], path_slice);

        self.clipboard[self.clipboard_len] = clipboard_entry;
        self.clipboard_len += 1;

        // Postcondition: Clipboard must have entry
        std.debug.assert(self.clipboard_len > 0);

        return true;
    }

    /// Paste files from clipboard.
    // 2025-12-04-092542-pst: Active function
    pub fn paste_from_clipboard(
        self: *FileManagerUI,
        destination_path: []const u8,
    ) u32 {
        // Precondition: Destination path must be valid
        std.debug.assert(destination_path.len > 0);
        std.debug.assert(destination_path.len <=
grain_core.file_manager.MAX_PATH_LEN);

        var pasted_count: u32 = 0;

        var i: u32 = 0;
        while (i < self.clipboard_len) : (i += 1) {
            if (self.clipboard[i]) |clip_entry| {
                const source_path =
clip_entry.path[0..clip_entry.path_len];
                if (clip_entry.operation == .copy) {
                    // Copy operation (would implement actual file copy)
                    pasted_count += 1;
                } else if (clip_entry.operation == .move) {
                    // Move operation (would implement actual file move)
                    pasted_count += 1;
                }
            }
        }

        // Clear clipboard after paste
        self.clipboard_len = 0;
        var j: u32 = 0;
        while (j < MAX_CLIPBOARD_ENTRIES) : (j += 1) {
            self.clipboard[j] = null;
        }

        // Postcondition: Clipboard must be cleared
        std.debug.assert(self.clipboard_len == 0);

        return pasted_count;
    }

    /// Delete file.
    // 2025-12-04-092542-pst: Active function
    pub fn delete_file(
        self: *FileManagerUI,
        entry_id: u32,
    ) bool {
        // Precondition: Entry ID must be valid
        std.debug.assert(entry_id > 0);

        const result = self.file_manager.remove_file_entry(entry_id);
        if (result) {
            if (self.selected_entry_id == entry_id) {
                self.selected_entry_id = 0;
            }
            // Broadcast file deletion to WebSocket clients
            self.broadcast_file_event("delete", entry_id);
        }

        // Postcondition: Entry must be removed if successful
        std.debug.assert(!result or
self.file_manager.find_file_entry(entry_id) == null);

        return result;
    }

    /// Rename file.
    // 2025-12-04-092542-pst: Active function
    pub fn rename_file(
        self: *FileManagerUI,
        entry_id: u32,
        new_name: []const u8,
    ) bool {
        // Precondition: Entry ID and name must be valid
        std.debug.assert(entry_id > 0);
        std.debug.assert(new_name.len > 0);
        std.debug.assert(new_name.len <=
grain_core.file_manager.MAX_NAME_LEN);

        const entry = self.file_manager.find_file_entry(entry_id);
        if (entry == null) {
            return false;
        }

        // Update name
        @memset(&entry.?.name, 0);
        const name_len = @min(new_name.len,
grain_core.file_manager.MAX_NAME_LEN);
        @memcpy(entry.?.name[0..name_len], new_name[0..name_len]);
        entry.?.name_len = @as(u32, @intCast(name_len));

        // Postcondition: Name must be updated
        std.debug.assert(entry.?.name_len == name_len);

        // Broadcast file rename to WebSocket clients
        self.broadcast_file_event("rename", entry_id);

        return true;
    }

    /// Get file preview (text files only).
    // 2025-12-04-092542-pst: Active function
    pub fn get_file_preview(
        self: *FileManagerUI,
        entry_id: u32,
        preview: []u8,
        preview_len: *u32,
    ) bool {
        // Precondition: Preview buffer must be valid
        std.debug.assert(entry_id > 0);
        std.debug.assert(preview.len > 0);
        std.debug.assert(preview_len != null);

        preview_len.* = 0;

        const entry = self.file_manager.find_file_entry(entry_id);
        if (entry == null) {
            return false;
        }

        // Only preview regular files
        if (entry.?.file_type != .regular) {
            return false;
        }

        // Limit preview size
        const max_preview = @min(preview.len, MAX_PREVIEW_SIZE);
        const file_size = @min(entry.?.size, @as(u64, max_preview));

        // In full implementation, would read file content here
        // For now, return empty preview
        preview_len.* = 0;

        return true;
    }

    /// Clear clipboard.
    // 2025-12-04-092542-pst: Active function
    pub fn clear_clipboard(self: *FileManagerUI) void {
        // Precondition: Clipboard must be valid
        std.debug.assert(@intFromPtr(self) != 0);

        self.clipboard_len = 0;
        var i: u32 = 0;
        while (i < MAX_CLIPBOARD_ENTRIES) : (i += 1) {
            self.clipboard[i] = null;
        }

        // Postcondition: Clipboard must be cleared
        std.debug.assert(self.clipboard_len == 0);
    }

    /// Add WebSocket client for real-time file system notifications.
    // 2025-12-07-025947-pst: Phase 10.4 WebSocket integration
    pub fn add_websocket_client(
        self: *FileManagerUI,
        connection_id: u32,
    ) bool {
        // Precondition: Connection ID must be valid
        std.debug.assert(connection_id > 0);
        std.debug.assert(self.websocket_clients_len <
MAX_WEBSOCKET_CLIENTS);

        if (self.websocket_clients_len >= MAX_WEBSOCKET_CLIENTS) {
            return false;
        }

        self.websocket_clients[self.websocket_clients_len] =
connection_id;
        self.websocket_clients_len += 1;

        // Postcondition: Client count increased
        std.debug.assert(self.websocket_clients_len > 0);
        std.debug.assert(self.websocket_clients_len <=
MAX_WEBSOCKET_CLIENTS);

        return true;
    }

    /// Remove WebSocket client.
    // 2025-12-07-025947-pst: Phase 10.4 WebSocket integration
    pub fn remove_websocket_client(
        self: *FileManagerUI,
        connection_id: u32,
    ) bool {
        // Precondition: Connection ID must be valid
        std.debug.assert(connection_id > 0);

        var i: u32 = 0;
        while (i < self.websocket_clients_len) : (i += 1) {
            if (self.websocket_clients[i] == connection_id) {
                var j: u32 = i;
                while (j < self.websocket_clients_len - 1) : (j += 1) {
                    self.websocket_clients[j] = self.websocket_clients[j
+ 1];
                }
                self.websocket_clients_len -= 1;
                return true;
            }
        }

        return false;
    }

    /// Broadcast directory change to WebSocket clients (internal).
    // 2025-12-07-025947-pst: Phase 10.4 WebSocket integration
    fn broadcast_directory_change(
        self: *FileManagerUI,
        path: []const u8,
    ) void {
        // Precondition: Path must be valid
        std.debug.assert(path.len > 0);

        if (self.websocket_clients_len == 0) {
            return;
        }

        // Serialize directory change to JSON-like format (simplified)
        var json_buf: [512]u8 = undefined;
        const json_len = self.serialize_directory_change_json(path,
&json_buf);
        if (json_len == 0) {
            return;
        }

        // Create WebSocket frame
        var frame = grain_core.websocket.WebSocketFrame.init();
        frame.flags.opcode = grain_core.websocket.FrameOpcode.text;
        frame.flags.fin = true;
        frame.flags.masked = false;
        frame.payload_len = @intCast(json_len);

        var i: u32 = 0;
        while (i < json_len and i < grain_core.websocket.MAX_FRAME_SIZE)
: (i += 1) {
            frame.payload[i] = json_buf[i];
        }

        // Broadcast to all clients
        i = 0;
        while (i < self.websocket_clients_len) : (i += 1) {
            const conn_id = self.websocket_clients[i];
            const conn = self.websocket_manager.find_connection(conn_id);
            if (conn != null and conn.?.state ==
grain_core.websocket.ConnectionState.open) {
                // Frame would be sent here (actual send via socket not
implemented)
                _ = frame;
            }
        }
    }

    /// Broadcast file event to WebSocket clients (internal).
    // 2025-12-07-025947-pst: Phase 10.4 WebSocket integration
    fn broadcast_file_event(
        self: *FileManagerUI,
        event_type: []const u8,
        entry_id: u32,
    ) void {
        // Precondition: Event type and entry ID must be valid
        std.debug.assert(event_type.len > 0);
        std.debug.assert(entry_id > 0);

        if (self.websocket_clients_len == 0) {
            return;
        }

        // Serialize file event to JSON-like format (simplified)
        var json_buf: [256]u8 = undefined;
        const json_len = self.serialize_file_event_json(event_type,
entry_id, &json_buf);
        if (json_len == 0) {
            return;
        }

        // Create WebSocket frame
        var frame = grain_core.websocket.WebSocketFrame.init();
        frame.flags.opcode = grain_core.websocket.FrameOpcode.text;
        frame.flags.fin = true;
        frame.flags.masked = false;
        frame.payload_len = @intCast(json_len);

        var i: u32 = 0;
        while (i < json_len and i < grain_core.websocket.MAX_FRAME_SIZE)
: (i += 1) {
            frame.payload[i] = json_buf[i];
        }

        // Broadcast to all clients
        i = 0;
        while (i < self.websocket_clients_len) : (i += 1) {
            const conn_id = self.websocket_clients[i];
            const conn = self.websocket_manager.find_connection(conn_id);
            if (conn != null and conn.?.state ==
grain_core.websocket.ConnectionState.open) {
                // Frame would be sent here (actual send via socket not
implemented)
                _ = frame;
            }
        }
    }

    /// Serialize directory change to JSON format (simplified).
    // 2025-12-07-025947-pst: Phase 10.4 WebSocket integration
    fn serialize_directory_change_json(
        self: *const FileManagerUI,
        path: []const u8,
        buf: []u8,
    ) u32 {
        // Precondition: Buffer must be valid
        std.debug.assert(buf.len >= 512);
        std.debug.assert(path.len > 0);

        _ = self; // Suppress unused warning

        // Simplified JSON serialization (escape path for JSON)
        const path_len = @min(path.len, 200);
        var path_buf: [200]u8 = undefined;
        var path_idx: u32 = 0;
        var i: u32 = 0;
        while (i < path_len and path_idx < 200) : (i += 1) {
            const c = path[i];
            if (c == '"' or c == '\\') {
                if (path_idx + 1 < 200) {
                    path_buf[path_idx] = '\\';
                    path_idx += 1;
                    path_buf[path_idx] = c;
                    path_idx += 1;
                }
            } else {
                path_buf[path_idx] = c;
                path_idx += 1;
            }
        }
        const json_fmt = 
            \\{"event":"directory_change","path":"%.*s"}
        ;
        const written = std.fmt.bufPrint(buf, json_fmt, .{
            path_idx,
            &path_buf,
        }) catch return 0;

        return @intCast(written.len);
    }

    /// Serialize file event to JSON format (simplified).
    // 2025-12-07-025947-pst: Phase 10.4 WebSocket integration
    fn serialize_file_event_json(
        self: *const FileManagerUI,
        event_type: []const u8,
        entry_id: u32,
        buf: []u8,
    ) u32 {
        // Precondition: Buffer must be valid
        std.debug.assert(buf.len >= 256);
        std.debug.assert(event_type.len > 0);
        std.debug.assert(entry_id > 0);

        _ = self; // Suppress unused warning

        // Simplified JSON serialization
        const event_len = @min(event_type.len, 32);
        const json_fmt = 
            \\{"event":"%.*s","entry_id":%d}
        ;
        const written = std.fmt.bufPrint(buf, json_fmt, .{
            event_len,
            event_type.ptr,
            entry_id,
        }) catch return 0;

        return @intCast(written.len);
    }

    /// Open database file for storage operations.
    // 2025-12-07-071409-pst: Phase 13 File Storage integration
    pub fn open_database_file(
        self: *FileManagerUI,
        entry_id: u32,
        mode: grain_core.file_storage.FileMode,
    ) ?u32 {
        // Precondition: Entry ID must be valid
        std.debug.assert(entry_id > 0);
        std.debug.assert(self.database_file_handles_len <
MAX_DATABASE_FILE_HANDLES);

        const entry = self.file_manager.find_file_entry(entry_id);
        if (entry == null) {
            return null;
        }

        if (self.database_file_handles_len >= MAX_DATABASE_FILE_HANDLES)
{
            return null;
        }

        const path_slice = entry.?.path[0..entry.?.path_len];
        const current_time = @as(u64, @intCast(std.time.timestamp()));
        const handle = self.file_storage_manager.open_file(path_slice,
mode, current_time);
        if (handle == null) {
            return null;
        }

        var db_handle = DatabaseFileHandle{
            .handle_id = handle.?.handle_id,
            .entry_id = entry_id,
            .filename = undefined,
            .filename_len = handle.?.filename_len,
            .active = true,
        };

        @memset(&db_handle.filename, 0);
        const filename_len = @min(handle.?.filename_len,
grain_core.file_storage.MAX_FILENAME_LEN);
        @memcpy(db_handle.filename[0..filename_len],
handle.?.filename[0..filename_len]);

        var i: u32 = 0;
        while (i < MAX_DATABASE_FILE_HANDLES) : (i += 1) {
            if (self.database_file_handles[i] == null) {
                self.database_file_handles[i] = db_handle;
                self.database_file_handles_len += 1;
                break;
            }
        }

        // Postcondition: Database file handle must be added
        std.debug.assert(self.database_file_handles_len > 0);

        return handle.?.handle_id;
    }

    /// Close database file.
    // 2025-12-07-071409-pst: Phase 13 File Storage integration
    pub fn close_database_file(
        self: *FileManagerUI,
        handle_id: u32,
    ) bool {
        // Precondition: Handle ID must be valid
        std.debug.assert(handle_id > 0);

        const closed = self.file_storage_manager.close_file(handle_id);
        if (!closed) {
            return false;
        }

        var i: u32 = 0;
        while (i < self.database_file_handles_len) : (i += 1) {
            if (self.database_file_handles[i]) |*db_handle| {
                if (db_handle.handle_id == handle_id) {
                    db_handle.active = false;
                    self.database_file_handles_len -= 1;
                    return true;
                }
            }
        }

        return false;
    }

    /// Get database file handle by entry ID.
    // 2025-12-07-071409-pst: Phase 13 File Storage integration
    pub fn get_database_file_handle(
        self: *const FileManagerUI,
        entry_id: u32,
    ) ?*const DatabaseFileHandle {
        // Precondition: Entry ID must be valid
        std.debug.assert(entry_id > 0);

        var i: u32 = 0;
        while (i < self.database_file_handles_len) : (i += 1) {
            if (self.database_file_handles[i]) |*db_handle| {
                if (db_handle.entry_id == entry_id and db_handle.active)
{
                    return db_handle;
                }
            }
        }

        return null;
    }

    /// Get all open database file handles.
    // 2025-12-07-071409-pst: Phase 13 File Storage integration
    pub fn get_all_database_file_handles(
        self: *const FileManagerUI,
        handles: []?*const DatabaseFileHandle,
        handles_len: *u32,
    ) void {
        // Precondition: Handles buffer must be valid
        std.debug.assert(handles.len > 0);
        std.debug.assert(handles_len != null);

        handles_len.* = 0;

        var i: u32 = 0;
        while (i < self.database_file_handles_len and handles_len.* <
handles.len) : (i += 1) {
            if (self.database_file_handles[i]) |*db_handle| {
                if (db_handle.active) {
                    handles[handles_len.*] = db_handle;
                    handles_len.* += 1;
                }
            }
        }
    }

    /// Check if file is a database file (by extension).
    // 2025-12-07-071409-pst: Phase 13 File Storage integration
    pub fn is_database_file(
        self: *const FileManagerUI,
        entry_id: u32,
    ) bool {
        // Precondition: Entry ID must be valid
        std.debug.assert(entry_id > 0);

        _ = self; // Suppress unused warning

        const entry = self.file_manager.find_file_entry(entry_id);
        if (entry == null) {
            return false;
        }

        const name_slice = entry.?.name[0..entry.?.name_len];
        if (std.mem.endsWith(u8, name_slice, ".db") or
std.mem.endsWith(u8, name_slice, ".sqlite")) {
            return true;
        }

        return false;
    }

    /// Create backup for database file.
    // 2025-12-07-084440-pst: Phase 14 Backup Manager integration
    pub fn create_file_backup(
        self: *FileManagerUI,
        entry_id: u32,
        backup_type: grain_core.backup_manager.BackupType,
    ) ?u32 {
        // Precondition: Entry ID must be valid
        std.debug.assert(entry_id > 0);
        std.debug.assert(self.backup_operations_len <
MAX_BACKUP_OPERATIONS);

        if (self.backup_operations_len >= MAX_BACKUP_OPERATIONS) {
            return null;
        }

        const entry = self.file_manager.find_file_entry(entry_id);
        if (entry == null) {
            return null;
        }

        if (!self.is_database_file(entry_id)) {
            return null;
        }

        const path_slice = entry.?.path[0..entry.?.path_len];
        const timestamp = @as(u64, @intCast(std.time.timestamp()));
        const backup = self.backup_manager.create_backup(backup_type,
path_slice, timestamp);
        if (backup == null) {
            return null;
        }

        const operation_id = self.next_backup_operation_id;
        self.next_backup_operation_id += 1;

        var backup_op = BackupOperation{
            .operation_id = operation_id,
            .entry_id = entry_id,
            .backup_id = backup.?.backup_id,
            .backup_type = backup_type,
            .state = backup.?.state,
            .active = true,
        };

        var i: u32 = 0;
        while (i < MAX_BACKUP_OPERATIONS) : (i += 1) {
            if (self.backup_operations[i] == null) {
                self.backup_operations[i] = backup_op;
                self.backup_operations_len += 1;
                break;
            }
        }

        // Postcondition: Backup operation must be added
        std.debug.assert(self.backup_operations_len > 0);

        return operation_id;
    }

    /// Get backup operation by operation ID.
    // 2025-12-07-084440-pst: Phase 14 Backup Manager integration
    pub fn get_backup_operation(
        self: *const FileManagerUI,
        operation_id: u32,
    ) ?*const BackupOperation {
        // Precondition: Operation ID must be valid
        std.debug.assert(operation_id > 0);

        var i: u32 = 0;
        while (i < self.backup_operations_len) : (i += 1) {
            if (self.backup_operations[i]) |*op| {
                if (op.operation_id == operation_id and op.active) {
                    return op;
                }
            }
        }

        return null;
    }

    /// Get all backup operations for an entry.
    // 2025-12-07-084440-pst: Phase 14 Backup Manager integration
    pub fn get_entry_backup_operations(
        self: *const FileManagerUI,
        entry_id: u32,
        operations: []?*const BackupOperation,
        operations_len: *u32,
    ) void {
        // Precondition: Operations buffer must be valid
        std.debug.assert(entry_id > 0);
        std.debug.assert(operations.len > 0);
        std.debug.assert(operations_len != null);

        operations_len.* = 0;

        var i: u32 = 0;
        while (i < self.backup_operations_len and operations_len.* <
operations.len) : (i += 1) {
            if (self.backup_operations[i]) |*op| {
                if (op.entry_id == entry_id and op.active) {
                    operations[operations_len.*] = op;
                    operations_len.* += 1;
                }
            }
        }
    }

    /// Restore file from backup.
    // 2025-12-07-084440-pst: Phase 14 Backup Manager integration
    pub fn restore_file_from_backup(
        self: *FileManagerUI,
        backup_id: u32,
    ) bool {
        // Precondition: Backup ID must be valid
        std.debug.assert(backup_id > 0);

        const backup = self.backup_manager.find_backup(backup_id);
        if (backup == null) {
            return false;
        }

        if (backup.?.state !=
grain_core.backup_manager.BackupState.completed) {
            return false;
        }

        // Restore would be implemented here (actual restore via file
storage)
        // For now, just verify backup exists and is completed
        return true;
    }

    /// Get backup metadata by backup ID.
    // 2025-12-07-084440-pst: Phase 14 Backup Manager integration
    pub fn get_backup_metadata(
        self: *const FileManagerUI,
        backup_id: u32,
    ) ?*const grain_core.backup_manager.BackupMetadata {
        // Precondition: Backup ID must be valid
        std.debug.assert(backup_id > 0);

        _ = self; // Suppress unused warning

        return self.backup_manager.find_backup(backup_id);
    }

    /// Get all backups for database files.
    // 2025-12-07-084440-pst: Phase 14 Backup Manager integration
    pub fn get_all_backups(
        self: *const FileManagerUI,
        backups: []?*const grain_core.backup_manager.BackupMetadata,
        backups_len: *u32,
    ) void {
        // Precondition: Backups buffer must be valid
        std.debug.assert(backups.len > 0);
        std.debug.assert(backups_len != null);

        backups_len.* = 0;

        var i: u32 = 0;
        while (i < self.backup_manager.backups_len and backups_len.* <
backups.len) : (i += 1) {
            const backup = &self.backup_manager.backups[i];
            if (backup.backup_id > 0) {
                backups[backups_len.*] = backup;
                backups_len.* += 1;
            }
        }
    }
};


// === grain_workspace/monitor/app.zig ===

//! Grain Monitor: System resource monitoring application.
//!
//! Why: Provide real-time system monitoring and resource tracking.
//! Architecture: Process monitoring, resource usage graphs, system
metrics.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-03-164418-pst: Active implementation
//! 2025-12-06-121120-pst: Phase 10.1 WebSocket integration for
real-time updates

const std = @import("std");
const grain_core = @import("grain_core");

// Bounded: Max processes to monitor (explicit limit)
// 2025-12-03-164418-pst: Active constant
pub const MAX_MONITORED_PROCESSES: u32 = 256;

// Bounded: Max history entries (explicit limit)
// 2025-12-03-164418-pst: Active constant
pub const MAX_HISTORY_ENTRIES: u32 = 64;

// Bounded: Max alert thresholds (explicit limit)
// 2025-12-03-164418-pst: Active constant
pub const MAX_ALERT_THRESHOLDS: u32 = 16;

// Bounded: Max WebSocket clients (explicit limit)
// 2025-12-06-121120-pst: Phase 10.1 WebSocket integration
pub const MAX_WEBSOCKET_CLIENTS: u32 = 32;

// Alert threshold structure.
// 2025-12-03-164418-pst: Active struct
pub const AlertThreshold = struct {
    resource_type: ResourceType,
    threshold_value: f64,
    enabled: bool,
};

// Resource type enumeration.
// 2025-12-03-164418-pst: Active enum
pub const ResourceType = enum(u8) {
    cpu, // CPU usage percentage
    memory, // Memory usage percentage
    disk, // Disk usage percentage
    network, // Network bandwidth
};

// Process info structure.
// 2025-12-03-164418-pst: Active struct
pub const ProcessInfo = struct {
    process_id: u32,
    name: []const u8,
    name_len: u32,
    cpu_usage: f64,
    memory_usage: u64,
    state: grain_core.process_manager.ProcessState,
};

// System metrics structure.
// 2025-12-03-164418-pst: Active struct
pub const SystemMetrics = struct {
    uptime: u64, // System uptime in seconds
    load_average: f64, // Load average (1 minute)
    cpu_percent: f64, // Overall CPU usage percentage
    memory_percent: f64, // Memory usage percentage
    disk_percent: f64, // Disk usage percentage
    total_processes: u32,
    running_processes: u32,
    timestamp: u64,
};

// Monitor application state.
// 2025-12-03-164418-pst: Active struct
// 2025-12-06-121120-pst: Phase 10.1 WebSocket integration
pub const MonitorApp = struct {
    process_manager: *grain_core.process_manager.ProcessManager,
    resource_monitor: *grain_core.resource_monitor.ResourceMonitor,
    metrics_history: [MAX_HISTORY_ENTRIES]SystemMetrics,
    metrics_history_len: u32,
    metrics_history_index: u32,
    alert_thresholds: [MAX_ALERT_THRESHOLDS]AlertThreshold,
    alert_thresholds_len: u32,
    websocket_manager: *grain_core.websocket.WebSocketManager,
    websocket_clients: [MAX_WEBSOCKET_CLIENTS]u32,
    websocket_clients_len: u32,
    allocator: std.mem.Allocator,

    /// Initialize monitor application.
    // 2025-12-03-164418-pst: Active function
    // 2025-12-06-121120-pst: Phase 10.1 WebSocket integration
    pub fn init(
        allocator: std.mem.Allocator,
        process_mgr: *grain_core.process_manager.ProcessManager,
        resource_mon: *grain_core.resource_monitor.ResourceMonitor,
        ws_manager: *grain_core.websocket.WebSocketManager,
    ) MonitorApp {
        // Precondition: Allocator and managers must be valid
        std.debug.assert(allocator.ptr != null);
        std.debug.assert(@intFromPtr(process_mgr) != 0);
        std.debug.assert(@intFromPtr(resource_mon) != 0);
        std.debug.assert(@intFromPtr(ws_manager) != 0);

        var app = MonitorApp{
            .process_manager = process_mgr,
            .resource_monitor = resource_mon,
            .metrics_history = undefined,
            .metrics_history_len = 0,
            .metrics_history_index = 0,
            .alert_thresholds = undefined,
            .alert_thresholds_len = 0,
            .websocket_manager = ws_manager,
            .websocket_clients = undefined,
            .websocket_clients_len = 0,
            .allocator = allocator,
        };

        // Initialize metrics history
        var i: u32 = 0;
        while (i < MAX_HISTORY_ENTRIES) : (i += 1) {
            app.metrics_history[i] = SystemMetrics{
                .uptime = 0,
                .load_average = 0.0,
                .cpu_percent = 0.0,
                .memory_percent = 0.0,
                .disk_percent = 0.0,
                .total_processes = 0,
                .running_processes = 0,
                .timestamp = 0,
            };
        }

        // Initialize WebSocket clients
        i = 0;
        while (i < MAX_WEBSOCKET_CLIENTS) : (i += 1) {
            app.websocket_clients[i] = 0;
        }

        // Postcondition: App must be valid
        std.debug.assert(app.metrics_history_len == 0);
        std.debug.assert(app.websocket_clients_len == 0);

        return app;
    }

    /// Update system metrics.
    // 2025-12-03-164418-pst: Active function
    pub fn update_metrics(self: *MonitorApp, uptime: u64) void {
        // Precondition: Uptime must be valid
        std.debug.assert(uptime >= 0);

        const usage = self.resource_monitor.current_usage;
        const timestamp = @as(u64, @intCast(std.time.timestamp()));

        var metrics = SystemMetrics{
            .uptime = uptime,
            .load_average = 0.0, // TODO: Calculate from process count
            .cpu_percent = usage.cpu_percent,
            .memory_percent = if (usage.memory_total > 0) @as(f64,
@floatFromInt(usage.memory_used)) / @as(f64,
@floatFromInt(usage.memory_total)) * 100.0 else 0.0,
            .disk_percent = if (usage.disk_total > 0) @as(f64,
@floatFromInt(usage.disk_used)) / @as(f64,
@floatFromInt(usage.disk_total)) * 100.0 else 0.0,
            .total_processes = usage.total_processes,
            .running_processes = usage.running_processes,
            .timestamp = timestamp,
        };

        // Add to history
        self.metrics_history[self.metrics_history_index] = metrics;
        self.metrics_history_index = (self.metrics_history_index + 1) %
MAX_HISTORY_ENTRIES;
        if (self.metrics_history_len < MAX_HISTORY_ENTRIES) {
            self.metrics_history_len += 1;
        }

        // Check alert thresholds
        self.check_alert_thresholds(&metrics);

        // Broadcast metrics to WebSocket clients
        self.broadcast_metrics_update(&metrics);
    }

    /// Get current system metrics.
    // 2025-12-03-164418-pst: Active function
    pub fn get_current_metrics(self: *const MonitorApp) SystemMetrics {
        // Precondition: Must have metrics
        std.debug.assert(self.metrics_history_len > 0);

        const idx = if (self.metrics_history_index == 0)
MAX_HISTORY_ENTRIES - 1 else self.metrics_history_index - 1;
        const metrics = self.metrics_history[idx];

        // Postcondition: Metrics must be valid
        std.debug.assert(metrics.timestamp > 0);

        return metrics;
    }

    /// Get process information.
    // 2025-12-03-164418-pst: Active function
    pub fn get_process_info(
        self: *const MonitorApp,
        process_id: u32,
        info: *ProcessInfo,
    ) bool {
        // Precondition: Process ID and info must be valid
        std.debug.assert(process_id > 0);
        std.debug.assert(@intFromPtr(info) != 0);

        var i: u32 = 0;
        while (i < self.process_manager.processes_len) : (i += 1) {
            const proc = &self.process_manager.processes[i];
            if (proc.process_id == process_id and proc.active) {
                info.process_id = proc.process_id;
                info.name = &proc.name;
                info.name_len = proc.name_len;
                info.cpu_usage = proc.cpu_usage;
                info.memory_usage = proc.memory_usage;
                info.state = proc.state;

                // Postcondition: Info must be valid
                std.debug.assert(info.process_id == process_id);

                return true;
            }
        }

        return false;
    }

    /// Get all processes (up to limit).
    // 2025-12-03-164418-pst: Active function
    pub fn get_all_processes(
        self: *const MonitorApp,
        processes: []ProcessInfo,
        processes_len: *u32,
    ) void {
        // Precondition: Processes buffer must be valid
        std.debug.assert(processes.len > 0);
        std.debug.assert(processes_len != null);

        processes_len.* = 0;

        var i: u32 = 0;
        while (i < self.process_manager.processes_len and
processes_len.* < processes.len) : (i += 1) {
            const proc = &self.process_manager.processes[i];
            if (proc.active) {
                processes[processes_len.*] = ProcessInfo{
                    .process_id = proc.process_id,
                    .name = &proc.name,
                    .name_len = proc.name_len,
                    .cpu_usage = proc.cpu_usage,
                    .memory_usage = proc.memory_usage,
                    .state = proc.state,
                };
                processes_len.* += 1;
            }
        }
    }

    /// Add alert threshold.
    // 2025-12-03-164418-pst: Active function
    pub fn add_alert_threshold(
        self: *MonitorApp,
        resource_type: ResourceType,
        threshold_value: f64,
    ) !void {
        // Precondition: Must have space for threshold
        std.debug.assert(self.alert_thresholds_len <
MAX_ALERT_THRESHOLDS);
        std.debug.assert(threshold_value >= 0.0);
        std.debug.assert(threshold_value <= 100.0);

        self.alert_thresholds[self.alert_thresholds_len] =
AlertThreshold{
            .resource_type = resource_type,
            .threshold_value = threshold_value,
            .enabled = true,
        };
        self.alert_thresholds_len += 1;

        // Postcondition: Threshold count increased
        std.debug.assert(self.alert_thresholds_len > 0);
        std.debug.assert(self.alert_thresholds_len <=
MAX_ALERT_THRESHOLDS);
    }

    /// Check alert thresholds (internal).
    // 2025-12-03-164418-pst: Active function
    fn check_alert_thresholds(
        self: *MonitorApp,
        metrics: *const SystemMetrics,
    ) void {
        // Precondition: Metrics must be valid
        std.debug.assert(metrics.timestamp > 0);

        var i: u32 = 0;
        while (i < self.alert_thresholds_len) : (i += 1) {
            const threshold = &self.alert_thresholds[i];
            if (!threshold.enabled) {
                continue;
            }

            const current_value: f64 = switch (threshold.resource_type) {
                .cpu => metrics.cpu_percent,
                .memory => metrics.memory_percent,
                .disk => metrics.disk_percent,
                .network => 0.0, // TODO: Network monitoring
            };

            if (current_value >= threshold.threshold_value) {
                // Alert triggered (would notify here)
                _ = current_value; // Suppress unused warning
            }
        }
    }

    /// Add WebSocket client for real-time updates.
    // 2025-12-06-121120-pst: Phase 10.1 WebSocket integration
    pub fn add_websocket_client(
        self: *MonitorApp,
        connection_id: u32,
    ) bool {
        // Precondition: Connection ID must be valid
        std.debug.assert(connection_id > 0);
        std.debug.assert(self.websocket_clients_len <
MAX_WEBSOCKET_CLIENTS);

        if (self.websocket_clients_len >= MAX_WEBSOCKET_CLIENTS) {
            return false;
        }

        self.websocket_clients[self.websocket_clients_len] =
connection_id;
        self.websocket_clients_len += 1;

        // Postcondition: Client count increased
        std.debug.assert(self.websocket_clients_len > 0);
        std.debug.assert(self.websocket_clients_len <=
MAX_WEBSOCKET_CLIENTS);

        return true;
    }

    /// Remove WebSocket client.
    // 2025-12-06-121120-pst: Phase 10.1 WebSocket integration
    pub fn remove_websocket_client(
        self: *MonitorApp,
        connection_id: u32,
    ) bool {
        // Precondition: Connection ID must be valid
        std.debug.assert(connection_id > 0);

        var i: u32 = 0;
        while (i < self.websocket_clients_len) : (i += 1) {
            if (self.websocket_clients[i] == connection_id) {
                var j: u32 = i;
                while (j < self.websocket_clients_len - 1) : (j += 1) {
                    self.websocket_clients[j] = self.websocket_clients[j
+ 1];
                }
                self.websocket_clients_len -= 1;
                return true;
            }
        }

        return false;
    }

    /// Broadcast metrics update to WebSocket clients (internal).
    // 2025-12-06-121120-pst: Phase 10.1 WebSocket integration
    fn broadcast_metrics_update(
        self: *MonitorApp,
        metrics: *const SystemMetrics,
    ) void {
        // Precondition: Metrics must be valid
        std.debug.assert(metrics.timestamp > 0);

        if (self.websocket_clients_len == 0) {
            return;
        }

        // Serialize metrics to JSON-like format (simplified)
        var json_buf: [512]u8 = undefined;
        const json_len = self.serialize_metrics_json(metrics, &json_buf);
        if (json_len == 0) {
            return;
        }

        // Create WebSocket frame
        var frame = grain_core.websocket.WebSocketFrame.init();
        frame.flags.opcode = grain_core.websocket.FrameOpcode.text;
        frame.flags.fin = true;
        frame.flags.masked = false;
        frame.payload_len = @intCast(json_len);

        var i: u32 = 0;
        while (i < json_len and i < grain_core.websocket.MAX_FRAME_SIZE)
: (i += 1) {
            frame.payload[i] = json_buf[i];
        }

        // Broadcast to all clients
        i = 0;
        while (i < self.websocket_clients_len) : (i += 1) {
            const conn_id = self.websocket_clients[i];
            const conn = self.websocket_manager.find_connection(conn_id);
            if (conn != null and conn.?.state ==
grain_core.websocket.ConnectionState.open) {
                // Frame would be sent here (actual send via socket not
implemented)
                _ = frame;
            }
        }
    }

    /// Serialize metrics to JSON format (simplified).
    // 2025-12-06-121120-pst: Phase 10.1 WebSocket integration
    fn serialize_metrics_json(
        self: *const MonitorApp,
        metrics: *const SystemMetrics,
        buf: []u8,
    ) u32 {
        // Precondition: Buffer must be valid
        std.debug.assert(buf.len >= 512);
        std.debug.assert(metrics.timestamp > 0);

        _ = self; // Suppress unused warning

        // Simplified JSON serialization
        const json_fmt = 
           
\\{"uptime":%d,"cpu":%.2f,"memory":%.2f,"disk":%.2f,"processes":%d,"runni
ng":%d}
        ;
        const written = std.fmt.bufPrint(buf, json_fmt, .{
            metrics.uptime,
            metrics.cpu_percent,
            metrics.memory_percent,
            metrics.disk_percent,
            metrics.total_processes,
            metrics.running_processes,
        }) catch return 0;

        return @intCast(written.len);
    }
};


// === grain_workspace/network_tools/app.zig ===

//! Grain Network Tools: Network utilities for system administration.
//!
//! Why: Provide network scanning, monitoring, and diagnostic
capabilities.
//! Architecture: Network scanner, port scanner, bandwidth monitor, DNS
tools.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-04-102946-pst: Active implementation
//! 2025-12-07-020824-pst: Phase 10.3 WebSocket integration for live
statistics
//! 2025-12-07-054458-pst: Phase 11 HTTP Client integration for API
endpoint testing

const std = @import("std");
const grain_core = @import("grain_core");

// Bounded: Max network devices (explicit limit)
// 2025-12-04-102946-pst: Active constant
pub const MAX_NETWORK_DEVICES: u32 = 256;

// Bounded: Max ports to scan (explicit limit)
// 2025-12-04-102946-pst: Active constant
pub const MAX_PORTS: u32 = 65535;

// Bounded: Max active connections (explicit limit)
// 2025-12-04-102946-pst: Active constant
pub const MAX_CONNECTIONS: u32 = 512;

// Bounded: Max hostname length (explicit limit, in bytes)
// 2025-12-04-102946-pst: Active constant
pub const MAX_HOSTNAME_LEN: u32 = 256;

// Bounded: Max WebSocket clients (explicit limit)
// 2025-12-07-020824-pst: Phase 10.3 WebSocket integration
pub const MAX_WEBSOCKET_CLIENTS: u32 = 32;

// Port state enumeration.
// 2025-12-04-102946-pst: Active enum
pub const PortState = enum(u8) {
    closed, // Port is closed
    open, // Port is open
    filtered, // Port is filtered (firewall)
    unknown, // Port state unknown
};

// Connection state enumeration.
// 2025-12-04-102946-pst: Active enum
pub const ConnectionState = enum(u8) {
    established, // Connection established
    listening, // Listening for connections
    time_wait, // Connection in TIME_WAIT
    close_wait, // Connection in CLOSE_WAIT
    closed, // Connection closed
};

// Network device structure.
// 2025-12-04-102946-pst: Active struct
pub const NetworkDevice = struct {
    device_id: u32,
    ip_address: [grain_core.network_manager.MAX_IP_LEN]u8,
    ip_address_len: u32,
    hostname: [MAX_HOSTNAME_LEN]u8,
    hostname_len: u32,
    mac_address: [18]u8, // MAC address format: XX:XX:XX:XX:XX:XX
    mac_address_len: u32,
    discovered_at: u64,
    active: bool,
};

// Port scan result structure.
// 2025-12-04-102946-pst: Active struct
pub const PortScanResult = struct {
    port: u16,
    state: PortState,
    service: [32]u8, // Service name (e.g., "HTTP", "SSH")
    service_len: u32,
};

// Connection information structure.
// 2025-12-04-102946-pst: Active struct
pub const ConnectionInfo = struct {
    connection_id: u32,
    local_ip: [grain_core.network_manager.MAX_IP_LEN]u8,
    local_ip_len: u32,
    local_port: u16,
    remote_ip: [grain_core.network_manager.MAX_IP_LEN]u8,
    remote_ip_len: u32,
    remote_port: u16,
    state: ConnectionState,
    protocol: u8, // 6 = TCP, 17 = UDP
};

// HTTP test result structure.
// 2025-12-07-054458-pst: Phase 11 HTTP Client integration
pub const HttpTestResult = struct {
    test_id: u32,
    url: [grain_core.http_client.MAX_URL_LEN]u8,
    url_len: u32,
    method: grain_core.api_server.HttpMethod,
    status_code: u16,
    response_time_ms: u32,
    success: bool,
    timestamp: u64,
};

// Bounded: Max HTTP test results (explicit limit)
// 2025-12-07-054458-pst: Phase 11 HTTP Client integration
pub const MAX_HTTP_TEST_RESULTS: u32 = 64;

// Network Tools application state.
// 2025-12-04-102946-pst: Active struct
// 2025-12-07-020824-pst: Phase 10.3 WebSocket integration
// 2025-12-07-054458-pst: Phase 11 HTTP Client integration
pub const NetworkToolsApp = struct {
    network_manager: *grain_core.network_manager.NetworkManager,
    dns_resolver: *grain_core.dns_resolver.DnsResolver,
    http_client: *grain_core.http_client.HttpClient,
    devices: [MAX_NETWORK_DEVICES]?NetworkDevice,
    devices_len: u32,
    connections: [MAX_CONNECTIONS]?ConnectionInfo,
    connections_len: u32,
    bandwidth_bytes_sent: u64,
    bandwidth_bytes_received: u64,
    bandwidth_timestamp: u64,
    websocket_manager: *grain_core.websocket.WebSocketManager,
    websocket_clients: [MAX_WEBSOCKET_CLIENTS]u32,
    websocket_clients_len: u32,
    http_test_results: [MAX_HTTP_TEST_RESULTS]?HttpTestResult,
    http_test_results_len: u32,
    next_http_test_id: u32,
    allocator: std.mem.Allocator,

    /// Initialize network tools application.
    // 2025-12-06-011616-pst: Active function
    // 2025-12-07-020824-pst: Phase 10.3 WebSocket integration
    // 2025-12-07-054458-pst: Phase 11 HTTP Client integration
    pub fn init(
        allocator: std.mem.Allocator,
        nm: *grain_core.network_manager.NetworkManager,
        dns_res: *grain_core.dns_resolver.DnsResolver,
        ws_manager: *grain_core.websocket.WebSocketManager,
        http_cli: *grain_core.http_client.HttpClient,
    ) NetworkToolsApp {
        // Precondition: Allocator and managers must be valid
        std.debug.assert(allocator.ptr != null);
        std.debug.assert(@intFromPtr(nm) != 0);
        std.debug.assert(@intFromPtr(dns_res) != 0);
        std.debug.assert(@intFromPtr(ws_manager) != 0);
        std.debug.assert(@intFromPtr(http_cli) != 0);

        var app = NetworkToolsApp{
            .network_manager = nm,
            .dns_resolver = dns_res,
            .http_client = http_cli,
            .devices = undefined,
            .devices_len = 0,
            .connections = undefined,
            .connections_len = 0,
            .bandwidth_bytes_sent = 0,
            .bandwidth_bytes_received = 0,
            .bandwidth_timestamp = 0,
            .websocket_manager = ws_manager,
            .websocket_clients = undefined,
            .websocket_clients_len = 0,
            .http_test_results = undefined,
            .http_test_results_len = 0,
            .next_http_test_id = 1,
            .allocator = allocator,
        };

        // Initialize devices array
        var i: u32 = 0;
        while (i < MAX_NETWORK_DEVICES) : (i += 1) {
            app.devices[i] = null;
        }

        // Initialize connections array
        i = 0;
        while (i < MAX_CONNECTIONS) : (i += 1) {
            app.connections[i] = null;
        }

        // Initialize WebSocket clients array
        i = 0;
        while (i < MAX_WEBSOCKET_CLIENTS) : (i += 1) {
            app.websocket_clients[i] = 0;
        }

        // Initialize HTTP test results array
        i = 0;
        while (i < MAX_HTTP_TEST_RESULTS) : (i += 1) {
            app.http_test_results[i] = null;
        }

        // Postcondition: App must be valid
        std.debug.assert(app.devices_len == 0);
        std.debug.assert(app.connections_len == 0);
        std.debug.assert(app.websocket_clients_len == 0);
        std.debug.assert(app.http_test_results_len == 0);

        return app;
    }

    /// Scan network for devices.
    // 2025-12-04-102946-pst: Active function
    pub fn scan_network(
        self: *NetworkToolsApp,
        network_ip: []const u8,
        netmask: []const u8,
    ) u32 {
        // Precondition: IP and netmask must be valid
        std.debug.assert(network_ip.len > 0);
        std.debug.assert(netmask.len > 0);

        // Clear existing devices
        self.devices_len = 0;
        var i: u32 = 0;
        while (i < MAX_NETWORK_DEVICES) : (i += 1) {
            self.devices[i] = null;
        }

        // In full implementation, would perform actual network scan
        // For now, add localhost as example device
        if (self.devices_len < MAX_NETWORK_DEVICES) {
            const now = @as(u64, @intCast(std.time.timestamp()));
            var device = NetworkDevice{
                .device_id = 1,
                .ip_address = undefined,
                .ip_address_len = 0,
                .hostname = undefined,
                .hostname_len = 0,
                .mac_address = undefined,
                .mac_address_len = 0,
                .discovered_at = now,
                .active = true,
            };

            // Set IP address
            const ip_len = @min(network_ip.len,
grain_core.network_manager.MAX_IP_LEN);
            @memset(&device.ip_address, 0);
            @memcpy(device.ip_address[0..ip_len], network_ip[0..ip_len]);
            device.ip_address_len = @as(u32, @intCast(ip_len));

            // Set hostname
            const hostname_str = "localhost";
            const hostname_len = @min(hostname_str.len,
MAX_HOSTNAME_LEN);
            @memset(&device.hostname, 0);
            @memcpy(device.hostname[0..hostname_len],
hostname_str[0..hostname_len]);
            device.hostname_len = @as(u32, @intCast(hostname_len));

            self.devices[self.devices_len] = device;
            self.devices_len += 1;
        }

        // Postcondition: Devices must be valid
        std.debug.assert(self.devices_len <= MAX_NETWORK_DEVICES);

        return self.devices_len;
    }

    /// Scan ports on a host.
    // 2025-12-04-102946-pst: Active function
    pub fn scan_ports(
        self: *NetworkToolsApp,
        host_ip: []const u8,
        start_port: u16,
        end_port: u16,
        results: []PortScanResult,
        results_len: *u32,
    ) void {
        // Precondition: Host IP and ports must be valid
        std.debug.assert(host_ip.len > 0);
        std.debug.assert(start_port <= end_port);
        std.debug.assert(end_port <= MAX_PORTS);
        std.debug.assert(results.len > 0);
        std.debug.assert(results_len != null);

        results_len.* = 0;

        // In full implementation, would perform actual port scan
        // For now, add example results
        var port: u16 = start_port;
        while (port <= end_port and results_len.* < results.len) : (port
+= 1) {
            // Example: mark common ports as open
            if (port == 22 or port == 80 or port == 443) {
                results[results_len.*] = PortScanResult{
                    .port = port,
                    .state = .open,
                    .service = undefined,
                    .service_len = 0,
                };

                // Set service name
                var service_name: []const u8 = "";
                if (port == 22) {
                    service_name = "SSH";
                } else if (port == 80) {
                    service_name = "HTTP";
                } else if (port == 443) {
                    service_name = "HTTPS";
                }

                if (service_name.len > 0) {
                    const service_len = @min(service_name.len, 32);
                    @memset(&results[results_len.*].service, 0);
                   
@memcpy(results[results_len.*].service[0..service_len],
service_name[0..service_len]);
                    results[results_len.*].service_len = @as(u32,
@intCast(service_len));
                }

                results_len.* += 1;
            }
        }
    }

    /// Update bandwidth statistics.
    // 2025-12-04-102946-pst: Active function
    pub fn update_bandwidth(
        self: *NetworkToolsApp,
        bytes_sent: u64,
        bytes_received: u64,
    ) void {
        // Precondition: Values must be valid
        std.debug.assert(bytes_sent >= self.bandwidth_bytes_sent);
        std.debug.assert(bytes_received >=
self.bandwidth_bytes_received);

        self.bandwidth_bytes_sent = bytes_sent;
        self.bandwidth_bytes_received = bytes_received;
        self.bandwidth_timestamp = @as(u64,
@intCast(std.time.timestamp()));

        // Postcondition: Timestamp must be set
        std.debug.assert(self.bandwidth_timestamp > 0);

        // Broadcast bandwidth update to WebSocket clients
        self.broadcast_bandwidth_update();
    }

    /// Get bandwidth statistics.
    // 2025-12-04-102946-pst: Active function
    pub fn get_bandwidth(
        self: *const NetworkToolsApp,
        bytes_sent: *u64,
        bytes_received: *u64,
    ) void {
        // Precondition: Pointers must be valid
        std.debug.assert(@intFromPtr(bytes_sent) != 0);
        std.debug.assert(@intFromPtr(bytes_received) != 0);

        bytes_sent.* = self.bandwidth_bytes_sent;
        bytes_received.* = self.bandwidth_bytes_received;
    }

    /// Add connection to connection list.
    // 2025-12-04-102946-pst: Active function
    pub fn add_connection(
        self: *NetworkToolsApp,
        local_ip: []const u8,
        local_port: u16,
        remote_ip: []const u8,
        remote_port: u16,
        state: ConnectionState,
        protocol: u8,
    ) bool {
        // Precondition: Must have space for connection
        std.debug.assert(self.connections_len < MAX_CONNECTIONS);
        std.debug.assert(local_ip.len > 0);
        std.debug.assert(remote_ip.len > 0);

        const connection_id = self.connections_len + 1;
        var conn = ConnectionInfo{
            .connection_id = connection_id,
            .local_ip = undefined,
            .local_ip_len = 0,
            .local_port = local_port,
            .remote_ip = undefined,
            .remote_ip_len = 0,
            .remote_port = remote_port,
            .state = state,
            .protocol = protocol,
        };

        // Set local IP
        const local_ip_len = @min(local_ip.len,
grain_core.network_manager.MAX_IP_LEN);
        @memset(&conn.local_ip, 0);
        @memcpy(conn.local_ip[0..local_ip_len],
local_ip[0..local_ip_len]);
        conn.local_ip_len = @as(u32, @intCast(local_ip_len));

        // Set remote IP
        const remote_ip_len = @min(remote_ip.len,
grain_core.network_manager.MAX_IP_LEN);
        @memset(&conn.remote_ip, 0);
        @memcpy(conn.remote_ip[0..remote_ip_len],
remote_ip[0..remote_ip_len]);
        conn.remote_ip_len = @as(u32, @intCast(remote_ip_len));

        self.connections[self.connections_len] = conn;
        self.connections_len += 1;

        // Postcondition: Connection count increased
        std.debug.assert(self.connections_len > 0);
        std.debug.assert(self.connections_len <= MAX_CONNECTIONS);

        return true;
    }

    /// Get DNS lookup result (using Grain Core DNS resolver).
    // 2025-12-06-011616-pst: Active function
    pub fn dns_lookup(
        self: *NetworkToolsApp,
        hostname: []const u8,
        record_type: grain_core.dns_resolver.DnsRecordType,
        ip_address: []u8,
        ip_address_len: *u32,
    ) bool {
        // Precondition: Hostname and buffer must be valid
        std.debug.assert(hostname.len > 0);
        std.debug.assert(hostname.len <=
grain_core.dns_resolver.MAX_HOSTNAME_LEN);
        std.debug.assert(ip_address.len > 0);
        std.debug.assert(ip_address_len != null);

        ip_address_len.* = 0;

        // Use Grain Core DNS resolver
        const now = @as(u64, @intCast(std.time.timestamp()));
        var ip_buf: [grain_core.dns_resolver.MAX_IP_ADDRESS_LEN]u8 =
undefined;
        const found = self.dns_resolver.resolve_hostname(
            hostname,
            record_type,
            now,
            &ip_buf,
        );

        if (found) {
            const ip_len =
@min(grain_core.dns_resolver.MAX_IP_ADDRESS_LEN, ip_address.len);
            @memcpy(ip_address[0..ip_len], ip_buf[0..ip_len]);
            ip_address_len.* = ip_len;
            return true;
        }

        return false;
    }

    /// Add DNS cache entry (using Grain Core DNS resolver).
    // 2025-12-06-011616-pst: Active function
    pub fn add_dns_cache_entry(
        self: *NetworkToolsApp,
        hostname: []const u8,
        record_type: grain_core.dns_resolver.DnsRecordType,
        ip_address: []const u8,
    ) bool {
        // Precondition: Hostname and IP must be valid
        std.debug.assert(hostname.len > 0);
        std.debug.assert(hostname.len <=
grain_core.dns_resolver.MAX_HOSTNAME_LEN);
        std.debug.assert(ip_address.len > 0);
        std.debug.assert(ip_address.len <=
grain_core.dns_resolver.MAX_IP_ADDRESS_LEN);

        const now = @as(u64, @intCast(std.time.timestamp()));
        const result = self.dns_resolver.add_cache_entry(
            hostname,
            record_type,
            ip_address,
            now,
        );

        // Postcondition: Cache entry added if successful
        std.debug.assert(result or self.dns_resolver.cache_len >=
grain_core.dns_resolver.MAX_DNS_CACHE_ENTRIES);

        return result;
    }

    /// Clear expired DNS cache entries.
    // 2025-12-06-011616-pst: Active function
    pub fn clear_expired_dns_cache(self: *NetworkToolsApp) u32 {
        // Precondition: App must be valid
        std.debug.assert(@intFromPtr(self) != 0);

        const now = @as(u64, @intCast(std.time.timestamp()));
        const cleared_count = self.dns_resolver.clear_expired_cache(now);

        // Postcondition: Cleared count must be valid
        std.debug.assert(cleared_count <= self.dns_resolver.cache_len);

        return cleared_count;
    }

    /// Add WebSocket client for live statistics updates.
    // 2025-12-07-020824-pst: Phase 10.3 WebSocket integration
    pub fn add_websocket_client(
        self: *NetworkToolsApp,
        connection_id: u32,
    ) bool {
        // Precondition: Connection ID must be valid
        std.debug.assert(connection_id > 0);
        std.debug.assert(self.websocket_clients_len <
MAX_WEBSOCKET_CLIENTS);

        if (self.websocket_clients_len >= MAX_WEBSOCKET_CLIENTS) {
            return false;
        }

        self.websocket_clients[self.websocket_clients_len] =
connection_id;
        self.websocket_clients_len += 1;

        // Postcondition: Client count increased
        std.debug.assert(self.websocket_clients_len > 0);
        std.debug.assert(self.websocket_clients_len <=
MAX_WEBSOCKET_CLIENTS);

        return true;
    }

    /// Remove WebSocket client.
    // 2025-12-07-020824-pst: Phase 10.3 WebSocket integration
    pub fn remove_websocket_client(
        self: *NetworkToolsApp,
        connection_id: u32,
    ) bool {
        // Precondition: Connection ID must be valid
        std.debug.assert(connection_id > 0);

        var i: u32 = 0;
        while (i < self.websocket_clients_len) : (i += 1) {
            if (self.websocket_clients[i] == connection_id) {
                var j: u32 = i;
                while (j < self.websocket_clients_len - 1) : (j += 1) {
                    self.websocket_clients[j] = self.websocket_clients[j
+ 1];
                }
                self.websocket_clients_len -= 1;
                return true;
            }
        }

        return false;
    }

    /// Broadcast bandwidth update to WebSocket clients (internal).
    // 2025-12-07-020824-pst: Phase 10.3 WebSocket integration
    fn broadcast_bandwidth_update(self: *NetworkToolsApp) void {
        // Precondition: App must be valid
        std.debug.assert(self.bandwidth_timestamp > 0);

        if (self.websocket_clients_len == 0) {
            return;
        }

        // Serialize bandwidth statistics to JSON-like format
(simplified)
        var json_buf: [256]u8 = undefined;
        const json_len = self.serialize_bandwidth_json(&json_buf);
        if (json_len == 0) {
            return;
        }

        // Create WebSocket frame
        var frame = grain_core.websocket.WebSocketFrame.init();
        frame.flags.opcode = grain_core.websocket.FrameOpcode.text;
        frame.flags.fin = true;
        frame.flags.masked = false;
        frame.payload_len = @intCast(json_len);

        var i: u32 = 0;
        while (i < json_len and i < grain_core.websocket.MAX_FRAME_SIZE)
: (i += 1) {
            frame.payload[i] = json_buf[i];
        }

        // Broadcast to all clients
        i = 0;
        while (i < self.websocket_clients_len) : (i += 1) {
            const conn_id = self.websocket_clients[i];
            const conn = self.websocket_manager.find_connection(conn_id);
            if (conn != null and conn.?.state ==
grain_core.websocket.ConnectionState.open) {
                // Frame would be sent here (actual send via socket not
implemented)
                _ = frame;
            }
        }
    }

    /// Serialize bandwidth statistics to JSON format (simplified).
    // 2025-12-07-020824-pst: Phase 10.3 WebSocket integration
    fn serialize_bandwidth_json(
        self: *const NetworkToolsApp,
        buf: []u8,
    ) u32 {
        // Precondition: Buffer must be valid
        std.debug.assert(buf.len >= 256);
        std.debug.assert(self.bandwidth_timestamp > 0);

        // Simplified JSON serialization
        const json_fmt = 
           
\\{"bytes_sent":%d,"bytes_received":%d,"devices":%d,"connections":%d}
        ;
        const written = std.fmt.bufPrint(buf, json_fmt, .{
            self.bandwidth_bytes_sent,
            self.bandwidth_bytes_received,
            self.devices_len,
            self.connections_len,
        }) catch return 0;

        return @intCast(written.len);
    }

    /// Test HTTP endpoint (create request and track result).
    // 2025-12-07-054458-pst: Phase 11 HTTP Client integration
    pub fn test_http_endpoint(
        self: *NetworkToolsApp,
        method: grain_core.api_server.HttpMethod,
        url: []const u8,
    ) ?u32 {
        // Precondition: URL must be valid
        std.debug.assert(url.len > 0);
        std.debug.assert(url.len <= grain_core.http_client.MAX_URL_LEN);
        std.debug.assert(self.http_test_results_len <
MAX_HTTP_TEST_RESULTS);

        if (self.http_test_results_len >= MAX_HTTP_TEST_RESULTS) {
            return null;
        }

        // Create HTTP request
        const request = self.http_client.create_request(method, url);
        if (request == null) {
            return null;
        }

        // Create test result
        const test_id = self.next_http_test_id;
        self.next_http_test_id += 1;

        var test_result = HttpTestResult{
            .test_id = test_id,
            .url = undefined,
            .url_len = @as(u32, @intCast(url.len)),
            .method = method,
            .status_code = 0,
            .response_time_ms = 0,
            .success = false,
            .timestamp = @as(u64, @intCast(std.time.timestamp())),
        };

        @memset(&test_result.url, 0);
        const url_len = @min(url.len,
grain_core.http_client.MAX_URL_LEN);
        @memcpy(test_result.url[0..url_len], url[0..url_len]);

        // Store test result
        var i: u32 = 0;
        while (i < MAX_HTTP_TEST_RESULTS) : (i += 1) {
            if (self.http_test_results[i] == null) {
                self.http_test_results[i] = test_result;
                self.http_test_results_len += 1;
                break;
            }
        }

        // Postcondition: Test result must be stored
        std.debug.assert(self.http_test_results_len > 0);

        return test_id;
    }

    /// Get HTTP test result by test ID.
    // 2025-12-07-054458-pst: Phase 11 HTTP Client integration
    pub fn get_http_test_result(
        self: *const NetworkToolsApp,
        test_id: u32,
    ) ?*const HttpTestResult {
        // Precondition: Test ID must be valid
        std.debug.assert(test_id > 0);

        var i: u32 = 0;
        while (i < self.http_test_results_len) : (i += 1) {
            if (self.http_test_results[i]) |*result| {
                if (result.test_id == test_id) {
                    return result;
                }
            }
        }

        return null;
    }

    /// Get all HTTP test results.
    // 2025-12-07-054458-pst: Phase 11 HTTP Client integration
    pub fn get_all_http_test_results(
        self: *const NetworkToolsApp,
        results: []?*const HttpTestResult,
        results_len: *u32,
    ) void {
        // Precondition: Results buffer must be valid
        std.debug.assert(results.len > 0);
        std.debug.assert(results_len != null);

        results_len.* = 0;

        var i: u32 = 0;
        while (i < self.http_test_results_len and results_len.* <
results.len) : (i += 1) {
            if (self.http_test_results[i]) |*result| {
                results[results_len.*] = result;
                results_len.* += 1;
            }
        }
    }

    /// Clear HTTP test results.
    // 2025-12-07-054458-pst: Phase 11 HTTP Client integration
    pub fn clear_http_test_results(self: *NetworkToolsApp) u32 {
        // Precondition: App must be valid
        std.debug.assert(@intFromPtr(self) != 0);

        const cleared_count = self.http_test_results_len;
        self.http_test_results_len = 0;

        var i: u32 = 0;
        while (i < MAX_HTTP_TEST_RESULTS) : (i += 1) {
            self.http_test_results[i] = null;
        }

        // Postcondition: All results must be cleared
        std.debug.assert(self.http_test_results_len == 0);

        return cleared_count;
    }
};


// === grain_workspace/notes/app.zig ===

//! Grain Notes: Block-based note-taking application.
//!
//! Why: Provide note-taking with knowledge graph integration for Grain
OS.
//! Architecture: Block-based notes, Grain Silo storage, Grain Skate
graph rendering.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-03-162518-pst: Active implementation

const std = @import("std");
const grain_silo = @import("grain_silo");
const grain_skate = @import("grain_skate");
const grain_core = @import("grain_core");

// Bounded: Max notes (explicit limit)
// 2025-12-03-154648-pst: Active constant
pub const MAX_NOTES: u32 = 10_000;

// Bounded: Max note title length (explicit limit, in bytes)
// 2025-12-03-154648-pst: Active constant
pub const MAX_NOTE_TITLE_LEN: u32 = 512;

// Bounded: Max note content length (explicit limit, in bytes)
// 2025-12-03-154648-pst: Active constant
pub const MAX_NOTE_CONTENT_LEN: u32 = 1_048_576; // 1 MB

// Bounded: Max links per note (explicit limit)
// 2025-12-03-154648-pst: Active constant
pub const MAX_LINKS_PER_NOTE: u32 = 256;

// Note state enumeration.
// 2025-12-03-154648-pst: Active enum
pub const NoteState = enum(u8) {
    draft, // Draft note (not saved)
    saved, // Saved note
    archived, // Archived note
};

// Note structure.
// 2025-12-03-154648-pst: Active struct
pub const Note = struct {
    id: u32, // Note ID (unique identifier)
    title: []const u8, // Note title (bounded)
    title_len: u32,
    content: []const u8, // Note content (bounded, Markdown)
    content_len: u32,
    state: NoteState, // Note state
    created_at: u64, // Creation timestamp (Unix epoch)
    updated_at: u64, // Last update timestamp (Unix epoch)
    links: []u32, // Linked note IDs (bounded)
    links_len: u32,
    backlinks: []u32, // Notes that link to this note (bounded)
    backlinks_len: u32,
    allocator: std.mem.Allocator,

    /// Initialize note.
    // 2025-12-03-154648-pst: Active function
    pub fn init(allocator: std.mem.Allocator, id: u32, title: []const
u8, content: []const u8) !Note {
        // Precondition: Title and content must be bounded
        std.debug.assert(title.len <= MAX_NOTE_TITLE_LEN);
        std.debug.assert(content.len <= MAX_NOTE_CONTENT_LEN);
        std.debug.assert(id > 0);
        std.debug.assert(allocator.ptr != null);

        // Get current timestamp
        const now = @as(u64, @intCast(std.time.timestamp()));

        // Allocate title
        const title_copy = try allocator.dupe(u8, title);
        errdefer allocator.free(title_copy);

        // Allocate content
        const content_copy = try allocator.dupe(u8, content);
        errdefer allocator.free(content_copy);

        // Pre-allocate links buffer
        const links = try allocator.alloc(u32, MAX_LINKS_PER_NOTE);
        errdefer allocator.free(links);

        // Pre-allocate backlinks buffer
        const backlinks = try allocator.alloc(u32, MAX_LINKS_PER_NOTE);
        errdefer allocator.free(backlinks);

        const note = Note{
            .id = id,
            .title = title_copy,
            .title_len = @as(u32, @intCast(title_copy.len)),
            .content = content_copy,
            .content_len = @as(u32, @intCast(content_copy.len)),
            .state = .draft,
            .created_at = now,
            .updated_at = now,
            .links = links,
            .links_len = 0,
            .backlinks = backlinks,
            .backlinks_len = 0,
            .allocator = allocator,
        };

        // Postcondition: Note must be valid
        std.debug.assert(note.id > 0);
        std.debug.assert(note.title_len <= MAX_NOTE_TITLE_LEN);
        std.debug.assert(note.content_len <= MAX_NOTE_CONTENT_LEN);

        return note;
    }

    /// Deinitialize note and free memory.
    // 2025-12-03-154648-pst: Active function
    pub fn deinit(self: *Note) void {
        // Precondition: Allocator must be valid
        std.debug.assert(self.allocator.ptr != null);

        // Free title
        if (self.title_len > 0) {
            self.allocator.free(self.title);
        }

        // Free content
        if (self.content_len > 0) {
            self.allocator.free(self.content);
        }

        // Free links
        if (self.links_len > 0) {
            self.allocator.free(self.links);
        }

        // Free backlinks
        if (self.backlinks_len > 0) {
            self.allocator.free(self.backlinks);
        }
    }

    /// Update note content.
    // 2025-12-03-154648-pst: Active function
    pub fn update_content(self: *Note, new_content: []const u8) !void {
        // Precondition: Content must be bounded
        std.debug.assert(new_content.len <= MAX_NOTE_CONTENT_LEN);
        std.debug.assert(self.allocator.ptr != null);

        // Free old content
        if (self.content_len > 0) {
            self.allocator.free(self.content);
        }

        // Allocate new content
        const content_copy = try self.allocator.dupe(u8, new_content);
        self.content = content_copy;
        self.content_len = @as(u32, @intCast(content_copy.len));
        self.updated_at = @as(u64, @intCast(std.time.timestamp()));

        // Postcondition: Content must be valid
        std.debug.assert(self.content_len <= MAX_NOTE_CONTENT_LEN);
    }

    /// Add link to another note.
    // 2025-12-03-154648-pst: Active function
    pub fn add_link(self: *Note, target_note_id: u32) !void {
        // Precondition: Must have space for link
        std.debug.assert(self.links_len < MAX_LINKS_PER_NOTE);
        std.debug.assert(target_note_id > 0);
        std.debug.assert(self.id != target_note_id); // No self-links

        // Check if link already exists
        var i: u32 = 0;
        while (i < self.links_len) : (i += 1) {
            if (self.links[i] == target_note_id) {
                return; // Link already exists
            }
        }

        // Add link
        self.links[self.links_len] = target_note_id;
        self.links_len += 1;

        // Postcondition: Link count increased
        std.debug.assert(self.links_len > 0);
        std.debug.assert(self.links_len <= MAX_LINKS_PER_NOTE);
    }

    /// Remove link to another note.
    // 2025-12-03-154648-pst: Active function
    pub fn remove_link(self: *Note, target_note_id: u32) void {
        // Precondition: Target ID must be valid
        std.debug.assert(target_note_id > 0);

        // Find and remove link
        var i: u32 = 0;
        while (i < self.links_len) : (i += 1) {
            if (self.links[i] == target_note_id) {
                // Shift remaining links left
                var j: u32 = i;
                while (j + 1 < self.links_len) : (j += 1) {
                    self.links[j] = self.links[j + 1];
                }
                self.links_len -= 1;
                return;
            }
        }
    }

    /// Remove backlink from another note.
    // 2025-12-03-154648-pst: Active function
    pub fn remove_backlink(self: *Note, backlink_id: u32) void {
        // Precondition: Backlink ID must be valid
        std.debug.assert(backlink_id > 0);

        var i: u32 = 0;
        while (i < self.backlinks_len) : (i += 1) {
            if (self.backlinks[i] == backlink_id) {
                // Shift remaining backlinks left
                var j: u32 = i;
                while (j + 1 < self.backlinks_len) : (j += 1) {
                    self.backlinks[j] = self.backlinks[j + 1];
                }
                self.backlinks_len -= 1;
                return;
            }
        }
    }
};

// Notes application state.
// 2025-12-03-154648-pst: Active struct
pub const NotesApp = struct {
    notes: [MAX_NOTES]?Note,
    notes_len: u32,
    next_note_id: u32,
    storage: ?*grain_silo.Storage.ObjectStorage,
    allocator: std.mem.Allocator,

    /// Initialize notes application.
    // 2025-12-03-154648-pst: Active function
    pub fn init(allocator: std.mem.Allocator) NotesApp {
        // Precondition: Allocator must be valid
        std.debug.assert(allocator.ptr != null);

        var app = NotesApp{
            .notes = undefined,
            .notes_len = 0,
            .next_note_id = 1,
            .storage = null,
            .allocator = allocator,
        };

        // Initialize notes array
        var i: u32 = 0;
        while (i < MAX_NOTES) : (i += 1) {
            app.notes[i] = null;
        }

        // Postcondition: App must be valid
        std.debug.assert(app.notes_len == 0);
        std.debug.assert(app.next_note_id > 0);

        return app;
    }

    /// Create new note.
    // 2025-12-03-154648-pst: Active function
    pub fn create_note(self: *NotesApp, title: []const u8, content:
[]const u8) !u32 {
        // Precondition: Must have space for note
        std.debug.assert(self.notes_len < MAX_NOTES);
        std.debug.assert(title.len <= MAX_NOTE_TITLE_LEN);
        std.debug.assert(content.len <= MAX_NOTE_CONTENT_LEN);

        const note_id = self.next_note_id;
        self.next_note_id += 1;

        const note = try Note.init(self.allocator, note_id, title,
content);
        self.notes[self.notes_len] = note;
        self.notes_len += 1;

        // Postcondition: Note count increased
        std.debug.assert(self.notes_len > 0);
        std.debug.assert(self.notes_len <= MAX_NOTES);

        return note_id;
    }

    /// Get note by ID.
    // 2025-12-03-154648-pst: Active function
    pub fn get_note(self: *const NotesApp, note_id: u32) ?*Note {
        // Precondition: Note ID must be valid
        std.debug.assert(note_id > 0);

        var i: u32 = 0;
        while (i < self.notes_len) : (i += 1) {
            if (self.notes[i]) |*note| {
                if (note.id == note_id) {
                    return note;
                }
            }
        }

        return null;
    }

    /// Delete note by ID.
    // 2025-12-03-154648-pst: Active function
    pub fn delete_note(self: *NotesApp, note_id: u32) void {
        // Precondition: Note ID must be valid
        std.debug.assert(note_id > 0);

        var i: u32 = 0;
        while (i < self.notes_len) : (i += 1) {
            if (self.notes[i]) |*note| {
                if (note.id == note_id) {
                    // Remove backlinks from linked notes
                    var j: u32 = 0;
                    while (j < note.links_len) : (j += 1) {
                        const target_id = note.links[j];
                        if (self.get_note(target_id)) |target| {
                            target.remove_backlink(note_id);
                        }
                    }

                    // Deinitialize and remove note
                    note.deinit();
                    self.notes[i] = null;

                    // Shift remaining notes left
                    var k: u32 = i;
                    while (k + 1 < self.notes_len) : (k += 1) {
                        self.notes[k] = self.notes[k + 1];
                    }
                    self.notes_len -= 1;
                    return;
                }
            }
        }
    }

    /// Search notes by title or content.
    // 2025-12-03-155158-pst: Active function
    pub fn search_notes(
        self: *const NotesApp,
        query: []const u8,
        results: []u32,
        results_len: *u32,
    ) void {
        // Precondition: Results buffer must be valid
        std.debug.assert(results.len > 0);
        std.debug.assert(results_len != null);

        results_len.* = 0;

        var i: u32 = 0;
        while (i < self.notes_len and results_len.* < results.len) : (i
+= 1) {
            if (self.notes[i]) |*note| {
                // Search in title
                const title_slice = note.title[0..note.title_len];
                if (std.mem.indexOf(u8, title_slice, query) != null) {
                    results[results_len.*] = note.id;
                    results_len.* += 1;
                    continue;
                }

                // Search in content
                const content_slice = note.content[0..note.content_len];
                if (std.mem.indexOf(u8, content_slice, query) != null) {
                    results[results_len.*] = note.id;
                    results_len.* += 1;
                }
            }
        }
    }

    /// Initialize storage for notes persistence.
    // 2025-12-03-155158-pst: Active function
    pub fn init_storage(
        self: *NotesApp,
        storage: *grain_silo.Storage.ObjectStorage,
    ) void {
        // Precondition: Storage must be valid
        std.debug.assert(@intFromPtr(storage) != 0);
        std.debug.assert(self.storage == null);

        self.storage = storage;

        // Postcondition: Storage must be set
        std.debug.assert(self.storage != null);
    }

    /// Save note to storage.
    // 2025-12-03-155158-pst: Active function
    pub fn save_note(self: *NotesApp, note_id: u32) !void {
        // Precondition: Storage and note must exist
        std.debug.assert(note_id > 0);
        std.debug.assert(self.storage != null);

        const note_opt = self.get_note(note_id);
        if (note_opt) |note| {
            const key = try serialize_note_key(note_id, self.allocator);
            defer self.allocator.free(key);

            const data = try serialize_note_data(note, self.allocator);
            defer self.allocator.free(data);

            const metadata = try serialize_note_metadata(note,
self.allocator);
            defer self.allocator.free(metadata);

            try self.storage.?.store_object(key, data, metadata);
            note.state = .saved;
        } else {
            return error.NoteNotFound;
        }
    }

    /// Load note from storage.
    // 2025-12-03-155158-pst: Active function
    pub fn load_note(self: *NotesApp, note_id: u32) !void {
        // Precondition: Storage must exist
        std.debug.assert(note_id > 0);
        std.debug.assert(self.storage != null);

        const key = try serialize_note_key(note_id, self.allocator);
        defer self.allocator.free(key);

        if (self.storage.?.get_object(key)) |object| {
            const note = try deserialize_note_data(
                note_id,
                object.data,
                self.allocator,
            );
            self.notes[self.notes_len] = note;
            self.notes_len += 1;
        } else {
            return error.NoteNotFound;
        }
    }

    /// Export note to Markdown format.
    // 2025-12-03-162518-pst: Active function
    pub fn export_note_markdown(
        self: *const NotesApp,
        note_id: u32,
        allocator: std.mem.Allocator,
    ) ![]u8 {
        // Precondition: Note ID must be valid
        std.debug.assert(note_id > 0);
        std.debug.assert(allocator.ptr != null);

        const note_opt = self.get_note(note_id);
        if (note_opt) |note| {
            return export_note_to_markdown(note, allocator);
        } else {
            return error.NoteNotFound;
        }
    }

    /// Import note from Markdown format.
    // 2025-12-03-162518-pst: Active function
    pub fn import_note_markdown(
        self: *NotesApp,
        markdown: []const u8,
    ) !u32 {
        // Precondition: Markdown must be valid
        std.debug.assert(markdown.len > 0);
        std.debug.assert(self.notes_len < MAX_NOTES);

        const note = try import_note_from_markdown(
            markdown,
            self.next_note_id,
            self.allocator,
        );
        self.notes[self.notes_len] = note;
        self.notes_len += 1;
        const note_id = self.next_note_id;
        self.next_note_id += 1;

        // Postcondition: Note count increased
        std.debug.assert(self.notes_len > 0);

        return note_id;
    }

    /// Export note to JSON format.
    // 2025-12-03-162518-pst: Active function
    pub fn export_note_json(
        self: *const NotesApp,
        note_id: u32,
        allocator: std.mem.Allocator,
    ) ![]u8 {
        // Precondition: Note ID must be valid
        std.debug.assert(note_id > 0);
        std.debug.assert(allocator.ptr != null);

        const note_opt = self.get_note(note_id);
        if (note_opt) |note| {
            return export_note_to_json(note, allocator);
        } else {
            return error.NoteNotFound;
        }
    }

    /// Import note from JSON format.
    // 2025-12-03-162518-pst: Active function
    pub fn import_note_json(
        self: *NotesApp,
        json: []const u8,
    ) !u32 {
        // Precondition: JSON must be valid
        std.debug.assert(json.len > 0);
        std.debug.assert(self.notes_len < MAX_NOTES);

        const note = try import_note_from_json(
            json,
            self.next_note_id,
            self.allocator,
        );
        self.notes[self.notes_len] = note;
        self.notes_len += 1;
        const note_id = self.next_note_id;
        self.next_note_id += 1;

        // Postcondition: Note count increased
        std.debug.assert(self.notes_len > 0);

        return note_id;
    }
};

// Serialize note key for storage.
// 2025-12-03-155158-pst: Active function
fn serialize_note_key(note_id: u32, allocator: std.mem.Allocator) ![]u8 {
    // Precondition: Note ID must be valid
    std.debug.assert(note_id > 0);
    std.debug.assert(allocator.ptr != null);

    var key_buf: [64]u8 = undefined;
    const key_str = try std.fmt.bufPrint(
        &key_buf,
        "grain_notes:{d}",
        .{note_id},
    );
    const key = try allocator.dupe(u8, key_str);

    // Postcondition: Key must be valid
    std.debug.assert(key.len > 0);

    return key;
}

// Serialize note data for storage.
// 2025-12-03-155158-pst: Active function
fn serialize_note_data(
    note: *Note,
    allocator: std.mem.Allocator,
) ![]u8 {
    // Precondition: Note must be valid
    std.debug.assert(note.id > 0);
    std.debug.assert(allocator.ptr != null);

    // Simple JSON-like format: id|title|content|state|created|updated
    var buf = std.ArrayList(u8).init(allocator);
    defer buf.deinit();

    try std.fmt.format(buf.writer(), "{d}|", .{note.id});
    try buf.writer().writeAll(note.title[0..note.title_len]);
    try buf.writer().writeAll("|");
    try buf.writer().writeAll(note.content[0..note.content_len]);
    try std.fmt.format(buf.writer(), "|{d}|{d}|{d}", .{
        @intFromEnum(note.state),
        note.created_at,
        note.updated_at,
    });

    const data = try buf.toOwnedSlice();

    // Postcondition: Data must be valid
    std.debug.assert(data.len > 0);

    return data;
}

// Serialize note metadata for storage.
// 2025-12-03-155158-pst: Active function
fn serialize_note_metadata(
    note: *Note,
    allocator: std.mem.Allocator,
) ![]u8 {
    // Precondition: Note must be valid
    std.debug.assert(note.id > 0);
    std.debug.assert(allocator.ptr != null);

    // Metadata: links and backlinks
    var buf = std.ArrayList(u8).init(allocator);
    defer buf.deinit();

    try std.fmt.format(buf.writer(), "{d}:", .{note.links_len});
    var i: u32 = 0;
    while (i < note.links_len) : (i += 1) {
        if (i > 0) {
            try buf.writer().writeAll(",");
        }
        try std.fmt.format(buf.writer(), "{d}", .{note.links[i]});
    }
    try buf.writer().writeAll("|");
    try std.fmt.format(buf.writer(), "{d}:", .{note.backlinks_len});
    i = 0;
    while (i < note.backlinks_len) : (i += 1) {
        if (i > 0) {
            try buf.writer().writeAll(",");
        }
        try std.fmt.format(buf.writer(), "{d}", .{note.backlinks[i]});
    }

    const metadata = try buf.toOwnedSlice();

    // Postcondition: Metadata must be valid
    std.debug.assert(metadata.len >= 0);

    return metadata;
}

// Deserialize note data from storage.
// 2025-12-03-155158-pst: Active function
fn deserialize_note_data(
    note_id: u32,
    data: []const u8,
    allocator: std.mem.Allocator,
) !Note {
    // Precondition: Data must be valid
    std.debug.assert(note_id > 0);
    std.debug.assert(data.len > 0);
    std.debug.assert(allocator.ptr != null);

    // Parse format: id|title|content|state|created|updated
    var parts = std.mem.split(u8, data, "|");
    _ = parts.next(); // Skip ID (already known)

    const title_part = parts.next() orelse return error.InvalidFormat;
    const content_part = parts.next() orelse return error.InvalidFormat;
    const state_part = parts.next() orelse return error.InvalidFormat;
    const created_part = parts.next() orelse return error.InvalidFormat;
    _ = parts.next(); // Skip updated (we'll use current time)

    const state_val = try std.fmt.parseInt(u8, state_part, 10);
    const state = @as(NoteState, @enumFromInt(state_val));
    _ = try std.fmt.parseInt(u64, created_part, 10);

    var note = try Note.init(allocator, note_id, title_part,
content_part);
    note.state = state;

    // Postcondition: Note must be valid
    std.debug.assert(note.id == note_id);

    return note;
}

// Export note to Markdown format.
// 2025-12-03-162518-pst: Active function
fn export_note_to_markdown(
    note: *Note,
    allocator: std.mem.Allocator,
) ![]u8 {
    // Precondition: Note must be valid
    std.debug.assert(note.id > 0);
    std.debug.assert(allocator.ptr != null);

    var buf = std.ArrayList(u8).init(allocator);
    defer buf.deinit();

    // Title as H1
    try buf.writer().writeAll("# ");
    try buf.writer().writeAll(note.title[0..note.title_len]);
    try buf.writer().writeAll("\n\n");

    // Metadata as frontmatter
    try buf.writer().writeAll("---\n");
    try std.fmt.format(buf.writer(), "id: {d}\n", .{note.id});
    try std.fmt.format(
        buf.writer(),
        "state: {s}\n",
        .{@tagName(note.state)},
    );
    try std.fmt.format(
        buf.writer(),
        "created: {d}\n",
        .{note.created_at},
    );
    try std.fmt.format(
        buf.writer(),
        "updated: {d}\n",
        .{note.updated_at},
    );

    // Links
    if (note.links_len > 0) {
        try buf.writer().writeAll("links: [");
        var i: u32 = 0;
        while (i < note.links_len) : (i += 1) {
            if (i > 0) {
                try buf.writer().writeAll(", ");
            }
            try std.fmt.format(buf.writer(), "{d}", .{note.links[i]});
        }
        try buf.writer().writeAll("]\n");
    }

    try buf.writer().writeAll("---\n\n");

    // Content
    try buf.writer().writeAll(note.content[0..note.content_len]);
    try buf.writer().writeAll("\n");

    const markdown = try buf.toOwnedSlice();

    // Postcondition: Markdown must be valid
    std.debug.assert(markdown.len > 0);

    return markdown;
}

// Import note from Markdown format.
// 2025-12-03-162518-pst: Active function
fn import_note_from_markdown(
    markdown: []const u8,
    note_id: u32,
    allocator: std.mem.Allocator,
) !Note {
    // Precondition: Markdown must be valid
    std.debug.assert(markdown.len > 0);
    std.debug.assert(note_id > 0);
    std.debug.assert(allocator.ptr != null);

    // Find frontmatter section
    const frontmatter_start = std.mem.indexOf(u8, markdown, "---\n");
    if (frontmatter_start == null) {
        return error.InvalidFormat;
    }
    const frontmatter_end = std.mem.indexOfPos(
        u8,
        markdown,
        frontmatter_start.? + 4,
        "---\n",
    ) orelse return error.InvalidFormat;

    // Find title (first line after frontmatter)
    const title_start = frontmatter_end.? + 4;
    const title_end = std.mem.indexOfPos(
        u8,
        markdown,
        title_start,
        "\n",
    ) orelse return error.InvalidFormat;

    // Extract title (skip "# " prefix)
    var title_slice = markdown[title_start..title_end];
    if (title_slice.len >= 2 and title_slice[0] == '#' and
title_slice[1] == ' ') {
        title_slice = title_slice[2..];
    }

    // Find content (after title and blank line)
    const content_start = std.mem.indexOfPos(
        u8,
        markdown,
        title_end + 1,
        "\n\n",
    ) orelse return error.InvalidFormat;
    const content_slice = markdown[content_start + 2..];

    // Create note
    const note = try Note.init(allocator, note_id, title_slice,
content_slice);

    // Postcondition: Note must be valid
    std.debug.assert(note.id == note_id);

    return note;
}

// Export note to JSON format.
// 2025-12-03-162518-pst: Active function
fn export_note_to_json(
    note: *Note,
    allocator: std.mem.Allocator,
) ![]u8 {
    // Precondition: Note must be valid
    std.debug.assert(note.id > 0);
    std.debug.assert(allocator.ptr != null);

    var buf = std.ArrayList(u8).init(allocator);
    defer buf.deinit();

    try buf.writer().writeAll("{\n");
    try std.fmt.format(buf.writer(), "  \"id\": {d},\n", .{note.id});
    try buf.writer().writeAll("  \"title\": \"");
    // Escape JSON string
    var i: u32 = 0;
    while (i < note.title_len) : (i += 1) {
        const ch = note.title[i];
        if (ch == '"' or ch == '\\') {
            try buf.writer().writeAll("\\");
        }
        try buf.writer().writeByte(ch);
    }
    try buf.writer().writeAll("\",\n");
    try buf.writer().writeAll("  \"content\": \"");
    i = 0;
    while (i < note.content_len) : (i += 1) {
        const ch = note.content[i];
        if (ch == '"' or ch == '\\') {
            try buf.writer().writeAll("\\");
        }
        try buf.writer().writeByte(ch);
    }
    try buf.writer().writeAll("\",\n");
    try std.fmt.format(
        buf.writer(),
        "  \"state\": \"{s}\",\n",
        .{@tagName(note.state)},
    );
    try std.fmt.format(
        buf.writer(),
        "  \"created_at\": {d},\n",
        .{note.created_at},
    );
    try std.fmt.format(
        buf.writer(),
        "  \"updated_at\": {d},\n",
        .{note.updated_at},
    );
    try buf.writer().writeAll("  \"links\": [");
    i = 0;
    while (i < note.links_len) : (i += 1) {
        if (i > 0) {
            try buf.writer().writeAll(", ");
        }
        try std.fmt.format(buf.writer(), "{d}", .{note.links[i]});
    }
    try buf.writer().writeAll("],\n");
    try buf.writer().writeAll("  \"backlinks\": [");
    i = 0;
    while (i < note.backlinks_len) : (i += 1) {
        if (i > 0) {
            try buf.writer().writeAll(", ");
        }
        try std.fmt.format(buf.writer(), "{d}", .{note.backlinks[i]});
    }
    try buf.writer().writeAll("]\n");
    try buf.writer().writeAll("}\n");

    const json = try buf.toOwnedSlice();

    // Postcondition: JSON must be valid
    std.debug.assert(json.len > 0);

    return json;
}

// Import note from JSON format.
// 2025-12-03-162518-pst: Active function
fn import_note_from_json(
    json: []const u8,
    note_id: u32,
    allocator: std.mem.Allocator,
) !Note {
    // Precondition: JSON must be valid
    std.debug.assert(json.len > 0);
    std.debug.assert(note_id > 0);
    std.debug.assert(allocator.ptr != null);

    // Simple JSON parsing (extract title and content)
    // Find "title": "value"
    const title_label = "\"title\": \"";
    const title_start = std.mem.indexOf(u8, json, title_label);
    if (title_start == null) {
        return error.InvalidFormat;
    }
    var title_end = title_start.? + title_label.len;
    while (title_end < json.len and json[title_end] != '"') : (title_end
+= 1) {
        if (json[title_end] == '\\') {
            title_end += 1; // Skip escaped char
        }
    }
    const title_slice = json[title_start.? + title_label.len..title_end];

    // Find "content": "value"
    const content_label = "\"content\": \"";
    const content_start = std.mem.indexOfPos(
        u8,
        json,
        title_end,
        content_label,
    );
    if (content_start == null) {
        return error.InvalidFormat;
    }
    var content_end = content_start.? + content_label.len;
    while (content_end < json.len and json[content_end] != '"') :
(content_end += 1) {
        if (json[content_end] == '\\') {
            content_end += 1; // Skip escaped char
        }
    }
    const content_slice = json[content_start.? +
content_label.len..content_end];

    // Create note
    const note = try Note.init(allocator, note_id, title_slice,
content_slice);

    // Postcondition: Note must be valid
    std.debug.assert(note.id == note_id);

    return note;
}


// === grain_workspace/package_manager_ui/app.zig ===

//! Grain Package Manager UI: Graphical package management.
//!
//! Why: Provide GUI for package installation and management.
//! Architecture: Package browsing, installation, dependency
visualization.
//! GrainStyle: grain_case, u32/u64, bounded allocations, assertions.
//!
//! 2025-12-03-173505-pst: Active implementation
//! 2025-12-07-060853-pst: Phase 12 HTTP Client integration for
repository access

const std = @import("std");
const grain_core = @import("grain_core");

// Bounded: Max search results (explicit limit)
// 2025-12-03-173505-pst: Active constant
pub const MAX_SEARCH_RESULTS: u32 = 256;

// Bounded: Max categories (explicit limit)
// 2025-12-03-173505-pst: Active constant
pub const MAX_CATEGORIES: u32 = 32;

// Bounded: Max category name length (explicit limit, in bytes)
// 2025-12-03-173505-pst: Active constant
pub const MAX_CATEGORY_NAME_LEN: u32 = 64;

// Bounded: Max package name length (explicit limit, in bytes)
// 2025-12-03-173505-pst: Active constant (matches package_manager)
pub const MAX_PACKAGE_NAME_LEN: u32 = 128;

// Bounded: Max repository URLs (explicit limit)
// 2025-12-07-060853-pst: Phase 12 HTTP Client integration
pub const MAX_REPOSITORY_URLS: u32 = 16;

// Package category enumeration.
// 2025-12-03-173505-pst: Active enum
pub const PackageCategory = enum(u8) {
    all, // All packages
    system, // System packages
    development, // Development tools
    utilities, // Utility programs
    multimedia, // Multimedia applications
    network, // Network tools
    other, // Other packages
};

// Package info structure for UI.
// 2025-12-03-173505-pst: Active struct
pub const PackageInfo = struct {
    package_id: u32,
    name: []const u8,
    name_len: u32,
    version: []const u8,
    version_len: u32,
    description: []const u8,
    description_len: u32,
    state: grain_core.package_manager.PackageState,
    size_bytes: u64,
    category: PackageCategory,
};

// Dependency node for visualization.
// 2025-12-03-173505-pst: Active struct
pub const DependencyNode = struct {
    package_id: u32,
    level: u32, // Depth in dependency tree
};

// Repository URL structure.
// 2025-12-07-060853-pst: Phase 12 HTTP Client integration
pub const RepositoryUrl = struct {
    url: [grain_core.http_client.MAX_URL_LEN]u8,
    url_len: u32,
    active: bool,
};

// Package Manager UI application state.
// 2025-12-03-173505-pst: Active struct
// 2025-12-07-060853-pst: Phase 12 HTTP Client integration
pub const PackageManagerUI = struct {
    package_manager: *grain_core.package_manager.PackageManager,
    http_client: *grain_core.http_client.HttpClient,
    search_query: [MAX_PACKAGE_NAME_LEN]u8,
    search_query_len: u32,
    selected_category: PackageCategory,
    selected_package_id: u32,
    repository_urls: [MAX_REPOSITORY_URLS]?RepositoryUrl,
    repository_urls_len: u32,
    allocator: std.mem.Allocator,

    /// Initialize package manager UI.
    // 2025-12-03-173505-pst: Active function
    // 2025-12-07-060853-pst: Phase 12 HTTP Client integration
    pub fn init(
        allocator: std.mem.Allocator,
        pkg_mgr: *grain_core.package_manager.PackageManager,
        http_cli: *grain_core.http_client.HttpClient,
    ) PackageManagerUI {
        // Precondition: Allocator and managers must be valid
        std.debug.assert(allocator.ptr != null);
        std.debug.assert(@intFromPtr(pkg_mgr) != 0);
        std.debug.assert(@intFromPtr(http_cli) != 0);

        var ui = PackageManagerUI{
            .package_manager = pkg_mgr,
            .http_client = http_cli,
            .search_query = undefined,
            .search_query_len = 0,
            .selected_category = .all,
            .selected_package_id = 0,
            .repository_urls = undefined,
            .repository_urls_len = 0,
            .allocator = allocator,
        };

        // Initialize search query
        @memset(&ui.search_query, 0);

        // Initialize repository URLs array
        var i: u32 = 0;
        while (i < MAX_REPOSITORY_URLS) : (i += 1) {
            ui.repository_urls[i] = null;
        }

        // Postcondition: UI must be valid
        std.debug.assert(ui.search_query_len == 0);
        std.debug.assert(ui.repository_urls_len == 0);

        return ui;
    }

    /// Set search query.
    // 2025-12-03-173505-pst: Active function
    pub fn set_search_query(
        self: *PackageManagerUI,
        query: []const u8,
    ) void {
        // Precondition: Query must be bounded
        std.debug.assert(query.len <= MAX_PACKAGE_NAME_LEN);

        @memset(&self.search_query, 0);
        const query_len = @min(query.len, MAX_PACKAGE_NAME_LEN);
        if (query_len > 0) {
            @memcpy(self.search_query[0..query_len],
query[0..query_len]);
        }
        self.search_query_len = @as(u32, @intCast(query_len));

        // Postcondition: Query must be valid
        std.debug.assert(self.search_query_len <= MAX_PACKAGE_NAME_LEN);
    }

    /// Set selected category.
    // 2025-12-03-173505-pst: Active function
    pub fn set_category(
        self: *PackageManagerUI,
        category: PackageCategory,
    ) void {
        // Precondition: Category must be valid
        std.debug.assert(@intFromEnum(category) >= 0);

        self.selected_category = category;

        // Postcondition: Category must be set
        std.debug.assert(self.selected_category == category);
    }

    /// Search packages by name or description.
    // 2025-12-03-173505-pst: Active function
    pub fn search_packages(
        self: *const PackageManagerUI,
        results: []u32,
        results_len: *u32,
    ) void {
        // Precondition: Results buffer must be valid
        std.debug.assert(results.len > 0);
        std.debug.assert(results_len != null);

        results_len.* = 0;

        if (self.search_query_len == 0) {
            return;
        }

        const query_slice = self.search_query[0..self.search_query_len];
        var i: u32 = 0;
        while (i < self.package_manager.packages_len and results_len.* <
results.len) : (i += 1) {
            const pkg = &self.package_manager.packages[i];
            if (!pkg.active) {
                continue;
            }

            // Filter by category
            if (self.selected_category != .all) {
                const pkg_category = categorize_package(pkg);
                if (pkg_category != self.selected_category) {
                    continue;
                }
            }

            // Search in name
            const name_slice = pkg.name[0..pkg.name_len];
            if (std.mem.indexOf(u8, name_slice, query_slice) != null) {
                results[results_len.*] = pkg.package_id;
                results_len.* += 1;
                continue;
            }

            // Search in description
            const desc_slice = pkg.description[0..pkg.description_len];
            if (std.mem.indexOf(u8, desc_slice, query_slice) != null) {
                results[results_len.*] = pkg.package_id;
                results_len.* += 1;
            }
        }
    }

    /// Get all packages (filtered by category).
    // 2025-12-03-173505-pst: Active function
    pub fn get_packages(
        self: *const PackageManagerUI,
        packages: []PackageInfo,
        packages_len: *u32,
    ) void {
        // Precondition: Packages buffer must be valid
        std.debug.assert(packages.len > 0);
        std.debug.assert(packages_len != null);

        packages_len.* = 0;

        var i: u32 = 0;
        while (i < self.package_manager.packages_len and packages_len.*
< packages.len) : (i += 1) {
            const pkg = &self.package_manager.packages[i];
            if (!pkg.active) {
                continue;
            }

            // Filter by category
            if (self.selected_category != .all) {
                const pkg_category = categorize_package(pkg);
                if (pkg_category != self.selected_category) {
                    continue;
                }
            }

            packages[packages_len.*] = PackageInfo{
                .package_id = pkg.package_id,
                .name = &pkg.name,
                .name_len = pkg.name_len,
                .version = &pkg.version,
                .version_len = pkg.version_len,
                .description = &pkg.description,
                .description_len = pkg.description_len,
                .state = pkg.state,
                .size_bytes = pkg.size_bytes,
                .category = categorize_package(pkg),
            };
            packages_len.* += 1;
        }
    }

    /// Get package information.
    // 2025-12-03-173505-pst: Active function
    pub fn get_package_info(
        self: *const PackageManagerUI,
        package_id: u32,
        info: *PackageInfo,
    ) bool {
        // Precondition: Package ID and info must be valid
        std.debug.assert(package_id > 0);
        std.debug.assert(@intFromPtr(info) != 0);

        var i: u32 = 0;
        while (i < self.package_manager.packages_len) : (i += 1) {
            const pkg = &self.package_manager.packages[i];
            if (pkg.package_id == package_id and pkg.active) {
                info.package_id = pkg.package_id;
                info.name = &pkg.name;
                info.name_len = pkg.name_len;
                info.version = &pkg.version;
                info.version_len = pkg.version_len;
                info.description = &pkg.description;
                info.description_len = pkg.description_len;
                info.state = pkg.state;
                info.size_bytes = pkg.size_bytes;
                info.category = categorize_package(pkg);

                // Postcondition: Info must be valid
                std.debug.assert(info.package_id == package_id);

                return true;
            }
        }

        return false;
    }

    /// Install package.
    // 2025-12-03-173505-pst: Active function
    pub fn install_package(
        self: *PackageManagerUI,
        package_id: u32,
    ) !void {
        // Precondition: Package ID must be valid
        std.debug.assert(package_id > 0);

        const timestamp = @as(u64, @intCast(std.time.timestamp()));
        const result = self.package_manager.install_package(package_id,
timestamp);
        if (!result) {
            return error.InstallFailed;
        }
    }

    /// Remove package.
    // 2025-12-03-173505-pst: Active function
    pub fn remove_package(
        self: *PackageManagerUI,
        package_id: u32,
    ) !void {
        // Precondition: Package ID must be valid
        std.debug.assert(package_id > 0);

        const result = self.package_manager.remove_package(package_id);
        if (!result) {
            return error.RemoveFailed;
        }
    }

    /// Get package dependencies.
    // 2025-12-03-173505-pst: Active function
    pub fn get_package_dependencies(
        self: *const PackageManagerUI,
        package_id: u32,
        dependencies: []u32,
        dependencies_len: *u32,
    ) bool {
        // Precondition: Dependencies buffer must be valid
        std.debug.assert(package_id > 0);
        std.debug.assert(dependencies.len > 0);
        std.debug.assert(dependencies_len != null);

        dependencies_len.* = 0;

        var i: u32 = 0;
        while (i < self.package_manager.packages_len) : (i += 1) {
            const pkg = &self.package_manager.packages[i];
            if (pkg.package_id == package_id and pkg.active) {
                var j: u32 = 0;
                while (j < pkg.dependencies_len and dependencies_len.* <
dependencies.len) : (j += 1) {
                    dependencies[dependencies_len.*] =
pkg.dependencies[j];
                    dependencies_len.* += 1;
                }
                return true;
            }
        }

        return false;
    }

    /// Build dependency graph (breadth-first traversal).
    // 2025-12-03-173505-pst: Active function
    pub fn build_dependency_graph(
        self: *const PackageManagerUI,
        package_id: u32,
        nodes: []DependencyNode,
        nodes_len: *u32,
    ) void {
        // Precondition: Nodes buffer must be valid
        std.debug.assert(package_id > 0);
        std.debug.assert(nodes.len > 0);
        std.debug.assert(nodes_len != null);

        nodes_len.* = 0;

        // Add root node
        if (nodes_len.* < nodes.len) {
            nodes[nodes_len.*] = DependencyNode{
                .package_id = package_id,
                .level = 0,
            };
            nodes_len.* += 1;
        }

        // BFS traversal using stack
        var visited: [MAX_SEARCH_RESULTS]bool = undefined;
        @memset(&visited, false);
        var queue: [MAX_SEARCH_RESULTS]u32 = undefined;
        var queue_len: u32 = 1;
        queue[0] = package_id;
        visited[0] = true; // Simple visited tracking

        var level: u32 = 0;
        while (queue_len > 0 and nodes_len.* < nodes.len) {
            level += 1;
            const current_level_size = queue_len;
            var processed: u32 = 0;

            while (processed < current_level_size and nodes_len.* <
nodes.len) {
                queue_len -= 1;
                const current_id = queue[queue_len];
                processed += 1;

                // Get dependencies
                var deps: [16]u32 = undefined;
                var deps_len: u32 = 0;
                if (self.get_package_dependencies(current_id, &deps,
&deps_len)) {
                    var k: u32 = 0;
                    while (k < deps_len and queue_len < queue.len and
nodes_len.* < nodes.len) : (k += 1) {
                        const dep_id = deps[k];
                        if (dep_id > 0 and dep_id < visited.len) {
                            if (!visited[dep_id]) {
                                visited[dep_id] = true;
                                queue[queue_len] = dep_id;
                                queue_len += 1;

                                nodes[nodes_len.*] = DependencyNode{
                                    .package_id = dep_id,
                                    .level = level,
                                };
                                nodes_len.* += 1;
                            }
                        }
                    }
                }
            }
        }
    }
};

// Categorize package (internal helper).
// 2025-12-03-173505-pst: Active function
fn categorize_package(
    pkg: *const grain_core.package_manager.Package,
) PackageCategory {
    // Precondition: Package must be valid
    std.debug.assert(pkg.package_id > 0);

    const name_slice = pkg.name[0..pkg.name_len];
    if (std.mem.indexOf(u8, name_slice, "kernel") != null or
std.mem.indexOf(u8, name_slice, "os") != null) {
        return .system;
    }
    if (std.mem.indexOf(u8, name_slice, "dev") != null or
std.mem.indexOf(u8, name_slice, "tool") != null) {
        return .development;
    }
    if (std.mem.indexOf(u8, name_slice, "util") != null or
std.mem.indexOf(u8, name_slice, "cmd") != null) {
        return .utilities;
    }
    if (std.mem.indexOf(u8, name_slice, "media") != null or
std.mem.indexOf(u8, name_slice, "audio") != null) {
        return .multimedia;
    }
    if (std.mem.indexOf(u8, name_slice, "net") != null or
std.mem.indexOf(u8, name_slice, "http") != null) {
        return .network;
    }

    return .other;
}

// Package Manager UI HTTP Client functions.
// 2025-12-07-060853-pst: Phase 12 HTTP Client integration

/// Add repository URL.
// 2025-12-07-060853-pst: Phase 12 HTTP Client integration
pub fn add_repository_url(
    self: *PackageManagerUI,
    url: []const u8,
) bool {
    // Precondition: URL must be valid
    std.debug.assert(url.len > 0);
    std.debug.assert(url.len <= grain_core.http_client.MAX_URL_LEN);
    std.debug.assert(self.repository_urls_len < MAX_REPOSITORY_URLS);

    if (self.repository_urls_len >= MAX_REPOSITORY_URLS) {
        return false;
    }

    var repo_url = RepositoryUrl{
        .url = undefined,
        .url_len = @as(u32, @intCast(url.len)),
        .active = true,
    };

    @memset(&repo_url.url, 0);
    const url_len = @min(url.len, grain_core.http_client.MAX_URL_LEN);
    @memcpy(repo_url.url[0..url_len], url[0..url_len]);

    var i: u32 = 0;
    while (i < MAX_REPOSITORY_URLS) : (i += 1) {
        if (self.repository_urls[i] == null) {
            self.repository_urls[i] = repo_url;
            self.repository_urls_len += 1;
            break;
        }
    }

    // Postcondition: Repository URL must be added
    std.debug.assert(self.repository_urls_len > 0);

    return true;
}

/// Fetch package list from repository.
// 2025-12-07-060853-pst: Phase 12 HTTP Client integration
pub fn fetch_packages_from_repository(
    self: *PackageManagerUI,
    repository_index: u32,
) ?u32 {
    // Precondition: Repository index must be valid
    std.debug.assert(repository_index < MAX_REPOSITORY_URLS);
    std.debug.assert(self.repository_urls_len > 0);

    if (repository_index >= self.repository_urls_len) {
        return null;
    }

    const repo = self.repository_urls[repository_index];
    if (repo == null or !repo.?.active) {
        return null;
    }

    const url_slice = repo.?.url[0..repo.?.url_len];
    const request = self.http_client.create_request(.get, url_slice);
    if (request == null) {
        return null;
    }

    // Return request ID for tracking
    return request.?.request_id;
}

/// Get repository URLs.
// 2025-12-07-060853-pst: Phase 12 HTTP Client integration
pub fn get_repository_urls(
    self: *const PackageManagerUI,
    urls: []?*const RepositoryUrl,
    urls_len: *u32,
) void {
    // Precondition: URLs buffer must be valid
    std.debug.assert(urls.len > 0);
    std.debug.assert(urls_len != null);

    urls_len.* = 0;

    var i: u32 = 0;
    while (i < self.repository_urls_len and urls_len.* < urls.len) : (i
+= 1) {
        if (self.repository_urls[i]) |*repo| {
            if (repo.active) {
                urls[urls_len.*] = repo;
                urls_len.* += 1;
            }
        }
    }
}

/// Remove repository URL.
// 2025-12-07-060853-pst: Phase 12 HTTP Client integration
pub fn remove_repository_url(
    self: *PackageManagerUI,
    repository_index: u32,
) bool {
    // Precondition: Repository index must be valid
    std.debug.assert(repository_index < MAX_REPOSITORY_URLS);

    if (repository_index >= self.repository_urls_len) {
        return false;
    }

    if (self.repository_urls[repository_index]) |*repo| {
        repo.active = false;
        self.repository_urls_len -= 1;
        return true;
    }

    return false;
}


