const std = @import("std");

// Graincard Generator
// Main entry point for 75x100 graincard generation

pub const types = @import("graincard/types.zig");
pub const layout = @import("graincard/layout.zig");
pub const ecology = @import("graincard/ecology.zig");
pub const cli = @import("graincard/cli.zig");
pub const png_generator = @import("graincard/png_generator.zig");
pub const font8x8 = @import("graincard/font8x8.zig");

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    try cli.run(allocator);
}

// === graincard/cli.zig ===

const std = @import("std");
const types = @import("types.zig");
const ecology = @import("ecology.zig");
const layout = @import("layout.zig");
const png_generator = @import("png_generator.zig");

// Graincard CLI
// Command-line interface for graincard generation

pub const Options = struct {
    seed: ?u64 = null,
    output: ?[]const u8 = null,
    range_start: ?u64 = null,
    range_end: ?u64 = null,
    output_dir: ?[]const u8 = null,
    ecology_type: ?types.EcologyType = null,
    season: ?types.Season = null,
    format: Format = .txt,
    png: bool = false,
    png_scale: u8 = 1,
    png_stalk_only: bool = false,

    pub const Format = enum {
        txt,
        json,
    };
};

pub fn parse_args(allocator: std.mem.Allocator) !Options {
    var args = try std.process.argsWithAllocator(allocator);
    defer args.deinit();

    _ = args.skip(); // Skip program name

    var options = Options{};

    while (args.next()) |arg| {
        if (std.mem.eql(u8, arg, "--seed")) {
            const seed_str = args.next() orelse return
error.MissingSeedValue;
            options.seed = try std.fmt.parseInt(u64, seed_str, 10);
        } else if (std.mem.eql(u8, arg, "--output")) {
            options.output = args.next() orelse return
error.MissingOutputValue;
        } else if (std.mem.eql(u8, arg, "--range")) {
            const range_str = args.next() orelse return
error.MissingRangeValue;
            const dash_pos = std.mem.indexOf(u8, range_str, "-") orelse
                return error.InvalidRangeFormat;
            
            const start_str = range_str[0..dash_pos];
            const end_str = range_str[dash_pos + 1 ..];
            
            options.range_start = try std.fmt.parseInt(u64, start_str,
10);
            options.range_end = try std.fmt.parseInt(u64, end_str, 10);
        } else if (std.mem.eql(u8, arg, "--output-dir")) {
            options.output_dir = args.next() orelse return
error.MissingOutputDirValue;
        } else if (std.mem.eql(u8, arg, "--ecology")) {
            const ecology_str = args.next() orelse return
error.MissingEcologyValue;
            options.ecology_type = std.meta.stringToEnum(
                types.EcologyType,
                ecology_str,
            ) orelse return error.InvalidEcologyType;
        } else if (std.mem.eql(u8, arg, "--season")) {
            const season_str = args.next() orelse return
error.MissingSeasonValue;
            options.season = std.meta.stringToEnum(
                types.Season,
                season_str,
            ) orelse return error.InvalidSeason;
        } else if (std.mem.eql(u8, arg, "--format")) {
            const format_str = args.next() orelse return
error.MissingFormatValue;
            options.format = std.meta.stringToEnum(
                Options.Format,
                format_str,
            ) orelse return error.InvalidFormat;
        } else if (std.mem.eql(u8, arg, "--png")) {
            options.png = true;
        } else if (std.mem.eql(u8, arg, "--png-scale")) {
            const scale_str = args.next() orelse return
error.MissingScaleValue;
            options.png_scale = try std.fmt.parseInt(u8, scale_str, 10);
        } else if (std.mem.eql(u8, arg, "--png-stalk-only")) {
            options.png_stalk_only = true;
        } else if (std.mem.eql(u8, arg, "--help") or std.mem.eql(u8,
arg, "-h")) {
            print_usage();
            std.process.exit(0);
        }
    }

    return options;
}

pub fn print_usage() void {
    std.debug.print(
        \\Usage: graincard [OPTIONS]
        \\
        \\Options:
        \\  --seed <u64>           Seed number for generation (required)
        \\  --output <path>        Output file path (default: stdout)
        \\  --range <start>-<end>  Generate multiple graincards
        \\  --output-dir <path>    Directory for batch output
        \\  --ecology <type>       Force specific ecology type
        \\  --season <season>      Force specific season
        \\  --format <txt|json>    Output format (default: txt)
        \\  --png                  Generate PNG image
        \\  --png-scale <1-3>      Scale factor for PNG (default: 1)
        \\  --png-stalk-only       Generate only the stalk visual in PNG
        \\  --help, -h             Show this help message
        \\
        \\Examples:
        \\  graincard --seed 12025 --output graincard_12025.txt
        \\  graincard --range 1-100 --output-dir ordinals/
        \\  graincard --seed 42069 --ecology wild_edges --season summer
        \\
    , .{});
}

pub fn run(allocator: std.mem.Allocator) !void {
    const options = try parse_args(allocator);

    // Validate options
    if (options.seed == null and options.range_start == null) {
        std.debug.print("Error: Either --seed or --range is
required\n\n", .{});
        print_usage();
        return error.MissingRequiredOption;
    }

    // Single graincard generation
    if (options.seed) |seed| {
        const graincard = try generate_graincard(allocator, seed,
options);
        defer allocator.free(graincard);

        if (options.output) |output_path| {
            const file = try std.fs.cwd().createFile(output_path, .{});
            defer file.close();
            try file.writeAll(graincard);
            std.debug.print("Generated graincard: {s}\n",
.{output_path});

            if (options.png) {
                // Generate PNG filename (replace extension or append
.png)
                const png_path = try std.fmt.allocPrint(allocator,
"{s}.png", .{output_path});
                defer allocator.free(png_path);
                
                try png_generator.ascii_to_png(allocator, graincard,
png_path, .{
                    .scale = options.png_scale,
                    .stalk_only = options.png_stalk_only,
                });
                std.debug.print("Generated PNG: {s}\n", .{png_path});
            }
        } else {
            std.debug.print("{s}", .{graincard});
        }
        return;
    }

    // Batch generation
    if (options.range_start) |start| {
        const end = options.range_end orelse return
error.MissingRangeEnd;
        const output_dir = options.output_dir orelse return
error.MissingOutputDir;

        // Create output directory
        try std.fs.cwd().makePath(output_dir);

        var current = start;
        while (current <= end) : (current += 1) {
            const graincard = try generate_graincard(allocator, current,
options);
            defer allocator.free(graincard);

            const filename = try std.fmt.allocPrint(
                allocator,
                "{s}/graincard_{d}.txt",
                .{ output_dir, current },
            );
            defer allocator.free(filename);

            const file = try std.fs.cwd().createFile(filename, .{});
            defer file.close();
            try file.writeAll(graincard);

            if (options.png) {
                const png_filename = try std.fmt.allocPrint(
                    allocator,
                    "{s}/graincard_{d}.png",
                    .{ output_dir, current },
                );
                defer allocator.free(png_filename);

                try png_generator.ascii_to_png(allocator, graincard,
png_filename, .{
                    .scale = options.png_scale,
                    .stalk_only = options.png_stalk_only,
                });
            }

            if (current % 10 == 0) {
                std.debug.print("Generated {d}/{d} graincards...\n", .{
current - start + 1, end - start + 1 });
            }
        }

        std.debug.print("✓ Generated {d} graincards in {s}/\n", .{ end -
start + 1, output_dir });
    }
}

fn generate_graincard(
    allocator: std.mem.Allocator,
    seed: u64,
    options: Options,
) ![]u8 {
    // Generate ecological parameters
    const params = try ecology.generate_ecological_params(
        allocator,
        seed,
        options.ecology_type,
        options.season,
    );
    // We need to free companions if we owned them, but they are in the
struct.
    // For now we rely on the fact that we are short-lived. 
    // Ideally we'd have a deinit on params or use an arena.
    
    // Generate stalk visual
    const stalk = try ecology.generate_stalk(allocator, params);
    defer allocator.free(stalk);

    // Create header
    const rarity_trait = types.get_rarity_trait(params.rarity_score);
    const rarity_pct = types.get_rarity_percentage(rarity_trait);
    
    // Note: Layout engine handles padding, so we just need content.
    const header = try std.fmt.allocPrint(
        allocator,
        \\  GRAINSEED #{d}
        \\  Rarity: {s} ({s})
        \\  Seed: {d}
        \\  Height: {d} segments
        \\  Type: {s}
        \\  Lean: {s}
        \\  Season: {s}
        \\  Leaves: {d}
    ,
        .{
            seed,
            @tagName(rarity_trait),
            rarity_pct,
            seed,
            params.stalk_height,
            @tagName(params.ecology_type),
            if (params.stalk_lean == 0) "Straight" else if
(params.stalk_lean < 0) "Left" else "Right",
            @tagName(params.season),
            params.leaf_count,
        },
    );
    defer allocator.free(header);

    // Format companions list
    var companions_buf: std.ArrayList(u8) = .{
        .items = &.{},
        .capacity = 0,
    };
    defer companions_buf.deinit(allocator);
    
    if (params.companions.len > 0) {
        try companions_buf.appendSlice(allocator, "  Companions: ");
        for (params.companions, 0..) |c, i| {
            if (i > 0) try companions_buf.appendSlice(allocator, ", ");
            try companions_buf.appendSlice(allocator, @tagName(c));
        }
    } else {
        try companions_buf.appendSlice(allocator, "  Companions: None");
    }

    // Create metrics box
    const metrics = try std.fmt.allocPrint(
        allocator,
        \\  Soil Food Web: {d} species
        \\  Carbon Sequestration: +{d:.1}% annually
        \\  Biodiversity Index: {d:.1}/10
        \\{s}
    ,
        .{
            params.nematode_diversity,
            params.soil_carbon_sequestration,
            params.biodiversity_index,
            companions_buf.items,
        },
    );
    defer allocator.free(metrics);

    const footer = "\"Code that grows. Grain that lasts.\"";

    // Assemble graincard
    const config = types.GraincardConfig{ .seed = seed };
    const content = types.GraincardContent{
        .header = header,
        .stalk_visual = stalk,
        .metrics_box = metrics,
        .footer = footer,
    };

    return layout.layout_graincard(allocator, config, content);
}

// === graincard/ecology.zig ===

const std = @import("std");
const types = @import("types.zig");

// Graincard Ecology Generator
// Generates ecological parameters and ASCII visualizations

pub fn generate_ecological_params(
    allocator: std.mem.Allocator,
    seed: u64,
    forced_ecology: ?types.EcologyType,
    forced_season: ?types.Season,
) !types.EcologicalParams {
    var rng = std.Random.DefaultPrng.init(seed);
    const random = rng.random();

    const ecology_type = forced_ecology orelse @as(
        types.EcologyType,
        @enumFromInt(random.intRangeAtMost(
            u4,
            0,
            @intFromEnum(types.EcologyType.ecosystem_immune),
        )),
    );

    const season = forced_season orelse @as(
        types.Season,
        @enumFromInt(random.intRangeAtMost(
            u3,
            0,
            @intFromEnum(types.Season.year_round),
        )),
    );

    const soil_type = @as(
        types.SoilType,
        @enumFromInt(random.intRangeAtMost(
            u3,
            0,
            @intFromEnum(types.SoilType.desert_sand),
        )),
    );

    const weather = @as(
        types.WeatherCondition,
        @enumFromInt(random.intRangeAtMost(
            u3,
            0,
            @intFromEnum(types.WeatherCondition.moonlit),
        )),
    );

    // Generate stalk characteristics
    const stalk_height = random.intRangeAtMost(u8, 5, 15);
    const stalk_lean = random.intRangeAtMost(i8, -3, 3);
    const leaf_count = random.intRangeAtMost(u8, 0, 9);

    // Generate soil metrics
    const mycorrhizal_fungi = random.intRangeAtMost(
        u32,
        200,
        2400,
    );
    const bacterial_biomass = random.intRangeAtMost(
        u32,
        400,
        1800,
    );
    const protozoa_count = random.intRangeAtMost(
        u32,
        5000,
        25000,
    );
    const nematode_diversity = random.intRangeAtMost(u8, 8, 47);
    const earthworm_activity = random.intRangeAtMost(u8, 3, 18);
    const soil_respiration = 0.8 + random.float(f32) * 2.0;

    // System metrics
    const living_root_coverage = random.intRangeAtMost(
        u16,
        180,
        365,
    );
    const soil_carbon_sequestration = random.float(f32) * 1.2;
    const pest_damage = random.float(f32) * 5.0;
    const biodiversity_index = 3.0 + random.float(f32) * 7.0;

    // Calculate rarity
    const rarity_score = calculate_rarity(.{
        .stalk_height = stalk_height,
        .stalk_lean = stalk_lean,
        .leaf_count = leaf_count,
        .ecology_type = ecology_type,
    });

    // Generate companions
    const companions = try generate_companions(allocator, random,
ecology_type);

    return .{
        .seed = seed,
        .ecology_type = ecology_type,
        .season = season,
        .soil_type = soil_type,
        .weather = weather,
        .companions = companions,
        .mycorrhizal_fungi = mycorrhizal_fungi,
        .bacterial_biomass = bacterial_biomass,
        .protozoa_count = protozoa_count,
        .nematode_diversity = nematode_diversity,
        .earthworm_activity = earthworm_activity,
        .soil_respiration = soil_respiration,
        .living_root_coverage = living_root_coverage,
        .soil_carbon_sequestration = soil_carbon_sequestration,
        .pest_damage = pest_damage,
        .biodiversity_index = biodiversity_index,
        .stalk_height = stalk_height,
        .stalk_lean = stalk_lean,
        .leaf_count = leaf_count,
        .rarity_score = rarity_score,
    };
}

fn generate_companions(
    allocator: std.mem.Allocator,
    random: std.Random,
    ecology_type: types.EcologyType,
) ![]const types.CompanionPlant {
    var list: std.ArrayList(types.CompanionPlant) = .{
        .items = &.{},
        .capacity = 0,
    };
    errdefer list.deinit(allocator);

    // Base probability for any companion
    if (random.boolean()) try list.append(allocator, .clover);
    
    // Ecology specific companions
    switch (ecology_type) {
        .polyculture => {
            if (random.boolean()) try list.append(allocator, .vetch);
            if (random.boolean()) try list.append(allocator, .field_pea);
        },
        .wild_edges => {
            if (random.boolean()) try list.append(allocator, .yarrow);
            if (random.boolean()) try list.append(allocator, .chicory);
        },
        .minimal_disturbance => {
            if (random.boolean()) try list.append(allocator,
.creeping_thyme);
        },
        .cover_crop => {
            try list.append(allocator, .vetch);
            try list.append(allocator, .clover);
        },
        .selective_weeding => {
            if (random.boolean()) try list.append(allocator, .dandelion);
            if (random.boolean()) try list.append(allocator, .plantain);
        },
        .ecosystem_immune => {
            try list.append(allocator, .yarrow);
            try list.append(allocator, .fennel);
            try list.append(allocator, .dandelion);
        },
        else => {},
    }

    // Random additions for biodiversity
    if (random.intRangeAtMost(u8, 0, 10) > 8) {
        const all_companions = std.enums.values(types.CompanionPlant);
        const idx = random.intRangeAtMost(usize, 0, all_companions.len -
1);
        try list.append(allocator, all_companions[idx]);
    }

    return list.toOwnedSlice(allocator);
}

pub fn generate_stalk(
    allocator: std.mem.Allocator,
    params: types.EcologicalParams,
) ![]u8 {
    var buffer: std.ArrayList(u8) = .{ .items = &.{}, .capacity = 0 };
    errdefer buffer.deinit(allocator);

    var rng = std.Random.DefaultPrng.init(params.seed);
    const random = rng.random();

    // Grain head
    try buffer.appendSlice(allocator, "      . \n");
    try buffer.appendSlice(allocator, "    \\ | / \n");
    try buffer.appendSlice(allocator, "   --(@)-- \n");
    try buffer.appendSlice(allocator, "    / | \\ \n");
    try buffer.appendSlice(allocator, "      | \n");

    // Stalk segments
    var current_lean: i8 = 0;
    var leaves_placed: u8 = 0;
    
    var i: u8 = 0;
    while (i < params.stalk_height) : (i += 1) {
        const sway = random.intRangeAtMost(i8, -1, 1);
        current_lean += sway;
        
        if (current_lean < -3) current_lean = -3;
        if (current_lean > 3) current_lean = 3;

        // Calculate indent
        var indent: usize = 6;
        if (current_lean < 0) {
            indent -= @intCast(@abs(current_lean));
        }
        if (current_lean > 0) {
            indent += @intCast(@abs(current_lean));
        }

        // Add indentation
        var j: usize = 0;
        while (j < indent) : (j += 1) {
            try buffer.append(allocator, ' ');
        }

        // Determine if leaf should be placed
        const has_leaf_left = leaves_placed < params.leaf_count and
            random.boolean() and i % 3 == 0;
        const has_leaf_right = !has_leaf_left and
            leaves_placed < params.leaf_count and
            random.boolean() and i % 3 == 0;

        if (has_leaf_left) {
            try buffer.append(allocator, '(');
            leaves_placed += 1;
        }
        
        try buffer.append(allocator, '|');
        
        if (has_leaf_right) {
            try buffer.append(allocator, ')');
            leaves_placed += 1;
        }
        
        try buffer.append(allocator, '\n');
    }

    // Roots
    try buffer.appendSlice(allocator, "    ~~~~~ \n");

    return buffer.toOwnedSlice(allocator);
}

const RarityInput = struct {
    stalk_height: u8,
    stalk_lean: i8,
    leaf_count: u8,
    ecology_type: types.EcologyType,
};

pub fn calculate_rarity(input: RarityInput) u8 {
    var score: u8 = 0;

    // Perfect straight = rare
    if (input.stalk_lean == 0) score += 30;

    // Maximum height = rare
    if (input.stalk_height >= 14) score += 20;

    // Many leaves = rare
    if (input.leaf_count >= 6) score += 25;

    // Extreme lean = rare
    if (@abs(input.stalk_lean) >= 3) score += 15;

    // Special ecology types = bonus
    if (input.ecology_type == .ecosystem_immune) score += 20;
    if (input.ecology_type == .minimal_disturbance) score += 15;

    return score;
}

// === graincard/font8x8.zig ===

const std = @import("std");

// 8x8 Bitmap Font (ASCII 0-127)
// Public Domain / CC0
// Derived from 8x8 font collection

pub const CHAR_WIDTH = 8;
pub const CHAR_HEIGHT = 8;

pub const font_data = [128][8]u8{
    // 0x00 - 0x0F (Control codes - mostly empty/placeholder)
    .{ 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 }, // NUL
    .{ 0x7E, 0x81, 0xA5, 0x81, 0xBD, 0x99, 0x81, 0x7E }, // SOH (smiley)
    .{ 0x7E, 0xFF, 0xDB, 0xFF, 0xC3, 0xE7, 0xFF, 0x7E }, // STX (filled
smiley)
    .{ 0x6C, 0xFE, 0xFE, 0xFE, 0x7C, 0x38, 0x10, 0x00 }, // ETX (heart)
    .{ 0x10, 0x38, 0x7C, 0xFE, 0x7C, 0x38, 0x10, 0x00 }, // EOT (diamond)
    .{ 0x38, 0x7C, 0x38, 0xFE, 0xFE, 0x7C, 0x38, 0x7C }, // ENQ (club)
    .{ 0x10, 0x10, 0x38, 0x7C, 0xFE, 0x7C, 0x38, 0x7C }, // ACK (spade)
    .{ 0x00, 0x00, 0x18, 0x3C, 0x3C, 0x18, 0x00, 0x00 }, // BEL (dot)
    .{ 0xFF, 0xFF, 0xE7, 0xC3, 0xC3, 0xE7, 0xFF, 0xFF }, // BS (inverse
dot)
    .{ 0x00, 0x3C, 0x66, 0x42, 0x42, 0x66, 0x3C, 0x00 }, // HT (circle)
    .{ 0xFF, 0xC3, 0x99, 0xBD, 0xBD, 0x99, 0xC3, 0xFF }, // LF (inverse
circle)
    .{ 0x0F, 0x07, 0x0F, 0x7D, 0xCC, 0xCC, 0xCC, 0x78 }, // VT (male)
    .{ 0x3C, 0x66, 0x66, 0x66, 0x3C, 0x18, 0x7E, 0x18 }, // FF (female)
    .{ 0x3F, 0x33, 0x3F, 0x30, 0x30, 0x70, 0xF0, 0xE0 }, // CR (note)
    .{ 0x7F, 0x63, 0x7F, 0x63, 0x63, 0x67, 0xE6, 0xC0 }, // SO (music)
    .{ 0x99, 0x5A, 0x3C, 0xE7, 0xE7, 0x3C, 0x5A, 0x99 }, // SI (sun)

    // 0x10 - 0x1F
    .{ 0x80, 0xE0, 0xF8, 0xFE, 0xF8, 0xE0, 0x80, 0x00 }, // DLE (right
tri)
    .{ 0x02, 0x0E, 0x3E, 0xFE, 0x3E, 0x0E, 0x02, 0x00 }, // DC1 (left
tri)
    .{ 0x18, 0x3C, 0x7E, 0x18, 0x18, 0x7E, 0x3C, 0x18 }, // DC2 (up down
arrow)
    .{ 0x66, 0x66, 0x66, 0x66, 0x66, 0x00, 0x66, 0x00 }, // DC3 (!!)
    .{ 0x7F, 0xDB, 0xDB, 0x7B, 0x1B, 0x1B, 0x1B, 0x00 }, // DC4
(paragraph)
