pub fn get_char_bitmap(char: u8) [8]u8 {
    if (char > 127) return font_data[0]; // Return NUL for non-ASCII
    return font_data[char];
}

// === graincard/layout.zig ===

const std = @import("std");
const types = @import("types.zig");

// Graincard Layout Engine
// Handles 75x100 graincard assembly with 1-char borders

pub fn create_border(
    allocator: std.mem.Allocator,
    width: usize,
    height: usize,
) ![]u8 {
    var buffer: std.ArrayList(u8) = .{ .items = &.{}, .capacity = 0 };
    defer buffer.deinit(allocator);

    // Top border
    try buffer.append(allocator, '+');
    var i: usize = 0;
    while (i < width - 2) : (i += 1) {
        try buffer.append(allocator, '-');
    }
    try buffer.append(allocator, '+');
    try buffer.append(allocator, '\n');

    // Middle rows
    var row: usize = 0;
    while (row < height - 2) : (row += 1) {
        try buffer.append(allocator, '|');
        var col: usize = 0;
        while (col < width - 2) : (col += 1) {
            try buffer.append(allocator, ' ');
        }
        try buffer.append(allocator, '|');
        try buffer.append(allocator, '\n');
    }

    // Bottom border
    try buffer.append(allocator, '+');
    i = 0;
    while (i < width - 2) : (i += 1) {
        try buffer.append(allocator, '-');
    }
    try buffer.append(allocator, '+');
    try buffer.append(allocator, '\n');

    return buffer.toOwnedSlice(allocator);
}

pub fn wrap_content(
    allocator: std.mem.Allocator,
    content: []const u8,
    max_width: usize,
) ![][]u8 {
    var lines: std.ArrayList([]u8) = .{ .items = &.{}, .capacity = 0 };
    errdefer {
        for (lines.items) |line| allocator.free(line);
        lines.deinit(allocator);
    }

    var line_start: usize = 0;
    var i: usize = 0;

    while (i < content.len) {
        if (content[i] == '\n' or i - line_start >= max_width) {
            const line = try allocator.dupe(
                u8,
                content[line_start..i],
            );
            try lines.append(allocator, line);
            line_start = i + 1;
        }
        i += 1;
    }

    // Add remaining content
    if (line_start < content.len) {
        const line = try allocator.dupe(
            u8,
            content[line_start..],
        );
        try lines.append(allocator, line);
    }

    return lines.toOwnedSlice(allocator);
}

pub fn layout_graincard(
    allocator: std.mem.Allocator,
    config: types.GraincardConfig,
    content: types.GraincardContent,
) ![]u8 {
    var buffer: std.ArrayList(u8) = .{ .items = &.{}, .capacity = 0 };
    errdefer buffer.deinit(allocator);

    // 1. Top Border
    try buffer.append(allocator, config.border_top_bottom);
    var i: usize = 0;
    while (i < config.content_width) : (i += 1) {
        try buffer.append(allocator, config.border_horizontal);
    }
    try buffer.append(allocator, config.border_top_bottom);
    try buffer.append(allocator, '\n');

    // 2. Content Sections
    // Helper to process and pad each section
    try append_padded_section(allocator, &buffer, content.header,
config, false);
    try append_padded_section(allocator, &buffer, content.stalk_visual,
config, true); // Center the stalk
    try append_padded_section(allocator, &buffer, content.metrics_box,
config, false);
    
    // Footer needs special handling to be bottom-aligned if we were
doing full height,
    // but for now we just append it.
    try append_padded_section(allocator, &buffer, content.footer,
config, true); // Center footer

    // 3. Bottom Border
    try buffer.append(allocator, config.border_top_bottom);
    i = 0;
    while (i < config.content_width) : (i += 1) {
        try buffer.append(allocator, config.border_horizontal);
    }
    try buffer.append(allocator, config.border_top_bottom);
    try buffer.append(allocator, '\n');

    return buffer.toOwnedSlice(allocator);
}

fn append_padded_section(
    allocator: std.mem.Allocator,
    buffer: *std.ArrayList(u8),
    content: []const u8,
    config: types.GraincardConfig,
    center: bool,
) !void {
    var it = std.mem.splitScalar(u8, content, '\n');
    while (it.next()) |line| {
        // Skip empty lines at start/end if they are just artifacts of
string literals
        if (line.len == 0) continue;

        try buffer.append(allocator, config.border_char);
        
        // Calculate padding
        var visible_len: usize = 0;
        // TODO: Handle UTF-8 length properly if we use fancy chars
        visible_len = line.len;

        if (visible_len > config.content_width) {
            // Truncate if too long (shouldn't happen with good
generation)
            try buffer.appendSlice(allocator,
line[0..config.content_width]);
        } else {
            const padding = config.content_width - visible_len;
            if (center) {
                const left_pad = padding / 2;
                const right_pad = padding - left_pad;
                try append_spaces(allocator, buffer, left_pad);
                try buffer.appendSlice(allocator, line);
                try append_spaces(allocator, buffer, right_pad);
            } else {
                // Left align
                try buffer.appendSlice(allocator, line);
                try append_spaces(allocator, buffer, padding);
            }
        }

        try buffer.append(allocator, config.border_char);
        try buffer.append(allocator, '\n');
    }
}

fn append_spaces(allocator: std.mem.Allocator, buffer:
*std.ArrayList(u8), count: usize) !void {
    var i: usize = 0;
    while (i < count) : (i += 1) {
        try buffer.append(allocator, ' ');
    }
}

// === graincard/png_generator.zig ===

const std = @import("std");
const zigimg = @import("zigimg");
const font8x8 = @import("font8x8.zig");
const types = @import("types.zig");

pub const PngOptions = struct {
    scale: u8 = 1,
    background: u8 = 255, // White
    foreground: u8 = 0,   // Black
    include_borders: bool = true,
    stalk_only: bool = false,
};

pub fn ascii_to_png(
    allocator: std.mem.Allocator,
    ascii_art: []const u8,
    output_path: []const u8,
    options: PngOptions,
) !void {
    // 1. Parse ASCII art into lines to determine dimensions
    var lines: std.ArrayList([]const u8) = .{ .items = &.{}, .capacity =
0 };
    defer lines.deinit(allocator);

    var max_width: usize = 0;
    var it = std.mem.splitScalar(u8, ascii_art, '\n');
    while (it.next()) |line| {
        try lines.append(allocator, line);
        if (line.len > max_width) max_width = line.len;
    }

    // 2. Calculate image dimensions
    const char_w = font8x8.CHAR_WIDTH * options.scale;
    const char_h = font8x8.CHAR_HEIGHT * options.scale;
    const img_width = max_width * char_w;
    const img_height = lines.items.len * char_h;

    // 3. Create grayscale image
    var image = try zigimg.Image.create(allocator, img_width,
img_height, .grayscale8);
    defer image.deinit(allocator);

    // Fill background
    const bg_color = zigimg.color.Grayscale8{ .value =
options.background };
    const fg_color = zigimg.color.Grayscale8{ .value =
options.foreground };

    for (image.pixels.grayscale8) |*pixel| {
        pixel.* = bg_color;
    }

    // 4. Render characters
    for (lines.items, 0..) |line, row| {
        for (line, 0..) |char, col| {
            const bitmap = font8x8.get_char_bitmap(char);
            
            // Render 8x8 bitmap with scaling
            var by: usize = 0;
            while (by < 8) : (by += 1) {
                var bx: usize = 0;
                while (bx < 8) : (bx += 1) {
                    // Check if bit is set (bits are stored MSB first)
                    const bit_set = (bitmap[by] & (@as(u8, 1) <<
@intCast(7 - bx))) != 0;
                    
                    if (bit_set) {
                        // Draw scaled pixel(s)
                        var sy: usize = 0;
                        while (sy < options.scale) : (sy += 1) {
                            var sx: usize = 0;
                            while (sx < options.scale) : (sx += 1) {
                                const px = (col * char_w) + (bx *
options.scale) + sx;
                                const py = (row * char_h) + (by *
options.scale) + sy;
                                
                                if (px < img_width and py < img_height) {
                                    const pixel_idx = py * img_width +
px;
                                    image.pixels.grayscale8[pixel_idx] =
fg_color;
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // 5. Write PNG file
    const write_buffer = try allocator.alloc(u8, 4096);
    defer allocator.free(write_buffer);
    try image.writeToFilePath(allocator, output_path, write_buffer, .{
.png = .{} });
}

pub fn graincard_to_png(
    allocator: std.mem.Allocator,
    content: types.GraincardContent,
    output_path: []const u8,
    options: PngOptions,
) !void {
    // Combine content based on options
    var full_content: std.ArrayList(u8) = .{ .items = &.{}, .capacity =
0 };
    defer full_content.deinit(allocator);

    if (options.stalk_only) {
        try full_content.appendSlice(allocator, content.stalk_visual);
    } else {
        // Full card assembly (simplified for now, similar to layout.zig
but just text)
        // Note: layout.zig adds borders, here we assume content parts
are raw text
        // If we want exact match, we should use the output of
layout_graincard
        // But layout_graincard returns []u8, so we can just pass that
in!
        
        // For now, let's assume the caller passes the fully laid out
text if they want the full card.
        // If they pass raw content structs, we might need to layout it
first.
        // Let's change the signature to take []const u8 (the final text)
        return error.UseAsciiToPngDirectly; 
    }

    try ascii_to_png(allocator, full_content.items, output_path,
options);
}

// === graincard/types.zig ===

const std = @import("std");

// Graincard Types
// Data structures for 75x100 graincard generation

pub const GraincardConfig = struct {
    seed: u64,
    width: usize = 75,
    height: usize = 100,
    content_width: usize = 73,
    content_height: usize = 98,
