        };
        self.functions_len += 1;

        // toUpper(str) - Convert to uppercase
        const toupper_name = try self.allocator.dupe(u8, "toUpper");
        errdefer self.allocator.free(toupper_name);
        self.functions[self.functions_len] = Function{
