    /// Built-in trim function: Trim whitespace from string.
    // 2025-11-24-184000-pst: Active function
    fn builtin_trim(interpreter: *Interpreter, args: []const Value)
Error!Value {
        if (args.len != 1) {
            return Error.invalid_argument;
        }
        if (args[0] != .string) {
            return Error.type_mismatch;
        }
        const str = args[0].string;
        // Find start (skip whitespace)
        var start: u32 = 0;
        while (start < str.len and (str[start] == ' ' or str[start] ==
'\t' or str[start] == '\n' or str[start] == '\r')) : (start += 1) {}
        // Find end (skip whitespace from end)
        var end: u32 = str.len;
        while (end > start and (str[end - 1] == ' ' or str[end - 1] ==
'\t' or str[end - 1] == '\n' or str[end - 1] == '\r')) : (end -= 1) {}
        const trimmed = str[start..end];
        return try Value.from_string(interpreter.allocator, trimmed);
    }

