    // 2025-11-24-213900-pst: Active function
    fn builtin_join(interpreter: *Interpreter, args: []const Value)
Error!Value {
        if (args.len != 2) {
            return Error.invalid_argument;
        }
        // Simplified: join two strings with delimiter
        if (args[0] != .string or args[1] != .string) {
            return Error.type_mismatch;
        }
        const str1 = args[0].string;
        const delimiter = args[1].string;

        // Return first string + delimiter
        const result = try std.fmt.allocPrint(interpreter.allocator,
"{s}{s}", .{ str1, delimiter });
        errdefer interpreter.allocator.free(result);
        return try Value.from_string(interpreter.allocator, result);
    }

    /// Execute AST (evaluate all top-level statements).
    pub fn execute(self: *Interpreter) Error!void {
        // Assert: Interpreter must be initialized
        std.debug.assert(self.parser.get_node_count() > 0);

        // Get all AST nodes from parser
        const node_count = self.parser.get_node_count();
        var i: u32 = 0;
        while (i < node_count) : (i += 1) {
            const node = self.parser.get_node(i);
            if (node) |n| {
                // Execute statement or declaration
                _ = try self.execute_statement_or_declaration(n);
            }
        }
    }

    /// Execute statement or declaration.
    fn execute_statement_or_declaration(self: *Interpreter, node:
Parser.Node) Error!Value {
        return switch (node.node_type) {
            .stmt_expr => self.execute_expression_statement(node),
            .stmt_var => self.execute_variable_statement(node),
            .stmt_const => self.execute_constant_statement(node),
            .stmt_if => self.execute_if_statement(node),
            .stmt_while => self.execute_while_statement(node),
            .stmt_for => self.execute_for_statement(node),
            .stmt_return => self.execute_return_statement(node),
            .stmt_break => self.execute_break_statement(node),
            .stmt_continue => self.execute_continue_statement(node),
            .stmt_block => self.execute_block_statement(node),
            .decl_fn => self.execute_function_declaration(node),
            .decl_var => self.execute_variable_declaration(node),
            .decl_const => self.execute_constant_declaration(node),
            else => Error.runtime_error,
        };
    }

    /// Execute expression statement.
    fn execute_expression_statement(self: *Interpreter, node:
Parser.Node) Error!Value {
        // Assert: Node must be expression statement
        std.debug.assert(node.node_type == .stmt_expr);

        // Get expression from statement data (uses group data)
        const group_data = node.data.group;
        const expr_node = self.parser.get_node(group_data.expr) orelse
return Error.runtime_error;

        // Evaluate expression (discard result)
        _ = try self.evaluate_expression(expr_node);

        return Value.from_null();
    }

    /// Execute variable statement.
    fn execute_variable_statement(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be variable statement
        std.debug.assert(node.node_type == .stmt_var);

        const stmt_data = node.data.var_stmt;

        // Check if variable already exists
        if (self.find_variable(stmt_data.name) != null) {
            return Error.variable_already_exists;
        }

        // Check variable limit
        if (self.variables_len >= MAX_VARIABLES) {
            return Error.too_many_variables;
        }

        // Evaluate initializer (if any)
        var value = Value.from_null();
        var inferred_type: ?VariableType = null;

        if (stmt_data.init) |init_node_idx| {
            const init_node = self.parser.get_node(init_node_idx) orelse
return Error.runtime_error;
            value = try self.evaluate_expression(init_node);

            // Type inference: infer type from initializer if not
explicitly declared
            if (stmt_data.type_node == null) {
                const inferred_type_name = try
self.infer_type_from_value(value);
                const type_name_copy = try self.allocator.dupe(u8,
inferred_type_name);
                errdefer self.allocator.free(type_name_copy);

                inferred_type = VariableType{
                    .type_name = type_name_copy,
                    .type_name_len = @as(u32,
@intCast(type_name_copy.len)),
                    .is_inferred = true,
                };
            }
        }

        // Parse declared type (if any)
        var declared_type: ?VariableType = null;
        if (stmt_data.type_node) |type_node_idx| {
            const type_node = self.parser.get_node(type_node_idx) orelse
return Error.runtime_error;
            if (type_node.node_type == .type_named) {
                const type_name = type_node.data.type_named.name;
                const type_name_copy = try self.allocator.dupe(u8,
type_name);
                errdefer self.allocator.free(type_name_copy);

                declared_type = VariableType{
                    .type_name = type_name_copy,
                    .type_name_len = @as(u32,
@intCast(type_name_copy.len)),
                    .is_inferred = false,
                };

                // Type checking: verify initializer matches declared
type
                if (stmt_data.init) |init_node_idx| {
                    const init_node =
self.parser.get_node(init_node_idx) orelse return Error.runtime_error;
                    const init_value = try
self.evaluate_expression(init_node);
                    if (!self.value_matches_type(init_value, type_name))
{
                        return Error.type_mismatch;
                    }
                }
            }
        }

        // Use declared type if available, otherwise use inferred type
        const var_type = declared_type orelse inferred_type;

        // Allocate variable name
        const var_name = try self.allocator.dupe(u8, stmt_data.name);
        errdefer self.allocator.free(var_name);

        // Store variable (with scope information and type)
        self.variables[self.variables_len] = Variable{
            .name = var_name,
            .name_len = @as(u32, @intCast(var_name.len)),
            .value = value,
            .is_const = false,
            .scope = if (self.scope_depth == 0) .global else .local,
            .scope_depth = self.scope_depth,
            .var_type = var_type,
        };
        self.variables_len += 1;

        return Value.from_null();
    }

    /// Execute constant statement.
    fn execute_constant_statement(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be constant statement
        std.debug.assert(node.node_type == .stmt_const);

        const stmt_data = node.data.var_stmt; // Reuse VarStmtData

        // Check if variable already exists
        if (self.find_variable(stmt_data.name) != null) {
            return Error.variable_already_exists;
        }

        // Check variable limit
        if (self.variables_len >= MAX_VARIABLES) {
            return Error.too_many_variables;
        }

        // Evaluate initializer (required for constants)
        const init_node_idx = stmt_data.init orelse return
Error.runtime_error;
        const init_node = self.parser.get_node(init_node_idx) orelse
return Error.runtime_error;
        const value = try self.evaluate_expression(init_node);

        // Allocate variable name
        const var_name = try self.allocator.dupe(u8, stmt_data.name);
        errdefer self.allocator.free(var_name);

        // Type inference: infer type from initializer if not explicitly
declared
        var inferred_type: ?VariableType = null;
        if (stmt_data.type_node == null) {
            const inferred_type_name = try
self.infer_type_from_value(value);
            const type_name_copy = try self.allocator.dupe(u8,
inferred_type_name);
            errdefer self.allocator.free(type_name_copy);

            inferred_type = VariableType{
                .type_name = type_name_copy,
                .type_name_len = @as(u32, @intCast(type_name_copy.len)),
                .is_inferred = true,
            };
        }

        // Parse declared type (if any)
        var declared_type: ?VariableType = null;
        if (stmt_data.type_node) |type_node_idx| {
            const type_node = self.parser.get_node(type_node_idx) orelse
return Error.runtime_error;
            if (type_node.node_type == .type_named) {
                const type_name = type_node.data.type_named.name;
                const type_name_copy = try self.allocator.dupe(u8,
type_name);
                errdefer self.allocator.free(type_name_copy);

                declared_type = VariableType{
                    .type_name = type_name_copy,
                    .type_name_len = @as(u32,
@intCast(type_name_copy.len)),
                    .is_inferred = false,
                };

                // Type checking: verify initializer matches declared
type
                if (!self.value_matches_type(value, type_name)) {
                    return Error.type_mismatch;
                }
            }
        }

        // Use declared type if available, otherwise use inferred type
        const var_type = declared_type orelse inferred_type;

        // Store variable (as constant, with scope information and type)
        self.variables[self.variables_len] = Variable{
            .name = var_name,
            .name_len = @as(u32, @intCast(var_name.len)),
            .value = value,
            .is_const = true,
            .scope = if (self.scope_depth == 0) .global else .local,
            .scope_depth = self.scope_depth,
            .var_type = var_type,
        };
        self.variables_len += 1;

        return Value.from_null();
    }

    /// Execute if statement.
    fn execute_if_statement(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be if statement
        std.debug.assert(node.node_type == .stmt_if);

        const stmt_data = node.data.if_stmt;

        // Evaluate condition
        const condition_node = self.parser.get_node(stmt_data.condition)
orelse return Error.runtime_error;
        const condition_value = try
self.evaluate_expression(condition_node);
        const condition_bool = condition_value.to_boolean();

        // Execute then or else block
        if (condition_bool) {
            const then_node = self.parser.get_node(stmt_data.then_block)
orelse return Error.runtime_error;
            return self.execute_block_statement(then_node);
        } else if (stmt_data.else_block) |else_node_idx| {
            const else_node = self.parser.get_node(else_node_idx) orelse
return Error.runtime_error;
            return self.execute_block_statement(else_node);
        }

        return Value.from_null();
    }

    /// Execute while statement.
    fn execute_while_statement(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be while statement
        std.debug.assert(node.node_type == .stmt_while);

        const stmt_data = node.data.while_stmt;

        // Loop while condition is true
        while (true) {
            // Reset control flow signal at start of iteration
            self.control_flow_signal = .none;

            const condition_node =
self.parser.get_node(stmt_data.condition) orelse return
Error.runtime_error;
            const condition_value = try
self.evaluate_expression(condition_node);
            const condition_bool = condition_value.to_boolean();

            if (!condition_bool) {
                break;
            }

            const body_node = self.parser.get_node(stmt_data.body)
orelse return Error.runtime_error;
            _ = try self.execute_block_statement(body_node);

            // Check for break signal
            if (self.control_flow_signal == .break_loop) {
                self.control_flow_signal = .none;
                break;
            }

            // Continue signal is handled by loop iteration (already at
top)
            if (self.control_flow_signal == .continue_loop) {
                self.control_flow_signal = .none;
                continue;
            }
        }

        // Reset control flow signal after loop
        self.control_flow_signal = .none;

        return Value.from_null();
    }

    /// Execute for statement.
    fn execute_for_statement(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be for statement
        std.debug.assert(node.node_type == .stmt_for);

        const stmt_data = node.data.for_stmt;

        // Execute initializer (if any)
        if (stmt_data.init) |init_node_idx| {
            const init_node = self.parser.get_node(init_node_idx) orelse
return Error.runtime_error;
            _ = try self.execute_statement_or_declaration(init_node);
        }

        // Loop while condition is true
        while (true) {
            // Reset control flow signal at start of iteration
            self.control_flow_signal = .none;

            // Check condition (if any)
            if (stmt_data.condition) |condition_node_idx| {
                const condition_node =
self.parser.get_node(condition_node_idx) orelse return
Error.runtime_error;
                const condition_value = try
self.evaluate_expression(condition_node);
                const condition_bool = condition_value.to_boolean();

                if (!condition_bool) {
                    break;
                }
            }

            // Execute body
            const body_node = self.parser.get_node(stmt_data.body)
orelse return Error.runtime_error;
            _ = try self.execute_block_statement(body_node);

            // Check for break signal (before update)
            if (self.control_flow_signal == .break_loop) {
                self.control_flow_signal = .none;
                break;
            }

            // Check for continue signal (skip update, go to next
iteration)
            if (self.control_flow_signal == .continue_loop) {
                self.control_flow_signal = .none;
                // Skip update and continue to next iteration
                continue;
            }

            // Execute update (if any)
            if (stmt_data.update) |update_node_idx| {
                const update_node =
self.parser.get_node(update_node_idx) orelse return Error.runtime_error;
                _ = try self.evaluate_expression(update_node);
            }
        }

        // Reset control flow signal after loop
        self.control_flow_signal = .none;

        return Value.from_null();
    }

    /// Execute return statement.
    // 2025-11-24-183000-pst: Active function
    fn execute_return_statement(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be return statement
        std.debug.assert(node.node_type == .stmt_return);

        const stmt_data = node.data.return_stmt;

        // Evaluate return value (if any)
        var return_value: Value = Value.from_null();
        if (stmt_data.value) |value_node_idx| {
            const value_node = self.parser.get_node(value_node_idx)
orelse return Error.runtime_error;
            return_value = try self.evaluate_expression(value_node);
        }

        // Store return value in current call frame (if in function)
        if (self.call_stack_len > 0) {
            const frame_idx = self.call_stack_len - 1;
            // Copy return value (for strings, allocate new copy)
            if (return_value == .string) {
                const return_val_copy = try
Value.from_string(self.allocator, return_value.string);
                self.call_stack[frame_idx].return_value =
return_val_copy;
            } else {
                self.call_stack[frame_idx].return_value = return_value;
            }
        }

        return return_value;
    }

    /// Execute break statement.
    fn execute_break_statement(self: *Interpreter, node: Parser.Node)
Error!Value {
        _ = node; // Unused for now
        // Set break signal
        self.control_flow_signal = .break_loop;
        return Value.from_null();
    }

    /// Execute continue statement.
    fn execute_continue_statement(self: *Interpreter, node: Parser.Node)
Error!Value {
        _ = node; // Unused for now
        // Set continue signal
        self.control_flow_signal = .continue_loop;
        return Value.from_null();
    }

    /// Execute block statement.
    fn execute_block_statement(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be block statement
        std.debug.assert(node.node_type == .stmt_block);

        const stmt_data = node.data.block;

        // Enter new scope
        const old_scope_depth = self.scope_depth;
        self.scope_depth += 1;
        defer self.scope_depth = old_scope_depth;

        // Track variables created in this scope
        const vars_before = self.variables_len;

        // Execute all statements in block
        var i: u32 = 0;
        while (i < stmt_data.statements_len) : (i += 1) {
            // Check for break/continue signal (propagate to loop)
            if (self.control_flow_signal != .none) {
                break;
            }

            // Check for return value in call frame (function returned)
            if (self.call_stack_len > 0) {
                const frame_idx = self.call_stack_len - 1;
                if (self.call_stack[frame_idx].return_value != null) {
                    break; // Function returned, stop executing
                }
            }

            const stmt_node_idx = stmt_data.statements[i];
            const stmt_node = self.parser.get_node(stmt_node_idx) orelse
return Error.runtime_error;
            _ = try self.execute_statement_or_declaration(stmt_node);

            // Check for break/continue signal after statement
            if (self.control_flow_signal != .none) {
                break;
            }

            // Check for return value after statement
            if (self.call_stack_len > 0) {
                const frame_idx = self.call_stack_len - 1;
                if (self.call_stack[frame_idx].return_value != null) {
                    break; // Function returned, stop executing
                }
            }
        }

        // Clean up local variables (free string values)
        while (self.variables_len > vars_before) {
            self.variables_len -= 1;
            const variable = &self.variables[self.variables_len];
            variable.value.deinit(self.allocator);
            self.allocator.free(variable.name);
        }

        return Value.from_null();
    }

    /// Execute function declaration.
    fn execute_function_declaration(self: *Interpreter, node:
Parser.Node) Error!Value {
        // Assert: Node must be function declaration
        std.debug.assert(node.node_type == .decl_fn);

        const decl_data = node.data.fn_decl;

        // Check if function already exists
        if (self.find_function(decl_data.name) != null) {
            return Error.runtime_error; // Function already defined
        }

        // Check function limit
        if (self.functions_len >= MAX_FUNCTIONS) {
            return Error.too_many_functions;
        }

        // Allocate function name
        const fn_name = try self.allocator.dupe(u8, decl_data.name);
        errdefer self.allocator.free(fn_name);

        // Store function (user-defined)
        self.functions[self.functions_len] = Function{
            .name = fn_name,
            .name_len = @as(u32, @intCast(fn_name.len)),
            .is_builtin = false,
            .param_count = decl_data.params_len,
            .body_node = decl_data.body,
            .builtin_handler = null,
        };
        self.functions_len += 1;

        return Value.from_null();
    }

    /// Execute variable declaration (top-level).
    fn execute_variable_declaration(self: *Interpreter, node:
Parser.Node) Error!Value {
        // Assert: Node must be variable declaration
        std.debug.assert(node.node_type == .decl_var);

        // Reuse variable statement logic
        const var_node = Parser.Node{
            .node_type = .stmt_var,
            .start = node.start,
            .end = node.end,
            .line = node.line,
            .column = node.column,
            .depth = node.depth,
            .data = node.data,
        };

        return self.execute_variable_statement(var_node);
    }

    /// Execute constant declaration (top-level).
    fn execute_constant_declaration(self: *Interpreter, node:
Parser.Node) Error!Value {
        // Assert: Node must be constant declaration
        std.debug.assert(node.node_type == .decl_const);

        // Reuse constant statement logic
        const const_node = Parser.Node{
            .node_type = .stmt_const,
            .start = node.start,
            .end = node.end,
            .line = node.line,
            .column = node.column,
            .depth = node.depth,
            .data = node.data,
        };

        return self.execute_constant_statement(const_node);
    }

    /// Evaluate expression.
    fn evaluate_expression(self: *Interpreter, node: Parser.Node)
Error!Value {
        return switch (node.node_type) {
            .expr_literal => self.evaluate_literal_expression(node),
            .expr_identifier =>
self.evaluate_identifier_expression(node),
            .expr_binary => self.evaluate_binary_expression(node),
            .expr_unary => self.evaluate_unary_expression(node),
            .expr_call => self.evaluate_call_expression(node),
            .expr_group => self.evaluate_group_expression(node),
            .expr_assign => self.evaluate_assign_expression(node),
            else => Error.runtime_error,
        };
    }

    /// Evaluate literal expression.
    fn evaluate_literal_expression(self: *Interpreter, node:
Parser.Node) Error!Value {
        // Assert: Node must be literal expression
        std.debug.assert(node.node_type == .expr_literal);

        const literal_data = node.data.literal;

        return switch (literal_data.literal_type) {
            .integer => blk: {
                const int_val = std.fmt.parseInt(i64,
literal_data.value, 10) catch return Error.runtime_error;
                break :blk Value.from_integer(int_val);
            },
            .float => blk: {
                const float_val = std.fmt.parseFloat(f64,
literal_data.value) catch return Error.runtime_error;
                break :blk Value.from_float(float_val);
            },
            .string => blk: {
                // Remove quotes and unescape
                const str_val = literal_data.value;
                if (str_val.len < 2) {
                    return Error.runtime_error;
                }
                const unquoted = str_val[1..str_val.len-1]; // Remove
quotes
                break :blk try Value.from_string(self.allocator,
unquoted);
            },
            .boolean_true => Value.from_boolean(true),
            .boolean_false => Value.from_boolean(false),
            .null => Value.from_null(),
        };
    }

    /// Evaluate identifier expression.
    fn evaluate_identifier_expression(self: *Interpreter, node:
Parser.Node) Error!Value {
        // Assert: Node must be identifier expression
        std.debug.assert(node.node_type == .expr_identifier);

        const identifier_data = node.data.identifier;

        // Find variable
        const variable = self.find_variable(identifier_data.name) orelse
{
            return Error.variable_not_found;
        };

        // Return variable value (copy for strings)
        return switch (variable.value) {
            .integer => |v| Value.from_integer(v),
            .float => |v| Value.from_float(v),
            .string => |v| blk: {
                // Copy string value
                break :blk try Value.from_string(self.allocator, v);
            },
            .boolean => |v| Value.from_boolean(v),
            .null => Value.from_null(),
        };
    }

    /// Evaluate binary expression.
    fn evaluate_binary_expression(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be binary expression
        std.debug.assert(node.node_type == .expr_binary);

        const binary_data = node.data.binary;

        // Evaluate operands
        const left_node = self.parser.get_node(binary_data.left) orelse
return Error.runtime_error;
        const right_node = self.parser.get_node(binary_data.right)
orelse return Error.runtime_error;
        const left_value = try self.evaluate_expression(left_node);
        const right_value = try self.evaluate_expression(right_node);

        // Perform operation
        return switch (binary_data.operator) {
            .add => self.binary_add(left_value, right_value),
            .subtract => self.binary_subtract(left_value, right_value),
            .multiply => self.binary_multiply(left_value, right_value),
            .divide => self.binary_divide(left_value, right_value),
            .modulo => self.binary_modulo(left_value, right_value),
            .eq => self.binary_eq(left_value, right_value),
            .ne => self.binary_ne(left_value, right_value),
            .lt => self.binary_lt(left_value, right_value),
            .le => self.binary_le(left_value, right_value),
            .gt => self.binary_gt(left_value, right_value),
            .ge => self.binary_ge(left_value, right_value),
            .and_op => self.binary_and(left_value, right_value),
            .or_op => self.binary_or(left_value, right_value),
        };
    }

    /// Binary addition.
    // 2025-11-23-160254-pst: Active function
    fn binary_add(self: *Interpreter, left: Value, right: Value)
Error!Value {
        // self will be used in full implementation for context
        return switch (left) {
            .integer => |l| switch (right) {
                .integer => |r| Value.from_integer(l + r),
                .float => |r| Value.from_float(@as(f64,
@floatFromInt(l)) + r),
                else => Error.type_mismatch,
            },
            .float => |l| switch (right) {
                .integer => |r| Value.from_float(l + @as(f64,
@floatFromInt(r))),
                .float => |r| Value.from_float(l + r),
                else => Error.type_mismatch,
            },
            .string => |l| switch (right) {
                .string => |r| {
                    // Concatenate strings
                    const combined = std.fmt.allocPrint(self.allocator,
"{s}{s}", .{ l, r }) catch return Error.OutOfMemory;
                    errdefer self.allocator.free(combined);
                    return try Value.from_string(self.allocator,
combined);
                },
                else => Error.type_mismatch,
            },
            else => Error.type_mismatch,
        };
    }

    /// Binary subtraction.
    fn binary_subtract(self: *Interpreter, left: Value, right: Value)
Error!Value {
        _ = self;
        return switch (left) {
            .integer => |l| switch (right) {
                .integer => |r| Value.from_integer(l - r),
                .float => |r| Value.from_float(@as(f64,
@floatFromInt(l)) - r),
                else => Error.type_mismatch,
            },
            .float => |l| switch (right) {
                .integer => |r| Value.from_float(l - @as(f64,
@floatFromInt(r))),
                .float => |r| Value.from_float(l - r),
                else => Error.type_mismatch,
            },
            else => Error.type_mismatch,
        };
    }

    /// Binary multiplication.
    fn binary_multiply(self: *Interpreter, left: Value, right: Value)
Error!Value {
        _ = self;
        return switch (left) {
            .integer => |l| switch (right) {
                .integer => |r| Value.from_integer(l * r),
                .float => |r| Value.from_float(@as(f64,
@floatFromInt(l)) * r),
                else => Error.type_mismatch,
            },
            .float => |l| switch (right) {
                .integer => |r| Value.from_float(l * @as(f64,
@floatFromInt(r))),
                .float => |r| Value.from_float(l * r),
                else => Error.type_mismatch,
            },
            else => Error.type_mismatch,
        };
    }

    /// Binary division.
    fn binary_divide(self: *Interpreter, left: Value, right: Value)
Error!Value {
        _ = self;
        return switch (left) {
            .integer => |l| switch (right) {
                .integer => |r| {
                    if (r == 0) {
                        return Error.division_by_zero;
                    }
                    return Value.from_integer(@divTrunc(l, r));
                },
                .float => |r| {
                    if (r == 0.0) {
                        return Error.division_by_zero;
                    }
                    return Value.from_float(@as(f64, @floatFromInt(l)) /
r);
                },
                else => Error.type_mismatch,
            },
            .float => |l| switch (right) {
                .integer => |r| {
                    if (r == 0) {
                        return Error.division_by_zero;
                    }
                    return Value.from_float(l / @as(f64,
@floatFromInt(r)));
                },
                .float => |r| {
                    if (r == 0.0) {
                        return Error.division_by_zero;
                    }
                    return Value.from_float(l / r);
                },
                else => Error.type_mismatch,
            },
            else => Error.type_mismatch,
        };
    }

    /// Binary modulo.
    fn binary_modulo(self: *Interpreter, left: Value, right: Value)
Error!Value {
        _ = self;
        return switch (left) {
            .integer => |l| switch (right) {
                .integer => |r| {
                    if (r == 0) {
                        return Error.division_by_zero;
                    }
                    return Value.from_integer(@mod(l, r));
                },
                else => Error.type_mismatch,
            },
            else => Error.type_mismatch,
        };
    }

    /// Binary equality.
    fn binary_eq(self: *Interpreter, left: Value, right: Value)
Error!Value {
        _ = self;
        return switch (left) {
            .integer => |l| switch (right) {
                .integer => |r| Value.from_boolean(l == r),
                .float => |r| Value.from_boolean(@as(f64,
@floatFromInt(l)) == r),
                else => Value.from_boolean(false),
            },
            .float => |l| switch (right) {
                .integer => |r| Value.from_boolean(l == @as(f64,
@floatFromInt(r))),
                .float => |r| Value.from_boolean(l == r),
                else => Value.from_boolean(false),
            },
            .string => |l| switch (right) {
                .string => |r| Value.from_boolean(std.mem.eql(u8, l, r)),
                else => Value.from_boolean(false),
            },
            .boolean => |l| switch (right) {
                .boolean => |r| Value.from_boolean(l == r),
                else => Value.from_boolean(false),
            },
            .null => switch (right) {
                .null => Value.from_boolean(true),
                else => Value.from_boolean(false),
            },
        };
    }

    /// Binary inequality.
    fn binary_ne(self: *Interpreter, left: Value, right: Value)
Error!Value {
        const eq_result = try self.binary_eq(left, right);
        return Value.from_boolean(!eq_result.to_boolean());
    }

    /// Binary less than.
    fn binary_lt(self: *Interpreter, left: Value, right: Value)
Error!Value {
        _ = self;
        return switch (left) {
            .integer => |l| switch (right) {
                .integer => |r| Value.from_boolean(l < r),
                .float => |r| Value.from_boolean(@as(f64,
@floatFromInt(l)) < r),
                else => Error.type_mismatch,
            },
            .float => |l| switch (right) {
                .integer => |r| Value.from_boolean(l < @as(f64,
@floatFromInt(r))),
                .float => |r| Value.from_boolean(l < r),
                else => Error.type_mismatch,
            },
            .string => |l| switch (right) {
                .string => |r| Value.from_boolean(std.mem.order(u8, l,
r) == .lt),
                else => Error.type_mismatch,
            },
            else => Error.type_mismatch,
        };
    }

    /// Binary less than or equal.
    fn binary_le(self: *Interpreter, left: Value, right: Value)
Error!Value {
        const lt_result = try self.binary_lt(left, right);
        const eq_result = try self.binary_eq(left, right);
        return Value.from_boolean(lt_result.to_boolean() or
eq_result.to_boolean());
    }

    /// Binary greater than.
    fn binary_gt(self: *Interpreter, left: Value, right: Value)
Error!Value {
        const le_result = try self.binary_le(left, right);
        return Value.from_boolean(!le_result.to_boolean());
    }

    /// Binary greater than or equal.
    fn binary_ge(self: *Interpreter, left: Value, right: Value)
Error!Value {
        const lt_result = try self.binary_lt(left, right);
        return Value.from_boolean(!lt_result.to_boolean());
    }

    /// Binary logical AND.
    fn binary_and(self: *Interpreter, left: Value, right: Value)
Error!Value {
        _ = self;
        const left_bool = left.to_boolean();
        if (!left_bool) {
            return Value.from_boolean(false);
        }
        return Value.from_boolean(right.to_boolean());
    }

    /// Binary logical OR.
    fn binary_or(self: *Interpreter, left: Value, right: Value)
Error!Value {
        _ = self;
        const left_bool = left.to_boolean();
        if (left_bool) {
            return Value.from_boolean(true);
        }
        return Value.from_boolean(right.to_boolean());
    }

    /// Evaluate unary expression.
    fn evaluate_unary_expression(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be unary expression
        std.debug.assert(node.node_type == .expr_unary);

        const unary_data = node.data.unary;

        // Evaluate operand
        const operand_node = self.parser.get_node(unary_data.operand)
orelse return Error.runtime_error;
        const operand_value = try self.evaluate_expression(operand_node);

        // Perform operation
        return switch (unary_data.operator) {
            .not => Value.from_boolean(!operand_value.to_boolean()),
            .negate => switch (operand_value) {
                .integer => |v| Value.from_integer(-v),
                .float => |v| Value.from_float(-v),
                else => Error.type_mismatch,
            },
        };
    }

    /// Evaluate call expression.
    fn evaluate_call_expression(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be call expression
        std.debug.assert(node.node_type == .expr_call);

        const call_data = node.data.call;

        // Get function name
        const callee_node = self.parser.get_node(call_data.callee)
orelse return Error.runtime_error;
        if (callee_node.node_type != .expr_identifier) {
            return Error.runtime_error;
        }
        const function_name = callee_node.data.identifier.name;

        // Find function
        const function = self.find_function(function_name) orelse {
            return Error.function_not_found;
        };

        // Evaluate arguments
        if (call_data.args_len > MAX_CALL_ARGS) {
            return Error.too_many_call_args;
        }

        var args: [MAX_CALL_ARGS]Value = undefined;
        var args_len: u32 = 0;
        var i: u32 = 0;
        while (i < call_data.args_len) : (i += 1) {
            const arg_node_idx = call_data.args[i];
            const arg_node = self.parser.get_node(arg_node_idx) orelse
return Error.runtime_error;
            args[args_len] = try self.evaluate_expression(arg_node);
            args_len += 1;
        }

        // Call function (built-in or user-defined)
        if (function.is_builtin) {
            if (function.builtin_handler) |handler| {
                return handler(self, args[0..args_len]);
            } else {
                return Error.runtime_error;
            }
        } else {
            // User-defined function call
            return self.call_user_function(function, args[0..args_len]);
        }
    }

    /// Call user-defined function.
    // 2025-11-24-183000-pst: Active function
    fn call_user_function(self: *Interpreter, function: *const Function,
args: []const Value) Error!Value {
        // Assert: Function must be user-defined
        std.debug.assert(!function.is_builtin);
        std.debug.assert(function.body_node != null);

        // Check call stack depth
        if (self.call_stack_len >= MAX_CALL_STACK) {
            return Error.call_stack_overflow;
        }

        // Check argument count matches parameter count
        if (args.len != function.param_count) {
            return Error.invalid_argument;
        }

        // Get function declaration node to access parameters
        const fn_decl_node_idx =
self.find_function_decl_node(function.name) orelse return
Error.runtime_error;
        const fn_decl_node = self.parser.get_node(fn_decl_node_idx)
orelse return Error.runtime_error;
        if (fn_decl_node.node_type != .decl_fn) {
            return Error.runtime_error;
        }
        const fn_decl_data = fn_decl_node.data.fn_decl;

        // Push call frame
        const frame_start = self.call_stack_len;
        self.call_stack[frame_start] = CallFrame{
            .function_name = function.name,
            .return_value = null,
            .local_vars_start = self.variables_len,
            .local_vars_count = 0,
        };
        self.call_stack_len += 1;

        // Create local variables for parameters
        var param_idx: u32 = 0;
        while (param_idx < fn_decl_data.params_len) : (param_idx += 1) {
            const param_node_idx = fn_decl_data.params[param_idx];
            const param_node = self.parser.get_node(param_node_idx)
orelse {
                // Clean up call frame
                self.call_stack_len -= 1;
                return Error.runtime_error;
            };

            // Parameter should be identifier (parameter name)
            if (param_node.node_type != .expr_identifier) {
                self.call_stack_len -= 1;
                return Error.runtime_error;
            }

            const param_name = param_node.data.identifier.name;
            const arg_value = args[param_idx];

            // Create local variable for parameter
            if (self.variables_len >= MAX_VARIABLES) {
                self.call_stack_len -= 1;
                return Error.too_many_variables;
            }

            const param_name_copy = try self.allocator.dupe(u8,
param_name);
            errdefer self.allocator.free(param_name_copy);

            // Copy argument value (for strings, allocate new copy)
            var param_value = arg_value;
            if (arg_value == .string) {
                param_value = try Value.from_string(self.allocator,
arg_value.string);
            }

            self.variables[self.variables_len] = Variable{
                .name = param_name_copy,
                .name_len = @as(u32, @intCast(param_name_copy.len)),
                .value = param_value,
                .is_const = false,
                .scope = .local,
                .scope_depth = self.scope_depth + 1,
                .var_type = null,
            };
            self.variables_len += 1;
            self.call_stack[frame_start].local_vars_count += 1;
        }

        // Increment scope depth
        const old_scope_depth = self.scope_depth;
        self.scope_depth += 1;

        // Execute function body
        const body_node_idx = function.body_node.?;
        const body_node = self.parser.get_node(body_node_idx) orelse {
            // Clean up
            self.cleanup_call_frame(frame_start);
            self.scope_depth = old_scope_depth;
            return Error.runtime_error;
        };

        // Execute function body
        if (body_node.node_type == .stmt_block) {
            // Execute block (may contain return statement)
            _ = self.execute_block_statement(body_node) catch |err| {
                // Clean up on error
                self.cleanup_call_frame(frame_start);
                self.scope_depth = old_scope_depth;
                return err;
            };
        } else {
            // Single statement body (could be return statement)
            _ = self.execute_statement(body_node) catch |err| {
                self.cleanup_call_frame(frame_start);
                self.scope_depth = old_scope_depth;
                return err;
            };
        }

        // Restore scope depth
        self.scope_depth = old_scope_depth;

        // Get return value from call frame (if set by return statement)
        // Must get before cleanup (cleanup pops frame)
        const frame_return = if (frame_start < self.call_stack_len)
self.call_stack[frame_start].return_value else null;

        // Clean up call frame (free local variables)
        self.cleanup_call_frame(frame_start);

        // Return value (or null if no return statement)
        if (frame_return) |val| {
            // Copy return value (for strings, allocate new copy)
            if (val == .string) {
                return try Value.from_string(self.allocator, val.string);
            } else {
                return val;
            }
        } else {
            return Value.from_null();
        }
    }

    /// Find function declaration node by name.
    // 2025-11-24-183000-pst: Active function
    fn find_function_decl_node(self: *const Interpreter, name: []const
u8) ?u32 {
        // Search through parser nodes for function declaration
        var i: u32 = 0;
        while (i < self.parser.get_node_count()) : (i += 1) {
            const node = self.parser.get_node(i) orelse continue;
            if (node.node_type == .decl_fn) {
                const fn_decl_data = node.data.fn_decl;
                if (std.mem.eql(u8, fn_decl_data.name, name)) {
                    return i;
                }
            }
        }
        return null;
    }

    /// Clean up call frame (free local variables, but preserve return
value).
    // 2025-11-24-183000-pst: Active function
    fn cleanup_call_frame(self: *Interpreter, frame_idx: u32) void {
        std.debug.assert(frame_idx < self.call_stack_len);
        const frame = &self.call_stack[frame_idx];

        // Free local variables
        var i: u32 = 0;
        while (i < frame.local_vars_count) : (i += 1) {
            const var_idx = frame.local_vars_start + i;
            if (var_idx < self.variables_len) {
                const variable = &self.variables[var_idx];
                // Free variable name
                self.allocator.free(variable.name);
                // Free variable value (if string)
                variable.value.deinit(self.allocator);
            }
        }

        // Remove variables from array (shift remaining variables)
        const vars_to_remove = frame.local_vars_count;
        if (vars_to_remove > 0 and frame.local_vars_start +
vars_to_remove < self.variables_len) {
            const remaining_count = self.variables_len -
(frame.local_vars_start + vars_to_remove);
            var j: u32 = 0;
            while (j < remaining_count) : (j += 1) {
                const src_idx = frame.local_vars_start + vars_to_remove
+ j;
                const dst_idx = frame.local_vars_start + j;
                self.variables[dst_idx] = self.variables[src_idx];
            }
        }
        self.variables_len -= vars_to_remove;

        // Note: return_value is preserved in frame until caller uses it
        // Pop call frame (return_value will be copied by caller if
needed)
        self.call_stack_len -= 1;
    }

    /// Evaluate group expression.
    fn evaluate_group_expression(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be group expression
        std.debug.assert(node.node_type == .expr_group);

        const group_data = node.data.group;

        // Evaluate inner expression
        const expr_node = self.parser.get_node(group_data.expr) orelse
return Error.runtime_error;
        return self.evaluate_expression(expr_node);
    }

    /// Evaluate assignment expression.
    fn evaluate_assign_expression(self: *Interpreter, node: Parser.Node)
Error!Value {
        // Assert: Node must be assignment expression
        std.debug.assert(node.node_type == .expr_assign);

        const assign_data = node.data.assign;

        // Get target identifier
        const target_node = self.parser.get_node(assign_data.target)
orelse return Error.runtime_error;
        if (target_node.node_type != .expr_identifier) {
            return Error.runtime_error;
        }
        const target_name = target_node.data.identifier.name;

        // Find variable (must exist)
        const variable = self.find_variable(target_name) orelse {
            return Error.variable_not_found;
        };

        // Check if constant (cannot assign to constants)
        if (variable.is_const) {
            return Error.runtime_error; // Cannot assign to constant
        }

        // Evaluate value expression
        const value_node = self.parser.get_node(assign_data.value)
orelse return Error.runtime_error;
        const new_value = try self.evaluate_expression(value_node);

        // Type checking: check against declared type or existing value
type
        if (variable.var_type) |var_type| {
            // Check against declared/inferred type
            const type_name = var_type.type_name;
            if (!self.value_matches_type(new_value, type_name)) {
                return Error.type_mismatch;
            }
        } else if (variable.value != .null) {
            // Fallback: check type compatibility with existing value
            if (!self.types_compatible(variable.value, new_value)) {
                return Error.type_mismatch;
            }
        }

        // Free old value (if string)
        variable.value.deinit(self.allocator);

        // Assign new value (copy for strings)
        const assigned_value = switch (new_value) {
            .integer => |v| Value.from_integer(v),
            .float => |v| Value.from_float(v),
            .string => |v| blk: {
                // Copy string value
                break :blk try Value.from_string(self.allocator, v);
            },
            .boolean => |v| Value.from_boolean(v),
            .null => Value.from_null(),
        };

        variable.value = assigned_value;

        // Return the assigned value (copy for strings)
        return switch (assigned_value) {
            .integer => |v| Value.from_integer(v),
            .float => |v| Value.from_float(v),
            .string => |v| blk: {
                // Copy string value for return
                break :blk try Value.from_string(self.allocator, v);
            },
            .boolean => |v| Value.from_boolean(v),
            .null => Value.from_null(),
        };
    }

    /// Check if two value types are compatible.
    fn types_compatible(self: *const Interpreter, old: Value, new:
Value) bool {
        _ = self;
        // Same type is always compatible
        if (@as(ValueType, old) == @as(ValueType, new)) {
            return true;
        }

        // Integer and float are compatible (numeric)
        return switch (old) {
            .integer => switch (new) {
                .float => true,
                else => false,
            },
            .float => switch (new) {
                .integer => true,
                else => false,
            },
            else => false,
        };
    }

    /// Infer type name from value.
    fn infer_type_from_value(self: *const Interpreter, value: Value)
Error![]const u8 {
        _ = self;
        return switch (value) {
            .integer => "i64",
            .float => "f64",
            .string => "string",
            .boolean => "bool",
            .null => "null",
        };
    }

    /// Check if value matches type name.
    fn value_matches_type(self: *const Interpreter, value: Value,
type_name: []const u8) bool {
        _ = self;
        // Type name matching (case-sensitive)
        return switch (value) {
            .integer => std.mem.eql(u8, type_name, "i32") or
std.mem.eql(u8, type_name, "i64") or std.mem.eql(u8, type_name, "int"),
            .float => std.mem.eql(u8, type_name, "f32") or
std.mem.eql(u8, type_name, "f64") or std.mem.eql(u8, type_name, "float"),
            .string => std.mem.eql(u8, type_name, "string") or
std.mem.eql(u8, type_name, "str"),
            .boolean => std.mem.eql(u8, type_name, "bool") or
std.mem.eql(u8, type_name, "boolean"),
            .null => std.mem.eql(u8, type_name, "null") or
std.mem.eql(u8, type_name, "void"),
        };
    }

    /// Find variable by name (with scope resolution).
    fn find_variable(self: *const Interpreter, name: []const u8)
?*Variable {
        // Search from most recent to oldest (local to global)
        var i: u32 = self.variables_len;
        while (i > 0) {
            i -= 1;
            const variable = &self.variables[i];
            if (std.mem.eql(u8, variable.name, name)) {
                // Check if variable is in accessible scope
                if (variable.scope_depth <= self.scope_depth) {
                    return variable;
                }
            }
        }
        return null;
    }

    /// Find function by name.
    fn find_function(self: *const Interpreter, name: []const u8)
?*Function {
        var i: u32 = 0;
        while (i < self.functions_len) : (i += 1) {
            if (std.mem.eql(u8, self.functions[i].name, name)) {
                return &self.functions[i];
            }
        }
        return null;
    }

    /// Get exit code.
    pub fn get_exit_code(self: *const Interpreter) u32 {
        return self.exit_code;
    }
};


// === grainscript/lexer.zig ===

const std = @import("std");

/// Grainscript Lexer: Tokenizes `.gr` files into tokens.
/// ~<~ Glow Airbend: explicit token types, bounded token buffer.
/// ~~~~ Glow Waterbend: streaming tokenization without recursion.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms)
pub const Lexer = struct {
    // Bounded: Max 10,000 tokens per file (explicit limit)
    pub const MAX_TOKENS: u32 = 10_000;

    // Bounded: Max 1,024 characters per token (explicit limit)
    pub const MAX_TOKEN_LEN: u32 = 1_024;

    // Bounded: Max 256 characters per identifier (explicit limit)
    pub const MAX_IDENTIFIER_LEN: u32 = 256;

    // Bounded: Max 4,096 characters per string literal (explicit limit)
    pub const MAX_STRING_LEN: u32 = 4_096;

    /// Token type enumeration.
    pub const TokenType = enum(u8) {
        // Literals
        integer, // 123, 0x1a, 0b1010
        float, // 123.456, 1.23e-4
        string, // "hello", 'world'
        boolean, // true, false

        // Identifiers
        identifier, // variable_name, function_name

        // Keywords
        kw_if, // if
        kw_else, // else
        kw_while, // while
        kw_for, // for
        kw_fn, // fn
        kw_var, // var
        kw_const, // const
        kw_return, // return
        kw_break, // break
        kw_continue, // continue
        kw_true, // true
        kw_false, // false
        kw_null, // null

        // Operators
        op_plus, // +
        op_minus, // -
        op_multiply, // *
        op_divide, // /
        op_modulo, // %
        op_assign, // =
        op_eq, // ==
        op_ne, // !=
        op_lt, // <
        op_le, // <=
        op_gt, // >
        op_ge, // >=
        op_and, // &&
        op_or, // ||
        op_not, // !
        op_pipe, // |
        op_ampersand, // &
        op_arrow, // ->

        // Punctuation
        punc_lparen, // (
        punc_rparen, // )
        punc_lbrace, // {
        punc_rbrace, // }
        punc_lbracket, // [
        punc_rbracket, // ]
        punc_comma, // ,
        punc_semicolon, // ;
        punc_colon, // :
        punc_dot, // .
        punc_question, // ?

        // Special
        eof, // End of file
        newline, // \n
        whitespace, // Space, tab
        comment, // // comment, /* comment */
        error_token, // Invalid token
    };

    /// Token structure.
    pub const Token = struct {
        token_type: TokenType,
        start: u32, // Start position in source
        end: u32, // End position in source (exclusive)
        line: u32, // Line number (1-indexed)
        column: u32, // Column number (1-indexed)
    };

    /// Lexer state.
    source: []const u8,
    position: u32, // Current position in source
    line: u32, // Current line number (1-indexed)
    column: u32, // Current column number (1-indexed)
    tokens: []Token,
    tokens_len: u32,
    allocator: std.mem.Allocator,

    /// Initialize lexer with source code.
    pub fn init(allocator: std.mem.Allocator, source: []const u8) !Lexer
{
        // Assert: Allocator must be valid (allocator is used below)

        // Assert: Source must be valid
        std.debug.assert(source.len <= std.math.maxInt(u32));

        // Pre-allocate token buffer
        const tokens = try allocator.alloc(Token, MAX_TOKENS);
        errdefer allocator.free(tokens);

        return Lexer{
            .source = source,
            .position = 0,
            .line = 1,
            .column = 1,
            .tokens = tokens,
            .tokens_len = 0,
            .allocator = allocator,
        };
    }

    /// Deinitialize lexer and free memory.
    pub fn deinit(self: *Lexer) void {
        // Assert: Lexer must be valid
        _ = self.allocator; // Allocator is used below

        self.allocator.free(self.tokens);
        self.* = undefined;
    }

    /// Tokenize entire source code.
    pub fn tokenize(self: *Lexer) !void {
        // Assert: Lexer must be initialized
        std.debug.assert(self.source.len <= std.math.maxInt(u32));
        std.debug.assert(self.tokens.len == MAX_TOKENS);

        // Reset state
        self.position = 0;
        self.line = 1;
        self.column = 1;
        self.tokens_len = 0;

        // Iterative tokenization (no recursion)
        while (self.position < self.source.len) {
            // Assert: Token count must be within bounds
            std.debug.assert(self.tokens_len < MAX_TOKENS);

            const token = try self.next_token();
            self.tokens[self.tokens_len] = token;
            self.tokens_len += 1;

            // Stop on EOF or error
            if (token.token_type == .eof or token.token_type ==
.error_token) {
                break;
            }
        }

        // Assert: At least one token (EOF)
        std.debug.assert(self.tokens_len > 0);
    }

    /// Get next token from source.
    fn next_token(self: *Lexer) !Token {
        // Assert: Position must be valid
        std.debug.assert(self.position <= self.source.len);

        // Skip whitespace and comments
        while (self.position < self.source.len) {
            const ch = self.source[self.position];

            if (ch == ' ' or ch == '\t') {
                self.advance();
                continue;
            }

            if (ch == '\n') {
                const token = Token{
                    .token_type = .newline,
                    .start = self.position,
                    .end = self.position + 1,
                    .line = self.line,
                    .column = self.column,
                };
                self.advance();
                self.line += 1;
                self.column = 1;
                return token;
            }

            // Single-line comment: //
            if (ch == '/' and self.position + 1 < self.source.len and
self.source[self.position + 1] == '/') {
                const start = self.position;
                self.advance(); // Skip '/'
                self.advance(); // Skip '/'

                // Skip to end of line
                while (self.position < self.source.len and
self.source[self.position] != '\n') {
                    self.advance();
                }

                const token = Token{
                    .token_type = .comment,
                    .start = start,
                    .end = self.position,
                    .line = self.line,
                    .column = self.column,
                };
                return token;
            }

            // Multi-line comment: /* */
            if (ch == '/' and self.position + 1 < self.source.len and
self.source[self.position + 1] == '*') {
                const start = self.position;
                self.advance(); // Skip '/'
                self.advance(); // Skip '*'

                // Skip to end of comment
                while (self.position + 1 < self.source.len) {
                    if (self.source[self.position] == '*' and
self.source[self.position + 1] == '/') {
                        self.advance(); // Skip '*'
                        self.advance(); // Skip '/'
                        break;
                    }
                    if (self.source[self.position] == '\n') {
                        self.line += 1;
                        self.column = 1;
                    } else {
                        self.column += 1;
                    }
                    self.advance();
                }

                const token = Token{
                    .token_type = .comment,
                    .start = start,
                    .end = self.position,
                    .line = self.line,
                    .column = self.column,
                };
                return token;
            }

            break;
        }

        // Check for EOF
        if (self.position >= self.source.len) {
            return Token{
                .token_type = .eof,
                .start = self.position,
                .end = self.position,
                .line = self.line,
                .column = self.column,
            };
        }

        const start = self.position;
        const start_line = self.line;
        const start_column = self.column;
        const ch = self.source[self.position];

        // Identifiers and keywords
        if (is_identifier_start(ch)) {
            return self.tokenize_identifier(start, start_line,
start_column);
        }

        // Numbers
        if (is_digit(ch)) {
            return self.tokenize_number(start, start_line, start_column);
        }

        // Strings
        if (ch == '"' or ch == '\'') {
            return self.tokenize_string(start, start_line, start_column,
ch);
        }

        // Operators and punctuation
        return self.tokenize_operator_or_punctuation(start, start_line,
start_column);
    }

    /// Tokenize identifier or keyword.
    fn tokenize_identifier(self: *Lexer, start: u32, start_line: u32,
start_column: u32) !Token {
        // Assert: Start position must be valid
        std.debug.assert(start < self.source.len);
        std.debug.assert(is_identifier_start(self.source[start]));

        var len: u32 = 0;
        var pos = start;

        // Iterative identifier parsing (no recursion)
        while (pos < self.source.len and len < MAX_IDENTIFIER_LEN) {
            const ch = self.source[pos];
            if (!is_identifier_char(ch)) {
                break;
            }
            pos += 1;
            len += 1;
        }

        // Assert: Identifier length must be within bounds
        std.debug.assert(len <= MAX_IDENTIFIER_LEN);

        const identifier = self.source[start..pos];
        const token_type = keyword_to_token_type(identifier);

        // Update position
        self.position = pos;
        self.column += len;

        return Token{
            .token_type = token_type,
            .start = start,
            .end = pos,
            .line = start_line,
            .column = start_column,
        };
    }

    /// Tokenize number (integer or float).
    fn tokenize_number(self: *Lexer, start: u32, start_line: u32,
start_column: u32) !Token {
        // Assert: Start position must be valid
        std.debug.assert(start < self.source.len);
        std.debug.assert(is_digit(self.source[start]));

        var pos = start;
        var has_dot = false;
        var has_exponent = false;

        // Integer part
        while (pos < self.source.len and is_digit(self.source[pos])) {
            pos += 1;
        }

        // Decimal point
        if (pos < self.source.len and self.source[pos] == '.') {
            has_dot = true;
            pos += 1;

            // Fractional part
            while (pos < self.source.len and is_digit(self.source[pos]))
{
                pos += 1;
            }
        }

        // Exponent
        if (pos < self.source.len and (self.source[pos] == 'e' or
self.source[pos] == 'E')) {
            has_exponent = true;
            pos += 1;

            // Optional sign
            if (pos < self.source.len and (self.source[pos] == '+' or
self.source[pos] == '-')) {
                pos += 1;
            }

            // Exponent digits
            while (pos < self.source.len and is_digit(self.source[pos]))
{
                pos += 1;
            }
        }

        // Hex prefix: 0x
        if (start + 2 <= self.source.len and self.source[start] == '0'
and self.source[start + 1] == 'x') {
            pos = start + 2;
            while (pos < self.source.len and
is_hex_digit(self.source[pos])) {
                pos += 1;
            }
        }

        // Binary prefix: 0b
        if (start + 2 <= self.source.len and self.source[start] == '0'
and self.source[start + 1] == 'b') {
            pos = start + 2;
            while (pos < self.source.len and (self.source[pos] == '0' or
self.source[pos] == '1')) {
                pos += 1;
            }
        }

        const token_type: TokenType = if (has_dot or has_exponent)
.float else .integer;

        // Update position
        const len = pos - start;
        self.position = pos;
        self.column += len;

        return Token{
            .token_type = token_type,
            .start = start,
            .end = pos,
            .line = start_line,
            .column = start_column,
        };
    }

    /// Tokenize string literal.
    fn tokenize_string(self: *Lexer, start: u32, start_line: u32,
start_column: u32, quote: u8) !Token {
        // Assert: Start position must be valid
        std.debug.assert(start < self.source.len);
        std.debug.assert(self.source[start] == quote);

        var pos = start + 1; // Skip opening quote

        // Iterative string parsing (no recursion)
        while (pos < self.source.len) {
            const ch = self.source[pos];

            // End of string
            if (ch == quote) {
                pos += 1; // Include closing quote
                break;
            }

            // Escape sequence
            if (ch == '\\' and pos + 1 < self.source.len) {
                pos += 2; // Skip escape sequence
                continue;
            }

            // Newline in string (error, but continue)
            if (ch == '\n') {
                self.line += 1;
                self.column = 1;
            } else {
                self.column += 1;
            }

            pos += 1;

            // Assert: String length must be within bounds
            if (pos - start > MAX_STRING_LEN) {
                return Token{
                    .token_type = .error_token,
                    .start = start,
                    .end = pos,
                    .line = start_line,
                    .column = start_column,
                };
            }
        }

        // Update position
        const len = pos - start;
        self.position = pos;
        self.column += len;

        return Token{
            .token_type = .string,
            .start = start,
            .end = pos,
            .line = start_line,
            .column = start_column,
        };
    }

    /// Tokenize operator or punctuation.
    fn tokenize_operator_or_punctuation(self: *Lexer, start: u32,
start_line: u32, start_column: u32) !Token {
        // Assert: Start position must be valid
        std.debug.assert(start < self.source.len);

        const ch = self.source[start];
        var token_type: TokenType = .error_token;
        var len: u32 = 1;

        // Single-character operators
        switch (ch) {
            '+' => token_type = .op_plus,
            '-' => {
                // Check for arrow: ->
                if (start + 1 < self.source.len and self.source[start +
1] == '>') {
                    token_type = .op_arrow;
                    len = 2;
                } else {
                    token_type = .op_minus;
                }
            },
            '*' => token_type = .op_multiply,
            '/' => token_type = .op_divide,
            '%' => token_type = .op_modulo,
            '=' => {
                // Check for equality: ==
                if (start + 1 < self.source.len and self.source[start +
1] == '=') {
                    token_type = .op_eq;
                    len = 2;
                } else {
                    token_type = .op_assign;
                }
            },
            '!' => {
                // Check for inequality: !=
                if (start + 1 < self.source.len and self.source[start +
1] == '=') {
                    token_type = .op_ne;
                    len = 2;
                } else {
                    token_type = .op_not;
                }
            },
            '<' => {
                // Check for less than or equal: <=
                if (start + 1 < self.source.len and self.source[start +
1] == '=') {
                    token_type = .op_le;
                    len = 2;
                } else {
                    token_type = .op_lt;
                }
            },
            '>' => {
                // Check for greater than or equal: >=
                if (start + 1 < self.source.len and self.source[start +
1] == '=') {
                    token_type = .op_ge;
                    len = 2;
                } else {
                    token_type = .op_gt;
                }
            },
            '&' => {
                // Check for logical and: &&
                if (start + 1 < self.source.len and self.source[start +
1] == '&') {
                    token_type = .op_and;
                    len = 2;
                } else {
                    token_type = .op_ampersand;
                }
            },
            '|' => {
                // Check for logical or: ||
                if (start + 1 < self.source.len and self.source[start +
1] == '|') {
                    token_type = .op_or;
                    len = 2;
                } else {
                    token_type = .op_pipe;
                }
            },
            '(' => token_type = .punc_lparen,
            ')' => token_type = .punc_rparen,
            '{' => token_type = .punc_lbrace,
            '}' => token_type = .punc_rbrace,
            '[' => token_type = .punc_lbracket,
            ']' => token_type = .punc_rbracket,
            ',' => token_type = .punc_comma,
            ';' => token_type = .punc_semicolon,
            ':' => token_type = .punc_colon,
            '.' => token_type = .punc_dot,
            '?' => token_type = .punc_question,
            else => token_type = .error_token,
        }

        // Update position
        self.position = start + len;
        self.column += len;

        return Token{
            .token_type = token_type,
            .start = start,
            .end = start + len,
            .line = start_line,
            .column = start_column,
        };
    }

    /// Advance position by one character.
    fn advance(self: *Lexer) void {
        // Assert: Position must be valid
        std.debug.assert(self.position < self.source.len);

        self.position += 1;
        self.column += 1;
    }

    /// Check if character is valid identifier start.
    fn is_identifier_start(ch: u8) bool {
        return (ch >= 'a' and ch <= 'z') or (ch >= 'A' and ch <= 'Z') or
ch == '_';
    }

    /// Check if character is valid identifier character.
    fn is_identifier_char(ch: u8) bool {
        return is_identifier_start(ch) or is_digit(ch);
    }

    /// Check if character is a digit.
    fn is_digit(ch: u8) bool {
        return ch >= '0' and ch <= '9';
    }

    /// Check if character is a hex digit.
    fn is_hex_digit(ch: u8) bool {
        return is_digit(ch) or (ch >= 'a' and ch <= 'f') or (ch >= 'A'
and ch <= 'F');
    }

    /// Convert keyword string to token type.
    fn keyword_to_token_type(keyword: []const u8) TokenType {
        // Assert: Keyword must be non-empty
        std.debug.assert(keyword.len > 0);

        if (std.mem.eql(u8, keyword, "if")) return .kw_if;
        if (std.mem.eql(u8, keyword, "else")) return .kw_else;
        if (std.mem.eql(u8, keyword, "while")) return .kw_while;
        if (std.mem.eql(u8, keyword, "for")) return .kw_for;
        if (std.mem.eql(u8, keyword, "fn")) return .kw_fn;
        if (std.mem.eql(u8, keyword, "var")) return .kw_var;
        if (std.mem.eql(u8, keyword, "const")) return .kw_const;
        if (std.mem.eql(u8, keyword, "return")) return .kw_return;
        if (std.mem.eql(u8, keyword, "break")) return .kw_break;
        if (std.mem.eql(u8, keyword, "continue")) return .kw_continue;
        if (std.mem.eql(u8, keyword, "true")) return .kw_true;
        if (std.mem.eql(u8, keyword, "false")) return .kw_false;
        if (std.mem.eql(u8, keyword, "null")) return .kw_null;

        return .identifier;
    }

    /// Get token at index.
    pub fn get_token(self: *const Lexer, index: u32) ?Token {
        // Assert: Index must be valid
        std.debug.assert(index < MAX_TOKENS);

        if (index >= self.tokens_len) {
            return null;
        }

        return self.tokens[index];
    }

    /// Get number of tokens.
    pub fn get_token_count(self: *const Lexer) u32 {
        return self.tokens_len;
    }

    /// Get source code.
    pub fn get_source(self: *const Lexer) []const u8 {
        return self.source;
    }

    /// Get all tokens (slice of tokens).
    pub fn get_tokens(self: *const Lexer) []const Token {
        return self.tokens[0..self.tokens_len];
    }
};

// === grainscript/parser.zig ===

const std = @import("std");
const Lexer = @import("lexer.zig").Lexer;

/// Grainscript Parser: Builds AST from tokens.
/// ~<~ Glow Airbend: explicit AST nodes, bounded tree depth.
/// ~~~~ Glow Waterbend: deterministic parsing, iterative algorithms.
///
/// GrainStyle/TigerStyle compliance:
/// - grain_case function names
/// - u32/u64 types (not usize)
/// - MAX_ constants for bounded allocations
/// - Assertions for preconditions/postconditions
/// - No recursion (iterative algorithms, stack-based)
pub const Parser = struct {
    // Bounded: Max 1,000 AST nodes per file (explicit limit)
    pub const MAX_AST_NODES: u32 = 1_000;

    // Bounded: Max 100 AST depth (explicit limit)
    pub const MAX_AST_DEPTH: u32 = 100;

    // Bounded: Max 256 expression operands (explicit limit)
    pub const MAX_EXPR_OPERANDS: u32 = 256;

    // Bounded: Max 64 function parameters (explicit limit)
    pub const MAX_FN_PARAMS: u32 = 64;

    // Bounded: Max 1,024 statement list items (explicit limit)
    pub const MAX_STMT_LIST: u32 = 1_024;

    /// AST node type enumeration.
    pub const NodeType = enum(u8) {
        // Expressions
        expr_literal, // Integer, float, string, boolean, null
        expr_identifier, // Variable or function name
        expr_binary, // Binary operation (+, -, *, /, ==, !=, etc.)
        expr_unary, // Unary operation (!, -)
        expr_call, // Function call
        expr_group, // Parenthesized expression
        expr_assign, // Assignment (=)

        // Statements
        stmt_expr, // Expression statement
        stmt_var, // Variable declaration
        stmt_const, // Constant declaration
        stmt_if, // If statement
        stmt_while, // While loop
        stmt_for, // For loop
        stmt_return, // Return statement
        stmt_break, // Break statement
        stmt_continue, // Continue statement
        stmt_block, // Block of statements

        // Declarations
        decl_fn, // Function declaration
        decl_var, // Variable declaration (top-level)
        decl_const, // Constant declaration (top-level)

        // Types
        type_named, // Named type (i32, u64, string, etc.)
        type_inferred, // Inferred type (placeholder)
    };

    /// AST node structure.
    pub const Node = struct {
        node_type: NodeType,
        start: u32, // Start position in source
        end: u32, // End position in source (exclusive)
        line: u32, // Line number (1-indexed)
        column: u32, // Column number (1-indexed)
        depth: u32, // Tree depth (for bounds checking)

        // Node data (union-like, but explicit for GrainStyle)
        data: NodeData,
    };

    /// Node data (explicit union for GrainStyle compliance).
    pub const NodeData = union(enum) {
        // Literal expression
        literal: LiteralData,
        // Identifier expression
        identifier: IdentifierData,
        // Binary expression
        binary: BinaryData,
        // Unary expression
        unary: UnaryData,
        // Function call expression
        call: CallData,
        // Grouped expression
        group: GroupData,
        // Assignment expression
        assign: AssignData,
        // Variable statement
        var_stmt: VarStmtData,
        // If statement
        if_stmt: IfStmtData,
        // While statement
        while_stmt: WhileStmtData,
        // For statement
        for_stmt: ForStmtData,
        // Return statement
        return_stmt: ReturnStmtData,
        // Block statement
        block: BlockData,
        // Function declaration
        fn_decl: FnDeclData,
        // Type
        type_named: TypeData,
        // Empty (for nodes that don't need data)
        empty: void,
    };

    /// Literal data (integer, float, string, boolean, null).
    pub const LiteralData = struct {
        literal_type: LiteralType,
        value: []const u8, // Source text of literal
        value_len: u32,
    };

    /// Literal type enumeration.
    pub const LiteralType = enum(u8) {
        integer,
        float,
        string,
        boolean_true,
        boolean_false,
        null,
    };

    /// Identifier data.
    pub const IdentifierData = struct {
        name: []const u8, // Identifier name
        name_len: u32,
    };

    /// Binary expression data.
    pub const BinaryData = struct {
        operator: BinaryOperator,
        left: u32, // Left operand node index
        right: u32, // Right operand node index
    };

    /// Binary operator enumeration.
    pub const BinaryOperator = enum(u8) {
        // Arithmetic
        add, // +
        subtract, // -
        multiply, // *
        divide, // /
        modulo, // %
        // Comparison
        eq, // ==
        ne, // !=
        lt, // <
        le, // <=
        gt, // >
        ge, // >=
        // Logical
        and_op, // &&
        or_op, // ||
    };

    /// Unary expression data.
    pub const UnaryData = struct {
        operator: UnaryOperator,
        operand: u32, // Operand node index
    };

    /// Unary operator enumeration.
    pub const UnaryOperator = enum(u8) {
        not, // !
        negate, // -
    };

    /// Function call data.
    pub const CallData = struct {
        callee: u32, // Function name node index
        args: []const u32, // Argument node indices
        args_len: u32,
    };

    /// Grouped expression data.
    pub const GroupData = struct {
        expr: u32, // Expression node index
    };

    /// Assignment expression data.
    pub const AssignData = struct {
        target: u32, // Target identifier node index
        value: u32, // Value expression node index
    };

    /// Variable statement data.
    pub const VarStmtData = struct {
        name: []const u8, // Variable name
        name_len: u32,
        type_node: ?u32, // Type node index (optional)
        init: ?u32, // Initializer expression node index (optional)
    };

    /// If statement data.
    pub const IfStmtData = struct {
        condition: u32, // Condition expression node index
        then_block: u32, // Then block node index
        else_block: ?u32, // Else block node index (optional)
    };

    /// While statement data.
    pub const WhileStmtData = struct {
        condition: u32, // Condition expression node index
        body: u32, // Body block node index
    };

    /// For statement data.
    pub const ForStmtData = struct {
        init: ?u32, // Initializer statement node index (optional)
        condition: ?u32, // Condition expression node index (optional)
        update: ?u32, // Update expression node index (optional)
        body: u32, // Body block node index
    };

    /// Return statement data.
    pub const ReturnStmtData = struct {
        value: ?u32, // Return value expression node index (optional)
    };

    /// Block statement data.
    pub const BlockData = struct {
        statements: []const u32, // Statement node indices
        statements_len: u32,
    };

    /// Function declaration data.
    pub const FnDeclData = struct {
        name: []const u8, // Function name
        name_len: u32,
        params: []const u32, // Parameter node indices
        params_len: u32,
        return_type: ?u32, // Return type node index (optional)
        body: u32, // Body block node index
    };

    /// Type data.
    pub const TypeData = struct {
        name: []const u8, // Type name (i32, u64, string, etc.)
        name_len: u32,
    };

    /// Parser state.
    lexer: *const Lexer,
    source: []const u8, // Source code (from lexer)
    tokens: []const Lexer.Token,
    token_index: u32, // Current token index
    nodes: []Node, // AST nodes
    nodes_len: u32, // Number of nodes
    allocator: std.mem.Allocator,
    depth: u32, // Current parsing depth

    /// Initialize parser with lexer.
    pub fn init(allocator: std.mem.Allocator, lexer: *const Lexer)
!Parser {
        // Assert: Allocator must be valid (allocator is used below)

        // Assert: Lexer must be valid
        std.debug.assert(lexer.get_token_count() > 0);

        // Pre-allocate node buffer
        const nodes = try allocator.alloc(Node, MAX_AST_NODES);
        errdefer allocator.free(nodes);

        // Get tokens from lexer
        const tokens = lexer.get_tokens();
        const source = lexer.get_source();

        return Parser{
            .lexer = lexer,
            .source = source,
            .tokens = tokens,
            .token_index = 0,
            .nodes = nodes,
            .nodes_len = 0,
            .allocator = allocator,
            .depth = 0,
        };
    }

    /// Deinitialize parser and free memory.
    pub fn deinit(self: *Parser) void {
        // Assert: Parser must be valid
        _ = self.allocator; // Allocator is used below

        // Free node buffer
        self.allocator.free(self.nodes);
        self.* = undefined;
    }

    /// Parse entire source code into AST.
    pub fn parse(self: *Parser) !void {
        // Assert: Parser must be initialized
        std.debug.assert(self.tokens.len > 0);
        std.debug.assert(self.nodes.len == MAX_AST_NODES);

        // Reset state
        self.token_index = 0;
        self.nodes_len = 0;
        self.depth = 0;

        // Parse statements until EOF
        while (self.token_index < self.tokens.len) {
            const token = self.get_current_token();
            if (token.token_type == .eof) {
                break;
            }

            // Skip comments and whitespace
            if (token.token_type == .comment or token.token_type ==
.whitespace or token.token_type == .newline) {
                self.advance();
                continue;
            }

            // Parse declaration or statement
            _ = try self.parse_declaration_or_statement();
        }

        // Assert: Must have at least one node (or empty file)
        // Assert: Depth must be zero (all blocks closed)
        std.debug.assert(self.depth == 0);
    }

    /// Parse declaration or statement.
    fn parse_declaration_or_statement(self: *Parser) ParserError!?u32 {
        // Assert: Token index must be valid
        std.debug.assert(self.token_index < self.tokens.len);

        const token = self.get_current_token();

        // Function declaration
        if (token.token_type == .kw_fn) {
            return try self.parse_function_declaration();
        }

        // Variable declaration
        if (token.token_type == .kw_var) {
            return try self.parse_variable_declaration();
        }

        // Constant declaration
        if (token.token_type == .kw_const) {
            return try self.parse_constant_declaration();
        }

        // Statement
        return try self.parse_statement();
    }

    /// Parse function declaration.
    fn parse_function_declaration(self: *Parser) ParserError!u32 {
        // Assert: Current token must be 'fn'
        std.debug.assert(self.get_current_token().token_type == .kw_fn);

        const start_token = self.get_current_token();
        self.advance(); // Skip 'fn'

        // Parse function name
        const name_token = self.get_current_token();
        if (name_token.token_type != .identifier) {
            return error.ExpectedIdentifier;
        }
        const name = self.source[name_token.start..name_token.end];
        self.advance(); // Skip identifier

        // Parse parameters
        if (self.get_current_token().token_type != .punc_lparen) {
            return error.ExpectedLeftParen;
        }
        self.advance(); // Skip '('

        var params = std.ArrayListUnmanaged(u32){};
        defer params.deinit(self.allocator);
        try params.ensureTotalCapacity(self.allocator, MAX_FN_PARAMS);

        // Parse parameter list
        while (self.get_current_token().token_type != .punc_rparen) {
            if (self.get_current_token().token_type == .eof) {
                return error.UnexpectedEof;
            }

            // Skip comma if not first parameter
            if (params.items.len > 0) {
                if (self.get_current_token().token_type != .punc_comma) {
                    return error.ExpectedComma;
                }
                self.advance(); // Skip ','
            }

            // Parse parameter name
            const param_name_token = self.get_current_token();
            if (param_name_token.token_type != .identifier) {
                return error.ExpectedIdentifier;
            }
            self.advance(); // Skip identifier

            // Parse parameter type (optional for now, required later)
            var param_type: ?u32 = null;
            if (self.get_current_token().token_type == .punc_colon) {
                self.advance(); // Skip ':'
                param_type = try self.parse_type();
            }

            // Create parameter node (for now, just identifier)
            const param_node = try self.create_node(
                .expr_identifier,
                param_name_token.start,
                param_name_token.end,
                param_name_token.line,
                param_name_token.column,
                .{ .identifier = .{ .name =
self.source[param_name_token.start..param_name_token.end], .name_len =
param_name_token.end - param_name_token.start } },
            );
            try params.append(self.allocator, param_node);
        }

        self.advance(); // Skip ')'

        // Parse return type (optional)
        var return_type: ?u32 = null;
        if (self.get_current_token().token_type == .op_arrow) {
            self.advance(); // Skip '->'
            return_type = try self.parse_type();
        }

        // Parse function body
        const body = try self.parse_block();

        // Create function declaration node
        const params_slice = try self.allocator.dupe(u32, params.items);
        errdefer self.allocator.free(params_slice);

        return try self.create_node(
            .decl_fn,
            start_token.start,
            self.get_current_token().end,
            start_token.line,
            start_token.column,
            .{ .fn_decl = .{
                .name = name,
                .name_len = @as(u32, @intCast(name.len)),
                .params = params_slice,
                .params_len = @as(u32, @intCast(params_slice.len)),
                .return_type = return_type,
                .body = body,
            } },
        );
    }

    /// Parse variable declaration.
    fn parse_variable_declaration(self: *Parser) ParserError!u32 {
        // Assert: Current token must be 'var'
        std.debug.assert(self.get_current_token().token_type == .kw_var);

        const start_token = self.get_current_token();
        self.advance(); // Skip 'var'

        // Parse variable name
        const name_token = self.get_current_token();
        if (name_token.token_type != .identifier) {
            return error.ExpectedIdentifier;
        }
        const name = self.source[name_token.start..name_token.end];
        self.advance(); // Skip identifier

        // Parse type (optional)
        var type_node: ?u32 = null;
        if (self.get_current_token().token_type == .punc_colon) {
            self.advance(); // Skip ':'
            type_node = try self.parse_type();
        }

        // Parse initializer (optional)
        var init_expr: ?u32 = null;
        if (self.get_current_token().token_type == .op_assign) {
            self.advance(); // Skip '='
            init_expr = try self.parse_expression();
        }

        // Create variable declaration node
        return try self.create_node(
            .stmt_var,
            start_token.start,
            self.get_current_token().end,
            start_token.line,
            start_token.column,
            .{ .var_stmt = .{
                .name = name,
                .name_len = @as(u32, @intCast(name.len)),
                .type_node = type_node,
                .init = init_expr,
            } },
        );
    }

    /// Parse constant declaration.
    fn parse_constant_declaration(self: *Parser) ParserError!u32 {
        // Assert: Current token must be 'const'
        std.debug.assert(self.get_current_token().token_type ==
.kw_const);

        const start_token = self.get_current_token();
        self.advance(); // Skip 'const'

        // Parse constant name
        const name_token = self.get_current_token();
        if (name_token.token_type != .identifier) {
            return error.ExpectedIdentifier;
        }
        const name = self.source[name_token.start..name_token.end];
        self.advance(); // Skip identifier

        // Parse type (optional)
        var type_node: ?u32 = null;
        if (self.get_current_token().token_type == .punc_colon) {
            self.advance(); // Skip ':'
            type_node = try self.parse_type();
        }

        // Parse initializer (required for const)
        if (self.get_current_token().token_type != .op_assign) {
            return error.ExpectedAssign;
        }
        self.advance(); // Skip '='
        const init_expr = try self.parse_expression();

        // Create constant declaration node
        return try self.create_node(
            .stmt_const,
            start_token.start,
            self.get_current_token().end,
            start_token.line,
            start_token.column,
            .{ .var_stmt = .{
                .name = name,
                .name_len = @as(u32, @intCast(name.len)),
                .type_node = type_node,
                .init = init_expr,
            } },
        );
    }

    /// Parse statement.
    fn parse_statement(self: *Parser) ParserError!?u32 {
        // Assert: Token index must be valid
        std.debug.assert(self.token_index < self.tokens.len);

        const token = self.get_current_token();

        // If statement
        if (token.token_type == .kw_if) {
            return try self.parse_if_statement();
        }

        // While statement
        if (token.token_type == .kw_while) {
            return try self.parse_while_statement();
        }

        // For statement
        if (token.token_type == .kw_for) {
            return try self.parse_for_statement();
        }

        // Return statement
        if (token.token_type == .kw_return) {
            return try self.parse_return_statement();
        }

        // Break statement
        if (token.token_type == .kw_break) {
            return try self.parse_break_statement();
        }

        // Continue statement
        if (token.token_type == .kw_continue) {
            return try self.parse_continue_statement();
        }

        // Block statement
        if (token.token_type == .punc_lbrace) {
            return try self.parse_block();
        }

        // Expression statement
        const expr = try self.parse_expression();
        const expr_node = self.get_node(expr) orelse return
error.InvalidNode;
        
        if (self.get_current_token().token_type == .punc_semicolon) {
            self.advance(); // Skip ';'
        }
        
        return try self.create_node(
            .stmt_expr,
            expr_node.start,
            expr_node.end,
            token.line,
            token.column,
            .{ .group = .{ .expr = expr } },
        );
    }

    /// Parse if statement.
    fn parse_if_statement(self: *Parser) ParserError!u32 {
        // Assert: Current token must be 'if'
        std.debug.assert(self.get_current_token().token_type == .kw_if);

        const start_token = self.get_current_token();
        self.advance(); // Skip 'if'

        // Parse condition
        if (self.get_current_token().token_type != .punc_lparen) {
            return error.ExpectedLeftParen;
        }
        self.advance(); // Skip '('
        const condition = try self.parse_expression();
        if (self.get_current_token().token_type != .punc_rparen) {
            return error.ExpectedRightParen;
        }
        self.advance(); // Skip ')'

        // Parse then block
        const then_block = try self.parse_block();

        // Parse else block (optional)
        var else_block: ?u32 = null;
        if (self.get_current_token().token_type == .kw_else) {
            self.advance(); // Skip 'else'
            else_block = try self.parse_block();
        }

        // Create if statement node
        return try self.create_node(
            .stmt_if,
            start_token.start,
            self.get_current_token().end,
            start_token.line,
            start_token.column,
            .{ .if_stmt = .{
                .condition = condition,
                .then_block = then_block,
                .else_block = else_block,
            } },
        );
    }

    /// Parse while statement.
    fn parse_while_statement(self: *Parser) ParserError!u32 {
        // Assert: Current token must be 'while'
        std.debug.assert(self.get_current_token().token_type ==
.kw_while);

        const start_token = self.get_current_token();
        self.advance(); // Skip 'while'

        // Parse condition
        if (self.get_current_token().token_type != .punc_lparen) {
            return error.ExpectedLeftParen;
        }
        self.advance(); // Skip '('
        const condition = try self.parse_expression();
        if (self.get_current_token().token_type != .punc_rparen) {
            return error.ExpectedRightParen;
        }
        self.advance(); // Skip ')'

        // Parse body
        const body = try self.parse_block();

        // Create while statement node
        return try self.create_node(
            .stmt_while,
            start_token.start,
            self.get_current_token().end,
            start_token.line,
            start_token.column,
            .{ .while_stmt = .{
                .condition = condition,
                .body = body,
            } },
        );
    }

    /// Parse for statement.
    fn parse_for_statement(self: *Parser) ParserError!u32 {
        // Assert: Current token must be 'for'
        std.debug.assert(self.get_current_token().token_type == .kw_for);

        const start_token = self.get_current_token();
        self.advance(); // Skip 'for'

        // Parse for loop header
        if (self.get_current_token().token_type != .punc_lparen) {
            return error.ExpectedLeftParen;
        }
        self.advance(); // Skip '('

        // Parse initializer (optional)
        var init_stmt: ?u32 = null;
        if (self.get_current_token().token_type != .punc_semicolon) {
            init_stmt = try self.parse_statement();
        }

        // Parse condition (optional)
        var condition: ?u32 = null;
        if (self.get_current_token().token_type != .punc_semicolon) {
            condition = try self.parse_expression();
        }
        if (self.get_current_token().token_type != .punc_semicolon) {
            return error.ExpectedSemicolon;
        }
        self.advance(); // Skip ';'

        // Parse update (optional)
        var update: ?u32 = null;
        if (self.get_current_token().token_type != .punc_rparen) {
            update = try self.parse_expression();
        }
        if (self.get_current_token().token_type != .punc_rparen) {
            return error.ExpectedRightParen;
        }
        self.advance(); // Skip ')'

        // Parse body
        const body = try self.parse_block();

        // Create for statement node
        return try self.create_node(
            .stmt_for,
            start_token.start,
            self.get_current_token().end,
            start_token.line,
            start_token.column,
            .{ .for_stmt = .{
                .init = init_stmt,
                .condition = condition,
                .update = update,
                .body = body,
            } },
        );
    }

    /// Parse return statement.
    fn parse_return_statement(self: *Parser) ParserError!u32 {
        // Assert: Current token must be 'return'
        std.debug.assert(self.get_current_token().token_type ==
.kw_return);

        const start_token = self.get_current_token();
        self.advance(); // Skip 'return'

        // Parse return value (optional)
        var value: ?u32 = null;
        if (self.get_current_token().token_type != .punc_semicolon and
            self.get_current_token().token_type != .newline and
            self.get_current_token().token_type != .eof)
        {
            value = try self.parse_expression();
        }

        if (self.get_current_token().token_type == .punc_semicolon) {
            self.advance(); // Skip ';'
        }

        // Create return statement node
        return try self.create_node(
            .stmt_return,
            start_token.start,
            self.get_current_token().end,
            start_token.line,
            start_token.column,
            .{ .return_stmt = .{ .value = value } },
        );
    }

    /// Parse break statement.
    fn parse_break_statement(self: *Parser) ParserError!u32 {
        // Assert: Current token must be 'break'
        std.debug.assert(self.get_current_token().token_type ==
.kw_break);

        const start_token = self.get_current_token();
        self.advance(); // Skip 'break'

        if (self.get_current_token().token_type == .punc_semicolon) {
            self.advance(); // Skip ';'
        }

        // Create break statement node
        return try self.create_node(
            .stmt_break,
            start_token.start,
            start_token.end,
            start_token.line,
            start_token.column,
            .{ .empty = {} },
        );
    }

    /// Parse continue statement.
    fn parse_continue_statement(self: *Parser) ParserError!u32 {
        // Assert: Current token must be 'continue'
        std.debug.assert(self.get_current_token().token_type ==
.kw_continue);

        const start_token = self.get_current_token();
        self.advance(); // Skip 'continue'

        if (self.get_current_token().token_type == .punc_semicolon) {
            self.advance(); // Skip ';'
        }

        // Create continue statement node
        return try self.create_node(
            .stmt_continue,
            start_token.start,
            start_token.end,
            start_token.line,
            start_token.column,
            .{ .empty = {} },
        );
    }

    /// Parse block statement.
    fn parse_block(self: *Parser) ParserError!u32 {
        // Assert: Current token must be '{'
        std.debug.assert(self.get_current_token().token_type ==
.punc_lbrace);

        const start_token = self.get_current_token();
        self.advance(); // Skip '{'

        // Assert: Depth must be within bounds
        std.debug.assert(self.depth < MAX_AST_DEPTH);
        self.depth += 1;
        defer self.depth -= 1;

        var statements = std.ArrayListUnmanaged(u32){};
        defer statements.deinit(self.allocator);
        try statements.ensureTotalCapacity(self.allocator,
MAX_STMT_LIST);

        // Parse statements until '}'
        while (self.get_current_token().token_type != .punc_rbrace) {
            if (self.get_current_token().token_type == .eof) {
                return error.UnexpectedEof;
            }

            // Skip comments and whitespace
            if (self.get_current_token().token_type == .comment or
                self.get_current_token().token_type == .whitespace or
                self.get_current_token().token_type == .newline)
            {
                self.advance();
                continue;
            }

            // Parse statement
            if (try self.parse_statement()) |stmt| {
                try statements.append(self.allocator, stmt);
            }
        }

        self.advance(); // Skip '}'

        // Create block node
        const statements_slice = try self.allocator.dupe(u32,
statements.items);
        errdefer self.allocator.free(statements_slice);

        return try self.create_node(
            .stmt_block,
            start_token.start,
            self.get_current_token().end,
            start_token.line,
            start_token.column,
            .{ .block = .{
                .statements = statements_slice,
                .statements_len = @as(u32,
@intCast(statements_slice.len)),
            } },
        );
    }

    /// Parse expression (iterative, precedence-based).
    fn parse_expression(self: *Parser) ParserError!u32 {
        // Assert: Token index must be valid
        std.debug.assert(self.token_index < self.tokens.len);

        // Check for assignment (lowest precedence)
        const token = self.get_current_token();
        if (token.token_type == .identifier) {
            // Look ahead to see if next token is assignment
            if (self.token_index + 1 < self.tokens.len) {
                const next_token = self.tokens[self.token_index + 1];
                if (next_token.token_type == .op_assign) {
                    // Parse assignment: identifier = expression
                    const target_token = token;
                    self.advance(); // Skip identifier
                    self.advance(); // Skip '='

                    // Parse target identifier
                    const target_name =
self.source[target_token.start..target_token.end];
                    const target = try self.create_node(
                        .expr_identifier,
                        target_token.start,
                        target_token.end,
                        target_token.line,
                        target_token.column,
                        .{ .identifier = .{
                            .name = target_name,
                            .name_len = @as(u32,
@intCast(target_name.len)),
                        } },
                    );

                    // Parse value expression
                    const value = try
self.parse_expression_precedence(0);

                    // Create assignment node
                    const target_node = self.get_node(target) orelse
return error.InvalidNode;
                    const value_node = self.get_node(value) orelse
return error.InvalidNode;

                    return try self.create_node(
                        .expr_assign,
                        target_node.start,
                        value_node.end,
                        target_token.line,
                        target_token.column,
                        .{ .assign = .{
                            .target = target,
                            .value = value,
                        } },
                    );
                }
            }
        }

        // Parse with precedence (iterative, no recursion)
        return try self.parse_expression_precedence(0);
    }

    /// Parse expression with precedence (iterative, stack-based).
    fn parse_expression_precedence(self: *Parser, min_precedence: u32)
ParserError!u32 {
        // Assert: Token index must be valid
        std.debug.assert(self.token_index < self.tokens.len);

        // Parse left operand
        var left = try self.parse_unary_expression();

        // Parse binary operators with precedence
        while (true) {
            const token = self.get_current_token();
            const precedence = get_binary_precedence(token.token_type);
            if (precedence == 0 or precedence < min_precedence) {
                break;
            }

            const operator_token = token;
            self.advance(); // Skip operator

            // Parse right operand
            const right = try
self.parse_expression_precedence(precedence + 1);

            // Create binary expression node
            const operator =
token_type_to_binary_operator(operator_token.token_type) orelse {
                return error.InvalidOperator;
            };

            // Get positions from nodes
            const left_node = self.get_node(left) orelse return
error.InvalidNode;
            const right_node = self.get_node(right) orelse return
error.InvalidNode;

            left = try self.create_node(
                .expr_binary,
                left_node.start,
                right_node.end,
                operator_token.line,
                operator_token.column,
                .{ .binary = .{
                    .operator = operator,
                    .left = left,
                    .right = right,
                } },
            );
        }

        return left;
    }

    /// Parse unary expression.
    fn parse_unary_expression(self: *Parser) ParserError!u32 {
        // Assert: Token index must be valid
        std.debug.assert(self.token_index < self.tokens.len);

        const token = self.get_current_token();

        // Unary operators
        if (token.token_type == .op_not or token.token_type ==
.op_minus) {
            const operator_token = token;
            self.advance(); // Skip operator

            const operand = try self.parse_unary_expression();

            const operator: UnaryOperator = if (token.token_type ==
.op_not) .not else .negate;

            return try self.create_node(
                .expr_unary,
                operator_token.start,
                self.get_current_token().end,
                operator_token.line,
                operator_token.column,
                .{ .unary = .{
                    .operator = operator,
                    .operand = operand,
                } },
            );
        }

        // Primary expression
        return try self.parse_primary_expression();
    }

    /// Parse primary expression.
    fn parse_primary_expression(self: *Parser) ParserError!u32 {
        // Assert: Token index must be valid
        std.debug.assert(self.token_index < self.tokens.len);

        const token = self.get_current_token();

        // Literal
        if (is_literal_token(token.token_type)) {
            return try self.parse_literal();
        }

        // Identifier
        if (token.token_type == .identifier) {
            const identifier_token = token;
            self.advance(); // Skip identifier

            // Function call
            if (self.get_current_token().token_type == .punc_lparen) {
                return try self.parse_function_call(identifier_token);
            }

            // Plain identifier
            const name =
self.source[identifier_token.start..identifier_token.end];
            return try self.create_node(
                .expr_identifier,
                identifier_token.start,
                identifier_token.end,
                identifier_token.line,
                identifier_token.column,
                .{ .identifier = .{
                    .name = name,
                    .name_len = identifier_token.end -
identifier_token.start,
                } },
            );
        }

        // Grouped expression
        if (token.token_type == .punc_lparen) {
            self.advance(); // Skip '('
            const expr = try self.parse_expression();
            if (self.get_current_token().token_type != .punc_rparen) {
                return error.ExpectedRightParen;
            }
            self.advance(); // Skip ')'

            return try self.create_node(
                .expr_group,
                token.start,
                self.get_current_token().end,
                token.line,
                token.column,
                .{ .group = .{ .expr = expr } },
            );
        }

        return error.UnexpectedToken;
    }

    /// Parse literal expression.
    fn parse_literal(self: *Parser) ParserError!u32 {
        // Assert: Current token must be a literal
       
std.debug.assert(is_literal_token(self.get_current_token().token_type));

        const token = self.get_current_token();
        const value = self.source[token.start..token.end];

        var literal_type: LiteralType = undefined;
        switch (token.token_type) {
            .integer => literal_type = .integer,
            .float => literal_type = .float,
            .string => literal_type = .string,
            .kw_true => literal_type = .boolean_true,
            .kw_false => literal_type = .boolean_false,
            .kw_null => literal_type = .null,
            else => return error.InvalidLiteral,
        }

        self.advance(); // Skip literal

        return try self.create_node(
            .expr_literal,
            token.start,
            token.end,
            token.line,
            token.column,
            .{ .literal = .{
                .literal_type = literal_type,
                .value = value,
                .value_len = token.end - token.start,
            } },
        );
    }

    /// Parse function call.
    fn parse_function_call(self: *Parser, callee_token: Lexer.Token)
ParserError!u32 {
        // Assert: Current token must be '('
        std.debug.assert(self.get_current_token().token_type ==
.punc_lparen);

        const start_token = self.get_current_token();
        self.advance(); // Skip '('

        // Create callee identifier node
        const callee_name =
self.source[callee_token.start..callee_token.end];
        const callee = try self.create_node(
            .expr_identifier,
            callee_token.start,
            callee_token.end,
            callee_token.line,
            callee_token.column,
            .{ .identifier = .{
                .name = callee_name,
                .name_len = callee_token.end - callee_token.start,
            } },
        );

        var args = std.ArrayListUnmanaged(u32){};
        defer args.deinit(self.allocator);
        try args.ensureTotalCapacity(self.allocator, MAX_EXPR_OPERANDS);

        // Parse argument list
        while (self.get_current_token().token_type != .punc_rparen) {
            if (self.get_current_token().token_type == .eof) {
                return error.UnexpectedEof;
            }

            // Skip comma if not first argument
            if (args.items.len > 0) {
                if (self.get_current_token().token_type != .punc_comma) {
                    return error.ExpectedComma;
                }
                self.advance(); // Skip ','
            }

            // Parse argument expression
            const arg = try self.parse_expression();
            try args.append(self.allocator, arg);
        }

        self.advance(); // Skip ')'

        // Create function call node
        const args_slice = try self.allocator.dupe(u32, args.items);
        errdefer self.allocator.free(args_slice);

        return try self.create_node(
            .expr_call,
            start_token.start,
            self.get_current_token().end,
            start_token.line,
            start_token.column,
            .{ .call = .{
                .callee = callee,
                .args = args_slice,
                .args_len = @as(u32, @intCast(args_slice.len)),
            } },
        );
    }

    /// Parse type.
    fn parse_type(self: *Parser) ParserError!u32 {
        // Assert: Token index must be valid
        std.debug.assert(self.token_index < self.tokens.len);

        const token = self.get_current_token();

        // Named type (identifier)
        if (token.token_type == .identifier) {
            const name = self.source[token.start..token.end];
            self.advance(); // Skip identifier

            return try self.create_node(
                .type_named,
                token.start,
                token.end,
                token.line,
                token.column,
                .{ .type_named = .{
                    .name = name,
                    .name_len = token.end - token.start,
                } },
            );
        }

        return error.ExpectedType;
    }

    /// Create AST node.
    fn create_node(self: *Parser, node_type: NodeType, start: u32, end:
u32, line: u32, column: u32, data: NodeData) !u32 {
        // Assert: Node count must be within bounds
        std.debug.assert(self.nodes_len < MAX_AST_NODES);

        // Assert: Depth must be within bounds
        std.debug.assert(self.depth <= MAX_AST_DEPTH);

        const index = self.nodes_len;
        self.nodes[index] = Node{
            .node_type = node_type,
            .start = start,
            .end = end,
            .line = line,
            .column = column,
            .depth = self.depth,
            .data = data,
        };
        self.nodes_len += 1;

        return index;
    }

    /// Get current token.
    fn get_current_token(self: *const Parser) Lexer.Token {
        // Assert: Token index must be valid
        std.debug.assert(self.token_index < self.tokens.len);

        return self.tokens[self.token_index];
    }

    /// Advance to next token.
    fn advance(self: *Parser) void {
        // Assert: Token index must be valid
        std.debug.assert(self.token_index < self.tokens.len);

        self.token_index += 1;
    }

    /// Get binary operator precedence (higher = tighter binding).
    fn get_binary_precedence(token_type: Lexer.TokenType) u32 {
        return switch (token_type) {
            // Logical operators (lowest precedence)
            .op_or => 1,
            .op_and => 2,
            // Comparison operators
            .op_eq, .op_ne, .op_lt, .op_le, .op_gt, .op_ge => 3,
            // Arithmetic operators
            .op_plus, .op_minus => 4,
            .op_multiply, .op_divide, .op_modulo => 5,
            else => 0, // Not a binary operator
        };
    }

    /// Convert token type to binary operator.
    fn token_type_to_binary_operator(token_type: Lexer.TokenType)
?BinaryOperator {
        return switch (token_type) {
            .op_plus => .add,
            .op_minus => .subtract,
            .op_multiply => .multiply,
            .op_divide => .divide,
            .op_modulo => .modulo,
            .op_eq => .eq,
            .op_ne => .ne,
            .op_lt => .lt,
            .op_le => .le,
            .op_gt => .gt,
            .op_ge => .ge,
            .op_and => .and_op,
            .op_or => .or_op,
            else => null,
        };
    }

    /// Check if token type is a literal.
    fn is_literal_token(token_type: Lexer.TokenType) bool {
        return switch (token_type) {
            .integer, .float, .string, .kw_true, .kw_false, .kw_null =>
true,
            else => false,
        };
    }

    /// Get node at index.
    pub fn get_node(self: *const Parser, index: u32) ?Node {
        // Assert: Index must be valid
        std.debug.assert(index < MAX_AST_NODES);

        if (index >= self.nodes_len) {
            return null;
        }

        return self.nodes[index];
    }

    /// Get number of nodes.
    pub fn get_node_count(self: *const Parser) u32 {
        return self.nodes_len;
    }
};

/// Parser errors.
pub const ParserError = error{
    ExpectedIdentifier,
    ExpectedLeftParen,
    ExpectedRightParen,
    ExpectedComma,
    ExpectedSemicolon,
    ExpectedAssign,
    ExpectedType,
    UnexpectedToken,
    UnexpectedEof,
    InvalidOperator,
    InvalidLiteral,
    InvalidNode,
    OutOfMemory,
};


