// === grainseed.zig ===

const std = @import("std");

// ╔═══════════════════════════════════════════════════════════════╗
// ║  G R A I N S E E D   v1.0                                     ║
// ║  "Plant a seed. Watch it grow. That's it. That's the program."║
// ╚═══════════════════════════════════════════════════════════════╝

const Stalk = struct {
    height: u8,
    lean: i8,
    seed: u64,
    rng: std.Random.DefaultPrng,

    fn init(seed: u64) Stalk {
        return Stalk{
            .height = 0,
            .lean = 0,
            .seed = seed,
            .rng = std.Random.DefaultPrng.init(seed),
        };
    }

    fn grow(self: *Stalk) void {
        const random = self.rng.random();
        self.height = random.intRangeAtMost(u8, 5, 15);
        
        std.debug.print("\n", .{});
        std.debug.print("      . \n", .{});
        std.debug.print("    \\ | / \n", .{});
        std.debug.print("   --(@)-- \n", .{});
        std.debug.print("    / | \\ \n", .{});
        std.debug.print("      | \n", .{});

        var i: u8 = 0;
        while (i < self.height) : (i += 1) {
            const sway = random.intRangeAtMost(i8, -1, 1);
            self.lean += sway;
            
            if (self.lean < -2) self.lean = -2;
            if (self.lean > 2) self.lean = 2;

            self.printSegment(i);
        }
        
        std.debug.print("    ~~~~~ \n", .{});
        std.debug.print("\n", .{});
    }

    fn printSegment(self: *Stalk, height_idx: u8) void {
        const random = self.rng.random();
        
        var indent: usize = 6;
        if (self.lean < 0) indent -= @intCast(@abs(self.lean));
        if (self.lean > 0) indent += @intCast(@abs(self.lean));

        var j: usize = 0;
        while (j < indent) : (j += 1) std.debug.print(" ", .{});

        const has_leaf_left = random.boolean() and height_idx % 3 == 0;
        const has_leaf_right = !has_leaf_left and random.boolean() and
height_idx % 3 == 0;

        if (has_leaf_left) std.debug.print("(", .{});
        std.debug.print("|", .{});
        if (has_leaf_right) std.debug.print(")", .{});
        
        std.debug.print("\n", .{});
    }
};

pub fn main() !void {
    var seed: u64 = 12025; 
    
    var args = std.process.args();
    _ = args.skip();
    if (args.next()) |arg| {
        seed = std.fmt.parseInt(u64, arg, 10) catch 12025;
    }

    std.debug.print("\n", .{});
    std.debug.print("┌─────────────────────────────────────────────┐\n",
.{});
    std.debug.print("│ GRAINSEED SIMULATOR 1997                    │\n",
.{});
    std.debug.print("│ (c) teamcarry11 - All Rights Reserved       │\n",
.{});
    std.debug.print("│                                             │\n",
.{});
    std.debug.print("│ Press ENTER to plant seed #{d: <15}│\n", .{seed});
    std.debug.print("└─────────────────────────────────────────────┘\n",
.{});
    std.debug.print("\n", .{});
    std.debug.print(">>> Initializing soil matrix...\n", .{});
    std.debug.print(">>> Calculating photosynthesis coefficients...\n",
.{});
    std.debug.print(">>> Planting...\n", .{});

    var stalk = Stalk.init(seed);
    stalk.grow();
    
    std.debug.print(">>> Growth complete!\n", .{});
    std.debug.print(">>> Thank you for using GRAINSEED v1.0\n", .{});
    std.debug.print("\n", .{});
}

// === grainseed_collection.zig ===

const std = @import("std");

// GRAINSEED ORDINALS COLLECTION GENERATOR
// Generates deterministic ASCII grainseeds for BTC Ordinals

const GrainseedMetadata = struct {
    seed_id: u64,
    height: u8,
    lean_direction: []const u8,
    leaf_count: u8,
    rarity_score: u8,
};

const Stalk = struct {
    height: u8,
    lean: i8,
    seed: u64,
    rng: std.Random.DefaultPrng,
    leaf_count: u8,

    fn init(seed: u64) Stalk {
        return Stalk{
            .height = 0,
            .lean = 0,
            .seed = seed,
            .rng = std.Random.DefaultPrng.init(seed),
            .leaf_count = 0,
        };
    }

    fn generateToBuffer(self: *Stalk, allocator: std.mem.Allocator,
buffer: *std.ArrayList(u8)) !GrainseedMetadata {
        const random = self.rng.random();
        self.height = random.intRangeAtMost(u8, 5, 15);
        self.leaf_count = 0;
        
        // Header
        try buffer.appendSlice(allocator, "      . \n");
        try buffer.appendSlice(allocator, "    \\ | / \n");
        try buffer.appendSlice(allocator, "   --(@)-- \n");
        try buffer.appendSlice(allocator, "    / | \\ \n");
        try buffer.appendSlice(allocator, "      | \n");

        // Stalk
        var i: u8 = 0;
        while (i < self.height) : (i += 1) {
            const sway = random.intRangeAtMost(i8, -1, 1);
            self.lean += sway;
            
            if (self.lean < -3) self.lean = -3;
            if (self.lean > 3) self.lean = 3;

            try self.printSegmentToBuffer(allocator, buffer, i);
        }
        
        // Roots
        try buffer.appendSlice(allocator, "    ~~~~~ \n");

        // Calculate rarity
        const rarity = self.calculateRarity();
        
        const lean_dir = if (self.lean < 0) "left" else if (self.lean >
0) "right" else "straight";
        
        return GrainseedMetadata{
            .seed_id = self.seed,
            .height = self.height,
            .lean_direction = lean_dir,
            .leaf_count = self.leaf_count,
            .rarity_score = rarity,
        };
    }

    fn printSegmentToBuffer(self: *Stalk, allocator: std.mem.Allocator,
buffer: *std.ArrayList(u8), height_idx: u8) !void {
        const random = self.rng.random();
        
        var indent: usize = 6;
        if (self.lean < 0) indent -= @intCast(@abs(self.lean));
        if (self.lean > 0) indent += @intCast(@abs(self.lean));

        var j: usize = 0;
        while (j < indent) : (j += 1) try buffer.append(allocator, ' ');

        const has_leaf_left = random.boolean() and height_idx % 3 == 0;
        const has_leaf_right = !has_leaf_left and random.boolean() and
height_idx % 3 == 0;

        if (has_leaf_left) {
            try buffer.append(allocator, '(');
            self.leaf_count += 1;
        }
        try buffer.append(allocator, '|');
        if (has_leaf_right) {
            try buffer.append(allocator, ')');
            self.leaf_count += 1;
        }
        
        try buffer.append(allocator, '\n');
    }

    fn calculateRarity(self: *Stalk) u8 {
        var score: u8 = 0;
        
        // Perfect straight = rare
        if (self.lean == 0) score += 30;
        
        // Maximum height = rare
        if (self.height >= 14) score += 20;
        
        // Many leaves = rare
        if (self.leaf_count >= 5) score += 25;
        
        // Extreme lean = rare
        if (@abs(self.lean) >= 3) score += 15;
        
        return score;
    }
};

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    const args = try std.process.argsAlloc(allocator);
    defer std.process.argsFree(allocator, args);

    if (args.len < 2) {
        std.debug.print("Usage: grainseed_collection <start_id>
[end_id]\n", .{});
        std.debug.print("Example: grainseed_collection 1 100\n", .{});
        return;
    }

    const start_id = try std.fmt.parseInt(u64, args[1], 10);
    const end_id = if (args.len >= 3) try std.fmt.parseInt(u64, args[2],
10) else start_id;

    std.debug.print("Generating Grainseeds #{d} to #{d}...\n\n",
.{start_id, end_id});

    // Create output directory
    const cwd = std.fs.cwd();
    cwd.makeDir("grainseeds_output") catch |err| {
        if (err != error.PathAlreadyExists) return err;
    };

    var id = start_id;
    while (id <= end_id) : (id += 1) {
        var buffer: std.ArrayList(u8) = .{
            .items = &.{},
            .capacity = 0,
        };
        defer buffer.deinit(allocator);

        var stalk = Stalk.init(id);
        const metadata = try stalk.generateToBuffer(allocator, &buffer);

        // Write to file
        const filename = try std.fmt.allocPrint(allocator,
"grainseeds_output/grainseed_{d}.txt", .{id});
        defer allocator.free(filename);

        const file = try cwd.createFile(filename, .{});
        defer file.close();

        try file.writeAll(buffer.items);

        // Print metadata
        std.debug.print("Grainseed #{d}: height={d}, lean={s},
leaves={d}, rarity={d}\n", 
            .{metadata.seed_id, metadata.height,
metadata.lean_direction, metadata.leaf_count, metadata.rarity_score});
    }

    std.debug.print("\n✓ Generated {d} grainseeds in
grainseeds_output/\n", .{end_id - start_id + 1});
}

// === grainvault.zig ===

const std = @import("std");

/// GrainVault: simple, explicit holder for API secrets needed to script
/// Cursor CLI and Claude Code sessions. The actual secret material is
/// expected to live in the external `{teamtreasure02}/grainvault`
/// repository, mirrored in via `grainmirror`. This stub reads from
/// environment variables so we avoid bundling secrets in-source.
pub const Vault = struct {
    cursor_cli_key: []const u8,
    claude_code_key: []const u8,

    pub fn initFromEnv(allocator: std.mem.Allocator) !Vault {
        const cursor_key = try dupEnv(allocator, "CURSOR_API_TOKEN");
        errdefer allocator.free(cursor_key);
        const claude_key = try dupEnv(allocator,
"CLAUDE_CODE_API_TOKEN");
        errdefer allocator.free(claude_key);

        return .{
            .cursor_cli_key = cursor_key,
            .claude_code_key = claude_key,
        };
    }

    pub fn deinit(self: *Vault, allocator: std.mem.Allocator) void {
        allocator.free(self.cursor_cli_key);
        allocator.free(self.claude_code_key);
        self.* = undefined;
    }

    pub fn cursorCommandArgs(self: Vault, extra_args: []const []const
u8, allocator: std.mem.Allocator) ![]const []const u8 {
        var list = std.ArrayList([]const u8).init(allocator);
        errdefer list.deinit();

        try list.append("cursor");
        try list.append("--api-key");
        try list.append(self.cursor_cli_key);
        for (extra_args) |arg| try list.append(arg);

        return list.toOwnedSlice();
    }

    pub fn claudeCommandArgs(self: Vault, extra_args: []const []const
u8, allocator: std.mem.Allocator) ![]const []const u8 {
        var list = std.ArrayList([]const u8).init(allocator);
        errdefer list.deinit();

        try list.append("claude");
        try list.append("--api-key");
        try list.append(self.claude_code_key);
        for (extra_args) |arg| try list.append(arg);

        return list.toOwnedSlice();
    }
};

fn dupEnv(allocator: std.mem.Allocator, key: []const u8) ![]const u8 {
    const value = std.process.getEnvVarOwned(allocator, key) catch |err|
switch (err) {
        error.EnvironmentVariableNotFound => return error.MissingSecret,
        else => return err,
    };
    if (value.len == 0) return error.MissingSecret;
    return value;
}

pub const MissingSecret = error{MissingSecret};

// === hashdag_consensus.zig ===

const std = @import("std");
const DagCore = @import("dag_core.zig").DagCore;

/// HashDAG Consensus: Event ordering via DAG consensus (Djinn's
proposal).
/// ~<~ Glow Airbend: explicit event ordering, bounded consensus.
/// ~~~~ Glow Waterbend: consensus flows deterministically through DAG.
///
/// This implements Djinn's HashDAG v0.1 proposal:
/// - Event-based: Everything is an event (code edit, web request, UI
update)
/// - Parent references: Events reference parents (like git commits)
/// - Virtual voting: Consensus without explicit vote messages
/// - Fast finality: Deterministic ordering in seconds
/// - High throughput: Parallel ingestion (not sequential blocks)
pub const HashDagConsensus = struct {
    allocator: std.mem.Allocator,
    dag: *DagCore,
    
    // Bounded: Max 10,000 pending events for consensus
    pub const MAX_PENDING_CONSENSUS: u32 = 10_000;
    
    // Bounded: Max 100 rounds for virtual voting
    pub const MAX_VOTING_ROUNDS: u32 = 100;
    
    // Bounded: Max 1,000 witnesses per round
    pub const MAX_WITNESSES_PER_ROUND: u32 = 1_000;
    
    /// Event in HashDAG consensus (extends DAG event with consensus
metadata).
    pub const ConsensusEvent = struct {
        event_id: u64, // DAG event ID
        creator_id: u32, // Creator/participant ID
        parents: []const u64, // Parent event IDs (HashDAG-style)
        parents_len: u32,
        timestamp: u64, // Unix timestamp
        round: u32 = 0, // Consensus round (determined by virtual voting)
        fame: ?bool = null, // Fame status (true = famous, false = not
famous, null = undecided)
        witness: bool = false, // Is this event a witness in its round?
        finality: bool = false, // Has this event achieved finality?
    };
    
    /// Consensus state for event ordering.
    pub const ConsensusState = struct {
        events: []ConsensusEvent,
        events_len: u32,
        current_round: u32 = 0,
        finalized_events: u32 = 0,
    };
    
    state: ConsensusState,
    
    /// Initialize HashDAG consensus.
    pub fn init(allocator: std.mem.Allocator, dag: *DagCore)
!HashDagConsensus {
        // Assert: Allocator and DAG must be valid
        std.debug.assert(allocator.ptr != null);
        _ = dag; // DAG is owned by caller
        
        // Pre-allocate consensus event buffer
        const events = try allocator.alloc(ConsensusEvent,
MAX_PENDING_CONSENSUS);
        errdefer allocator.free(events);
        
        return HashDagConsensus{
            .allocator = allocator,
            .dag = dag,
            .state = ConsensusState{
                .events = events,
                .events_len = 0,
                .current_round = 0,
                .finalized_events = 0,
            },
        };
    }
    
    /// Deinitialize HashDAG consensus.
    pub fn deinit(self: *HashDagConsensus) void {
        // Free parent arrays
        for (self.state.events[0..self.state.events_len]) |*event| {
            if (event.parents.len > 0) {
                self.allocator.free(event.parents);
            }
        }
        
        self.allocator.free(self.state.events);
    }
    
    /// Add event to consensus (HashDAG-style with parent references).
    pub fn addEvent(
        self: *HashDagConsensus,
        event_id: u64,
        creator_id: u32,
        parents: []const u64,
    ) !void {
        // Assert: Event count must be within bounds
        std.debug.assert(self.state.events_len < MAX_PENDING_CONSENSUS);
        
        // Assert: Event ID must be valid (must exist in DAG)
        const dag_event = self.findDagEvent(event_id);
        std.debug.assert(dag_event != null);
        
        // Assert: Creator ID must be valid
        std.debug.assert(creator_id < 1_000_000); // Reasonable limit
        
        // Copy parent IDs
        const parent_ids = try self.allocator.dupe(u64, parents);
        errdefer self.allocator.free(parent_ids);
        
        // Create consensus event
        const consensus_event = ConsensusEvent{
            .event_id = event_id,
            .creator_id = creator_id,
            .parents = parent_ids,
            .parents_len = @as(u32, @intCast(parent_ids.len)),
            .timestamp = std.time.timestamp(),
            .round = 0, // Will be determined by virtual voting
            .fame = null, // Will be determined by virtual voting
            .witness = false, // Will be determined by virtual voting
            .finality = false, // Will be determined by finality manager
        };
        
        const event_idx = self.state.events_len;
        self.state.events[event_idx] = consensus_event;
        self.state.events_len += 1;
        
        // Assert: Event was added
        std.debug.assert(self.state.events_len == event_idx + 1);
    }
    
    /// Determine consensus round for events (virtual voting,
HashDAG-style).
    pub fn determineRounds(self: *HashDagConsensus) !void {
        // Assert: Events must be valid
        std.debug.assert(self.state.events_len <= MAX_PENDING_CONSENSUS);
        
        // Simple round determination: round = max(parent rounds) + 1
        // This is a simplified version of HashDAG's virtual voting
        for (self.state.events[0..self.state.events_len]) |*event| {
            if (event.round == 0) {
                // Find max parent round
                var max_parent_round: u32 = 0;
                
                for (event.parents) |parent_id| {
                    const parent_event =
self.findConsensusEvent(parent_id);
                    if (parent_event) |parent| {
                        if (parent.round > max_parent_round) {
                            max_parent_round = parent.round;
                        }
                    }
                }
                
                // Round = max parent round + 1
                event.round = max_parent_round + 1;
                
                // Update current round
                if (event.round > self.state.current_round) {
                    self.state.current_round = event.round;
                }
            }
        }
        
        // Assert: All events have rounds assigned
        for (self.state.events[0..self.state.events_len]) |event| {
            std.debug.assert(event.round > 0);
        }
    }
    
    /// Determine witness events (events that are first in their round
from their creator).
    pub fn determineWitnesses(self: *HashDagConsensus) !void {
        // Assert: Rounds must be determined first
        std.debug.assert(self.state.current_round > 0);
        
        // For each creator, find first event in each round (witness)
        var creator_rounds = std.AutoHashMap(u32,
u32).init(self.allocator);
        defer creator_rounds.deinit();
        
        for (self.state.events[0..self.state.events_len]) |*event| {
            const entry = try creator_rounds.getOrPut(event.creator_id);
            
            if (!entry.found_existing) {
                // First event from this creator in this round = witness
                entry.value_ptr.* = event.round;
                event.witness = true;
            } else {
                // Check if this is first event in this round from this
creator
                if (event.round < entry.value_ptr.*) {
                    // Reset previous witness
                    for (self.state.events[0..self.state.events_len])
|*e| {
                        if (e.creator_id == event.creator_id and e.round
== entry.value_ptr.*) {
                            e.witness = false;
                        }
                    }
                    entry.value_ptr.* = event.round;
                    event.witness = true;
                }
            }
        }
        
        // Assert: At least one witness per round
        // TODO: Verify witness distribution
    }
    
    /// Determine fame status (simplified virtual voting).
    pub fn determineFame(self: *HashDagConsensus) !void {
        // Assert: Witnesses must be determined first
        // TODO: Verify witnesses are set
        
        // Simplified fame determination: witness events are famous
        // In full HashDAG, fame is determined by virtual voting across
rounds
        for (self.state.events[0..self.state.events_len]) |*event| {
            if (event.witness) {
                event.fame = true; // Witness events are famous
            } else {
                event.fame = false; // Non-witness events are not famous
            }
        }
        
        // Assert: All events have fame status
        for (self.state.events[0..self.state.events_len]) |event| {
            std.debug.assert(event.fame != null);
        }
    }
    
    /// Determine finality (fast finality, seconds not minutes).
    pub fn determineFinality(self: *HashDagConsensus) !void {
        // Assert: Fame must be determined first
        // TODO: Verify fame is set
        
        // Simplified finality: events in rounds N-2 or earlier are
finalized
        // In full HashDAG, finality is determined by famous witness
consensus
        const finality_round = if (self.state.current_round >= 2)
self.state.current_round - 2 else 0;
        
        for (self.state.events[0..self.state.events_len]) |*event| {
            if (event.round <= finality_round and event.fame == true) {
                event.finality = true;
                self.state.finalized_events += 1;
            }
        }
        
        // Assert: Finalized events count is correct
        var finalized_count: u32 = 0;
        for (self.state.events[0..self.state.events_len]) |event| {
            if (event.finality) {
                finalized_count += 1;
            }
        }
        std.debug.assert(finalized_count == self.state.finalized_events);
    }
    
    /// Get ordered events (deterministic ordering via HashDAG
consensus).
    pub fn getOrderedEvents(self: *const HashDagConsensus) []const
ConsensusEvent {
        // Return events sorted by: round, then timestamp, then event ID
        // This provides deterministic ordering
        const events = self.state.events[0..self.state.events_len];
        
        // Sort events (round, timestamp, event_id)
        // For now, return unsorted (caller should sort)
        // TODO: Implement proper sorting
        return events;
    }
    
    /// Find consensus event by DAG event ID.
    fn findConsensusEvent(self: *const HashDagConsensus, event_id: u64)
?*const ConsensusEvent {
        for (self.state.events[0..self.state.events_len]) |*event| {
            if (event.event_id == event_id) {
                return event;
            }
        }
        return null;
    }
    
    /// Find DAG event by ID (helper function).
    fn findDagEvent(self: *const HashDagConsensus, event_id: u64)
?*const DagCore.Event {
        const events =
self.dag.pending_events[0..self.dag.pending_events_len];
        for (events) |*event| {
            if (event.id == event_id) {
                return event;
            }
        }
        return null;
    }
    
    /// Process consensus (determine rounds, witnesses, fame, finality).
    pub fn processConsensus(self: *HashDagConsensus) !void {
        // Assert: Events must be valid
        std.debug.assert(self.state.events_len <= MAX_PENDING_CONSENSUS);
        
        // Step 1: Determine rounds
        try self.determineRounds();
        
        // Step 2: Determine witnesses
        try self.determineWitnesses();
        
        // Step 3: Determine fame
        try self.determineFame();
        
        // Step 4: Determine finality
        try self.determineFinality();
        
        // Assert: Consensus processed
        std.debug.assert(self.state.current_round > 0);
    }
    
    /// Get finality statistics.
    pub fn getFinalityStats(self: *const HashDagConsensus) FinalityStats
{
        var stats = FinalityStats{
            .total_events = self.state.events_len,
            .finalized_events = self.state.finalized_events,
            .pending_events = self.state.events_len -
self.state.finalized_events,
            .current_round = self.state.current_round,
            .finality_rate = 0.0,
        };
        
        if (stats.total_events > 0) {
            stats.finality_rate = @as(f64,
@floatFromInt(stats.finalized_events)) / @as(f64,
@floatFromInt(stats.total_events));
        }
        
        return stats;
    }
    
    /// Finality statistics.
    pub const FinalityStats = struct {
        total_events: u32,
        finalized_events: u32,
        pending_events: u32,
        current_round: u32,
        finality_rate: f64, // 0.0 to 1.0
    };
};

test "hashdag consensus initialization" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag = try DagCore.init(arena.allocator());
    defer dag.deinit();
    
    var consensus = try HashDagConsensus.init(arena.allocator(), &dag);
    defer consensus.deinit();
    
    // Assert: Consensus initialized
    try std.testing.expect(consensus.state.events_len == 0);
    try std.testing.expect(consensus.state.current_round == 0);
}

test "hashdag consensus add event" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag = try DagCore.init(arena.allocator());
    defer dag.deinit();
    
    var consensus = try HashDagConsensus.init(arena.allocator(), &dag);
    defer consensus.deinit();
    
    // Add DAG event first
    const dag_node_id = try dag.addNode(.ast_node, "test", .{});
    const dag_event_id = try dag.addEvent(.code_edit, dag_node_id,
"edit", &.{});
    
    // Add consensus event
    try consensus.addEvent(dag_event_id, 0, &.{});
    
    // Assert: Event was added
    try std.testing.expect(consensus.state.events_len == 1);
    try std.testing.expect(consensus.state.events[0].event_id ==
dag_event_id);
}

test "hashdag consensus determine rounds" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag = try DagCore.init(arena.allocator());
    defer dag.deinit();
    
    var consensus = try HashDagConsensus.init(arena.allocator(), &dag);
    defer consensus.deinit();
    
    // Add DAG events
    const dag_node_id = try dag.addNode(.ast_node, "test", .{});
    const dag_event1 = try dag.addEvent(.code_edit, dag_node_id,
"edit1", &.{});
    const dag_event2 = try dag.addEvent(.code_edit, dag_node_id,
"edit2", &.{});
    
    // Add consensus events (event2 references event1 as parent)
    try consensus.addEvent(dag_event1, 0, &.{});
    try consensus.addEvent(dag_event2, 0, &.{dag_event1});
    
    // Determine rounds
    try consensus.determineRounds();
    
    // Assert: Rounds determined
    try std.testing.expect(consensus.state.events[0].round == 1);
    try std.testing.expect(consensus.state.events[1].round == 2);
    try std.testing.expect(consensus.state.current_round == 2);
}

test "hashdag consensus process consensus" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    
    var dag = try DagCore.init(arena.allocator());
    defer dag.deinit();
    
    var consensus = try HashDagConsensus.init(arena.allocator(), &dag);
    defer consensus.deinit();
    
    // Add DAG events
    const dag_node_id = try dag.addNode(.ast_node, "test", .{});
    const dag_event1 = try dag.addEvent(.code_edit, dag_node_id,
"edit1", &.{});
    const dag_event2 = try dag.addEvent(.code_edit, dag_node_id,
"edit2", &.{});
    
    // Add consensus events
    try consensus.addEvent(dag_event1, 0, &.{});
    try consensus.addEvent(dag_event2, 0, &.{dag_event1});
    
    // Process consensus
    try consensus.processConsensus();
    
    // Assert: Consensus processed
    try std.testing.expect(consensus.state.current_round > 0);
    try std.testing.expect(consensus.state.events[0].fame != null);
}


// === kernel/audio.zig ===

//! Audio Device Management
//! Why: Manage audio devices for multimedia applications.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Maximum number of audio devices.
/// Why: Bounded allocation for device tracking.
const MAX_AUDIO_DEVICES: u32 = 16;

/// Maximum device name length.
/// Why: Bounded string storage for device names.
const MAX_DEVICE_NAME_LEN: u32 = 128;

/// Maximum audio buffer size (64KB).
/// Why: Bounded allocation for audio I/O buffers.
const MAX_AUDIO_BUFFER_SIZE: u32 = 64 * 1024;

/// Audio device type.
/// Why: Categorize audio devices (speaker, headphone, microphone, etc.).
pub const AudioDeviceType = enum(u8) {
    unknown = 0,
    speaker = 1,
    headphone = 2,
    microphone = 3,
    bluetooth = 4,
    usb = 5,
};

/// Audio device state.
/// Why: Track device state (disconnected, connected, active, disabled).
pub const AudioDeviceState = enum(u8) {
    disconnected = 0,
    connected = 1,
    active = 2,
    disabled = 3,
};

/// Audio format.
/// Why: Specify audio format (sample rate, channels, bit depth).
/// Grain Style: Explicit types, bounded values.
pub const AudioFormat = struct {
    /// Sample rate in Hz (e.g., 44100, 48000).
    sample_rate: u32,
    
    /// Number of channels (1 = mono, 2 = stereo).
    channels: u32,
    
    /// Bit depth (8, 16, 24, 32).
    bit_depth: u32,
    
    /// Initialize audio format with defaults.
    /// Why: Explicit initialization, clear state.
    pub fn init() AudioFormat {
        return AudioFormat{
            .sample_rate = 44100,
            .channels = 2,
            .bit_depth = 16,
        };
    }
    
    /// Validate audio format.
    /// Why: Ensure format is valid.
    /// Contract: sample_rate, channels, bit_depth must be valid.
    pub fn is_valid(self: *const AudioFormat) bool {
        // Assert: Sample rate must be reasonable (8kHz to 192kHz).
        if (self.sample_rate < 8000 or self.sample_rate > 192000) {
            return false;
        }
        
        // Assert: Channels must be reasonable (1 to 8).
        if (self.channels == 0 or self.channels > 8) {
            return false;
        }
        
        // Assert: Bit depth must be valid (8, 16, 24, 32).
        if (self.bit_depth != 8 and
            self.bit_depth != 16 and
            self.bit_depth != 24 and
            self.bit_depth != 32) {
            return false;
        }
        
        return true;
    }
};

/// Audio device entry.
/// Why: Track audio device configuration and state.
/// Grain Style: Static allocation, explicit types.
pub const AudioDevice = struct {
    /// Device ID (non-zero if allocated).
    device_id: u32,
    
    /// Device name (null-terminated).
    name: [MAX_DEVICE_NAME_LEN]u8,
    
    /// Device type.
    device_type: AudioDeviceType,
    
    /// Device state.
    state: AudioDeviceState,
    
    /// Volume level (0-100 percentage).
    volume: u32,
    
    /// Mute state.
    muted: bool,
    
    /// Whether this entry is allocated (in use).
    allocated: bool,
    
    /// Owner process ID (0 = kernel-owned, non-zero = process-owned).
    /// Why: Track which process owns this device for resource cleanup.
    owner_process_id: u32,
    
    /// Audio format (sample rate, channels, bit depth).
    /// Why: Specify audio format for I/O operations.
    format: AudioFormat,
    
    /// Input buffer (for recording/input devices).
    /// Why: Buffer incoming audio data.
    input_buffer: [MAX_AUDIO_BUFFER_SIZE]u8,
    
    /// Input buffer size (actual data length).
    input_buffer_len: u32,
    
    /// Output buffer (for playback/output devices).
    /// Why: Buffer outgoing audio data.
    output_buffer: [MAX_AUDIO_BUFFER_SIZE]u8,
    
    /// Output buffer size (actual data length).
    output_buffer_len: u32,
    
    /// Initialize empty audio device entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() AudioDevice {
        var device = AudioDevice{
            .device_id = 0,
            .name = undefined,
            .device_type = .unknown,
            .state = .disconnected,
            .volume = 50,
            .muted = false,
            .allocated = false,
            .owner_process_id = 0,
            .format = AudioFormat.init(),
            .input_buffer = [_]u8{0} ** MAX_AUDIO_BUFFER_SIZE,
            .input_buffer_len = 0,
            .output_buffer = [_]u8{0} ** MAX_AUDIO_BUFFER_SIZE,
            .output_buffer_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_DEVICE_NAME_LEN) : (i += 1) {
            device.name[i] = 0;
        }
        return device;
    }
    
    /// Set device name.
    /// Why: Configure device name.
    /// Contract: name must be valid, non-empty, null-terminated.
    pub fn set_name(self: *AudioDevice, name: []const u8) bool {
        // Assert: Entry must be allocated.
        Debug.kassert(self.allocated, "Entry not allocated", .{});
        
        // Assert: Name must be non-empty.
        if (name.len == 0) {
            return false;
        }
        
        // Assert: Name must fit in buffer (including null terminator).
        if (name.len >= MAX_DEVICE_NAME_LEN) {
            return false;
        }
        
        // Copy name to buffer.
        var i: u32 = 0;
        while (i < MAX_DEVICE_NAME_LEN) : (i += 1) {
            self.name[i] = 0;
        }
        std.mem.copyForwards(u8, self.name[0..name.len], name);
        self.name[name.len] = 0; // Null terminator
        
        return true;
    }
    
    /// Get device name.
    /// Why: Retrieve device name.
    /// Contract: Returns null-terminated string.
    pub fn get_name(self: *const AudioDevice) []const u8 {
        // Assert: Entry must be allocated.
        Debug.kassert(self.allocated, "Entry not allocated", .{});
        
        // Find null terminator.
        var len: u32 = 0;
        while (len < MAX_DEVICE_NAME_LEN) : (len += 1) {
            if (self.name[len] == 0) {
                break;
            }
        }
        
        return self.name[0..len];
    }
    
    /// Set audio format.
    /// Why: Configure audio format for I/O operations.
    /// Contract: format must be valid.
    pub fn set_format(self: *AudioDevice, format: AudioFormat) bool {
        // Assert: Entry must be allocated.
        Debug.kassert(self.allocated, "Entry not allocated", .{});
        
        // Assert: Format must be valid.
        if (!format.is_valid()) {
            return false;
        }
        
        self.format = format;
        return true;
    }
    
    /// Get audio format.
    /// Why: Retrieve audio format.
    /// Contract: Returns current format.
    pub fn get_format(self: *const AudioDevice) AudioFormat {
        // Assert: Entry must be allocated.
        Debug.kassert(self.allocated, "Entry not allocated", .{});
        
        return self.format;
    }
};

/// Audio device manager.
/// Why: Manage all audio devices.
/// Grain Style: Static allocation, bounded operations.
pub const AudioDeviceManager = struct {
    /// Device entries.
    devices: [MAX_AUDIO_DEVICES]AudioDevice,
    
    /// Next device ID (simple allocator, starts at 1).
    /// Why: Track device ID allocation (1-based, 0 is invalid).
    next_device_id: u32,
    
    /// Master volume (0-100 percentage).
    master_volume: u32,
    
    /// Master mute state.
    master_muted: bool,
    
    /// Active output device ID (0 if none).
    active_output_device_id: u32,
    
    /// Active input device ID (0 if none).
    active_input_device_id: u32,
    
    /// Whether manager is initialized.
    initialized: bool,
    
    /// Initialize audio device manager.
    /// Why: Set up manager state.
    pub fn init() AudioDeviceManager {
        var manager = AudioDeviceManager{
            .devices = undefined,
            .next_device_id = 1,
            .master_volume = 50,
            .master_muted = false,
            .active_output_device_id = 0,
            .active_input_device_id = 0,
            .initialized = true,
        };
        var i: u32 = 0;
        while (i < MAX_AUDIO_DEVICES) : (i += 1) {
            manager.devices[i] = AudioDevice.init();
        }
        return manager;
    }
    
    /// Create a new audio device.
    /// Why: Add a new audio device.
    /// Contract: name must be valid, non-empty, null-terminated,
device_type must be valid.
    /// Returns: Device ID, or null if no free slot.
    pub fn create_device(
        self: *AudioDeviceManager,
        name: []const u8,
        device_type: AudioDeviceType,
        owner_process_id: u32,
    ) ?u32 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Name must be non-empty.
        if (name.len == 0) {
            return null;
        }
        
        // Assert: Name must fit in buffer.
        if (name.len >= MAX_DEVICE_NAME_LEN) {
            return null;
        }
        
        // Find free slot.
        var idx: u32 = 0;
        while (idx < MAX_AUDIO_DEVICES) : (idx += 1) {
            if (!self.devices[idx].allocated) {
                // Initialize device.
                self.devices[idx] = AudioDevice.init();
                self.devices[idx].allocated = true;
                self.devices[idx].device_id = self.next_device_id;
                self.devices[idx].device_type = device_type;
                self.devices[idx].owner_process_id = owner_process_id;
                
                // Set name.
                if (!self.devices[idx].set_name(name)) {
                    self.devices[idx].allocated = false;
                    return null;
                }
                
                // Increment device ID.
                const device_id = self.next_device_id;
                self.next_device_id += 1;
                if (self.next_device_id == 0) {
                    self.next_device_id = 1; // Wrap around (skip 0)
                }
                
                return device_id;
            }
        }
        
        // No free slot found.
        return null;
    }
    
    /// Get device by ID.
    /// Why: Retrieve device entry.
    /// Contract: device_id must be valid (non-zero).
    /// Returns: Pointer to device entry, or null if not found.
    pub fn get_device(
        self: *AudioDeviceManager,
        device_id: u32,
    ) ?*AudioDevice {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Device ID must be non-zero.
        if (device_id == 0) {
            return null;
        }
        
        // Search for device with matching ID.
        var idx: u32 = 0;
        while (idx < MAX_AUDIO_DEVICES) : (idx += 1) {
            if (self.devices[idx].allocated and
self.devices[idx].device_id == device_id) {
                return &self.devices[idx];
            }
        }
        
        // Device not found.
        return null;
    }
    
    /// Set device volume.
    /// Why: Control device volume.
    /// Contract: device_id must be valid, volume must be 0-100.
    pub fn set_device_volume(
        self: *AudioDeviceManager,
        device_id: u32,
        volume: u32,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Volume must be valid (0-100).
        if (volume > 100) {
            return false;
        }
        
        const device = self.get_device(device_id) orelse {
            return false;
        };
        
        device.volume = volume;
        return true;
    }
    
    /// Set device mute state.
    /// Why: Control device mute state.
    /// Contract: device_id must be valid.
    pub fn set_device_mute(
        self: *AudioDeviceManager,
        device_id: u32,
        muted: bool,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const device = self.get_device(device_id) orelse {
            return false;
        };
        
        device.muted = muted;
        return true;
    }
    
    /// Set device state.
    /// Why: Control device state.
    /// Contract: device_id must be valid, state must be valid.
    pub fn set_device_state(
        self: *AudioDeviceManager,
        device_id: u32,
        state: AudioDeviceState,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const device = self.get_device(device_id) orelse {
            return false;
        };
        
        device.state = state;
        return true;
    }
    
    /// Set active output device.
    /// Why: Select active output device.
    /// Contract: device_id must be valid (or 0 to clear).
    pub fn set_active_output_device(
        self: *AudioDeviceManager,
        device_id: u32,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // If device_id is 0, clear active device.
        if (device_id == 0) {
            self.active_output_device_id = 0;
            return true;
        }
        
        // Verify device exists.
        const device = self.get_device(device_id) orelse {
            return false;
        };
        
        // Verify device is output-capable (speaker, headphone,
bluetooth, usb).
        if (device.device_type != .speaker and
            device.device_type != .headphone and
            device.device_type != .bluetooth and
            device.device_type != .usb) {
            return false;
        }
        
        self.active_output_device_id = device_id;
        return true;
    }
    
    /// Set active input device.
    /// Why: Select active input device.
    /// Contract: device_id must be valid (or 0 to clear).
    pub fn set_active_input_device(
        self: *AudioDeviceManager,
        device_id: u32,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // If device_id is 0, clear active device.
        if (device_id == 0) {
            self.active_input_device_id = 0;
            return true;
        }
        
        // Verify device exists.
        const device = self.get_device(device_id) orelse {
            return false;
        };
        
        // Verify device is input-capable (microphone, bluetooth, usb).
        if (device.device_type != .microphone and
            device.device_type != .bluetooth and
            device.device_type != .usb) {
            return false;
        }
        
        self.active_input_device_id = device_id;
        return true;
    }
    
    /// Set master volume.
    /// Why: Control master volume.
    /// Contract: volume must be 0-100.
    pub fn set_master_volume(
        self: *AudioDeviceManager,
        volume: u32,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Volume must be valid (0-100).
        if (volume > 100) {
            return false;
        }
        
        self.master_volume = volume;
        return true;
    }
    
    /// Set master mute state.
    /// Why: Control master mute state.
    pub fn set_master_mute(
        self: *AudioDeviceManager,
        muted: bool,
    ) void {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        self.master_muted = muted;
    }
    
    /// Delete device.
    /// Why: Remove audio device.
    /// Contract: device_id must be valid.
    pub fn delete_device(
        self: *AudioDeviceManager,
        device_id: u32,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Search for device with matching ID.
        var idx: u32 = 0;
        while (idx < MAX_AUDIO_DEVICES) : (idx += 1) {
            if (self.devices[idx].allocated and
self.devices[idx].device_id == device_id) {
                // Clear active device references if this device is
active.
                if (self.active_output_device_id == device_id) {
                    self.active_output_device_id = 0;
                }
                if (self.active_input_device_id == device_id) {
                    self.active_input_device_id = 0;
                }
                
                // Deallocate device.
                self.devices[idx] = AudioDevice.init();
                return true;
            }
        }
        
        // Device not found.
        return false;
    }
    
    /// Set audio format for device.
    /// Why: Configure audio format for I/O operations.
    /// Contract: device_id must be valid, format must be valid.
    pub fn set_device_format(
        self: *AudioDeviceManager,
        device_id: u32,
        format: AudioFormat,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Format must be valid.
        if (!format.is_valid()) {
            return false;
        }
        
        const device = self.get_device(device_id) orelse {
            return false;
        };
        
        return device.set_format(format);
    }
    
    /// Read audio data from device.
    /// Why: Read audio data from input device.
    /// Contract: device_id must be valid, buffer must be valid, len
must be valid.
    /// Returns: Number of bytes read, or null on error.
    pub fn read_audio(
        self: *AudioDeviceManager,
        device_id: u32,
        buffer: []u8,
    ) ?u32 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Buffer must be non-empty.
        if (buffer.len == 0) {
            return null;
        }
        
        // Assert: Buffer must fit within max size.
        if (buffer.len > MAX_AUDIO_BUFFER_SIZE) {
            return null;
        }
        
        const device = self.get_device(device_id) orelse {
            return null;
        };
        
        // Assert: Device must be input-capable (microphone, bluetooth,
usb).
        if (device.device_type != .microphone and
            device.device_type != .bluetooth and
            device.device_type != .usb) {
            return null;
        }
        
        // Assert: Device must be active.
        if (device.state != .active) {
            return null;
        }
        
        // Calculate bytes to read (min of available data and buffer
size).
        const available = device.input_buffer_len;
        const bytes_to_read = @min(available, @as(u32,
@intCast(buffer.len)));
        
        // Copy data from input buffer.
        if (bytes_to_read > 0) {
            std.mem.copyForwards(u8, buffer[0..bytes_to_read], 
                device.input_buffer[0..bytes_to_read]);
            
            // Shift remaining data to front of buffer.
            if (bytes_to_read < available) {
                const remaining = available - bytes_to_read;
                std.mem.copyForwards(u8, 
                    device.input_buffer[0..remaining],
                    device.input_buffer[bytes_to_read..available]);
            }
            
            device.input_buffer_len -= bytes_to_read;
        }
        
        return bytes_to_read;
    }
    
    /// Write audio data to device.
    /// Why: Write audio data to output device.
    /// Contract: device_id must be valid, data must be valid, len must
be valid.
    /// Returns: Number of bytes written, or null on error.
    pub fn write_audio(
        self: *AudioDeviceManager,
        device_id: u32,
        data: []const u8,
    ) ?u32 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Data must be non-empty.
        if (data.len == 0) {
            return null;
        }
        
        // Assert: Data must fit within max size.
        if (data.len > MAX_AUDIO_BUFFER_SIZE) {
            return null;
        }
        
        const device = self.get_device(device_id) orelse {
            return null;
        };
        
        // Assert: Device must be output-capable (speaker, headphone,
bluetooth, usb).
        if (device.device_type != .speaker and
            device.device_type != .headphone and
            device.device_type != .bluetooth and
            device.device_type != .usb) {
            return null;
        }
        
        // Assert: Device must be active.
        if (device.state != .active) {
            return null;
        }
        
        // Calculate bytes to write (min of available space and data
size).
        const available = MAX_AUDIO_BUFFER_SIZE -
device.output_buffer_len;
        const bytes_to_write = @min(available, @as(u32,
@intCast(data.len)));
        
        // Copy data to output buffer.
        if (bytes_to_write > 0) {
            std.mem.copyForwards(u8, 
               
device.output_buffer[device.output_buffer_len..device.output_buffer_len
+ bytes_to_write],
                data[0..bytes_to_write]);
            
            device.output_buffer_len += bytes_to_write;
        }
        
        return bytes_to_write;
    }
};


// === kernel/basin_kernel.zig ===

//! Grain Basin kernel — The foundation that holds everything
//!
//! Grain Basin kernel is a Zig monolith kernel for RISC-V64, designed
for the next 30 years.
//! Non-POSIX, type-safe, minimal syscall surface, Grain Style safety.
//!
//! **Homebrew Bundle**: `grainbasin`
//!
//! **Vision**: Modern kernel design inspired by seL4 (minimal), Aero OS
(monolithic),
//! and Fuchsia (capability-based), but built in pure Zig for RISC-V.
//!
//! **Note**: Theseus OS uses SAS/SPL architecture (not traditional
monolithic).
//! Aero OS proves monolithic kernels work (runs real apps), but targets
x86_64 only.
//! Grain Basin kernel fills the gap: RISC-V native, non-POSIX, minimal
syscall surface.
//!
//! **Target**: Framework 13 DeepComputing RISC-V Mainboard
//! **Development**: macOS Tahoe IDE with RISC-V VM for testing

const std = @import("std");
const Debug = @import("debug.zig");
const Timer = @import("timer.zig").Timer;
const InterruptController = @import("interrupt.zig").InterruptController;
const Scheduler = @import("scheduler.zig").Scheduler;
const ChannelTable = @import("channel.zig").ChannelTable;
const ProcessContext = @import("process.zig").ProcessContext;
const Storage = @import("storage.zig").Storage;
const Keyboard = @import("keyboard.zig").Keyboard;
const Mouse = @import("mouse.zig").Mouse;
const MemoryPool = @import("memory.zig").MemoryPool;
const SignalTable = @import("signal.zig").SignalTable;
const Signal = @import("signal.zig").Signal;
const SignalAction = @import("signal.zig").SignalAction;
const elf_parser = @import("elf_parser.zig");
const segment_loader = @import("segment_loader.zig");
const page_table = @import("page_table.zig");
const PageTable = page_table.PageTable;
const page_fault_stats = @import("page_fault_stats.zig");
const PageFaultStats = page_fault_stats.PageFaultStats;
const memory_stats = @import("memory_stats.zig");
const MemoryStats = memory_stats.MemoryStats;
const cow = @import("cow.zig");
const CowTable = cow.CowTable;
const resource_cleanup = @import("resource_cleanup.zig");
const KernelLogBuffer = @import("kernel_log_buffer.zig").KernelLogBuffer;
const KernelLogEntry = @import("kernel_log_buffer.zig").KernelLogEntry;
const KernelLogLevel = @import("kernel_log_buffer.zig").KernelLogLevel;
const scheduler_stats = @import("scheduler_stats.zig");
const process_group = @import("process_group.zig");
const ProcessGroupManager = process_group.ProcessGroupManager;
const process_group_stats = @import("process_group_stats.zig");
const ProcessGroupStatsManager =
process_group_stats.ProcessGroupStatsManager;
const process_group_limits = @import("process_group_limits.zig");
const ProcessGroupLimitsManager =
process_group_limits.ProcessGroupLimitsManager;
const network = @import("network.zig");
const NetworkInterfaceManager = network.NetworkInterfaceManager;
const tcp_socket = @import("tcp_socket.zig");
const TcpSocketManager = tcp_socket.TcpSocketManager;
const udp_socket = @import("udp_socket.zig");
const UdpSocketManager = udp_socket.UdpSocketManager;
const audio = @import("audio.zig");
const AudioDeviceManager = audio.AudioDeviceManager;

// Export resource_cleanup for tests.
pub const resource_cleanup_module = resource_cleanup;

// Export RawIO for tests to disable hardware access.
pub const RawIO = @import("raw_io.zig");

/// Basin Kernel syscall numbers.
/// Why: Explicit syscall enumeration for type safety and clarity.
pub const Syscall = enum(u32) {
    // Process & Thread Management
    spawn = 1,
    exit = 2,
    yield = 3,
    wait = 4,
    
    // Memory Management
    map = 10,
    unmap = 11,
    protect = 12,
    
    // Inter-Process Communication
    channel_create = 20,
    channel_send = 21,
    channel_recv = 22,
    
    // I/O Operations
    open = 30,
    read = 31,
    write = 32,
    close = 33,
    unlink = 34,
    rename = 35,
    mkdir = 36,
    opendir = 37,
    readdir = 38,
    closedir = 39,
    
    // Time & Scheduling
    clock_gettime = 40,
    sleep_until = 41,
    
    // System Information
    sysinfo = 50,
    enumerate_processes = 51,
    get_process_info = 52,
    read_kernel_log = 53,
    set_priority = 54,
    get_priority = 55,
    setpgid = 56,
    getpgid = 57,
    setsid = 58,
    getsid = 59,
    
    // Input Events
    read_input_event = 60,
    
    // Framebuffer Operations
    fb_clear = 70,
    fb_draw_pixel = 71,
    fb_draw_text = 72,
    
    // Signal Operations
    kill = 80,
    signal = 81,
    sigaction = 82,
    
    // Network Operations
    network_create_interface = 90,
    network_set_state = 91,
    network_set_ipv4 = 92,
    network_get_interface = 93,
    
    // TCP Socket Operations
    tcp_socket = 100,
    tcp_bind = 101,
    tcp_listen = 102,
    tcp_accept = 103,
    tcp_connect = 104,
    tcp_send = 105,
    tcp_recv = 106,
    tcp_close = 107,
    
    // UDP Socket Operations
    udp_socket = 110,
    udp_bind = 111,
    udp_sendto = 112,
    udp_recvfrom = 113,
    udp_close = 114,
    
    // Audio Device Operations
    audio_create_device = 120,
    audio_set_volume = 121,
    audio_set_mute = 122,
    audio_set_state = 123,
    audio_set_active_output = 124,
    audio_set_active_input = 125,
    audio_set_master_volume = 126,
    audio_set_master_mute = 127,
    audio_get_device = 128,
    audio_set_format = 129,
    audio_read = 130,
    audio_write = 131,
};

/// Memory mapping flags.
/// Why: Explicit flags instead of POSIX-style bitmasks for type safety.
pub const MapFlags = packed struct {
    read: bool = false,
    write: bool = false,
    execute: bool = false,
    shared: bool = false,
    _padding: u28 = 0,
    
    /// Create MapFlags from boolean values.
    /// Why: Explicit construction, no magic numbers.
    pub fn init(flags: struct {
        read: bool = false,
        write: bool = false,
        execute: bool = false,
        shared: bool = false,
    }) MapFlags {
        return MapFlags{
            .read = flags.read,
            .write = flags.write,
            .execute = flags.execute,
            .shared = flags.shared,
            ._padding = 0,
        };
    }
};

/// File open flags.
/// Why: Explicit flags instead of POSIX O_* constants.
pub const OpenFlags = packed struct {
    read: bool = false,
    write: bool = false,
    create: bool = false,
    truncate: bool = false,
    _padding: u28 = 0,
    
    /// Create OpenFlags from boolean values.
    /// Why: Explicit construction, no magic numbers.
    pub fn init(flags: struct {
        read: bool = false,
        write: bool = false,
        create: bool = false,
        truncate: bool = false,
    }) OpenFlags {
        return OpenFlags{
            .read = flags.read,
            .write = flags.write,
            .create = flags.create,
            .truncate = flags.truncate,
            ._padding = 0,
        };
    }
};

/// Clock ID for time operations.
/// Why: Explicit clock types instead of POSIX CLOCK_* constants.
pub const ClockId = enum(u32) {
    monotonic = 0,
    realtime = 1,
};

/// Strongly-typed kernel handle (not integer file descriptor).
/// Why: Type safety, prevent handle confusion, explicit resource
management.
pub const Handle = struct {
    value: u64,
    
    /// Create handle from value.
    /// Why: Explicit construction, validate handle value.
    pub fn init(value: u64) Handle {
        // Assert: handle value must be non-zero (0 is invalid handle).
        Debug.kassert(value != 0, "Handle value must be non-zero", .{});
        
        return Handle{ .value = value };
    }
    
    /// Check if handle is valid (non-zero).
    /// Why: Explicit validation, prevent use of invalid handles.
    pub fn is_valid(self: Handle) bool {
        return self.value != 0;
    }
    
    /// Compare handles for equality.
    /// Why: Explicit comparison, prevent accidental comparison with
integers.
    pub fn eql(self: Handle, other: Handle) bool {
        return self.value == other.value;
    }
};

/// System information structure.
/// Why: Strongly-typed struct instead of POSIX sysinfo.
pub const SysInfo = struct {
    /// Total physical memory (bytes).
    total_memory: u64,
    
    /// Available physical memory (bytes).
    available_memory: u64,
    
    /// Used physical memory (bytes).
    /// Why: Track memory usage for resource monitoring.
    used_memory: u64,
    
    /// Number of CPU cores.
    cpu_cores: u32,
    
    /// Uptime (nanoseconds since boot).
    uptime_ns: u64,
    
    /// Load average (1-minute average, scaled by 1000).
    load_avg_1min: u32,
    
    /// Total number of processes (allocated).
    /// Why: Track process count for system monitoring.
    total_processes: u32,
    
    /// Number of running processes.
    /// Why: Track active process count for system monitoring.
    running_processes: u32,
    
    /// Number of exited processes.
    /// Why: Track terminated process count for system monitoring.
    exited_processes: u32,
    
    /// Initialize SysInfo with default values.
    /// Why: Explicit initialization, prevent uninitialized fields.
    pub fn init() SysInfo {
        return SysInfo{
            .total_memory = 0,
            .available_memory = 0,
            .used_memory = 0,
            .cpu_cores = 0,
            .uptime_ns = 0,
            .load_avg_1min = 0,
            .total_processes = 0,
            .running_processes = 0,
            .exited_processes = 0,
        };
    }
};

/// Process information structure for userspace.
/// Why: Provide process information to userspace programs.
/// GrainStyle: Explicit types, bounded size, deterministic layout.
pub const ProcessInfo = struct {
    /// Process ID.
    pid: u32,
    /// Parent process ID (0 if no parent).
    parent_pid: u32,
    /// Process state (0=free, 1=running, 2=exited).
    state: u8,
    /// Total CPU time used (nanoseconds).
    cpu_time_ns: u64,
    /// Memory used (bytes).
    memory_used: u64,
    
    /// Initialize ProcessInfo with default values.
    /// Why: Explicit initialization, prevent uninitialized fields.
    pub fn init() ProcessInfo {
        return ProcessInfo{
            .pid = 0,
            .parent_pid = 0,
            .state = 0,
            .cpu_time_ns = 0,
            .memory_used = 0,
        };
    }
};

/// User ID (32-bit, explicit type per GrainStyle).
/// Why: Explicit type instead of usize for portability.
pub const UserId = u32;

/// Group ID (32-bit, explicit type per GrainStyle).
/// Why: Explicit type instead of usize for portability.
pub const GroupId = u32;

/// User Record
/// Why: Track user identity, permissions, home directory
/// Grain Style: Explicit types (u32 not usize), static allocation
pub const User = struct {
    /// User ID (0 = root)
    uid: UserId,
    /// Group ID (primary group)
    gid: GroupId,
    /// Username (max 32 chars, static allocation)
    name: [32]u8,
    /// Home directory path (max 256 chars)
    home: [256]u8,
    /// Capabilities bitmap (future: fine-grained permissions)
    capabilities: u64,
    
    /// Initialize empty user entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() User {
        return User{
            .uid = 0,
            .gid = 0,
            .name = [_]u8{0} ** 32,
            .home = [_]u8{0} ** 256,
            .capabilities = 0,
        };
    }
    
    /// Validate user record.
    /// Why: Ensure user data is valid.
    pub fn validate(self: *const User) void {
        Debug.kassert(self.uid < 65536, "UID too large: {d}",
.{self.uid});
        Debug.kassert(self.gid < 65536, "GID too large: {d}",
.{self.gid});
        // Name can be empty for uninitialized entries
    }
};

/// Current User Context
/// Why: Track current user for permission checks
/// Single-threaded: No locks needed, deterministic
pub const UserContext = struct {
    /// Current user ID
    uid: UserId,
    /// Current group ID
    gid: GroupId,
    /// Effective user ID (for setuid)
    euid: UserId,
    /// Effective group ID (for setgid)
    egid: GroupId,
    
    /// Initialize user context.
    /// Why: Explicit initialization, clear state.
    pub fn init(uid: UserId, gid: GroupId) UserContext {
        return UserContext{
            .uid = uid,
            .gid = gid,
            .euid = uid,
            .egid = gid,
        };
    }
    
    /// Check if current user is root.
    /// Why: Explicit root check for permission validation.
    pub fn is_root(self: *const UserContext) bool {
        return self.euid == 0;
    }
    
    /// Check if user has capability.
    /// Why: Explicit capability check for permission validation.
    pub fn has_capability(self: *const UserContext, cap: u64) bool {
        _ = cap; // Future: Use capability bitmap
        if (self.is_root()) return true;
        // Future: Check capability bitmap from user record
        return false;
    }
};

/// Basin Kernel error types.
/// Why: Explicit error types instead of POSIX errno.
pub const BasinError = error{
    invalid_handle,
    invalid_argument,
    permission_denied,
    not_found,
    out_of_memory,
    resource_exhausted,
    would_block,
    interrupted,
    invalid_syscall,
    invalid_address,
    unaligned_access,
    out_of_bounds,
    user_not_found,
    invalid_user,
};

/// Syscall result wrapper.
/// Why: Explicit result type, prevent confusion with raw return values.
pub const SyscallResult = union(enum) {
    success: u64,
    err: BasinError,
    
    /// Create success result.
    /// Why: Explicit construction, type safety.
    pub fn ok(value: u64) SyscallResult {
        return SyscallResult{ .success = value };
    }
    
    /// Create error result.
    /// Why: Explicit construction, type safety.
    pub fn fail(err: BasinError) SyscallResult {
        return SyscallResult{ .err = err };
    }
};

/// Memory mapping entry.
/// Why: Track memory mappings for map/unmap/protect syscalls.
/// Grain Style: Static allocation, explicit state tracking.
const MemoryMapping = struct {
    /// Mapping address (page-aligned).
    address: u64,
    /// Mapping size (page-aligned, bytes).
    size: u64,
    /// Mapping flags (permissions).
    flags: MapFlags,
    /// Whether this entry is allocated (in use).
    allocated: bool,
    /// Owner process ID (0 = kernel-owned, non-zero = process-owned).
    /// Why: Track which process owns this mapping for resource cleanup.
    owner_process_id: u32,
    
    /// Initialize empty mapping entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() MemoryMapping {
        return MemoryMapping{
            .address = 0,
            .size = 0,
            .flags = MapFlags.init(.{}),
            .allocated = false,
            .owner_process_id = 0,
        };
    }
    
    /// Check if mapping overlaps with address range.
    /// Why: Validate no overlapping mappings.
    pub fn overlaps(self: MemoryMapping, addr: u64, size: u64) bool {
        if (!self.allocated) {
            return false;
        }
        // Check if ranges overlap: (self.address < addr + size) &&
(addr < self.address + self.size)
        return (self.address < addr + size) and (addr < self.address +
self.size);
    }
};

/// Memory mapping table.
/// Why: Track all memory mappings for kernel memory management.
/// Grain Style: Static allocation, max 256 entries (sufficient for 4MB
VM).
const MAX_MAPPINGS: u32 = 256;

/// File handle entry.
/// Why: Track file handles for open/read/write/close syscalls.
/// Grain Style: Static allocation, explicit state tracking.
const FileHandle = struct {
    /// Handle ID (non-zero if allocated).
    id: u64,
    /// File path (null-terminated, max 256 bytes).
    path: [256]u8,
    /// Path length (bytes, excluding null terminator).
    path_len: u32,
    /// Open flags (permissions).
    flags: OpenFlags,
    /// Current read/write position (bytes from start).
    position: u64,
    /// File buffer (in-memory file data, max 64KB).
    buffer: [64 * 1024]u8,
    /// Buffer size (actual data length, bytes).
    buffer_size: u32,
    /// Whether this entry is allocated (in use).
    allocated: bool,
    /// Owner process ID (0 = kernel-owned, non-zero = process-owned).
    /// Why: Track which process owns this handle for resource cleanup.
    owner_process_id: u32,
    
    /// Initialize empty file handle entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() FileHandle {
        return FileHandle{
            .id = 0,
            .path = [_]u8{0} ** 256,
            .path_len = 0,
            .flags = OpenFlags.init(.{}),
            .position = 0,
            .buffer = [_]u8{0} ** (64 * 1024),
            .buffer_size = 0,
            .allocated = false,
            .owner_process_id = 0,
        };
    }
};

/// Directory handle entry.
/// Why: Track directory handles for opendir/readdir/closedir syscalls.
/// Grain Style: Static allocation, explicit state tracking.
const DirectoryHandle = struct {
    /// Handle ID (non-zero if allocated).
    id: u64,
    /// Directory path (null-terminated, max 256 bytes).
    path: [256]u8,
    /// Path length (bytes, excluding null terminator).
    path_len: u32,
    /// Current read position (entry index, 0-based).
    position: u32,
    /// Whether this entry is allocated (in use).
    allocated: bool,
    
    /// Initialize empty directory handle entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() DirectoryHandle {
        return DirectoryHandle{
            .id = 0,
            .path = [_]u8{0} ** 256,
            .path_len = 0,
            .position = 0,
            .allocated = false,
        };
    }
};

/// File handle table.
/// Why: Track all file handles for kernel file system management.
/// Grain Style: Static allocation, max 64 entries.
const MAX_HANDLES: u32 = 64;

/// Directory handle table.
/// Why: Track all directory handles for kernel directory operations.
/// Grain Style: Static allocation, max 32 entries.
const MAX_DIR_HANDLES: u32 = 32;

/// Process state enumeration.
/// Why: Explicit process states for type safety.
pub const ProcessState = enum(u8) {
    /// Process is running (active).
    running,
    /// Process has exited (terminated).
    exited,
    /// Process slot is free (not allocated).
    free,
};

/// Process entry.
/// Why: Track process information for spawn/wait/exit syscalls.
/// Grain Style: Static allocation, explicit state tracking.
pub const Process = struct {
    /// Process ID (non-zero if allocated).
    id: u64,
    /// Process state (running, exited, free).
    state: ProcessState,
    /// Exit status (valid only when state == exited).
    exit_status: u32,
    /// Executable pointer (ELF data pointer in VM memory).
    /// Why: Track where ELF executable is located in VM memory.
    executable_ptr: u64,
    /// Executable length (bytes).
    /// Why: Track ELF executable size for validation.
    executable_len: u64,
    /// Entry point (program counter at start).
    /// Why: Track where process execution starts (ELF entry point).
    entry_point: u64,
    /// Stack pointer (initial SP value).
    /// Why: Track initial stack pointer for process.
    stack_pointer: u64,
    /// Process execution context (optional, for enhanced process
management).
    /// Why: Track process execution state (PC, SP, registers).
    context: ?ProcessContext = null,
    /// Signal table for process.
    /// Why: Handle signals (SIGTERM, SIGKILL, etc.) for process.
    signals: SignalTable,
    /// Total CPU time used (nanoseconds).
    /// Why: Track CPU usage for resource monitoring.
    cpu_time_ns: u64,
    /// Memory used (bytes).
    /// Why: Track memory usage for resource monitoring.
    memory_used: u64,
    /// Parent process ID (0 if no parent).
    /// Why: Track parent-child relationships.
    parent_pid: u64,
    /// Process priority (nice value, -20 to 19, default 0).
    /// Why: Track process priority for scheduling decisions.
    /// Note: Lower nice value = higher priority (POSIX-style).
    priority: i8,
    /// Time slice quantum (instruction steps per time slice, default
1000).
    /// Why: Track time slice allocation for fair scheduling.
    time_slice_quantum: u64,
    /// Process group ID (0 if no group).
    /// Why: Track process group membership for group-based operations.
    pgid: u64,
    /// Session ID (0 if no session).
    /// Why: Track session membership for session-based operations.
    sid: u64,
    /// Whether this entry is allocated (in use).
    allocated: bool,
    
    /// Initialize empty process entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() Process {
        return Process{
            .id = 0,
            .state = .free,
            .exit_status = 0,
            .executable_ptr = 0,
            .executable_len = 0,
            .entry_point = 0,
            .stack_pointer = 0,
            .context = null,
            .signals = SignalTable.init(),
            .cpu_time_ns = 0,
            .memory_used = 0,
            .parent_pid = 0,
            .priority = 0, // Default priority (nice value 0)
            .time_slice_quantum = 1000, // Default time slice (1000
instruction steps)
            .pgid = 0, // No process group by default
            .sid = 0, // No session by default
            .allocated = false,
        };
    }
};

/// Process table.
/// Why: Track all processes for kernel process management.
/// Grain Style: Static allocation, max 16 entries.
const MAX_PROCESSES: u32 = 16;

// Compile-time assertions for handle table size.
comptime {
    std.debug.assert(MAX_HANDLES > 0);
    std.debug.assert(MAX_HANDLES <= 0xFFFFFFFF);
    std.debug.assert(MAX_HANDLES < 0xFFFFFFFF);
}

/// Basin Kernel syscall interface (stub for future implementation).
/// Why: Define interface early, implement incrementally.
/// User table (static allocation).
/// Why: Fixed-size user table, no dynamic allocation
/// Grain Style: Static array, max 256 users
const MAX_USERS: u32 = 256;

pub const BasinKernel = struct {
    /// Memory mapping table (static allocation).
    /// Why: Track memory mappings for map/unmap/protect syscalls.
    /// Grain Style: Static allocation, max 256 entries.
    mappings: [MAX_MAPPINGS]MemoryMapping =
[_]MemoryMapping{MemoryMapping.init()} ** MAX_MAPPINGS,
    
    /// Next address for kernel-chosen allocations (simple allocator).
    /// Why: Track allocation position for kernel-chosen addresses.
    next_alloc_addr: u64 = 0x100000, // Start after kernel space (1MB)
    
    /// File handle table (static allocation).
    /// Why: Track file handles for open/read/write/close syscalls.
    /// Grain Style: Static allocation, max 64 entries.
    handles: [MAX_HANDLES]FileHandle = [_]FileHandle{FileHandle.init()}
** MAX_HANDLES,
    
    /// Next handle ID (simple allocator, starts at 1).
    /// Why: Track handle ID allocation (1-based, 0 is invalid).
    next_handle_id: u64 = 1,
    
    /// Directory handle table (static allocation).
    /// Why: Track directory handles for opendir/readdir/closedir
syscalls.
    /// Grain Style: Static allocation, max 32 entries.
    dir_handles: [MAX_DIR_HANDLES]DirectoryHandle =
[_]DirectoryHandle{DirectoryHandle.init()} ** MAX_DIR_HANDLES,
    
    /// Next directory handle ID (simple allocator, starts at 1).
    /// Why: Track directory handle ID allocation (1-based, 0 is
invalid).
    next_dir_handle_id: u64 = 1,
    
    /// Process table (static allocation).
    /// Why: Track processes for spawn/wait/exit syscalls.
    /// Grain Style: Static allocation, max 16 entries.
    processes: [MAX_PROCESSES]Process = [_]Process{Process.init()} **
MAX_PROCESSES,
    
    /// Next process ID (simple allocator, starts at 1).
    /// Why: Track process ID allocation (1-based, 0 is invalid).
    next_process_id: u64 = 1,
    
    /// User table (static allocation).
    /// Why: Track users for permission checks and user management.
    /// Grain Style: Static allocation, max 256 users.
    users: [MAX_USERS]User = [_]User{User.init()} ** MAX_USERS,
    
    /// User count (number of initialized users).
    /// Why: Track how many users are initialized.
    user_count: u32 = 0,
    
    /// Current user context.
    /// Why: Track current user for permission checks.
    /// Single-threaded: No locks needed, deterministic.
    current_user: UserContext = UserContext{
        .uid = 0,
        .gid = 0,
        .euid = 0,
        .egid = 0,
    },
    
    /// Timer driver.
    /// Why: Provide monotonic clock and time-based syscalls.
    /// Grain Style: Static allocation, initialized at kernel boot.
    timer: Timer,
    
    /// Interrupt controller.
    /// Why: Handle interrupts (timer, external, software).
    /// Grain Style: Static allocation, initialized at kernel boot.
    interrupt_controller: InterruptController,
    
    /// Process scheduler.
    /// Why: Manage process execution and scheduling.
    /// Grain Style: Static allocation, initialized at kernel boot.
    scheduler: Scheduler,
    
    /// Process group manager.
    /// Why: Manage process groups and sessions.
    /// Grain Style: Static allocation, initialized at kernel boot.
    process_group_manager: ProcessGroupManager,
    
    /// Process group statistics manager.
    /// Why: Track statistics for process groups.
    /// Grain Style: Static allocation, initialized at kernel boot.
    process_group_stats: ProcessGroupStatsManager,
    
    /// Process group limits manager.
    /// Why: Enforce resource limits for process groups.
    /// Grain Style: Static allocation, initialized at kernel boot.
    process_group_limits: ProcessGroupLimitsManager,
    
    /// Network interface manager.
    /// Why: Manage network interfaces for TCP/UDP syscalls.
    /// Grain Style: Static allocation, initialized at kernel boot.
    network_interfaces: NetworkInterfaceManager,
    
    /// TCP socket manager.
    /// Why: Manage TCP sockets for network communication.
    /// Grain Style: Static allocation, initialized at kernel boot.
    tcp_sockets: TcpSocketManager,
    
    /// UDP socket manager.
    /// Why: Manage UDP sockets for network communication.
    /// Grain Style: Static allocation, initialized at kernel boot.
    udp_sockets: UdpSocketManager,
    
    /// IPC channel table.
    /// Why: Manage inter-process communication channels.
    /// Grain Style: Static allocation, initialized at kernel boot.
    channels: ChannelTable,
    
    /// Storage filesystem.
    /// Why: Manage files and directories for file I/O syscalls.
    /// Grain Style: Static allocation, initialized at kernel boot.
    storage: Storage,
    
    /// Keyboard driver.
    /// Why: Track keyboard state and key presses.
    /// Grain Style: Static allocation, initialized at kernel boot.
    keyboard: Keyboard,
    
    /// Mouse driver.
    /// Why: Track mouse state (position, buttons).
    /// Grain Style: Static allocation, initialized at kernel boot.
    mouse: Mouse,
    
    /// Kernel log buffer.
    /// Why: Store kernel log entries for userspace access.
    /// Grain Style: Static allocation, initialized at kernel boot.
    log_buffer: KernelLogBuffer,
    
    /// Memory pool for kernel allocations.
    /// Why: Provide kernel-side memory allocation.
    /// Grain Style: Static allocation, initialized at kernel boot.
    memory_pool: MemoryPool,
    
    /// Page table for memory protection.
    /// Why: Track page-level memory permissions and mappings.
    /// Grain Style: Static allocation, initialized at kernel boot.
    page_table: PageTable,
    
    /// Page fault statistics.
    /// Why: Track page fault types and frequencies for diagnostics.
    /// Grain Style: Static allocation, initialized at kernel boot.
    page_fault_stats: PageFaultStats,
    
    /// Memory usage statistics.
    /// Why: Track memory usage, mapped pages, and allocation patterns.
    /// Grain Style: Static allocation, initialized at kernel boot.
    memory_stats: MemoryStats,
    
    /// Copy-on-Write (COW) table.
    /// Why: Track reference counts and COW marking for shared memory
pages.
    /// Grain Style: Static allocation, initialized at kernel boot.
    cow_table: CowTable,
    
    /// VM memory read callback (optional).
    /// Why: Allow kernel to read VM memory for ELF parsing and process
setup.
    /// Note: Type-erased to avoid requiring VM import at module level.
    /// Contract: Must be set by integration layer before use.
    vm_memory_reader: ?*const fn (addr: u64, len: u32, buffer: []u8)
?u32 = null,
    
    /// User data for VM memory reader (optional).
    /// Why: Pass context to memory reader (e.g., VM instance).
    vm_memory_reader_user_data: ?*anyopaque = null,
    
    /// VM memory write callback (optional).
    /// Why: Allow kernel to write VM memory for segment data loading.
    /// Note: Type-erased to avoid requiring VM import at module level.
    /// Contract: Must be set by integration layer before use.
    /// Returns: Number of bytes written, or null if write fails.
    vm_memory_writer: ?*const fn (addr: u64, len: u32, data: []const u8)
?u32 = null,
    
    /// User data for VM memory writer (optional).
    /// Why: Pass context to memory writer (e.g., VM instance).
    vm_memory_writer_user_data: ?*anyopaque = null,
    
    /// Initialize Basin Kernel.
    /// Why: Explicit initialization, validate kernel state.
    pub fn init() BasinKernel {
        var kernel = BasinKernel{
            .timer = Timer.init(),
            .interrupt_controller = InterruptController.init(),
            .scheduler = Scheduler.init(),
            .process_group_manager = ProcessGroupManager.init(),
            .process_group_stats = ProcessGroupStatsManager.init(),
            .process_group_limits = ProcessGroupLimitsManager.init(),
            .network_interfaces = NetworkInterfaceManager.init(),
            .tcp_sockets = TcpSocketManager.init(),
            .udp_sockets = UdpSocketManager.init(),
            .audio_devices = AudioDeviceManager.init(),
            .channels = ChannelTable.init(),
            .storage = Storage.init(),
            .keyboard = Keyboard.init(),
            .mouse = Mouse.init(),
            .log_buffer = undefined, // Will initialize below with timer
reference
            .memory_pool = MemoryPool.init(),
            .page_table = PageTable.init(),
            .page_fault_stats = PageFaultStats.init(),
            .memory_stats = MemoryStats.init(),
            .cow_table = CowTable.init(),
        };
        
        // Initialize log buffer with timer reference (after timer is
created).
        kernel.log_buffer = KernelLogBuffer.init(&kernel.timer);
        
        // Initialize default users (root and xy).
        kernel.init_users();
        
        // Assert: All mappings must be unallocated initially.
        for (kernel.mappings, 0..) |mapping, i| {
            Debug.kassert(!mapping.allocated, "Mapping {d} should be
unallocated", .{i});
        }
        
        // Assert: Next allocation address must be page-aligned.
        Debug.kassert(kernel.next_alloc_addr % 4096 == 0, "Next alloc
addr {x} not aligned", .{kernel.next_alloc_addr});
        
        // Assert: All handles must be unallocated initially.
        for (kernel.handles, 0..) |handle, i| {
            Debug.kassert(!handle.allocated, "Handle {d} should be
unallocated", .{i});
            Debug.kassert(handle.id == 0, "Handle {d} ID should be 0",
.{i});
        }
        
        // Assert: Next handle ID must be non-zero (1-based).
        Debug.kassert(kernel.next_handle_id != 0, "Next handle ID is 0",
.{});
        
        // Assert: Root user must exist.
        Debug.kassert(kernel.user_count >= 1, "User count {d} < 1",
.{kernel.user_count});
        Debug.kassert(kernel.users[0].uid == 0, "First user UID {d} !=
0", .{kernel.users[0].uid});
        
        // Assert: Timer must be initialized.
        Debug.kassert(kernel.timer.initialized, "Timer not initialized",
.{});
        Debug.kassert(kernel.timer.boot_time_ns > 0, "Boot time is
zero", .{});
        
        // Assert: Interrupt controller must be initialized.
        Debug.kassert(kernel.interrupt_controller.initialized,
"Interrupt controller not initialized", .{});
        
        // Assert: Scheduler must be initialized.
        Debug.kassert(kernel.scheduler.initialized, "Scheduler not
initialized", .{});
        Debug.kassert(kernel.scheduler.current_pid == 0, "Current PID
not 0 at init", .{});
        
        return kernel;
    }
    
    /// Initialize default users.
    /// Why: Create root and xy users at kernel boot.
    /// Grain Style: Static allocation, explicit initialization.
    fn init_users(self: *BasinKernel) void {
        // Root user (uid=0)
        var root = User.init();
        root.uid = 0;
        root.gid = 0;
        @memcpy(root.name[0..4], "root");
        @memcpy(root.home[0..5], "/root");
        root.capabilities = 0xFFFFFFFFFFFFFFFF; // All capabilities
        root.validate();
        self.users[0] = root;
        
        // xy user (uid=1000)
        var xy = User.init();
        xy.uid = 1000;
        xy.gid = 1000;
        @memcpy(xy.name[0..2], "xy");
        @memcpy(xy.home[0..8], "/home/xy");
        xy.capabilities = 0x0000000000000001; // Basic user capabilities
        xy.validate();
        self.users[1] = xy;
        
        self.user_count = 2;
        
        // Assert: Root user must exist.
        Debug.kassert(self.users[0].uid == 0, "Root UID check failed",
.{});
        Debug.kassert(self.users[1].uid == 1000, "XY UID check failed",
.{});
        Debug.kassert(self.user_count == 2, "User count check failed",
.{});
    }
    
    /// Find user by UID.
    /// Why: Look up user record for permission checks.
    /// Returns: User index if found, null otherwise.
    pub fn find_user_by_uid(self: *const BasinKernel, uid: UserId) ?u32 {
        for (0..self.user_count) |i| {
            if (self.users[i].uid == uid) {
                return @as(u32, @intCast(i));
            }
        }
        return null;
    }
    
    /// Calculate memory usage for a process by summing its memory
mappings.
    /// Why: Track total memory used by a process for resource
monitoring.
    /// Contract: process_id must be valid (non-zero).
    /// Returns: Total memory used in bytes (sum of all mapping sizes).
    /// Grain Style: Explicit types, bounded operations, deterministic
calculation.
    fn calculate_process_memory_usage(self: *const BasinKernel,
process_id: u64) u64 {
        // Assert: process ID must be valid (non-zero).
        Debug.kassert(process_id != 0, "Process ID is 0", .{});
        
        const process_id_u32 = @as(u32, @truncate(process_id));
        var total_memory: u64 = 0;
        
        // Sum memory from all mappings owned by this process.
        // Why: Calculate total memory used by summing mapping sizes.
        for (0..MAX_MAPPINGS) |i| {
            const mapping = &self.mappings[i];
            if (mapping.allocated and mapping.owner_process_id ==
process_id_u32) {
                total_memory +%= mapping.size; // Saturating add to
prevent overflow
            }
        }
        
        // Assert: Total memory must be reasonable (bounded by VM memory
size).
        const VM_MEMORY_SIZE: u64 = 4 * 1024 * 1024; // 4MB default
        Debug.kassert(total_memory <= VM_MEMORY_SIZE, "Process memory >
VM size", .{});
        
        return total_memory;
    }
    
    /// Update memory usage for a process.
    /// Why: Keep process memory_used field current when mappings change.
    /// Contract: process_id must be valid (non-zero).
    /// Grain Style: Explicit types, bounded operations.
    fn update_process_memory_usage(self: *BasinKernel, process_id: u64)
void {
        // Assert: process ID must be valid (non-zero).
        Debug.kassert(process_id != 0, "Process ID is 0", .{});
        
        // Find process in process table.
        for (0..MAX_PROCESSES) |i| {
            if (self.processes[i].allocated and self.processes[i].id ==
process_id) {
                // Calculate and update memory usage.
                const memory_used =
self.calculate_process_memory_usage(process_id);
                self.processes[i].memory_used = memory_used;
                return;
            }
        }
    }
    
    /// Find user by name.
    /// Why: Look up user record by username.
    /// Returns: User index if found, null otherwise.
    pub fn find_user_by_name(self: *const BasinKernel, name: []const u8)
?u32 {
        for (0..self.user_count) |i| {
            const user_name_array = self.users[i].name;
            // Find null terminator to get actual string length
            var user_name_len: u32 = 0;
            for (user_name_array, 0..) |byte, idx| {
                if (byte == 0) {
                    user_name_len = @as(u32, @intCast(idx));
                    break;
                }
            }
            if (user_name_len == 0) continue; // Skip uninitialized
entries
            const user_name = user_name_array[0..user_name_len];
            if (std.mem.eql(u8, user_name, name)) {
                return @as(u32, @intCast(i));
            }
        }
        return null;
    }
    
    /// Set current user context.
    /// Why: Change current user for permission checks.
    /// Contract: uid must exist in user table.
    pub fn set_current_user(self: *BasinKernel, uid: UserId) !void {
        const user_idx = self.find_user_by_uid(uid) orelse {
            return BasinError.user_not_found;
        };
        
        const user = self.users[user_idx];
        self.current_user = UserContext.init(user.uid, user.gid);
        
        // Assert: Current user must be set correctly.
        Debug.kassert(self.current_user.uid == uid, "Set current user
failed", .{});
    }
    
    /// Find free mapping entry.
    /// Why: Allocate new mapping entry.
    /// Returns: Index of free entry, or null if table full.
    /// Grain Style: Comprehensive assertions for table state.
    fn find_free_mapping(self: *BasinKernel) ?u32 {
        // Assert: self pointer must be valid.
        const self_ptr = @intFromPtr(self);
        Debug.kassert(self_ptr != 0, "Self ptr is null", .{});
        Debug.kassert(self_ptr % @alignOf(BasinKernel) == 0, "Self ptr
unaligned", .{});
        
        var found_index: ?u32 = null;
        var free_count: u32 = 0;
        
        for (self.mappings, 0..) |mapping, i| {
            if (!mapping.allocated) {
                free_count += 1;
                if (found_index == null) {
                    found_index = @as(u32, @intCast(i));
                }
                
                // Note: For fuzz testing robustness, we don't assert
unallocated mapping state here
                // to avoid crashes if there's a bug. The actual
validation happens at allocation/deallocation time.
            } else {
                // Note: For fuzz testing robustness, we don't assert
allocated mapping state here
                // to avoid crashes if there's a bug. The actual
validation happens at allocation time.
                // We just find free entries without validating their
state.
            }
        }
        
        // Assert: Free count must be <= MAX_MAPPINGS.
        Debug.kassert(free_count <= MAX_MAPPINGS, "Free count > MAX",
.{});
        
        return found_index;
    }
    
    /// Find mapping by address.
    /// Why: Look up mapping for unmap/protect operations.
    /// Returns: Index of mapping, or null if not found.
    /// Grain Style: Comprehensive assertions for address validation.
    fn find_mapping_by_address(self: *BasinKernel, addr: u64) ?u32 {
        // Assert: self pointer must be valid.
        const self_ptr = @intFromPtr(self);
        Debug.kassert(self_ptr != 0, "Self ptr is null", .{});
        Debug.kassert(self_ptr % @alignOf(BasinKernel) == 0, "Self ptr
unaligned", .{});
        
        // Assert: Address must be page-aligned.
        Debug.kassert(addr % 4096 == 0, "Address {x} not aligned",
.{addr});
        
        var found_index: ?u32 = null;
        var match_count: u32 = 0;
        
        for (self.mappings, 0..) |mapping, i| {
            if (mapping.allocated and mapping.address == addr) {
                match_count += 1;
                if (found_index == null) {
                    found_index = @as(u32, @intCast(i));
                }
                
                // Assert: Matching mapping must have valid state.
                Debug.kassert(mapping.address == addr, "Mapping addr
mismatch", .{});
                Debug.kassert(mapping.size >= 4096, "Mapping size too
small", .{});
                Debug.kassert(mapping.size % 4096 == 0, "Mapping size
unaligned", .{});
            }
        }
        
        // Assert: Address must be unique (no duplicate mappings).
        Debug.kassert(match_count <= 1, "Duplicate mappings found", .{});
        
        return found_index;
    }
    
    /// Check memory permissions for an address.
    /// Why: Enforce memory protection by checking read/write/execute
permissions.
    /// Contract: Address must be valid, returns permissions if mapped,
null if not mapped.
    /// Returns: MapFlags with permissions, or null if address is not
mapped.
    /// Note: Kernel space (0x80000000+) and framebuffer (0x90000000+)
are always readable/writable.
    /// Uses page table for page-level granularity.
    pub fn check_memory_permission(self: *const BasinKernel, addr: u64)
?MapFlags {
        // Assert: self pointer must be valid (precondition).
        const self_ptr = @intFromPtr(self);
        Debug.kassert(self_ptr != 0, "Self ptr is null", .{});
        Debug.kassert(self_ptr % @alignOf(BasinKernel) == 0, "Self ptr
unaligned", .{});
        
        // Use page table for page-level permission checking.
        const page_flags = self.page_table.check_permission(addr) orelse
{
            return null;
        };
        
        // Convert PageFlags to MapFlags (same structure).
        return MapFlags{
            .read = page_flags.read,
            .write = page_flags.write,
            .execute = page_flags.execute,
            .shared = page_flags.shared,
            ._padding = 0,
        };
    }
    
    /// Check if address range overlaps with any existing mapping.
    /// Why: Validate no overlapping mappings.
    /// Grain Style: Comprehensive assertions for overlap detection.
    fn check_overlap(self: *BasinKernel, addr: u64, size: u64) bool {
        // Assert: self pointer must be valid.
        const self_ptr = @intFromPtr(self);
        Debug.kassert(self_ptr != 0, "Self ptr is null", .{});
        Debug.kassert(self_ptr % @alignOf(BasinKernel) == 0, "Self ptr
unaligned", .{});
        
        // Assert: Address and size must be valid.
        Debug.kassert(addr % 4096 == 0, "Addr {x} unaligned", .{addr});
// Page-aligned
        Debug.kassert(size >= 4096, "Size {d} too small", .{size}); //
At least 1 page
        Debug.kassert(size % 4096 == 0, "Size {d} unaligned", .{size});
// Page-aligned
        
        var overlap_count: u32 = 0;
        
        for (self.mappings) |mapping| {
            if (mapping.overlaps(addr, size)) {
                overlap_count += 1;
                
                // Assert: Overlapping mapping must be allocated.
                Debug.kassert(mapping.allocated, "Overlapping mapping
not allocated", .{});
                
                // Assert: Overlap condition must be true.
                const does_overlap = (mapping.address < addr + size) and
(addr < mapping.address + mapping.size);
                Debug.kassert(does_overlap, "Overlap logic error", .{});
            }
        }
        
        // Assert: Overlap count must be consistent (0 or 1, no
duplicates).
        Debug.kassert(overlap_count <= 1, "Multiple overlaps found",
.{});
        
        return overlap_count > 0;
    }
    
    /// Count allocated mappings (for testing and validation).
    /// Why: Validate mapping table state consistency.
    /// Grain Style: Comprehensive assertions for state validation.
    pub fn count_allocated_mappings(self: *BasinKernel) u32 {
        // Assert: self pointer must be valid.
        const self_ptr = @intFromPtr(self);
        Debug.kassert(self_ptr != 0, "Self ptr is null", .{});
        Debug.kassert(self_ptr % @alignOf(BasinKernel) == 0, "Self ptr
unaligned", .{});
        
        var count: u32 = 0;
        
        for (self.mappings) |mapping| {
            if (mapping.allocated) {
                // Note: For fuzz testing robustness, we don't assert
mapping state here
                // to avoid crashes if there's a bug. The actual
validation happens at allocation time.
                // We just count allocated mappings without validating
their state.
                count += 1;
            }
        }
        
        // Note: For fuzz testing robustness, we don't assert count <=
MAX_MAPPINGS here.
        // The test will validate the count.
        
        return count;
    }
    
    /// Find free handle entry.
    /// Why: Allocate new handle entry.
    /// Returns: Index of free entry, or null if table full.
    /// Grain Style: Comprehensive assertions for table state.
    fn find_free_handle(self: *BasinKernel) ?u32 {
        // Assert: self pointer must be valid.
        const self_ptr = @intFromPtr(self);
        Debug.kassert(self_ptr != 0, "Self ptr is null", .{});
        Debug.kassert(self_ptr % @alignOf(BasinKernel) == 0, "Self ptr
unaligned", .{});
        
        for (self.handles, 0..) |handle, i| {
            if (!handle.allocated) {
                // Note: For fuzz testing robustness, we don't assert
unallocated handle state here
                // to avoid crashes if there's a bug. The actual
validation happens at allocation/deallocation time.
                return @as(u32, @intCast(i));
            }
        }
        return null;
    }
    
    /// Find handle by ID.
    /// Why: Look up handle for read/write/close operations.
    /// Returns: Index of handle, or null if not found.
    /// Grain Style: Comprehensive assertions for handle validation.
    fn find_handle_by_id(self: *BasinKernel, handle_id: u64) ?u32 {
        // Assert: self pointer must be valid.
        const self_ptr = @intFromPtr(self);
        Debug.kassert(self_ptr != 0, "Self ptr is null", .{});
        Debug.kassert(self_ptr % @alignOf(BasinKernel) == 0, "Self ptr
unaligned", .{});
        
        // Assert: Handle ID must be non-zero (0 is invalid).
        Debug.kassert(handle_id != 0, "Handle ID is 0", .{});
        
        for (self.handles, 0..) |handle, i| {
            if (handle.allocated and handle.id == handle_id) {
                // Assert: Handle must be allocated and match ID.
                Debug.kassert(handle.allocated, "Handle not allocated",
.{});
                Debug.kassert(handle.id == handle_id, "Handle ID
mismatch", .{});
                return @as(u32, @intCast(i));
            }
        }
        return null;
    }
    
    /// Count allocated handles (for testing and validation).
    /// Why: Validate handle table state consistency.
    /// Grain Style: Comprehensive assertions for state validation.
    pub fn count_allocated_handles(self: *BasinKernel) u32 {
        // Assert: self pointer must be valid.
        const self_ptr = @intFromPtr(self);
        Debug.kassert(self_ptr != 0, "Self ptr is null", .{});
        Debug.kassert(self_ptr % @alignOf(BasinKernel) == 0, "Self ptr
unaligned", .{});
        
        var count: u32 = 0;
        
        for (self.handles) |handle| {
            if (handle.allocated) {
                // Note: For fuzz testing robustness, we don't assert
handle state here
                // to avoid crashes if there's a bug. The actual
validation happens at allocation time.
                // We just count allocated handles without validating
their state.
                count += 1;
            }
        }
        
        // Note: For fuzz testing robustness, we don't assert count <=
MAX_HANDLES here.
        // The test will validate the count.
        
        return count;
    }
    
    /// Handle syscall from user space.
    /// Why: Central syscall entry point, validate syscall number and
arguments.
    /// Grain Style: Comprehensive assertions for all syscall parameters
and state.
    pub fn handle_syscall(
        self: *BasinKernel,
        syscall_num: u32,
        arg1: u64,
        arg2: u64,
        arg3: u64,
        arg4: u64,
    ) BasinError!SyscallResult {
        // Assert: self pointer must be valid.
        const self_ptr = @intFromPtr(self);
        Debug.kassert(self_ptr != 0, "Self ptr is null", .{});
        Debug.kassert(self_ptr % @alignOf(BasinKernel) == 0, "Self ptr
unaligned", .{});
        
        // Assert: syscall number must be >= 10 (kernel syscalls, not
SBI).
        // Why: SBI calls use function ID < 10, kernel syscalls use >=
10.
        Debug.kassert(syscall_num >= 10, "Syscall num {d} < 10",
.{syscall_num});
        
        // Assert: syscall number must be within valid range.
        Debug.kassert(syscall_num <= @intFromEnum(Syscall.getsid),
"Syscall num {d} too high", .{syscall_num});
        
        // Decode syscall number.
        const syscall = @as(?Syscall, @enumFromInt(syscall_num)) orelse {
            // Assert: Invalid syscall number must return error.
            Debug.kassert(syscall_num < 10 or syscall_num >
@intFromEnum(Syscall.getsid), "Invalid syscall logic", .{});
            return BasinError.invalid_syscall;
        };
        
        // Assert: syscall must be valid enum value.
        Debug.kassert(@intFromEnum(syscall) == syscall_num, "Syscall
enum mismatch", .{});
        
        // Assert: syscall must be kernel syscall (not SBI).
        Debug.kassert(@intFromEnum(syscall) >= 10, "Syscall enum < 10",
.{});
        
        // Route to appropriate syscall handler.
        // Why: Explicit routing, type-safe syscall handling.
        return switch (syscall) {
            .spawn => self.syscall_spawn(arg1, arg2, arg3, arg4),
            .exit => self.syscall_exit(arg1, arg2, arg3, arg4),
            .yield => self.syscall_yield(arg1, arg2, arg3, arg4),
            .wait => self.syscall_wait(arg1, arg2, arg3, arg4),
            .map => self.syscall_map(arg1, arg2, arg3, arg4),
            .unmap => self.syscall_unmap(arg1, arg2, arg3, arg4),
            .protect => self.syscall_protect(arg1, arg2, arg3, arg4),
            .channel_create => self.syscall_channel_create(arg1, arg2,
arg3, arg4),
            .channel_send => self.syscall_channel_send(arg1, arg2, arg3,
arg4),
            .channel_recv => self.syscall_channel_recv(arg1, arg2, arg3,
arg4),
            .open => self.syscall_open(arg1, arg2, arg3, arg4),
            .read => self.syscall_read(arg1, arg2, arg3, arg4),
            .write => self.syscall_write(arg1, arg2, arg3, arg4),
            .close => self.syscall_close(arg1, arg2, arg3, arg4),
            .unlink => self.syscall_unlink(arg1, arg2, arg3, arg4),
            .rename => self.syscall_rename(arg1, arg2, arg3, arg4),
