//! Kernel Boot Sequence
//! Why: Ensure all kernel subsystems initialize in correct order with
validation.
//! Grain Style: Explicit types (u32/u64 not usize), comprehensive
assertions, static allocation.

const std = @import("std");
const Debug = @import("debug.zig");
const BasinKernel = @import("basin_kernel.zig").BasinKernel;

/// Boot phase enumeration.
/// Why: Explicit boot phases for clear initialization order.
pub const BootPhase = enum(u32) {
    /// Early initialization (before subsystems).
    early = 0,
    /// Timer initialization (needed for time-based operations).
    timer = 1,
    /// Interrupt controller initialization (needed for interrupt
handling).
    interrupt = 2,
    /// Memory pool initialization (needed for kernel allocations).
    memory = 3,
    /// Storage initialization (needed for file I/O).
    storage = 4,
    /// Scheduler initialization (needed for process management).
    scheduler = 5,
    /// IPC channels initialization (needed for inter-process
communication).
    channels = 6,
    /// Input devices initialization (keyboard, mouse).
    input = 7,
    /// User management initialization.
    users = 8,
    /// Complete (all subsystems initialized).
    complete = 9,
};

/// Boot sequence state.
/// Why: Track boot progress and validate initialization order.
pub const BootSequence = struct {
    /// Current boot phase.
    /// Why: Track which phase we're in.
    current_phase: BootPhase = .early,
    
    /// Boot start timestamp (monotonic nanoseconds).
    /// Why: Measure boot time for diagnostics.
    boot_start_ns: u64 = 0,
    
    /// Boot complete timestamp (monotonic nanoseconds).
    /// Why: Measure boot time for diagnostics.
    boot_complete_ns: u64 = 0,
    
    /// Initialize boot sequence.
    /// Why: Start boot sequence tracking.
    pub fn init() BootSequence {
        return BootSequence{
            .current_phase = .early,
            .boot_start_ns = 0,
            .boot_complete_ns = 0,
        };
    }
    
    /// Start boot sequence.
    /// Why: Record boot start time and validate initial state.
    pub fn start(self: *BootSequence, timer: *const
@import("timer.zig").Timer) void {
        // Assert: Boot sequence must be in early phase (precondition).
        Debug.kassert(self.current_phase == .early, "Boot not in early
phase", .{});
        
        // Record boot start time.
        self.boot_start_ns = timer.get_monotonic_ns();
        
        // Assert: Boot start time must be valid (postcondition).
        Debug.kassert(self.boot_start_ns > 0, "Boot start time is zero",
.{});
    }
    
    /// Advance to next boot phase.
    /// Why: Ensure phases are executed in correct order.
    pub fn advance(self: *BootSequence, next_phase: BootPhase) void {
        // Assert: Next phase must be after current phase (precondition).
        const current_val = @intFromEnum(self.current_phase);
        const next_val = @intFromEnum(next_phase);
        Debug.kassert(next_val > current_val, "Boot phase regression",
.{});
        Debug.kassert(next_val <= @intFromEnum(BootPhase.complete),
"Boot phase out of range", .{});
        
        self.current_phase = next_phase;
        
        // Assert: Phase must be updated (postcondition).
        Debug.kassert(self.current_phase == next_phase, "Phase not
updated", .{});
    }
    
    /// Complete boot sequence.
    /// Why: Mark boot as complete and record completion time.
    pub fn complete(self: *BootSequence, timer: *const
@import("timer.zig").Timer) void {
        // Assert: Boot must be in final phase before complete
(precondition).
        Debug.kassert(self.current_phase == .users, "Boot not in users
phase", .{});
        
        // Record boot completion time.
        self.boot_complete_ns = timer.get_monotonic_ns();
        
        // Advance to complete phase.
        self.current_phase = .complete;
        
        // Assert: Boot must be complete (postcondition).
        Debug.kassert(self.current_phase == .complete, "Boot not
complete", .{});
        Debug.kassert(self.boot_complete_ns > self.boot_start_ns, "Boot
time invalid", .{});
    }
    
    /// Get boot duration (nanoseconds).
    /// Why: Measure boot performance.
    pub fn get_boot_duration_ns(self: *const BootSequence) u64 {
        // Assert: Boot must be complete (precondition).
        Debug.kassert(self.current_phase == .complete, "Boot not
complete", .{});
        Debug.kassert(self.boot_complete_ns > self.boot_start_ns, "Boot
time invalid", .{});
        
        const duration = self.boot_complete_ns - self.boot_start_ns;
        
        // Assert: Duration must be positive (postcondition).
        Debug.kassert(duration > 0, "Boot duration is zero", .{});
        
        return duration;
    }
    
    /// Check if boot is complete.
    /// Why: Validate boot state for operations that require full
initialization.
    pub fn is_complete(self: *const BootSequence) bool {
        return self.current_phase == .complete;
    }
};

/// Execute kernel boot sequence.
/// Why: Initialize all kernel subsystems in correct order with
validation.
/// Contract: kernel must be uninitialized (all subsystems at default
state).
/// Postcondition: All subsystems initialized, boot sequence complete.
pub fn boot_kernel(kernel: *BasinKernel) void {
    // Assert: Kernel timer must be initialized (precondition).
    Debug.kassert(kernel.timer.initialized, "Timer not initialized",
.{});
    
    // Create boot sequence tracker.
    var boot = BootSequence.init();
    
    // Start boot sequence.
    boot.start(&kernel.timer);
    Debug.log(.info, "Boot sequence started", .{});
    
    // Phase 1: Timer (already initialized in BasinKernel.init()).
    // Why: Timer is needed for all time-based operations.
    Debug.kassert(kernel.timer.initialized, "Timer not initialized",
.{});
    boot.advance(.timer);
    Debug.log(.info, "Boot phase: Timer initialized", .{});
    
    // Phase 2: Interrupt controller (already initialized).
    // Why: Interrupt controller is needed for interrupt handling.
    Debug.kassert(kernel.interrupt_controller.initialized, "Interrupt
controller not initialized", .{});
    boot.advance(.interrupt);
    Debug.log(.info, "Boot phase: Interrupt controller initialized",
.{});
    
    // Phase 3: Memory pool (already initialized).
    // Why: Memory pool is needed for kernel allocations.
    const MAX_PAGES: u32 = 1024; // From memory.zig
    Debug.kassert(kernel.memory_pool.allocated_pages <= MAX_PAGES,
"Memory pool invalid", .{});
    boot.advance(.memory);
    Debug.log(.info, "Boot phase: Memory pool initialized", .{});
    
    // Phase 4: Storage (already initialized).
    // Why: Storage is needed for file I/O operations.
    const MAX_FILES: u32 = 128; // From storage.zig
    Debug.kassert(kernel.storage.file_count <= MAX_FILES, "Storage
invalid", .{});
    boot.advance(.storage);
    Debug.log(.info, "Boot phase: Storage initialized", .{});
    
    // Phase 5: Scheduler (already initialized).
    // Why: Scheduler is needed for process management.
    Debug.kassert(kernel.scheduler.initialized, "Scheduler not
initialized", .{});
    boot.advance(.scheduler);
    Debug.log(.info, "Boot phase: Scheduler initialized", .{});
    
    // Phase 6: IPC channels (already initialized).
    // Why: IPC channels are needed for inter-process communication.
    const MAX_CHANNELS: u32 = 64; // From channel.zig
    Debug.kassert(kernel.channels.channel_count <= MAX_CHANNELS,
"Channels invalid", .{});
    boot.advance(.channels);
    Debug.log(.info, "Boot phase: IPC channels initialized", .{});
    
    // Phase 7: Input devices (already initialized).
    // Why: Input devices are needed for keyboard/mouse input.
    Debug.kassert(kernel.keyboard.last_key_code == 0, "Keyboard not
initialized", .{});
    Debug.kassert(kernel.mouse.x == 0 and kernel.mouse.y == 0, "Mouse
not initialized", .{});
    boot.advance(.input);
    Debug.log(.info, "Boot phase: Input devices initialized", .{});
    
    // Phase 8: Users (already initialized).
    // Why: Users are needed for permission checks.
    Debug.kassert(kernel.user_count >= 1, "No users initialized", .{});
    Debug.kassert(kernel.users[0].uid == 0, "Root user not initialized",
.{});
    boot.advance(.users);
    Debug.log(.info, "Boot phase: Users initialized ({d} users)",
.{kernel.user_count});
    
    // Complete boot sequence.
    boot.complete(&kernel.timer);
    const boot_duration_ns = boot.get_boot_duration_ns();
    const boot_duration_ms = boot_duration_ns / 1000000;
    Debug.log(.info, "Boot sequence complete ({d} ms)",
.{boot_duration_ms});
    
    // Assert: Boot must be complete (postcondition).
    Debug.kassert(boot.is_complete(), "Boot not complete", .{});
    
    // Assert: All subsystems must be initialized (postcondition).
    Debug.kassert(kernel.timer.initialized, "Timer not initialized",
.{});
    Debug.kassert(kernel.interrupt_controller.initialized, "Interrupt
controller not initialized", .{});
    Debug.kassert(kernel.scheduler.initialized, "Scheduler not
initialized", .{});
    Debug.kassert(kernel.user_count >= 1, "No users initialized", .{});
}


// === kernel/channel.zig ===

//! Grain Basin IPC Channel
//! Why: Inter-process communication via message queues.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Maximum message size (bytes).
/// Why: Bounded message size for safety and static allocation.
/// Note: Must match kernel validation (64KB max per message).
pub const MAX_MESSAGE_SIZE: u32 = 4096;

/// Maximum messages per channel.
/// Why: Bounded queue size for safety and static allocation.
pub const MAX_MESSAGES: u32 = 32;

/// Channel message.
/// Why: Store message data in channel queue.
/// Grain Style: Static allocation, bounded size.
pub const Message = struct {
    /// Message data (bounded size).
    data: [MAX_MESSAGE_SIZE]u8,
    /// Message length (bytes, <= MAX_MESSAGE_SIZE).
    length: u32,
    /// Whether message is valid (in queue).
    valid: bool,
    
    /// Initialize empty message.
    /// Why: Explicit initialization, clear state.
    pub fn init() Message {
        return Message{
            .data = [_]u8{0} ** MAX_MESSAGE_SIZE,
            .length = 0,
            .valid = false,
        };
    }
};

/// IPC channel for inter-process communication.
/// Why: Enable processes to send/receive messages.
/// Grain Style: Static allocation, bounded queue.
pub const Channel = struct {
    /// Channel ID (non-zero if allocated).
    id: u64,
    /// Message queue (bounded size).
    messages: [MAX_MESSAGES]Message,
    /// Number of messages in queue.
    message_count: u32,
    /// Read position (index of next message to read).
    read_pos: u32,
    /// Write position (index of next message to write).
    write_pos: u32,
    /// Whether channel is allocated.
    allocated: bool,
    /// Owner process ID (0 = kernel-owned, non-zero = process-owned).
    /// Why: Track which process owns this channel for resource cleanup.
    owner_process_id: u32,
    
    /// Initialize empty channel.
    /// Why: Explicit initialization, clear state.
    pub fn init() Channel {
        return Channel{
            .id = 0,
            .messages = [_]Message{Message.init()} ** MAX_MESSAGES,
            .message_count = 0,
            .read_pos = 0,
            .write_pos = 0,
            .allocated = false,
            .owner_process_id = 0,
        };
    }
    
    /// Send message to channel.
    /// Why: Add message to channel queue.
    /// Contract: data must be <= MAX_MESSAGE_SIZE, channel must be
allocated.
    /// Returns: true if sent, false if queue full.
    pub fn send(self: *Channel, data: []const u8) bool {
        // Assert: Channel must be allocated.
        Debug.kassert(self.allocated, "Channel not allocated", .{});
        
        // Assert: Data length must be <= MAX_MESSAGE_SIZE.
        Debug.kassert(data.len <= MAX_MESSAGE_SIZE, "Data too large",
.{});
        
        // Assert: Data length must be > 0.
        Debug.kassert(data.len > 0, "Data empty", .{});
        
        // Check if queue is full.
        if (self.message_count >= MAX_MESSAGES) {
            return false; // Queue full
        }
        
        // Assert: Write position must be within bounds.
        Debug.kassert(self.write_pos < MAX_MESSAGES, "Write pos >= MAX",
.{});
        
        // Get message slot at write position.
        var msg = &self.messages[self.write_pos];
        
        // Copy data to message.
        @memcpy(msg.data[0..data.len], data);
        msg.length = @as(u32, @intCast(data.len));
        msg.valid = true;
        
        // Update write position (wrap around).
        self.write_pos = (self.write_pos + 1) % MAX_MESSAGES;
        self.message_count += 1;
        
        // Assert: Message count must be <= MAX_MESSAGES.
        Debug.kassert(self.message_count <= MAX_MESSAGES, "Message count
> MAX", .{});
        
        // Assert: Message must be valid.
        Debug.kassert(msg.valid, "Message not valid", .{});
        Debug.kassert(msg.length == @as(u32, @intCast(data.len)),
"Message length mismatch", .{});
        
        return true;
    }
    
    /// Receive message from channel.
    /// Why: Remove message from channel queue.
    /// Contract: buffer must be >= MAX_MESSAGE_SIZE, channel must be
allocated.
    /// Returns: bytes received if message available, 0 if queue empty.
    pub fn receive(self: *Channel, buffer: []u8) u32 {
        // Assert: Channel must be allocated.
        Debug.kassert(self.allocated, "Channel not allocated", .{});
        
        // Assert: Buffer must be >= MAX_MESSAGE_SIZE.
        Debug.kassert(buffer.len >= MAX_MESSAGE_SIZE, "Buffer too
small", .{});
        
        // Check if queue is empty.
        if (self.message_count == 0) {
            return 0; // Queue empty
        }
        
        // Assert: Read position must be within bounds.
        Debug.kassert(self.read_pos < MAX_MESSAGES, "Read pos >= MAX",
.{});
        
        // Get message at read position.
        var msg = &self.messages[self.read_pos];
        
        // Assert: Message must be valid.
        Debug.kassert(msg.valid, "Message not valid", .{});
        
        // Copy message data to buffer.
        const bytes_to_copy = @min(msg.length, @as(u32,
@intCast(buffer.len)));
        @memcpy(buffer[0..bytes_to_copy], msg.data[0..bytes_to_copy]);
        
        // Clear message.
        msg.valid = false;
        msg.length = 0;
        
        // Update read position (wrap around).
        self.read_pos = (self.read_pos + 1) % MAX_MESSAGES;
        self.message_count -= 1;
        
        // Assert: Message count must be >= 0.
        Debug.kassert(self.message_count >= 0, "Message count negative",
.{});
        
        // Assert: Message must be cleared.
        Debug.kassert(!msg.valid, "Message still valid", .{});
        
        return bytes_to_copy;
    }
    
    /// Check if channel has messages.
    /// Why: Query channel state without blocking.
    /// Contract: Channel must be allocated.
    pub fn has_messages(self: *const Channel) bool {
        // Assert: Channel must be allocated.
        Debug.kassert(self.allocated, "Channel not allocated", .{});
        
        return self.message_count > 0;
    }
    
    /// Get message count.
    /// Why: Query number of messages in queue.
    /// Contract: Channel must be allocated.
    pub fn get_message_count(self: *const Channel) u32 {
        // Assert: Channel must be allocated.
        Debug.kassert(self.allocated, "Channel not allocated", .{});
        
        // Assert: Message count must be <= MAX_MESSAGES.
        Debug.kassert(self.message_count <= MAX_MESSAGES, "Message count
> MAX", .{});
        
        return self.message_count;
    }
};

/// Channel table for kernel.
/// Why: Manage all IPC channels in kernel.
/// Grain Style: Static allocation, max 64 channels.
pub const ChannelTable = struct {
    /// Channels array (static allocation).
    channels: [64]Channel,
    /// Number of allocated channels.
    channel_count: u32,
    /// Next channel ID (starts at 1).
    next_channel_id: u64,
    
    /// Initialize channel table.
    /// Why: Set up channel table state.
    pub fn init() ChannelTable {
        return ChannelTable{
            .channels = [_]Channel{Channel.init()} ** 64,
            .channel_count = 0,
            .next_channel_id = 1,
        };
    }
    
    /// Create new channel.
    /// Why: Allocate channel for IPC.
    /// Returns: Channel ID if created, 0 if table full.
    pub fn create(self: *ChannelTable) u64 {
        // Assert: Channel count must be < max channels.
        Debug.kassert(self.channel_count < 64, "Channel table full",
.{});
        
        // Find free channel slot.
        var slot: ?u32 = null;
        for (0..64) |i| {
            if (!self.channels[i].allocated) {
                slot = @as(u32, @intCast(i));
                break;
            }
        }
        
        if (slot == null) {
            return 0; // No free slot
        }
        
        const idx = slot.?;
        
        // Allocate channel ID.
        const channel_id = self.next_channel_id;
        self.next_channel_id += 1;
        
        // Initialize channel.
        self.channels[idx].id = channel_id;
        self.channels[idx].allocated = true;
        self.channels[idx].message_count = 0;
        self.channels[idx].read_pos = 0;
        self.channels[idx].write_pos = 0;
        self.channels[idx].owner_process_id = 0; // Will be set by
syscall_channel_create
        
        self.channel_count += 1;
        
        // Assert: Channel must be allocated.
        Debug.kassert(self.channels[idx].allocated, "Channel not
allocated", .{});
        Debug.kassert(self.channels[idx].id == channel_id, "Channel ID
mismatch", .{});
        Debug.kassert(channel_id != 0, "Channel ID is 0", .{});
        
        return channel_id;
    }
    
    /// Find channel by ID.
    /// Why: Look up channel for send/receive operations.
    /// Returns: Channel pointer if found, null otherwise.
    pub fn find(self: *ChannelTable, channel_id: u64) ?*Channel {
        // Assert: Channel ID must be non-zero.
        Debug.kassert(channel_id != 0, "Channel ID is 0", .{});
        
        for (0..64) |i| {
            if (self.channels[i].allocated and self.channels[i].id ==
channel_id) {
                // Assert: Channel must be allocated.
                Debug.kassert(self.channels[i].allocated, "Channel not
allocated", .{});
                Debug.kassert(self.channels[i].id == channel_id,
"Channel ID mismatch", .{});
                
                return &self.channels[i];
            }
        }
        
        return null;
    }
    
    /// Get channel count.
    /// Why: Query number of allocated channels.
    pub fn get_count(self: *const ChannelTable) u32 {
        // Assert: Channel count must be <= 64.
        Debug.kassert(self.channel_count <= 64, "Channel count > 64",
.{});
        
        return self.channel_count;
    }
};

// Test channel initialization.
test "channel init" {
    const channel = Channel.init();
    
    // Assert: Channel must be unallocated initially.
    try std.testing.expect(!channel.allocated);
    try std.testing.expect(channel.id == 0);
    try std.testing.expect(channel.message_count == 0);
}

// Test channel send and receive.
test "channel send receive" {
    var channel = Channel.init();
    channel.allocated = true;
    channel.id = 1;
    
    const data = "Hello, World!";
    const sent = channel.send(data);
    
    // Assert: Message must be sent.
    try std.testing.expect(sent);
    try std.testing.expect(channel.message_count == 1);
    
    var buffer: [MAX_MESSAGE_SIZE]u8 = undefined;
    const received = channel.receive(&buffer);
    
    // Assert: Message must be received.
    try std.testing.expect(received == data.len);
    try std.testing.expect(std.mem.eql(u8, buffer[0..received], data));
    try std.testing.expect(channel.message_count == 0);
}

// Test channel table.
test "channel table create" {
    var table = ChannelTable.init();
    
    const id1 = table.create();
    
    // Assert: Channel must be created.
    try std.testing.expect(id1 != 0);
    try std.testing.expect(table.channel_count == 1);
    
    const channel = table.find(id1);
    
    // Assert: Channel must be found.
    try std.testing.expect(channel != null);
    try std.testing.expect(channel.?.id == id1);
}


// === kernel/cow.zig ===

//! Copy-on-Write (COW) Memory Sharing System
//!
//! Objective: Enable efficient memory sharing between processes using
copy-on-write semantics.
//! Why: Allow multiple processes to share read-only memory pages,
copying pages only when modified.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track reference counts for shared pages
//! - Mark pages as COW when shared
//! - Copy pages on first write (fault handling)
//! - Decrement reference counts on unmap
//! - Free pages when reference count reaches zero
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-01-XX
//! GrainStyle: Comprehensive COW tracking, deterministic behavior,
explicit limits

const std = @import("std");
const Debug = @import("debug.zig");

/// Page size (4KB, standard RISC-V page size).
/// Why: Explicit constant for page size, matches RISC-V standard.
pub const PAGE_SIZE: u64 = 4096;

/// Maximum number of pages in VM memory (4MB / 4KB = 1024 pages).
/// Why: Bounded allocation, prevents unbounded growth.
const MAX_PAGES: u32 = 1024;

/// Maximum reference count for a shared page.
/// Why: Bounded reference count to prevent overflow.
const MAX_REF_COUNT: u32 = 255;

/// COW page entry.
/// Why: Track reference count and COW state for each page.
/// GrainStyle: Static allocation, explicit state tracking.
pub const CowPageEntry = struct {
    /// Reference count (number of processes sharing this page).
    /// Why: Track how many processes share this page.
    ref_count: u32 = 0,
    
    /// Whether this page is marked for copy-on-write.
    /// Why: Track if page should be copied on write.
    cow_marked: bool = false,
    
    /// Initialize empty COW page entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() CowPageEntry {
        return CowPageEntry{
            .ref_count = 0,
            .cow_marked = false,
        };
    }
    
    /// Check if page is shared (ref_count > 1).
    /// Why: Determine if page is shared between processes.
    pub fn is_shared(self: CowPageEntry) bool {
        return self.ref_count > 1;
    }
    
    /// Check if page should be copied on write.
    /// Why: Determine if COW should trigger on write.
    pub fn should_copy_on_write(self: CowPageEntry) bool {
        return self.cow_marked and self.ref_count > 1;
    }
};

/// COW page table.
/// Why: Track reference counts and COW state for all pages in VM memory.
/// GrainStyle: Static allocation, max 1024 pages (4MB VM).
pub const CowTable = struct {
    /// COW page entries (one per 4KB page).
    /// Why: Static array for bounded allocation.
    pages: [MAX_PAGES]CowPageEntry =
[_]CowPageEntry{CowPageEntry.init()} ** MAX_PAGES,
    
    /// Initialize COW table.
    /// Why: Explicit initialization, clear state.
    pub fn init() CowTable {
        const table = CowTable{};
        
        // Assert: All pages must be initialized (precondition).
        for (table.pages) |page| {
            Debug.kassert(page.ref_count == 0, "Page ref count not
zero", .{});
            Debug.kassert(!page.cow_marked, "Page already COW marked",
.{});
        }
        
        return table;
    }
    
    /// Get page index from address.
    /// Why: Convert address to page index for table lookup.
    /// Contract: Address must be valid (within VM memory bounds).
    /// Returns: Page index (0-1023), or null if address is out of
bounds.
    pub fn get_page_index(addr: u64) ?u32 {
        // Assert: Address must be valid (precondition).
        const VM_MEMORY_SIZE: u64 = 4 * 1024 * 1024; // 4MB default
        if (addr >= VM_MEMORY_SIZE) {
            return null; // Out of bounds
        }
        
        const page_idx = @as(u32, @intCast(addr / PAGE_SIZE));
        
        // Assert: Page index must be within bounds (postcondition).
        Debug.kassert(page_idx < MAX_PAGES, "Page index out of bounds",
.{});
        
        return page_idx;
    }
    
    /// Get COW page entry for address.
    /// Why: Look up COW state for a given address.
    /// Contract: Address must be valid, returns page entry (may be
unshared).
    /// Returns: COW page entry for the page containing the address, or
null if out of bounds.
    pub fn get_page(self: *const CowTable, addr: u64) ?*const
CowPageEntry {
        const page_idx = CowTable.get_page_index(addr) orelse {
            return null; // Out of bounds
        };
        
        // Assert: Page index must be valid (postcondition).
        Debug.kassert(page_idx < MAX_PAGES, "Page index out of bounds",
.{});
        
        return @ptrCast(&self.pages[page_idx]);
    }
    
    /// Increment reference count for pages in address range.
    /// Why: Track that pages are being shared (mapped by another
process).
    /// Contract: Address and size must be page-aligned, size must be
non-zero.
    /// Returns: Error if invalid arguments, success if reference counts
incremented.
    pub fn increment_refs(
        self: *CowTable,
        addr: u64,
        size: u64,
        mark_cow: bool,
    ) void {
        // Assert: Address must be page-aligned (precondition).
        Debug.kassert(addr % PAGE_SIZE == 0, "Address not page-aligned",
.{});
        
        // Assert: Size must be page-aligned and non-zero (precondition).
        Debug.kassert(size > 0, "Size is zero", .{});
        Debug.kassert(size % PAGE_SIZE == 0, "Size not page-aligned",
.{});
        
        const start_page = CowTable.get_page_index(addr).?;
        const num_pages = @as(u32, @intCast(size / PAGE_SIZE));
        const end_page = start_page + num_pages;
        
        // Assert: End page must be within bounds (precondition).
        Debug.kassert(end_page <= MAX_PAGES, "End page out of bounds",
.{});
        
        // Increment reference counts for all pages in range.
        for (start_page..end_page) |page_idx| {
            const page = &self.pages[page_idx];
            
            // Assert: Reference count must not overflow (precondition).
            Debug.kassert(page.ref_count < MAX_REF_COUNT, "Ref count
overflow", .{});
            
            page.ref_count += 1;
            if (mark_cow) {
                page.cow_marked = true;
            }
            
            // Assert: Reference count must be incremented
(postcondition).
            Debug.kassert(page.ref_count > 0, "Ref count not
incremented", .{});
        }
    }
    
    /// Decrement reference count for pages in address range.
    /// Why: Track that pages are no longer shared (unmapped by a
process).
    /// Contract: Address and size must be page-aligned, size must be
non-zero.
    /// Returns: Error if invalid arguments, success if reference counts
decremented.
    pub fn decrement_refs(
        self: *CowTable,
        addr: u64,
        size: u64,
    ) void {
        // Assert: Address must be page-aligned (precondition).
        Debug.kassert(addr % PAGE_SIZE == 0, "Address not page-aligned",
.{});
        
        // Assert: Size must be page-aligned and non-zero (precondition).
        Debug.kassert(size > 0, "Size is zero", .{});
        Debug.kassert(size % PAGE_SIZE == 0, "Size not page-aligned",
.{});
        
        const start_page = CowTable.get_page_index(addr).?;
        const num_pages = @as(u32, @intCast(size / PAGE_SIZE));
        const end_page = start_page + num_pages;
        
        // Assert: End page must be within bounds (precondition).
        Debug.kassert(end_page <= MAX_PAGES, "End page out of bounds",
.{});
        
        // Decrement reference counts for all pages in range.
        for (start_page..end_page) |page_idx| {
            const page = &self.pages[page_idx];
            
            // Assert: Reference count must be non-zero (precondition).
            Debug.kassert(page.ref_count > 0, "Ref count is zero", .{});
            
            page.ref_count -= 1;
            
            // Clear COW mark if reference count reaches 1 or 0.
            if (page.ref_count <= 1) {
                page.cow_marked = false;
            }
            
            // Assert: Reference count must be decremented
(postcondition).
            Debug.kassert(page.ref_count < MAX_REF_COUNT, "Ref count not
decremented", .{});
        }
    }
    
    /// Check if page should be copied on write.
    /// Why: Determine if COW should trigger for a write to this address.
    /// Contract: Address must be valid.
    /// Returns: true if page should be copied, false otherwise.
    pub fn should_copy_on_write(self: *const CowTable, addr: u64) bool {
        const page = self.get_page(addr) orelse {
            return false; // Out of bounds
        };
        
        return page.*.should_copy_on_write();
    }
    
    /// Get reference count for a page.
    /// Why: Query how many processes share a page.
    /// Contract: Address must be valid.
    /// Returns: Reference count for the page, or 0 if out of bounds.
    pub fn get_ref_count(self: *const CowTable, addr: u64) u32 {
        const page = self.get_page(addr) orelse {
            return 0; // Out of bounds
        };
        
        return page.*.ref_count;
    }
    
    /// Check if page is shared.
    /// Why: Determine if page is shared between multiple processes.
    /// Contract: Address must be valid.
    /// Returns: true if page is shared (ref_count > 1), false otherwise.
    pub fn is_shared(self: *const CowTable, addr: u64) bool {
        const page = self.get_page(addr) orelse {
            return false; // Out of bounds
        };
        
        return page.*.is_shared();
    }
};


// === kernel/debug.zig ===

const RawIO = @import("raw_io.zig");
const std = @import("std");

/// Grain Style: Explicit logging levels
pub const LogLevel = enum {
    debug,
    info,
    warn,
    error_lvl, // 'error' is a keyword
};

/// Grain Style: Minimal kprint implementation to avoid heavy std
dependencies
/// and linker errors with atomics.
/// Grain Style: Minimal kprint implementation to avoid heavy std
dependencies
/// and linker errors with atomics.
pub fn kprint(comptime fmt: []const u8, args: anytype) void {
    var arg_idx: usize = 0;
    var i: usize = 0;
    while (i < fmt.len) {
        if (fmt[i] == '{') {
            // Handle format specifier
            if (i + 1 < fmt.len and fmt[i+1] == '}') {
                // Simple {}
                print_arg(args, arg_idx);
                arg_idx += 1;
                i += 2;
            } else if (i + 2 < fmt.len and fmt[i+1] == 'd' and fmt[i+2]
== '}') {
                // {d} decimal
                print_arg(args, arg_idx);
                arg_idx += 1;
                i += 3;
            } else if (i + 2 < fmt.len and fmt[i+1] == 'x' and fmt[i+2]
== '}') {
                // {x} hex
                print_hex_arg(args, arg_idx);
                arg_idx += 1;
                i += 3;
            } else if (i + 2 < fmt.len and fmt[i+1] == 's' and fmt[i+2]
== '}') {
                // {s} string
                print_arg(args, arg_idx);
                arg_idx += 1;
                i += 3;
            } else {
                // Unknown, just print char
                RawIO.write_byte(fmt[i]);
                i += 1;
            }
        } else {
            RawIO.write_byte(fmt[i]);
            i += 1;
        }
    }
}

fn print_arg(args: anytype, idx: usize) void {
    inline for (std.meta.fields(@TypeOf(args)), 0..) |field, i| {
        if (i == idx) {
            const val = @field(args, field.name);
            const T = @TypeOf(val);
            if (T == []const u8) {
                RawIO.write(val);
            } else {
                switch (@typeInfo(T)) {
                    .int => print_int(val),
                    .bool => if (val) RawIO.write("true") else
RawIO.write("false"),
                    else => RawIO.write("?"),
                }
            }
            return;
        }
    }
}

fn print_hex_arg(args: anytype, idx: usize) void {
    inline for (std.meta.fields(@TypeOf(args)), 0..) |field, i| {
        if (i == idx) {
            const val = @field(args, field.name);
            const T = @TypeOf(val);
            switch (@typeInfo(T)) {
                .int => print_hex(val),
                else => RawIO.write("?"),
            }
            return;
        }
    }
}

fn print_int(val: anytype) void {
    if (val == 0) {
        RawIO.write_byte('0');
        return;
    }
    
    var v = val;
    var buf: [32]u8 = undefined;
    var i: usize = 0;
    
    // Handle negative for signed integers
    const info = @typeInfo(@TypeOf(val));
    if (info == .int and info.int.signedness == .signed) {
        if (v < 0) {
            RawIO.write_byte('-');
            v = -v;
        }
    }
    
    while (v > 0) {
        buf[i] = @as(u8, @intCast(v % 10)) + '0';
        v = @divTrunc(v, 10);
        i += 1;
    }
    
    while (i > 0) {
        i -= 1;
        RawIO.write_byte(buf[i]);
    }
}

fn print_hex(val: anytype) void {
    if (val == 0) {
        RawIO.write("0x0");
        return;
    }
    
    RawIO.write("0x");
    var v = val;
    var buf: [32]u8 = undefined;
    var i: usize = 0;
    
    while (v > 0) {
        const digit = @as(u8, @intCast(v % 16));
        if (digit < 10) {
            buf[i] = digit + '0';
        } else {
            buf[i] = digit - 10 + 'a';
        }
        v = @divTrunc(v, 16);
        i += 1;
    }
    
    while (i > 0) {
        i -= 1;
        RawIO.write_byte(buf[i]);
    }
}

/// Grain Style: Explicit assertion with message
pub fn kassert(ok: bool, comptime msg: []const u8, args: anytype) void {
    if (!ok) {
        kprint("\n[ASSERT FAILED] ", .{});
        kprint(msg, args);
        kprint("\n", .{});
        
        // Trap/Hang
        while (true) {
            asm volatile ("wfi");
        }
    }
}

/// Grain Style: Log with level
pub fn log(comptime level: LogLevel, comptime fmt: []const u8, args:
anytype) void {
    const prefix = switch (level) {
        .debug => "[DEBUG] ",
        .info => "[INFO]  ",
        .warn => "[WARN]  ",
        .error_lvl => "[ERROR] ",
    };
    
    RawIO.write(prefix);
    kprint(fmt, args);
    RawIO.write("\n");
}

// === kernel/devx/abi.zig ===

pub const EntryPoints = struct {
    start: []const u8 = "_start",
    panic_handler: []const u8 = "grain_panic",
    debug_writer: []const u8 = "grain_debug_write",
};

pub const CallingConvention = struct {
    register_order: []const u8 = "a0..a7",
    stack_alignment: u8 = 16,
};

pub const ABI = struct {
    entry: EntryPoints = .{},
    cc: CallingConvention = .{},
};

pub const current = ABI{};

// === kernel/elf_parser.zig ===

//! ELF Parser for Kernel
//! Why: Parse ELF headers to extract entry point and segment
information for process spawning.
//! Grain Style: Explicit types (u32/u64 not usize), comprehensive
assertions, static allocation.

const std = @import("std");
const Debug = @import("debug.zig");

/// ELF header structure (64-bit, little-endian).
/// Why: Explicit ELF structure for parsing entry point and segment info.
const Elf64_Ehdr = extern struct {
    /// ELF magic number: 0x7F "ELF".
    e_ident: [16]u8,
    /// Object file type (1 = relocatable, 2 = executable, 3 = shared).
    e_type: u16,
    /// Machine architecture (243 = RISC-V).
    e_machine: u16,
    /// Object file version (usually 1).
    e_version: u32,
    /// Entry point virtual address.
    e_entry: u64,
    /// Program header table file offset.
    e_phoff: u64,
    /// Section header table file offset.
    e_shoff: u64,
    /// Processor-specific flags.
    e_flags: u32,
    /// ELF header size in bytes.
    e_ehsize: u16,
    /// Program header table entry size.
    e_phentsize: u16,
    /// Program header table entry count.
    e_phnum: u16,
    /// Section header table entry size.
    e_shentsize: u16,
    /// Section header table entry count.
    e_shnum: u16,
    /// Section header string table index.
    e_shstrndx: u16,
};

/// ELF magic number: 0x7F "ELF".
/// Why: Validate ELF file format.
const ELF_MAGIC = [_]u8{ 0x7F, 'E', 'L', 'F' };

/// ELF program header structure (64-bit, little-endian).
/// Why: Parse program headers to extract segment information.
const Elf64_Phdr = extern struct {
    /// Segment type (1 = PT_LOAD, 2 = PT_DYNAMIC, etc.).
    p_type: u32,
    /// Segment flags (read, write, execute).
    p_flags: u32,
    /// Segment file offset.
    p_offset: u64,
    /// Segment virtual address.
    p_vaddr: u64,
    /// Segment physical address (usually same as virtual).
    p_paddr: u64,
    /// Segment size in file.
    p_filesz: u64,
    /// Segment size in memory.
    p_memsz: u64,
    /// Segment alignment.
    p_align: u64,
};

/// ELF parser result.
/// Why: Return parsed ELF information for process setup.
pub const ElfInfo = struct {
    /// Entry point virtual address.
    /// Why: Set process PC to entry point.
    entry_point: u64,
    /// Whether ELF is valid.
    /// Why: Validate ELF format before using.
    valid: bool,
    /// Program header table offset.
    /// Why: Location of program headers for segment loading.
    phoff: u64,
    /// Program header entry size.
    /// Why: Size of each program header entry.
    phentsize: u16,
    /// Program header count.
    /// Why: Number of program headers.
    phnum: u16,
    
    /// Initialize empty ELF info.
    /// Why: Explicit initialization, clear state.
    pub fn init() ElfInfo {
        return ElfInfo{
            .entry_point = 0,
            .valid = false,
            .phoff = 0,
            .phentsize = 0,
            .phnum = 0,
        };
    }
};

/// Parse ELF header from memory buffer.
/// Why: Extract entry point and validate ELF format for process
spawning.
/// Contract: buffer must be >= 64 bytes (ELF header size), buffer must
be valid ELF format.
/// Returns: ElfInfo with entry point if valid, invalid ElfInfo
otherwise.
/// Grain Style: Static allocation, no recursion, explicit types.
pub fn parse_elf_header(buffer: []const u8) ElfInfo {
    // Assert: Buffer must be non-empty (precondition).
    Debug.kassert(buffer.len > 0, "Buffer empty", .{});
    
    // Assert: Buffer must be >= ELF header size (64 bytes).
    const ELF_HEADER_SIZE: u32 = 64;
    if (buffer.len < ELF_HEADER_SIZE) {
        return ElfInfo.init(); // Invalid: too small
    }
    
    // Assert: Buffer must start with ELF magic number.
    if (buffer[0] != ELF_MAGIC[0] or buffer[1] != ELF_MAGIC[1] or 
        buffer[2] != ELF_MAGIC[2] or buffer[3] != ELF_MAGIC[3]) {
        return ElfInfo.init(); // Invalid: not ELF format
    }
    
    // Assert: ELF class must be 64-bit (byte 4 = 2).
    if (buffer[4] != 2) {
        return ElfInfo.init(); // Invalid: not 64-bit
    }
    
    // Assert: ELF endianness must be little-endian (byte 5 = 1).
    if (buffer[5] != 1) {
        return ElfInfo.init(); // Invalid: not little-endian
    }
    
    // Parse ELF header (requires alignment, but we can read fields
directly).
    // Why: Extract entry point without requiring aligned buffer.
    // Note: e_entry is at offset 24 in ELF64 header.
    const ENTRY_POINT_OFFSET: u32 = 24;
    if (buffer.len < ENTRY_POINT_OFFSET + 8) {
        return ElfInfo.init(); // Invalid: buffer too small for entry
point
    }
    
    // Read entry point (little-endian u64 at offset 24).
    var entry_point: u64 = 0;
    var i: u32 = 0;
    while (i < 8) : (i += 1) {
        const byte = buffer[ENTRY_POINT_OFFSET + i];
        entry_point |= (@as(u64, byte) << @as(u6, @intCast(i * 8)));
    }
    
    // Assert: Entry point must be non-zero (valid executable).
    if (entry_point == 0) {
        return ElfInfo.init(); // Invalid: zero entry point
    }
    
    // Assert: Entry point must be within reasonable range (not too
high).
    const MAX_ENTRY_POINT: u64 = 0xFFFFFFFFFFFF; // 48-bit address space
    if (entry_point > MAX_ENTRY_POINT) {
        return ElfInfo.init(); // Invalid: entry point too large
    }
    
    // Read program header table offset (little-endian u64 at offset 32).
    // Why: Extract program header location for future segment loading.
    const PHOFF_OFFSET: u32 = 32;
    if (buffer.len < PHOFF_OFFSET + 8) {
        return ElfInfo.init(); // Invalid: buffer too small for phoff
    }
    
    var phoff: u64 = 0;
    i = 0;
    while (i < 8) : (i += 1) {
        const byte = buffer[PHOFF_OFFSET + i];
        phoff |= (@as(u64, byte) << @as(u6, @intCast(i * 8)));
    }
    
    // Read program header entry size (little-endian u16 at offset 54).
    // Why: Size of each program header entry.
    const PHENTSIZE_OFFSET: u32 = 54;
    if (buffer.len < PHENTSIZE_OFFSET + 2) {
        return ElfInfo.init(); // Invalid: buffer too small for phentsize
    }
    
    const phentsize: u16 = @as(u16, buffer[PHENTSIZE_OFFSET]) |
(@as(u16, buffer[PHENTSIZE_OFFSET + 1]) << 8);
    
    // Read program header count (little-endian u16 at offset 56).
    // Why: Number of program headers.
    const PHNUM_OFFSET: u32 = 56;
    if (buffer.len < PHNUM_OFFSET + 2) {
        return ElfInfo.init(); // Invalid: buffer too small for phnum
    }
    
    const phnum: u16 = @as(u16, buffer[PHNUM_OFFSET]) | (@as(u16,
buffer[PHNUM_OFFSET + 1]) << 8);
    
    // Assert: Program header entry size must be reasonable (56 bytes
for ELF64).
    const ELF64_PHDR_SIZE: u16 = 56;
    if (phentsize != 0 and phentsize < ELF64_PHDR_SIZE) {
        return ElfInfo.init(); // Invalid: phentsize too small
    }
    
    // Assert: Program header count must be reasonable (max 128
segments).
    const MAX_PHDR_COUNT: u16 = 128;
    if (phnum > MAX_PHDR_COUNT) {
        return ElfInfo.init(); // Invalid: too many program headers
    }
    
    // Return valid ELF info with program header information.
    const info = ElfInfo{
        .entry_point = entry_point,
        .valid = true,
        .phoff = phoff,
        .phentsize = phentsize,
        .phnum = phnum,
    };
    
    // Assert: ELF info must be valid (postcondition).
    Debug.kassert(info.valid, "ELF info not valid", .{});
    Debug.kassert(info.entry_point != 0, "Entry point is zero", .{});
    
    return info;
}

/// Program segment information.
/// Why: Track segment details for loading into VM memory.
pub const ProgramSegment = struct {
    /// Segment type (1 = PT_LOAD, etc.).
    p_type: u32,
    /// Segment virtual address.
    p_vaddr: u64,
    /// Segment size in file.
    p_filesz: u64,
    /// Segment size in memory.
    p_memsz: u64,
    /// Segment flags (read, write, execute).
    p_flags: u32,
    /// Segment file offset.
    p_offset: u64,
    /// Segment alignment.
    p_align: u64,
    /// Whether segment is valid for loading.
    valid: bool,
    
    /// Initialize empty segment.
    /// Why: Explicit initialization, clear state.
    pub fn init() ProgramSegment {
        return ProgramSegment{
            .p_type = 0,
            .p_vaddr = 0,
            .p_filesz = 0,
            .p_memsz = 0,
            .p_flags = 0,
            .p_offset = 0,
            .p_align = 0,
            .valid = false,
        };
    }
};

/// Parse program header from memory buffer.
/// Why: Extract segment information for loading into VM memory.
/// Contract: buffer must be >= 56 bytes (ELF64 program header size),
buffer must be valid program header.
/// Returns: ProgramSegment with segment info if valid, invalid
ProgramSegment otherwise.
/// Grain Style: Static allocation, no recursion, explicit types.
pub fn parse_program_header(buffer: []const u8) ProgramSegment {
    // Assert: Buffer must be non-empty (precondition).
    Debug.kassert(buffer.len > 0, "Buffer empty", .{});
    
    // Assert: Buffer must be >= program header size (56 bytes for
ELF64).
    const ELF64_PHDR_SIZE: u32 = 56;
    if (buffer.len < ELF64_PHDR_SIZE) {
        return ProgramSegment.init(); // Invalid: too small
    }
    
    // Read program header fields (little-endian).
    // p_type at offset 0 (u32)
    var p_type: u32 = 0;
    var i: u32 = 0;
    while (i < 4) : (i += 1) {
        const byte = buffer[i];
        p_type |= (@as(u32, byte) << @as(u5, @intCast(i * 8)));
    }
    
    // p_flags at offset 4 (u32)
    var p_flags: u32 = 0;
    i = 0;
    while (i < 4) : (i += 1) {
        const byte = buffer[4 + i];
        p_flags |= (@as(u32, byte) << @as(u5, @intCast(i * 8)));
    }
    
    // p_offset at offset 8 (u64)
    var p_offset: u64 = 0;
    i = 0;
    while (i < 8) : (i += 1) {
        const byte = buffer[8 + i];
        p_offset |= (@as(u64, byte) << @as(u6, @intCast(i * 8)));
    }
    
    // p_vaddr at offset 16 (u64)
    var p_vaddr: u64 = 0;
    i = 0;
    while (i < 8) : (i += 1) {
        const byte = buffer[16 + i];
        p_vaddr |= (@as(u64, byte) << @as(u6, @intCast(i * 8)));
    }
    
    // p_paddr at offset 24 (u64) - not used, but read for completeness
    _ = buffer[24..32];
    
    // p_filesz at offset 32 (u64)
    var p_filesz: u64 = 0;
    i = 0;
    while (i < 8) : (i += 1) {
        const byte = buffer[32 + i];
        p_filesz |= (@as(u64, byte) << @as(u6, @intCast(i * 8)));
    }
    
    // p_memsz at offset 40 (u64)
    var p_memsz: u64 = 0;
    i = 0;
    while (i < 8) : (i += 1) {
        const byte = buffer[40 + i];
        p_memsz |= (@as(u64, byte) << @as(u6, @intCast(i * 8)));
    }
    
    // p_align at offset 48 (u64)
    var p_align: u64 = 0;
    i = 0;
    while (i < 8) : (i += 1) {
        const byte = buffer[48 + i];
        p_align |= (@as(u64, byte) << @as(u6, @intCast(i * 8)));
    }
    
    // Validate segment.
    // Why: Ensure segment is valid for loading.
    const PT_LOAD: u32 = 1; // Loadable segment type
    if (p_type != PT_LOAD) {
        return ProgramSegment.init(); // Not a loadable segment
    }
    
    // Assert: Virtual address must be non-zero and reasonable.
    if (p_vaddr == 0) {
        return ProgramSegment.init(); // Invalid: zero virtual address
    }
    
    const MAX_VADDR: u64 = 0xFFFFFFFFFFFF; // 48-bit address space
    if (p_vaddr > MAX_VADDR) {
        return ProgramSegment.init(); // Invalid: virtual address too
large
    }
    
    // Assert: Memory size must be >= file size.
    if (p_memsz < p_filesz) {
        return ProgramSegment.init(); // Invalid: memory size < file size
    }
    
    // Assert: Alignment must be power of 2 (if non-zero).
    if (p_align != 0) {
        // Check if p_align is power of 2.
        const is_power_of_2 = (p_align & (p_align - 1)) == 0;
        if (!is_power_of_2) {
            return ProgramSegment.init(); // Invalid: alignment not
power of 2
        }
    }
    
    // Return valid program segment.
    const segment = ProgramSegment{
        .p_type = p_type,
        .p_vaddr = p_vaddr,
        .p_filesz = p_filesz,
        .p_memsz = p_memsz,
        .p_flags = p_flags,
        .p_offset = p_offset,
        .p_align = p_align,
        .valid = true,
    };
    
    // Assert: Segment must be valid (postcondition).
    Debug.kassert(segment.valid, "Segment not valid", .{});
    Debug.kassert(segment.p_type == PT_LOAD, "Segment type not PT_LOAD",
.{});
    Debug.kassert(segment.p_vaddr != 0, "Virtual address is zero", .{});
    
    return segment;
}


// === kernel/framebuffer.zig ===

//! framebuffer: simple framebuffer driver for Grain Basin Kernel
//!
//! Why: Provide basic pixel-level drawing for GUI display.
//! GrainStyle: Static allocation, explicit limits, comprehensive
assertions.

const std = @import("std");

// Framebuffer constants
pub const FRAMEBUFFER_BASE: u64 = 0x90000000;
pub const FRAMEBUFFER_WIDTH: u32 = 1024;
pub const FRAMEBUFFER_HEIGHT: u32 = 768;
pub const FRAMEBUFFER_BPP: u32 = 4; // 32-bit RGBA
pub const FRAMEBUFFER_SIZE: u32 = FRAMEBUFFER_WIDTH * FRAMEBUFFER_HEIGHT
* FRAMEBUFFER_BPP; // 3MB

// Color constants (32-bit RGBA)
pub const COLOR_BLACK: u32 = 0x00000000;
pub const COLOR_WHITE: u32 = 0xFFFFFFFF;
pub const COLOR_RED: u32 = 0xFF0000FF;
pub const COLOR_GREEN: u32 = 0x00FF00FF;
pub const COLOR_BLUE: u32 = 0x0000FFFF;
pub const COLOR_DARK_BG: u32 = 0x1E1E2EFF; // Dark background color

// Framebuffer state
pub const Framebuffer = struct {
    base: u64,
    width: u32,
    height: u32,
    bpp: u32,
    memory: []u8,

    // Initialize framebuffer
    // Why: Set up framebuffer state and clear to background color.
    pub fn init(memory: []u8) Framebuffer {
        std.debug.assert(memory.len >= FRAMEBUFFER_SIZE);
        std.debug.assert(FRAMEBUFFER_WIDTH > 0);
        std.debug.assert(FRAMEBUFFER_HEIGHT > 0);
        std.debug.assert(FRAMEBUFFER_BPP == 4);

        const fb = Framebuffer{
            .base = FRAMEBUFFER_BASE,
            .width = FRAMEBUFFER_WIDTH,
            .height = FRAMEBUFFER_HEIGHT,
            .bpp = FRAMEBUFFER_BPP,
            .memory = memory[0..FRAMEBUFFER_SIZE],
        };

        // Assert: framebuffer must be initialized correctly.
        std.debug.assert(fb.width == FRAMEBUFFER_WIDTH);
        std.debug.assert(fb.height == FRAMEBUFFER_HEIGHT);
        std.debug.assert(fb.memory.len == FRAMEBUFFER_SIZE);

        return fb;
    }

    // Clear framebuffer to a color
    // Why: Fill entire framebuffer with a single color (e.g.,
background).
    pub fn clear(self: *const Framebuffer, color: u32) void {
        std.debug.assert(self.memory.len == FRAMEBUFFER_SIZE);

        // Convert 32-bit RGBA color to bytes
        const r: u8 = @as(u8, @truncate((color >> 24) & 0xFF));
        const g: u8 = @as(u8, @truncate((color >> 16) & 0xFF));
        const b: u8 = @as(u8, @truncate((color >> 8) & 0xFF));
        const a: u8 = @as(u8, @truncate(color & 0xFF));

        // Fill framebuffer with color (RGBA format)
        var i: u32 = 0;
        while (i < FRAMEBUFFER_SIZE) : (i += 4) {
            self.memory[i + 0] = r;
            self.memory[i + 1] = g;
            self.memory[i + 2] = b;
            self.memory[i + 3] = a;
        }

        // Assert: framebuffer must be filled (check first and last
pixel).
        std.debug.assert(self.memory[0] == r);
        std.debug.assert(self.memory[FRAMEBUFFER_SIZE - 4] == r);
    }

    // Draw a single pixel
    // Why: Basic pixel-level drawing primitive.
    pub fn draw_pixel(self: *const Framebuffer, x: u32, y: u32, color:
u32) void {
        std.debug.assert(x < self.width);
        std.debug.assert(y < self.height);
        std.debug.assert(self.memory.len == FRAMEBUFFER_SIZE);

        // Calculate pixel offset (RGBA format, row-major order)
        const offset: u32 = (y * self.width + x) * self.bpp;
        std.debug.assert(offset + 3 < FRAMEBUFFER_SIZE);

        // Convert 32-bit RGBA color to bytes
        const r: u8 = @as(u8, @truncate((color >> 24) & 0xFF));
        const g: u8 = @as(u8, @truncate((color >> 16) & 0xFF));
        const b: u8 = @as(u8, @truncate((color >> 8) & 0xFF));
        const a: u8 = @as(u8, @truncate(color & 0xFF));

        // Write pixel (RGBA format)
        self.memory[offset + 0] = r;
        self.memory[offset + 1] = g;
        self.memory[offset + 2] = b;
        self.memory[offset + 3] = a;

        // Assert: pixel must be written correctly.
        std.debug.assert(self.memory[offset + 0] == r);
    }

    // Draw a filled rectangle
    // Why: Common drawing primitive for UI elements.
    pub fn draw_rect(self: *const Framebuffer, x: u32, y: u32, w: u32,
h: u32, color: u32) void {
        std.debug.assert(x < self.width);
        std.debug.assert(y < self.height);
        std.debug.assert(x + w <= self.width);
        std.debug.assert(y + h <= self.height);
        std.debug.assert(w > 0);
        std.debug.assert(h > 0);

        var py: u32 = y;
        while (py < y + h) : (py += 1) {
            var px: u32 = x;
            while (px < x + w) : (px += 1) {
                self.draw_pixel(px, py, color);
            }
        }

        // Assert: rectangle must be drawn (check corners).
        std.debug.assert(self.memory[(y * self.width + x) * self.bpp] ==
@as(u8, @truncate((color >> 24) & 0xFF)));
    }

    // Draw a test pattern
    // Why: Visual verification that framebuffer is working.
    pub fn draw_test_pattern(self: *const Framebuffer) void {
        std.debug.assert(self.memory.len == FRAMEBUFFER_SIZE);

        // Clear to dark background
        self.clear(COLOR_DARK_BG);

        // Draw colored rectangles
        const rect_size: u32 = 100;
        const spacing: u32 = 20;

        // Red rectangle (top-left)
        self.draw_rect(spacing, spacing, rect_size, rect_size,
COLOR_RED);

        // Green rectangle (top-right)
        self.draw_rect(self.width - rect_size - spacing, spacing,
rect_size, rect_size, COLOR_GREEN);

        // Blue rectangle (bottom-left)
        self.draw_rect(spacing, self.height - rect_size - spacing,
rect_size, rect_size, COLOR_BLUE);

        // White rectangle (bottom-right)
        self.draw_rect(self.width - rect_size - spacing, self.height -
rect_size - spacing, rect_size, rect_size, COLOR_WHITE);

        // Assert: test pattern must be drawn (check first red pixel).
        const red_offset: u32 = (spacing * self.width + spacing) *
self.bpp;
        std.debug.assert(self.memory[red_offset] == 0xFF);
    }

    // Draw a single character using 8x8 bitmap font
    // Why: Basic text rendering primitive for kernel messages.
    // GrainStyle: Explicit bounds checking, deterministic rendering.
    pub fn draw_char(self: *const Framebuffer, ch: u8, x: u32, y: u32,
fg_color: u32, bg_color: u32) void {
        // Assert: character position must be within bounds.
        std.debug.assert(x + 8 <= self.width);
        std.debug.assert(y + 8 <= self.height);
        
        // Get character pattern (8x8 bitmap, 64 bits).
        const pattern = get_char_pattern(ch);
        
        // Extract foreground and background colors.
        const fg_r: u8 = @truncate((fg_color >> 24) & 0xFF);
        const fg_g: u8 = @truncate((fg_color >> 16) & 0xFF);
        const fg_b: u8 = @truncate((fg_color >> 8) & 0xFF);
        const bg_r: u8 = @truncate((bg_color >> 24) & 0xFF);
        const bg_g: u8 = @truncate((bg_color >> 16) & 0xFF);
        const bg_b: u8 = @truncate((bg_color >> 8) & 0xFF);
        
        // Draw character (8x8 pixels).
        var py: u32 = 0;
        while (py < 8) : (py += 1) {
            var px: u32 = 0;
            while (px < 8) : (px += 1) {
                const bit_idx = py * 8 + px;
                const bit = (pattern >> @as(u6, @intCast(63 - bit_idx)))
& 1;
                
                const pixel_x = x + px;
                const pixel_y = y + py;
                const offset: u32 = (pixel_y * self.width + pixel_x) *
self.bpp;
                
                // Assert: offset must be within bounds.
                std.debug.assert(offset + 3 < FRAMEBUFFER_SIZE);
                
                if (bit == 1) {
                    // Foreground color
                    self.memory[offset + 0] = fg_r;
                    self.memory[offset + 1] = fg_g;
                    self.memory[offset + 2] = fg_b;
                } else {
                    // Background color
                    self.memory[offset + 0] = bg_r;
                    self.memory[offset + 1] = bg_g;
                    self.memory[offset + 2] = bg_b;
                }
                self.memory[offset + 3] = 0xFF; // Alpha
            }
        }
    }
    
    // Draw text string at position
    // Why: Render kernel boot messages and status text.
    // GrainStyle: Explicit bounds checking, deterministic rendering.
    pub fn draw_text(self: *const Framebuffer, text: []const u8, x: u32,
y: u32, fg_color: u32, bg_color: u32) void {
        // Assert: text must not be empty.
        std.debug.assert(text.len > 0);
        
        // Assert: starting position must be within bounds.
        std.debug.assert(x < self.width);
        std.debug.assert(y < self.height);
        
        var char_x: u32 = x;
        var char_y: u32 = y;
        const char_width: u32 = 8;
        const char_height: u32 = 8;
        
        var i: u32 = 0;
        while (i < text.len) : (i += 1) {
            const ch = text[i];
            
            // Handle newline.
            if (ch == '\n') {
                char_x = x;
                char_y += char_height;
                continue;
            }
            
            // Assert: character position must be within bounds.
            if (char_x + char_width > self.width) {
                // Wrap to next line.
                char_x = x;
                char_y += char_height;
            }
            
            // Assert: character must fit vertically.
            if (char_y + char_height > self.height) {
                break; // Out of bounds, stop rendering.
            }
            
            // Draw character.
            self.draw_char(ch, char_x, char_y, fg_color, bg_color);
            char_x += char_width;
        }
    }
    
    // Get 8x8 bitmap pattern for character
    // Why: Simple bitmap font for kernel text rendering.
    // Pattern is row-major, MSB first (top-left to bottom-right).
    fn get_char_pattern(ch: u8) u64 {
        return switch (ch) {
            ' ' => 0x0000000000000000,
            '!' => 0x1818181818001800,
            '"' => 0x3636000000000000,
            '#' => 0x36367F36367F3636,
            '$' => 0x0C3E033E301F0C00,
            '%' => 0x006333180C666300,
            '&' => 0x1C361C6E3B331E00,
            '\'' => 0x0C0C180000000000,
            '(' => 0x0C18181818180C00,
            ')' => 0x180C0C0C0C0C1800,
            '*' => 0x00183C7E3C180000,
            '+' => 0x000018187E181800,
            ',' => 0x0000000000180C18,
            '-' => 0x000000007E000000,
            '.' => 0x0000000000181800,
            '/' => 0x303018180C0C0606,
            '0' => 0x3C666E7E76663C00,
            '1' => 0x1818381818187E00,
            '2' => 0x3C66060C18307E00,
            '3' => 0x3C66061C06663C00,
            '4' => 0x060E1E367F060600,
            '5' => 0x7E607C0606663C00,
            '6' => 0x1C30607C66663C00,
            '7' => 0x7E060C1818181800,
            '8' => 0x3C66663C66663C00,
            '9' => 0x3C66663E060C3800,
            ':' => 0x0000180000180000,
            ';' => 0x0000180000180C18,
            '<' => 0x000C1830180C0000,
            '=' => 0x00007E00007E0000,
            '>' => 0x00180C060C180000,
            '?' => 0x3C66060C18001800,
            '@' => 0x3C66766E60663C00,
            'A' => 0x183C66667E666600,
            'B' => 0x7C66667C66667C00,
            'C' => 0x3C66606060663C00,
            'D' => 0x786C6666666C7800,
            'E' => 0x7E60607C60607E00,
            'F' => 0x7E60607C60606000,
            'G' => 0x3C66606E66663C00,
            'H' => 0x6666667E66666600,
            'I' => 0x3C18181818183C00,
            'J' => 0x1E0C0C0C6C6C3800,
            'K' => 0x666C78786C666600,
            'L' => 0x6060606060607E00,
            'M' => 0x63777F6B63636300,
            'N' => 0x66767E7E6E666600,
            'O' => 0x3C66666666663C00,
            'P' => 0x7C66667C60606000,
            'Q' => 0x3C6666666E3C0600,
            'R' => 0x7C66667C6C666600,
            'S' => 0x3C603C06063C00,
            'T' => 0x7E18181818181800,
            'U' => 0x6666666666663C00,
            'V' => 0x66666666663C1800,
            'W' => 0x63636B7F77636300,
            'X' => 0x66663C183C666600,
            'Y' => 0x6666663C18181800,
            'Z' => 0x7E060C1830607E00,
            '[' => 0x3C30303030303C00,
            '\\' => 0x06060C0C18183030,
            ']' => 0x3C0C0C0C0C0C3C00,
            '^' => 0x183C660000000000,
            '_' => 0x0000000000007E00,
            '`' => 0x18180C0000000000,
            'a' => 0x00003C063E663E00,
            'b' => 0x60607C6666667C00,
            'c' => 0x00003C6660603C00,
            'd' => 0x06063E6666663E00,
            'e' => 0x00003C667E603C00,
            'f' => 0x1C30307C30303000,
            'g' => 0x00003E66663E063C,
            'h' => 0x60607C6666666600,
            'i' => 0x1800181818181800,
            'j' => 0x0C000C0C0C6C3800,
            'k' => 0x6060666C786C6600,
            'l' => 0x1818181818181800,
            'm' => 0x0000767F6B636300,
            'n' => 0x00007C6666666600,
            'o' => 0x00003C6666663C00,
            'p' => 0x00007C66667C6060,
            'q' => 0x00003E66663E0606,
            'r' => 0x00007C6660606000,
            's' => 0x00003E603C067C00,
            't' => 0x30307C3030301C00,
            'u' => 0x0000666666663E00,
            'v' => 0x00006666663C1800,
            'w' => 0x0000636B7F360000,
            'x' => 0x0000663C183C6600,
            'y' => 0x00006666663E063C,
            'z' => 0x00007E0C18307E00,
            '{' => 0x0C18187018180C00,
            '|' => 0x1818180018181800,
            '}' => 0x3018180E18183000,
            '~' => 0x0000003E6C000000,
            else => 0x7E8185B581817E00, // fallback: box
        };
    }
};


// === kernel/interrupt.zig ===

//! Grain Basin Interrupt Controller
//! Why: Handle interrupts (timer, external, software) for kernel.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Interrupt type (RISC-V interrupt types).
/// Why: Explicit interrupt types for type safety.
pub const InterruptType = enum(u32) {
    /// Software interrupt (from other cores or software).
    software = 1,
    /// Timer interrupt (from SBI timer or hardware timer).
    timer = 5,
    /// External interrupt (from devices, keyboard, mouse, etc.).
    external = 9,
};

/// Interrupt handler function type.
/// Why: Type-safe interrupt handler registration.
/// Contract: Handler must be fast, non-blocking, and return void.
pub const InterruptHandler = *const fn (interrupt_type: InterruptType,
context: ?*anyopaque) void;

/// Interrupt context (optional data for handler).
/// Why: Allow handlers to access kernel state or device data.
pub const InterruptContext = struct {
    /// Context data (opaque pointer).
    data: ?*anyopaque,
    /// Context type identifier (for type safety).
    type_id: u32,
};

/// Interrupt controller for Grain Basin kernel.
/// Why: Central interrupt handling, routing, and dispatch.
/// Grain Style: Static allocation, explicit state tracking.
pub const InterruptController = struct {
    /// Timer interrupt handler (optional).
    /// Why: Register handler for timer interrupts.
    timer_handler: ?InterruptHandler = null,
    /// Timer interrupt context (optional).
    /// Why: Pass context to timer handler.
    timer_context: ?*anyopaque = null,
    
    /// External interrupt handler (optional).
    /// Why: Register handler for external interrupts.
    external_handler: ?InterruptHandler = null,
    /// External interrupt context (optional).
    /// Why: Pass context to external handler.
    external_context: ?*anyopaque = null,
    
    /// Software interrupt handler (optional).
    /// Why: Register handler for software interrupts.
    software_handler: ?InterruptHandler = null,
    /// Software interrupt context (optional).
    /// Why: Pass context to software handler.
    software_context: ?*anyopaque = null,
    
    /// Pending interrupts (bitmask).
    /// Why: Track pending interrupts for deferred handling.
    pending: u32 = 0,
    
    /// Whether interrupt controller is initialized.
    /// Why: Track initialization state for safety.
    initialized: bool = false,
    
    /// Initialize interrupt controller.
    /// Why: Set up interrupt controller state.
    /// Contract: Must be called once at kernel boot.
    pub fn init() InterruptController {
        return InterruptController{
            .timer_handler = null,
            .timer_context = null,
            .external_handler = null,
            .external_context = null,
            .software_handler = null,
            .software_context = null,
            .pending = 0,
            .initialized = true,
        };
    }
    
    /// Register timer interrupt handler.
    /// Why: Set handler for timer interrupts.
    /// Contract: Handler must be fast, non-blocking.
    pub fn register_timer_handler(
        self: *InterruptController,
        handler: InterruptHandler,
        context: ?*anyopaque,
    ) void {
        // Assert: Interrupt controller must be initialized.
        Debug.kassert(self.initialized, "Interrupt controller not
initialized", .{});
        
        // Assert: Handler must be non-null.
        const handler_ptr = @intFromPtr(handler);
        Debug.kassert(handler_ptr != 0, "Handler is null", .{});
        
        // Register handler and context.
        self.timer_handler = handler;
        self.timer_context = context;
        
        // Assert: Handler must be registered.
        Debug.kassert(self.timer_handler != null, "Handler not
registered", .{});
    }
    
    /// Register external interrupt handler.
    /// Why: Set handler for external interrupts (devices).
    /// Contract: Handler must be fast, non-blocking.
    pub fn register_external_handler(
        self: *InterruptController,
        handler: InterruptHandler,
        context: ?*anyopaque,
    ) void {
        // Assert: Interrupt controller must be initialized.
        Debug.kassert(self.initialized, "Interrupt controller not
initialized", .{});
        
        // Assert: Handler must be non-null.
        const handler_ptr = @intFromPtr(handler);
        Debug.kassert(handler_ptr != 0, "Handler is null", .{});
        
        // Register handler and context.
        self.external_handler = handler;
        self.external_context = context;
        
        // Assert: Handler must be registered.
        Debug.kassert(self.external_handler != null, "Handler not
registered", .{});
    }
    
    /// Register software interrupt handler.
    /// Why: Set handler for software interrupts (IPC, etc.).
    /// Contract: Handler must be fast, non-blocking.
    pub fn register_software_handler(
        self: *InterruptController,
        handler: InterruptHandler,
        context: ?*anyopaque,
    ) void {
        // Assert: Interrupt controller must be initialized.
        Debug.kassert(self.initialized, "Interrupt controller not
initialized", .{});
        
        // Assert: Handler must be non-null.
        const handler_ptr = @intFromPtr(handler);
        Debug.kassert(handler_ptr != 0, "Handler is null", .{});
        
        // Register handler and context.
        self.software_handler = handler;
        self.software_context = context;
        
        // Assert: Handler must be registered.
        Debug.kassert(self.software_handler != null, "Handler not
registered", .{});
    }
    
    /// Handle interrupt (dispatch to registered handler).
    /// Why: Central interrupt dispatch, route to appropriate handler.
    /// Contract: Interrupt type must be valid, handler must be
registered.
    pub fn handle_interrupt(
        self: *InterruptController,
        interrupt_type: InterruptType,
    ) void {
        // Assert: Interrupt controller must be initialized.
        Debug.kassert(self.initialized, "Interrupt controller not
initialized", .{});
        
        // Dispatch based on interrupt type.
        switch (interrupt_type) {
            .timer => {
                if (self.timer_handler) |handler| {
                    // Assert: Handler must be non-null.
                    const handler_ptr = @intFromPtr(handler);
                    Debug.kassert(handler_ptr != 0, "Timer handler is
null", .{});
                    
                    // Call timer handler.
                    handler(interrupt_type, self.timer_context);
                }
            },
            .external => {
                if (self.external_handler) |handler| {
                    // Assert: Handler must be non-null.
                    const handler_ptr = @intFromPtr(handler);
                    Debug.kassert(handler_ptr != 0, "External handler is
null", .{});
                    
                    // Call external handler.
                    handler(interrupt_type, self.external_context);
                }
            },
            .software => {
                if (self.software_handler) |handler| {
                    // Assert: Handler must be non-null.
                    const handler_ptr = @intFromPtr(handler);
                    Debug.kassert(handler_ptr != 0, "Software handler is
null", .{});
                    
                    // Call software handler.
                    handler(interrupt_type, self.software_context);
                }
            },
        }
    }
    
    /// Mark interrupt as pending (deferred handling).
    /// Why: Allow interrupts to be handled later (e.g., in main loop).
    /// Contract: Interrupt type must be valid.
    pub fn mark_pending(self: *InterruptController, interrupt_type:
InterruptType) void {
        // Assert: Interrupt controller must be initialized.
        Debug.kassert(self.initialized, "Interrupt controller not
initialized", .{});
        
        // Set pending bit for interrupt type.
        const interrupt_id = @as(u5,
@intCast(@intFromEnum(interrupt_type)));
        self.pending |= (@as(u32, 1) << interrupt_id);
        
        // Assert: Pending bit must be set.
        Debug.kassert((self.pending & (@as(u32, 1) << interrupt_id)) !=
0, "Pending bit not set", .{});
    }
    
    /// Process pending interrupts.
    /// Why: Handle deferred interrupts in main loop.
    /// Contract: Must be called periodically (e.g., in trap loop).
    pub fn process_pending(self: *InterruptController) void {
        // Assert: Interrupt controller must be initialized.
        Debug.kassert(self.initialized, "Interrupt controller not
initialized", .{});
        
        // Process timer interrupt if pending.
        if ((self.pending & (@as(u32, 1) <<
@intFromEnum(InterruptType.timer))) != 0) {
            self.handle_interrupt(.timer);
            self.pending &= ~(@as(u32, 1) <<
@intFromEnum(InterruptType.timer));
        }
        
        // Process external interrupt if pending.
        if ((self.pending & (@as(u32, 1) <<
@intFromEnum(InterruptType.external))) != 0) {
            self.handle_interrupt(.external);
            self.pending &= ~(@as(u32, 1) <<
@intFromEnum(InterruptType.external));
        }
        
        // Process software interrupt if pending.
        if ((self.pending & (@as(u32, 1) <<
@intFromEnum(InterruptType.software))) != 0) {
            self.handle_interrupt(.software);
            self.pending &= ~(@as(u32, 1) <<
@intFromEnum(InterruptType.software));
        }
    }
    
    /// Check if interrupt is pending.
    /// Why: Query pending interrupt state.
    /// Contract: Interrupt type must be valid.
    pub fn is_pending(self: *const InterruptController, interrupt_type:
InterruptType) bool {
        // Assert: Interrupt controller must be initialized.
        Debug.kassert(self.initialized, "Interrupt controller not
initialized", .{});
        
        const interrupt_id = @as(u5,
@intCast(@intFromEnum(interrupt_type)));
        return (self.pending & (@as(u32, 1) << interrupt_id)) != 0;
    }
    
    /// Clear pending interrupt.
    /// Why: Clear pending interrupt state.
    /// Contract: Interrupt type must be valid.
    pub fn clear_pending(self: *InterruptController, interrupt_type:
InterruptType) void {
        // Assert: Interrupt controller must be initialized.
        Debug.kassert(self.initialized, "Interrupt controller not
initialized", .{});
        
        const interrupt_id = @as(u5,
@intCast(@intFromEnum(interrupt_type)));
        self.pending &= ~(@as(u32, 1) << interrupt_id);
        
        // Assert: Pending bit must be cleared.
        Debug.kassert((self.pending & (@as(u32, 1) << interrupt_id)) ==
0, "Pending bit not cleared", .{});
    }
};

// Test interrupt controller initialization.
test "interrupt controller init" {
    const controller = InterruptController.init();
    
    // Assert: Controller must be initialized.
    try std.testing.expect(controller.initialized);
    try std.testing.expect(controller.pending == 0);
    try std.testing.expect(controller.timer_handler == null);
}

// Test timer handler registration.
test "interrupt controller register timer" {
    var controller = InterruptController.init();
    
    var handler_called_ptr = struct {
        value: bool = false,
    }{};
    
    const handler: InterruptHandler = struct {
        fn handle(_: InterruptType, ctx: ?*anyopaque) void {
            if (ctx) |c| {
                const called = @as(*struct { value: bool },
@ptrCast(@alignCast(c)));
                called.value = true;
            }
        }
    }.handle;
    
    controller.register_timer_handler(handler, &handler_called_ptr);
    
    // Assert: Handler must be registered.
    try std.testing.expect(controller.timer_handler != null);
    
    // Test handler call.
    controller.handle_interrupt(.timer);
    
    // Assert: Handler must be called.
    try std.testing.expect(handler_called_ptr.value);
}

// Test pending interrupts.
test "interrupt controller pending" {
    var controller = InterruptController.init();
    
    // Mark timer interrupt as pending.
    controller.mark_pending(.timer);
    
    // Assert: Timer interrupt must be pending.
    try std.testing.expect(controller.is_pending(.timer));
    
    // Clear pending.
    controller.clear_pending(.timer);
    
    // Assert: Timer interrupt must not be pending.
    try std.testing.expect(!controller.is_pending(.timer));
}

// Test process pending interrupts.
test "interrupt controller process pending" {
    var controller = InterruptController.init();
    
    var handler_called_ptr = struct {
        value: bool = false,
    }{};
    
    const handler: InterruptHandler = struct {
        fn handle(_: InterruptType, ctx: ?*anyopaque) void {
            if (ctx) |c| {
                const called = @as(*struct { value: bool },
@ptrCast(@alignCast(c)));
                called.value = true;
            }
        }
    }.handle;
    
    controller.register_timer_handler(handler, &handler_called_ptr);
    
    // Mark timer interrupt as pending.
    controller.mark_pending(.timer);
    
    // Process pending interrupts.
    controller.process_pending();
    
    // Assert: Handler must be called.
    try std.testing.expect(handler_called_ptr.value);
    
    // Assert: Pending must be cleared.
    try std.testing.expect(!controller.is_pending(.timer));
}


// === kernel/kernel_log_buffer.zig ===

//! Kernel Log Buffer
//! Why: Store kernel log entries for userspace access via syscall.
//! Grain Style: Static allocation, bounded buffer, explicit types.

const std = @import("std");
const Debug = @import("debug.zig");
const Timer = @import("timer.zig").Timer;

/// Maximum number of log entries in buffer.
/// Why: Bounded allocation, prevent unbounded growth.
const MAX_LOG_ENTRIES: u32 = 256;

/// Maximum message length per log entry.
/// Why: Bounded message size, prevent buffer overflow.
const MAX_MESSAGE_LEN: u32 = 256;

/// Maximum source name length.
/// Why: Bounded source identifier size.
const MAX_SOURCE_LEN: u32 = 32;

/// Log level enumeration (matches debug.zig LogLevel).
/// Why: Explicit log levels for filtering.
pub const KernelLogLevel = enum(u8) {
    debug = 0,
    info = 1,
    warn = 2,
    error_lvl = 3,
};

/// Kernel log entry structure.
/// Why: Store log entry with timestamp, level, source, and message.
/// Grain Style: Explicit types, bounded size, deterministic layout.
pub const KernelLogEntry = struct {
    /// Timestamp (nanoseconds since boot).
    timestamp: u64,
    /// Log level (0=debug, 1=info, 2=warn, 3=error).
    level: u8,
    /// Source identifier (null-terminated).
    source: [MAX_SOURCE_LEN]u8,
    /// Message (null-terminated).
    message: [MAX_MESSAGE_LEN]u8,
    
    /// Initialize empty log entry.
    /// Why: Explicit initialization, prevent uninitialized fields.
    pub fn init() KernelLogEntry {
        return KernelLogEntry{
            .timestamp = 0,
            .level = 0,
            .source = [_]u8{0} ** MAX_SOURCE_LEN,
            .message = [_]u8{0} ** MAX_MESSAGE_LEN,
        };
    }
};

/// Kernel log buffer.
/// Why: Store kernel log entries for userspace access.
/// Grain Style: Static allocation, circular buffer, bounded size.
pub const KernelLogBuffer = struct {
    /// Log entries (circular buffer).
    entries: [MAX_LOG_ENTRIES]KernelLogEntry,
    /// Write index (next entry to write).
    write_index: u32,
    /// Entry count (number of valid entries, up to MAX_LOG_ENTRIES).
    entry_count: u32,
    /// Timer reference for timestamps.
    timer: *const Timer,
    
    /// Initialize log buffer.
    /// Why: Explicit initialization, clear state.
    pub fn init(timer: *const Timer) KernelLogBuffer {
        return KernelLogBuffer{
            .entries = [_]KernelLogEntry{KernelLogEntry.init()} **
MAX_LOG_ENTRIES,
            .write_index = 0,
            .entry_count = 0,
            .timer = timer,
        };
    }
    
    /// Add log entry to buffer.
    /// Why: Store log entry for userspace access.
    /// Contract: source and message must be null-terminated, within
size limits.
    pub fn add_entry(
        self: *KernelLogBuffer,
        level: KernelLogLevel,
        source: []const u8,
        message: []const u8,
    ) void {
        // Assert: source length must be within bounds.
        Debug.kassert(source.len < MAX_SOURCE_LEN, "Source too long",
.{});
        
        // Assert: message length must be within bounds.
        Debug.kassert(message.len < MAX_MESSAGE_LEN, "Message too long",
.{});
        
        // Get current timestamp.
        const timestamp = self.timer.get_uptime_ns();
        
        // Get entry at write index.
        const idx = self.write_index;
        var entry = &self.entries[idx];
        
        // Initialize entry.
        entry.timestamp = timestamp;
        entry.level = @intFromEnum(level);
        
        // Copy source (null-terminated).
        var i: u32 = 0;
        while (i < source.len and i < MAX_SOURCE_LEN - 1) : (i += 1) {
            entry.source[i] = source[i];
        }
        entry.source[i] = 0;
        
        // Copy message (null-terminated).
        i = 0;
        while (i < message.len and i < MAX_MESSAGE_LEN - 1) : (i += 1) {
            entry.message[i] = message[i];
        }
        entry.message[i] = 0;
        
        // Update write index (circular buffer).
        self.write_index = (self.write_index + 1) % MAX_LOG_ENTRIES;
        
        // Update entry count (bounded by MAX_LOG_ENTRIES).
        if (self.entry_count < MAX_LOG_ENTRIES) {
            self.entry_count += 1;
        }
    }
    
    /// Get number of log entries.
    /// Why: Return entry count for userspace.
    pub fn get_entry_count(self: *const KernelLogBuffer) u32 {
        return self.entry_count;
    }
    
    /// Get log entry by index (0-based, oldest first).
    /// Why: Allow userspace to read entries sequentially.
    /// Returns: null if index is out of range, otherwise pointer to
entry.
    pub fn get_entry(self: *const KernelLogBuffer, index: u32) ?*const
KernelLogEntry {
        if (index >= self.entry_count) {
            return null;
        }
        
        // Calculate actual index in circular buffer.
        // Oldest entry is at (write_index - entry_count) %
MAX_LOG_ENTRIES.
        const start_idx = if (self.entry_count == MAX_LOG_ENTRIES) 
            self.write_index 
        else 
            0;
        const actual_idx = (start_idx + index) % MAX_LOG_ENTRIES;
        
        return &self.entries[actual_idx];
    }
};


// === kernel/keyboard.zig ===

//! Grain Basin Keyboard Driver
//! Why: Kernel-side keyboard state tracking and key code abstraction.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Maximum number of keys to track.
/// Why: Bounded key state table for safety and static allocation.
pub const MAX_KEYS: u32 = 256;

/// Key code type.
/// Why: Explicit key code type for type safety.
pub const KeyCode = u32;

/// Key state (pressed or released).
/// Why: Explicit key state enumeration.
pub const KeyState = enum(u8) {
    released = 0,
    pressed = 1,
};

/// Keyboard driver state.
/// Why: Track keyboard state for kernel input handling.
/// Grain Style: Static allocation, bounded key state table.
pub const Keyboard = struct {
    /// Key state table (pressed/released for each key).
    /// Why: Track which keys are currently pressed.
    /// Grain Style: Static allocation, max 256 keys.
    key_states: [MAX_KEYS]KeyState,
    
    /// Last key code pressed (0 if none).
    /// Why: Track most recent key press for polling.
    last_key_code: KeyCode,
    
    /// Last key state change (pressed or released).
    /// Why: Track most recent key state change.
    last_key_state: KeyState,
    
    /// Initialize keyboard driver.
    /// Why: Set up keyboard state.
    pub fn init() Keyboard {
        return Keyboard{
            .key_states = [_]KeyState{.released} ** MAX_KEYS,
            .last_key_code = 0,
            .last_key_state = .released,
        };
    }
    
    /// Handle key press event.
    /// Why: Update keyboard state when key is pressed.
    /// Contract: key_code must be < MAX_KEYS.
    pub fn handle_key_press(self: *Keyboard, key_code: KeyCode) void {
        // Assert: Key code must be < MAX_KEYS.
        Debug.kassert(key_code < MAX_KEYS, "Key code >= MAX_KEYS", .{});
        
        // Update key state.
        self.key_states[key_code] = .pressed;
        self.last_key_code = key_code;
        self.last_key_state = .pressed;
        
        // Assert: Key state must be updated.
        Debug.kassert(self.key_states[key_code] == .pressed, "Key state
not pressed", .{});
        Debug.kassert(self.last_key_code == key_code, "Last key code
mismatch", .{});
    }
    
    /// Handle key release event.
    /// Why: Update keyboard state when key is released.
    /// Contract: key_code must be < MAX_KEYS.
    pub fn handle_key_release(self: *Keyboard, key_code: KeyCode) void {
        // Assert: Key code must be < MAX_KEYS.
        Debug.kassert(key_code < MAX_KEYS, "Key code >= MAX_KEYS", .{});
        
        // Update key state.
        self.key_states[key_code] = .released;
        self.last_key_code = key_code;
        self.last_key_state = .released;
        
        // Assert: Key state must be updated.
        Debug.kassert(self.key_states[key_code] == .released, "Key state
not released", .{});
        Debug.kassert(self.last_key_code == key_code, "Last key code
mismatch", .{});
    }
    
    /// Check if key is pressed.
    /// Why: Query key state for polling.
    /// Contract: key_code must be < MAX_KEYS.
    /// Returns: true if key is pressed, false otherwise.
    pub fn is_key_pressed(self: *const Keyboard, key_code: KeyCode) bool
{
        // Assert: Key code must be < MAX_KEYS.
        Debug.kassert(key_code < MAX_KEYS, "Key code >= MAX_KEYS", .{});
        
        const pressed = self.key_states[key_code] == .pressed;
        
        // Assert: Result must be consistent with key state.
        Debug.kassert(pressed == (self.key_states[key_code] ==
.pressed), "Key state inconsistent", .{});
        
        return pressed;
    }
    
    /// Get last key code.
    /// Why: Query most recent key press for polling.
    /// Returns: Last key code (0 if none).
    pub fn get_last_key_code(self: *const Keyboard) KeyCode {
        // Assert: Last key code must be < MAX_KEYS or 0.
        Debug.kassert(self.last_key_code < MAX_KEYS or
self.last_key_code == 0, "Last key code invalid", .{});
        
        return self.last_key_code;
    }
    
    /// Get last key state.
    /// Why: Query most recent key state change for polling.
    /// Returns: Last key state (pressed or released).
    pub fn get_last_key_state(self: *const Keyboard) KeyState {
        // Assert: Last key state must be valid.
        Debug.kassert(self.last_key_state == .pressed or
self.last_key_state == .released, "Last key state invalid", .{});
        
        return self.last_key_state;
    }
    
    /// Clear all key states.
    /// Why: Reset keyboard state (e.g., on driver reset).
    pub fn clear_all(self: *Keyboard) void {
        // Clear all key states.
        for (0..MAX_KEYS) |i| {
            self.key_states[i] = .released;
        }
        self.last_key_code = 0;
        self.last_key_state = .released;
        
        // Assert: All keys must be released.
        for (0..MAX_KEYS) |i| {
            Debug.kassert(self.key_states[i] == .released, "Key not
released", .{});
        }
        Debug.kassert(self.last_key_code == 0, "Last key code not 0",
.{});
    }
};

// Test keyboard initialization.
test "keyboard init" {
    const keyboard = Keyboard.init();
    
    // Assert: Keyboard must be initialized.
    try std.testing.expect(keyboard.last_key_code == 0);
    try std.testing.expect(keyboard.last_key_state == .released);
    
    // Assert: All keys must be released.
    for (0..MAX_KEYS) |i| {
        try std.testing.expect(keyboard.key_states[i] == .released);
    }
}

// Test key press.
test "keyboard key press" {
    var keyboard = Keyboard.init();
    
    const key_code: KeyCode = 65; // 'A' key
    keyboard.handle_key_press(key_code);
    
    // Assert: Key must be pressed.
    try std.testing.expect(keyboard.is_key_pressed(key_code));
    try std.testing.expect(keyboard.get_last_key_code() == key_code);
    try std.testing.expect(keyboard.get_last_key_state() == .pressed);
}

// Test key release.
test "keyboard key release" {
    var keyboard = Keyboard.init();
    
    const key_code: KeyCode = 65; // 'A' key
    keyboard.handle_key_press(key_code);
    keyboard.handle_key_release(key_code);
    
    // Assert: Key must be released.
    try std.testing.expect(!keyboard.is_key_pressed(key_code));
    try std.testing.expect(keyboard.get_last_key_code() == key_code);
    try std.testing.expect(keyboard.get_last_key_state() == .released);
}

// Test multiple keys.
test "keyboard multiple keys" {
    var keyboard = Keyboard.init();
    
    const key1: KeyCode = 65; // 'A'
    const key2: KeyCode = 66; // 'B'
    
    keyboard.handle_key_press(key1);
    keyboard.handle_key_press(key2);
    
    // Assert: Both keys must be pressed.
    try std.testing.expect(keyboard.is_key_pressed(key1));
    try std.testing.expect(keyboard.is_key_pressed(key2));
    try std.testing.expect(keyboard.get_last_key_code() == key2);
    
    keyboard.handle_key_release(key1);
    
    // Assert: Key1 released, key2 still pressed.
    try std.testing.expect(!keyboard.is_key_pressed(key1));
    try std.testing.expect(keyboard.is_key_pressed(key2));
}

// Test clear all.
test "keyboard clear all" {
    var keyboard = Keyboard.init();
    
    keyboard.handle_key_press(65);
    keyboard.handle_key_press(66);
    keyboard.clear_all();
    
    // Assert: All keys must be released.
    try std.testing.expect(!keyboard.is_key_pressed(65));
    try std.testing.expect(!keyboard.is_key_pressed(66));
    try std.testing.expect(keyboard.get_last_key_code() == 0);
}


// === kernel/main.zig ===

const Panic = @import("panic.zig");
const Trap = @import("trap.zig");
const BasinKernel = @import("basin_kernel.zig").BasinKernel;
const Debug = @import("debug.zig");
const Framebuffer = @import("framebuffer.zig").Framebuffer;
const boot = @import("boot.zig");

// Global kernel instance
var kernel: BasinKernel = undefined;

// Global framebuffer (initialized in kmain)
// Why: Static allocation for framebuffer state.
var framebuffer: ?Framebuffer = null;

pub export fn kmain() noreturn {
    // 1. Early boot banner (serial output)
    Debug.kprint("\n", .{});
    Debug.kprint("   ______           _          ____  _____\n", .{});
    Debug.kprint("  / ____/________ _(_)___     / __ \\/ ___/\n", .{});
    Debug.kprint(" / / __/ ___/ __ `/ / __ \\   / / / /\\__ \\ \n", .{});
    Debug.kprint("/ /_/ / /  / /_/ / / / / /  / /_/ /___/ / \n", .{});
    Debug.kprint("\\____/_/   \\__,_/_/_/ /_/   \\____//____/  \n", .{});
    Debug.kprint("                                          \n", .{});
    Debug.kprint("Grain Basin Kernel v0.1.0 (RISC-V64)\n", .{});
    Debug.kprint("Copyright (c) 2025 Team Carry\n\n", .{});

    // 2. Initialize Kernel
    Debug.log(.info, "Initializing Basin...", .{});
    kernel = BasinKernel.init();
    
    // 3. Execute boot sequence (validate all subsystems initialized).
    // Why: Ensure all subsystems are initialized in correct order.
    boot.boot_kernel(&kernel);
    
    Debug.log(.info, "Users initialized: {d}", .{kernel.user_count});

    // 4. Initialize framebuffer (access at 0x90000000)
    // Why: Display boot messages and kernel output on screen.
    // Note: Framebuffer memory is mapped by VM at 0x90000000.
    // The kernel accesses it via store instructions, which the VM
translates.
    // For now, framebuffer is initialized host-side by
VM.init_framebuffer().
    // Kernel can write to it via store instructions to 0x90000000+
addresses.
    // Note: Direct pointer access in kernel requires unsafe code.
    // We'll use a syscall-based approach for kernel framebuffer access
in the future.
    
    Debug.log(.info, "Framebuffer available at 0x90000000 (initialized
by VM).", .{});
    Debug.log(.info, "System ready. Entering trap loop.", .{});

    // 5. Enter trap loop (handles interrupts and exceptions)
    // Why: Process pending interrupts and handle exceptions in main
loop.
    Trap.loop_with_kernel(&kernel);
}

// === kernel/memory.zig ===

//! Grain Basin Memory Allocator
//! Why: Kernel-side memory allocation with page-based management.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Page size in bytes (4KB, standard RISC-V page size).
/// Why: Standard page size for RISC-V architecture.
pub const PAGE_SIZE: u64 = 4096;

/// Maximum number of pages to track.
/// Why: Bounded page table for safety and static allocation.
pub const MAX_PAGES: u32 = 1024;

/// Maximum memory pool size (4MB, matches VM memory size).
/// Why: Bounded memory pool for kernel allocations.
pub const MAX_POOL_SIZE: u64 = 4 * 1024 * 1024;

/// Page state (free or allocated).
/// Why: Explicit page state enumeration.
pub const PageState = enum(u8) {
    free = 0,
    allocated = 1,
};

/// Memory pool for kernel allocations.
/// Why: Provide kernel-side memory allocation without external
allocator.
/// Grain Style: Static allocation, bounded pool, explicit types.
pub const MemoryPool = struct {
    /// Memory pool buffer (static allocation).
    /// Why: Pre-allocated memory for kernel use.
    /// Grain Style: Static allocation, max 4MB.
    buffer: [MAX_POOL_SIZE]u8,
    
    /// Page state table (tracks which pages are allocated).
    /// Why: Track page allocation state for management.
    /// Grain Style: Static allocation, max 1024 pages.
    page_states: [MAX_PAGES]PageState,
    
    /// Number of allocated pages.
    /// Why: Track allocation count for bounds checking.
    allocated_pages: u32,
    
    /// Next free page index (for simple allocation).
    /// Why: Track allocation position for sequential allocation.
    next_free_page: u32,
    
    /// Initialize memory pool.
    /// Why: Set up memory pool state.
    pub fn init() MemoryPool {
        return MemoryPool{
            .buffer = [_]u8{0} ** MAX_POOL_SIZE,
            .page_states = [_]PageState{.free} ** MAX_PAGES,
            .allocated_pages = 0,
            .next_free_page = 0,
        };
    }
    
    /// Allocate pages.
    /// Why: Allocate contiguous pages for kernel use.
    /// Contract: num_pages must be > 0, <= MAX_PAGES.
    /// Returns: Page index if allocated, null if insufficient pages.
    pub fn allocate_pages(self: *MemoryPool, num_pages: u32) ?u32 {
        // Assert: Number of pages must be > 0.
        if (num_pages == 0) {
            return null; // Invalid request
        }
        
        // Assert: Number of pages must be <= MAX_PAGES.
        if (num_pages > MAX_PAGES) {
            return null; // Too many pages
        }
        
        // Assert: Allocated pages must be <= MAX_PAGES.
        Debug.kassert(self.allocated_pages <= MAX_PAGES, "Allocated
pages > MAX", .{});
        
        // Find contiguous free pages (simple first-fit algorithm).
        var start_page: ?u32 = null;
        var consecutive_free: u32 = 0;
        
        for (0..MAX_PAGES) |i| {
            const page_idx = @as(u32, @intCast(i));
            
            if (self.page_states[page_idx] == .free) {
                if (consecutive_free == 0) {
                    start_page = page_idx;
                }
                consecutive_free += 1;
                
                if (consecutive_free >= num_pages) {
                    break; // Found enough contiguous pages
                }
            } else {
                consecutive_free = 0;
                start_page = null;
            }
        }
        
        if (start_page == null or consecutive_free < num_pages) {
            return null; // Insufficient contiguous pages
        }
        
        const start = start_page.?;
        
        // Mark pages as allocated.
        for (0..num_pages) |i| {
            const page_idx = start + @as(u32, @intCast(i));
            self.page_states[page_idx] = .allocated;
        }
        
        self.allocated_pages += num_pages;
        
        // Assert: Pages must be allocated.
        for (0..num_pages) |i| {
            const page_idx = start + @as(u32, @intCast(i));
            Debug.kassert(self.page_states[page_idx] == .allocated,
"Page not allocated", .{});
        }
        Debug.kassert(self.allocated_pages <= MAX_PAGES, "Allocated
pages > MAX", .{});
        
        return start;
    }
    
    /// Deallocate pages.
    /// Why: Free pages for reuse.
    /// Contract: start_page must be valid, num_pages must be > 0.
    /// Returns: true if deallocated, false if invalid.
    pub fn deallocate_pages(self: *MemoryPool, start_page: u32,
num_pages: u32) bool {
        // Assert: Start page must be < MAX_PAGES.
        if (start_page >= MAX_PAGES) {
            return false; // Invalid page index
        }
        
        // Assert: Number of pages must be > 0.
        if (num_pages == 0) {
            return false; // Invalid request
        }
        
        // Assert: End page must be <= MAX_PAGES.
        if (start_page + num_pages > MAX_PAGES) {
            return false; // Out of bounds
        }
        
        // Assert: Allocated pages must be >= num_pages.
        Debug.kassert(self.allocated_pages >= num_pages, "Allocated
pages < num_pages", .{});
        
        // Mark pages as free.
        for (0..num_pages) |i| {
            const page_idx = start_page + @as(u32, @intCast(i));
            
            // Assert: Page must be allocated before deallocation.
            if (self.page_states[page_idx] != .allocated) {
                return false; // Page not allocated
            }
            
            self.page_states[page_idx] = .free;
        }
        
        self.allocated_pages -= num_pages;
        
        // Assert: Pages must be freed.
        for (0..num_pages) |i| {
            const page_idx = start_page + @as(u32, @intCast(i));
            Debug.kassert(self.page_states[page_idx] == .free, "Page not
freed", .{});
        }
        Debug.kassert(self.allocated_pages <= MAX_PAGES, "Allocated
pages > MAX", .{});
        
        return true;
    }
    
    /// Get page address.
    /// Why: Convert page index to physical address.
    /// Contract: page_idx must be < MAX_PAGES.
    /// Returns: Physical address of page.
    pub fn get_page_address(self: *const MemoryPool, page_idx: u32) u64 {
        _ = self; // Unused, but kept for consistency
        
        // Assert: Page index must be < MAX_PAGES.
        Debug.kassert(page_idx < MAX_PAGES, "Page idx >= MAX_PAGES",
.{});
        
        // Calculate physical address (page index * PAGE_SIZE).
        const address = @as(u64, page_idx) * PAGE_SIZE;
        
        // Assert: Address must be within pool bounds.
        Debug.kassert(address < MAX_POOL_SIZE, "Address >=
MAX_POOL_SIZE", .{});
        
        return address;
    }
    
    /// Get allocated page count.
    /// Why: Query number of allocated pages.
    /// Returns: Number of allocated pages.
    pub fn get_allocated_pages(self: *const MemoryPool) u32 {
        // Assert: Allocated pages must be <= MAX_PAGES.
        Debug.kassert(self.allocated_pages <= MAX_PAGES, "Allocated
pages > MAX", .{});
        
        return self.allocated_pages;
    }
    
    /// Get free page count.
    /// Why: Query number of free pages.
    /// Returns: Number of free pages.
    pub fn get_free_pages(self: *const MemoryPool) u32 {
        // Assert: Allocated pages must be <= MAX_PAGES.
        Debug.kassert(self.allocated_pages <= MAX_PAGES, "Allocated
pages > MAX", .{});
        
        const free = MAX_PAGES - self.allocated_pages;
        
        // Assert: Free pages must be <= MAX_PAGES.
        Debug.kassert(free <= MAX_PAGES, "Free pages > MAX", .{});
        
        return free;
    }
    
    /// Allocate memory (convenience function).
    /// Why: Allocate memory in bytes (converts to pages).
    /// Contract: size must be > 0, <= MAX_POOL_SIZE.
    /// Returns: Page index if allocated, null if insufficient memory.
    pub fn allocate(self: *MemoryPool, size: u64) ?u32 {
        // Assert: Size must be > 0.
        if (size == 0) {
            return null; // Invalid request
        }
        
        // Assert: Size must be <= MAX_POOL_SIZE.
        if (size > MAX_POOL_SIZE) {
            return null; // Too large
        }
        
        // Calculate number of pages needed (round up).
        const num_pages = @as(u32, @intCast((size + PAGE_SIZE - 1) /
PAGE_SIZE));
        
        // Assert: Number of pages must be <= MAX_PAGES.
        Debug.kassert(num_pages <= MAX_PAGES, "Num pages > MAX", .{});
        
        return self.allocate_pages(num_pages);
    }
    
    /// Deallocate memory (convenience function).
    /// Why: Deallocate memory in bytes (converts to pages).
    /// Contract: start_page must be valid, size must be > 0.
    /// Returns: true if deallocated, false if invalid.
    pub fn deallocate(self: *MemoryPool, start_page: u32, size: u64)
bool {
        // Assert: Size must be > 0.
        if (size == 0) {
            return false; // Invalid request
        }
        
        // Calculate number of pages (round up).
        const num_pages = @as(u32, @intCast((size + PAGE_SIZE - 1) /
PAGE_SIZE));
        
        // Assert: Number of pages must be <= MAX_PAGES.
        Debug.kassert(num_pages <= MAX_PAGES, "Num pages > MAX", .{});
        
        return self.deallocate_pages(start_page, num_pages);
    }
};

// Test memory pool initialization.
test "memory pool init" {
    const pool = MemoryPool.init();
    
    // Assert: Pool must be initialized.
    try std.testing.expect(pool.allocated_pages == 0);
    try std.testing.expect(pool.get_free_pages() == MAX_PAGES);
    
    // Assert: All pages must be free.
    for (0..MAX_PAGES) |i| {
        try std.testing.expect(pool.page_states[i] == .free);
    }
}

// Test page allocation.
test "memory pool allocate pages" {
    var pool = MemoryPool.init();
    
    const page_idx = pool.allocate_pages(1);
    
    // Assert: Page must be allocated.
    try std.testing.expect(page_idx != null);
    try std.testing.expect(pool.get_allocated_pages() == 1);
    try std.testing.expect(pool.get_free_pages() == MAX_PAGES - 1);
}

// Test page deallocation.
test "memory pool deallocate pages" {
    var pool = MemoryPool.init();
    
    const page_idx = pool.allocate_pages(1);
    try std.testing.expect(page_idx != null);
    
    const deallocated = pool.deallocate_pages(page_idx.?, 1);
    
    // Assert: Page must be deallocated.
    try std.testing.expect(deallocated);
    try std.testing.expect(pool.get_allocated_pages() == 0);
    try std.testing.expect(pool.get_free_pages() == MAX_PAGES);
}

// Test multiple page allocation.
test "memory pool multiple pages" {
    var pool = MemoryPool.init();
    
    const page1 = pool.allocate_pages(2);
    const page2 = pool.allocate_pages(3);
    
    // Assert: Both allocations must succeed.
    try std.testing.expect(page1 != null);
    try std.testing.expect(page2 != null);
    try std.testing.expect(page1.? != page2.?);
    try std.testing.expect(pool.get_allocated_pages() == 5);
}

// Test page address calculation.
test "memory pool page address" {
    var pool = MemoryPool.init();
    
    const page_idx: u32 = 10;
    const address = pool.get_page_address(page_idx);
    
    // Assert: Address must be correct.
    try std.testing.expect(address == page_idx * PAGE_SIZE);
}

// Test allocate convenience function.
test "memory pool allocate bytes" {
    var pool = MemoryPool.init();
    
    const page_idx = pool.allocate(8192); // 2 pages
    
    // Assert: Allocation must succeed.
    try std.testing.expect(page_idx != null);
    try std.testing.expect(pool.get_allocated_pages() >= 2);
}

// Test deallocate convenience function.
test "memory pool deallocate bytes" {
    var pool = MemoryPool.init();
    
    const page_idx = pool.allocate(8192);
    try std.testing.expect(page_idx != null);
    
    const deallocated = pool.deallocate(page_idx.?, 8192);
    
    // Assert: Deallocation must succeed.
    try std.testing.expect(deallocated);
    try std.testing.expect(pool.get_allocated_pages() == 0);
}


// === kernel/memory_stats.zig ===

//! Memory Usage Statistics Tracking System
//!
//! Objective: Track memory usage, mapped pages, and allocation patterns
for monitoring and debugging.
//! Why: Monitor memory consumption, identify memory leaks, validate
memory management, and optimize memory usage.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track total memory size and used memory
//! - Track number of mapped pages and unmapped pages
//! - Track memory allocation patterns (by permission type)
//! - Track memory fragmentation metrics
//! - Provide statistics interface for querying memory data
//! - Reset capability for new measurement periods
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-01-XX
//! GrainStyle: Comprehensive memory tracking, deterministic behavior,
explicit limits

const std = @import("std");
const Debug = @import("debug.zig");

/// Page size (4KB, standard RISC-V page size).
/// Why: Explicit constant for page size, matches RISC-V standard.
const PAGE_SIZE: u64 = 4096;

/// Maximum number of pages in VM memory (4MB / 4KB = 1024 pages).
/// Why: Bounded allocation, prevents unbounded growth.
const MAX_PAGES: u32 = 1024;

/// Memory usage statistics tracker.
/// Why: Track memory usage, mapped pages, and allocation patterns for
monitoring.
/// GrainStyle: Explicit types, bounded counters, deterministic tracking.
pub const MemoryStats = struct {
    /// Total memory size in bytes.
    /// Why: Track total available memory.
    total_memory_bytes: u64 = 0,
    
    /// Number of mapped pages.
    /// Why: Track how many pages are currently mapped.
    mapped_pages: u32 = 0,
    
    /// Number of unmapped pages.
    /// Why: Track how many pages are available for allocation.
    unmapped_pages: u32 = 0,
    
    /// Pages with read permission.
    /// Why: Track memory allocation by permission type.
    pages_read: u32 = 0,
    
    /// Pages with write permission.
    /// Why: Track memory allocation by permission type.
    pages_write: u32 = 0,
    
    /// Pages with execute permission.
    /// Why: Track memory allocation by permission type.
    pages_execute: u32 = 0,
    
    /// Total number of memory mappings.
    /// Why: Track number of distinct memory regions allocated.
    total_mappings: u32 = 0,
    
    /// Whether statistics tracker is initialized.
    /// Why: Track initialization state for safety.
    initialized: bool = false,
    
    /// Initialize memory statistics tracker.
    /// Why: Set up statistics tracker state.
    /// Contract: Must be called once before use.
    pub fn init() MemoryStats {
        return MemoryStats{
            .total_memory_bytes = 0,
            .mapped_pages = 0,
            .unmapped_pages = MAX_PAGES,
            .pages_read = 0,
            .pages_write = 0,
            .pages_execute = 0,
            .total_mappings = 0,
            .initialized = true,
        };
    }
    
    /// Update statistics from page table.
    /// Why: Refresh statistics based on current page table state.
    /// Contract: Page table must be valid, statistics tracker must be
initialized.
    /// Note: Uses type-erased pointer to avoid circular dependencies
with page_table module.
    pub fn update_from_page_table(
        self: *MemoryStats,
        page_table_ptr: *const anyopaque,
        total_memory_bytes: u64,
    ) void {
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(self.initialized, "Memory stats not initialized",
.{});
        
        // Assert: Page table pointer must be valid (precondition).
        const table_ptr = @intFromPtr(page_table_ptr);
        Debug.kassert(table_ptr != 0, "Page table ptr is null", .{});
        
        // Assert: Total memory must be valid (precondition).
        Debug.kassert(total_memory_bytes > 0, "Total memory is zero",
.{});
        Debug.kassert(total_memory_bytes <= 4 * 1024 * 1024, "Total
memory exceeds 4MB", .{});
        
        // Reset counters.
        self.total_memory_bytes = total_memory_bytes;
        self.mapped_pages = 0;
        self.unmapped_pages = 0;
        self.pages_read = 0;
        self.pages_write = 0;
        self.pages_execute = 0;
        
        // Count pages by state and permissions.
        // Note: We access the page table structure directly via pointer
casting to avoid circular dependencies.
        // The page table structure has a 'pages' field at offset 0
which is an array of PageEntry.
        // PageEntry structure: { flags: { read, write, execute, shared,
_padding }, mapped: bool }
        const PageEntry = struct {
            flags: struct {
                read: bool,
                write: bool,
                execute: bool,
                shared: bool,
                _padding: u28,
            },
            mapped: bool,
        };
        
        // Access page table pages via type-erased pointer (pages array
is at offset 0).
        const pages_ptr = @as(*const [MAX_PAGES]PageEntry,
@ptrCast(@alignCast(page_table_ptr)));
        
        // Count pages by state and permissions.
        for (pages_ptr.*) |page| {
            if (page.mapped) {
                self.mapped_pages += 1;
                
                // Count permissions.
                if (page.flags.read) {
                    self.pages_read += 1;
                }
                if (page.flags.write) {
                    self.pages_write += 1;
                }
                if (page.flags.execute) {
                    self.pages_execute += 1;
                }
            } else {
                self.unmapped_pages += 1;
            }
        }
        
        // Assert: Page counts must be consistent (postcondition).
        Debug.kassert(self.mapped_pages + self.unmapped_pages ==
MAX_PAGES, "Page count mismatch", .{});
        Debug.kassert(self.mapped_pages <= MAX_PAGES, "Mapped pages
exceed max", .{});
        Debug.kassert(self.unmapped_pages <= MAX_PAGES, "Unmapped pages
exceed max", .{});
    }
    
    /// Update statistics from mapping count.
    /// Why: Track number of distinct memory mappings.
    /// Contract: Mapping count must be valid.
    pub fn update_mapping_count(self: *MemoryStats, mapping_count: u32)
void {
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(self.initialized, "Memory stats not initialized",
.{});
        
        // Assert: Mapping count must be valid (precondition).
        Debug.kassert(mapping_count <= 256, "Mapping count exceeds max",
.{});
        
        self.total_mappings = mapping_count;
        
        // Assert: Mapping count must be set correctly (postcondition).
        Debug.kassert(self.total_mappings == mapping_count, "Mapping
count not set", .{});
    }
    
    /// Get memory usage percentage.
    /// Why: Calculate memory usage as percentage of total.
    /// Returns: Memory usage percentage (0.0 to 100.0).
    pub fn get_usage_percentage(self: *const MemoryStats) f64 {
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(self.initialized, "Memory stats not initialized",
.{});
        
        if (self.total_memory_bytes == 0) {
            return 0.0;
        }
        
        const mapped_bytes = @as(u64, self.mapped_pages) * PAGE_SIZE;
        const usage_percent = (@as(f64, @floatFromInt(mapped_bytes)) *
100.0) / @as(f64, @floatFromInt(self.total_memory_bytes));
        
        // Assert: Usage percentage must be valid (postcondition).
        Debug.kassert(usage_percent >= 0.0, "Usage percentage negative",
.{});
        Debug.kassert(usage_percent <= 100.0, "Usage percentage exceeds
100", .{});
        
        return usage_percent;
    }
    
    /// Get memory fragmentation metric.
    /// Why: Calculate memory fragmentation (ratio of unmapped pages to
total pages).
    /// Returns: Fragmentation ratio (0.0 to 1.0, higher = more
fragmented).
    pub fn get_fragmentation_ratio(self: *const MemoryStats) f64 {
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(self.initialized, "Memory stats not initialized",
.{});
        
        if (MAX_PAGES == 0) {
            return 0.0;
        }
        
        const fragmentation = @as(f64,
@floatFromInt(self.unmapped_pages)) / @as(f64, @floatFromInt(MAX_PAGES));
        
        // Assert: Fragmentation ratio must be valid (postcondition).
        Debug.kassert(fragmentation >= 0.0, "Fragmentation ratio
negative", .{});
        Debug.kassert(fragmentation <= 1.0, "Fragmentation ratio exceeds
1", .{});
        
        return fragmentation;
    }
    
    /// Reset memory statistics.
    /// Why: Clear statistics for new measurement period.
    pub fn reset(self: *MemoryStats) void {
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(self.initialized, "Memory stats not initialized",
.{});
        
        // Reset all counters.
        self.total_memory_bytes = 0;
        self.mapped_pages = 0;
        self.unmapped_pages = MAX_PAGES;
        self.pages_read = 0;
        self.pages_write = 0;
        self.pages_execute = 0;
        self.total_mappings = 0;
        
        // Assert: All counters must be reset (postcondition).
        Debug.kassert(self.mapped_pages == 0, "Mapped pages not reset",
.{});
        Debug.kassert(self.unmapped_pages == MAX_PAGES, "Unmapped pages
not reset", .{});
        Debug.kassert(self.total_mappings == 0, "Total mappings not
reset", .{});
    }
};

/// Memory statistics snapshot (for diagnostics).
/// Why: Capture memory statistics at a point in time.
/// GrainStyle: Static allocation, explicit types.
pub const MemoryStatsSnapshot = struct {
    /// Total memory size in bytes.
    total_memory_bytes: u64,
    /// Number of mapped pages.
    mapped_pages: u32,
    /// Number of unmapped pages.
    unmapped_pages: u32,
    /// Pages with read permission.
    pages_read: u32,
    /// Pages with write permission.
    pages_write: u32,
    /// Pages with execute permission.
    pages_execute: u32,
    /// Total number of memory mappings.
    total_mappings: u32,
    /// Memory usage percentage.
    usage_percentage: f64,
    /// Memory fragmentation ratio.
    fragmentation_ratio: f64,
    
    /// Create memory statistics snapshot.
    /// Why: Capture current memory statistics state.
    /// Contract: Memory stats must be initialized.
    pub fn create(stats: *const MemoryStats) MemoryStatsSnapshot {
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(stats.initialized, "Memory stats not initialized",
.{});
        
        return MemoryStatsSnapshot{
            .total_memory_bytes = stats.total_memory_bytes,
            .mapped_pages = stats.mapped_pages,
            .unmapped_pages = stats.unmapped_pages,
            .pages_read = stats.pages_read,
            .pages_write = stats.pages_write,
            .pages_execute = stats.pages_execute,
            .total_mappings = stats.total_mappings,
            .usage_percentage = stats.get_usage_percentage(),
            .fragmentation_ratio = stats.get_fragmentation_ratio(),
        };
    }
    
    /// Print memory statistics snapshot.
    /// Why: Display memory statistics for debugging.
    pub fn print(self: *const MemoryStatsSnapshot) void {
        // Assert: Snapshot must be valid (precondition).
        const self_ptr = @intFromPtr(self);
        Debug.kassert(self_ptr != 0, "Snapshot ptr is null", .{});
        Debug.kassert(self_ptr % @alignOf(MemoryStatsSnapshot) == 0,
"Snapshot ptr unaligned", .{});
        
        Debug.kprint("Memory Statistics:\n", .{});
        Debug.kprint("  Total memory: {d} bytes\n",
.{self.total_memory_bytes});
        Debug.kprint("  Mapped pages: {d}\n", .{self.mapped_pages});
        Debug.kprint("  Unmapped pages: {d}\n", .{self.unmapped_pages});
        Debug.kprint("  Pages with read: {d}\n", .{self.pages_read});
        Debug.kprint("  Pages with write: {d}\n", .{self.pages_write});
        Debug.kprint("  Pages with execute: {d}\n",
.{self.pages_execute});
        Debug.kprint("  Total mappings: {d}\n", .{self.total_mappings});
        Debug.kprint("  Usage percentage: {d:.2}%\n",
.{self.usage_percentage});
        Debug.kprint("  Fragmentation ratio: {d:.3}\n",
.{self.fragmentation_ratio});
    }
};


// === kernel/mouse.zig ===

//! Grain Basin Mouse Driver
//! Why: Kernel-side mouse state tracking (position, buttons).
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Maximum mouse X coordinate.
/// Why: Bounded mouse position for safety.
pub const MAX_MOUSE_X: u32 = 65535;

/// Maximum mouse Y coordinate.
/// Why: Bounded mouse position for safety.
pub const MAX_MOUSE_Y: u32 = 65535;

/// Mouse button type.
/// Why: Explicit mouse button enumeration.
pub const MouseButton = enum(u8) {
    left = 0,
    right = 1,
    middle = 2,
    button4 = 3,
    button5 = 4,
};

/// Mouse button state (pressed or released).
/// Why: Explicit button state enumeration.
pub const ButtonState = enum(u8) {
    released = 0,
    pressed = 1,
};

/// Maximum number of mouse buttons.
/// Why: Bounded button state table for safety.
pub const MAX_BUTTONS: u32 = 5;

/// Mouse driver state.
/// Why: Track mouse state for kernel input handling.
/// Grain Style: Static allocation, bounded button state table.
pub const Mouse = struct {
    /// Current X coordinate (0 to MAX_MOUSE_X).
    x: u32,
    
    /// Current Y coordinate (0 to MAX_MOUSE_Y).
    y: u32,
    
    /// Button states (pressed/released for each button).
    /// Why: Track which buttons are currently pressed.
    /// Grain Style: Static allocation, max 5 buttons.
    button_states: [MAX_BUTTONS]ButtonState,
    
    /// Last button pressed (null if none).
    /// Why: Track most recent button press for polling.
    last_button: ?MouseButton,
    
    /// Last button state change (pressed or released).
    /// Why: Track most recent button state change.
    last_button_state: ButtonState,
    
    /// Initialize mouse driver.
    /// Why: Set up mouse state.
    pub fn init() Mouse {
        return Mouse{
            .x = 0,
            .y = 0,
            .button_states = [_]ButtonState{.released} ** MAX_BUTTONS,
            .last_button = null,
            .last_button_state = .released,
        };
    }
    
    /// Set mouse position.
    /// Why: Update mouse coordinates.
    /// Contract: x must be <= MAX_MOUSE_X, y must be <= MAX_MOUSE_Y.
    pub fn set_position(self: *Mouse, x: u32, y: u32) void {
        // Assert: X coordinate must be <= MAX_MOUSE_X.
        Debug.kassert(x <= MAX_MOUSE_X, "X > MAX_MOUSE_X", .{});
        
        // Assert: Y coordinate must be <= MAX_MOUSE_Y.
        Debug.kassert(y <= MAX_MOUSE_Y, "Y > MAX_MOUSE_Y", .{});
        
        // Update position.
        self.x = x;
        self.y = y;
        
        // Assert: Position must be updated.
        Debug.kassert(self.x == x, "X not updated", .{});
        Debug.kassert(self.y == y, "Y not updated", .{});
    }
    
    /// Get mouse X coordinate.
    /// Why: Query mouse X position.
    /// Returns: X coordinate (0 to MAX_MOUSE_X).
    pub fn get_x(self: *const Mouse) u32 {
        // Assert: X coordinate must be <= MAX_MOUSE_X.
        Debug.kassert(self.x <= MAX_MOUSE_X, "X > MAX_MOUSE_X", .{});
        
        return self.x;
    }
    
    /// Get mouse Y coordinate.
    /// Why: Query mouse Y position.
    /// Returns: Y coordinate (0 to MAX_MOUSE_Y).
    pub fn get_y(self: *const Mouse) u32 {
        // Assert: Y coordinate must be <= MAX_MOUSE_Y.
        Debug.kassert(self.y <= MAX_MOUSE_Y, "Y > MAX_MOUSE_Y", .{});
        
        return self.y;
    }
    
    /// Handle button press event.
    /// Why: Update mouse state when button is pressed.
    /// Contract: button must be valid MouseButton.
    pub fn handle_button_press(self: *Mouse, button: MouseButton) void {
        // Assert: Button must be valid.
        Debug.kassert(@intFromEnum(button) < MAX_BUTTONS, "Button >=
MAX_BUTTONS", .{});
        
        const button_idx = @as(u32, @intFromEnum(button));
        
        // Update button state.
        self.button_states[button_idx] = .pressed;
        self.last_button = button;
        self.last_button_state = .pressed;
        
        // Assert: Button state must be updated.
        Debug.kassert(self.button_states[button_idx] == .pressed,
"Button state not pressed", .{});
        Debug.kassert(self.last_button == button, "Last button
mismatch", .{});
    }
    
    /// Handle button release event.
    /// Why: Update mouse state when button is released.
    /// Contract: button must be valid MouseButton.
    pub fn handle_button_release(self: *Mouse, button: MouseButton) void
{
        // Assert: Button must be valid.
        Debug.kassert(@intFromEnum(button) < MAX_BUTTONS, "Button >=
MAX_BUTTONS", .{});
        
        const button_idx = @as(u32, @intFromEnum(button));
        
        // Update button state.
        self.button_states[button_idx] = .released;
        self.last_button = button;
        self.last_button_state = .released;
        
        // Assert: Button state must be updated.
        Debug.kassert(self.button_states[button_idx] == .released,
"Button state not released", .{});
        Debug.kassert(self.last_button == button, "Last button
mismatch", .{});
    }
    
    /// Check if button is pressed.
    /// Why: Query button state for polling.
    /// Contract: button must be valid MouseButton.
    /// Returns: true if button is pressed, false otherwise.
    pub fn is_button_pressed(self: *const Mouse, button: MouseButton)
bool {
        // Assert: Button must be valid.
        Debug.kassert(@intFromEnum(button) < MAX_BUTTONS, "Button >=
MAX_BUTTONS", .{});
        
        const button_idx = @as(u32, @intFromEnum(button));
        const pressed = self.button_states[button_idx] == .pressed;
        
        // Assert: Result must be consistent with button state.
        Debug.kassert(pressed == (self.button_states[button_idx] ==
.pressed), "Button state inconsistent", .{});
        
        return pressed;
    }
    
    /// Get last button pressed.
    /// Why: Query most recent button press for polling.
    /// Returns: Last button (null if none).
    pub fn get_last_button(self: *const Mouse) ?MouseButton {
        // Assert: Last button must be valid or null.
        if (self.last_button) |button| {
            Debug.kassert(@intFromEnum(button) < MAX_BUTTONS, "Last
button invalid", .{});
        }
        
        return self.last_button;
    }
    
    /// Get last button state.
    /// Why: Query most recent button state change for polling.
    /// Returns: Last button state (pressed or released).
    pub fn get_last_button_state(self: *const Mouse) ButtonState {
        // Assert: Last button state must be valid.
        Debug.kassert(self.last_button_state == .pressed or
self.last_button_state == .released, "Last button state invalid", .{});
        
        return self.last_button_state;
    }
    
    /// Clear all button states.
    /// Why: Reset mouse state (e.g., on driver reset).
    pub fn clear_all_buttons(self: *Mouse) void {
        // Clear all button states.
        for (0..MAX_BUTTONS) |i| {
            self.button_states[i] = .released;
        }
        self.last_button = null;
        self.last_button_state = .released;
        
        // Assert: All buttons must be released.
        for (0..MAX_BUTTONS) |i| {
            Debug.kassert(self.button_states[i] == .released, "Button
not released", .{});
        }
        Debug.kassert(self.last_button == null, "Last button not null",
.{});
    }
};

// Test mouse initialization.
test "mouse init" {
    const mouse = Mouse.init();
    
    // Assert: Mouse must be initialized.
    try std.testing.expect(mouse.x == 0);
    try std.testing.expect(mouse.y == 0);
    try std.testing.expect(mouse.last_button == null);
    try std.testing.expect(mouse.last_button_state == .released);
    
    // Assert: All buttons must be released.
    for (0..MAX_BUTTONS) |i| {
        try std.testing.expect(mouse.button_states[i] == .released);
    }
}

// Test mouse position.
test "mouse position" {
    var mouse = Mouse.init();
    
    mouse.set_position(100, 200);
    
    // Assert: Position must be updated.
    try std.testing.expect(mouse.get_x() == 100);
    try std.testing.expect(mouse.get_y() == 200);
}

// Test button press.
test "mouse button press" {
    var mouse = Mouse.init();
    
    mouse.handle_button_press(.left);
    
    // Assert: Button must be pressed.
    try std.testing.expect(mouse.is_button_pressed(.left));
    try std.testing.expect(mouse.get_last_button() == .left);
    try std.testing.expect(mouse.get_last_button_state() == .pressed);
}

// Test button release.
test "mouse button release" {
    var mouse = Mouse.init();
    
    mouse.handle_button_press(.left);
    mouse.handle_button_release(.left);
    
    // Assert: Button must be released.
    try std.testing.expect(!mouse.is_button_pressed(.left));
    try std.testing.expect(mouse.get_last_button() == .left);
    try std.testing.expect(mouse.get_last_button_state() == .released);
}

// Test multiple buttons.
test "mouse multiple buttons" {
    var mouse = Mouse.init();
    
    mouse.handle_button_press(.left);
    mouse.handle_button_press(.right);
    
    // Assert: Both buttons must be pressed.
    try std.testing.expect(mouse.is_button_pressed(.left));
    try std.testing.expect(mouse.is_button_pressed(.right));
    try std.testing.expect(mouse.get_last_button() == .right);
    
    mouse.handle_button_release(.left);
    
    // Assert: Left released, right still pressed.
    try std.testing.expect(!mouse.is_button_pressed(.left));
    try std.testing.expect(mouse.is_button_pressed(.right));
}

// Test clear all buttons.
test "mouse clear all buttons" {
    var mouse = Mouse.init();
    
    mouse.handle_button_press(.left);
    mouse.handle_button_press(.right);
    mouse.clear_all_buttons();
    
    // Assert: All buttons must be released.
    try std.testing.expect(!mouse.is_button_pressed(.left));
    try std.testing.expect(!mouse.is_button_pressed(.right));
    try std.testing.expect(mouse.get_last_button() == null);
}


// === kernel/network.zig ===

//! Network Interface Management
//! Why: Manage network interfaces for TCP/UDP syscalls.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Maximum number of network interfaces.
/// Why: Bounded allocation for interface tracking.
const MAX_NETWORK_INTERFACES: u32 = 8;

/// Maximum interface name length.
/// Why: Bounded string storage for interface names.
const MAX_INTERFACE_NAME_LEN: u32 = 16;

/// Network interface state.
/// Why: Track interface state (up/down).
pub const InterfaceState = enum(u8) {
    down = 0,
    up = 1,
};

/// Network interface entry.
/// Why: Track network interface configuration and state.
/// Grain Style: Static allocation, explicit types.
pub const NetworkInterface = struct {
    /// Interface name (null-terminated).
    name: [MAX_INTERFACE_NAME_LEN]u8,
    
    /// Interface state (up/down).
    state: InterfaceState,
    
    /// IPv4 address (network byte order).
    ipv4_addr: u32,
    
    /// IPv4 netmask (network byte order).
    ipv4_netmask: u32,
    
    /// IPv4 gateway (network byte order).
    ipv4_gateway: u32,
    
    /// IPv6 address (128 bits, network byte order).
    ipv6_addr: [16]u8,
    
    /// Whether this entry is allocated (in use).
    allocated: bool,
    
    /// Initialize empty network interface entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() NetworkInterface {
        return NetworkInterface{
            .name = [_]u8{0} ** MAX_INTERFACE_NAME_LEN,
            .state = .down,
            .ipv4_addr = 0,
            .ipv4_netmask = 0,
            .ipv4_gateway = 0,
            .ipv6_addr = [_]u8{0} ** 16,
            .allocated = false,
        };
    }
    
    /// Set interface name.
    /// Why: Configure interface name.
    /// Contract: name must be valid, non-empty, null-terminated.
    pub fn set_name(self: *NetworkInterface, name: []const u8) bool {
        // Assert: Entry must be allocated.
        Debug.kassert(self.allocated, "Entry not allocated", .{});
        
        // Assert: Name must be non-empty.
        if (name.len == 0) {
            return false;
        }
        
        // Assert: Name must fit in buffer (including null terminator).
        if (name.len >= MAX_INTERFACE_NAME_LEN) {
            return false;
        }
        
        // Copy name to buffer.
        std.mem.set(u8, &self.name, 0);
        std.mem.copyForwards(u8, self.name[0..name.len], name);
        self.name[name.len] = 0; // Null terminator
        
        return true;
    }
    
    /// Get interface name.
    /// Why: Retrieve interface name.
    /// Contract: Returns null-terminated string.
    pub fn get_name(self: *const NetworkInterface) []const u8 {
        // Assert: Entry must be allocated.
        Debug.kassert(self.allocated, "Entry not allocated", .{});
        
        // Find null terminator.
        var len: u32 = 0;
        while (len < MAX_INTERFACE_NAME_LEN) : (len += 1) {
            if (self.name[len] == 0) {
                break;
            }
        }
        
        return self.name[0..len];
    }
};

/// Network interface manager.
/// Why: Manage all network interfaces.
/// Grain Style: Static allocation, bounded operations.
pub const NetworkInterfaceManager = struct {
    /// Interface entries.
    interfaces: [MAX_NETWORK_INTERFACES]NetworkInterface,
    
    /// Whether manager is initialized.
    initialized: bool,
    
    /// Initialize network interface manager.
    /// Why: Set up manager state.
    pub fn init() NetworkInterfaceManager {
        const manager = NetworkInterfaceManager{
            .interfaces = [_]NetworkInterface{NetworkInterface.init()}
** MAX_NETWORK_INTERFACES,
            .initialized = true,
        };
        
        return manager;
    }
    
    /// Create a new network interface.
    /// Why: Add a new network interface.
    /// Contract: name must be valid, non-empty, null-terminated.
    /// Returns: Interface index, or null if no free slot.
    pub fn create_interface(
        self: *NetworkInterfaceManager,
        name: []const u8,
    ) ?u32 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Name must be non-empty.
        if (name.len == 0) {
            return null;
        }
        
        // Assert: Name must fit in buffer.
        if (name.len >= MAX_INTERFACE_NAME_LEN) {
            return null;
        }
        
        // Find free slot.
        var idx: u32 = 0;
        while (idx < MAX_NETWORK_INTERFACES) : (idx += 1) {
            if (!self.interfaces[idx].allocated) {
                // Initialize interface.
                self.interfaces[idx] = NetworkInterface.init();
                self.interfaces[idx].allocated = true;
                
                // Set name.
                if (!self.interfaces[idx].set_name(name)) {
                    self.interfaces[idx].allocated = false;
                    return null;
                }
                
                return idx;
            }
        }
        
        // No free slot found.
        return null;
    }
    
    /// Get interface by index.
    /// Why: Retrieve interface entry.
    /// Contract: idx must be valid (within bounds).
    /// Returns: Pointer to interface entry, or null if not found.
    pub fn get_interface(
        self: *NetworkInterfaceManager,
        idx: u32,
    ) ?*NetworkInterface {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Index must be within bounds.
        if (idx >= MAX_NETWORK_INTERFACES) {
            return null;
        }
        
        // Check if interface is allocated.
        if (!self.interfaces[idx].allocated) {
            return null;
        }
        
        return &self.interfaces[idx];
    }
    
    /// Find interface by name.
    /// Why: Look up interface by name.
    /// Contract: name must be valid, non-empty.
    /// Returns: Interface index, or null if not found.
    pub fn find_interface_by_name(
        self: *const NetworkInterfaceManager,
        name: []const u8,
    ) ?u32 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Name must be non-empty.
        if (name.len == 0) {
            return null;
        }
        
        // Search for interface with matching name.
        var idx: u32 = 0;
        while (idx < MAX_NETWORK_INTERFACES) : (idx += 1) {
            if (self.interfaces[idx].allocated) {
                const iface_name = self.interfaces[idx].get_name();
                if (std.mem.eql(u8, iface_name, name)) {
                    return idx;
                }
            }
        }
        
        // Interface not found.
        return null;
    }
    
    /// Set interface state (up/down).
    /// Why: Control interface state.
    /// Contract: idx must be valid, state must be valid.
    pub fn set_interface_state(
        self: *NetworkInterfaceManager,
        idx: u32,
        state: InterfaceState,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const iface = self.get_interface(idx) orelse {
            return false;
        };
        
        iface.state = state;
        return true;
    }
    
    /// Set IPv4 address.
    /// Why: Configure IPv4 address.
    /// Contract: idx must be valid, addr must be in network byte order.
    pub fn set_ipv4_address(
        self: *NetworkInterfaceManager,
        idx: u32,
        addr: u32,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const iface = self.get_interface(idx) orelse {
            return false;
        };
        
        iface.ipv4_addr = addr;
        return true;
    }
    
    /// Set IPv4 netmask.
    /// Why: Configure IPv4 netmask.
    /// Contract: idx must be valid, netmask must be in network byte
order.
    pub fn set_ipv4_netmask(
        self: *NetworkInterfaceManager,
        idx: u32,
        netmask: u32,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const iface = self.get_interface(idx) orelse {
            return false;
        };
        
        iface.ipv4_netmask = netmask;
        return true;
    }
    
    /// Set IPv4 gateway.
    /// Why: Configure IPv4 gateway.
    /// Contract: idx must be valid, gateway must be in network byte
order.
    pub fn set_ipv4_gateway(
        self: *NetworkInterfaceManager,
        idx: u32,
        gateway: u32,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const iface = self.get_interface(idx) orelse {
            return false;
        };
        
        iface.ipv4_gateway = gateway;
        return true;
    }
    
    /// Delete interface.
    /// Why: Remove network interface.
    /// Contract: idx must be valid.
    pub fn delete_interface(
        self: *NetworkInterfaceManager,
        idx: u32,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Index must be within bounds.
        if (idx >= MAX_NETWORK_INTERFACES) {
            return false;
        }
        
        // Check if interface is allocated.
        if (!self.interfaces[idx].allocated) {
            return false;
        }
        
        // Deallocate interface.
        self.interfaces[idx] = NetworkInterface.init();
        return true;
    }
};


// === kernel/page_fault_stats.zig ===

//! Page Fault Statistics Tracking System
//!
//! Objective: Track page fault counts by type for debugging and
monitoring.
//! Why: Monitor page fault frequency, identify memory access patterns,
and validate page table behavior.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track page fault counts by type (instruction, load, store)
//! - Track total page fault count
//! - Track page fault addresses (for debugging)
//! - Provide statistics interface for querying page fault data
//! - Reset capability for new measurement periods
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-01-XX
//! GrainStyle: Comprehensive page fault tracking, deterministic
behavior, explicit limits

const std = @import("std");
const Debug = @import("debug.zig");

/// Maximum number of page fault types (instruction, load, store).
/// Why: Bounded array size for page fault counters.
const MAX_PAGE_FAULT_TYPES: u32 = 3;

/// Maximum number of recent page fault addresses to track (for
debugging).
/// Why: Bounded buffer for recent page fault addresses.
const MAX_RECENT_FAULTS: u32 = 16;

/// Page fault type.
/// Why: Explicit page fault types for type safety.
pub const PageFaultType = enum(u32) {
    /// Instruction page fault (code 12).
    instruction = 12,
    /// Load page fault (code 13).
    load = 13,
    /// Store page fault (code 15).
    store = 15,
};

/// Page fault statistics tracker.
/// Why: Track page fault counts by type for debugging and monitoring.
/// GrainStyle: Explicit types, bounded counters, deterministic tracking.
pub const PageFaultStats = struct {
    /// Page fault counts by type.
    /// Why: Track how many times each page fault type occurs.
    fault_counts: [MAX_PAGE_FAULT_TYPES]u64 = [_]u64{0} **
MAX_PAGE_FAULT_TYPES,
    
    /// Total page fault count (sum of all types).
    /// Why: Quick access to total page fault count.
    total_count: u64 = 0,
    
    /// Recent page fault addresses (circular buffer).
    /// Why: Track recent page fault addresses for debugging.
    recent_addresses: [MAX_RECENT_FAULTS]u64 = [_]u64{0} **
MAX_RECENT_FAULTS,
    
    /// Write index for recent addresses (circular buffer).
    /// Why: Track next position to write in circular buffer.
    recent_write_idx: u32 = 0,
    
    /// Whether statistics tracker is initialized.
    /// Why: Track initialization state for safety.
    initialized: bool = false,
    
    /// Initialize page fault statistics tracker.
    /// Why: Set up statistics tracker state.
    /// Contract: Must be called once before use.
    pub fn init() PageFaultStats {
        return PageFaultStats{
            .fault_counts = [_]u64{0} ** MAX_PAGE_FAULT_TYPES,
            .total_count = 0,
            .recent_addresses = [_]u64{0} ** MAX_RECENT_FAULTS,
            .recent_write_idx = 0,
            .initialized = true,
        };
    }
    
    /// Record page fault occurrence.
    /// Why: Track page fault for statistics.
    /// Contract: Page fault type must be valid (instruction, load, or
store).
    pub fn record_page_fault(
        self: *PageFaultStats,
        fault_type: PageFaultType,
        fault_address: u64,
    ) void {
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(self.initialized, "Page fault stats not
initialized", .{});
        
        // Assert: Fault address must be valid (precondition).
        Debug.kassert(fault_address < 0x100000000, "Fault address out of
bounds", .{});
        
        // Get fault type index (0=instruction, 1=load, 2=store).
        const fault_idx: u32 = switch (fault_type) {
            .instruction => 0,
            .load => 1,
            .store => 2,
        };
        
        // Assert: Fault index must be valid (postcondition).
        Debug.kassert(fault_idx < MAX_PAGE_FAULT_TYPES, "Fault index out
of bounds", .{});
        
        // Increment page fault count for this type.
        self.fault_counts[fault_idx] += 1;
        self.total_count += 1;
        
        // Record recent page fault address (circular buffer).
        self.recent_addresses[self.recent_write_idx] = fault_address;
        self.recent_write_idx = (self.recent_write_idx + 1) %
MAX_RECENT_FAULTS;
        
        // Assert: Counters must be consistent (postcondition).
        Debug.kassert(self.fault_counts[fault_idx] > 0, "Fault count not
incremented", .{});
        Debug.kassert(self.total_count > 0, "Total count not
incremented", .{});
        Debug.kassert(self.total_count >= self.fault_counts[fault_idx],
"Total count inconsistent", .{});
    }
    
    /// Get page fault count for specific type.
    /// Why: Query page fault frequency for specific page fault type.
    /// Contract: Page fault type must be valid.
    pub fn get_count(self: *const PageFaultStats, fault_type:
PageFaultType) u64 {
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(self.initialized, "Page fault stats not
initialized", .{});
        
        // Get fault type index.
        const fault_idx: u32 = switch (fault_type) {
            .instruction => 0,
            .load => 1,
            .store => 2,
        };
        
        // Assert: Fault index must be valid (postcondition).
        Debug.kassert(fault_idx < MAX_PAGE_FAULT_TYPES, "Fault index out
of bounds", .{});
        
        const count = self.fault_counts[fault_idx];
        
        // Assert: Count must be valid (postcondition).
        Debug.kassert(count <= self.total_count, "Fault count exceeds
total", .{});
        
        return count;
    }
    
    /// Get total page fault count.
    /// Why: Query total page fault frequency.
    pub fn get_total_count(self: *const PageFaultStats) u64 {
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(self.initialized, "Page fault stats not
initialized", .{});
        
        return self.total_count;
    }
    
    /// Get recent page fault addresses.
    /// Why: Query recent page fault addresses for debugging.
    /// Returns: Slice of recent page fault addresses (up to
MAX_RECENT_FAULTS).
    pub fn get_recent_addresses(self: *const PageFaultStats) []const u64
{
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(self.initialized, "Page fault stats not
initialized", .{});
        
        return &self.recent_addresses;
    }
    
    /// Reset page fault statistics.
    /// Why: Clear statistics for new measurement period.
    pub fn reset(self: *PageFaultStats) void {
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(self.initialized, "Page fault stats not
initialized", .{});
        
        // Reset all counters.
        for (0..MAX_PAGE_FAULT_TYPES) |i| {
            self.fault_counts[i] = 0;
        }
        self.total_count = 0;
        
        // Reset recent addresses buffer.
        for (0..MAX_RECENT_FAULTS) |i| {
            self.recent_addresses[i] = 0;
        }
        self.recent_write_idx = 0;
        
        // Assert: All counters must be reset (postcondition).
        Debug.kassert(self.total_count == 0, "Total count not reset",
.{});
        for (0..MAX_PAGE_FAULT_TYPES) |i| {
            Debug.kassert(self.fault_counts[i] == 0, "Fault count not
reset", .{});
        }
    }
};

/// Page fault statistics snapshot (for diagnostics).
/// Why: Capture page fault statistics at a point in time.
/// GrainStyle: Static allocation, explicit types.
pub const PageFaultStatsSnapshot = struct {
    /// Instruction page fault count.
    instruction_count: u64,
    /// Load page fault count.
    load_count: u64,
    /// Store page fault count.
    store_count: u64,
    /// Total page fault count.
    total_count: u64,
    
    /// Create page fault statistics snapshot.
    /// Why: Capture current page fault statistics state.
    /// Contract: Page fault stats must be initialized.
    pub fn create(stats: *const PageFaultStats) PageFaultStatsSnapshot {
        // Assert: Statistics tracker must be initialized (precondition).
        Debug.kassert(stats.initialized, "Page fault stats not
initialized", .{});
        
        return PageFaultStatsSnapshot{
            .instruction_count = stats.get_count(.instruction),
            .load_count = stats.get_count(.load),
            .store_count = stats.get_count(.store),
            .total_count = stats.get_total_count(),
        };
    }
    
    /// Print page fault statistics snapshot.
    /// Why: Display page fault statistics for debugging.
    pub fn print(self: *const PageFaultStatsSnapshot) void {
        // Assert: Snapshot must be valid (precondition).
        const self_ptr = @intFromPtr(self);
        Debug.kassert(self_ptr != 0, "Snapshot ptr is null", .{});
        Debug.kassert(self_ptr % @alignOf(PageFaultStatsSnapshot) == 0,
"Snapshot ptr unaligned", .{});
        
        Debug.kprint("Page Fault Statistics:\n", .{});
        Debug.kprint("  Instruction page faults: {d}\n",
.{self.instruction_count});
        Debug.kprint("  Load page faults: {d}\n", .{self.load_count});
        Debug.kprint("  Store page faults: {d}\n", .{self.store_count});
        Debug.kprint("  Total page faults: {d}\n", .{self.total_count});
    }
};


// === kernel/page_table.zig ===

//! Page Table Implementation
//! Why: Page-level memory protection for fine-grained access control.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Page size (4KB, standard RISC-V page size).
/// Why: Explicit constant for page size, matches RISC-V standard.
pub const PAGE_SIZE: u64 = 4096;

/// Maximum number of pages in VM memory (4MB / 4KB = 1024 pages).
/// Why: Bounded allocation, prevents unbounded growth.
pub const MAX_PAGES: u32 = 1024;

/// Page permissions flags (matches MapFlags from basin_kernel).
/// Why: Explicit flags instead of POSIX-style bitmasks for type safety.
pub const PageFlags = packed struct {
    read: bool = false,
    write: bool = false,
    execute: bool = false,
    shared: bool = false,
    _padding: u28 = 0,
    
    /// Create PageFlags from boolean values.
    /// Why: Explicit construction, no magic numbers.
    pub fn init(flags: struct {
        read: bool = false,
        write: bool = false,
        execute: bool = false,
        shared: bool = false,
    }) PageFlags {
        return PageFlags{
            .read = flags.read,
            .write = flags.write,
            .execute = flags.execute,
            .shared = flags.shared,
            ._padding = 0,
        };
    }
};

/// Page table entry.
/// Why: Track permissions for each 4KB page in VM memory.
/// Grain Style: Static allocation, explicit state tracking.
pub const PageEntry = struct {
    /// Page permissions (read, write, execute).
    flags: PageFlags,
    /// Whether this page is mapped (allocated).
    mapped: bool,
    
    /// Initialize empty page entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() PageEntry {
        return PageEntry{
            .flags = PageFlags.init(.{}),
            .mapped = false,
        };
    }
    
    /// Check if page has read permission.
    /// Why: Explicit permission check, no magic numbers.
    pub fn can_read(self: PageEntry) bool {
        return self.mapped and self.flags.read;
    }
    
    /// Check if page has write permission.
    /// Why: Explicit permission check, no magic numbers.
    pub fn can_write(self: PageEntry) bool {
        return self.mapped and self.flags.write;
    }
    
    /// Check if page has execute permission.
    /// Why: Explicit permission check, no magic numbers.
    pub fn can_execute(self: PageEntry) bool {
        return self.mapped and self.flags.execute;
    }
};

/// Page table.
/// Why: Track page-level permissions for all pages in VM memory.
/// Grain Style: Static allocation, max 1024 pages (4MB VM).
pub const PageTable = struct {
    /// Page entries (one per 4KB page).
    /// Why: Static array for bounded allocation.
    pages: [MAX_PAGES]PageEntry = [_]PageEntry{PageEntry.init()} **
MAX_PAGES,
    
    /// Initialize page table.
    /// Why: Explicit initialization, clear state.
    pub fn init() PageTable {
        const table = PageTable{};
        
        // Assert: All pages must be initialized (precondition).
        for (table.pages) |page| {
            Debug.kassert(!page.mapped, "Page already mapped", .{});
        }
        
        return table;
    }
    
    /// Get page index from address.
    /// Why: Convert address to page index for table lookup.
    /// Contract: Address must be valid (within VM memory bounds).
    /// Returns: Page index (0-1023), or null if address is out of
bounds.
    pub fn get_page_index(addr: u64) ?u32 {
        // Assert: Address must be valid (precondition).
        const VM_MEMORY_SIZE: u64 = 4 * 1024 * 1024; // 4MB default
        if (addr >= VM_MEMORY_SIZE) {
            return null; // Out of bounds
        }
        
        const page_idx_u64 = addr / PAGE_SIZE;
        const page_idx = @as(u32, @intCast(page_idx_u64));
        
        // Assert: Page index must be within bounds (postcondition).
        Debug.kassert(page_idx < MAX_PAGES, "Page index out of bounds",
.{});
        
        return page_idx;
    }
    
    /// Get page entry for address (read-only).
    /// Why: Look up page permissions for a given address (for reading).
    /// Contract: Address must be valid, returns page entry (may be
unmapped).
    /// Returns: Page entry for the page containing the address, or null
if out of bounds.
    pub fn get_page(self: *const PageTable, addr: u64) ?*const PageEntry
{
        const page_idx = PageTable.get_page_index(addr) orelse {
            return null; // Out of bounds
        };
        
        // Assert: Page index must be valid (postcondition).
        Debug.kassert(page_idx < MAX_PAGES, "Page index out of bounds",
.{});
        
        return &self.pages[page_idx];
    }
    
    /// Map pages in address range.
    /// Why: Set permissions for a contiguous range of pages.
    /// Contract: Address and size must be page-aligned, size must be
non-zero.
    /// Returns: Error if invalid arguments, success if pages mapped.
    pub fn map_pages(
        self: *PageTable,
        addr: u64,
        size: u64,
        flags: PageFlags,
    ) void {
        // Assert: Address must be page-aligned (precondition).
        Debug.kassert(addr % PAGE_SIZE == 0, "Address not page-aligned",
.{});
        
        // Assert: Size must be page-aligned and non-zero (precondition).
        Debug.kassert(size > 0, "Size is zero", .{});
        Debug.kassert(size % PAGE_SIZE == 0, "Size not page-aligned",
.{});
        
        // Assert: Flags must have at least one permission
(precondition).
        Debug.kassert(flags.read or flags.write or flags.execute, "No
permissions set", .{});
        
        const start_page = PageTable.get_page_index(addr).?;
        const num_pages = @as(u32, @intCast(size / PAGE_SIZE));
        const end_page = start_page + num_pages;
        
        // Assert: End page must be within bounds (precondition).
        Debug.kassert(end_page <= MAX_PAGES, "End page out of bounds",
.{});
        
        // Map all pages in range.
        for (start_page..end_page) |page_idx| {
            const page = &self.pages[page_idx];
            page.flags = flags;
            page.mapped = true;
            
            // Assert: Page must be mapped correctly (postcondition).
            Debug.kassert(page.mapped, "Page not mapped", .{});
            Debug.kassert(page.flags.read == flags.read, "Read flag
mismatch", .{});
            Debug.kassert(page.flags.write == flags.write, "Write flag
mismatch", .{});
            Debug.kassert(page.flags.execute == flags.execute, "Execute
flag mismatch", .{});
        }
    }
    
    /// Unmap pages in address range.
    /// Why: Clear permissions for a contiguous range of pages.
    /// Contract: Address and size must be page-aligned, size must be
non-zero.
    /// Returns: Error if invalid arguments, success if pages unmapped.
    pub fn unmap_pages(
        self: *PageTable,
        addr: u64,
        size: u64,
    ) void {
        // Assert: Address must be page-aligned (precondition).
        Debug.kassert(addr % PAGE_SIZE == 0, "Address not page-aligned",
.{});
        
        // Assert: Size must be page-aligned and non-zero (precondition).
        Debug.kassert(size > 0, "Size is zero", .{});
        Debug.kassert(size % PAGE_SIZE == 0, "Size not page-aligned",
.{});
        
        const start_page = PageTable.get_page_index(addr).?;
        const num_pages = @as(u32, @intCast(size / PAGE_SIZE));
        const end_page = start_page + num_pages;
        
        // Assert: End page must be within bounds (precondition).
        Debug.kassert(end_page <= MAX_PAGES, "End page out of bounds",
.{});
        
        // Unmap all pages in range.
        for (start_page..end_page) |page_idx| {
            const page = &self.pages[page_idx];
            page.mapped = false;
            page.flags = PageFlags.init(.{});
            
            // Assert: Page must be unmapped correctly (postcondition).
            Debug.kassert(!page.mapped, "Page still mapped", .{});
        }
    }
    
    /// Update permissions for pages in address range.
    /// Why: Change permissions for a contiguous range of pages.
    /// Contract: Address and size must be page-aligned, size must be
non-zero.
    /// Returns: Error if invalid arguments, success if permissions
updated.
    pub fn protect_pages(
        self: *PageTable,
        addr: u64,
        size: u64,
        flags: PageFlags,
    ) void {
        // Assert: Address must be page-aligned (precondition).
        Debug.kassert(addr % PAGE_SIZE == 0, "Address not page-aligned",
.{});
        
        // Assert: Size must be page-aligned and non-zero (precondition).
        Debug.kassert(size > 0, "Size is zero", .{});
        Debug.kassert(size % PAGE_SIZE == 0, "Size not page-aligned",
.{});
        
        // Assert: Flags must have at least one permission
(precondition).
        Debug.kassert(flags.read or flags.write or flags.execute, "No
permissions set", .{});
        
        const start_page = PageTable.get_page_index(addr).?;
        const num_pages = @as(u32, @intCast(size / PAGE_SIZE));
        const end_page = start_page + num_pages;
        
        // Assert: End page must be within bounds (precondition).
        Debug.kassert(end_page <= MAX_PAGES, "End page out of bounds",
.{});
        
        // Update permissions for all pages in range.
        for (start_page..end_page) |page_idx| {
            const page = &self.pages[page_idx];
            
            // Assert: Page must be mapped (precondition).
            Debug.kassert(page.mapped, "Page not mapped", .{});
            
            page.flags = flags;
            
            // Assert: Permissions must be updated correctly
(postcondition).
            Debug.kassert(page.flags.read == flags.read, "Read flag
mismatch", .{});
            Debug.kassert(page.flags.write == flags.write, "Write flag
mismatch", .{});
            Debug.kassert(page.flags.execute == flags.execute, "Execute
flag mismatch", .{});
        }
    }
    
    /// Check memory permissions for an address.
    /// Why: Enforce memory protection by checking read/write/execute
permissions.
    /// Contract: Address must be valid, returns permissions if mapped,
null if not mapped.
    /// Returns: PageFlags with permissions, or null if address is not
mapped.
    /// Note: Kernel space (0x80000000+) and framebuffer (0x90000000+)
are always readable/writable.
    pub fn check_permission(self: *const PageTable, addr: u64)
?PageFlags {
        // Assert: Address must be valid (precondition).
        const VM_MEMORY_SIZE: u64 = 4 * 1024 * 1024; // 4MB default
        if (addr >= VM_MEMORY_SIZE) {
            return null; // Out of bounds
        }
        
        // Kernel space (0x80000000+) always has all permissions.
        if (addr >= 0x80000000 and addr < 0x90000000) {
            return PageFlags.init(.{ .read = true, .write = true,
.execute = true });
        }
        
        // Framebuffer space (0x90000000+) always has read/write
permissions.
        if (addr >= 0x90000000) {
            return PageFlags.init(.{ .read = true, .write = true,
.execute = false });
        }
        
        // Check page table for user space.
        const page = self.get_page(addr) orelse {
            return null; // Out of bounds
        };
        
        if (!page.mapped) {
            return null; // Page not mapped
        }
        
        return page.flags;
    }
};


