// === kernel/process.zig ===

//! Grain Basin Process Management
//! Why: Enhanced process management with ELF loading support.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Process execution context.
/// Why: Track process execution state (PC, SP, registers).
/// Grain Style: Static allocation, explicit state tracking.
pub const ProcessContext = struct {
    /// Program counter (entry point or current PC).
    /// Why: Track where process execution starts or continues.
    pc: u64,
    /// Stack pointer (initial SP or current SP).
    /// Why: Track process stack location.
    sp: u64,
    /// Entry point (from ELF header).
    /// Why: Track original entry point for restart/debugging.
    entry_point: u64,
    /// Whether context is initialized.
    /// Why: Track initialization state for safety.
    initialized: bool,
    
    /// Initialize process context.
    /// Why: Set up process execution context.
    /// Contract: pc and sp must be valid addresses within VM memory.
    pub fn init(pc: u64, sp: u64, entry_point: u64) ProcessContext {
        // Assert: PC must be non-zero (valid entry point).
        Debug.kassert(pc != 0, "PC is 0", .{});
        
        // Assert: SP must be non-zero (valid stack pointer).
        Debug.kassert(sp != 0, "SP is 0", .{});
        
        // Assert: Entry point must match PC (for initial context).
        Debug.kassert(entry_point == pc, "Entry point != PC", .{});
        
        return ProcessContext{
            .pc = pc,
            .sp = sp,
            .entry_point = entry_point,
            .initialized = true,
        };
    }
    
    /// Update program counter.
    /// Why: Track process execution progress.
    /// Contract: pc must be valid address.
    pub fn update_pc(self: *ProcessContext, pc: u64) void {
        // Assert: Context must be initialized.
        Debug.kassert(self.initialized, "Context not initialized", .{});
        
        // Assert: PC must be non-zero.
        Debug.kassert(pc != 0, "PC is 0", .{});
        
        self.pc = pc;
        
        // Assert: PC must be updated.
        Debug.kassert(self.pc == pc, "PC not updated", .{});
    }
    
    /// Get program counter.
    /// Why: Query current execution position.
    /// Contract: Context must be initialized.
    pub fn get_pc(self: *const ProcessContext) u64 {
        // Assert: Context must be initialized.
        Debug.kassert(self.initialized, "Context not initialized", .{});
        
        // Assert: PC must be non-zero.
        Debug.kassert(self.pc != 0, "PC is 0", .{});
        
        return self.pc;
    }
    
    /// Get stack pointer.
    /// Why: Query current stack position.
    /// Contract: Context must be initialized.
    pub fn get_sp(self: *const ProcessContext) u64 {
        // Assert: Context must be initialized.
        Debug.kassert(self.initialized, "Context not initialized", .{});
        
        // Assert: SP must be non-zero.
        Debug.kassert(self.sp != 0, "SP is 0", .{});
        
        return self.sp;
    }
    
    /// Reset to entry point.
    /// Why: Restart process execution from beginning.
    /// Contract: Context must be initialized.
    pub fn reset(self: *ProcessContext) void {
        // Assert: Context must be initialized.
        Debug.kassert(self.initialized, "Context not initialized", .{});
        
        // Assert: Entry point must be non-zero.
        Debug.kassert(self.entry_point != 0, "Entry point is 0", .{});
        
        self.pc = self.entry_point;
        
        // Assert: PC must be reset to entry point.
        Debug.kassert(self.pc == self.entry_point, "PC not reset", .{});
    }
};

// Test process context initialization.
test "process context init" {
    const context = ProcessContext.init(0x10000, 0x400000, 0x10000);
    
    // Assert: Context must be initialized.
    try std.testing.expect(context.initialized);
    try std.testing.expect(context.pc == 0x10000);
    try std.testing.expect(context.sp == 0x400000);
    try std.testing.expect(context.entry_point == 0x10000);
}

// Test process context update PC.
test "process context update pc" {
    var context = ProcessContext.init(0x10000, 0x400000, 0x10000);
    
    context.update_pc(0x10010);
    
    // Assert: PC must be updated.
    try std.testing.expect(context.get_pc() == 0x10010);
    try std.testing.expect(context.get_sp() == 0x400000);
}

// Test process context reset.
test "process context reset" {
    var context = ProcessContext.init(0x10000, 0x400000, 0x10000);
    
    context.update_pc(0x10010);
    context.reset();
    
    // Assert: PC must be reset to entry point.
    try std.testing.expect(context.get_pc() == 0x10000);
    try std.testing.expect(context.entry_point == 0x10000);
}


// === kernel/process_execution.zig ===

//! Process Execution and Context Switching
//! Why: Execute processes in VM by switching contexts and running VM
until process exits or yields.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");
const ProcessContext = @import("process.zig").ProcessContext;
const VM = @import("kernel_vm").VM;
const Scheduler = @import("scheduler.zig").Scheduler;

/// Switch VM to process context (set VM registers from ProcessContext).
/// Why: Prepare VM to execute a process by loading its context.
/// Contract: process_context must be initialized, vm must be
initialized.
/// Grain Style: Explicit types, comprehensive assertions, no recursion.
pub fn switch_to_process_context(vm: *VM, process_context: *const
ProcessContext) void {
    // Assert: Process context must be initialized (precondition).
    Debug.kassert(process_context.initialized, "Process context not
initialized", .{});
    
    // Assert: VM must be initialized (precondition).
    Debug.kassert(vm.memory_size > 0, "VM not initialized", .{});
    
    // Assert: PC must be non-zero (valid entry point).
    Debug.kassert(process_context.pc != 0, "PC is 0", .{});
    
    // Assert: SP must be non-zero (valid stack pointer).
    Debug.kassert(process_context.sp != 0, "SP is 0", .{});
    
    // Set VM program counter to process PC.
    // Why: Start execution at process entry point or current PC.
    vm.regs.pc = process_context.pc;
    
    // Set VM stack pointer register (x2 = SP in RISC-V).
    // Why: Process needs valid stack pointer for execution.
    const SP_REGISTER: u5 = 2;
    vm.regs.set(SP_REGISTER, process_context.sp);
    
    // Assert: VM PC must be set correctly (postcondition).
    Debug.kassert(vm.regs.pc == process_context.pc, "VM PC not set",
.{});
    
    // Assert: VM SP register must be set correctly (postcondition).
    Debug.kassert(vm.regs.get(SP_REGISTER) == process_context.sp, "VM SP
not set", .{});
}

/// Save VM context to process context (save VM registers to
ProcessContext).
/// Why: Preserve process execution state when switching away from
process.
/// Contract: process_context must be initialized, vm must be
initialized.
/// Grain Style: Explicit types, comprehensive assertions, no recursion.
pub fn save_process_context(vm: *VM, process_context: *ProcessContext)
void {
    // Assert: Process context must be initialized (precondition).
    Debug.kassert(process_context.initialized, "Process context not
initialized", .{});
    
    // Assert: VM must be initialized (precondition).
    Debug.kassert(vm.memory_size > 0, "VM not initialized", .{});
    
    // Assert: VM PC must be non-zero (valid execution state).
    Debug.kassert(vm.regs.pc != 0, "VM PC is 0", .{});
    
    // Save VM program counter to process context.
    // Why: Track current execution position.
    process_context.pc = vm.regs.pc;
    
    // Save VM stack pointer register (x2 = SP in RISC-V) to process
context.
    // Why: Track current stack position.
    const SP_REGISTER: u5 = 2;
    process_context.sp = vm.regs.get(SP_REGISTER);
    
    // Assert: Process context PC must be saved correctly
(postcondition).
    Debug.kassert(process_context.pc == vm.regs.pc, "Process PC not
saved", .{});
    
    // Assert: Process context SP must be saved correctly
(postcondition).
    Debug.kassert(process_context.sp == vm.regs.get(SP_REGISTER),
"Process SP not saved", .{});
}

/// Execute process in VM until it exits, yields, or time slice expires.
/// Why: Run process execution loop, handling syscalls, context
switches, and preemption.
/// Contract: process_context must be initialized, vm must be
initialized.
/// Returns: true if process should continue (yield), false if process
exited or preempted.
/// Grain Style: Explicit types, bounded execution, no recursion.
pub fn execute_process(
    vm: *VM,
    process_context: *ProcessContext,
    max_steps: u64,
    scheduler: ?*Scheduler,
) bool {
    // Assert: Process context must be initialized (precondition).
    Debug.kassert(process_context.initialized, "Process context not
initialized", .{});
    
    // Assert: VM must be initialized (precondition).
    Debug.kassert(vm.memory_size > 0, "VM not initialized", .{});
    
    // Assert: Max steps must be reasonable (bounded execution).
    const MAX_STEPS_LIMIT: u64 = 1_000_000_000; // 1 billion steps max
    Debug.kassert(max_steps <= MAX_STEPS_LIMIT, "Max steps too large",
.{});
    
    // Switch VM to process context (set VM registers from
ProcessContext).
    // Why: Prepare VM to execute process.
    switch_to_process_context(vm, process_context);
    
    // Start VM execution (set state to running).
    // Why: VM must be running to execute instructions.
    vm.state = .running;
    
    // Execute VM steps until process exits, yields, or time slice
expires.
    // Why: Run process until it makes exit syscall, yields, or is
preempted.
    var steps_executed: u64 = 0;
    while (steps_executed < max_steps) : (steps_executed += 1) {
        // Check if VM is halted or errored (process exited or error
occurred).
        if (vm.state != .running) {
            break;
        }
        
        // Execute one VM step (use JIT if enabled, falls back to
interpreter).
        // Why: Execute one instruction at a time with JIT acceleration.
        vm.step_jit() catch |err| {
            // VM execution error: save context and return false
(process exited).
            _ = err;
            save_process_context(vm, process_context);
            return false;
        };
        
        // Decrement time slice if scheduler is provided.
        // Why: Track time slice usage for preemption.
        if (scheduler) |sched| {
            const expired = sched.decrement_time_slice(1);
            if (expired) {
                // Time slice expired: preempt process.
                save_process_context(vm, process_context);
                return true; // Process should continue (yield due to
preemption).
            }
        }
        
        // Check if process made exit syscall (syscall number 2 = exit).
        // Why: Detect when process calls exit syscall.
        // Note: This is a simplified check - in a full implementation,
we'd check
        // the syscall handler return value or process state.
        // For now, we check if VM is halted (which happens after exit
syscall).
        if (vm.state == .halted) {
            // Process exited: save context and return false.
            save_process_context(vm, process_context);
            return false;
        }
    }
    
    // Save process context before returning (preserve execution state).
    // Why: Track current execution position for next time slice.
    save_process_context(vm, process_context);
    
    // Assert: Steps executed must be within limit (postcondition).
    Debug.kassert(steps_executed <= max_steps, "Steps executed exceeded
limit", .{});
    
    // Return true if process should continue (yield case).
    // Why: Process may need more time slices to complete.
    return vm.state == .running;
}

// Test: switch to process context.
test "switch to process context sets VM registers" {
    var vm = VM.init(&[_]u8{}, 0);
    const context = ProcessContext.init(0x10000, 0x400000, 0x10000);
    
    switch_to_process_context(&vm, &context);
    
    // Assert: VM PC must be set to context PC.
    try std.testing.expect(vm.regs.pc == 0x10000);
    
    // Assert: VM SP register must be set to context SP.
    try std.testing.expect(vm.regs.get(2) == 0x400000);
}

// Test: save process context.
test "save process context preserves VM state" {
    var vm = VM.init(&[_]u8{}, 0);
    vm.regs.pc = 0x10010;
    vm.regs.set(2, 0x400010); // SP register
    
    var context = ProcessContext.init(0x10000, 0x400000, 0x10000);
    save_process_context(&vm, &context);
    
    // Assert: Context PC must be saved from VM PC.
    try std.testing.expect(context.pc == 0x10010);
    
    // Assert: Context SP must be saved from VM SP register.
    try std.testing.expect(context.sp == 0x400010);
}

// Test: execute process runs VM steps.
test "execute process runs VM until halted" {
    var vm = VM.init(&[_]u8{}, 0);
    var context = ProcessContext.init(0x10000, 0x400000, 0x10000);
    
    // Note: This test will fail if VM tries to execute invalid
instructions.
    // For now, we just test that the function runs without crashing.
    // In a full implementation, we'd load valid instructions into VM
memory.
    const should_continue = execute_process(&vm, &context, 100, null);
    
    // Assert: Process execution should complete (halted or errored).
    // Note: This is a basic test - full implementation would check
process state.
    _ = should_continue;
}


// === kernel/process_group.zig ===

//! Process Group and Session Management
//! Why: Organize processes into groups and sessions for better
management.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");
const Process = @import("basin_kernel.zig").Process;

/// Maximum number of process groups.
/// Why: Bounded allocation for process group tracking.
const MAX_PROCESS_GROUPS: u32 = 64;

/// Maximum number of sessions.
/// Why: Bounded allocation for session tracking.
const MAX_SESSIONS: u32 = 32;

/// Process group entry.
/// Why: Track process group membership and leader.
/// Grain Style: Static allocation, explicit types.
pub const ProcessGroup = struct {
    /// Process group ID (non-zero if allocated).
    pgid: u64,
    
    /// Session ID this group belongs to.
    sid: u64,
    
    /// Leader process ID (process that created the group).
    leader_pid: u64,
    
    /// Number of processes in this group.
    process_count: u32,
    
    /// Whether this entry is allocated (in use).
    allocated: bool,
    
    /// Initialize empty process group entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() ProcessGroup {
        return ProcessGroup{
            .pgid = 0,
            .sid = 0,
            .leader_pid = 0,
            .process_count = 0,
            .allocated = false,
        };
    }
};

/// Session entry.
/// Why: Track session membership and leader.
/// Grain Style: Static allocation, explicit types.
pub const Session = struct {
    /// Session ID (non-zero if allocated).
    sid: u64,
    
    /// Leader process ID (process that created the session).
    leader_pid: u64,
    
    /// Number of process groups in this session.
    group_count: u32,
    
    /// Whether this entry is allocated (in use).
    allocated: bool,
    
    /// Initialize empty session entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() Session {
        return Session{
            .sid = 0,
            .leader_pid = 0,
            .group_count = 0,
            .allocated = false,
        };
    }
};

/// Process group manager.
/// Why: Manage process groups and sessions.
/// Grain Style: Static allocation, bounded operations.
pub const ProcessGroupManager = struct {
    /// Process group table.
    groups: [MAX_PROCESS_GROUPS]ProcessGroup,
    
    /// Session table.
    sessions: [MAX_SESSIONS]Session,
    
    /// Next process group ID (simple allocator, starts at 1).
    next_pgid: u64,
    
    /// Next session ID (simple allocator, starts at 1).
    next_sid: u64,
    
    /// Whether manager is initialized.
    initialized: bool,
    
    /// Initialize process group manager.
    /// Why: Set up manager state.
    pub fn init() ProcessGroupManager {
        const manager = ProcessGroupManager{
            .groups = [_]ProcessGroup{ProcessGroup.init()} **
MAX_PROCESS_GROUPS,
            .sessions = [_]Session{Session.init()} ** MAX_SESSIONS,
            .next_pgid = 1,
            .next_sid = 1,
            .initialized = true,
        };
        
        return manager;
    }
    
    /// Create a new process group.
    /// Why: Create a process group for organizing processes.
    /// Contract: pid must be valid (non-zero), processes array must be
valid.
    /// Returns: Process group ID if successful, 0 if failed.
    pub fn create_group(
        self: *ProcessGroupManager,
        pid: u64,
        sid: u64,
        processes: []Process,
        max_processes: u32,
    ) u64 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process ID must be valid (non-zero).
        Debug.kassert(pid != 0, "Process ID is 0", .{});
        
        // Assert: Session ID must be valid (non-zero).
        Debug.kassert(sid != 0, "Session ID is 0", .{});
        
        // Find empty slot in groups table.
        var idx: u32 = 0;
        while (idx < MAX_PROCESS_GROUPS) : (idx += 1) {
            if (!self.groups[idx].allocated) {
                const pgid = self.next_pgid;
                self.next_pgid += 1;
                
                // Initialize group entry.
                self.groups[idx].pgid = pgid;
                self.groups[idx].sid = sid;
                self.groups[idx].leader_pid = pid;
                self.groups[idx].process_count = 1;
                self.groups[idx].allocated = true;
                
                // Update process to belong to this group.
                self.set_process_group(pid, pgid, processes,
max_processes);
                
                // Update session group count.
                self.increment_session_group_count(sid);
                
                return pgid;
            }
        }
        
        // No free slot found.
        return 0;
    }
    
    /// Set process group for a process.
    /// Why: Assign process to a process group.
    /// Contract: pid and pgid must be valid (non-zero).
    fn set_process_group(
        _: *ProcessGroupManager,
        pid: u64,
        pgid: u64,
        processes: []Process,
        max_processes: u32,
    ) void {
        // Find process in process table.
        var idx: u32 = 0;
        while (idx < max_processes) : (idx += 1) {
            if (processes[idx].allocated and processes[idx].id == pid) {
                // Update process group ID.
                processes[idx].pgid = pgid;
                break;
            }
        }
    }
    
    /// Increment session group count.
    /// Why: Track number of groups in a session.
    /// Contract: sid must be valid (non-zero).
    fn increment_session_group_count(self: *ProcessGroupManager, sid:
u64) void {
        // Find session in sessions table.
        var idx: u32 = 0;
        while (idx < MAX_SESSIONS) : (idx += 1) {
            if (self.sessions[idx].allocated and self.sessions[idx].sid
== sid) {
                self.sessions[idx].group_count += 1;
                break;
            }
        }
    }
    
    /// Create a new session.
    /// Why: Create a session for organizing process groups.
    /// Contract: pid must be valid (non-zero).
    /// Returns: Session ID if successful, 0 if failed.
    pub fn create_session(self: *ProcessGroupManager, pid: u64) u64 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process ID must be valid (non-zero).
        Debug.kassert(pid != 0, "Process ID is 0", .{});
        
        // Find empty slot in sessions table.
        var idx: u32 = 0;
        while (idx < MAX_SESSIONS) : (idx += 1) {
            if (!self.sessions[idx].allocated) {
                const sid = self.next_sid;
                self.next_sid += 1;
                
                // Initialize session entry.
                self.sessions[idx].sid = sid;
                self.sessions[idx].leader_pid = pid;
                self.sessions[idx].group_count = 0;
                self.sessions[idx].allocated = true;
                
                return sid;
            }
        }
        
        // No free slot found.
        return 0;
    }
    
    /// Get process group ID for a process.
    /// Why: Query which process group a process belongs to.
    /// Contract: pid must be valid (non-zero).
    /// Returns: Process group ID if found, 0 if not found.
    pub fn get_process_group(
        self: *const ProcessGroupManager,
        pid: u64,
        processes: []const Process,
        max_processes: u32,
    ) u64 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Find process in process table.
        var idx: u32 = 0;
        while (idx < max_processes) : (idx += 1) {
            if (processes[idx].allocated and processes[idx].id == pid) {
                // Return process group ID from process struct.
                return processes[idx].pgid;
            }
        }
        
        return 0; // Process not found.
    }
    
    /// Get session ID for a process.
    /// Why: Query which session a process belongs to.
    /// Contract: pid must be valid (non-zero).
    /// Returns: Session ID if found, 0 if not found.
    pub fn get_session(
        self: *const ProcessGroupManager,
        pid: u64,
        processes: []const Process,
        max_processes: u32,
    ) u64 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Find process in process table.
        var idx: u32 = 0;
        while (idx < max_processes) : (idx += 1) {
            if (processes[idx].allocated and processes[idx].id == pid) {
                // Return session ID from process struct.
                return processes[idx].sid;
            }
        }
        
        return 0; // Process not found.
    }
    
    /// Reset manager state.
    /// Why: Clear manager state (for testing or reinitialization).
    pub fn reset(self: *ProcessGroupManager) void {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Reset all groups.
        var idx: u32 = 0;
        while (idx < MAX_PROCESS_GROUPS) : (idx += 1) {
            self.groups[idx] = ProcessGroup.init();
        }
        
        // Reset all sessions.
        idx = 0;
        while (idx < MAX_SESSIONS) : (idx += 1) {
            self.sessions[idx] = Session.init();
        }
        
        self.next_pgid = 1;
        self.next_sid = 1;
    }
};

// Test: process group manager initialization.
test "process group manager init" {
    const manager = ProcessGroupManager.init();
    
    // Assert: Manager must be initialized.
    try std.testing.expect(manager.initialized);
    try std.testing.expect(manager.next_pgid == 1);
    try std.testing.expect(manager.next_sid == 1);
}

// Test: create session.
test "process group manager create session" {
    var manager = ProcessGroupManager.init();
    
    const sid = manager.create_session(1);
    
    // Assert: Session must be created.
    try std.testing.expect(sid != 0);
    try std.testing.expect(sid == 1);
}

// Test: create process group.
test "process group manager create group" {
    var manager = ProcessGroupManager.init();
    
    const sid = manager.create_session(1);
    const pgid = manager.create_group(1, sid, &[_]Process{}, 0);
    
    // Assert: Process group must be created.
    try std.testing.expect(pgid != 0);
    try std.testing.expect(pgid == 1);
}


// === kernel/process_group_limits.zig ===

//! Process Group Resource Limits
//! Why: Enforce resource limits per process group for resource
management.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Maximum number of process group limit entries.
/// Why: Bounded allocation for limit tracking.
const MAX_PROCESS_GROUP_LIMITS: u32 = 64;

/// Resource limit entry for a process group.
/// Why: Track and enforce resource limits per process group.
/// Grain Style: Static allocation, explicit types.
pub const ProcessGroupLimits = struct {
    /// Process group ID.
    pgid: u64,
    
    /// Maximum CPU time allowed (nanoseconds, 0 = unlimited).
    max_cpu_time_ns: u64,
    
    /// Maximum memory allowed (bytes, 0 = unlimited).
    max_memory_bytes: u64,
    
    /// Maximum number of processes allowed (0 = unlimited).
    max_process_count: u32,
    
    /// Whether this entry is allocated (in use).
    allocated: bool,
    
    /// Initialize empty process group limits entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() ProcessGroupLimits {
        return ProcessGroupLimits{
            .pgid = 0,
            .max_cpu_time_ns = 0, // Unlimited by default
            .max_memory_bytes = 0, // Unlimited by default
            .max_process_count = 0, // Unlimited by default
            .allocated = false,
        };
    }
    
    /// Check if CPU time limit is exceeded.
    /// Why: Enforce CPU time limits.
    /// Contract: current_cpu_time_ns must be valid.
    pub fn is_cpu_time_exceeded(
        self: *const ProcessGroupLimits,
        current_cpu_time_ns: u64,
    ) bool {
        // Assert: Entry must be allocated.
        Debug.kassert(self.allocated, "Entry not allocated", .{});
        
        // If limit is 0 (unlimited), never exceeded.
        if (self.max_cpu_time_ns == 0) {
            return false;
        }
        
        // Check if current usage exceeds limit.
        return current_cpu_time_ns > self.max_cpu_time_ns;
    }
    
    /// Check if memory limit is exceeded.
    /// Why: Enforce memory limits.
    /// Contract: current_memory_bytes must be valid.
    pub fn is_memory_exceeded(
        self: *const ProcessGroupLimits,
        current_memory_bytes: u64,
    ) bool {
        // Assert: Entry must be allocated.
        Debug.kassert(self.allocated, "Entry not allocated", .{});
        
        // If limit is 0 (unlimited), never exceeded.
        if (self.max_memory_bytes == 0) {
            return false;
        }
        
        // Check if current usage exceeds limit.
        return current_memory_bytes > self.max_memory_bytes;
    }
    
    /// Check if process count limit is exceeded.
    /// Why: Enforce process count limits.
    /// Contract: current_process_count must be valid.
    pub fn is_process_count_exceeded(
        self: *const ProcessGroupLimits,
        current_process_count: u32,
    ) bool {
        // Assert: Entry must be allocated.
        Debug.kassert(self.allocated, "Entry not allocated", .{});
        
        // If limit is 0 (unlimited), never exceeded.
        if (self.max_process_count == 0) {
            return false;
        }
        
        // Check if current count exceeds limit.
        return current_process_count >= self.max_process_count;
    }
};

/// Process group limits manager.
/// Why: Manage resource limits for all process groups.
/// Grain Style: Static allocation, bounded operations.
pub const ProcessGroupLimitsManager = struct {
    /// Limit entries.
    limits: [MAX_PROCESS_GROUP_LIMITS]ProcessGroupLimits,
    
    /// Whether manager is initialized.
    initialized: bool,
    
    /// Initialize process group limits manager.
    /// Why: Set up manager state.
    pub fn init() ProcessGroupLimitsManager {
        const manager = ProcessGroupLimitsManager{
            .limits = [_]ProcessGroupLimits{ProcessGroupLimits.init()}
** MAX_PROCESS_GROUP_LIMITS,
            .initialized = true,
        };
        
        return manager;
    }
    
    /// Get or create limits entry for a process group.
    /// Why: Track limits for a process group.
    /// Contract: pgid must be valid (non-zero).
    /// Returns: Pointer to limits entry, or null if no free slot.
    pub fn get_or_create_limits(
        self: *ProcessGroupLimitsManager,
        pgid: u64,
    ) ?*ProcessGroupLimits {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        // Try to find existing entry for this process group.
        var idx: u32 = 0;
        while (idx < MAX_PROCESS_GROUP_LIMITS) : (idx += 1) {
            if (self.limits[idx].allocated and self.limits[idx].pgid ==
pgid) {
                return &self.limits[idx];
            }
        }
        
        // No existing entry found, create new one.
        idx = 0;
        while (idx < MAX_PROCESS_GROUP_LIMITS) : (idx += 1) {
            if (!self.limits[idx].allocated) {
                self.limits[idx].pgid = pgid;
                self.limits[idx].max_cpu_time_ns = 0; // Unlimited by
default
                self.limits[idx].max_memory_bytes = 0; // Unlimited by
default
                self.limits[idx].max_process_count = 0; // Unlimited by
default
                self.limits[idx].allocated = true;
                
                return &self.limits[idx];
            }
        }
        
        // No free slot found.
        return null;
    }
    
    /// Get limits entry for a process group.
    /// Why: Retrieve limits for a process group.
    /// Contract: pgid must be valid (non-zero).
    /// Returns: Pointer to limits entry, or null if not found.
    pub fn get_limits(
        self: *const ProcessGroupLimitsManager,
        pgid: u64,
    ) ?*const ProcessGroupLimits {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        // Find existing entry for this process group.
        var idx: u32 = 0;
        while (idx < MAX_PROCESS_GROUP_LIMITS) : (idx += 1) {
            if (self.limits[idx].allocated and self.limits[idx].pgid ==
pgid) {
                return &self.limits[idx];
            }
        }
        
        // Entry not found.
        return null;
    }
    
    /// Set CPU time limit for a process group.
    /// Why: Configure CPU time limits.
    /// Contract: pgid must be valid (non-zero), max_cpu_time_ns must be
valid.
    pub fn set_cpu_time_limit(
        self: *ProcessGroupLimitsManager,
        pgid: u64,
        max_cpu_time_ns: u64,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        const limits_entry = self.get_or_create_limits(pgid);
        if (limits_entry) |entry| {
            entry.max_cpu_time_ns = max_cpu_time_ns;
            return true;
        }
        
        return false;
    }
    
    /// Set memory limit for a process group.
    /// Why: Configure memory limits.
    /// Contract: pgid must be valid (non-zero), max_memory_bytes must
be valid.
    pub fn set_memory_limit(
        self: *ProcessGroupLimitsManager,
        pgid: u64,
        max_memory_bytes: u64,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        const limits_entry = self.get_or_create_limits(pgid);
        if (limits_entry) |entry| {
            entry.max_memory_bytes = max_memory_bytes;
            return true;
        }
        
        return false;
    }
    
    /// Set process count limit for a process group.
    /// Why: Configure process count limits.
    /// Contract: pgid must be valid (non-zero), max_process_count must
be valid.
    pub fn set_process_count_limit(
        self: *ProcessGroupLimitsManager,
        pgid: u64,
        max_process_count: u32,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        const limits_entry = self.get_or_create_limits(pgid);
        if (limits_entry) |entry| {
            entry.max_process_count = max_process_count;
            return true;
        }
        
        return false;
    }
    
    /// Check if process group can spawn a new process.
    /// Why: Enforce process count limits before spawning.
    /// Contract: pgid and current_process_count must be valid.
    pub fn can_spawn_process(
        self: *const ProcessGroupLimitsManager,
        pgid: u64,
        current_process_count: u32,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // If no process group (pgid == 0), allow spawn.
        if (pgid == 0) {
            return true;
        }
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        const limits_entry = self.get_limits(pgid);
        if (limits_entry) |entry| {
            // Check if adding one more process would exceed limit.
            const new_count = current_process_count + 1;
            return !entry.is_process_count_exceeded(new_count);
        }
        
        // No limits set, allow spawn.
        return true;
    }
    
    /// Check if process group can allocate memory.
    /// Why: Enforce memory limits before memory allocation.
    /// Contract: pgid, current_memory_bytes, and requested_bytes must
be valid.
    pub fn can_allocate_memory(
        self: *const ProcessGroupLimitsManager,
        pgid: u64,
        current_memory_bytes: u64,
        requested_bytes: u64,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // If no process group (pgid == 0), allow allocation.
        if (pgid == 0) {
            return true;
        }
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        const limits_entry = self.get_limits(pgid);
        if (limits_entry) |entry| {
            // Check if adding requested bytes would exceed limit.
            const new_memory = current_memory_bytes +% requested_bytes;
// Saturating add
            return !entry.is_memory_exceeded(new_memory);
        }
        
        // No limits set, allow allocation.
        return true;
    }
};


// === kernel/process_group_stats.zig ===

//! Process Group Statistics
//! Why: Track statistics for process groups for monitoring and
debugging.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Process group statistics entry.
/// Why: Track statistics for a single process group.
/// Grain Style: Static allocation, explicit types.
pub const ProcessGroupStats = struct {
    /// Process group ID.
    pgid: u64,
    
    /// Number of processes in this group.
    process_count: u32,
    
    /// Total CPU time used by all processes in this group (nanoseconds).
    total_cpu_time_ns: u64,
    
    /// Total memory used by all processes in this group (bytes).
    total_memory_used: u64,
    
    /// Number of signals sent to this group.
    signals_sent: u32,
    
    /// Number of processes that have exited in this group.
    exited_count: u32,
    
    /// Whether this entry is allocated (in use).
    allocated: bool,
    
    /// Initialize empty process group statistics entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() ProcessGroupStats {
        return ProcessGroupStats{
            .pgid = 0,
            .process_count = 0,
            .total_cpu_time_ns = 0,
            .total_memory_used = 0,
            .signals_sent = 0,
            .exited_count = 0,
            .allocated = false,
        };
    }
    
    /// Reset statistics for this entry.
    /// Why: Clear statistics while keeping entry allocated.
    pub fn reset(self: *ProcessGroupStats) void {
        // Assert: Entry must be allocated.
        Debug.kassert(self.allocated, "Entry not allocated", .{});
        
        self.process_count = 0;
        self.total_cpu_time_ns = 0;
        self.total_memory_used = 0;
        self.signals_sent = 0;
        self.exited_count = 0;
    }
};

/// Maximum number of process group statistics entries.
/// Why: Bounded allocation for statistics tracking.
const MAX_PROCESS_GROUP_STATS: u32 = 64;

/// Process group statistics manager.
/// Why: Track statistics for all process groups.
/// Grain Style: Static allocation, bounded operations.
pub const ProcessGroupStatsManager = struct {
    /// Statistics entries.
    stats: [MAX_PROCESS_GROUP_STATS]ProcessGroupStats,
    
    /// Whether manager is initialized.
    initialized: bool,
    
    /// Initialize process group statistics manager.
    /// Why: Set up manager state.
    pub fn init() ProcessGroupStatsManager {
        const manager = ProcessGroupStatsManager{
            .stats = [_]ProcessGroupStats{ProcessGroupStats.init()} **
MAX_PROCESS_GROUP_STATS,
            .initialized = true,
        };
        
        return manager;
    }
    
    /// Get or create statistics entry for a process group.
    /// Why: Track statistics for a process group.
    /// Contract: pgid must be valid (non-zero).
    /// Returns: Pointer to statistics entry, or null if no free slot.
    pub fn get_or_create_stats(
        self: *ProcessGroupStatsManager,
        pgid: u64,
    ) ?*ProcessGroupStats {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        // Try to find existing entry for this process group.
        var idx: u32 = 0;
        while (idx < MAX_PROCESS_GROUP_STATS) : (idx += 1) {
            if (self.stats[idx].allocated and self.stats[idx].pgid ==
pgid) {
                return &self.stats[idx];
            }
        }
        
        // No existing entry found, create new one.
        idx = 0;
        while (idx < MAX_PROCESS_GROUP_STATS) : (idx += 1) {
            if (!self.stats[idx].allocated) {
                self.stats[idx].pgid = pgid;
                self.stats[idx].process_count = 0;
                self.stats[idx].total_cpu_time_ns = 0;
                self.stats[idx].total_memory_used = 0;
                self.stats[idx].signals_sent = 0;
                self.stats[idx].exited_count = 0;
                self.stats[idx].allocated = true;
                
                return &self.stats[idx];
            }
        }
        
        // No free slot found.
        return null;
    }
    
    /// Get statistics entry for a process group.
    /// Why: Retrieve statistics for a process group.
    /// Contract: pgid must be valid (non-zero).
    /// Returns: Pointer to statistics entry, or null if not found.
    pub fn get_stats(
        self: *ProcessGroupStatsManager,
        pgid: u64,
    ) ?*ProcessGroupStats {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        // Find existing entry for this process group.
        var idx: u32 = 0;
        while (idx < MAX_PROCESS_GROUP_STATS) : (idx += 1) {
            if (self.stats[idx].allocated and self.stats[idx].pgid ==
pgid) {
                return &self.stats[idx];
            }
        }
        
        // Entry not found.
        return null;
    }
    
    /// Update process count for a process group.
    /// Why: Track number of processes in a group.
    /// Contract: pgid must be valid (non-zero).
    pub fn update_process_count(
        self: *ProcessGroupStatsManager,
        pgid: u64,
        count: u32,
    ) void {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        const stats_entry = self.get_or_create_stats(pgid);
        if (stats_entry) |entry| {
            entry.process_count = count;
        }
    }
    
    /// Add CPU time to a process group.
    /// Why: Track CPU time usage for a process group.
    /// Contract: pgid must be valid (non-zero), cpu_time_ns must be
valid.
    pub fn add_cpu_time(
        self: *ProcessGroupStatsManager,
        pgid: u64,
        cpu_time_ns: u64,
    ) void {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        const stats_entry = self.get_or_create_stats(pgid);
        if (stats_entry) |entry| {
            // Saturating add to prevent overflow.
            entry.total_cpu_time_ns = entry.total_cpu_time_ns +%
cpu_time_ns;
        }
    }
    
    /// Add memory usage to a process group.
    /// Why: Track memory usage for a process group.
    /// Contract: pgid must be valid (non-zero), memory_bytes must be
valid.
    pub fn add_memory_used(
        self: *ProcessGroupStatsManager,
        pgid: u64,
        memory_bytes: u64,
    ) void {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        const stats_entry = self.get_or_create_stats(pgid);
        if (stats_entry) |entry| {
            // Saturating add to prevent overflow.
            entry.total_memory_used = entry.total_memory_used +%
memory_bytes;
        }
    }
    
    /// Increment signal count for a process group.
    /// Why: Track number of signals sent to a process group.
    /// Contract: pgid must be valid (non-zero).
    pub fn increment_signal_count(
        self: *ProcessGroupStatsManager,
        pgid: u64,
    ) void {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        const stats_entry = self.get_or_create_stats(pgid);
        if (stats_entry) |entry| {
            // Saturating increment to prevent overflow.
            entry.signals_sent = entry.signals_sent +% 1;
        }
    }
    
    /// Increment exited count for a process group.
    /// Why: Track number of processes that have exited in a group.
    /// Contract: pgid must be valid (non-zero).
    pub fn increment_exited_count(
        self: *ProcessGroupStatsManager,
        pgid: u64,
    ) void {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Process group ID must be valid (non-zero).
        Debug.kassert(pgid != 0, "Process group ID is 0", .{});
        
        const stats_entry = self.get_or_create_stats(pgid);
        if (stats_entry) |entry| {
            // Saturating increment to prevent overflow.
            entry.exited_count = entry.exited_count +% 1;
        }
    }
    
    /// Reset all statistics.
    /// Why: Clear all statistics entries.
    pub fn reset_all(self: *ProcessGroupStatsManager) void {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        var idx: u32 = 0;
        while (idx < MAX_PROCESS_GROUP_STATS) : (idx += 1) {
            if (self.stats[idx].allocated) {
                self.stats[idx].reset();
            }
        }
    }
    
    /// Print statistics for all process groups.
    /// Why: Debug output for process group statistics.
    pub fn print_stats(self: *const ProcessGroupStatsManager) void {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        var active_count: u32 = 0;
        var idx: u32 = 0;
        while (idx < MAX_PROCESS_GROUP_STATS) : (idx += 1) {
            if (self.stats[idx].allocated) {
                active_count += 1;
            }
        }
        
        std.debug.print("Process Group Statistics:\n", .{});
        std.debug.print("  Active groups: {d}\n", .{active_count});
        
        idx = 0;
        while (idx < MAX_PROCESS_GROUP_STATS) : (idx += 1) {
            if (self.stats[idx].allocated) {
                const entry = &self.stats[idx];
                std.debug.print("  PGID {d}:\n", .{entry.pgid});
                std.debug.print("    Processes: {d}\n",
.{entry.process_count});
                std.debug.print("    CPU time: {d} ns\n",
.{entry.total_cpu_time_ns});
                std.debug.print("    Memory: {d} bytes\n",
.{entry.total_memory_used});
                std.debug.print("    Signals sent: {d}\n",
.{entry.signals_sent});
                std.debug.print("    Exited: {d}\n",
.{entry.exited_count});
            }
        }
    }
};


// === kernel/raw_io.zig ===

// QEMU RISC-V virt machine UART0 address
const UART0_BASE: usize = 0x10000000;

// Global flag to disable RawIO in test mode.
// Why: In tests, hardware addresses don't exist, so we need to avoid
writing to them.
// Grain Style: Explicit flag, no magic numbers.
var raw_io_enabled: bool = true;

/// Disable RawIO (for testing).
/// Why: Allow tests to disable hardware access to avoid SIGILL.
pub fn disable() void {
    raw_io_enabled = false;
}

/// Enable RawIO (for production).
/// Why: Allow re-enabling hardware access after tests.
pub fn enable() void {
    raw_io_enabled = true;
}

pub fn write(msg: []const u8) void {
    // Why: In test mode, skip hardware access to avoid SIGILL.
    if (!raw_io_enabled) {
        return; // No-op when disabled
    }
    
    const uart = @as(*volatile u8, @ptrFromInt(UART0_BASE));
    for (msg) |c| {
        // Wait for THR (Transmitter Holding Register) to be empty?
        // For QEMU/Simple UART we can usually just write.
        // In a real driver we'd check LSR (Line Status Register) bit 5.
        // const lsr = @as(*volatile u8, @ptrFromInt(UART0_BASE + 5));
        // while ((lsr.* & 0x20) == 0) {}
        
        uart.* = c;
    }
}

pub fn write_byte(c: u8) void {
    // Why: In test mode, skip hardware access to avoid SIGILL.
    if (!raw_io_enabled) {
        return; // No-op when disabled
    }
    
    const uart = @as(*volatile u8, @ptrFromInt(UART0_BASE));
    uart.* = c;
}

// === kernel/resource_cleanup.zig ===

//! Resource Cleanup for Process Termination
//! Why: Clean up process resources (memory mappings, handles, channels)
when process exits.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");
const BasinKernel = @import("basin_kernel.zig").BasinKernel;
const ProcessState = @import("basin_kernel.zig").ProcessState;

/// Clean up all resources owned by a process.
/// Why: Free memory mappings, handles, and channels when process exits.
/// Contract: process_id must be valid, kernel must be initialized.
/// Returns: Number of resources cleaned up (mappings + handles +
channels).
/// Grain Style: Explicit types, bounded operations, static allocation.
pub fn cleanup_process_resources(
    kernel: *BasinKernel,
    process_id: u32,
) u32 {
    // Assert: Kernel must be initialized (precondition).
    const kernel_ptr = @intFromPtr(kernel);
    Debug.kassert(kernel_ptr != 0, "Kernel ptr is null", .{});
    Debug.kassert(kernel_ptr % @alignOf(BasinKernel) == 0, "Kernel ptr
unaligned", .{});

    // Assert: Process ID must be valid (non-zero).
    Debug.kassert(process_id != 0, "Process ID is 0", .{});

    // Clean up memory mappings owned by process.
    // Why: Free memory mappings when process exits.
    const mappings_freed = cleanup_process_mappings(kernel, process_id);

    // Clean up file handles owned by process.
    // Why: Close file handles when process exits.
    const handles_closed = cleanup_process_handles(kernel, process_id);

    // Clean up IPC channels owned by process.
    // Why: Close IPC channels when process exits.
    const channels_closed = cleanup_process_channels(kernel, process_id);

    // Assert: Resource counts must be reasonable (postcondition).
    const MAX_RESOURCES: u32 = 1000; // Reasonable limit
    Debug.kassert(mappings_freed <= MAX_RESOURCES, "Mappings freed too
large", .{});
    Debug.kassert(handles_closed <= MAX_RESOURCES, "Handles closed too
large", .{});
    Debug.kassert(channels_closed <= MAX_RESOURCES, "Channels closed too
large", .{});

    const total_cleaned = mappings_freed + handles_closed +
channels_closed;

    // Assert: Total cleaned must be reasonable (postcondition).
    Debug.kassert(total_cleaned <= MAX_RESOURCES * 3, "Total cleaned too
large", .{});

    return total_cleaned;
}

/// Clean up memory mappings owned by a process.
/// Why: Free memory mappings when process exits.
/// Contract: process_id must be valid, kernel must be initialized.
/// Returns: Number of mappings freed.
/// Grain Style: Explicit types, bounded operations, static allocation.
fn cleanup_process_mappings(
    kernel: *BasinKernel,
    process_id: u32,
) u32 {
    // Assert: Kernel must be initialized (precondition).
    const kernel_ptr = @intFromPtr(kernel);
    Debug.kassert(kernel_ptr != 0, "Kernel ptr is null", .{});

    // Assert: Process ID must be valid (non-zero).
    Debug.kassert(process_id != 0, "Process ID is 0", .{});

    // Free all memory mappings owned by this process.
    // Why: Process memory mappings should be freed on exit.
    var mappings_freed: u32 = 0;
    const MAX_MAPPINGS: u32 = 256; // Matches MAX_MAPPINGS in
basin_kernel.zig

    var i: u32 = 0;
    while (i < MAX_MAPPINGS) : (i += 1) {
        const mapping = &kernel.mappings[i];
        if (mapping.allocated and mapping.owner_process_id ==
process_id) {
            // Free mapping (mark as unallocated).
            // Why: Free memory mapping when process exits.
            mapping.allocated = false;
            mapping.owner_process_id = 0;
            mappings_freed += 1;

            // Assert: Mapping must be freed (postcondition).
            Debug.kassert(!mapping.allocated, "Mapping not freed", .{});
            Debug.kassert(mapping.owner_process_id == 0, "Owner not
cleared", .{});
        }
    }

    // Assert: Mappings freed must be reasonable (postcondition).
    Debug.kassert(mappings_freed <= MAX_MAPPINGS, "Mappings freed too
large", .{});

    return mappings_freed;
}

/// Clean up file handles owned by a process.
/// Why: Close file handles when process exits.
/// Contract: process_id must be valid, kernel must be initialized.
/// Returns: Number of handles closed.
/// Grain Style: Explicit types, bounded operations, static allocation.
fn cleanup_process_handles(
    kernel: *BasinKernel,
    process_id: u32,
) u32 {
    // Assert: Kernel must be initialized (precondition).
    const kernel_ptr = @intFromPtr(kernel);
    Debug.kassert(kernel_ptr != 0, "Kernel ptr is null", .{});

    // Assert: Process ID must be valid (non-zero).
    Debug.kassert(process_id != 0, "Process ID is 0", .{});

    // Close all file handles owned by this process.
    // Why: Process file handles should be closed on exit.
    var handles_closed: u32 = 0;
    const MAX_HANDLES: u32 = 256; // Matches MAX_HANDLES in
basin_kernel.zig

    var i: u32 = 0;
    while (i < MAX_HANDLES) : (i += 1) {
        const handle = &kernel.handles[i];
        if (handle.allocated and handle.owner_process_id == process_id) {
            // Close handle (mark as unallocated).
            // Why: Close file handle when process exits.
            handle.allocated = false;
            handle.owner_process_id = 0;
            handles_closed += 1;

            // Assert: Handle must be closed (postcondition).
            Debug.kassert(!handle.allocated, "Handle not closed", .{});
            Debug.kassert(handle.owner_process_id == 0, "Owner not
cleared", .{});
        }
    }

    // Assert: Handles closed must be reasonable (postcondition).
    Debug.kassert(handles_closed <= MAX_HANDLES, "Handles closed too
large", .{});

    return handles_closed;
}

/// Clean up IPC channels owned by a process.
/// Why: Close IPC channels when process exits.
/// Contract: process_id must be valid, kernel must be initialized.
/// Returns: Number of channels closed.
/// Grain Style: Explicit types, bounded operations, static allocation.
fn cleanup_process_channels(
    kernel: *BasinKernel,
    process_id: u32,
) u32 {
    // Assert: Kernel must be initialized (precondition).
    const kernel_ptr = @intFromPtr(kernel);
    Debug.kassert(kernel_ptr != 0, "Kernel ptr is null", .{});

    // Assert: Process ID must be valid (non-zero).
    Debug.kassert(process_id != 0, "Process ID is 0", .{});

    // Close all IPC channels owned by this process.
    // Why: Process IPC channels should be closed on exit.
    var channels_closed: u32 = 0;
    const MAX_CHANNELS: u32 = 64; // Matches ChannelTable size

    var i: u32 = 0;
    while (i < MAX_CHANNELS) : (i += 1) {
        const channel = &kernel.channels.channels[i];
        if (channel.allocated and channel.owner_process_id ==
process_id) {
            // Close channel (mark as unallocated).
            // Why: Close IPC channel when process exits.
            channel.allocated = false;
            channel.owner_process_id = 0;
            channels_closed += 1;

            // Assert: Channel must be closed (postcondition).
            Debug.kassert(!channel.allocated, "Channel not closed", .{});
            Debug.kassert(channel.owner_process_id == 0, "Owner not
cleared", .{});
        }
    }

    // Assert: Channels closed must be reasonable (postcondition).
    Debug.kassert(channels_closed <= MAX_CHANNELS, "Channels closed too
large", .{});

    return channels_closed;
}


// === kernel/scheduler.zig ===

//! Grain Basin Process Scheduler
//! Why: Manage process execution, scheduling, and state transitions.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");
const ProcessState = @import("basin_kernel.zig").ProcessState;
const Process = @import("basin_kernel.zig").Process;
const scheduler_stats = @import("scheduler_stats.zig");
const SchedulerStats = scheduler_stats.SchedulerStats;

/// Process scheduler for Grain Basin kernel.
/// Why: Manage process execution order and state management.
/// Grain Style: Static allocation, explicit state tracking.
pub const Scheduler = struct {
    /// Current running process ID (0 = no process running).
    /// Why: Track which process is currently executing.
    current_pid: u64,
    
    /// Next process to schedule (round-robin index).
    /// Why: Track position in round-robin scheduling.
    next_index: u32,
    
    /// Time slice remaining for current process (instruction steps).
    /// Why: Track remaining time before preemption.
    time_slice_remaining: u64,
    
    /// Whether scheduler is initialized.
    /// Why: Track initialization state for safety.
    initialized: bool,
    
    /// Scheduler statistics tracker.
    /// Why: Track scheduler behavior and performance metrics.
    stats: SchedulerStats,
    
    /// Initialize scheduler.
    /// Why: Set up scheduler state.
    /// Contract: Must be called once at kernel boot.
    pub fn init() Scheduler {
        return Scheduler{
            .current_pid = 0,
            .next_index = 0,
            .time_slice_remaining = 0,
            .initialized = true,
            .stats = SchedulerStats.init(),
        };
    }
    
    /// Set current running process with time slice.
    /// Why: Update scheduler state when process starts.
    /// Contract: pid must be valid (non-zero), time_slice must be > 0.
    pub fn set_current(self: *Scheduler, pid: u64, time_slice: u64) void
{
        // Assert: Scheduler must be initialized.
        Debug.kassert(self.initialized, "Scheduler not initialized",
.{});
        
        // Assert: Process ID must be valid (non-zero).
        Debug.kassert(pid != 0, "Process ID is 0", .{});
        
        // Assert: Time slice must be positive.
        Debug.kassert(time_slice > 0, "Time slice must be > 0", .{});
        
        // Record context switch if switching to different process.
        if (self.current_pid != 0 and self.current_pid != pid) {
            self.stats.record_context_switch();
        }
        
        self.current_pid = pid;
        self.time_slice_remaining = time_slice;
        self.stats.record_process_scheduled();
        
        // Assert: Current PID must be set.
        Debug.kassert(self.current_pid == pid, "Current PID not set",
.{});
        
        // Assert: Time slice must be set.
        Debug.kassert(self.time_slice_remaining == time_slice, "Time
slice not set", .{});
    }
    
    /// Decrement time slice for current process.
    /// Why: Track time slice usage during execution.
    /// Contract: Must be called during process execution.
    /// Returns: true if time slice expired, false otherwise.
    pub fn decrement_time_slice(self: *Scheduler, steps: u64) bool {
        // Assert: Scheduler must be initialized.
        Debug.kassert(self.initialized, "Scheduler not initialized",
.{});
        
        // Assert: Current PID must be set.
        Debug.kassert(self.current_pid != 0, "Current PID is 0", .{});
        
        // Decrement time slice (saturating subtract to prevent
underflow).
        if (self.time_slice_remaining > steps) {
            self.time_slice_remaining -= steps;
            return false;
        } else {
            // Time slice expired.
            self.time_slice_remaining = 0;
            self.stats.record_time_slice_expiration();
            self.stats.record_preemption();
            return true;
        }
    }
    
    /// Check if current process time slice expired.
    /// Why: Determine if process should be preempted.
    /// Contract: Must be called during process execution.
    /// Returns: true if time slice expired, false otherwise.
    pub fn is_time_slice_expired(self: *const Scheduler) bool {
        // Assert: Scheduler must be initialized.
        Debug.kassert(self.initialized, "Scheduler not initialized",
.{});
        
        return self.time_slice_remaining == 0;
    }
    
    /// Get remaining time slice for current process.
    /// Why: Query remaining time before preemption.
    /// Contract: Returns 0 if no process running or time slice expired.
    pub fn get_time_slice_remaining(self: *const Scheduler) u64 {
        // Assert: Scheduler must be initialized.
        Debug.kassert(self.initialized, "Scheduler not initialized",
.{});
        
        return self.time_slice_remaining;
    }
    
    /// Get current running process ID.
    /// Why: Query which process is currently executing.
    /// Contract: Returns 0 if no process running.
    pub fn get_current(self: *const Scheduler) u64 {
        // Assert: Scheduler must be initialized.
        Debug.kassert(self.initialized, "Scheduler not initialized",
.{});
        
        return self.current_pid;
    }
    
    /// Clear current running process.
    /// Why: Update scheduler when process exits.
    /// Contract: Must be called when process terminates.
    pub fn clear_current(self: *Scheduler) void {
        // Assert: Scheduler must be initialized.
        Debug.kassert(self.initialized, "Scheduler not initialized",
.{});
        
        // Assert: Current PID must be non-zero before clearing.
        Debug.kassert(self.current_pid != 0, "Current PID already 0",
.{});
        
        self.current_pid = 0;
        self.time_slice_remaining = 0;
        
        // Assert: Current PID must be cleared.
        Debug.kassert(self.current_pid == 0, "Current PID not cleared",
.{});
        
        // Assert: Time slice must be cleared.
        Debug.kassert(self.time_slice_remaining == 0, "Time slice not
cleared", .{});
    }
    
    /// Find next runnable process (priority-based with round-robin
fallback).
    /// Why: Select highest priority process, using round-robin for same
priority.
    /// Contract: processes array must be valid, max_processes must be
<= array length.
    /// Returns: Process ID if found, 0 if no runnable process.
    pub fn find_next_runnable(
        self: *Scheduler,
        processes: []const Process,
        max_processes: u32,
    ) u64 {
        // Assert: Scheduler must be initialized.
        Debug.kassert(self.initialized, "Scheduler not initialized",
.{});
        
        // Assert: max_processes must be <= array length.
        Debug.kassert(max_processes <= processes.len, "Max processes >
array length", .{});
        
        // Find highest priority runnable process.
        var best_priority: i8 = 20; // Start with lowest priority
(highest nice value).
        var best_pid: u64 = 0;
        var best_idx: u32 = 0;
        var found_count: u32 = 0;
        
        // First pass: find highest priority (lowest nice value).
        var idx: u32 = 0;
        while (idx < max_processes) : (idx += 1) {
            const process = processes[idx];
            
            // Check if process is runnable (allocated and running).
            if (process.id != 0 and process.state == .running) {
                const priority = process.priority;
                
                // Lower nice value = higher priority.
                if (priority < best_priority) {
                    best_priority = priority;
                    best_pid = process.id;
                    best_idx = idx;
                    found_count = 1;
                } else if (priority == best_priority) {
                    found_count += 1;
                }
            }
        }
        
        // If no runnable process found, return 0.
        if (best_pid == 0) {
            return 0;
        }
        
        // If only one process with best priority, return it.
        if (found_count == 1) {
            self.next_index = (best_idx + 1) % max_processes;
            self.stats.record_priority_selection();
            self.stats.record_scheduling_decision();
            return best_pid;
        }
        
        // Multiple processes with same priority: use round-robin.
        self.stats.record_round_robin_selection();
        self.stats.record_scheduling_decision();
        return self.find_next_runnable_round_robin(processes,
max_processes, best_priority);
    }
    
    /// Find next runnable process with specific priority (round-robin).
    /// Why: Round-robin among processes with same priority.
    /// Contract: processes array must be valid, max_processes must be
<= array length.
    /// Returns: Process ID if found, 0 if no runnable process.
    fn find_next_runnable_round_robin(
        self: *Scheduler,
        processes: []const Process,
        max_processes: u32,
        target_priority: i8,
    ) u64 {
        // Round-robin: start from next_index, wrap around.
        var checked: u32 = 0;
        var idx: u32 = self.next_index;
        
        while (checked < max_processes) : (checked += 1) {
            // Assert: Index must be within bounds.
            Debug.kassert(idx < max_processes, "Index >= max_processes",
.{});
            
            const process = processes[idx];
            
            // Check if process is runnable with target priority.
            if (process.id != 0 and process.state == .running and
process.priority == target_priority) {
                // Update next_index for next round-robin.
                self.next_index = (idx + 1) % max_processes;
                
                // Assert: Process ID must be non-zero.
                Debug.kassert(process.id != 0, "Process ID is 0", .{});
                
                return process.id;
            }
            
            // Move to next index (wrap around).
            idx = (idx + 1) % max_processes;
        }
        
        // No runnable process found with target priority.
        return 0;
    }
    
    /// Check if process is current running process.
    /// Why: Validate process state for operations.
    /// Contract: pid must be valid (non-zero).
    pub fn is_current(self: *const Scheduler, pid: u64) bool {
        // Assert: Scheduler must be initialized.
        Debug.kassert(self.initialized, "Scheduler not initialized",
.{});
        
        // Assert: Process ID must be valid (non-zero).
        Debug.kassert(pid != 0, "Process ID is 0", .{});
        
        return self.current_pid == pid;
    }
    
    /// Get scheduler statistics.
    /// Why: Access scheduler behavior metrics for monitoring.
    /// Contract: Returns reference to statistics tracker.
    pub fn get_stats(self: *const Scheduler) *const SchedulerStats {
        // Assert: Scheduler must be initialized.
        Debug.kassert(self.initialized, "Scheduler not initialized",
.{});
        
        return &self.stats;
    }
    
    /// Reset scheduler state.
    /// Why: Clear scheduler state (for testing or reinitialization).
    /// Contract: Must be called when all processes are terminated.
    pub fn reset(self: *Scheduler) void {
        // Assert: Scheduler must be initialized.
        Debug.kassert(self.initialized, "Scheduler not initialized",
.{});
        
        self.current_pid = 0;
        self.next_index = 0;
        self.time_slice_remaining = 0;
        self.stats.reset();
        
        // Assert: Scheduler must be reset.
        Debug.kassert(self.current_pid == 0, "Current PID not reset",
.{});
        Debug.kassert(self.next_index == 0, "Next index not reset", .{});
        Debug.kassert(self.time_slice_remaining == 0, "Time slice not
reset", .{});
    }
};

// Test scheduler initialization.
test "scheduler init" {
    const scheduler = Scheduler.init();
    
    // Assert: Scheduler must be initialized.
    try std.testing.expect(scheduler.initialized);
    try std.testing.expect(scheduler.current_pid == 0);
    try std.testing.expect(scheduler.next_index == 0);
}

// Test set current process.
test "scheduler set current" {
    var scheduler = Scheduler.init();
    
    const pid: u64 = 1;
    const time_slice: u64 = 1000;
    scheduler.set_current(pid, time_slice);
    
    // Assert: Current PID must be set.
    try std.testing.expect(scheduler.get_current() == pid);
    try std.testing.expect(scheduler.is_current(pid));
    try std.testing.expect(scheduler.get_time_slice_remaining() ==
time_slice);
}

// Test clear current process.
test "scheduler clear current" {
    var scheduler = Scheduler.init();
    
    scheduler.set_current(1, 1000);
    scheduler.clear_current();
    
    // Assert: Current PID must be cleared.
    try std.testing.expect(scheduler.get_current() == 0);
    try std.testing.expect(!scheduler.is_current(1));
    try std.testing.expect(scheduler.get_time_slice_remaining() == 0);
}

// Test find next runnable process (priority-based).
test "scheduler find next runnable priority" {
    var scheduler = Scheduler.init();
    
    // Create processes with different priorities.
    var processes = [_]Process{
        Process.init(),
        Process.init(),
        Process.init(),
        Process.init(),
    };
    
    // Process 1: priority -10 (high priority).
    processes[0].id = 1;
    processes[0].state = .running;
    processes[0].allocated = true;
    processes[0].priority = -10;
    
    // Process 2: priority 0 (normal priority).
    processes[1].id = 2;
    processes[1].state = .running;
    processes[1].allocated = true;
    processes[1].priority = 0;
    
    // Process 3: priority 10 (low priority).
    processes[2].id = 3;
    processes[2].state = .running;
    processes[2].allocated = true;
    processes[2].priority = 10;
    
    // Process 4: not allocated.
    processes[3].id = 0;
    processes[3].state = .free;
    
    // Should select process 1 (highest priority, -10).
    const pid1 = scheduler.find_next_runnable(&processes, 4);
    try std.testing.expect(pid1 == 1);
    
    // Process 1 exits, should select process 2 (priority 0).
    processes[0].state = .exited;
    const pid2 = scheduler.find_next_runnable(&processes, 4);
    try std.testing.expect(pid2 == 2);
}

// Test find next runnable process (round-robin for same priority).
test "scheduler find next runnable round robin" {
    var scheduler = Scheduler.init();
    
    // Create processes with same priority.
    var processes = [_]Process{
        Process.init(),
        Process.init(),
        Process.init(),
    };
    
    // All processes have priority 0.
    processes[0].id = 1;
    processes[0].state = .running;
    processes[0].allocated = true;
    processes[0].priority = 0;
    
    processes[1].id = 2;
    processes[1].state = .running;
    processes[1].allocated = true;
    processes[1].priority = 0;
    
    processes[2].id = 3;
    processes[2].state = .running;
    processes[2].allocated = true;
    processes[2].priority = 0;
    
    // Should round-robin through processes with same priority.
    const pid1 = scheduler.find_next_runnable(&processes, 3);
    try std.testing.expect(pid1 == 1 or pid1 == 2 or pid1 == 3);
    
    const pid2 = scheduler.find_next_runnable(&processes, 3);
    try std.testing.expect(pid2 == 1 or pid2 == 2 or pid2 == 3);
    try std.testing.expect(pid2 != pid1); // Should be different.
}

// Test reset scheduler.
test "scheduler reset" {
    var scheduler = Scheduler.init();
    
    scheduler.set_current(1, 1000);
    scheduler.reset();
    
    // Assert: Scheduler must be reset.
    try std.testing.expect(scheduler.get_current() == 0);
    try std.testing.expect(scheduler.next_index == 0);
    try std.testing.expect(scheduler.time_slice_remaining == 0);
}

// Test time slice decrement.
test "scheduler decrement time slice" {
    var scheduler = Scheduler.init();
    
    scheduler.set_current(1, 1000);
    
    // Decrement by 100 steps.
    const expired1 = scheduler.decrement_time_slice(100);
    try std.testing.expect(!expired1);
    try std.testing.expect(scheduler.get_time_slice_remaining() == 900);
    
    // Decrement by 900 steps (should expire).
    const expired2 = scheduler.decrement_time_slice(900);
    try std.testing.expect(expired2);
    try std.testing.expect(scheduler.get_time_slice_remaining() == 0);
    try std.testing.expect(scheduler.is_time_slice_expired());
    
    // Test saturating subtract (decrement beyond 0).
    const expired3 = scheduler.decrement_time_slice(100);
    try std.testing.expect(expired3);
    try std.testing.expect(scheduler.get_time_slice_remaining() == 0);
}

// Test time slice expiration check.
test "scheduler time slice expiration" {
    var scheduler = Scheduler.init();
    
    scheduler.set_current(1, 1000);
    try std.testing.expect(!scheduler.is_time_slice_expired());
    
    const expired = scheduler.decrement_time_slice(1000);
    try std.testing.expect(expired);
    try std.testing.expect(scheduler.is_time_slice_expired());
}


// === kernel/scheduler_stats.zig ===

//! Scheduler Statistics Tracking System
//!
//! Objective: Track scheduler behavior and performance for monitoring.
//! Why: Monitor scheduling decisions, preemptions, and context switches.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track total scheduling decisions
//! - Track preemptions and context switches
//! - Track priority-based vs round-robin selections
//! - Track time slice expirations
//! - Provide statistics interface for querying scheduler data
//! - Reset capability for new measurement periods
//!
//! GrainStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-12-03
//! GrainStyle: Comprehensive scheduler tracking, deterministic
behavior, explicit limits

const std = @import("std");
const Debug = @import("debug.zig");

/// Scheduler statistics tracker.
/// Why: Track scheduler behavior and performance metrics.
/// GrainStyle: Static allocation, bounded counters, explicit types.
pub const SchedulerStats = struct {
    /// Total scheduling decisions made.
    /// Why: Track how many times scheduler selected a process.
    total_scheduling_decisions: u64,
    
    /// Total preemptions (time slice expirations).
    /// Why: Track how many times processes were preempted.
    total_preemptions: u64,
    
    /// Total context switches (process switches).
    /// Why: Track how many times scheduler switched processes.
    total_context_switches: u64,
    
    /// Total processes scheduled.
    /// Why: Track how many unique processes were scheduled.
    total_processes_scheduled: u64,
    
    /// Total priority-based selections.
    /// Why: Track how many times priority-based selection was used.
    priority_based_selections: u64,
    
    /// Total round-robin selections.
    /// Why: Track how many times round-robin selection was used.
    round_robin_selections: u64,
    
    /// Total time slice expirations.
    /// Why: Track how many times time slices expired.
    time_slice_expirations: u64,
    
    /// Initialize scheduler statistics.
    /// Why: Set up statistics tracker with zero counters.
    pub fn init() SchedulerStats {
        return SchedulerStats{
            .total_scheduling_decisions = 0,
            .total_preemptions = 0,
            .total_context_switches = 0,
            .total_processes_scheduled = 0,
            .priority_based_selections = 0,
            .round_robin_selections = 0,
            .time_slice_expirations = 0,
        };
    }
    
    /// Record a scheduling decision.
    /// Why: Track when scheduler selects a process.
    pub fn record_scheduling_decision(self: *SchedulerStats) void {
        self.total_scheduling_decisions += 1;
        
        // Assert: Counter must be incremented (postcondition).
        Debug.kassert(self.total_scheduling_decisions > 0, "Counter not
incremented", .{});
    }
    
    /// Record a preemption.
    /// Why: Track when a process is preempted.
    pub fn record_preemption(self: *SchedulerStats) void {
        self.total_preemptions += 1;
        
        // Assert: Counter must be incremented (postcondition).
        Debug.kassert(self.total_preemptions > 0, "Counter not
incremented", .{});
    }
    
    /// Record a context switch.
    /// Why: Track when scheduler switches to a different process.
    pub fn record_context_switch(self: *SchedulerStats) void {
        self.total_context_switches += 1;
        
        // Assert: Counter must be incremented (postcondition).
        Debug.kassert(self.total_context_switches > 0, "Counter not
incremented", .{});
    }
    
    /// Record a process scheduled.
    /// Why: Track when a process is scheduled for execution.
    pub fn record_process_scheduled(self: *SchedulerStats) void {
        self.total_processes_scheduled += 1;
        
        // Assert: Counter must be incremented (postcondition).
        Debug.kassert(self.total_processes_scheduled > 0, "Counter not
incremented", .{});
    }
    
    /// Record a priority-based selection.
    /// Why: Track when priority-based selection is used.
    pub fn record_priority_selection(self: *SchedulerStats) void {
        self.priority_based_selections += 1;
        
        // Assert: Counter must be incremented (postcondition).
        Debug.kassert(self.priority_based_selections > 0, "Counter not
incremented", .{});
    }
    
    /// Record a round-robin selection.
    /// Why: Track when round-robin selection is used.
    pub fn record_round_robin_selection(self: *SchedulerStats) void {
        self.round_robin_selections += 1;
        
        // Assert: Counter must be incremented (postcondition).
        Debug.kassert(self.round_robin_selections > 0, "Counter not
incremented", .{});
    }
    
    /// Record a time slice expiration.
    /// Why: Track when a time slice expires.
    pub fn record_time_slice_expiration(self: *SchedulerStats) void {
        self.time_slice_expirations += 1;
        
        // Assert: Counter must be incremented (postcondition).
        Debug.kassert(self.time_slice_expirations > 0, "Counter not
incremented", .{});
    }
    
    /// Print scheduler statistics.
    /// Why: Display scheduler behavior metrics for monitoring.
    pub fn print_stats(self: *const SchedulerStats) void {
        std.debug.print("\nScheduler Statistics:\n", .{});
        std.debug.print("  Total Scheduling Decisions: {}\n",
.{self.total_scheduling_decisions});
        std.debug.print("  Total Preemptions: {}\n",
.{self.total_preemptions});
        std.debug.print("  Total Context Switches: {}\n",
.{self.total_context_switches});
        std.debug.print("  Total Processes Scheduled: {}\n",
.{self.total_processes_scheduled});
        std.debug.print("  Priority-Based Selections: {}\n",
.{self.priority_based_selections});
        std.debug.print("  Round-Robin Selections: {}\n",
.{self.round_robin_selections});
        std.debug.print("  Time Slice Expirations: {}\n",
.{self.time_slice_expirations});
        
        // Calculate percentages if applicable.
        if (self.total_scheduling_decisions > 0) {
            const priority_pct = @as(f64,
@floatFromInt(self.priority_based_selections)) /
                @as(f64, @floatFromInt(self.total_scheduling_decisions))
* 100.0;
            const round_robin_pct = @as(f64,
@floatFromInt(self.round_robin_selections)) /
                @as(f64, @floatFromInt(self.total_scheduling_decisions))
* 100.0;
            std.debug.print("  Priority Selection Rate: {d:.2}%\n",
.{priority_pct});
            std.debug.print("  Round-Robin Selection Rate: {d:.2}%\n",
.{round_robin_pct});
        }
    }
    
    /// Reset all statistics.
    /// Why: Clear counters for new measurement period.
    pub fn reset(self: *SchedulerStats) void {
        self.total_scheduling_decisions = 0;
        self.total_preemptions = 0;
        self.total_context_switches = 0;
        self.total_processes_scheduled = 0;
        self.priority_based_selections = 0;
        self.round_robin_selections = 0;
        self.time_slice_expirations = 0;
        
        // Assert: All counters must be zero (postcondition).
        Debug.kassert(self.total_scheduling_decisions == 0, "Counter not
reset", .{});
        Debug.kassert(self.total_preemptions == 0, "Counter not reset",
.{});
        Debug.kassert(self.total_context_switches == 0, "Counter not
reset", .{});
    }
};

// Test: scheduler statistics initialization.
test "scheduler stats init" {
    const stats = SchedulerStats.init();
    
    // Assert: All counters must be zero.
    try std.testing.expect(stats.total_scheduling_decisions == 0);
    try std.testing.expect(stats.total_preemptions == 0);
    try std.testing.expect(stats.total_context_switches == 0);
}

// Test: scheduler statistics recording.
test "scheduler stats recording" {
    var stats = SchedulerStats.init();
    
    stats.record_scheduling_decision();
    try std.testing.expect(stats.total_scheduling_decisions == 1);
    
    stats.record_preemption();
    try std.testing.expect(stats.total_preemptions == 1);
    
    stats.record_context_switch();
    try std.testing.expect(stats.total_context_switches == 1);
}

// Test: scheduler statistics reset.
test "scheduler stats reset" {
    var stats = SchedulerStats.init();
    
    stats.record_scheduling_decision();
    stats.record_preemption();
    stats.reset();
    
    // Assert: All counters must be zero after reset.
    try std.testing.expect(stats.total_scheduling_decisions == 0);
    try std.testing.expect(stats.total_preemptions == 0);
}


// === kernel/segment_loader.zig ===

//! Segment Loader for Process Spawning
//! Why: Extract segment loading logic from syscall_spawn to reduce
nesting and function length.
//! Grain Style: Explicit types (u32/u64 not usize), comprehensive
assertions, static allocation.

const std = @import("std");
const Debug = @import("debug.zig");
const elf_parser = @import("elf_parser.zig");
const BasinKernel = @import("basin_kernel.zig").BasinKernel;
const MapFlags = @import("basin_kernel.zig").MapFlags;
const SyscallResult = @import("basin_kernel.zig").SyscallResult;

/// Load a single program segment into VM memory.
/// Why: Extract segment loading logic to reduce nesting in
syscall_spawn.
/// Contract: segment must be valid, read_fn and write_fn must be
non-null, executable must be valid.
/// Returns: true if segment was loaded successfully, false otherwise.
/// Grain Style: Static allocation, explicit types, bounded operations.
pub fn load_program_segment(
    segment: elf_parser.ProgramSegment,
    executable: u64,
    read_fn: *const fn (addr: u64, len: u32, buffer: []u8) ?u32,
    write_fn: *const fn (addr: u64, len: u32, data: []const u8) ?u32,
    kernel: *BasinKernel,
) bool {
    // Assert: Segment must be valid (precondition).
    Debug.kassert(segment.valid, "Segment not valid", .{});
    Debug.kassert(segment.p_type == 1, "Segment not PT_LOAD", .{}); //
PT_LOAD = 1
    
    // Create memory mapping for segment (page-aligned size).
    // Why: Map segment virtual address range with proper permissions.
    const segment_size = segment.p_memsz;
    const page_size: u64 = 4096;
    const aligned_size = ((segment_size + page_size - 1) / page_size) *
page_size;
    
    // Convert segment flags to MapFlags.
    // Why: RISC-V ELF uses PF_R (0x4), PF_W (0x2), PF_X (0x1) flags.
    const PF_R: u32 = 0x4;
    const PF_W: u32 = 0x2;
    const PF_X: u32 = 0x1;
    
    const map_flags = MapFlags{
        .read = (segment.p_flags & PF_R) != 0,
        .write = (segment.p_flags & PF_W) != 0,
        .execute = (segment.p_flags & PF_X) != 0,
        .shared = false,
        ._padding = 0,
    };
    
    // Create mapping for segment (use segment's virtual address).
    // Why: Map segment at its intended virtual address.
    const map_result = kernel.syscall_map(segment.p_vaddr, aligned_size,
@as(u64, @intCast(@as(u32, @bitCast(map_flags)))), 0) catch {
        return false; // Mapping failed
    };
    
    if (map_result != .success) {
        return false; // Mapping failed
    }
    
    // Load segment data into VM memory.
    // Why: Copy segment data from ELF file to VM memory after mapping
is created.
    return load_segment_data(segment, executable, read_fn, write_fn);
}

/// Load segment data from ELF file into VM memory.
/// Why: Extract data loading logic to reduce nesting.
/// Contract: segment must be valid, read_fn and write_fn must be
non-null, executable must be valid.
/// Returns: true if segment data was loaded successfully, false
otherwise.
/// Grain Style: Static allocation, explicit types, bounded operations.
fn load_segment_data(
    segment: elf_parser.ProgramSegment,
    executable: u64,
    read_fn: *const fn (addr: u64, len: u32, buffer: []u8) ?u32,
    write_fn: *const fn (addr: u64, len: u32, data: []const u8) ?u32,
) bool {
    // Assert: Segment must be valid (precondition).
    Debug.kassert(segment.valid, "Segment not valid", .{});
    
    // Read segment data from ELF file.
    // Why: Segment data is at executable + p_offset in ELF file.
    const segment_data_size = @as(u32, @intCast(segment.p_filesz));
    if (segment_data_size == 0) {
        // Empty segment, just zero-fill if needed.
        return zero_fill_bss(segment, write_fn);
    }
    
    // Assert: Segment data size must be reasonable (max 1MB per
segment).
    const MAX_SEGMENT_SIZE: u32 = 1024 * 1024;
    if (segment_data_size > MAX_SEGMENT_SIZE) {
        return false; // Segment too large
    }
    
    // Read segment data from ELF file.
    var segment_data_buffer: [1024 * 1024]u8 = undefined;
    const segment_data = segment_data_buffer[0..segment_data_size];
    
    const bytes_read = read_fn(executable + segment.p_offset,
segment_data_size, segment_data) orelse {
        return false; // Failed to read segment data
    };
    
    if (bytes_read != segment_data_size) {
        return false; // Incomplete read
    }
    
    // Write segment data to VM memory at segment's virtual address.
    const bytes_written = write_fn(segment.p_vaddr, segment_data_size,
segment_data) orelse {
        return false; // Failed to write segment data
    };
    
    // Assert: All segment data must be written.
    Debug.kassert(bytes_written == segment_data_size, "Segment data not
fully written", .{});
    
    // Zero-fill remaining memory if memsz > filesz (BSS section).
    return zero_fill_bss(segment, write_fn);
}

/// Zero-fill BSS section (memory beyond file size).
/// Why: Extract BSS zero-filling logic to reduce nesting.
/// Contract: segment must be valid, write_fn must be non-null.
/// Returns: true if BSS was zero-filled successfully, false otherwise.
/// Grain Style: Static allocation, explicit types, bounded operations.
fn zero_fill_bss(
    segment: elf_parser.ProgramSegment,
    write_fn: *const fn (addr: u64, len: u32, data: []const u8) ?u32,
) bool {
    // Assert: Segment must be valid (precondition).
    Debug.kassert(segment.valid, "Segment not valid", .{});
    
    // Zero-fill remaining memory if memsz > filesz (BSS section).
    if (segment.p_memsz <= segment.p_filesz) {
        return true; // No BSS section
    }
    
    const zero_fill_size = @as(u32, @intCast(segment.p_memsz -
segment.p_filesz));
    const MAX_ZERO_FILL: u32 = 1024 * 1024; // Max 1MB BSS
    
    if (zero_fill_size > MAX_ZERO_FILL) {
        return false; // BSS too large
    }
    
    var zero_buffer: [1024 * 1024]u8 = undefined;
    @memset(zero_buffer[0..zero_fill_size], 0);
    
    const zero_addr = segment.p_vaddr + segment.p_filesz;
    const bytes_written = write_fn(zero_addr, zero_fill_size,
zero_buffer[0..zero_fill_size]) orelse {
        return false; // Failed to zero-fill BSS
    };
    
    // Assert: All BSS must be zero-filled.
    Debug.kassert(bytes_written == zero_fill_size, "BSS not fully
zero-filled", .{});
    
    return true;
}


// === kernel/signal.zig ===

//! Grain Basin Signal Handling
//! Why: Process communication and control via signals (SIGTERM,
SIGKILL, etc.).
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Signal number (POSIX-compatible subset).
/// Why: Explicit signal types for type safety.
pub const Signal = enum(u32) {
    /// Hangup (terminal closed).
    sighup = 1,
    /// Interrupt (Ctrl+C).
    sigint = 2,
    /// Quit (Ctrl+\).
    sigquit = 3,
    /// Illegal instruction.
    sigill = 4,
    /// Abort.
    sigabrt = 6,
    /// Floating point exception.
    sigfpe = 8,
    /// Kill (cannot be caught or ignored).
    sigkill = 9,
    /// User-defined signal 1.
    sigusr1 = 10,
    /// Segmentation fault.
    sigsegv = 11,
    /// User-defined signal 2.
    sigusr2 = 12,
    /// Broken pipe.
    sigpipe = 13,
    /// Alarm clock.
    sigalrm = 14,
    /// Termination request.
    sigterm = 15,
    /// Child process terminated.
    sigchld = 17,
    /// Continue (resume execution).
    sigcont = 18,
    /// Stop (suspend execution).
    sigstop = 19,
    /// Terminal stop (Ctrl+Z).
    sigtstp = 20,
};

/// Signal handler function type.
/// Why: Type-safe signal handler registration.
/// Contract: Handler must be fast, non-blocking, and return void.
pub const SignalHandler = *const fn (signal: Signal, context:
?*anyopaque) void;

/// Signal action (handler + flags).
/// Why: POSIX-compatible signal action structure.
pub const SignalAction = struct {
    /// Signal handler function (optional).
    /// Why: Allow process to handle signals.
    handler: ?SignalHandler = null,
    /// Signal context (optional data for handler).
    /// Why: Allow handlers to access process state.
    context: ?*anyopaque = null,
    /// Signal mask (signals to block during handler).
    /// Why: Prevent signal reentrancy.
    mask: u32 = 0,
    /// Flags (future: SA_RESTART, etc.).
    /// Why: Signal behavior flags.
    flags: u32 = 0,
};

/// Signal table for a process.
/// Why: Track signal handlers and pending signals per process.
/// Grain Style: Static allocation, bounded signals.
pub const SignalTable = struct {
    /// Signal actions (one per signal type).
    /// Why: Store handler for each signal.
    actions: [32]SignalAction = [_]SignalAction{SignalAction{}} ** 32,
    /// Pending signals bitmap (32 signals max).
    /// Why: Track signals waiting to be delivered.
    pending: u32 = 0,
    /// Blocked signals bitmap (32 signals max).
    /// Why: Block signals from being delivered.
    blocked: u32 = 0,
    /// Initialized flag.
    /// Why: Track initialization state.
    initialized: bool = false,

    /// Initialize signal table.
    /// Why: Set up signal handling for a process.
    /// Contract: Must be called before use, sets initialized flag.
    pub fn init() SignalTable {
        var table = SignalTable{
            .actions = [_]SignalAction{SignalAction{}} ** 32,
            .pending = 0,
            .blocked = 0,
            .initialized = false,
        };
        
        // Assert: Table must be uninitialized (precondition).
        Debug.kassert(!table.initialized, "Table already initialized",
.{});
        
        table.initialized = true;
        
        // Assert: Table must be initialized (postcondition).
        Debug.kassert(table.initialized, "Table not initialized", .{});
        Debug.kassert(table.pending == 0, "Pending signals not zero",
.{});
        Debug.kassert(table.blocked == 0, "Blocked signals not zero",
.{});
        
        return table;
    }

    /// Register signal handler.
    /// Why: Allow process to handle specific signals.
    /// Contract: Signal number must be valid (< 32), handler can be
null (default action).
    pub fn register_handler(
        self: *SignalTable,
        signal: Signal,
        action: SignalAction,
    ) void {
        // Assert: Table must be initialized (precondition).
        Debug.kassert(self.initialized, "Table not initialized", .{});
        
        const signal_num = @intFromEnum(signal);
        
        // Assert: Signal number must be valid (precondition).
        Debug.kassert(signal_num < 32, "Signal number out of range",
.{});
        
        // SIGKILL cannot be caught or ignored.
        if (signal == .sigkill) {
            return;
        }
        
        self.actions[signal_num] = action;
        
        // Assert: Handler must be registered (postcondition).
        Debug.kassert(self.actions[signal_num].handler ==
action.handler, "Handler not set", .{});
    }

    /// Send signal to process.
    /// Why: Deliver signal to process (from kernel or other process).
    /// Contract: Signal number must be valid (< 32).
    pub fn send_signal(self: *SignalTable, signal: Signal) void {
        // Assert: Table must be initialized (precondition).
        Debug.kassert(self.initialized, "Table not initialized", .{});
        
        const signal_num = @intFromEnum(signal);
        
        // Assert: Signal number must be valid (precondition).
        Debug.kassert(signal_num < 32, "Signal number out of range",
.{});
        
        // SIGKILL always succeeds (cannot be blocked).
        if (signal == .sigkill) {
            self.pending |= (@as(u32, 1) << @as(u5,
@truncate(signal_num)));
            return;
        }
        
        // Check if signal is blocked.
        if (self.blocked & (@as(u32, 1) << @as(u5,
@truncate(signal_num))) != 0) {
            return;
        }
        
        // Mark signal as pending.
        self.pending |= (@as(u32, 1) << @as(u5, @truncate(signal_num)));
        
        // Assert: Signal must be pending (postcondition).
        Debug.kassert((self.pending & (@as(u32, 1) << @as(u5,
@truncate(signal_num)))) != 0, "Signal not pending", .{});
    }

    /// Block signal.
    /// Why: Prevent signal from being delivered.
    /// Contract: Signal number must be valid (< 32).
    pub fn block_signal(self: *SignalTable, signal: Signal) void {
        // Assert: Table must be initialized (precondition).
        Debug.kassert(self.initialized, "Table not initialized", .{});
        
        const signal_num = @intFromEnum(signal);
        
        // Assert: Signal number must be valid (precondition).
        Debug.kassert(signal_num < 32, "Signal number out of range",
.{});
        
        // SIGKILL cannot be blocked.
        if (signal == .sigkill) {
            return;
        }
        
        self.blocked |= (@as(u32, 1) << @as(u5, @truncate(signal_num)));
        
        // Assert: Signal must be blocked (postcondition).
        Debug.kassert((self.blocked & (@as(u32, 1) << @as(u5,
@truncate(signal_num)))) != 0, "Signal not blocked", .{});
    }

    /// Unblock signal.
    /// Why: Allow signal to be delivered.
    /// Contract: Signal number must be valid (< 32).
    pub fn unblock_signal(self: *SignalTable, signal: Signal) void {
        // Assert: Table must be initialized (precondition).
        Debug.kassert(self.initialized, "Table not initialized", .{});
        
        const signal_num = @intFromEnum(signal);
        
        // Assert: Signal number must be valid (precondition).
        Debug.kassert(signal_num < 32, "Signal number out of range",
.{});
        
        self.blocked &= ~(@as(u32, 1) << @as(u5, @truncate(signal_num)));
        
        // Assert: Signal must be unblocked (postcondition).
        Debug.kassert((self.blocked & (@as(u32, 1) << @as(u5,
@truncate(signal_num)))) == 0, "Signal still blocked", .{});
    }

    /// Check if signal is pending.
    /// Why: Query signal delivery status.
    /// Contract: Signal number must be valid (< 32).
    pub fn is_pending(self: *const SignalTable, signal: Signal) bool {
        // Assert: Table must be initialized (precondition).
        Debug.kassert(self.initialized, "Table not initialized", .{});
        
        const signal_num = @intFromEnum(signal);
        
        // Assert: Signal number must be valid (precondition).
        Debug.kassert(signal_num < 32, "Signal number out of range",
.{});
        
        return (self.pending & (@as(u32, 1) << @as(u5,
@truncate(signal_num)))) != 0;
    }

    /// Process pending signals.
    /// Why: Deliver pending signals to handlers.
    /// Contract: Must be called from process context, handlers must be
fast.
    pub fn process_pending(self: *SignalTable, context: ?*anyopaque)
void {
        // Assert: Table must be initialized (precondition).
        Debug.kassert(self.initialized, "Table not initialized", .{});
        
        var signal_num: u32 = 0;
        while (signal_num < 32) : (signal_num += 1) {
            const signal_mask = @as(u32, 1) << @as(u5,
@truncate(signal_num));
            
            // Check if signal is pending and not blocked.
            if ((self.pending & signal_mask) != 0 and (self.blocked &
signal_mask) == 0) {
                const signal = @as(Signal, @enumFromInt(signal_num));
                const action = self.actions[signal_num];
                
                // Clear pending flag.
                self.pending &= ~signal_mask;
                
                // Call handler if registered.
                if (action.handler) |handler| {
                    handler(signal, action.context orelse context);
                }
            }
        }
        
        // Assert: All unblocked signals processed (postcondition).
        // Note: Some signals may remain pending if blocked.
    }
};


// === kernel/storage.zig ===

//! Grain Basin Storage Filesystem
//! Why: In-memory filesystem for kernel file I/O operations.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Maximum file size (bytes).
/// Why: Bounded file size for safety and static allocation.
pub const MAX_FILE_SIZE: u32 = 64 * 1024; // 64KB

/// Maximum file name length (bytes, including null terminator).
/// Why: Bounded file name length for safety.
pub const MAX_FILENAME_LEN: u32 = 256;

/// Maximum directory entries.
/// Why: Bounded directory size for safety and static allocation.
pub const MAX_DIR_ENTRIES: u32 = 64;

/// File entry in filesystem.
/// Why: Store file data and metadata.
/// Grain Style: Static allocation, bounded size.
pub const FileEntry = struct {
    /// File name (null-terminated).
    name: [MAX_FILENAME_LEN]u8,
    /// Name length (bytes, excluding null terminator).
    name_len: u32,
    /// File data (bounded size).
    data: [MAX_FILE_SIZE]u8,
    /// Data length (bytes, <= MAX_FILE_SIZE).
    data_len: u32,
    /// Whether file is allocated (in use).
    allocated: bool,
    
    /// Initialize empty file entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() FileEntry {
        return FileEntry{
            .name = [_]u8{0} ** MAX_FILENAME_LEN,
            .name_len = 0,
            .data = [_]u8{0} ** MAX_FILE_SIZE,
            .data_len = 0,
            .allocated = false,
        };
    }
    
    /// Set file name.
    /// Why: Update file name with validation.
    /// Contract: name must be non-empty, <= MAX_FILENAME_LEN-1.
    pub fn set_name(self: *FileEntry, name: []const u8) bool {
        // Assert: Name length must be > 0.
        if (name.len == 0) {
            return false; // Empty name
        }
        
        // Assert: Name length must be <= MAX_FILENAME_LEN-1 (leave room
for null terminator).
        if (name.len >= MAX_FILENAME_LEN) {
            return false; // Name too long
        }
        
        // Copy name and null-terminate.
        @memcpy(self.name[0..name.len], name);
        self.name[name.len] = 0;
        self.name_len = @as(u32, @intCast(name.len));
        
        // Assert: Name must be set correctly.
        Debug.kassert(self.name_len == @as(u32, @intCast(name.len)),
"Name len mismatch", .{});
        Debug.kassert(self.name[name.len] == 0, "Name not
null-terminated", .{});
        
        return true;
    }
    
    /// Write data to file.
    /// Why: Update file contents.
    /// Contract: data must be <= MAX_FILE_SIZE.
    /// Returns: bytes written if successful, 0 if file full.
    pub fn write(self: *FileEntry, data: []const u8) u32 {
        // Assert: File must be allocated.
        Debug.kassert(self.allocated, "File not allocated", .{});
        
        // Assert: Data length must be <= MAX_FILE_SIZE.
        if (data.len > MAX_FILE_SIZE) {
            return 0; // Data too large
        }
        
        // Copy data to file.
        @memcpy(self.data[0..data.len], data);
        self.data_len = @as(u32, @intCast(data.len));
        
        // Assert: Data must be written correctly.
        Debug.kassert(self.data_len == @as(u32, @intCast(data.len)),
"Data len mismatch", .{});
        Debug.kassert(self.data_len <= MAX_FILE_SIZE, "Data len > MAX",
.{});
        
        return self.data_len;
    }
    
    /// Read data from file.
    /// Why: Get file contents.
    /// Contract: buffer must be >= MAX_FILE_SIZE.
    /// Returns: bytes read.
    pub fn read(self: *const FileEntry, buffer: []u8) u32 {
        // Assert: File must be allocated.
        Debug.kassert(self.allocated, "File not allocated", .{});
        
        // Assert: Buffer must be >= MAX_FILE_SIZE.
        Debug.kassert(buffer.len >= MAX_FILE_SIZE, "Buffer too small",
.{});
        
        // Copy file data to buffer.
        const bytes_to_copy = @min(self.data_len, @as(u32,
@intCast(buffer.len)));
        @memcpy(buffer[0..bytes_to_copy], self.data[0..bytes_to_copy]);
        
        // Assert: Bytes copied must be <= data_len.
        Debug.kassert(bytes_to_copy <= self.data_len, "Bytes copied >
data_len", .{});
        
        return bytes_to_copy;
    }
    
    /// Get file size.
    /// Why: Query file size without reading.
    /// Contract: File must be allocated.
    pub fn get_size(self: *const FileEntry) u32 {
        // Assert: File must be allocated.
        Debug.kassert(self.allocated, "File not allocated", .{});
        
        // Assert: Data length must be <= MAX_FILE_SIZE.
        Debug.kassert(self.data_len <= MAX_FILE_SIZE, "Data len > MAX",
.{});
        
        return self.data_len;
    }
};

/// Directory entry in filesystem.
/// Why: Store directory structure and file references.
/// Grain Style: Static allocation, bounded entries.
pub const DirectoryEntry = struct {
    /// Directory name (null-terminated).
    name: [MAX_FILENAME_LEN]u8,
    /// Name length (bytes, excluding null terminator).
    name_len: u32,
    /// File indices (references to FileEntry array).
    file_indices: [MAX_DIR_ENTRIES]u32,
    /// Number of files in directory.
    file_count: u32,
    /// Whether directory is allocated (in use).
    allocated: bool,
    
    /// Initialize empty directory entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() DirectoryEntry {
        return DirectoryEntry{
            .name = [_]u8{0} ** MAX_FILENAME_LEN,
            .name_len = 0,
            .file_indices = [_]u32{0} ** MAX_DIR_ENTRIES,
            .file_count = 0,
            .allocated = false,
        };
    }
    
    /// Set directory name.
    /// Why: Update directory name with validation.
    /// Contract: name must be non-empty, <= MAX_FILENAME_LEN-1.
    pub fn set_name(self: *DirectoryEntry, name: []const u8) bool {
        // Assert: Name length must be > 0.
        if (name.len == 0) {
            return false; // Empty name
        }
        
        // Assert: Name length must be <= MAX_FILENAME_LEN-1.
        if (name.len >= MAX_FILENAME_LEN) {
            return false; // Name too long
        }
        
        // Copy name and null-terminate.
        @memcpy(self.name[0..name.len], name);
        self.name[name.len] = 0;
        self.name_len = @as(u32, @intCast(name.len));
        
        // Assert: Name must be set correctly.
        Debug.kassert(self.name_len == @as(u32, @intCast(name.len)),
"Name len mismatch", .{});
        
        return true;
    }
    
    /// Add file to directory.
    /// Why: Track file in directory.
    /// Contract: file_index must be valid, directory must not be full.
    /// Returns: true if added, false if directory full.
    pub fn add_file(self: *DirectoryEntry, file_index: u32) bool {
        // Assert: Directory must be allocated.
        Debug.kassert(self.allocated, "Directory not allocated", .{});
        
        // Assert: File index must be valid (non-zero).
        Debug.kassert(file_index != 0, "File index is 0", .{});
        
        // Check if directory is full.
        if (self.file_count >= MAX_DIR_ENTRIES) {
            return false; // Directory full
        }
        
        // Add file index.
        self.file_indices[self.file_count] = file_index;
        self.file_count += 1;
        
        // Assert: File count must be <= MAX_DIR_ENTRIES.
        Debug.kassert(self.file_count <= MAX_DIR_ENTRIES, "File count >
MAX", .{});
        
        return true;
    }
    
    /// Get file count.
    /// Why: Query number of files in directory.
    /// Contract: Directory must be allocated.
    pub fn get_file_count(self: *const DirectoryEntry) u32 {
        // Assert: Directory must be allocated.
        Debug.kassert(self.allocated, "Directory not allocated", .{});
        
        // Assert: File count must be <= MAX_DIR_ENTRIES.
        Debug.kassert(self.file_count <= MAX_DIR_ENTRIES, "File count >
MAX", .{});
        
        return self.file_count;
    }
};

/// Storage filesystem for kernel.
/// Why: Manage files and directories for file I/O syscalls.
/// Grain Style: Static allocation, bounded tables.
pub const Storage = struct {
    /// File table (static allocation).
    files: [128]FileEntry,
    /// Number of allocated files.
    file_count: u32,
    /// Next file index (starts at 1, 0 is invalid).
    next_file_index: u32,
    
    /// Directory table (static allocation).
    directories: [32]DirectoryEntry,
    /// Number of allocated directories.
    directory_count: u32,
    /// Next directory index (starts at 1, 0 is invalid).
    next_directory_index: u32,
    
    /// Initialize storage filesystem.
    /// Why: Set up filesystem state.
    pub fn init() Storage {
        return Storage{
            .files = [_]FileEntry{FileEntry.init()} ** 128,
            .file_count = 0,
            .next_file_index = 1,
            .directories = [_]DirectoryEntry{DirectoryEntry.init()} **
32,
            .directory_count = 0,
            .next_directory_index = 1,
        };
    }
    
    /// Create file.
    /// Why: Allocate file entry for new file.
    /// Contract: name must be non-empty, <= MAX_FILENAME_LEN-1.
    /// Returns: File index if created, 0 if table full or invalid name.
    pub fn create_file(self: *Storage, name: []const u8) u32 {
        // Assert: Name must be non-empty.
        if (name.len == 0) {
            return 0; // Empty name
        }
        
        // Assert: File count must be < max files.
        Debug.kassert(self.file_count < 128, "File table full", .{});
        
        // Find free file slot.
        var slot: ?u32 = null;
        for (0..128) |i| {
            if (!self.files[i].allocated) {
                slot = @as(u32, @intCast(i));
                break;
            }
        }
        
        if (slot == null) {
            return 0; // No free slot
        }
        
        const idx = slot.?;
        
        // Set file name.
        const name_set = self.files[idx].set_name(name);
        if (!name_set) {
            return 0; // Invalid name
        }
        
        // Allocate file.
        self.files[idx].allocated = true;
        self.files[idx].data_len = 0;
        self.file_count += 1;
        
        // Assert: File must be allocated.
        Debug.kassert(self.files[idx].allocated, "File not allocated",
.{});
        Debug.kassert(self.files[idx].name_len > 0, "File name not set",
.{});
        
        // Return file index (1-based).
        const file_index = self.next_file_index;
        self.next_file_index += 1;
        
        return file_index;
    }
    
    /// Find file by name.
    /// Why: Look up file for read/write operations.
    /// Contract: name must be non-empty.
    /// Returns: File index if found, 0 if not found.
    pub fn find_file(self: *const Storage, name: []const u8) u32 {
        // Assert: Name must be non-empty.
        if (name.len == 0) {
            return 0; // Empty name
        }
        
        // Search for file by name.
        for (0..128) |i| {
            if (self.files[i].allocated) {
                // Compare names.
                if (self.files[i].name_len == @as(u32,
@intCast(name.len))) {
                    if (std.mem.eql(u8,
self.files[i].name[0..self.files[i].name_len], name)) {
                        // Assert: File must be allocated.
                        Debug.kassert(self.files[i].allocated, "File not
allocated", .{});
                        
                        // Return file index (1-based, using array index
+ 1).
                        return @as(u32, @intCast(i)) + 1;
                    }
                }
            }
        }
        
        return 0; // Not found
    }
    
    /// Get file by index.
    /// Why: Access file entry by index.
    /// Contract: file_index must be valid (1-based, 0 is invalid).
    /// Returns: File entry pointer if found, null otherwise.
    pub fn get_file(self: *Storage, file_index: u32) ?*FileEntry {
        // Assert: File index must be valid (non-zero, within bounds).
        if (file_index == 0) {
            return null; // Invalid index
        }
        
        const idx = file_index - 1; // Convert to 0-based
        if (idx >= 128) {
            return null; // Out of bounds
        }
        
        if (!self.files[idx].allocated) {
            return null; // Not allocated
        }
        
        // Assert: File must be allocated.
        Debug.kassert(self.files[idx].allocated, "File not allocated",
.{});
        
        return &self.files[idx];
    }
    
    /// Delete file.
    /// Why: Remove file from filesystem.
    /// Contract: file_index must be valid.
    /// Returns: true if deleted, false if not found.
    pub fn delete_file(self: *Storage, file_index: u32) bool {
        // Assert: File index must be valid (non-zero).
        if (file_index == 0) {
            return false; // Invalid index
        }
        
        const idx = file_index - 1; // Convert to 0-based
        if (idx >= 128) {
            return false; // Out of bounds
        }
        
        if (!self.files[idx].allocated) {
            return false; // Not allocated
        }
        
        // Clear file entry.
        self.files[idx].allocated = false;
        self.files[idx].name_len = 0;
        self.files[idx].data_len = 0;
        self.file_count -= 1;
        
        // Assert: File must be cleared.
        Debug.kassert(!self.files[idx].allocated, "File still
allocated", .{});
        Debug.kassert(self.files[idx].name_len == 0, "File name not
cleared", .{});
        
        return true;
    }
    
    /// Create directory.
    /// Why: Allocate directory entry for new directory.
    /// Contract: name must be non-empty, <= MAX_FILENAME_LEN-1.
    /// Returns: Directory index if created, 0 if table full or invalid
name.
    pub fn create_directory(self: *Storage, name: []const u8) u32 {
        // Assert: Name must be non-empty.
        if (name.len == 0) {
            return 0; // Empty name
        }
        
        // Assert: Directory count must be < max directories.
        Debug.kassert(self.directory_count < 32, "Directory table full",
.{});
        
        // Find free directory slot.
        var slot: ?u32 = null;
        for (0..32) |i| {
            if (!self.directories[i].allocated) {
                slot = @as(u32, @intCast(i));
                break;
            }
        }
        
        if (slot == null) {
            return 0; // No free slot
        }
        
        const idx = slot.?;
        
        // Set directory name.
        const name_set = self.directories[idx].set_name(name);
        if (!name_set) {
            return 0; // Invalid name
        }
        
        // Allocate directory.
        self.directories[idx].allocated = true;
        self.directories[idx].file_count = 0;
        self.directory_count += 1;
        
        // Assert: Directory must be allocated.
        Debug.kassert(self.directories[idx].allocated, "Directory not
allocated", .{});
        Debug.kassert(self.directories[idx].name_len > 0, "Directory
name not set", .{});
        
        // Return directory index (1-based).
        const dir_index = self.next_directory_index;
        self.next_directory_index += 1;
        
        return dir_index;
    }
    
    /// Get file count.
    /// Why: Query number of allocated files.
    pub fn get_file_count(self: *const Storage) u32 {
        // Assert: File count must be <= 128.
        Debug.kassert(self.file_count <= 128, "File count > 128", .{});
        
        return self.file_count;
    }
    
    /// Get directory count.
    /// Why: Query number of allocated directories.
    pub fn get_directory_count(self: *const Storage) u32 {
        // Assert: Directory count must be <= 32.
        Debug.kassert(self.directory_count <= 32, "Directory count >
32", .{});
        
        return self.directory_count;
    }
};

// Test storage initialization.
test "storage init" {
    const storage = Storage.init();
    
    // Assert: Storage must be initialized.
    try std.testing.expect(storage.file_count == 0);
    try std.testing.expect(storage.directory_count == 0);
    try std.testing.expect(storage.next_file_index == 1);
    try std.testing.expect(storage.next_directory_index == 1);
}

// Test file creation.
test "storage create file" {
    var storage = Storage.init();
    
    const file_index = storage.create_file("test.txt");
    
    // Assert: File must be created.
    try std.testing.expect(file_index != 0);
    try std.testing.expect(storage.file_count == 1);
    
    const file = storage.get_file(file_index);
    
    // Assert: File must be found.
    try std.testing.expect(file != null);
    try std.testing.expect(file.?.allocated);
}

// Test file write and read.
test "storage file write read" {
    var storage = Storage.init();
    
    const file_index = storage.create_file("test.txt");
    try std.testing.expect(file_index != 0);
    
    const file = storage.get_file(file_index);
    try std.testing.expect(file != null);
    
    const data = "Hello, World!";
    const written = file.?.write(data);
    
    // Assert: Data must be written.
    try std.testing.expect(written == data.len);
    try std.testing.expect(file.?.get_size() == data.len);
    
    var buffer: [MAX_FILE_SIZE]u8 = undefined;
    const read = file.?.read(&buffer);
    
    // Assert: Data must be read correctly.
    try std.testing.expect(read == data.len);
    try std.testing.expect(std.mem.eql(u8, buffer[0..read], data));
}

// Test file find.
test "storage find file" {
    var storage = Storage.init();
    
    const file_index = storage.create_file("test.txt");
    try std.testing.expect(file_index != 0);
    
    const found = storage.find_file("test.txt");
    
    // Assert: File must be found.
    try std.testing.expect(found == file_index);
    
    const not_found = storage.find_file("nonexistent.txt");
    
    // Assert: Non-existent file must not be found.
    try std.testing.expect(not_found == 0);
}

// Test file delete.
test "storage delete file" {
    var storage = Storage.init();
    
    const file_index = storage.create_file("test.txt");
    try std.testing.expect(file_index != 0);
    try std.testing.expect(storage.file_count == 1);
    
    const deleted = storage.delete_file(file_index);
    
    // Assert: File must be deleted.
    try std.testing.expect(deleted);
    try std.testing.expect(storage.file_count == 0);
    
    const file = storage.get_file(file_index);
    
    // Assert: File must not be found after deletion.
    try std.testing.expect(file == null);
}

// Test directory creation.
test "storage create directory" {
    var storage = Storage.init();
    
    const dir_index = storage.create_directory("test_dir");
    
    // Assert: Directory must be created.
    try std.testing.expect(dir_index != 0);
    try std.testing.expect(storage.directory_count == 1);
}


// === kernel/syscall_table.zig ===

const std = @import("std");

pub const Syscall = struct {
    number: u16,
    name: []const u8,
    description: []const u8,
};

pub const table = [_]Syscall{
    .{ .number = 0, .name = "debug_write", .description = "Writes bytes
to the kernel debug console." },
    .{ .number = 1, .name = "exit", .description = "Terminates the
calling task with a status code." },
};

pub fn describe(number: u16) ?Syscall {
    for (table) |entry| {
        if (entry.number == number) return entry;
    }
    return null;
}

// === kernel/tcp_socket.zig ===

//! TCP Socket Management
//! Why: Manage TCP sockets for network communication.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Maximum number of TCP sockets.
/// Why: Bounded allocation for socket tracking.
const MAX_TCP_SOCKETS: u32 = 64;

/// Maximum socket buffer size (64KB).
/// Why: Bounded buffer allocation for socket data.
const MAX_SOCKET_BUFFER_SIZE: u32 = 64 * 1024;

/// TCP socket state.
/// Why: Track socket state for connection management.
pub const TcpSocketState = enum(u8) {
    closed = 0,
    listening = 1,
    connecting = 2,
    connected = 3,
    closing = 4,
};

/// TCP socket entry.
/// Why: Track TCP socket configuration and state.
/// Grain Style: Static allocation, explicit types.
pub const TcpSocket = struct {
    /// Socket ID (non-zero if allocated).
    socket_id: u64,
    
    /// Socket state.
    state: TcpSocketState,
    
    /// Local IPv4 address (network byte order).
    local_addr: u32,
    
    /// Local port (host byte order).
    local_port: u16,
    
    /// Remote IPv4 address (network byte order, 0 if not connected).
    remote_addr: u32,
    
    /// Remote port (host byte order, 0 if not connected).
    remote_port: u16,
    
    /// Receive buffer (incoming data).
    recv_buffer: [MAX_SOCKET_BUFFER_SIZE]u8,
    
    /// Receive buffer size (actual data length, bytes).
    recv_buffer_size: u32,
    
    /// Send buffer (outgoing data).
    send_buffer: [MAX_SOCKET_BUFFER_SIZE]u8,
    
    /// Send buffer size (actual data length, bytes).
    send_buffer_size: u32,
    
    /// Whether this entry is allocated (in use).
    allocated: bool,
    
    /// Owner process ID (0 = kernel-owned, non-zero = process-owned).
    /// Why: Track which process owns this socket for resource cleanup.
    owner_process_id: u32,
    
    /// Initialize empty TCP socket entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() TcpSocket {
        return TcpSocket{
            .socket_id = 0,
            .state = .closed,
            .local_addr = 0,
            .local_port = 0,
            .remote_addr = 0,
            .remote_port = 0,
            .recv_buffer = [_]u8{0} ** MAX_SOCKET_BUFFER_SIZE,
            .recv_buffer_size = 0,
            .send_buffer = [_]u8{0} ** MAX_SOCKET_BUFFER_SIZE,
            .send_buffer_size = 0,
            .allocated = false,
            .owner_process_id = 0,
        };
    }
    
    /// Check if socket is in a valid state for operations.
    /// Why: Validate socket state before operations.
    /// Contract: Socket must be allocated.
    pub fn is_valid(self: *const TcpSocket) bool {
        // Assert: Socket must be allocated.
        Debug.kassert(self.allocated, "Socket not allocated", .{});
        
        return self.state != .closed;
    }
};

/// TCP socket manager.
/// Why: Manage all TCP sockets.
/// Grain Style: Static allocation, bounded operations.
pub const TcpSocketManager = struct {
    /// Socket entries.
    sockets: [MAX_TCP_SOCKETS]TcpSocket,
    
    /// Next socket ID (simple allocator, starts at 1).
    /// Why: Track socket ID allocation (1-based, 0 is invalid).
    next_socket_id: u64,
    
    /// Whether manager is initialized.
    initialized: bool,
    
    /// Initialize TCP socket manager.
    /// Why: Set up manager state.
    pub fn init() TcpSocketManager {
        const manager = TcpSocketManager{
            .sockets = [_]TcpSocket{TcpSocket.init()} ** MAX_TCP_SOCKETS,
            .next_socket_id = 1,
            .initialized = true,
        };
        
        return manager;
    }
    
    /// Create a new TCP socket.
    /// Why: Allocate a new TCP socket.
    /// Contract: Returns socket ID, or null if no free slot.
    pub fn create_socket(
        self: *TcpSocketManager,
        owner_process_id: u32,
    ) ?u64 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Find free slot.
        var idx: u32 = 0;
        while (idx < MAX_TCP_SOCKETS) : (idx += 1) {
            if (!self.sockets[idx].allocated) {
                // Initialize socket.
                self.sockets[idx] = TcpSocket.init();
                self.sockets[idx].allocated = true;
                self.sockets[idx].socket_id = self.next_socket_id;
                self.sockets[idx].owner_process_id = owner_process_id;
                
                // Increment socket ID.
                const socket_id = self.next_socket_id;
                self.next_socket_id += 1;
                if (self.next_socket_id == 0) {
                    self.next_socket_id = 1; // Wrap around (skip 0)
                }
                
                return socket_id;
            }
        }
        
        // No free slot found.
        return null;
    }
    
    /// Get socket by ID.
    /// Why: Retrieve socket entry.
    /// Contract: socket_id must be valid (non-zero).
    /// Returns: Pointer to socket entry, or null if not found.
    pub fn get_socket(
        self: *TcpSocketManager,
        socket_id: u64,
    ) ?*TcpSocket {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Socket ID must be non-zero.
        if (socket_id == 0) {
            return null;
        }
        
        // Search for socket with matching ID.
        var idx: u32 = 0;
        while (idx < MAX_TCP_SOCKETS) : (idx += 1) {
            if (self.sockets[idx].allocated and
self.sockets[idx].socket_id == socket_id) {
                return &self.sockets[idx];
            }
        }
        
        // Socket not found.
        return null;
    }
    
    /// Bind socket to local address and port.
    /// Why: Configure local endpoint for socket.
    /// Contract: socket_id must be valid, addr and port must be valid.
    pub fn bind_socket(
        self: *TcpSocketManager,
        socket_id: u64,
        addr: u32,
        port: u16,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const socket = self.get_socket(socket_id) orelse {
            return false;
        };
        
        // Assert: Socket must be in closed state.
        if (socket.state != .closed) {
            return false;
        }
        
        // Set local address and port.
        socket.local_addr = addr;
        socket.local_port = port;
        
        return true;
    }
    
    /// Set socket to listening state.
    /// Why: Enable socket to accept incoming connections.
    /// Contract: socket_id must be valid, socket must be bound.
    pub fn listen_socket(
        self: *TcpSocketManager,
        socket_id: u64,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const socket = self.get_socket(socket_id) orelse {
            return false;
        };
        
        // Assert: Socket must be bound (local_addr and local_port set).
        if (socket.local_addr == 0 or socket.local_port == 0) {
            return false;
        }
        
        // Assert: Socket must be in closed state.
        if (socket.state != .closed) {
            return false;
        }
        
        // Set socket to listening state.
        socket.state = .listening;
        
        return true;
    }
    
    /// Accept incoming connection (stub: returns new socket ID).
    /// Why: Accept incoming connection on listening socket.
    /// Contract: socket_id must be valid, socket must be listening.
    /// Returns: New socket ID for accepted connection, or null if no
connection.
    pub fn accept_connection(
        self: *TcpSocketManager,
        socket_id: u64,
        owner_process_id: u32,
    ) ?u64 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const socket = self.get_socket(socket_id) orelse {
            return null;
        };
        
        // Assert: Socket must be in listening state.
        if (socket.state != .listening) {
            return null;
        }
        
        // Create new socket for accepted connection (stub: would create
from incoming connection).
        const new_socket_id = self.create_socket(owner_process_id)
orelse {
            return null;
        };
        
        const new_socket = self.get_socket(new_socket_id).?;
        new_socket.state = .connected;
        new_socket.local_addr = socket.local_addr;
        new_socket.local_port = socket.local_port;
        // Stub: remote_addr and remote_port would be set from incoming
connection.
        new_socket.remote_addr = 0;
        new_socket.remote_port = 0;
        
        return new_socket_id;
    }
    
    /// Connect socket to remote address and port.
    /// Why: Establish connection to remote endpoint.
    /// Contract: socket_id must be valid, addr and port must be valid.
    pub fn connect_socket(
        self: *TcpSocketManager,
        socket_id: u64,
        addr: u32,
        port: u16,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const socket = self.get_socket(socket_id) orelse {
            return false;
        };
        
        // Assert: Socket must be in closed state.
        if (socket.state != .closed) {
            return false;
        }
        
        // Set remote address and port.
        socket.remote_addr = addr;
        socket.remote_port = port;
        
        // Set socket to connected state (stub: would establish
connection).
        socket.state = .connected;
        
        return true;
    }
    
    /// Send data on socket.
    /// Why: Transmit data on connected socket.
    /// Contract: socket_id must be valid, data must be valid, socket
must be connected.
    /// Returns: Number of bytes sent, or null on error.
    pub fn send_data(
        self: *TcpSocketManager,
        socket_id: u64,
        data: []const u8,
    ) ?u32 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const socket = self.get_socket(socket_id) orelse {
            return null;
        };
        
        // Assert: Socket must be in connected state.
        if (socket.state != .connected) {
            return null;
        }
        
        // Assert: Data must fit in send buffer.
        if (socket.send_buffer_size + data.len > MAX_SOCKET_BUFFER_SIZE)
{
            return null; // Buffer full
        }
        
        // Copy data to send buffer (stub: would transmit over network).
        std.mem.copyForwards(u8,
socket.send_buffer[socket.send_buffer_size..], data);
        socket.send_buffer_size += @as(u32, @truncate(data.len));
        
        return @as(u32, @truncate(data.len));
    }
    
    /// Receive data from socket.
    /// Why: Read incoming data from connected socket.
    /// Contract: socket_id must be valid, buffer must be valid, socket
must be connected.
    /// Returns: Number of bytes received, or null on error.
    pub fn recv_data(
        self: *TcpSocketManager,
        socket_id: u64,
        buffer: []u8,
    ) ?u32 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const socket = self.get_socket(socket_id) orelse {
            return null;
        };
        
        // Assert: Socket must be in connected state.
        if (socket.state != .connected) {
            return null;
        }
        
        // Assert: Buffer must be non-empty.
        if (buffer.len == 0) {
            return null;
        }
        
        // Copy data from receive buffer (stub: would read from network).
        const bytes_to_copy = @min(socket.recv_buffer_size, @as(u32,
@truncate(buffer.len)));
        if (bytes_to_copy > 0) {
            std.mem.copyForwards(u8, buffer,
socket.recv_buffer[0..bytes_to_copy]);
            // Remove copied data from buffer (shift remaining data).
            std.mem.copyForwards(u8, socket.recv_buffer[0..],
socket.recv_buffer[bytes_to_copy..socket.recv_buffer_size]);
            socket.recv_buffer_size -= bytes_to_copy;
        }
        
        return bytes_to_copy;
    }
    
    /// Close socket.
    /// Why: Release socket resources.
    /// Contract: socket_id must be valid.
    pub fn close_socket(
        self: *TcpSocketManager,
        socket_id: u64,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const socket = self.get_socket(socket_id) orelse {
            return false;
        };
        
        // Set socket to closed state and deallocate.
        socket.state = .closed;
        socket.allocated = false;
        
        return true;
    }
};


// === kernel/timer.zig ===

//! Grain Basin Timer Driver
//! Why: Provide monotonic clock and time-based syscalls for kernel.
//! Grain Style: Explicit types (u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Timer driver for Grain Basin kernel.
/// Why: Track boot time, provide monotonic clock, enable time-based
syscalls.
/// Grain Style: Static allocation, explicit state tracking.
pub const Timer = struct {
    /// Boot time (nanoseconds since epoch, or 0 if not initialized).
    /// Why: Track when kernel booted for uptime calculation.
    boot_time_ns: u64,
    
    /// Last timer value (nanoseconds since boot, or 0 if not set).
    /// Why: Track last SBI timer value for monotonic clock.
    last_timer_ns: u64,
    
    /// Whether timer is initialized.
    /// Why: Track initialization state for safety.
    initialized: bool,
    
    /// Initialize timer driver.
    /// Why: Set boot time and initialize timer state.
    /// Contract: Must be called once at kernel boot.
    pub fn init() Timer {
        // Get current time (nanoseconds since epoch).
        // Note: In VM, we use host system time. On real hardware, use
SBI timer.
        const now_ns = get_host_time_ns();
        
        return Timer{
            .boot_time_ns = now_ns,
            .last_timer_ns = 0,
            .initialized = true,
        };
    }
    
    /// Get monotonic clock time (nanoseconds since boot).
    /// Why: Provide monotonic clock for clock_gettime syscall.
    /// Contract: Timer must be initialized.
    pub fn get_monotonic_ns(self: *const Timer) u64 {
        // Assert: Timer must be initialized.
        Debug.kassert(self.initialized, "Timer not initialized", .{});
        
        // Get current time (nanoseconds since epoch).
        const now_ns = get_host_time_ns();
        
        // Calculate monotonic time (nanoseconds since boot).
        const monotonic_ns = if (now_ns >= self.boot_time_ns)
            now_ns - self.boot_time_ns
        else
            0; // Handle clock rollback (shouldn't happen, but safe)
        
        // Assert: Monotonic time must be non-negative.
        Debug.kassert(monotonic_ns >= 0, "Monotonic time negative", .{});
        
        return monotonic_ns;
    }
    
    /// Get realtime clock time (nanoseconds since epoch).
    /// Why: Provide realtime clock for clock_gettime syscall.
    /// Contract: Timer must be initialized.
    pub fn get_realtime_ns(self: *const Timer) u64 {
        // Assert: Timer must be initialized.
        Debug.kassert(self.initialized, "Timer not initialized", .{});
        
        // Get current time (nanoseconds since epoch).
        const now_ns = get_host_time_ns();
        
        // Assert: Realtime must be >= boot time.
        Debug.kassert(now_ns >= self.boot_time_ns, "Realtime < boot
time", .{});
        
        return now_ns;
    }
    
    /// Get uptime (nanoseconds since boot).
    /// Why: Provide uptime for sysinfo syscall.
    /// Contract: Timer must be initialized.
    pub fn get_uptime_ns(self: *const Timer) u64 {
        // Assert: Timer must be initialized.
        Debug.kassert(self.initialized, "Timer not initialized", .{});
        
        return self.get_monotonic_ns();
    }
    
    /// Set SBI timer (for timer interrupts).
    /// Why: Set timer interrupt for sleep_until and scheduling.
    /// Contract: Timer must be initialized, time_value must be valid.
    /// Note: In VM, this is handled by VM's handle_sbi_call. On real
hardware, use SBI.
    pub fn set_timer(self: *Timer, time_value: u64) void {
        // Assert: Timer must be initialized.
        Debug.kassert(self.initialized, "Timer not initialized", .{});
        
        // Assert: Time value must be reasonable (not too far in future).
        // Max 1 year in future (nanoseconds).
        const MAX_FUTURE_NS: u64 = 365 * 24 * 60 * 60 * 1000000000;
        Debug.kassert(time_value <= MAX_FUTURE_NS, "Time value too
large", .{});
        
        // Update last timer value.
        self.last_timer_ns = time_value;
        
        // Assert: Last timer value must be set.
        Debug.kassert(self.last_timer_ns == time_value, "Timer value not
set", .{});
    }
    
    /// Get host system time (nanoseconds since epoch).
    /// Why: Get current time from host system (VM) or hardware (real).
    /// Note: In VM, uses std.time. On real hardware, would use SBI
timer.
    fn get_host_time_ns() u64 {
        // Get current time (nanoseconds since epoch).
        // Note: std.time.timestamp() returns seconds, we need
nanoseconds.
        const now_sec = std.time.timestamp();
        const now_ns = @as(u64, @intCast(now_sec)) * 1000000000;
        
        // Assert: Time must be reasonable (not before year 2000).
        const YEAR_2000_NS: u64 = 946684800 * 1000000000; // Jan 1, 2000
        Debug.kassert(now_ns >= YEAR_2000_NS, "Time before year 2000",
.{});
        
        return now_ns;
    }
};

// Test timer initialization.
test "timer init" {
    const timer = Timer.init();
    
    // Assert: Timer must be initialized.
    try std.testing.expect(timer.initialized);
    try std.testing.expect(timer.boot_time_ns > 0);
}

// Test monotonic clock.
test "timer monotonic" {
    var timer = Timer.init();
    
    const t1 = timer.get_monotonic_ns();
    const t2 = timer.get_monotonic_ns();
    
    // Assert: Monotonic time must be non-decreasing.
    try std.testing.expect(t2 >= t1);
    try std.testing.expect(t1 >= 0);
    try std.testing.expect(t2 >= 0);
}

// Test realtime clock.
test "timer realtime" {
    var timer = Timer.init();
    
    const rt = timer.get_realtime_ns();
    
    // Assert: Realtime must be >= boot time.
    try std.testing.expect(rt >= timer.boot_time_ns);
}

// Test uptime.
test "timer uptime" {
    var timer = Timer.init();
    
    const uptime1 = timer.get_uptime_ns();
    const uptime2 = timer.get_uptime_ns();
    
    // Assert: Uptime must be non-decreasing.
    try std.testing.expect(uptime2 >= uptime1);
    try std.testing.expect(uptime1 >= 0);
    try std.testing.expect(uptime2 >= 0);
}

// Test set timer.
test "timer set timer" {
    var timer = Timer.init();
    
    const time_value: u64 = 1000000000; // 1 second
    
    timer.set_timer(time_value);
    
    // Assert: Last timer value must be set.
    try std.testing.expect(timer.last_timer_ns == time_value);
}


// === kernel/trap.zig ===

//! Trap Handler Loop
//! Why: Main kernel loop for handling interrupts and syscalls.
//! Grain Style: Explicit state tracking, bounded execution.

const Panic = @import("panic.zig");
const InterruptController = @import("interrupt.zig").InterruptController;
const BasinKernel = @import("basin_kernel.zig").BasinKernel;
const Debug = @import("debug.zig");
const page_fault_stats = @import("page_fault_stats.zig");

/// Exception type (RISC-V exception codes).
/// Why: Explicit exception types for type safety.
pub const ExceptionType = enum(u32) {
    /// Instruction address misaligned.
    instruction_address_misaligned = 0,
    /// Instruction access fault.
    instruction_access_fault = 1,
    /// Illegal instruction.
    illegal_instruction = 2,
    /// Breakpoint.
    breakpoint = 3,
    /// Load address misaligned.
    load_address_misaligned = 4,
    /// Load access fault.
    load_access_fault = 5,
    /// Store/AMO address misaligned.
    store_address_misaligned = 6,
    /// Store/AMO access fault.
    store_access_fault = 7,
    /// Environment call from U-mode.
    environment_call_from_u_mode = 8,
    /// Environment call from S-mode.
    environment_call_from_s_mode = 9,
    /// Instruction page fault.
    instruction_page_fault = 12,
    /// Load page fault.
    load_page_fault = 13,
    /// Store/AMO page fault.
    store_page_fault = 15,
};

/// Trap loop (main kernel loop).
/// Why: Process interrupts and handle syscalls in main loop.
/// Contract: Must be called from kernel main, runs indefinitely.
/// Note: In VM, syscalls are handled by VM's syscall handler.
///       This loop processes pending interrupts and exceptions.
/// GrainStyle: Bounded loops, explicit state tracking, no recursion.
pub fn loop_with_kernel(kernel: *BasinKernel) noreturn {
    // Assert: Kernel pointer must be valid (precondition).
    const kernel_ptr = @intFromPtr(kernel);
    Debug.kassert(kernel_ptr != 0, "Kernel ptr is null", .{});
    Debug.kassert(kernel_ptr % @alignOf(BasinKernel) == 0, "Kernel ptr
unaligned", .{});
    
    Panic.write("grain kernel: entering trap loop\n");
    
    // Main trap loop (bounded iterations per cycle).
    // Why: Process interrupts and exceptions in main loop.
    // GrainStyle: Bounded execution, no infinite loops without bounds.
    var iteration_count: u32 = 0;
    const MAX_ITERATIONS_PER_CYCLE: u32 = 1000; // Prevent infinite
loops.
    
    while (true) {
        // Assert: Iteration count must be bounded (invariant).
        Debug.kassert(iteration_count < MAX_ITERATIONS_PER_CYCLE,
"Iteration count overflow", .{});
        
        // Process pending interrupts.
        // Why: Handle deferred interrupts (timer, external, software).
        kernel.interrupt_controller.process_pending();
        
        // Assert: Interrupt controller must be initialized
(postcondition).
        Debug.kassert(kernel.interrupt_controller.initialized,
"Interrupt controller not initialized", .{});
        
        // Yield CPU if no work (cooperative scheduling).
        // Why: Allow other processes to run if current process yields.
        // Note: In VM, scheduling is handled by VM's step loop.
        // This is a placeholder for future cooperative scheduling.
        
        // Reset iteration count periodically (prevent overflow).
        iteration_count += 1;
        if (iteration_count >= MAX_ITERATIONS_PER_CYCLE) {
            iteration_count = 0;
        }
    }
}

/// Legacy trap loop (backward compatibility).
/// Why: Maintain compatibility with existing code that calls loop().
/// Contract: Must be called from kernel main, runs indefinitely.
/// Note: This version doesn't process interrupts (requires kernel
reference).
///       Use loop_with_kernel() for full functionality.
pub fn loop() noreturn {
    Panic.write("grain kernel: entering trap loop (legacy mode)\n");
    
    // Legacy loop (no interrupt processing).
    // Why: Backward compatibility with code that doesn't pass kernel
reference.
    // Note: In VM environment, interrupts are processed via VM's
interrupt handling.
    while (true) {
        // Empty loop (interrupts handled by VM).
    }
}

/// Handle exception (called from VM on exception).
/// Why: Process exceptions (illegal instruction, misaligned access,
etc.).
/// Contract: Exception type must be valid, kernel must be initialized.
/// GrainStyle: Explicit error handling, bounded execution.
/// Note: Exception statistics are tracked by VM, not kernel.
pub fn handle_exception(
    kernel: *BasinKernel,
    exception_type: ExceptionType,
    exception_pc: u64,
    exception_value: u64,
) void {
    // Assert: Kernel pointer must be valid (precondition).
    const kernel_ptr = @intFromPtr(kernel);
    Debug.kassert(kernel_ptr != 0, "Kernel ptr is null", .{});
    Debug.kassert(kernel_ptr % @alignOf(BasinKernel) == 0, "Kernel ptr
unaligned", .{});
    
    // Assert: Exception type must be valid (precondition).
    const exception_id = @intFromEnum(exception_type);
    Debug.kassert(exception_id < 16, "Invalid exception type", .{});
    
    // Log exception (for debugging).
    // Why: Track exceptions for debugging and error recovery.
    Debug.kprint("kernel: exception {d} at PC=0x{x}, value=0x{x}\n", .{
        exception_id,
        exception_pc,
        exception_value,
    });
    
    // Determine if exception is fatal (should terminate process).
    // Why: Some exceptions are fatal and should terminate the process.
    const is_fatal = is_fatal_exception(exception_type);
    
    // Handle exception based on type.
    // Why: Different exceptions require different handling.
    switch (exception_type) {
        .illegal_instruction => {
            // Illegal instruction: fatal exception, terminate process.
            // Why: Invalid instructions indicate program errors.
            Debug.kprint("kernel: illegal instruction at PC=0x{x}
(fatal)\n", .{exception_pc});
        },
        .load_address_misaligned, .store_address_misaligned => {
            // Misaligned access: fatal exception, terminate process.
            // Why: Misaligned accesses indicate program errors.
            Debug.kprint("kernel: misaligned access at PC=0x{x},
address=0x{x} (fatal)\n", .{
                exception_pc,
                exception_value,
            });
        },
        .load_access_fault, .store_access_fault => {
            // Access fault: fatal exception, terminate process.
            // Why: Access faults indicate memory protection violations.
            Debug.kprint("kernel: access fault at PC=0x{x},
address=0x{x} (fatal)\n", .{
                exception_pc,
                exception_value,
            });
        },
        .instruction_access_fault => {
            // Instruction access fault: fatal exception, terminate
process.
            // Why: Instruction fetch faults indicate program errors.
            Debug.kprint("kernel: instruction access fault at PC=0x{x}
(fatal)\n", .{exception_pc});
        },
        .instruction_page_fault => {
            // Instruction page fault: record statistics, then terminate
process.
            // Why: Instruction page faults indicate memory protection
violations.
            Debug.kprint("kernel: instruction page fault at PC=0x{x},
address=0x{x} (fatal)\n", .{
                exception_pc,
                exception_value,
            });
            // Record page fault statistics.
            kernel.page_fault_stats.record_page_fault(
                page_fault_stats.PageFaultType.instruction,
                exception_value,
            );
        },
        .load_page_fault, .store_page_fault => {
            // Page fault: record statistics, then terminate process.
            // Why: Page faults indicate memory protection violations.
            Debug.kprint("kernel: page fault at PC=0x{x}, address=0x{x}
(fatal)\n", .{
                exception_pc,
                exception_value,
            });
            
            // Record page fault statistics.
            const fault_type = if (exception_type == .load_page_fault) 
                page_fault_stats.PageFaultType.load 
            else 
                page_fault_stats.PageFaultType.store;
            kernel.page_fault_stats.record_page_fault(fault_type,
exception_value);
        },
        .breakpoint => {
            // Breakpoint: non-fatal, continue execution.
            // Why: Breakpoints are for debugging, not errors.
            Debug.kprint("kernel: breakpoint at PC=0x{x}\n",
.{exception_pc});
        },
        .environment_call_from_u_mode, .environment_call_from_s_mode => {
            // Environment call (syscall): handled by VM's syscall
handler.
            // Why: Syscalls are handled by VM, not trap loop.
            // Note: This should not be called from trap loop.
            Debug.kprint("kernel: environment call at PC=0x{x} (handled
by VM)\n", .{exception_pc});
        },
        else => {
            // Other exceptions: log and continue (non-fatal by default).
            // Why: Handle unknown exceptions gracefully.
            Debug.kprint("kernel: unknown exception {d} at PC=0x{x}\n",
.{
                exception_id,
                exception_pc,
            });
        },
    }
    
    // Terminate process on fatal exceptions.
    // Why: Fatal exceptions indicate unrecoverable errors.
    if (is_fatal) {
        terminate_process_on_exception(kernel, exception_type,
exception_pc);
    }
    
    // Assert: Exception must be handled (postcondition).
    Debug.kassert(true, "Exception handled", .{});
}

/// Check if exception is fatal (should terminate process).
/// Why: Determine which exceptions should terminate the process.
/// Contract: Exception type must be valid.
/// Returns: true if exception is fatal, false otherwise.
fn is_fatal_exception(exception_type: ExceptionType) bool {
    return switch (exception_type) {
        .illegal_instruction,
        .load_address_misaligned,
        .store_address_misaligned,
        .load_access_fault,
        .store_access_fault,
        .instruction_access_fault,
        .instruction_page_fault,
        .load_page_fault,
        .store_page_fault,
        => true,
        .breakpoint,
        .environment_call_from_u_mode,
        .environment_call_from_s_mode,
        .instruction_address_misaligned,
        => false,
    };
}

/// Terminate current process on fatal exception.
/// Why: Cleanly terminate process when fatal exception occurs.
/// Contract: Kernel must be initialized, current process must exist.
/// GrainStyle: Explicit error handling, bounded execution.
fn terminate_process_on_exception(
    kernel: *BasinKernel,
    exception_type: ExceptionType,
    exception_pc: u64,
) void {
    // Assert: Kernel pointer must be valid (precondition).
    const kernel_ptr = @intFromPtr(kernel);
    Debug.kassert(kernel_ptr != 0, "Kernel ptr is null", .{});
    Debug.kassert(kernel_ptr % @alignOf(BasinKernel) == 0, "Kernel ptr
unaligned", .{});
    
    // Get current process ID from scheduler.
    const current_process_id = kernel.scheduler.get_current();
    
    // If no current process, nothing to terminate.
    if (current_process_id == 0) {
        Debug.kprint("kernel: no current process to terminate\n", .{});
        return;
    }
    
    // Find process in process table.
    // Why: Locate process to terminate.
    var found: ?u32 = null;
    const max_processes: u32 = 64; // MAX_PROCESSES constant (from
BasinKernel).
    var i: u32 = 0;
    while (i < max_processes) : (i += 1) {
        if (kernel.processes[i].allocated and kernel.processes[i].id ==
current_process_id) {
            found = i;
            break;
        }
    }
    
    if (found) |idx| {
        const process = &kernel.processes[idx];
        
        // Calculate exit status from exception type.
        // Why: Exit status = 128 + exception code (Unix convention).
        const exception_code = @intFromEnum(exception_type);
        const exit_status: u32 = 128 + @as(u32,
@truncate(exception_code));
        
        // Mark process as exited.
        process.state = .exited;
        process.exit_status = exit_status;
        
        // Clear from scheduler.
        if (kernel.scheduler.is_current(current_process_id)) {
            kernel.scheduler.clear_current();
        }
        
        // Clean up process resources (memory mappings, handles,
channels).
        // Why: Free resources when process terminates due to exception.
        const process_id_u32 = @as(u32, @truncate(current_process_id));
        const resource_cleanup = @import("resource_cleanup.zig");
        const resources_cleaned =
resource_cleanup.cleanup_process_resources(
            kernel,
            process_id_u32,
        );
        
        // Log process termination.
        Debug.kprint("kernel: process {d} terminated due to exception
{d} at PC=0x{x}, exit status={d}, resources cleaned={d}\n", .{
            current_process_id,
            exception_code,
            exception_pc,
            exit_status,
            resources_cleaned,
        });
        
        // Assert: Process must be marked as exited (postcondition).
        Debug.kassert(process.state == .exited, "Process not exited",
.{});
        Debug.kassert(process.exit_status == exit_status, "Exit status
mismatch", .{});
        
        // Assert: Resources cleaned must be reasonable (postcondition).
        const MAX_RESOURCES: u32 = 1000;
        Debug.kassert(resources_cleaned <= MAX_RESOURCES * 3, "Resources
cleaned too large", .{});
    } else {
        // Process not found (should not happen).
        Debug.kprint("kernel: process {d} not found for termination\n",
.{current_process_id});
    }
}

// === kernel/udp_socket.zig ===

//! UDP Socket Management
//! Why: Manage UDP sockets for network communication.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");
const Debug = @import("debug.zig");

/// Maximum number of UDP sockets.
/// Why: Bounded allocation for socket tracking.
const MAX_UDP_SOCKETS: u32 = 64;

/// Maximum socket buffer size (64KB).
/// Why: Bounded buffer allocation for socket data.
const MAX_SOCKET_BUFFER_SIZE: u32 = 64 * 1024;

/// UDP socket state.
/// Why: Track socket state for connection management.
pub const UdpSocketState = enum(u8) {
    closed = 0,
    bound = 1,
};

/// UDP socket entry.
/// Why: Track UDP socket configuration and state.
/// Grain Style: Static allocation, explicit types.
pub const UdpSocket = struct {
    /// Socket ID (non-zero if allocated).
    socket_id: u64,
    
    /// Socket state.
    state: UdpSocketState,
    
    /// Local IPv4 address (network byte order).
    local_addr: u32,
    
    /// Local port (host byte order).
    local_port: u16,
    
    /// Receive buffer (incoming data).
    recv_buffer: [MAX_SOCKET_BUFFER_SIZE]u8,
    
    /// Receive buffer size (actual data length, bytes).
    recv_buffer_size: u32,
    
    /// Send buffer (outgoing data).
    send_buffer: [MAX_SOCKET_BUFFER_SIZE]u8,
    
    /// Send buffer size (actual data length, bytes).
    send_buffer_size: u32,
    
    /// Whether this entry is allocated (in use).
    allocated: bool,
    
    /// Owner process ID (0 = kernel-owned, non-zero = process-owned).
    /// Why: Track which process owns this socket for resource cleanup.
    owner_process_id: u32,
    
    /// Initialize empty UDP socket entry.
    /// Why: Explicit initialization, clear state.
    pub fn init() UdpSocket {
        return UdpSocket{
            .socket_id = 0,
            .state = .closed,
            .local_addr = 0,
            .local_port = 0,
            .recv_buffer = [_]u8{0} ** MAX_SOCKET_BUFFER_SIZE,
            .recv_buffer_size = 0,
            .send_buffer = [_]u8{0} ** MAX_SOCKET_BUFFER_SIZE,
            .send_buffer_size = 0,
            .allocated = false,
            .owner_process_id = 0,
        };
    }
    
    /// Check if socket is in a valid state for operations.
    /// Why: Validate socket state before operations.
    /// Contract: Socket must be allocated.
    pub fn is_valid(self: *const UdpSocket) bool {
        // Assert: Socket must be allocated.
        Debug.kassert(self.allocated, "Socket not allocated", .{});
        
        return self.state != .closed;
    }
};

/// UDP socket manager.
/// Why: Manage all UDP sockets.
/// Grain Style: Static allocation, bounded operations.
pub const UdpSocketManager = struct {
    /// Socket entries.
    sockets: [MAX_UDP_SOCKETS]UdpSocket,
    
    /// Next socket ID (simple allocator, starts at 1).
    /// Why: Track socket ID allocation (1-based, 0 is invalid).
    next_socket_id: u64,
    
    /// Whether manager is initialized.
    initialized: bool,
    
    /// Initialize UDP socket manager.
    /// Why: Set up manager state.
    pub fn init() UdpSocketManager {
        const manager = UdpSocketManager{
            .sockets = [_]UdpSocket{UdpSocket.init()} ** MAX_UDP_SOCKETS,
            .next_socket_id = 1,
            .initialized = true,
        };
        
        return manager;
    }
    
    /// Create a new UDP socket.
    /// Why: Allocate a new UDP socket.
    /// Contract: Returns socket ID, or null if no free slot.
    pub fn create_socket(
        self: *UdpSocketManager,
        owner_process_id: u32,
    ) ?u64 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Find free slot.
        var idx: u32 = 0;
        while (idx < MAX_UDP_SOCKETS) : (idx += 1) {
            if (!self.sockets[idx].allocated) {
                // Initialize socket.
                self.sockets[idx] = UdpSocket.init();
                self.sockets[idx].allocated = true;
                self.sockets[idx].socket_id = self.next_socket_id;
                self.sockets[idx].owner_process_id = owner_process_id;
                
                // Increment socket ID.
                const socket_id = self.next_socket_id;
                self.next_socket_id += 1;
                if (self.next_socket_id == 0) {
                    self.next_socket_id = 1; // Wrap around (skip 0)
                }
                
                return socket_id;
            }
        }
        
        // No free slot found.
        return null;
    }
    
    /// Get socket by ID.
    /// Why: Retrieve socket entry.
    /// Contract: socket_id must be valid (non-zero).
    /// Returns: Pointer to socket entry, or null if not found.
    pub fn get_socket(
        self: *UdpSocketManager,
        socket_id: u64,
    ) ?*UdpSocket {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        // Assert: Socket ID must be non-zero.
        if (socket_id == 0) {
            return null;
        }
        
        // Search for socket with matching ID.
        var idx: u32 = 0;
        while (idx < MAX_UDP_SOCKETS) : (idx += 1) {
            if (self.sockets[idx].allocated and
self.sockets[idx].socket_id == socket_id) {
                return &self.sockets[idx];
            }
        }
        
        // Socket not found.
        return null;
    }
    
    /// Bind socket to local address and port.
    /// Why: Configure local endpoint for socket.
    /// Contract: socket_id must be valid, addr and port must be valid.
    pub fn bind_socket(
        self: *UdpSocketManager,
        socket_id: u64,
        addr: u32,
        port: u16,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const socket = self.get_socket(socket_id) orelse {
            return false;
        };
        
        // Assert: Socket must be in closed state.
        if (socket.state != .closed) {
            return false;
        }
        
        // Set local address and port.
        socket.local_addr = addr;
        socket.local_port = port;
        socket.state = .bound;
        
        return true;
    }
    
    /// Send data to remote address and port.
    /// Why: Transmit data to remote endpoint.
    /// Contract: socket_id must be valid, data must be valid, addr and
port must be valid.
    /// Returns: Number of bytes sent, or null on error.
    pub fn sendto(
        self: *UdpSocketManager,
        socket_id: u64,
        data: []const u8,
        addr: u32,
        port: u16,
    ) ?u32 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const socket = self.get_socket(socket_id) orelse {
            return null;
        };
        
        // Assert: Socket must be in bound state.
        if (socket.state != .bound) {
            return null;
        }
        
        // Assert: Data must fit in send buffer.
        if (socket.send_buffer_size + data.len > MAX_SOCKET_BUFFER_SIZE)
{
            return null; // Buffer full
        }
        
        // Copy data to send buffer (stub: would transmit over network).
        std.mem.copyForwards(u8,
socket.send_buffer[socket.send_buffer_size..], data);
        socket.send_buffer_size += @as(u32, @truncate(data.len));
        
        // Note: addr and port are validated but not used in stub
implementation.
        _ = addr;
        _ = port;
        
        return @as(u32, @truncate(data.len));
    }
    
    /// Receive data from socket.
    /// Why: Read incoming data from bound socket.
    /// Contract: socket_id must be valid, buffer must be valid, socket
must be bound.
    /// Returns: Number of bytes received, or null on error.
    pub fn recvfrom(
        self: *UdpSocketManager,
        socket_id: u64,
        buffer: []u8,
        addr_ptr: ?*u32,
        port_ptr: ?*u16,
    ) ?u32 {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const socket = self.get_socket(socket_id) orelse {
            return null;
        };
        
        // Assert: Socket must be in bound state.
        if (socket.state != .bound) {
            return null;
        }
        
        // Assert: Buffer must be non-empty.
        if (buffer.len == 0) {
            return null;
        }
        
        // Copy data from receive buffer (stub: would read from network).
        const bytes_to_copy = @min(socket.recv_buffer_size, @as(u32,
@truncate(buffer.len)));
        if (bytes_to_copy > 0) {
            std.mem.copyForwards(u8, buffer,
socket.recv_buffer[0..bytes_to_copy]);
            // Remove copied data from buffer (shift remaining data).
            std.mem.copyForwards(u8, socket.recv_buffer[0..],
socket.recv_buffer[bytes_to_copy..socket.recv_buffer_size]);
            socket.recv_buffer_size -= bytes_to_copy;
        }
        
        // Set remote address and port (stub: would get from received
packet).
        if (addr_ptr) |addr| {
            addr.* = 0; // Stub: would set from received packet
        }
        if (port_ptr) |port| {
            port.* = 0; // Stub: would set from received packet
        }
        
        return bytes_to_copy;
    }
    
    /// Close socket.
    /// Why: Release socket resources.
    /// Contract: socket_id must be valid.
    pub fn close_socket(
        self: *UdpSocketManager,
        socket_id: u64,
    ) bool {
        // Assert: Manager must be initialized.
        Debug.kassert(self.initialized, "Manager not initialized", .{});
        
        const socket = self.get_socket(socket_id) orelse {
            return false;
        };
        
        // Set socket to closed state and deallocate.
        socket.state = .closed;
        socket.allocated = false;
        
        return true;
    }
};


// === kernel_vm/arch.zig ===

//! Architecture Abstraction Layer
//! Why: Support multiple architectures (RISC-V64, AArch64) with unified
interface.
//! Grain Style: Explicit types (u32/u64 not usize), static allocation,
comprehensive assertions.

const std = @import("std");

/// Target architecture.
/// Why: Specify which architecture to emulate.
pub const Architecture = enum(u8) {
    riscv64 = 0,
    aarch64 = 1,
};

/// Architecture-specific register file interface.
/// Why: Abstract register operations across architectures.
pub const RegisterFileInterface = struct {
    /// Get register value.
    /// Why: Read register value (architecture-specific).
    /// Contract: reg_index must be valid for architecture.
    get: *const fn (self: *anyopaque, reg_index: u8) u64,
    
    /// Set register value.
    /// Why: Write register value (architecture-specific).
    /// Contract: reg_index must be valid for architecture.
    set: *const fn (self: *anyopaque, reg_index: u8, value: u64) void,
    
    /// Get program counter.
    /// Why: Read program counter (architecture-specific).
    get_pc: *const fn (self: *anyopaque) u64,
    
    /// Set program counter.
    /// Why: Write program counter (architecture-specific).
    set_pc: *const fn (self: *anyopaque, value: u64) void,
    
    /// Get number of registers.
    /// Why: Query register count (architecture-specific).
    get_register_count: *const fn (self: *anyopaque) u8,
};

/// Architecture-specific memory interface.
/// Why: Abstract memory operations across architectures.
pub const MemoryInterface = struct {
    /// Read memory at address (8 bytes).
    /// Why: Read memory (architecture-specific endianness/alignment).
    /// Contract: addr must be valid, aligned.
    read64: *const fn (self: *anyopaque, addr: u64) anyerror!u64,
    
    /// Write memory at address (8 bytes).
    /// Why: Write memory (architecture-specific endianness/alignment).
    /// Contract: addr must be valid, aligned.
    write64: *const fn (self: *anyopaque, addr: u64, value: u64)
anyerror!void,
    
    /// Get memory size.
    /// Why: Query memory size (architecture-specific).
    get_memory_size: *const fn (self: *anyopaque) u64,
};

/// Architecture-specific instruction decoder interface.
/// Why: Abstract instruction decoding across architectures.
pub const InstructionDecoderInterface = struct {
    /// Decode instruction.
    /// Why: Decode instruction (architecture-specific).
    /// Contract: instruction must be valid for architecture.
    decode: *const fn (self: *anyopaque, instruction: u32) anyerror!void,
    
    /// Get instruction length.
    /// Why: Query instruction length (architecture-specific).
    /// Contract: Returns instruction length in bytes (4 for RISC-V, 4
for AArch64).
    get_instruction_length: *const fn (self: *anyopaque) u32,
};

/// Architecture configuration.
/// Why: Store architecture-specific configuration.
pub const ArchConfig = struct {
    /// Target architecture.
    arch: Architecture,
    
    /// Memory size in bytes.
    memory_size: u64,
    
    /// Instruction length in bytes (4 for RISC-V, 4 for AArch64).
    instruction_length: u32,
    
    /// Register count (32 for RISC-V, 31 for AArch64).
    register_count: u8,
    
    /// Initialize architecture configuration.
    /// Why: Set up architecture-specific defaults.
    pub fn init(arch: Architecture) ArchConfig {
        return switch (arch) {
            .riscv64 => ArchConfig{
                .arch = .riscv64,
                .memory_size = 8 * 1024 * 1024, // 8MB default
                .instruction_length = 4,
                .register_count = 32,
            },
            .aarch64 => ArchConfig{
                .arch = .aarch64,
                .memory_size = 8 * 1024 * 1024, // 8MB default
                .instruction_length = 4,
                .register_count = 31, // AArch64 has 31 general-purpose
registers (x0-x30)
            },
        };
    }
    
    /// Validate architecture configuration.
    /// Why: Ensure configuration is valid.
    pub fn is_valid(self: *const ArchConfig) bool {
        // Assert: Memory size must be reasonable (1MB to 1GB).
        if (self.memory_size < 1024 * 1024 or self.memory_size > 1024 *
1024 * 1024) {
            return false;
        }
        
        // Assert: Instruction length must be valid (4 bytes for both
architectures).
        if (self.instruction_length != 4) {
            return false;
        }
        
        // Assert: Register count must be valid.
        if (self.register_count == 0 or self.register_count > 32) {
            return false;
        }
        
        return true;
    }
};

/// Get architecture name.
/// Why: Human-readable architecture name.
pub fn get_arch_name(arch: Architecture) []const u8 {
    return switch (arch) {
        .riscv64 => "RISC-V64",
        .aarch64 => "AArch64",
    };
}

/// Check if architecture is supported.
/// Why: Validate architecture support.
pub fn is_arch_supported(arch: Architecture) bool {
    _ = arch;
    // Both architectures are supported.
    return true;
}


// === kernel_vm/benchmark.zig ===

//! VM Performance Benchmarking Framework
//!
//! Objective: Provide benchmarking framework for VM performance
evaluation.
//! Why: Enable systematic performance testing, comparison, and
regression detection.
//! GrainStyle: Static allocation, bounded buffers, explicit types,
deterministic benchmarking.
//!
//! Methodology:
//! - Benchmark execution (run test programs and measure performance)
//! - Performance metrics collection (instructions, cycles, memory, JIT
stats)
//! - Benchmark comparison (compare current vs baseline results)
//! - Performance regression detection (detect performance degradation)
//! - Bounded benchmark results (MAX_BENCHMARKS: 64)
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded buffers: fixed-size benchmark result arrays
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-12-02
//! GrainStyle: Comprehensive benchmarking framework, deterministic
behavior, explicit limits

const std = @import("std");
const VM = @import("vm.zig").VM;
const VMError = @import("vm.zig").VM.VMError;

// Bounded: Maximum number of benchmarks.
pub const MAX_BENCHMARKS: u32 = 64;

// Benchmark result.
pub const BenchmarkResult = struct {
    name: [64]u8,
    name_len: u32,
    instructions_executed: u64,
    cycles_simulated: u64,
    memory_reads: u64,
    memory_writes: u64,
    syscalls: u64,
    execution_time_ns: u64,
    jit_cache_hit_rate: f64,
    passed: bool,

    pub fn init() BenchmarkResult {
        return BenchmarkResult{
            .name = [_]u8{0} ** 64,
            .name_len = 0,
            .instructions_executed = 0,
            .cycles_simulated = 0,
            .memory_reads = 0,
            .memory_writes = 0,
            .syscalls = 0,
            .execution_time_ns = 0,
            .jit_cache_hit_rate = 0.0,
            .passed = false,
        };
    }
};

// VM benchmark runner.
pub const VMBenchmark = struct {
    results: [MAX_BENCHMARKS]BenchmarkResult,
    results_count: u32,

    pub fn init() VMBenchmark {
        var benchmark = VMBenchmark{
            .results = undefined,
            .results_count = 0,
        };
        var i: u32 = 0;
        while (i < MAX_BENCHMARKS) : (i += 1) {
            benchmark.results[i] = BenchmarkResult.init();
        }
        return benchmark;
    }

    pub fn run_benchmark(self: *VMBenchmark, vm: *VM, name: []const u8,
max_steps: u64) VMError!BenchmarkResult {
        if (self.results_count >= MAX_BENCHMARKS) {
            return VMError.invalid_memory_access;
        }
        if (name.len > 64) {
            return VMError.invalid_memory_access;
        }
        var result = BenchmarkResult.init();
        @memcpy(result.name[0..name.len], name);
        result.name_len = @as(u32, @intCast(name.len));
        const perf_before = vm.performance;
        const start_time = std.time.nanoTimestamp();
        vm.start();
        var steps: u64 = 0;
        while (vm.state == .running and steps < max_steps) : (steps +=
1) {
            try vm.step_jit();
        }
        const end_time = std.time.nanoTimestamp();
        const execution_time: i64 = end_time - start_time;
        result.execution_time_ns = if (execution_time > 0) @as(u64,
@intCast(execution_time)) else 0;
        result.instructions_executed =
vm.performance.instructions_executed - perf_before.instructions_executed;
        result.cycles_simulated = vm.performance.cycles_simulated -
perf_before.cycles_simulated;
        result.memory_reads = vm.performance.memory_reads -
perf_before.memory_reads;
        result.memory_writes = vm.performance.memory_writes -
perf_before.memory_writes;
        result.syscalls = vm.performance.syscalls - perf_before.syscalls;
        if (vm.jit) |jit_ctx| {
            const total_ops = jit_ctx.perf_counters.cache_hits +
jit_ctx.perf_counters.cache_misses;
            result.jit_cache_hit_rate = if (total_ops > 0)
                @as(f64,
@floatFromInt(jit_ctx.perf_counters.cache_hits)) / @as(f64,
@floatFromInt(total_ops))
            else
                0.0;
        }
        result.passed = (vm.state == .halted);
        const idx = self.results_count;
        self.results[idx] = result;
        self.results_count += 1;
        return result;
    }

    pub fn compare_results(self: *const VMBenchmark, baseline: *const
VMBenchmark) void {
        std.debug.print("\n=== Benchmark Comparison ===\n", .{});
        var i: u32 = 0;
        while (i < self.results_count) : (i += 1) {
            const current = &self.results[i];
            var found = false;
            var j: u32 = 0;
            while (j < baseline.results_count) : (j += 1) {
                const base = &baseline.results[j];
                if (std.mem.eql(u8, current.name[0..current.name_len],
base.name[0..base.name_len])) {
                    found = true;
                    const speedup = if (current.execution_time_ns > 0)
                        @as(f64, @floatFromInt(base.execution_time_ns))
/ @as(f64, @floatFromInt(current.execution_time_ns))
                    else
                        0.0;
                    std.debug.print("  {}: {d:.2}x speedup\n", .{
current.name[0..current.name_len], speedup });
                    break;
                }
            }
            if (!found) {
                std.debug.print("  {}: (no baseline)\n",
.{current.name[0..current.name_len]});
            }
        }
    }

    pub fn print_results(self: *const VMBenchmark) void {
        std.debug.print("\n=== Benchmark Results ===\n", .{});
        var i: u32 = 0;
        while (i < self.results_count) : (i += 1) {
            const result = &self.results[i];
            std.debug.print("  {}: ",
.{result.name[0..result.name_len]});
            std.debug.print("{} instructions, ",
.{result.instructions_executed});
            std.debug.print("{} ns, ", .{result.execution_time_ns});
            std.debug.print("JIT hit rate: {d:.2}%, ",
.{result.jit_cache_hit_rate * 100.0});
            std.debug.print("Status: {s}\n", .{if (result.passed) "PASS"
else "FAIL"});
        }
    }

    pub fn get_results_count(self: *const VMBenchmark) u32 {
        return self.results_count;
    }

    pub fn get_result(self: *const VMBenchmark, index: u32) ?*const
BenchmarkResult {
        if (index >= self.results_count) {
            return null;
        }
        return &self.results[index];
    }

    pub fn clear_results(self: *VMBenchmark) void {
        self.results_count = 0;
    }
};


// === kernel_vm/benchmark_jit.zig ===

const std = @import("std");
const vm_mod = @import("vm.zig");
const jit_mod = @import("jit.zig");
const builtin = @import("builtin");

/// Fibonacci benchmark for JIT vs Interpreter comparison
/// Calculates fib(30) using recursion to stress-test control flow and
stack operations.
pub fn main() !void {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) {
        std.debug.print("Benchmarks require macOS on Apple Silicon.\n",
.{});
        return;
    }

    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();

    std.debug.print("\n🚀 Grain Vantage Benchmark: JIT vs Interpreter\n",
.{});
    std.debug.print("=========================================\n", .{});

    // RISC-V64 machine code for recursive Fibonacci(n)
    // Input: a0 = n
    // Output: a0 = fib(n)
    // C code:
    // long fib(long n) {
    //     if (n <= 1) return n;
    //     return fib(n-1) + fib(n-2);
    // }

    
    // Using a pre-compiled simple iterative loop for stability first,
then recursive.
    // Sum(n): 0 to n
    // a0 = n
    // result in a0
    const sum_program = [_]u8{
        // li t0, 0 (sum = 0)
        0x93, 0x02, 0x00, 0x00,
        // li t1, 0 (i = 0)
        0x13, 0x03, 0x00, 0x00,
        // loop:
        // bge t1, a0, exit
        0x63, 0xd6, 0xa3, 0x00, // offset +12 -> exit
        // add t0, t0, t1
        0x33, 0x02, 0x62, 0x00,
        // addi t1, t1, 1
        0x93, 0x83, 0x13, 0x00,
        // j loop
        0x6f, 0xf0, 0x5f, 0xff, // offset -12
        // exit:
        // mv a0, t0
        0x13, 0x05, 0x52, 0x00,
        // ret
        0x67, 0x80, 0x00, 0x00,
    };

    const n_iterations = 1000; // Increased for better measurement
accuracy
    const n_runs = 1; // Single run for now (can increase if memory
allows)
    
    var interpreter_times: [n_runs]i64 = undefined;
    var jit_times: [n_runs]i64 = undefined;
    
    std.debug.print("Running {d} iterations, {d} run(s)...\n\n", .{
n_iterations, n_runs });
    
    // 1. Run Interpreter (multiple runs, reuse single VM)
    std.debug.print("📊 Interpreter Benchmarks:\n", .{});
    std.debug.print("───────────────────────────\n", .{});
    
    const vm_interp = try allocator.create(vm_mod.VM);
    defer allocator.destroy(vm_interp);
    vm_interp.init(&sum_program, 0x80000000); // Use init() to avoid JIT
allocation
    
    for (0..n_runs) |run_idx| {
        // Reset VM state for each run
        vm_interp.regs = .{};
        vm_interp.regs.set(10, n_iterations);
        vm_interp.regs.set(1, 0x90000000); // RA = Magic exit
        vm_interp.regs.pc = 0x80000000;
        vm_interp.state = .running;
        
        const start = std.time.nanoTimestamp();
        
        var steps: usize = 0;
        while (vm_interp.regs.pc != 0x90000000 and vm_interp.state ==
.running) {
            vm_interp.step() catch |err| {
                std.debug.print("Interpreter error at PC=0x{x}: {}\n",
.{vm_interp.regs.pc, err});
                break;
            };
            steps += 1;
            if (steps > 100000) {
                std.debug.print("Interpreter timeout! PC=0x{x}\n",
.{vm_interp.regs.pc});
                break;
            }
        }
        
        const end = std.time.nanoTimestamp();
        const duration: i64 = @intCast(end - start);
        interpreter_times[run_idx] = duration;
        
        std.debug.print("  Run {}: {d:.2} ms ({} steps)\n", .{
            run_idx + 1,
            @as(f64, @floatFromInt(duration)) / 1_000_000.0,
            steps,
        });
    }

    // 2. Run JIT (multiple runs, reuse single VM)
    std.debug.print("\n🚀 JIT Benchmarks:\n", .{});
    std.debug.print("──────────────────\n", .{});
    
    const vm_jit = try allocator.create(vm_mod.VM);
    defer allocator.destroy(vm_jit);
    try vm_jit.init_with_jit(allocator, &sum_program, 0x80000000);
    defer vm_jit.deinit_jit(allocator);
    vm_jit.jit_enabled = true; // Enable JIT
    
    for (0..n_runs) |run_idx| {
        // Reset VM state for each run
        vm_jit.regs = .{};
        vm_jit.regs.set(10, n_iterations);
        vm_jit.regs.set(1, 0x90000000); // RA = Magic exit
        vm_jit.regs.pc = 0x80000000;
        vm_jit.state = .running;
        
        // Clear JIT cache between runs (for fair comparison)
        if (vm_jit.jit) |jit| {
            jit.block_cache.clearRetainingCapacity();
        }
        
        const start = std.time.nanoTimestamp();
        
        var steps: usize = 0;
        while (vm_jit.regs.pc != 0x90000000 and vm_jit.state ==
.running) {
            vm_jit.step_jit() catch |err| {
                std.debug.print("JIT error at PC=0x{x}: {}\n",
.{vm_jit.regs.pc, err});
                break;
            };
            steps += 1;
            if (steps > 100000) {
                std.debug.print("JIT timeout! PC=0x{x}\n",
.{vm_jit.regs.pc});
                break;
            }
        }
        
        const end = std.time.nanoTimestamp();
        const duration: i64 = @intCast(end - start);
        jit_times[run_idx] = duration;
        
        std.debug.print("  Run {}: {d:.2} ms ({} steps)\n", .{
            run_idx + 1,
            @as(f64, @floatFromInt(duration)) / 1_000_000.0,
            steps,
        });
        
        // Print JIT stats on last run
        if (run_idx == n_runs - 1) {
            if (vm_jit.jit) |jit| {
                std.debug.print("\n", .{});
            jit.perf_counters.print_stats();
        }
    }
    }
    
    // 3. Calculate statistics
    std.debug.print("\n📈 Performance Summary:\n", .{});
    std.debug.print("════════════════════════\n", .{});
    
    // Calculate averages
    var interpreter_avg: f64 = 0.0;
    var jit_avg: f64 = 0.0;
    
    for (0..n_runs) |i| {
        interpreter_avg += @as(f64, @floatFromInt(interpreter_times[i]));
        jit_avg += @as(f64, @floatFromInt(jit_times[i]));
    }
    
    interpreter_avg /= @as(f64, @floatFromInt(n_runs));
    jit_avg /= @as(f64, @floatFromInt(n_runs));
    
    const speedup = interpreter_avg / jit_avg;
    
    std.debug.print("Interpreter Average: {d:.2} ms\n",
.{interpreter_avg / 1_000_000.0});
    std.debug.print("JIT Average:         {d:.2} ms\n", .{jit_avg /
1_000_000.0});
    std.debug.print("Speedup:             {d:.2}x\n", .{speedup});
    
    // Verify 10x+ speedup requirement
    std.debug.print("\n✅ Verification:\n", .{});
    std.debug.print("═══════════════\n", .{});
    
    if (speedup >= 10.0) {
        std.debug.print("✅ PASS: Speedup ({d:.2}x) meets 10x+
requirement!\n", .{speedup});
    } else {
        std.debug.print("❌ FAIL: Speedup ({d:.2}x) below 10x
requirement\n", .{speedup});
    }
    
    // Memory info: JIT uses ~64MB code buffer (static allocation)
    std.debug.print("\n📊 Memory Usage:\n", .{});
    std.debug.print("════════════════\n", .{});
    std.debug.print("JIT Code Buffer: 64 MB (static allocation)\n", .{});
    std.debug.print("Block Cache:     ~10,000 entries (dynamic)\n", .{});
    std.debug.print("Memory Overhead: ~64 MB (acceptable for 10x+
speedup)\n", .{});
}

// === kernel_vm/branch_stats.zig ===

//! VM Branch Prediction Statistics Tracking System
//!
//! Objective: Track branch instruction outcomes (taken/not taken) for
branch prediction analysis.
//! Why: Monitor branch behavior, identify branch patterns, optimize
branch prediction.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track branch instructions by PC
//! - Track branch outcomes (taken vs not taken)
//! - Track branch prediction accuracy
//! - Calculate branch taken rate
//! - Provide statistics interface for querying branch data
//! - Reset capability for new measurement periods
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive branch tracking, deterministic behavior,
explicit limits

const std = @import("std");

// Bounded: Max branch PCs to track.
pub const MAX_BRANCH_PCS: u32 = 128;

// Branch entry: tracks branch statistics for a PC.
pub const BranchEntry = struct {
    pc: u64,
    total_branches: u64,
    taken_count: u64,
    not_taken_count: u64,

    pub fn init(pc: u64) BranchEntry {
        return BranchEntry{
            .pc = pc,
            .total_branches = 0,
            .taken_count = 0,
            .not_taken_count = 0,
        };
    }

    fn get_taken_rate(self: *const BranchEntry) f64 {
        if (self.total_branches == 0) {
            return 0.0;
        }
        return @as(f64, @floatFromInt(self.taken_count)) /
            @as(f64, @floatFromInt(self.total_branches)) * 100.0;
    }
};

// VM branch statistics tracker.
pub const VMBranchStats = struct {
    entries: [MAX_BRANCH_PCS]BranchEntry,
    entries_len: u32,
    total_branches: u64,
    total_taken: u64,
    total_not_taken: u64,

    pub fn init() VMBranchStats {
        var stats = VMBranchStats{
            .entries = undefined,
            .entries_len = 0,
            .total_branches = 0,
            .total_taken = 0,
            .total_not_taken = 0,
        };
        var i: u32 = 0;
        while (i < MAX_BRANCH_PCS) : (i += 1) {
            stats.entries[i] = BranchEntry.init(0);
        }
        return stats;
    }

    fn find_or_add_branch(self: *VMBranchStats, pc: u64) ?u32 {
        // Find existing branch entry.
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].pc == pc) {
                return i;
            }
        }
        // Add new branch entry if space available.
        if (self.entries_len >= MAX_BRANCH_PCS) {
            return null;
        }
        const idx = self.entries_len;
        self.entries[idx] = BranchEntry.init(pc);
        self.entries_len += 1;
        return idx;
    }

    pub fn record_branch(self: *VMBranchStats, pc: u64, taken: bool)
void {
        self.total_branches += 1;
        if (taken) {
            self.total_taken += 1;
        } else {
            self.total_not_taken += 1;
        }
        if (self.find_or_add_branch(pc)) |idx| {
            self.entries[idx].total_branches += 1;
            if (taken) {
                self.entries[idx].taken_count += 1;
            } else {
                self.entries[idx].not_taken_count += 1;
            }
        }
    }

    fn print_top_branches(self: *const VMBranchStats) void {
        if (self.total_branches == 0 or self.entries_len == 0) {
            return;
        }
        std.debug.print("  Top Branches:\n", .{});
        var top_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.entries_len and top_count < 10) : (i += 1) {
            const entry = self.entries[i];
            if (entry.total_branches > 0) {
                const taken_rate = entry.get_taken_rate();
                std.debug.print("    0x{x}: {} branches, {d:.2}%
taken\n", .{
                    entry.pc,
                    entry.total_branches,
                    taken_rate,
                });
                top_count += 1;
            }
        }
    }

    pub fn print_stats(self: *const VMBranchStats) void {
        std.debug.print("\nVM Branch Statistics:\n", .{});
        std.debug.print("  Total Branches: {}\n",
.{self.total_branches});
        std.debug.print("  Total Taken: {}\n", .{self.total_taken});
        std.debug.print("  Total Not Taken: {}\n",
.{self.total_not_taken});
        if (self.total_branches > 0) {
            const overall_taken_rate = @as(f64,
@floatFromInt(self.total_taken)) /
                @as(f64, @floatFromInt(self.total_branches)) * 100.0;
            std.debug.print("  Overall Taken Rate: {d:.2}%\n",
.{overall_taken_rate});
        }
        std.debug.print("  Unique Branch PCs: {}\n",
.{self.entries_len});
        self.print_top_branches();
    }

    pub fn reset(self: *VMBranchStats) void {
        self.total_branches = 0;
        self.total_taken = 0;
        self.total_not_taken = 0;
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            self.entries[i].total_branches = 0;
            self.entries[i].taken_count = 0;
            self.entries[i].not_taken_count = 0;
        }
        self.entries_len = 0;
    }
};


// === kernel_vm/checkpoint.zig ===

//! VM Checkpoint/Restore System
//!
//! Objective: Provide checkpoint/restore capabilities for VM state
management.
//! Why: Enable saving and restoring complete VM state for debugging and
state management.
//! GrainStyle: Static allocation, bounded buffers, explicit types,
deterministic checkpointing.
//!
//! Methodology:
//! - Checkpoint creation (save complete VM state to buffer)
//! - Checkpoint restoration (restore VM state from buffer)
//! - Bounded checkpoint buffer (MAX_CHECKPOINT_SIZE: 1MB)
//! - State validation (verify checkpoint integrity)
//! - Multiple checkpoints (support multiple saved states)
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded buffers: fixed-size checkpoint buffer
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-26
//! GrainStyle: Comprehensive checkpoint/restore, deterministic
behavior, explicit limits

const std = @import("std");
const VM = @import("vm.zig").VM;
const VMError = @import("vm.zig").VM.VMError;

// Bounded: Maximum checkpoint size (1MB per checkpoint).
pub const MAX_CHECKPOINT_SIZE: u32 = 1024 * 1024;
// Bounded: Maximum number of checkpoints (sufficient for debugging).
pub const MAX_CHECKPOINTS: u32 = 16;
// Bounded: Maximum VM memory size for checkpointing (8MB).
pub const MAX_VM_MEMORY_SIZE: u32 = 8 * 1024 * 1024;

// Checkpoint header (metadata for checkpoint).
pub const CheckpointHeader = struct {
    magic: u32,
    version: u32,
    vm_memory_size: u32,
    pc: u64,
    state: u32,
    checksum: u32,

    pub fn init() CheckpointHeader {
        return CheckpointHeader{
            .magic = 0x564D4350,
            .version = 1,
            .vm_memory_size = 0,
            .pc = 0,
            .state = 0,
            .checksum = 0,
        };
    }
};

// VM checkpoint manager.
pub const VMCheckpoint = struct {
    checkpoints: [MAX_CHECKPOINTS]?CheckpointData,
    checkpoint_count: u32,

    const CheckpointData = struct {
        header: CheckpointHeader,
        memory: [MAX_VM_MEMORY_SIZE]u8,
        memory_size: u32,
        registers: [32]u64,
    };

    pub fn init() VMCheckpoint {
        return VMCheckpoint{
            .checkpoints = [_]?CheckpointData{null} ** MAX_CHECKPOINTS,
            .checkpoint_count = 0,
        };
    }

    pub fn create_checkpoint(self: *VMCheckpoint, vm: *VM,
checkpoint_id: u32) VMError!bool {
        if (checkpoint_id >= MAX_CHECKPOINTS) {
            return VMError.invalid_memory_access;
        }
        if (self.checkpoint_count >= MAX_CHECKPOINTS) {
            return VMError.invalid_memory_access;
        }
        var header = CheckpointHeader.init();
        header.vm_memory_size = vm.memory_size;
        header.pc = vm.regs.pc;
        header.state = @intFromEnum(vm.state);
        var registers: [32]u64 = undefined;
        var i: u32 = 0;
        while (i < 32) : (i += 1) {
            registers[i] = vm.regs.get(@as(u5, @intCast(i)));
        }
        const memory_size = vm.memory_size;
        if (memory_size > MAX_VM_MEMORY_SIZE) {
            return VMError.invalid_memory_access;
        }
        var checkpoint = CheckpointData{
            .header = header,
            .memory = [_]u8{0} ** MAX_VM_MEMORY_SIZE,
            .memory_size = @as(u32, @intCast(memory_size)),
            .registers = registers,
        };
        @memcpy(checkpoint.memory[0..memory_size],
vm.memory[0..memory_size]);
        checkpoint.header.checksum =
self.calculate_checksum(&checkpoint);
        if (self.checkpoints[checkpoint_id]) |_| {
            self.checkpoint_count -= 1;
        }
        self.checkpoints[checkpoint_id] = checkpoint;
        self.checkpoint_count += 1;
        return true;
    }

    pub fn restore_checkpoint(self: *VMCheckpoint, vm: *VM,
checkpoint_id: u32) VMError!bool {
        if (checkpoint_id >= MAX_CHECKPOINTS) {
            return VMError.invalid_memory_access;
        }
        const checkpoint_opt = self.checkpoints[checkpoint_id];
        if (checkpoint_opt == null) {
            return VMError.invalid_memory_access;
        }
        const checkpoint = checkpoint_opt.?;
        if (checkpoint.header.magic != 0x564D4350) {
            return VMError.invalid_memory_access;
        }
        if (checkpoint.header.version != 1) {
            return VMError.invalid_memory_access;
        }
        const checksum = self.calculate_checksum(&checkpoint);
        if (checksum != checkpoint.header.checksum) {
            return VMError.invalid_memory_access;
        }
        if (checkpoint.header.vm_memory_size != vm.memory_size) {
            return VMError.invalid_memory_access;
        }
        @memcpy(vm.memory[0..checkpoint.memory_size],
checkpoint.memory[0..checkpoint.memory_size]);
        vm.regs.pc = checkpoint.header.pc;
        vm.state = @enumFromInt(checkpoint.header.state);
        var i: u32 = 0;
        while (i < 32) : (i += 1) {
            vm.regs.set(@as(u5, @intCast(i)), checkpoint.registers[i]);
        }
        return true;
    }

    pub fn delete_checkpoint(self: *VMCheckpoint, checkpoint_id: u32)
bool {
        if (checkpoint_id >= MAX_CHECKPOINTS) {
            return false;
        }
        if (self.checkpoints[checkpoint_id] == null) {
            return false;
        }
        self.checkpoints[checkpoint_id] = null;
        self.checkpoint_count -= 1;
        return true;
    }

    pub fn has_checkpoint(self: *const VMCheckpoint, checkpoint_id: u32)
bool {
        if (checkpoint_id >= MAX_CHECKPOINTS) {
            return false;
        }
        return self.checkpoints[checkpoint_id] != null;
    }

    pub fn get_checkpoint_count(self: *const VMCheckpoint) u32 {
        return self.checkpoint_count;
    }

    fn calculate_checksum(self: *const VMCheckpoint, checkpoint: *const
CheckpointData) u32 {
        _ = self;
        var sum: u32 = 0;
        sum +%= checkpoint.header.magic;
        sum +%= checkpoint.header.version;
        sum +%= checkpoint.header.vm_memory_size;
        sum +%= @as(u32, @truncate(checkpoint.header.pc));
        sum +%= @as(u32, @truncate(checkpoint.header.pc >> 32));
        sum +%= checkpoint.header.state;
        var i: u32 = 0;
        while (i < 32) : (i += 1) {
            sum +%= @as(u32, @truncate(checkpoint.registers[i]));
            sum +%= @as(u32, @truncate(checkpoint.registers[i] >> 32));
        }
        const memory_size = checkpoint.memory_size;
        i = 0;
        while (i < memory_size) : (i += 1) {
            sum +%= checkpoint.memory[i];
        }
        return sum;
    }
};


// === kernel_vm/debug_command.zig ===

//! VM Debugging Command Interface
//!
//! Objective: Provide unified debugging command interface combining
breakpoints, watchpoints,
//! state inspection, and execution control.
//! Why: Enable debugging tools to use a single high-level API for all
debugging operations.
//! GrainStyle: Static allocation, bounded buffers, explicit types,
deterministic debugging.
//!
//! Methodology:
//! - Unified debugging API (combines debug_interface, state_inspection,
execution_control)
//! - Command-based interface (set breakpoint, continue, step, inspect
state)
//! - Debugging session management (start, pause, resume, stop)
//! - Bounded command buffer (MAX_COMMAND_SIZE: 256 bytes)
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded buffers: fixed-size command buffers
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-25
//! GrainStyle: Comprehensive debugging command interface, deterministic
behavior, explicit limits

const std = @import("std");
const VM = @import("vm.zig").VM;
const VMError = @import("vm.zig").VM.VMError;
const debug_interface_mod = @import("debug_interface.zig");
const state_inspection_mod = @import("state_inspection.zig");
const execution_control_mod = @import("execution_control.zig");

// Bounded: Maximum command size for debugging commands.
pub const MAX_COMMAND_SIZE: u32 = 256;

// Debugging command result.
pub const DebugCommandResult = enum {
    success,
    error_occurred,
    breakpoint_hit,
    watchpoint_triggered,
};

// Unified debugging command interface.
pub const VMDebugCommand = struct {
    vm: *VM,
    debug_interface: *debug_interface_mod.VMDebugInterface,
    state_inspector: state_inspection_mod.VMStateInspector,
    execution_controller: execution_control_mod.VMExecutionController,

    pub fn init(vm: *VM) VMDebugCommand {
        return VMDebugCommand{
            .vm = vm,
            .debug_interface = &vm.debug_interface,
            .state_inspector =
state_inspection_mod.VMStateInspector.init(vm),
            .execution_controller =
execution_control_mod.VMExecutionController.init(vm),
        };
    }

    pub fn set_breakpoint(self: *VMDebugCommand, pc: u64) bool {
        return self.debug_interface.set_breakpoint(pc);
    }

    pub fn remove_breakpoint(self: *VMDebugCommand, pc: u64) bool {
        return self.debug_interface.remove_breakpoint(pc);
    }

    pub fn set_watchpoint(self: *VMDebugCommand, address: u64, size:
u64, watch_reads: bool, watch_writes: bool) bool {
        return self.debug_interface.set_watchpoint(address, size,
watch_reads, watch_writes);
    }

    pub fn remove_watchpoint(self: *VMDebugCommand, address: u64) bool {
        return self.debug_interface.remove_watchpoint(address);
    }

    pub fn continue_execution(self: *VMDebugCommand) void {
        self.execution_controller.continue_execution();
        self.debug_interface.clear_breakpoint_hit();
        self.debug_interface.clear_watchpoint_triggered();
    }

    pub fn step_over(self: *VMDebugCommand) void {
        self.execution_controller.step_over();
        self.debug_interface.clear_breakpoint_hit();
        self.debug_interface.clear_watchpoint_triggered();
    }

    pub fn step_into(self: *VMDebugCommand) void {
        self.execution_controller.step_into();
        self.debug_interface.clear_breakpoint_hit();
        self.debug_interface.clear_watchpoint_triggered();
    }

    pub fn pause_execution(self: *VMDebugCommand) void {
        self.execution_controller.pause();
    }

    pub fn get_register_state(self: *const VMDebugCommand)
state_inspection_mod.RegisterState {
        return self.state_inspector.get_register_state();
    }

    pub fn get_register(self: *const VMDebugCommand, reg_num: u32) u64 {
        return self.state_inspector.get_register(reg_num);
    }

    pub fn get_pc(self: *const VMDebugCommand) u64 {
        return self.state_inspector.get_pc();
    }

    pub fn dump_memory(self: *const VMDebugCommand, address: u64, size:
u32) ?state_inspection_mod.MemoryDump {
        return self.state_inspector.dump_memory(address, size);
    }

    pub fn read_memory_u64(self: *const VMDebugCommand, address: u64)
?u64 {
        return self.state_inspector.read_memory_u64(address);
    }

    pub fn read_memory_u32(self: *const VMDebugCommand, address: u64)
?u32 {
        return self.state_inspector.read_memory_u32(address);
    }

    pub fn dump_stack(self: *const VMDebugCommand, stack_pointer: u64)
?state_inspection_mod.MemoryDump {
        return self.state_inspector.dump_stack(stack_pointer);
    }

    pub fn check_breakpoint_hit(self: *const VMDebugCommand) bool {
        return self.debug_interface.breakpoint_hit;
    }

    pub fn check_watchpoint_triggered(self: *const VMDebugCommand) bool {
        return self.debug_interface.watchpoint_triggered;
    }

    pub fn get_last_breakpoint_pc(self: *const VMDebugCommand) u64 {
        return self.debug_interface.last_breakpoint_pc;
    }

    pub fn get_last_watchpoint_addr(self: *const VMDebugCommand) u64 {
        return self.debug_interface.last_watchpoint_addr;
    }

    pub fn execute_step(self: *VMDebugCommand)
VMError!DebugCommandResult {
        if (self.debug_interface.breakpoint_hit) {
            return DebugCommandResult.breakpoint_hit;
        }
        if (self.debug_interface.watchpoint_triggered) {
            return DebugCommandResult.watchpoint_triggered;
        }
        const should_continue =
self.execution_controller.should_continue();
        if (should_continue) {
            try self.vm.step();
            return DebugCommandResult.success;
        }
        const should_step = self.execution_controller.should_step();
        if (should_step) {
            const continued = try
self.execution_controller.execute_step();
            if (!continued) {
                return DebugCommandResult.success;
            }
            return DebugCommandResult.success;
        }
        return DebugCommandResult.success;
    }

    pub fn print_state(self: *const VMDebugCommand) void {
        self.state_inspector.print_register_state();
    }

    pub fn print_memory(self: *const VMDebugCommand, address: u64, size:
u32) void {
        self.state_inspector.print_memory_dump(address, size);
    }
};


// === kernel_vm/debug_interface.zig ===

//! VM Debugging Interface System
//!
//! Objective: Provide debugging capabilities (breakpoints, watchpoints,
step debugging).
//! Why: Enable debugging of kernel code running in the VM, set
breakpoints, watch memory/registers.
//! GrainStyle: Static allocation, bounded arrays, explicit types,
deterministic debugging.
//!
//! Methodology:
//! - Breakpoint management (set/remove breakpoints at PC addresses)
//! - Watchpoint management (watch memory addresses for read/write)
//! - Step debugging (execute one instruction at a time)
//! - Register watch (monitor register changes)
//! - Debug state tracking (breakpoint hit, watchpoint triggered)
//! - Bounded breakpoint/watchpoint arrays
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded arrays: fixed-size breakpoint/watchpoint arrays
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive debugging interface, deterministic
behavior, explicit limits

const std = @import("std");

// Bounded: Maximum number of breakpoints (sufficient for kernel
debugging).
pub const MAX_BREAKPOINTS: u32 = 32;
// Bounded: Maximum number of watchpoints (sufficient for memory
debugging).
pub const MAX_WATCHPOINTS: u32 = 32;

// Breakpoint entry: tracks breakpoint at PC address.
pub const Breakpoint = struct {
    pc: u64,
    enabled: bool,

    pub fn init(pc: u64) Breakpoint {
        return Breakpoint{
            .pc = pc,
            .enabled = true,
        };
    }
};

// Watchpoint entry: tracks watchpoint at memory address.
pub const Watchpoint = struct {
    address: u64,
    size: u64,
    watch_reads: bool,
    watch_writes: bool,
    enabled: bool,

    pub fn init(address: u64, size: u64, watch_reads: bool,
watch_writes: bool) Watchpoint {
        std.debug.assert(size > 0);
        std.debug.assert(size <= 8);
        return Watchpoint{
            .address = address,
            .size = size,
            .watch_reads = watch_reads,
            .watch_writes = watch_writes,
            .enabled = true,
        };
    }
};

// VM debugging interface.
pub const VMDebugInterface = struct {
    breakpoints: [MAX_BREAKPOINTS]Breakpoint,
    breakpoints_len: u32,
    watchpoints: [MAX_WATCHPOINTS]Watchpoint,
    watchpoints_len: u32,
    step_mode: bool,
    breakpoint_hit: bool,
    watchpoint_triggered: bool,
    last_breakpoint_pc: u64,
    last_watchpoint_addr: u64,

    pub fn init() VMDebugInterface {
        var debug = VMDebugInterface{
            .breakpoints = undefined,
            .breakpoints_len = 0,
            .watchpoints = undefined,
            .watchpoints_len = 0,
            .step_mode = false,
            .breakpoint_hit = false,
            .watchpoint_triggered = false,
            .last_breakpoint_pc = 0,
            .last_watchpoint_addr = 0,
        };
        var i: u32 = 0;
        while (i < MAX_BREAKPOINTS) : (i += 1) {
            debug.breakpoints[i] = Breakpoint.init(0);
        }
        i = 0;
        while (i < MAX_WATCHPOINTS) : (i += 1) {
            debug.watchpoints[i] = Watchpoint.init(0, 1, false, false);
        }
        return debug;
    }

    pub fn set_breakpoint(self: *VMDebugInterface, pc: u64) bool {
        if (self.breakpoints_len >= MAX_BREAKPOINTS) {
            return false;
        }
        var i: u32 = 0;
        while (i < self.breakpoints_len) : (i += 1) {
            if (self.breakpoints[i].pc == pc) {
                self.breakpoints[i].enabled = true;
                return true;
            }
        }
        const idx = self.breakpoints_len;
        self.breakpoints[idx] = Breakpoint.init(pc);
        self.breakpoints_len += 1;
        return true;
    }

    pub fn remove_breakpoint(self: *VMDebugInterface, pc: u64) bool {
        var i: u32 = 0;
        while (i < self.breakpoints_len) : (i += 1) {
            if (self.breakpoints[i].pc == pc) {
                self.breakpoints[i].enabled = false;
                return true;
            }
        }
        return false;
    }

    pub fn check_breakpoint(self: *VMDebugInterface, pc: u64) bool {
        var i: u32 = 0;
        while (i < self.breakpoints_len) : (i += 1) {
            const bp = &self.breakpoints[i];
            if (bp.enabled and bp.pc == pc) {
                self.breakpoint_hit = true;
                self.last_breakpoint_pc = pc;
                return true;
            }
        }
        return false;
    }

    pub fn set_watchpoint(self: *VMDebugInterface, address: u64, size:
u64, watch_reads: bool, watch_writes: bool) bool {
        if (self.watchpoints_len >= MAX_WATCHPOINTS) {
            return false;
        }
        const idx = self.watchpoints_len;
        self.watchpoints[idx] = Watchpoint.init(address, size,
watch_reads, watch_writes);
        self.watchpoints_len += 1;
        return true;
    }

    pub fn remove_watchpoint(self: *VMDebugInterface, address: u64) bool
{
        var i: u32 = 0;
        while (i < self.watchpoints_len) : (i += 1) {
            if (self.watchpoints[i].address == address) {
                self.watchpoints[i].enabled = false;
                return true;
            }
        }
        return false;
    }

    pub fn check_watchpoint_read(self: *VMDebugInterface, address: u64,
size: u64) bool {
        var i: u32 = 0;
        while (i < self.watchpoints_len) : (i += 1) {
            const wp = &self.watchpoints[i];
            if (wp.enabled and wp.watch_reads) {
                if (address >= wp.address and address + size <=
wp.address + wp.size) {
                    self.watchpoint_triggered = true;
                    self.last_watchpoint_addr = address;
                    return true;
                }
            }
        }
        return false;
    }

    pub fn check_watchpoint_write(self: *VMDebugInterface, address: u64,
size: u64) bool {
        var i: u32 = 0;
        while (i < self.watchpoints_len) : (i += 1) {
            const wp = &self.watchpoints[i];
            if (wp.enabled and wp.watch_writes) {
                if (address >= wp.address and address + size <=
wp.address + wp.size) {
                    self.watchpoint_triggered = true;
                    self.last_watchpoint_addr = address;
                    return true;
                }
            }
        }
        return false;
    }

    pub fn enable_step_mode(self: *VMDebugInterface) void {
        self.step_mode = true;
    }

    pub fn disable_step_mode(self: *VMDebugInterface) void {
        self.step_mode = false;
    }

    pub fn clear_breakpoint_hit(self: *VMDebugInterface) void {
        self.breakpoint_hit = false;
    }

    pub fn clear_watchpoint_triggered(self: *VMDebugInterface) void {
        self.watchpoint_triggered = false;
    }
};


// === kernel_vm/error_log.zig ===

//! Error Logging System
//!
//! Objective: Structured error logging for VM and kernel operations.
//! Why: Track errors for debugging, monitoring, and recovery decisions.
//! GrainStyle: Static allocation, bounded buffers, explicit types,
deterministic logging.
//!
//! Methodology:
//! - Circular buffer for error logs (bounded, prevents memory growth)
//! - Structured error entries (timestamp, error type, message, context)
//! - Thread-safe logging (single-threaded VM, but prepare for future)
//! - Error statistics (count by type, recent errors)
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded buffers: fixed-size circular buffer (no dynamic allocation)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-01-XX
//! GrainStyle: Comprehensive error tracking, deterministic behavior,
explicit limits

const std = @import("std");

/// Maximum number of error log entries (bounded buffer).
/// Why: Prevent unbounded memory growth, limit log size for embedded
systems.
/// Note: 256 entries is sufficient for debugging, can be increased if
needed.
const MAX_ERROR_LOG_ENTRIES: u32 = 256;

/// Error log entry.
/// Why: Structured error information for debugging and monitoring.
/// GrainStyle: Explicit types, static allocation, deterministic
encoding.
pub const ErrorLogEntry = struct {
    /// Timestamp (monotonic nanoseconds since VM start).
    /// Why: Order errors chronologically, measure error rates.
    timestamp: u64,
    /// Error type (encoded as u32 for compact storage).
    /// Why: Categorize errors for statistics and filtering.
    error_type: u32,
    /// Error message (null-terminated string, max 64 bytes).
    /// Why: Human-readable error description.
    message: [64]u8,
    /// Message length (actual bytes used in message).
    /// Why: Avoid scanning for null terminator.
    message_len: u32,
    /// Context data (optional, for error-specific information).
    /// Why: Store additional error context (e.g., address, register
values).
    context: u64,
    
    /// Initialize error log entry.
    /// Why: Create structured error entry from error information.
    /// Contract: message must be non-empty, message_len must match
message length.
    pub fn init(timestamp: u64, error_type: u32, message: []const u8,
context: u64) ErrorLogEntry {
        // Assert: Message must be non-empty (precondition).
        std.debug.assert(message.len > 0);
        std.debug.assert(message.len <= 64);
        
        var entry = ErrorLogEntry{
            .timestamp = timestamp,
            .error_type = error_type,
            .message = [_]u8{0} ** 64,
            .message_len = 0,
            .context = context,
        };
        
        // Copy message (truncate if too long).
        const copy_len = @min(message.len, 63);
        @memcpy(entry.message[0..copy_len], message[0..copy_len]);
        entry.message[copy_len] = 0; // Null terminator.
        entry.message_len = @as(u32, @intCast(copy_len));
        
        // Assert: Message must be copied correctly (postcondition).
        std.debug.assert(entry.message_len <= 63);
        std.debug.assert(entry.message[entry.message_len] == 0);
        
        return entry;
    }
    
    /// Get error message as slice.
    /// Why: Return message without null terminator for display.
    pub fn get_message(self: *const ErrorLogEntry) []const u8 {
        return self.message[0..self.message_len];
    }
};

/// Error log (circular buffer).
/// Why: Track recent errors for debugging and monitoring.
/// GrainStyle: Static allocation, bounded buffer, deterministic
behavior.
pub const ErrorLog = struct {
    /// Error entries (circular buffer).
    entries: [MAX_ERROR_LOG_ENTRIES]ErrorLogEntry =
[_]ErrorLogEntry{undefined} ** MAX_ERROR_LOG_ENTRIES,
    /// Write index (next position to write).
    write_idx: u32 = 0,
    /// Number of entries written (for full buffer detection).
    entry_count: u32 = 0,
    /// Error statistics (count by type).
    /// Why: Track error frequency for monitoring and recovery decisions.
    stats: ErrorStats = .{},
    
    /// Error statistics.
    /// Why: Aggregate error information for monitoring.
    pub const ErrorStats = struct {
        /// Total error count.
        total_errors: u32 = 0,
        /// Error count by type (indexed by error_type).
        /// Note: Limited to 32 error types (can be expanded if needed).
        errors_by_type: [32]u32 = [_]u32{0} ** 32,
        
        /// Increment error count for type.
        /// Why: Track error frequency.
        pub fn increment(self: *ErrorStats, error_type: u32) void {
            self.total_errors += 1;
            if (error_type < 32) {
                self.errors_by_type[error_type] += 1;
            }
            
            // Assert: Statistics must be consistent (postcondition).
            std.debug.assert(self.total_errors > 0);
        }
        
        /// Get error count for type.
        /// Why: Query error frequency for specific type.
        pub fn get_count(self: *const ErrorStats, error_type: u32) u32 {
            if (error_type < 32) {
                return self.errors_by_type[error_type];
            }
            return 0;
        }
    };
    
    /// Log error entry.
    /// Why: Record error for debugging and monitoring.
    /// Contract: timestamp must be monotonic, error_type must be valid.
    pub fn log(self: *ErrorLog, timestamp: u64, error_type: u32,
message: []const u8, context: u64) void {
        // Assert: Message must be non-empty (precondition).
        std.debug.assert(message.len > 0);
        std.debug.assert(message.len <= 64);
        
        // Create error entry.
        const entry = ErrorLogEntry.init(timestamp, error_type, message,
context);
        
        // Write to circular buffer.
        self.entries[self.write_idx] = entry;
        self.write_idx = (self.write_idx + 1) % MAX_ERROR_LOG_ENTRIES;
        
        // Update entry count (saturate at MAX_ERROR_LOG_ENTRIES).
        if (self.entry_count < MAX_ERROR_LOG_ENTRIES) {
            self.entry_count += 1;
        }
        
        // Update statistics.
        self.stats.increment(error_type);
        
        // Assert: Write index must be valid (postcondition).
        std.debug.assert(self.write_idx < MAX_ERROR_LOG_ENTRIES);
        std.debug.assert(self.entry_count <= MAX_ERROR_LOG_ENTRIES);
    }
    
    /// Get recent errors (last N entries).
    /// Why: Retrieve recent errors for debugging and display.
    /// Contract: count must be <= MAX_ERROR_LOG_ENTRIES.
    /// Returns: Slice of error entries (most recent first).
    pub fn get_recent(self: *const ErrorLog, count: u32, buffer:
[]ErrorLogEntry) []ErrorLogEntry {
        // Assert: Count must be valid (precondition).
        std.debug.assert(count <= MAX_ERROR_LOG_ENTRIES);
        std.debug.assert(count <= buffer.len);
        
        const actual_count = @min(count, self.entry_count);
        if (actual_count == 0) {
            return buffer[0..0];
        }
        
        // Copy entries in reverse order (most recent first).
        var i: u32 = 0;
        var read_idx: u32 = if (self.entry_count >=
MAX_ERROR_LOG_ENTRIES)
            self.write_idx
        else
            0;
        
        // Start from most recent entry and work backwards.
        while (i < actual_count) : (i += 1) {
            const idx = if (read_idx == 0)
                MAX_ERROR_LOG_ENTRIES - 1
            else
                read_idx - 1;
            
            buffer[i] = self.entries[idx];
            read_idx = idx;
        }
        
        // Assert: Returned count must match actual count
(postcondition).
        std.debug.assert(i == actual_count);
        
        return buffer[0..actual_count];
    }
    
    /// Clear error log.
    /// Why: Reset error log for testing or after recovery.
    pub fn clear(self: *ErrorLog) void {
        self.write_idx = 0;
        self.entry_count = 0;
        self.stats = .{};
        
        // Assert: Log must be cleared (postcondition).
        std.debug.assert(self.write_idx == 0);
        std.debug.assert(self.entry_count == 0);
        std.debug.assert(self.stats.total_errors == 0);
    }
    
    /// Get error statistics.
    /// Why: Query error statistics for monitoring.
    pub fn get_stats(self: *const ErrorLog) ErrorStats {
        return self.stats;
    }
};

/// Error type constants (for error_type field).
/// Why: Standardize error type encoding for statistics and filtering.
pub const ErrorType = enum(u32) {
    /// Invalid instruction.
    invalid_instruction = 0,
    /// Invalid memory access.
    invalid_memory_access = 1,
    /// Unaligned memory access.
    unaligned_access = 2,
    /// Syscall error.
    syscall_error = 3,
    /// JIT compilation error.
    jit_error = 4,
    /// Integration error.
    integration_error = 5,
    /// Unknown error.
    unknown = 31,
};


// === kernel_vm/exception_stats.zig ===

//! Exception Statistics Tracking System
//!
//! Objective: Track exception counts by type for debugging and
monitoring.
//! Why: Monitor exception frequency, identify problematic code
patterns, and validate exception handling.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track exception counts by type (illegal instruction, misaligned
access, etc.)
//! - Track total exception count
//! - Provide statistics interface for querying exception data
//! - Reset capability for new measurement periods
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-01-XX
//! GrainStyle: Comprehensive exception tracking, deterministic
behavior, explicit limits

const std = @import("std");

/// Maximum number of exception types (RISC-V has 16 exception codes).
/// Why: Bounded array size for exception counters.
const MAX_EXCEPTION_TYPES: u32 = 16;

/// Exception statistics tracker.
/// Why: Track exception counts by type for debugging and monitoring.
/// GrainStyle: Explicit types, bounded counters, deterministic tracking.
pub const ExceptionStats = struct {
    /// Exception counts by type (indexed by exception code).
    /// Why: Track how many times each exception type occurs.
    exception_counts: [MAX_EXCEPTION_TYPES]u64 = [_]u64{0} **
MAX_EXCEPTION_TYPES,
    
    /// Total exception count (sum of all exception types).
    /// Why: Quick access to total exception count.
    total_count: u64 = 0,
    
    /// Whether statistics tracker is initialized.
    /// Why: Track initialization state for safety.
    initialized: bool = false,
    
    /// Initialize exception statistics tracker.
    /// Why: Set up statistics tracker state.
    /// Contract: Must be called once before use.
    pub fn init() ExceptionStats {
        return ExceptionStats{
            .exception_counts = [_]u64{0} ** MAX_EXCEPTION_TYPES,
            .total_count = 0,
            .initialized = true,
        };
    }
    
    /// Record exception occurrence.
    /// Why: Track exception for statistics.
    /// Contract: Exception type must be valid (< 16).
    pub fn record_exception(self: *ExceptionStats, exception_type: u32)
void {
        // Assert: Statistics tracker must be initialized (precondition).
        std.debug.assert(self.initialized);
        
        // Assert: Exception type must be valid (precondition).
        std.debug.assert(exception_type < MAX_EXCEPTION_TYPES);
        
        // Increment exception count for this type.
        self.exception_counts[exception_type] += 1;
        self.total_count += 1;
        
        // Assert: Counters must be consistent (postcondition).
        std.debug.assert(self.exception_counts[exception_type] > 0);
        std.debug.assert(self.total_count > 0);
        std.debug.assert(self.total_count >=
self.exception_counts[exception_type]);
    }
    
    /// Get exception count for specific type.
    /// Why: Query exception frequency for specific exception type.
    /// Contract: Exception type must be valid (< 16).
    pub fn get_count(self: *const ExceptionStats, exception_type: u32)
u64 {
        // Assert: Statistics tracker must be initialized (precondition).
        std.debug.assert(self.initialized);
        
        // Assert: Exception type must be valid (precondition).
        std.debug.assert(exception_type < MAX_EXCEPTION_TYPES);
        
        const count = self.exception_counts[exception_type];
        
        // Assert: Count must be valid (postcondition).
        std.debug.assert(count <= self.total_count);
        
        return count;
    }
    
    /// Get total exception count.
    /// Why: Query total exception frequency.
    pub fn get_total_count(self: *const ExceptionStats) u64 {
        // Assert: Statistics tracker must be initialized (precondition).
        std.debug.assert(self.initialized);
        
        return self.total_count;
    }
    
    /// Get exception statistics summary.
    /// Why: Get complete exception statistics for analysis.
    pub fn get_summary(self: *const ExceptionStats) ExceptionSummary {
        // Assert: Statistics tracker must be initialized (precondition).
        std.debug.assert(self.initialized);
        
        var summary = ExceptionSummary{
            .total_count = self.total_count,
            .illegal_instruction = self.exception_counts[2], //
Exception code 2
            .load_address_misaligned = self.exception_counts[4], //
Exception code 4
            .store_address_misaligned = self.exception_counts[6], //
Exception code 6
            .load_access_fault = self.exception_counts[5], // Exception
code 5
            .store_access_fault = self.exception_counts[7], // Exception
code 7
            .instruction_access_fault = self.exception_counts[1], //
Exception code 1
            .instruction_address_misaligned = self.exception_counts[0],
// Exception code 0
            .environment_call = self.exception_counts[8] +
self.exception_counts[9], // Codes 8 and 9
            .page_faults = self.exception_counts[12] +
self.exception_counts[13] + self.exception_counts[15], // Codes 12, 13,
15
            .other = 0,
        };
        
        // Calculate "other" count (exceptions not in summary).
        var other_count: u64 = 0;
        for (0..MAX_EXCEPTION_TYPES) |i| {
            const exception_code = @as(u32, @intCast(i));
            if (exception_code != 0 and exception_code != 1 and
exception_code != 2 and
                exception_code != 4 and exception_code != 5 and
exception_code != 6 and
                exception_code != 7 and exception_code != 8 and
exception_code != 9 and
                exception_code != 12 and exception_code != 13 and
exception_code != 15) {
                other_count += self.exception_counts[i];
            }
        }
        summary.other = other_count;
        
        // Assert: Summary must be consistent (postcondition).
        const calculated_total = summary.illegal_instruction +
summary.load_address_misaligned +
            summary.store_address_misaligned + summary.load_access_fault
+
            summary.store_access_fault +
summary.instruction_access_fault +
            summary.instruction_address_misaligned +
summary.environment_call +
            summary.page_faults + summary.other;
        std.debug.assert(calculated_total == summary.total_count);
        
        return summary;
    }
    
    /// Reset all exception statistics.
    /// Why: Clear statistics for new measurement period.
    pub fn reset(self: *ExceptionStats) void {
        // Assert: Statistics tracker must be initialized (precondition).
        std.debug.assert(self.initialized);
        
        // Reset all counters.
        for (0..MAX_EXCEPTION_TYPES) |i| {
            self.exception_counts[i] = 0;
        }
        self.total_count = 0;
        
        // Assert: Statistics must be reset (postcondition).
        std.debug.assert(self.total_count == 0);
        for (0..MAX_EXCEPTION_TYPES) |i| {
            std.debug.assert(self.exception_counts[i] == 0);
        }
    }
    
    /// Print exception statistics summary.
    /// Why: Display statistics for debugging and monitoring.
    pub fn print_summary(self: *const ExceptionStats) void {
        // Assert: Statistics tracker must be initialized (precondition).
        std.debug.assert(self.initialized);
        
        const summary = self.get_summary();
        
        std.debug.print("=== Exception Statistics ===\n", .{});
        std.debug.print("Total exceptions: {}\n",
.{summary.total_count});
        std.debug.print("Illegal instruction: {}\n",
.{summary.illegal_instruction});
        std.debug.print("Load address misaligned: {}\n",
.{summary.load_address_misaligned});
        std.debug.print("Store address misaligned: {}\n",
.{summary.store_address_misaligned});
        std.debug.print("Load access fault: {}\n",
.{summary.load_access_fault});
        std.debug.print("Store access fault: {}\n",
.{summary.store_access_fault});
        std.debug.print("Instruction access fault: {}\n",
.{summary.instruction_access_fault});
        std.debug.print("Instruction address misaligned: {}\n",
.{summary.instruction_address_misaligned});
        std.debug.print("Environment calls: {}\n",
.{summary.environment_call});
        std.debug.print("Page faults: {}\n", .{summary.page_faults});
        std.debug.print("Other exceptions: {}\n", .{summary.other});
        std.debug.print("===========================\n", .{});
    }
};

/// Exception statistics summary.
/// Why: Structured summary of exception statistics for analysis.
/// GrainStyle: Explicit types, clear structure.
pub const ExceptionSummary = struct {
    /// Total exception count.
    total_count: u64,
    /// Illegal instruction exceptions (code 2).
    illegal_instruction: u64,
    /// Load address misaligned exceptions (code 4).
    load_address_misaligned: u64,
    /// Store address misaligned exceptions (code 6).
    store_address_misaligned: u64,
    /// Load access fault exceptions (code 5).
    load_access_fault: u64,
    /// Store access fault exceptions (code 7).
    store_access_fault: u64,
    /// Instruction access fault exceptions (code 1).
    instruction_access_fault: u64,
    /// Instruction address misaligned exceptions (code 0).
    instruction_address_misaligned: u64,
    /// Environment call exceptions (codes 8, 9).
    environment_call: u64,
    /// Page fault exceptions (codes 12, 13, 15).
    page_faults: u64,
    /// Other exceptions (not in above categories).
    other: u64,
};


// === kernel_vm/execution_control.zig ===

//! VM Execution Control System
//!
//! Objective: Provide execution control capabilities (continue, step
over, step into).
//! Why: Enable debugging tools to control VM execution flow when
breakpoints are hit.
//! GrainStyle: Static allocation, bounded tracking, explicit types,
deterministic control.
//!
//! Methodology:
//! - Continue execution (resume until next breakpoint)
//! - Step over (execute one instruction, skip function calls)
//! - Step into (execute one instruction, enter function calls)
//! - Execution state tracking (paused, running, stepping)
//! - Bounded call stack tracking (MAX_CALL_STACK: 64)
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded arrays: fixed-size call stack
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive execution control, deterministic behavior,
explicit limits

const std = @import("std");
const VM = @import("vm.zig").VM;
const VMError = @import("vm.zig").VM.VMError;

// Bounded: Maximum call stack depth for step over/into tracking.
pub const MAX_CALL_STACK: u32 = 64;

// Execution control state.
pub const ExecutionState = enum {
    running,
    paused,
    stepping_over,
    stepping_into,
};

// Call stack entry (for step over/into tracking).
pub const CallStackEntry = struct {
    pc: u64,
    return_pc: u64,

    pub fn init(pc: u64, return_pc: u64) CallStackEntry {
        return CallStackEntry{
            .pc = pc,
            .return_pc = return_pc,
        };
    }
};

// VM execution controller.
pub const VMExecutionController = struct {
    vm: *VM,
    state: ExecutionState,
    call_stack: [MAX_CALL_STACK]CallStackEntry,
    call_stack_len: u32,
    step_over_target_pc: u64,
    step_into_depth: u32,

    pub fn init(vm: *VM) VMExecutionController {
        var controller = VMExecutionController{
            .vm = vm,
            .state = .paused,
            .call_stack = undefined,
            .call_stack_len = 0,
            .step_over_target_pc = 0,
            .step_into_depth = 0,
        };
        var i: u32 = 0;
        while (i < MAX_CALL_STACK) : (i += 1) {
            controller.call_stack[i] = CallStackEntry.init(0, 0);
        }
        return controller;
    }

    pub fn continue_execution(self: *VMExecutionController) void {
        self.state = .running;
        self.call_stack_len = 0;
        self.step_over_target_pc = 0;
        self.step_into_depth = 0;
    }

    pub fn step_over(self: *VMExecutionController) void {
        self.state = .stepping_over;
        self.step_over_target_pc = self.vm.regs.pc;
        self.call_stack_len = 0;
        self.step_into_depth = 0;
    }

    pub fn step_into(self: *VMExecutionController) void {
        self.state = .stepping_into;
        self.step_into_depth = self.call_stack_len;
        self.step_over_target_pc = 0;
    }

    pub fn pause(self: *VMExecutionController) void {
        self.state = .paused;
    }

    pub fn should_continue(self: *const VMExecutionController) bool {
        return self.state == .running;
    }

    pub fn should_step(self: *const VMExecutionController) bool {
        return self.state == .stepping_over or self.state ==
.stepping_into;
    }

    pub fn execute_step(self: *VMExecutionController) VMError!bool {
        if (self.state == .paused) {
            return false;
        }
        if (self.state == .running) {
            try self.vm.step();
            return true;
        }
        if (self.state == .stepping_over) {
            try self.vm.step();
            const pc_after = self.vm.regs.pc;
            if (pc_after == self.step_over_target_pc + 4) {
                self.state = .paused;
                return false;
            }
            return true;
        }
        if (self.state == .stepping_into) {
            try self.vm.step();
            if (self.call_stack_len <= self.step_into_depth) {
                self.state = .paused;
                return false;
            }
            return true;
        }
        return false;
    }

    pub fn push_call_stack(self: *VMExecutionController, pc: u64,
return_pc: u64) bool {
        if (self.call_stack_len >= MAX_CALL_STACK) {
            return false;
        }
        const idx = self.call_stack_len;
        self.call_stack[idx] = CallStackEntry.init(pc, return_pc);
        self.call_stack_len += 1;
        return true;
    }

    pub fn pop_call_stack(self: *VMExecutionController) ?CallStackEntry {
        if (self.call_stack_len == 0) {
            return null;
        }
        self.call_stack_len -= 1;
        return self.call_stack[self.call_stack_len];
    }

    pub fn get_call_stack_depth(self: *const VMExecutionController) u32 {
        return self.call_stack_len;
    }
};


// === kernel_vm/execution_flow.zig ===

//! VM Execution Flow Tracking System
//!
//! Objective: Track program counter sequences to identify execution
patterns, loops, and control flow.
//! Why: Understand execution flow, detect loops, identify hot code
regions, optimize JIT compilation.
//! GrainStyle: Static allocation, bounded buffers, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track recent PC values (circular buffer)
//! - Detect loop patterns (repeated PC sequences)
//! - Track branch targets (PC transitions)
//! - Identify hot code regions (frequently executed PCs)
//! - Provide statistics interface for querying execution flow data
//! - Reset capability for new measurement periods
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded buffers: fixed-size circular buffers (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive execution flow tracking, deterministic
behavior, explicit limits

const std = @import("std");

// Bounded: Max PC history entries (circular buffer size).
pub const MAX_PC_HISTORY: u32 = 256;

// Bounded: Max unique PCs to track.
pub const MAX_UNIQUE_PCS: u32 = 128;

// PC execution entry: tracks execution count for a PC value.
pub const PCEntry = struct {
    pc: u64,
    execution_count: u64,

    pub fn init(pc: u64) PCEntry {
        return PCEntry{
            .pc = pc,
            .execution_count = 0,
        };
    }
};

// VM execution flow tracker.
pub const VMExecutionFlow = struct {
    pc_history: [MAX_PC_HISTORY]u64,
    pc_history_index: u32,
    pc_history_len: u32,
    unique_pcs: [MAX_UNIQUE_PCS]PCEntry,
    unique_pcs_len: u32,
    total_instructions: u64,

    pub fn init() VMExecutionFlow {
        var flow = VMExecutionFlow{
            .pc_history = undefined,
            .pc_history_index = 0,
            .pc_history_len = 0,
            .unique_pcs = undefined,
            .unique_pcs_len = 0,
            .total_instructions = 0,
        };
        var i: u32 = 0;
        while (i < MAX_UNIQUE_PCS) : (i += 1) {
            flow.unique_pcs[i] = PCEntry.init(0);
        }
        return flow;
    }

    fn find_or_add_pc(self: *VMExecutionFlow, pc: u64) ?u32 {
        // Find existing PC entry.
        var i: u32 = 0;
        while (i < self.unique_pcs_len) : (i += 1) {
            if (self.unique_pcs[i].pc == pc) {
                return i;
            }
        }
        // Add new PC entry if space available.
        if (self.unique_pcs_len >= MAX_UNIQUE_PCS) {
            return null;
        }
        const idx = self.unique_pcs_len;
        self.unique_pcs[idx] = PCEntry.init(pc);
        self.unique_pcs_len += 1;
        return idx;
    }

    pub fn record_pc(self: *VMExecutionFlow, pc: u64) void {
        self.total_instructions += 1;
        
        // Add to circular buffer.
        self.pc_history[self.pc_history_index] = pc;
        self.pc_history_index = (self.pc_history_index + 1) %
MAX_PC_HISTORY;
        if (self.pc_history_len < MAX_PC_HISTORY) {
            self.pc_history_len += 1;
        }
        
        // Track unique PCs.
        if (self.find_or_add_pc(pc)) |idx| {
            self.unique_pcs[idx].execution_count += 1;
        }
    }

    fn detect_loop_pattern(self: *const VMExecutionFlow) ?u64 {
        // Detect simple loop: same PC repeated multiple times.
        if (self.pc_history_len < 4) {
            return null;
        }
        const last_pc = self.pc_history[(self.pc_history_index +
MAX_PC_HISTORY - 1) % MAX_PC_HISTORY];
        var repeat_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.pc_history_len and i < 16) : (i += 1) {
            const idx = (self.pc_history_index + MAX_PC_HISTORY - 1 - i)
% MAX_PC_HISTORY;
            if (self.pc_history[idx] == last_pc) {
                repeat_count += 1;
            } else {
                break;
            }
        }
        if (repeat_count >= 4) {
            return last_pc;
        }
        return null;
    }

    fn print_top_pcs(self: *const VMExecutionFlow) void {
        if (self.total_instructions == 0 or self.unique_pcs_len == 0) {
            return;
        }
        std.debug.print("  Top PCs:\n", .{});
        var top_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.unique_pcs_len and top_count < 10) : (i += 1) {
            const entry = self.unique_pcs[i];
            if (entry.execution_count > 0) {
                const percentage = @as(f64,
@floatFromInt(entry.execution_count)) /
                    @as(f64, @floatFromInt(self.total_instructions)) *
100.0;
                std.debug.print("    0x{x}: {} ({d:.2}%)\n", .{
                    entry.pc,
                    entry.execution_count,
                    percentage,
                });
                top_count += 1;
            }
        }
    }

    pub fn print_stats(self: *const VMExecutionFlow) void {
        std.debug.print("\nVM Execution Flow Statistics:\n", .{});
        std.debug.print("  Total Instructions: {}\n",
.{self.total_instructions});
        std.debug.print("  Unique PCs: {}\n", .{self.unique_pcs_len});
        std.debug.print("  PC History Length: {}\n",
.{self.pc_history_len});
        if (self.detect_loop_pattern()) |loop_pc| {
            std.debug.print("  Detected Loop: 0x{x}\n", .{loop_pc});
        }
        self.print_top_pcs();
    }

    pub fn reset(self: *VMExecutionFlow) void {
        self.total_instructions = 0;
        self.pc_history_index = 0;
        self.pc_history_len = 0;
        var i: u32 = 0;
        while (i < self.unique_pcs_len) : (i += 1) {
            self.unique_pcs[i].execution_count = 0;
        }
        self.unique_pcs_len = 0;
    }
};


// === kernel_vm/instruction_perf.zig ===

//! VM Instruction Performance Profiling System
//!
//! Objective: Track execution time per instruction type for performance
analysis.
//! Why: Identify slow instruction types, optimize hot paths, measure
JIT effectiveness.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track total execution time per opcode
//! - Track execution count per opcode
//! - Calculate average execution time per instruction type
//! - Track total profiling time
//! - Provide statistics interface for querying performance data
//! - Reset capability for new measurement periods
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive performance profiling, deterministic
behavior, explicit limits

const std = @import("std");

// Bounded: Maximum number of opcodes to track (RISC-V has ~50 base
opcodes).
pub const MAX_OPCODES: u32 = 64;

// Instruction performance entry: tracks execution time and count for an
opcode.
pub const InstructionPerfEntry = struct {
    opcode: u32,
    total_time_ns: u64,
    execution_count: u64,

    pub fn init(opcode: u32) InstructionPerfEntry {
        std.debug.assert(opcode < MAX_OPCODES);
        return InstructionPerfEntry{
            .opcode = opcode,
            .total_time_ns = 0,
            .execution_count = 0,
        };
    }

    fn get_avg_time_ns(self: *const InstructionPerfEntry) u64 {
        if (self.execution_count == 0) {
            return 0;
        }
        return self.total_time_ns / self.execution_count;
    }
};

// VM instruction performance profiler.
pub const VMInstructionPerf = struct {
    entries: [MAX_OPCODES]InstructionPerfEntry,
    entries_len: u32,
    total_profiling_time_ns: u64,

    pub fn init() VMInstructionPerf {
        var perf = VMInstructionPerf{
            .entries = undefined,
            .entries_len = 0,
            .total_profiling_time_ns = 0,
        };
        var i: u32 = 0;
        while (i < MAX_OPCODES) : (i += 1) {
            perf.entries[i] = InstructionPerfEntry.init(i);
        }
        return perf;
    }

    fn find_or_add_entry(self: *VMInstructionPerf, opcode: u32)
*InstructionPerfEntry {
        std.debug.assert(opcode < MAX_OPCODES);
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].opcode == opcode) {
                return &self.entries[i];
            }
        }
        if (self.entries_len < MAX_OPCODES) {
            const idx = self.entries_len;
            self.entries[idx] = InstructionPerfEntry.init(opcode);
            self.entries_len += 1;
            return &self.entries[idx];
        }
        return &self.entries[0];
    }

    pub fn record_execution(self: *VMInstructionPerf, opcode: u32,
time_ns: u64) void {
        std.debug.assert(opcode < MAX_OPCODES);
        const entry = self.find_or_add_entry(opcode);
        entry.total_time_ns += time_ns;
        entry.execution_count += 1;
        self.total_profiling_time_ns += time_ns;
    }

    fn print_top_instructions(self: *const VMInstructionPerf) void {
        if (self.entries_len == 0) {
            return;
        }
        std.debug.print("  Top Instructions by Time:\n", .{});
        var top_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.entries_len and top_count < 10) : (i += 1) {
            const entry = &self.entries[i];
            if (entry.execution_count > 0) {
                const avg_time = entry.get_avg_time_ns();
                const percentage = if (self.total_profiling_time_ns > 0)
                    @as(f64, @floatFromInt(entry.total_time_ns)) /
                        @as(f64,
@floatFromInt(self.total_profiling_time_ns)) * 100.0
                else
                    0.0;
                std.debug.print("    Opcode {}: {} execs, {}ns total,
{}ns avg ({d:.2}%)\n", .{
                    entry.opcode,
                    entry.execution_count,
                    entry.total_time_ns,
                    avg_time,
                    percentage,
                });
                top_count += 1;
            }
        }
    }

    pub fn print_stats(self: *const VMInstructionPerf) void {
        std.debug.print("\nVM Instruction Performance:\n", .{});
        std.debug.print("  Total Profiling Time: {}ns\n",
.{self.total_profiling_time_ns});
        std.debug.print("  Unique Opcodes: {}\n", .{self.entries_len});
        self.print_top_instructions();
    }

    pub fn reset(self: *VMInstructionPerf) void {
        self.entries_len = 0;
        self.total_profiling_time_ns = 0;
        var i: u32 = 0;
        while (i < MAX_OPCODES) : (i += 1) {
            self.entries[i].total_time_ns = 0;
            self.entries[i].execution_count = 0;
        }
    }
};


// === kernel_vm/instruction_stats.zig ===

//! VM Instruction Execution Statistics Tracking System
//!
//! Objective: Track instruction execution frequency and patterns for VM
monitoring.
//! Why: Monitor which instructions are executed most, identify
execution patterns.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track execution count per instruction opcode
//! - Track total instructions executed
//! - Track instruction categories (arithmetic, memory, control flow)
//! - Provide statistics interface for querying instruction data
//! - Reset capability for new measurement periods
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive instruction tracking, deterministic
behavior, explicit limits

const std = @import("std");

// Bounded: Max instruction opcodes to track (RISC-V has ~100 opcodes).
pub const MAX_OPCODES: u32 = 128;

// Instruction category enumeration.
pub const InstructionCategory = enum(u8) {
    arithmetic = 0,
    memory = 1,
    control_flow = 2,
    system = 3,
    other = 4,
};

// Instruction execution entry: tracks execution count for an opcode.
pub const InstructionEntry = struct {
    opcode: u32,
    execution_count: u64,
    category: InstructionCategory,

    pub fn init(opcode: u32, category: InstructionCategory)
InstructionEntry {
        std.debug.assert(opcode < 256);
        return InstructionEntry{
            .opcode = opcode,
            .execution_count = 0,
            .category = category,
        };
    }
};

// VM instruction statistics tracker.
pub const VMInstructionStats = struct {
    entries: [MAX_OPCODES]InstructionEntry,
    entries_len: u32,
    total_instructions: u64,

    pub fn init() VMInstructionStats {
        var stats = VMInstructionStats{
            .entries = undefined,
            .entries_len = 0,
            .total_instructions = 0,
        };
        var i: u32 = 0;
        while (i < MAX_OPCODES) : (i += 1) {
            stats.entries[i] = InstructionEntry.init(0, .other);
        }
        return stats;
    }

    fn get_category_for_opcode(opcode: u32) InstructionCategory {
        // Categorize RISC-V opcodes.
        const opcode_low = opcode & 0x7F;
        switch (opcode_low) {
            0x33, 0x3B, 0x13, 0x1B => return .arithmetic, // R/I-type
arithmetic
            0x03, 0x23 => return .memory, // Load/Store
            0x63, 0x6F, 0x67 => return .control_flow, // Branch/Jump
            0x73 => return .system, // System/ECALL
            else => return .other,
        }
    }

    fn find_or_add_entry(self: *VMInstructionStats, opcode: u32) ?u32 {
        std.debug.assert(opcode < 256);
        // Find existing entry.
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].opcode == opcode) {
                return i;
            }
        }
        // Add new entry if space available.
        if (self.entries_len >= MAX_OPCODES) {
            return null;
        }
        const idx = self.entries_len;
        const category = get_category_for_opcode(opcode);
        self.entries[idx] = InstructionEntry.init(opcode, category);
        self.entries_len += 1;
        return idx;
    }

    pub fn record_instruction(self: *VMInstructionStats, opcode: u32)
void {
        std.debug.assert(opcode < 256);
        self.total_instructions += 1;
        if (self.find_or_add_entry(opcode)) |idx| {
            self.entries[idx].execution_count += 1;
        }
    }

    fn get_category_string(category: InstructionCategory) []const u8 {
        return switch (category) {
            .arithmetic => "arithmetic",
            .memory => "memory",
            .control_flow => "control_flow",
            .system => "system",
            .other => "other",
        };
    }

    fn print_top_instructions(self: *const VMInstructionStats) void {
        if (self.total_instructions == 0 or self.entries_len == 0) {
            return;
        }
        std.debug.print("  Top Instructions:\n", .{});
        var top_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.entries_len and top_count < 10) : (i += 1) {
            const entry = self.entries[i];
            if (entry.execution_count > 0) {
                const percentage = @as(f64,
@floatFromInt(entry.execution_count)) /
                    @as(f64, @floatFromInt(self.total_instructions)) *
100.0;
                const category_str = get_category_string(entry.category);
                std.debug.print("    0x{x:02X}: {} ({d:.2}%) [{}]\n", .{
                    entry.opcode,
                    entry.execution_count,
                    percentage,
                    category_str,
                });
                top_count += 1;
            }
        }
    }

    pub fn print_stats(self: *const VMInstructionStats) void {
        std.debug.print("\nVM Instruction Statistics:\n", .{});
        std.debug.print("  Total Instructions: {}\n",
.{self.total_instructions});
        std.debug.print("  Unique Opcodes: {}\n", .{self.entries_len});
        self.print_top_instructions();
    }

    pub fn reset(self: *VMInstructionStats) void {
        self.total_instructions = 0;
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            self.entries[i].execution_count = 0;
        }
    }
};


// === kernel_vm/instruction_trace.zig ===

//! VM Instruction Trace Logging System
//!
//! Objective: Provide instruction trace logging for debugging (history
of executed instructions).
//! Why: Enable debugging tools to see a history of executed
instructions for debugging.
//! GrainStyle: Static allocation, bounded circular buffer, explicit
types, deterministic logging.
//!
//! Methodology:
//! - Instruction trace logging (record PC, instruction, registers,
memory accesses)
//! - Circular buffer (bounded trace history, MAX_TRACE_ENTRIES: 1024)
//! - Trace entry format (PC, instruction, register state, memory access)
//! - Trace filtering (enable/disable tracing, filter by PC range)
//! - Trace export (dump trace to buffer for analysis)
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded buffers: fixed-size circular trace buffer
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-25
//! GrainStyle: Comprehensive instruction trace logging, deterministic
behavior, explicit limits

const std = @import("std");
const VM = @import("vm.zig").VM;

// Bounded: Maximum trace entries in circular buffer (sufficient for
debugging).
pub const MAX_TRACE_ENTRIES: u32 = 1024;

// Trace entry: records instruction execution details.
pub const TraceEntry = struct {
    pc: u64,
    instruction: u32,
    regs: [32]u64,
    memory_read_addr: ?u64,
    memory_write_addr: ?u64,
    memory_read_value: ?u64,
    memory_write_value: ?u64,

    pub fn init() TraceEntry {
        return TraceEntry{
            .pc = 0,
            .instruction = 0,
            .regs = [_]u64{0} ** 32,
            .memory_read_addr = null,
            .memory_write_addr = null,
            .memory_read_value = null,
            .memory_write_value = null,
        };
    }
};

// VM instruction trace logger.
pub const VMInstructionTrace = struct {
    trace_buffer: [MAX_TRACE_ENTRIES]TraceEntry,
    trace_index: u32,
    trace_count: u32,
    enabled: bool,
    filter_pc_min: ?u64,
    filter_pc_max: ?u64,

    pub fn init() VMInstructionTrace {
        var trace = VMInstructionTrace{
            .trace_buffer = undefined,
            .trace_index = 0,
            .trace_count = 0,
            .enabled = false,
            .filter_pc_min = null,
            .filter_pc_max = null,
        };
        var i: u32 = 0;
        while (i < MAX_TRACE_ENTRIES) : (i += 1) {
            trace.trace_buffer[i] = TraceEntry.init();
        }
        return trace;
    }

    pub fn enable(self: *VMInstructionTrace) void {
        self.enabled = true;
    }

    pub fn disable(self: *VMInstructionTrace) void {
        self.enabled = false;
    }

    pub fn set_filter(self: *VMInstructionTrace, pc_min: ?u64, pc_max:
?u64) void {
        self.filter_pc_min = pc_min;
        self.filter_pc_max = pc_max;
    }

    pub fn clear_filter(self: *VMInstructionTrace) void {
        self.filter_pc_min = null;
        self.filter_pc_max = null;
    }

    pub fn should_trace(self: *const VMInstructionTrace, pc: u64) bool {
        if (!self.enabled) {
            return false;
        }
        if (self.filter_pc_min) |min| {
            if (pc < min) {
                return false;
            }
        }
        if (self.filter_pc_max) |max| {
            if (pc > max) {
                return false;
            }
        }
        return true;
    }

    pub fn record_instruction(self: *VMInstructionTrace, vm: *VM, pc:
u64, instruction: u32) void {
        if (!self.should_trace(pc)) {
            return;
        }
        const idx = self.trace_index;
        var entry = &self.trace_buffer[idx];
        entry.pc = pc;
        entry.instruction = instruction;
        var i: u32 = 0;
        while (i < 32) : (i += 1) {
            entry.regs[i] = vm.regs.get(@as(u5, @intCast(i)));
        }
        entry.memory_read_addr = null;
        entry.memory_write_addr = null;
        entry.memory_read_value = null;
        entry.memory_write_value = null;
        self.trace_index = (self.trace_index + 1) % MAX_TRACE_ENTRIES;
        if (self.trace_count < MAX_TRACE_ENTRIES) {
            self.trace_count += 1;
        }
    }

    pub fn record_memory_read(self: *VMInstructionTrace, address: u64,
value: u64) void {
        if (!self.enabled) {
            return;
        }
        if (self.trace_count == 0) {
            return;
        }
        const prev_idx = if (self.trace_index == 0) MAX_TRACE_ENTRIES -
1 else self.trace_index - 1;
        var entry = &self.trace_buffer[prev_idx];
        entry.memory_read_addr = address;
        entry.memory_read_value = value;
    }

    pub fn record_memory_write(self: *VMInstructionTrace, address: u64,
value: u64) void {
        if (!self.enabled) {
            return;
        }
        if (self.trace_count == 0) {
            return;
        }
        const prev_idx = if (self.trace_index == 0) MAX_TRACE_ENTRIES -
1 else self.trace_index - 1;
        var entry = &self.trace_buffer[prev_idx];
        entry.memory_write_addr = address;
        entry.memory_write_value = value;
    }

    pub fn get_trace_count(self: *const VMInstructionTrace) u32 {
        return self.trace_count;
    }

    pub fn get_trace_entry(self: *const VMInstructionTrace, index: u32)
?*const TraceEntry {
        if (index >= self.trace_count) {
            return null;
        }
        const start_idx = if (self.trace_count < MAX_TRACE_ENTRIES) 0
else self.trace_index;
        const actual_idx = (start_idx + index) % MAX_TRACE_ENTRIES;
        return &self.trace_buffer[actual_idx];
    }

    pub fn clear_trace(self: *VMInstructionTrace) void {
        self.trace_index = 0;
        self.trace_count = 0;
    }

    pub fn print_trace(self: *const VMInstructionTrace, max_entries:
u32) void {
        const count = if (max_entries > self.trace_count)
self.trace_count else max_entries;
        std.debug.print("\nInstruction Trace ({} entries):\n", .{count});
        var i: u32 = 0;
        while (i < count) : (i += 1) {
            const entry_opt = self.get_trace_entry(i);
            if (entry_opt) |entry| {
                std.debug.print("  [{:4}] PC: 0x{x}, Inst: 0x{x}", .{ i,
entry.pc, entry.instruction });
                if (entry.memory_read_addr) |addr| {
                    std.debug.print(", Read: 0x{x} = 0x{x}", .{ addr,
entry.memory_read_value.? });
                }
                if (entry.memory_write_addr) |addr| {
                    std.debug.print(", Write: 0x{x} = 0x{x}", .{ addr,
entry.memory_write_value.? });
                }
                std.debug.print("\n", .{});
            }
        }
    }
};


// === kernel_vm/integration.zig ===

//! VM-Kernel Integration Layer
//! Why: Bridge VM syscall interface (u64 return) with kernel syscall
interface (SyscallResult).
//! Grain Style: Comprehensive contracts, explicit types, input/output
validation.

const std = @import("std");
const VM = @import("vm.zig").VM;
const basin_kernel = @import("basin_kernel");
const BasinKernel = basin_kernel.BasinKernel;
const BasinError = basin_kernel.BasinError;
const SyscallResult = basin_kernel.SyscallResult;
const ProcessContext = basin_kernel.ProcessContext;
const process_execution = basin_kernel.process_execution;
const loadKernel = @import("loader.zig").loadKernel;

/// Module-level kernel pointer for syscall handler access.
/// Why: VM syscall handler interface doesn't support closures, so we
use module-level storage.
/// Contract: Must be set before syscall_handler_wrapper is called (set
by Integration.finish_init).
/// Note: Safe for single-threaded execution only.
var global_kernel_ptr: ?*BasinKernel = null;

/// Module-level VM pointer for input event access.
/// Why: Input event syscall needs VM access, but kernel doesn't have VM
reference.
/// Contract: Must be set before syscall_handler_wrapper is called (set
by Integration.finish_init).
/// Note: Safe for single-threaded execution only.
var global_vm_ptr: ?*VM = null;

/// VM memory reader wrapper (called by kernel to read VM memory).
/// Why: Bridge kernel memory read interface with VM memory access.
/// Contract: global_vm_ptr must be set before this is called.
/// Returns: Number of bytes read, or null if read fails.
/// Grain Style: Explicit types, bounded operations, static allocation.
fn vm_memory_reader_wrapper(addr: u64, len: u32, buffer: []u8) ?u32 {
    // Contract: global_vm_ptr must be set (precondition).
    const vm = global_vm_ptr orelse {
        return null; // VM not initialized
    };
    
    // Contract: VM must be initialized.
    const vm_addr = @intFromPtr(vm);
    std.debug.assert(vm_addr != 0);
    std.debug.assert(vm_addr % @alignOf(VM) == 0);
    
    // Contract: Address and length must be valid.
    const VM_MEMORY_SIZE: u64 = 4 * 1024 * 1024; // 4MB default
    if (addr >= VM_MEMORY_SIZE) {
        return null; // Invalid address
    }
    if (len == 0) {
        return null; // Invalid length
    }
    if (addr + @as(u64, len) > VM_MEMORY_SIZE) {
        return null; // Address + length exceeds VM memory
    }
    
    // Contract: Buffer must be large enough.
    if (buffer.len < len) {
        return null; // Buffer too small
    }
    
    // Read memory from VM (use translate_address to handle address
translation).
    // Why: VM memory uses address translation, need to translate
virtual to physical.
    const read_len = @as(u64, len);
    var i: u64 = 0;
    while (i < read_len) : (i += 1) {
        const virt_addr = addr + i;
        const phys_offset = vm.translate_address(virt_addr) orelse {
            return null; // Address not mapped
        };
        
        // Contract: Physical offset must be within VM memory bounds.
        if (phys_offset >= vm.memory_size) {
            return null; // Invalid physical offset
        }
        
        // Read byte from VM memory.
        buffer[@intCast(i)] = vm.memory[@intCast(phys_offset)];
    }
    
    // Assert: All bytes must be read (postcondition).
    std.debug.assert(i == read_len);
    
    return @as(u32, @intCast(len));
}

/// VM memory writer wrapper (called by kernel to write VM memory).
/// Why: Bridge kernel memory write interface with VM memory access.
/// Contract: global_vm_ptr must be set before this is called.
/// Returns: Number of bytes written, or null if write fails.
/// Grain Style: Explicit types, bounded operations, static allocation.
fn vm_memory_writer_wrapper(addr: u64, len: u32, data: []const u8) ?u32 {
    // Contract: global_vm_ptr must be set (precondition).
    const vm = global_vm_ptr orelse {
        return null; // VM not initialized
    };
    
    // Contract: VM must be initialized.
    const vm_addr = @intFromPtr(vm);
    std.debug.assert(vm_addr != 0);
    std.debug.assert(vm_addr % @alignOf(VM) == 0);
    
    // Contract: Address and length must be valid.
    const VM_MEMORY_SIZE: u64 = 4 * 1024 * 1024; // 4MB default
    if (addr >= VM_MEMORY_SIZE) {
        return null; // Invalid address
    }
    if (len == 0) {
        return null; // Invalid length
    }
    if (addr + @as(u64, len) > VM_MEMORY_SIZE) {
        return null; // Address + length exceeds VM memory
    }
    
    // Contract: Data buffer must be large enough.
    if (data.len < len) {
        return null; // Data buffer too small
    }
    
    // Write memory to VM (use translate_address to handle address
translation).
    // Why: VM memory uses address translation, need to translate
virtual to physical.
    const write_len = @as(u64, len);
    var i: u64 = 0;
    while (i < write_len) : (i += 1) {
        const virt_addr = addr + i;
        const phys_offset = vm.translate_address(virt_addr) orelse {
            return null; // Address not mapped
        };
        
        // Contract: Physical offset must be within VM memory bounds.
        if (phys_offset >= vm.memory_size) {
            return null; // Invalid physical offset
        }
        
        // Write byte to VM memory.
        vm.memory[@intCast(phys_offset)] = data[@intCast(i)];
    }
    
    // Assert: All bytes must be written (postcondition).
    std.debug.assert(i == write_len);
    
    return @as(u32, @intCast(len));
}

/// Read VM memory buffer (helper for kernel syscalls that need VM
memory access).
/// Why: Kernel syscalls (like spawn) need to read VM memory but kernel
doesn't have VM reference.
/// Contract: global_vm_ptr must be set, addr and len must be valid,
buffer must be large enough.
/// Returns: Number of bytes read, or error if read fails.
/// Grain Style: Explicit types, bounded operations, static allocation.
fn read_vm_memory(addr: u64, len: u32, buffer: []u8) !u32 {
    // Contract: global_vm_ptr must be set (precondition).
    const vm = global_vm_ptr orelse {
        return error.VmNotInitialized;
    };
    
    // Contract: VM must be initialized.
    const vm_addr = @intFromPtr(vm);
    std.debug.assert(vm_addr != 0);
    std.debug.assert(vm_addr % @alignOf(VM) == 0);
    
    // Contract: Address and length must be valid.
    const VM_MEMORY_SIZE: u64 = 4 * 1024 * 1024; // 4MB default
    if (addr >= VM_MEMORY_SIZE) {
        return error.InvalidAddress;
    }
    if (len == 0) {
        return error.InvalidLength;
    }
    if (addr + @as(u64, len) > VM_MEMORY_SIZE) {
        return error.InvalidAddress;
    }
    
    // Contract: Buffer must be large enough.
    if (buffer.len < len) {
        return error.BufferTooSmall;
    }
    
    // Read memory from VM (use translate_address to handle address
translation).
    // Why: VM memory uses address translation, need to translate
virtual to physical.
    const read_len = @as(u64, len);
    var i: u64 = 0;
    while (i < read_len) : (i += 1) {
        const virt_addr = addr + i;
        const phys_offset = vm.translate_address(virt_addr) orelse {
            return error.InvalidAddress; // Address not mapped
        };
        
        // Contract: Physical offset must be within VM memory bounds.
        if (phys_offset >= vm.memory_size) {
            return error.InvalidAddress;
        }
        
        // Read byte from VM memory.
        buffer[@intCast(i)] = vm.memory[@intCast(phys_offset)];
    }
    
    // Assert: All bytes must be read (postcondition).
    std.debug.assert(i == read_len);
    
    return @as(u32, @intCast(len));
}

/// Permission checker wrapper (called by VM to check memory
permissions).
/// Why: Bridge VM permission check interface with kernel permission
check function.
/// Contract: global_kernel_ptr must be set before this is called.
/// Returns: u32 with permission bits (bit 0=read, bit 1=write, bit
2=execute), or 0 if not mapped.
fn permission_checker_wrapper(addr: u64) u32 {
    // Contract: global_kernel_ptr must be set (precondition).
    const kernel = global_kernel_ptr orelse {
        // No kernel: allow all access (backward compatibility).
        return 0b111; // read, write, execute
    };
    
    // Check memory permissions via kernel.
    const permissions = kernel.check_memory_permission(addr);
    
    if (permissions) |flags| {
        // Convert MapFlags to permission bits.
        var result: u32 = 0;
        if (flags.read) result |= 1; // bit 0 = read
        if (flags.write) result |= 2; // bit 1 = write
        if (flags.execute) result |= 4; // bit 2 = execute
        return result;
    } else {
        // Address not mapped: return 0 (no permissions).
        return 0;
    }
}

/// VM-Kernel integration state.
/// Why: Encapsulate VM and kernel instances, manage lifecycle.
/// Grain Style: Static allocation, explicit state tracking.
/// Note: Stores VM and kernel pointers instead of values to avoid
copying large structs (stack overflow prevention).
pub const Integration = struct {
    /// VM instance pointer (RISC-V64 emulator).
    /// Why: Store pointer instead of value to avoid copying 4MB struct.
    vm: *VM,
    /// Kernel instance pointer (Grain Basin kernel).
    /// Why: Store pointer instead of value to avoid copying ~75KB
struct (users array).
    kernel: *BasinKernel,
    /// Whether integration is initialized.
    initialized: bool,

    const Self = @This();

    /// Initialize integration with kernel ELF.
    /// Contract:
    ///   Input: vm_ptr must point to uninitialized VM struct, elf_data
must be non-empty, valid RISC-V64 ELF
    ///   Output: Initialized Integration instance, VM PC set to entry
point
    ///   Errors: Invalid ELF format, memory allocation failure
    /// Why: Load kernel into VM, initialize kernel state.
    /// Note: Returns uninitialized Self, caller must call finish_init()
to complete setup.
    /// Note: Caller must ensure vm_ptr lives for the lifetime of
Integration.
    /// GrainStyle: In-place initialization pattern - caller provides
storage.
    pub fn init(vm_ptr: *VM, elf_data: []const u8) !Self {
        // Contract: ELF data must be non-empty.
        if (elf_data.len == 0) {
            return error.EmptyElfData;
        }

        // Contract: ELF data must be large enough for ELF header (64
bytes minimum).
        const MIN_ELF_HEADER_SIZE: u32 = 64;
        if (elf_data.len < MIN_ELF_HEADER_SIZE) {
            return error.InvalidElfHeader;
        }

        // Load kernel ELF into VM (in-place initialization).
        // Contract: loadKernel validates ELF format, initializes VM
in-place.
        // GrainStyle: Use in-place initialization to avoid stack
overflow.
        try loadKernel(vm_ptr, std.heap.page_allocator, elf_data);

        // Contract: VM must be in halted state after loading.
        std.debug.assert(vm_ptr.state == .halted);

        // Note: finish_init() will complete the setup.
        // Note: Kernel will be initialized by caller and passed as
pointer.

        // Return uninitialized Integration (will be finished by
finish_init).
        // Note: Store pointers to VM and kernel to avoid copying large
structs.
        // Caller must provide kernel pointer.
        unreachable; // Use init_with_kernel instead
    }

    /// Initialize integration with VM and kernel pointers.
    /// Contract:
    ///   Input: vm_ptr and kernel_ptr must point to initialized VM and
kernel instances
    ///   Output: Uninitialized Integration instance (caller must call
finish_init())
    /// Why: Allow caller to allocate kernel on heap to avoid stack
overflow.
    /// GrainStyle: In-place initialization pattern - caller provides
storage.
    pub fn init_with_kernel(vm_ptr: *VM, kernel_ptr: *BasinKernel) Self {
        // Contract: VM and kernel pointers must be valid.
        const vm_addr = @intFromPtr(vm_ptr);
        const kernel_addr = @intFromPtr(kernel_ptr);
        std.debug.assert(vm_addr != 0);
        std.debug.assert(kernel_addr != 0);
        std.debug.assert(vm_addr % @alignOf(VM) == 0);
        std.debug.assert(kernel_addr % @alignOf(BasinKernel) == 0);

        return Self{
            .vm = vm_ptr,
            .kernel = kernel_ptr,
            .initialized = false,
        };
    }

    /// Finish initialization (set up syscall handler and framebuffer).
    /// Contract:
    ///   Input: Self must be partially initialized (VM and kernel set)
    ///   Output: Integration fully initialized, syscall handler
registered, framebuffer initialized
    /// Why: Complete initialization after Self is created (needed for
thread-local storage).
    /// Note: Framebuffer is initialized before kernel execution starts
(host-side initialization).
    pub fn finish_init(self: *Self) void {
        // Contract: Integration must not be already initialized.
        std.debug.assert(!self.initialized);

        // Set module-level kernel pointer for syscall handler access.
        // Contract: kernel pointer must be valid.
        const kernel_ptr = @intFromPtr(self.kernel);
        std.debug.assert(kernel_ptr != 0);
        std.debug.assert(kernel_ptr % @alignOf(BasinKernel) == 0);
        
        // Set module-level storage (accessed by
syscall_handler_wrapper).
        // Note: Allow resetting if already set (for testing scenarios).
        // In production, this should be null, but in tests we may need
to reset.
        global_kernel_ptr = self.kernel;
        global_vm_ptr = self.vm;

        // Register kernel as VM syscall handler.
        // Contract: syscall_handler_wrapper will access kernel via
thread-local storage.
        self.vm.*.set_syscall_handler(syscall_handler_wrapper, null);
        
        // Register kernel as VM permission checker.
        // Contract: permission_checker_wrapper will access kernel via
thread-local storage.
        self.vm.*.permission_checker = permission_checker_wrapper;
        self.vm.*.permission_checker_user_data = null;
        
        // Register VM memory reader in kernel (for ELF parsing in
syscall_spawn).
        // Why: Allow kernel to read VM memory for process spawning.
        // Contract: vm_memory_reader_wrapper will access VM via
global_vm_ptr.
        self.kernel.*.vm_memory_reader = vm_memory_reader_wrapper;
        self.kernel.*.vm_memory_reader_user_data = null;

        // Register VM memory writer in kernel (for segment data loading
in syscall_spawn).
        // Why: Allow kernel to write VM memory for segment data loading.
        // Contract: vm_memory_writer_wrapper will access VM via
global_vm_ptr.
        self.kernel.*.vm_memory_writer = vm_memory_writer_wrapper;
        self.kernel.*.vm_memory_writer_user_data = null;

        // Initialize framebuffer from host-side (before kernel
execution starts).
        // Why: Set up framebuffer with test pattern for visual
verification.
        // Contract: VM must be initialized and kernel loaded before
framebuffer initialization.
        self.vm.*.init_framebuffer();

        // Contract: Integration must be initialized after finish_init.
        self.initialized = true;
        std.debug.assert(self.initialized);
    }

    /// Cleanup integration (reset module-level state).
    /// Contract:
    ///   Input: Integration must be initialized
    ///   Output: Module-level state reset, safe for creating new
Integration instance
    /// Why: Allow multiple Integration instances in tests (reset
global_kernel_ptr).
    pub fn cleanup(self: *Self) void {
        // Contract: Integration must be initialized.
        std.debug.assert(self.initialized);

        // Reset module-level storage (allows creating new Integration
instance).
        // Contract: Only reset if this Integration instance owns the
global pointer.
        if (global_kernel_ptr) |ptr| {
            if (ptr == self.kernel) {
                global_kernel_ptr = null;
            }
        }
        if (global_vm_ptr) |ptr| {
            if (ptr == self.vm) {
                global_vm_ptr = null;
            }
        }

        // Reset initialization flag.
        self.initialized = false;
    }

    /// Run current process in VM (scheduler-process execution
integration).
    /// Why: Execute current process from scheduler using process
execution module.
    /// Contract: Integration must be initialized, current process must
exist and have context.
    /// Returns: true if process should continue (yield), false if
process exited.
    /// Grain Style: Explicit types, bounded execution, comprehensive
assertions.
    pub fn run_current_process(self: *Self, max_steps: u64) bool {
        // Assert: Integration must be initialized (precondition).
        std.debug.assert(self.initialized);
        
        // Assert: VM and kernel must be valid (precondition).
        const vm_ptr = @intFromPtr(self.vm);
        const kernel_ptr = @intFromPtr(self.kernel);
        std.debug.assert(vm_ptr != 0);
        std.debug.assert(kernel_ptr != 0);
        
        // Assert: Max steps must be reasonable (bounded execution).
        const MAX_STEPS_LIMIT: u64 = 1_000_000_000; // 1 billion steps
max
        std.debug.assert(max_steps <= MAX_STEPS_LIMIT);
        
        // Get current process ID from scheduler.
        // Why: Find which process should be executed.
        const current_pid = self.kernel.scheduler.get_current();
        
        // Assert: Current PID must be non-zero (process must exist).
        if (current_pid == 0) {
            return false; // No process to run
        }
        
        // Find process in process table.
        // Why: Get process context for execution.
        var process_idx: ?usize = null;
        const MAX_PROCESSES: u32 = 16;
        for (0..MAX_PROCESSES) |i| {
            if (self.kernel.processes[i].allocated and
self.kernel.processes[i].id == current_pid) {
                process_idx = i;
                break;
            }
        }
        
        // Assert: Process must be found (precondition).
        if (process_idx == null) {
            return false; // Process not found
        }
        
        const idx = process_idx.?;
        const process = &self.kernel.processes[idx];
        
        // Assert: Process must have context (precondition).
        if (process.context == null) {
            return false; // Process has no context
        }
        
        const process_context = process.context.?;
        
        // Assert: Process context must be initialized (precondition).
        std.debug.assert(process_context.initialized);
        
        // Execute process in VM using process execution module.
        // Why: Run process until it exits or yields.
        // Record start time for CPU time tracking.
        // Why: Track CPU time used by process for resource monitoring.
        const start_time_ns = self.kernel.timer.get_uptime_ns();
        
        // Execute process in VM.
        // Execute process with time slice preemption support.
        // Why: Enable time slice-based preemption for fair scheduling.
        const should_continue = process_execution.execute_process(
            self.vm,
            process_context,
            max_steps,
            &self.kernel.scheduler,
        );
        
        // Record end time and update CPU time.
        // Why: Calculate elapsed CPU time and update process statistics.
        const end_time_ns = self.kernel.timer.get_uptime_ns();
        const elapsed_ns = end_time_ns -% start_time_ns; // Saturating
subtract to prevent underflow
        
        // Update process CPU time.
        // Why: Track total CPU time used by process.
        process.cpu_time_ns +%= elapsed_ns; // Saturating add to prevent
overflow
        
        // Check if process exited (state changed to exited).
        // Why: Update scheduler if process terminated.
        if (process.state == .exited) {
            // Clear from scheduler if it's the current process.
            if (self.kernel.scheduler.is_current(current_pid)) {
                self.kernel.scheduler.clear_current();
            }
            return false; // Process exited
        }
        
        // Assert: Process state must be valid (postcondition).
        std.debug.assert(process.state == .running or process.state ==
.exited);
        
        // Return whether process should continue (yield case).
        return should_continue;
    }
    
    /// Schedule and run next process (round-robin scheduling with
process execution).
    /// Why: Find next runnable process and execute it in VM.
    /// Contract: Integration must be initialized.
    /// Returns: true if a process was scheduled and run, false if no
runnable process.
    /// Grain Style: Explicit types, bounded execution, comprehensive
assertions.
    pub fn schedule_and_run_next(self: *Self, max_steps: u64) bool {
        // Assert: Integration must be initialized (precondition).
        std.debug.assert(self.initialized);
        
        // Assert: Max steps must be reasonable (bounded execution).
        const MAX_STEPS_LIMIT: u64 = 1_000_000_000; // 1 billion steps
max
        std.debug.assert(max_steps <= MAX_STEPS_LIMIT);
        
        // Find next runnable process from scheduler.
        // Why: Round-robin scheduling selects next process to execute.
        const MAX_PROCESSES: u32 = 16;
        const next_pid = self.kernel.scheduler.find_next_runnable(
            &self.kernel.processes,
            MAX_PROCESSES,
        );
        
        // Check if no runnable process found.
        if (next_pid == 0) {
            return false; // No runnable process
        }
        
        // Get process time slice quantum.
        // Why: Use process-specific time slice for scheduling.
        var process_idx: ?usize = null;
        const MAX_PROCESSES: u32 = 16;
        for (0..MAX_PROCESSES) |i| {
            if (self.kernel.processes[i].allocated and
self.kernel.processes[i].id == next_pid) {
                process_idx = i;
                break;
            }
        }
        
        if (process_idx == null) {
            return false; // Process not found
        }
        
        const idx = process_idx.?;
        const process = &self.kernel.processes[idx];
        const time_slice = process.time_slice_quantum;
        
        // Set as current process in scheduler with time slice.
        // Why: Update scheduler state before execution with time slice.
        self.kernel.scheduler.set_current(next_pid, time_slice);
        
        // Run current process (which is now next_pid).
        // Why: Execute the scheduled process.
        const should_continue = self.run_current_process(max_steps);
        
        // Assert: Process execution must complete (postcondition).
        // Note: should_continue indicates if process yielded (true) or
exited (false).
        _ = should_continue;
        
        // Check if process was preempted (time slice expired).
        // Why: Reschedule if time slice expired.
        if (self.kernel.scheduler.is_time_slice_expired()) {
            // Time slice expired: clear current process for
rescheduling.
            self.kernel.scheduler.clear_current();
        }
        
        // Return true if process was scheduled and run.
        return true;
    }
    
    /// Run scheduler loop (execute processes with time slice
preemption).
    /// Why: Coordinate process execution, preemption, and rescheduling.
    /// Contract: Integration must be initialized.
    /// Returns: Number of scheduling cycles completed.
    /// Grain Style: Explicit types, bounded execution, comprehensive
assertions.
    pub fn run_scheduler_loop(self: *Self, max_cycles: u32,
max_steps_per_process: u64) u32 {
        // Assert: Integration must be initialized (precondition).
        std.debug.assert(self.initialized);
        
        // Assert: Max cycles must be reasonable (bounded execution).
        const MAX_CYCLES_LIMIT: u32 = 1_000_000; // 1 million cycles max
        std.debug.assert(max_cycles <= MAX_CYCLES_LIMIT);
        
        // Assert: Max steps must be reasonable (bounded execution).
        const MAX_STEPS_LIMIT: u64 = 1_000_000_000; // 1 billion steps
max
        std.debug.assert(max_steps_per_process <= MAX_STEPS_LIMIT);
        
        var cycles_completed: u32 = 0;
        
        // Scheduler loop: run processes until max cycles or no runnable
processes.
        while (cycles_completed < max_cycles) : (cycles_completed += 1) {
            // Find and run next process.
            const scheduled =
self.schedule_and_run_next(max_steps_per_process);
            
            // If no runnable process, break loop.
            if (!scheduled) {
                break; // No more runnable processes
            }
        }
        
        // Assert: Cycles completed must be within limit (postcondition).
        std.debug.assert(cycles_completed <= max_cycles);
        
        return cycles_completed;
    }

    /// Run VM execution loop until halted or error.
    /// Contract:
    ///   Input: Integration must be initialized
    ///   Output: VM execution completes (halted or errored)
    ///   Errors: VM execution errors (invalid instruction, memory
access)
    /// Why: Execute VM instructions, handle syscalls via kernel.
    pub fn run(self: *Self) !void {
        // Contract: Integration must be initialized.
        std.debug.assert(self.initialized);

        // Contract: VM must be in halted state before starting.
        std.debug.assert(self.vm.*.state == .halted);

        // Start VM execution.
        self.vm.*.start();

        // Contract: VM must be in running state after start.
        std.debug.assert(self.vm.*.state == .running);

        // Execute VM instructions until halted or error.
        while (self.vm.*.state == .running) {
            // Contract: VM step may return error (invalid instruction,
memory access).
            // Use JIT if enabled (falls back to interpreter if not).
            try self.vm.*.step_jit();
        }

        // Contract: VM must be halted or errored after loop.
        std.debug.assert(self.vm.*.state == .halted or self.vm.*.state
== .errored);
    }

    /// Get VM state.
    /// Contract:
    ///   Input: Integration must be initialized
    ///   Output: Current VM state (running, halted, errored)
    /// Why: Query VM execution state.
    pub fn get_vm_state(self: *const Self) VM.VMState {
        // Contract: Integration must be initialized.
        std.debug.assert(self.initialized);

        return self.vm.*.state;
    }

    /// Get kernel instance (for testing/debugging).
    /// Contract:
    ///   Input: Integration must be initialized
    ///   Output: Non-null pointer to kernel instance
    /// Why: Allow external access to kernel for testing/debugging.
    pub fn get_kernel(self: *Self) *BasinKernel {
        // Contract: Integration must be initialized.
        std.debug.assert(self.initialized);

        // Contract: Kernel pointer must be valid.
        const kernel_ptr = @intFromPtr(&self.kernel);
        std.debug.assert(kernel_ptr != 0);
        std.debug.assert(kernel_ptr % @alignOf(BasinKernel) == 0);

        return &self.kernel;
    }

    /// Get VM instance (for testing/debugging).
    /// Contract:
    ///   Input: Integration must be initialized
    ///   Output: Non-null pointer to VM instance
    /// Why: Allow external access to VM for testing/debugging.
    pub fn get_vm(self: *Self) *VM {
        // Contract: Integration must be initialized.
        std.debug.assert(self.initialized);

        // Contract: VM pointer must be valid.
        const vm_ptr = @intFromPtr(self.vm);
        std.debug.assert(vm_ptr != 0);
        std.debug.assert(vm_ptr % @alignOf(VM) == 0);

        return self.vm;
    }
};

/// Syscall handler wrapper (converts SyscallResult to u64).
/// Contract:
///   Input: syscall_num >= 10 (kernel syscalls), user_data must be
valid Integration pointer
///   Output: u64 result (negative = error code, non-negative = success
value)
///   Errors: Panic if user_data is null or invalid
/// Why: Bridge VM syscall interface (u64) with kernel interface
(SyscallResult).
/// RISC-V Convention: Negative values = error codes, non-negative =
success values.
/// Note: VM passes user_data (set via set_syscall_handler) to handler.
///       We cast user_data to Integration* and extract kernel from it.
fn syscall_handler_wrapper(
    syscall_num: u32,
    arg1: u64,
    arg2: u64,
    arg3: u64,
    arg4: u64,
) u64 {
    // Contract: syscall_num must be >= 10 (kernel syscalls, not SBI).
    std.debug.assert(syscall_num >= 10);

    // Handle VM-specific syscalls directly (needs VM access).
    // Why: These syscalls need VM memory access, kernel doesn't have VM
reference.
    
    // Syscall numbers
    const READ_INPUT_EVENT_SYSCALL: u32 = 60;
    const CLOCK_GETTIME_SYSCALL: u32 = 40;
    const FB_CLEAR_SYSCALL: u32 = 70;
    const FB_DRAW_PIXEL_SYSCALL: u32 = 71;
    const FB_DRAW_TEXT_SYSCALL: u32 = 72;
    
    // Handle input event syscall (needs VM access to input queue).
    if (syscall_num == READ_INPUT_EVENT_SYSCALL) {
        const vm = global_vm_ptr orelse {
            @panic("syscall_handler_wrapper called before
Integration.finish_init");
        };
        const vm_addr = @intFromPtr(vm);
        std.debug.assert(vm_addr != 0);
        std.debug.assert(vm_addr % @alignOf(VM) == 0);
        
        if (vm.input_event_queue.count == 0) {
            return @as(u64, @bitCast(@as(i64, -6))); // would_block
        }
        
        const event = vm.input_event_queue.dequeue() orelse {
            return @as(u64, @bitCast(@as(i64, -6))); // would_block
        };
        
        if (arg1 == 0) {
            return @as(u64, @bitCast(@as(i64, -2))); // invalid_argument
        }
        
        const VM_MEMORY_SIZE: u64 = 4 * 1024 * 1024;
        const EVENT_SIZE: u64 = 32;
        if (arg1 + EVENT_SIZE > VM_MEMORY_SIZE) {
            return @as(u64, @bitCast(@as(i64, -9))); // invalid_address
        }
        
        const event_ptr = @as([*]u8, @ptrFromInt(@as(usize,
@intCast(arg1))));
        event_ptr[0] = event.event_type;
        event_ptr[1] = 0;
        event_ptr[2] = 0;
        event_ptr[3] = 0;
        
        if (event.event_type == 0) {
            event_ptr[4] = event.mouse.kind;
            event_ptr[5] = event.mouse.button;
            @memcpy(event_ptr[6..10], &std.mem.toBytes(@as(u32,
event.mouse.x)));
            @memcpy(event_ptr[10..14], &std.mem.toBytes(@as(u32,
event.mouse.y)));
            event_ptr[14] = event.mouse.modifiers;
            @memset(event_ptr[15..32], 0);
        } else {
            event_ptr[4] = event.keyboard.kind;
            event_ptr[5] = 0;
            event_ptr[6] = 0;
            event_ptr[7] = 0;
            @memcpy(event_ptr[8..12], &std.mem.toBytes(@as(u32,
event.keyboard.key_code)));
            @memcpy(event_ptr[12..16], &std.mem.toBytes(@as(u32,
event.keyboard.character)));
            event_ptr[16] = event.keyboard.modifiers;
            @memset(event_ptr[17..32], 0);
        }
        
        return EVENT_SIZE;
    }
    
    // Handle clock_gettime syscall (needs VM access to write timespec).
    // Why: Kernel doesn't have direct VM memory access, integration
layer handles it.
    if (syscall_num == CLOCK_GETTIME_SYSCALL) {
        const kernel = global_kernel_ptr orelse {
            @panic("syscall_handler_wrapper called before
Integration.finish_init");
        };
        const kernel_addr = @intFromPtr(kernel);
        std.debug.assert(kernel_addr != 0);
        std.debug.assert(kernel_addr % @alignOf(BasinKernel) == 0);
        
        const vm = global_vm_ptr orelse {
            @panic("syscall_handler_wrapper called before
Integration.finish_init");
        };
        const vm_addr = @intFromPtr(vm);
        std.debug.assert(vm_addr != 0);
        std.debug.assert(vm_addr % @alignOf(VM) == 0);
        
        const clock_id: u64 = arg1;
        const timespec_ptr: u64 = arg2;
        
        // Validate clock_id (monotonic=0, realtime=1).
        if (clock_id > 1) {
            return @as(u64, @bitCast(@as(i64, -2))); // invalid_argument
        }
        
        // Validate timespec pointer.
        if (timespec_ptr == 0) {
            return @as(u64, @bitCast(@as(i64, -2))); // invalid_argument
        }
        
        const VM_MEMORY_SIZE: u64 = 4 * 1024 * 1024;
        const TIMESPEC_SIZE: u64 = 16; // 8 bytes seconds + 8 bytes
nanoseconds
        if (timespec_ptr + TIMESPEC_SIZE > VM_MEMORY_SIZE) {
            return @as(u64, @bitCast(@as(i64, -9))); // invalid_address
        }
        
        // Get time from kernel timer.
        const time_ns: u64 = if (clock_id == 0)
            kernel.timer.get_monotonic_ns()
        else
            kernel.timer.get_realtime_ns();
        
        // Convert nanoseconds to seconds and nanoseconds.
        const seconds: u64 = time_ns / 1000000000;
        const nanoseconds: u64 = time_ns % 1000000000;
        
        // Assert: Nanoseconds must be valid (0-999999999).
        std.debug.assert(nanoseconds < 1000000000);
        
        // Write timespec structure to VM memory.
        const timespec_phys = vm.translate_address(timespec_ptr) orelse {
            return @as(u64, @bitCast(@as(i64, -9))); // invalid_address
        };
        
        // Write seconds (8 bytes, little-endian).
        const seconds_bytes = std.mem.toBytes(seconds);
        @memcpy(vm.memory[@as(usize,
@intCast(timespec_phys))..@as(usize, @intCast(timespec_phys + 8))],
&seconds_bytes);
        
        // Write nanoseconds (8 bytes, little-endian).
        const nanoseconds_bytes = std.mem.toBytes(nanoseconds);
        @memcpy(vm.memory[@as(usize, @intCast(timespec_phys +
8))..@as(usize, @intCast(timespec_phys + 16))], &nanoseconds_bytes);
        
        // Return success (0).
        return 0;
    }
    
    // Handle framebuffer syscalls (needs VM access to framebuffer
memory).
    // These are handled here because kernel doesn't have direct VM
memory access.
    if (syscall_num == FB_CLEAR_SYSCALL or syscall_num ==
FB_DRAW_PIXEL_SYSCALL or syscall_num == FB_DRAW_TEXT_SYSCALL) {
        const vm = global_vm_ptr orelse {
            @panic("syscall_handler_wrapper called before
Integration.finish_init");
        };
        const vm_addr = @intFromPtr(vm);
        std.debug.assert(vm_addr != 0);
        std.debug.assert(vm_addr % @alignOf(VM) == 0);
        
        const FRAMEBUFFER_BASE: u64 = 0x90000000;
        const FRAMEBUFFER_WIDTH: u32 = 1024;
        const FRAMEBUFFER_HEIGHT: u32 = 768;
        const FRAMEBUFFER_BPP: u32 = 4;
        const FRAMEBUFFER_SIZE: u32 = FRAMEBUFFER_WIDTH *
FRAMEBUFFER_HEIGHT * FRAMEBUFFER_BPP;
        
        if (syscall_num == FB_CLEAR_SYSCALL) {
            const color: u32 = @truncate(arg1);
            const fb_phys_offset =
vm.translate_address(FRAMEBUFFER_BASE) orelse {
                return @as(u64, @bitCast(@as(i64, -9))); //
invalid_address
            };
            const fb_memory = vm.memory[@as(usize,
@intCast(fb_phys_offset))..@as(usize, @intCast(fb_phys_offset +
FRAMEBUFFER_SIZE))];
            const r: u8 = @truncate((color >> 24) & 0xFF);
            const g: u8 = @truncate((color >> 16) & 0xFF);
            const b: u8 = @truncate((color >> 8) & 0xFF);
            const a: u8 = @truncate(color & 0xFF);
            var i: u32 = 0;
            while (i < FRAMEBUFFER_SIZE) : (i += 4) {
                fb_memory[i + 0] = r;
                fb_memory[i + 1] = g;
                fb_memory[i + 2] = b;
                fb_memory[i + 3] = a;
            }
            // Mark entire framebuffer as dirty (clear operation changes
everything).
            vm.framebuffer_dirty.mark_all();
            return 0;
        }
        
        if (syscall_num == FB_DRAW_PIXEL_SYSCALL) {
            const x: u32 = @truncate(arg1);
            const y: u32 = @truncate(arg2);
            const color: u32 = @truncate(arg3);
            if (x >= FRAMEBUFFER_WIDTH or y >= FRAMEBUFFER_HEIGHT) {
                return @as(u64, @bitCast(@as(i64, -11))); //
out_of_bounds
            }
            const fb_phys_offset =
vm.translate_address(FRAMEBUFFER_BASE) orelse {
                return @as(u64, @bitCast(@as(i64, -9))); //
invalid_address
            };
            const offset: u32 = (y * FRAMEBUFFER_WIDTH + x) *
FRAMEBUFFER_BPP;
            const pixel_addr = @as(usize, @intCast(fb_phys_offset +
offset));
            const r: u8 = @truncate((color >> 24) & 0xFF);
            const g: u8 = @truncate((color >> 16) & 0xFF);
            const b: u8 = @truncate((color >> 8) & 0xFF);
            const a: u8 = @truncate(color & 0xFF);
            vm.memory[pixel_addr + 0] = r;
            vm.memory[pixel_addr + 1] = g;
            vm.memory[pixel_addr + 2] = b;
            vm.memory[pixel_addr + 3] = a;
            // Mark pixel as dirty (optimization: only sync changed
regions).
            vm.framebuffer_dirty.mark_pixel(x, y);
            return 0;
        }
        
        if (syscall_num == FB_DRAW_TEXT_SYSCALL) {
            const text_ptr: u64 = arg1;
            const x: u32 = @truncate(arg2);
            const y: u32 = @truncate(arg3);
            const fg_color: u32 = @truncate(arg4);
            const bg_color: u32 = 0x1E1E2EFF;
            if (text_ptr == 0) {
                return @as(u64, @bitCast(@as(i64, -2))); //
invalid_argument
            }
            if (x >= FRAMEBUFFER_WIDTH or y >= FRAMEBUFFER_HEIGHT) {
                return @as(u64, @bitCast(@as(i64, -11))); //
out_of_bounds
            }
            const text_phys = vm.translate_address(text_ptr) orelse {
                return @as(u64, @bitCast(@as(i64, -9))); //
invalid_address
            };
            const MAX_TEXT_LEN: u32 = 256;
            var text_buf: [MAX_TEXT_LEN]u8 = undefined;
            var text_len: u32 = 0;
            while (text_len < MAX_TEXT_LEN) : (text_len += 1) {
                const char_addr = @as(usize, @intCast(text_phys +
text_len));
                if (char_addr >= vm.memory.len) {
                    return @as(u64, @bitCast(@as(i64, -9))); //
invalid_address
                }
                const ch = vm.memory[char_addr];
                text_buf[text_len] = ch;
                if (ch == 0) break;
            }
            if (text_len == 0) {
                return @as(u64, @bitCast(@as(i64, -2))); //
invalid_argument
            }
            const fb_phys_offset =
vm.translate_address(FRAMEBUFFER_BASE) orelse {
                return @as(u64, @bitCast(@as(i64, -9))); //
invalid_address
            };
            const text_slice = text_buf[0..text_len];
            var char_x: u32 = x;
            var char_y: u32 = y;
            const char_width: u32 = 8;
            const char_height: u32 = 8;
            for (text_slice) |ch| {
                if (ch == 0) break;
                if (ch == '\n') {
                    char_x = x;
                    char_y += char_height;
                    continue;
                }
                if (char_x + char_width <= FRAMEBUFFER_WIDTH and char_y
+ char_height <= FRAMEBUFFER_HEIGHT) {
                    var py: u32 = 0;
                    while (py < char_height) : (py += 1) {
                        var px: u32 = 0;
                        while (px < char_width) : (px += 1) {
                            const pixel_offset: u32 = ((char_y + py) *
FRAMEBUFFER_WIDTH + (char_x + px)) * FRAMEBUFFER_BPP;
                            const pixel_addr = @as(usize,
@intCast(fb_phys_offset + pixel_offset));
                            const use_fg = (px > 0 and px < char_width -
1 and py > 0 and py < char_height - 1);
                            const pixel_color = if (use_fg) fg_color
else bg_color;
                            const r: u8 = @truncate((pixel_color >> 24)
& 0xFF);
                            const g: u8 = @truncate((pixel_color >> 16)
& 0xFF);
                            const b: u8 = @truncate((pixel_color >> 8) &
0xFF);
                            const a: u8 = @truncate(pixel_color & 0xFF);
                            vm.memory[pixel_addr + 0] = r;
                            vm.memory[pixel_addr + 1] = g;
                            vm.memory[pixel_addr + 2] = b;
                            vm.memory[pixel_addr + 3] = a;
                            // Mark pixel as dirty (optimization: only
sync changed regions).
                            vm.framebuffer_dirty.mark_pixel(char_x + px,
char_y + py);
                        }
                    }
                }
                char_x += char_width;
                if (char_x + char_width > FRAMEBUFFER_WIDTH) {
                    char_x = x;
                    char_y += char_height;
                }
            }
            return text_len;
        }
    }
    
    // Get kernel pointer from module-level storage (set by
Integration.finish_init).
    // Contract: global_kernel_ptr must be set before
syscall_handler_wrapper is called.
    const kernel = global_kernel_ptr orelse {
        @panic("syscall_handler_wrapper called before
Integration.finish_init");
    };

    // Contract: kernel pointer must be valid.
    const kernel_addr = @intFromPtr(kernel);
    std.debug.assert(kernel_addr != 0);
    std.debug.assert(kernel_addr % @alignOf(BasinKernel) == 0);

    return syscall_handler_wrapper_impl(kernel, syscall_num, arg1, arg2,
arg3, arg4);
}

/// Internal syscall handler implementation.
/// Contract:
///   Input: kernel must be valid BasinKernel pointer, syscall_num >= 10
///   Output: u64 result (negative = error code, non-negative = success
value)
/// Why: Separate implementation from wrapper for clarity.
fn syscall_handler_wrapper_impl(
    kernel: *BasinKernel,
    syscall_num: u32,
    arg1: u64,
    arg2: u64,
    arg3: u64,
    arg4: u64,
) u64 {
    // Contract: syscall_num must be >= 10 (kernel syscalls, not SBI).
    std.debug.assert(syscall_num >= 10);

    // Contract: kernel pointer must be valid.
    const kernel_ptr = @intFromPtr(kernel);
    std.debug.assert(kernel_ptr != 0);
    std.debug.assert(kernel_ptr % @alignOf(BasinKernel) == 0);

    // Call kernel syscall handler.
    // Contract: handle_syscall returns BasinError!SyscallResult.
    const result = kernel.handle_syscall(syscall_num, arg1, arg2, arg3,
arg4) catch |err| {
        // Contract: BasinError must be converted to negative u64.
        // RISC-V convention: Negative values = error codes.
        // Error codes: -1 = invalid_handle, -2 = invalid_argument, etc.
        const error_code: i64 = switch (err) {
            BasinError.invalid_handle => -1,
            BasinError.invalid_argument => -2,
            BasinError.permission_denied => -3,
            BasinError.not_found => -4,
            BasinError.out_of_memory => -5,
            BasinError.would_block => -6,
            BasinError.interrupted => -7,
            BasinError.invalid_syscall => -8,
            BasinError.invalid_address => -9,
            BasinError.unaligned_access => -10,
            BasinError.out_of_bounds => -11,
            BasinError.user_not_found => -12,
            BasinError.invalid_user => -13,
        };
        return @as(u64, @bitCast(error_code));
    };

    // Contract: SyscallResult must be success or error.
    return switch (result) {
        .success => |value| {
            // Contract: Success value must be non-negative (RISC-V
convention).
            std.debug.assert(value >= 0);
            return value;
        },
        .err => |err| {
            // Contract: Error must be converted to negative u64.
            const error_code: i64 = switch (err) {
            BasinError.invalid_handle => -1,
            BasinError.invalid_argument => -2,
            BasinError.permission_denied => -3,
            BasinError.not_found => -4,
            BasinError.out_of_memory => -5,
            BasinError.would_block => -6,
            BasinError.interrupted => -7,
            BasinError.invalid_syscall => -8,
            BasinError.invalid_address => -9,
            BasinError.unaligned_access => -10,
            BasinError.out_of_bounds => -11,
            BasinError.user_not_found => -12,
            BasinError.invalid_user => -13,
            };
            return @as(u64, @bitCast(error_code));
        },
    };
}

/// Load userspace ELF program into VM.
/// Contract:
///   Input: elf_data must be non-empty, valid RISC-V64 ELF executable
///   Output: VM with userspace program loaded, PC set to entry point,
SP set to stack address
///   Errors: Invalid ELF format, address out of bounds, memory
allocation failure
/// Why: Load userspace programs (not kernel) into VM memory.
/// Note: Userspace programs typically load at addresses like 0x10000+
(different from kernel at 0x1000).
/// Note: RISC-V ELF executables are typically position-independent and
use their own virtual addresses.
pub fn loadUserspaceELF(
    target: *VM,
    allocator: std.mem.Allocator,
    elf_data: []const u8,
    argv: []const []const u8,
) !void {
    
    // Contract: ELF data must be non-empty.
    if (elf_data.len == 0) {
        std.debug.print("DEBUG integration.zig: ELF data is empty\n",
.{});
        return error.EmptyElfData;
    }

    // Contract: ELF data must be large enough for ELF header (64 bytes
minimum).
    const MIN_ELF_HEADER_SIZE: u32 = 64;
    if (elf_data.len < MIN_ELF_HEADER_SIZE) {
        std.debug.print("DEBUG integration.zig: ELF data too small ({} <
{})\n", .{ elf_data.len, MIN_ELF_HEADER_SIZE });
        return error.InvalidElfHeader;
    }

    // Use existing loadKernel function (it's generic enough for
userspace too).
    // Contract: loadKernel validates ELF format and loads segments at
their virtual addresses.
    // Note: RISC-V ELF executables specify their own load addresses in
p_vaddr.
    std.debug.print("DEBUG integration.zig: About to call loadKernel,
allocator.ptr=0x{x}\n", .{@intFromPtr(allocator.ptr)});
    std.debug.print("DEBUG integration.zig: elf_data.ptr=0x{x},
elf_data.len={}\n", .{ @intFromPtr(elf_data.ptr), elf_data.len });
    
    // GrainStyle: Use in-place initialization to avoid stack overflow.
    std.debug.print("DEBUG integration.zig: Calling loadKernel...\n",
.{});
    loadKernel(target, allocator, elf_data) catch |err| {
        std.debug.print("DEBUG integration.zig: loadKernel failed:
{}\n", .{err});
        // Convert LoaderError to IntegrationError.
        return switch (err) {
            error.SegmentOutOfBounds => error.AddressOutOfBounds,
            error.InvalidElfFormat => error.InvalidElfHeader,
        };
    };
    std.debug.print("DEBUG integration.zig: loadKernel completed
successfully\n", .{});

    // Contract: VM must be in halted state after loading.
    // Check: VM state must be halted (return error instead of asserting
for userspace programs).
    std.debug.print("DEBUG integration.zig: Checking VM state...\n",
.{});
    if (target.state != .halted) {
        std.debug.print("DEBUG integration.zig: VM state is {}, expected
halted\n", .{target.state});
        return error.InvalidState;
    }
    std.debug.print("DEBUG integration.zig: VM state is halted\n", .{});

    // Contract: PC must be set to entry point (done by loadKernel).
    // Note: Entry point can be 0x0 for some programs (e.g.,
position-independent executables).
    // We only check that it's within VM memory bounds (done in
loadKernel).
    std.debug.print("DEBUG integration.zig: PC=0x{x}\n",
.{target.regs.pc});
    _ = target.regs.pc; // PC is set by loadKernel

    // Set up userspace stack pointer (SP register = x2).
    std.debug.print("DEBUG integration.zig: Setting up stack...\n", .{});
    // Contract: Stack address must be page-aligned and within VM memory.
    const VM_MEMORY_SIZE: u64 = 4 * 1024 * 1024; // 4MB
    const PAGE_SIZE: u64 = 4096;
    const STACK_ADDRESS: u64 = VM_MEMORY_SIZE - PAGE_SIZE; // Top of
memory, page-aligned
    std.debug.print("DEBUG integration.zig: STACK_ADDRESS=0x{x},
target.memory_size=0x{x}\n", .{ STACK_ADDRESS, target.memory_size });
    // Check: Stack address must be page-aligned and within VM memory.
    if (STACK_ADDRESS % PAGE_SIZE != 0 or STACK_ADDRESS >=
target.memory_size) {
        std.debug.print("DEBUG integration.zig: Stack address validation
failed\n", .{});
        return error.AddressOutOfBounds;
    }
    std.debug.print("DEBUG integration.zig: Stack address validated,
setting SP register...\n", .{});

    target.regs.set(2, STACK_ADDRESS); // x2 = SP register
    std.debug.print("DEBUG integration.zig: SP register set
successfully\n", .{});

    // Contract: SP register must be set correctly (verified by regs.set
above).
    // Note: We don't assert here to avoid crashes during userspace
program loading.

    // Set up argv/argc on stack (RISC-V calling convention).
    // Contract: argv array and strings must fit in stack space.
    // Note: RISC-V calling convention: a0 = argc, a1 = argv pointer
    // Stack layout (from high to low, growing downward):
    //   [argc][argv_ptr][argv[0] ptr][argv[1] ptr]...[argv[N] ptr][null
terminator][argv[0] string][argv[1] string]...
    //   High address (STACK_ADDRESS)                                   
Low address (sp after setup)
    if (argv.len > 0) {
        var sp: u64 = STACK_ADDRESS;
        
        // Calculate total space needed:
        // - argv array: (argv.len + 1) * 8 bytes (pointers + null
terminator)
        // - strings: sum of all string lengths + null terminators
        var total_string_len: u64 = 0;
        for (argv) |arg| {
            total_string_len += arg.len + 1; // +1 for null terminator
        }
        
        // Align string data to 8-byte boundary
        const string_data_size = (total_string_len + 7) & ~@as(u64, 7);
        
        // Calculate argv array address (before strings)
        const argv_array_size = (argv.len + 1) * 8; // +1 for null
terminator
        const argv_array_addr = sp - 16 - argv_array_size; // Reserve 16
bytes for argc/argv_ptr
        
        // Calculate string data start address (after argv array)
        const string_data_start = argv_array_addr - string_data_size;
        
        // Check: All addresses must be within VM memory bounds.
        // Note: Stack grows downward, so string_data_start should be
less than STACK_ADDRESS.
        if (string_data_start >= STACK_ADDRESS or string_data_start +
string_data_size > target.memory_size) {
            std.debug.print("DEBUG integration.zig: argv setup would
exceed stack bounds: string_data_start=0x{x}, STACK_ADDRESS=0x{x},
memory_size=0x{x}\n", .{ string_data_start, STACK_ADDRESS,
target.memory_size });
            return error.AddressOutOfBounds;
        }
        
        // Write strings to stack (from low to high address)
        var current_string_addr = string_data_start;
        var argv_ptrs: [256]u64 = undefined; // Max 256 arguments
        if (argv.len > 256) {
            return error.TooManyArguments;
        }
        
        for (argv, 0..) |arg, i| {
            // Store string address in argv_ptrs array
            argv_ptrs[i] = current_string_addr;
            
            // Write string data (with null terminator)
            if (current_string_addr + arg.len + 1 > target.memory_size) {
                return error.AddressOutOfBounds;
            }
           
@memcpy(target.memory[@intCast(current_string_addr)..@intCast(current_str
ing_addr + arg.len)], arg);
            target.memory[@intCast(current_string_addr + arg.len)] = 0;
// Null terminator
            
            // Move to next string (aligned to 8 bytes)
            current_string_addr += (arg.len + 1 + 7) & ~@as(u64, 7);
        }
        
        // Write argv array (pointers to strings, followed by null
terminator)
        var argv_array_current = argv_array_addr;
        for (0..argv.len) |i| {
            if (argv_array_current + 8 > target.memory_size) {
                return error.AddressOutOfBounds;
            }
           
@memcpy(target.memory[@intCast(argv_array_current)..@intCast(argv_array_c
urrent + 8)], &std.mem.toBytes(argv_ptrs[i]));
            argv_array_current += 8;
        }
        
        // Write null terminator for argv array
        if (argv_array_current + 8 > target.memory_size) {
            return error.AddressOutOfBounds;
        }
       
@memcpy(target.memory[@intCast(argv_array_current)..@intCast(argv_array_c
urrent + 8)], &[_]u8{0} ** 8);
        
        // Reserve space for argc and argv pointer (16 bytes, 8-byte
aligned)
        sp -= 16;
        
        // Write argc (argument count) at sp
        if (sp + 8 > target.memory_size) {
            return error.AddressOutOfBounds;
        }
        const argc: u64 = argv.len;
        @memcpy(target.memory[@intCast(sp)..@intCast(sp + 8)],
&std.mem.toBytes(argc));
        
        // Write argv pointer (points to array of string pointers) at sp
+ 8
        if (sp + 16 > target.memory_size) {
            return error.AddressOutOfBounds;
        }
        @memcpy(target.memory[@intCast(sp + 8)..@intCast(sp + 16)],
&std.mem.toBytes(argv_array_addr));
        
        // Set registers according to RISC-V calling convention
        target.regs.set(10, argc); // a0 = argc
        target.regs.set(11, argv_array_addr); // a1 = argv (pointer to
array of string pointers)
        
        // Update SP to point to new stack top (after argc/argv_ptr)
        target.regs.set(2, sp);
        
        std.debug.print("DEBUG integration.zig: argv setup complete:
argc={}, argv_ptr=0x{x}, sp=0x{x}\n", .{ argc, argv_array_addr, sp });
    } else {
        // No arguments: argc = 0, argv = null
        target.regs.set(10, 0); // a0 = argc = 0
        target.regs.set(11, 0); // a1 = argv = null
        std.debug.print("DEBUG integration.zig: No argv provided,
argc=0, argv=null\n", .{});
    }

    // Assert: VM must be in halted state after loading.
    std.debug.print("DEBUG integration.zig: Final check: VM state={}\n",
.{target.state});
    std.debug.assert(target.state == .halted);
    std.debug.print("DEBUG integration.zig: loadUserspaceELF completed
successfully\n", .{});
}

/// Integration errors.
/// Why: Explicit error types for VM-kernel integration.
pub const IntegrationError = error{
    EmptyElfData,
    InvalidElfHeader,
    AddressOutOfBounds,
    InvalidState,
    UnalignedAddress,
    TooManyArguments,
    UserNotFound,
    InvalidUser,
};

// === kernel_vm/jit.zig ===

const std = @import("std");
const builtin = @import("builtin");

extern fn pthread_jit_write_protect_np(enabled: c_int) void;

/// Errors that can occur during JIT compilation or execution.
pub const JitError = error{
    OutOfMemory,
    BufferOverflow,
    InvalidInstruction,
    EncodingError,
    ProtectionFailure,
    InvalidSnapshot,
    ThresholdNotMet, // Block execution count below compilation threshold
};

// Bounded: Max hot paths to track.
pub const MAX_HOT_PATHS: u32 = 32;

// Hot path entry: tracks execution count for a PC.
pub const HotPathEntry = struct {
    pc: u64,
    execution_count: u64,
    last_seen: u64, // Timestamp of last execution.

    pub fn init(pc: u64) HotPathEntry {
        // Allow pc=0 for initialization (will be set later).
        return HotPathEntry{
            .pc = pc,
            .execution_count = 0,
            .last_seen = 0,
        };
    }
};

// Hot path tracker: identifies frequently executed blocks.
pub const HotPathTracker = struct {
    paths: [MAX_HOT_PATHS]HotPathEntry,
    paths_len: u32,
    total_executions: u64,
    sequence_number: u64, // Monotonic counter for last_seen.

    pub fn init() HotPathTracker {
        var tracker = HotPathTracker{
            .paths = undefined,
            .paths_len = 0,
            .total_executions = 0,
            .sequence_number = 0,
        };
        var i: u32 = 0;
        while (i < MAX_HOT_PATHS) : (i += 1) {
            tracker.paths[i] = HotPathEntry.init(0);
        }
        return tracker;
    }

    fn find_path_index(self: *const HotPathTracker, pc: u64) ?u32 {
        std.debug.assert(pc > 0);
        var i: u32 = 0;
        while (i < self.paths_len) : (i += 1) {
            if (self.paths[i].pc == pc) {
                return i;
            }
        }
        return null;
    }

    fn find_empty_slot(self: *const HotPathTracker) ?u32 {
        var i: u32 = 0;
        while (i < self.paths_len) : (i += 1) {
            if (self.paths[i].pc == 0) {
                return i;
            }
        }
        return null;
    }

    fn add_new_path(self: *HotPathTracker, pc: u64) void {
        std.debug.assert(pc > 0);
        if (self.paths_len < MAX_HOT_PATHS) {
            const idx = self.paths_len;
            self.paths[idx] = HotPathEntry.init(pc);
            self.paths[idx].execution_count = 1;
            self.paths[idx].last_seen = self.sequence_number;
            self.paths_len += 1;
        } else if (self.find_empty_slot()) |empty_slot| {
            self.paths[empty_slot] = HotPathEntry.init(pc);
            self.paths[empty_slot].execution_count = 1;
            self.paths[empty_slot].last_seen = self.sequence_number;
        }
    }

    pub fn record_execution(self: *HotPathTracker, pc: u64) void {
        std.debug.assert(pc > 0);
        self.total_executions += 1;
        self.sequence_number += 1;
        // Find existing entry or create new one.
        if (self.find_path_index(pc)) |idx| {
            self.paths[idx].execution_count += 1;
            self.paths[idx].last_seen = self.sequence_number;
        } else {
            self.add_new_path(pc);
        }
    }

    pub fn get_hot_paths(self: *const HotPathTracker, threshold: u64)
[]const HotPathEntry {
        std.debug.assert(threshold > 0);
        // Return paths that exceed threshold (simplified: return all
for now).
        if (self.paths_len == 0) {
            return &[_]HotPathEntry{};
        }
        return self.paths[0..self.paths_len];
    }
};

/// Performance Counters for the JIT.
pub const JitPerfCounters = struct {
    blocks_compiled: u64 = 0,
    instructions_translated: u64 = 0,
    cache_hits: u64 = 0,
    cache_misses: u64 = 0,
    total_execution_time_ns: u64 = 0,
    jit_compile_time_ns: u64 = 0,
    interpreter_fallbacks: u64 = 0,
    hot_path_tracker: HotPathTracker,
    total_code_size_bytes: u64 = 0,
    max_code_size_bytes: u64 = 0,
    min_code_size_bytes: u64 = 0,
    chain_opportunities: u64 = 0, // Direct jumps that could be chained
    chains_created: u64 = 0, // Actual chains created
    chain_hits: u64 = 0, // Executions via chains
    blocks_invalidated: u64 = 0, // Blocks invalidated
    cache_invalidations: u64 = 0, // Full cache invalidations
    threshold_deferred: u64 = 0, // Blocks deferred due to threshold

    pub fn print_stats(self: *const JitPerfCounters) void {
        std.debug.print("\nJIT Performance Stats:\n", .{});
        std.debug.print("  Blocks Compiled: {}\n",
.{self.blocks_compiled});
        std.debug.print("  Instructions Translated: {}\n",
.{self.instructions_translated});
        std.debug.print("  Cache Hits: {}\n", .{self.cache_hits});
        std.debug.print("  Cache Misses: {}\n", .{self.cache_misses});
        if (self.cache_hits + self.cache_misses > 0) {
            const hit_rate = @as(f64, @floatFromInt(self.cache_hits)) /
                @as(f64, @floatFromInt(self.cache_hits +
self.cache_misses)) * 100.0;
            std.debug.print("  Hit Rate: {d:.2}%\n", .{hit_rate});
        }
        std.debug.print("  Interpreter Fallbacks: {}\n",
.{self.interpreter_fallbacks});
        if (self.hot_path_tracker.total_executions > 0) {
            std.debug.print("  Total Executions: {}\n",
.{self.hot_path_tracker.total_executions});
            std.debug.print("  Hot Paths Tracked: {}\n",
.{self.hot_path_tracker.paths_len});
        }
        if (self.total_code_size_bytes > 0) {
            const code_size_kb = @as(f64,
@floatFromInt(self.total_code_size_bytes)) / 1024.0;
            std.debug.print("  Total Code Size: {d:.2} KB\n",
.{code_size_kb});
            if (self.blocks_compiled > 0) {
                const avg_size = self.total_code_size_bytes /
self.blocks_compiled;
                std.debug.print("  Avg Code Size: {} bytes/block\n",
.{avg_size});
            }
            if (self.max_code_size_bytes > 0) {
                std.debug.print("  Max Code Size: {} bytes\n",
.{self.max_code_size_bytes});
            }
            if (self.min_code_size_bytes > 0) {
                std.debug.print("  Min Code Size: {} bytes\n",
.{self.min_code_size_bytes});
            }
        }
        if (self.total_execution_time_ns > 0) {
            const exec_ms = @as(f64,
@floatFromInt(self.total_execution_time_ns)) / 1_000_000.0;
            std.debug.print("  Total Execution Time: {d:.2} ms\n",
.{exec_ms});
        }
        if (self.jit_compile_time_ns > 0) {
            const compile_ms = @as(f64,
@floatFromInt(self.jit_compile_time_ns)) / 1_000_000.0;
            std.debug.print("  Total Compile Time: {d:.2} ms\n",
.{compile_ms});
        }
        if (self.blocks_compiled > 0 and self.jit_compile_time_ns > 0) {
            const avg_compile_ns = self.jit_compile_time_ns /
self.blocks_compiled;
            const avg_compile_us = @as(f64,
@floatFromInt(avg_compile_ns)) / 1_000.0;
            std.debug.print("  Avg Compile Time: {d:.2} us/block\n",
.{avg_compile_us});
        }
        if (self.chain_opportunities > 0) {
            std.debug.print("  Chain Opportunities: {}\n",
.{self.chain_opportunities});
            std.debug.print("  Chains Created: {}\n",
.{self.chains_created});
            if (self.chains_created > 0) {
                const chain_rate = @as(f64,
@floatFromInt(self.chains_created)) /
                    @as(f64, @floatFromInt(self.chain_opportunities)) *
100.0;
                std.debug.print("  Chain Rate: {d:.2}%\n",
.{chain_rate});
            }
            std.debug.print("  Chain Hits: {}\n", .{self.chain_hits});
        }
        if (self.blocks_invalidated > 0) {
            std.debug.print("  Blocks Invalidated: {}\n",
.{self.blocks_invalidated});
        }
        if (self.cache_invalidations > 0) {
            std.debug.print("  Cache Invalidations: {}\n",
.{self.cache_invalidations});
        }
        if (self.threshold_deferred > 0) {
            std.debug.print("  Threshold Deferred: {}\n",
.{self.threshold_deferred});
        }
    }
};

/// The Guest State represents the RISC-V CPU state in memory.
pub const GuestState = extern struct {
    regs: [32]u64 align(16), // x0-x31
    pc: u64 align(8), // Program Counter
};

/// Decoded RISC-V Instruction.
pub const Instruction = struct {
    opcode: u7,
    rd: u5,
    funct3: u3,
    rs1: u5,
    rs2: u5,
    funct7: u7,
    imm: i32, // Sign-extended immediate

    pub fn decode(raw: u32) Instruction {
        const opcode: u7 = @truncate(raw);
        const rd: u5 = @truncate(raw >> 7);
        const funct3: u3 = @truncate(raw >> 12);
        const rs1: u5 = @truncate(raw >> 15);
        const rs2: u5 = @truncate(raw >> 20);
        const funct7: u7 = @truncate(raw >> 25);

        // Assert: opcode extraction is correct (consistency check)
        std.debug.assert(opcode == @as(u7, @truncate(raw)));
        // Assert: rd extraction is correct
        std.debug.assert(rd == @as(u5, @truncate(raw >> 7)));

        // Immediate decoding
        var imm: i32 = 0;
        switch (opcode) {
            0x13, 0x03, 0x67 => { // I-Type (ADDI, LW, JALR, LogicImm)
                imm = @as(i32, @bitCast(raw)) >> 20;
            },
            0x23 => { // S-Type (SW)
                const imm_lo = (raw >> 7) & 0x1F;
                const imm_hi = (raw >> 25) & 0x7F;
                const combined = imm_lo | (imm_hi << 5);
                imm = (@as(i32, @intCast(combined)) << 20) >> 20;
            },
            0x63 => { // B-Type (BRANCH)
                const bit11 = (raw >> 7) & 0x1;
                const bits1_4 = (raw >> 8) & 0xF;
                const bits5_10 = (raw >> 25) & 0x3F;
                const bit12 = (raw >> 31) & 0x1;
                const combined = (bits1_4 << 1) | (bits5_10 << 5) |
(bit11 << 11) | (bit12 << 12);
                imm = (@as(i32, @intCast(combined)) << 19) >> 19;
            },
            0x37, 0x17 => { // U-Type (LUI, AUIPC)
                imm = @as(i32, @bitCast(raw & 0xFFFFF000));
            },
            0x6F => { // J-Type (JAL)
                const bits12_19 = (raw >> 12) & 0xFF;
                const bit11 = (raw >> 20) & 0x1;
                const bits1_10 = (raw >> 21) & 0x3FF;
                const bit20 = (raw >> 31) & 0x1;
                const combined = (bits1_10 << 1) | (bit11 << 11) |
(bits12_19 << 12) | (bit20 << 20);
                imm = (@as(i32, @intCast(combined)) << 11) >> 11;
            },
            else => {},
        }

        return Instruction{
            .opcode = opcode,
            .rd = rd,
            .funct3 = funct3,
            .rs1 = rs1,
            .rs2 = rs2,
            .funct7 = funct7,
            .imm = imm,
        };
    }
};

/// Fixup for backpatching forward jumps.
/// GrainStyle: Use explicit u32 instead of usize for code buffer offsets
const Fixup = struct {
    patch_addr: u32, // Offset in code_buffer (max 64MB, fits in u32)
    next: ?*Fixup,
};

/// The JIT Context manages the translation process.
/// GrainStyle: Use explicit u32/u64 instead of usize for cross-platform
consistency
pub const JitContext = struct {
    allocator: std.mem.Allocator,
    code_buffer: []align(16384) u8,
    cursor: u32, // Code buffer offset (max 64MB, fits in u32)
    guest_state: *GuestState,
    guest_ram: []u8,
    memory_size: u64, // VM memory size in bytes
    framebuffer_size: u32,
    perf_counters: JitPerfCounters,

    block_cache: std.AutoHashMap(u64, u32), // Maps guest PC to code
buffer offset
    pending_fixups: std.AutoHashMap(u64, *Fixup),
    compilation_threshold: u32, // Minimum executions before compiling
(0 = compile immediately)

    pub fn init(allocator: std.mem.Allocator, guest_state: *GuestState,
guest_ram: []u8, memory_size: u64) !JitContext {
        // Assert: guest RAM must be non-empty
        std.debug.assert(guest_ram.len > 0);
        // Assert: guest state must be aligned
        std.debug.assert(@intFromPtr(guest_state) % @alignOf(GuestState)
== 0);
        // Assert: guest RAM must be 4-byte aligned (for 32-bit accesses)
        std.debug.assert(@intFromPtr(guest_ram.ptr) % 4 == 0);

        const buffer_size: u32 = 64 * 1024 * 1024;
        const PROT_READ = 0x1;
        const PROT_WRITE = 0x2;
        const PROT_EXEC = 0x4;

        const ptr = try std.posix.mmap(null, buffer_size, PROT_READ |
PROT_WRITE | PROT_EXEC, .{ .TYPE = .PRIVATE, .ANONYMOUS = true, .JIT =
true }, -1, 0);

        const buffer = @as([]align(16384) u8,
@alignCast(ptr[0..buffer_size]));

        if (builtin.os.tag == .macos and builtin.cpu.arch == .aarch64) {
            pthread_jit_write_protect_np(0);
        }
        @memset(buffer, 0);
        if (builtin.os.tag == .macos and builtin.cpu.arch == .aarch64) {
            pthread_jit_write_protect_np(1);
        }

        var cache = std.AutoHashMap(u64, u32).init(allocator);
        try cache.ensureTotalCapacity(10_000);

        var fixups = std.AutoHashMap(u64, *Fixup).init(allocator);
        try fixups.ensureTotalCapacity(1000);

        // Framebuffer constants (matching VM translate_address)
        const FRAMEBUFFER_SIZE: u32 = 1024 * 768 * 4; // 3MB
        
        // Assert: memory_size must be large enough for framebuffer
        std.debug.assert(memory_size >= FRAMEBUFFER_SIZE);

        const self = JitContext{
            .allocator = allocator,
            .code_buffer = buffer,
            .cursor = 0,
            .guest_state = guest_state,
            .guest_ram = guest_ram,
            .memory_size = memory_size,
            .framebuffer_size = FRAMEBUFFER_SIZE,
            .perf_counters = .{
                .hot_path_tracker = HotPathTracker.init(),
                .total_code_size_bytes = 0,
                .max_code_size_bytes = 0,
                .min_code_size_bytes = 0,
            },
            .block_cache = cache,
            .pending_fixups = fixups,
        };
        
        // Assert: JIT context must be initialized correctly
        std.debug.assert(self.memory_size == memory_size);
        std.debug.assert(self.framebuffer_size == FRAMEBUFFER_SIZE);

        self.verify_integrity();
        return self;
    }

    pub fn deinit(self: *JitContext) void {
        // Assert: code buffer must be valid
        std.debug.assert(self.code_buffer.len > 0);
        // Assert: cursor must be within bounds
        std.debug.assert(self.cursor <= self.code_buffer.len);
        
        std.posix.munmap(self.code_buffer);
        self.block_cache.deinit();
        self.pending_fixups.deinit();
    }

    pub fn verify_integrity(self: *const JitContext) void {
        std.debug.assert(self.cursor <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
    }

    pub fn protect_code(self: *JitContext) void {
        // Assert: code buffer must be valid
        std.debug.assert(self.code_buffer.len > 0);
        // Assert: cursor must be within bounds
        std.debug.assert(self.cursor <= self.code_buffer.len);
        
        if (builtin.os.tag == .macos and builtin.cpu.arch == .aarch64) {
            pthread_jit_write_protect_np(1);
        }
    }

    pub fn unprotect_code(self: *JitContext) void {
        // Assert: code buffer must be valid
        std.debug.assert(self.code_buffer.len > 0);
        // Assert: cursor must be within bounds
        std.debug.assert(self.cursor <= self.code_buffer.len);

        if (builtin.os.tag == .macos and builtin.cpu.arch == .aarch64) {
            pthread_jit_write_protect_np(0);
        }
    }

    /// GrainStyle: Use explicit u32 instead of usize for code buffer
offsets
    pub fn flush_cache(self: *JitContext, start_offset: u32, len: u32)
void {
        // Assert: start offset must be within bounds
        std.debug.assert(start_offset < self.code_buffer.len);
        // Assert: end offset must be within bounds
        std.debug.assert(start_offset + len <= self.code_buffer.len);
        
        // Instruction cache flushing is usually automatic on Apple
Silicon for JIT memory,
        // but we keep the hook for correctness and portability.
    }

    // --- Emitters ---

    fn emit_u32(self: *JitContext, inst: u32) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        std.mem.writeInt(u32, self.code_buffer[self.cursor..][0..4],
inst, .little);
        self.cursor += 4;
        std.debug.assert(self.cursor == start_cursor + 4);
    }

    pub fn emit_add(self: *JitContext, rd: u5, rn: u5, rm: u5) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        const opcode: u32 = 0x8B000000;
        const inst = opcode | (@as(u32, rm) << 16) | (@as(u32, rn) << 5)
| @as(u32, rd);
        self.emit_u32(inst);
        std.debug.assert(self.cursor == start_cursor + 4);
        std.debug.assert(self.cursor <= self.code_buffer.len);
    }

    pub fn emit_subs(self: *JitContext, rd: u5, rn: u5, rm: u5) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        const opcode: u32 = 0xEB000000;
        const inst = opcode | (@as(u32, rm) << 16) | (@as(u32, rn) << 5)
| @as(u32, rd);
        self.emit_u32(inst);
        std.debug.assert(self.cursor == start_cursor + 4);
        std.debug.assert(self.cursor <= self.code_buffer.len);
    }

    /// Emit conditional set instruction (cset).
    /// Why: Set register to 1 if condition is true, else 0.
    /// Contract: Sets rd to 1 if condition is true, 0 otherwise.
    /// GrainStyle: Explicit condition codes, deterministic behavior.
    pub fn emit_cset(self: *JitContext, rd: u5, cond: u4) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        std.debug.assert(cond < 16); // Valid condition code
        const start_cursor = self.cursor;
        const opcode: u32 = 0x1A800000;
        const inst = opcode | (@as(u32, cond) << 12) | @as(u32, rd);
        self.emit_u32(inst);
        std.debug.assert(self.cursor == start_cursor + 4);
        std.debug.assert(self.cursor <= self.code_buffer.len);
    }

    /// Emit compare instruction (cmp).
    /// Why: Compare two registers and set flags.
    /// Contract: Compares rn and rm, sets condition flags.
    /// GrainStyle: Uses subs to set flags, deterministic behavior.
    pub fn emit_cmp(self: *JitContext, rn: u5, rm: u5) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        // Use xzr (register 31) as destination (discard result, only
set flags).
        const xzr: u5 = 31;
        self.emit_subs(xzr, rn, rm);
    }

    pub fn emit_mov_imm(self: *JitContext, rd: u5, imm: u16) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        const opcode: u32 = 0xD2800000;
        const inst = opcode | (@as(u32, imm) << 5) | @as(u32, rd);
        self.emit_u32(inst);
        std.debug.assert(self.cursor == start_cursor + 4);
        std.debug.assert(self.cursor <= self.code_buffer.len);
    }

    pub fn emit_mov_u64(self: *JitContext, rd: u5, val: u64) void {
        std.debug.assert(self.cursor + 16 <= self.code_buffer.len); //
Max 4 instructions
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        const imm0: u16 = @truncate(val);
        self.emit_mov_imm(rd, imm0);
        const imm1: u16 = @truncate(val >> 16);
        if (imm1 != 0) self.emit_movk(rd, imm1, 1);
        const imm2: u16 = @truncate(val >> 32);
        if (imm2 != 0) self.emit_movk(rd, imm2, 2);
        const imm3: u16 = @truncate(val >> 48);
        if (imm3 != 0) self.emit_movk(rd, imm3, 3);
        std.debug.assert(self.cursor >= start_cursor + 4); // At least 1
instruction
        std.debug.assert(self.cursor <= start_cursor + 16); // At most 4
instructions
    }

    fn emit_movk(self: *JitContext, rd: u5, imm: u16, shift_idx: u2)
void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        const opcode: u32 = 0xF2800000;
        const inst = opcode | (@as(u32, shift_idx) << 21) | (@as(u32,
imm) << 5) | @as(u32, rd);
        self.emit_u32(inst);
        std.debug.assert(self.cursor == start_cursor + 4);
        std.debug.assert(self.cursor <= self.code_buffer.len);
    }

    pub fn emit_ret(self: *JitContext) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        self.emit_u32(0xD65F03C0);
        std.debug.assert(self.cursor == start_cursor + 4);
        std.debug.assert(self.cursor <= self.code_buffer.len);
    }

    /// Emit call to target function (bl instruction).
    /// Why: Enable block chaining by calling next block directly.
    /// Contract: Calls target function with guest_state as argument.
    /// GrainStyle: Explicit function pointer, deterministic call.
    pub fn emit_call_target(self: *JitContext, target_func: *const fn
(*GuestState) callconv(.c) void) void {
        std.debug.assert(self.cursor + 16 <= self.code_buffer.len); //
Max 4 instructions for 64-bit address
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        
        // Load target function address into x16 (IP0, caller-saved).
        const target_addr = @intFromPtr(target_func);
        self.emit_mov_u64(16, target_addr);
        
        // Call target function: blr x16 (branch with link to register).
        const blr_inst: u32 = 0xD63F0200 | (@as(u32, 16) << 5);
        self.emit_u32(blr_inst);
        
        std.debug.assert(self.cursor >= start_cursor + 4);
        std.debug.assert(self.cursor <= start_cursor + 20); // At most 5
instructions
    }

    pub fn emit_b(self: *JitContext, offset: i28) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        const imm26: u32 = @as(u32, @bitCast(@as(i32, @intCast(offset >>
2)))) & 0x03FFFFFF;
        const inst = 0x14000000 | imm26;
        self.emit_u32(inst);
        std.debug.assert(self.cursor == start_cursor + 4);
        std.debug.assert(self.cursor <= self.code_buffer.len);
    }

    pub fn emit_b_cond(self: *JitContext, cond: u4, offset: i19) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        const imm19: u32 = @as(u32, @bitCast(@as(i32, @intCast(offset >>
2)))) & 0x7FFFF;
        const inst = 0x54000000 | (imm19 << 5) | @as(u32, cond);
        self.emit_u32(inst);
        std.debug.assert(self.cursor == start_cursor + 4);
        std.debug.assert(self.cursor <= self.code_buffer.len);
    }

    pub fn emit_br(self: *JitContext, rn: u5) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        const inst = 0xD61F0000 | (@as(u32, rn) << 5);
        self.emit_u32(inst);
        std.debug.assert(self.cursor == start_cursor + 4);
        std.debug.assert(self.cursor <= self.code_buffer.len);
    }

