    pub fn emit_ldr_reg(self: *JitContext, rt: u5, rn: u5, rm: u5, size:
u2, signed: bool) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        var inst: u32 = 0x38206800;
        const opc: u32 = if (signed) 0x2 else 0x1;
        inst |= (opc << 22);
        inst |= (@as(u32, size) << 30);
        inst |= (@as(u32, rm) << 16);
        inst |= (@as(u32, rn) << 5);
        inst |= @as(u32, rt);
        self.emit_u32(inst);
        std.debug.assert(self.cursor == start_cursor + 4);
        std.debug.assert(self.cursor <= self.code_buffer.len);
    }

    pub fn emit_str_reg(self: *JitContext, rt: u5, rn: u5, rm: u5, size:
u2) void {
        std.debug.assert(self.cursor + 4 <= self.code_buffer.len);
        std.debug.assert(self.cursor % 4 == 0);
        const start_cursor = self.cursor;
        var inst: u32 = 0x38206800;
        inst |= (@as(u32, size) << 30);
        inst |= (@as(u32, rm) << 16);
        inst |= (@as(u32, rn) << 5);
        inst |= @as(u32, rt);
        self.emit_u32(inst);
        std.debug.assert(self.cursor == start_cursor + 4);
        std.debug.assert(self.cursor <= self.code_buffer.len);
    }

    /// Emit address translation code
    /// Why: Translate guest virtual address to physical offset in VM
memory
    /// Contract: Takes guest address in addr_reg, outputs physical
offset in same register
    /// GrainStyle: Explicit bounds checking, deterministic translation
    /// Address translation logic:
    ///   - 0x90000000+: Framebuffer -> offset = memory_size -
framebuffer_size + (addr - 0x90000000)
    ///   - 0x80000000+: Kernel -> offset = addr - 0x80000000
    ///   - Otherwise: Direct mapping -> offset = addr
    fn emit_translate_address(self: *JitContext, addr_reg: u5) void {
        // Assert: addr_reg must be valid (0-31)
        std.debug.assert(addr_reg < 32);
        
        // Use x4, x5, x6 as temporary registers (x27=mem_base,
x28=guest_state are reserved)
        const tmp1: u5 = 4;
        const tmp2: u5 = 5;
        const tmp3: u5 = 6;
        
        const KERNEL_BASE: u64 = 0x80000000;
        const FRAMEBUFFER_BASE: u64 = 0x90000000;
        
        // Check if address >= FRAMEBUFFER_BASE (0x90000000)
        self.emit_mov_u64(tmp1, FRAMEBUFFER_BASE);
        self.emit_subs(tmp2, addr_reg, tmp1); // tmp2 = addr -
0x90000000, sets flags
        // If addr >= 0x90000000, carry flag is set (unsigned >=)
        
        // Branch to framebuffer translation if addr >= 0x90000000
        self.emit_b_cond(0x2, 0); // HS (unsigned >=), will patch later
        const framebuffer_patch_pos: u32 = self.cursor - 4;
        
        // Check if address >= KERNEL_BASE (0x80000000)
        self.emit_mov_u64(tmp1, KERNEL_BASE);
        self.emit_subs(tmp3, addr_reg, tmp1); // tmp3 = addr -
0x80000000, sets flags (use tmp3 to preserve tmp2)
        
        // Branch to kernel translation if addr >= 0x80000000
        self.emit_b_cond(0x2, 0); // HS (unsigned >=), will patch later
        const kernel_patch_pos: u32 = self.cursor - 4;
        
        // Low memory: direct mapping (addr_reg already contains offset)
        self.emit_b(0); // Will patch later
        const done_patch_pos: u32 = self.cursor - 4;
        
        // Framebuffer translation: offset = memory_size -
framebuffer_size + (addr - 0x90000000)
        // At this point: addr_reg = guest_addr, tmp2 = addr - 0x90000000
        const framebuffer_code_start: u32 = self.cursor;
        self.emit_mov_u64(tmp1, @as(u64, self.memory_size));
        self.emit_mov_u64(tmp3, @as(u64, self.framebuffer_size));
        self.emit_subs(tmp1, tmp1, tmp3); // tmp1 = memory_size -
framebuffer_size
        self.emit_add(addr_reg, tmp1, tmp2); // addr_reg = (memory_size
- framebuffer_size) + (addr - 0x90000000)
        self.emit_b(0); // Jump to done, will patch later
        const framebuffer_done_patch: u32 = self.cursor - 4;
        
        // Kernel translation: offset = addr - 0x80000000
        // At this point: addr_reg = guest_addr, tmp3 = addr - 0x80000000
        const kernel_code_start: u32 = self.cursor;
        self.emit_mov(addr_reg, tmp3); // addr_reg = addr - 0x80000000
        self.emit_b(0); // Jump to done, will patch later
        const kernel_done_patch: u32 = self.cursor - 4;
        
        // Done label
        const done_code_start: u32 = self.cursor;
        
        // Patch branch offsets
        // GrainStyle: Use explicit u32 for offsets, cast to i19/i28 for
branch instructions
        // Framebuffer branch: from framebuffer_patch_pos to
framebuffer_code_start
        const framebuffer_diff: i32 = @as(i32,
@intCast(framebuffer_code_start)) - @as(i32,
@intCast(framebuffer_patch_pos));
        const framebuffer_offset = @as(i19, @intCast(framebuffer_diff >>
2));
        self.patch_b_cond(framebuffer_patch_pos, framebuffer_offset);
        
        // Kernel branch: from kernel_patch_pos to kernel_code_start
        const kernel_diff: i32 = @as(i32, @intCast(kernel_code_start)) -
@as(i32, @intCast(kernel_patch_pos));
        const kernel_offset = @as(i19, @intCast(kernel_diff >> 2));
        self.patch_b_cond(kernel_patch_pos, kernel_offset);
        
        // Done branch: from done_patch_pos to done_code_start
        const done_diff: i32 = @as(i32, @intCast(done_code_start)) -
@as(i32, @intCast(done_patch_pos));
        const done_offset = @as(i28, @intCast(done_diff >> 2));
        self.patch_b(done_patch_pos, done_offset);
        
        // Framebuffer done branch: from framebuffer_done_patch to
done_code_start
        const framebuffer_done_diff: i32 = @as(i32,
@intCast(done_code_start)) - @as(i32, @intCast(framebuffer_done_patch));
        const framebuffer_done_offset = @as(i28,
@intCast(framebuffer_done_diff >> 2));
        self.patch_b(framebuffer_done_patch, framebuffer_done_offset);
        
        // Kernel done branch: from kernel_done_patch to done_code_start
        const kernel_done_diff: i32 = @as(i32,
@intCast(done_code_start)) - @as(i32, @intCast(kernel_done_patch));
        const kernel_done_offset = @as(i28, @intCast(kernel_done_diff >>
2));
        self.patch_b(kernel_done_patch, kernel_done_offset);
    }
    
    /// Patch B instruction at position
    /// GrainStyle: Use explicit u32 instead of usize for code buffer
offsets
    fn patch_b(self: *JitContext, pos: u32, offset: i28) void {
        std.debug.assert(pos + 4 <= self.code_buffer.len);
        const existing = std.mem.readInt(u32,
self.code_buffer[pos..][0..4], .little);
        const imm26: u32 = @as(u32, @intCast(offset)) & 0x03FFFFFF;
        const inst = (existing & 0xFC000000) | imm26;
        std.mem.writeInt(u32, self.code_buffer[pos..][0..4], inst,
.little);
    }
    
    /// Patch B.cond instruction at position
    /// GrainStyle: Use explicit u32 instead of usize for code buffer
offsets
    fn patch_b_cond(self: *JitContext, pos: u32, offset: i19) void {
        std.debug.assert(pos + 4 <= self.code_buffer.len);
        const existing = std.mem.readInt(u32,
self.code_buffer[pos..][0..4], .little);
        const imm19: u32 = @as(u32, @intCast(offset)) & 0x7FFFF;
        const cond = existing & 0xF;
        const inst = 0x54000000 | (imm19 << 5) | cond;
        std.mem.writeInt(u32, self.code_buffer[pos..][0..4], inst,
.little);
    }
    
    /// Emit MOV (register to register)
    fn emit_mov(self: *JitContext, rd: u5, rn: u5) void {
        self.emit_add(rd, rn, 0); // MOV is ADD with zero
    }

    // --- Translation Logic ---

    // RVC Expansion: Convert 16-bit compressed instructions to 32-bit
standard form
    fn expand_rvc(raw16: u16) ?u32 {
        const opcode: u2 = @truncate(raw16 & 0x3);
        const funct3: u3 = @truncate(raw16 >> 13);

        return switch (opcode) {
            0x0 => expand_rvc_q0(raw16, funct3),
            0x1 => expand_rvc_q1(raw16, funct3),
            0x2 => expand_rvc_q2(raw16, funct3),
            0x3 => null, // Not a compressed instruction
        };
    }

    fn expand_rvc_q0(raw16: u16, funct3: u3) ?u32 {
        return switch (funct3) {
            0x0 => expand_c_addi4spn(raw16),
            0x2 => expand_c_lw(raw16),
            0x6 => expand_c_sw(raw16),
            else => null,
        };
    }

    fn expand_rvc_q1(raw16: u16, funct3: u3) ?u32 {
        return switch (funct3) {
            0x0 => expand_c_addi(raw16),
            0x1 => expand_c_jal(raw16),
            0x2 => expand_c_li(raw16),
            0x3 => expand_c_addi16sp_lui(raw16),
            0x4 => expand_c_misc_alu(raw16),
            0x5 => expand_c_j(raw16),
            0x6 => expand_c_beqz(raw16),
            0x7 => expand_c_bnez(raw16),
        };
    }

    fn expand_rvc_q2(raw16: u16, funct3: u3) ?u32 {
        return switch (funct3) {
            0x0 => expand_c_slli(raw16),
            0x2 => expand_c_lwsp(raw16),
            0x4 => expand_c_jr_mv_add(raw16),
            0x6 => expand_c_swsp(raw16),
            else => null,
        };
    }

    // C.ADDI4SPN: addi rd', x2, nzuimm
    fn expand_c_addi4spn(raw16: u16) ?u32 {
        const nzuimm = ((raw16 >> 7) & 0x30) | ((raw16 >> 1) & 0x3C0) |
            ((raw16 >> 4) & 0x4) | ((raw16 >> 2) & 0x8);
        if (nzuimm == 0) return null;
        const rd_p: u5 = @truncate((raw16 >> 2) & 0x7);
        const rd = rd_p + 8;
        return 0x00010013 | (@as(u32, rd) << 7) | (@as(u32, nzuimm) <<
20);
    }

    // C.LW: lw rd', offset(rs1')
    fn expand_c_lw(raw16: u16) ?u32 {
        const rd_p: u5 = @truncate((raw16 >> 2) & 0x7);
        const rs1_p: u5 = @truncate((raw16 >> 7) & 0x7);
        const offset = ((raw16 >> 7) & 0x38) | ((raw16 >> 4) & 0x4) |
((raw16 << 1) & 0x40);
        const rd = rd_p + 8;
        const rs1 = rs1_p + 8;
        return 0x00002003 | (@as(u32, rd) << 7) | (@as(u32, rs1) << 15)
| (@as(u32, offset) << 20);
    }

    // C.SW: sw rs2', offset(rs1')
    fn expand_c_sw(raw16: u16) ?u32 {
        const rs2_p: u5 = @truncate((raw16 >> 2) & 0x7);
        const rs1_p: u5 = @truncate((raw16 >> 7) & 0x7);
        const offset = ((raw16 >> 7) & 0x38) | ((raw16 >> 4) & 0x4) |
((raw16 << 1) & 0x40);
        const rs2 = rs2_p + 8;
        const rs1 = rs1_p + 8;
        const imm_11_5 = (offset >> 5) & 0x7F;
        const imm_4_0 = offset & 0x1F;
        return 0x00002023 | (@as(u32, imm_4_0) << 7) | (@as(u32, rs1) <<
15) |
            (@as(u32, rs2) << 20) | (@as(u32, imm_11_5) << 25);
    }

    // C.ADDI: addi rd, rd, nzimm
    fn expand_c_addi(raw16: u16) ?u32 {
        const rd: u5 = @truncate((raw16 >> 7) & 0x1F);
        if (rd == 0) return 0x00000013; // C.NOP
        const nzimm = ((raw16 >> 7) & 0x20) | ((raw16 >> 2) & 0x1F);
        const imm = if ((nzimm & 0x20) != 0) @as(u32, nzimm) |
0xFFFFFFC0 else @as(u32, nzimm);
        return 0x00000013 | (@as(u32, rd) << 7) | (@as(u32, rd) << 15) |
(@as(u32, imm) << 20);
    }

    // C.JAL: jal x1, offset (RV32 only, RV64 uses C.ADDIW)
    fn expand_c_jal(raw16: u16) ?u32 {
        const offset = ((raw16 >> 1) & 0x800) | ((raw16 >> 7) & 0x10) |
            ((raw16 >> 1) & 0x300) | ((raw16 << 2) & 0x400) |
            ((raw16 >> 1) & 0x40) | ((raw16 << 1) & 0x80) |
            ((raw16 >> 2) & 0xE) | ((raw16 << 3) & 0x20);
        const imm = if ((offset & 0x800) != 0) @as(u32, offset) |
0xFFFFF000 else @as(u32, offset);
        return 0x0000006F | (1 << 7) | (@as(u32, imm) & 0xFFFFF000);
    }

    // C.LI: addi rd, x0, imm
    fn expand_c_li(raw16: u16) ?u32 {
        const rd: u5 = @truncate((raw16 >> 7) & 0x1F);
        const imm_raw = ((raw16 >> 7) & 0x20) | ((raw16 >> 2) & 0x1F);
        const imm = if ((imm_raw & 0x20) != 0) @as(u32, imm_raw) |
0xFFFFFFC0 else @as(u32, imm_raw);
        return 0x00000013 | (@as(u32, rd) << 7) | (@as(u32, imm) << 20);
    }

    // C.ADDI16SP / C.LUI
    fn expand_c_addi16sp_lui(raw16: u16) ?u32 {
        const rd: u5 = @truncate((raw16 >> 7) & 0x1F);
        if (rd == 2) {
            // C.ADDI16SP
            const nzimm = ((raw16 >> 3) & 0x200) | ((raw16 >> 2) & 0x10)
|
                ((raw16 << 1) & 0x40) | ((raw16 << 4) & 0x180) | ((raw16
<< 3) & 0x20);
            if (nzimm == 0) return null;
            const imm = if ((nzimm & 0x200) != 0) @as(u32, nzimm) |
0xFFFFFC00 else @as(u32, nzimm);
            return 0x00010013 | (2 << 7) | (2 << 15) | (@as(u32, imm) <<
20);
        } else {
            // C.LUI
            const nzimm = ((raw16 >> 7) & 0x20) | ((raw16 >> 2) & 0x1F);
            if (nzimm == 0) return null;
            const imm = if ((nzimm & 0x20) != 0) @as(u32, nzimm) |
0xFFFFFFC0 else @as(u32, nzimm);
            return 0x00000037 | (@as(u32, rd) << 7) | ((@as(u32, imm) &
0x3F) << 12);
        }
    }

    // C.MISC-ALU: SRLI, SRAI, ANDI, SUB, XOR, OR, AND
    fn expand_c_misc_alu(raw16: u16) ?u32 {
        const rd_p: u5 = @truncate((raw16 >> 7) & 0x7);
        const rd = rd_p + 8;
        const funct2 = (raw16 >> 10) & 0x3;

        if (funct2 < 3) {
            const shamt = ((raw16 >> 7) & 0x20) | ((raw16 >> 2) & 0x1F);
            return switch (funct2) {
                0 => 0x00005013 | (@as(u32, rd) << 7) | (@as(u32, rd) <<
15) | (@as(u32, shamt) << 20),
                1 => 0x40005013 | (@as(u32, rd) << 7) | (@as(u32, rd) <<
15) | (@as(u32, shamt) << 20),
                2 => blk: {
                    const imm_raw = ((raw16 >> 7) & 0x20) | ((raw16 >>
2) & 0x1F);
                    const imm = if ((imm_raw & 0x20) != 0) @as(u32,
imm_raw) | 0xFFFFFFC0 else @as(u32, imm_raw);
                    break :blk 0x00007013 | (@as(u32, rd) << 7) |
(@as(u32, rd) << 15) | (@as(u32, imm) << 20);
                },
                else => null,
            };
        } else {
            const rs2_p: u5 = @truncate((raw16 >> 2) & 0x7);
            const rs2 = rs2_p + 8;
            const funct6 = (raw16 >> 10) & 0x3;
            const bit5 = (raw16 >> 12) & 0x1;
            const op = (funct6 << 1) | bit5;
            return switch (op) {
                0x3 => 0x40000033 | (@as(u32, rd) << 7) | (@as(u32, rd)
<< 15) | (@as(u32, rs2) << 20),
                0x4 => 0x00004033 | (@as(u32, rd) << 7) | (@as(u32, rd)
<< 15) | (@as(u32, rs2) << 20),
                0x5 => 0x00006033 | (@as(u32, rd) << 7) | (@as(u32, rd)
<< 15) | (@as(u32, rs2) << 20),
                0x6 => 0x00007033 | (@as(u32, rd) << 7) | (@as(u32, rd)
<< 15) | (@as(u32, rs2) << 20),
                else => null,
            };
        }
    }

    // C.J: jal x0, offset
    fn expand_c_j(raw16: u16) ?u32 {
        const offset = ((raw16 >> 1) & 0x800) | ((raw16 >> 7) & 0x10) |
            ((raw16 >> 1) & 0x300) | ((raw16 << 2) & 0x400) |
            ((raw16 >> 1) & 0x40) | ((raw16 << 1) & 0x80) |
            ((raw16 >> 2) & 0xE) | ((raw16 << 3) & 0x20);
        const imm = if ((offset & 0x800) != 0) @as(u32, offset) |
0xFFFFF000 else @as(u32, offset);
        return 0x0000006F | (@as(u32, imm) & 0xFFFFF000);
    }

    // C.BEQZ: beq rs1', x0, offset
    fn expand_c_beqz(raw16: u16) ?u32 {
        const rs1_p: u5 = @truncate((raw16 >> 7) & 0x7);
        const rs1 = rs1_p + 8;
        const offset = ((raw16 >> 4) & 0x100) | ((raw16 >> 7) & 0x18) |
            ((raw16 << 1) & 0xC0) | ((raw16 >> 2) & 0x6) | ((raw16 << 3)
& 0x20);
        const imm = if ((offset & 0x100) != 0) @as(u32, offset) |
0xFFFFFE00 else @as(u32, offset);
        const imm_12 = (imm >> 12) & 0x1;
        const imm_10_5 = (imm >> 5) & 0x3F;
        const imm_4_1 = (imm >> 1) & 0xF;
        const imm_11 = (imm >> 11) & 0x1;
        return 0x00000063 | (@as(u32, rs1) << 15) | (@as(u32, imm_11) <<
7) |
            (@as(u32, imm_4_1) << 8) | (@as(u32, imm_10_5) << 25) |
(@as(u32, imm_12) << 31);
    }

    // C.BNEZ: bne rs1', x0, offset
    fn expand_c_bnez(raw16: u16) ?u32 {
        const rs1_p: u5 = @truncate((raw16 >> 7) & 0x7);
        const rs1 = rs1_p + 8;
        const offset = ((raw16 >> 4) & 0x100) | ((raw16 >> 7) & 0x18) |
            ((raw16 << 1) & 0xC0) | ((raw16 >> 2) & 0x6) | ((raw16 << 3)
& 0x20);
        const imm = if ((offset & 0x100) != 0) @as(u32, offset) |
0xFFFFFE00 else @as(u32, offset);
        const imm_12 = (imm >> 12) & 0x1;
        const imm_10_5 = (imm >> 5) & 0x3F;
        const imm_4_1 = (imm >> 1) & 0xF;
        const imm_11 = (imm >> 11) & 0x1;
        return 0x00001063 | (@as(u32, rs1) << 15) | (@as(u32, imm_11) <<
7) |
            (@as(u32, imm_4_1) << 8) | (@as(u32, imm_10_5) << 25) |
(@as(u32, imm_12) << 31);
    }

    // C.SLLI: slli rd, rd, shamt
    fn expand_c_slli(raw16: u16) ?u32 {
        const rd: u5 = @truncate((raw16 >> 7) & 0x1F);
        if (rd == 0) return null;
        const shamt = ((raw16 >> 7) & 0x20) | ((raw16 >> 2) & 0x1F);
        return 0x00001013 | (@as(u32, rd) << 7) | (@as(u32, rd) << 15) |
(@as(u32, shamt) << 20);
    }

    // C.LWSP: lw rd, offset(x2)
    fn expand_c_lwsp(raw16: u16) ?u32 {
        const rd: u5 = @truncate((raw16 >> 7) & 0x1F);
        if (rd == 0) return null;
        const offset = ((raw16 >> 7) & 0x20) | ((raw16 >> 2) & 0x1C) |
((raw16 << 4) & 0xC0);
        return 0x00002003 | (@as(u32, rd) << 7) | (2 << 15) | (@as(u32,
offset) << 20);
    }

    // C.JR / C.MV / C.JALR / C.ADD
    fn expand_c_jr_mv_add(raw16: u16) ?u32 {
        const rs1: u5 = @truncate((raw16 >> 7) & 0x1F);
        const rs2: u5 = @truncate((raw16 >> 2) & 0x1F);
        const bit12 = (raw16 >> 12) & 0x1;

        if (bit12 == 0) {
            if (rs2 == 0) {
                // C.JR
                if (rs1 == 0) return null;
                return 0x00000067 | (@as(u32, rs1) << 15);
            } else {
                // C.MV
                return 0x00000033 | (@as(u32, rs1) << 7) | (@as(u32,
rs2) << 20);
            }
        } else {
            if (rs2 == 0) {
                // C.JALR
                if (rs1 == 0) return null;
                return 0x000000E7 | (1 << 7) | (@as(u32, rs1) << 15);
            } else {
                // C.ADD
                return 0x00000033 | (@as(u32, rs1) << 7) | (@as(u32,
rs1) << 15) | (@as(u32, rs2) << 20);
            }
        }
    }

    // C.SWSP: sw rs2, offset(x2)
    fn expand_c_swsp(raw16: u16) ?u32 {
        const rs2: u5 = @truncate((raw16 >> 2) & 0x1F);
        const offset = ((raw16 >> 7) & 0x3C) | ((raw16 >> 1) & 0xC0);
        const imm_11_5 = (offset >> 5) & 0x7F;
        const imm_4_0 = offset & 0x1F;
        return 0x00002023 | (@as(u32, imm_4_0) << 7) | (2 << 15) |
            (@as(u32, rs2) << 20) | (@as(u32, imm_11_5) << 25);
    }

    const FetchResult = struct {
        inst: u32,
        len: u8,
    };

    fn fetch_inst(self: *JitContext, pc: u64) !FetchResult {
        if (pc >= 0x80000000 and pc < 0x80000000 + self.guest_ram.len) {
            const offset = pc - 0x80000000;
            if (offset + 2 > self.guest_ram.len) return
error.BufferOverflow;

            const raw16 = std.mem.readInt(u16,
self.guest_ram[offset..][0..2], .little);

            // Check if compressed (bits [1:0] != 0b11)
            if ((raw16 & 0x3) != 0x3) {
                if (expand_rvc(raw16)) |expanded| {
                    return .{ .inst = expanded, .len = 2 };
                }
                return error.InvalidInstruction;
            }

            // Standard 32-bit instruction
            if (offset + 4 > self.guest_ram.len) return
error.BufferOverflow;
            const raw32 = std.mem.readInt(u32,
self.guest_ram[offset..][0..4], .little);
            return .{ .inst = raw32, .len = 4 };
        }
        return error.InvalidInstruction;
    }

    /// GrainStyle: Use explicit u32 instead of usize for code buffer
offsets
    fn record_fixup(self: *JitContext, target_pc: u64, patch_offset:
u32) !void {
        const fixup = try self.allocator.create(Fixup);
        fixup.* = .{ .patch_addr = patch_offset, .next = null };

        if (self.pending_fixups.getPtr(target_pc)) |head_ptr| {
            fixup.next = head_ptr.*;
            head_ptr.* = fixup;
        } else {
            try self.pending_fixups.put(target_pc, fixup);
        }
    }

    /// Invalidate a compiled block, forcing recompilation.
    /// Why: Support self-modifying code, debugging, and code updates.
    /// Contract: Removes block from cache, allowing recompilation on
next access.
    /// GrainStyle: Explicit invalidation, deterministic behavior.
    pub fn invalidate_block(self: *JitContext, guest_pc: u64) void {
        std.debug.assert(guest_pc > 0);
        if (self.block_cache.remove(guest_pc)) {
            self.perf_counters.blocks_invalidated += 1;
        }
    }

    /// Invalidate all compiled blocks, forcing full recompilation.
    /// Why: Support major code changes or debugging scenarios.
    /// Contract: Clears entire block cache.
    /// GrainStyle: Explicit bulk invalidation, deterministic behavior.
    pub fn invalidate_all_blocks(self: *JitContext) void {
        const count = self.block_cache.count();
        self.block_cache.clearRetainingCapacity();
        if (count > 0) {
            self.perf_counters.cache_invalidations += 1;
            self.perf_counters.blocks_invalidated += @intCast(count);
        }
    }

    /// Check if a block should be compiled based on execution threshold.
    /// Why: Only compile frequently executed blocks to reduce
compilation overhead.
    /// Contract: Returns true if block should be compiled, false if
threshold not met.
    /// GrainStyle: Explicit threshold checking, deterministic behavior.
    fn should_compile_block(self: *const JitContext, guest_pc: u64) bool
{
        std.debug.assert(guest_pc > 0);
        // If threshold is 0, compile immediately (threshold disabled).
        if (self.compilation_threshold == 0) {
            return true;
        }
        // Check execution count in hot path tracker.
        if
(self.perf_counters.hot_path_tracker.find_path_index(guest_pc)) |idx| {
            const execution_count =
self.perf_counters.hot_path_tracker.paths[idx].execution_count;
            return execution_count >= self.compilation_threshold;
        }
        // Block not tracked yet: don't compile (threshold not met).
        return false;
    }

    /// Set compilation threshold (minimum executions before compiling).
    /// Why: Control when blocks are compiled to balance compilation
cost vs execution speed.
    /// Contract: 0 = compile immediately, >0 = compile after N
executions.
    /// GrainStyle: Explicit threshold configuration, deterministic
behavior.
    pub fn set_compilation_threshold(self: *JitContext, threshold: u32)
void {
        self.compilation_threshold = threshold;
    }

    pub fn compile_block(self: *JitContext, guest_pc: u64) !*const fn
(*GuestState) callconv(.c) void {
        self.unprotect_code();
        defer self.protect_code();

        const start_offset: u32 = self.cursor;
        var current_pc = guest_pc;
        var instructions_in_block: u32 = 0;

        if (self.block_cache.get(guest_pc)) |addr| {
            // Cache hit: return existing compiled block.
            self.perf_counters.cache_hits += 1;
            return @ptrCast(@alignCast(@as(*const anyopaque,
@ptrFromInt(@intFromPtr(self.code_buffer.ptr) + @as(usize, addr)))));
        }

        // Check compilation threshold before compiling.
        if (!self.should_compile_block(guest_pc)) {
            // Threshold not met: track deferral and return error.
            self.perf_counters.threshold_deferred += 1;
            return error.ThresholdNotMet;
        }

        // Cache miss: compile new block.
        self.perf_counters.cache_misses += 1;
        self.apply_fixups(guest_pc, start_offset);

        while (true) {
            const fetch_result = try self.fetch_inst(current_pc);
            const inst = Instruction.decode(fetch_result.inst);

            switch (inst.opcode) {
                0x33 => { // ADD, SUB, SLL, SLT, SLTU, XOR, SRL, SRA,
OR, AND (R-Type)
                    self.emit_ldr_from_state(0, inst.rs1);
                    self.emit_ldr_from_state(1, inst.rs2);

                    switch (inst.funct3) {
                        0x0 => { // ADD/SUB
                            if (inst.funct7 == 0x00) { // ADD
                                self.emit_add(0, 0, 1);
                            } else if (inst.funct7 == 0x20) { // SUB
                                self.emit_subs(0, 0, 1);
                            }
                        },
                        0x1 => self.emit_lsl_v(0, 0, 1), // SLL
                        0x4 => self.emit_eor(0, 0, 1), // XOR
                        0x5 => { // SRL/SRA
                            if (inst.funct7 == 0x00) { // SRL
                                self.emit_lsr_v(0, 0, 1);
                            } else if (inst.funct7 == 0x20) { // SRA
                                self.emit_asr_v(0, 0, 1);
                            }
                        },
                        0x2 => { // SLT (Set Less Than, signed)
                            self.emit_cmp(0, 1); // Compare rs1 (reg 0)
with rs2 (reg 1)
                            self.emit_cset(0, 0xB); // Set reg 0 to 1 if
LT (signed less than), else 0
                        },
                        0x3 => { // SLTU (Set Less Than Unsigned)
                            self.emit_cmp(0, 1); // Compare rs1 (reg 0)
with rs2 (reg 1)
                            self.emit_cset(0, 0x3); // Set reg 0 to 1 if
LO (unsigned less than), else 0
                        },
                        0x6 => self.emit_orr(0, 0, 1), // OR
                        0x7 => self.emit_and(0, 0, 1), // AND
                        else => {},
                    }
                    self.emit_str_to_state(0, inst.rd);
                },
                0x13 => { // ADDI, SLTI, SLTIU, XORI, ORI, ANDI, SLLI,
SRLI, SRAI (I-Type)
                    self.emit_ldr_from_state(0, inst.rs1);
                    const imm_u: u64 = @bitCast(@as(i64, inst.imm));

                    switch (inst.funct3) {
                        0x0 => { // ADDI
                            self.emit_mov_u64(1, imm_u);
                            self.emit_add(0, 0, 1);
                        },
                        0x4 => { // XORI
                            self.emit_mov_u64(1, imm_u);
                            self.emit_eor(0, 0, 1);
                        },
                        0x6 => { // ORI
                            self.emit_mov_u64(1, imm_u);
                            self.emit_orr(0, 0, 1);
                        },
                        0x7 => { // ANDI
                            self.emit_mov_u64(1, imm_u);
                            self.emit_and(0, 0, 1);
                        },
                        0x1 => { // SLLI
                            const shamt: u6 = @truncate(@as(u32,
@bitCast(inst.imm)));
                            self.emit_lsl_i(0, 0, shamt);
                        },
                        0x5 => { // SRLI/SRAI
                            const shamt: u6 = @truncate(@as(u32,
@bitCast(inst.imm)));
                            if ((inst.imm >> 10) == 0) { // SRLI
                                self.emit_lsr_i(0, 0, shamt);
                            } else { // SRAI
                                self.emit_asr_i(0, 0, shamt);
                            }
                        },
                        0x2 => { // SLTI (Set Less Than Immediate,
signed)
                            self.emit_mov_u64(1, imm_u);
                            self.emit_cmp(0, 1); // Compare rs1 (reg 0)
with imm (reg 1)
                            self.emit_cset(0, 0xB); // Set reg 0 to 1 if
LT (signed less than), else 0
                        },
                        0x3 => { // SLTIU (Set Less Than Immediate
Unsigned)
                            self.emit_mov_u64(1, imm_u);
                            self.emit_cmp(0, 1); // Compare rs1 (reg 0)
with imm (reg 1)
                            self.emit_cset(0, 0x3); // Set reg 0 to 1 if
LO (unsigned less than), else 0
                        },
                        else => {},
                    }
                    self.emit_str_to_state(0, inst.rd);
                },
                0x37 => { // LUI
                    const imm_u: u64 = @bitCast(@as(i64, inst.imm));
                    self.emit_mov_u64(0, imm_u);
                    self.emit_str_to_state(0, inst.rd);
                },
                0x17 => { // AUIPC
                    const imm_u: u64 = @bitCast(@as(i64, inst.imm));
                    self.emit_mov_u64(0, current_pc);
                    self.emit_mov_u64(1, imm_u);
                    self.emit_add(0, 0, 1);
                    self.emit_str_to_state(0, inst.rd);
                },
                0x03 => { // LB, LH, LW, LBU, LHU, LWU, LD (Load)
                    self.emit_ldr_from_state(1, inst.rs1); // x1 = base
                    const imm_u: u64 = @bitCast(@as(i64, inst.imm));
                    self.emit_mov_u64(2, imm_u); // x2 = offset
                    self.emit_add(1, 1, 2); // x1 = guest_addr

                    // Translate virtual address to physical offset
                    // Why: Support both kernel (0x80000000+) and
framebuffer (0x90000000+) addresses
                    self.emit_translate_address(1); // x1 = physical
offset

                    const size: u2 = switch (inst.funct3) {
                        0x0, 0x4 => 0, // Byte
                        0x1, 0x5 => 1, // Half
                        0x2, 0x6 => 2, // Word
                        0x3 => 3, // Double
                        else => 3,
                    };
                    const signed = switch (inst.funct3) {
                        0x0, 0x1, 0x2 => true,
                        else => false,
                    };

                    // Load from memory: x0 = [x27 + x1] where x27 is
mem_base
                    self.emit_ldr_reg(0, 27, 1, size, signed);
                    self.emit_str_to_state(0, inst.rd);
                },
                0x23 => { // SB, SH, SW, SD (Store)
                    self.emit_ldr_from_state(1, inst.rs1); // x1 = base
                    const imm_u: u64 = @bitCast(@as(i64, inst.imm));
                    self.emit_mov_u64(2, imm_u); // x2 = offset
                    self.emit_add(1, 1, 2); // x1 = guest_addr

                    // Translate virtual address to physical offset
                    // Why: Support both kernel (0x80000000+) and
framebuffer (0x90000000+) addresses
                    self.emit_translate_address(1); // x1 = physical
offset

                    self.emit_ldr_from_state(0, inst.rs2); // x0 = value
to store

                    const size: u2 = switch (inst.funct3) {
                        0x0 => 0, // Byte
                        0x1 => 1, // Half
                        0x2 => 2, // Word
                        0x3 => 3, // Double
                        else => 3,
                    };

                    // Store to memory: [x27 + x1] = x0 where x27 is
mem_base
                    self.emit_str_reg(0, 27, 1, size);
                },
                0x63 => { // BRANCH (B-Type)
                    self.emit_ldr_from_state(0, inst.rs1);
                    self.emit_ldr_from_state(1, inst.rs2);
                    self.emit_subs(31, 0, 1);

                    const cond: u4 = switch (inst.funct3) {
                        0 => 0x0, // EQ
                        1 => 0x1, // NE
                        4 => 0xB, // LT
                        5 => 0xA, // GE
                        6 => 0x3, // LO
                        7 => 0x2, // HS
                        else => 0xE, // AL
                    };

                    const patch_pos = self.cursor;
                    self.emit_b_cond(cond, 0);
                    try self.record_fixup(current_pc + @as(u64,
@bitCast(@as(i64, inst.imm))), patch_pos);
                },
                0x6F => { // JAL (J-Type)
                    const ret_addr = current_pc + 4;
                    self.emit_mov_u64(0, ret_addr);
                    self.emit_str_to_state(0, inst.rd);

                    const target_pc = current_pc + @as(u64,
@bitCast(@as(i64, inst.imm)));
                    // Track chain opportunity for direct jumps.
                    self.perf_counters.chain_opportunities += 1;
                    
                    // Try to chain if target block exists in cache.
                    if (self.block_cache.get(target_pc)) |target_offset|
{
                        // Target block exists: chain directly to it.
                        const target_func =
@ptrCast(@alignCast(@as(*const anyopaque,
@ptrFromInt(@intFromPtr(self.code_buffer.ptr) + @as(usize,
target_offset)))));
                        // Emit call to target function instead of
branch.
                        self.emit_call_target(target_func);
                        // After chained block returns, return to
dispatcher.
                        self.emit_ret();
                        self.perf_counters.chains_created += 1;
                    } else {
                        // Target not compiled yet: use fixup.
                        const patch_pos = self.cursor;
                        self.emit_b(0);
                        try self.record_fixup(target_pc, patch_pos);
                    }

                    break;
                },
                0x67 => { // JALR (I-Type)
                    const ret_addr = current_pc + 4;
                    self.emit_mov_u64(0, ret_addr);
                    self.emit_str_to_state(0, inst.rd);

                    self.emit_ldr_from_state(1, inst.rs1);
                    const imm_u: u64 = @bitCast(@as(i64, inst.imm));
                    self.emit_mov_u64(2, imm_u);
                    self.emit_add(1, 1, 2);

                    self.emit_ret();
                    break;
                },
                else => {
                    // Unknown
                },
            }

            current_pc += fetch_result.len;
            instructions_in_block += 1;
            self.perf_counters.instructions_translated += 1;

            if (instructions_in_block > 100) break;
        }

        if (instructions_in_block > 100) {
            self.emit_ret();
        }

        try self.block_cache.put(guest_pc, start_offset);
        self.perf_counters.blocks_compiled += 1;
        
        // Track code size for this block.
        const block_size: u32 = self.cursor - start_offset;
        const block_size_u64: u64 = @intCast(block_size);
        self.perf_counters.total_code_size_bytes += block_size_u64;
        if (self.perf_counters.max_code_size_bytes == 0 or
block_size_u64 > self.perf_counters.max_code_size_bytes) {
            self.perf_counters.max_code_size_bytes = block_size_u64;
        }
        if (self.perf_counters.min_code_size_bytes == 0 or
block_size_u64 < self.perf_counters.min_code_size_bytes) {
            self.perf_counters.min_code_size_bytes = block_size_u64;
        }

        self.flush_cache(start_offset, self.cursor - start_offset);

        // GrainStyle: Cast u32 to usize only for pointer arithmetic
        const code_ptr = @intFromPtr(self.code_buffer.ptr) + @as(usize,
start_offset);
        return @ptrCast(@alignCast(@as(*const anyopaque,
@ptrFromInt(code_ptr))));
    }

    /// GrainStyle: Use explicit u32 instead of usize for code buffer
offsets
    fn apply_fixups(self: *JitContext, target_pc: u64, target_addr: u32)
void {
        if (self.pending_fixups.fetchRemove(target_pc)) |entry| {
            var current: ?*Fixup = entry.value;
            while (current) |fixup| {
                const offset = @as(i64, @intCast(target_addr)) -
@as(i64, @intCast(fixup.patch_addr));

                const existing = std.mem.readInt(u32,
self.code_buffer[fixup.patch_addr..][0..4], .little);

                var inst: u32 = 0;
                if ((existing & 0x7C000000) == 0x14000000) {
                    const imm26: u32 = @as(u32, @bitCast(@as(i32,
@intCast(offset >> 2)))) & 0x03FFFFFF;
                    inst = 0x14000000 | imm26;
                } else if ((existing & 0xFF000000) == 0x54000000) {
                    const imm19: u32 = @as(u32, @bitCast(@as(i32,
@intCast(offset >> 2)))) & 0x7FFFF;
                    const cond = existing & 0xF;
                    inst = 0x54000000 | (imm19 << 5) | cond;
                }

                if (inst != 0) {
                    std.mem.writeInt(u32,
self.code_buffer[fixup.patch_addr..][0..4], inst, .little);
                }

                const next = fixup.next;
                self.allocator.destroy(fixup);
                current = next;
            }
        }
    }

    pub fn dump_code(self: *JitContext, filename: []const u8) !void {
        const file = try std.fs.cwd().createFile(filename, .{});
        defer file.close();
        try file.writeAll(self.code_buffer[0..self.cursor]);
    }

    pub fn enter_jit(code: *const anyopaque, state: *GuestState,
mem_base: [*]u8) void {
        asm volatile (
            \\  mov x28, %[state]
            \\  mov x27, %[mem_base]
            \\  blr %[code]
            :
            : [code] "r" (code),
              [state] "r" (state),
              [mem_base] "r" (mem_base),
            : .{ .x27 = true, .x28 = true, .x30 = true, .memory = true
});
    }
};

test "JIT: Simple ADD" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return;

    const allocator = std.testing.allocator;

    std.debug.print("\nSetting up memory...\n", .{});
    var ram = try allocator.alloc(u8, 1024 * 1024);
    defer allocator.free(ram);
    @memset(ram, 0);

    // 2. Write RISC-V Code (ADDI x1, x0, 10; ADDI x2, x0, 20; ADD x3,
x1, x2; RET)
    // ADDI x1, x0, 10  -> 0x00A00093
    // ADDI x2, x0, 20  -> 0x01400113
    // ADD x3, x1, x2   -> 0x002081B3
    // RET (JALR x0, x1, 0) -> 0x00008067
    const code = [_]u32{
        0x00A00093,
        0x01400113,
        0x002081B3,
        0x00008067,
    };

    const start_pc: u64 = 0x80000000;
    for (code, 0..) |inst, i| {
        std.mem.writeInt(u32, ram[i * 4 ..][0..4], inst, .little);
    }

    var state = GuestState{ .regs = undefined, .pc = start_pc };
    @memset(&state.regs, 0);

    var jit = try JitContext.init(allocator, &state, ram);
    defer jit.deinit();

    const func = try jit.compile_block(start_pc);
    JitContext.enter_jit(func, &state, ram.ptr);

    try std.testing.expectEqual(@as(u64, 10), state.regs[1]);
    try std.testing.expectEqual(@as(u64, 20), state.regs[2]);
    try std.testing.expectEqual(@as(u64, 30), state.regs[3]);
}

test "JIT: Load/Store/Logic" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return;

    const allocator = std.testing.allocator;
    var ram = try allocator.alloc(u8, 1024 * 1024);
    defer allocator.free(ram);
    @memset(ram, 0);

    // Initialize RAM with some data at offset 0x100 (80000100)
    std.mem.writeInt(u32, ram[0x100..][0..4], 0xDEADBEEF, .little);

    // Code:
    // ADDI x1, x0, 0x100       (x1 = 0x100)
    // ADDI x2, x0, 1           (x2 = 1)
    // SLLI x2, x2, 31          (x2 = 0x80000000)
    // ADD x1, x1, x2           (x1 = 0x80000100)
    // LW x3, 0(x1)             (x3 = *0x80000100 = 0xDEADBEEF)
    // ADDI x4, x0, 1           (x4 = 1)
    // SLLI x4, x4, 4           (x4 = 16)
    // OR x5, x3, x4            (x5 = 0xDEADBEEF | 0x10 = 0xDEADBEFF)
    // SW x5, 4(x1)             (*0x80000104 = x5)
    // RET

    // ADDI x1, x0, 0x100 -> 0x10000093
    // ADDI x2, x0, 1     -> 0x00100113
    // SLLI x2, x2, 31    -> 0x01F11113
    // ADD x1, x1, x2     -> 0x002080B3
    // LW x3, 0(x1)       -> 0x0000A183
    // ADDI x4, x0, 1     -> 0x00100213
    // SLLI x4, x4, 4     -> 0x00421213
    // OR x5, x3, x4      -> 0x0041E2B3
    // SW x5, 4(x1)       -> 0x0050A223
    // RET                -> 0x00008067

    const code = [_]u32{
        0x10000093,
        0x00100113,
        0x01F11113,
        0x002080B3,
        0x0000A183,
        0x00100213,
        0x00421213,
        0x0041E2B3,
        0x0050A223,
        0x00008067,
    };

    const start_pc: u64 = 0x80000000;
    for (code, 0..) |inst, i| {
        std.mem.writeInt(u32, ram[i * 4 ..][0..4], inst, .little);
    }

    var state = GuestState{ .regs = undefined, .pc = start_pc };
    @memset(&state.regs, 0);

    var jit = try JitContext.init(allocator, &state, ram);
    defer jit.deinit();

    const func = try jit.compile_block(start_pc);
    JitContext.enter_jit(func, &state, ram.ptr);

    // Verify Registers
    try std.testing.expectEqual(@as(u64, 0xFFFFFFFFDEADBEEF),
state.regs[3]); // LW result (sign-extended)
    try std.testing.expectEqual(@as(u64, 16), state.regs[4]); // SLLI
result
    try std.testing.expectEqual(@as(u64, 0xFFFFFFFFDEADBEFF),
state.regs[5]); // OR result (sign-extended)

    // Verify Memory Store
    const stored = std.mem.readInt(u32, ram[0x104..][0..4], .little);
    try std.testing.expectEqual(@as(u32, 0xDEADBEFF), stored);
}

test "JIT: RVC Compressed Instructions" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return;

    const allocator = std.testing.allocator;
    var ram = try allocator.alloc(u8, 1024 * 1024);
    defer allocator.free(ram);
    @memset(ram, 0);

    // Test compressed instructions:
    // C.ADDI x1, 5     -> 0x0505 (ADDI x1, x1, 5)
    // C.LI x2, 10      -> 0x4509 (ADDI x2, x0, 10)
    // C.MV x3, x1      -u003e 0x8186 (x3 = x1)
    // C.ADD x3, x2     -u003e 0x918A (x3 = x3 + x2)

    const code = [_]u16{
        0x0095, // C.ADDI x1, 5
        0x4129, // C.LI x2, 10
        0x8186, // C.MV x3, x1
        0x918A, // C.ADD x3, x2
        0x8082, // C.JR x1
    };

    const start_pc: u64 = 0x80000000;
    for (code, 0..) |inst, i| {
        std.mem.writeInt(u16, ram[i * 2 ..][0..2], inst, .little);
    }

    var state = GuestState{ .regs = undefined, .pc = start_pc };
    @memset(&state.regs, 0);
    state.regs[1] = 0; // x1 starts at 0

    var jit = try JitContext.init(allocator, &state, ram);
    defer jit.deinit();

    const func = try jit.compile_block(start_pc);
    JitContext.enter_jit(func, &state, ram.ptr);

    // Verify Results
    try std.testing.expectEqual(@as(u64, 5), state.regs[1]); // C.ADDI
x1, 5
    try std.testing.expectEqual(@as(u64, 10), state.regs[2]); // C.LI
x2, 10
    try std.testing.expectEqual(@as(u64, 15), state.regs[3]); // C.MV
x3, x1; C.ADD x3, x2
}

