// === kernel_vm/loader.zig ===

const std = @import("std");
const VM = @import("vm.zig").VM;

/// RISC-V64 ELF kernel loader.
/// Grain Style: Static allocation where possible, comprehensive
assertions.
/// ~<~ Glow Earthbend: ELF parsing is explicit, no hidden allocations.

/// ELF header structure (64-bit, little-endian).
/// Why: Explicit ELF structure for kernel loading.
const Elf64_Ehdr = extern struct {
    /// ELF magic number: 0x7F "ELF".
    e_ident: [16]u8,
    /// Object file type (1 = relocatable, 2 = executable, 3 = shared).
    e_type: u16,
    /// Machine architecture (243 = RISC-V).
    e_machine: u16,
    /// Object file version (usually 1).
    e_version: u32,
    /// Entry point virtual address.
    e_entry: u64,
    /// Program header table file offset.
    e_phoff: u64,
    /// Section header table file offset.
    e_shoff: u64,
    /// Processor-specific flags.
    e_flags: u32,
    /// ELF header size in bytes.
    e_ehsize: u16,
    /// Program header table entry size.
    e_phentsize: u16,
    /// Program header table entry count.
    e_phnum: u16,
    /// Section header table entry size.
    e_shentsize: u16,
    /// Section header table entry count.
    e_shnum: u16,
    /// Section header string table index.
    e_shstrndx: u16,
};

/// Program header structure (64-bit, little-endian).
/// Why: Explicit program header for loading kernel segments.
const Elf64_Phdr = extern struct {
    /// Segment type (1 = loadable).
    p_type: u32,
    /// Segment flags (read, write, execute).
    p_flags: u32,
    /// Segment file offset.
    p_offset: u64,
    /// Segment virtual address.
    p_vaddr: u64,
    /// Segment physical address.
    p_paddr: u64,
    /// Segment size in file.
    p_filesz: u64,
    /// Segment size in memory.
    p_memsz: u64,
    /// Segment alignment.
    p_align: u64,
};

/// ELF magic number: 0x7F "ELF".
const ELF_MAGIC = [_]u8{ 0x7F, 'E', 'L', 'F' };

/// Loader errors.
/// Why: Explicit error types for ELF loading.
pub const LoaderError = error{
    SegmentOutOfBounds,
    InvalidElfFormat,
};

/// Load RISC-V64 kernel ELF into VM (GrainStyle: in-place
initialization).
/// Why: Parse ELF file and load kernel segments into VM memory.
/// Contract: target must point to uninitialized VM struct.
/// Contract: elf_data must be valid ELF format.
/// Errors: SegmentOutOfBounds if ELF segments don't fit in VM memory.
/// Errors: InvalidElfFormat if ELF header is invalid.
/// Postcondition: VM is initialized with ELF segments loaded, PC set to
entry point.
pub fn loadKernel(target: *VM, _: std.mem.Allocator, elf_data: []const
u8) LoaderError!void {
    std.debug.print("DEBUG loader.zig: loadKernel called,
elf_data.len={}\n", .{elf_data.len});
    
    // Check: ELF data must be non-empty.
    if (elf_data.len == 0) {
        std.debug.print("DEBUG loader.zig: ELF data is empty\n", .{});
        return error.InvalidElfFormat;
    }
    
    // Check: ELF data must be large enough for ELF header.
    if (elf_data.len < @sizeOf(Elf64_Ehdr)) {
        std.debug.print("DEBUG loader.zig: ELF data too small ({} <
{})\n", .{ elf_data.len, @sizeOf(Elf64_Ehdr) });
        return error.InvalidElfFormat;
    }
    
    // Parse ELF header.
    // Why: @alignCast required because Elf64_Ehdr requires alignment.
    // Note: ELF files are typically aligned, but we check alignment to
avoid crashes.
    // Check: ELF data pointer alignment (Elf64_Ehdr requires 8-byte
alignment).
    const alignment_required = @alignOf(Elf64_Ehdr);
    const ptr_addr = @intFromPtr(elf_data.ptr);
    std.debug.print("DEBUG loader.zig: ptr_addr=0x{x},
alignment_required={}, aligned={}\n", .{ ptr_addr, alignment_required,
ptr_addr % alignment_required == 0 });
    
    const ehdr: *const Elf64_Ehdr = if (ptr_addr % alignment_required !=
0) blk: {
        std.debug.print("DEBUG loader.zig: Using aligned buffer
(unaligned pointer)\n", .{});
        // ELF data is not properly aligned - copy to aligned buffer.
        var aligned_buffer: [@sizeOf(Elf64_Ehdr)]u8
align(alignment_required) = undefined;
        @memcpy(&aligned_buffer, elf_data[0..@sizeOf(Elf64_Ehdr)]);
        break :blk @as(*const Elf64_Ehdr, @ptrCast(&aligned_buffer));
    } else blk: {
        std.debug.print("DEBUG loader.zig: Using @alignCast (aligned
pointer)\n", .{});
        break :blk @as(*const Elf64_Ehdr,
@alignCast(@ptrCast(elf_data.ptr)));
    };
    
    std.debug.print("DEBUG loader.zig: ELF header parsed, magic={x:0>2}
{x:0>2} {x:0>2} {x:0>2}\n", .{ ehdr.e_ident[0], ehdr.e_ident[1],
ehdr.e_ident[2], ehdr.e_ident[3] });
    
    // Check: ELF magic number must match (return error instead of
asserting for userspace programs).
    if (!std.mem.eql(u8, ehdr.e_ident[0..4], &ELF_MAGIC)) {
        return error.InvalidElfFormat;
    }
    
    // Check: ELF class must be 64-bit (e_ident[4] = 2).
    if (ehdr.e_ident[4] != 2) {
        return error.InvalidElfFormat;
    }
    
    // Check: ELF endianness must be little-endian (e_ident[5] = 1).
    if (ehdr.e_ident[5] != 1) {
        return error.InvalidElfFormat;
    }
    
    // Check: ELF version must be 1 (e_ident[6] = 1).
    if (ehdr.e_ident[6] != 1) {
        return error.InvalidElfFormat;
    }
    
    // Check: Machine architecture must be RISC-V (243).
    if (ehdr.e_machine != 243) {
        return error.InvalidElfFormat;
    }
    
    // Check: ELF type must be executable (2).
    if (ehdr.e_type != 2) {
        return error.InvalidElfFormat;
    }
    
    // Check: Program header table must be present.
    if (ehdr.e_phnum == 0 or ehdr.e_phoff == 0) {
        return error.InvalidElfFormat;
    }
    
    // Check: Program header table must fit in ELF data.
    const phdr_size = @as(usize, ehdr.e_phnum) * @sizeOf(Elf64_Phdr);
    if (ehdr.e_phoff + phdr_size > elf_data.len) {
        return error.InvalidElfFormat;
    }
    
    // Initialize VM (will be populated with kernel segments).
    // GrainStyle: Use in-place initialization to avoid stack overflow.
    VM.init(target, &[_]u8{}, 0);
    
    // Load each program header segment.
    // Why: Load kernel code/data segments into VM memory.
    const phdr_base = elf_data[@intCast(ehdr.e_phoff)..];
    std.debug.print("DEBUG loader.zig: Loading {} program headers\n",
.{ehdr.e_phnum});
    var phdr_idx: u16 = 0;
    var first_load_vaddr: ?u64 = null; // Track first PT_LOAD segment
for PIE entry point adjustment
    while (phdr_idx < ehdr.e_phnum) : (phdr_idx += 1) {
        std.debug.print("DEBUG loader.zig: Processing program header
{}/{}\n", .{ phdr_idx + 1, ehdr.e_phnum });
        const phdr_offset = phdr_idx * @sizeOf(Elf64_Phdr);
        // Check: Program header must fit in ELF data.
        if (phdr_offset + @sizeOf(Elf64_Phdr) > phdr_base.len) {
            std.debug.print("DEBUG loader.zig: Program header {} out of
bounds\n", .{phdr_idx});
            return error.InvalidElfFormat;
        }
        
        // Why: @alignCast required because Elf64_Phdr requires
alignment.
        const phdr = @as(*const Elf64_Phdr,
@alignCast(@ptrCast(phdr_base.ptr + phdr_offset)));
        std.debug.print("DEBUG loader.zig: Program header {}: type={},
vaddr=0x{x}, filesz={}, memsz={}\n", .{ phdr_idx, phdr.p_type,
phdr.p_vaddr, phdr.p_filesz, phdr.p_memsz });
        
        // Only load PT_LOAD segments (type 1).
        if (phdr.p_type == 1) {
            // Track first PT_LOAD segment for PIE entry point
adjustment.
            if (first_load_vaddr == null) {
                first_load_vaddr = phdr.p_vaddr;
            }
            std.debug.print("DEBUG loader.zig: Loading PT_LOAD segment
at vaddr=0x{x}\n", .{phdr.p_vaddr});
            // Check: Segment must fit in ELF data (return error instead
of asserting for userspace programs).
            if (phdr.p_offset + phdr.p_filesz > elf_data.len) {
                return error.InvalidElfFormat;
            }
            
            // Check: Segment must fit in VM memory (return error
instead of asserting for userspace programs).
            if (phdr.p_vaddr + phdr.p_memsz > target.memory_size) {
                return error.SegmentOutOfBounds;
            }
            
            // Check: Segment address must be valid for memory copy.
            if (phdr.p_vaddr + phdr.p_filesz > target.memory_size) {
                return error.SegmentOutOfBounds;
            }
            
            // Load segment data into VM memory.
            // Contract: All bounds must be checked before memory
operations.
            const segment_data =
elf_data[@intCast(phdr.p_offset)..][0..@intCast(phdr.p_filesz)];
            const dest_start = @as(usize, @intCast(phdr.p_vaddr));
            const dest_end = dest_start + segment_data.len;
            
            // Check: Destination must be within VM memory bounds.
            if (dest_start >= target.memory_size) {
                std.debug.print("DEBUG loader.zig: Segment vaddr 0x{x}
>= memory_size 0x{x}\n", .{ phdr.p_vaddr, target.memory_size });
                return error.SegmentOutOfBounds;
            }
            if (dest_end > target.memory_size) {
                std.debug.print("DEBUG loader.zig: Segment end 0x{x} >
memory_size 0x{x}\n", .{ phdr.p_vaddr + phdr.p_filesz,
target.memory_size });
                return error.SegmentOutOfBounds;
            }
            
            // Check: Destination slice must be valid.
            if (dest_start + segment_data.len > target.memory.len) {
                std.debug.print("DEBUG loader.zig: Segment would
overflow memory array\n", .{});
                return error.SegmentOutOfBounds;
            }
            
            // Safe to copy: all bounds checked.
            std.debug.print("DEBUG loader.zig: Copying {} bytes from
offset {} to vaddr 0x{x}\n", .{ segment_data.len, phdr.p_offset,
phdr.p_vaddr });
            @memcpy(target.memory[dest_start..dest_end], segment_data);
            std.debug.print("DEBUG loader.zig: Copy completed
successfully\n", .{});
            
            // Zero-fill memory beyond file size (if memsz > filesz).
            if (phdr.p_memsz > phdr.p_filesz) {
                const zero_start = @as(usize, @intCast(phdr.p_vaddr +
phdr.p_filesz));
                const zero_len = @as(usize, @intCast(phdr.p_memsz -
phdr.p_filesz));
                std.debug.print("DEBUG loader.zig: Zero-filling {} bytes
at vaddr 0x{x}\n", .{ zero_len, phdr.p_vaddr + phdr.p_filesz });
                // Check: Zero-fill region must fit in VM memory.
                if (zero_start + zero_len > target.memory_size) {
                    std.debug.print("DEBUG loader.zig: Zero-fill would
exceed memory_size\n", .{});
                    return error.SegmentOutOfBounds;
                }
                if (zero_start + zero_len > target.memory.len) {
                    std.debug.print("DEBUG loader.zig: Zero-fill would
overflow memory array\n", .{});
                    return error.SegmentOutOfBounds;
                }
                @memset(target.memory[zero_start..zero_start +
zero_len], 0);
                std.debug.print("DEBUG loader.zig: Zero-fill completed
successfully\n", .{});
            }
        }
    }
    
    // Set VM PC to ELF entry point.
    // Note: For PIE executables, if entry point is 0x0, use first
PT_LOAD segment's vaddr as base.
    var entry_point = ehdr.e_entry;
    if (entry_point == 0x0) {
        if (first_load_vaddr) |base_addr| {
            std.debug.print("DEBUG loader.zig: PIE executable detected
(entry=0x0), using first PT_LOAD vaddr 0x{x} as entry point\n",
.{base_addr});
            entry_point = base_addr;
        }
    }
    std.debug.print("DEBUG loader.zig: Setting entry point to 0x{x}\n",
.{entry_point});
    // Check: Entry point must be within VM memory bounds.
    if (entry_point >= target.memory_size) {
        std.debug.print("DEBUG loader.zig: Entry point 0x{x} >=
memory_size 0x{x}\n", .{ entry_point, target.memory_size });
        return error.SegmentOutOfBounds;
    }
    
    target.regs.pc = entry_point;
    std.debug.print("DEBUG loader.zig: Entry point set successfully,
PC=0x{x}\n", .{target.regs.pc});
    
    // Contract: PC must be set to entry point (verified by assignment
above).
    // Note: Entry point can be 0x0 for position-independent executables
(adjusted to first PT_LOAD vaddr).
    
    // Assert: VM must be in halted state after loading.
    std.debug.assert(target.state == .halted);
}


// === kernel_vm/memory_protection.zig ===

//! VM Memory Protection System
//!
//! Objective: Provide memory protection capabilities (page tables,
permissions, access control).
//! Why: Enable kernel development with proper memory protection and
isolation.
//! GrainStyle: Static allocation, bounded page tables, explicit types,
deterministic protection.
//!
//! Methodology:
//! - Page table management (create, modify, query page tables)
//! - Memory permission management (read, write, execute permissions)
//! - Page fault handling (detect and handle page faults)
//! - Memory region protection (protect memory regions with permissions)
//! - Bounded page table entries (MAX_PAGE_TABLE_ENTRIES: 1024)
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded arrays: fixed-size page table arrays
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-12-02
//! GrainStyle: Comprehensive memory protection, deterministic behavior,
explicit limits

const std = @import("std");
const VM = @import("vm.zig").VM;
const VMError = @import("vm.zig").VM.VMError;

// Bounded: Maximum page table entries (sufficient for kernel
development).
pub const MAX_PAGE_TABLE_ENTRIES: u32 = 1024;
// Page size: 4KB (standard RISC-V page size).
pub const PAGE_SIZE: u64 = 4096;

// Memory permissions (bit flags).
pub const MemoryPermissions = struct {
    pub const READ: u8 = 1;
    pub const WRITE: u8 = 2;
    pub const EXECUTE: u8 = 4;
    pub const USER: u8 = 8;
};

// Page table entry.
pub const PageTableEntry = struct {
    virtual_address: u64,
    physical_address: u64,
    permissions: u8,
    present: bool,

    pub fn init() PageTableEntry {
        return PageTableEntry{
            .virtual_address = 0,
            .physical_address = 0,
            .permissions = 0,
            .present = false,
        };
    }
};

// VM memory protection manager.
pub const VMMemoryProtection = struct {
    page_table: [MAX_PAGE_TABLE_ENTRIES]PageTableEntry,
    page_table_len: u32,

    pub fn init() VMMemoryProtection {
        var protection = VMMemoryProtection{
            .page_table = undefined,
            .page_table_len = 0,
        };
        var i: u32 = 0;
        while (i < MAX_PAGE_TABLE_ENTRIES) : (i += 1) {
            protection.page_table[i] = PageTableEntry.init();
        }
        return protection;
    }

    pub fn map_page(self: *VMMemoryProtection, virtual_addr: u64,
physical_addr: u64, permissions: u8) bool {
        if (self.page_table_len >= MAX_PAGE_TABLE_ENTRIES) {
            return false;
        }
        if (virtual_addr % PAGE_SIZE != 0) {
            return false;
        }
        if (physical_addr % PAGE_SIZE != 0) {
            return false;
        }
        var i: u32 = 0;
        while (i < self.page_table_len) : (i += 1) {
            const entry = &self.page_table[i];
            if (entry.virtual_address == virtual_addr) {
                entry.physical_address = physical_addr;
                entry.permissions = permissions;
                entry.present = true;
                return true;
            }
        }
        const idx = self.page_table_len;
        self.page_table[idx] = PageTableEntry{
            .virtual_address = virtual_addr,
            .physical_address = physical_addr,
            .permissions = permissions,
            .present = true,
        };
        self.page_table_len += 1;
        return true;
    }

    pub fn unmap_page(self: *VMMemoryProtection, virtual_addr: u64) bool
{
        var i: u32 = 0;
        while (i < self.page_table_len) : (i += 1) {
            const entry = &self.page_table[i];
            if (entry.virtual_address == virtual_addr) {
                entry.present = false;
                return true;
            }
        }
        return false;
    }

    pub fn get_permissions(self: *const VMMemoryProtection,
virtual_addr: u64) ?u8 {
        const page_addr = (virtual_addr / PAGE_SIZE) * PAGE_SIZE;
        var i: u32 = 0;
        while (i < self.page_table_len) : (i += 1) {
            const entry = &self.page_table[i];
            if (entry.present and entry.virtual_address == page_addr) {
                return entry.permissions;
            }
        }
        return null;
    }

    pub fn check_permission(self: *const VMMemoryProtection,
virtual_addr: u64, required_perm: u8) bool {
        const perms_opt = self.get_permissions(virtual_addr);
        if (perms_opt == null) {
            return false;
        }
        const perms = perms_opt.?;
        return (perms & required_perm) != 0;
    }

    pub fn translate_address(self: *const VMMemoryProtection,
virtual_addr: u64) ?u64 {
        const page_addr = (virtual_addr / PAGE_SIZE) * PAGE_SIZE;
        var i: u32 = 0;
        while (i < self.page_table_len) : (i += 1) {
            const entry = &self.page_table[i];
            if (entry.present and entry.virtual_address == page_addr) {
                const offset = virtual_addr - page_addr;
                return entry.physical_address + offset;
            }
        }
        return null;
    }

    pub fn protect_region(self: *VMMemoryProtection, start_addr: u64,
end_addr: u64, permissions: u8) bool {
        var addr = (start_addr / PAGE_SIZE) * PAGE_SIZE;
        const end = (end_addr / PAGE_SIZE) * PAGE_SIZE;
        while (addr <= end) {
            const page_addr = addr;
            var found = false;
            var i: u32 = 0;
            while (i < self.page_table_len) : (i += 1) {
                const entry = &self.page_table[i];
                if (entry.virtual_address == page_addr) {
                    entry.permissions = permissions;
                    found = true;
                    break;
                }
            }
            if (!found) {
                if (self.page_table_len >= MAX_PAGE_TABLE_ENTRIES) {
                    return false;
                }
                const idx = self.page_table_len;
                self.page_table[idx] = PageTableEntry{
                    .virtual_address = page_addr,
                    .physical_address = page_addr,
                    .permissions = permissions,
                    .present = true,
                };
                self.page_table_len += 1;
            }
            addr += PAGE_SIZE;
        }
        return true;
    }

    pub fn get_page_count(self: *const VMMemoryProtection) u32 {
        return self.page_table_len;
    }
};


// === kernel_vm/memory_stats.zig ===

//! VM Memory Statistics Tracking System
//!
//! Objective: Track memory usage, access patterns, and allocation
metrics for VM monitoring.
//! Why: Monitor memory consumption, identify access patterns, validate
memory management.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track total memory size and used memory
//! - Track memory access patterns (reads/writes by region)
//! - Track memory access counts
//! - Track memory fragmentation metrics
//! - Provide statistics interface for querying memory data
//! - Reset capability for new measurement periods
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive memory tracking, deterministic behavior,
explicit limits

const std = @import("std");

// Bounded: Max memory regions to track.
pub const MAX_MEMORY_REGIONS: u32 = 16;

// Memory region: tracks access patterns for a memory range.
pub const MemoryRegion = struct {
    start_addr: u64,
    end_addr: u64,
    read_count: u64,
    write_count: u64,
    total_bytes_read: u64,
    total_bytes_written: u64,

    pub fn init(start_addr: u64, end_addr: u64) MemoryRegion {
        // Allow 0,0 for uninitialized regions.
        if (start_addr > 0 or end_addr > 0) {
            std.debug.assert(start_addr < end_addr);
        }
        return MemoryRegion{
            .start_addr = start_addr,
            .end_addr = end_addr,
            .read_count = 0,
            .write_count = 0,
            .total_bytes_read = 0,
            .total_bytes_written = 0,
        };
    }

    pub fn contains(self: *const MemoryRegion, addr: u64) bool {
        // Handle uninitialized regions (start_addr == 0 and end_addr ==
0).
        if (self.start_addr == 0 and self.end_addr == 0) {
            return false;
        }
        return addr >= self.start_addr and addr < self.end_addr;
    }
};

// VM memory statistics tracker.
pub const VMMemoryStats = struct {
    total_memory_bytes: u64,
    used_memory_bytes: u64,
    regions: [MAX_MEMORY_REGIONS]MemoryRegion,
    regions_len: u32,
    total_reads: u64,
    total_writes: u64,
    total_bytes_read: u64,
    total_bytes_written: u64,

    pub fn init(total_memory_bytes: u64) VMMemoryStats {
        std.debug.assert(total_memory_bytes > 0);
        var stats = VMMemoryStats{
            .total_memory_bytes = total_memory_bytes,
            .used_memory_bytes = 0,
            .regions = undefined,
            .regions_len = 0,
            .total_reads = 0,
            .total_writes = 0,
            .total_bytes_read = 0,
            .total_bytes_written = 0,
        };
        var i: u32 = 0;
        while (i < MAX_MEMORY_REGIONS) : (i += 1) {
            stats.regions[i] = MemoryRegion.init(0, 0);
        }
        return stats;
    }

    pub fn add_region(self: *VMMemoryStats, start_addr: u64, end_addr:
u64) void {
        // Allow 0,0 for uninitialized regions, but require valid range
for active regions.
        if (start_addr > 0 or end_addr > 0) {
            std.debug.assert(start_addr < end_addr);
        }
        if (self.regions_len >= MAX_MEMORY_REGIONS) {
            return;
        }
        const idx = self.regions_len;
        self.regions[idx] = MemoryRegion.init(start_addr, end_addr);
        self.regions_len += 1;
    }

    pub fn record_read(self: *VMMemoryStats, addr: u64, size: u64) void {
        // Track reads regardless of bounds (virtual addresses may
exceed physical memory).
        self.total_reads += 1;
        self.total_bytes_read += size;
        self.update_region_access(addr, size, true);
    }

    pub fn record_write(self: *VMMemoryStats, addr: u64, size: u64) void
{
        // Track writes regardless of bounds (virtual addresses may
exceed physical memory).
        self.total_writes += 1;
        self.total_bytes_written += size;
        self.update_region_access(addr, size, false);
    }

    fn update_region_access(self: *VMMemoryStats, addr: u64, size: u64,
is_read: bool) void {
        var i: u32 = 0;
        while (i < self.regions_len) : (i += 1) {
            if (self.regions[i].contains(addr)) {
                if (is_read) {
                    self.regions[i].read_count += 1;
                    self.regions[i].total_bytes_read += size;
                } else {
                    self.regions[i].write_count += 1;
                    self.regions[i].total_bytes_written += size;
                }
                break;
            }
        }
    }

    pub fn update_used_memory(self: *VMMemoryStats, used_bytes: u64)
void {
        std.debug.assert(used_bytes <= self.total_memory_bytes);
        self.used_memory_bytes = used_bytes;
    }

    pub fn print_stats(self: *const VMMemoryStats) void {
        std.debug.print("\nVM Memory Statistics:\n", .{});
        std.debug.print("  Total Memory: {} bytes ({d:.2} MB)\n", .{
            self.total_memory_bytes,
            @as(f64, @floatFromInt(self.total_memory_bytes)) / (1024.0 *
1024.0),
        });
        std.debug.print("  Used Memory: {} bytes ({d:.2} MB)\n", .{
            self.used_memory_bytes,
            @as(f64, @floatFromInt(self.used_memory_bytes)) / (1024.0 *
1024.0),
        });
        if (self.total_memory_bytes > 0) {
            const usage_percent = @as(f64,
@floatFromInt(self.used_memory_bytes)) /
                @as(f64, @floatFromInt(self.total_memory_bytes)) * 100.0;
            std.debug.print("  Memory Usage: {d:.2}%\n",
.{usage_percent});
        }
        std.debug.print("  Total Reads: {}\n", .{self.total_reads});
        std.debug.print("  Total Writes: {}\n", .{self.total_writes});
        if (self.total_bytes_read > 0) {
            const read_mb = @as(f64,
@floatFromInt(self.total_bytes_read)) / (1024.0 * 1024.0);
            std.debug.print("  Total Bytes Read: {d:.2} MB\n",
.{read_mb});
        }
        if (self.total_bytes_written > 0) {
            const write_mb = @as(f64,
@floatFromInt(self.total_bytes_written)) / (1024.0 * 1024.0);
            std.debug.print("  Total Bytes Written: {d:.2} MB\n",
.{write_mb});
        }
        if (self.regions_len > 0) {
            std.debug.print("  Memory Regions Tracked: {}\n",
.{self.regions_len});
            var i: u32 = 0;
            while (i < self.regions_len) : (i += 1) {
                const region = self.regions[i];
                if (region.read_count > 0 or region.write_count > 0) {
                    std.debug.print("    Region 0x{x}-0x{x}: {} reads,
{} writes\n", .{
                        region.start_addr,
                        region.end_addr,
                        region.read_count,
                        region.write_count,
                    });
                }
            }
        }
    }

    pub fn reset(self: *VMMemoryStats) void {
        self.used_memory_bytes = 0;
        self.total_reads = 0;
        self.total_writes = 0;
        self.total_bytes_read = 0;
        self.total_bytes_written = 0;
        var i: u32 = 0;
        while (i < self.regions_len) : (i += 1) {
            self.regions[i].read_count = 0;
            self.regions[i].write_count = 0;
            self.regions[i].total_bytes_read = 0;
            self.regions[i].total_bytes_written = 0;
        }
    }
};


// === kernel_vm/optimization_hints.zig ===

//! VM Performance Optimization Hints System
//!
//! Objective: Analyze collected VM statistics and provide optimization
recommendations.
//! Why: Enable automatic detection of performance bottlenecks and
optimization opportunities.
//! GrainStyle: Static allocation, bounded buffers, explicit types,
deterministic analysis.
//!
//! Methodology:
//! - Analyze instruction statistics (identify hot instructions)
//! - Analyze memory access patterns (identify cache misses, hot memory
regions)
//! - Analyze branch patterns (identify mispredicted branches)
//! - Analyze register usage (identify register pressure)
//! - Generate optimization hints (JIT optimization, memory layout,
register allocation)
//! - Bounded hint buffer (MAX_HINTS: 32)
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded buffers: fixed-size hint buffer
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-12-02
//! GrainStyle: Comprehensive optimization hints, deterministic
behavior, explicit limits

const std = @import("std");
const VM = @import("vm.zig").VM;
const stats_aggregator_mod = @import("stats_aggregator.zig");

// Bounded: Maximum number of optimization hints.
pub const MAX_HINTS: u32 = 32;

// Optimization hint type.
pub const OptimizationHintType = enum {
    hot_instruction,
    memory_hot_spot,
    branch_misprediction,
    register_pressure,
    cache_miss,
    jit_opportunity,
};

// Optimization hint.
pub const OptimizationHint = struct {
    hint_type: OptimizationHintType,
    address: u64,
    description: [128]u8,
    description_len: u32,
    priority: u32,

    pub fn init() OptimizationHint {
        return OptimizationHint{
            .hint_type = .hot_instruction,
            .address = 0,
            .description = [_]u8{0} ** 128,
            .description_len = 0,
            .priority = 0,
        };
    }
};

// VM optimization hints analyzer.
pub const VMOptimizationHints = struct {
    hints: [MAX_HINTS]OptimizationHint,
    hints_count: u32,

    pub fn init() VMOptimizationHints {
        var analyzer = VMOptimizationHints{
            .hints = undefined,
            .hints_count = 0,
        };
        var i: u32 = 0;
        while (i < MAX_HINTS) : (i += 1) {
            analyzer.hints[i] = OptimizationHint.init();
        }
        return analyzer;
    }

    pub fn analyze_vm(self: *VMOptimizationHints, vm: *VM) void {
        self.hints_count = 0;
        self.analyze_hot_instructions(vm);
        self.analyze_memory_hot_spots(vm);
        self.analyze_branch_mispredictions(vm);
        self.analyze_register_pressure(vm);
        self.analyze_jit_opportunities(vm);
    }

    fn analyze_hot_instructions(self: *VMOptimizationHints, vm: *VM)
void {
        const stats = &vm.instruction_stats;
        var max_count: u64 = 0;
        var hot_opcode: u32 = 0;
        var i: u32 = 0;
        while (i < stats.entries_len) : (i += 1) {
            const entry = &stats.entries[i];
            if (entry.count > max_count) {
                max_count = entry.count;
                hot_opcode = entry.opcode;
            }
        }
        if (max_count > 1000 and self.hints_count < MAX_HINTS) {
            const hint = &self.hints[self.hints_count];
            hint.hint_type = .hot_instruction;
            hint.address = 0;
            hint.priority = 3;
            const desc = std.fmt.bufPrint(hint.description[0..], "Hot
instruction: opcode 0x{x} executed {} times", .{ hot_opcode, max_count
}) catch "";
            hint.description_len = @as(u32, @intCast(desc.len));
            self.hints_count += 1;
        }
    }

    fn analyze_memory_hot_spots(self: *VMOptimizationHints, vm: *VM)
void {
        const stats = &vm.memory_stats;
        var max_accesses: u64 = 0;
        var hot_region: u32 = 0;
        var i: u32 = 0;
        while (i < stats.regions_len) : (i += 1) {
            const region = &stats.regions[i];
            const total_accesses = region.read_count +
region.write_count;
            if (total_accesses > max_accesses) {
                max_accesses = total_accesses;
                hot_region = i;
            }
        }
        if (max_accesses > 500 and self.hints_count < MAX_HINTS) {
            const region = &stats.regions[hot_region];
            const hint = &self.hints[self.hints_count];
            hint.hint_type = .memory_hot_spot;
            hint.address = region.start_address;
            hint.priority = 2;
            const desc = std.fmt.bufPrint(hint.description[0..], "Memory
hot spot: 0x{x}-0x{x} accessed {} times", .{ region.start_address,
region.end_address, max_accesses }) catch "";
            hint.description_len = @as(u32, @intCast(desc.len));
            self.hints_count += 1;
        }
    }

    fn analyze_branch_mispredictions(self: *VMOptimizationHints, vm:
*VM) void {
        const stats = &vm.branch_stats;
        var worst_rate: f64 = 1.0;
        var worst_pc: u64 = 0;
        var i: u32 = 0;
        while (i < stats.entries_len) : (i += 1) {
            const entry = &stats.entries[i];
            const rate = stats.get_taken_rate(entry.pc);
            if (rate > 0.0 and rate < worst_rate) {
                worst_rate = rate;
                worst_pc = entry.pc;
            }
        }
        if (worst_rate < 0.3 and self.hints_count < MAX_HINTS) {
            const hint = &self.hints[self.hints_count];
            hint.hint_type = .branch_misprediction;
            hint.address = worst_pc;
            hint.priority = 1;
            const desc = std.fmt.bufPrint(hint.description[0..], "Branch
misprediction: PC 0x{x} taken rate {d:.2}%", .{ worst_pc, worst_rate *
100.0 }) catch "";
            hint.description_len = @as(u32, @intCast(desc.len));
            self.hints_count += 1;
        }
    }

    fn analyze_register_pressure(self: *VMOptimizationHints, vm: *VM)
void {
        const stats = &vm.register_stats;
        var max_usage: u64 = 0;
        var hot_register: u32 = 0;
        var i: u32 = 0;
        while (i < stats.entries_len) : (i += 1) {
            const entry = &stats.entries[i];
            const total_usage = entry.read_count + entry.write_count;
            if (total_usage > max_usage) {
                max_usage = total_usage;
                hot_register = i;
            }
        }
        if (max_usage > 10000 and self.hints_count < MAX_HINTS) {
            const hint = &self.hints[self.hints_count];
            hint.hint_type = .register_pressure;
            hint.address = hot_register;
            hint.priority = 2;
            const desc = std.fmt.bufPrint(hint.description[0..],
"Register pressure: x{} accessed {} times", .{ hot_register, max_usage
}) catch "";
            hint.description_len = @as(u32, @intCast(desc.len));
            self.hints_count += 1;
        }
    }

    fn analyze_jit_opportunities(self: *VMOptimizationHints, vm: *VM)
void {
        if (vm.jit == null or !vm.jit_enabled) {
            return;
        }
        const jit_ctx = vm.jit.?;
        const cache_hit_rate: f64 = if (jit_ctx.perf_counters.cache_hits
+ jit_ctx.perf_counters.cache_misses > 0)
            @as(f64, @floatFromInt(jit_ctx.perf_counters.cache_hits)) /
@as(f64, @floatFromInt(jit_ctx.perf_counters.cache_hits +
jit_ctx.perf_counters.cache_misses))
        else
            0.0;
        if (cache_hit_rate < 0.5 and self.hints_count < MAX_HINTS) {
            const hint = &self.hints[self.hints_count];
            hint.hint_type = .jit_opportunity;
            hint.address = 0;
            hint.priority = 1;
            const desc = std.fmt.bufPrint(hint.description[0..], "JIT
cache hit rate: {d:.2}% (low)", .{cache_hit_rate * 100.0}) catch "";
            hint.description_len = @as(u32, @intCast(desc.len));
            self.hints_count += 1;
        }
    }

    pub fn get_hints_count(self: *const VMOptimizationHints) u32 {
        return self.hints_count;
    }

    pub fn get_hint(self: *const VMOptimizationHints, index: u32)
?*const OptimizationHint {
        if (index >= self.hints_count) {
            return null;
        }
        return &self.hints[index];
    }

    pub fn print_hints(self: *const VMOptimizationHints) void {
        std.debug.print("\nVM Optimization Hints ({} hints):\n",
.{self.hints_count});
        var i: u32 = 0;
        while (i < self.hints_count) : (i += 1) {
            const hint = &self.hints[i];
            std.debug.print("  [{:2}] Priority {}: ", .{ i,
hint.priority });
            std.debug.print("{s}\n",
.{hint.description[0..hint.description_len]});
        }
    }
};


// === kernel_vm/performance.zig ===

//! VM Performance Monitoring System
//!
//! Objective: Track VM performance metrics for monitoring,
optimization, and diagnostics.
//! Why: Measure execution performance, identify bottlenecks, and
validate optimizations.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track instruction count, cycle count, IPC (instructions per cycle)
//! - Track memory access patterns (reads, writes, cache hits/misses)
//! - Track JIT performance (compilation time, cache hit rate)
//! - Track syscall performance (count, average latency)
//! - Provide diagnostics interface for state inspection
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-01-XX
//! GrainStyle: Comprehensive performance tracking, deterministic
behavior, explicit limits

const std = @import("std");
const exception_stats_mod = @import("exception_stats.zig");

/// Performance metrics for VM execution.
/// Why: Track execution performance for monitoring and optimization.
/// GrainStyle: Explicit types, bounded counters, deterministic tracking.
pub const PerformanceMetrics = struct {
    /// Total instructions executed (since VM start).
    /// Why: Measure total work done by VM.
    instructions_executed: u64 = 0,
    
    /// Total cycles simulated (approximate, 1 cycle per instruction).
    /// Why: Estimate execution time for performance analysis.
    cycles_simulated: u64 = 0,
    
    /// Memory read operations count.
    /// Why: Track memory access patterns for optimization.
    memory_reads: u64 = 0,
    
    /// Memory write operations count.
    /// Why: Track memory access patterns for optimization.
    memory_writes: u64 = 0,
    
    /// Syscall invocations count.
    /// Why: Track syscall frequency for optimization.
    syscalls: u64 = 0,
    
    /// JIT compilation count.
    /// Why: Track JIT activity for performance analysis.
    jit_compilations: u64 = 0,
    
    /// JIT cache hits count.
    /// Why: Measure JIT cache effectiveness.
    jit_cache_hits: u64 = 0,
    
    /// JIT cache misses count.
    /// Why: Measure JIT cache effectiveness.
    jit_cache_misses: u64 = 0,
    
    /// Interpreter fallback count (JIT failures).
    /// Why: Track JIT reliability and fallback frequency.
    interpreter_fallbacks: u64 = 0,
    
    /// Increment instruction count.
    /// Why: Track instruction execution.
    pub fn increment_instruction(self: *PerformanceMetrics) void {
        self.instructions_executed += 1;
        self.cycles_simulated += 1; // Approximate: 1 cycle per
instruction.
        
        // Assert: Counters must be consistent (postcondition).
        std.debug.assert(self.instructions_executed > 0);
        std.debug.assert(self.cycles_simulated >=
self.instructions_executed);
    }
    
    /// Increment memory read count.
    /// Why: Track memory read operations.
    pub fn increment_memory_read(self: *PerformanceMetrics) void {
        self.memory_reads += 1;
        
        // Assert: Counter must be consistent (postcondition).
        std.debug.assert(self.memory_reads > 0);
    }
    
    /// Increment memory write count.
    /// Why: Track memory write operations.
    pub fn increment_memory_write(self: *PerformanceMetrics) void {
        self.memory_writes += 1;
        
        // Assert: Counter must be consistent (postcondition).
        std.debug.assert(self.memory_writes > 0);
    }
    
    /// Increment syscall count.
    /// Why: Track syscall invocations.
    pub fn increment_syscall(self: *PerformanceMetrics) void {
        self.syscalls += 1;
        
        // Assert: Counter must be consistent (postcondition).
        std.debug.assert(self.syscalls > 0);
    }
    
    /// Increment JIT compilation count.
    /// Why: Track JIT compilation activity.
    pub fn increment_jit_compilation(self: *PerformanceMetrics) void {
        self.jit_compilations += 1;
        
        // Assert: Counter must be consistent (postcondition).
        std.debug.assert(self.jit_compilations > 0);
    }
    
    /// Increment JIT cache hit count.
    /// Why: Track JIT cache effectiveness.
    pub fn increment_jit_cache_hit(self: *PerformanceMetrics) void {
        self.jit_cache_hits += 1;
        
        // Assert: Counter must be consistent (postcondition).
        std.debug.assert(self.jit_cache_hits > 0);
    }
    
    /// Increment JIT cache miss count.
    /// Why: Track JIT cache effectiveness.
    pub fn increment_jit_cache_miss(self: *PerformanceMetrics) void {
        self.jit_cache_misses += 1;
        
        // Assert: Counter must be consistent (postcondition).
        std.debug.assert(self.jit_cache_misses > 0);
    }
    
    /// Increment interpreter fallback count.
    /// Why: Track JIT reliability.
    pub fn increment_interpreter_fallback(self: *PerformanceMetrics)
void {
        self.interpreter_fallbacks += 1;
        
        // Assert: Counter must be consistent (postcondition).
        std.debug.assert(self.interpreter_fallbacks > 0);
    }
    
    /// Calculate instructions per cycle (IPC).
    /// Why: Measure execution efficiency.
    /// Returns: IPC ratio (instructions / cycles), or 0 if cycles is 0.
    pub fn get_ipc(self: *const PerformanceMetrics) f64 {
        if (self.cycles_simulated == 0) {
            return 0.0;
        }
        
        const ipc = @as(f64, @floatFromInt(self.instructions_executed))
/ @as(f64, @floatFromInt(self.cycles_simulated));
        
        // Assert: IPC must be valid (postcondition).
        std.debug.assert(ipc >= 0.0);
        std.debug.assert(ipc <= 1.0); // Approximate: 1 cycle per
instruction.
        
        return ipc;
    }
    
    /// Calculate JIT cache hit rate.
    /// Why: Measure JIT cache effectiveness.
    /// Returns: Hit rate (0.0 to 1.0), or 0 if no cache accesses.
    pub fn get_jit_cache_hit_rate(self: *const PerformanceMetrics) f64 {
        const total_cache_accesses = self.jit_cache_hits +
self.jit_cache_misses;
        if (total_cache_accesses == 0) {
            return 0.0;
        }
        
        const hit_rate = @as(f64, @floatFromInt(self.jit_cache_hits)) /
@as(f64, @floatFromInt(total_cache_accesses));
        
        // Assert: Hit rate must be valid (postcondition).
        std.debug.assert(hit_rate >= 0.0);
        std.debug.assert(hit_rate <= 1.0);
        
        return hit_rate;
    }
    
    /// Reset all metrics.
    /// Why: Clear metrics for new measurement period.
    pub fn reset(self: *PerformanceMetrics) void {
        self.instructions_executed = 0;
        self.cycles_simulated = 0;
        self.memory_reads = 0;
        self.memory_writes = 0;
        self.syscalls = 0;
        self.jit_compilations = 0;
        self.jit_cache_hits = 0;
        self.jit_cache_misses = 0;
        self.interpreter_fallbacks = 0;
        
        // Assert: Metrics must be reset (postcondition).
        std.debug.assert(self.instructions_executed == 0);
        std.debug.assert(self.cycles_simulated == 0);
    }
    
    /// Print performance metrics summary.
    /// Why: Display metrics for debugging and monitoring.
    pub fn print_summary(self: *const PerformanceMetrics) void {
        std.debug.print("=== VM Performance Metrics ===\n", .{});
        std.debug.print("Instructions executed: {}\n",
.{self.instructions_executed});
        std.debug.print("Cycles simulated: {}\n",
.{self.cycles_simulated});
        std.debug.print("IPC: {d:.3}\n", .{self.get_ipc()});
        std.debug.print("Memory reads: {}\n", .{self.memory_reads});
        std.debug.print("Memory writes: {}\n", .{self.memory_writes});
        std.debug.print("Syscalls: {}\n", .{self.syscalls});
        std.debug.print("JIT compilations: {}\n",
.{self.jit_compilations});
        std.debug.print("JIT cache hits: {}\n", .{self.jit_cache_hits});
        std.debug.print("JIT cache misses: {}\n",
.{self.jit_cache_misses});
        std.debug.print("JIT cache hit rate: {d:.3}\n",
.{self.get_jit_cache_hit_rate()});
        std.debug.print("Interpreter fallbacks: {}\n",
.{self.interpreter_fallbacks});
        std.debug.print("==============================\n", .{});
    }
};

/// Diagnostics snapshot for VM state inspection.
/// Why: Capture VM state for debugging and diagnostics.
/// GrainStyle: Explicit types, static allocation, deterministic
encoding.
pub const DiagnosticsSnapshot = struct {
    /// VM state (running, halted, errored).
    state: u32,
    /// Program counter.
    pc: u64,
    /// Stack pointer (x2 register).
    sp: u64,
    /// Memory size in bytes.
    memory_size: u64,
    /// Memory usage (bytes used, approximate).
    memory_used: u64,
    /// JIT enabled flag.
    jit_enabled: bool,
    /// Error log entry count.
    error_count: u32,
    /// Performance metrics snapshot.
    metrics: PerformanceMetrics,
    /// Exception statistics snapshot.
    /// Why: Capture exception statistics for debugging and analysis.
    exception_stats: ExceptionStatsSnapshot,
    
    /// Exception statistics snapshot type.
    /// Why: Explicit type for exception statistics in diagnostics.
    pub const ExceptionStatsSnapshot = struct {
        /// Exception counts by type (16 exception types).
        exception_counts: [16]u64,
        /// Total exception count.
        total_count: u64,
    };
    
    /// Create diagnostics snapshot from VM state.
    /// Why: Capture current VM state for inspection.
    pub fn create(
        state: u32,
        pc: u64,
        sp: u64,
        memory_size: u64,
        memory_used: u64,
        jit_enabled: bool,
        error_count: u32,
        metrics: PerformanceMetrics,
        exception_stats: exception_stats_mod.ExceptionStats,
    ) DiagnosticsSnapshot {
        // Capture exception statistics.
        var exception_counts: [16]u64 = undefined;
        var i: u32 = 0;
        while (i < 16) : (i += 1) {
            exception_counts[i] = exception_stats.exception_counts[i];
        }
        const exception_stats_snapshot:
DiagnosticsSnapshot.ExceptionStatsSnapshot = .{
            .exception_counts = exception_counts,
            .total_count = exception_stats.total_count,
        };
        
        return DiagnosticsSnapshot{
            .state = state,
            .pc = pc,
            .sp = sp,
            .memory_size = memory_size,
            .memory_used = memory_used,
            .jit_enabled = jit_enabled,
            .error_count = error_count,
            .metrics = metrics,
            .exception_stats = exception_stats_snapshot,
        };
    }
    
    /// Print diagnostics snapshot.
    /// Why: Display VM state for debugging.
    pub fn print(self: *const DiagnosticsSnapshot) void {
        std.debug.print("=== VM Diagnostics Snapshot ===\n", .{});
        std.debug.print("State: {}\n", .{self.state});
        std.debug.print("PC: 0x{x}\n", .{self.pc});
        std.debug.print("SP: 0x{x}\n", .{self.sp});
        std.debug.print("Memory size: {} bytes\n", .{self.memory_size});
        std.debug.print("Memory used: {} bytes\n", .{self.memory_used});
        std.debug.print("JIT enabled: {}\n", .{self.jit_enabled});
        std.debug.print("Error count: {}\n", .{self.error_count});
        self.metrics.print_summary();
        std.debug.print("Exception statistics:\n", .{});
        std.debug.print("  Total exceptions: {}\n",
.{self.exception_stats.total_count});
        std.debug.print("  Illegal instruction: {}\n",
.{self.exception_stats.exception_counts[2]});
        std.debug.print("  Load address misaligned: {}\n",
.{self.exception_stats.exception_counts[4]});
        std.debug.print("  Store address misaligned: {}\n",
.{self.exception_stats.exception_counts[6]});
        std.debug.print("  Load access fault: {}\n",
.{self.exception_stats.exception_counts[5]});
        std.debug.print("  Store access fault: {}\n",
.{self.exception_stats.exception_counts[7]});
        std.debug.print("================================\n", .{});
    }
};


// === kernel_vm/register_stats.zig ===

//! VM Register Usage Statistics Tracking System
//!
//! Objective: Track register read/write frequency for register usage
analysis.
//! Why: Monitor which registers are used most, identify register
pressure, optimize register allocation.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track read count per register (0-31)
//! - Track write count per register (0-31)
//! - Track total register operations
//! - Calculate register usage percentages
//! - Provide statistics interface for querying register data
//! - Reset capability for new measurement periods
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive register tracking, deterministic behavior,
explicit limits

const std = @import("std");

// Bounded: Number of registers in RISC-V (32 general-purpose registers).
pub const NUM_REGISTERS: u32 = 32;

// Register usage entry: tracks read/write counts for a register.
pub const RegisterEntry = struct {
    register_num: u32,
    read_count: u64,
    write_count: u64,

    pub fn init(register_num: u32) RegisterEntry {
        std.debug.assert(register_num < NUM_REGISTERS);
        return RegisterEntry{
            .register_num = register_num,
            .read_count = 0,
            .write_count = 0,
        };
    }

    fn get_total_ops(self: *const RegisterEntry) u64 {
        return self.read_count + self.write_count;
    }
};

// VM register statistics tracker.
pub const VMRegisterStats = struct {
    entries: [NUM_REGISTERS]RegisterEntry,
    total_reads: u64,
    total_writes: u64,

    pub fn init() VMRegisterStats {
        var stats = VMRegisterStats{
            .entries = undefined,
            .total_reads = 0,
            .total_writes = 0,
        };
        var i: u32 = 0;
        while (i < NUM_REGISTERS) : (i += 1) {
            stats.entries[i] = RegisterEntry.init(i);
        }
        return stats;
    }

    pub fn record_read(self: *VMRegisterStats, register_num: u32) void {
        std.debug.assert(register_num < NUM_REGISTERS);
        self.total_reads += 1;
        self.entries[register_num].read_count += 1;
    }

    pub fn record_write(self: *VMRegisterStats, register_num: u32) void {
        std.debug.assert(register_num < NUM_REGISTERS);
        self.total_writes += 1;
        self.entries[register_num].write_count += 1;
    }

    fn print_top_registers(self: *const VMRegisterStats) void {
        const total_ops = self.total_reads + self.total_writes;
        if (total_ops == 0) {
            return;
        }
        std.debug.print("  Top Registers:\n", .{});
        var top_count: u32 = 0;
        var i: u32 = 0;
        while (i < NUM_REGISTERS and top_count < 10) : (i += 1) {
            const entry = &self.entries[i];
            const ops = entry.get_total_ops();
            if (ops > 0) {
                const percentage = @as(f64, @floatFromInt(ops)) /
                    @as(f64, @floatFromInt(total_ops)) * 100.0;
                std.debug.print("    x{}: {} reads, {} writes
({d:.2}%)\n", .{
                    entry.register_num,
                    entry.read_count,
                    entry.write_count,
                    percentage,
                });
                top_count += 1;
            }
        }
    }

    pub fn print_stats(self: *const VMRegisterStats) void {
        std.debug.print("\nVM Register Statistics:\n", .{});
        std.debug.print("  Total Reads: {}\n", .{self.total_reads});
        std.debug.print("  Total Writes: {}\n", .{self.total_writes});
        const total_ops = self.total_reads + self.total_writes;
        std.debug.print("  Total Operations: {}\n", .{total_ops});
        if (total_ops > 0) {
            const read_pct = @as(f64, @floatFromInt(self.total_reads)) /
                @as(f64, @floatFromInt(total_ops)) * 100.0;
            const write_pct = @as(f64, @floatFromInt(self.total_writes))
/
                @as(f64, @floatFromInt(total_ops)) * 100.0;
            std.debug.print("  Read/Write Ratio: {d:.2}% reads, {d:.2}%
writes\n", .{
                read_pct,
                write_pct,
            });
        }
        self.print_top_registers();
    }

    pub fn reset(self: *VMRegisterStats) void {
        self.total_reads = 0;
        self.total_writes = 0;
        var i: u32 = 0;
        while (i < NUM_REGISTERS) : (i += 1) {
            self.entries[i].read_count = 0;
            self.entries[i].write_count = 0;
        }
    }
};


// === kernel_vm/sbi.zig ===

// SPDX-License-Identifier: MIT
// SPDX-FileCopyrightText: Grain Basin kernel - RISC-V SBI wrapper
// Inspired by CascadeOS/zig-sbi (MIT licensed) - see credits in docs

/// RISC-V SBI (Supervisor Binary Interface) wrapper.
/// Grain Style: Minimal, type-safe, comprehensive assertions.
/// Why: Platform runtime services (timer, console, reset) for RISC-V
kernels.
/// Credits: Inspired by CascadeOS/zig-sbi (MIT licensed).

const std = @import("std");

/// SBI Extension ID (EID) for legacy functions.
/// Why: Legacy SBI functions use EID as function ID directly.
pub const EID = enum(u32) {
    /// Set timer (legacy).
    LEGACY_SET_TIMER = 0x0,
    /// Console putchar (legacy) - write character to console.
    LEGACY_CONSOLE_PUTCHAR = 0x1,
    /// Console getchar (legacy) - read character from console.
    LEGACY_CONSOLE_GETCHAR = 0x2,
    /// Clear IPI (legacy).
    LEGACY_CLEAR_IPI = 0x3,
    /// Send IPI (legacy).
    LEGACY_SEND_IPI = 0x4,
    /// Remote fence I (legacy).
    LEGACY_REMOTE_FENCE_I = 0x5,
    /// Remote SFENCE VMA (legacy).
    LEGACY_REMOTE_SFENCE_VMA = 0x6,
    /// Remote SFENCE VMA with ASID (legacy).
    LEGACY_REMOTE_SFENCE_VMA_ASID = 0x7,
    /// Shutdown (legacy) - system shutdown/reboot.
    LEGACY_SHUTDOWN = 0x8,
};

/// SBI error codes.
/// Why: Standard SBI error return values.
pub const SBIError = enum(i64) {
    /// Success (no error).
    Success = 0,
    /// Failed (unspecified error).
    Failed = -1,
    /// Not supported (function not available).
    NotSupported = -2,
    /// Invalid parameter.
    InvalidParameter = -3,
    /// Denied (permission denied).
    Denied = -4,
    /// Invalid address.
    InvalidAddress = -5,
};

/// SBI console putchar result.
/// Why: Type-safe result for console output.
pub const ConsolePutcharResult = enum(u64) {
    /// Success (character written).
    Success = 0,
    _,
};

/// SBI console getchar result.
/// Why: Type-safe result for console input.
pub const ConsoleGetcharResult = enum(i64) {
    /// No character available (non-blocking).
    NoChar = -1,
    _,
};

/// Check if SBI function ID is legacy (< 10).
/// Why: Legacy SBI functions use EID directly as function ID.
pub fn is_legacy_sbi(eid: u32) bool {
    // Assert: EID must be valid (< 10 for legacy).
    std.debug.assert(eid < 10);
    return eid < 10;
}

/// Get SBI error code from return value.
/// Why: Convert SBI return value to error code.
pub fn get_sbi_error(result: i64) SBIError {
    // Assert: result must be valid error code.
    std.debug.assert(result <= 0);
    
    // Convert to error enum.
    return switch (result) {
        @intFromEnum(SBIError.Success) => .Success,
        @intFromEnum(SBIError.Failed) => .Failed,
        @intFromEnum(SBIError.NotSupported) => .NotSupported,
        @intFromEnum(SBIError.InvalidParameter) => .InvalidParameter,
        @intFromEnum(SBIError.Denied) => .Denied,
        @intFromEnum(SBIError.InvalidAddress) => .InvalidAddress,
        else => .Failed, // Unknown error -> Failed.
    };
}

/// SBI console putchar (write character to console).
/// Why: Standard RISC-V console output function.
/// Calling convention: character in a0 (x10), returns 0 on success.
pub fn console_putchar(character: u8) ConsolePutcharResult {
    // Assert: character must be valid (always true for u8).
    _ = character;
    
    // Note: Actual SBI call would use inline assembly here.
    // In VM, this is handled by VM's handle_sbi_call.
    // This function is for type safety and documentation.
    
    // Return success (VM will handle actual output).
    return .Success;
}

/// SBI console getchar (read character from console).
/// Why: Standard RISC-V console input function.
/// Calling convention: returns character in a0 (x10), or -1 if no
character.
pub fn console_getchar() ConsoleGetcharResult {
    // Note: Actual SBI call would use inline assembly here.
    // In VM, this is handled by VM's handle_sbi_call.
    // This function is for type safety and documentation.
    
    // Return no character (non-blocking).
    return .NoChar;
}

/// SBI shutdown (system shutdown/reboot).
/// Why: Standard RISC-V shutdown function.
/// Calling convention: no arguments, doesn't return.
pub fn shutdown() noreturn {
    // Note: Actual SBI call would use inline assembly here.
    // In VM, this is handled by VM's handle_sbi_call.
    // This function is for type safety and documentation.
    
    // Shutdown never returns.
    while (true) {
        std.Thread.yield();
    }
}

/// SBI set timer (set timer interrupt).
/// Why: Standard RISC-V timer function.
/// Calling convention: time_value in a0 (x10), no return value.
pub fn set_timer(time_value: u64) void {
    // Assert: time_value must be valid (always true for u64).
    _ = time_value;
    
    // Note: Actual SBI call would use inline assembly here.
    // In VM, this is handled by VM's handle_sbi_call.
    // This function is for type safety and documentation.
}


// === kernel_vm/serial.zig ===

const std = @import("std");

/// Serial output buffer for kernel printf/debug output.
/// Grain Style: Static allocation, deterministic output.
/// ~<~ Glow Waterbend: Serial output flows deterministically.

/// Serial output buffer (64KB static allocation).
/// Why: Static allocation eliminates allocator dependency.
const SERIAL_BUFFER_SIZE: usize = 64 * 1024;

/// Serial output handler.
/// Why: Capture kernel serial output for display in VM pane.
pub const SerialOutput = struct {
    /// Output buffer (circular buffer).
    buffer: [SERIAL_BUFFER_SIZE]u8 = [_]u8{0} ** SERIAL_BUFFER_SIZE,
    /// Write position (circular buffer head).
    write_pos: usize = 0,
    /// Read position (circular buffer tail, for display).
    read_pos: usize = 0,
    /// Total bytes written (for overflow detection).
    total_written: usize = 0,

    const Self = @This();

    /// Write byte to serial output.
    /// Why: Handle kernel serial writes (e.g., printf output via
SBI_CONSOLE_PUTCHAR).
    /// Grain Style: Comprehensive assertions for buffer management and
circular buffer wrapping.
    pub fn writeByte(self: *Self, byte: u8) void {
        // Assert: self pointer must be valid.
        const self_ptr = @intFromPtr(self);
        std.debug.assert(self_ptr != 0);
        std.debug.assert(self_ptr % @alignOf(Self) == 0);
        
        // Assert: buffer must be initialized (non-empty).
        std.debug.assert(self.buffer.len == SERIAL_BUFFER_SIZE);
        std.debug.assert(self.buffer.len > 0);
        
        // Assert: write position must be within buffer bounds.
        std.debug.assert(self.write_pos < SERIAL_BUFFER_SIZE);
        
        // Assert: total_written must be valid (non-negative, can wrap).
        // Note: total_written can wrap (usize overflow), but that's OK
for counting.
        
        // Store old write position for validation.
        const old_write_pos = self.write_pos;
        const old_total_written = self.total_written;
        
        // Write byte to buffer (circular buffer).
        self.buffer[self.write_pos] = byte;
        self.write_pos = (self.write_pos + 1) % SERIAL_BUFFER_SIZE;
        self.total_written += 1;
        
        // Assert: byte must be written correctly.
        std.debug.assert(self.buffer[old_write_pos] == byte);
        
        // Assert: write position must wrap correctly.
        std.debug.assert(self.write_pos < SERIAL_BUFFER_SIZE);
        
        // Assert: write position must advance (or wrap).
        if (old_write_pos < SERIAL_BUFFER_SIZE - 1) {
            std.debug.assert(self.write_pos == old_write_pos + 1);
        } else {
            // Wrapped: write_pos should be 0.
            std.debug.assert(self.write_pos == 0);
        }
        
        // Assert: total_written must increment.
        std.debug.assert(self.total_written == old_total_written + 1);
    }

    /// Write string to serial output.
    /// Why: Handle kernel string output (e.g., printf format strings).
    pub fn writeString(self: *Self, str: []const u8) void {
        // Assert: string must be non-empty.
        std.debug.assert(str.len > 0);
        
        for (str) |byte| {
            self.writeByte(byte);
        }
    }

    /// Get serial output as string (for display).
    /// Why: Return serial output for rendering in VM pane.
    pub fn get_output(self: *const Self) []const u8 {
        // Return entire buffer (circular buffer, may contain old data).
        // Future: Implement proper circular buffer reading.
        return &self.buffer;
    }

    /// Clear serial output buffer.
    /// Why: Reset output for clean display.
    pub fn clear(self: *Self) void {
        @memset(&self.buffer, 0);
        self.write_pos = 0;
        self.read_pos = 0;
        self.total_written = 0;
        
        // Assert: buffer must be cleared.
        std.debug.assert(self.buffer[0] == 0);
        std.debug.assert(self.write_pos == 0);
        std.debug.assert(self.read_pos == 0);
    }
};


// === kernel_vm/state_inspection.zig ===

//! VM State Inspection System
//!
//! Objective: Provide state inspection capabilities (registers, memory,
stack).
//! Why: Enable debugging tools to inspect VM state when breakpoints are
hit.
//! GrainStyle: Static allocation, bounded buffers, explicit types,
deterministic inspection.
//!
//! Methodology:
//! - Register inspection (read all 32 registers + PC)
//! - Memory inspection (read memory at specific addresses)
//! - Stack inspection (read stack region)
//! - State snapshot (capture complete VM state)
//! - Bounded memory dumps (MAX_DUMP_SIZE: 1KB per dump)
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded buffers: fixed-size memory dump buffers
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive state inspection, deterministic behavior,
explicit limits

const std = @import("std");
const VM = @import("vm.zig").VM;

// Bounded: Maximum dump size for memory inspection (1KB per dump).
pub const MAX_DUMP_SIZE: u32 = 1024;
// Bounded: Maximum stack inspection size (1KB stack region).
pub const MAX_STACK_SIZE: u32 = 1024;

// Register state snapshot (all 32 registers + PC).
pub const RegisterState = struct {
    regs: [32]u64,
    pc: u64,

    pub fn init() RegisterState {
        return RegisterState{
            .regs = [_]u64{0} ** 32,
            .pc = 0,
        };
    }
};

// Memory dump (bounded buffer for memory inspection).
pub const MemoryDump = struct {
    address: u64,
    data: [MAX_DUMP_SIZE]u8,
    size: u32,

    pub fn init() MemoryDump {
        return MemoryDump{
            .address = 0,
            .data = [_]u8{0} ** MAX_DUMP_SIZE,
            .size = 0,
        };
    }
};

// VM state inspector.
pub const VMStateInspector = struct {
    vm: *VM,

    pub fn init(vm: *VM) VMStateInspector {
        return VMStateInspector{
            .vm = vm,
        };
    }

    pub fn get_register_state(self: *const VMStateInspector)
RegisterState {
        var state = RegisterState.init();
        var i: u32 = 0;
        while (i < 32) : (i += 1) {
            state.regs[i] = self.vm.regs.get(@as(u5, @intCast(i)));
        }
        state.pc = self.vm.regs.pc;
        return state;
    }

    pub fn get_register(self: *const VMStateInspector, reg_num: u32) u64
{
        std.debug.assert(reg_num < 32);
        return self.vm.regs.get(@as(u5, @intCast(reg_num)));
    }

    pub fn get_pc(self: *const VMStateInspector) u64 {
        return self.vm.regs.pc;
    }

    pub fn dump_memory(self: *const VMStateInspector, address: u64,
size: u32) ?MemoryDump {
        if (size > MAX_DUMP_SIZE) {
            return null;
        }
        const addr_u32 = @as(u32, @intCast(address));
        if (addr_u32 + size > self.vm.memory_size) {
            return null;
        }
        var dump = MemoryDump.init();
        dump.address = address;
        dump.size = size;
        const start = @as(usize, @intCast(addr_u32));
        @memcpy(dump.data[0..size], self.vm.memory[start..][0..size]);
        return dump;
    }

    pub fn read_memory_u64(self: *const VMStateInspector, address: u64)
?u64 {
        const addr_u32 = @as(u32, @intCast(address));
        if (addr_u32 + 8 > self.vm.memory_size) {
            return null;
        }
        const start = @as(usize, @intCast(addr_u32));
        const bytes = self.vm.memory[start..][0..8];
        return std.mem.readInt(u64, bytes, .little);
    }

    pub fn read_memory_u32(self: *const VMStateInspector, address: u64)
?u32 {
        const addr_u32 = @as(u32, @intCast(address));
        if (addr_u32 + 4 > self.vm.memory_size) {
            return null;
        }
        const start = @as(usize, @intCast(addr_u32));
        const bytes = self.vm.memory[start..][0..4];
        return std.mem.readInt(u32, bytes, .little);
    }

    pub fn dump_stack(self: *const VMStateInspector, stack_pointer: u64)
?MemoryDump {
        const sp_u32 = @as(u32, @intCast(stack_pointer));
        if (sp_u32 >= self.vm.memory_size) {
            return null;
        }
        const dump_size = if (sp_u32 + MAX_STACK_SIZE >
self.vm.memory_size)
            self.vm.memory_size - sp_u32
        else
            MAX_STACK_SIZE;
        return self.dump_memory(stack_pointer, @as(u32,
@intCast(dump_size)));
    }

    pub fn print_register_state(self: *const VMStateInspector) void {
        const state = self.get_register_state();
        std.debug.print("\nVM Register State:\n", .{});
        std.debug.print("  PC: 0x{x}\n", .{state.pc});
        var i: u32 = 0;
        while (i < 32) : (i += 1) {
            if (state.regs[i] != 0 or i == 0) {
                std.debug.print("  x{}: 0x{x}\n", .{ i, state.regs[i] });
            }
        }
    }

    pub fn print_memory_dump(self: *const VMStateInspector, address:
u64, size: u32) void {
        const dump = self.dump_memory(address, size) orelse {
            std.debug.print("Memory dump failed: invalid address or
size\n", .{});
            return;
        };
        std.debug.print("\nMemory Dump at 0x{x} ({} bytes):\n", .{
dump.address, dump.size });
        var i: u32 = 0;
        while (i < dump.size) : (i += 16) {
            const line_size = if (i + 16 > dump.size) dump.size - i else
16;
            std.debug.print("  {:08x}: ", .{dump.address + i});
            var j: u32 = 0;
            while (j < line_size) : (j += 1) {
                std.debug.print("{:02x} ", .{dump.data[i + j]});
            }
            std.debug.print("\n", .{});
        }
    }
};


// === kernel_vm/state_snapshot.zig ===

//! VM State Snapshot System
//!
//! Objective: Save and restore complete VM state for debugging,
testing, and checkpointing.
//! Why: Enable VM state persistence, debugging, and reproducible test
scenarios.
//! GrainStyle: Static allocation, explicit types, deterministic
serialization.
//!
//! Methodology:
//! - Capture complete VM state (registers, memory, flags, performance
metrics)
//! - Serialize to binary format (deterministic, efficient)
//! - Restore from snapshot (reproducible execution)
//! - Validate state consistency (assertions for correctness)
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded buffers: fixed-size structures (no dynamic allocation)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-01-XX
//! GrainStyle: Comprehensive state capture, deterministic behavior,
explicit limits

const std = @import("std");
const VM = @import("vm.zig").VM;
const VMError = VM.VMError;

/// Performance snapshot type.
/// Why: Explicit type for performance metrics.
pub const PerformanceSnapshot = struct {
    instructions_executed: u64,
    cycles_simulated: u64,
    memory_reads: u64,
    memory_writes: u64,
    syscalls: u64,
    jit_compilations: u64,
    jit_cache_hits: u64,
    jit_cache_misses: u64,
    interpreter_fallbacks: u64,
};

/// Exception statistics snapshot type.
/// Why: Explicit type for exception statistics in snapshot.
pub const ExceptionStatsSnapshot = struct {
    /// Exception counts by type (16 exception types).
    exception_counts: [16]u64,
    /// Total exception count.
    total_count: u64,
};

/// VM state snapshot (complete VM state capture).
/// Why: Enable state persistence, debugging, and reproducible execution.
/// GrainStyle: Explicit types, static allocation, deterministic
encoding.
/// Note: Snapshot includes all VM state except JIT code buffer (can be
recompiled).
pub const VMStateSnapshot = struct {
    /// Register file (32 GP registers + PC).
    /// Why: Capture all register state for complete restoration.
    regs: [33]u64, // 32 GP registers + PC
    
    /// Memory snapshot (complete VM memory).
    /// Why: Capture memory state for complete restoration.
    /// Note: Size matches VM_MEMORY_SIZE (8MB default).
    memory: []u8,
    
    /// VM state (running, halted, errored).
    state: u32,
    
    /// Last error (if state == errored).
    last_error: u32,
    
    /// Memory size in bytes.
    memory_size: u64,
    
    /// Performance metrics snapshot.
    /// Why: Capture performance state for analysis.
    performance: PerformanceSnapshot,
    
    /// Error log entry count.
    error_count: u32,
    
    /// Exception statistics snapshot.
    /// Why: Capture exception statistics for debugging and analysis.
    exception_stats: ExceptionStatsSnapshot,
    
    /// JIT enabled flag.
    jit_enabled: bool,
    
    /// Create snapshot from VM state.
    /// Why: Capture current VM state for persistence.
    /// Contract: VM must be initialized, memory buffer must be provided.
    pub fn create(vm: *const VM, memory_buffer: []u8) !VMStateSnapshot {
        // Assert: VM must be initialized (precondition).
        std.debug.assert(vm.memory_size > 0);
        std.debug.assert(vm.memory.len > 0);
        
        // Assert: Memory buffer must be large enough (precondition).
        std.debug.assert(memory_buffer.len >= vm.memory.len);
        
        // Capture register file (32 GP registers + PC).
        var regs: [33]u64 = undefined;
        var i: u32 = 0;
        while (i < 32) : (i += 1) {
            regs[i] = vm.regs.get(@as(u5, @intCast(i)));
        }
        regs[32] = vm.regs.pc;
        
        // Copy memory (complete VM memory).
        @memcpy(memory_buffer[0..vm.memory.len],
vm.memory[0..vm.memory.len]);
        
        // Capture VM state.
        const state_val: u32 = switch (vm.state) {
            .running => 0,
            .halted => 1,
            .errored => 2,
        };
        
        // Capture last error.
        const last_error_val: u32 = if (vm.last_error) |err| blk: {
            if (err == VM.VMError.invalid_instruction) break :blk 0;
            if (err == VM.VMError.invalid_memory_access) break :blk 1;
            if (err == VM.VMError.unaligned_instruction) break :blk 2;
            if (err == VM.VMError.unaligned_memory_access) break :blk 3;
            break :blk 255; // Unknown error
        } else 255; // No error
        
        // Capture performance metrics.
        const perf = vm.performance;
        const performance_snapshot: PerformanceSnapshot = .{
            .instructions_executed = perf.instructions_executed,
            .cycles_simulated = perf.cycles_simulated,
            .memory_reads = perf.memory_reads,
            .memory_writes = perf.memory_writes,
            .syscalls = perf.syscalls,
            .jit_compilations = perf.jit_compilations,
            .jit_cache_hits = perf.jit_cache_hits,
            .jit_cache_misses = perf.jit_cache_misses,
            .interpreter_fallbacks = perf.interpreter_fallbacks,
        };
        
        // Capture exception statistics.
        const exc_stats = vm.exception_stats;
        var exception_counts: [16]u64 = undefined;
        var exc_i: u32 = 0;
        while (exc_i < 16) : (exc_i += 1) {
            exception_counts[exc_i] = exc_stats.exception_counts[exc_i];
        }
        const exception_stats_snapshot: ExceptionStatsSnapshot = .{
            .exception_counts = exception_counts,
            .total_count = exc_stats.total_count,
        };
        
        // Create snapshot.
        const snapshot = VMStateSnapshot{
            .regs = regs,
            .memory = memory_buffer[0..vm.memory.len],
            .state = state_val,
            .last_error = last_error_val,
            .memory_size = vm.memory_size,
            .performance = performance_snapshot,
            .error_count = vm.error_log.entry_count,
            .exception_stats = exception_stats_snapshot,
            .jit_enabled = vm.jit_enabled,
        };
        
        // Assert: Snapshot must be valid (postcondition).
        std.debug.assert(snapshot.memory.len == vm.memory.len);
        std.debug.assert(snapshot.memory_size == vm.memory_size);
        
        return snapshot;
    }
    
    /// Restore VM state from snapshot.
    /// Why: Restore VM to saved state for debugging and testing.
    /// Contract: VM must be initialized, snapshot must be valid.
    pub fn restore(self: *const VMStateSnapshot, vm: *VM) !void {
        // Assert: VM must be initialized (precondition).
        std.debug.assert(vm.memory_size > 0);
        
        // Assert: Snapshot memory size must match VM memory size
(precondition).
        std.debug.assert(self.memory_size == vm.memory_size);
        std.debug.assert(self.memory.len == vm.memory.len);
        
        // Restore register file (32 GP registers + PC).
        var i: u32 = 0;
        while (i < 32) : (i += 1) {
            vm.regs.set(@as(u5, @intCast(i)), self.regs[i]);
        }
        vm.regs.pc = self.regs[32];
        
        // Restore memory (complete VM memory).
        @memcpy(vm.memory[0..self.memory.len],
self.memory[0..self.memory.len]);
        
        // Restore VM state.
        vm.state = switch (self.state) {
            0 => .running,
            1 => .halted,
            2 => .errored,
            else => .halted, // Default to halted for invalid state.
        };
        
        // Restore last error.
        vm.last_error = switch (self.last_error) {
            0 => VMError.invalid_instruction,
            1 => VMError.invalid_memory_access,
            2 => VMError.unaligned_instruction,
            3 => VMError.unaligned_memory_access,
            else => null, // No error.
        };
        
        // Restore performance metrics.
        vm.performance.instructions_executed =
self.performance.instructions_executed;
        vm.performance.cycles_simulated =
self.performance.cycles_simulated;
        vm.performance.memory_reads = self.performance.memory_reads;
        vm.performance.memory_writes = self.performance.memory_writes;
        vm.performance.syscalls = self.performance.syscalls;
        vm.performance.jit_compilations =
self.performance.jit_compilations;
        vm.performance.jit_cache_hits = self.performance.jit_cache_hits;
        vm.performance.jit_cache_misses =
self.performance.jit_cache_misses;
        vm.performance.interpreter_fallbacks =
self.performance.interpreter_fallbacks;
        
        // Restore exception statistics.
        var exc_i: u32 = 0;
        while (exc_i < 16) : (exc_i += 1) {
            vm.exception_stats.exception_counts[exc_i] =
self.exception_stats.exception_counts[exc_i];
        }
        vm.exception_stats.total_count =
self.exception_stats.total_count;
        
        // Note: Error log and JIT state are not restored (can be
recreated).
        // Why: Error log is for debugging, JIT can be recompiled.
        
        // Assert: VM state must be restored correctly (postcondition).
        std.debug.assert(vm.regs.pc == self.regs[32]);
        std.debug.assert(vm.memory_size == self.memory_size);
    }
    
    /// Validate snapshot consistency.
    /// Why: Verify snapshot is valid before restoration.
    /// Returns: true if valid, false otherwise.
    pub fn is_valid(self: *const VMStateSnapshot) bool {
        // Assert: Memory size must be valid.
        if (self.memory_size == 0) {
            return false;
        }
        
        // Assert: Memory buffer must match memory size.
        if (self.memory.len != self.memory_size) {
            return false;
        }
        
        // Assert: State must be valid (0-2).
        if (self.state > 2) {
            return false;
        }
        
        // Assert: PC must be 4-byte aligned (RISC-V requirement).
        if (self.regs[32] % 4 != 0) {
            return false;
        }
        
        return true;
    }
};

// === kernel_vm/stats_aggregator.zig ===

//! VM Statistics Aggregator System
//!
//! Objective: Unified statistics reporting that aggregates all VM
statistics modules.
//! Why: Provide comprehensive VM execution analysis in a single
interface.
//! GrainStyle: Static allocation, explicit types, deterministic
reporting.
//!
//! Methodology:
//! - Aggregate statistics from all VM tracking modules
//! - Provide unified print interface
//! - Calculate derived metrics (ratios, percentages, averages)
//! - Format statistics for easy analysis
//! - Reset all statistics in one call
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded operations: no dynamic allocation
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive statistics aggregation, deterministic
behavior

const std = @import("std");
const VM = @import("vm.zig").VM;

// VM statistics aggregator.
pub const VMStatsAggregator = struct {
    vm: *VM,

    pub fn init(vm: *VM) VMStatsAggregator {
        return VMStatsAggregator{
            .vm = vm,
        };
    }

    fn print_performance_summary(self: *const VMStatsAggregator) void {
        const perf = &self.vm.performance;
        std.debug.print("\n=== Performance Metrics ===\n", .{});
        std.debug.print("  Instructions Executed: {}\n",
.{perf.instructions_executed});
        std.debug.print("  Cycles Simulated: {}\n",
.{perf.cycles_simulated});
        std.debug.print("  Memory Reads: {}\n", .{perf.memory_reads});
        std.debug.print("  Memory Writes: {}\n", .{perf.memory_writes});
        std.debug.print("  Syscalls: {}\n", .{perf.syscalls});
    }

    fn print_exception_summary(self: *const VMStatsAggregator) void {
        const exc = &self.vm.exception_stats;
        if (exc.total_count == 0) {
            return;
        }
        std.debug.print("\n=== Exception Statistics ===\n", .{});
        std.debug.print("  Total Exceptions: {}\n", .{exc.total_count});
        exc.print_stats();
    }

    fn print_memory_summary(self: *const VMStatsAggregator) void {
        const mem = &self.vm.memory_stats;
        std.debug.print("\n=== Memory Statistics ===\n", .{});
        std.debug.print("  Total Memory: {} bytes\n",
.{mem.total_memory_bytes});
        std.debug.print("  Used Memory: {} bytes\n",
.{mem.used_memory_bytes});
        if (mem.total_memory_bytes > 0) {
            const usage_pct = @as(f64,
@floatFromInt(mem.used_memory_bytes)) /
                @as(f64, @floatFromInt(mem.total_memory_bytes)) * 100.0;
            std.debug.print("  Memory Usage: {d:.2}%\n", .{usage_pct});
        }
        std.debug.print("  Total Reads: {}\n", .{mem.total_reads});
        std.debug.print("  Total Writes: {}\n", .{mem.total_writes});
    }

    fn print_instruction_summary(self: *const VMStatsAggregator) void {
        const inst = &self.vm.instruction_stats;
        if (inst.total_instructions == 0) {
            return;
        }
        std.debug.print("\n=== Instruction Statistics ===\n", .{});
        inst.print_stats();
    }

    fn print_syscall_summary(self: *const VMStatsAggregator) void {
        const sys = &self.vm.syscall_stats;
        if (sys.total_syscalls == 0) {
            return;
        }
        std.debug.print("\n=== Syscall Statistics ===\n", .{});
        sys.print_stats();
    }

    fn print_execution_flow_summary(self: *const VMStatsAggregator) void
{
        const flow = &self.vm.execution_flow;
        if (flow.total_instructions == 0) {
            return;
        }
        std.debug.print("\n=== Execution Flow Statistics ===\n", .{});
        flow.print_stats();
    }

    fn print_register_summary(self: *const VMStatsAggregator) void {
        const reg = &self.vm.register_stats;
        const total_ops = reg.total_reads + reg.total_writes;
        if (total_ops == 0) {
            return;
        }
        std.debug.print("\n=== Register Statistics ===\n", .{});
        reg.print_stats();
    }

    fn print_instruction_perf_summary(self: *const VMStatsAggregator)
void {
        const perf = &self.vm.instruction_perf;
        if (perf.total_profiling_time_ns == 0) {
            return;
        }
        std.debug.print("\n=== Instruction Performance ===\n", .{});
        perf.print_stats();
    }

    pub fn print_all_stats(self: *const VMStatsAggregator) void {
        std.debug.print("\n", .{});
       
std.debug.print("╔══════════════════════════════════════════════════════╗
\n", .{});
        std.debug.print("║         VM Statistics Summary                
║\n", .{});
       
std.debug.print("╚══════════════════════════════════════════════════════╝
\n", .{});
        self.print_performance_summary();
        self.print_exception_summary();
        self.print_memory_summary();
        self.print_instruction_summary();
        self.print_syscall_summary();
        self.print_execution_flow_summary();
        self.print_register_summary();
        self.print_instruction_perf_summary();
        std.debug.print("\n", .{});
    }

    pub fn reset_all_stats(self: *VMStatsAggregator) void {
        self.vm.performance = .{};
        self.vm.exception_stats =
exception_stats_mod.ExceptionStats.init();
        self.vm.memory_stats.reset();
        self.vm.instruction_stats.reset();
        self.vm.syscall_stats.reset();
        self.vm.execution_flow.reset();
        self.vm.register_stats.reset();
        self.vm.instruction_perf.reset();
    }

    pub fn export_to_json(self: *VMStatsAggregator) []const u8 {
        const export_mod = @import("stats_export.zig");
        var exporter = export_mod.VMStatsExporter.init(self.vm);
        return exporter.export_to_json();
    }
};

const exception_stats_mod = @import("exception_stats.zig");


// === kernel_vm/stats_export.zig ===

//! VM Statistics Export System
//!
//! Objective: Export VM statistics to JSON format for analysis and
visualization.
//! Why: Enable external tools to analyze VM performance, memory usage,
and execution patterns.
//! GrainStyle: Static allocation, bounded buffers, explicit types,
deterministic export.
//!
//! Methodology:
//! - Export all VM statistics to JSON format
//! - Bounded JSON buffer (MAX_JSON_SIZE: 1MB)
//! - Structured JSON output (performance, exceptions, memory,
instructions, syscalls, flow, registers, branches, perf)
//! - Provide export interface for all statistics modules
//! - Reset capability for new measurement periods
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded buffers: fixed-size JSON buffer (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive statistics export, deterministic behavior,
explicit limits

const std = @import("std");
const VM = @import("vm.zig").VM;

// Bounded: Maximum JSON export size (1MB should be sufficient for all
statistics).
pub const MAX_JSON_SIZE: u32 = 1024 * 1024;

// VM statistics exporter.
pub const VMStatsExporter = struct {
    vm: *VM,
    json_buffer: [MAX_JSON_SIZE]u8,
    json_len: u32,

    pub fn init(vm: *VM) VMStatsExporter {
        return VMStatsExporter{
            .vm = vm,
            .json_buffer = undefined,
            .json_len = 0,
        };
    }

    fn append_json(self: *VMStatsExporter, text: []const u8) void {
        const remaining = MAX_JSON_SIZE - self.json_len;
        if (remaining < text.len) {
            return;
        }
        @memcpy(self.json_buffer[self.json_len..][0..text.len], text);
        self.json_len += @as(u32, @intCast(text.len));
    }

    fn export_performance(self: *VMStatsExporter) void {
        const perf = &self.vm.performance;
        var buf: [256]u8 = undefined;
        const json = std.fmt.bufPrint(&buf,
            \\"performance": {{
            \\  "instructions_executed": {},
            \\  "cycles_simulated": {},
            \\  "memory_reads": {},
            \\  "memory_writes": {},
            \\  "syscalls": {}
            \\}},
        , .{
            perf.instructions_executed,
            perf.cycles_simulated,
            perf.memory_reads,
            perf.memory_writes,
            perf.syscalls,
        }) catch return;
        self.append_json(json);
    }

    fn export_exceptions(self: *VMStatsExporter) void {
        const exc = &self.vm.exception_stats;
        if (exc.total_count == 0) {
            self.append_json("\"exceptions\": {}");
            return;
        }
        var buf: [512]u8 = undefined;
        const json = std.fmt.bufPrint(&buf,
            \\"exceptions": {{
            \\  "total_count": {}
            \\}},
        , .{exc.total_count}) catch return;
        self.append_json(json);
    }

    fn export_memory(self: *VMStatsExporter) void {
        const mem = &self.vm.memory_stats;
        var buf: [256]u8 = undefined;
        const json = std.fmt.bufPrint(&buf,
            \\"memory": {{
            \\  "total_memory_bytes": {},
            \\  "used_memory_bytes": {},
            \\  "total_reads": {},
            \\  "total_writes": {},
            \\  "total_bytes_read": {},
            \\  "total_bytes_written": {}
            \\}},
        , .{
            mem.total_memory_bytes,
            mem.used_memory_bytes,
            mem.total_reads,
            mem.total_writes,
            mem.total_bytes_read,
            mem.total_bytes_written,
        }) catch return;
        self.append_json(json);
    }

    fn export_instructions(self: *VMStatsExporter) void {
        const inst = &self.vm.instruction_stats;
        if (inst.total_instructions == 0) {
            self.append_json("\"instructions\": {}");
            return;
        }
        var buf: [256]u8 = undefined;
        const json = std.fmt.bufPrint(&buf,
            \\"instructions": {{
            \\  "total_instructions": {}
            \\}},
        , .{inst.total_instructions}) catch return;
        self.append_json(json);
    }

    fn export_syscalls(self: *VMStatsExporter) void {
        const sys = &self.vm.syscall_stats;
        if (sys.total_syscalls == 0) {
            self.append_json("\"syscalls\": {}");
            return;
        }
        var buf: [256]u8 = undefined;
        const json = std.fmt.bufPrint(&buf,
            \\"syscalls": {{
            \\  "total_syscalls": {}
            \\}},
        , .{sys.total_syscalls}) catch return;
        self.append_json(json);
    }

    fn export_execution_flow(self: *VMStatsExporter) void {
        const flow = &self.vm.execution_flow;
        if (flow.total_instructions == 0) {
            self.append_json("\"execution_flow\": {}");
            return;
        }
        var buf: [256]u8 = undefined;
        const json = std.fmt.bufPrint(&buf,
            \\"execution_flow": {{
            \\  "total_instructions": {}
            \\}},
        , .{flow.total_instructions}) catch return;
        self.append_json(json);
    }

    fn export_registers(self: *VMStatsExporter) void {
        const reg = &self.vm.register_stats;
        const total_ops = reg.total_reads + reg.total_writes;
        if (total_ops == 0) {
            self.append_json("\"registers\": {}");
            return;
        }
        var buf: [256]u8 = undefined;
        const json = std.fmt.bufPrint(&buf,
            \\"registers": {{
            \\  "total_reads": {},
            \\  "total_writes": {}
            \\}},
        , .{ reg.total_reads, reg.total_writes }) catch return;
        self.append_json(json);
    }

    fn export_branches(self: *VMStatsExporter) void {
        const branch = &self.vm.branch_stats;
        if (branch.total_branches == 0) {
            self.append_json("\"branches\": {}");
            return;
        }
        var buf: [256]u8 = undefined;
        const json = std.fmt.bufPrint(&buf,
            \\"branches": {{
            \\  "total_branches": {},
            \\  "total_taken": {},
            \\  "total_not_taken": {}
            \\}},
        , .{
            branch.total_branches,
            branch.total_taken,
            branch.total_not_taken,
        }) catch return;
        self.append_json(json);
    }

    fn export_instruction_perf(self: *VMStatsExporter) void {
        const perf = &self.vm.instruction_perf;
        if (perf.total_profiling_time_ns == 0) {
            self.append_json("\"instruction_perf\": {}");
            return;
        }
        var buf: [256]u8 = undefined;
        const json = std.fmt.bufPrint(&buf,
            \\"instruction_perf": {{
            \\  "total_profiling_time_ns": {},
            \\  "unique_opcodes": {}
            \\}},
        , .{ perf.total_profiling_time_ns, perf.entries_len }) catch
return;
        self.append_json(json);
    }

    pub fn export_to_json(self: *VMStatsExporter) []const u8 {
        self.json_len = 0;
        self.append_json("{\n");
        self.export_performance();
        self.append_json(",\n");
        self.export_exceptions();
        self.append_json(",\n");
        self.export_memory();
        self.append_json(",\n");
        self.export_instructions();
        self.append_json(",\n");
        self.export_syscalls();
        self.append_json(",\n");
        self.export_execution_flow();
        self.append_json(",\n");
        self.export_registers();
        self.append_json(",\n");
        self.export_branches();
        self.append_json(",\n");
        self.export_instruction_perf();
        self.append_json("\n}\n");
        return self.json_buffer[0..self.json_len];
    }
};


// === kernel_vm/syscall.zig ===

//! Grain Basin kernel syscall integration for RISC-V VM.
//! Why: Separate syscall handling from VM core to avoid circular
dependencies.

const std = @import("std");

/// Handle ECALL syscall with Grain Basin kernel.
/// Why: Separate function that can be called from VM when basin_kernel
is available.
pub fn handleSyscall(
    kernel: anytype,
    syscall_num: u32,
    arg1: u64,
    arg2: u64,
    arg3: u64,
    arg4: u64,
) @TypeOf(kernel.handleSyscall(arg1, arg2, arg3, arg4)) {
    return kernel.handleSyscall(syscall_num, arg1, arg2, arg3, arg4);
}


// === kernel_vm/syscall_stats.zig ===

//! VM Syscall Execution Statistics Tracking System
//!
//! Objective: Track syscall execution frequency and patterns for VM
monitoring.
//! Why: Monitor which syscalls are executed most, identify kernel usage
patterns.
//! GrainStyle: Static allocation, bounded counters, explicit types,
deterministic tracking.
//!
//! Methodology:
//! - Track execution count per syscall number
//! - Track total syscalls executed
//! - Track syscall categories (process, memory, I/O, IPC, system)
//! - Provide statistics interface for querying syscall data
//! - Reset capability for new measurement periods
//!
//! TigerStyle Principles:
//! - Explicit types: u32/u64 instead of usize
//! - Bounded counters: fixed-size counters (no overflow issues)
//! - Pair assertions: preconditions and postconditions
//! - Comments explain why: methodology and rationale documented
//! - Static allocation: no dynamic allocation after initialization
//!
//! Date: 2025-11-24
//! GrainStyle: Comprehensive syscall tracking, deterministic behavior,
explicit limits

const std = @import("std");

// Bounded: Max syscall numbers to track (kernel has ~20 syscalls).
pub const MAX_SYSCALLS: u32 = 32;

// Syscall category enumeration.
pub const SyscallCategory = enum(u8) {
    process = 0,
    memory = 1,
    io = 2,
    ipc = 3,
    system = 4,
    other = 5,
};

// Syscall execution entry: tracks execution count for a syscall number.
pub const SyscallEntry = struct {
    syscall_number: u32,
    execution_count: u64,
    category: SyscallCategory,

    pub fn init(syscall_number: u32, category: SyscallCategory)
SyscallEntry {
        std.debug.assert(syscall_number < 256);
        return SyscallEntry{
            .syscall_number = syscall_number,
            .execution_count = 0,
            .category = category,
        };
    }
};

// VM syscall statistics tracker.
pub const VMSyscallStats = struct {
    entries: [MAX_SYSCALLS]SyscallEntry,
    entries_len: u32,
    total_syscalls: u64,

    pub fn init() VMSyscallStats {
        var stats = VMSyscallStats{
            .entries = undefined,
            .entries_len = 0,
            .total_syscalls = 0,
        };
        var i: u32 = 0;
        while (i < MAX_SYSCALLS) : (i += 1) {
            stats.entries[i] = SyscallEntry.init(0, .other);
        }
        return stats;
    }

    fn get_category_for_syscall(syscall_number: u32) SyscallCategory {
        // Categorize kernel syscalls.
        switch (syscall_number) {
            0, 1, 2, 3 => return .process, // spawn, exit, yield, wait
            4, 5, 6 => return .memory, // map, unmap, protect
            7, 8, 9 => return .io, // open, read, write, close
            10, 11, 12 => return .ipc, // channel_create, channel_send,
channel_recv
            13, 14, 15 => return .system, // clock_gettime, sleep_until,
sysinfo
            else => return .other,
        }
    }

    fn find_or_add_entry(self: *VMSyscallStats, syscall_number: u32)
?u32 {
        std.debug.assert(syscall_number < 256);
        // Find existing entry.
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            if (self.entries[i].syscall_number == syscall_number) {
                return i;
            }
        }
        // Add new entry if space available.
        if (self.entries_len >= MAX_SYSCALLS) {
            return null;
        }
        const idx = self.entries_len;
        const category = get_category_for_syscall(syscall_number);
        self.entries[idx] = SyscallEntry.init(syscall_number, category);
        self.entries_len += 1;
        return idx;
    }

    pub fn record_syscall(self: *VMSyscallStats, syscall_number: u32)
void {
        std.debug.assert(syscall_number < 256);
        self.total_syscalls += 1;
        if (self.find_or_add_entry(syscall_number)) |idx| {
            self.entries[idx].execution_count += 1;
        }
    }

    fn get_category_string(category: SyscallCategory) []const u8 {
        return switch (category) {
            .process => "process",
            .memory => "memory",
            .io => "io",
            .ipc => "ipc",
            .system => "system",
            .other => "other",
        };
    }

    fn print_top_syscalls(self: *const VMSyscallStats) void {
        if (self.total_syscalls == 0 or self.entries_len == 0) {
            return;
        }
        std.debug.print("  Top Syscalls:\n", .{});
        var top_count: u32 = 0;
        var i: u32 = 0;
        while (i < self.entries_len and top_count < 10) : (i += 1) {
            const entry = self.entries[i];
            if (entry.execution_count > 0) {
                const percentage = @as(f64,
@floatFromInt(entry.execution_count)) /
                    @as(f64, @floatFromInt(self.total_syscalls)) * 100.0;
                const category_str = get_category_string(entry.category);
                std.debug.print("    syscall {}: {} ({d:.2}%) [{}]\n", .{
                    entry.syscall_number,
                    entry.execution_count,
                    percentage,
                    category_str,
                });
                top_count += 1;
            }
        }
    }

    pub fn print_stats(self: *const VMSyscallStats) void {
        std.debug.print("\nVM Syscall Statistics:\n", .{});
        std.debug.print("  Total Syscalls: {}\n",
.{self.total_syscalls});
        std.debug.print("  Unique Syscalls: {}\n", .{self.entries_len});
        self.print_top_syscalls();
    }

    pub fn reset(self: *VMSyscallStats) void {
        self.total_syscalls = 0;
        var i: u32 = 0;
        while (i < self.entries_len) : (i += 1) {
            self.entries[i].execution_count = 0;
        }
    }
};


// === kernel_vm/test.zig ===

const std = @import("std");
const kernel_vm = @import("kernel_vm");
const VM = kernel_vm.VM;
const loadKernel = kernel_vm.loadKernel;
const SerialOutput = kernel_vm.SerialOutput;

/// Test RISC-V VM functionality.
/// Grain Style: Comprehensive test coverage, deterministic behavior.
pub fn main() !void {
    std.debug.print("[kernel_vm_test] Testing RISC-V VM...\n", .{});

    // Test 1: VM initialization.
    std.debug.print("[kernel_vm_test] Test 1: VM initialization\n", .{});
    // GrainStyle: Use in-place initialization to avoid stack overflow.
    var vm: VM = undefined;
    VM.init(&vm, &[_]u8{0x13, 0x00, 0x00, 0x00}, 0x1000); // NOP
instruction.
    std.debug.assert(vm.regs.pc == 0x1000);
    std.debug.assert(vm.state == .halted);
    std.debug.print("[kernel_vm_test] ✓ VM initialized correctly\n",
.{});

    // Test 2: Register file (x0 hardwired to zero).
    std.debug.print("[kernel_vm_test] Test 2: Register file (x0
hardwired)\n", .{});
    vm.regs.set(0, 0x12345678);
    const x0_value = vm.regs.get(0);
    std.debug.assert(x0_value == 0); // x0 must always be zero.
    std.debug.print("[kernel_vm_test] ✓ x0 hardwired to zero\n", .{});

    // Test 3: Memory read/write.
    std.debug.print("[kernel_vm_test] Test 3: Memory read/write\n", .{});
    try vm.write64(0x2000, 0xDEADBEEFCAFEBABE);
    const read_value = try vm.read64(0x2000);
    std.debug.assert(read_value == 0xDEADBEEFCAFEBABE);
    std.debug.print("[kernel_vm_test] ✓ Memory read/write works\n", .{});

    // Test 4: Instruction fetch.
    std.debug.print("[kernel_vm_test] Test 4: Instruction fetch\n", .{});
    vm.regs.pc = 0x1000;
    const inst = try vm.fetch_instruction();
    std.debug.assert(inst == 0x00000013); // NOP (ADDI x0, x0, 0).
    std.debug.print("[kernel_vm_test] ✓ Instruction fetch works\n", .{});

    // Test 5: Serial output.
    std.debug.print("[kernel_vm_test] Test 5: Serial output\n", .{});
    var serial = SerialOutput{};
    serial.writeString("Hello, RISC-V!\n");
    const output = serial.get_output();
    std.debug.assert(output.len > 0);
    std.debug.print("[kernel_vm_test] ✓ Serial output works\n", .{});

    // Test 6: ADD instruction.
    std.debug.print("[kernel_vm_test] Test 6: ADD instruction\n", .{});
    // ADD x1, x2, x3: x1 = x2 + x3
    // Encoding: funct7(0) | rs2(3) | rs1(2) | 000 | rd(1) | 0110011
    // = 0x003100B3
    // Little-endian bytes: [0xB3, 0x00, 0x31, 0x00]
    // Add ECALL after to halt VM (0x00000073)
    const add_kernel = [_]u8{ 0xB3, 0x00, 0x31, 0x00, 0x73, 0x00, 0x00,
0x00 };
    // Reuse existing VM to avoid stack overflow (4MB array).
    @memset(&vm.memory, 0);
    @memcpy(vm.memory[0x1000..][0..add_kernel.len], &add_kernel);
    vm.regs.pc = 0x1000;
    vm.state = .halted;
    vm.regs.set(2, 10); // x2 = 10
    vm.regs.set(3, 20); // x3 = 20
    vm.start();
    
    // Assert: VM state must be running before step.
    std.debug.assert(vm.state == .running);
    
    // Execute ADD instruction.
    try vm.step();
    
    // Assert: VM state must be valid after step (not errored).
    std.debug.assert(vm.state != .errored);
    
    const add_result = vm.regs.get(1);
    std.debug.assert(add_result == 30); // x1 = 10 + 20 = 30
    std.debug.print("[kernel_vm_test] ✓ ADD instruction works\n", .{});

    // Test 7: SUB instruction.
    std.debug.print("[kernel_vm_test] Test 7: SUB instruction\n", .{});
    // SUB x1, x2, x3: x1 = x2 - x3
    // Encoding: funct7(0x20) | rs2(3) | rs1(2) | 000 | rd(1) | 0110011
    // = 0x403100B3
    // Little-endian bytes: [0xB3, 0x00, 0x31, 0x40]
    // Add ECALL after to halt VM (0x00000073)
    const sub_kernel = [_]u8{ 0xB3, 0x00, 0x31, 0x40, 0x73, 0x00, 0x00,
0x00 };
    // Reuse existing VM to avoid stack overflow.
    @memset(&vm.memory, 0);
    @memcpy(vm.memory[0x1000..][0..sub_kernel.len], &sub_kernel);
    vm.regs.pc = 0x1000;
    vm.state = .halted;
    vm.regs.set(2, 30); // x2 = 30
    vm.regs.set(3, 10); // x3 = 10
    vm.start();
    try vm.step();
    const sub_result = vm.regs.get(1);
    std.debug.assert(sub_result == 20); // x1 = 30 - 10 = 20
    std.debug.print("[kernel_vm_test] ✓ SUB instruction works\n", .{});

    // Test 8: SLT instruction (signed comparison).
    std.debug.print("[kernel_vm_test] Test 8: SLT instruction\n", .{});
    // SLT x1, x2, x3: x1 = (x2 < x3) ? 1 : 0
    // Encoding: funct7(0) | rs2(3) | rs1(2) | 010 | rd(1) | 0110011
    // = 0x003120B3
    // Little-endian bytes: [0xB3, 0x20, 0x31, 0x00]
    // Add ECALL after to halt VM (0x00000073)
    const slt_kernel = [_]u8{ 0xB3, 0x20, 0x31, 0x00, 0x73, 0x00, 0x00,
0x00 };
    // Reuse existing VM to avoid stack overflow.
    @memset(&vm.memory, 0);
    @memcpy(vm.memory[0x1000..][0..slt_kernel.len], &slt_kernel);
    vm.regs.pc = 0x1000;
    vm.state = .halted;
    vm.regs.set(2, 10); // x2 = 10
    vm.regs.set(3, 20); // x3 = 20
    vm.start();
    try vm.step();
    const slt_result_lt = vm.regs.get(1);
    std.debug.assert(slt_result_lt == 1); // 10 < 20, so x1 = 1
    std.debug.print("[kernel_vm_test] ✓ SLT instruction works (10 <
20)\n", .{});

    // Test SLT with reversed operands (should return 0).
    @memset(&vm.memory, 0);
    @memcpy(vm.memory[0x1000..][0..slt_kernel.len], &slt_kernel);
    vm.regs.pc = 0x1000;
    vm.state = .halted;
    vm.regs.set(2, 20); // x2 = 20
    vm.regs.set(3, 10); // x3 = 10
    vm.start();
    try vm.step();
    const slt_result_gt = vm.regs.get(1);
    std.debug.assert(slt_result_gt == 0); // 20 < 10 is false, so x1 = 0
    std.debug.print("[kernel_vm_test] ✓ SLT instruction works (20 <
10)\n", .{});

    // Test SLT with negative numbers (signed comparison).
    @memset(&vm.memory, 0);
    @memcpy(vm.memory[0x1000..][0..slt_kernel.len], &slt_kernel);
    vm.regs.pc = 0x1000;
    vm.state = .halted;
    vm.regs.set(2, @as(u64, @bitCast(@as(i64, -10)))); // x2 = -10
(signed)
    vm.regs.set(3, 10); // x3 = 10
    vm.start();
    try vm.step();
    const slt_result_neg = vm.regs.get(1);
    std.debug.assert(slt_result_neg == 1); // -10 < 10, so x1 = 1
    std.debug.print("[kernel_vm_test] ✓ SLT instruction works (signed
comparison)\n", .{});

    // Test 9: OR instruction (bitwise OR).
    std.debug.print("[kernel_vm_test] Test 9: OR instruction\n", .{});
    // OR x1, x2, x3: x1 = x2 | x3
    // Encoding: funct7(0) | rs2(3) | rs1(2) | 110 | rd(1) | 0110011
    // = 0x003160B3
    // Little-endian bytes: [0xB3, 0x60, 0x31, 0x00]
    // Add ECALL after to halt VM (0x00000073)
    const or_kernel = [_]u8{ 0xB3, 0x60, 0x31, 0x00, 0x73, 0x00, 0x00,
0x00 };
    @memset(&vm.memory, 0);
    @memcpy(vm.memory[0x1000..][0..or_kernel.len], &or_kernel);
    vm.regs.pc = 0x1000;
    vm.state = .halted;
    vm.regs.set(2, 0b1010); // x2 = 0b1010 (10 decimal)
    vm.regs.set(3, 0b1100); // x3 = 0b1100 (12 decimal)
    vm.start();
    try vm.step();
    const or_result = vm.regs.get(1);
    std.debug.assert(or_result == 0b1110); // x1 = 0b1010 | 0b1100 =
0b1110 (14 decimal)
    std.debug.print("[kernel_vm_test] ✓ OR instruction works\n", .{});

    // Test 10: AND instruction (bitwise AND).
    std.debug.print("[kernel_vm_test] Test 10: AND instruction\n", .{});
    // AND x1, x2, x3: x1 = x2 & x3
    // Encoding: funct7(0) | rs2(3) | rs1(2) | 111 | rd(1) | 0110011
    // = 0x003170B3
    // Little-endian bytes: [0xB3, 0x70, 0x31, 0x00]
    // Add ECALL after to halt VM (0x00000073)
    const and_kernel = [_]u8{ 0xB3, 0x70, 0x31, 0x00, 0x73, 0x00, 0x00,
0x00 };
    @memset(&vm.memory, 0);
    @memcpy(vm.memory[0x1000..][0..and_kernel.len], &and_kernel);
    vm.regs.pc = 0x1000;
    vm.state = .halted;
    vm.regs.set(2, 0b1010); // x2 = 0b1010 (10 decimal)
    vm.regs.set(3, 0b1100); // x3 = 0b1100 (12 decimal)
    vm.start();
    try vm.step();
    const and_result = vm.regs.get(1);
    std.debug.assert(and_result == 0b1000); // x1 = 0b1010 & 0b1100 =
0b1000 (8 decimal)
    std.debug.print("[kernel_vm_test] ✓ AND instruction works\n", .{});

    // Test 11: XOR instruction (bitwise XOR).
    std.debug.print("[kernel_vm_test] Test 11: XOR instruction\n", .{});
    // XOR x1, x2, x3: x1 = x2 ^ x3
    // Encoding: funct7(0) | rs2(3) | rs1(2) | 100 | rd(1) | 0110011
    // = 0x003140B3
    // Little-endian bytes: [0xB3, 0x40, 0x31, 0x00]
    // Add ECALL after to halt VM (0x00000073)
    const xor_kernel = [_]u8{ 0xB3, 0x40, 0x31, 0x00, 0x73, 0x00, 0x00,
0x00 };
    @memset(&vm.memory, 0);
    @memcpy(vm.memory[0x1000..][0..xor_kernel.len], &xor_kernel);
    vm.regs.pc = 0x1000;
    vm.state = .halted;
    vm.regs.set(2, 0b1010); // x2 = 0b1010 (10 decimal)
    vm.regs.set(3, 0b1100); // x3 = 0b1100 (12 decimal)
    vm.start();
    try vm.step();
    const xor_result = vm.regs.get(1);
    std.debug.assert(xor_result == 0b0110); // x1 = 0b1010 ^ 0b1100 =
0b0110 (6 decimal)
    std.debug.print("[kernel_vm_test] ✓ XOR instruction works\n", .{});

    // Test 12: SLL instruction (shift left logical).
    std.debug.print("[kernel_vm_test] Test 12: SLL instruction\n", .{});
    // SLL x1, x2, x3: x1 = x2 << x3
    // Encoding: funct7(0) | rs2(3) | rs1(2) | 001 | rd(1) | 0110011
    // = 0x003110B3
    // Little-endian bytes: [0xB3, 0x10, 0x31, 0x00]
    // Add ECALL after to halt VM (0x00000073)
    const sll_kernel = [_]u8{ 0xB3, 0x10, 0x31, 0x00, 0x73, 0x00, 0x00,
0x00 };
    @memset(&vm.memory, 0);
    @memcpy(vm.memory[0x1000..][0..sll_kernel.len], &sll_kernel);
    vm.regs.pc = 0x1000;
    vm.state = .halted;
    vm.regs.set(2, 0b1010); // x2 = 0b1010 (10 decimal)
    vm.regs.set(3, 2); // x3 = 2 (shift by 2)
    vm.start();
    try vm.step();
    const sll_result = vm.regs.get(1);
    std.debug.assert(sll_result == 0b101000); // x1 = 0b1010 << 2 =
0b101000 (40 decimal)
    std.debug.print("[kernel_vm_test] ✓ SLL instruction works\n", .{});

    // Test 13: SRL instruction (shift right logical).
    std.debug.print("[kernel_vm_test] Test 13: SRL instruction\n", .{});
    // SRL x1, x2, x3: x1 = x2 >> x3
    // Encoding: funct7(0) | rs2(3) | rs1(2) | 101 | rd(1) | 0110011
    // = 0x003150B3
    // Little-endian bytes: [0xB3, 0x50, 0x31, 0x00]
    // Add ECALL after to halt VM (0x00000073)
    const srl_kernel = [_]u8{ 0xB3, 0x50, 0x31, 0x00, 0x73, 0x00, 0x00,
0x00 };
    @memset(&vm.memory, 0);
    @memcpy(vm.memory[0x1000..][0..srl_kernel.len], &srl_kernel);
    vm.regs.pc = 0x1000;
    vm.state = .halted;
    vm.regs.set(2, 0b101000); // x2 = 0b101000 (40 decimal)
    vm.regs.set(3, 2); // x3 = 2 (shift by 2)
    vm.start();
    try vm.step();
    const srl_result = vm.regs.get(1);
    std.debug.assert(srl_result == 0b1010); // x1 = 0b101000 >> 2 =
0b1010 (10 decimal)
    std.debug.print("[kernel_vm_test] ✓ SRL instruction works\n", .{});

    // Test 14: SRA instruction (shift right arithmetic).
    std.debug.print("[kernel_vm_test] Test 14: SRA instruction\n", .{});
    // SRA x1, x2, x3: x1 = x2 >> x3 (sign-extended)
    // Encoding: funct7(0x20) | rs2(3) | rs1(2) | 101 | rd(1) | 0110011
    // = 0x403150B3
    // Little-endian bytes: [0xB3, 0x50, 0x31, 0x40]
    // Add ECALL after to halt VM (0x00000073)
    const sra_kernel = [_]u8{ 0xB3, 0x50, 0x31, 0x40, 0x73, 0x00, 0x00,
0x00 };
    @memset(&vm.memory, 0);
    @memcpy(vm.memory[0x1000..][0..sra_kernel.len], &sra_kernel);
    vm.regs.pc = 0x1000;
    vm.state = .halted;
    vm.regs.set(2, @as(u64, @bitCast(@as(i64, -40)))); // x2 = -40
(signed, 0xFFFFFFD8)
    vm.regs.set(3, 2); // x3 = 2 (shift by 2)
    vm.start();
    try vm.step();
    const sra_result = vm.regs.get(1);
    std.debug.assert(sra_result == @as(u64, @bitCast(@as(i64, -10))));
// x1 = -40 >> 2 = -10 (sign-extended)
    std.debug.print("[kernel_vm_test] ✓ SRA instruction works\n", .{});

    std.debug.print("[kernel_vm_test] All tests passed!\n", .{});
}


// === kernel_vm/test_vm_jit.zig ===

const std = @import("std");
const vm_mod = @import("vm.zig");
const jit_mod = @import("jit.zig");
const builtin = @import("builtin");

test "VM: JIT Integration" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return;
    
    const allocator = std.testing.allocator;
    
    // Simple RISC-V program: ADDI x1, x0, 42; RET
    const program = [_]u8{
        0x93, 0x00, 0xA0, 0x02, // ADDI x1, x0, 42
        0x67, 0x80, 0x00, 0x00, // RET (JALR x0, x1, 0)
    };
    
    // Initialize VM with JIT
    var vm: vm_mod.VM = undefined;
    try vm.init_with_jit(allocator, &program, 0x80000000);
    defer vm.deinit_jit(allocator);
    
    // Verify JIT is enabled
    try std.testing.expect(vm.jit_enabled);
    try std.testing.expect(vm.jit != null);
    
    // Set VM to running state
    vm.state = .running;
    
    // Execute with JIT
    try vm.step_jit();
    
    // Verify result
    try std.testing.expectEqual(@as(u64, 42), vm.regs.get(1));
    
    // Print JIT stats
    if (vm.jit) |jit_ctx| {
        jit_ctx.perf_counters.print_stats();
    }
}

test "VM: JIT Fallback to Interpreter" {
    if (builtin.os.tag != .macos or builtin.cpu.arch != .aarch64) return;
    
    const allocator = std.testing.allocator;
    
    // Program with invalid instruction
    const program = [_]u8{
        0xFF, 0xFF, 0xFF, 0xFF, // Invalid instruction
        0x67, 0x80, 0x00, 0x00, // RET
    };
    
    // Initialize VM with JIT
    var vm: vm_mod.VM = undefined;
    try vm.init_with_jit(allocator, &program, 0x80000000);
    defer vm.deinit_jit(allocator);
    
    vm.state = .running;
    
    // Execute with JIT (should fall back to interpreter)
    try vm.step_jit();
    
    // Verify fallback counter incremented
    if (vm.jit) |jit_ctx| {
        try
std.testing.expect(jit_ctx.perf_counters.interpreter_fallbacks > 0);
    }
}

