                // Opcode 0x2e: Zig compiler compatibility - decode as
I-type instruction.
                // Some Zig-compiled code generates instructions with
opcode 0x2e that should be I-type.
                const funct3 = @as(u3, @truncate(inst >> 12));
                std.debug.print("DEBUG vm.zig: Opcode 0x2e detected:
inst=0x{x}, funct3=0b{b:0>3}\n", .{ inst, funct3 });

                // Try to decode as I-type instruction variants based on
funct3.
                if (funct3 == 0b001) {
                    // SLLI variant (Shift Left Logical Immediate)
                    std.debug.print("DEBUG vm.zig: Executing opcode 0x2e
with funct3=0b001 as SLLI\n", .{});
                    try self.execute_slli(inst);
                } else if (funct3 == 0b000) {
                    // ADDI variant
                    std.debug.print("DEBUG vm.zig: Executing opcode 0x2e
with funct3=0b000 as ADDI\n", .{});
                    try self.execute_addi(inst);
                } else if (funct3 == 0b100) {
                    // XORI variant
                    std.debug.print("DEBUG vm.zig: Executing opcode 0x2e
with funct3=0b100 as XORI\n", .{});
                    try self.execute_xori(inst);
