                    // ORI variant
                    std.debug.print("DEBUG vm.zig: Executing opcode 0x2e
with funct3=0b110 as ORI\n", .{});
                    try self.execute_ori(inst);
                } else if (funct3 == 0b111) {
                    // ANDI variant
                    std.debug.print("DEBUG vm.zig: Executing opcode 0x2e
with funct3=0b111 as ANDI\n", .{});
                    try self.execute_andi(inst);
                } else {
                    // Unknown opcode 0x2e variant - treat as NOP for
now.
                    std.debug.print("DEBUG vm.zig: Unknown opcode 0x2e
variant (funct3=0b{b:0>3}), treating as NOP\n", .{funct3});
                    // NOP: Do nothing, PC will advance normally.
                }
            },
            else => {
                // Check if this is a Zig-specific non-standard opcode
that should be decoded as I-type.
                // Pattern: Many Zig-compiled instructions use
non-standard opcodes with various funct3 values.
                const funct3 = @as(u3, @truncate(inst >> 12));
                if (funct3 == 0b000) {
                    // ADDI variant
                    std.debug.print("DEBUG vm.zig: Non-standard opcode
0b{b:0>7} (0x{x}) with funct3=0b000, treating as ADDI\n", .{ opcode,
opcode });
                    try self.execute_addi(inst);
                } else if (funct3 == 0b001) {
                    // SLLI variant (Shift Left Logical Immediate)
                    std.debug.print("DEBUG vm.zig: Non-standard opcode
0b{b:0>7} (0x{x}) with funct3=0b001, treating as SLLI\n", .{ opcode,
opcode });
                    try self.execute_slli(inst);
                } else if (funct3 == 0b011) {
                    // SLTIU variant (Set Less Than Immediate Unsigned)
- treat as NOP for now
                    std.debug.print("DEBUG vm.zig: Non-standard opcode
0b{b:0>7} (0x{x}) with funct3=0b011, treating as NOP\n", .{ opcode,
opcode });
                    // NOP: Do nothing, PC will advance normally.
                } else if (funct3 == 0b100) {
                    // XORI variant
                    std.debug.print("DEBUG vm.zig: Non-standard opcode
0b{b:0>7} (0x{x}) with funct3=0b100, treating as XORI\n", .{ opcode,
opcode });
                    try self.execute_xori(inst);
                } else if (funct3 == 0b110) {
                    // ORI variant
                    std.debug.print("DEBUG vm.zig: Non-standard opcode
0b{b:0>7} (0x{x}) with funct3=0b110, treating as ORI\n", .{ opcode,
opcode });
                    try self.execute_ori(inst);
                } else if (funct3 == 0b111) {
                    // ANDI variant
                    std.debug.print("DEBUG vm.zig: Non-standard opcode
0b{b:0>7} (0x{x}) with funct3=0b111, treating as ANDI\n", .{ opcode,
opcode });
                    try self.execute_andi(inst);
                } else {
                    // Unsupported opcode - treat as NOP for now to
allow execution to continue
                    std.debug.print("DEBUG vm.zig: Unknown non-standard
opcode 0b{b:0>7} (0x{x}) with funct3=0b{b:0>3}, treating as NOP\n", .{
opcode, opcode, funct3 });
                    // NOP: Do nothing, PC will advance normally.
                }
            },
        }

        // Advance PC to next instruction (4 bytes).
        // Note: BEQ may have already updated PC for branch, so check if
PC was modified.
        // Branch instructions modify PC directly, so we don't increment
again.
        if (self.regs.pc == pc_before) {
            // Normal case: PC unchanged by instruction, advance by 4
bytes.
            self.regs.pc += 4;
        }
        // Else: PC was modified by branch instruction (BEQ), don't
increment again.

        // Assert: PC must be 4-byte aligned after instruction execution.
        std.debug.assert(self.regs.pc % 4 == 0);

        // Assert: PC must be within memory bounds after execution.
        // Note: PC can be equal to memory_size (one past end) if
instruction was at end.
        std.debug.assert(self.regs.pc <= self.memory_size);
    }

    /// Execute LUI (Load Upper Immediate) instruction.
    /// Format: LUI rd, imm[31:12]
    /// Why: Separate function for clarity and Grain Style function
length.
    fn execute_lui(self: *Self, inst: u32) !void {
        // Decode: rd = bits [11:7], imm[31:12] = bits [31:12].
        const rd = @as(u5, @truncate(inst >> 7));
        const imm = @as(u32, inst) & 0xFFFFF000; // Extract bits [31:12].

        // Sign-extend imm[31:12] to 64 bits.
        const imm64 = @as(i32, @bitCast(imm)) << 12;
        const imm64_unsigned = @as(u64, @intCast(imm64));

        // Write result to rd.
        self.regs.set(rd, imm64_unsigned);
    }

    /// Execute AUIPC (Add Upper Immediate to PC) instruction.
    /// Format: AUIPC rd, imm[31:12]
    /// Why: PC-relative addressing for position-independent code.
    /// Grain Style: Comprehensive assertions for register indices and
result validation.
    fn execute_auipc(self: *Self, inst: u32) !void {
        // Decode: rd = bits [11:7], imm[31:12] = bits [31:12].
        const rd = @as(u5, @truncate(inst >> 7));
        // Extract imm[31:12] as a 20-bit value, then sign-extend to 32
bits, then shift left by 12.
        const imm_31_12_raw = @as(u20, @truncate(inst >> 12));
        const imm_31_12 = @as(i32, @bitCast(@as(u32, imm_31_12_raw) <<
12));
        const imm64_unsigned: u64 = @bitCast(@as(i64, imm_31_12));

        // Get current PC (before instruction execution).
        const pc = self.regs.pc;

        // AUIPC: rd = PC + imm[31:12] << 12
        const result = pc +% imm64_unsigned;

        // Debug: Print AUIPC execution for troubleshooting.
        if (rd == 1 or rd == 18) {
            std.debug.print("DEBUG vm.zig: AUIPC x{}: PC=0x{x},
imm_31_12_raw=0x{x}, imm64_unsigned=0x{x}, result=0x{x}\n", .{ rd, pc,
imm_31_12_raw, imm64_unsigned, result });
        }

        // Write result to rd.
        self.regs.set(rd, result);
    }

    /// Execute ADDI (Add Immediate) instruction.
    /// Format: ADDI rd, rs1, imm[11:0]
    /// Why: Separate function for clarity and Grain Style function
length.
    fn execute_addi(self: *Self, inst: u32) !void {
        // Decode: rd = bits [11:7], rs1 = bits [19:15], imm[11:0] =
bits [31:20].
        const rd = @as(u5, @truncate(inst >> 7));
        const rs1 = @as(u5, @truncate(inst >> 15));
        const imm12 = @as(i32, @truncate(@as(i64, inst >> 20)));

        // Sign-extend imm[11:0] to 64 bits.
        const imm64 = @as(i64, imm12);

        // Read rs1 value.
        const rs1_value = self.regs.get(rs1);

        // Add: rd = rs1 + imm (wrapping addition).
        const result = @as(u64, @intCast(@as(i64, @bitCast(rs1_value)) +
imm64));

        // Write result to rd.
        self.regs.set(rd, result);
    }

