                    'H', 'h' => [7]u8{ 0b10001, 0b10001, 0b10001,
0b11111, 0b10001, 0b10001, 0b10001 },
                    'I', 'i' => [7]u8{ 0b01110, 0b00100, 0b00100,
0b00100, 0b00100, 0b00100, 0b01110 },
                    'J', 'j' => [7]u8{ 0b00111, 0b00010, 0b00010,
