    /// Render character to pixel buffer.
    // Returns pixel data as RGBA array (width * height * 4 bytes).
    // Caller is responsible for rendering pixels to their buffer.
    // 2025-12-03-140357-pst: Active function
    pub fn render_char_to_pixels(
        self: *const FontRenderer,
        ch: u8,
        fg_r: u8,
        fg_g: u8,
        fg_b: u8,
        fg_a: u8,
        bg_r: u8,
        bg_g: u8,
        bg_b: u8,
        bg_a: u8,
        pixel_buffer: []u8,
    ) bool {
        std.debug.assert(pixel_buffer.len >= self.get_char_width() *
self.get_char_height() * 4);
        const pattern = self.get_char_pattern(ch) orelse return false;
        const font_w = self.get_font_width();
        const font_h = self.get_font_height();
        var row: u32 = 0;
        while (row < font_h) : (row += 1) {
            var col: u32 = 0;
            while (col < font_w) : (col += 1) {
                const bit_mask = switch (self.font_size) {
                    .font_5x7 => @as(u5, 1) << @as(u3, @intCast(4 -
col)),
                    .font_8x8 => @as(u8, 1) << @as(u3, @intCast(7 -
col)),
                };
                const pattern_row = pattern[@as(usize, @intCast(row))];
                const bit_set = (pattern_row & bit_mask) != 0;
                const pixel_idx = (row * self.get_char_width() + col) *
4;
                if (bit_set) {
                    pixel_buffer[pixel_idx + 0] = fg_r;
                    pixel_buffer[pixel_idx + 1] = fg_g;
                    pixel_buffer[pixel_idx + 2] = fg_b;
                    pixel_buffer[pixel_idx + 3] = fg_a;
                } else {
                    pixel_buffer[pixel_idx + 0] = bg_r;
                    pixel_buffer[pixel_idx + 1] = bg_g;
                    pixel_buffer[pixel_idx + 2] = bg_b;
                    pixel_buffer[pixel_idx + 3] = bg_a;
                }
            }
        }
        return true;
    }
};


// === simple_rng.zig ===

/// SimpleRng: tiny linear congruential generator for fuzz/style tests.
///
/// GrainStyle prefers explicit determinism and no hidden allocations.
/// This helper centralizes the wrap-safe arithmetic shared between
/// timestamp fuzzing and npub generation.
pub const SimpleRng = struct {
    state: u64,

    pub fn init(seed: u64) SimpleRng {
        return .{ .state = seed };
    }

    fn next(self: *SimpleRng) u64 {
        self.state = self.state *% 6364136223846793005 +% 1;
        return self.state;
    }

    pub fn boolean(self: *SimpleRng) bool {
        return (self.next() & 1) == 1;
    }

    pub fn range(self: *SimpleRng, comptime T: type, upper: T) T {
        return self.uint_less_than(T, upper);
    }

    pub fn uint_less_than(self: *SimpleRng, comptime T: type, bound: T)
T {
        return @intCast(self.next() % @as(u64, bound));
    }
};

