// === userspace/fb_demo.zig ===

//! Framebuffer Demo Program
//!
//! Objective: Demonstrate framebuffer syscalls (fb_clear,
fb_draw_pixel, fb_draw_text)
//! from userspace. This program runs in Grain Vantage VM and renders to
the framebuffer.
//!
//! Methodology:
//! - Clear framebuffer to dark background
//! - Draw colored pixels in a pattern
//! - Draw text messages
//! - Exit cleanly
//!
//! GrainStyle: Explicit types, assertions, bounded execution, static
allocation where possible.
//! Why: Test the full stack: VM -> Kernel -> Syscalls -> Framebuffer ->
Display

const std = @import("std");
const basin_kernel = @import("basin_kernel");
const Syscall = basin_kernel.Syscall;

// Framebuffer syscall numbers (must match kernel/basin_kernel.zig).
const FB_CLEAR: u32 = 70;
const FB_DRAW_PIXEL: u32 = 71;
const FB_DRAW_TEXT: u32 = 72;

// Color constants (32-bit RGBA format: R in MSB, A in LSB).
const COLOR_DARK_BG: u32 = 0x1E1E2EFF; // Dark background
const COLOR_WHITE: u32 = 0xFFFFFFFF;   // White
const COLOR_RED: u32 = 0xFF0000FF;     // Red
const COLOR_GREEN: u32 = 0x00FF00FF;   // Green
const COLOR_BLUE: u32 = 0x0000FFFF;    // Blue

// Framebuffer dimensions (must match kernel/framebuffer.zig).
const FB_WIDTH: u32 = 1024;
const FB_HEIGHT: u32 = 768;

/// Perform syscall via inline assembly.
/// Why: Direct syscall invocation from userspace program.
/// Contract: syscall_num must be valid kernel syscall.
/// Returns: u64 result (negative = error, non-negative = success).
fn syscall(
    syscall_num: u32,
    arg1: u64,
    arg2: u64,
    arg3: u64,
    arg4: u64,
) u64 {
    // Assert: syscall_num must be valid (>= 1).
    std.debug.assert(syscall_num >= 1);
    
    // RISC-V syscall convention: a7 = syscall number, a0-a3 =
arguments, a0 = return value.
    var result: u64 = undefined;
    asm volatile (
        \\ ecall
        : [result] "={x10}" (result)
        : [syscall_num] "{x17}" (syscall_num),
          [arg1] "{x10}" (arg1),
          [arg2] "{x11}" (arg2),
          [arg3] "{x12}" (arg3),
          [arg4] "{x13}" (arg4)
        : "memory"
    );
    
    // Assert: Result must be valid u64 (always true, but documents
expectation).
    _ = result;
    
    return result;
}

/// Clear framebuffer to specified color.
/// Why: Test fb_clear syscall.
/// Contract: color must be valid 32-bit RGBA value.
fn fb_clear(color: u32) void {
    const result = syscall(FB_CLEAR, color, 0, 0, 0);
    
    // Assert: Syscall must succeed (result == 0).
    std.debug.assert(result == 0);
}

/// Draw a single pixel at specified coordinates.
/// Why: Test fb_draw_pixel syscall.
/// Contract: x and y must be within framebuffer bounds.
fn fb_draw_pixel(x: u32, y: u32, color: u32) void {
    // Assert: Coordinates must be within bounds.
    std.debug.assert(x < FB_WIDTH);
    std.debug.assert(y < FB_HEIGHT);
    
    const result = syscall(FB_DRAW_PIXEL, x, y, color, 0);
    
    // Assert: Syscall must succeed (result == 0).
    std.debug.assert(result == 0);
}

/// Draw text string at specified coordinates.
/// Why: Test fb_draw_text syscall.
/// Contract: text_ptr must point to null-terminated string in kernel
memory, x and y within bounds.
fn fb_draw_text(text_ptr: [*]const u8, x: u32, y: u32, fg_color: u32)
void {
    // Assert: Text pointer must be valid (non-null).
    std.debug.assert(@intFromPtr(text_ptr) != 0);
    
    // Assert: Coordinates must be within bounds.
    std.debug.assert(x < FB_WIDTH);
    std.debug.assert(y < FB_HEIGHT);
    
    const result = syscall(FB_DRAW_TEXT, @intFromPtr(text_ptr), x, y,
fg_color);
    
    // Assert: Syscall must succeed (result >= 0, character count).
    std.debug.assert(result >= 0);
}

/// Main entry point.
/// Why: Program entry point, orchestrates framebuffer demo.
/// Contract: Program runs in VM, has access to kernel syscalls.
pub fn main() void {
    // Clear framebuffer to dark background.
    fb_clear(COLOR_DARK_BG);
    
    // Draw colored pixels in a pattern (10x10 grid).
    const grid_size: u32 = 10;
    const spacing: u32 = 50;
    var y: u32 = 0;
    while (y < grid_size) : (y += 1) {
        var x: u32 = 0;
        while (x < grid_size) : (x += 1) {
            const px: u32 = 100 + x * spacing;
            const py: u32 = 100 + y * spacing;
            
            // Alternate colors based on position.
            const color: u32 = if ((x + y) % 3 == 0) COLOR_RED else if
((x + y) % 3 == 1) COLOR_GREEN else COLOR_BLUE;
            
            fb_draw_pixel(px, py, color);
        }
    }
    
    // Draw text messages (must be in kernel memory, so we use static
strings).
    // Note: In real implementation, text would be copied to kernel
memory first.
    // For demo, we assume static strings are accessible.
    const text1 = "Grain OS Framebuffer Demo";
    const text2 = "Userspace Program Running";
    const text3 = "fb_clear, fb_draw_pixel, fb_draw_text";
    
    // Draw text at different y positions.
    // Note: In real implementation, we'd need to copy strings to kernel
memory.
    // For now, we'll use the address of static strings (they're in
program memory).
    fb_draw_text(text1.ptr, 50, 50, COLOR_WHITE);
    fb_draw_text(text2.ptr, 50, 70, COLOR_WHITE);
    fb_draw_text(text3.ptr, 50, 90, COLOR_WHITE);
    
    // Exit program (syscall exit = 2).
    syscall(@intFromEnum(Syscall.exit), 0, 0, 0, 0);
    
    // Assert: Should never reach here (exit syscall should terminate).
    unreachable;
}


// === userspace/grainscape/browser.zig ===

const std = @import("std");
const stdlib = @import("userspace_stdlib");

// Grainscape Browser - Core Module
// A minimal text-based browser for Grain OS

pub const BrowserConfig = struct {
    viewport_width: usize = 80,
    viewport_height: usize = 24,
    max_history: usize = 100,
    user_agent: []const u8 = "Grainscape/0.1.0 (Grain OS; RISC-V64)",
};

pub const Url = struct {
    scheme: []const u8, // "http", "https", "grain"
    host: []const u8,
    port: ?u16 = null,
    path: []const u8 = "/",
    
    pub fn parse(allocator: std.mem.Allocator, url_str: []const u8) !Url
{
        // Simple URL parser
        // Format: scheme://host:port/path
        
        const scheme_end = std.mem.indexOf(u8, url_str, "://") orelse
return error.InvalidUrl;
        const scheme = url_str[0..scheme_end];
        
        var remainder = url_str[scheme_end + 3..];
        
        // Find path start
        const path_start = std.mem.indexOf(u8, remainder, "/") orelse
remainder.len;
        const host_port = remainder[0..path_start];
        const path = if (path_start < remainder.len)
remainder[path_start..] else "/";
        
        // Parse host:port
        var host: []const u8 = undefined;
        var port: ?u16 = null;
        
        if (std.mem.indexOf(u8, host_port, ":")) |colon_pos| {
            host = host_port[0..colon_pos];
            const port_str = host_port[colon_pos + 1..];
            port = try std.fmt.parseInt(u16, port_str, 10);
        } else {
            host = host_port;
        }
        
        return Url{
            .scheme = try allocator.dupe(u8, scheme),
            .host = try allocator.dupe(u8, host),
            .port = port,
            .path = try allocator.dupe(u8, path),
        };
    }
    
    pub fn deinit(self: *Url, allocator: std.mem.Allocator) void {
        allocator.free(self.scheme);
        allocator.free(self.host);
        allocator.free(self.path);
    }
};

pub const Page = struct {
    url: Url,
    title: []const u8,
    content: []const u8,
    rendered_lines: [][]const u8,
    
    pub fn deinit(self: *Page, allocator: std.mem.Allocator) void {
        self.url.deinit(allocator);
        allocator.free(self.title);
        allocator.free(self.content);
        for (self.rendered_lines) |line| {
            allocator.free(line);
        }
        allocator.free(self.rendered_lines);
    }
};

pub const Browser = struct {
    allocator: std.mem.Allocator,
    config: BrowserConfig,
    current_page: ?Page = null,
    history: std.ArrayList([]const u8),
    history_index: usize = 0,
    
    pub fn init(allocator: std.mem.Allocator, config: BrowserConfig)
!Browser {
        return Browser{
            .allocator = allocator,
            .config = config,
            .history = .{
                .items = &.{},
                .capacity = 0,
            },
        };
    }
    
    pub fn deinit(self: *Browser) void {
        if (self.current_page) |*page| {
            page.deinit(self.allocator);
        }
        for (self.history.items) |url| {
            self.allocator.free(url);
        }
        self.history.deinit(self.allocator);
    }
    
    pub fn navigate(self: *Browser, url_str: []const u8) !void {
        // Parse URL
        var url = try Url.parse(self.allocator, url_str);
        errdefer url.deinit(self.allocator);
        
        // Fetch content (stub for now)
        const content = try self.fetch_content(&url);
        errdefer self.allocator.free(content);
        
        // Render content
        const rendered = try self.render_content(content);
        errdefer {
            for (rendered) |line| self.allocator.free(line);
            self.allocator.free(rendered);
        }
        
        // Extract title (first line or URL)
        const title = try self.allocator.dupe(u8, url.host);
        
        // Clean up old page
        if (self.current_page) |*old_page| {
            old_page.deinit(self.allocator);
        }
        
        // Set new page
        self.current_page = Page{
            .url = url,
            .title = title,
            .content = content,
            .rendered_lines = rendered,
        };
        
        // Add to history
        const history_url = try self.allocator.dupe(u8, url_str);
        try self.history.append(self.allocator, history_url);
        self.history_index = self.history.items.len - 1;
    }
    
    fn fetch_content(self: *Browser, url: *const Url) ![]const u8 {
        // Stub: In real implementation, this would make HTTP requests
        // For now, return a placeholder
        
        if (std.mem.eql(u8, url.scheme, "grain")) {
            // Internal Grain OS pages
            return try self.allocator.dupe(u8, 
                \\Welcome to Grainscape
                \\
                \\This is the Grain OS native browser.
                \\
                \\Features:
                \\- Text-based rendering
                \\- Minimal resource usage
                \\- Native RISC-V performance
                \\
                \\Navigate to grain://help for more information.
            );
        }
        
        return try self.allocator.dupe(u8, "Page content placeholder");
    }
    
    fn render_content(self: *Browser, content: []const u8) ![][]const u8
{
        // Simple line-based rendering
        var lines: std.ArrayList([]const u8) = .{
            .items = &.{},
            .capacity = 0,
        };
        errdefer {
            for (lines.items) |line| self.allocator.free(line);
            lines.deinit(self.allocator);
        }
        
        var it = std.mem.splitScalar(u8, content, '\n');
        while (it.next()) |line| {
            // Wrap long lines
            if (line.len > self.config.viewport_width) {
                var start: usize = 0;
                while (start < line.len) {
                    const end = @min(start + self.config.viewport_width,
line.len);
                    const wrapped = try self.allocator.dupe(u8,
line[start..end]);
                    try lines.append(self.allocator, wrapped);
                    start = end;
                }
            } else {
                const dup_line = try self.allocator.dupe(u8, line);
                try lines.append(self.allocator, dup_line);
            }
        }
        
        return lines.toOwnedSlice(self.allocator);
    }
    
    pub fn render_viewport(self: *Browser, writer: anytype) !void {
        if (self.current_page) |*page| {
            // Render title bar
            try writer.print("+-- {s} ", .{page.title});
            const title_len = page.title.len + 5;
            var i: usize = title_len;
            while (i < self.config.viewport_width) : (i += 1) {
                try writer.writeByte('-');
            }
            try writer.writeByte('+');
            try writer.writeByte('\n');
            
            // Render content lines
            const max_lines = self.config.viewport_height - 3; // Title
+ status + border
            for (page.rendered_lines, 0..) |line, idx| {
                if (idx >= max_lines) break;
                try writer.print("| {s}", .{line});
                
                // Pad to viewport width
                const padding = self.config.viewport_width - line.len -
2;
                var j: usize = 0;
                while (j < padding) : (j += 1) {
                    try writer.writeByte(' ');
                }
                try writer.writeByte('|');
                try writer.writeByte('\n');
            }
            
            // Fill remaining lines
            const rendered_count = @min(page.rendered_lines.len,
max_lines);
            var remaining = max_lines - rendered_count;
            while (remaining > 0) : (remaining -= 1) {
                try writer.writeByte('|');
                i = 0;
                while (i < self.config.viewport_width - 2) : (i += 1) {
                    try writer.writeByte(' ');
                }
                try writer.writeByte('|');
                try writer.writeByte('\n');
            }
            
            // Bottom border
            try writer.writeByte('+');
            i = 0;
            while (i < self.config.viewport_width - 2) : (i += 1) {
                try writer.writeByte('-');
            }
            try writer.writeByte('+');
            try writer.writeByte('\n');
        } else {
            try writer.writeAll("No page loaded. Navigate to a URL to
begin.\n");
        }
    }
};

// === userspace/grainscape/main.zig ===

const std = @import("std");
const browser_mod = @import("browser.zig");

// Grainscape - Main Entry Point
// The native browser for Grain OS

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    
    // Print banner
    std.debug.print(
        \\
        \\ 
+========================================================================
+
        \\  |                          GRAINSCAPE v0.1.0                
|
        \\  |                    The Grain OS Native Browser            
|
        \\ 
+========================================================================
+
        \\
        \\
    , .{});
    
    // Initialize browser
    const config = browser_mod.BrowserConfig{
        .viewport_width = 75,
        .viewport_height = 20,
    };
    
    var browser = try browser_mod.Browser.init(allocator, config);
    defer browser.deinit();
    
    // Navigate to welcome page
    std.debug.print("Navigating to grain://welcome...\n\n", .{});
    try browser.navigate("grain://welcome");
    
    // Render viewport (to a buffer then print)
    var buf: std.ArrayList(u8) = .{
        .items = &.{},
        .capacity = 0,
    };
    defer buf.deinit(allocator);
    
    try browser.render_viewport(buf.writer(allocator));
    std.debug.print("{s}\n", .{buf.items});
    
    std.debug.print("\n", .{});
    std.debug.print("Commands:\n", .{});
    std.debug.print("  (In future: interactive mode with navigation)\n",
.{});
    std.debug.print("  For now: demonstrating text rendering\n", .{});
}

// === userspace/grainscape/tls_demo.zig ===

const std = @import("std");
const tls = @import("tls");

// Grainscape TLS Demo
// Tests basic HTTPS connectivity using grain-tls (forked from
ianic/tls.zig)

pub fn main() !void {
    var gpa = std.heap.GeneralPurposeAllocator(.{}){};
    defer _ = gpa.deinit();
    const allocator = gpa.allocator();
    
    std.debug.print("\n=== Grainscape TLS Demo ===\n\n", .{});
    
    // Test connection to example.com
    const host = "example.com";
    const port: u16 = 443;
    
    std.debug.print("Connecting to {s}:{d}...\n", .{ host, port });

    // Create TCP connection
    var stream = try std.net.tcpConnectToHost(allocator, host, port);
    defer stream.close();

    std.debug.print("TCP connection established\n", .{});

    // Wrap with TLS using Grain TLS
    std.debug.print("Initiating TLS handshake...\n", .{});

    var tls_client = try tls.TlsClient.init(allocator, stream, host);
    defer tls_client.deinit();

    std.debug.print("TLS handshake complete!\n", .{});
    std.debug.print("Protocol: TLS 1.3\n", .{});

    // Send HTTP GET request
    const request = "GET / HTTP/1.1\r\nHost: example.com\r\nConnection:
close\r\n\r\n";
    std.debug.print("\nSending HTTP request...\n", .{});

    try tls_client.writeAll(request);

    // Read response
    std.debug.print("Reading response...\n\n", .{});

    var total_bytes: usize = 0;
    var first_chunk = true;
    while (try tls_client.next()) |data| {
        total_bytes += data.len;
        if (first_chunk) {
            // Print first 500 bytes
            std.debug.print("{s}", .{data[0..@min(500, data.len)]});
            if (data.len > 500) {
                std.debug.print("... (truncated)\n", .{});
            }
            first_chunk = false;
        }
    }

    std.debug.print("\n--- Response ({d} bytes total) ---\n",
.{total_bytes});
    std.debug.print("\n✓ TLS demo successful!\n", .{});
}

// === userspace/stdlib.zig ===

//! Minimal Standard Library for Grain Basin Userspace
//! Why: Provide syscall wrappers and basic functionality for Zig
programs running in VM.
//! Grain Style: Comprehensive contracts, explicit types, input/output
validation.

const std = @import("std");

/// Syscall numbers (must match kernel/basin_kernel.zig).
/// Why: Explicit syscall enumeration for type safety.
pub const Syscall = enum(u32) {
    // Process & Thread Management
    spawn = 1,
    exit = 2,
    yield = 3,
    wait = 4,

    // Memory Management
    map = 10,
    unmap = 11,
    protect = 12,

    // Inter-Process Communication
    channel_create = 20,
    channel_send = 21,
    channel_recv = 22,

    // I/O Operations
    open = 30,
    read = 31,
    write = 32,
    close = 33,
    unlink = 34,
    rename = 35,
    mkdir = 36,
    opendir = 37,
    readdir = 38,
    closedir = 39,

    // Time & Scheduling
    clock_gettime = 40,
    sleep_until = 41,

    // System Information
    sysinfo = 50,
};

/// Make a syscall (RISC-V convention: syscall number in a7, args in
a0-a3, result in a0).
/// Contract:
///   Input: syscall_num must be valid Syscall enum value, args are
syscall-specific
///   Output: Returns u64 result (negative for errors, non-negative for
success)
///   Errors: Invalid syscall number, invalid arguments
/// Why: Low-level syscall interface for userspace programs.
/// Note: This uses inline assembly to emit ECALL instruction.
pub fn syscall(
    syscall_num: Syscall,
    arg1: u64,
    arg2: u64,
    arg3: u64,
    arg4: u64,
) u64 {
    // Contract: syscall_num must be valid enum value.
    const syscall_val = @intFromEnum(syscall_num);

    // RISC-V syscall convention: ECALL with syscall number in a7 (x17),
args in a0-a3 (x10-x13)
    // Inline assembly: load syscall number into a7, args into a0-a3,
execute ECALL, result in a0
    return asm volatile ("ecall"
        : [ret] "={x10}" (-> u64),
        : [syscall] "{x17}" (syscall_val),
          [arg1] "{x10}" (arg1),
          [arg2] "{x11}" (arg2),
          [arg3] "{x12}" (arg3),
          [arg4] "{x13}" (arg4),
        : .{ .memory = true }
    );
}

/// Exit the current process.
/// Contract:
///   Input: exit_code is the process exit status
///   Output: Never returns (process terminates)
/// Why: Clean process termination.
pub fn exit(exit_code: u32) noreturn {
    _ = syscall(.exit, exit_code, 0, 0, 0);
    // Should never return, but if it does, loop forever
    while (true) {}
}

/// Write data to a file handle.
/// Contract:
///   Input: handle must be valid file handle, data must be valid slice
///   Output: Returns number of bytes written, or negative error code
///   Errors: Invalid handle, permission denied, out of memory
/// Why: File I/O for userspace programs.
pub fn write(handle: u32, data: []const u8) i64 {
    // Contract: data.len must be reasonable (prevent overflow).
    if (data.len > 0x7FFFFFFF) {
        return -2; // invalid_argument (length too large)
    }

    // Contract: len must be <= data.len (implicitly true for slice).
    const result = syscall(.write, handle, @intFromPtr(data.ptr),
data.len, 0);

    // Convert u64 result to i64 (negative = error, non-negative =
success)
    return @as(i64, @bitCast(result));
}

/// Read data from a file handle.
/// Contract:
///   Input: handle must be valid file handle, buffer must be valid slice
///   Output: Returns number of bytes read, or negative error code
///   Errors: Invalid handle, permission denied, end of file
/// Why: File I/O for userspace programs.
pub fn read(handle: u32, buffer: []u8) i64 {
    // Contract: buffer.len must be reasonable (prevent overflow).
    if (buffer.len > 0x7FFFFFFF) {
        return -2; // invalid_argument (length too large)
    }

    // Contract: len must be <= buffer.len (implicitly true for slice).
    const result = syscall(.read, handle, @intFromPtr(buffer.ptr),
buffer.len, 0);

    // Convert u64 result to i64 (negative = error, non-negative =
success)
    return @as(i64, @bitCast(result));
}

/// Open a file.
/// Contract:
///   Input: path must be null-terminated string, flags must be valid
///   Output: Returns file handle (non-negative), or negative error code
///   Errors: File not found, permission denied, out of memory
/// Why: File system access for userspace programs.
pub fn open(path: [*:0]const u8, flags: u32) i64 {
    // Calculate path length (null-terminated string).
    var len: u64 = 0;
    while (path[len] != 0) : (len += 1) {
        // Bounds check (prevent infinite loop).
        if (len >= 4096) {
            return -2; // invalid_argument (path too long)
        }
    }

    const result = syscall(.open, @intFromPtr(path), len, flags, 0);

    // Convert u64 result to i64 (negative = error, non-negative =
success)
    return @as(i64, @bitCast(result));
}

/// Close a file handle.
/// Contract:
///   Input: handle must be valid file handle
///   Output: Returns 0 on success, or negative error code
///   Errors: Invalid handle
/// Why: Resource cleanup for userspace programs.
pub fn close(handle: u32) i64 {
    const result = syscall(.close, handle, 0, 0, 0);

    // Convert u64 result to i64 (negative = error, non-negative =
success)
    return @as(i64, @bitCast(result));
}

/// Unlink (delete) a file.
/// Contract:
///   Input: path must be null-terminated string
///   Output: Returns 0 on success, or negative error code
///   Errors: File not found, permission denied
/// Why: File deletion for userspace programs.
pub fn unlink(path: [*:0]const u8) i64 {
    // Calculate path length (null-terminated string).
    var len: u64 = 0;
    while (path[len] != 0) : (len += 1) {
        // Bounds check (prevent infinite loop).
        if (len >= 4096) {
            return -2; // invalid_argument (path too long)
        }
    }

    const result = syscall(.unlink, @intFromPtr(path), len, 0, 0);

    // Convert u64 result to i64 (negative = error, non-negative =
success)
    return @as(i64, @bitCast(result));
}

/// Rename a file or directory.
/// Contract:
///   Input: old_path and new_path must be null-terminated strings
///   Output: Returns 0 on success, or negative error code
///   Errors: File not found, permission denied
/// Why: File renaming/moving for userspace programs.
pub fn rename(old_path: [*:0]const u8, new_path: [*:0]const u8) i64 {
    // Calculate old path length (null-terminated string).
    var old_len: u64 = 0;
    while (old_path[old_len] != 0) : (old_len += 1) {
        // Bounds check (prevent infinite loop).
        if (old_len >= 4096) {
            return -2; // invalid_argument (path too long)
        }
    }

    // Calculate new path length (null-terminated string).
    var new_len: u64 = 0;
    while (new_path[new_len] != 0) : (new_len += 1) {
        // Bounds check (prevent infinite loop).
        if (new_len >= 4096) {
            return -2; // invalid_argument (path too long)
        }
    }

    const result = syscall(.rename, @intFromPtr(old_path), old_len,
@intFromPtr(new_path), new_len);

    // Convert u64 result to i64 (negative = error, non-negative =
success)
    return @as(i64, @bitCast(result));
}

/// Create a directory.
/// Contract:
///   Input: path must be null-terminated string
///   Output: Returns 0 on success, or negative error code
///   Errors: Directory already exists, permission denied
/// Why: Directory creation for userspace programs.
pub fn mkdir(path: [*:0]const u8) i64 {
    // Calculate path length (null-terminated string).
    var len: u64 = 0;
    while (path[len] != 0) : (len += 1) {
        // Bounds check (prevent infinite loop).
        if (len >= 4096) {
            return -2; // invalid_argument (path too long)
        }
    }

    const result = syscall(.mkdir, @intFromPtr(path), len, 0, 0);

    // Convert u64 result to i64 (negative = error, non-negative =
success)
    return @as(i64, @bitCast(result));
}

/// Open a directory.
/// Contract:
///   Input: path must be null-terminated string
///   Output: Returns directory handle (non-negative), or negative error
code
///   Errors: Directory not found, permission denied
/// Why: Directory access for userspace programs.
pub fn opendir(path: [*:0]const u8) i64 {
    // Calculate path length (null-terminated string).
    var len: u64 = 0;
    while (path[len] != 0) : (len += 1) {
        // Bounds check (prevent infinite loop).
        if (len >= 256) {
            return -2; // invalid_argument (path too long)
        }
    }

    const result = syscall(.opendir, @intFromPtr(path), len, 0, 0);

    // Convert u64 result to i64 (negative = error, non-negative =
success)
    return @as(i64, @bitCast(result));
}

/// Read a directory entry.
/// Contract:
///   Input: dir_handle must be valid directory handle, entry_buffer
must be valid slice
///   Output: Returns number of bytes written to buffer, or 0 if end of
directory, or negative error code
///   Errors: Invalid handle, permission denied
/// Why: Directory listing for userspace programs.
pub fn readdir(dir_handle: u32, entry_buffer: []u8) i64 {
    // Contract: entry_buffer.len must be reasonable (prevent overflow).
    if (entry_buffer.len > 0x7FFFFFFF) {
        return -2; // invalid_argument (length too large)
    }

    const result = syscall(.readdir, dir_handle,
@intFromPtr(entry_buffer.ptr), entry_buffer.len, 0);

    // Convert u64 result to i64 (negative = error, 0 = end of
directory, positive = bytes written)
    return @as(i64, @bitCast(result));
}

/// Close a directory handle.
/// Contract:
///   Input: dir_handle must be valid directory handle
///   Output: Returns 0 on success, or negative error code
///   Errors: Invalid handle
/// Why: Resource cleanup for userspace programs.
pub fn closedir(dir_handle: u32) i64 {
    const result = syscall(.closedir, dir_handle, 0, 0, 0);

    // Convert u64 result to i64 (negative = error, non-negative =
success)
    return @as(i64, @bitCast(result));
}

/// Write a string to stdout (handle 1).
/// Contract:
///   Input: str must be non-null, null-terminated string
///   Output: Returns number of bytes written, or negative error code
/// Why: Convenience function for printing to stdout.
pub fn print(str: [*:0]const u8) i64 {
    // Calculate string length (null-terminated).
    var len: u64 = 0;
    while (str[len] != 0) : (len += 1) {
        // Bounds check (prevent infinite loop).
        if (len >= 4096) {
            return -2; // invalid_argument (string too long)
        }
    }

    // Write to stdout (handle 1).
    const stdout_handle: u32 = 1;
    return write(stdout_handle, str[0..len]);
}

/// Minimal stdio module (stub for now).
pub const io = struct {
    /// Standard output handle (stdout).
    pub const stdout_handle: u32 = 1;

    /// Standard error handle (stderr).
    pub const stderr_handle: u32 = 2;

    /// Standard input handle (stdin).
    pub const stdin_handle: u32 = 0;
};

// === userspace/utils/args.zig ===

//! Argument Parsing Helper for Userspace Utilities
//! Why: Common argument parsing functionality for shell utilities
//! Grain Style: Static allocation, explicit types, comprehensive
assertions

/// Maximum number of arguments (Grain Style: explicit size)
const MAX_ARGS: u32 = 64;

/// Maximum argument length (Grain Style: explicit size)
const MAX_ARG_LEN: u32 = 256;

/// Parsed arguments structure
/// Why: Store parsed command-line arguments for utilities
pub const Args = struct {
    /// Argument count (excluding program name)
    argc: u32,
    
    /// Argument values (pointers to strings on stack)
    argv: [MAX_ARGS][*:0]const u8,
    
    /// Initialize Args from RISC-V calling convention
    /// Contract:
    ///   Input: argc (from a0), argv (from a1) - RISC-V convention
    ///   Output: Parsed Args structure
    ///   Errors: Too many arguments, argument too long
    /// Why: Parse command-line arguments for userspace programs
    pub fn init(argc: u64, argv: [*][*:0]const u8) Args {
        // Contract: argc must be reasonable
        if (argc > MAX_ARGS) {
            // Return empty args if too many
            return Args{ .argc = 0, .argv = undefined };
        }
        
        var args = Args{
            .argc = if (argc > 0) argc - 1 else 0, // Exclude program
name
            .argv = undefined,
        };
        
        // Copy argument pointers (skip argv[0] which is program name)
        var i: u32 = 0;
        while (i < args.argc) : (i += 1) {
            args.argv[i] = argv[i + 1];
        }
        
        return args;
    }
    
    /// Initialize Args by reading from RISC-V registers
    /// Contract:
    ///   Reads argc from a0 (x10) and argv from a1 (x11)
    ///   Output: Parsed Args structure
    /// Why: Convenience function to read registers directly
    pub fn init_from_registers() Args {
        // Read argc from register a0 (x10) using inline assembly
        const argc_val: u64 = asm volatile (""
            : [ret] "={x10}" (-> u64),
        );
        
        // Read argv pointer from register a1 (x11) using inline assembly
        const argv_ptr: [*][*:0]const u8 = asm volatile (""
            : [ret] "={x11}" (-> [*][*:0]const u8),
        );
        
        return init(argc_val, argv_ptr);
    }
    
    /// Get argument by index
    /// Contract:
    ///   Input: index must be < argc
    ///   Output: Returns argument string or null if out of bounds
    pub fn get(self: *const Args, index: u32) ?[*:0]const u8 {
        if (index >= self.argc) return null;
        return self.argv[index];
    }
    
    /// Check if flag is present
    /// Contract:
    ///   Input: flag must be non-null (e.g., "-n")
    ///   Output: Returns true if flag is present
    pub fn has_flag(self: *const Args, flag: [*:0]const u8) bool {
        var i: u32 = 0;
        while (i < self.argc) : (i += 1) {
            if (self.argv[i][0] == '-' and self.argv[i][1] == flag[1]) {
                return true;
            }
        }
        return false;
    }
};


// === userspace/utils/core/cat.zig ===

//! cat: Concatenate and print files
//! Why: Essential file viewing utility for userspace programs
//! Grain Style: Static allocation, explicit types, comprehensive
assertions

const stdlib = @import("userspace_stdlib");

/// Maximum line length for reading (Grain Style: explicit size)
const MAX_LINE_LEN: u32 = 4096;

/// Maximum number of files to process
const MAX_FILES: u32 = 64;

/// Open flags (Grain Style: explicit values)
const O_RDONLY: u32 = 0;

/// Copy file contents to stdout
/// Contract:
///   Input: file_path must be null-terminated string
///   Output: Returns true on success, false on error
/// Why: Read file and print to stdout
fn cat_file(file_path: [*:0]const u8) bool {
    // Open file
    const fd = stdlib.open(file_path, O_RDONLY);
    if (fd < 0) {
        return false; // Failed to open file
    }
    
    var buffer: [MAX_LINE_LEN]u8 = undefined;
    
    // Read and print file contents
    while (true) {
        const bytes_read = stdlib.read(@intCast(fd), &buffer);
        if (bytes_read <= 0) break;
        
        const bytes_written = stdlib.write(stdlib.io.stdout_handle,
buffer[0..@intCast(bytes_read)]);
        if (bytes_written < 0) break;
    }
    
    // Close file
    _ = stdlib.close(@intCast(fd));
    return true;
}

/// Entry point for cat utility
/// Contract:
///   Input: argc, argv (RISC-V calling convention: a0=argc, a1=argv)
///   Output: Exit code 0 on success, non-zero on error
/// Why: Print file contents to stdout
pub fn main() void {
    const args = @import("userspace_args").Args.init_from_registers();
    
    // If no arguments, read from stdin
    if (args.argc == 0) {
        var buffer: [MAX_LINE_LEN]u8 = undefined;
        while (true) {
            const bytes_read = stdlib.read(stdlib.io.stdin_handle,
&buffer);
            if (bytes_read <= 0) break;
            
            const bytes_written = stdlib.write(stdlib.io.stdout_handle,
buffer[0..@intCast(bytes_read)]);
            if (bytes_written < 0) break;
        }
    } else {
        // Process each file argument
        var i: u32 = 0;
        while (i < args.argc) : (i += 1) {
            if (args.get(i)) |file_path| {
                _ = cat_file(file_path);
            }
        }
    }
    
    stdlib.exit(0);
}


// === userspace/utils/core/cp.zig ===

//! cp: Copy files/directories
//! Why: Essential file copying utility for userspace programs
//! Grain Style: Static allocation, explicit types, comprehensive
assertions

const stdlib = @import("userspace_stdlib");

/// Maximum path length (Grain Style: explicit size)
const MAX_PATH_LEN: u32 = 256;

/// Maximum buffer size for copying (Grain Style: explicit size)
const COPY_BUFFER_SIZE: u32 = 4096;

/// Open flags (Grain Style: explicit values)
const O_RDONLY: u32 = 0;
const O_WRONLY: u32 = 1;
const O_CREAT: u32 = 2;

/// Copy file from source to destination
/// Contract:
///   Input: src_path and dst_path must be null-terminated strings
///   Output: Returns true on success, false on error
/// Why: Copy file contents from source to destination
fn copy_file(src_path: [*:0]const u8, dst_path: [*:0]const u8) bool {
    // Open source file
    const src_fd = stdlib.open(src_path, O_RDONLY);
    if (src_fd < 0) {
        return false; // Failed to open source
    }
    
    // Open/create destination file
    const dst_fd = stdlib.open(dst_path, O_WRONLY | O_CREAT);
    if (dst_fd < 0) {
        _ = stdlib.close(@intCast(src_fd));
        return false; // Failed to open/create destination
    }
    
    var buffer: [COPY_BUFFER_SIZE]u8 = undefined;
    
    // Copy file contents
    while (true) {
        const bytes_read = stdlib.read(@intCast(src_fd), &buffer);
        if (bytes_read <= 0) break;
        
        const bytes_written = stdlib.write(@intCast(dst_fd),
buffer[0..@intCast(bytes_read)]);
        if (bytes_written < 0) break;
    }
    
    // Close files
    _ = stdlib.close(@intCast(src_fd));
    _ = stdlib.close(@intCast(dst_fd));
    return true;
}

/// Entry point for cp utility
/// Contract:
///   Input: argc, argv (RISC-V calling convention: a0=argc, a1=argv)
///   Output: Exit code 0 on success, non-zero on error
/// Why: Copy files and directories
pub fn main() void {
    const args = @import("userspace_args").Args.init_from_registers();
    
    // Need at least source and destination
    if (args.argc < 2) {
        const error_msg: [*:0]const u8 = "cp: missing file operand\n";
        _ = stdlib.print(error_msg);
        stdlib.exit(1);
    }
    
    // Check for -r flag (recursive) - not yet implemented
    const recursive = args.has_flag("-r");
    if (recursive) {
        const error_msg: [*:0]const u8 = "cp: -r flag not yet
implemented\n";
        _ = stdlib.print(error_msg);
        stdlib.exit(1);
    }
    
    // Get source and destination paths
    const src_path = args.get(0) orelse {
        stdlib.exit(1);
    };
    const dst_path = args.get(args.argc - 1) orelse {
        stdlib.exit(1);
    };
    
    // Copy file
    if (!copy_file(src_path, dst_path)) {
        const error_msg: [*:0]const u8 = "cp: failed to copy file\n";
        _ = stdlib.print(error_msg);
        stdlib.exit(1);
    }
    
    stdlib.exit(0);
}

